INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'γενέσεως  ̊Ἰησοῦ  ̊Χριστοῦ, υἱοῦ Δαυὶδ, υἱοῦ Ἀβραάμ:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, '¶Ἀβραὰμ ἐγέννησεν τὸν Ἰσαάκ, Ἰσαὰκ δὲ ἐγέννησεν τὸν Ἰακώβ, Ἰακὼβ δὲ ἐγέννησεν τὸν Ἰούδαν καὶ τοὺς ἀδελφοὺς αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Ἰούδας δὲ ἐγέννησεν τὸν Φαρὲς καὶ τὸν Ζάρα ἐκ τῆς Θαμάρ, Φαρὲς δὲ ἐγέννησεν τὸν Ἑσρώμ, Ἑσρὼμ δὲ ἐγέννησεν τὸν Ἀράμ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'Ἀρὰμ δὲ ἐγέννησεν τὸν Ἀμιναδάβ, Ἀμιναδὰβ δὲ ἐγέννησεν τὸν Ναασσών, Ναασσὼν δὲ ἐγέννησεν τὸν Σαλμών,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Σαλμὼν δὲ ἐγέννησεν τὸν Βόες ἐκ τῆς Ῥαχάβ, Βόες δὲ ἐγέννησεν τὸν Ἰωβὴδ ἐκ τῆς Ῥούθ, Ἰωβὴδ δὲ ἐγέννησεν τὸν Ἰεσσαί,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Ἰεσσαὶ δὲ ἐγέννησεν τὸν Δαυὶδ τὸν βασιλέα. ¶Δαυὶδ δὲ ἐγέννησεν τὸν Σολομῶνα ἐκ τῆς τοῦ Οὐρίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Σολομὼν δὲ ἐγέννησεν τὸν Ῥοβοάμ, Ῥοβοὰμ δὲ ἐγέννησεν τὸν Ἀβιά, Ἀβιὰ δὲ ἐγέννησεν τὸν Ἀσάφ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Ἀσὰφ δὲ ἐγέννησεν τὸν Ἰωσαφάτ, Ἰωσαφὰτ δὲ ἐγέννησεν τὸν Ἰωράμ, Ἰωρὰμ δὲ ἐγέννησεν τὸν Ὀζίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Ὀζίας δὲ ἐγέννησεν τὸν Ἰωαθάμ, Ἰωαθὰμ δὲ ἐγέννησεν τὸν Ἀχάζ, Ἀχὰζ δὲ ἐγέννησεν τὸν Ἑζεκίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Ἑζεκίας δὲ ἐγέννησεν τὸν Μανασσῆ, Μανασσῆς δὲ ἐγέννησεν τὸν Ἀμώς, Ἀμὼς δὲ ἐγέννησεν τὸν Ἰωσίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Ἰωσίας δὲ ἐγέννησεν τὸν Ἰεχονίαν καὶ τοὺς ἀδελφοὺς αὐτοῦ ἐπὶ τῆς μετοικεσίας Βαβυλῶνος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, '¶Μετὰ δὲ τὴν μετοικεσίαν Βαβυλῶνος, Ἰεχονίας ἐγέννησεν τὸν Σαλαθιήλ, Σαλαθιὴλ δὲ ἐγέννησεν τὸν Ζοροβαβέλ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Ζοροβαβὲλ δὲ ἐγέννησεν τὸν Ἀβιούδ, Ἀβιοὺδ δὲ ἐγέννησεν τὸν Ἐλιακείμ, Ἐλιακεὶμ δὲ ἐγέννησεν τὸν Ἀζώρ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Ἀζὼρ δὲ ἐγέννησεν τὸν Σαδώκ, Σαδὼκ δὲ ἐγέννησεν τὸν Ἀχείμ, Ἀχεὶμ δὲ ἐγέννησεν τὸν Ἐλιούδ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 15, 'Ἐλιοὺδ δὲ ἐγέννησεν τὸν Ἐλεάζαρ, Ἐλεάζαρ δὲ ἐγέννησεν τὸν Ματθάν, Ματθὰν δὲ ἐγέννησεν τὸν Ἰακώβ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 16, 'Ἰακὼβ δὲ ἐγέννησεν τὸν Ἰωσὴφ τὸν ἄνδρα Μαρίας, ἐξ ἧς ἐγεννήθη  ̊Ἰησοῦς, ὁ λεγόμενος  ̊Χριστός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 17, '¶Πᾶσαι οὖν αἱ γενεαὶ ἀπὸ Ἀβραὰμ ἕως Δαυὶδ γενεαὶ δεκατέσσαρες, καὶ ἀπὸ Δαυὶδ ἕως τῆς μετοικεσίας Βαβυλῶνος γενεαὶ δεκατέσσαρες, καὶ ἀπὸ τῆς μετοικεσίας Βαβυλῶνος ἕως τοῦ  ̊Χριστοῦ γενεαὶ δεκατέσσαρες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 18, '¶Τοῦ δὲ  ̊Ἰησοῦ  ̊Χριστοῦ ἡ γένεσις οὕτως ἦν: μνηστευθείσης τῆς μητρὸς αὐτοῦ Μαρίας τῷ Ἰωσήφ, πρὶν ἢ συνελθεῖν αὐτοὺς, εὑρέθη ἐν γαστρὶ ἔχουσα ἐκ  ̊Πνεύματος Ἁγίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 19, 'Ἰωσὴφ δὲ ὁ ἀνὴρ αὐτῆς, δίκαιος ὢν καὶ μὴ θέλων αὐτὴν δειγματίσαι, ἐβουλήθη λάθρᾳ ἀπολῦσαι αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 20, 'Ταῦτα δὲ αὐτοῦ ἐνθυμηθέντος, ἰδοὺ, ἄγγελος  ̊Κυρίου κατʼ ὄναρ ἐφάνη αὐτῷ λέγων, “Ἰωσὴφ, υἱὸς Δαυίδ, μὴ φοβηθῇς παραλαβεῖν Μαριὰμ τὴν γυναῖκά σου, τὸ γὰρ ἐν αὐτῇ γεννηθὲν ἐκ  ̊Πνεύματός ἐστιν Ἁγίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 21, 'Τέξεται δὲ υἱὸν, καὶ καλέσεις τὸ ὄνομα αὐτοῦ  ̊Ἰησοῦν, αὐτὸς γὰρ σώσει τὸν λαὸν αὐτοῦ ἀπὸ τῶν ἁμαρτιῶν αὐτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 22, 'Τοῦτο δὲ ὅλον γέγονεν, ἵνα πληρωθῇ τὸ ῥηθὲν ὑπὸ  ̊Κυρίου διὰ τοῦ προφήτου λέγοντος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 23, '“Ἰδοὺ, ἡ παρθένος ἐν γαστρὶ ἕξει καὶ τέξεται υἱόν, καὶ καλέσουσιν τὸ ὄνομα αὐτοῦ Ἐμμανουήλ”, ὅ ἐστιν μεθερμηνευόμενον, “Μεθʼ ἡμῶν ὁ  ̊Θεός”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 24, 'Ἐγερθεὶς δὲ ὁ Ἰωσὴφ ἀπὸ τοῦ ὕπνου, ἐποίησεν ὡς προσέταξεν αὐτῷ ὁ ἄγγελος  ̊Κυρίου, καὶ παρέλαβεν τὴν γυναῖκα αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 25, 'καὶ οὐκ ἐγίνωσκεν αὐτὴν ἕως οὗ ἔτεκεν υἱόν· καὶ ἐκάλεσεν τὸ ὄνομα αὐτοῦ,  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, '¶Τοῦ δὲ  ̊Ἰησοῦ γεννηθέντος ἐν Βηθλέεμ τῆς Ἰουδαίας ἐν ἡμέραις Ἡρῴδου τοῦ βασιλέως, ἰδοὺ, μάγοι ἀπὸ ἀνατολῶν παρεγένοντο εἰς Ἱεροσόλυμα');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'λέγοντες, “Ποῦ ἐστιν ὁ, τεχθεὶς Βασιλεὺς τῶν Ἰουδαίων; Εἴδομεν γὰρ αὐτοῦ τὸν ἀστέρα ἐν τῇ ἀνατολῇ καὶ ἤλθομεν προσκυνῆσαι αὐτῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Ἀκούσας δὲ ὁ βασιλεὺς Ἡρῴδης ἐταράχθη, καὶ πᾶσα Ἱεροσόλυμα μετʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Καὶ συναγαγὼν πάντας τοὺς ἀρχιερεῖς καὶ γραμματεῖς τοῦ λαοῦ, ἐπυνθάνετο παρʼ αὐτῶν ποῦ ὁ  ̊Χριστὸς γεννᾶται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Οἱ δὲ εἶπαν αὐτῷ, “Ἐν Βηθλέεμ τῆς Ἰουδαίας”· οὕτως γὰρ γέγραπται διὰ τοῦ προφήτου:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, '“Καὶ σύ Βηθλέεμ, γῆ Ἰούδα, οὐδαμῶς ἐλαχίστη εἶ ἐν τοῖς ἡγεμόσιν Ἰούδα· ἐξ σοῦ γὰρ ἐξελεύσεται ἡγούμενος, ὅστις ποιμανεῖ τὸν λαόν μου τὸν Ἰσραήλ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, '¶Τότε Ἡρῴδης λάθρᾳ καλέσας τοὺς μάγους, ἠκρίβωσεν παρʼ αὐτῶν τὸν χρόνον τοῦ φαινομένου ἀστέρος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Καὶ πέμψας αὐτοὺς εἰς Βηθλέεμ εἶπεν, “Πορευθέντες, ἐξετάσατε ἀκριβῶς περὶ τοῦ παιδίου· ἐπὰν δὲ εὕρητε, ἀπαγγείλατέ μοι ὅπως κἀγὼ ἐλθὼν προσκυνήσω αὐτῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Οἱ δὲ ἀκούσαντες τοῦ βασιλέως, ἐπορεύθησαν, καὶ ἰδοὺ, ὁ ἀστὴρ, ὃν εἶδον ἐν τῇ ἀνατολῇ, προῆγεν αὐτούς ἕως ἐλθὼν ἐστάθη ἐπάνω οὗ ἦν τὸ παιδίον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Ἰδόντες δὲ τὸν ἀστέρα, ἐχάρησαν χαρὰν μεγάλην σφόδρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Καὶ ἐλθόντες εἰς τὴν οἰκίαν, εἶδον τὸ παιδίον μετὰ Μαρίας τῆς μητρὸς αὐτοῦ, καὶ πεσόντες προσεκύνησαν αὐτῷ, καὶ ἀνοίξαντες τοὺς θησαυροὺς αὐτῶν, προσήνεγκαν αὐτῷ δῶρα: χρυσὸν, καὶ λίβανον, καὶ σμύρναν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Καὶ χρηματισθέντες κατʼ ὄναρ μὴ ἀνακάμψαι πρὸς Ἡρῴδην, διʼ ἄλλης ὁδοῦ ἀνεχώρησαν εἰς τὴν χώραν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, '¶Ἀναχωρησάντων δὲ αὐτῶν, ἰδοὺ, ἄγγελος  ̊Κυρίου φαίνεται κατʼ ὄναρ τῷ Ἰωσὴφ λέγων, “Ἐγερθεὶς, παράλαβε τὸ παιδίον καὶ τὴν μητέρα αὐτοῦ καὶ φεῦγε εἰς Αἴγυπτον, καὶ ἴσθι ἐκεῖ ἕως ἂν εἴπω σοι· μέλλει γὰρ Ἡρῴδης ζητεῖν τὸ παιδίον, τοῦ ἀπολέσαι αὐτό.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Ὁ δὲ ἐγερθεὶς, παρέλαβε τὸ παιδίον καὶ τὴν μητέρα αὐτοῦ νυκτὸς καὶ ἀνεχώρησεν εἰς Αἴγυπτον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'καὶ ἦν ἐκεῖ ἕως τῆς τελευτῆς Ἡρῴδου, ἵνα πληρωθῇ τὸ ῥηθὲν ὑπὸ  ̊Κυρίου διὰ τοῦ προφήτου λέγοντος, “Ἐξ Αἰγύπτου ἐκάλεσα τὸν Υἱόν μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, '¶Τότε Ἡρῴδης, ἰδὼν ὅτι ἐνεπαίχθη ὑπὸ τῶν μάγων, ἐθυμώθη λίαν καὶ ἀποστείλας, ἀνεῖλεν πάντας τοὺς παῖδας τοὺς ἐν Βηθλέεμ καὶ ἐν πᾶσι τοῖς ὁρίοις αὐτῆς ἀπὸ διετοῦς καὶ κατωτέρω, κατὰ τὸν χρόνον ὃν ἠκρίβωσεν παρὰ τῶν μάγων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Τότε ἐπληρώθη τὸ ῥηθὲν διὰ Ἰερεμίου τοῦ προφήτου λέγοντος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, '“Φωνὴ ἐν Ῥαμὰ ἠκούσθη, κλαυθμὸς καὶ ὀδυρμὸς πολύς, Ῥαχὴλ κλαίουσα τὰ τέκνα αὐτῆς, καὶ οὐκ ἤθελεν παρακληθῆναι, ὅτι οὐκ εἰσίν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 19, '¶Τελευτήσαντος δὲ τοῦ Ἡρῴδου, ἰδοὺ, ἄγγελος  ̊Κυρίου φαίνεται κατʼ ὄναρ τῷ Ἰωσὴφ ἐν Αἰγύπτῳ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 20, 'λέγων, “Ἐγερθεὶς, παράλαβε τὸ παιδίον καὶ τὴν μητέρα αὐτοῦ, καὶ πορεύου εἰς γῆν Ἰσραήλ, τεθνήκασιν γὰρ οἱ ζητοῦντες τὴν ψυχὴν τοῦ παιδίου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 21, 'Ὁ δὲ ἐγερθεὶς, παρέλαβεν τὸ παιδίον καὶ τὴν μητέρα αὐτοῦ, καὶ εἰσῆλθεν εἰς γῆν Ἰσραήλ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 22, 'Ἀκούσας δὲ ὅτι Ἀρχέλαος βασιλεύει τῆς Ἰουδαίας ἀντὶ τοῦ πατρὸς αὐτοῦ Ἡρῴδου, ἐφοβήθη ἐκεῖ ἀπελθεῖν· χρηματισθεὶς δὲ κατʼ ὄναρ, ἀνεχώρησεν εἰς τὰ μέρη τῆς Γαλιλαίας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 23, 'καὶ ἐλθὼν, κατῴκησεν εἰς πόλιν λεγομένην Ναζαρέτ, ὅπως πληρωθῇ τὸ ῥηθὲν διὰ τῶν προφητῶν, ὅτι “Ναζωραῖος κληθήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, '¶Ἐν δὲ ταῖς ἡμέραις ἐκείναις παραγίνεται Ἰωάννης ὁ Βαπτιστὴς, κηρύσσων ἐν τῇ ἐρήμῳ τῆς Ἰουδαίας');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'λέγων, “Μετανοεῖτε, ἤγγικεν γὰρ ἡ Βασιλεία τῶν Οὐρανῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Οὗτος γάρ ἐστιν ὁ ῥηθεὶς διὰ Ἠσαΐου τοῦ προφήτου λέγοντος, “Φωνὴ βοῶντος ἐν τῇ ἐρήμῳ: ‘Ἑτοιμάσατε τὴν ὁδὸν  ̊Κυρίου, εὐθείας ποιεῖτε τὰς τρίβους αὐτοῦ.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Αὐτὸς δὲ ὁ Ἰωάννης εἶχεν τὸ ἔνδυμα αὐτοῦ ἀπὸ τριχῶν καμήλου καὶ ζώνην δερματίνην περὶ τὴν ὀσφὺν αὐτοῦ, ἡ δὲ τροφὴ ἦν αὐτοῦ ἀκρίδες καὶ μέλι ἄγριον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Τότε ἐξεπορεύετο πρὸς αὐτὸν Ἱεροσόλυμα, καὶ πᾶσα ἡ Ἰουδαία, καὶ πᾶσα ἡ περίχωρος τοῦ Ἰορδάνου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'καὶ ἐβαπτίζοντο ἐν τῷ Ἰορδάνῃ Ποταμῷ ὑπʼ αὐτοῦ, ἐξομολογούμενοι τὰς ἁμαρτίας αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, '¶Ἰδὼν δὲ πολλοὺς τῶν Φαρισαίων καὶ Σαδδουκαίων ἐρχομένους ἐπὶ τὸ βάπτισμα αὐτοῦ, εἶπεν αὐτοῖς, “Γεννήματα ἐχιδνῶν, τίς ὑπέδειξεν ὑμῖν φυγεῖν ἀπὸ τῆς μελλούσης ὀργῆς;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Ποιήσατε οὖν καρπὸν ἄξιον τῆς μετανοίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Καὶ μὴ δόξητε λέγειν ἐν ἑαυτοῖς, πατέρα ἔχομεν τὸν Ἀβραάμ, λέγω γὰρ ὑμῖν ὅτι δύναται ὁ  ̊Θεὸς ἐκ τῶν λίθων τούτων ἐγεῖραι τέκνα τῷ Ἀβραάμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Ἤδη δὲ ἡ ἀξίνη πρὸς τὴν ῥίζαν τῶν δένδρων κεῖται· πᾶν οὖν δένδρον μὴ ποιοῦν καρπὸν καλὸν ἐκκόπτεται καὶ εἰς πῦρ βάλλεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, '¶Ἐγὼ μὲν ὑμᾶς βαπτίζω ἐν ὕδατι εἰς μετάνοιαν, ὁ δὲ ὀπίσω μου ἐρχόμενος ἰσχυρότερός μού ἐστιν, οὗ οὐκ εἰμὶ ἱκανὸς τὰ ὑποδήματα βαστάσαι. Αὐτὸς ὑμᾶς βαπτίσει ἐν  ̊Πνεύματι Ἁγίῳ καὶ πυρί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Οὗ τὸ πτύον ἐν τῇ χειρὶ αὐτοῦ, καὶ διακαθαριεῖ τὴν ἅλωνα αὐτοῦ, καὶ συνάξει τὸν σῖτον αὐτοῦ εἰς τὴν ἀποθήκην, τὸ δὲ ἄχυρον κατακαύσει πυρὶ ἀσβέστῳ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, '¶Τότε παραγίνεται ὁ  ̊Ἰησοῦς ἀπὸ τῆς Γαλιλαίας ἐπὶ τὸν Ἰορδάνην πρὸς τὸν Ἰωάννην, τοῦ βαπτισθῆναι ὑπʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Ὁ δὲ διεκώλυεν αὐτὸν λέγων, “Ἐγὼ χρείαν ἔχω ὑπὸ σοῦ βαπτισθῆναι, καὶ σὺ ἔρχῃ πρός με;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Ἀποκριθεὶς δὲ ὁ  ̊Ἰησοῦς εἶπεν πρὸς αὐτόν, “Ἄφες ἄρτι, οὕτως γὰρ πρέπον ἐστὶν ἡμῖν πληρῶσαι πᾶσαν δικαιοσύνην.” Τότε ἀφίησιν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Βαπτισθεὶς δὲ, ὁ  ̊Ἰησοῦς εὐθὺς ἀνέβη ἀπὸ τοῦ ὕδατος· καὶ ἰδοὺ, ἀνεῴχθησαν οἱ οὐρανοί, καὶ εἶδεν τὸ  ̊Πνεῦμα τοῦ  ̊Θεοῦ καταβαῖνον ὡσεὶ περιστερὰν καὶ ἐρχόμενον ἐπʼ αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Καὶ ἰδοὺ, φωνὴ ἐκ τῶν οὐρανῶν λέγουσα, “Οὗτός ἐστιν ὁ Υἱός μου, ὁ ἀγαπητός ἐν ᾧ εὐδόκησα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, '¶Τότε ὁ  ̊Ἰησοῦς ἀνήχθη εἰς τὴν ἔρημον ὑπὸ τοῦ  ̊Πνεύματος πειρασθῆναι ὑπὸ τοῦ διαβόλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Καὶ νηστεύσας ἡμέρας τεσσεράκοντα καὶ νύκτας τεσσεράκοντα, ὕστερον ἐπείνασεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Καὶ προσελθὼν ὁ πειράζων, εἶπεν αὐτῷ, “Εἰ Υἱὸς εἶ τοῦ  ̊Θεοῦ, εἰπὲ ἵνα οἱ λίθοι οὗτοι ἄρτοι γένωνται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Ὁ δὲ ἀποκριθεὶς εἶπεν, “Γέγραπται, ‘Οὐκ ἐπʼ ἄρτῳ μόνῳ ζήσεται ὁ ἄνθρωπος, ἀλλʼ ἐπὶ παντὶ ῥήματι ἐκπορευομένῳ διὰ στόματος  ̊Θεοῦ.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, '¶Τότε παραλαμβάνει αὐτὸν ὁ διάβολος εἰς τὴν ἁγίαν πόλιν, καὶ ἔστησεν αὐτὸν ἐπὶ τὸ πτερύγιον τοῦ ἱεροῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'καὶ λέγει αὐτῷ, “Εἰ Υἱὸς εἶ τοῦ  ̊Θεοῦ, βάλε σεαυτὸν κάτω· γέγραπται γὰρ, ὅτι ‘Τοῖς ἀγγέλοις αὐτοῦ ἐντελεῖται περὶ σοῦ’, καὶ, ‘Ἐπὶ χειρῶν ἀροῦσίν σε, μήποτε προσκόψῃς πρὸς λίθον τὸν πόδα σου.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Ἔφη αὐτῷ ὁ  ̊Ἰησοῦς, “Πάλιν γέγραπται, ‘Οὐκ ἐκπειράσεις  ̊Κύριον τὸν  ̊Θεόν σου.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, '¶Πάλιν παραλαμβάνει αὐτὸν ὁ διάβολος εἰς ὄρος ὑψηλὸν λίαν, καὶ δείκνυσιν αὐτῷ πάσας τὰς βασιλείας τοῦ κόσμου καὶ τὴν δόξαν αὐτῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'καὶ εἶπεν αὐτῷ, “Ταῦτά σοι πάντα δώσω, ἐὰν πεσὼν προσκυνήσῃς μοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Τότε λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Ὕπαγε, Σατανᾶ· γέγραπται γάρ, ‘ ̊Κύριον τὸν  ̊Θεόν σου προσκυνήσεις, καὶ αὐτῷ μόνῳ λατρεύσεις.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Τότε ἀφίησιν αὐτὸν ὁ διάβολος, καὶ ἰδοὺ, ἄγγελοι προσῆλθον καὶ διηκόνουν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, '¶Ἀκούσας δὲ ὅτι Ἰωάννης παρεδόθη, ἀνεχώρησεν εἰς τὴν Γαλιλαίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Καὶ καταλιπὼν τὴν Ναζαρὰ, ἐλθὼν κατῴκησεν εἰς Καφαρναοὺμ, τὴν παραθαλασσίαν ἐν ὁρίοις Ζαβουλὼν καὶ Νεφθαλείμ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'ἵνα πληρωθῇ τὸ ῥηθὲν διὰ Ἠσαΐου τοῦ προφήτου λέγοντος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, '“Γῆ Ζαβουλὼν καὶ γῆ Νεφθαλείμ, ὁδὸν θαλάσσης, πέραν τοῦ Ἰορδάνου, Γαλιλαία τῶν ἐθνῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Ὁ λαὸς ὁ καθήμενος ἐν σκοτίᾳ φῶς εἶδεν μέγα, καὶ τοῖς καθημένοις ἐν χώρᾳ καὶ σκιᾷ θανάτου, φῶς ἀνέτειλεν αὐτοῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 17, 'Ἀπὸ τότε ἤρξατο ὁ  ̊Ἰησοῦς κηρύσσειν καὶ λέγειν, “Μετανοεῖτε, ἤγγικεν γὰρ ἡ Βασιλεία τῶν Οὐρανῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 18, '¶Περιπατῶν δὲ παρὰ τὴν θάλασσαν τῆς Γαλιλαίας, εἶδεν δύο ἀδελφούς, Σίμωνα τὸν λεγόμενον Πέτρον καὶ Ἀνδρέαν τὸν ἀδελφὸν αὐτοῦ, βάλλοντας ἀμφίβληστρον εἰς τὴν θάλασσαν, ἦσαν γὰρ ἁλεεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 19, 'Καὶ λέγει αὐτοῖς, “Δεῦτε ὀπίσω μου, καὶ ποιήσω ὑμᾶς ἁλεεῖς ἀνθρώπων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 20, 'Οἱ δὲ εὐθέως ἀφέντες τὰ δίκτυα, ἠκολούθησαν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 21, 'Καὶ προβὰς ἐκεῖθεν, εἶδεν ἄλλους δύο ἀδελφούς, Ἰάκωβον τὸν τοῦ Ζεβεδαίου καὶ Ἰωάννην τὸν ἀδελφὸν αὐτοῦ, ἐν τῷ πλοίῳ μετὰ Ζεβεδαίου τοῦ πατρὸς αὐτῶν, καταρτίζοντας τὰ δίκτυα αὐτῶν, καὶ ἐκάλεσεν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 22, 'Οἱ δὲ εὐθέως ἀφέντες τὸ πλοῖον καὶ τὸν πατέρα αὐτῶν, ἠκολούθησαν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 23, '¶Καὶ περιῆγεν ὁ  ̊Ἰησοῦς ἐν ὅλῃ τῇ Γαλιλαίᾳ, διδάσκων ἐν ταῖς συναγωγαῖς αὐτῶν, καὶ κηρύσσων τὸ εὐαγγέλιον τῆς βασιλείας, καὶ θεραπεύων πᾶσαν νόσον καὶ πᾶσαν μαλακίαν ἐν τῷ λαῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 24, 'Καὶ ἀπῆλθεν ἡ ἀκοὴ αὐτοῦ εἰς ὅλην τὴν Συρίαν. Καὶ προσήνεγκαν αὐτῷ πάντας τοὺς κακῶς, ἔχοντας ποικίλαις νόσοις, καὶ βασάνοις συνεχομένους, δαιμονιζομένους, καὶ σεληνιαζομένους, καὶ παραλυτικούς, καὶ ἐθεράπευσεν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 25, 'Καὶ ἠκολούθησαν αὐτῷ ὄχλοι πολλοὶ ἀπὸ τῆς Γαλιλαίας, καὶ Δεκαπόλεως, καὶ Ἱεροσολύμων, καὶ Ἰουδαίας, καὶ πέραν τοῦ Ἰορδάνου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, '¶Ἰδὼν δὲ τοὺς ὄχλους, ἀνέβη εἰς τὸ ὄρος· καὶ καθίσαντος αὐτοῦ, προσῆλθον αὐτῷ οἱ μαθηταὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Καὶ ἀνοίξας τὸ στόμα αὐτοῦ, ἐδίδασκεν αὐτοὺς λέγων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, '“Μακάριοι οἱ πτωχοὶ τῷ πνεύματι, ὅτι αὐτῶν ἐστιν ἡ Βασιλεία τῶν Οὐρανῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Μακάριοι οἱ πενθοῦντες, ὅτι αὐτοὶ παρακληθήσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Μακάριοι οἱ πραεῖς, ὅτι αὐτοὶ κληρονομήσουσιν τὴν γῆν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Μακάριοι οἱ πεινῶντες καὶ διψῶντες τὴν δικαιοσύνην, ὅτι αὐτοὶ χορτασθήσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Μακάριοι οἱ ἐλεήμονες, ὅτι αὐτοὶ ἐλεηθήσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Μακάριοι οἱ καθαροὶ τῇ καρδίᾳ, ὅτι αὐτοὶ τὸν  ̊Θεὸν ὄψονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'Μακάριοι οἱ εἰρηνοποιοί, ὅτι αὐτοὶ υἱοὶ  ̊Θεοῦ κληθήσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Μακάριοι οἱ δεδιωγμένοι ἕνεκεν δικαιοσύνης, ὅτι αὐτῶν ἐστιν ἡ Βασιλεία τῶν Οὐρανῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Μακάριοί ἐστε ὅταν ὀνειδίσωσιν ὑμᾶς καὶ διώξωσιν καὶ εἴπωσιν πᾶν πονηρὸν καθʼ ὑμῶν ψευδόμενοι ἕνεκεν ἐμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Χαίρετε καὶ ἀγαλλιᾶσθε, ὅτι ὁ μισθὸς ὑμῶν πολὺς ἐν τοῖς οὐρανοῖς· οὕτως γὰρ ἐδίωξαν τοὺς προφήτας τοὺς πρὸ ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, '¶Ὑμεῖς ἐστε τὸ ἅλας τῆς γῆς· ἐὰν δὲ τὸ ἅλας μωρανθῇ, ἐν τίνι ἁλισθήσεται; Εἰς οὐδὲν ἰσχύει ἔτι, εἰ μὴ βληθὲν ἔξω, καταπατεῖσθαι ὑπὸ τῶν ἀνθρώπων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, '¶Ὑμεῖς ἐστε τὸ φῶς τοῦ κόσμου. Οὐ δύναται πόλις κρυβῆναι ἐπάνω ὄρους κειμένη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 15, 'Οὐδὲ καίουσιν λύχνον καὶ τιθέασιν αὐτὸν ὑπὸ τὸν μόδιον, ἀλλʼ ἐπὶ τὴν λυχνίαν, καὶ λάμπει πᾶσιν τοῖς ἐν τῇ οἰκίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 16, 'Οὕτως λαμψάτω τὸ φῶς ὑμῶν ἔμπροσθεν τῶν ἀνθρώπων, ὅπως ἴδωσιν ὑμῶν τὰ καλὰ ἔργα, καὶ δοξάσωσιν τὸν Πατέρα ὑμῶν τὸν ἐν τοῖς οὐρανοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 17, '¶Μὴ νομίσητε ὅτι ἦλθον καταλῦσαι τὸν νόμον ἢ τοὺς προφήτας· οὐκ ἦλθον καταλῦσαι, ἀλλὰ πληρῶσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 18, 'Ἀμὴν, γὰρ λέγω ὑμῖν, ἕως ἂν παρέλθῃ ὁ οὐρανὸς καὶ ἡ γῆ, ἰῶτα ἓν ἢ μία κεραία οὐ μὴ παρέλθῃ ἀπὸ τοῦ νόμου, ἕως ἂν πάντα γένηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 19, 'Ὃς ἐὰν οὖν λύσῃ μίαν τῶν ἐντολῶν τούτων τῶν ἐλαχίστων, καὶ διδάξῃ οὕτως τοὺς ἀνθρώπους, ἐλάχιστος κληθήσεται ἐν τῇ Βασιλείᾳ τῶν Οὐρανῶν· ὃς δʼ ἂν ποιήσῃ καὶ διδάξῃ, οὗτος μέγας κληθήσεται ἐν τῇ Βασιλείᾳ τῶν Οὐρανῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 20, 'Λέγω γὰρ ὑμῖν ὅτι ἐὰν μὴ περισσεύσῃ ὑμῶν ἡ δικαιοσύνη πλεῖον τῶν γραμματέων καὶ Φαρισαίων, οὐ μὴ εἰσέλθητε εἰς τὴν Βασιλείαν τῶν Οὐρανῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 21, '¶Ἠκούσατε ὅτι ἐρρέθη τοῖς ἀρχαίοις, ‘“Οὐ φονεύσεις”, ὃς δʼ, ἂν φονεύσῃ, ἔνοχος ἔσται τῇ κρίσει.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 22, 'Ἐγὼ δὲ λέγω ὑμῖν ὅτι πᾶς ὁ ὀργιζόμενος τῷ ἀδελφῷ αὐτοῦ, ἔνοχος ἔσται τῇ κρίσει· ὃς δʼ ἂν εἴπῃ τῷ ἀδελφῷ αὐτοῦ, ‘Ῥακά’, ἔνοχος ἔσται τῷ Συνεδρίῳ· ὃς δʼ ἂν εἴπῃ, ‘Μωρέ’, ἔνοχος ἔσται εἰς τὴν Γέενναν τοῦ πυρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 23, 'Ἐὰν οὖν προσφέρῃς τὸ δῶρόν σου ἐπὶ τὸ θυσιαστήριον, κἀκεῖ μνησθῇς ὅτι ὁ ἀδελφός σου ἔχει τι κατὰ σοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 24, 'ἄφες ἐκεῖ τὸ δῶρόν σου ἔμπροσθεν τοῦ θυσιαστηρίου. Καὶ ὕπαγε πρῶτον διαλλάγηθι τῷ ἀδελφῷ σου, καὶ τότε ἐλθὼν, πρόσφερε τὸ δῶρόν σου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 25, 'Ἴσθι εὐνοῶν τῷ ἀντιδίκῳ σου ταχὺ, ἕως ὅτου εἶ μετʼ αὐτοῦ ἐν τῇ ὁδῷ, μήποτέ σε παραδῷ ὁ ἀντίδικος τῷ κριτῇ, καὶ ὁ κριτὴς τῷ ὑπηρέτῃ, καὶ εἰς φυλακὴν βληθήσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 26, 'Ἀμὴν, λέγω σοι, οὐ μὴ ἐξέλθῃς ἐκεῖθεν, ἕως ἂν ἀποδῷς τὸν ἔσχατον κοδράντην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 27, '¶Ἠκούσατε ὅτι ἐρρέθη, ‘Οὐ μοιχεύσεις.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 28, 'Ἐγὼ δὲ λέγω ὑμῖν ὅτι πᾶς ὁ βλέπων γυναῖκα πρὸς τὸ ἐπιθυμῆσαι αὐτὴν, ἤδη ἐμοίχευσεν αὐτὴν ἐν τῇ καρδίᾳ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 29, 'Εἰ δὲ ὁ ὀφθαλμός σου ὁ δεξιὸς σκανδαλίζει σε, ἔξελε αὐτὸν καὶ βάλε ἀπὸ σοῦ, συμφέρει γάρ σοι ἵνα ἀπόληται ἓν τῶν μελῶν σου, καὶ μὴ ὅλον τὸ σῶμά σου βληθῇ εἰς Γέενναν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 30, 'Καὶ εἰ ἡ δεξιά σου χεὶρ σκανδαλίζει σε, ἔκκοψον αὐτὴν καὶ βάλε ἀπὸ σοῦ, συμφέρει γάρ σοι ἵνα ἀπόληται ἓν τῶν μελῶν σου, καὶ μὴ ὅλον τὸ σῶμά σου εἰς Γέενναν ἀπέλθῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 31, '¶Ἐρρέθη δέ, ‘Ὃς ἂν ἀπολύσῃ τὴν γυναῖκα αὐτοῦ, δότω αὐτῇ ἀποστάσιον.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 32, 'Ἐγὼ δὲ λέγω ὑμῖν ὅτι πᾶς ὁ ἀπολύων τὴν γυναῖκα αὐτοῦ, παρεκτὸς λόγου πορνείας, ποιεῖ αὐτὴν μοιχευθῆναι, καὶ ὃς ἐὰν ἀπολελυμένην γαμήσῃ, μοιχᾶται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 33, '¶Πάλιν ἠκούσατε ὅτι ἐρρέθη τοῖς ἀρχαίοις, ‘Οὐκ ἐπιορκήσεις, ἀποδώσεις δὲ τῷ  ̊Κυρίῳ τοὺς ὅρκους σου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 34, 'Ἐγὼ δὲ λέγω ὑμῖν μὴ ὀμόσαι ὅλως· μήτε ἐν τῷ οὐρανῷ, ὅτι θρόνος ἐστὶν τοῦ  ̊Θεοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 35, 'μήτε ἐν τῇ γῇ, ὅτι ὑποπόδιόν ἐστιν τῶν ποδῶν αὐτοῦ· μήτε εἰς Ἱεροσόλυμα, ὅτι πόλις ἐστὶν τοῦ μεγάλου Βασιλέως·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 36, 'μήτε ἐν τῇ κεφαλῇ σου ὀμόσῃς, ὅτι οὐ δύνασαι μίαν τρίχα λευκὴν ποιῆσαι ἢ μέλαιναν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 37, 'Ἔστω δὲ ὁ λόγος ὑμῶν, ναὶ ναί, οὒ οὔ· τὸ δὲ περισσὸν τούτων ἐκ τοῦ πονηροῦ ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 38, '¶Ἠκούσατε ὅτι ἐρρέθη, ‘Ὀφθαλμὸν ἀντὶ ὀφθαλμοῦ καὶ ὀδόντα ἀντὶ ὀδόντος.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 39, 'Ἐγὼ δὲ λέγω ὑμῖν, μὴ ἀντιστῆναι τῷ πονηρῷ· ἀλλʼ ὅστις σε ῥαπίζει εἰς τὴν δεξιὰν σιαγόνα, σου στρέψον αὐτῷ καὶ τὴν ἄλλην·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 40, 'καὶ τῷ θέλοντί σοι κριθῆναι καὶ τὸν χιτῶνά σου λαβεῖν, ἄφες αὐτῷ καὶ τὸ ἱμάτιον·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 41, 'καὶ ὅστις σε ἀγγαρεύσει μίλιον ἕν, ὕπαγε μετʼ αὐτοῦ δύο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 42, 'Τῷ αἰτοῦντί σε, δός, καὶ τὸν θέλοντα ἀπὸ σοῦ δανίσασθαι, μὴ ἀποστραφῇς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 43, '¶Ἠκούσατε ὅτι ἐρρέθη, ‘“Ἀγαπήσεις τὸν πλησίον σου”, καὶ μισήσεις τὸν ἐχθρόν σου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 44, 'Ἐγὼ δὲ λέγω ὑμῖν, ἀγαπᾶτε τοὺς ἐχθροὺς ὑμῶν, καὶ προσεύχεσθε ὑπὲρ τῶν διωκόντων ὑμᾶς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 45, 'ὅπως γένησθε υἱοὶ τοῦ Πατρὸς ὑμῶν τοῦ ἐν οὐρανοῖς, ὅτι τὸν ἥλιον αὐτοῦ ἀνατέλλει ἐπὶ πονηροὺς καὶ ἀγαθοὺς, καὶ βρέχει ἐπὶ δικαίους καὶ ἀδίκους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 46, 'Ἐὰν γὰρ ἀγαπήσητε τοὺς ἀγαπῶντας ὑμᾶς, τίνα μισθὸν ἔχετε; Οὐχὶ καὶ οἱ τελῶναι τὸ αὐτὸ ποιοῦσιν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 47, 'Καὶ ἐὰν ἀσπάσησθε τοὺς ἀδελφοὺς ὑμῶν μόνον, τί περισσὸν ποιεῖτε; Οὐχὶ καὶ οἱ ἐθνικοὶ τὸ αὐτὸ ποιοῦσιν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 48, 'Ἔσεσθε οὖν ὑμεῖς τέλειοι ὡς ὁ Πατὴρ ὑμῶν ὁ οὐράνιος τέλειός ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, '¶Προσέχετε τὴν δικαιοσύνην ὑμῶν μὴ ποιεῖν ἔμπροσθεν τῶν ἀνθρώπων, πρὸς τὸ θεαθῆναι αὐτοῖς· εἰ δὲ μή γε, μισθὸν οὐκ ἔχετε παρὰ τῷ Πατρὶ ὑμῶν, τῷ ἐν τοῖς οὐρανοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, '¶Ὅταν οὖν ποιῇς ἐλεημοσύνην, μὴ σαλπίσῃς ἔμπροσθέν σου, ὥσπερ οἱ ὑποκριταὶ ποιοῦσιν ἐν ταῖς συναγωγαῖς καὶ ἐν ταῖς ῥύμαις, ὅπως δοξασθῶσιν ὑπὸ τῶν ἀνθρώπων. Ἀμὴν, λέγω ὑμῖν, ἀπέχουσιν τὸν μισθὸν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Σοῦ δὲ ποιοῦντος ἐλεημοσύνην, μὴ γνώτω ἡ ἀριστερά σου τί ποιεῖ ἡ δεξιά σου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'ὅπως ᾖ σου ἡ ἐλεημοσύνη ἐν τῷ κρυπτῷ· καὶ ὁ Πατήρ σου, ὁ βλέπων ἐν τῷ κρυπτῷ, ἀποδώσει σοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, '¶Καὶ ὅταν προσεύχῃ, οὐκ ἔσεσθε ὡς οἱ ὑποκριταί, ὅτι φιλοῦσιν ἐν ταῖς συναγωγαῖς καὶ ἐν ταῖς γωνίαις τῶν πλατειῶν ἑστῶτες προσεύχεσθαι, ὅπως φανῶσιν τοῖς ἀνθρώποις. Ἀμὴν, λέγω ὑμῖν, ἀπέχουσι τὸν μισθὸν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'Σὺ δὲ ὅταν προσεύχῃ, εἴσελθε εἰς τὸ ταμεῖόν σου καὶ κλείσας τὴν θύραν σου, πρόσευξαι τῷ Πατρί σου, τῷ ἐν τῷ κρυπτῷ, καὶ ὁ Πατήρ σου, ὁ βλέπων ἐν τῷ κρυπτῷ, ἀποδώσει σοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, '¶Προσευχόμενοι δὲ μὴ βατταλογήσητε ὥσπερ οἱ ἐθνικοί, δοκοῦσιν γὰρ ὅτι ἐν τῇ πολυλογίᾳ αὐτῶν εἰσακουσθήσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Μὴ οὖν ὁμοιωθῆτε αὐτοῖς, οἶδεν γὰρ ὁ  ̊Θεὸς ὁ Πατὴρ ὑμῶν ὧν χρείαν ἔχετε πρὸ τοῦ ὑμᾶς αἰτῆσαι αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, '¶Οὕτως οὖν προσεύχεσθε ὑμεῖς: ‘Πάτερ ἡμῶν, ὁ ἐν τοῖς οὐρανοῖς, ἁγιασθήτω τὸ ὄνομά σου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'ἐλθέτω ἡ βασιλεία σου, γενηθήτω τὸ θέλημά σου, ὡς ἐν οὐρανῷ καὶ ἐπὶ γῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Τὸν ἄρτον ἡμῶν τὸν ἐπιούσιον δὸς ἡμῖν σήμερον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Καὶ ἄφες ἡμῖν τὰ ὀφειλήματα ἡμῶν, ὡς καὶ ἡμεῖς ἀφήκαμεν τοῖς ὀφειλέταις ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Καὶ μὴ εἰσενέγκῃς ἡμᾶς εἰς πειρασμόν, ἀλλὰ ῥῦσαι ἡμᾶς ἀπὸ τοῦ πονηροῦ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Ἐὰν γὰρ ἀφῆτε τοῖς ἀνθρώποις τὰ παραπτώματα αὐτῶν, ἀφήσει καὶ ὑμῖν ὁ Πατὴρ ὑμῶν ὁ οὐράνιος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Ἐὰν δὲ μὴ ἀφῆτε τοῖς ἀνθρώποις τὰ παραπτώματα αὐτῶν, οὐδὲ ὁ Πατὴρ ὑμῶν ἀφήσει τὰ παραπτώματα ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, '¶Ὅταν δὲ νηστεύητε, μὴ γίνεσθε ὡς οἱ ὑποκριταὶ σκυθρωποί, ἀφανίζουσιν γὰρ τὰ πρόσωπα αὐτῶν, ὅπως φανῶσιν τοῖς ἀνθρώποις νηστεύοντες. Ἀμὴν, λέγω ὑμῖν, ἀπέχουσιν τὸν μισθὸν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Σὺ δὲ νηστεύων, ἄλειψαί σου τὴν κεφαλὴν καὶ τὸ πρόσωπόν σου νίψαι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'ὅπως μὴ φανῇς τοῖς ἀνθρώποις νηστεύων, ἀλλὰ τῷ Πατρί σου τῷ ἐν τῷ κρυφαίῳ· καὶ ὁ Πατήρ σου, ὁ βλέπων ἐν τῷ κρυφαίῳ, ἀποδώσει σοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, '¶Μὴ θησαυρίζετε ὑμῖν θησαυροὺς ἐπὶ τῆς γῆς, ὅπου σὴς καὶ βρῶσις ἀφανίζει, καὶ ὅπου κλέπται διορύσσουσιν καὶ κλέπτουσιν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'θησαυρίζετε δὲ ὑμῖν θησαυροὺς ἐν οὐρανῷ, ὅπου οὔτε σὴς οὔτε βρῶσις ἀφανίζει, καὶ ὅπου κλέπται οὐ διορύσσουσιν οὐδὲ κλέπτουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 21, 'Ὅπου γάρ ἐστιν ὁ θησαυρός σου, ἐκεῖ ἔσται καὶ ἡ καρδία σου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 22, '¶Ὁ λύχνος τοῦ σώματός ἐστιν ὁ ὀφθαλμός. Ἐὰν οὖν ᾖ ὁ ὀφθαλμός σου ἁπλοῦς, ὅλον τὸ σῶμά σου φωτεινὸν ἔσται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 23, 'Ἐὰν δὲ ὁ ὀφθαλμός σου πονηρὸς ᾖ, ὅλον τὸ σῶμά σου σκοτεινὸν ἔσται. Εἰ οὖν τὸ φῶς τὸ ἐν σοὶ σκότος, ἐστίν τὸ σκότος πόσον!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 24, '¶Οὐδεὶς δύναται δυσὶ κυρίοις δουλεύειν· ἢ γὰρ τὸν ἕνα μισήσει καὶ τὸν ἕτερον ἀγαπήσει, ἢ ἑνὸς ἀνθέξεται καὶ τοῦ ἑτέρου καταφρονήσει. Οὐ δύνασθε  ̊Θεῷ δουλεύειν καὶ μαμωνᾷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 25, '¶Διὰ τοῦτο λέγω ὑμῖν, μὴ μεριμνᾶτε τῇ ψυχῇ ὑμῶν τί φάγητε ἢ τί πίητε, μηδὲ τῷ σώματι ὑμῶν τί ἐνδύσησθε. Οὐχὶ ἡ ψυχὴ πλεῖόν ἐστι τῆς τροφῆς, καὶ τὸ σῶμα τοῦ ἐνδύματος;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 26, 'Ἐμβλέψατε εἰς τὰ πετεινὰ τοῦ οὐρανοῦ, ὅτι οὐ σπείρουσιν, οὐδὲ θερίζουσιν, οὐδὲ συνάγουσιν εἰς ἀποθήκας, καὶ ὁ Πατὴρ ὑμῶν ὁ οὐράνιος τρέφει αὐτά· οὐχ ὑμεῖς μᾶλλον διαφέρετε αὐτῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 27, 'Τίς δὲ ἐξ ὑμῶν μεριμνῶν δύναται προσθεῖναι ἐπὶ τὴν ἡλικίαν αὐτοῦ πῆχυν ἕνα;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 28, 'Καὶ περὶ ἐνδύματος τί μεριμνᾶτε; Καταμάθετε τὰ κρίνα τοῦ ἀγροῦ πῶς αὐξάνουσιν· οὐ κοπιοῦσιν οὐδὲ νήθουσιν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 29, 'λέγω δὲ ὑμῖν ὅτι οὐδὲ Σολομὼν ἐν πάσῃ τῇ δόξῃ αὐτοῦ περιεβάλετο ὡς ἓν τούτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 30, 'Εἰ δὲ τὸν χόρτον τοῦ ἀγροῦ σήμερον ὄντα, καὶ αὔριον εἰς κλίβανον βαλλόμενον, ὁ  ̊Θεὸς οὕτως ἀμφιέννυσιν, οὐ πολλῷ μᾶλλον ὑμᾶς, ὀλιγόπιστοι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 31, 'Μὴ οὖν μεριμνήσητε λέγοντες, ‘Τί φάγωμεν’, ἤ, ‘Τί πίωμεν’, ἤ, ‘Τί περιβαλώμεθα;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 32, 'Πάντα γὰρ ταῦτα τὰ ἔθνη ἐπιζητοῦσιν· οἶδεν γὰρ ὁ Πατὴρ ὑμῶν ὁ οὐράνιος ὅτι χρῄζετε τούτων ἁπάντων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 33, 'Ζητεῖτε δὲ πρῶτον τὴν βασιλείαν καὶ τὴν δικαιοσύνην αὐτοῦ, καὶ ταῦτα πάντα προστεθήσεται ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 34, 'Μὴ οὖν μεριμνήσητε εἰς τὴν αὔριον, ἡ γὰρ αὔριον μεριμνήσει ἑαυτῆς. Ἀρκετὸν τῇ ἡμέρᾳ ἡ κακία αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, '¶Μὴ κρίνετε, ἵνα μὴ κριθῆτε·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'ἐν ᾧ γὰρ κρίματι κρίνετε, κριθήσεσθε, καὶ ἐν ᾧ μέτρῳ μετρεῖτε, μετρηθήσεται ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Τί δὲ βλέπεις τὸ κάρφος τὸ ἐν τῷ ὀφθαλμῷ τοῦ ἀδελφοῦ σου, τὴν δὲ ἐν τῷ σῷ ὀφθαλμῷ δοκὸν οὐ κατανοεῖς;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Ἢ πῶς ἐρεῖς τῷ ἀδελφῷ σου, ‘Ἄφες ἐκβάλω τὸ κάρφος ἐκ τοῦ ὀφθαλμοῦ σου’, καὶ ἰδοὺ, ἡ δοκὸς ἐν τῷ ὀφθαλμῷ σοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Ὑποκριτά, ἔκβαλε πρῶτον ἐκ τοῦ ὀφθαλμοῦ σοῦ τὴν δοκόν, καὶ τότε διαβλέψεις ἐκβαλεῖν τὸ κάρφος ἐκ τοῦ ὀφθαλμοῦ τοῦ ἀδελφοῦ σου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, '¶Μὴ δῶτε τὸ ἅγιον τοῖς κυσίν, μηδὲ βάλητε τοὺς μαργαρίτας ὑμῶν ἔμπροσθεν τῶν χοίρων, μήποτε καταπατήσουσιν αὐτοὺς ἐν τοῖς ποσὶν αὐτῶν, καὶ στραφέντες ῥήξωσιν ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, '¶Αἰτεῖτε καὶ δοθήσεται ὑμῖν· ζητεῖτε καὶ εὑρήσετε· κρούετε καὶ ἀνοιγήσεται ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Πᾶς γὰρ ὁ αἰτῶν λαμβάνει, καὶ ὁ ζητῶν εὑρίσκει, καὶ τῷ κρούοντι ἀνοιγήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Ἢ τίς ἐστιν ἐξ ὑμῶν ἄνθρωπος, ὃν αἰτήσει ὁ υἱὸς αὐτοῦ ἄρτον, μὴ λίθον ἐπιδώσει αὐτῷ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Ἢ καὶ ἰχθὺν αἰτήσει, μὴ ὄφιν ἐπιδώσει αὐτῷ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Εἰ οὖν ὑμεῖς πονηροὶ ὄντες, οἴδατε δόματα ἀγαθὰ διδόναι τοῖς τέκνοις ὑμῶν, πόσῳ μᾶλλον ὁ Πατὴρ ὑμῶν ὁ ἐν τοῖς οὐρανοῖς δώσει ἀγαθὰ τοῖς αἰτοῦσιν αὐτόν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, '¶Πάντα οὖν, ὅσα ἐὰν θέλητε ἵνα ποιῶσιν ὑμῖν οἱ ἄνθρωποι, οὕτως καὶ ὑμεῖς ποιεῖτε αὐτοῖς. Οὗτος γάρ ἐστιν ὁ νόμος καὶ οἱ προφῆται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, '¶Εἰσέλθατε διὰ τῆς στενῆς πύλης· ὅτι πλατεῖα ἡ πύλη καὶ εὐρύχωρος ἡ ὁδὸς ἡ ἀπάγουσα εἰς τὴν ἀπώλειαν, καὶ πολλοί εἰσιν οἱ εἰσερχόμενοι διʼ αὐτῆς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'τί στενὴ ἡ πύλη καὶ τεθλιμμένη ἡ ὁδὸς ἡ ἀπάγουσα εἰς τὴν ζωήν, καὶ ὀλίγοι εἰσὶν οἱ εὑρίσκοντες αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, '¶Προσέχετε ἀπὸ τῶν ψευδοπροφητῶν, οἵτινες ἔρχονται πρὸς ὑμᾶς ἐν ἐνδύμασι προβάτων, ἔσωθεν δέ εἰσιν λύκοι ἅρπαγες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'Ἀπὸ τῶν καρπῶν αὐτῶν ἐπιγνώσεσθε αὐτούς. Μήτι συλλέγουσιν ἀπὸ ἀκανθῶν σταφυλὰς, ἢ ἀπὸ τριβόλων σῦκα;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Οὕτως πᾶν δένδρον ἀγαθὸν καρποὺς καλοὺς ποιεῖ, τὸ δὲ σαπρὸν δένδρον καρποὺς πονηροὺς ποιεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Οὐ δύναται δένδρον ἀγαθὸν καρποὺς πονηροὺς ἐνεγκεῖν, οὐδὲ δένδρον σαπρὸν καρποὺς καλοὺς ποιεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Πᾶν δένδρον μὴ ποιοῦν καρπὸν καλὸν ἐκκόπτεται καὶ εἰς πῦρ βάλλεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Ἄρα γε ἀπὸ τῶν καρπῶν αὐτῶν ἐπιγνώσεσθε αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, '¶Οὐ πᾶς ὁ λέγων μοι, ‘ ̊Κύριε,  ̊Κύριε’, εἰσελεύσεται εἰς τὴν Βασιλείαν τῶν Οὐρανῶν, ἀλλʼ ὁ ποιῶν τὸ θέλημα τοῦ Πατρός μου τοῦ ἐν τοῖς οὐρανοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Πολλοὶ ἐροῦσίν μοι ἐν ἐκείνῃ τῇ ἡμέρᾳ, ‘ ̊Κύριε,  ̊Κύριε, οὐ τῷ σῷ ὀνόματι ἐπροφητεύσαμεν, καὶ τῷ σῷ ὀνόματι δαιμόνια ἐξεβάλομεν, καὶ τῷ σῷ ὀνόματι δυνάμεις πολλὰς ἐποιήσαμεν;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Καὶ τότε ὁμολογήσω αὐτοῖς, ὅτι ‘Οὐδέποτε ἔγνων ὑμᾶς, “ἀποχωρεῖτε ἀπʼ ἐμοῦ, οἱ ἐργαζόμενοι τὴν ἀνομίαν”.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, '¶Πᾶς οὖν ὅστις ἀκούει μου τοὺς λόγους τούτους καὶ ποιεῖ αὐτούς, ὁμοιωθήσεται ἀνδρὶ φρονίμῳ, ὅστις ᾠκοδόμησεν αὐτοῦ τὴν οἰκίαν ἐπὶ τὴν πέτραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Καὶ κατέβη ἡ βροχὴ, καὶ ἦλθον οἱ ποταμοὶ, καὶ ἔπνευσαν οἱ ἄνεμοι, καὶ προσέπεσαν τῇ οἰκίᾳ ἐκείνῃ, καὶ οὐκ ἔπεσεν, τεθεμελίωτο γὰρ ἐπὶ τὴν πέτραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Καὶ πᾶς ὁ ἀκούων μου τοὺς λόγους τούτους καὶ μὴ ποιῶν αὐτοὺς, ὁμοιωθήσεται ἀνδρὶ μωρῷ, ὅστις ᾠκοδόμησεν αὐτοῦ τὴν οἰκίαν ἐπὶ τὴν ἄμμον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Καὶ κατέβη ἡ βροχὴ, καὶ ἦλθον οἱ ποταμοὶ, καὶ ἔπνευσαν οἱ ἄνεμοι, καὶ προσέκοψαν τῇ οἰκίᾳ ἐκείνῃ, καὶ ἔπεσεν καὶ ἦν ἡ πτῶσις αὐτῆς μεγάλη.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, '¶Καὶ ἐγένετο, ὅτε ἐτέλεσεν ὁ  ̊Ἰησοῦς τοὺς λόγους τούτους, ἐξεπλήσσοντο οἱ ὄχλοι ἐπὶ τῇ διδαχῇ αὐτοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 29, 'ἦν γὰρ διδάσκων αὐτοὺς ὡς ἐξουσίαν ἔχων, καὶ οὐχ ὡς οἱ γραμματεῖς αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, '¶Καταβάντος δὲ αὐτοῦ ἀπὸ τοῦ ὄρους, ἠκολούθησαν αὐτῷ ὄχλοι πολλοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'Καὶ ἰδοὺ, λεπρὸς προσελθὼν, προσεκύνει αὐτῷ λέγων, “ ̊Κύριε, ἐὰν θέλῃς, δύνασαί με καθαρίσαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Καὶ ἐκτείνας τὴν χεῖρα, ἥψατο αὐτοῦ λέγων, “Θέλω, καθαρίσθητι.” Καὶ εὐθέως ἐκαθαρίσθη αὐτοῦ ἡ λέπρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Καὶ λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Ὅρα μηδενὶ εἴπῃς, ἀλλὰ ὕπαγε σεαυτὸν, δεῖξον τῷ ἱερεῖ, καὶ προσένεγκον τὸ δῶρον ὃ προσέταξεν Μωϋσῆς, εἰς μαρτύριον αὐτοῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, '¶Εἰσελθόντος δὲ αὐτοῦ εἰς Καφαρναοὺμ, προσῆλθεν αὐτῷ ἑκατόνταρχος παρακαλῶν αὐτὸν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'καὶ λέγων,  ̊Κύριε, ὁ παῖς μου βέβληται ἐν τῇ οἰκίᾳ παραλυτικός, δεινῶς βασανιζόμενος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Καὶ λέγει αὐτῷ, “Ἐγὼ ἐλθὼν, θεραπεύσω αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Ἀποκριθεὶς δὲ ὁ ἑκατόνταρχος ἔφη, “ ̊Κύριε, οὐκ εἰμὶ ἱκανὸς ἵνα μου ὑπὸ τὴν στέγην εἰσέλθῃς, ἀλλὰ μόνον εἰπὲ λόγῳ καὶ ἰαθήσεται ὁ παῖς μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Καὶ γὰρ ἐγὼ ἄνθρωπός εἰμι ὑπὸ ἐξουσίαν τασσόμενος, ἔχων ὑπʼ ἐμαυτὸν στρατιώτας, καὶ λέγω τούτῳ, ‘Πορεύθητι’, καὶ πορεύεται, καὶ ἄλλῳ, ‘Ἔρχου’, καὶ ἔρχεται, καὶ τῷ δούλῳ μου, ‘Ποίησον τοῦτο’, καὶ ποιεῖ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Ἀκούσας δὲ, ὁ  ̊Ἰησοῦς ἐθαύμασεν καὶ εἶπεν τοῖς ἀκολουθοῦσιν, “Ἀμὴν, λέγω ὑμῖν, παρʼ οὐδενὶ τοσαύτην πίστιν ἐν τῷ Ἰσραὴλ εὗρον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Λέγω δὲ ὑμῖν ὅτι πολλοὶ ἀπὸ ἀνατολῶν καὶ δυσμῶν ἥξουσιν καὶ ἀνακλιθήσονται μετὰ Ἀβραὰμ, καὶ Ἰσαὰκ, καὶ Ἰακὼβ, ἐν τῇ Βασιλείᾳ τῶν Οὐρανῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'οἱ δὲ υἱοὶ τῆς βασιλείας ἐκβληθήσονται εἰς τὸ σκότος τὸ ἐξώτερον, ἐκεῖ ἔσται ὁ κλαυθμὸς καὶ ὁ βρυγμὸς τῶν ὀδόντων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Καὶ εἶπεν ὁ  ̊Ἰησοῦς τῷ ἑκατοντάρχῃ, “Ὕπαγε, ὡς ἐπίστευσας, γενηθήτω σοι.” Καὶ ἰάθη ὁ παῖς ἐν τῇ ὥρᾳ ἐκείνῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 14, '¶Καὶ ἐλθὼν ὁ  ̊Ἰησοῦς εἰς τὴν οἰκίαν Πέτρου, εἶδεν τὴν πενθερὰν αὐτοῦ βεβλημένην καὶ πυρέσσουσαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 15, 'καὶ ἥψατο τῆς χειρὸς αὐτῆς, καὶ ἀφῆκεν αὐτὴν ὁ πυρετός, καὶ ἠγέρθη, καὶ διηκόνει αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 16, '¶Ὀψίας δὲ γενομένης, προσήνεγκαν αὐτῷ δαιμονιζομένους πολλούς, καὶ ἐξέβαλεν τὰ πνεύματα λόγῳ, καὶ πάντας τοὺς κακῶς ἔχοντας, ἐθεράπευσεν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 17, 'ὅπως πληρωθῇ τὸ ῥηθὲν διὰ Ἠσαΐου τοῦ προφήτου λέγοντος, “Αὐτὸς τὰς ἀσθενείας ἡμῶν ἔλαβεν καὶ τὰς νόσους ἐβάστασεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 18, '¶Ἰδὼν δὲ ὁ  ̊Ἰησοῦς ὄχλον περὶ αὐτὸν, ἐκέλευσεν ἀπελθεῖν εἰς τὸ πέραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 19, 'Καὶ προσελθὼν, εἷς γραμματεὺς εἶπεν αὐτῷ, “Διδάσκαλε, ἀκολουθήσω σοι ὅπου ἐὰν ἀπέρχῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 20, 'Καὶ λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Αἱ ἀλώπεκες φωλεοὺς ἔχουσιν καὶ τὰ πετεινὰ τοῦ οὐρανοῦ κατασκηνώσεις, ὁ δὲ Υἱὸς τοῦ Ἀνθρώπου οὐκ ἔχει ποῦ τὴν κεφαλὴν κλίνῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 21, 'Ἕτερος δὲ τῶν μαθητῶν εἶπεν αὐτῷ, “ ̊Κύριε, ἐπίτρεψόν μοι πρῶτον ἀπελθεῖν καὶ θάψαι τὸν πατέρα μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 22, 'Ὁ δὲ  ̊Ἰησοῦς λέγει αὐτῷ, “Ἀκολούθει μοι καὶ ἄφες τοὺς νεκροὺς θάψαι τοὺς ἑαυτῶν νεκρούς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 23, '¶Καὶ ἐμβάντι αὐτῷ εἰς πλοῖον, ἠκολούθησαν αὐτῷ οἱ μαθηταὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 24, 'Καὶ ἰδοὺ, σεισμὸς μέγας ἐγένετο ἐν τῇ θαλάσσῃ, ὥστε τὸ πλοῖον καλύπτεσθαι ὑπὸ τῶν κυμάτων, αὐτὸς δὲ ἐκάθευδεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 25, 'Καὶ προσελθόντες, ἤγειραν αὐτὸν λέγοντες, “ ̊Κύριε, σῶσον, ἀπολλύμεθα!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 26, 'Καὶ λέγει αὐτοῖς, “Τί δειλοί ἐστε, ὀλιγόπιστοι;” Τότε ἐγερθεὶς, ἐπετίμησεν τοῖς ἀνέμοις καὶ τῇ θαλάσσῃ, καὶ ἐγένετο γαλήνη μεγάλη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 27, 'Οἱ δὲ ἄνθρωποι ἐθαύμασαν λέγοντες, “Ποταπός ἐστιν οὗτος, ὅτι καὶ οἱ ἄνεμοι καὶ ἡ θάλασσα αὐτῷ ὑπακούουσιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 28, '¶Καὶ ἐλθόντος αὐτοῦ εἰς τὸ πέραν εἰς τὴν χώραν τῶν Γαδαρηνῶν, ὑπήντησαν αὐτῷ δύο δαιμονιζόμενοι ἐκ τῶν μνημείων ἐξερχόμενοι, χαλεποὶ λίαν ὥστε μὴ ἰσχύειν τινὰ παρελθεῖν διὰ τῆς ὁδοῦ ἐκείνης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 29, 'Καὶ ἰδοὺ, ἔκραξαν λέγοντες, “Τί ἡμῖν καὶ σοί, Υἱὲ τοῦ  ̊Θεοῦ; Ἦλθες ὧδε πρὸ καιροῦ βασανίσαι ἡμᾶς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 30, 'Ἦν δὲ μακρὰν ἀπʼ αὐτῶν ἀγέλη χοίρων πολλῶν βοσκομένη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 31, 'Οἱ δὲ δαίμονες παρεκάλουν αὐτὸν λέγοντες, “Εἰ ἐκβάλλεις ἡμᾶς, ἀπόστειλον ἡμᾶς εἰς τὴν ἀγέλην τῶν χοίρων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 32, 'Καὶ εἶπεν αὐτοῖς, “Ὑπάγετε.” Οἱ δὲ ἐξελθόντες ἀπῆλθον εἰς τοὺς χοίρους· καὶ ἰδοὺ, ὥρμησεν πᾶσα ἡ ἀγέλη κατὰ τοῦ κρημνοῦ εἰς τὴν θάλασσαν, καὶ ἀπέθανον ἐν τοῖς ὕδασιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 33, 'Οἱ δὲ βόσκοντες ἔφυγον, καὶ ἀπελθόντες εἰς τὴν πόλιν, ἀπήγγειλαν πάντα καὶ τὰ τῶν δαιμονιζομένων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 34, 'Καὶ ἰδοὺ, πᾶσα ἡ πόλις ἐξῆλθεν εἰς ὑπάντησιν τῷ  ̊Ἰησοῦ, καὶ ἰδόντες αὐτὸν, παρεκάλεσαν ὅπως μεταβῇ ἀπὸ τῶν ὁρίων αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, '¶Καὶ ἐμβὰς εἰς πλοῖον, διεπέρασεν καὶ ἦλθεν εἰς τὴν ἰδίαν πόλιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, '¶Καὶ ἰδοὺ, προσέφερον αὐτῷ παραλυτικὸν ἐπὶ κλίνης βεβλημένον. Καὶ ἰδὼν ὁ  ̊Ἰησοῦς τὴν πίστιν αὐτῶν, εἶπεν τῷ παραλυτικῷ, “Θάρσει, τέκνον, ἀφίενταί σου αἱ ἁμαρτίαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Καὶ ἰδού, τινες τῶν γραμματέων εἶπον ἐν ἑαυτοῖς, “Οὗτος βλασφημεῖ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Καὶ ἰδὼν ὁ  ̊Ἰησοῦς τὰς ἐνθυμήσεις αὐτῶν εἶπεν, “Ἵνα τί ἐνθυμεῖσθε πονηρὰ ἐν ταῖς καρδίαις ὑμῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Τί γάρ ἐστιν εὐκοπώτερον εἰπεῖν, ‘Ἀφίονται σου αἱ ἁμαρτίαι’, ἢ εἰπεῖν, ‘Ἔγειρε καὶ περιπάτει’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Ἵνα δὲ εἰδῆτε ὅτι ἐξουσίαν ἔχει ὁ Υἱὸς τοῦ Ἀνθρώπου ἐπὶ τῆς γῆς ἀφιέναι ἁμαρτίας” (τότε λέγει τῷ παραλυτικῷ), “Ἐγερθεὶς, ἆρόν σου τὴν κλίνην καὶ ὕπαγε εἰς τὸν οἶκόν σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Καὶ ἐγερθεὶς, ἀπῆλθεν εἰς τὸν οἶκον αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Ἰδόντες δὲ, οἱ ὄχλοι ἐφοβήθησαν καὶ ἐδόξασαν τὸν  ̊Θεὸν, τὸν δόντα ἐξουσίαν τοιαύτην τοῖς ἀνθρώποις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, '¶Καὶ παράγων ὁ  ̊Ἰησοῦς ἐκεῖθεν, εἶδεν ἄνθρωπον καθήμενον ἐπὶ τὸ τελώνιον Μαθθαῖον λεγόμενον, καὶ λέγει αὐτῷ. “Ἀκολούθει μοι.” Καὶ ἀναστὰς, ἠκολούθησεν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, '¶Καὶ ἐγένετο αὐτοῦ ἀνακειμένου ἐν τῇ οἰκίᾳ, καὶ ἰδοὺ, πολλοὶ τελῶναι καὶ ἁμαρτωλοὶ ἐλθόντες συνανέκειντο τῷ  ̊Ἰησοῦ καὶ τοῖς μαθηταῖς αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Καὶ ἰδόντες, οἱ Φαρισαῖοι ἔλεγον τοῖς μαθηταῖς αὐτοῦ, “Διὰ τί μετὰ τῶν τελωνῶν καὶ ἁμαρτωλῶν ἐσθίει ὁ διδάσκαλος ὑμῶν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'Ὁ δὲ ἀκούσας εἶπεν, “Οὐ χρείαν ἔχουσιν οἱ ἰσχύοντες ἰατροῦ, ἀλλὰ οἱ κακῶς ἔχοντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Πορευθέντες δὲ, μάθετε τί ἐστιν: ‘Ἔλεος θέλω καὶ οὐ θυσίαν’, οὐ γὰρ ἦλθον καλέσαι δικαίους, ἀλλὰ ἁμαρτωλούς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, '¶Τότε προσέρχονται αὐτῷ οἱ μαθηταὶ Ἰωάννου λέγοντες, “Διὰ τί ἡμεῖς καὶ οἱ Φαρισαῖοι νηστεύομεν, οἱ δὲ μαθηταί σου οὐ νηστεύουσιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Καὶ εἶπεν αὐτοῖς ὁ  ̊Ἰησοῦς, “Μὴ δύνανται οἱ υἱοὶ τοῦ νυμφῶνος πενθεῖν, ἐφʼ ὅσον μετʼ αὐτῶν ἐστιν ὁ νυμφίος; Ἐλεύσονται δὲ ἡμέραι ὅταν ἀπαρθῇ ἀπʼ αὐτῶν ὁ νυμφίος, καὶ τότε νηστεύσουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Οὐδεὶς δὲ ἐπιβάλλει ἐπίβλημα ῥάκους ἀγνάφου ἐπὶ ἱματίῳ παλαιῷ· αἴρει γὰρ τὸ πλήρωμα αὐτοῦ ἀπὸ τοῦ ἱματίου, καὶ χεῖρον σχίσμα γίνεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Οὐδὲ βάλλουσιν οἶνον νέον εἰς ἀσκοὺς παλαιούς· εἰ δὲ μή γε, ῥήγνυνται οἱ ἀσκοί, καὶ ὁ οἶνος ἐκχεῖται καὶ οἱ ἀσκοὶ ἀπόλλυνται. Ἀλλὰ βάλλουσιν οἶνον νέον εἰς ἀσκοὺς καινούς, καὶ ἀμφότεροι συντηροῦνται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, '¶Ταῦτα αὐτοῦ λαλοῦντος αὐτοῖς, ἰδοὺ, ἄρχων εἷς προσελθὼν, προσεκύνει αὐτῷ λέγων, ὅτι “Ἡ θυγάτηρ μου ἄρτι ἐτελεύτησεν· ἀλλὰ ἐλθὼν ἐπίθες τὴν χεῖρά σου ἐπʼ αὐτήν καὶ ζήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Καὶ ἐγερθεὶς, ὁ  ̊Ἰησοῦς ἠκολούθησεν αὐτῷ καὶ οἱ μαθηταὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Καὶ ἰδοὺ, γυνὴ αἱμορροοῦσα δώδεκα ἔτη προσελθοῦσα ὄπισθεν, ἥψατο τοῦ κρασπέδου τοῦ ἱματίου αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Ἔλεγεν γὰρ ἐν ἑαυτῇ, “Ἐὰν μόνον ἅψωμαι τοῦ ἱματίου αὐτοῦ, σωθήσομαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Ὁ δὲ  ̊Ἰησοῦς στραφεὶς καὶ ἰδὼν αὐτὴν εἶπεν, “Θάρσει, θύγατερ· ἡ πίστις σου σέσωκέν σε.” Καὶ ἐσώθη ἡ γυνὴ ἀπὸ τῆς ὥρας ἐκείνης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Καὶ ἐλθὼν ὁ  ̊Ἰησοῦς εἰς τὴν οἰκίαν τοῦ ἄρχοντος, καὶ ἰδὼν τοὺς αὐλητὰς καὶ τὸν ὄχλον θορυβούμενον');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'ἔλεγεν, “Ἀναχωρεῖτε, οὐ γὰρ ἀπέθανεν τὸ κοράσιον, ἀλλὰ καθεύδει.” Καὶ κατεγέλων αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Ὅτε δὲ ἐξεβλήθη ὁ ὄχλος, εἰσελθὼν ἐκράτησεν τῆς χειρὸς αὐτῆς, καὶ ἠγέρθη τὸ κοράσιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'Καὶ ἐξῆλθεν ἡ φήμη αὕτη εἰς ὅλην τὴν γῆν ἐκείνην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, '¶Καὶ παράγοντι ἐκεῖθεν τῷ  ̊Ἰησοῦ, ἠκολούθησαν αὐτῷ δύο τυφλοὶ κράζοντες καὶ λέγοντες, “Ἐλέησον ἡμᾶς, υἱὸς Δαυίδ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'Ἐλθόντι δὲ εἰς τὴν οἰκίαν, προσῆλθον αὐτῷ οἱ τυφλοί, καὶ λέγει αὐτοῖς ὁ  ̊Ἰησοῦς, “Πιστεύετε ὅτι δύναμαι τοῦτο ποιῆσαι;” Λέγουσιν αὐτῷ, “Ναί,  ̊Κύριε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 29, 'Τότε ἥψατο τῶν ὀφθαλμῶν αὐτῶν λέγων, “Κατὰ τὴν πίστιν ὑμῶν γενηθήτω ὑμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 30, 'Καὶ ἠνεῴχθησαν αὐτῶν οἱ ὀφθαλμοί. Καὶ ἐνεβριμήθη αὐτοῖς ὁ  ̊Ἰησοῦς λέγων, “Ὁρᾶτε μηδεὶς γινωσκέτω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 31, 'Οἱ δὲ ἐξελθόντες, διεφήμισαν αὐτὸν ἐν ὅλῃ τῇ γῇ ἐκείνῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 32, '¶Αὐτῶν δὲ ἐξερχομένων, ἰδοὺ, προσήνεγκαν αὐτῷ κωφὸν δαιμονιζόμενον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 33, 'Καὶ ἐκβληθέντος τοῦ δαιμονίου, ἐλάλησεν ὁ κωφός. Καὶ ἐθαύμασαν οἱ ὄχλοι λέγοντες, “Οὐδέποτε ἐφάνη οὕτως ἐν τῷ Ἰσραήλ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 34, 'Οἱ δὲ Φαρισαῖοι ἔλεγον, “Ἐν τῷ ἄρχοντι τῶν δαιμονίων ἐκβάλλει τὰ δαιμόνια.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 35, '¶Καὶ περιῆγεν ὁ  ̊Ἰησοῦς τὰς πόλεις πάσας καὶ τὰς κώμας, διδάσκων ἐν ταῖς συναγωγαῖς αὐτῶν, καὶ κηρύσσων τὸ εὐαγγέλιον τῆς βασιλείας, καὶ θεραπεύων πᾶσαν νόσον καὶ πᾶσαν μαλακίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 36, 'Ἰδὼν δὲ τοὺς ὄχλους, ἐσπλαγχνίσθη περὶ αὐτῶν, ὅτι ἦσαν ἐσκυλμένοι καὶ ἐρριμμένοι, ὡσεὶ πρόβατα μὴ ἔχοντα ποιμένα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 37, 'Τότε λέγει τοῖς μαθηταῖς αὐτοῦ, “Ὁ μὲν θερισμὸς πολύς, οἱ δὲ ἐργάται ὀλίγοι·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 38, 'δεήθητε οὖν τοῦ  ̊Κυρίου τοῦ θερισμοῦ, ὅπως ἐκβάλῃ ἐργάτας εἰς τὸν θερισμὸν αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, '¶Καὶ προσκαλεσάμενος τοὺς δώδεκα μαθητὰς αὐτοῦ, ἔδωκεν αὐτοῖς ἐξουσίαν πνευμάτων ἀκαθάρτων, ὥστε ἐκβάλλειν αὐτὰ καὶ θεραπεύειν πᾶσαν νόσον καὶ πᾶσαν μαλακίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Τῶν δὲ δώδεκα ἀποστόλων τὰ ὀνόματά ἐστιν ταῦτα: πρῶτος Σίμων ὁ λεγόμενος Πέτρος, καὶ Ἀνδρέας ὁ ἀδελφὸς αὐτοῦ, καὶ Ἰάκωβος ὁ τοῦ Ζεβεδαίου, καὶ Ἰωάννης ὁ ἀδελφὸς αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Φίλιππος καὶ Βαρθολομαῖος, Θωμᾶς καὶ Μαθθαῖος ὁ τελώνης, Ἰάκωβος ὁ τοῦ Ἁλφαίου καὶ Θαδδαῖος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Σίμων ὁ Καναναῖος καὶ Ἰούδας ὁ Ἰσκαριώτης, ὁ καὶ παραδοὺς αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, '¶Τούτους τοὺς δώδεκα ἀπέστειλεν ὁ  ̊Ἰησοῦς παραγγείλας αὐτοῖς λέγων, “Εἰς ὁδὸν ἐθνῶν μὴ ἀπέλθητε, καὶ εἰς πόλιν Σαμαρειτῶν μὴ εἰσέλθητε·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'πορεύεσθε δὲ μᾶλλον πρὸς τὰ πρόβατα τὰ ἀπολωλότα οἴκου Ἰσραήλ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Πορευόμενοι δὲ κηρύσσετε λέγοντες, ὅτι ‘Ἤγγικεν ἡ Βασιλεία τῶν Οὐρανῶν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Ἀσθενοῦντας θεραπεύετε, νεκροὺς ἐγείρετε, λεπροὺς καθαρίζετε, δαιμόνια ἐκβάλλετε· δωρεὰν ἐλάβετε, δωρεὰν δότε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Μὴ κτήσησθε χρυσὸν, μηδὲ ἄργυρον, μηδὲ χαλκὸν εἰς τὰς ζώνας ὑμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'μὴ πήραν εἰς ὁδὸν, μηδὲ δύο χιτῶνας, μηδὲ ὑποδήματα, μηδὲ ῥάβδον· ἄξιος γὰρ ὁ ἐργάτης τῆς τροφῆς αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Εἰς ἣν δʼ ἂν πόλιν ἢ κώμην εἰσέλθητε, ἐξετάσατε τίς ἐν αὐτῇ ἄξιός ἐστιν, κἀκεῖ μείνατε ἕως ἂν ἐξέλθητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Εἰσερχόμενοι δὲ εἰς τὴν οἰκίαν, ἀσπάσασθε αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'Καὶ ἐὰν μὲν ᾖ ἡ οἰκία ἀξία, ἐλθάτω ἡ εἰρήνη ὑμῶν ἐπʼ αὐτήν· ἐὰν δὲ μὴ ᾖ ἀξία, ἡ εἰρήνη ὑμῶν πρὸς ὑμᾶς ἐπιστραφήτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Καὶ ὃς ἂν μὴ δέξηται ὑμᾶς, μηδὲ ἀκούσῃ τοὺς λόγους ὑμῶν, ἐξερχόμενοι ἔξω τῆς οἰκίας ἢ τῆς πόλεως ἐκείνης, ἐκτινάξατε τὸν κονιορτὸν τῶν ποδῶν ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Ἀμὴν, λέγω ὑμῖν, ἀνεκτότερον ἔσται γῇ Σοδόμων καὶ Γομόρρων ἐν ἡμέρᾳ κρίσεως, ἢ τῇ πόλει ἐκείνῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, '¶Ἰδοὺ, ἐγὼ ἀποστέλλω ὑμᾶς ὡς πρόβατα ἐν μέσῳ λύκων· γίνεσθε οὖν φρόνιμοι ὡς οἱ ὄφεις καὶ ἀκέραιοι ὡς αἱ περιστεραί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'Προσέχετε δὲ ἀπὸ τῶν ἀνθρώπων· παραδώσουσιν γὰρ ὑμᾶς εἰς συνέδρια, καὶ ἐν ταῖς συναγωγαῖς αὐτῶν μαστιγώσουσιν ὑμᾶς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'καὶ ἐπὶ ἡγεμόνας δὲ καὶ βασιλεῖς ἀχθήσεσθε ἕνεκεν ἐμοῦ, εἰς μαρτύριον αὐτοῖς καὶ τοῖς ἔθνεσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Ὅταν δὲ παραδῶσιν ὑμᾶς, μὴ μεριμνήσητε πῶς ἢ τί λαλήσητε· δοθήσεται γὰρ ὑμῖν ἐν ἐκείνῃ τῇ ὥρᾳ τί λαλήσητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'Οὐ γὰρ ὑμεῖς ἐστε οἱ λαλοῦντες, ἀλλὰ τὸ  ̊Πνεῦμα τοῦ Πατρὸς ὑμῶν τὸ λαλοῦν ἐν ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'Παραδώσει δὲ ἀδελφὸς ἀδελφὸν εἰς θάνατον, καὶ πατὴρ τέκνον, καὶ ἐπαναστήσονται τέκνα ἐπὶ γονεῖς, καὶ θανατώσουσιν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'Καὶ ἔσεσθε μισούμενοι ὑπὸ πάντων διὰ τὸ ὄνομά μου· ὁ δὲ ὑπομείνας εἰς τέλος, οὗτος σωθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Ὅταν δὲ διώκωσιν ὑμᾶς ἐν τῇ πόλει ταύτῃ, φεύγετε εἰς τὴν ἑτέραν· ἀμὴν, γὰρ λέγω ὑμῖν, οὐ μὴ τελέσητε τὰς πόλεις τοῦ Ἰσραὴλ, ἕως ἔλθῃ ὁ Υἱὸς τοῦ Ἀνθρώπου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, '¶Οὐκ ἔστιν μαθητὴς ὑπὲρ τὸν διδάσκαλον, οὐδὲ δοῦλος ὑπὲρ τὸν κύριον αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Ἀρκετὸν τῷ μαθητῇ ἵνα γένηται ὡς ὁ διδάσκαλος αὐτοῦ, καὶ ὁ δοῦλος ὡς ὁ κύριος αὐτοῦ. Εἰ τὸν οἰκοδεσπότην Βεελζεβοὺλ ἐπεκάλεσαν, πόσῳ μᾶλλον τοὺς οἰκιακοὺς αὐτοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, '¶Μὴ οὖν φοβηθῆτε αὐτούς· οὐδὲν γάρ ἐστιν κεκαλυμμένον ὃ οὐκ ἀποκαλυφθήσεται, καὶ κρυπτὸν ὃ οὐ γνωσθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Ὃ λέγω ὑμῖν ἐν τῇ σκοτίᾳ, εἴπατε ἐν τῷ φωτί· καὶ ὃ εἰς τὸ οὖς ἀκούετε, κηρύξατε ἐπὶ τῶν δωμάτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Καὶ μὴ φοβηθῆτε ἀπὸ τῶν ἀποκτεννόντων τὸ σῶμα, τὴν δὲ ψυχὴν μὴ δυναμένων ἀποκτεῖναι· φοβεῖσθε δὲ μᾶλλον τὸν δυνάμενον καὶ ψυχὴν καὶ σῶμα ἀπολέσαι ἐν Γεέννῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Οὐχὶ δύο στρουθία ἀσσαρίου πωλεῖται; Καὶ ἓν ἐξ αὐτῶν οὐ πεσεῖται ἐπὶ τὴν γῆν, ἄνευ τοῦ Πατρὸς ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Ὑμῶν δὲ καὶ αἱ τρίχες τῆς κεφαλῆς πᾶσαι ἠριθμημέναι εἰσίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Μὴ οὖν φοβεῖσθε· πολλῶν στρουθίων διαφέρετε ὑμεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, '¶Πᾶς οὖν ὅστις ὁμολογήσει ἐν ἐμοὶ ἔμπροσθεν τῶν ἀνθρώπων, ὁμολογήσω κἀγὼ ἐν αὐτῷ ἔμπροσθεν τοῦ Πατρός μου τοῦ ἐν οὐρανοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Ὅστις δʼ ἀρνήσηταί με ἔμπροσθεν τῶν ἀνθρώπων, ἀρνήσομαι κἀγὼ αὐτὸν ἔμπροσθεν τοῦ Πατρός μου τοῦ ἐν οὐρανοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, '¶Μὴ νομίσητε ὅτι ἦλθον βαλεῖν εἰρήνην ἐπὶ τὴν γῆν· οὐκ ἦλθον βαλεῖν εἰρήνην, ἀλλὰ μάχαιραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Ἦλθον γὰρ ‘διχάσαι ἄνθρωπον κατὰ τοῦ πατρὸς αὐτοῦ, καὶ θυγατέρα κατὰ τῆς μητρὸς αὐτῆς, καὶ νύμφην κατὰ τῆς πενθερᾶς αὐτῆς');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'καὶ ἐχθροὶ τοῦ ἀνθρώπου οἱ οἰκιακοὶ αὐτοῦ’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Ὁ φιλῶν πατέρα ἢ μητέρα ὑπὲρ ἐμὲ, οὐκ ἔστιν μου ἄξιος· καὶ ὁ φιλῶν υἱὸν ἢ θυγατέρα ὑπὲρ ἐμὲ, οὐκ ἔστιν μου ἄξιος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Καὶ ὃς οὐ λαμβάνει τὸν σταυρὸν αὐτοῦ καὶ ἀκολουθεῖ ὀπίσω μου, οὐκ ἔστιν μου ἄξιος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Ὁ εὑρὼν τὴν ψυχὴν αὐτοῦ ἀπολέσει αὐτήν, καὶ ὁ ἀπολέσας τὴν ψυχὴν αὐτοῦ ἕνεκεν ἐμοῦ εὑρήσει αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 40, '¶Ὁ δεχόμενος ὑμᾶς ἐμὲ δέχεται, καὶ ὁ ἐμὲ δεχόμενος δέχεται τὸν ἀποστείλαντά με.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 41, 'Ὁ δεχόμενος προφήτην εἰς ὄνομα προφήτου, μισθὸν προφήτου λήμψεται, καὶ ὁ δεχόμενος δίκαιον εἰς ὄνομα δικαίου, μισθὸν δικαίου λήμψεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 42, 'Καὶ ὃς ἐὰν ποτίσῃ ἕνα τῶν μικρῶν τούτων ποτήριον ψυχροῦ, μόνον εἰς ὄνομα μαθητοῦ, ἀμὴν, λέγω ὑμῖν, οὐ μὴ ἀπολέσῃ τὸν μισθὸν αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, '¶Καὶ ἐγένετο ὅτε ἐτέλεσεν ὁ  ̊Ἰησοῦς διατάσσων τοῖς δώδεκα μαθηταῖς αὐτοῦ, μετέβη ἐκεῖθεν τοῦ διδάσκειν καὶ κηρύσσειν ἐν ταῖς πόλεσιν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, '¶Ὁ δὲ Ἰωάννης, ἀκούσας ἐν τῷ δεσμωτηρίῳ τὰ ἔργα τοῦ  ̊Χριστοῦ, πέμψας διὰ τῶν μαθητῶν αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'εἶπεν αὐτῷ, “Σὺ εἶ ὁ ἐρχόμενος, ἢ ἕτερον προσδοκῶμεν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Καὶ ἀποκριθεὶς ὁ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Πορευθέντες ἀπαγγείλατε Ἰωάννῃ ἃ ἀκούετε καὶ βλέπετε:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, '‘τυφλοὶ ἀναβλέπουσιν’, καὶ χωλοὶ περιπατοῦσιν, λεπροὶ καθαρίζονται, καὶ κωφοὶ ἀκούουσιν, καὶ νεκροὶ ἐγείρονται, καὶ ‘πτωχοὶ εὐαγγελίζονται’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Καὶ μακάριός ἐστιν ὃς ἐὰν μὴ σκανδαλισθῇ ἐν ἐμοί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, '¶Τούτων δὲ πορευομένων, ἤρξατο ὁ  ̊Ἰησοῦς λέγειν τοῖς ὄχλοις περὶ Ἰωάννου, “Τί ἐξήλθατε εἰς τὴν ἔρημον θεάσασθαι; Κάλαμον ὑπὸ ἀνέμου σαλευόμενον;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Ἀλλὰ τί ἐξήλθατε ἰδεῖν; Ἄνθρωπον ἐν μαλακοῖς ἠμφιεσμένον; Ἰδοὺ, οἱ τὰ μαλακὰ φοροῦντες ἐν τοῖς οἴκοις τῶν βασιλέων');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'ἀλλὰ τί ἐξήλθατε; Προφήτην ἰδεῖν; Ναί, λέγω ὑμῖν, καὶ περισσότερον προφήτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Οὗτός ἐστιν περὶ οὗ γέγραπται, ‘Ἰδοὺ, ἐγὼ ἀποστέλλω τὸν ἄγγελόν μου πρὸ προσώπου σου, ὃς κατασκευάσει τὴν ὁδόν σου ἔμπροσθέν σου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Ἀμὴν, λέγω ὑμῖν, οὐκ ἐγήγερται ἐν γεννητοῖς γυναικῶν μείζων Ἰωάννου τοῦ Βαπτιστοῦ. Ὁ δὲ μικρότερος ἐν τῇ Βασιλείᾳ τῶν Οὐρανῶν, μείζων αὐτοῦ ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Ἀπὸ δὲ τῶν ἡμερῶν Ἰωάννου τοῦ Βαπτιστοῦ ἕως ἄρτι, ἡ Βασιλεία τῶν Οὐρανῶν βιάζεται, καὶ βιασταὶ ἁρπάζουσιν αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Πάντες γὰρ οἱ προφῆται καὶ ὁ νόμος ἕως Ἰωάννου ἐπροφήτευσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Καὶ εἰ θέλετε δέξασθαι, αὐτός ἐστιν Ἠλίας, ὁ μέλλων ἔρχεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Ὁ ἔχων ὦτα ἀκούειν, ἀκουέτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, '¶Τίνι δὲ ὁμοιώσω τὴν γενεὰν ταύτην; Ὁμοία ἐστὶν παιδίοις καθημένοις ἐν ταῖς ἀγοραῖς, ἃ προσφωνοῦντα τοῖς ἑτέροις');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'λέγουσιν, ‘Ηὐλήσαμεν ὑμῖν καὶ οὐκ ὠρχήσασθε· ἐθρηνήσαμεν καὶ οὐκ ἐκόψασθε.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'Ἦλθεν γὰρ Ἰωάννης μήτε ἐσθίων μήτε πίνων, καὶ λέγουσιν, ‘Δαιμόνιον ἔχει.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Ἦλθεν ὁ Υἱὸς τοῦ Ἀνθρώπου ἐσθίων καὶ πίνων, καὶ λέγουσιν, ‘Ἰδοὺ, ἄνθρωπος, φάγος καὶ οἰνοπότης, τελωνῶν φίλος καὶ ἁμαρτωλῶν!’ Καὶ ἐδικαιώθη ἡ σοφία ἀπὸ τῶν τέκνων αὐτῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, '¶Τότε ἤρξατο ὀνειδίζειν τὰς πόλεις ἐν αἷς ἐγένοντο αἱ πλεῖσται δυνάμεις αὐτοῦ, ὅτι οὐ μετενόησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Οὐαί σοι, Χοραζίν! Οὐαί σοι, Βηθσαϊδάν! Ὅτι εἰ ἐν Τύρῳ καὶ Σιδῶνι ἐγένοντο αἱ δυνάμεις αἱ γενόμεναι ἐν ὑμῖν, πάλαι ἂν ἐν σάκκῳ καὶ σποδῷ μετενόησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Πλὴν λέγω ὑμῖν, Τύρῳ καὶ Σιδῶνι ἀνεκτότερον ἔσται ἐν ἡμέρᾳ κρίσεως ἢ ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Καὶ σύ, Καφαρναούμ, μὴ ἕως οὐρανοῦ ὑψωθήσῃ; ἕως ἍΙδου καταβήσῃ. Ὅτι εἰ ἐν Σοδόμοις ἐγενήθησαν αἱ δυνάμεις αἱ γενόμεναι ἐν σοί, ἔμεινεν ἂν μέχρι τῆς σήμερον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Πλὴν λέγω ὑμῖν ὅτι γῇ Σοδόμων ἀνεκτότερον ἔσται ἐν ἡμέρᾳ κρίσεως ἢ σοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, '¶Ἐν ἐκείνῳ τῷ καιρῷ ἀποκριθεὶς ὁ  ̊Ἰησοῦς εἶπεν, “Ἐξομολογοῦμαί σοι, Πάτερ,  ̊Κύριε τοῦ οὐρανοῦ καὶ τῆς γῆς, ὅτι ἔκρυψας ταῦτα ἀπὸ σοφῶν καὶ συνετῶν, καὶ ἀπεκάλυψας αὐτὰ νηπίοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Ναί, ὁ Πατήρ, ὅτι οὕτως εὐδοκία ἐγένετο ἔμπροσθέν σου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Πάντα μοι παρεδόθη ὑπὸ τοῦ Πατρός μου, καὶ οὐδεὶς ἐπιγινώσκει τὸν Υἱὸν, εἰ μὴ ὁ Πατήρ, οὐδὲ τὸν Πατέρα τις ἐπιγινώσκει, εἰ μὴ ὁ Υἱὸς, καὶ ᾧ ἐὰν βούληται ὁ Υἱὸς ἀποκαλύψαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, '¶Δεῦτε πρός με, πάντες οἱ κοπιῶντες καὶ πεφορτισμένοι, κἀγὼ ἀναπαύσω ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Ἄρατε τὸν ζυγόν μου ἐφʼ ὑμᾶς, καὶ μάθετε ἀπʼ ἐμοῦ, ὅτι πραΰς εἰμι καὶ ταπεινὸς τῇ καρδίᾳ, ‘καὶ εὑρήσετε ἀνάπαυσιν ταῖς ψυχαῖς ὑμῶν’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Ὁ γὰρ ζυγός μου χρηστὸς καὶ τὸ φορτίον μου ἐλαφρόν ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, '¶Ἐν ἐκείνῳ τῷ καιρῷ, ἐπορεύθη ὁ  ̊Ἰησοῦς τοῖς Σάββασιν διὰ τῶν σπορίμων· οἱ δὲ μαθηταὶ αὐτοῦ ἐπείνασαν, καὶ ἤρξαντο τίλλειν στάχυας καὶ ἐσθίειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'Οἱ δὲ Φαρισαῖοι ἰδόντες, εἶπαν αὐτῷ, “Ἰδοὺ, οἱ μαθηταί σου ποιοῦσιν ὃ οὐκ ἔξεστιν ποιεῖν ἐν Σαββάτῳ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Ὁ δὲ εἶπεν αὐτοῖς, “Οὐκ ἀνέγνωτε τί ἐποίησεν Δαυὶδ, ὅτε ἐπείνασεν καὶ οἱ μετʼ αὐτοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Πῶς εἰσῆλθεν εἰς τὸν οἶκον τοῦ  ̊Θεοῦ, καὶ τοὺς ἄρτους τῆς Προθέσεως ἔφαγον, ὃ οὐκ ἐξὸν ἦν αὐτῷ φαγεῖν, οὐδὲ τοῖς μετʼ αὐτοῦ, εἰ μὴ τοῖς ἱερεῦσιν μόνοις;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'Ἢ οὐκ ἀνέγνωτε ἐν τῷ νόμῳ ὅτι τοῖς Σάββασιν οἱ ἱερεῖς ἐν τῷ ἱερῷ τὸ Σάββατον βεβηλοῦσιν, καὶ ἀναίτιοί εἰσιν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Λέγω δὲ ὑμῖν ὅτι τοῦ ἱεροῦ μεῖζόν ἐστιν ὧδε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Εἰ δὲ ἐγνώκειτε τί ἐστιν: ‘Ἔλεος θέλω καὶ οὐ θυσίαν’, οὐκ ἂν κατεδικάσατε τοὺς ἀναιτίους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, ' ̊Κύριος γάρ ἐστιν τοῦ Σαββάτου ὁ Υἱὸς τοῦ Ἀνθρώπου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, '¶Καὶ μεταβὰς ἐκεῖθεν, ἦλθεν εἰς τὴν συναγωγὴν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Καὶ ἰδοὺ, ἄνθρωπος χεῖρα ἔχων ξηράν. Καὶ ἐπηρώτησαν αὐτὸν λέγοντες, “Εἰ ἔξεστιν τοῖς Σάββασιν θεραπεύειν;” Ἵνα κατηγορήσωσιν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Ὁ δὲ εἶπεν αὐτοῖς, “Τίς ἔσται ἐξ ὑμῶν ἄνθρωπος, ὃς ἕξει πρόβατον ἕν, καὶ ἐὰν ἐμπέσῃ τοῦτο τοῖς Σάββασιν εἰς βόθυνον, οὐχὶ κρατήσει αὐτὸ καὶ ἐγερεῖ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Πόσῳ οὖν διαφέρει ἄνθρωπος προβάτου; Ὥστε ἔξεστιν τοῖς Σάββασιν καλῶς ποιεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'Τότε λέγει τῷ ἀνθρώπῳ, “Ἔκτεινόν σου τὴν χεῖρα.” Καὶ ἐξέτεινεν, καὶ ἀπεκατεστάθη, ὑγιὴς ὡς ἡ ἄλλη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Ἐξελθόντες δὲ, οἱ Φαρισαῖοι συμβούλιον ἔλαβον κατʼ αὐτοῦ, ὅπως αὐτὸν ἀπολέσωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, '¶Ὁ δὲ  ̊Ἰησοῦς γνοὺς, ἀνεχώρησεν ἐκεῖθεν. Καὶ ἠκολούθησαν αὐτῷ πολλοί, καὶ ἐθεράπευσεν αὐτοὺς πάντας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'καὶ ἐπετίμησεν αὐτοῖς ἵνα μὴ φανερὸν αὐτὸν ποιήσωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Ἵνα πληρωθῇ τὸ ῥηθὲν διὰ Ἠσαΐου τοῦ προφήτου λέγοντος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, '“Ἰδοὺ, ὁ παῖς μου ὃν ᾑρέτισα, ὁ ἀγαπητός μου ὃν εὐδόκησεν ἡ ψυχή μου. Θήσω τὸ  ̊Πνεῦμά μου ἐπʼ αὐτόν, καὶ κρίσιν τοῖς ἔθνεσιν ἀπαγγελεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'Οὐκ ἐρίσει, οὐδὲ κραυγάσει, οὐδὲ ἀκούσει τις ἐν ταῖς πλατείαις τὴν φωνὴν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'Κάλαμον συντετριμμένον οὐ κατεάξει, καὶ λίνον τυφόμενον οὐ σβέσει, ἕως ἂν ἐκβάλῃ εἰς νῖκος τὴν κρίσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Καὶ τῷ ὀνόματι αὐτοῦ ἔθνη ἐλπιοῦσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, '¶Τότε προσηνέχθη αὐτῷ δαιμονιζόμενος, τυφλὸς καὶ κωφός, καὶ ἐθεράπευσεν αὐτόν, ὥστε τὸν κωφὸν λαλεῖν καὶ βλέπειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'Καὶ ἐξίσταντο πάντες οἱ ὄχλοι καὶ ἔλεγον, “Μήτι οὗτός ἐστιν ὁ υἱὸς Δαυίδ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'Οἱ δὲ Φαρισαῖοι ἀκούσαντες εἶπον, “Οὗτος οὐκ ἐκβάλλει τὰ δαιμόνια, εἰ μὴ ἐν τῷ Βεεζεβοὺλ, ἄρχοντι τῶν δαιμονίων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Εἰδὼς δὲ τὰς ἐνθυμήσεις αὐτῶν, εἶπεν αὐτοῖς, “Πᾶσα βασιλεία μερισθεῖσα καθʼ ἑαυτῆς ἐρημοῦται, καὶ πᾶσα πόλις ἢ οἰκία μερισθεῖσα καθʼ ἑαυτῆς οὐ σταθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Καὶ εἰ ὁ Σατανᾶς τὸν Σατανᾶν ἐκβάλλει, ἐφʼ ἑαυτὸν ἐμερίσθη. Πῶς οὖν σταθήσεται ἡ βασιλεία αὐτοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Καὶ εἰ ἐγὼ ἐν Βεεζεβοὺλ ἐκβάλλω τὰ δαιμόνια, οἱ υἱοὶ ὑμῶν ἐν τίνι ἐκβάλλουσιν; Διὰ τοῦτο, αὐτοὶ κριταὶ ἔσονται ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Εἰ δὲ ἐν  ̊Πνεύματι  ̊Θεοῦ ἐγὼ ἐκβάλλω τὰ δαιμόνια, ἄρα ἔφθασεν ἐφʼ ὑμᾶς ἡ Βασιλεία τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Ἢ πῶς δύναταί τις εἰσελθεῖν εἰς τὴν οἰκίαν τοῦ ἰσχυροῦ καὶ τὰ σκεύη αὐτοῦ ἁρπάσαι, ἐὰν μὴ πρῶτον δήσῃ τὸν ἰσχυρόν; Καὶ τότε τὴν οἰκίαν αὐτοῦ διαρπάσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 30, 'Ὁ μὴ ὢν μετʼ ἐμοῦ κατʼ ἐμοῦ ἐστιν, καὶ ὁ μὴ συνάγων μετʼ ἐμοῦ σκορπίζει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 31, 'Διὰ τοῦτο λέγω ὑμῖν, πᾶσα ἁμαρτία καὶ βλασφημία ἀφεθήσεται τοῖς ἀνθρώποις, ἡ δὲ τοῦ  ̊Πνεύματος βλασφημία οὐκ ἀφεθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 32, 'Καὶ ὃς ἐὰν εἴπῃ λόγον κατὰ τοῦ Υἱοῦ τοῦ Ἀνθρώπου, ἀφεθήσεται αὐτῷ· ὃς δʼ ἂν εἴπῃ κατὰ τοῦ  ̊Πνεύματος τοῦ Ἁγίου, οὐκ ἀφεθήσεται αὐτῷ, οὔτε ἐν τούτῳ τῷ αἰῶνι οὔτε ἐν τῷ μέλλοντι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 33, '¶Ἢ ποιήσατε τὸ δένδρον καλὸν καὶ τὸν καρπὸν αὐτοῦ καλόν, ἢ ποιήσατε τὸ δένδρον σαπρὸν καὶ τὸν καρπὸν αὐτοῦ σαπρόν· ἐκ γὰρ τοῦ καρποῦ, τὸ δένδρον γινώσκεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 34, 'Γεννήματα ἐχιδνῶν, πῶς δύνασθε ἀγαθὰ λαλεῖν, πονηροὶ ὄντες; Ἐκ γὰρ τοῦ περισσεύματος τῆς καρδίας, τὸ στόμα λαλεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 35, 'Ὁ ἀγαθὸς ἄνθρωπος ἐκ τοῦ ἀγαθοῦ θησαυροῦ ἐκβάλλει ἀγαθά, καὶ ὁ πονηρὸς ἄνθρωπος ἐκ τοῦ πονηροῦ θησαυροῦ ἐκβάλλει πονηρά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 36, 'Λέγω δὲ ὑμῖν ὅτι πᾶν ῥῆμα ἀργὸν ὃ λαλήσουσιν οἱ ἄνθρωποι, ἀποδώσουσιν περὶ αὐτοῦ λόγον ἐν ἡμέρᾳ κρίσεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 37, 'Ἐκ γὰρ τῶν λόγων σου δικαιωθήσῃ, καὶ ἐκ τῶν λόγων σου καταδικασθήσῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 38, '¶Τότε ἀπεκρίθησαν αὐτῷ τινες τῶν γραμματέων καὶ Φαρισαίων λέγοντες, “Διδάσκαλε, θέλομεν ἀπὸ σοῦ σημεῖον ἰδεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 39, 'Ὁ δὲ ἀποκριθεὶς εἶπεν αὐτοῖς, “Γενεὰ πονηρὰ καὶ μοιχαλὶς σημεῖον ἐπιζητεῖ, καὶ σημεῖον οὐ δοθήσεται αὐτῇ, εἰ μὴ τὸ σημεῖον Ἰωνᾶ τοῦ προφήτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 40, 'Ὥσπερ γὰρ ‘ἦν Ἰωνᾶς ἐν τῇ κοιλίᾳ τοῦ κήτους τρεῖς ἡμέρας καὶ τρεῖς νύκτας’, οὕτως ἔσται ὁ Υἱὸς τοῦ Ἀνθρώπου ἐν τῇ καρδίᾳ τῆς γῆς τρεῖς ἡμέρας καὶ τρεῖς νύκτας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 41, 'Ἄνδρες Νινευῖται ἀναστήσονται ἐν τῇ κρίσει μετὰ τῆς γενεᾶς ταύτης, καὶ κατακρινοῦσιν αὐτήν· ὅτι μετενόησαν εἰς τὸ κήρυγμα Ἰωνᾶ, καὶ ἰδοὺ, πλεῖον Ἰωνᾶ ὧδε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 42, 'Βασίλισσα νότου ἐγερθήσεται ἐν τῇ κρίσει μετὰ τῆς γενεᾶς ταύτης, καὶ κατακρινεῖ αὐτήν· ὅτι ἦλθεν ἐκ τῶν περάτων τῆς γῆς ἀκοῦσαι τὴν σοφίαν Σολομῶνος, καὶ ἰδοὺ, πλεῖον Σολομῶνος ὧδε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 43, '¶Ὅταν δὲ τὸ ἀκάθαρτον πνεῦμα ἐξέλθῃ ἀπὸ τοῦ ἀνθρώπου, διέρχεται διʼ ἀνύδρων τόπων ζητοῦν ἀνάπαυσιν καὶ οὐχ εὑρίσκει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 44, 'Τότε λέγει, ‘Εἰς τὸν οἶκόν μου ἐπιστρέψω ὅθεν ἐξῆλθον.’ Καὶ ἐλθὸν, εὑρίσκει σχολάζοντα σεσαρωμένον καὶ κεκοσμημένον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 45, 'Τότε πορεύεται καὶ παραλαμβάνει μεθʼ ἑαυτοῦ ἑπτὰ ἕτερα πνεύματα πονηρότερα ἑαυτοῦ, καὶ εἰσελθόντα κατοικεῖ ἐκεῖ· καὶ γίνεται τὰ ἔσχατα τοῦ ἀνθρώπου ἐκείνου χείρονα τῶν πρώτων. Οὕτως ἔσται καὶ τῇ γενεᾷ ταύτῃ τῇ πονηρᾷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 46, '¶Ἔτι αὐτοῦ λαλοῦντος τοῖς ὄχλοις, ἰδοὺ, ἡ μήτηρ καὶ οἱ ἀδελφοὶ αὐτοῦ εἱστήκεισαν ἔξω, ζητοῦντες αὐτῷ λαλῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 47, 'Εἶπεν δέ τις αὐτῷ, “Ἰδοὺ, ἡ μήτηρ σου καὶ οἱ ἀδελφοί σου ἔξω ἑστήκασιν ζητοῦντές σοι λαλῆσαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 48, 'Ὁ δὲ ἀποκριθεὶς εἶπεν τῷ λέγοντι αὐτῷ, “Τίς ἐστιν ἡ μήτηρ μου καὶ τίνες εἰσὶν οἱ ἀδελφοί μου;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 49, 'Καὶ ἐκτείνας τὴν χεῖρα αὐτοῦ ἐπὶ τοὺς μαθητὰς αὐτοῦ εἶπεν, “Ἰδοὺ, ἡ μήτηρ μου καὶ οἱ ἀδελφοί μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 50, 'Ὅστις γὰρ ἂν ποιήσῃ τὸ θέλημα τοῦ Πατρός μου τοῦ ἐν οὐρανοῖς, αὐτός μου ἀδελφὸς, καὶ ἀδελφὴ, καὶ μήτηρ ἐστίν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, '¶Ἐν τῇ ἡμέρᾳ ἐκείνῃ, ἐξελθὼν ὁ  ̊Ἰησοῦς τῆς οἰκίας, ἐκάθητο παρὰ τὴν θάλασσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Καὶ συνήχθησαν πρὸς αὐτὸν ὄχλοι πολλοί, ὥστε αὐτὸν εἰς πλοῖον ἐμβάντα καθῆσθαι, καὶ πᾶς ὁ ὄχλος ἐπὶ τὸν αἰγιαλὸν εἱστήκει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Καὶ ἐλάλησεν αὐτοῖς πολλὰ ἐν παραβολαῖς λέγων, “Ἰδοὺ, ἐξῆλθεν ὁ σπείρων τοῦ σπείρειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Καὶ ἐν τῷ σπείρειν αὐτὸν, ἃ μὲν ἔπεσεν παρὰ τὴν ὁδόν, καὶ ἦλθεν τὰ πετεινὰ καὶ κατέφαγεν αὐτά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Ἄλλα δὲ ἔπεσεν ἐπὶ τὰ πετρώδη, ὅπου οὐκ εἶχεν γῆν πολλήν, καὶ εὐθέως ἐξανέτειλεν διὰ τὸ μὴ ἔχειν βάθος γῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'ἡλίου δὲ ἀνατείλαντος, ἐκαυματίσθη καὶ διὰ τὸ μὴ ἔχειν ῥίζαν ἐξηράνθη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Ἄλλα δὲ ἔπεσεν ἐπὶ τὰς ἀκάνθας, καὶ ἀνέβησαν αἱ ἄκανθαι καὶ ἀπέπνιξαν αὐτά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Ἄλλα δὲ ἔπεσεν ἐπὶ τὴν γῆν τὴν καλὴν, καὶ ἐδίδου καρπόν– ὃ μὲν ἑκατὸν, ὃ δὲ ἑξήκοντα, ὃ δὲ τριάκοντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Ὁ ἔχων ὦτα, ἀκουέτω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, '¶Καὶ προσελθόντες οἱ μαθηταὶ εἶπαν αὐτῷ, “Διὰ τί ἐν παραβολαῖς λαλεῖς αὐτοῖς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Ὁ δὲ ἀποκριθεὶς εἶπεν αὐτοῖς, “Ὅτι ὑμῖν δέδοται γνῶναι τὰ μυστήρια τῆς Βασιλείας τῶν Οὐρανῶν, ἐκείνοις δὲ οὐ δέδοται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Ὅστις γὰρ ἔχει, δοθήσεται αὐτῷ καὶ περισσευθήσεται· ὅστις δὲ οὐκ ἔχει, καὶ ὃ ἔχει ἀρθήσεται ἀπʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Διὰ τοῦτο ἐν παραβολαῖς αὐτοῖς λαλῶ, ὅτι βλέποντες οὐ βλέπουσιν, καὶ ἀκούοντες οὐκ ἀκούουσιν, οὐδὲ συνίουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Καὶ ἀναπληροῦται αὐτοῖς ἡ προφητεία Ἠσαΐου ἡ λέγουσα, ‘Ἀκοῇ ἀκούσετε καὶ οὐ μὴ συνῆτε, καὶ βλέποντες βλέψετε καὶ οὐ μὴ ἴδητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Ἐπαχύνθη γὰρ ἡ καρδία τοῦ λαοῦ τούτου, καὶ τοῖς ὠσὶν βαρέως ἤκουσαν, καὶ τοὺς ὀφθαλμοὺς αὐτῶν ἐκάμμυσαν· μήποτε ἴδωσιν τοῖς ὀφθαλμοῖς, καὶ τοῖς ὠσὶν ἀκούσωσιν, καὶ τῇ καρδίᾳ συνῶσιν, καὶ ἐπιστρέψωσιν καὶ ἰάσομαι αὐτούς.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Ὑμῶν δὲ μακάριοι οἱ ὀφθαλμοὶ ὅτι βλέπουσιν, καὶ τὰ ὦτα ὑμῶν ὅτι ἀκούουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Ἀμὴν, γὰρ λέγω ὑμῖν ὅτι πολλοὶ προφῆται καὶ δίκαιοι ἐπεθύμησαν ἰδεῖν ἃ βλέπετε, καὶ οὐκ εἶδαν, καὶ ἀκοῦσαι ἃ ἀκούετε, καὶ οὐκ ἤκουσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, '¶Ὑμεῖς οὖν ἀκούσατε τὴν παραβολὴν τοῦ σπείραντος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Παντὸς ἀκούοντος τὸν λόγον τῆς βασιλείας καὶ μὴ συνιέντος, ἔρχεται ὁ πονηρὸς καὶ ἁρπάζει τὸ ἐσπαρμένον ἐν τῇ καρδίᾳ αὐτοῦ. Οὗτός ἐστιν ὁ παρὰ τὴν ὁδὸν σπαρείς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Ὁ δὲ ἐπὶ τὰ πετρώδη σπαρείς, οὗτός ἐστιν ὁ τὸν λόγον ἀκούων καὶ εὐθὺς μετὰ χαρᾶς λαμβάνων αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'οὐκ ἔχει δὲ ῥίζαν ἐν ἑαυτῷ, ἀλλὰ πρόσκαιρός ἐστιν, γενομένης δὲ θλίψεως ἢ διωγμοῦ διὰ τὸν λόγον, εὐθὺς σκανδαλίζεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Ὁ δὲ εἰς τὰς ἀκάνθας σπαρείς, οὗτός ἐστιν ὁ τὸν λόγον ἀκούων, καὶ ἡ μέριμνα τοῦ αἰῶνος καὶ ἡ ἀπάτη τοῦ πλούτου συμπνίγει τὸν λόγον, καὶ ἄκαρπος γίνεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Ὁ δὲ ἐπὶ τὴν καλὴν γῆν σπαρείς, οὗτός ἐστιν ὁ τὸν λόγον ἀκούων καὶ συνιείς, ὃς δὴ καρποφορεῖ καὶ ποιεῖ, ὃ μὲν ἑκατὸν, ὃ δὲ ἑξήκοντα, ὃ δὲ τριάκοντα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, '¶Ἄλλην παραβολὴν παρέθηκεν αὐτοῖς λέγων, “Ὡμοιώθη ἡ Βασιλεία τῶν Οὐρανῶν, ἀνθρώπῳ σπείραντι καλὸν σπέρμα ἐν τῷ ἀγρῷ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Ἐν δὲ τῷ καθεύδειν τοὺς ἀνθρώπους, ἦλθεν αὐτοῦ ὁ ἐχθρὸς καὶ ἐπέσπειρεν ζιζάνια ἀνὰ μέσον τοῦ σίτου καὶ ἀπῆλθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 26, 'Ὅτε δὲ ἐβλάστησεν ὁ χόρτος καὶ καρπὸν ἐποίησεν, τότε ἐφάνη καὶ τὰ ζιζάνια.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 27, 'Προσελθόντες δὲ οἱ δοῦλοι τοῦ οἰκοδεσπότου εἶπον αὐτῷ, ‘Κύριε, οὐχὶ καλὸν σπέρμα ἔσπειρας ἐν τῷ σῷ ἀγρῷ; Πόθεν οὖν ἔχει ζιζάνια;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 28, 'Ὁ δὲ ἔφη αὐτοῖς, ‘Ἐχθρὸς ἄνθρωπος τοῦτο ἐποίησεν.’ Οἱ δὲ δοῦλοι λέγουσιν αὐτῷ, ‘Θέλεις οὖν ἀπελθόντες, συλλέξωμεν αὐτά;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 29, 'Ὁ δέ φησιν, ‘Οὔ, μήποτε συλλέγοντες τὰ ζιζάνια, ἐκριζώσητε ἅμα αὐτοῖς τὸν σῖτον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 30, 'Ἄφετε συναυξάνεσθαι ἀμφότερα μέχρι τοῦ θερισμοῦ· καὶ ἐν καιρῷ τοῦ θερισμοῦ ἐρῶ τοῖς θερισταῖς, “Συλλέξατε πρῶτον τὰ ζιζάνια καὶ δήσατε αὐτὰ εἰς δέσμας πρὸς τὸ κατακαῦσαι αὐτά, τὸν δὲ σῖτον συναγάγετε εἰς τὴν ἀποθήκην μου.”’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 31, '¶Ἄλλην παραβολὴν παρέθηκεν αὐτοῖς λέγων, “Ὁμοία ἐστὶν ἡ Βασιλεία τῶν Οὐρανῶν κόκκῳ σινάπεως, ὃν λαβὼν ἄνθρωπος ἔσπειρεν ἐν τῷ ἀγρῷ αὐτοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 32, 'ὃ μικρότερον μέν ἐστιν πάντων τῶν σπερμάτων, ὅταν δὲ αὐξηθῇ μεῖζον τῶν λαχάνων ἐστὶν καὶ γίνεται δένδρον, ὥστε ἐλθεῖν ‘τὰ πετεινὰ τοῦ οὐρανοῦ καὶ κατασκηνοῦν ἐν τοῖς κλάδοις αὐτοῦ’.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 33, '¶Ἄλλην παραβολὴν ἐλάλησεν αὐτοῖς: “Ὁμοία ἐστὶν ἡ Βασιλεία τῶν Οὐρανῶν ζύμῃ, ἣν λαβοῦσα, γυνὴ ἐνέκρυψεν εἰς ἀλεύρου σάτα τρία, ἕως οὗ ἐζυμώθη ὅλον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 34, '¶Ταῦτα πάντα ἐλάλησεν ὁ  ̊Ἰησοῦς ἐν παραβολαῖς τοῖς ὄχλοις, καὶ χωρὶς παραβολῆς οὐδὲν ἐλάλει αὐτοῖς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 35, 'ὅπως πληρωθῇ τὸ ῥηθὲν διὰ τοῦ προφήτου λέγοντος, “Ἀνοίξω ἐν παραβολαῖς τὸ στόμα μου, ἐρεύξομαι κεκρυμμένα ἀπὸ καταβολῆς κόσμου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 36, '¶Τότε ἀφεὶς τοὺς ὄχλους, ἦλθεν εἰς τὴν οἰκίαν. Καὶ προσῆλθον αὐτῷ οἱ μαθηταὶ αὐτοῦ λέγοντες, “Διασάφησον ἡμῖν τὴν παραβολὴν τῶν ζιζανίων τοῦ ἀγροῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 37, 'Ὁ δὲ ἀποκριθεὶς εἶπεν, “Ὁ σπείρων τὸ καλὸν σπέρμα ἐστὶν ὁ Υἱὸς τοῦ Ἀνθρώπου·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 38, 'ὁ δὲ ἀγρός ἐστιν ὁ κόσμος· τὸ δὲ καλὸν σπέρμα, οὗτοί εἰσιν οἱ υἱοὶ τῆς βασιλείας· τὰ δὲ ζιζάνιά εἰσιν οἱ υἱοὶ τοῦ πονηροῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 39, 'ὁ δὲ ἐχθρὸς, ὁ σπείρας αὐτά, ἐστιν ὁ διάβολος· ὁ δὲ θερισμὸς συντέλεια αἰῶνός ἐστιν, οἱ δὲ θερισταὶ ἄγγελοί εἰσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 40, 'Ὥσπερ οὖν συλλέγεται τὰ ζιζάνια καὶ πυρὶ κατακαίεται, οὕτως ἔσται ἐν τῇ συντελείᾳ τοῦ αἰῶνος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 41, 'Ἀποστελεῖ ὁ Υἱὸς τοῦ Ἀνθρώπου τοὺς ἀγγέλους αὐτοῦ, καὶ συλλέξουσιν ἐκ τῆς βασιλείας αὐτοῦ πάντα τὰ σκάνδαλα καὶ τοὺς ποιοῦντας τὴν ἀνομίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 42, 'καὶ βαλοῦσιν αὐτοὺς εἰς τὴν κάμινον τοῦ πυρός· ἐκεῖ ἔσται ὁ κλαυθμὸς καὶ ὁ βρυγμὸς τῶν ὀδόντων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 43, 'Τότε ‘οἱ δίκαιοι ἐκλάμψουσιν ὡς ὁ ἥλιος’ ἐν τῇ βασιλείᾳ τοῦ Πατρὸς αὐτῶν. Ὁ ἔχων ὦτα, ἀκουέτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 44, '¶Ὁμοία ἐστὶν ἡ Βασιλεία τῶν Οὐρανῶν θησαυρῷ κεκρυμμένῳ ἐν τῷ ἀγρῷ, ὃν εὑρὼν ἄνθρωπος ἔκρυψεν, καὶ ἀπὸ τῆς χαρᾶς αὐτοῦ ὑπάγει καὶ πωλεῖ πάντα ὅσα ἔχει, καὶ ἀγοράζει τὸν ἀγρὸν ἐκεῖνον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 45, '¶Πάλιν ὁμοία ἐστὶν ἡ Βασιλεία τῶν Οὐρανῶν ἀνθρώπῳ ἐμπόρῳ ζητοῦντι καλοὺς μαργαρίτας·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 46, 'εὑρὼν δὲ ἕνα πολύτιμον μαργαρίτην ἀπελθὼν, πέπρακεν πάντα ὅσα εἶχεν, καὶ ἠγόρασεν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 47, '¶Πάλιν ὁμοία ἐστὶν ἡ Βασιλεία τῶν Οὐρανῶν σαγήνῃ βληθείσῃ εἰς τὴν θάλασσαν καὶ ἐκ παντὸς γένους συναγαγούσῃ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 48, 'ἣν ὅτε ἐπληρώθη, ἀναβιβάσαντες ἐπὶ τὸν αἰγιαλὸν καὶ καθίσαντες, συνέλεξαν τὰ καλὰ εἰς ἄγγη, τὰ δὲ σαπρὰ ἔξω ἔβαλον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 49, 'Οὕτως ἔσται ἐν τῇ συντελείᾳ τοῦ αἰῶνος· ἐξελεύσονται οἱ ἄγγελοι, καὶ ἀφοριοῦσιν τοὺς πονηροὺς ἐκ μέσου τῶν δικαίων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 50, 'καὶ βαλοῦσιν αὐτοὺς εἰς τὴν κάμινον τοῦ πυρός. Ἐκεῖ ἔσται ὁ κλαυθμὸς καὶ ὁ βρυγμὸς τῶν ὀδόντων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 51, '¶Συνήκατε ταῦτα πάντα;” Λέγουσιν αὐτῷ, “Ναί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 52, 'Ὁ δὲ εἶπεν αὐτοῖς, “Διὰ τοῦτο, πᾶς γραμματεὺς μαθητευθεὶς τῇ Βασιλείᾳ τῶν Οὐρανῶν ὅμοιός ἐστιν ἀνθρώπῳ, οἰκοδεσπότῃ, ὅστις ἐκβάλλει ἐκ τοῦ θησαυροῦ αὐτοῦ καινὰ καὶ παλαιά.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 53, '¶Καὶ ἐγένετο ὅτε ἐτέλεσεν ὁ  ̊Ἰησοῦς τὰς παραβολὰς ταύτας, μετῆρεν ἐκεῖθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 54, 'Καὶ ἐλθὼν εἰς τὴν πατρίδα αὐτοῦ, ἐδίδασκεν αὐτοὺς ἐν τῇ συναγωγῇ αὐτῶν, ὥστε ἐκπλήσσεσθαι αὐτοὺς καὶ λέγειν, “Πόθεν τούτῳ ἡ σοφία αὕτη καὶ αἱ δυνάμεις;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 55, 'Οὐχ οὗτός ἐστιν ὁ τοῦ τέκτονος υἱός; Οὐχ ἡ μήτηρ αὐτοῦ λέγεται Μαριὰμ, καὶ οἱ ἀδελφοὶ αὐτοῦ, Ἰάκωβος, καὶ Ἰωσὴφ, καὶ Σίμων, καὶ Ἰούδας;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 56, 'Καὶ αἱ ἀδελφαὶ αὐτοῦ οὐχὶ πᾶσαι πρὸς ἡμᾶς εἰσιν; Πόθεν οὖν τούτῳ ταῦτα πάντα;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 57, 'Καὶ ἐσκανδαλίζοντο ἐν αὐτῷ. Ὁ δὲ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Οὐκ ἔστιν προφήτης ἄτιμος, εἰ μὴ ἐν τῇ πατρίδι καὶ ἐν τῇ οἰκίᾳ αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 58, 'Καὶ οὐκ ἐποίησεν ἐκεῖ δυνάμεις πολλὰς, διὰ τὴν ἀπιστίαν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 1, '¶Ἐν ἐκείνῳ τῷ καιρῷ ἤκουσεν Ἡρῴδης ὁ τετράρχης τὴν ἀκοὴν  ̊Ἰησοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 2, 'καὶ εἶπεν τοῖς παισὶν αὐτοῦ, “Οὗτός ἐστιν Ἰωάννης ὁ Βαπτιστής· αὐτὸς ἠγέρθη ἀπὸ τῶν νεκρῶν, καὶ διὰ τοῦτο αἱ δυνάμεις ἐνεργοῦσιν ἐν αὐτῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 3, 'Ὁ γὰρ Ἡρῴδης κρατήσας τὸν Ἰωάννην, ἔδησεν αὐτὸν καὶ ἐν φυλακῇ ἀπέθετο, διὰ Ἡρῳδιάδα, τὴν γυναῖκα Φιλίππου, τοῦ ἀδελφοῦ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 4, 'Ἔλεγεν γὰρ αὐτῷ ὁ Ἰωάννης, “Οὐκ ἔξεστίν σοι ἔχειν αὐτήν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 5, 'Καὶ θέλων αὐτὸν ἀποκτεῖναι, ἐφοβήθη τὸν ὄχλον, ὅτι ὡς προφήτην αὐτὸν εἶχον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 6, 'Γενεσίοις δὲ γενομένοις τοῦ Ἡρῴδου, ὠρχήσατο ἡ θυγάτηρ τῆς Ἡρῳδιάδος ἐν τῷ μέσῳ καὶ ἤρεσεν τῷ Ἡρῴδῃ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 7, 'ὅθεν μεθʼ ὅρκου, ὡμολόγησεν αὐτῇ δοῦναι ὃ ἐὰν αἰτήσηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 8, 'Ἡ δὲ προβιβασθεῖσα ὑπὸ τῆς μητρὸς αὐτῆς, “Δός μοι”, φησίν, “ὧδε ἐπὶ πίνακι, τὴν κεφαλὴν Ἰωάννου τοῦ Βαπτιστοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 9, 'Καὶ ἐλυπήθη ὁ βασιλεὺς διὰ δὲ τοὺς ὅρκους καὶ τοὺς συνανακειμένους, ἐκέλευσεν δοθῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 10, 'Καὶ πέμψας, ἀπεκεφάλισεν Ἰωάννην ἐν τῇ φυλακῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 11, 'Καὶ ἠνέχθη ἡ κεφαλὴ αὐτοῦ ἐπὶ πίνακι, καὶ ἐδόθη τῷ κορασίῳ, καὶ ἤνεγκεν τῇ μητρὶ αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 12, 'Καὶ προσελθόντες, οἱ μαθηταὶ αὐτοῦ ἦραν τὸ πτῶμα καὶ ἔθαψαν αὐτόν, καὶ ἐλθόντες, ἀπήγγειλαν τῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 13, '¶Ἀκούσας δὲ, ὁ  ̊Ἰησοῦς ἀνεχώρησεν ἐκεῖθεν ἐν πλοίῳ εἰς ἔρημον τόπον κατʼ ἰδίαν. Καὶ ἀκούσαντες, οἱ ὄχλοι ἠκολούθησαν αὐτῷ πεζῇ ἀπὸ τῶν πόλεων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 14, 'Καὶ ἐξελθὼν, εἶδεν πολὺν ὄχλον, καὶ ἐσπλαγχνίσθη ἐπʼ αὐτοῖς καὶ ἐθεράπευσεν τοὺς ἀρρώστους αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 15, 'Ὀψίας δὲ γενομένης, προσῆλθον αὐτῷ οἱ μαθηταὶ λέγοντες, “Ἔρημός ἐστιν ὁ τόπος καὶ ἡ ὥρα ἤδη παρῆλθεν· ἀπόλυσον τοὺς ὄχλους, ἵνα ἀπελθόντες εἰς τὰς κώμας, ἀγοράσωσιν ἑαυτοῖς βρώματα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 16, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Οὐ χρείαν ἔχουσιν ἀπελθεῖν. Δότε αὐτοῖς ὑμεῖς φαγεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 17, 'Οἱ δὲ λέγουσιν αὐτῷ, “Οὐκ ἔχομεν ὧδε, εἰ μὴ πέντε ἄρτους καὶ δύο ἰχθύας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 18, 'Ὁ δὲ εἶπεν, “Φέρετέ μοι ὧδε αὐτούς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 19, 'Καὶ κελεύσας τοὺς ὄχλους ἀνακλιθῆναι ἐπὶ τοῦ χόρτου, καὶ λαβὼν τοὺς πέντε ἄρτους καὶ τοὺς δύο ἰχθύας, ἀναβλέψας εἰς τὸν οὐρανὸν, εὐλόγησεν καὶ κλάσας, ἔδωκεν τοῖς μαθηταῖς τοὺς ἄρτους, οἱ δὲ μαθηταὶ τοῖς ὄχλοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 20, 'Καὶ ἔφαγον πάντες καὶ ἐχορτάσθησαν, καὶ ἦραν τὸ περισσεῦον τῶν κλασμάτων, δώδεκα κοφίνους πλήρεις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 21, 'Οἱ δὲ ἐσθίοντες ἦσαν ἄνδρες ὡσεὶ πεντακισχίλιοι, χωρὶς γυναικῶν καὶ παιδίων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 22, '¶Καὶ εὐθέως ἠνάγκασεν τοὺς μαθητὰς ἐμβῆναι εἰς τὸ πλοῖον, καὶ προάγειν αὐτὸν εἰς τὸ πέραν, ἕως οὗ ἀπολύσῃ τοὺς ὄχλους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 23, 'Καὶ ἀπολύσας τοὺς ὄχλους, ἀνέβη εἰς τὸ ὄρος κατʼ ἰδίαν προσεύξασθαι. Ὀψίας δὲ γενομένης, μόνος ἦν ἐκεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 24, 'Τὸ δὲ πλοῖον ἤδη μέσον τῆς θαλάσσης ἦν, βασανιζόμενον ὑπὸ τῶν κυμάτων, ἦν γὰρ ἐναντίος ὁ ἄνεμος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 25, 'Τετάρτῃ δὲ φυλακῇ τῆς νυκτὸς, ἦλθεν πρὸς αὐτοὺς περιπατῶν ἐπὶ τὴν θάλασσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 26, 'Οἱ δὲ μαθηταὶ ἰδόντες, αὐτὸν ἐπὶ τῆς θαλάσσης περιπατοῦντα, ἐταράχθησαν λέγοντες, ὅτι “Φάντασμά ἐστιν”, καὶ ἀπὸ τοῦ φόβου ἔκραξαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 27, 'Εὐθὺς δὲ ἐλάλησεν ὁ  ̊Ἰησοῦς αὐτοῖς λέγων, “Θαρσεῖτε, ἐγώ εἰμι, μὴ φοβεῖσθε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 28, '¶Ἀποκριθεὶς δὲ αὐτῷ, ὁ Πέτρος εἶπεν, “ ̊Κύριε, εἰ σὺ εἶ, κέλευσόν με ἐλθεῖν πρὸς σὲ ἐπὶ τὰ ὕδατα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 29, 'Ὁ δὲ εἶπεν, “Ἐλθέ.” Καὶ καταβὰς ἀπὸ τοῦ πλοίου, Πέτρος περιεπάτησεν ἐπὶ τὰ ὕδατα καὶ ἦλθεν πρὸς τὸν  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 30, 'Βλέπων δὲ τὸν ἄνεμον ἰσχυρὸν, ἐφοβήθη καὶ ἀρξάμενος καταποντίζεσθαι, ἔκραξεν λέγων, “ ̊Κύριε, σῶσόν με.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 31, 'Εὐθέως δὲ ὁ  ̊Ἰησοῦς ἐκτείνας τὴν χεῖρα, ἐπελάβετο αὐτοῦ καὶ λέγει αὐτῷ, “Ὀλιγόπιστε, εἰς τί ἐδίστασας;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 32, 'Καὶ ἀναβάντων αὐτῶν εἰς τὸ πλοῖον, ἐκόπασεν ὁ ἄνεμος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 33, 'Οἱ δὲ ἐν τῷ πλοίῳ προσεκύνησαν αὐτῷ λέγοντες, “Ἀληθῶς  ̊Θεοῦ Υἱὸς εἶ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 34, '¶Καὶ διαπεράσαντες, ἦλθον ἐπὶ τὴν γῆν εἰς Γεννησαρέτ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 35, 'Καὶ ἐπιγνόντες αὐτὸν, οἱ ἄνδρες τοῦ τόπου ἐκείνου ἀπέστειλαν εἰς ὅλην τὴν περίχωρον ἐκείνην, καὶ προσήνεγκαν αὐτῷ πάντας τοὺς κακῶς ἔχοντας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 36, 'καὶ παρεκάλουν αὐτὸν ἵνα μόνον ἅψωνται τοῦ κρασπέδου τοῦ ἱματίου αὐτοῦ· καὶ ὅσοι ἥψαντο διεσώθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 1, '¶Τότε προσέρχονται τῷ  ̊Ἰησοῦ ἀπὸ Ἱεροσολύμων, Φαρισαῖοι καὶ γραμματεῖς λέγοντες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 2, '“Διὰ τί οἱ μαθηταί σου παραβαίνουσιν τὴν παράδοσιν τῶν πρεσβυτέρων; Οὐ γὰρ νίπτονται τὰς χεῖρας ὅταν ἄρτον ἐσθίωσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 3, 'Ὁ δὲ ἀποκριθεὶς εἶπεν αὐτοῖς, “Διὰ τί καὶ ὑμεῖς παραβαίνετε τὴν ἐντολὴν τοῦ  ̊Θεοῦ διὰ τὴν παράδοσιν ὑμῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 4, 'Ὁ γὰρ  ̊Θεὸς ἐνετείλατο λέγων, ‘Τίμα τὸν πατέρα καὶ τὴν μητέρα’, καί, ‘Ὁ κακολογῶν πατέρα ἢ μητέρα, θανάτῳ τελευτάτω.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 5, 'Ὑμεῖς δὲ λέγετε, ‘Ὃς ἂν εἴπῃ τῷ πατρὶ ἢ τῇ μητρί, “Δῶρον ὃ ἐὰν ἐξ ἐμοῦ ὠφεληθῇς”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 6, 'οὐ μὴ τιμήσει τὸν πατέρα αὐτοῦ.’ Καὶ ἠκυρώσατε τὸν λόγον τοῦ  ̊Θεοῦ διὰ τὴν παράδοσιν ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 7, 'Ὑποκριταί! Καλῶς ἐπροφήτευσεν περὶ ὑμῶν Ἠσαΐας λέγων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 8, '‘Ὁ λαὸς οὗτος τοῖς χείλεσίν με τιμᾷ, ἡ δὲ καρδία αὐτῶν πόρρω ἀπέχει ἀπʼ ἐμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 9, 'Μάτην δὲ σέβονταί με, διδάσκοντες διδασκαλίας ἐντάλματα ἀνθρώπων.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 10, '¶Καὶ προσκαλεσάμενος τὸν ὄχλον, εἶπεν αὐτοῖς, “Ἀκούετε καὶ συνίετε!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 11, 'Οὐ τὸ εἰσερχόμενον εἰς τὸ στόμα κοινοῖ τὸν ἄνθρωπον, ἀλλὰ τὸ ἐκπορευόμενον ἐκ τοῦ στόματος, τοῦτο κοινοῖ τὸν ἄνθρωπον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 12, 'Τότε προσελθόντες οἱ μαθηταὶ λέγουσιν αὐτῷ, “Οἶδας ὅτι οἱ Φαρισαῖοι ἀκούσαντες τὸν λόγον ἐσκανδαλίσθησαν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 13, 'Ὁ δὲ ἀποκριθεὶς εἶπεν, “Πᾶσα φυτεία ἣν οὐκ ἐφύτευσεν ὁ Πατήρ μου ὁ οὐράνιος ἐκριζωθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 14, 'Ἄφετε αὐτούς· ὁδηγοί εἰσιν τυφλοί τυφλὸς, δὲ τυφλὸν ἐὰν ὁδηγῇ, ἀμφότεροι εἰς βόθυνον πεσοῦνται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 15, 'Ἀποκριθεὶς δὲ ὁ Πέτρος εἶπεν αὐτῷ, “Φράσον ἡμῖν τὴν παραβολήν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 16, 'Ὁ δὲ εἶπεν, “Ἀκμὴν καὶ ὑμεῖς ἀσύνετοί ἐστε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 17, 'Οὔπω νοεῖτε ὅτι πᾶν τὸ εἰσπορευόμενον εἰς τὸ στόμα, εἰς τὴν κοιλίαν χωρεῖ, καὶ εἰς ἀφεδρῶνα ἐκβάλλεται;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 18, 'Τὰ δὲ ἐκπορευόμενα ἐκ τοῦ στόματος, ἐκ τῆς καρδίας ἐξέρχεται, κἀκεῖνα κοινοῖ τὸν ἄνθρωπον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 19, 'Ἐκ γὰρ τῆς καρδίας ἐξέρχονται διαλογισμοὶ πονηροί, φόνοι, μοιχεῖαι, πορνεῖαι, κλοπαί, ψευδομαρτυρίαι, βλασφημίαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 20, 'Ταῦτά ἐστιν τὰ κοινοῦντα τὸν ἄνθρωπον, τὸ δὲ ἀνίπτοις χερσὶν φαγεῖν, οὐ κοινοῖ τὸν ἄνθρωπον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 21, '¶Καὶ ἐξελθὼν ἐκεῖθεν, ὁ  ̊Ἰησοῦς ἀνεχώρησεν εἰς τὰ μέρη Τύρου καὶ Σιδῶνος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 22, 'Καὶ ἰδοὺ, γυνὴ Χαναναία ἀπὸ τῶν ὁρίων ἐκείνων ἐξελθοῦσα, ἔκραζεν λέγουσα, “Ἐλέησόν με,  ̊Κύριε, Υἱὸς Δαυίδ· ἡ θυγάτηρ μου κακῶς δαιμονίζεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 23, 'Ὁ δὲ οὐκ ἀπεκρίθη αὐτῇ λόγον. Καὶ προσελθόντες, οἱ μαθηταὶ αὐτοῦ ἠρώτουν αὐτὸν λέγοντες, “Ἀπόλυσον αὐτήν, ὅτι κράζει ὄπισθεν ἡμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 24, 'Ὁ δὲ ἀποκριθεὶς εἶπεν, “Οὐκ ἀπεστάλην εἰ μὴ εἰς τὰ πρόβατα τὰ ἀπολωλότα οἴκου Ἰσραήλ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 25, 'Ἡ δὲ ἐλθοῦσα προσεκύνει αὐτῷ λέγουσα, “ ̊Κύριε, βοήθει μοι!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 26, 'Ὁ δὲ ἀποκριθεὶς εἶπεν, “Οὐκ ἔστιν καλὸν λαβεῖν τὸν ἄρτον τῶν τέκνων καὶ βαλεῖν τοῖς κυναρίοις.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 27, 'Ἡ δὲ εἶπεν, “Ναί,  ̊Κύριε, καὶ γὰρ τὰ κυνάρια ἐσθίει ἀπὸ τῶν ψιχίων τῶν πιπτόντων ἀπὸ τῆς τραπέζης τῶν κυρίων αὐτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 28, 'Τότε ἀποκριθεὶς ὁ  ̊Ἰησοῦς εἶπεν αὐτῇ, “Ὦ γύναι, μεγάλη σου ἡ πίστις· γενηθήτω σοι ὡς θέλεις.” Καὶ ἰάθη ἡ θυγάτηρ αὐτῆς ἀπὸ τῆς ὥρας ἐκείνης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 29, '¶Καὶ μεταβὰς ἐκεῖθεν, ὁ  ̊Ἰησοῦς ἦλθεν παρὰ τὴν θάλασσαν τῆς Γαλιλαίας, καὶ ἀναβὰς εἰς τὸ ὄρος, ἐκάθητο ἐκεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 30, 'Καὶ προσῆλθον αὐτῷ ὄχλοι πολλοὶ, ἔχοντες μεθʼ ἑαυτῶν χωλούς, κυλλούς, τυφλούς, κωφούς, καὶ ἑτέρους πολλούς, καὶ ἔρριψαν αὐτοὺς παρὰ τοὺς πόδας αὐτοῦ, καὶ ἐθεράπευσεν αὐτούς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 31, 'ὥστε τοὺς ὄχλους θαυμάσαι, βλέποντας κωφοὺς λαλοῦντας, κυλλοὺς ὑγιεῖς, καὶ χωλοὺς περιπατοῦντας, καὶ τυφλοὺς βλέποντας· καὶ ἐδόξασαν τὸν  ̊Θεὸν Ἰσραήλ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 32, '¶Ὁ δὲ  ̊Ἰησοῦς προσκαλεσάμενος τοὺς μαθητὰς αὐτοῦ εἶπεν, “Σπλαγχνίζομαι ἐπὶ τὸν ὄχλον, ὅτι ἤδη ἡμέραι τρεῖς προσμένουσίν μοι, καὶ οὐκ ἔχουσιν τί φάγωσιν· καὶ ἀπολῦσαι αὐτοὺς νήστεις οὐ θέλω, μήποτε ἐκλυθῶσιν ἐν τῇ ὁδῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 33, 'Καὶ λέγουσιν αὐτῷ οἱ μαθηταί, “Πόθεν ἡμῖν ἐν ἐρημίᾳ, ἄρτοι τοσοῦτοι ὥστε χορτάσαι ὄχλον τοσοῦτον;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 34, 'Καὶ λέγει αὐτοῖς ὁ  ̊Ἰησοῦς, “Πόσους ἄρτους ἔχετε;” Οἱ δὲ εἶπον, “Ἑπτά, καὶ ὀλίγα ἰχθύδια.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 35, 'Καὶ παραγγείλας τῷ ὄχλῳ ἀναπεσεῖν ἐπὶ τὴν γῆν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 36, 'ἔλαβεν τοὺς ἑπτὰ ἄρτους καὶ τοὺς ἰχθύας, καὶ εὐχαριστήσας ἔκλασεν καὶ ἐδίδου τοῖς μαθηταῖς, οἱ δὲ μαθηταὶ τοῖς ὄχλοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 37, 'Καὶ ἔφαγον πάντες καὶ ἐχορτάσθησαν, καὶ ἦραν τὸ περισσεῦον τῶν κλασμάτων, ἑπτὰ σπυρίδας πλήρεις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 38, 'Οἱ δὲ ἐσθίοντες ἦσαν τετρακισχίλιοι ἄνδρες, χωρὶς γυναικῶν καὶ παιδίων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 39, 'Καὶ ἀπολύσας τοὺς ὄχλους, ἐνέβη εἰς τὸ πλοῖον καὶ ἦλθεν εἰς τὰ ὅρια Μαγαδάν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 1, '¶Καὶ προσελθόντες οἱ Φαρισαῖοι καὶ Σαδδουκαῖοι, πειράζοντες ἐπηρώτησαν αὐτὸν σημεῖον ἐκ τοῦ οὐρανοῦ ἐπιδεῖξαι αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 2, 'Ὁ δὲ ἀποκριθεὶς εἶπεν αὐτοῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 3, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 4, '“Γενεὰ πονηρὰ καὶ μοιχαλὶς σημεῖον ἐπιζητεῖ, καὶ σημεῖον οὐ δοθήσεται αὐτῇ, εἰ μὴ τὸ σημεῖον Ἰωνᾶ.” Καὶ καταλιπὼν αὐτοὺς ἀπῆλθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 5, '¶Καὶ ἐλθόντες οἱ μαθηταὶ εἰς τὸ πέραν, ἐπελάθοντο ἄρτους λαβεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 6, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Ὁρᾶτε καὶ προσέχετε ἀπὸ τῆς ζύμης τῶν Φαρισαίων καὶ Σαδδουκαίων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 7, 'Οἱ δὲ διελογίζοντο ἐν ἑαυτοῖς λέγοντες, ὅτι “Ἄρτους οὐκ ἐλάβομεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 8, 'Γνοὺς δὲ, ὁ  ̊Ἰησοῦς εἶπεν, “Τί διαλογίζεσθε ἐν ἑαυτοῖς, ὀλιγόπιστοι, ὅτι ἄρτους οὐκ ἔχετε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 9, 'Οὔπω νοεῖτε, οὐδὲ μνημονεύετε τοὺς πέντε ἄρτους τῶν πεντακισχιλίων, καὶ πόσους κοφίνους ἐλάβετε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 10, 'Οὐδὲ τοὺς ἑπτὰ ἄρτους τῶν τετρακισχιλίων, καὶ πόσας σπυρίδας ἐλάβετε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 11, 'Πῶς οὐ νοεῖτε ὅτι οὐ περὶ ἄρτων εἶπον ὑμῖν; Προσέχετε δὲ ἀπὸ τῆς ζύμης τῶν Φαρισαίων καὶ Σαδδουκαίων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 12, 'Τότε συνῆκαν ὅτι οὐκ εἶπεν προσέχειν ἀπὸ τῆς ζύμης τῶν ἄρτων, ἀλλὰ ἀπὸ τῆς διδαχῆς τῶν Φαρισαίων καὶ Σαδδουκαίων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 13, '¶Ἐλθὼν δὲ ὁ  ̊Ἰησοῦς εἰς τὰ μέρη Καισαρείας τῆς Φιλίππου, ἠρώτα τοὺς μαθητὰς αὐτοῦ λέγων, “Τίνα λέγουσιν οἱ ἄνθρωποι εἶναι τὸν Υἱὸν τοῦ Ἀνθρώπου;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 14, 'Οἱ δὲ εἶπον, “Οἱ μὲν Ἰωάννην τὸν Βαπτιστήν, ἄλλοι δὲ Ἠλίαν, ἕτεροι δὲ Ἰερεμίαν ἢ ἕνα τῶν προφητῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 15, 'Λέγει αὐτοῖς, “Ὑμεῖς δὲ, τίνα με λέγετε εἶναι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 16, 'Ἀποκριθεὶς δὲ Σίμων Πέτρος εἶπεν, “Σὺ εἶ ὁ  ̊Χριστὸς, ὁ Υἱὸς τοῦ  ̊Θεοῦ τοῦ ζῶντος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 17, 'Ἀποκριθεὶς δὲ ὁ  ̊Ἰησοῦς εἶπεν αὐτῷ, “Μακάριος εἶ, Σίμων Βαριωνᾶ, ὅτι σὰρξ καὶ αἷμα οὐκ ἀπεκάλυψέν σοι, ἀλλʼ ὁ Πατήρ μου, ὁ ἐν τοῖς οὐρανοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 18, 'Κἀγὼ δέ σοι λέγω ὅτι σὺ εἶ Πέτρος, καὶ ἐπὶ ταύτῃ τῇ πέτρᾳ οἰκοδομήσω μου τὴν ἐκκλησίαν, καὶ πύλαι ἍΙδου οὐ κατισχύσουσιν αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 19, 'Δώσω σοι τὰς κλεῖδας τῆς Βασιλείας τῶν Οὐρανῶν, καὶ ὃ ἐὰν δήσῃς ἐπὶ τῆς γῆς, ἔσται δεδεμένον ἐν τοῖς οὐρανοῖς, καὶ ὃ ἐὰν λύσῃς ἐπὶ τῆς γῆς, ἔσται λελυμένον ἐν τοῖς οὐρανοῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 20, 'Τότε διεστείλατο τοῖς μαθηταῖς ἵνα μηδενὶ εἴπωσιν ὅτι αὐτός ἐστιν ὁ  ̊Χριστός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 21, '¶Ἀπὸ τότε ἤρξατο ὁ  ̊Ἰησοῦς  ̊Χριστὸς δεικνύειν τοῖς μαθηταῖς αὐτοῦ ὅτι δεῖ αὐτὸν εἰς Ἱεροσόλυμα ἀπελθεῖν, καὶ πολλὰ παθεῖν ἀπὸ τῶν πρεσβυτέρων, καὶ ἀρχιερέων, καὶ γραμματέων, καὶ ἀποκτανθῆναι καὶ τῇ τρίτῃ ἡμέρᾳ ἐγερθῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 22, 'Καὶ προσλαβόμενος αὐτὸν, ὁ Πέτρος ἤρξατο ἐπιτιμᾶν αὐτῷ λέγων, “Ἵλεώς σοι,  ̊Κύριε· οὐ μὴ ἔσται σοι τοῦτο.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 23, 'Ὁ δὲ στραφεὶς εἶπεν τῷ Πέτρῳ, “Ὕπαγε ὀπίσω μου, Σατανᾶ! Σκάνδαλον εἶ ἐμοῦ, ὅτι οὐ φρονεῖς τὰ τοῦ  ̊Θεοῦ, ἀλλὰ τὰ τῶν ἀνθρώπων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 24, '¶Τότε ὁ  ̊Ἰησοῦς εἶπεν τοῖς μαθηταῖς αὐτοῦ, “Εἴ τις θέλει ὀπίσω μου ἐλθεῖν, ἀπαρνησάσθω ἑαυτὸν, καὶ ἀράτω τὸν σταυρὸν αὐτοῦ, καὶ ἀκολουθείτω μοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 25, 'Ὃς γὰρ ἐὰν θέλῃ τὴν ψυχὴν αὐτοῦ σῶσαι, ἀπολέσει αὐτήν· ὃς δʼ ἂν ἀπολέσῃ τὴν ψυχὴν αὐτοῦ ἕνεκεν ἐμοῦ, εὑρήσει αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 26, 'Τί γὰρ ὠφεληθήσεται ἄνθρωπος, ἐὰν τὸν κόσμον ὅλον κερδήσῃ, τὴν δὲ ψυχὴν αὐτοῦ ζημιωθῇ; Ἢ τί δώσει ἄνθρωπος ἀντάλλαγμα τῆς ψυχῆς αὐτοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 27, 'Μέλλει γὰρ ὁ Υἱὸς τοῦ Ἀνθρώπου ἔρχεσθαι ἐν τῇ δόξῃ τοῦ Πατρὸς αὐτοῦ μετὰ τῶν ἀγγέλων αὐτοῦ, καὶ ‘τότε ἀποδώσει ἑκάστῳ κατὰ τὴν πρᾶξιν αὐτοῦ’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 28, 'Ἀμὴν, λέγω ὑμῖν ὅτι εἰσίν τινες τῶν ὧδε ἑστώτων οἵτινες οὐ μὴ γεύσωνται θανάτου, ἕως ἂν ἴδωσιν τὸν Υἱὸν τοῦ Ἀνθρώπου ἐρχόμενον ἐν τῇ βασιλείᾳ αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 1, '¶Καὶ μεθʼ ἡμέρας ἓξ, παραλαμβάνει ὁ  ̊Ἰησοῦς τὸν Πέτρον, καὶ Ἰάκωβον, καὶ Ἰωάννην, τὸν ἀδελφὸν αὐτοῦ, καὶ ἀναφέρει αὐτοὺς εἰς ὄρος ὑψηλὸν κατʼ ἰδίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 2, 'Καὶ μετεμορφώθη ἔμπροσθεν αὐτῶν, καὶ ἔλαμψεν τὸ πρόσωπον αὐτοῦ ὡς ὁ ἥλιος, τὰ δὲ ἱμάτια αὐτοῦ ἐγένετο λευκὰ ὡς τὸ φῶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 3, 'Καὶ ἰδοὺ, ὤφθη αὐτοῖς Μωϋσῆς καὶ Ἠλίας συλλαλοῦντες μετʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 4, 'Ἀποκριθεὶς δὲ, ὁ Πέτρος εἶπεν τῷ  ̊Ἰησοῦ, “ ̊Κύριε, καλόν ἐστιν ἡμᾶς ὧδε εἶναι. Εἰ θέλεις, ποιήσω ὧδε τρεῖς σκηνάς, σοὶ μίαν, καὶ Μωϋσεῖ μίαν, καὶ Ἠλίᾳ μίαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 5, 'Ἔτι αὐτοῦ λαλοῦντος, ἰδοὺ, νεφέλη φωτεινὴ ἐπεσκίασεν αὐτούς, καὶ ἰδοὺ, φωνὴ ἐκ τῆς νεφέλης λέγουσα, “Οὗτός ἐστιν ὁ Υἱός μου, ὁ ἀγαπητός ἐν ᾧ εὐδόκησα· ἀκούετε αὐτοῦ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 6, 'Καὶ ἀκούσαντες, οἱ μαθηταὶ ἔπεσαν ἐπὶ πρόσωπον αὐτῶν καὶ ἐφοβήθησαν σφόδρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 7, 'Καὶ προσῆλθεν ὁ  ̊Ἰησοῦς καὶ ἁψάμενος αὐτῶν εἶπεν, “Ἐγέρθητε καὶ μὴ φοβεῖσθε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 8, 'Ἐπάραντες δὲ τοὺς ὀφθαλμοὺς αὐτῶν, οὐδένα εἶδον εἰ μὴ αὐτὸν  ̊Ἰησοῦν μόνον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 9, '¶Καὶ καταβαινόντων αὐτῶν ἐκ τοῦ ὄρους, ἐνετείλατο αὐτοῖς ὁ  ̊Ἰησοῦς λέγων, “Μηδενὶ εἴπητε τὸ ὅραμα, ἕως οὗ ὁ Υἱὸς τοῦ Ἀνθρώπου ἐκ νεκρῶν ἀναστῇ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 10, 'Καὶ ἐπηρώτησαν αὐτὸν οἱ μαθηταὶ αὐτοῦ λέγοντες, “Τί οὖν οἱ γραμματεῖς λέγουσιν ὅτι Ἠλίαν δεῖ ἐλθεῖν πρῶτον;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 11, 'Ὁ δὲ ἀποκριθεὶς εἶπεν, “Ἠλίας μὲν ἔρχεται καὶ ἀποκαταστήσει πάντα·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 12, 'λέγω δὲ ὑμῖν ὅτι Ἠλίας ἤδη ἦλθεν καὶ οὐκ ἐπέγνωσαν αὐτὸν, ἀλλὰ ἐποίησαν ἐν αὐτῷ ὅσα ἠθέλησαν. Οὕτως καὶ ὁ Υἱὸς τοῦ Ἀνθρώπου μέλλει πάσχειν ὑπʼ αὐτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 13, 'Τότε συνῆκαν οἱ μαθηταὶ ὅτι περὶ Ἰωάννου τοῦ Βαπτιστοῦ εἶπεν αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 14, '¶Καὶ ἐλθόντων πρὸς τὸν ὄχλον, προσῆλθεν αὐτῷ ἄνθρωπος γονυπετῶν αὐτὸν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 15, 'καὶ λέγων, “ ̊Κύριε, ἐλέησόν μου τὸν υἱόν, ὅτι σεληνιάζεται καὶ κακῶς ἔχει, πολλάκις γὰρ πίπτει εἰς τὸ πῦρ, καὶ πολλάκις εἰς τὸ ὕδωρ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 16, 'Καὶ προσήνεγκα αὐτὸν τοῖς μαθηταῖς σου, καὶ οὐκ ἠδυνήθησαν αὐτὸν θεραπεῦσαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 17, 'Ἀποκριθεὶς δὲ ὁ  ̊Ἰησοῦς εἶπεν, “Ὦ γενεὰ ἄπιστος καὶ διεστραμμένη, ἕως πότε μεθʼ ὑμῶν ἔσομαι; Ἕως πότε ἀνέξομαι ὑμῶν; Φέρετέ μοι αὐτὸν ὧδε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 18, 'Καὶ ἐπετίμησεν αὐτῷ ὁ  ̊Ἰησοῦς, καὶ ἐξῆλθεν ἀπʼ αὐτοῦ τὸ δαιμόνιον, καὶ ἐθεραπεύθη ὁ παῖς ἀπὸ τῆς ὥρας ἐκείνης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 19, 'Τότε προσελθόντες οἱ μαθηταὶ τῷ  ̊Ἰησοῦ κατʼ ἰδίαν εἶπον, “Διὰ τί ἡμεῖς οὐκ ἠδυνήθημεν ἐκβαλεῖν αὐτό;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 20, 'Ὁ δὲ λέγει αὐτοῖς, “Διὰ τὴν ὀλιγοπιστίαν ὑμῶν. Ἀμὴν, γὰρ λέγω ὑμῖν, ἐὰν ἔχητε πίστιν ὡς κόκκον σινάπεως, ἐρεῖτε τῷ ὄρει τούτῳ, ‘Μετάβα ἔνθεν ἐκεῖ’, καὶ μεταβήσεται, καὶ οὐδὲν ἀδυνατήσει ὑμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 21, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 22, '¶Συστρεφομένων δὲ αὐτῶν ἐν τῇ Γαλιλαίᾳ, εἶπεν αὐτοῖς ὁ  ̊Ἰησοῦς, “Μέλλει ὁ Υἱὸς τοῦ Ἀνθρώπου παραδίδοσθαι εἰς χεῖρας ἀνθρώπων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 23, 'καὶ ἀποκτενοῦσιν αὐτόν, καὶ τῇ τρίτῃ ἡμέρᾳ ἐγερθήσεται.” Καὶ ἐλυπήθησαν σφόδρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 24, '¶Ἐλθόντων δὲ αὐτῶν εἰς Καφαρναοὺμ, προσῆλθον οἱ τὰ δίδραχμα λαμβάνοντες τῷ Πέτρῳ καὶ εἶπον, “Ὁ διδάσκαλος ὑμῶν οὐ τελεῖ τὰ δίδραχμα;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 25, 'Λέγει, “Ναί.” Καὶ ἐλθόντα εἰς τὴν οἰκίαν, προέφθασεν αὐτὸν ὁ  ̊Ἰησοῦς λέγων, “Τί σοι δοκεῖ, Σίμων; Οἱ βασιλεῖς τῆς γῆς, ἀπὸ τίνων λαμβάνουσιν τέλη ἢ κῆνσον; Ἀπὸ τῶν υἱῶν αὐτῶν ἢ ἀπὸ τῶν ἀλλοτρίων;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 26, 'λέγει αὐτῷ ὁ Πέτρος “Ἀπὸ τῶν ἀλλοτρίων.” Εἰπόντος δέ, “Ἀπὸ τῶν ἀλλοτρίων”, ἔφη αὐτῷ ὁ  ̊Ἰησοῦς, “Ἄρα γε ἐλεύθεροί εἰσιν οἱ υἱοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 27, 'Ἵνα δὲ μὴ σκανδαλίσωμεν αὐτούς, πορευθεὶς εἰς θάλασσαν, βάλε ἄγκιστρον καὶ τὸν ἀναβάντα πρῶτον ἰχθὺν ἆρον, καὶ ἀνοίξας τὸ στόμα αὐτοῦ, εὑρήσεις στατῆρα· ἐκεῖνον λαβὼν, δὸς αὐτοῖς ἀντὶ ἐμοῦ καὶ σοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 1, '¶Ἐν ἐκείνῃ τῇ ὥρᾳ προσῆλθον οἱ μαθηταὶ τῷ  ̊Ἰησοῦ λέγοντες, “Τίς ἄρα μείζων ἐστὶν ἐν τῇ Βασιλείᾳ τῶν Οὐρανῶν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 2, 'Καὶ προσκαλεσάμενος παιδίον, ἔστησεν αὐτὸ ἐν μέσῳ αὐτῶν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 3, 'καὶ εἶπεν, “Ἀμὴν, λέγω ὑμῖν, ἐὰν μὴ στραφῆτε καὶ γένησθε ὡς τὰ παιδία, οὐ μὴ εἰσέλθητε εἰς τὴν Βασιλείαν τῶν Οὐρανῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 4, 'Ὅστις οὖν ταπεινώσει ἑαυτὸν ὡς τὸ παιδίον τοῦτο, οὗτός ἐστιν ὁ μείζων ἐν τῇ Βασιλείᾳ τῶν Οὐρανῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 5, 'Καὶ ὃς ἐὰν δέξηται ἓν παιδίον τοιοῦτο ἐπὶ τῷ ὀνόματί μου, ἐμὲ δέχεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 6, '¶Ὃς δʼ ἂν σκανδαλίσῃ ἕνα τῶν μικρῶν τούτων τῶν πιστευόντων εἰς ἐμέ, συμφέρει αὐτῷ ἵνα κρεμασθῇ μύλος ὀνικὸς περὶ τὸν τράχηλον αὐτοῦ, καὶ καταποντισθῇ ἐν τῷ πελάγει τῆς θαλάσσης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 7, 'Οὐαὶ τῷ κόσμῳ ἀπὸ τῶν σκανδάλων! Ἀνάγκη γὰρ ἐστιν ἐλθεῖν τὰ σκάνδαλα, πλὴν οὐαὶ τῷ ἀνθρώπῳ ἐκείνῳ διʼ οὗ τὸ σκάνδαλον ἔρχεται!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 8, '¶Εἰ δὲ ἡ χείρ σου ἢ ὁ πούς σου σκανδαλίζει σε, ἔκκοψον αὐτὸν καὶ βάλε ἀπὸ σοῦ· καλόν σοί ἐστιν εἰσελθεῖν εἰς τὴν ζωὴν κυλλὸν ἢ χωλόν, ἢ δύο χεῖρας ἢ δύο πόδας ἔχοντα, βληθῆναι εἰς τὸ πῦρ τὸ αἰώνιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 9, 'Καὶ εἰ ὁ ὀφθαλμός σου σκανδαλίζει σε, ἔξελε αὐτὸν καὶ βάλε ἀπὸ σοῦ· καλόν σοί ἐστιν μονόφθαλμον εἰς τὴν ζωὴν εἰσελθεῖν, ἢ δύο ὀφθαλμοὺς ἔχοντα βληθῆναι εἰς τὴν Γέενναν τοῦ πυρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 10, '¶Ὁρᾶτε μὴ καταφρονήσητε ἑνὸς τῶν μικρῶν τούτων, λέγω γὰρ ὑμῖν ὅτι οἱ ἄγγελοι αὐτῶν ἐν οὐρανοῖς, διὰ παντὸς βλέπουσι τὸ πρόσωπον τοῦ Πατρός μου, τοῦ ἐν οὐρανοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 11, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 12, 'Τί ὑμῖν δοκεῖ; Ἐὰν γένηταί τινι ἀνθρώπῳ ἑκατὸν πρόβατα, καὶ πλανηθῇ ἓν ἐξ αὐτῶν, οὐχὶ ἀφεὶς τὰ ἐνενήκοντα ἐννέα ἐπὶ τὰ ὄρη, καὶ πορευθεὶς ζητεῖ τὸ πλανώμενον;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 13, 'Καὶ ἐὰν γένηται εὑρεῖν αὐτό, ἀμὴν, λέγω ὑμῖν ὅτι χαίρει ἐπʼ αὐτῷ μᾶλλον ἢ ἐπὶ τοῖς ἐνενήκοντα ἐννέα τοῖς μὴ πεπλανημένοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 14, 'Οὕτως οὐκ ἔστιν θέλημα ἔμπροσθεν τοῦ Πατρὸς ὑμῶν, τοῦ ἐν οὐρανοῖς, ἵνα ἀπόληται ἓν τῶν μικρῶν τούτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 15, '¶Ἐὰν δὲ ἁμαρτήσῃ ὁ ἀδελφός σου, ὕπαγε ἔλεγξον αὐτὸν μεταξὺ σοῦ καὶ αὐτοῦ μόνου. Ἐάν σου ἀκούσῃ, ἐκέρδησας τὸν ἀδελφόν σου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 16, 'Ἐὰν δὲ μὴ ἀκούσῃ, παράλαβε μετὰ σοῦ ἔτι, ἕνα ἢ δύο, ἵνα ‘ἐπὶ στόματος δύο μαρτύρων ἢ τριῶν, σταθῇ πᾶν ῥῆμα’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 17, 'Ἐὰν δὲ παρακούσῃ αὐτῶν, εἰπὲ τῇ ἐκκλησίᾳ. Ἐὰν δὲ καὶ τῆς ἐκκλησίας παρακούσῃ, ἔστω σοι ὥσπερ ὁ ἐθνικὸς καὶ ὁ τελώνης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 18, 'Ἀμὴν, λέγω ὑμῖν, ὅσα ἂν δήσητε ἐπὶ τῆς γῆς, ἔσται δεδεμένα ἐν οὐρανῷ, καὶ ὅσα ἐὰν λύσητε ἐπὶ τῆς γῆς, ἔσται λελυμένα ἐν οὐρανῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 19, 'Πάλιν ἀμὴν, λέγω ὑμῖν ὅτι ἐὰν δύο συμφωνήσωσιν ἐξ ὑμῶν ἐπὶ τῆς γῆς περὶ παντὸς πράγματος, οὗ ἐὰν αἰτήσωνται, γενήσεται αὐτοῖς παρὰ τοῦ Πατρός μου, τοῦ ἐν οὐρανοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 20, 'Οὗ γάρ εἰσιν δύο ἢ τρεῖς συνηγμένοι εἰς τὸ ἐμὸν ὄνομα, ἐκεῖ εἰμι ἐν μέσῳ αὐτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 21, '¶Τότε προσελθὼν, ὁ Πέτρος εἶπεν αὐτῷ, “ ̊Κύριε, ποσάκις ἁμαρτήσει εἰς ἐμὲ ὁ ἀδελφός μου, καὶ ἀφήσω αὐτῷ; Ἕως ἑπτάκις;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 22, 'Λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Οὐ λέγω σοι ἕως ἑπτάκις, ἀλλὰ ἕως ἑβδομηκοντάκις ἑπτά!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 23, '¶Διὰ τοῦτο ὡμοιώθη ἡ Βασιλεία τῶν Οὐρανῶν ἀνθρώπῳ βασιλεῖ, ὃς ἠθέλησεν συνᾶραι λόγον μετὰ τῶν δούλων αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 24, 'Ἀρξαμένου δὲ αὐτοῦ συναίρειν, προσήχθη εἷς αὐτῷ ὀφειλέτης μυρίων ταλάντων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 25, 'Μὴ ἔχοντος δὲ αὐτοῦ ἀποδοῦναι, ἐκέλευσεν αὐτὸν ὁ κύριος πραθῆναι, καὶ τὴν γυναῖκα, καὶ τὰ τέκνα, καὶ πάντα ὅσα εἶχεν, καὶ ἀποδοθῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 26, 'Πεσὼν οὖν ὁ δοῦλος προσεκύνει αὐτῷ λέγων, ‘Κύριε, μακροθύμησον ἐπʼ ἐμοί, καὶ πάντα ἀποδώσω σοι.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 27, 'Σπλαγχνισθεὶς δὲ, ὁ κύριος τοῦ δούλου ἐκείνου ἀπέλυσεν αὐτόν, καὶ τὸ δάνειον ἀφῆκεν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 28, 'Ἐξελθὼν δὲ, ὁ δοῦλος ἐκεῖνος εὗρεν ἕνα τῶν συνδούλων αὐτοῦ, ὃς ὤφειλεν αὐτῷ ἑκατὸν δηνάρια, καὶ κρατήσας αὐτὸν ἔπνιγεν λέγων, ‘Ἀπόδος εἴ τι ὀφείλεις.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 29, 'Πεσὼν οὖν, ὁ σύνδουλος αὐτοῦ παρεκάλει αὐτὸν λέγων, ‘Μακροθύμησον ἐπʼ ἐμοί, καὶ ἀποδώσω σοι.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 30, 'Ὁ δὲ οὐκ ἤθελεν, ἀλλὰ ἀπελθὼν, ἔβαλεν αὐτὸν εἰς φυλακὴν, ἕως ἀποδῷ τὸ ὀφειλόμενον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 31, 'Ἰδόντες οὖν οἱ σύνδουλοι αὐτοῦ τὰ γενόμενα, ἐλυπήθησαν σφόδρα, καὶ ἐλθόντες διεσάφησαν τῷ κυρίῳ ἑαυτῶν πάντα τὰ γενόμενα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 32, 'Τότε προσκαλεσάμενος αὐτὸν ὁ κύριος αὐτοῦ λέγει αὐτῷ, ‘Δοῦλε πονηρέ, πᾶσαν τὴν ὀφειλὴν ἐκείνην ἀφῆκά σοι, ἐπεὶ παρεκάλεσάς με.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 33, 'Οὐκ ἔδει καὶ σὲ ἐλεῆσαι τὸν σύνδουλόν σου, ὡς κἀγὼ σὲ ἠλέησα;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 34, 'Καὶ ὀργισθεὶς, ὁ κύριος αὐτοῦ παρέδωκεν αὐτὸν τοῖς βασανισταῖς, ἕως οὗ ἀποδῷ πᾶν τὸ ὀφειλόμενον αὑτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 35, 'Οὕτως καὶ ὁ Πατήρ μου ὁ οὐράνιος ποιήσει ὑμῖν, ἐὰν μὴ ἀφῆτε ἕκαστος τῷ ἀδελφῷ αὐτοῦ ἀπὸ τῶν καρδιῶν ὑμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 1, '¶Καὶ ἐγένετο, ὅτε ἐτέλεσεν ὁ  ̊Ἰησοῦς τοὺς λόγους τούτους, μετῆρεν ἀπὸ τῆς Γαλιλαίας καὶ ἦλθεν εἰς τὰ ὅρια τῆς Ἰουδαίας πέραν τοῦ Ἰορδάνου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 2, 'Καὶ ἠκολούθησαν αὐτῷ ὄχλοι πολλοί, καὶ ἐθεράπευσεν αὐτοὺς ἐκεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 3, '¶Καὶ προσῆλθον αὐτῷ Φαρισαῖοι, πειράζοντες αὐτὸν καὶ λέγοντες, “Εἰ ἔξεστιν ἀπολῦσαι τὴν γυναῖκα αὐτοῦ κατὰ πᾶσαν αἰτίαν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 4, 'Ὁ δὲ ἀποκριθεὶς εἶπεν, “Οὐκ ἀνέγνωτε ὅτι ὁ ποιήσας ἀπʼ ἀρχῆς, ‘ἄρσεν καὶ θῆλυ, ἐποίησεν αὐτοὺς’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 5, 'Καὶ εἶπεν, ‘Ἕνεκα τούτου καταλείψει ἄνθρωπος τὸν πατέρα καὶ τὴν μητέρα, καὶ κολληθήσεται τῇ γυναικὶ αὐτοῦ, καὶ ἔσονται οἱ δύο εἰς σάρκα μίαν’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 6, 'Ὥστε οὐκέτι εἰσὶν δύο, ἀλλὰ σὰρξ μία. Ὃ οὖν ὁ  ̊Θεὸς συνέζευξεν, ἄνθρωπος μὴ χωριζέτω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 7, 'Λέγουσιν αὐτῷ, “Τί οὖν Μωϋσῆς ἐνετείλατο ‘δοῦναι βιβλίον ἀποστασίου καὶ ἀπολῦσαι αὐτήν’;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 8, 'Λέγει αὐτοῖς, ὅτι “Μωϋσῆς πρὸς τὴν σκληροκαρδίαν ὑμῶν, ἐπέτρεψεν ὑμῖν ἀπολῦσαι τὰς γυναῖκας ὑμῶν, ἀπʼ ἀρχῆς δὲ οὐ γέγονεν οὕτως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 9, 'Λέγω δὲ ὑμῖν ὅτι ὃς ἂν ἀπολύσῃ τὴν γυναῖκα αὐτοῦ μὴ ἐπὶ πορνείᾳ, καὶ γαμήσῃ ἄλλην, μοιχᾶται. Καὶ ὁ ἀπολελυμένην γαμῶν μοιχᾶται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 10, '¶Λέγουσιν αὐτῷ οἱ μαθηταί, “Εἰ οὕτως ἐστὶν ἡ αἰτία τοῦ ἀνθρώπου μετὰ τῆς γυναικός, οὐ συμφέρει γαμῆσαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 11, 'Ὁ δὲ εἶπεν αὐτοῖς, “Οὐ πάντες χωροῦσιν τὸν λόγον τοῦτον, ἀλλʼ οἷς δέδοται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 12, 'Εἰσὶν γὰρ εὐνοῦχοι, οἵτινες ἐκ κοιλίας μητρὸς ἐγεννήθησαν οὕτως, καὶ εἰσὶν εὐνοῦχοι οἵτινες εὐνουχίσθησαν ὑπὸ τῶν ἀνθρώπων, καὶ εἰσὶν εὐνοῦχοι οἵτινες εὐνούχισαν ἑαυτοὺς διὰ τὴν Βασιλείαν τῶν Οὐρανῶν. Ὁ δυνάμενος χωρεῖν, χωρείτω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 13, '¶Τότε προσηνέχθησαν αὐτῷ παιδία, ἵνα τὰς χεῖρας ἐπιθῇ αὐτοῖς καὶ προσεύξηται· οἱ δὲ μαθηταὶ ἐπετίμησαν αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 14, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν, “Ἄφετε τὰ παιδία καὶ μὴ κωλύετε αὐτὰ ἐλθεῖν πρός με, τῶν γὰρ τοιούτων ἐστὶν ἡ Βασιλεία τῶν Οὐρανῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 15, 'Καὶ ἐπιθεὶς τὰς χεῖρας αὐτοῖς, ἐπορεύθη ἐκεῖθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 16, '¶Καὶ ἰδοὺ, εἷς προσελθὼν αὐτῷ εἶπεν, “Διδάσκαλε, τί ἀγαθὸν ποιήσω, ἵνα σχῶ ζωὴν αἰώνιον;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 17, 'Ὁ δὲ εἶπεν αὐτῷ, “Τί με ἐρωτᾷς περὶ τοῦ ἀγαθοῦ; Εἷς ἐστιν ὁ ἀγαθός. Εἰ δὲ θέλεις εἰς τὴν ζωὴν εἰσελθεῖν, τήρει τὰς ἐντολάς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 18, 'Λέγει αὐτῷ, “Ποίας;” Ὁ δὲ  ̊Ἰησοῦς εἶπεν, τὸ “Οὐ φονεύσεις, οὐ μοιχεύσεις, οὐ κλέψεις, οὐ ψευδομαρτυρήσεις”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 19, '“Τίμα τὸν πατέρα καὶ τὴν μητέρα”, καὶ, “Ἀγαπήσεις τὸν πλησίον σου ὡς σεαυτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 20, 'Λέγει αὐτῷ ὁ νεανίσκος, “Πάντα Ταῦτα ἐφύλαξα· τί ἔτι ὑστερῶ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 21, 'Ἔφη αὐτῷ ὁ  ̊Ἰησοῦς, “Εἰ θέλεις τέλειος εἶναι, ὕπαγε πώλησόν σου τὰ ὑπάρχοντα, καὶ δὸς πτωχοῖς, καὶ ἕξεις θησαυρὸν ἐν οὐρανοῖς, καὶ δεῦρο, ἀκολούθει μοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 22, 'Ἀκούσας δὲ, ὁ νεανίσκος τὸν λόγον, ἀπῆλθεν λυπούμενος, ἦν γὰρ ἔχων κτήματα πολλά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 23, '¶Ὁ δὲ  ̊Ἰησοῦς εἶπεν τοῖς μαθηταῖς αὐτοῦ, “Ἀμὴν, λέγω ὑμῖν ὅτι πλούσιος δυσκόλως εἰσελεύσεται εἰς τὴν Βασιλείαν τῶν Οὐρανῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 24, 'Πάλιν δὲ λέγω ὑμῖν, εὐκοπώτερόν ἐστιν κάμηλον διὰ τρήματος ῥαφίδος διελθεῖν ἢ πλούσιον εἰσελθεῖν εἰς τὴν Βασιλείαν τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 25, 'Ἀκούσαντες δὲ, οἱ μαθηταὶ ἐξεπλήσσοντο σφόδρα λέγοντες, “Τίς ἄρα δύναται σωθῆναι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 26, 'Ἐμβλέψας δὲ ὁ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Παρὰ ἀνθρώποις τοῦτο ἀδύνατόν ἐστιν, παρὰ δὲ  ̊Θεῷ πάντα δυνατά.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 27, '¶Τότε ἀποκριθεὶς ὁ Πέτρος εἶπεν αὐτῷ, “Ἰδοὺ, ἡμεῖς ἀφήκαμεν πάντα καὶ ἠκολουθήσαμέν σοι· τί ἄρα ἔσται ἡμῖν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 28, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Ἀμὴν, λέγω ὑμῖν ὅτι ὑμεῖς οἱ ἀκολουθήσαντές μοι ἐν τῇ παλιγγενεσίᾳ, ὅταν καθίσῃ ὁ Υἱὸς τοῦ Ἀνθρώπου ἐπὶ θρόνου δόξης αὐτοῦ, καθήσεσθε καὶ ὑμεῖς ἐπὶ δώδεκα θρόνους, κρίνοντες τὰς δώδεκα φυλὰς τοῦ Ἰσραήλ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 29, 'Καὶ πᾶς ὅστις ἀφῆκεν οἰκίας, ἢ ἀδελφοὺς, ἢ ἀδελφὰς, ἢ πατέρα, ἢ μητέρα, ἢ γυναῖκα, ἢ τέκνα, ἢ ἀγροὺς, ἕνεκεν τοῦ ἐμοῦ ὀνόματος, ἑκατονταπλασίονα λήμψεται καὶ ζωὴν αἰώνιον κληρονομήσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 30, 'Πολλοὶ δὲ ἔσονται πρῶτοι ἔσχατοι, καὶ ἔσχατοι πρῶτοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 1, '¶Ὁμοία γάρ ἐστιν ἡ Βασιλεία τῶν Οὐρανῶν ἀνθρώπῳ, οἰκοδεσπότῃ, ὅστις ἐξῆλθεν ἅμα πρωῒ μισθώσασθαι ἐργάτας εἰς τὸν ἀμπελῶνα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 2, 'Συμφωνήσας δὲ μετὰ τῶν ἐργατῶν ἐκ δηναρίου τὴν ἡμέραν, ἀπέστειλεν αὐτοὺς εἰς τὸν ἀμπελῶνα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 3, 'Καὶ ἐξελθὼν περὶ τρίτην ὥραν, εἶδεν ἄλλους ἑστῶτας ἐν τῇ ἀγορᾷ ἀργούς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 4, 'καὶ ἐκείνοις εἶπεν, ‘Ὑπάγετε καὶ ὑμεῖς εἰς τὸν ἀμπελῶνα, καὶ ὃ ἐὰν ᾖ δίκαιον, δώσω ὑμῖν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 5, 'Οἱ δὲ ἀπῆλθον. Πάλιν ἐξελθὼν περὶ ἕκτην καὶ ἐνάτην ὥραν, ἐποίησεν ὡσαύτως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 6, 'Περὶ δὲ τὴν ἑνδεκάτην ἐξελθὼν, εὗρεν ἄλλους ἑστῶτας, καὶ λέγει αὐτοῖς, ‘Τί ὧδε ἑστήκατε ὅλην τὴν ἡμέραν ἀργοί;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 7, 'Λέγουσιν αὐτῷ, ‘Ὅτι οὐδεὶς ἡμᾶς ἐμισθώσατο.’ Λέγει αὐτοῖς, ‘Ὑπάγετε καὶ ὑμεῖς εἰς τὸν ἀμπελῶνα.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 8, 'Ὀψίας δὲ γενομένης λέγει ὁ κύριος τοῦ ἀμπελῶνος τῷ ἐπιτρόπῳ αὐτοῦ, ‘Κάλεσον τοὺς ἐργάτας καὶ ἀπόδος αὐτοῖς τὸν μισθὸν, ἀρξάμενος ἀπὸ τῶν ἐσχάτων ἕως τῶν πρώτων.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 9, 'Καὶ ἐλθόντες οἱ περὶ τὴν ἑνδεκάτην ὥραν, ἔλαβον ἀνὰ δηνάριον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 10, 'Καὶ ἐλθόντες οἱ πρῶτοι ἐνόμισαν ὅτι πλεῖον λήμψονται, καὶ ἔλαβον ἀνὰ δηνάριον καὶ αὐτοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 11, 'Λαβόντες δὲ, ἐγόγγυζον κατὰ τοῦ οἰκοδεσπότου');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 12, 'λέγοντες, ‘Οὗτοι οἱ ἔσχατοι μίαν ὥραν ἐποίησαν, καὶ ἴσους ἡμῖν αὐτοὺς ἐποίησας, τοῖς βαστάσασιν τὸ βάρος τῆς ἡμέρας καὶ τὸν καύσωνα.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 13, 'Ὁ δὲ ἀποκριθεὶς ἑνὶ αὐτῶν εἶπεν, ‘Ἑταῖρε, οὐκ ἀδικῶ σε. Οὐχὶ δηναρίου συνεφώνησάς μοι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 14, 'Ἆρον τὸ σὸν καὶ ὕπαγε. Θέλω δὲ τούτῳ τῷ ἐσχάτῳ δοῦναι ὡς καὶ σοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 15, 'Ἢ οὐκ ἔξεστίν μοι, ὃ θέλω ποιῆσαι ἐν τοῖς ἐμοῖς; Ἢ ὁ ὀφθαλμός σου πονηρός ἐστιν, ὅτι ἐγὼ ἀγαθός εἰμι;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 16, 'Οὕτως ἔσονται οἱ ἔσχατοι πρῶτοι, καὶ οἱ πρῶτοι ἔσχατοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 17, '¶Καὶ ἀναβαίνων ὁ  ̊Ἰησοῦς εἰς Ἱεροσόλυμα, παρέλαβεν τοὺς δώδεκα μαθητὰς κατʼ ἰδίαν, καὶ ἐν τῇ ὁδῷ εἶπεν αὐτοῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 18, '“Ἰδοὺ, ἀναβαίνομεν εἰς Ἱεροσόλυμα, καὶ ὁ Υἱὸς τοῦ Ἀνθρώπου παραδοθήσεται τοῖς ἀρχιερεῦσιν καὶ γραμματεῦσιν, καὶ κατακρινοῦσιν αὐτὸν θανάτῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 19, 'καὶ παραδώσουσιν αὐτὸν τοῖς ἔθνεσιν, εἰς τὸ ἐμπαῖξαι, καὶ μαστιγῶσαι, καὶ σταυρῶσαι, καὶ τῇ τρίτῃ ἡμέρᾳ ἀναστήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 20, '¶Τότε προσῆλθεν αὐτῷ ἡ μήτηρ τῶν υἱῶν Ζεβεδαίου μετὰ τῶν υἱῶν αὐτῆς, προσκυνοῦσα καὶ αἰτοῦσά τι παρʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 21, 'Ὁ δὲ εἶπεν αὐτῇ, “Τί θέλεις;” Λέγει αὐτῷ, “Εἰπὲ ἵνα καθίσωσιν οὗτοι οἱ δύο υἱοί μου, εἷς ἐκ δεξιῶν καὶ εἷς ἐξ εὐωνύμων σου ἐν τῇ βασιλείᾳ σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 22, 'Ἀποκριθεὶς δὲ ὁ  ̊Ἰησοῦς εἶπεν, “Οὐκ οἴδατε τί αἰτεῖσθε. Δύνασθε πιεῖν τὸ ποτήριον ὃ ἐγὼ μέλλω πίνειν;” Λέγουσιν αὐτῷ, “Δυνάμεθα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 23, 'Λέγει αὐτοῖς, “Τὸ μὲν ποτήριόν μου πίεσθε, τὸ δὲ καθίσαι ἐκ δεξιῶν μου καὶ ἐξ εὐωνύμων, οὐκ ἔστιν ἐμὸν δοῦναι, ἀλλʼ οἷς ἡτοίμασται ὑπὸ τοῦ Πατρός μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 24, '¶Καὶ ἀκούσαντες, οἱ δέκα ἠγανάκτησαν περὶ τῶν δύο ἀδελφῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 25, 'Ὁ δὲ  ̊Ἰησοῦς προσκαλεσάμενος αὐτοὺς εἶπεν, “Οἴδατε ὅτι οἱ ἄρχοντες τῶν ἐθνῶν κατακυριεύουσιν αὐτῶν, καὶ οἱ μεγάλοι κατεξουσιάζουσιν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 26, 'Οὐχ οὕτως ἔσται ἐν ὑμῖν· ἀλλʼ ὃς ἐὰν θέλῃ ἐν ὑμῖν μέγας γενέσθαι, ἔσται ὑμῶν διάκονος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 27, 'καὶ ὃς ἂν θέλῃ ἐν ὑμῖν εἶναι πρῶτος, ἔσται ὑμῶν δοῦλος·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 28, 'ὥσπερ ὁ Υἱὸς τοῦ Ἀνθρώπου οὐκ ἦλθεν διακονηθῆναι, ἀλλὰ διακονῆσαι καὶ δοῦναι τὴν ψυχὴν αὐτοῦ λύτρον ἀντὶ πολλῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 29, '¶Καὶ ἐκπορευομένων αὐτῶν ἀπὸ Ἰεριχὼ, ἠκολούθησεν αὐτῷ ὄχλος πολύς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 30, 'Καὶ ἰδοὺ, δύο τυφλοὶ καθήμενοι παρὰ τὴν ὁδόν, ἀκούσαντες ὅτι  ̊Ἰησοῦς παράγει, ἔκραξαν λέγοντες, ἐλέησον ἡμᾶς,  ̊Κύριε, Υἱὲ Δαυίδ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 31, 'Ὁ δὲ ὄχλος ἐπετίμησεν αὐτοῖς ἵνα σιωπήσωσιν. Οἱ δὲ μεῖζον ἔκραξαν λέγοντες, “ ̊Κύριε, ἐλέησον ἡμᾶς, Υἱὸς Δαυίδ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 32, 'Καὶ στὰς, ὁ  ̊Ἰησοῦς ἐφώνησεν αὐτοὺς καὶ εἶπεν, “Τί θέλετε ποιήσω ὑμῖν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 33, 'Λέγουσιν αὐτῷ, “ ̊Κύριε, ἵνα ἀνοιγῶσιν οἱ ὀφθαλμοὶ ἡμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 34, 'Σπλαγχνισθεὶς δὲ, ὁ  ̊Ἰησοῦς ἥψατο τῶν ὀφθαλμῶν αὐτῶν, καὶ εὐθέως ἀνέβλεψαν καὶ ἠκολούθησαν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 1, '¶Καὶ ὅτε ἤγγισαν εἰς Ἱεροσόλυμα καὶ ἦλθον εἰς Βηθφαγὴ πρὸς τὸ Ὄρος τῶν Ἐλαιῶν, τότε  ̊Ἰησοῦς ἀπέστειλεν δύο μαθητὰς');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 2, 'λέγων αὐτοῖς, “Πορεύεσθε εἰς τὴν κώμην, τὴν κατέναντι ὑμῶν, καὶ εὐθέως εὑρήσετε ὄνον δεδεμένην καὶ πῶλον μετʼ αὐτῆς· λύσαντες ἀγάγετέ μοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 3, 'Καὶ ἐάν τις ὑμῖν εἴπῃ τι, ἐρεῖτε, ὅτι ‘Ὁ  ̊Κύριος αὐτῶν χρείαν ἔχει’, εὐθὺς δὲ ἀποστελεῖ αὐτούς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 4, 'Τοῦτο δὲ ὅλον γέγονεν, ἵνα πληρωθῇ τὸ ῥηθὲν διὰ τοῦ προφήτου λέγοντος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 5, '“Εἴπατε τῇ θυγατρὶ Σιών, ‘Ἰδοὺ, ὁ βασιλεύς σου ἔρχεταί σοι, πραῢς καὶ ἐπιβεβηκὼς ἐπὶ ὄνον καὶ ἐπὶ πῶλον, υἱὸν ὑποζυγίου.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 6, 'Πορευθέντες δὲ οἱ μαθηταὶ, καὶ ποιήσαντες καθὼς συνέταξεν αὐτοῖς ὁ  ̊Ἰησοῦς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 7, 'ἤγαγον τὴν ὄνον καὶ τὸν πῶλον, καὶ ἐπέθηκαν ἐπʼ αὐτῶν τὰ ἱμάτια, καὶ ἐπεκάθισεν ἐπάνω αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 8, 'Ὁ δὲ πλεῖστος ὄχλος ἔστρωσαν ἑαυτῶν τὰ ἱμάτια ἐν τῇ ὁδῷ, ἄλλοι δὲ ἔκοπτον κλάδους ἀπὸ τῶν δένδρων, καὶ ἐστρώννυον ἐν τῇ ὁδῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 9, 'Οἱ δὲ ὄχλοι οἱ προάγοντες αὐτὸν καὶ οἱ ἀκολουθοῦντες ἔκραζον λέγοντες, “Ὡσαννὰ τῷ Υἱῷ Δαυίδ! ‘Εὐλογημένος ὁ ἐρχόμενος ἐν ὀνόματι  ̊Κυρίου!’ Ὡσαννὰ ἐν τοῖς ὑψίστοις!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 10, 'Καὶ εἰσελθόντος αὐτοῦ εἰς Ἱεροσόλυμα, ἐσείσθη πᾶσα ἡ πόλις λέγουσα, “Τίς ἐστιν οὗτος;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 11, 'Οἱ δὲ ὄχλοι ἔλεγον, “Οὗτός ἐστιν ὁ προφήτης  ̊Ἰησοῦς, ὁ ἀπὸ Ναζαρὲθ τῆς Γαλιλαίας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 12, '¶Καὶ εἰσῆλθεν  ̊Ἰησοῦς εἰς τὸ ἱερόν, καὶ ἐξέβαλεν πάντας τοὺς πωλοῦντας καὶ ἀγοράζοντας ἐν τῷ ἱερῷ, καὶ τὰς τραπέζας τῶν κολλυβιστῶν κατέστρεψεν, καὶ τὰς καθέδρας τῶν πωλούντων τὰς περιστεράς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 13, 'Καὶ λέγει αὐτοῖς, “Γέγραπται, ‘Ὁ οἶκός μου οἶκος προσευχῆς κληθήσεται’, ὑμεῖς δὲ αὐτὸν ποιεῖτε ‘σπήλαιον λῃστῶν’.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 14, '¶Καὶ προσῆλθον αὐτῷ, τυφλοὶ καὶ χωλοὶ ἐν τῷ ἱερῷ, καὶ ἐθεράπευσεν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 15, 'Ἰδόντες δὲ οἱ ἀρχιερεῖς καὶ οἱ γραμματεῖς, τὰ θαυμάσια ἃ ἐποίησεν, καὶ τοὺς παῖδας τοὺς κράζοντας ἐν τῷ ἱερῷ καὶ λέγοντας, “Ὡσαννὰ τῷ Υἱῷ Δαυίδ”, ἠγανάκτησαν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 16, 'καὶ εἶπαν αὐτῷ, “Ἀκούεις τί οὗτοι λέγουσιν;” Ὁ δὲ  ̊Ἰησοῦς λέγει αὐτοῖς, “Ναί, οὐδέποτε ἀνέγνωτε, ὅτι ‘Ἐκ στόματος νηπίων καὶ θηλαζόντων, κατηρτίσω αἶνον’;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 17, 'Καὶ καταλιπὼν αὐτοὺς, ἐξῆλθεν ἔξω τῆς πόλεως εἰς Βηθανίαν, καὶ ηὐλίσθη ἐκεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 18, '¶Πρωῒ δὲ ἐπανάγων εἰς τὴν πόλιν, ἐπείνασεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 19, 'Καὶ ἰδὼν συκῆν μίαν ἐπὶ τῆς ὁδοῦ, ἦλθεν ἐπʼ αὐτήν καὶ οὐδὲν εὗρεν ἐν αὐτῇ, εἰ μὴ φύλλα μόνον, καὶ λέγει αὐτῇ, “Μηκέτι ἐκ σοῦ καρπὸς γένηται εἰς τὸν αἰῶνα.” Καὶ ἐξηράνθη παραχρῆμα ἡ συκῆ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 20, 'Καὶ ἰδόντες οἱ μαθηταὶ ἐθαύμασαν λέγοντες, “Πῶς παραχρῆμα ἐξηράνθη ἡ συκῆ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 21, 'Ἀποκριθεὶς δὲ, ὁ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Ἀμὴν, λέγω ὑμῖν, ἐὰν ἔχητε πίστιν καὶ μὴ διακριθῆτε, οὐ μόνον τὸ τῆς συκῆς ποιήσετε, ἀλλὰ κἂν τῷ ὄρει τούτῳ εἴπητε, ‘Ἄρθητι καὶ βλήθητι εἰς τὴν θάλασσαν’, γενήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 22, 'Καὶ πάντα ὅσα ἂν αἰτήσητε ἐν τῇ προσευχῇ πιστεύοντες, λήμψεσθε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 23, '¶Καὶ ἐλθόντος αὐτοῦ εἰς τὸ ἱερὸν, προσῆλθον αὐτῷ διδάσκοντι οἱ ἀρχιερεῖς καὶ οἱ πρεσβύτεροι τοῦ λαοῦ λέγοντες, “Ἐν ποίᾳ ἐξουσίᾳ ταῦτα ποιεῖς; Καὶ τίς σοι ἔδωκεν τὴν ἐξουσίαν ταύτην;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 24, 'Ἀποκριθεὶς δὲ, ὁ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Ἐρωτήσω ὑμᾶς κἀγὼ λόγον ἕνα, ὃν ἐὰν εἴπητέ μοι, κἀγὼ ὑμῖν ἐρῶ ἐν ποίᾳ ἐξουσίᾳ ταῦτα ποιῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 25, 'Τὸ βάπτισμα τὸ Ἰωάννου, πόθεν ἦν; Ἐξ οὐρανοῦ ἢ ἐξ ἀνθρώπων;” Οἱ δὲ διελογίζοντο παρʼ ἑαυτοῖς λέγοντες, “Ἐὰν εἴπωμεν, ‘Ἐξ οὐρανοῦ’, ἐρεῖ ἡμῖν, ‘Διὰ τί οὖν οὐκ ἐπιστεύσατε αὐτῷ;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 26, 'Ἐὰν δὲ εἴπωμεν, ‘Ἐξ ἀνθρώπων’, φοβούμεθα τὸν ὄχλον, πάντες γὰρ ὡς προφήτην ἔχουσιν τὸν Ἰωάννην.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 27, 'Καὶ ἀποκριθέντες τῷ  ̊Ἰησοῦ, εἶπον, “Οὐκ οἴδαμεν.” Ἔφη αὐτοῖς καὶ αὐτός, “Οὐδὲ ἐγὼ λέγω ὑμῖν ἐν ποίᾳ ἐξουσίᾳ ταῦτα ποιῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 28, '¶Τί δὲ ὑμῖν δοκεῖ; Ἄνθρωπος εἶχεν τέκνα δύο. Καὶ προσελθὼν τῷ πρώτῳ εἶπεν, ‘Τέκνον, ὕπαγε σήμερον, ἐργάζου ἐν τῷ ἀμπελῶνι.’ μου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 29, 'Ὁ δὲ ἀποκριθεὶς εἶπεν, ‘Οὐ θέλω’· ὕστερον μεταμεληθεὶς, ἀπῆλθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 30, 'Προσελθὼν δὲ τῷ ἑτέρῳ εἶπεν ὡσαύτως. Ὁ δὲ ἀποκριθεὶς εἶπεν, ‘Ἐγώ, κύριε’· καὶ οὐκ ἀπῆλθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 31, 'Τίς ἐκ τῶν δύο ἐποίησεν τὸ θέλημα τοῦ πατρός;” Λέγουσιν, “Ὁ πρῶτος.” Λέγει αὐτοῖς ὁ  ̊Ἰησοῦς, “Ἀμὴν, λέγω ὑμῖν ὅτι οἱ τελῶναι καὶ αἱ πόρναι προάγουσιν ὑμᾶς εἰς τὴν Βασιλείαν τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 32, 'Ἦλθεν γὰρ Ἰωάννης πρὸς ὑμᾶς ἐν ὁδῷ δικαιοσύνης, καὶ οὐκ ἐπιστεύσατε αὐτῷ, οἱ δὲ τελῶναι καὶ αἱ πόρναι ἐπίστευσαν αὐτῷ· ὑμεῖς δὲ ἰδόντες, οὐ μετεμελήθητε ὕστερον τοῦ πιστεῦσαι αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 33, '¶Ἄλλην παραβολὴν ἀκούσατε: ἄνθρωπος ἦν οἰκοδεσπότης, ὅστις ἐφύτευσεν ἀμπελῶνα, καὶ φραγμὸν αὐτῷ περιέθηκεν, ‘καὶ ὤρυξεν ἐν αὐτῷ ληνὸν, καὶ ᾠκοδόμησεν πύργον’, καὶ ἐξέδετο αὐτὸν γεωργοῖς, καὶ ἀπεδήμησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 34, 'Ὅτε δὲ ἤγγισεν ὁ καιρὸς τῶν καρπῶν, ἀπέστειλεν τοὺς δούλους αὐτοῦ πρὸς τοὺς γεωργοὺς, λαβεῖν τοὺς καρποὺς αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 35, 'Καὶ λαβόντες οἱ γεωργοὶ τοὺς δούλους αὐτοῦ, ὃν μὲν ἔδειραν, ὃν δὲ ἀπέκτειναν, ὃν δὲ ἐλιθοβόλησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 36, 'Πάλιν ἀπέστειλεν ἄλλους δούλους, πλείονας τῶν πρώτων, καὶ ἐποίησαν αὐτοῖς ὡσαύτως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 37, 'Ὕστερον δὲ ἀπέστειλεν πρὸς αὐτοὺς τὸν υἱὸν αὐτοῦ λέγων, ‘Ἐντραπήσονται τὸν υἱόν μου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 38, 'Οἱ δὲ γεωργοὶ ἰδόντες τὸν υἱὸν, εἶπον ἐν ἑαυτοῖς, ‘Οὗτός ἐστιν ὁ κληρονόμος· δεῦτε, ἀποκτείνωμεν αὐτὸν καὶ σχῶμεν τὴν κληρονομίαν αὐτοῦ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 39, 'Καὶ λαβόντες αὐτὸν, ἐξέβαλον ἔξω τοῦ ἀμπελῶνος καὶ ἀπέκτειναν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 40, 'Ὅταν οὖν ἔλθῃ ὁ κύριος τοῦ ἀμπελῶνος, τί ποιήσει τοῖς γεωργοῖς ἐκείνοις;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 41, 'Λέγουσιν αὐτῷ, “Κακοὺς κακῶς ἀπολέσει αὐτούς, καὶ τὸν ἀμπελῶνα ἐκδώσεται ἄλλοις γεωργοῖς, οἵτινες ἀποδώσουσιν αὐτῷ τοὺς καρποὺς ἐν τοῖς καιροῖς αὐτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 42, '¶Λέγει αὐτοῖς ὁ  ̊Ἰησοῦς, “Οὐδέποτε ἀνέγνωτε ἐν ταῖς Γραφαῖς, ‘Λίθον ὃν ἀπεδοκίμασαν οἱ οἰκοδομοῦντες, οὗτος ἐγενήθη εἰς κεφαλὴν γωνίας· παρὰ  ̊Κυρίου ἐγένετο αὕτη, καὶ ἔστιν θαυμαστὴ ἐν ὀφθαλμοῖς ἡμῶν’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 43, 'Διὰ τοῦτο λέγω ὑμῖν ὅτι ἀρθήσεται ἀφʼ ὑμῶν ἡ Βασιλεία τοῦ  ̊Θεοῦ, καὶ δοθήσεται ἔθνει ποιοῦντι τοὺς καρποὺς αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 44, 'Καὶ ὁ πεσὼν ἐπὶ τὸν λίθον τοῦτον, συνθλασθήσεται· ἐφʼ ὃν δʼ ἂν πέσῃ, λικμήσει αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 45, '¶Καὶ ἀκούσαντες οἱ ἀρχιερεῖς καὶ οἱ Φαρισαῖοι τὰς παραβολὰς αὐτοῦ, ἔγνωσαν ὅτι περὶ αὐτῶν λέγει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 46, 'Καὶ ζητοῦντες αὐτὸν κρατῆσαι, ἐφοβήθησαν τοὺς ὄχλους, ἐπεὶ εἰς προφήτην αὐτὸν εἶχον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 1, '¶Καὶ ἀποκριθεὶς ὁ  ̊Ἰησοῦς πάλιν εἶπεν ἐν παραβολαῖς αὐτοῖς λέγων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 2, '“Ὡμοιώθη ἡ Βασιλεία τῶν Οὐρανῶν ἀνθρώπῳ, βασιλεῖ, ὅστις ἐποίησεν γάμους τῷ υἱῷ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 3, 'Καὶ ἀπέστειλεν τοὺς δούλους αὐτοῦ, καλέσαι τοὺς κεκλημένους εἰς τοὺς γάμους, καὶ οὐκ ἤθελον ἐλθεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 4, 'Πάλιν ἀπέστειλεν ἄλλους δούλους λέγων, ‘Εἴπατε τοῖς κεκλημένοις, “Ἰδοὺ, τὸ ἄριστόν μου ἡτοίμακα, οἱ ταῦροί μου καὶ τὰ σιτιστὰ τεθυμένα, καὶ πάντα ἕτοιμα· δεῦτε εἰς τοὺς γάμους.”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 5, 'Οἱ δὲ ἀμελήσαντες ἀπῆλθον, ὃς μὲν εἰς τὸν ἴδιον ἀγρόν, ὃς δὲ ἐπὶ τὴν ἐμπορίαν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 6, 'Οἱ δὲ λοιποὶ κρατήσαντες τοὺς δούλους αὐτοῦ, ὕβρισαν καὶ ἀπέκτειναν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 7, 'Ὁ δὲ βασιλεὺς ὠργίσθη, καὶ πέμψας τὰ στρατεύματα αὐτοῦ, ἀπώλεσεν τοὺς φονεῖς ἐκείνους, καὶ τὴν πόλιν αὐτῶν ἐνέπρησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 8, 'Τότε λέγει τοῖς δούλοις αὐτοῦ, ‘Ὁ μὲν γάμος ἕτοιμός ἐστιν, οἱ δὲ κεκλημένοι οὐκ ἦσαν ἄξιοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 9, 'Πορεύεσθε οὖν ἐπὶ τὰς διεξόδους τῶν ὁδῶν, καὶ ὅσους ἐὰν εὕρητε, καλέσατε εἰς τοὺς γάμους.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 10, 'Καὶ ἐξελθόντες, οἱ δοῦλοι ἐκεῖνοι εἰς τὰς ὁδοὺς, συνήγαγον πάντας οὓς εὗρον, πονηρούς τε καὶ ἀγαθούς· καὶ ἐπλήσθη ὁ γάμος ἀνακειμένων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 11, 'Εἰσελθὼν δὲ ὁ βασιλεὺς θεάσασθαι τοὺς ἀνακειμένους, εἶδεν ἐκεῖ ἄνθρωπον οὐκ ἐνδεδυμένον ἔνδυμα γάμου·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 12, 'καὶ λέγει αὐτῷ, ‘Ἑταῖρε, πῶς εἰσῆλθες ὧδε μὴ ἔχων ἔνδυμα γάμου;’ Ὁ δὲ ἐφιμώθη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 13, 'Τότε ὁ βασιλεὺς εἶπεν τοῖς διακόνοις, ‘Δήσαντες αὐτοῦ πόδας καὶ χεῖρας, ἐκβάλετε αὐτὸν εἰς τὸ σκότος τὸ ἐξώτερον· ἐκεῖ ἔσται ὁ κλαυθμὸς καὶ ὁ βρυγμὸς τῶν ὀδόντων.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 14, 'Πολλοὶ γάρ εἰσιν κλητοὶ, ὀλίγοι δὲ ἐκλεκτοί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 15, '¶Τότε πορευθέντες, οἱ Φαρισαῖοι συμβούλιον ἔλαβον ὅπως αὐτὸν παγιδεύσωσιν ἐν λόγῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 16, 'Καὶ ἀποστέλλουσιν αὐτῷ τοὺς μαθητὰς αὐτῶν μετὰ τῶν Ἡρῳδιανῶν λέγοντας, “Διδάσκαλε, οἴδαμεν ὅτι ἀληθὴς εἶ, καὶ τὴν ὁδὸν τοῦ  ̊Θεοῦ ἐν ἀληθείᾳ διδάσκεις, καὶ οὐ μέλει σοι περὶ οὐδενός, οὐ γὰρ βλέπεις εἰς πρόσωπον ἀνθρώπων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 17, 'Εἰπὲ οὖν ἡμῖν, τί σοι δοκεῖ; Ἔξεστιν δοῦναι κῆνσον Καίσαρι ἢ οὔ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 18, 'Γνοὺς δὲ ὁ  ̊Ἰησοῦς τὴν πονηρίαν αὐτῶν εἶπεν, “Τί με πειράζετε, ὑποκριταί;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 19, 'Ἐπιδείξατέ μοι τὸ νόμισμα τοῦ κήνσου.” Οἱ δὲ προσήνεγκαν αὐτῷ δηνάριον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 20, 'Καὶ λέγει αὐτοῖς, “Τίνος ἡ εἰκὼν αὕτη καὶ ἡ ἐπιγραφή;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 21, 'Λέγουσιν, “Καίσαρος.” Τότε λέγει αὐτοῖς, “Ἀπόδοτε οὖν τὰ Καίσαρος Καίσαρι, καὶ τὰ τοῦ  ̊Θεοῦ τῷ  ̊Θεῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 22, 'Καὶ ἀκούσαντες ἐθαύμασαν, καὶ ἀφέντες αὐτὸν ἀπῆλθαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 23, '¶Ἐν ἐκείνῃ τῇ ἡμέρᾳ προσῆλθον αὐτῷ Σαδδουκαῖοι λέγοντες, μὴ εἶναι ἀνάστασιν, καὶ ἐπηρώτησαν αὐτὸν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 24, 'λέγοντες, “Διδάσκαλε, Μωϋσῆς εἶπεν, ‘Ἐάν τις ἀποθάνῃ μὴ ἔχων τέκνα, ἐπιγαμβρεύσει ὁ ἀδελφὸς αὐτοῦ τὴν γυναῖκα αὐτοῦ, καὶ ἀναστήσει σπέρμα τῷ ἀδελφῷ αὐτοῦ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 25, 'Ἦσαν δὲ παρʼ ἡμῖν ἑπτὰ ἀδελφοί· καὶ ὁ πρῶτος γήμας ἐτελεύτησεν, καὶ μὴ ἔχων σπέρμα, ἀφῆκεν τὴν γυναῖκα αὐτοῦ τῷ ἀδελφῷ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 26, 'Ὁμοίως καὶ ὁ δεύτερος, καὶ ὁ τρίτος, ἕως τῶν ἑπτά,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 27, 'ὕστερον δὲ πάντων, ἀπέθανεν ἡ γυνή.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 28, 'Ἐν τῇ ἀναστάσει οὖν, τίνος τῶν ἑπτὰ ἔσται γυνή; Πάντες γὰρ ἔσχον αὐτήν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 29, '¶Ἀποκριθεὶς δὲ, ὁ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Πλανᾶσθε, μὴ εἰδότες τὰς Γραφὰς, μηδὲ τὴν δύναμιν τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 30, 'Ἐν γὰρ τῇ ἀναστάσει, οὔτε γαμοῦσιν οὔτε γαμίζονται, ἀλλʼ ὡς ἄγγελοι ἐν τῷ οὐρανῷ εἰσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 31, 'Περὶ δὲ τῆς ἀναστάσεως τῶν νεκρῶν, οὐκ ἀνέγνωτε τὸ ῥηθὲν ὑμῖν ὑπὸ τοῦ  ̊Θεοῦ λέγοντος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 32, '‘Ἐγώ εἰμι ὁ  ̊Θεὸς Ἀβραὰμ, καὶ ὁ  ̊Θεὸς Ἰσαὰκ, καὶ ὁ  ̊Θεὸς Ἰακώβ’; Οὐκ ἔστιν ὁ  ̊Θεὸς νεκρῶν, ἀλλὰ ζώντων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 33, 'Καὶ ἀκούσαντες, οἱ ὄχλοι ἐξεπλήσσοντο ἐπὶ τῇ διδαχῇ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 34, '¶Οἱ δὲ Φαρισαῖοι ἀκούσαντες ὅτι ἐφίμωσεν τοὺς Σαδδουκαίους, συνήχθησαν ἐπὶ τὸ αὐτό.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 35, 'Καὶ ἐπηρώτησεν εἷς ἐξ αὐτῶν, νομικὸς πειράζων αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 36, '“Διδάσκαλε, ποία ἐντολὴ μεγάλη ἐν τῷ νόμῳ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 37, 'Ὁ δὲ ἔφη αὐτῷ, “‘Ἀγαπήσεις  ̊Κύριον τὸν  ̊Θεόν σου ἐν ὅλῃ καρδίᾳ σου, καὶ ἐν ὅλῃ ψυχῇ σου, καὶ ἐν ὅλῃ τῇ διανοίᾳ σου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 38, 'Αὕτη ἐστὶν ἡ μεγάλη καὶ πρώτη ἐντολή.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 39, 'Δευτέρα ὁμοία αὐτῇ, ‘Ἀγαπήσεις τὸν πλησίον σου ὡς σεαυτόν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 40, 'Ἐν ταύταις ταῖς δυσὶν ἐντολαῖς, ὅλος ὁ νόμος κρέμαται καὶ οἱ προφῆται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 41, '¶Συνηγμένων δὲ τῶν Φαρισαίων, ἐπηρώτησεν αὐτοὺς ὁ  ̊Ἰησοῦς');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 42, 'λέγων, “Τί ὑμῖν δοκεῖ περὶ τοῦ  ̊Χριστοῦ; Τίνος υἱός ἐστιν;” Λέγουσιν αὐτῷ, “Τοῦ Δαυίδ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 43, 'Λέγει αὐτοῖς, “Πῶς οὖν Δαυὶδ ἐν  ̊Πνεύματι καλεῖ  ̊Κύριον αὐτὸν λέγων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 44, '‘Εἶπεν  ̊Κύριος τῷ  ̊Κυρίῳ μου, “Κάθου ἐκ δεξιῶν μου, ἕως ἂν θῶ τοὺς ἐχθρούς σου ὑποκάτω τῶν ποδῶν σου”’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 45, 'Εἰ οὖν Δαυὶδ καλεῖ αὐτὸν, ‘ ̊Κύριον’, πῶς υἱὸς αὐτοῦ ἐστιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 46, 'Καὶ οὐδεὶς ἐδύνατο ἀποκριθῆναι αὐτῷ λόγον, οὐδὲ ἐτόλμησέν τις ἀπʼ ἐκείνης τῆς ἡμέρας ἐπερωτῆσαι αὐτὸν οὐκέτι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 1, '¶Τότε ὁ  ̊Ἰησοῦς ἐλάλησεν τοῖς ὄχλοις καὶ τοῖς μαθηταῖς αὐτοῦ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 2, 'λέγων, “Ἐπὶ τῆς Μωϋσέως καθέδρας ἐκάθισαν οἱ γραμματεῖς καὶ οἱ Φαρισαῖοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 3, 'Πάντα οὖν ὅσα ἂν εἴπωσιν ὑμῖν, ποιήσατε καὶ τηρεῖτε, κατὰ δὲ τὰ ἔργα αὐτῶν, μὴ ποιεῖτε, λέγουσιν γὰρ καὶ οὐ ποιοῦσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 4, 'Δεσμεύουσιν δὲ φορτία βαρέα καὶ δυσβάστακτα, καὶ ἐπιτιθέασιν ἐπὶ τοὺς ὤμους τῶν ἀνθρώπων, αὐτοὶ δὲ τῷ δακτύλῳ αὐτῶν οὐ θέλουσιν κινῆσαι αὐτά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 5, 'Πάντα δὲ τὰ ἔργα αὐτῶν, ποιοῦσιν πρὸς τὸ θεαθῆναι τοῖς ἀνθρώποις. Πλατύνουσι γὰρ τὰ φυλακτήρια αὐτῶν καὶ μεγαλύνουσι τὰ κράσπεδα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 6, 'Φιλοῦσι δὲ τὴν πρωτοκλισίαν ἐν τοῖς δείπνοις, καὶ τὰς πρωτοκαθεδρίας ἐν ταῖς συναγωγαῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 7, 'καὶ τοὺς ἀσπασμοὺς ἐν ταῖς ἀγοραῖς, καὶ καλεῖσθαι ὑπὸ τῶν ἀνθρώπων, ‘Ῥαββί’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 8, 'Ὑμεῖς δὲ μὴ κληθῆτε ‘Ῥαββί’, εἷς γάρ ἐστιν ὑμῶν ὁ καθηγητὴς, πάντες δὲ ὑμεῖς ἀδελφοί ἐστε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 9, 'Καὶ ‘Πατέρα’ μὴ καλέσητε ὑμῶν ἐπὶ τῆς γῆς, εἷς γάρ ἐστιν ὑμῶν ὁ Πατὴρ ὁ οὐράνιος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 10, 'Μηδὲ κληθῆτε ‘Καθηγηταί’, ὅτι καθηγητὴς ὑμῶν ἐστιν εἷς, ὁ  ̊Χριστός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 11, 'Ὁ δὲ μείζων ὑμῶν ἔσται ὑμῶν διάκονος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 12, 'Ὅστις δὲ ὑψώσει ἑαυτὸν, ταπεινωθήσεται, καὶ ὅστις ταπεινώσει ἑαυτὸν, ὑψωθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 13, '¶Οὐαὶ δὲ ὑμῖν, γραμματεῖς καὶ Φαρισαῖοι, ὑποκριταί! Ὅτι κλείετε τὴν Βασιλείαν τῶν Οὐρανῶν ἔμπροσθεν τῶν ἀνθρώπων· ὑμεῖς γὰρ οὐκ εἰσέρχεσθε, οὐδὲ τοὺς εἰσερχομένους ἀφίετε εἰσελθεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 14, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 15, 'Οὐαὶ ὑμῖν, γραμματεῖς καὶ Φαρισαῖοι, ὑποκριταί! Ὅτι περιάγετε τὴν θάλασσαν καὶ τὴν ξηρὰν ποιῆσαι ἕνα προσήλυτον, καὶ ὅταν γένηται, ποιεῖτε αὐτὸν υἱὸν Γεέννης διπλότερον ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 16, '¶Οὐαὶ ὑμῖν, ὁδηγοὶ τυφλοὶ, οἱ λέγοντες, ‘Ὃς ἂν ὀμόσῃ ἐν τῷ ναῷ, οὐδέν ἐστιν, ὃς δʼ ἂν ὀμόσῃ ἐν τῷ χρυσῷ τοῦ ναοῦ ὀφείλει.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 17, 'Μωροὶ καὶ τυφλοί! Τίς γὰρ μείζων ἐστίν, ὁ χρυσὸς ἢ ὁ ναὸς ὁ ἁγιάσας τὸν χρυσόν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 18, 'Καί, ‘Ὃς ἂν ὀμόσῃ ἐν τῷ θυσιαστηρίῳ, οὐδέν ἐστιν, ὃς δʼ ἂν ὀμόσῃ ἐν τῷ δώρῳ τῷ ἐπάνω αὐτοῦ ὀφείλει.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 19, 'Μωροὶ καὶ τυφλοί! Τί γὰρ μεῖζον, τὸ δῶρον, ἢ τὸ θυσιαστήριον τὸ ἁγιάζον τὸ δῶρον;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 20, 'Ὁ οὖν ὀμόσας ἐν τῷ θυσιαστηρίῳ, ὀμνύει ἐν αὐτῷ καὶ ἐν πᾶσι τοῖς ἐπάνω αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 21, 'Καὶ ὁ ὀμόσας ἐν τῷ ναῷ, ὀμνύει ἐν αὐτῷ καὶ ἐν τῷ κατοικοῦντι αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 22, 'Καὶ ὁ ὀμόσας ἐν τῷ οὐρανῷ, ὀμνύει ἐν τῷ θρόνῳ τοῦ  ̊Θεοῦ καὶ ἐν τῷ καθημένῳ ἐπάνω αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 23, '¶Οὐαὶ ὑμῖν, γραμματεῖς καὶ Φαρισαῖοι, ὑποκριταί! Ὅτι ἀποδεκατοῦτε τὸ ἡδύοσμον, καὶ τὸ ἄνηθον, καὶ τὸ κύμινον, καὶ ἀφήκατε τὰ βαρύτερα τοῦ νόμου: τὴν κρίσιν, καὶ τὸ ἔλεος, καὶ τὴν πίστιν. Ταῦτα δὲ ἔδει ποιῆσαι, κἀκεῖνα μὴ ἀφεῖναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 24, 'Ὁδηγοὶ τυφλοί! Οἱ διϋλίζοντες τὸν κώνωπα τὴν δὲ κάμηλον καταπίνοντες!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 25, '¶Οὐαὶ ὑμῖν, γραμματεῖς καὶ Φαρισαῖοι, ὑποκριταί! Ὅτι καθαρίζετε τὸ ἔξωθεν τοῦ ποτηρίου καὶ τῆς παροψίδος, ἔσωθεν δὲ γέμουσιν ἐξ ἁρπαγῆς καὶ ἀκρασίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 26, 'Φαρισαῖε τυφλέ! Καθάρισον πρῶτον τὸ ἐντὸς τοῦ ποτηρίου καὶ τῆς παροψίδος, ἵνα γένηται καὶ τὸ ἐκτὸς αὐτῶν καθαρόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 27, '¶Οὐαὶ ὑμῖν, γραμματεῖς καὶ Φαρισαῖοι, ὑποκριταί! Ὅτι παρομοιάζετε τάφοις κεκονιαμένοις, οἵτινες ἔξωθεν μὲν φαίνονται ὡραῖοι, ἔσωθεν δὲ γέμουσιν ὀστέων νεκρῶν καὶ πάσης ἀκαθαρσίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 28, 'Οὕτως καὶ ὑμεῖς ἔξωθεν μὲν φαίνεσθε τοῖς ἀνθρώποις δίκαιοι, ἔσωθεν δέ ἐστε μεστοὶ ὑποκρίσεως καὶ ἀνομίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 29, '¶Οὐαὶ ὑμῖν, γραμματεῖς καὶ Φαρισαῖοι, ὑποκριταί! Ὅτι οἰκοδομεῖτε τοὺς τάφους τῶν προφητῶν, καὶ κοσμεῖτε τὰ μνημεῖα τῶν δικαίων');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 30, 'καὶ λέγετε, ‘Εἰ ἤμεθα ἐν ταῖς ἡμέραις τῶν πατέρων ἡμῶν, οὐκ ἂν ἤμεθα κοινωνοὶ αὐτῶν ἐν τῷ αἵματι τῶν προφητῶν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 31, 'Ὥστε μαρτυρεῖτε ἑαυτοῖς ὅτι υἱοί ἐστε τῶν φονευσάντων τοὺς προφήτας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 32, 'Καὶ ὑμεῖς πληρώσατε τὸ μέτρον τῶν πατέρων ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 33, 'Ὄφεις, γεννήματα ἐχιδνῶν, πῶς φύγητε ἀπὸ τῆς κρίσεως τῆς Γεέννης;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 34, 'Διὰ τοῦτο, ἰδοὺ, ἐγὼ ἀποστέλλω πρὸς ὑμᾶς προφήτας, καὶ σοφοὺς, καὶ γραμματεῖς. Ἐξ αὐτῶν ἀποκτενεῖτε καὶ σταυρώσετε, καὶ ἐξ αὐτῶν μαστιγώσετε ἐν ταῖς συναγωγαῖς ὑμῶν, καὶ διώξετε ἀπὸ πόλεως εἰς πόλιν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 35, 'ὅπως ἔλθῃ ἐφʼ ὑμᾶς πᾶν αἷμα δίκαιον ἐκχυννόμενον ἐπὶ τῆς γῆς, ἀπὸ τοῦ αἵματος Ἅβελ τοῦ δικαίου, ἕως τοῦ αἵματος Ζαχαρίου υἱοῦ Βαραχίου, ὃν ἐφονεύσατε μεταξὺ τοῦ ναοῦ καὶ τοῦ θυσιαστηρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 36, 'Ἀμὴν, λέγω ὑμῖν, ἥξει πάντα ταῦτα ἐπὶ τὴν γενεὰν ταύτην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 37, '¶Ἰερουσαλὴμ, Ἰερουσαλήμ, ἡ ἀποκτείνουσα τοὺς προφήτας καὶ λιθοβολοῦσα, τοὺς ἀπεσταλμένους πρὸς αὐτήν! Ποσάκις ἠθέλησα ἐπισυναγαγεῖν τὰ τέκνα σου, ὃν τρόπον ὄρνις ἐπισυνάγει τὰ νοσσία αὐτῆς ὑπὸ τὰς πτέρυγας, καὶ οὐκ ἠθελήσατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 38, 'Ἰδοὺ, ἀφίεται ὑμῖν ὁ οἶκος ὑμῶν ἔρημος!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 39, 'Λέγω γὰρ ὑμῖν, οὐ μή με ἴδητε ἀπʼ ἄρτι ἕως ἂν εἴπητε, ‘Εὐλογημένος ὁ ἐρχόμενος ἐν ὀνόματι  ̊Κυρίου!’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 1, '¶Καὶ ἐξελθὼν ὁ  ̊Ἰησοῦς ἀπὸ τοῦ ἱεροῦ ἐπορεύετο, καὶ προσῆλθον οἱ μαθηταὶ αὐτοῦ, ἐπιδεῖξαι αὐτῷ τὰς οἰκοδομὰς τοῦ ἱεροῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 2, 'Ὁ δὲ ἀποκριθεὶς εἶπεν αὐτοῖς, “Οὐ βλέπετε ταῦτα πάντα; Ἀμὴν, λέγω ὑμῖν, οὐ μὴ ἀφεθῇ ὧδε λίθος ἐπὶ λίθον, ὃς οὐ καταλυθήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 3, '¶Καθημένου δὲ αὐτοῦ ἐπὶ τοῦ Ὄρους τῶν Ἐλαιῶν, προσῆλθον αὐτῷ οἱ μαθηταὶ κατʼ ἰδίαν λέγοντες, “Εἰπὲ ἡμῖν πότε ταῦτα ἔσται, καὶ τί τὸ σημεῖον τῆς σῆς παρουσίας καὶ συντελείας τοῦ αἰῶνος;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 4, 'Καὶ ἀποκριθεὶς ὁ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Βλέπετε, μή τις ὑμᾶς πλανήσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 5, 'Πολλοὶ γὰρ ἐλεύσονται ἐπὶ τῷ ὀνόματί μου λέγοντες, ‘Ἐγώ εἰμι ὁ  ̊Χριστός’, καὶ πολλοὺς πλανήσουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 6, 'Μελλήσετε δὲ ἀκούειν πολέμους, καὶ ἀκοὰς πολέμων. Ὁρᾶτε, μὴ θροεῖσθε· δεῖ γὰρ γενέσθαι, ἀλλʼ οὔπω ἐστὶν τὸ τέλος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 7, 'Ἐγερθήσεται γὰρ ἔθνος ἐπὶ ἔθνος, καὶ βασιλεία ἐπὶ βασιλείαν, καὶ ἔσονται λιμοὶ καὶ σεισμοὶ κατὰ τόπους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 8, 'Πάντα δὲ ταῦτα ἀρχὴ ὠδίνων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 9, '¶Τότε παραδώσουσιν ὑμᾶς εἰς θλῖψιν, καὶ ἀποκτενοῦσιν ὑμᾶς. Καὶ ἔσεσθε μισούμενοι ὑπὸ πάντων τῶν ἐθνῶν, διὰ τὸ ὄνομά μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 10, 'Καὶ τότε σκανδαλισθήσονται πολλοὶ, καὶ ἀλλήλους παραδώσουσιν καὶ μισήσουσιν ἀλλήλους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 11, 'Καὶ πολλοὶ ψευδοπροφῆται ἐγερθήσονται καὶ πλανήσουσιν πολλούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 12, 'Καὶ διὰ τὸ πληθυνθῆναι τὴν ἀνομίαν, ψυγήσεται ἡ ἀγάπη τῶν πολλῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 13, 'Ὁ δὲ ὑπομείνας εἰς τέλος, οὗτος σωθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 14, 'Καὶ κηρυχθήσεται τοῦτο τὸ εὐαγγέλιον τῆς βασιλείας ἐν ὅλῃ τῇ οἰκουμένῃ, εἰς μαρτύριον πᾶσιν τοῖς ἔθνεσιν, καὶ τότε ἥξει τὸ τέλος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 15, '¶Ὅταν οὖν ἴδητε ‘τὸ βδέλυγμα τῆς ἐρημώσεως’, τὸ ῥηθὲν διὰ Δανιὴλ τοῦ προφήτου, ἑστὸς ἐν τόπῳ ἁγίῳ (ὁ ἀναγινώσκων νοείτω),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 16, 'τότε οἱ ἐν τῇ Ἰουδαίᾳ, φευγέτωσαν εἰς τὰ ὄρη,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 17, 'ὁ ἐπὶ τοῦ δώματος, μὴ καταβάτω ἆραι τὰ ἐκ τῆς οἰκίας αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 18, 'καὶ ὁ ἐν τῷ ἀγρῷ, μὴ ἐπιστρεψάτω ὀπίσω ἆραι τὸ ἱμάτιον αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 19, 'Οὐαὶ δὲ ταῖς ἐν γαστρὶ ἐχούσαις, καὶ ταῖς θηλαζούσαις ἐν ἐκείναις ταῖς ἡμέραις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 20, 'Προσεύχεσθε δὲ ἵνα μὴ γένηται ἡ φυγὴ ὑμῶν χειμῶνος, μηδὲ Σαββάτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 21, 'Ἔσται γὰρ τότε θλῖψις μεγάλη, οἵα οὐ γέγονεν ἀπʼ ἀρχῆς κόσμου ἕως τοῦ νῦν, οὐδʼ οὐ μὴ γένηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 22, 'Καὶ εἰ μὴ ἐκολοβώθησαν αἱ ἡμέραι ἐκεῖναι, οὐκ ἂν ἐσώθη πᾶσα σάρξ, διὰ δὲ τοὺς ἐκλεκτοὺς, κολοβωθήσονται αἱ ἡμέραι ἐκεῖναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 23, 'Τότε ἐάν τις ὑμῖν εἴπῃ, ‘Ἰδοὺ, ὧδε ὁ  ̊Χριστός’, ἤ ‘Ὧδε’, μὴ πιστεύσητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 24, 'Ἐγερθήσονται γὰρ ψευδόχριστοι καὶ ψευδοπροφῆται, καὶ δώσουσιν σημεῖα μεγάλα καὶ τέρατα, ὥστε πλανῆσαι εἰ δυνατὸν καὶ τοὺς ἐκλεκτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 25, 'Ἰδοὺ, προείρηκα ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 26, 'Ἐὰν οὖν εἴπωσιν ὑμῖν, ‘Ἰδοὺ, ἐν τῇ ἐρήμῳ ἐστίν’, μὴ ἐξέλθητε. ‘Ἰδοὺ, ἐν τοῖς ταμείοις’, μὴ πιστεύσητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 27, 'Ὥσπερ γὰρ ἡ ἀστραπὴ ἐξέρχεται ἀπὸ ἀνατολῶν καὶ φαίνεται ἕως δυσμῶν, οὕτως ἔσται ἡ παρουσία τοῦ Υἱοῦ τοῦ Ἀνθρώπου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 28, 'Ὅπου ἐὰν ᾖ τὸ πτῶμα, ἐκεῖ συναχθήσονται οἱ ἀετοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 29, '¶Εὐθέως δὲ μετὰ τὴν θλῖψιν τῶν ἡμερῶν ἐκείνων, ‘ὁ ἥλιος σκοτισθήσεται καὶ ἡ σελήνη οὐ δώσει τὸ φέγγος αὐτῆς’, ‘καὶ οἱ ἀστέρες πεσοῦνται ἀπὸ τοῦ οὐρανοῦ’, καὶ αἱ δυνάμεις τῶν οὐρανῶν σαλευθήσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 30, 'Καὶ τότε φανήσεται τὸ σημεῖον τοῦ Υἱοῦ τοῦ Ἀνθρώπου ἐν οὐρανῷ, καὶ τότε κόψονται πᾶσαι αἱ φυλαὶ τῆς γῆς, καὶ ὄψονται ‘τὸν Υἱὸν τοῦ Ἀνθρώπου, ἐρχόμενον ἐπὶ τῶν νεφελῶν τοῦ οὐρανοῦ’ μετὰ δυνάμεως καὶ δόξης πολλῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 31, 'Καὶ ἀποστελεῖ τοὺς ἀγγέλους αὐτοῦ μετὰ ‘σάλπιγγος φωνῆς μεγάλης, καὶ ἐπισυνάξουσιν’ τοὺς ἐκλεκτοὺς αὐτοῦ ἐκ τῶν τεσσάρων ἀνέμων, ἀπʼ ἄκρων οὐρανῶν ἕως ἄκρων αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 32, '¶Ἀπὸ δὲ τῆς συκῆς, μάθετε τὴν παραβολήν: ὅταν ἤδη ὁ κλάδος αὐτῆς γένηται ἁπαλὸς καὶ τὰ φύλλα ἐκφύῃ, γινώσκετε ὅτι ἐγγὺς τὸ θέρος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 33, 'Οὕτως καὶ ὑμεῖς ὅταν ἴδητε ταῦτα πάντα, γινώσκετε ὅτι ἐγγύς ἐστιν ἐπὶ θύραις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 34, 'Ἀμὴν, λέγω ὑμῖν ὅτι οὐ μὴ παρέλθῃ ἡ γενεὰ αὕτη, ἕως ἂν πάντα ταῦτα γένηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 35, 'Ὁ οὐρανὸς καὶ ἡ γῆ παρελεύσεται, οἱ δὲ λόγοι μου οὐ μὴ παρέλθωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 36, '¶Περὶ δὲ τῆς ἡμέρας ἐκείνης καὶ ὥρας οὐδεὶς οἶδεν, οὐδὲ οἱ ἄγγελοι τῶν οὐρανῶν, οὐδὲ ὁ Υἱός, εἰ μὴ ὁ Πατὴρ μόνος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 37, 'Ὥσπερ γὰρ αἱ ἡμέραι τοῦ Νῶε, οὕτως ἔσται ἡ παρουσία τοῦ Υἱοῦ τοῦ Ἀνθρώπου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 38, 'Ὡς γὰρ ἦσαν ἐν ταῖς ἡμέραις ταῖς πρὸ τοῦ κατακλυσμοῦ τρώγοντες καὶ πίνοντες, γαμοῦντες καὶ γαμίζοντες, ἄχρι ἧς ἡμέρας εἰσῆλθεν, Νῶε εἰς τὴν κιβωτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 39, 'Καὶ οὐκ ἔγνωσαν, ἕως ἦλθεν ὁ κατακλυσμὸς καὶ ἦρεν ἅπαντας, οὕτως ἔσται ἡ παρουσία τοῦ Υἱοῦ τοῦ Ἀνθρώπου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 40, 'Τότε ἔσονται δύο ἐν τῷ ἀγρῷ, εἷς παραλαμβάνεται, καὶ εἷς ἀφίεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 41, 'Δύο ἀλήθουσαι ἐν τῷ μύλῳ, μία παραλαμβάνεται, καὶ μία ἀφίεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 42, 'Γρηγορεῖτε οὖν, ὅτι οὐκ οἴδατε ποίᾳ ἡμέρᾳ ὁ  ̊Κύριος ὑμῶν ἔρχεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 43, 'Ἐκεῖνο δὲ γινώσκετε ὅτι εἰ ᾔδει ὁ οἰκοδεσπότης, ποίᾳ φυλακῇ ὁ κλέπτης ἔρχεται, ἐγρηγόρησεν ἂν, καὶ οὐκ ἂν εἴασεν διορυγῆναι τὴν οἰκίαν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 44, 'Διὰ τοῦτο καὶ, ὑμεῖς γίνεσθε ἕτοιμοι, ὅτι ᾗ οὐ δοκεῖτε ὥρᾳ, ὁ Υἱὸς τοῦ Ἀνθρώπου ἔρχεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 45, '¶Τίς ἄρα ἐστὶν ὁ πιστὸς δοῦλος καὶ φρόνιμος, ὃν κατέστησεν ὁ κύριος ἐπὶ τῆς οἰκετείας αὐτοῦ, τοῦ δοῦναι αὐτοῖς τὴν τροφὴν ἐν καιρῷ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 46, 'Μακάριος ὁ δοῦλος ἐκεῖνος, ὃν ἐλθὼν ὁ κύριος αὐτοῦ εὑρήσει οὕτως ποιοῦντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 47, 'Ἀμὴν, λέγω ὑμῖν ὅτι ἐπὶ πᾶσιν τοῖς ὑπάρχουσιν αὐτοῦ, καταστήσει αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 48, 'Ἐὰν δὲ εἴπῃ ὁ κακὸς δοῦλος ἐκεῖνος ἐν τῇ καρδίᾳ αὐτοῦ, ‘Χρονίζει μου ὁ κύριος’,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 49, 'καὶ ἄρξηται τύπτειν τοὺς συνδούλους αὐτοῦ, ἐσθίῃ δὲ καὶ πίνῃ μετὰ τῶν μεθυόντων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 50, 'ἥξει ὁ κύριος τοῦ δούλου ἐκείνου ἐν ἡμέρᾳ ᾗ οὐ προσδοκᾷ, καὶ ἐν ὥρᾳ ᾗ οὐ γινώσκει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 51, 'καὶ διχοτομήσει αὐτὸν, καὶ τὸ μέρος αὐτοῦ μετὰ τῶν ὑποκριτῶν θήσει· ἐκεῖ ἔσται ὁ κλαυθμὸς καὶ ὁ βρυγμὸς τῶν ὀδόντων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 1, '¶Τότε ὁμοιωθήσεται ἡ Βασιλεία τῶν Οὐρανῶν δέκα παρθένοις, αἵτινες λαβοῦσαι τὰς λαμπάδας αὐτῶν ἐξῆλθον εἰς ὑπάντησιν τοῦ νυμφίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 2, 'Πέντε δὲ ἐξ αὐτῶν ἦσαν μωραὶ, καὶ πέντε φρόνιμοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 3, 'Αἱ γὰρ μωραὶ λαβοῦσαι τὰς λαμπάδας αὐτῶν, οὐκ ἔλαβον μεθʼ ἑαυτῶν ἔλαιον·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 4, 'αἱ δὲ φρόνιμοι ἔλαβον ἔλαιον ἐν τοῖς ἀγγείοις, μετὰ τῶν λαμπάδων ἑαυτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 5, 'Χρονίζοντος δὲ τοῦ νυμφίου, ἐνύσταξαν πᾶσαι καὶ ἐκάθευδον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 6, 'Μέσης δὲ νυκτὸς, κραυγὴ γέγονεν, ‘Ἰδοὺ, ὁ νυμφίος!’ Ἐξέρχεσθε εἰς ἀπάντησιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 7, 'Τότε ἠγέρθησαν πᾶσαι αἱ παρθένοι ἐκεῖναι, καὶ ἐκόσμησαν τὰς λαμπάδας ἑαυτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 8, 'Αἱ δὲ μωραὶ ταῖς φρονίμοις εἶπον, ‘Δότε ἡμῖν ἐκ τοῦ ἐλαίου ὑμῶν, ὅτι αἱ λαμπάδες ἡμῶν σβέννυνται.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 9, 'Ἀπεκρίθησαν δὲ αἱ φρόνιμοι λέγουσαι, ‘Μήποτε οὐ μὴ ἀρκέσῃ ἡμῖν καὶ ὑμῖν· πορεύεσθε μᾶλλον πρὸς τοὺς πωλοῦντας, καὶ ἀγοράσατε ἑαυταῖς.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 10, 'Ἀπερχομένων δὲ αὐτῶν ἀγοράσαι, ἦλθεν ὁ νυμφίος, καὶ αἱ ἕτοιμοι εἰσῆλθον μετʼ αὐτοῦ εἰς τοὺς γάμους, καὶ ἐκλείσθη ἡ θύρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 11, 'Ὕστερον δὲ ἔρχονται καὶ αἱ λοιπαὶ παρθένοι λέγουσαι, ‘Κύριε, κύριε, ἄνοιξον ἡμῖν!’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 12, 'Ὁ δὲ ἀποκριθεὶς εἶπεν, ‘Ἀμὴν, λέγω ὑμῖν, οὐκ οἶδα ὑμᾶς.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 13, 'Γρηγορεῖτε οὖν, ὅτι οὐκ οἴδατε τὴν ἡμέραν, οὐδὲ τὴν ὥραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 14, '¶Ὥσπερ γὰρ ἄνθρωπος ἀποδημῶν, ἐκάλεσεν τοὺς ἰδίους δούλους, καὶ παρέδωκεν αὐτοῖς τὰ ὑπάρχοντα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 15, 'Καὶ ᾧ μὲν ἔδωκεν πέντε τάλαντα, ᾧ δὲ δύο, ᾧ δὲ ἕν, ἑκάστῳ κατὰ τὴν ἰδίαν δύναμιν, καὶ ἀπεδήμησεν εὐθέως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 16, 'Πορευθεὶς, ὁ τὰ πέντε τάλαντα λαβὼν, ἠργάσατο ἐν αὐτοῖς καὶ ἐκέρδησεν ἄλλα πέντε τάλαντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 17, 'Ὡσαύτως καὶ ὁ τὰ δύο, ἐκέρδησεν ἄλλα δύο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 18, 'Ὁ δὲ τὸ ἓν λαβὼν, ἀπελθὼν ὤρυξεν γῆν καὶ ἔκρυψεν τὸ ἀργύριον τοῦ κυρίου αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 19, 'Μετὰ δὲ πολὺν χρόνον, ἔρχεται ὁ κύριος τῶν δούλων ἐκείνων, καὶ συναίρει λόγον μετʼ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 20, 'Καὶ προσελθὼν ὁ, τὰ πέντε τάλαντα λαβὼν, προσήνεγκεν ἄλλα πέντε τάλαντα λέγων, ‘Κύριε, πέντε τάλαντά μοι παρέδωκας, ἴδε, ἄλλα πέντε τάλαντα ἐκέρδησα.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 21, 'Ἔφη αὐτῷ ὁ κύριος αὐτοῦ, ‘Εὖ, δοῦλε ἀγαθὲ καὶ πιστέ! Ἐπὶ ὀλίγα ἦς πιστός, ἐπὶ πολλῶν σε καταστήσω· εἴσελθε εἰς τὴν χαρὰν τοῦ κυρίου σου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 22, 'Προσελθὼν καὶ ὁ τὰ δύο τάλαντα εἶπεν, ‘Κύριε, δύο τάλαντά μοι παρέδωκας. Ἴδε, ἄλλα δύο τάλαντα ἐκέρδησα.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 23, 'Ἔφη αὐτῷ ὁ κύριος αὐτοῦ, ‘Εὖ, δοῦλε ἀγαθὲ καὶ πιστέ! Ἐπὶ ὀλίγα ἦς πιστός, ἐπὶ πολλῶν σε καταστήσω· εἴσελθε εἰς τὴν χαρὰν τοῦ κυρίου σου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 24, 'Προσελθὼν δὲ καὶ ὁ τὸ ἓν τάλαντον εἰληφὼς εἶπεν, ‘Κύριε, ἔγνων σε, ὅτι σκληρὸς εἶ ἄνθρωπος, θερίζων ὅπου οὐκ ἔσπειρας, καὶ συνάγων ὅθεν οὐ διεσκόρπισας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 25, 'Καὶ φοβηθεὶς ἀπελθὼν, ἔκρυψα τὸ τάλαντόν σου ἐν τῇ γῇ. Ἴδε, ἔχεις τὸ σόν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 26, 'Ἀποκριθεὶς δὲ ὁ κύριος αὐτοῦ εἶπεν αὐτῷ, ‘Πονηρὲ Δοῦλε καὶ ὀκνηρέ! ἬΙδεις ὅτι θερίζω ὅπου οὐκ ἔσπειρα, καὶ συνάγω ὅθεν οὐ διεσκόρπισα;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 27, 'Ἔδει σε οὖν βαλεῖν τὰ ἀργύριά μου τοῖς τραπεζίταις, καὶ ἐλθὼν, ἐγὼ ἐκομισάμην ἂν τὸ ἐμὸν σὺν τόκῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 28, 'Ἄρατε οὖν ἀπʼ αὐτοῦ τὸ τάλαντον, καὶ δότε τῷ ἔχοντι τὰ δέκα τάλαντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 29, 'Τῷ γὰρ ἔχοντι παντὶ δοθήσεται καὶ περισσευθήσεται, τοῦ δὲ μὴ ἔχοντος, καὶ ὃ ἔχει ἀρθήσεται ἀπʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 30, 'Καὶ τὸν ἀχρεῖον δοῦλον, ἐκβάλετε εἰς τὸ σκότος τὸ ἐξώτερον. Ἐκεῖ ἔσται ὁ κλαυθμὸς καὶ ὁ βρυγμὸς τῶν ὀδόντων.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 31, '¶Ὅταν δὲ ἔλθῃ ὁ Υἱὸς τοῦ Ἀνθρώπου ἐν τῇ δόξῃ αὐτοῦ, καὶ πάντες οἱ ἄγγελοι μετʼ αὐτοῦ, τότε καθίσει ἐπὶ θρόνου δόξης αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 32, 'Καὶ συναχθήσονται ἔμπροσθεν αὐτοῦ πάντα τὰ ἔθνη, καὶ ἀφοριεῖ αὐτοὺς ἀπʼ ἀλλήλων, ὥσπερ ὁ ποιμὴν ἀφορίζει τὰ πρόβατα ἀπὸ τῶν ἐρίφων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 33, 'Καὶ στήσει τὰ μὲν πρόβατα ἐκ δεξιῶν αὐτοῦ, τὰ δὲ ἐρίφια ἐξ εὐωνύμων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 34, 'Τότε ἐρεῖ ὁ Βασιλεὺς τοῖς ἐκ δεξιῶν αὐτοῦ, ‘Δεῦτε οἱ εὐλογημένοι τοῦ Πατρός μου, κληρονομήσατε τὴν ἡτοιμασμένην ὑμῖν βασιλείαν ἀπὸ καταβολῆς κόσμου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 35, 'Ἐπείνασα γὰρ καὶ ἐδώκατέ μοι φαγεῖν, ἐδίψησα καὶ ἐποτίσατέ με, ξένος ἤμην καὶ συνηγάγετέ με,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 36, 'γυμνὸς καὶ περιεβάλετέ με, ἠσθένησα καὶ ἐπεσκέψασθέ με, ἐν φυλακῇ ἤμην καὶ ἤλθατε πρός με.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 37, 'Τότε ἀποκριθήσονται αὐτῷ οἱ δίκαιοι λέγοντες, ‘ ̊Κύριε, πότε σε εἴδομεν πεινῶντα καὶ ἐθρέψαμεν, ἢ διψῶντα καὶ ἐποτίσαμεν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 38, 'Πότε δέ σε εἴδομεν ξένον καὶ συνηγάγομεν, ἢ γυμνὸν καὶ περιεβάλομεν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 39, 'Πότε δέ σε εἴδομεν ἀσθενῆ ἢ ἐν φυλακῇ, καὶ ἤλθομεν πρός σε;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 40, 'Καὶ ἀποκριθεὶς ὁ Βασιλεὺς ἐρεῖ αὐτοῖς, ‘Ἀμὴν, λέγω ὑμῖν, ἐφʼ ὅσον ἐποιήσατε ἑνὶ τούτων τῶν ἀδελφῶν μου τῶν ἐλαχίστων, ἐμοὶ ἐποιήσατε.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 41, 'Τότε ἐρεῖ καὶ τοῖς ἐξ εὐωνύμων, ‘Πορεύεσθε ἀπʼ ἐμοῦ κατηραμένοι εἰς τὸ πῦρ τὸ αἰώνιον, τὸ ἡτοιμασμένον τῷ διαβόλῳ καὶ τοῖς ἀγγέλοις αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 42, 'Ἐπείνασα γὰρ καὶ οὐκ ἐδώκατέ μοι φαγεῖν, καὶ ἐδίψησα καὶ οὐκ ἐποτίσατέ με,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 43, 'ξένος ἤμην καὶ οὐ συνηγάγετέ με, γυμνὸς καὶ οὐ περιεβάλετέ με, ἀσθενὴς καὶ ἐν φυλακῇ καὶ οὐκ ἐπεσκέψασθέ με.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 44, 'Τότε ἀποκριθήσονται καὶ αὐτοὶ λέγοντες, ‘ ̊Κύριε, πότε σε εἴδομεν πεινῶντα, ἢ διψῶντα, ἢ ξένον, ἢ γυμνὸν, ἢ ἀσθενῆ, ἢ ἐν φυλακῇ, καὶ οὐ διηκονήσαμέν σοι;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 45, 'Τότε ἀποκριθήσεται αὐτοῖς λέγων, ‘Ἀμὴν, λέγω ὑμῖν, ἐφʼ ὅσον οὐκ ἐποιήσατε ἑνὶ τούτων τῶν ἐλαχίστων, οὐδὲ ἐμοὶ ἐποιήσατε.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 46, 'Καὶ ἀπελεύσονται οὗτοι εἰς κόλασιν αἰώνιον, οἱ δὲ δίκαιοι εἰς ζωὴν αἰώνιον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 1, '¶Καὶ ἐγένετο ὅτε ἐτέλεσεν ὁ  ̊Ἰησοῦς πάντας τοὺς λόγους τούτους, εἶπεν τοῖς μαθηταῖς αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 2, '“Οἴδατε ὅτι μετὰ δύο ἡμέρας τὸ Πάσχα γίνεται, καὶ ὁ Υἱὸς τοῦ Ἀνθρώπου παραδίδοται εἰς τὸ σταυρωθῆναι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 3, '¶Τότε συνήχθησαν οἱ ἀρχιερεῖς καὶ οἱ πρεσβύτεροι τοῦ λαοῦ εἰς τὴν αὐλὴν τοῦ ἀρχιερέως, τοῦ λεγομένου Καϊάφα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 4, 'καὶ συνεβουλεύσαντο ἵνα τὸν  ̊Ἰησοῦν δόλῳ κρατήσωσιν καὶ ἀποκτείνωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 5, 'Ἔλεγον δέ, “Μὴ ἐν τῇ ἑορτῇ, ἵνα μὴ θόρυβος γένηται ἐν τῷ λαῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 6, '¶Τοῦ δὲ  ̊Ἰησοῦ γενομένου ἐν Βηθανίᾳ ἐν οἰκίᾳ Σίμωνος τοῦ λεπροῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 7, 'προσῆλθεν αὐτῷ γυνὴ ἔχουσα ἀλάβαστρον μύρου βαρυτίμου, καὶ κατέχεεν ἐπὶ τῆς κεφαλῆς αὐτοῦ ἀνακειμένου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 8, 'Ἰδόντες δὲ, οἱ μαθηταὶ ἠγανάκτησαν λέγοντες, “Εἰς τί ἡ ἀπώλεια αὕτη;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 9, 'Ἐδύνατο γὰρ τοῦτο πραθῆναι πολλοῦ καὶ δοθῆναι πτωχοῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 10, 'Γνοὺς δὲ, ὁ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Τί κόπους παρέχετε τῇ γυναικί; Ἔργον γὰρ καλὸν ἠργάσατο εἰς ἐμέ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 11, 'Πάντοτε γὰρ τοὺς πτωχοὺς ἔχετε μεθʼ ἑαυτῶν, ἐμὲ δὲ οὐ πάντοτε ἔχετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 12, 'Βαλοῦσα γὰρ αὕτη τὸ μύρον τοῦτο ἐπὶ τοῦ σώματός μου, πρὸς τὸ ἐνταφιάσαι με ἐποίησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 13, 'Ἀμὴν, λέγω ὑμῖν, ὅπου ἐὰν κηρυχθῇ τὸ εὐαγγέλιον τοῦτο ἐν ὅλῳ τῷ κόσμῳ, λαληθήσεται καὶ ὃ ἐποίησεν αὕτη εἰς μνημόσυνον αὐτῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 14, '¶Τότε πορευθεὶς εἷς τῶν δώδεκα, ὁ λεγόμενος Ἰούδας Ἰσκαριώτης πρὸς τοὺς ἀρχιερεῖς');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 15, 'εἶπεν, “Τί θέλετέ μοι δοῦναι, κἀγὼ ὑμῖν παραδώσω αὐτόν;” Οἱ δὲ ἔστησαν αὐτῷ τριάκοντα ἀργύρια.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 16, 'Καὶ ἀπὸ τότε ἐζήτει εὐκαιρίαν, ἵνα αὐτὸν παραδῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 17, '¶Τῇ δὲ πρώτῃ τῶν Ἀζύμων, προσῆλθον οἱ μαθηταὶ τῷ  ̊Ἰησοῦ λέγοντες, “Ποῦ θέλεις ἑτοιμάσωμέν σοι φαγεῖν τὸ Πάσχα;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 18, 'Ὁ δὲ εἶπεν, “Ὑπάγετε εἰς τὴν πόλιν πρὸς τὸν δεῖνα καὶ εἴπατε αὐτῷ, ‘Ὁ διδάσκαλος λέγει, “Ὁ καιρός μου ἐγγύς ἐστιν· πρὸς σὲ ποιῶ τὸ Πάσχα μετὰ τῶν μαθητῶν μου.”’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 19, 'Καὶ ἐποίησαν οἱ μαθηταὶ ὡς συνέταξεν αὐτοῖς ὁ  ̊Ἰησοῦς, καὶ ἡτοίμασαν τὸ Πάσχα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 20, '¶Ὀψίας δὲ γενομένης, ἀνέκειτο μετὰ τῶν δώδεκα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 21, 'καὶ ἐσθιόντων αὐτῶν εἶπεν, “Ἀμὴν, λέγω ὑμῖν ὅτι εἷς ἐξ ὑμῶν παραδώσει με.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 22, 'Καὶ λυπούμενοι σφόδρα, ἤρξαντο λέγειν αὐτῷ εἷς ἕκαστος, αὐτῶν, “Μήτι ἐγώ εἰμι,  ̊Κύριε;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 23, 'Ὁ δὲ ἀποκριθεὶς εἶπεν, “Ὁ ἐμβάψας μετʼ ἐμοῦ τὴν χεῖρα ἐν τῷ τρυβλίῳ, οὗτός με παραδώσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 24, 'Ὁ μὲν Υἱὸς τοῦ Ἀνθρώπου ὑπάγει καθὼς γέγραπται περὶ αὐτοῦ, οὐαὶ δὲ τῷ ἀνθρώπῳ ἐκείνῳ διʼ οὗ ὁ Υἱὸς τοῦ Ἀνθρώπου παραδίδοται. Καλὸν ἦν αὐτῷ, εἰ οὐκ ἐγεννήθη ὁ ἄνθρωπος ἐκεῖνος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 25, 'Ἀποκριθεὶς δὲ Ἰούδας, ὁ παραδιδοὺς αὐτὸν εἶπεν, “Μήτι ἐγώ εἰμι, Ῥαββί;” Λέγει αὐτῷ, “Σὺ εἶπας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 26, '¶Ἐσθιόντων δὲ αὐτῶν, λαβὼν ὁ  ̊Ἰησοῦς ἄρτον, καὶ εὐλογήσας ἔκλασεν καὶ δοὺς τοῖς μαθηταῖς εἶπεν, “Λάβετε, φάγετε, τοῦτό ἐστιν τὸ σῶμά μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 27, 'Καὶ λαβὼν ποτήριον καὶ εὐχαριστήσας, ἔδωκεν αὐτοῖς λέγων, “Πίετε ἐξ αὐτοῦ πάντες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 28, 'τοῦτο γάρ ἐστιν τὸ αἷμά μου τῆς διαθήκης, τὸ περὶ πολλῶν ἐκχυννόμενον εἰς ἄφεσιν ἁμαρτιῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 29, 'Λέγω δὲ ὑμῖν, οὐ μὴ πίω ἀπʼ ἄρτι ἐκ τούτου τοῦ γενήματος τῆς ἀμπέλου ἕως τῆς ἡμέρας ἐκείνης, ὅταν αὐτὸ πίνω μεθʼ ὑμῶν καινὸν ἐν τῇ βασιλείᾳ τοῦ Πατρός μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 30, 'Καὶ ὑμνήσαντες, ἐξῆλθον εἰς τὸ Ὄρος τῶν Ἐλαιῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 31, '¶Τότε λέγει αὐτοῖς ὁ  ̊Ἰησοῦς, “Πάντες ὑμεῖς σκανδαλισθήσεσθε ἐν ἐμοὶ ἐν τῇ νυκτὶ ταύτῃ, γέγραπται γάρ, ‘Πατάξω τὸν ποιμένα, καὶ διασκορπισθήσονται τὰ πρόβατα τῆς ποίμνης.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 32, 'Μετὰ δὲ τὸ ἐγερθῆναί με, προάξω ὑμᾶς εἰς τὴν Γαλιλαίαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 33, 'Ἀποκριθεὶς δὲ ὁ Πέτρος εἶπεν αὐτῷ, “Εἰ πάντες σκανδαλισθήσονται ἐν σοί, ἐγὼ οὐδέποτε σκανδαλισθήσομαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 34, 'Ἔφη αὐτῷ ὁ  ̊Ἰησοῦς, “Ἀμὴν, λέγω σοι ὅτι ἐν ταύτῃ τῇ νυκτὶ πρὶν ἀλέκτορα φωνῆσαι, τρὶς ἀπαρνήσῃ με.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 35, 'Λέγει αὐτῷ ὁ Πέτρος, “Κἂν δέῃ με σὺν σοὶ ἀποθανεῖν, οὐ μή σε ἀπαρνήσομαι.” Ὁμοίως καὶ πάντες οἱ μαθηταὶ εἶπον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 36, '¶Τότε ἔρχεται μετʼ αὐτῶν ὁ  ̊Ἰησοῦς εἰς χωρίον λεγόμενον Γεθσημανὶ, καὶ λέγει τοῖς μαθηταῖς, “Καθίσατε αὐτοῦ ἕως οὗ ἀπελθὼν ἐκεῖ προσεύξωμαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 37, 'Καὶ παραλαβὼν τὸν Πέτρον καὶ τοὺς δύο υἱοὺς Ζεβεδαίου, ἤρξατο λυπεῖσθαι καὶ ἀδημονεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 38, 'Τότε λέγει αὐτοῖς, “Περίλυπός ἐστιν ἡ ψυχή μου ἕως θανάτου· μείνατε ὧδε καὶ γρηγορεῖτε μετʼ ἐμοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 39, 'Καὶ προσελθὼν μικρὸν, ἔπεσεν ἐπὶ πρόσωπον αὐτοῦ προσευχόμενος καὶ λέγων, “Πάτερ μου, εἰ δυνατόν ἐστιν, παρελθάτω ἀπʼ ἐμοῦ τὸ ποτήριον τοῦτο. Πλὴν οὐχ ὡς ἐγὼ θέλω, ἀλλʼ ὡς σύ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 40, 'Καὶ ἔρχεται πρὸς τοὺς μαθητὰς καὶ εὑρίσκει αὐτοὺς καθεύδοντας, καὶ λέγει τῷ Πέτρῳ, “Οὕτως οὐκ ἰσχύσατε μίαν ὥραν γρηγορῆσαι μετʼ ἐμοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 41, 'Γρηγορεῖτε καὶ προσεύχεσθε, ἵνα μὴ εἰσέλθητε εἰς πειρασμόν. Τὸ μὲν πνεῦμα πρόθυμον, ἡ δὲ σὰρξ ἀσθενής.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 42, 'Πάλιν ἐκ δευτέρου ἀπελθὼν προσηύξατο λέγων, “Πάτερ μου, εἰ οὐ δύναται τοῦτο παρελθεῖν, ἐὰν μὴ αὐτὸ πίω, γενηθήτω τὸ θέλημά σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 43, 'Καὶ ἐλθὼν πάλιν, εὗρεν αὐτοὺς καθεύδοντας, ἦσαν γὰρ αὐτῶν οἱ ὀφθαλμοὶ βεβαρημένοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 44, 'Καὶ ἀφεὶς αὐτοὺς πάλιν ἀπελθὼν, προσηύξατο ἐκ τρίτου τὸν αὐτὸν λόγον εἰπὼν πάλιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 45, 'Τότε ἔρχεται πρὸς τοὺς μαθητὰς καὶ λέγει αὐτοῖς, “Καθεύδετε τὸ λοιπὸν καὶ ἀναπαύεσθε; Ἰδοὺ, ἤγγικεν ἡ ὥρα, καὶ ὁ Υἱὸς τοῦ Ἀνθρώπου παραδίδοται εἰς χεῖρας ἁμαρτωλῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 46, 'Ἐγείρεσθε, ἄγωμεν! Ἰδοὺ, ἤγγικεν ὁ παραδιδούς με!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 47, '¶Καὶ ἔτι αὐτοῦ λαλοῦντος, ἰδοὺ, Ἰούδας εἷς τῶν δώδεκα ἦλθεν, καὶ μετʼ αὐτοῦ ὄχλος πολὺς μετὰ μαχαιρῶν καὶ ξύλων ἀπὸ τῶν ἀρχιερέων καὶ πρεσβυτέρων τοῦ λαοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 48, 'Ὁ δὲ παραδιδοὺς αὐτὸν, ἔδωκεν αὐτοῖς σημεῖον λέγων, “Ὃν ἂν φιλήσω, αὐτός ἐστιν· κρατήσατε αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 49, 'Καὶ εὐθέως προσελθὼν τῷ  ̊Ἰησοῦ εἶπεν, “Χαῖρε, Ῥαββί, καὶ κατεφίλησεν αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 50, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν αὐτῷ, “Ἑταῖρε, Ἐφʼ ὃ πάρει;” Τότε προσελθόντες, ἐπέβαλον τὰς χεῖρας ἐπὶ τὸν  ̊Ἰησοῦν, καὶ ἐκράτησαν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 51, 'Καὶ ἰδοὺ, εἷς τῶν μετὰ  ̊Ἰησοῦ, ἐκτείνας τὴν χεῖρα, ἀπέσπασεν τὴν μάχαιραν αὐτοῦ καὶ πατάξας τὸν δοῦλον τοῦ ἀρχιερέως, ἀφεῖλεν αὐτοῦ τὸ ὠτίον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 52, 'Τότε λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Ἀπόστρεψον τὴν μάχαιράν σου εἰς τὸν τόπον αὐτῆς, πάντες γὰρ οἱ λαβόντες μάχαιραν, ἐν μαχαίρῃ ἀπολοῦνται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 53, 'Ἢ δοκεῖς ὅτι οὐ δύναμαι ἄρτι παρακαλέσαι τὸν Πατέρα μου, καὶ παραστήσει μοι πλείω δώδεκα λεγεῶνων ἀγγέλων;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 54, 'Πῶς οὖν πληρωθῶσιν αἱ Γραφαὶ, ὅτι οὕτως δεῖ γενέσθαι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 55, 'Ἐν ἐκείνῃ τῇ ὥρᾳ, εἶπεν ὁ  ̊Ἰησοῦς τοῖς ὄχλοις, “Ὡς ἐπὶ λῃστὴν ἐξήλθατε μετὰ μαχαιρῶν καὶ ξύλων συλλαβεῖν με; Καθʼ ἡμέραν ἐν τῷ ἱερῷ, ἐκαθεζόμην διδάσκων, καὶ οὐκ ἐκρατήσατέ με.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 56, 'Τοῦτο δὲ ὅλον γέγονεν, ἵνα πληρωθῶσιν αἱ Γραφαὶ τῶν προφητῶν.” Τότε οἱ μαθηταὶ πάντες, ἀφέντες αὐτὸν ἔφυγον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 57, '¶Οἱ δὲ κρατήσαντες τὸν  ̊Ἰησοῦν, ἀπήγαγον πρὸς Καϊάφαν τὸν ἀρχιερέα, ὅπου οἱ γραμματεῖς καὶ οἱ πρεσβύτεροι συνήχθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 58, 'Ὁ δὲ Πέτρος ἠκολούθει αὐτῷ ἀπὸ μακρόθεν ἕως τῆς αὐλῆς τοῦ ἀρχιερέως, καὶ εἰσελθὼν ἔσω, ἐκάθητο μετὰ τῶν ὑπηρετῶν ἰδεῖν τὸ τέλος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 59, 'Οἱ δὲ ἀρχιερεῖς καὶ τὸ Συνέδριον ὅλον ἐζήτουν ψευδομαρτυρίαν κατὰ τοῦ  ̊Ἰησοῦ, ὅπως αὐτὸν θανατώσωσιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 60, 'καὶ οὐχ εὗρον, πολλῶν προσελθόντων ψευδομαρτύρων. Ὕστερον δὲ προσελθόντες δύο');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 61, 'εἶπον, “Οὗτος ἔφη, ‘Δύναμαι καταλῦσαι τὸν ναὸν τοῦ  ̊Θεοῦ, καὶ διὰ τριῶν ἡμερῶν αὑτόν οἰκοδομῆσαι.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 62, 'Καὶ ἀναστὰς, ὁ ἀρχιερεὺς εἶπεν αὐτῷ, “Οὐδὲν ἀποκρίνῃ, τί οὗτοί σου καταμαρτυροῦσιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 63, 'Ὁ δὲ  ̊Ἰησοῦς ἐσιώπα. Καὶ ὁ ἀρχιερεὺς εἶπεν αὐτῷ, “Ἐξορκίζω σε κατὰ τοῦ  ̊Θεοῦ τοῦ ζῶντος ἵνα ἡμῖν εἴπῃς εἰ σὺ εἶ ὁ  ̊Χριστὸς, ὁ Υἱὸς τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 64, 'Λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Σὺ εἶπας. Πλὴν λέγω ὑμῖν, ἀπʼ ἄρτι ὄψεσθε τὸν Υἱὸν τοῦ Ἀνθρώπου, ‘καθήμενον ἐκ δεξιῶν’ τῆς δυνάμεως, καὶ ‘ἐρχόμενον ἐπὶ τῶν νεφελῶν τοῦ οὐρανοῦ’.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 65, 'Τότε ὁ ἀρχιερεὺς διέρρηξεν τὰ ἱμάτια αὐτοῦ λέγων, “Ἐβλασφήμησεν· τί ἔτι χρείαν ἔχομεν μαρτύρων; Ἴδε, νῦν ἠκούσατε τὴν βλασφημίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 66, 'Τί ὑμῖν δοκεῖ;” Οἱ δὲ ἀποκριθέντες εἶπον, “Ἔνοχος θανάτου ἐστίν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 67, 'Τότε ἐνέπτυσαν εἰς τὸ πρόσωπον αὐτοῦ καὶ ἐκολάφισαν αὐτόν, οἱ δὲ ἐράπισαν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 68, 'λέγοντες, “Προφήτευσον ἡμῖν,  ̊Χριστέ, τίς ἐστιν ὁ παίσας σε;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 69, '¶Ὁ δὲ Πέτρος ἐκάθητο ἔξω ἐν τῇ αὐλῇ, καὶ προσῆλθεν αὐτῷ μία παιδίσκη λέγουσα, “Καὶ σὺ ἦσθα μετὰ  ̊Ἰησοῦ τοῦ Γαλιλαίου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 70, 'Ὁ δὲ ἠρνήσατο ἔμπροσθεν πάντων λέγων, “Οὐκ οἶδα τί λέγεις.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 71, 'Ἐξελθόντα δὲ εἰς τὸν πυλῶνα, εἶδεν αὐτὸν ἄλλη καὶ λέγει τοῖς ἐκεῖ, “Οὗτος ἦν μετὰ  ̊Ἰησοῦ τοῦ Ναζωραίου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 72, 'Καὶ πάλιν ἠρνήσατο μετὰ ὅρκου, ὅτι “Οὐκ οἶδα τὸν ἄνθρωπον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 73, 'Μετὰ μικρὸν δὲ προσελθόντες οἱ ἑστῶτες εἶπον τῷ Πέτρῳ, “Ἀληθῶς καὶ σὺ ἐξ αὐτῶν εἶ, καὶ γὰρ ἡ λαλιά σου δῆλόν σε ποιεῖ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 74, 'Τότε ἤρξατο καταθεματίζειν καὶ ὀμνύειν, ὅτι “Οὐκ οἶδα τὸν ἄνθρωπον!” Καὶ εὐθέως ἀλέκτωρ ἐφώνησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 75, 'Καὶ ἐμνήσθη ὁ Πέτρος τοῦ ῥήματος  ̊Ἰησοῦ εἰρηκότος, ὅτι “Πρὶν ἀλέκτορα φωνῆσαι, τρὶς ἀπαρνήσῃ με”. Καὶ ἐξελθὼν ἔξω, ἔκλαυσεν πικρῶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 1, '¶Πρωΐας δὲ γενομένης, συμβούλιον ἔλαβον πάντες οἱ ἀρχιερεῖς καὶ οἱ πρεσβύτεροι τοῦ λαοῦ κατὰ τοῦ  ̊Ἰησοῦ, ὥστε θανατῶσαι αὐτόν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 2, 'καὶ δήσαντες αὐτὸν ἀπήγαγον καὶ παρέδωκαν Πιλάτῳ τῷ ἡγεμόνι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 3, '¶Τότε ἰδὼν Ἰούδας ὁ παραδιδοὺς αὐτὸν, ὅτι κατεκρίθη, μεταμεληθεὶς ἔστρεψεν τὰ τριάκοντα ἀργύρια τοῖς ἀρχιερεῦσιν καὶ πρεσβυτέροις');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 4, 'λέγων, “Ἥμαρτον παραδοὺς αἷμα ἀθῷον.” Οἱ δὲ εἶπον, “Τί πρὸς ἡμᾶς; Σὺ ὄψῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 5, 'Καὶ ῥίψας τὰ ἀργύρια εἰς τὸν ναὸν, ἀνεχώρησεν καὶ ἀπελθὼν ἀπήγξατο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 6, 'Οἱ δὲ ἀρχιερεῖς λαβόντες τὰ ἀργύρια εἶπον, “Οὐκ ἔξεστιν βαλεῖν αὐτὰ εἰς τὸν κορβανᾶν, ἐπεὶ τιμὴ αἵματός ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 7, 'Συμβούλιον δὲ λαβόντες, ἠγόρασαν ἐξ αὐτῶν τὸν Ἀγρὸν τοῦ Κεραμέως, εἰς ταφὴν τοῖς ξένοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 8, 'Διὸ ἐκλήθη ὁ ἀγρὸς ἐκεῖνος, Ἀγρὸς Αἵματος ἕως τῆς σήμερον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 9, 'Τότε ἐπληρώθη τὸ ῥηθὲν διὰ Ἰερεμίου τοῦ προφήτου λέγοντος, “Καὶ ἔλαβον τὰ τριάκοντα ἀργύρια, τὴν τιμὴν τοῦ τετιμημένου, ὃν ἐτιμήσαντο” ἀπὸ υἱῶν Ἰσραήλ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 10, '“καὶ ἔδωκαν αὐτὰ εἰς τὸν Ἀγρὸν τοῦ Κεραμέως, καθὰ συνέταξέν μοι  ̊Κύριος”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 11, '¶Ὁ δὲ  ̊Ἰησοῦς ἐστάθη ἔμπροσθεν τοῦ ἡγεμόνος· καὶ ἐπηρώτησεν αὐτὸν ὁ ἡγεμὼν λέγων, “Σὺ εἶ ὁ βασιλεὺς τῶν Ἰουδαίων;” Ὁ δὲ  ̊Ἰησοῦς ἔφη αὐτῷ, “Σὺ λέγεις.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 12, 'Καὶ ἐν τῷ κατηγορεῖσθαι αὐτὸν ὑπὸ τῶν ἀρχιερέων καὶ τῶν πρεσβυτέρων, οὐδὲν ἀπεκρίνατο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 13, 'Τότε λέγει αὐτῷ ὁ Πιλᾶτος, “Οὐκ ἀκούεις πόσα σου καταμαρτυροῦσιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 14, 'Καὶ οὐκ ἀπεκρίθη αὐτῷ πρὸς οὐδὲ ἓν ῥῆμα, ὥστε θαυμάζειν τὸν ἡγεμόνα λίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 15, '¶Κατὰ δὲ ἑορτὴν, εἰώθει ὁ ἡγεμὼν ἀπολύειν ἕνα τῷ ὄχλῳ δέσμιον, ὃν ἤθελον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 16, 'Εἶχον δὲ τότε δέσμιον ἐπίσημον, λεγόμενον Βαραββᾶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 17, 'Συνηγμένων οὖν αὐτῶν, εἶπεν αὐτοῖς ὁ Πιλᾶτος, “Τίνα θέλετε ἀπολύσω ὑμῖν, Βαραββᾶν ἢ  ̊Ἰησοῦν, τὸν λεγόμενον  ̊Χριστόν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 18, 'ᾔδει γὰρ ὅτι διὰ φθόνον παρέδωκαν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 19, 'Καθημένου δὲ αὐτοῦ ἐπὶ τοῦ βήματος, ἀπέστειλεν πρὸς αὐτὸν ἡ γυνὴ αὐτοῦ λέγουσα, “Μηδὲν σοὶ καὶ τῷ δικαίῳ ἐκείνῳ, πολλὰ γὰρ ἔπαθον σήμερον κατʼ ὄναρ διʼ αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 20, 'Οἱ δὲ ἀρχιερεῖς καὶ οἱ πρεσβύτεροι ἔπεισαν τοὺς ὄχλους, ἵνα αἰτήσωνται τὸν Βαραββᾶν, τὸν δὲ  ̊Ἰησοῦν ἀπολέσωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 21, 'Ἀποκριθεὶς δὲ ὁ ἡγεμὼν εἶπεν αὐτοῖς, “Τίνα θέλετε ἀπὸ τῶν δύο, ἀπολύσω ὑμῖν;” Οἱ δὲ εἶπον, τὸν “Βαραββᾶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 22, 'Λέγει αὐτοῖς ὁ Πιλᾶτος, “Τί οὖν ποιήσω  ̊Ἰησοῦν, τὸν λεγόμενον  ̊Χριστόν;” Λέγουσιν πάντες, “Σταυρωθήτω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 23, 'Ὁ δὲ ἔφη, “Τί γὰρ κακὸν ἐποίησεν;” Οἱ δὲ περισσῶς ἔκραζον λέγοντες, “Σταυρωθήτω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 24, 'Ἰδὼν δὲ ὁ Πιλᾶτος ὅτι οὐδὲν ὠφελεῖ, ἀλλὰ μᾶλλον θόρυβος γίνεται, λαβὼν ὕδωρ, ἀπενίψατο τὰς χεῖρας ἀπέναντι τοῦ ὄχλου λέγων, “Ἀθῷός εἰμι ἀπὸ τοῦ αἵματος τοῦ δικαίου τούτου. Ὑμεῖς ὄψεσθε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 25, 'Καὶ ἀποκριθεὶς πᾶς ὁ λαὸς εἶπεν, “Τὸ αἷμα αὐτοῦ ἐφʼ ἡμᾶς καὶ ἐπὶ τὰ τέκνα ἡμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 26, 'Τότε ἀπέλυσεν αὐτοῖς τὸν Βαραββᾶν, τὸν δὲ  ̊Ἰησοῦν φραγελλώσας, παρέδωκεν, ἵνα σταυρωθῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 27, '¶Τότε οἱ στρατιῶται τοῦ ἡγεμόνος, παραλαβόντες τὸν  ̊Ἰησοῦν εἰς τὸ πραιτώριον, συνήγαγον ἐπʼ αὐτὸν ὅλην τὴν σπεῖραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 28, 'Καὶ ἐκδύσαντες αὐτὸν, χλαμύδα κοκκίνην περιέθηκαν αὐτῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 29, 'καὶ πλέξαντες στέφανον ἐξ ἀκανθῶν, ἐπέθηκαν ἐπὶ τῆς κεφαλῆς αὐτοῦ, καὶ κάλαμον ἐν τῇ δεξιᾷ αὐτοῦ, καὶ γονυπετήσαντες ἔμπροσθεν αὐτοῦ, ἐνέπαιξαν αὐτῷ λέγοντες, “Χαῖρε, ὁ Βασιλεῦς τῶν Ἰουδαίων!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 30, 'Καὶ ἐμπτύσαντες εἰς αὐτὸν, ἔλαβον τὸν κάλαμον, καὶ ἔτυπτον εἰς τὴν κεφαλὴν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 31, 'Καὶ ὅτε ἐνέπαιξαν αὐτῷ, ἐξέδυσαν αὐτὸν τὴν χλαμύδα καὶ ἐνέδυσαν αὐτὸν τὰ ἱμάτια αὐτοῦ, καὶ ἀπήγαγον αὐτὸν εἰς τὸ σταυρῶσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 32, '¶Ἐξερχόμενοι δὲ, εὗρον ἄνθρωπον Κυρηναῖον, ὀνόματι Σίμωνα. Τοῦτον ἠγγάρευσαν ἵνα ἄρῃ τὸν σταυρὸν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 33, 'Καὶ ἐλθόντες εἰς τόπον λεγόμενον Γολγοθᾶ, ὅ ἐστιν “Κρανίου Τόπος” λεγόμενος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 34, 'Ἔδωκαν αὐτῷ πιεῖν οἶνον μετὰ χολῆς μεμιγμένον· καὶ γευσάμενος, οὐκ ἠθέλησεν πιεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 35, 'Σταυρώσαντες δὲ αὐτὸν, διεμερίσαντο τὰ ἱμάτια αὐτοῦ βάλλοντες κλῆρον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 36, 'καὶ καθήμενοι ἐτήρουν αὐτὸν ἐκεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 37, 'Καὶ ἐπέθηκαν ἐπάνω τῆς κεφαλῆς αὐτοῦ τὴν αἰτίαν αὐτοῦ γεγραμμένην, “Οὗτός ἐστιν  ̊Ἰησοῦς, ὁ Βασιλεὺς τῶν Ἰουδαίων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 38, '¶Τότε σταυροῦνται σὺν αὐτῷ δύο λῃσταί, εἷς ἐκ δεξιῶν, καὶ εἷς ἐξ εὐωνύμων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 39, 'Οἱ δὲ παραπορευόμενοι ἐβλασφήμουν αὐτὸν, κινοῦντες τὰς κεφαλὰς αὐτῶν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 40, 'καὶ λέγοντες, “Ὁ καταλύων τὸν ναὸν καὶ ἐν τρισὶν ἡμέραις οἰκοδομῶν, σῶσον σεαυτόν, εἰ υἱὸς εἶ τοῦ  ̊Θεοῦ, κατάβηθι ἀπὸ τοῦ σταυροῦ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 41, 'Ὁμοίως οἱ ἀρχιερεῖς ἐμπαίζοντες μετὰ τῶν γραμματέων καὶ πρεσβυτέρων ἔλεγον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 42, '“Ἄλλους ἔσωσεν, ἑαυτὸν οὐ δύναται σῶσαι. Βασιλεὺς Ἰσραήλ ἐστιν, καταβάτω νῦν ἀπὸ τοῦ σταυροῦ, καὶ πιστεύσομεν ἐπʼ αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 43, '‘Πέποιθεν ἐπὶ τὸν  ̊Θεόν, ῥυσάσθω νῦν εἰ θέλει αὐτόν.’ Εἶπεν γὰρ, ὅτι ‘ ̊Θεοῦ εἰμι Υἱός.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 44, 'Τὸ δʼ αὐτὸ καὶ οἱ λῃσταὶ, οἱ συσταυρωθέντες σὺν αὐτῷ, ὠνείδιζον αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 45, '¶Ἀπὸ δὲ ἕκτης ὥρας, σκότος ἐγένετο ἐπὶ πᾶσαν τὴν γῆν ἕως ὥρας ἐνάτης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 46, 'Περὶ δὲ τὴν ἐνάτην ὥραν, ἐβόησεν ὁ  ̊Ἰησοῦς φωνῇ μεγάλῃ λέγων, “Ἐλωί, Ἐλωί, λεμὰ σαβαχθάνι;” Τοῦτʼ ἔστιν, “ ̊Θεέ μου,  ̊Θεέ μου, ἵνα τί με ἐγκατέλιπες;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 47, 'Τινὲς δὲ τῶν ἐκεῖ ἑστηκότων ἀκούσαντες ἔλεγον, ὅτι “Ἠλίαν φωνεῖ οὗτος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 48, 'Καὶ εὐθέως δραμὼν εἷς ἐξ αὐτῶν καὶ λαβὼν σπόγγον, πλήσας τε ὄξους καὶ περιθεὶς καλάμῳ, ἐπότιζεν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 49, 'Οἱ δὲ λοιποὶ ἔλεγον, “Ἄφες, ἴδωμεν εἰ ἔρχεται Ἠλίας σώσων αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 50, 'Ὁ δὲ  ̊Ἰησοῦς πάλιν κράξας φωνῇ μεγάλῃ, ἀφῆκεν τὸ πνεῦμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 51, 'Καὶ ἰδοὺ, τὸ καταπέτασμα τοῦ ναοῦ ἐσχίσθη ἀπʼ ἄνωθεν ἕως κάτω, εἰς δύο καὶ ἡ γῆ ἐσείσθη, καὶ αἱ πέτραι ἐσχίσθησαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 52, 'καὶ τὰ μνημεῖα ἀνεῴχθησαν, καὶ πολλὰ σώματα τῶν κεκοιμημένων ἁγίων ἠγέρθη·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 53, 'καὶ ἐξελθόντες ἐκ τῶν μνημείων μετὰ τὴν ἔγερσιν αὐτοῦ, εἰσῆλθον εἰς τὴν ἁγίαν πόλιν καὶ ἐνεφανίσθησαν πολλοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 54, 'Ὁ δὲ ἑκατόνταρχος καὶ οἱ μετʼ αὐτοῦ τηροῦντες τὸν  ̊Ἰησοῦν, ἰδόντες τὸν σεισμὸν καὶ τὰ γενόμενα, ἐφοβήθησαν σφόδρα λέγοντες, “Ἀληθῶς Υἱὸς  ̊Θεοῦ ἦν οὗτος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 55, '¶Ἦσαν δὲ ἐκεῖ γυναῖκες πολλαὶ ἀπὸ μακρόθεν θεωροῦσαι, αἵτινες ἠκολούθησαν τῷ  ̊Ἰησοῦ ἀπὸ τῆς Γαλιλαίας διακονοῦσαι αὐτῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 56, 'ἐν αἷς ἦν Μαρία ἡ Μαγδαληνὴ, καὶ Μαρία ἡ τοῦ Ἰακώβου καὶ Ἰωσὴ μήτηρ, καὶ ἡ μήτηρ τῶν υἱῶν Ζεβεδαίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 57, '¶Ὀψίας δὲ γενομένης, ἦλθεν ἄνθρωπος πλούσιος ἀπὸ Ἁριμαθαίας, τοὔνομα Ἰωσήφ, ὃς καὶ αὐτὸς ἐμαθήτευσεν τῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 58, 'Οὗτος προσελθὼν τῷ Πιλάτῳ, ᾐτήσατο τὸ σῶμα τοῦ  ̊Ἰησοῦ. Τότε ὁ Πιλᾶτος ἐκέλευσεν ἀποδοθῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 59, 'καὶ λαβὼν τὸ σῶμα, ὁ Ἰωσὴφ ἐνετύλιξεν αὐτὸ σινδόνι καθαρᾷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 60, 'καὶ ἔθηκεν αὐτὸ ἐν τῷ καινῷ αὐτοῦ μνημείῳ, ὃ ἐλατόμησεν ἐν τῇ πέτρᾳ, καὶ προσκυλίσας λίθον μέγαν τῇ θύρᾳ τοῦ μνημείου, ἀπῆλθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 61, 'Ἦν δὲ ἐκεῖ Μαριὰμ ἡ Μαγδαληνὴ καὶ ἡ ἄλλη Μαρία, καθήμεναι ἀπέναντι τοῦ τάφου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 62, '¶Τῇ δὲ ἐπαύριον, ἥτις ἐστὶν μετὰ τὴν παρασκευήν, συνήχθησαν οἱ ἀρχιερεῖς καὶ οἱ Φαρισαῖοι πρὸς Πιλᾶτον');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 63, 'λέγοντες, “Κύριε, ἐμνήσθημεν ὅτι ἐκεῖνος ὁ πλάνος εἶπεν ἔτι ζῶν, ‘Μετὰ τρεῖς ἡμέρας ἐγείρομαι.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 64, 'Κέλευσον οὖν ἀσφαλισθῆναι τὸν τάφον ἕως τῆς τρίτης ἡμέρας, μήποτε ἐλθόντες οἱ μαθηταὶ κλέψωσιν αὐτὸν καὶ εἴπωσιν τῷ λαῷ, ‘Ἠγέρθη ἀπὸ τῶν νεκρῶν’, καὶ ἔσται ἡ ἐσχάτη πλάνη χείρων τῆς πρώτης.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 65, 'Ἔφη δὲ αὐτοῖς ὁ Πιλᾶτος, “Ἔχετε κουστωδίαν, ὑπάγετε ἀσφαλίσασθε ὡς οἴδατε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 66, 'Οἱ δὲ πορευθέντες ἠσφαλίσαντο τὸν τάφον, σφραγίσαντες τὸν λίθον μετὰ τῆς κουστωδίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 1, '¶Ὀψὲ δὲ Σαββάτων, τῇ ἐπιφωσκούσῃ εἰς μίαν σαββάτων, ἦλθεν Μαρία ἡ Μαγδαληνὴ καὶ ἡ ἄλλη Μαρία, θεωρῆσαι τὸν τάφον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 2, 'Καὶ ἰδοὺ, σεισμὸς ἐγένετο μέγας· ἄγγελος γὰρ  ̊Κυρίου καταβὰς ἐξ οὐρανοῦ καὶ προσελθὼν, ἀπεκύλισεν τὸν λίθον καὶ ἐκάθητο ἐπάνω αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 3, 'Ἦν δὲ ἡ εἰδέα αὐτοῦ ὡς ἀστραπὴ, καὶ τὸ ἔνδυμα αὐτοῦ λευκὸν ὡς χιών.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 4, 'Ἀπὸ δὲ τοῦ φόβου αὐτοῦ, ἐσείσθησαν οἱ τηροῦντες, καὶ ἐγενήθησαν ὡς νεκροί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 5, 'Ἀποκριθεὶς δὲ ὁ ἄγγελος εἶπεν ταῖς γυναιξίν, “Μὴ φοβεῖσθε ὑμεῖς, οἶδα γὰρ ὅτι  ̊Ἰησοῦν, τὸν ἐσταυρωμένον, ζητεῖτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 6, 'Οὐκ ἔστιν ὧδε, ἠγέρθη γὰρ καθὼς εἶπεν. Δεῦτε ἴδετε τὸν τόπον ὅπου ἔκειτο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 7, 'Καὶ ταχὺ πορευθεῖσαι, εἴπατε τοῖς μαθηταῖς αὐτοῦ ὅτι ἠγέρθη ἀπὸ τῶν νεκρῶν, καὶ ἰδοὺ, προάγει ὑμᾶς εἰς τὴν Γαλιλαίαν, ἐκεῖ αὐτὸν ὄψεσθε. Ἰδοὺ, εἶπον ὑμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 8, 'Καὶ ἀπελθοῦσαι ταχὺ ἀπὸ τοῦ μνημείου, μετὰ φόβου καὶ χαρᾶς μεγάλης, ἔδραμον ἀπαγγεῖλαι τοῖς μαθηταῖς αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 9, 'Καὶ ἰδοὺ,  ̊Ἰησοῦς ὑπήντησεν αὐταῖς λέγων, “Χαίρετε!” Αἱ δὲ προσελθοῦσαι, ἐκράτησαν αὐτοῦ τοὺς πόδας καὶ προσεκύνησαν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 10, 'Τότε λέγει αὐταῖς ὁ  ̊Ἰησοῦς, “Μὴ φοβεῖσθε. Ὑπάγετε ἀπαγγείλατε τοῖς ἀδελφοῖς μου ἵνα ἀπέλθωσιν εἰς τὴν Γαλιλαίαν, καὶ ἐκεῖ με ὄψονται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 11, '¶Πορευομένων δὲ αὐτῶν, ἰδού, τινες τῆς κουστωδίας ἐλθόντες εἰς τὴν πόλιν, ἀπήγγειλαν τοῖς ἀρχιερεῦσιν ἅπαντα τὰ γενόμενα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 12, 'Καὶ συναχθέντες μετὰ τῶν πρεσβυτέρων, συμβούλιόν τε λαβόντες, ἀργύρια ἱκανὰ ἔδωκαν τοῖς στρατιώταις');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 13, 'λέγοντες, “Εἴπατε ὅτι, ‘Οἱ μαθηταὶ αὐτοῦ νυκτὸς ἐλθόντες ἔκλεψαν αὐτὸν, ἡμῶν κοιμωμένων.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 14, 'Καὶ ἐὰν ἀκουσθῇ τοῦτο ἐπὶ τοῦ ἡγεμόνος, ἡμεῖς πείσομεν καὶ ὑμᾶς ἀμερίμνους ποιήσομεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 15, 'Οἱ δὲ λαβόντες ἀργύρια ἐποίησαν ὡς ἐδιδάχθησαν. Καὶ διεφημίσθη ὁ λόγος οὗτος παρὰ Ἰουδαίοις μέχρι τῆς σήμερον');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 16, '¶Οἱ δὲ ἕνδεκα μαθηταὶ ἐπορεύθησαν εἰς τὴν Γαλιλαίαν, εἰς τὸ ὄρος οὗ ἐτάξατο αὐτοῖς ὁ  ̊Ἰησοῦς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 17, 'Καὶ ἰδόντες αὐτὸν προσεκύνησαν, οἱ δὲ ἐδίστασαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 18, 'Καὶ προσελθὼν, ὁ  ̊Ἰησοῦς ἐλάλησεν αὐτοῖς λέγων, “Ἐδόθη μοι πᾶσα ἐξουσία ἐν οὐρανῷ καὶ ἐπὶ γῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 19, 'Πορευθέντες οὖν, μαθητεύσατε πάντα τὰ ἔθνη, βαπτίζοντες αὐτοὺς εἰς τὸ ὄνομα τοῦ Πατρὸς, καὶ τοῦ Υἱοῦ, καὶ τοῦ Ἁγίου  ̊Πνεύματος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 20, 'διδάσκοντες αὐτοὺς τηρεῖν πάντα ὅσα ἐνετειλάμην ὑμῖν. Καὶ ἰδοὺ, ἐγὼ μεθʼ ὑμῶν εἰμι πάσας τὰς ἡμέρας, ἕως τῆς συντελείας τοῦ αἰῶνος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, '¶Ἀρχὴ τοῦ εὐαγγελίου  ̊Ἰησοῦ  ̊Χριστοῦ, Υἱοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, '¶Καθὼς γέγραπται ἐν τῷ Ἠσαΐᾳ τῷ προφήτῃ: “Ἰδοὺ, ἀποστέλλω τὸν ἄγγελόν μου πρὸ προσώπου σου, ὃς κατασκευάσει τὴν ὁδόν σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, '“Φωνὴ βοῶντος ἐν τῇ ἐρήμῳ: ‘Ἑτοιμάσατε τὴν ὁδὸν  ̊Κυρίου, εὐθείας ποιεῖτε τὰς τρίβους αὐτοῦ.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Ἐγένετο Ἰωάννης, ὁ βαπτίζων ἐν τῇ ἐρήμῳ, καὶ κηρύσσων βάπτισμα μετανοίας εἰς ἄφεσιν ἁμαρτιῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Καὶ ἐξεπορεύετο πρὸς αὐτὸν πᾶσα ἡ Ἰουδαία χώρα καὶ οἱ Ἱεροσολυμῖται πάντες, καὶ ἐβαπτίζοντο ὑπʼ αὐτοῦ ἐν τῷ Ἰορδάνῃ ποταμῷ, ἐξομολογούμενοι τὰς ἁμαρτίας αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Καὶ ἦν ὁ Ἰωάννης ἐνδεδυμένος τρίχας καμήλου, καὶ ζώνην δερματίνην περὶ τὴν ὀσφὺν αὐτοῦ, καὶ ἔσθων ἀκρίδας καὶ μέλι ἄγριον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Καὶ ἐκήρυσσεν λέγων, “Ἔρχεται ὁ ἰσχυρότερός μου ὀπίσω μου, οὗ οὐκ εἰμὶ ἱκανὸς, κύψας λῦσαι τὸν ἱμάντα τῶν ὑποδημάτων αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'Ἐγὼ ἐβάπτισα ὑμᾶς ὕδατι, αὐτὸς δὲ βαπτίσει ὑμᾶς  ̊Πνεύματι Ἁγίῳ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, '¶Καὶ ἐγένετο ἐν ἐκείναις ταῖς ἡμέραις, ἦλθεν  ̊Ἰησοῦς ἀπὸ Ναζαρὲτ τῆς Γαλιλαίας, καὶ ἐβαπτίσθη εἰς τὸν Ἰορδάνην ὑπὸ Ἰωάννου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'Καὶ εὐθὺς ἀναβαίνων ἐκ τοῦ ὕδατος, εἶδεν σχιζομένους τοὺς οὐρανοὺς, καὶ τὸ  ̊Πνεῦμα ὡς περιστερὰν καταβαῖνον ἐπʼ αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Καὶ φωνὴ ἐγένετο ἐκ τῶν οὐρανῶν: “Σὺ εἶ ὁ Υἱός μου ὁ ἀγαπητός, ἐν σοὶ εὐδόκησα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, '¶Καὶ εὐθὺς τὸ  ̊Πνεῦμα αὐτὸν ἐκβάλλει εἰς τὴν ἔρημον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Καὶ ἦν ἐν τῇ ἐρήμῳ τεσσεράκοντα ἡμέρας, πειραζόμενος ὑπὸ τοῦ Σατανᾶ, καὶ ἦν μετὰ τῶν θηρίων, καὶ οἱ ἄγγελοι διηκόνουν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, '¶Καὶ ¶Μετὰ τὸ παραδοθῆναι τὸν Ἰωάννην, ἦλθεν ὁ  ̊Ἰησοῦς εἰς τὴν Γαλιλαίαν, κηρύσσων τὸ εὐαγγέλιον τοῦ  ̊Θεοῦ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'καὶ λέγων, ὅτι “Πεπλήρωται ὁ καιρὸς καὶ ἤγγικεν ἡ Βασιλεία τοῦ  ̊Θεοῦ· μετανοεῖτε καὶ πιστεύετε ἐν τῷ εὐαγγελίῳ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, '¶Καὶ παράγων παρὰ τὴν θάλασσαν τῆς Γαλιλαίας, εἶδεν Σίμωνα καὶ Ἀνδρέαν, τὸν ἀδελφὸν Σίμωνος, ἀμφιβάλλοντας ἐν τῇ θαλάσσῃ, ἦσαν γὰρ ἁλεεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Καὶ εἶπεν αὐτοῖς ὁ  ̊Ἰησοῦς, “Δεῦτε ὀπίσω μου, καὶ ποιήσω ὑμᾶς γενέσθαι ἁλεεῖς ἀνθρώπων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Καὶ εὐθέως ἀφέντες τὰ δίκτυα, ἠκολούθησαν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Καὶ προβὰς ὀλίγον, εἶδεν Ἰάκωβον τὸν τοῦ Ζεβεδαίου, καὶ Ἰωάννην τὸν ἀδελφὸν αὐτοῦ, καὶ αὐτοὺς ἐν τῷ πλοίῳ καταρτίζοντας τὰ δίκτυα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Καὶ εὐθὺς ἐκάλεσεν αὐτούς. Καὶ ἀφέντες τὸν πατέρα αὐτῶν Ζεβεδαῖον ἐν τῷ πλοίῳ μετὰ τῶν μισθωτῶν, ἀπῆλθον ὀπίσω αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, '¶Καὶ εἰσπορεύονται εἰς Καφαρναούμ. Καὶ εὐθέως τοῖς Σάββασιν, εἰσελθὼν εἰς τὴν συναγωγὴν, ἐδίδασκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Καὶ ἐξεπλήσσοντο ἐπὶ τῇ διδαχῇ αὐτοῦ, ἦν γὰρ διδάσκων αὐτοὺς ὡς ἐξουσίαν ἔχων, καὶ οὐχ ὡς οἱ γραμματεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Καὶ εὐθὺς ἦν ἐν τῇ συναγωγῇ αὐτῶν ἄνθρωπος ἐν πνεύματι ἀκαθάρτῳ, καὶ ἀνέκραξεν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'λέγων, “Τί ἡμῖν καὶ σοί,  ̊Ἰησοῦ Ναζαρηνέ; Ἦλθες ἀπολέσαι ἡμᾶς; Οἶδά σε τίς εἶ, ὁ Ἅγιος τοῦ  ̊Θεοῦ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Καὶ ἐπετίμησεν αὐτῷ ὁ  ̊Ἰησοῦς λέγων, “Φιμώθητι καὶ ἔξελθε ἐξ αὐτοῦ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Καὶ σπαράξαν αὐτὸν, τὸ πνεῦμα τὸ ἀκάθαρτον, καὶ φωνῆσαν φωνῇ μεγάλῃ, ἐξῆλθεν ἐξ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Καὶ ἐθαμβήθησαν ἅπαντες, ὥστε συζητεῖν αὐτοὺς λέγοντας, “Τί ἐστιν τοῦτο; διδαχὴ καινή, κατʼ ἐξουσίαν καὶ τοῖς πνεύμασιν τοῖς ἀκαθάρτοις ἐπιτάσσει, καὶ ὑπακούουσιν αὐτῷ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 28, 'Καὶ ἐξῆλθεν ἡ ἀκοὴ αὐτοῦ εὐθὺς πανταχοῦ εἰς ὅλην τὴν περίχωρον τῆς Γαλιλαίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 29, '¶Καὶ εὐθὺς ἐκ τῆς συναγωγῆς ἐξελθὼν, ἦλθεν εἰς τὴν οἰκίαν Σίμωνος καὶ Ἀνδρέου, μετὰ Ἰακώβου καὶ Ἰωάννου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 30, 'Ἡ δὲ πενθερὰ Σίμωνος κατέκειτο πυρέσσουσα, καὶ εὐθὺς λέγουσιν αὐτῷ περὶ αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 31, 'Καὶ προσελθὼν, ἤγειρεν αὐτὴν, κρατήσας τῆς χειρός. Καὶ ἀφῆκεν αὐτὴν ὁ πυρετός, καὶ διηκόνει αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 32, '¶Ὀψίας δὲ γενομένης, ὅτε ἔδυ ὁ ἥλιος, ἔφερον πρὸς αὐτὸν πάντας τοὺς κακῶς ἔχοντας καὶ τοὺς δαιμονιζομένους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 33, 'Καὶ ἦν ὅλη ἡ πόλις ἐπισυνηγμένη πρὸς τὴν θύραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 34, 'Καὶ ἐθεράπευσεν πολλοὺς κακῶς ἔχοντας ποικίλαις νόσοις, καὶ δαιμόνια πολλὰ ἐξέβαλεν, καὶ οὐκ ἤφιεν τὰ δαιμόνια, λαλεῖν ὅτι ᾔδεισαν αὐτόν.  ̊Χριστὸν εἶναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 35, '¶Καὶ πρωῒ ἔννυχα λίαν, ἀναστὰς ἐξῆλθεν καὶ ἀπῆλθεν εἰς ἔρημον τόπον, κἀκεῖ προσηύχετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 36, 'Καὶ κατεδίωξεν αὐτὸν Σίμων καὶ οἱ μετʼ αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 37, 'καὶ εὗρον αὐτὸν καὶ λέγουσιν αὐτῷ, ὅτι “Πάντες ζητοῦσίν σε!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 38, 'Καὶ λέγει αὐτοῖς, “Ἄγωμεν ἀλλαχοῦ εἰς τὰς ἐχομένας κωμοπόλεις, ἵνα καὶ ἐκεῖ κηρύξω, εἰς τοῦτο γὰρ ἐξῆλθον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 39, 'Καὶ ἦλθεν κηρύσσων, εἰς τὰς συναγωγὰς αὐτῶν εἰς ὅλην τὴν Γαλιλαίαν, καὶ τὰ δαιμόνια ἐκβάλλων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 40, '¶Καὶ ἔρχεται πρὸς αὐτὸν λεπρὸς, παρακαλῶν αὐτὸν λέγων αὐτῷ, ὅτι “Ἐὰν θέλῃς, δύνασαί με καθαρίσαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 41, 'Καὶ σπλαγχνισθεὶς, ἐκτείνας τὴν χεῖρα αὐτοῦ, ἥψατο καὶ λέγει αὐτῷ, “Θέλω, καθαρίσθητι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 42, 'Καὶ εὐθὺς ἀπῆλθεν ἀπʼ αὐτοῦ ἡ λέπρα, καὶ ἐκαθαρίσθη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 43, 'Καὶ ἐμβριμησάμενος αὐτῷ, εὐθὺς ἐξέβαλεν αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 44, 'καὶ λέγει αὐτῷ, “Ὅρα, μηδενὶ μηδὲν εἴπῃς, ἀλλὰ ὕπαγε, σεαυτὸν δεῖξον τῷ ἱερεῖ, καὶ προσένεγκε περὶ τοῦ καθαρισμοῦ σου ἃ προσέταξεν Μωϋσῆς, εἰς μαρτύριον αὐτοῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 45, 'Ὁ δὲ ἐξελθὼν ἤρξατο κηρύσσειν πολλὰ καὶ διαφημίζειν τὸν λόγον, ὥστε μηκέτι αὐτὸν δύνασθαι φανερῶς εἰς πόλιν εἰσελθεῖν, ἀλλʼ ἔξω ἐπʼ ἐρήμοις τόποις ἦν, καὶ ἤρχοντο πρὸς αὐτὸν πάντοθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, '¶Καὶ εἰσελθὼν πάλιν εἰς Καφαρναοὺμ διʼ ἡμερῶν, ἠκούσθη ὅτι ἐν οἴκῳ ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Καὶ συνήχθησαν πολλοὶ, ὥστε μηκέτι χωρεῖν, μηδὲ τὰ πρὸς τὴν θύραν, καὶ ἐλάλει αὐτοῖς τὸν λόγον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'Καὶ ἔρχονται φέροντες πρὸς αὐτὸν παραλυτικὸν, αἰρόμενον ὑπὸ τεσσάρων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'Καὶ μὴ δυνάμενοι προσενέγκαι αὐτῷ διὰ τὸν ὄχλον, ἀπεστέγασαν τὴν στέγην ὅπου ἦν, καὶ ἐξορύξαντες, χαλῶσι τὸν κράβαττον ὅπου ὁ παραλυτικὸς κατέκειτο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Καὶ ἰδὼν ὁ  ̊Ἰησοῦς τὴν πίστιν αὐτῶν, λέγει τῷ παραλυτικῷ, “Τέκνον, ἀφέωνται σου αἱ ἁμαρτίαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Ἦσαν δέ τινες τῶν γραμματέων ἐκεῖ, καθήμενοι καὶ διαλογιζόμενοι ἐν ταῖς καρδίαις αὐτῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, '“Τί οὗτος οὕτως λαλεῖ; Βλασφημεῖ! Τίς δύναται ἀφιέναι ἁμαρτίας, εἰ μὴ εἷς ὁ  ̊Θεός;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Καὶ εὐθὺς ἐπιγνοὺς ὁ  ̊Ἰησοῦς τῷ πνεύματι αὐτοῦ ὅτι οὕτως διαλογίζονται ἐν ἑαυτοῖς, λέγει αὐτοῖς, “Τί ταῦτα διαλογίζεσθε ἐν ταῖς καρδίαις ὑμῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Τί ἐστιν εὐκοπώτερον, εἰπεῖν τῷ παραλυτικῷ, ἀφέωνταί σοι αἱ ἁμαρτίαι’, ἢ εἰπεῖν, ‘Ἔγειρε καὶ ἆρον τὸν κράβαττόν σου καὶ περιπάτει’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Ἵνα δὲ εἰδῆτε ὅτι ἐξουσίαν ἔχει ὁ Υἱὸς τοῦ Ἀνθρώπου ἐπὶ τῆς γῆς ἀφιέναι ἁμαρτίας”, (λέγει τῷ παραλυτικῷ),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, '“Σοὶ λέγω, ἔγειρε ἆρον τὸν κράβαττόν σου, καὶ ὕπαγε εἰς τὸν οἶκόν σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Καὶ ἠγέρθη, καὶ εὐθὺς ἄρας τὸν κράβαττον, ἐξῆλθεν ἔμπροσθεν πάντων, ὥστε ἐξίστασθαι πάντας, καὶ δοξάζειν τὸν  ̊Θεὸν λέγοντας, ὅτι “Οὕτως οὐδέποτε εἴδομεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, '¶Καὶ ἐξῆλθεν πάλιν παρὰ τὴν θάλασσαν, καὶ πᾶς ὁ ὄχλος ἤρχετο πρὸς αὐτόν, καὶ ἐδίδασκεν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Καὶ παράγων εἶδεν Λευὶν τὸν τοῦ Ἁλφαίου, καθήμενον ἐπὶ τὸ τελώνιον, καὶ λέγει αὐτῷ, “Ἀκολούθει μοι.” Καὶ ἀναστὰς, ἠκολούθησεν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, '¶Καὶ γίνεται κατακεῖσθαι αὐτὸν ἐν τῇ οἰκίᾳ αὐτοῦ, καὶ πολλοὶ τελῶναι καὶ ἁμαρτωλοὶ συνανέκειντο τῷ  ̊Ἰησοῦ καὶ τοῖς μαθηταῖς αὐτοῦ, ἦσαν γὰρ πολλοὶ, καὶ ἠκολούθουν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'Καὶ οἱ γραμματεῖς τῶν Φαρισαίων, ἰδόντες ὅτι ἐσθίει μετὰ τῶν ἁμαρτωλῶν καὶ τῶν τελωνῶν, ἔλεγον τοῖς μαθηταῖς αὐτοῦ, ὅτι “Μετὰ τῶν τελωνῶν καὶ ἁμαρτωλῶν ἐσθίει;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Καὶ ἀκούσας, ὁ  ̊Ἰησοῦς λέγει αὐτοῖς, “Οὐ χρείαν ἔχουσιν οἱ ἰσχύοντες ἰατροῦ, ἀλλʼ οἱ κακῶς ἔχοντες. Οὐκ ἦλθον καλέσαι δικαίους, ἀλλὰ ἁμαρτωλούς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, '¶Καὶ ἦσαν οἱ μαθηταὶ Ἰωάννου καὶ οἱ Φαρισαῖοι νηστεύοντες. Καὶ ἔρχονται καὶ λέγουσιν αὐτῷ, “Διὰ τί οἱ μαθηταὶ Ἰωάννου καὶ οἱ μαθηταὶ τῶν Φαρισαίων νηστεύουσιν, οἱ δὲ σοὶ μαθηταὶ οὐ νηστεύουσιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Καὶ εἶπεν αὐτοῖς ὁ  ̊Ἰησοῦς, “Μὴ δύνανται οἱ υἱοὶ τοῦ νυμφῶνος ἐν ᾧ ὁ νυμφίος μετʼ αὐτῶν ἐστιν νηστεύειν; Ὅσον χρόνον ἔχουσιν τὸν νυμφίον μετʼ αὐτῶν, οὐ δύνανται νηστεύειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Ἐλεύσονται δὲ ἡμέραι ὅταν ἀπαρθῇ ἀπʼ αὐτῶν ὁ νυμφίος, καὶ τότε νηστεύσουσιν ἐν ἐκείνῃ τῇ ἡμέρᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, '¶Οὐδεὶς ἐπίβλημα ῥάκους ἀγνάφου ἐπιράπτει ἐπὶ ἱμάτιον παλαιόν· εἰ δὲ μή αἴρει ἀπʼ αὐτοῦ τὸ πλήρωμα τὸ καινὸν τοῦ παλαιοῦ, καὶ χεῖρον σχίσμα γίνεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Καὶ οὐδεὶς βάλλει οἶνον νέον εἰς ἀσκοὺς παλαιούς· εἰ δὲ μή ῥήξει ὁ οἶνος τοὺς ἀσκούς, καὶ ὁ οἶνος ἀπόλλυται καὶ οἱ ἀσκοί. Ἀλλὰ οἶνον νέον εἰς ἀσκοὺς καινοὺς βλητέον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, '¶Καὶ ἐγένετο, αὐτὸν ἐν τοῖς Σάββασιν παραπορεύεσθαι διὰ τῶν σπορίμων, καὶ οἱ μαθηταὶ αὐτοῦ ἤρξαντο ὁδὸν ποιεῖν, τίλλοντες τοὺς στάχυας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Καὶ οἱ Φαρισαῖοι ἔλεγον αὐτῷ, “Ἴδε, τί ποιοῦσιν τοῖς Σάββασιν ὃ οὐκ ἔξεστιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Καὶ λέγει αὐτοῖς, “Οὐδέποτε ἀνέγνωτε τί ἐποίησεν Δαυὶδ, ὅτε χρείαν ἔσχεν καὶ ἐπείνασεν, αὐτὸς καὶ οἱ μετʼ αὐτοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Πῶς εἰσῆλθεν εἰς τὸν οἶκον τοῦ  ̊Θεοῦ ἐπὶ Ἀβιαθὰρ ἀρχιερέως, καὶ τοὺς ἄρτους τῆς Προθέσεως ἔφαγεν, οὓς οὐκ ἔξεστιν φαγεῖν, εἰ μὴ τοὺς ἱερεῖς, καὶ ἔδωκεν καὶ τοῖς σὺν αὐτῷ οὖσιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 27, 'Καὶ ἔλεγεν αὐτοῖς, “Τὸ Σάββατον διὰ τὸν ἄνθρωπον ἐγένετο, καὶ οὐχ ὁ ἄνθρωπος διὰ τὸ Σάββατον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 28, 'Ὥστε  ̊Κύριός ἐστιν ὁ Υἱὸς τοῦ Ἀνθρώπου καὶ τοῦ Σαββάτου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, '¶Καὶ εἰσῆλθεν πάλιν εἰς συναγωγήν, καὶ ἦν ἐκεῖ ἄνθρωπος, ἐξηραμμένην ἔχων τὴν χεῖρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Καὶ παρετήρουν αὐτὸν, εἰ τοῖς Σάββασιν θεραπεύσει αὐτόν, ἵνα κατηγορήσωσιν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Καὶ λέγει τῷ ἀνθρώπῳ τῷ τὴν χεῖρα ἔχοντι ξηράν, “Ἔγειρε εἰς τὸ μέσον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Καὶ λέγει αὐτοῖς, “Ἔξεστιν τοῖς Σάββασιν ἀγαθοποιῆσαι ἢ κακοποιῆσαι, ψυχὴν σῶσαι ἢ ἀποκτεῖναι;” Οἱ δὲ ἐσιώπων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Καὶ περιβλεψάμενος αὐτοὺς μετʼ ὀργῆς, συλλυπούμενος ἐπὶ τῇ πωρώσει τῆς καρδίας αὐτῶν, λέγει τῷ ἀνθρώπῳ, “Ἔκτεινον τὴν χεῖρα σου.” Καὶ ἐξέτεινεν, καὶ ἀπεκατεστάθη ἡ χεὶρ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Καὶ ἐξελθόντες, οἱ Φαρισαῖοι εὐθὺς μετὰ τῶν Ἡρῳδιανῶν συμβούλιον ἐποίησαν κατʼ αὐτοῦ, ὅπως αὐτὸν ἀπολέσωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, '¶Καὶ ὁ  ̊Ἰησοῦς μετὰ τῶν μαθητῶν αὐτοῦ, ἀνεχώρησεν πρὸς τὴν θάλασσαν· καὶ πολὺ πλῆθος ἀπὸ τῆς Γαλιλαίας ἠκολούθησεν, καὶ ἀπὸ τῆς Ἰουδαίας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'καὶ ἀπὸ Ἱεροσολύμων, καὶ ἀπὸ τῆς Ἰδουμαίας, καὶ πέραν τοῦ Ἰορδάνου, καὶ περὶ Τύρον καὶ Σιδῶνα, πλῆθος πολύ ἀκούοντες ὅσα ἐποίει, ἦλθον πρὸς αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Καὶ εἶπεν τοῖς μαθηταῖς αὐτοῦ ἵνα πλοιάριον προσκαρτερῇ αὐτῷ διὰ τὸν ὄχλον, ἵνα μὴ θλίβωσιν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Πολλοὺς γὰρ ἐθεράπευσεν, ὥστε ἐπιπίπτειν αὐτῷ, ἵνα αὐτοῦ ἅψωνται ὅσοι εἶχον μάστιγας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Καὶ τὰ πνεύματα τὰ ἀκάθαρτα, ὅταν αὐτὸν ἐθεώρουν, προσέπιπτον αὐτῷ καὶ ἔκραζον λέγοντα, ὅτι “Σὺ εἶ ὁ Υἱὸς τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Καὶ πολλὰ ἐπετίμα αὐτοῖς ἵνα μὴ αὐτὸν φανερὸν ποιήσωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, '¶Καὶ ἀναβαίνει εἰς τὸ ὄρος, καὶ προσκαλεῖται οὓς ἤθελεν αὐτός, καὶ ἀπῆλθον πρὸς αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Καὶ ἐποίησεν δώδεκα, οὓς καὶ ἀποστόλους ὠνόμασεν, ἵνα ὦσιν μετʼ αὐτοῦ, καὶ ἵνα ἀποστέλλῃ αὐτοὺς κηρύσσειν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'καὶ ἔχειν ἐξουσίαν ἐκβάλλειν τὰ δαιμόνια.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Καὶ ἐποίησεν τοὺς δώδεκα: καὶ ἐπέθηκεν ὄνομα τῷ Σίμωνι, Πέτρον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'καὶ Ἰάκωβον τὸν τοῦ Ζεβεδαίου, καὶ Ἰωάννην τὸν ἀδελφὸν τοῦ Ἰακώβου, καὶ ἐπέθηκεν αὐτοῖς ὀνόματα Βοανηργές, ὅ ἐστιν “Υἱοὶ βροντῆς”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'καὶ Ἀνδρέαν, καὶ Φίλιππον, καὶ Βαρθολομαῖον, καὶ Ματθαῖον, καὶ Θωμᾶν, καὶ Ἰάκωβον τὸν τοῦ Ἁλφαίου, καὶ Θαδδαῖον, καὶ Σίμωνα τὸν Καναναῖον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 19, 'καὶ Ἰούδαν Ἰσκαριώθ, ὃς καὶ παρέδωκεν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 20, '¶Καὶ ἔρχεται εἰς οἶκον, καὶ συνέρχεται πάλιν ὁ ὄχλος, ὥστε μὴ δύνασθαι αὐτοὺς μηδὲ ἄρτον φαγεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 21, 'Καὶ ἀκούσαντες, οἱ παρʼ αὐτοῦ ἐξῆλθον κρατῆσαι αὐτόν, ἔλεγον γὰρ, ὅτι “Ἐξέστη.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 22, 'Καὶ οἱ γραμματεῖς, οἱ ἀπὸ Ἱεροσολύμων καταβάντες ἔλεγον, ὅτι “Βεελζεβοὺλ ἔχει”, καὶ, ὅτι “Ἐν τῷ ἄρχοντι τῶν δαιμονίων, ἐκβάλλει τὰ δαιμόνια.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 23, 'Καὶ προσκαλεσάμενος αὐτοὺς, ἐν παραβολαῖς ἔλεγεν αὐτοῖς, “Πῶς δύναται Σατανᾶς Σατανᾶν ἐκβάλλειν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 24, 'Καὶ ἐὰν βασιλεία ἐφʼ ἑαυτὴν μερισθῇ, οὐ δύναται σταθῆναι ἡ βασιλεία ἐκείνη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 25, 'Καὶ ἐὰν οἰκία ἐφʼ ἑαυτὴν μερισθῇ, οὐ δυνήσεται ἡ οἰκία ἐκείνη σταθῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 26, 'Καὶ εἰ ὁ Σατανᾶς ἀνέστη ἐφʼ ἑαυτὸν καὶ ἐμερίσθη, οὐ δύναται στῆναι, ἀλλὰ τέλος ἔχει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 27, 'Ἀλλʼ οὐ δύναται οὐδεὶς εἰς τὴν οἰκίαν τοῦ ἰσχυροῦ εἰσελθὼν τὰ σκεύη αὐτοῦ διαρπάσαι, ἐὰν μὴ πρῶτον τὸν ἰσχυρὸν δήσῃ, καὶ τότε τὴν οἰκίαν αὐτοῦ διαρπάσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 28, '¶Ἀμὴν, λέγω ὑμῖν ὅτι πάντα ἀφεθήσεται τοῖς υἱοῖς τῶν ἀνθρώπων τὰ ἁμαρτήματα καὶ αἱ βλασφημίαι, ὅσα ἐὰν βλασφημήσωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 29, 'Ὃς δʼ ἂν βλασφημήσῃ εἰς τὸ  ̊Πνεῦμα τὸ Ἅγιον, οὐκ ἔχει ἄφεσιν εἰς τὸν αἰῶνα, ἀλλὰ ἔνοχός ἐστιν αἰωνίου ἁμαρτήματος”–');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 30, 'ὅτι ἔλεγον, “Πνεῦμα ἀκάθαρτον ἔχει.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 31, '¶Καὶ ἔρχονται ἡ μήτηρ αὐτοῦ καὶ οἱ ἀδελφοὶ αὐτοῦ, καὶ ἔξω στήκοντες, ἀπέστειλαν πρὸς αὐτὸν καλοῦντες αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 32, 'Καὶ ἐκάθητο περὶ αὐτὸν ὄχλος, καὶ λέγουσιν αὐτῷ, “Ἰδοὺ, ἡ μήτηρ σου καὶ οἱ ἀδελφοί σου, ἔξω ζητοῦσίν σε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 33, 'Καὶ ἀποκριθεὶς αὐτοῖς λέγει, “Τίς ἐστιν ἡ μήτηρ μου, καὶ οἱ ἀδελφοί μου;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 34, 'Καὶ περιβλεψάμενος τοὺς περὶ αὐτὸν, κύκλῳ καθημένους λέγει, “Ἴδε, ἡ μήτηρ μου καὶ οἱ ἀδελφοί μου!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 35, 'Ὃς γὰρ ἂν ποιήσῃ τὸ θέλημα τοῦ  ̊Θεοῦ, οὗτος ἀδελφός μου καὶ ἀδελφὴ καὶ μήτηρ ἐστίν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, '¶Καὶ πάλιν ἤρξατο διδάσκειν παρὰ τὴν θάλασσαν. Καὶ συνάγεται πρὸς αὐτὸν ὄχλος πλεῖστος, ὥστε αὐτὸν εἰς τὸ πλοῖον ἐμβάντα, καθῆσθαι ἐν τῇ θαλάσσῃ, καὶ πᾶς ὁ ὄχλος πρὸς τὴν θάλασσαν ἐπὶ τῆς γῆς ἦσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Καὶ ἐδίδασκεν αὐτοὺς ἐν παραβολαῖς πολλά, καὶ ἔλεγεν αὐτοῖς ἐν τῇ διδαχῇ αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, '“Ἀκούετε! Ἰδοὺ, ἐξῆλθεν ὁ σπείρων σπεῖραι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Καὶ ἐγένετο ἐν τῷ σπείρειν, ὃ μὲν ἔπεσεν παρὰ τὴν ὁδόν, καὶ ἦλθεν τὰ πετεινὰ καὶ κατέφαγεν αὐτό.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Καὶ ἄλλο ἔπεσεν ἐπὶ τὸ πετρῶδες, καὶ ὅπου οὐκ εἶχεν γῆν πολλήν, καὶ εὐθὺς ἐξανέτειλεν διὰ τὸ μὴ ἔχειν βάθος γῆς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'καὶ ὅτε ἀνέτειλεν ὁ ἥλιος ἐκαυματίσθη, καὶ διὰ τὸ μὴ ἔχειν ῥίζαν ἐξηράνθη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Καὶ ἄλλο ἔπεσεν εἰς τὰς ἀκάνθας, καὶ ἀνέβησαν αἱ ἄκανθαι καὶ συνέπνιξαν αὐτό, καὶ καρπὸν οὐκ ἔδωκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Καὶ ἄλλα ἔπεσεν εἰς τὴν γῆν τὴν καλήν, καὶ ἐδίδου καρπὸν, ἀναβαίνοντα καὶ αὐξανόμενα, καὶ ἔφερεν εἰς τριάκοντα, καὶ ἓν ἑξήκοντα, καὶ ἓν ἑκατόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Καὶ ἔλεγεν, “Ὃς ἔχει ὦτα ἀκούειν, ἀκουέτω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, '¶Καὶ ὅτε ἐγένετο κατὰ μόνας, ἠρώτων αὐτὸν οἱ περὶ αὐτὸν σὺν τοῖς δώδεκα τὰς παραβολάς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Καὶ ἔλεγεν αὐτοῖς, “Ὑμῖν τὸ μυστήριον δέδοται τῆς Βασιλείας τοῦ  ̊Θεοῦ· ἐκείνοις δὲ τοῖς ἔξω, ἐν παραβολαῖς τὰ πάντα γίνεται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'ἵνα ‘βλέποντες, βλέπωσιν καὶ μὴ ἴδωσιν, καὶ ἀκούοντες, ἀκούωσι καὶ μὴ συνιῶσιν, μήποτε ἐπιστρέψωσιν καὶ ἀφεθῇ αὐτοῖς.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, '¶Καὶ λέγει αὐτοῖς, “Οὐκ οἴδατε τὴν παραβολὴν ταύτην, καὶ πῶς πάσας τὰς παραβολὰς γνώσεσθε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Ὁ σπείρων τὸν λόγον σπείρει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Οὗτοι δέ εἰσιν οἱ παρὰ τὴν ὁδὸν, ὅπου σπείρεται ὁ λόγος, καὶ ὅταν ἀκούσωσιν, εὐθὺς ἔρχεται ὁ Σατανᾶς, καὶ αἴρει τὸν λόγον τὸν ἐσπαρμένον εἰς αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Καὶ οὗτοί εἰσιν ὁμοίως οἱ ἐπὶ τὰ πετρώδη σπειρόμενοι, οἳ ὅταν ἀκούσωσιν τὸν λόγον, εὐθὺς μετὰ χαρᾶς λαμβάνουσιν αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'καὶ οὐκ ἔχουσιν ῥίζαν ἐν ἑαυτοῖς, ἀλλὰ πρόσκαιροί εἰσιν, εἶτα γενομένης θλίψεως ἢ διωγμοῦ διὰ τὸν λόγον, εὐθὺς σκανδαλίζονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 18, 'Καὶ ἄλλοι εἰσὶν οἱ εἰς τὰς ἀκάνθας σπειρόμενοι, οὗτοί εἰσιν οἱ τὸν λόγον ἀκούσαντες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 19, 'καὶ αἱ μέριμναι τοῦ αἰῶνος, καὶ ἡ ἀπάτη τοῦ πλούτου, καὶ αἱ περὶ τὰ λοιπὰ ἐπιθυμίαι εἰσπορευόμεναι, συμπνίγουσιν τὸν λόγον, καὶ ἄκαρπος γίνεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 20, 'Καὶ ἐκεῖνοί εἰσιν οἱ ἐπὶ τὴν γῆν τὴν καλὴν σπαρέντες, οἵτινες ἀκούουσιν τὸν λόγον καὶ παραδέχονται καὶ καρποφοροῦσιν, ἓν τριάκοντα, καὶ ἓν ἑξήκοντα, καὶ ἓν ἑκατόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 21, '¶Καὶ ἔλεγεν αὐτοῖς, “Μήτι ἔρχεται ὁ λύχνος, ἵνα ὑπὸ τὸν μόδιον τεθῇ, ἢ ὑπὸ τὴν κλίνην; Οὐχ ἵνα ἐπὶ τὴν λυχνίαν τεθῇ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 22, 'Οὐ γάρ ἐστιν κρυπτὸν, ἐὰν μὴ ἵνα φανερωθῇ, οὐδὲ ἐγένετο ἀπόκρυφον, ἀλλʼ ἵνα ἔλθῃ εἰς φανερόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 23, 'Εἴ τις ἔχει ὦτα ἀκούειν, ἀκουέτω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 24, 'Καὶ ἔλεγεν αὐτοῖς, “Βλέπετε τί ἀκούετε. Ἐν ᾧ μέτρῳ μετρεῖτε μετρηθήσεται ὑμῖν, καὶ προστεθήσεται ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 25, 'Ὃς γὰρ ἔχει, δοθήσεται αὐτῷ· καὶ ὃς οὐκ ἔχει, καὶ ὃ ἔχει ἀρθήσεται ἀπʼ αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 26, '¶Καὶ ἔλεγεν, “Οὕτως ἐστὶν ἡ Βασιλεία τοῦ  ̊Θεοῦ: ὡς ἄνθρωπος βάλῃ τὸν σπόρον ἐπὶ τῆς γῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 27, 'καὶ καθεύδῃ καὶ ἐγείρηται νύκτα καὶ ἡμέραν, καὶ ὁ σπόρος βλαστᾷ καὶ μηκύνηται– ὡς οὐκ οἶδεν αὐτός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 28, 'Αὐτομάτη ἡ γῆ καρποφορεῖ: πρῶτον χόρτον, εἶτεν στάχυν, εἶτα πλήρης σῖτον ἐν τῷ στάχυϊ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 29, 'Ὅταν δὲ παραδοῖ ὁ καρπός, εὐθὺς ἀποστέλλει τὸ δρέπανον, ὅτι παρέστηκεν ὁ θερισμός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 30, '¶Καὶ ἔλεγεν, “Πῶς ὁμοιώσωμεν τὴν Βασιλείαν τοῦ  ̊Θεοῦ, ἢ ἐν τίνι αὐτὴν παραβολῇ θῶμεν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 31, 'Ὡς κόκκῳ σινάπεως, ὃς ὅταν σπαρῇ ἐπὶ τῆς γῆς, μικρότερον ὂν πάντων τῶν σπερμάτων τῶν ἐπὶ τῆς γῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 32, 'καὶ ὅταν σπαρῇ, ἀναβαίνει καὶ γίνεται μεῖζον πάντων τῶν λαχάνων, καὶ ποιεῖ κλάδους μεγάλους, ὥστε ‘δύνασθαι ὑπὸ τὴν σκιὰν αὐτοῦ τὰ πετεινὰ τοῦ οὐρανοῦ κατασκηνοῦν’.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 33, '¶Καὶ τοιαύταις παραβολαῖς πολλαῖς, ἐλάλει αὐτοῖς τὸν λόγον, καθὼς ἠδύναντο ἀκούειν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 34, 'χωρὶς δὲ παραβολῆς οὐκ ἐλάλει αὐτοῖς, κατʼ ἰδίαν δὲ τοῖς ἰδίοις μαθηταῖς, ἐπέλυεν πάντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 35, '¶Καὶ λέγει αὐτοῖς ἐν ἐκείνῃ τῇ ἡμέρᾳ ὀψίας γενομένης, “Διέλθωμεν εἰς τὸ πέραν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 36, 'Καὶ ἀφέντες τὸν ὄχλον, παραλαμβάνουσιν αὐτὸν ὡς ἦν ἐν τῷ πλοίῳ. Καὶ ἄλλα πλοῖα ἦν μετʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 37, 'Καὶ γίνεται λαῖλαψ μεγάλη ἀνέμου, καὶ τὰ κύματα ἐπέβαλλεν εἰς τὸ πλοῖον, ὥστε ἤδη γεμίζεσθαι τὸ πλοῖον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 38, 'Καὶ αὐτὸς ἦν ἐν τῇ πρύμνῃ, ἐπὶ τὸ προσκεφάλαιον καθεύδων. Καὶ διεγείρουσιν αὐτὸν καὶ λέγουσιν αὐτῷ, “Διδάσκαλε, οὐ μέλει σοι ὅτι ἀπολλύμεθα;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 39, 'Καὶ διεγερθεὶς, ἐπετίμησεν τῷ ἀνέμῳ καὶ εἶπεν τῇ θαλάσσῃ, “Σιώπα, πεφίμωσο.” Καὶ ἐκόπασεν ὁ ἄνεμος, καὶ ἐγένετο γαλήνη μεγάλη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 40, 'Καὶ εἶπεν αὐτοῖς, “Τί δειλοί ἐστε; Οὔπω ἔχετε πίστιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 41, 'Καὶ ἐφοβήθησαν φόβον μέγαν, καὶ ἔλεγον πρὸς ἀλλήλους, “Τίς ἄρα οὗτός ἐστιν, ὅτι καὶ ὁ ἄνεμος καὶ ἡ θάλασσα αὐτῷ ὑπακούει;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, '¶Καὶ ἦλθον εἰς τὸ πέραν τῆς θαλάσσης, εἰς τὴν χώραν τῶν Γερασηνῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Καὶ ἐξελθόντος αὐτοῦ ἐκ τοῦ πλοίου, ὑπήντησεν αὐτῷ ἐκ τῶν μνημείων ἄνθρωπος ἐν πνεύματι ἀκαθάρτῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'ὃς τὴν κατοίκησιν εἶχεν ἐν τοῖς μνήμασιν, καὶ οὐδὲ ἁλύσει οὐκέτι οὐδεὶς ἐδύνατο αὐτὸν δῆσαι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'διὰ τὸ αὐτὸν πολλάκις πέδαις καὶ ἁλύσεσι δεδέσθαι, καὶ διεσπάσθαι ὑπʼ αὐτοῦ τὰς ἁλύσεις καὶ τὰς πέδας συντετρῖφθαι, καὶ οὐδεὶς ἴσχυεν αὐτὸν δαμάσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Καὶ διὰ παντὸς νυκτὸς καὶ ἡμέρας ἐν τοῖς μνήμασιν καὶ ἐν τοῖς ὄρεσιν, ἦν κράζων καὶ κατακόπτων ἑαυτὸν λίθοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Καὶ ἰδὼν τὸν  ̊Ἰησοῦν ἀπὸ μακρόθεν, ἔδραμεν καὶ προσεκύνησεν αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'καὶ κράξας φωνῇ μεγάλῃ λέγει, “Τί ἐμοὶ καὶ σοί  ̊Ἰησοῦ, Υἱὲ τοῦ  ̊Θεοῦ τοῦ Ὑψίστου; Ὁρκίζω σε τὸν  ̊Θεόν, μή με βασανίσῃς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Ἔλεγεν γὰρ αὐτῷ, “Ἔξελθε, τὸ πνεῦμα τὸ ἀκάθαρτον ἐκ τοῦ ἀνθρώπου!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Καὶ ἐπηρώτα αὐτόν, “Τί ὄνομά σοι;” Καὶ λέγει αὐτῷ, “Λεγιὼν ὄνομά μοι, ὅτι πολλοί ἐσμεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Καὶ παρεκάλει αὐτὸν πολλὰ ἵνα μὴ αὐτὰ ἀποστείλῃ ἔξω τῆς χώρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Ἦν δὲ ἐκεῖ πρὸς τῷ ὄρει, ἀγέλη χοίρων μεγάλη βοσκομένη·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'καὶ παρεκάλεσαν αὐτὸν λέγοντες, “Πέμψον ἡμᾶς εἰς τοὺς χοίρους, ἵνα εἰς αὐτοὺς εἰσέλθωμεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Καὶ ἐπέτρεψεν αὐτοῖς. Καὶ ἐξελθόντα, τὰ πνεύματα τὰ ἀκάθαρτα εἰσῆλθον εἰς τοὺς χοίρους, καὶ ὥρμησεν ἡ ἀγέλη κατὰ τοῦ κρημνοῦ εἰς τὴν θάλασσαν, ὡς δισχίλιοι, καὶ ἐπνίγοντο ἐν τῇ θαλάσσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Καὶ οἱ βόσκοντες αὐτοὺς ἔφυγον, καὶ ἀπήγγειλαν εἰς τὴν πόλιν καὶ εἰς τοὺς ἀγρούς. Καὶ ἐξῆλθον ἰδεῖν τί ἐστιν τὸ γεγονός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Καὶ ἔρχονται πρὸς τὸν  ̊Ἰησοῦν, καὶ θεωροῦσιν τὸν δαιμονιζόμενον καθήμενον, ἱματισμένον καὶ σωφρονοῦντα, τὸν ἐσχηκότα τὸν λεγεῶνα, καὶ ἐφοβήθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Καὶ διηγήσαντο αὐτοῖς οἱ ἰδόντες, πῶς ἐγένετο τῷ δαιμονιζομένῳ, καὶ περὶ τῶν χοίρων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Καὶ ἤρξαντο παρακαλεῖν αὐτὸν ἀπελθεῖν ἀπὸ τῶν ὁρίων αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Καὶ ἐμβαίνοντος αὐτοῦ εἰς τὸ πλοῖον, παρεκάλει αὐτὸν ὁ δαιμονισθεὶς ἵνα μετʼ αὐτοῦ ᾖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Καὶ οὐκ ἀφῆκεν αὐτόν, ἀλλὰ λέγει αὐτῷ, “Ὕπαγε εἰς τὸν οἶκόν σου, πρὸς τοὺς σούς, καὶ ἀπάγγειλον αὐτοῖς ὅσα ὁ  ̊Κύριός σοι πεποίηκεν, καὶ ἠλέησέν σε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Καὶ ἀπῆλθεν καὶ ἤρξατο κηρύσσειν ἐν τῇ Δεκαπόλει, ὅσα ἐποίησεν αὐτῷ ὁ  ̊Ἰησοῦς, καὶ πάντες ἐθαύμαζον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 21, '¶Καὶ διαπεράσαντος τοῦ  ̊Ἰησοῦ ἐν τῷ πλοίῳ πάλιν εἰς τὸ πέραν, συνήχθη ὄχλος πολὺς ἐπʼ αὐτόν, καὶ ἦν παρὰ τὴν θάλασσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 22, 'Καὶ ἰδοὺ, ἔρχεται εἷς τῶν ἀρχισυναγώγων ὀνόματι Ἰάειρος, καὶ ἰδὼν αὐτὸν, πίπτει πρὸς τοὺς πόδας αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 23, 'καὶ παρακαλεῖ αὐτὸν πολλὰ λέγων, ὅτι “Τὸ θυγάτριόν μου ἐσχάτως ἔχει, ἵνα ἐλθὼν, ἐπιθῇς τὰς χεῖρας αὐτῇ, ἵνα σωθῇ καὶ ζήσῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 24, 'Καὶ ἀπῆλθεν μετʼ αὐτοῦ. ¶Καὶ ἠκολούθει αὐτῷ ὄχλος πολύς, καὶ συνέθλιβον αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 25, 'Καὶ γυνὴ οὖσα ἐν ῥύσει αἵματος δώδεκα ἔτη,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 26, 'καὶ πολλὰ παθοῦσα ὑπὸ πολλῶν ἰατρῶν, καὶ δαπανήσασα τὰ παρʼ ἑαυτῆς πάντα, καὶ μηδὲν ὠφεληθεῖσα, ἀλλὰ μᾶλλον εἰς τὸ χεῖρον ἐλθοῦσα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 27, 'ἀκούσασα τὰ περὶ τοῦ  ̊Ἰησοῦ, ἐλθοῦσα ἐν τῷ ὄχλῳ ὄπισθεν, ἥψατο τοῦ ἱματίου αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 28, 'Ἔλεγεν γὰρ, ὅτι “Ἐὰν ἅψωμαι κἂν τῶν ἱματίων αὐτοῦ, σωθήσομαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 29, 'Καὶ εὐθὺς ἐξηράνθη ἡ πηγὴ τοῦ αἵματος αὐτῆς, καὶ ἔγνω τῷ σώματι ὅτι ἴαται ἀπὸ τῆς μάστιγος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 30, 'Καὶ εὐθὺς ὁ  ̊Ἰησοῦς, ἐπιγνοὺς ἐν ἑαυτῷ τὴν ἐξ αὐτοῦ δύναμιν ἐξελθοῦσαν, ἐπιστραφεὶς ἐν τῷ ὄχλῳ ἔλεγεν, “Τίς μου ἥψατο τῶν ἱματίων;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 31, 'Καὶ ἔλεγον αὐτῷ οἱ μαθηταὶ αὐτοῦ, “Βλέπεις τὸν ὄχλον συνθλίβοντά σε, καὶ λέγεις, ‘Τίς μου ἥψατο;’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 32, 'Καὶ περιεβλέπετο ἰδεῖν τὴν τοῦτο ποιήσασαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 33, 'Ἡ δὲ γυνὴ, φοβηθεῖσα καὶ τρέμουσα, εἰδυῖα ὃ γέγονεν αὐτῇ, ἦλθεν καὶ προσέπεσεν αὐτῷ, καὶ εἶπεν αὐτῷ πᾶσαν τὴν ἀλήθειαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 34, 'Ὁ δὲ εἶπεν αὐτῇ, “Θυγάτηρ, ἡ πίστις σου σέσωκέν σε· ὕπαγε εἰς εἰρήνην, καὶ ἴσθι ὑγιὴς ἀπὸ τῆς μάστιγός σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 35, '¶Ἔτι αὐτοῦ λαλοῦντος, ἔρχονται ἀπὸ τοῦ ἀρχισυναγώγου λέγοντες, ὅτι “Ἡ θυγάτηρ σου ἀπέθανεν· τί ἔτι σκύλλεις τὸν διδάσκαλον;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 36, 'Ὁ δὲ  ̊Ἰησοῦς παρακούσας τὸν λόγον λαλούμενον λέγει τῷ ἀρχισυναγώγῳ, “Μὴ φοβοῦ, μόνον πίστευε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 37, 'Καὶ οὐκ ἀφῆκεν οὐδένα μετʼ αὐτοῦ συνακολουθῆσαι, εἰ μὴ τὸν Πέτρον, καὶ Ἰάκωβον, καὶ Ἰωάννην τὸν ἀδελφὸν Ἰακώβου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 38, 'Καὶ ἔρχονται εἰς τὸν οἶκον τοῦ ἀρχισυναγώγου, καὶ θεωρεῖ θόρυβον, καὶ κλαίοντας καὶ ἀλαλάζοντας πολλά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 39, 'Καὶ εἰσελθὼν λέγει αὐτοῖς, “Τί θορυβεῖσθε καὶ κλαίετε; Τὸ παιδίον οὐκ ἀπέθανεν, ἀλλὰ καθεύδει.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 40, 'Καὶ κατεγέλων αὐτοῦ. Αὐτὸς δὲ ἐκβαλὼν πάντας, παραλαμβάνει τὸν πατέρα τοῦ παιδίου, καὶ τὴν μητέρα, καὶ τοὺς μετʼ αὐτοῦ, καὶ εἰσπορεύεται ὅπου ἦν τὸ παιδίον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 41, 'Καὶ κρατήσας τῆς χειρὸς τοῦ παιδίου, λέγει αὐτῇ, “Ταλιθά, κούμ!” Ὅ ἐστιν μεθερμηνευόμενον “Τὸ κοράσιον, σοὶ λέγω, ἔγειρε!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 42, 'Καὶ εὐθὺς ἀνέστη τὸ κοράσιον καὶ περιεπάτει, ἦν γὰρ ἐτῶν δώδεκα. Καὶ ἐξέστησαν εὐθὺς ἐκστάσει μεγάλῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 43, 'Καὶ διεστείλατο αὐτοῖς πολλὰ ἵνα μηδεὶς γνοῖ τοῦτο, καὶ εἶπεν δοθῆναι αὐτῇ φαγεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 1, '¶Καὶ ἐξῆλθεν ἐκεῖθεν, καὶ ἔρχεται εἰς τὴν πατρίδα αὐτοῦ, καὶ ἀκολουθοῦσιν αὐτῷ οἱ μαθηταὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 2, 'Καὶ γενομένου Σαββάτου, ἤρξατο διδάσκειν ἐν τῇ συναγωγῇ· καὶ πολλοὶ ἀκούοντες ἐξεπλήσσοντο λέγοντες, “Πόθεν τούτῳ ταῦτα, καὶ τίς ἡ σοφία ἡ δοθεῖσα τούτῳ, καὶ αἱ δυνάμεις τοιαῦται διὰ τῶν χειρῶν αὐτοῦ γινόμεναι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 3, 'Οὐχ οὗτός ἐστιν ὁ τέκτων, ὁ υἱὸς τῆς Μαρίας, καὶ ἀδελφὸς Ἰακώβου, καὶ Ἰωσῆτος, καὶ Ἰούδα, καὶ Σίμωνος; Καὶ οὐκ εἰσὶν αἱ ἀδελφαὶ αὐτοῦ ὧδε πρὸς ἡμᾶς;” Καὶ ἐσκανδαλίζοντο ἐν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 4, 'Καὶ ἔλεγεν αὐτοῖς ὁ  ̊Ἰησοῦς, ὅτι “Οὐκ ἔστιν προφήτης ἄτιμος, εἰ μὴ ἐν τῇ πατρίδι αὐτοῦ, καὶ ἐν τοῖς συγγενέσιν αὐτοῦ, καὶ ἐν τῇ οἰκίᾳ αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 5, 'Καὶ οὐκ ἐδύνατο ἐκεῖ ποιῆσαι οὐδεμίαν δύναμιν, εἰ μὴ ὀλίγοις ἀρρώστοις, ἐπιθεὶς τὰς χεῖρας, ἐθεράπευσεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 6, 'Καὶ ἐθαύμασεν διὰ τὴν ἀπιστίαν αὐτῶν. ¶Καὶ περιῆγεν τὰς κώμας, κύκλῳ διδάσκων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 7, 'Καὶ προσκαλεῖται τοὺς δώδεκα, καὶ ἤρξατο αὐτοὺς ἀποστέλλειν δύο δύο, καὶ ἐδίδου αὐτοῖς ἐξουσίαν τῶν πνευμάτων τῶν ἀκαθάρτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 8, 'Καὶ παρήγγειλεν αὐτοῖς ἵνα μηδὲν αἴρωσιν εἰς ὁδὸν, εἰ μὴ ῥάβδον μόνον, μὴ ἄρτον, μὴ πήραν, μὴ εἰς τὴν ζώνην χαλκόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 9, 'ἀλλὰ ὑποδεδεμένους σανδάλια, καὶ μὴ ἐνδύσησθε δύο χιτῶνας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 10, 'Καὶ ἔλεγεν αὐτοῖς, “Ὅπου ἐὰν εἰσέλθητε εἰς οἰκίαν, ἐκεῖ μένετε ἕως ἂν ἐξέλθητε ἐκεῖθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 11, 'Καὶ ὃς ἂν τόπος μὴ δέξηται ὑμᾶς, μηδὲ ἀκούσωσιν ὑμῶν, ἐκπορευόμενοι ἐκεῖθεν, ἐκτινάξατε τὸν χοῦν τὸν ὑποκάτω τῶν ποδῶν ὑμῶν, εἰς μαρτύριον αὐτοῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 12, 'Καὶ ἐξελθόντες, ἐκήρυξαν ἵνα μετανοῶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 13, 'Καὶ δαιμόνια πολλὰ ἐξέβαλλον, καὶ ἤλειφον ἐλαίῳ πολλοὺς ἀρρώστους καὶ ἐθεράπευον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 14, '¶Καὶ ἤκουσεν ὁ βασιλεὺς Ἡρῴδης, φανερὸν γὰρ ἐγένετο τὸ ὄνομα αὐτοῦ, καὶ ἔλεγεν, ὅτι “Ἰωάννης ὁ βαπτίζων ἐγήγερται ἐκ νεκρῶν, καὶ διὰ τοῦτο ἐνεργοῦσιν αἱ δυνάμεις ἐν αὐτῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 15, 'Ἄλλοι δὲ ἔλεγον, ὅτι “Ἠλίας ἐστίν”· ἄλλοι δὲ ἔλεγον, ὅτι “Προφήτης, ὡς εἷς τῶν προφητῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 16, 'Ἀκούσας δὲ, ὁ Ἡρῴδης ἔλεγεν, ὅτι “Ὃν ἐγὼ ἀπεκεφάλισα Ἰωάννην, οὗτος ἠγέρθη!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 17, '¶Αὐτὸς γὰρ ὁ Ἡρῴδης, ἀποστείλας ἐκράτησεν τὸν Ἰωάννην, καὶ ἔδησεν αὐτὸν ἐν φυλακῇ διὰ Ἡρῳδιάδα, τὴν γυναῖκα Φιλίππου, τοῦ ἀδελφοῦ αὐτοῦ, ὅτι αὐτὴν ἐγάμησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 18, 'Ἔλεγεν γὰρ ὁ Ἰωάννης τῷ Ἡρῴδῃ, ὅτι “Οὐκ ἔξεστίν σοι ἔχειν τὴν γυναῖκα τοῦ ἀδελφοῦ σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 19, 'Ἡ δὲ Ἡρῳδιὰς ἐνεῖχεν αὐτῷ, καὶ ἤθελεν αὐτὸν ἀποκτεῖναι, καὶ οὐκ ἠδύνατο·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 20, 'ὁ γὰρ Ἡρῴδης ἐφοβεῖτο τὸν Ἰωάννην, εἰδὼς αὐτὸν ἄνδρα δίκαιον καὶ ἅγιον, καὶ συνετήρει αὐτόν, καὶ ἀκούσας αὐτοῦ, πολλὰ ἠπόρει, καὶ ἡδέως αὐτοῦ ἤκουεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 21, 'Καὶ γενομένης ἡμέρας εὐκαίρου, ὅτε Ἡρῴδης τοῖς γενεσίοις αὐτοῦ δεῖπνον ἐποίησεν, τοῖς μεγιστᾶσιν αὐτοῦ, καὶ τοῖς χιλιάρχοις, καὶ τοῖς πρώτοις τῆς Γαλιλαίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 22, 'Καὶ εἰσελθούσης τῆς θυγατρὸς αὐτοῦ Ἡρῳδιάδος, καὶ ὀρχησαμένης ἤρεσεν τῷ Ἡρῴδῃ καὶ τοῖς συνανακειμένοις. Ὁ δὲ βασιλεὺς εἶπεν τῷ κορασίῳ, “Αἴτησόν με ὃ ἐὰν θέλῃς, καὶ δώσω σοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 23, 'Καὶ ὤμοσεν αὐτῇ, ὅτι “Ὃ ἐάν αἰτήσῃς, με, δώσω σοι, ἕως ἡμίσους τῆς βασιλείας μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 24, 'Καὶ ἐξελθοῦσα, εἶπεν τῇ μητρὶ αὐτῆς, “Τί αἰτήσωμαι;” Ἡ δὲ εἶπεν, “Τὴν κεφαλὴν Ἰωάννου τοῦ βαπτίζοντος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 25, 'Καὶ εἰσελθοῦσα εὐθὺς μετὰ σπουδῆς πρὸς τὸν βασιλέα, ᾐτήσατο λέγουσα, “Θέλω ἵνα ἐξαυτῆς δῷς μοι ἐπὶ πίνακι τὴν κεφαλὴν Ἰωάννου τοῦ Βαπτιστοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 26, 'Καὶ περίλυπος γενόμενος ὁ βασιλεὺς, διὰ τοὺς ὅρκους καὶ τοὺς συνανακειμένους οὐκ ἠθέλησεν ἀθετῆσαι αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 27, 'Καὶ εὐθὺς ἀποστείλας ὁ βασιλεὺς σπεκουλάτορα, ἐπέταξεν ἐνέγκαι τὴν κεφαλὴν αὐτοῦ. Καὶ ἀπελθὼν, ἀπεκεφάλισεν αὐτὸν ἐν τῇ φυλακῇ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 28, 'καὶ ἤνεγκεν τὴν κεφαλὴν αὐτοῦ ἐπὶ πίνακι, καὶ ἔδωκεν αὐτὴν τῷ κορασίῳ, καὶ τὸ κοράσιον ἔδωκεν αὐτὴν τῇ μητρὶ αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 29, 'Καὶ ἀκούσαντες, οἱ μαθηταὶ αὐτοῦ ἦλθον, καὶ ἦραν τὸ πτῶμα αὐτοῦ, καὶ ἔθηκαν αὐτὸ ἐν μνημείῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 30, '¶Καὶ συνάγονται οἱ ἀπόστολοι πρὸς τὸν  ̊Ἰησοῦν καὶ ἀπήγγειλαν αὐτῷ, πάντα ὅσα ἐποίησαν καὶ ὅσα ἐδίδαξαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 31, 'Καὶ λέγει αὐτοῖς, “Δεῦτε ὑμεῖς αὐτοὶ κατʼ ἰδίαν εἰς ἔρημον τόπον, καὶ ἀναπαύσασθε ὀλίγον.” Ἦσαν γὰρ οἱ ἐρχόμενοι καὶ οἱ ὑπάγοντες πολλοί, καὶ οὐδὲ φαγεῖν εὐκαίρουν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 32, 'Καὶ ἀπῆλθον ἐν τῷ πλοίῳ εἰς ἔρημον τόπον κατʼ ἰδίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 33, 'Καὶ εἶδον αὐτοὺς ὑπάγοντας, καὶ ἐπέγνωσαν πολλοί, καὶ πεζῇ ἀπὸ πασῶν τῶν πόλεων συνέδραμον ἐκεῖ, καὶ προῆλθον αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 34, 'Καὶ ἐξελθὼν, εἶδεν πολὺν ὄχλον καὶ ἐσπλαγχνίσθη ἐπʼ αὐτοὺς, ὅτι ἦσαν ὡς πρόβατα μὴ ἔχοντα ποιμένα, καὶ ἤρξατο διδάσκειν αὐτοὺς πολλά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 35, 'Καὶ ἤδη ὥρας πολλῆς γενομένης, προσελθόντες αὐτῷ οἱ μαθηταὶ αὐτοῦ ἔλεγον, ὅτι “Ἔρημός ἐστιν ὁ τόπος, καὶ ἤδη ὥρα πολλή·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 36, 'ἀπόλυσον αὐτούς, ἵνα ἀπελθόντες εἰς τοὺς κύκλῳ ἀγροὺς καὶ κώμας, ἀγοράσωσιν ἑαυτοῖς τί φάγωσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 37, 'Ὁ δὲ ἀποκριθεὶς εἶπεν αὐτοῖς, “Δότε αὐτοῖς ὑμεῖς φαγεῖν.” Καὶ λέγουσιν αὐτῷ, “Ἀπελθόντες, ἀγοράσωμεν δηναρίων διακοσίων ἄρτους, καὶ δώσομεν αὐτοῖς φαγεῖν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 38, 'Ὁ δὲ λέγει αὐτοῖς, “Πόσους ἄρτους ἔχετε; Ὑπάγετε, ἴδετε.” Καὶ γνόντες λέγουσιν, “Πέντε καὶ δύο ἰχθύας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 39, 'Καὶ ἐπέταξεν αὐτοῖς ἀνακλῖναι πάντας, συμπόσια συμπόσια ἐπὶ τῷ χλωρῷ χόρτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 40, 'Καὶ ἀνέπεσον πρασιαὶ πρασιαὶ, κατὰ ἑκατὸν καὶ κατὰ πεντήκοντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 41, 'Καὶ λαβὼν τοὺς πέντε ἄρτους καὶ τοὺς δύο ἰχθύας, ἀναβλέψας εἰς τὸν οὐρανὸν, εὐλόγησεν καὶ κατέκλασεν τοὺς ἄρτους, καὶ ἐδίδου τοῖς μαθηταῖς αὐτοῦ, ἵνα παρατιθῶσιν αὐτοῖς, καὶ τοὺς δύο ἰχθύας ἐμέρισεν πᾶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 42, 'Καὶ ἔφαγον πάντες καὶ ἐχορτάσθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 43, 'Καὶ ἦραν κλάσματα δώδεκα κοφίνων πληρώματα, καὶ ἀπὸ τῶν ἰχθύων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 44, 'Καὶ ἦσαν οἱ φαγόντες τοὺς ἄρτους, πεντακισχίλιοι ἄνδρες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 45, '¶Καὶ εὐθὺς ἠνάγκασεν τοὺς μαθητὰς αὐτοῦ ἐμβῆναι εἰς τὸ πλοῖον, καὶ προάγειν εἰς τὸ πέραν πρὸς Βηθσαϊδάν, ἕως αὐτὸς ἀπολύει τὸν ὄχλον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 46, 'Καὶ ἀποταξάμενος αὐτοῖς, ἀπῆλθεν εἰς τὸ ὄρος προσεύξασθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 47, '¶Καὶ ὀψίας γενομένης, ἦν τὸ πλοῖον ἐν μέσῳ τῆς θαλάσσης, καὶ αὐτὸς μόνος ἐπὶ τῆς γῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 48, 'Καὶ ἰδὼν αὐτοὺς βασανιζομένους ἐν τῷ ἐλαύνειν, ἦν γὰρ ὁ ἄνεμος ἐναντίος αὐτοῖς, περὶ τετάρτην φυλακὴν τῆς νυκτὸς, ἔρχεται πρὸς αὐτοὺς, περιπατῶν ἐπὶ τῆς θαλάσσης, καὶ ἤθελεν παρελθεῖν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 49, 'Οἱ, δὲ ἰδόντες αὐτὸν ἐπὶ τῆς θαλάσσης περιπατοῦντα, ἔδοξαν ὅτι φάντασμά ἐστιν, καὶ ἀνέκραξαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 50, 'Πάντες γὰρ αὐτὸν εἶδον, καὶ ἐταράχθησαν. Ὁ δὲ εὐθὺς ἐλάλησεν μετʼ αὐτῶν, καὶ λέγει αὐτοῖς, “Θαρσεῖτε, ἐγώ εἰμι, μὴ φοβεῖσθε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 51, 'Καὶ ἀνέβη πρὸς αὐτοὺς εἰς τὸ πλοῖον, καὶ ἐκόπασεν ὁ ἄνεμος. Καὶ λίαν ἐν ἑαυτοῖς ἐξίσταντο,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 52, 'οὐ γὰρ συνῆκαν ἐπὶ τοῖς ἄρτοις, ἀλλʼ ἦν αὐτῶν ἡ καρδία πεπωρωμένη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 53, '¶Καὶ διαπεράσαντες ἐπὶ τὴν γῆν ἦλθον εἰς Γεννησαρὲτ, καὶ προσωρμίσθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 54, 'Καὶ ἐξελθόντων αὐτῶν ἐκ τοῦ πλοίου, εὐθὺς ἐπιγνόντες αὐτὸν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 55, 'περιέδραμον ὅλην τὴν χώραν ἐκείνην, καὶ ἤρξαντο ἐπὶ τοῖς κραβάττοις τοὺς κακῶς ἔχοντας περιφέρειν, ὅπου ἤκουον ὅτι ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 56, 'Καὶ ὅπου ἂν εἰσεπορεύετο εἰς κώμας, ἢ εἰς πόλεις, ἢ εἰς ἀγροὺς, ἐν ταῖς ἀγοραῖς ἐτίθεσαν τοὺς ἀσθενοῦντας, καὶ παρεκάλουν αὐτὸν ἵνα κἂν τοῦ κρασπέδου τοῦ ἱματίου αὐτοῦ ἅψωνται· καὶ ὅσοι ἂν ἥψαντο αὐτοῦ ἐσῴζοντο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 1, '¶Καὶ συνάγονται πρὸς αὐτὸν οἱ Φαρισαῖοι καί τινες τῶν γραμματέων, ἐλθόντες ἀπὸ Ἱεροσολύμων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 2, 'καὶ ἰδόντες τινὰς τῶν μαθητῶν αὐτοῦ, ὅτι κοιναῖς χερσίν, τοῦτʼ ἔστιν ἀνίπτοις, ἐσθίουσιν τοὺς ἄρτους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 3, '(Οἱ γὰρ Φαρισαῖοι καὶ πάντες οἱ Ἰουδαῖοι, ἐὰν μὴ πυγμῇ νίψωνται τὰς χεῖρας οὐκ ἐσθίουσιν, κρατοῦντες τὴν παράδοσιν τῶν πρεσβυτέρων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 4, 'καὶ ἀπʼ ἀγορᾶς ἐὰν μὴ βαπτίσωνται οὐκ ἐσθίουσιν, καὶ ἄλλα πολλά ἐστιν ἃ παρέλαβον κρατεῖν, βαπτισμοὺς ποτηρίων καὶ ξεστῶν καὶ χαλκίων.)');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 5, 'Καὶ ἐπερωτῶσιν αὐτὸν οἱ Φαρισαῖοι καὶ οἱ γραμματεῖς, “Διὰ τί οἱ μαθηταί σου οὐ περιπατοῦσιν κατὰ τὴν παράδοσιν τῶν πρεσβυτέρων, ἀλλὰ κοιναῖς χερσὶν ἐσθίουσιν τὸν ἄρτον;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 6, 'Ὁ δὲ ἀποκριθεὶς εἶπεν αὐτοῖς, “Καλῶς ἐπροφήτευσεν Ἠσαΐας περὶ ὑμῶν τῶν ὑποκριτῶν, ὡς γέγραπται, ὅτι ‘Οὗτος ὁ λαὸς τοῖς χείλεσίν με τιμᾷ, ἡ δὲ καρδία αὐτῶν πόρρω ἀπέχει ἀπʼ ἐμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 7, 'Μάτην δὲ σέβονταί με, διδάσκοντες διδασκαλίας ἐντάλματα ἀνθρώπων.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 8, 'Ἀφέντες τὴν ἐντολὴν τοῦ  ̊Θεοῦ, κρατεῖτε τὴν παράδοσιν τῶν ἀνθρώπων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 9, '¶Καὶ ἔλεγεν αὐτοῖς, “Καλῶς ἀθετεῖτε τὴν ἐντολὴν τοῦ  ̊Θεοῦ, ἵνα τὴν παράδοσιν ὑμῶν τηρήσητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 10, 'Μωϋσῆς γὰρ εἶπεν, ‘Τίμα τὸν πατέρα σου καὶ τὴν μητέρα σου’, καί, ‘Ὁ κακολογῶν πατέρα ἢ μητέρα θανάτῳ τελευτάτω.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 11, 'Ὑμεῖς δὲ λέγετε, ‘Ἐὰν εἴπῃ ἄνθρωπος τῷ πατρὶ ἢ τῇ μητρί, “Κορβᾶν”’, (ὅ ἐστιν “Δῶρον”), ‘“ὃ ἐὰν ἐξ ἐμοῦ ὠφεληθῇς”’,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 12, 'οὐκέτι ἀφίετε αὐτὸν οὐδὲν ποιῆσαι τῷ πατρὶ ἢ τῇ μητρί,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 13, 'ἀκυροῦντες τὸν λόγον τοῦ  ̊Θεοῦ τῇ παραδόσει ὑμῶν ᾗ παρεδώκατε. Καὶ παρόμοια τοιαῦτα πολλὰ ποιεῖτε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 14, '¶Καὶ προσκαλεσάμενος πάλιν τὸν ὄχλον, ἔλεγεν αὐτοῖς, “Ἀκούετέ μου πάντες καὶ συνίετε:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 15, 'οὐδέν ἐστιν ἔξωθεν τοῦ ἀνθρώπου εἰσπορευόμενον εἰς αὐτὸν, ὃ δύναται αὐτὸν κοινῶσαι ἀλλὰ τὰ ἐκ τοῦ ἀνθρώπου ἐκπορευόμενά, ἐστιν τὰ κοινοῦντα τὸν ἄνθρωπον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 16, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 17, '¶Καὶ ὅτε εἰσῆλθεν εἰς οἶκον ἀπὸ τοῦ ὄχλου, ἐπηρώτων αὐτὸν οἱ μαθηταὶ αὐτοῦ τὴν παραβολήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 18, 'Καὶ λέγει αὐτοῖς, “Οὕτως καὶ ὑμεῖς ἀσύνετοί ἐστε; Οὐ νοεῖτε ὅτι πᾶν τὸ ἔξωθεν εἰσπορευόμενον εἰς τὸν ἄνθρωπον, οὐ δύναται αὐτὸν κοινῶσαι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 19, 'ὅτι οὐκ εἰσπορεύεται αὐτοῦ εἰς τὴν καρδίαν, ἀλλʼ εἰς τὴν κοιλίαν, καὶ εἰς τὸν ἀφεδρῶνα ἐκπορεύεται;” (Καθαρίζων πάντα τὰ βρώματα.)');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 20, 'Ἔλεγεν δὲ, ὅτι “Τὸ ἐκ τοῦ ἀνθρώπου ἐκπορευόμενον, ἐκεῖνο κοινοῖ τὸν ἄνθρωπον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 21, 'Ἔσωθεν γὰρ ἐκ τῆς καρδίας τῶν ἀνθρώπων οἱ διαλογισμοὶ οἱ κακοὶ ἐκπορεύονται, πορνεῖαι, κλοπαί, φόνοι, μοιχεῖαι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 22, 'πλεονεξίαι, πονηρίαι, δόλος, ἀσέλγεια, ὀφθαλμὸς πονηρός, βλασφημία, ὑπερηφανία, ἀφροσύνη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 23, 'Πάντα ταῦτα τὰ πονηρὰ ἔσωθεν ἐκπορεύεται καὶ κοινοῖ τὸν ἄνθρωπον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 24, '¶Ἐκεῖθεν δὲ ἀναστὰς, ἀπῆλθεν εἰς τὰ ὅρια Τύρου καὶ Σιδῶνος. Καὶ εἰσελθὼν εἰς οἰκίαν, οὐδένα ἤθελεν γνῶναι, καὶ οὐκ ἠδυνάσθη λαθεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 25, 'Ἀλλʼ εὐθὺς ἀκούσασα γυνὴ περὶ αὐτοῦ, ἧς εἶχεν τὸ θυγάτριον αὐτῆς πνεῦμα ἀκάθαρτον ἐλθοῦσα, προσέπεσεν πρὸς τοὺς πόδας αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 26, 'Ἡ δὲ γυνὴ ἦν Ἑλληνίς, Συροφοινίκισσα τῷ γένει, καὶ ἠρώτα αὐτὸν ἵνα τὸ δαιμόνιον ἐκβάλῃ ἐκ τῆς θυγατρὸς αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 27, 'Καὶ ἔλεγεν αὐτῇ, “Ἄφες πρῶτον χορτασθῆναι τὰ τέκνα, οὐ γάρ ἐστιν καλὸν λαβεῖν τὸν ἄρτον τῶν τέκνων, καὶ τοῖς κυναρίοις βαλεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 28, 'Ἡ δὲ ἀπεκρίθη καὶ λέγει αὐτῷ, “Ναί,  ̊Κύριε, καὶ τὰ κυνάρια ὑποκάτω τῆς τραπέζης ἐσθίουσιν ἀπὸ τῶν ψιχίων τῶν παιδίων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 29, 'Καὶ εἶπεν αὐτῇ, “Διὰ τοῦτον τὸν λόγον ὕπαγε, ἐξελήλυθεν τὸ δαιμόνιον, ἐκ τῆς θυγατρός σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 30, 'Καὶ ἀπελθοῦσα εἰς τὸν οἶκον αὐτῆς, εὗρεν τὸ παιδίον βεβλημένον ἐπὶ τὴν κλίνην, καὶ τὸ δαιμόνιον ἐξεληλυθός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 31, '¶Καὶ πάλιν ἐξελθὼν ἐκ τῶν ὁρίων Τύρου, ἦλθεν διὰ Σιδῶνος εἰς τὴν θάλασσαν τῆς Γαλιλαίας, ἀνὰ μέσον τῶν ὁρίων Δεκαπόλεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 32, 'Καὶ φέρουσιν αὐτῷ κωφὸν καὶ μογιλάλον, καὶ παρακαλοῦσιν αὐτὸν ἵνα ἐπιθῇ αὐτῷ τὴν χεῖρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 33, 'Καὶ ἀπολαβόμενος αὐτὸν ἀπὸ τοῦ ὄχλου κατʼ ἰδίαν, ἔβαλεν τοὺς δακτύλους αὐτοῦ εἰς τὰ ὦτα αὐτοῦ, καὶ πτύσας, ἥψατο τῆς γλώσσης αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 34, 'καὶ ἀναβλέψας εἰς τὸν οὐρανὸν ἐστέναξεν, καὶ λέγει αὐτῷ, “Ἐφφαθά”, ὅ ἐστιν, “Διανοίχθητι”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 35, 'Καὶ ἠνοίγησαν αὐτοῦ αἱ ἀκοαί, καὶ ἐλύθη ὁ δεσμὸς τῆς γλώσσης αὐτοῦ, καὶ ἐλάλει ὀρθῶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 36, 'Καὶ διεστείλατο αὐτοῖς ἵνα μηδενὶ λέγωσιν. Ὅσον δὲ αὐτοῖς διεστέλλετο, αὐτοὶ μᾶλλον περισσότερον ἐκήρυσσον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 37, 'Καὶ ὑπερπερισσῶς ἐξεπλήσσοντο λέγοντες, “Καλῶς πάντα πεποίηκεν, καὶ τοὺς κωφοὺς ποιεῖ ἀκούειν, καὶ ἀλάλους λαλεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 1, '¶Ἐν ἐκείναις ταῖς ἡμέραις πάλιν, πολλοῦ ὄχλου ὄντος, καὶ μὴ ἐχόντων τί φάγωσιν, προσκαλεσάμενος τοὺς μαθητὰς αὐτοῦ, λέγει αὐτοῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 2, '“Σπλαγχνίζομαι ἐπὶ τὸν ὄχλον, ὅτι ἤδη ἡμέραι τρεῖς προσμένουσίν μοι, καὶ οὐκ ἔχουσιν τί φάγωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 3, 'Καὶ ἐὰν ἀπολύσω αὐτοὺς νήστεις εἰς οἶκον αὐτῶν, ἐκλυθήσονται ἐν τῇ ὁδῷ. Καί τινες αὐτῶν ἀπὸ μακρόθεν ἥκασιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 4, 'Καὶ ἀπεκρίθησαν αὐτῷ οἱ μαθηταὶ αὐτοῦ, “Πόθεν τούτους δυνήσεταί τις ὧδε χορτάσαι ἄρτων ἐπʼ ἐρημίας;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 5, 'Καὶ ἠρώτα αὐτούς, “Πόσους ἔχετε ἄρτους;” Οἱ δὲ εἶπαν, “Ἑπτά.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 6, 'Καὶ παραγγέλλει τῷ ὄχλῳ ἀναπεσεῖν ἐπὶ τῆς γῆς. Καὶ λαβὼν τοὺς ἑπτὰ ἄρτους, εὐχαριστήσας ἔκλασεν καὶ ἐδίδου τοῖς μαθηταῖς αὐτοῦ, ἵνα παρατιθῶσιν, καὶ παρέθηκαν τῷ ὄχλῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 7, 'Καὶ εἶχαν ἰχθύδια ὀλίγα· καὶ εὐλογήσας αὐτὰ, εἶπεν καὶ ταῦτα παρατιθέναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 8, 'Καὶ ἔφαγον καὶ ἐχορτάσθησαν, καὶ ἦραν περισσεύματα κλασμάτων ἑπτὰ σπυρίδας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 9, 'Ἦσαν δὲ οἱ φαγόντες ὡς τετρακισχίλιοι. Καὶ ἀπέλυσεν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 10, 'Καὶ εὐθὺς ἐμβὰς εἰς τὸ πλοῖον μετὰ τῶν μαθητῶν αὐτοῦ, ἦλθεν εἰς τὰ μέρη Δαλμανουθά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 11, '¶Καὶ ἐξῆλθον οἱ Φαρισαῖοι καὶ, ἤρξαντο συζητεῖν αὐτῷ, ζητοῦντες παρʼ αὐτοῦ σημεῖον ἀπὸ τοῦ οὐρανοῦ, πειράζοντες αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 12, 'Καὶ ἀναστενάξας τῷ πνεύματι αὐτοῦ λέγει, “Τί ἡ γενεὰ αὕτη ζητεῖ σημεῖον; Ἀμὴν, λέγω ὑμῖν, εἰ δοθήσεται τῇ γενεᾷ ταύτῃ σημεῖον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 13, 'Καὶ ἀφεὶς αὐτοὺς, πάλιν ἐμβὰς ἀπῆλθεν εἰς τὸ πέραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 14, '¶Καὶ ἐπελάθοντο λαβεῖν ἄρτους, καὶ εἰ μὴ ἕνα ἄρτον οὐκ εἶχον μεθʼ ἑαυτῶν ἐν τῷ πλοίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 15, 'Καὶ διεστέλλετο αὐτοῖς λέγων, “Ὁρᾶτε, βλέπετε ἀπὸ τῆς ζύμης τῶν Φαρισαίων καὶ τῆς ζύμης Ἡρῴδου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 16, 'Καὶ διελογίζοντο πρὸς ἀλλήλους, Ὅτι ἄρτους οὐκ ἔχουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 17, 'Καὶ γνοὺς, ὁ  ̊Ἰησοῦς λέγει αὐτοῖς, “Τί διαλογίζεσθε ὅτι ἄρτους οὐκ ἔχετε; Οὔπω νοεῖτε, οὐδὲ συνίετε; Πεπωρωμένην ἔχετε τὴν καρδίαν ὑμῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 18, '‘Ὀφθαλμοὺς ἔχοντες, οὐ βλέπετε; Καὶ ὦτα ἔχοντες, οὐκ ἀκούετε;’ Καὶ οὐ μνημονεύετε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 19, 'Ὅτε τοὺς πέντε ἄρτους ἔκλασα εἰς τοὺς πεντακισχιλίους, πόσους κοφίνους κλασμάτων πλήρεις ἤρατε;” Λέγουσιν αὐτῷ, “Δώδεκα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 20, '“Ὅτε δὲ τοὺς ἑπτὰ εἰς τοὺς τετρακισχιλίους, πόσων σπυρίδων πληρώματα κλασμάτων ἤρατε;” καὶ λέγουσιν “Ἑπτά.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 21, 'Καὶ ἔλεγεν αὐτοῖς, “Πῶς οὔπω συνίετε;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 22, '¶Καὶ ἔρχονται εἰς Βηθσαϊδάν, καὶ φέρουσιν αὐτῷ τυφλὸν, καὶ παρακαλοῦσιν αὐτὸν ἵνα αὐτοῦ ἅψηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 23, 'Καὶ ἐπιλαβόμενος τῆς χειρὸς τοῦ τυφλοῦ, ἐξήνεγκεν αὐτὸν ἔξω τῆς κώμης, καὶ πτύσας εἰς τὰ ὄμματα αὐτοῦ, ἐπιθεὶς τὰς χεῖρας αὐτῷ, ἐπηρώτα αὐτόν, “Εἴ τι βλέπεις;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 24, 'Καὶ ἀναβλέψας ἔλεγεν, “Βλέπω τοὺς ἀνθρώπους, ὅτι ὡς δένδρα ὁρῶ περιπατοῦντας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 25, 'Εἶτα πάλιν ἐπέθηκεν τὰς χεῖρας ἐπὶ τοὺς ὀφθαλμοὺς αὐτοῦ, καὶ διέβλεψεν καὶ ἀπεκατέστη καὶ ἐνέβλεπεν τηλαυγῶς ἅπαντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 26, 'Καὶ ἀπέστειλεν αὐτὸν εἰς οἶκον αὐτοῦ λέγων, “Μηδὲ εἰς τὴν κώμην εἰσέλθῃς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 27, '¶Καὶ ἐξῆλθεν ὁ  ̊Ἰησοῦς καὶ οἱ μαθηταὶ αὐτοῦ εἰς τὰς κώμας Καισαρείας τῆς Φιλίππου. Καὶ ἐν τῇ ὁδῷ ἐπηρώτα τοὺς μαθητὰς αὐτοῦ λέγων αὐτοῖς, “Τίνα με λέγουσιν οἱ ἄνθρωποι εἶναι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 28, 'Οἱ δὲ εἶπαν αὐτῷ λέγοντες, ὅτι “Ἰωάννην τὸν Βαπτιστήν, καὶ ἄλλοι Ἠλίαν, ἄλλοι δὲ ὅτι εἷς τῶν προφητῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 29, 'Καὶ αὐτὸς ἐπηρώτα αὐτούς, “Ὑμεῖς δὲ τίνα με λέγετε εἶναι;” Ἀποκριθεὶς δὲ ὁ Πέτρος λέγει αὐτῷ, “Σὺ εἶ ὁ  ̊Χριστός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 30, 'Καὶ ἐπετίμησεν αὐτοῖς ἵνα μηδενὶ λέγωσιν περὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 31, '¶Καὶ ἤρξατο διδάσκειν αὐτοὺς ὅτι δεῖ τὸν Υἱὸν τοῦ Ἀνθρώπου πολλὰ παθεῖν, καὶ ἀποδοκιμασθῆναι ὑπὸ τῶν πρεσβυτέρων καὶ τῶν ἀρχιερέων καὶ τῶν γραμματέων, καὶ ἀποκτανθῆναι, καὶ μετὰ τρεῖς ἡμέρας ἀναστῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 32, 'Καὶ παρρησίᾳ τὸν λόγον ἐλάλει. Καὶ προσλαβόμενος αὐτὸν, ὁ Πέτρος ἤρξατο ἐπιτιμᾶν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 33, 'Ὁ δὲ, ἐπιστραφεὶς καὶ ἰδὼν τοὺς μαθητὰς αὐτοῦ, ἐπετίμησεν τῷ Πέτρῳ καὶ λέγει, “Ὕπαγε ὀπίσω μου, Σατανᾶ, ὅτι οὐ φρονεῖς τὰ τοῦ  ̊Θεοῦ, ἀλλὰ τὰ τῶν ἀνθρώπων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 34, '¶Καὶ προσκαλεσάμενος τὸν ὄχλον σὺν τοῖς μαθηταῖς αὐτοῦ, εἶπεν αὐτοῖς, “Εἴ τις θέλει ὀπίσω μου ἀκολουθεῖν ἀπαρνησάσθω ἑαυτὸν, καὶ ἀράτω τὸν σταυρὸν αὐτοῦ, καὶ ἀκολουθείτω μοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 35, 'Ὃς γὰρ ἐὰν θέλῃ τὴν ψυχὴν αὐτοῦ σῶσαι, ἀπολέσει αὐτήν, ὃς δʼ ἂν ἀπολέσει τὴν ψυχὴν αὐτοῦ ἕνεκεν ἐμοῦ καὶ τοῦ εὐαγγελίου, σώσει αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 36, 'Τί γὰρ ὠφελεῖ ἄνθρωπον, κερδήσῃ τὸν κόσμον ὅλον καὶ ζημιωθῆναι τὴν ψυχὴν αὐτοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 37, 'Τί γὰρ δώσει ἄνθρωπος ἀντάλλαγμα τῆς ψυχῆς αὐτοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 38, 'Ὃς γὰρ ἐὰν ἐπαισχυνθῇ με καὶ τοὺς ἐμοὺς λόγους ἐν τῇ γενεᾷ ταύτῃ, τῇ μοιχαλίδι καὶ ἁμαρτωλῷ, καὶ ὁ Υἱὸς τοῦ Ἀνθρώπου ἐπαισχυνθήσεται αὐτὸν ὅταν ἔλθῃ ἐν τῇ δόξῃ τοῦ Πατρὸς αὐτοῦ, μετὰ τῶν ἀγγέλων τῶν ἁγίων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 1, 'Καὶ ἔλεγεν αὐτοῖς, “Ἀμὴν, λέγω ὑμῖν ὅτι εἰσίν τινες τῶν ὧδε ἑστηκότων, οἵτινες οὐ μὴ γεύσωνται θανάτου, ἕως ἂν ἴδωσιν τὴν Βασιλείαν τοῦ  ̊Θεοῦ ἐληλυθυῖαν ἐν δυνάμει.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 2, '¶Καὶ μετὰ ἡμέρας ἓξ, παραλαμβάνει ὁ  ̊Ἰησοῦς τὸν Πέτρον, καὶ τὸν Ἰάκωβον, καὶ τὸν Ἰωάννην, καὶ ἀναφέρει αὐτοὺς εἰς ὄρος ὑψηλὸν κατʼ ἰδίαν μόνους. Καὶ μετεμορφώθη ἔμπροσθεν αὐτῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 3, 'καὶ τὰ ἱμάτια αὐτοῦ ἐγένετο στίλβοντα λευκὰ λίαν, οἷα γναφεὺς ἐπὶ τῆς γῆς οὐ δύναται οὕτως λευκᾶναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 4, 'Καὶ ὤφθη αὐτοῖς Ἠλίας σὺν Μωϋσεῖ, καὶ ἦσαν συλλαλοῦντες τῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 5, 'Καὶ ἀποκριθεὶς ὁ Πέτρος λέγει τῷ  ̊Ἰησοῦ, “Ῥαββί, καλόν ἐστιν ἡμᾶς ὧδε εἶναι, καὶ ποιήσωμεν τρεῖς σκηνάς, σοὶ μίαν, καὶ Μωϋσεῖ μίαν, καὶ Ἠλίᾳ μίαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 6, 'Οὐ γὰρ ᾔδει τί ἀποκριθῇ· ἔκφοβοι γὰρ ἐγένοντο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 7, 'Καὶ ἐγένετο νεφέλη ἐπισκιάζουσα αὐτοῖς, καὶ ἐγένετο φωνὴ ἐκ τῆς νεφέλης: “Οὗτός ἐστιν ὁ Υἱός μου, ὁ ἀγαπητός, ἀκούετε αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 8, 'Καὶ ἐξάπινα περιβλεψάμενοι, οὐκέτι οὐδένα εἶδον, εἰ μὴ τὸν  ̊Ἰησοῦν μόνον μεθʼ ἑαυτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 9, '¶Καὶ καταβαινόντων αὐτῶν ἀπὸ τοῦ ὄρους, διεστείλατο αὐτοῖς ἵνα μηδενὶ ἃ εἶδον διηγήσωνται, εἰ μὴ ὅταν ὁ Υἱὸς τοῦ Ἀνθρώπου ἐκ νεκρῶν ἀναστῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 10, 'Καὶ τὸν λόγον ἐκράτησαν πρὸς ἑαυτοὺς, συζητοῦντες τί ἐστιν τὸ ἐκ νεκρῶν ἀναστῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 11, 'Καὶ ἐπηρώτων αὐτὸν λέγοντες, ὅτι “Λέγουσιν Οἱ γραμματεῖς ὅτι Ἠλίαν δεῖ ἐλθεῖν πρῶτον;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 12, 'Ὁ δὲ ἔφη αὐτοῖς, “Ἠλίας μὲν ἐλθὼν πρῶτον ἀποκαθιστάνει πάντα, καὶ πῶς γέγραπται ἐπὶ τὸν Υἱὸν τοῦ Ἀνθρώπου, ἵνα πολλὰ πάθῃ καὶ ἐξουδενηθῇ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 13, 'Ἀλλὰ λέγω ὑμῖν ὅτι καὶ Ἠλίας ἐλήλυθεν, καὶ ἐποίησαν αὐτῷ ὅσα ἤθελον, καθὼς γέγραπται ἐπʼ αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 14, '¶Καὶ ἐλθόντες πρὸς τοὺς μαθητὰς, εἶδεν ὄχλον πολὺν περὶ αὐτοὺς, καὶ γραμματεῖς συζητοῦντας πρὸς αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 15, 'Καὶ εὐθὺς πᾶς ὁ ὄχλος ἰδόντες αὐτὸν ἐξεθαμβήθησαν, καὶ προστρέχοντες ἠσπάζοντο αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 16, 'Καὶ ἐπηρώτησεν αὐτούς, “Τί συζητεῖτε πρὸς αὑτούς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 17, 'Καὶ ἀπεκρίθη αὐτῷ εἷς ἐκ τοῦ ὄχλου, “Διδάσκαλε, ἤνεγκα τὸν υἱόν μου πρὸς σέ, ἔχοντα πνεῦμα ἄλαλον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 18, 'Καὶ ὅπου ἐὰν αὐτὸν καταλάβῃ, ῥήσσει αὐτόν, καὶ ἀφρίζει καὶ τρίζει τοὺς ὀδόντας, καὶ ξηραίνεται. Καὶ εἶπα τοῖς μαθηταῖς σου ἵνα αὐτὸ ἐκβάλωσιν, καὶ οὐκ ἴσχυσαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 19, 'Ὁ δὲ ἀποκριθεὶς αὐτοῖς λέγει, “Ὦ γενεὰ ἄπιστος! Ἕως πότε πρὸς ὑμᾶς ἔσομαι; Ἕως πότε ἀνέξομαι ὑμῶν; Φέρετε αὐτὸν πρός με.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 20, 'Καὶ ἤνεγκαν αὐτὸν πρὸς αὐτόν. Καὶ ἰδὼν αὐτὸν, τὸ πνεῦμα εὐθὺς συνεσπάραξεν αὐτόν, καὶ πεσὼν ἐπὶ τῆς γῆς, ἐκυλίετο ἀφρίζων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 21, 'Καὶ ἐπηρώτησεν τὸν πατέρα αὐτοῦ, “Πόσος χρόνος ἐστὶν, ὡς τοῦτο γέγονεν αὐτῷ;” Ὁ δὲ εἶπεν, “Ἐκ παιδιόθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 22, 'Καὶ πολλάκις καὶ εἰς πῦρ αὐτὸν ἔβαλεν καὶ εἰς ὕδατα, ἵνα ἀπολέσῃ αὐτόν. Ἀλλʼ εἴ τι δύνῃ, βοήθησον ἡμῖν, σπλαγχνισθεὶς ἐφʼ ἡμᾶς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 23, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν αὐτῷ, τὸ “Εἰ δύνῃ; Πάντα δυνατὰ τῷ πιστεύοντι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 24, 'Καὶ εὐθέως κράξας, ὁ πατὴρ τοῦ παιδίου ἔλεγεν, “Πιστεύω, βοήθει μου τῇ ἀπιστίᾳ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 25, 'Ἰδὼν δὲ ὁ  ̊Ἰησοῦς ὅτι ἐπισυντρέχει ὄχλος, ἐπετίμησεν τῷ πνεύματι τῷ ἀκαθάρτῳ λέγων αὐτῷ, “τὸ ἄλαλον καὶ κωφὸν πνεῦμα, ἐγὼ ἐπιτάσσω σοι, ἔξελθε ἐξ αὐτοῦ, καὶ μηκέτι εἰσέλθῃς εἰς αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 26, 'Καὶ κράξας, καὶ πολλὰ σπαράξας, ἐξῆλθεν· καὶ ἐγένετο ὡσεὶ νεκρὸς, ὥστε τοὺς πολλοὺς λέγειν ὅτι ἀπέθανεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 27, 'Ὁ δὲ  ̊Ἰησοῦς κρατήσας τῆς χειρὸς αὐτοῦ, ἤγειρεν αὐτόν, καὶ ἀνέστη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 28, 'Καὶ εἰσελθόντος αὐτοῦ εἰς οἶκον, οἱ μαθηταὶ αὐτοῦ κατʼ ἰδίαν ἐπηρώτων αὐτόν, Ὅτι “Ἡμεῖς οὐκ ἠδυνήθημεν ἐκβαλεῖν αὐτό;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 29, 'Καὶ εἶπεν αὐτοῖς, “Τοῦτο τὸ γένος ἐν οὐδενὶ δύναται ἐξελθεῖν, εἰ μὴ ἐν προσευχῇ καὶ νηστείᾳ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 30, '¶Κἀκεῖθεν ἐξελθόντες, παρεπορεύοντο διὰ τῆς Γαλιλαίας, καὶ οὐκ ἤθελεν ἵνα τις γνοῖ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 31, 'ἐδίδασκεν γὰρ τοὺς μαθητὰς αὐτοῦ, καὶ ἔλεγεν αὐτοῖς, ὅτι “Ὁ Υἱὸς τοῦ Ἀνθρώπου παραδίδοται εἰς χεῖρας ἀνθρώπων, καὶ ἀποκτενοῦσιν αὐτόν, καὶ ἀποκτανθεὶς, μετὰ τρεῖς ἡμέρας ἀναστήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 32, 'Οἱ δὲ ἠγνόουν τὸ ῥῆμα, καὶ ἐφοβοῦντο αὐτὸν ἐπερωτῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 33, '¶Καὶ ἦλθον εἰς Καφαρναούμ. Καὶ ἐν τῇ οἰκίᾳ γενόμενος, ἐπηρώτα αὐτούς, “Τί ἐν τῇ ὁδῷ διελογίζεσθε;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 34, 'Οἱ δὲ ἐσιώπων, πρὸς ἀλλήλους γὰρ διελέχθησαν ἐν τῇ ὁδῷ, τίς μείζων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 35, 'Καὶ καθίσας, ἐφώνησεν τοὺς δώδεκα καὶ λέγει αὐτοῖς, “Εἴ τις θέλει πρῶτος εἶναι, ἔσται πάντων ἔσχατος καὶ πάντων διάκονος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 36, 'Καὶ λαβὼν παιδίον, ἔστησεν αὐτὸ ἐν μέσῳ αὐτῶν, καὶ ἐναγκαλισάμενος αὐτὸ, εἶπεν αὐτοῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 37, '“Ὃς ἂν ἓν τῶν τοιούτων παιδίων δέξηται ἐπὶ τῷ ὀνόματί μου, ἐμὲ δέχεται· καὶ ὃς ἂν ἐμὲ δέξηται, οὐκ ἐμὲ δέχεται, ἀλλὰ τὸν ἀποστείλαντά με.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 38, '¶Ἔφη αὐτῷ ὁ Ἰωάννης, “Διδάσκαλε, εἴδομέν τινα ἐν τῷ ὀνόματί σου ἐκβάλλοντα δαιμόνια, καὶ ἐκωλύομεν αὐτόν, ὅτι οὐκ ἠκολούθει ἡμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 39, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν, “Μὴ κωλύετε αὐτόν, οὐδεὶς γάρ ἐστιν ὃς ποιήσει δύναμιν ἐπὶ τῷ ὀνόματί μου, καὶ δυνήσεται ταχὺ κακολογῆσαί με.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 40, 'Ὃς γὰρ οὐκ ἔστιν καθʼ ἡμῶν, ὑπὲρ ἡμῶν ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 41, 'Ὃς γὰρ ἂν ποτίσῃ ὑμᾶς ποτήριον ὕδατος ἐν ὀνόματι, ὅτι  ̊Χριστοῦ ἐστε, ἀμὴν, λέγω ὑμῖν ὅτι οὐ μὴ ἀπολέσῃ τὸν μισθὸν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 42, '¶Καὶ ὃς ἂν σκανδαλίσῃ ἕνα τῶν μικρῶν τούτων τῶν πιστευόντων εἰς ἐμέ, καλόν ἐστιν αὐτῷ μᾶλλον εἰ περίκειται μύλος ὀνικὸς περὶ τὸν τράχηλον αὐτοῦ, καὶ βέβληται εἰς τὴν θάλασσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 43, 'Καὶ ἐὰν σκανδαλίζῃ σε ἡ χείρ σου, ἀπόκοψον αὐτήν· καλόν ἐστίν σε κυλλὸν εἰσελθεῖν εἰς τὴν ζωὴν, ἢ τὰς δύο χεῖρας ἔχοντα ἀπελθεῖν εἰς τὴν Γέενναν, εἰς τὸ πῦρ τὸ ἄσβεστον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 44, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 45, 'Καὶ ἐὰν ὁ πούς σου σκανδαλίζῃ σε, ἀπόκοψον αὐτόν· καλόν ἐστίν σε εἰσελθεῖν εἰς τὴν ζωὴν χωλὸν, ἢ τοὺς δύο πόδας ἔχοντα βληθῆναι εἰς τὴν Γέενναν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 46, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 47, 'Καὶ ἐὰν ὁ ὀφθαλμός σου σκανδαλίζῃ σε, ἔκβαλε αὐτόν· καλόν σέ ἐστιν μονόφθαλμον εἰσελθεῖν εἰς τὴν Βασιλείαν τοῦ  ̊Θεοῦ, ἢ δύο ὀφθαλμοὺς ἔχοντα βληθῆναι εἰς τὴν Γέενναν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 48, 'ὅπου ‘ὁ σκώληξ αὐτῶν οὐ τελευτᾷ, καὶ τὸ πῦρ οὐ σβέννυται’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 49, '¶Πᾶς γὰρ πυρὶ ἁλισθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 50, 'Καλὸν τὸ ἅλας, ἐὰν δὲ τὸ ἅλας ἄναλον γένηται, ἐν τίνι αὐτὸ ἀρτύσετε; Ἔχετε ἐν ἑαυτοῖς ἅλα, καὶ εἰρηνεύετε ἐν ἀλλήλοις.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 1, '¶Καὶ ἐκεῖθεν ἀναστὰς, ἔρχεται εἰς τὰ ὅρια τῆς Ἰουδαίας, καὶ πέραν τοῦ Ἰορδάνου, καὶ συμπορεύονται πάλιν ὄχλοι πρὸς αὐτόν, καὶ ὡς εἰώθει, πάλιν ἐδίδασκεν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 2, '¶Καὶ προσελθόντες, Φαρισαῖοι ἐπηρώτων αὐτὸν, “Εἰ ἔξεστιν ἀνδρὶ γυναῖκα ἀπολῦσαι;” Πειράζοντες αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 3, 'Ὁ δὲ ἀποκριθεὶς εἶπεν αὐτοῖς, “Τί ὑμῖν ἐνετείλατο Μωϋσῆς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 4, 'Οἱ δὲ εἶπαν, “Ἐπέτρεψεν Μωϋσῆς ‘βιβλίον ἀποστασίου γράψαι καὶ ἀπολῦσαι’.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 5, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Πρὸς τὴν σκληροκαρδίαν ὑμῶν, ἔγραψεν ὑμῖν τὴν ἐντολὴν ταύτην·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 6, 'ἀπὸ δὲ ἀρχῆς κτίσεως, ‘ἄρσεν καὶ θῆλυ ἐποίησεν αὐτούς’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 7, '‘Ἕνεκεν τούτου καταλείψει ἄνθρωπος τὸν πατέρα αὐτοῦ καὶ τὴν μητέρα, καὶ προσκολληθήσεται γυναῖκα αὑτοῦ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 8, 'καὶ ἔσονται οἱ δύο εἰς σάρκα μίαν’. Ὥστε οὐκέτι εἰσὶν δύο, ἀλλὰ μία σάρξ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 9, 'Ὃ οὖν ὁ  ̊Θεὸς συνέζευξεν, ἄνθρωπος μὴ χωριζέτω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 10, '¶Καὶ εἰς τὴν οἰκίαν πάλιν, οἱ μαθηταὶ περὶ τούτου ἐπηρώτων αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 11, 'Καὶ λέγει αὐτοῖς, “Ὃς ἂν ἀπολύσῃ τὴν γυναῖκα αὐτοῦ, καὶ γαμήσῃ ἄλλην, μοιχᾶται ἐπʼ αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 12, 'Καὶ ἐὰν αὐτὴ ἀπολύσασα τὸν ἄνδρα αὐτῆς, γαμήσῃ ἄλλον, μοιχᾶται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 13, '¶Καὶ προσέφερον αὐτῷ παιδία, ἵνα αὐτῶν ἅψηται· οἱ δὲ μαθηταὶ ἐπετίμησαν αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 14, 'Ἰδὼν δὲ, ὁ  ̊Ἰησοῦς ἠγανάκτησεν καὶ εἶπεν αὐτοῖς, “Ἄφετε τὰ παιδία ἔρχεσθαι πρός με, καὶ μὴ κωλύετε αὐτά, τῶν γὰρ τοιούτων ἐστὶν ἡ Βασιλεία τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 15, 'Ἀμὴν, λέγω ὑμῖν, ὃς ἂν μὴ δέξηται τὴν Βασιλείαν τοῦ  ̊Θεοῦ ὡς παιδίον, οὐ μὴ εἰσέλθῃ εἰς αὐτήν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 16, 'Καὶ ἐναγκαλισάμενος αὐτὰ, κατευλόγει τιθεὶς τὰς χεῖρας ἐπʼ αὐτά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 17, '¶Καὶ ἐκπορευομένου αὐτοῦ εἰς ὁδὸν, προσδραμὼν εἷς καὶ γονυπετήσας αὐτὸν, ἐπηρώτα αὐτόν, “Διδάσκαλε ἀγαθέ, τί ποιήσω, ἵνα ζωὴν αἰώνιον κληρονομήσω;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 18, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν αὐτῷ, “Τί με λέγεις ἀγαθόν; Οὐδεὶς ἀγαθὸς, εἰ μὴ εἷς ὁ  ̊Θεός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 19, 'Τὰς ἐντολὰς οἶδας: ‘μὴ φονεύσῃς, μὴ μοιχεύσῃς, μὴ κλέψῃς, μὴ ψευδομαρτυρήσῃς’, μὴ ἀποστερήσῃς, ‘Τίμα τὸν πατέρα σου καὶ τὴν μητέρα.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 20, 'Ὁ δὲ ἔφη αὐτῷ, “Διδάσκαλε, ταῦτα πάντα ἐφυλαξάμην ἐκ νεότητός μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 21, 'Ὁ δὲ  ̊Ἰησοῦς ἐμβλέψας αὐτῷ, ἠγάπησεν αὐτὸν καὶ εἶπεν αὐτῷ, “Ἕν σε ὑστερεῖ: ὕπαγε, ὅσα ἔχεις πώλησον, καὶ δὸς πτωχοῖς, καὶ ἕξεις θησαυρὸν ἐν οὐρανῷ, καὶ δεῦρο, ἀκολούθει μοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 22, 'Ὁ δὲ, στυγνάσας ἐπὶ τῷ λόγῳ, ἀπῆλθεν λυπούμενος, ἦν γὰρ ἔχων κτήματα πολλά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 23, '¶Καὶ περιβλεψάμενος, ὁ  ̊Ἰησοῦς λέγει τοῖς μαθηταῖς αὐτοῦ, “Πῶς δυσκόλως οἱ τὰ χρήματα ἔχοντες, εἰς τὴν Βασιλείαν τοῦ  ̊Θεοῦ εἰσελεύσονται!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 24, 'Οἱ δὲ μαθηταὶ ἐθαμβοῦντο ἐπὶ τοῖς λόγοις αὐτοῦ. Ὁ δὲ  ̊Ἰησοῦς πάλιν ἀποκριθεὶς λέγει αὐτοῖς, “Τέκνα, πῶς δύσκολόν ἐστιν εἰς τὴν Βασιλείαν τοῦ  ̊Θεοῦ εἰσελθεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 25, 'Εὐκοπώτερόν ἐστιν κάμηλον διὰ τρυμαλιᾶς ῥαφίδος διελθεῖν, ἢ πλούσιον εἰς τὴν Βασιλείαν τοῦ  ̊Θεοῦ εἰσελθεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 26, 'Οἱ δὲ περισσῶς ἐξεπλήσσοντο, λέγοντες πρὸς αὐτόν, “Καὶ τίς δύναται σωθῆναι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 27, 'Ἐμβλέψας αὐτοῖς, ὁ  ̊Ἰησοῦς λέγει, “Παρὰ ἀνθρώποις ἀδύνατον, ἀλλʼ οὐ παρὰ  ̊Θεῷ, πάντα γὰρ δυνατὰ παρὰ τῷ  ̊Θεῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 28, '¶Ἤρξατο λέγειν ὁ Πέτρος αὐτῷ, “Ἰδοὺ, ἡμεῖς ἀφήκαμεν πάντα καὶ ἠκολουθήκαμέν σοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 29, 'Ἔφη ὁ  ̊Ἰησοῦς, “Ἀμὴν, λέγω ὑμῖν, οὐδείς ἐστιν ὃς ἀφῆκεν οἰκίαν, ἢ ἀδελφοὺς, ἢ ἀδελφὰς, ἢ μητέρα, ἢ πατέρα, ἢ τέκνα, ἢ ἀγροὺς, ἕνεκεν ἐμοῦ καὶ τοῦ εὐαγγελίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 30, 'ἐὰν μὴ λάβῃ ἑκατονταπλασίονα νῦν ἐν τῷ καιρῷ τούτῳ, οἰκίας, καὶ ἀδελφοὺς, καὶ ἀδελφὰς, καὶ μητέρας, καὶ τέκνα, καὶ ἀγροὺς, μετὰ διωγμῶν, καὶ ἐν τῷ αἰῶνι τῷ ἐρχομένῳ, ζωὴν αἰώνιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 31, 'Πολλοὶ δὲ ἔσονται πρῶτοι ἔσχατοι, καὶ ἔσχατοι πρῶτοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 32, '¶Ἦσαν δὲ ἐν τῇ ὁδῷ ἀναβαίνοντες εἰς Ἱεροσόλυμα, καὶ ἦν προάγων αὐτοὺς ὁ  ̊Ἰησοῦς, καὶ ἐθαμβοῦντο, οἱ δὲ ἀκολουθοῦντες ἐφοβοῦντο. Καὶ παραλαβὼν πάλιν τοὺς δώδεκα, ἤρξατο αὐτοῖς λέγειν τὰ μέλλοντα αὐτῷ συμβαίνειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 33, 'Ὅτι “Ἰδοὺ, ἀναβαίνομεν εἰς Ἱεροσόλυμα, καὶ ὁ Υἱὸς τοῦ Ἀνθρώπου παραδοθήσεται τοῖς ἀρχιερεῦσιν καὶ τοῖς γραμματεῦσιν, καὶ κατακρινοῦσιν αὐτὸν θανάτῳ, καὶ παραδώσουσιν αὐτὸν τοῖς ἔθνεσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 34, 'Καὶ ἐμπαίξουσιν αὐτῷ, καὶ ἐμπτύσουσιν αὐτῷ, καὶ μαστιγώσουσιν αὐτὸν, καὶ ἀποκτενοῦσιν, καὶ μετὰ τρεῖς ἡμέρας ἀναστήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 35, '¶Καὶ προσπορεύονται αὐτῷ Ἰάκωβος καὶ Ἰωάννης, οἱ δύο υἱοὶ Ζεβεδαίου, λέγοντες αὐτῷ, “Διδάσκαλε, θέλομεν ἵνα ὃ ἐὰν αἰτήσωμέν σε, ποιήσῃς ἡμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 36, 'Ὁ δὲ εἶπεν αὐτοῖς, “Τί θέλετε με ποιήσω ὑμῖν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 37, 'Οἱ δὲ εἶπαν αὐτῷ, “Δὸς ἡμῖν, ἵνα εἷς σου ἐκ δεξιῶν, καὶ εἷς ἐξ εὐωνύμων καθίσωμεν ἐν τῇ δόξῃ σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 38, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Οὐκ οἴδατε τί αἰτεῖσθε. Δύνασθε πιεῖν τὸ ποτήριον ὃ ἐγὼ πίνω, ἢ τὸ βάπτισμα ὃ ἐγὼ βαπτίζομαι βαπτισθῆναι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 39, 'Οἱ δὲ εἶπαν αὐτῷ, “Δυνάμεθα.” Ὁ δὲ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Τὸ ποτήριον ὃ ἐγὼ πίνω, πίεσθε, καὶ τὸ βάπτισμα ὃ ἐγὼ βαπτίζομαι, βαπτισθήσεσθε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 40, 'τὸ δὲ καθίσαι ἐκ δεξιῶν μου ἢ ἐξ εὐωνύμων, οὐκ ἔστιν ἐμὸν δοῦναι, ἀλλʼ οἷς ἡτοίμασται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 41, '¶Καὶ ἀκούσαντες, οἱ δέκα ἤρξαντο ἀγανακτεῖν περὶ Ἰακώβου καὶ Ἰωάννου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 42, 'Καὶ προσκαλεσάμενος αὐτοὺς ὁ  ̊Ἰησοῦς λέγει αὐτοῖς, “Οἴδατε ὅτι οἱ δοκοῦντες ἄρχειν τῶν ἐθνῶν κατακυριεύουσιν αὐτῶν, καὶ οἱ μεγάλοι αὐτῶν κατεξουσιάζουσιν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 43, 'Οὐχ οὕτως δέ ἐστιν ἐν ὑμῖν· ἀλλʼ ὃς ἂν θέλῃ μέγας γενέσθαι ἐν ὑμῖν, ἔσται ὑμῶν διάκονος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 44, 'καὶ ὃς ἂν θέλῃ ἐν ὑμῖν εἶναι πρῶτος, ἔσται πάντων δοῦλος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 45, 'Καὶ γὰρ ὁ Υἱὸς τοῦ Ἀνθρώπου οὐκ ἦλθεν διακονηθῆναι, ἀλλὰ διακονῆσαι, καὶ δοῦναι τὴν ψυχὴν αὐτοῦ λύτρον ἀντὶ πολλῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 46, '¶Καὶ ἔρχονται εἰς Ἰεριχώ. Καὶ ἐκπορευομένου αὐτοῦ ἀπὸ Ἰεριχὼ, καὶ τῶν μαθητῶν αὐτοῦ, καὶ ὄχλου ἱκανοῦ, ὁ υἱὸς Τιμαίου, Βαρτιμαῖος, τυφλὸς προσαίτης, ἐκάθητο παρὰ τὴν ὁδόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 47, 'Καὶ ἀκούσας ὅτι  ̊Ἰησοῦς ὁ Ναζωραῖός ἐστιν, ἤρξατο κράζειν καὶ λέγειν, “Υἱὲ Δαυὶδ,  ̊Ἰησοῦ, ἐλέησόν με.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 48, 'Καὶ ἐπετίμων αὐτῷ πολλοὶ ἵνα σιωπήσῃ· ὁ δὲ πολλῷ μᾶλλον ἔκραζεν, “Υἱὲ Δαυίδ, ἐλέησόν με.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 49, 'Καὶ στὰς, ὁ  ̊Ἰησοῦς εἶπεν, “Φωνήσατε αὐτόν.” Καὶ φωνοῦσι τὸν τυφλὸν, λέγοντες αὐτῷ, “Θάρσει, ἔγειρε, φωνεῖ σε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 50, 'Ὁ δὲ, ἀποβαλὼν τὸ ἱμάτιον αὐτοῦ ἀναπηδήσας, ἦλθεν πρὸς τὸν  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 51, 'Καὶ ἀποκριθεὶς αὐτῷ ὁ  ̊Ἰησοῦς εἶπεν, “Τί σοι θέλεις ποιήσω;” Ὁ δὲ τυφλὸς εἶπεν αὐτῷ, “Ῥαββουνί, ἵνα ἀναβλέψω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 52, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν αὐτῷ, “Ὕπαγε, ἡ πίστις σου σέσωκέν σε.” Καὶ εὐθὺς ἀνέβλεψεν, καὶ ἠκολούθει αὐτῷ ἐν τῇ ὁδῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 1, '¶Καὶ ὅτε ἐγγίζουσιν εἰς Ἱεροσόλυμα, εἰς Βηθφαγὴ καὶ Βηθανίαν πρὸς τὸ Ὄρος τῶν Ἐλαιῶν, ἀποστέλλει δύο τῶν μαθητῶν αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 2, 'καὶ λέγει αὐτοῖς, “Ὑπάγετε εἰς τὴν κώμην τὴν κατέναντι ὑμῶν, καὶ εὐθὺς εἰσπορευόμενοι εἰς αὐτὴν, εὑρήσετε πῶλον δεδεμένον ἐφʼ ὃν οὐδεὶς ἀνθρώπων οὔπω ἐκάθισεν· λύσατε αὐτὸν καὶ φέρετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 3, 'Καὶ ἐάν τις ὑμῖν εἴπῃ, ‘Τί ποιεῖτε τοῦτο;’ Εἴπατε, ὅτι ‘Ὁ  ̊Κύριος αὐτοῦ χρείαν ἔχει’, καὶ εὐθὺς αὐτὸν ἀποστέλλει πάλιν ὧδε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 4, 'Καὶ ἀπῆλθον, καὶ εὗρον πῶλον δεδεμένον πρὸς τὴν θύραν ἔξω ἐπὶ τοῦ ἀμφόδου, καὶ λύουσιν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 5, 'Καί τινες τῶν ἐκεῖ ἑστηκότων ἔλεγον αὐτοῖς, “Τί ποιεῖτε λύοντες τὸν πῶλον;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 6, 'Οἱ δὲ εἶπον αὐτοῖς καθὼς εἶπεν ὁ  ̊Ἰησοῦς, καὶ ἀφῆκαν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 7, 'Καὶ ἄγουσιν τὸν πῶλον πρὸς τὸν  ̊Ἰησοῦν, καὶ ἐπιβάλλουσιν αὐτῷ τὰ ἱμάτια αὐτῶν, καὶ ἐκάθισεν ἐπʼ αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 8, 'Καὶ πολλοὶ τὰ ἱμάτια αὐτῶν ἔστρωσαν εἰς τὴν ὁδόν, ἄλλοι δὲ στιβάδας κόψαντες ἐκ τῶν ἀγρῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 9, 'Καὶ οἱ προάγοντες καὶ οἱ ἀκολουθοῦντες ἔκραζον, “Ὡσαννά! ‘Εὐλογημένος ὁ ἐρχόμενος ἐν ὀνόματι  ̊Κυρίου!’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 10, 'Εὐλογημένη ἡ ἐρχομένη βασιλεία τοῦ πατρὸς ἡμῶν, Δαυίδ! Ὡσαννὰ ἐν τοῖς ὑψίστοις!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 11, '¶Καὶ εἰσῆλθεν εἰς Ἱεροσόλυμα, εἰς τὸ ἱερόν· καὶ περιβλεψάμενος πάντα, ὀψίας ἤδη οὔσης τῆς ὥρας, ἐξῆλθεν εἰς Βηθανίαν μετὰ τῶν δώδεκα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 12, '¶Καὶ τῇ ἐπαύριον, ἐξελθόντων αὐτῶν ἀπὸ Βηθανίας, ἐπείνασεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 13, 'Καὶ ἰδὼν συκῆν ἀπὸ μακρόθεν ἔχουσαν φύλλα, ἦλθεν εἰ ἄρα τι εὑρήσει ἐν αὐτῇ, καὶ ἐλθὼν ἐπʼ αὐτὴν, οὐδὲν εὗρεν εἰ μὴ φύλλα, ὁ γὰρ καιρὸς οὐκ ἦν σύκων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 14, 'Καὶ ἀποκριθεὶς εἶπεν αὐτῇ, “Μηκέτι εἰς τὸν αἰῶνα, ἐκ σοῦ μηδεὶς καρπὸν φάγοι.” Καὶ ἤκουον οἱ μαθηταὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 15, '¶Καὶ ἔρχονται εἰς Ἱεροσόλυμα, καὶ εἰσελθὼν εἰς τὸ ἱερὸν, ἤρξατο ἐκβάλλειν τοὺς πωλοῦντας καὶ τοὺς ἀγοράζοντας ἐν τῷ ἱερῷ, καὶ τὰς τραπέζας τῶν κολλυβιστῶν καὶ τὰς καθέδρας τῶν πωλούντων τὰς περιστερὰς κατέστρεψεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 16, 'Καὶ οὐκ ἤφιεν ἵνα τις διενέγκῃ σκεῦος διὰ τοῦ ἱεροῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 17, 'Καὶ ἐδίδασκεν καὶ ἔλεγεν αὐτοῖς, “Οὐ γέγραπται, ὅτι ‘Ὁ οἶκός μου, οἶκος προσευχῆς κληθήσεται πᾶσιν τοῖς ἔθνεσιν’; Ὑμεῖς δὲ ἐποιήσατε αὐτὸν ‘σπήλαιον λῃστῶν’.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 18, 'Καὶ ἤκουσαν οἱ ἀρχιερεῖς καὶ οἱ γραμματεῖς, καὶ ἐζήτουν πῶς αὐτὸν ἀπολέσωσιν· ἐφοβοῦντο γὰρ αὐτόν, πᾶς γὰρ ὁ ὄχλος ἐξεπλήσσετο ἐπὶ τῇ διδαχῇ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 19, 'Καὶ ὅταν ὀψὲ ἐγένετο, ἐξεπορεύοντο ἔξω τῆς πόλεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 20, '¶Καὶ παραπορευόμενοι πρωῒ, εἶδον τὴν συκῆν ἐξηραμμένην ἐκ ῥιζῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 21, 'Καὶ ἀναμνησθεὶς ὁ Πέτρος λέγει αὐτῷ, “Ῥαββί, ἴδε, ἡ συκῆ ἣν κατηράσω ἐξήρανται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 22, 'Καὶ ἀποκριθεὶς ὁ  ̊Ἰησοῦς λέγει αὐτοῖς, “Ἔχετε πίστιν  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 23, 'Ἀμὴν, λέγω ὑμῖν ὅτι ὃς ἂν εἴπῃ τῷ ὄρει τούτῳ, ‘Ἄρθητι καὶ βλήθητι εἰς τὴν θάλασσαν’, καὶ μὴ διακριθῇ ἐν τῇ καρδίᾳ αὐτοῦ, ἀλλὰ πιστεύῃ ὅτι ὃ λαλεῖ γίνεται, ἔσται αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 24, 'Διὰ τοῦτο λέγω ὑμῖν, πάντα ὅσα προσεύχεσθε καὶ αἰτεῖσθε, πιστεύετε ὅτι ἐλάβετε, καὶ ἔσται ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 25, 'Καὶ ὅταν στήκητε προσευχόμενοι, ἀφίετε εἴ τι ἔχετε κατά τινος, ἵνα καὶ ὁ Πατὴρ ὑμῶν, ὁ ἐν τοῖς οὐρανοῖς, ἀφῇ ὑμῖν τὰ παραπτώματα ὑμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 26, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 27, '¶Καὶ ἔρχονται πάλιν εἰς Ἱεροσόλυμα, καὶ ἐν τῷ ἱερῷ περιπατοῦντος αὐτοῦ, ἔρχονται πρὸς αὐτὸν οἱ ἀρχιερεῖς, καὶ οἱ γραμματεῖς, καὶ οἱ πρεσβύτεροι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 28, 'Καὶ ἔλεγον αὐτῷ, “Ἐν ποίᾳ ἐξουσίᾳ ταῦτα ποιεῖς; Ἢ τίς σοι ἔδωκεν τὴν ἐξουσίαν ταύτην, ἵνα ταῦτα ποιῇς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 29, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Ἐπερωτήσω ὑμᾶς κἀγὼ ἕνα λόγον, καὶ ἀποκρίθητέ μοι, καὶ ἐρῶ ὑμῖν ἐν ποίᾳ ἐξουσίᾳ ταῦτα ποιῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 30, 'Τὸ βάπτισμα τὸ Ἰωάννου, ἐξ οὐρανοῦ ἦν ἢ ἐξ ἀνθρώπων; Ἀποκρίθητέ μοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 31, 'Καὶ διελογίζοντο πρὸς ἑαυτοὺς λέγοντες, ἐὰν εἴπωμεν, ‘Ἐξ οὐρανοῦ’, ἐρεῖ, ‘Διὰ τί οὖν οὐκ ἐπιστεύσατε αὐτῷ;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 32, 'Ἀλλὰ εἴπωμεν, ‘Ἐξ ἀνθρώπων’;” (Ἐφοβοῦντο τὸν ὄχλον, ἅπαντες γὰρ εἶχον τὸν Ἰωάννην ὄντως ὅτι προφήτης ἦν.)');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 33, 'Καὶ ἀποκριθέντες τῷ  ̊Ἰησοῦ λέγουσιν, “Οὐκ οἴδαμεν.” Καὶ ὁ  ̊Ἰησοῦς λέγει αὐτοῖς, “Οὐδὲ ἐγὼ λέγω ὑμῖν ἐν ποίᾳ ἐξουσίᾳ ταῦτα ποιῶ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 1, '¶Καὶ ἤρξατο αὐτοῖς ἐν παραβολαῖς λαλεῖν: “Ἀμπελῶνα ἄνθρωπος ἐφύτευσεν, καὶ περιέθηκεν φραγμὸν, καὶ ‘ὤρυξεν ὑπολήνιον, καὶ ᾠκοδόμησεν πύργον’, καὶ ἐξέδετο αὐτὸν γεωργοῖς, καὶ ἀπεδήμησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 2, 'Καὶ ἀπέστειλεν πρὸς τοὺς γεωργοὺς τῷ καιρῷ δοῦλον, ἵνα παρὰ τῶν γεωργῶν λάβῃ ἀπὸ τῶν καρπῶν τοῦ ἀμπελῶνος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 3, 'Καὶ λαβόντες αὐτὸν, ἔδειραν καὶ ἀπέστειλαν κενόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 4, 'Καὶ πάλιν ἀπέστειλεν πρὸς αὐτοὺς ἄλλον δοῦλον, κἀκεῖνον ἐκεφαλίωσαν καὶ ἠτίμασαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 5, 'Καὶ ἄλλον ἀπέστειλεν, κἀκεῖνον ἀπέκτειναν, καὶ πολλοὺς ἄλλους, οὓς μὲν δέροντες, οὓς δὲ ἀποκτέννοντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 6, 'Ἔτι ἕνα εἶχεν υἱὸν ἀγαπητόν, ἀπέστειλεν αὐτὸν ἔσχατον πρὸς αὐτοὺς λέγων, ὅτι ‘Ἐντραπήσονται τὸν υἱόν μου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 7, 'Ἐκεῖνοι δὲ οἱ γεωργοὶ πρὸς ἑαυτοὺς εἶπαν, ὅτι ‘Οὗτός ἐστιν ὁ κληρονόμος· δεῦτε, ἀποκτείνωμεν αὐτόν, καὶ ἡμῶν ἔσται ἡ κληρονομία.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 8, 'Καὶ λαβόντες, ἀπέκτειναν αὐτόν, καὶ ἐξέβαλον αὐτὸν ἔξω τοῦ ἀμπελῶνος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 9, 'Τί οὖν ποιήσει ὁ κύριος τοῦ ἀμπελῶνος; Ἐλεύσεται καὶ ἀπολέσει τοὺς γεωργούς, καὶ δώσει τὸν ἀμπελῶνα ἄλλοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 10, 'Οὐδὲ τὴν Γραφὴν ταύτην ἀνέγνωτε: ‘Λίθον ὃν ἀπεδοκίμασαν οἱ οἰκοδομοῦντες, οὗτος ἐγενήθη εἰς κεφαλὴν γωνίας·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 11, 'παρὰ  ̊Κυρίου ἐγένετο αὕτη, καὶ ἔστιν θαυμαστὴ ἐν ὀφθαλμοῖς ἡμῶν’;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 12, '¶Καὶ ἐζήτουν αὐτὸν κρατῆσαι, καὶ ἐφοβήθησαν τὸν ὄχλον, ἔγνωσαν γὰρ ὅτι πρὸς αὐτοὺς τὴν παραβολὴν εἶπεν. Καὶ ἀφέντες αὐτὸν, ἀπῆλθον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 13, '¶Καὶ ἀποστέλλουσιν πρὸς αὐτόν τινας τῶν Φαρισαίων καὶ τῶν Ἡρῳδιανῶν, ἵνα αὐτὸν ἀγρεύσωσιν λόγῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 14, 'Καὶ ἐλθόντες, λέγουσιν αὐτῷ, “Διδάσκαλε, οἴδαμεν ὅτι ἀληθὴς εἶ, καὶ οὐ μέλει σοι περὶ οὐδενός, οὐ γὰρ βλέπεις εἰς πρόσωπον ἀνθρώπων, ἀλλʼ ἐπʼ ἀληθείας τὴν ὁδὸν τοῦ  ̊Θεοῦ διδάσκεις. Ἔξεστιν δοῦναι κῆνσον Καίσαρι ἢ οὔ; Δῶμεν ἢ μὴ δῶμεν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 15, 'Ὁ δὲ εἰδὼς αὐτῶν τὴν ὑπόκρισιν, εἶπεν αὐτοῖς, “Τί με πειράζετε; Φέρετέ μοι δηνάριον, ἵνα ἴδω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 16, 'Οἱ δὲ ἤνεγκαν. Καὶ λέγει αὐτοῖς, “Τίνος ἡ εἰκὼν αὕτη καὶ ἡ ἐπιγραφή;” Οἱ δὲ εἶπαν αὐτῷ, “Καίσαρος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 17, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Τὰ Καίσαρος ἀπόδοτε Καίσαρι, καὶ τὰ τοῦ  ̊Θεοῦ τῷ  ̊Θεῷ.” Καὶ ἐξεθαύμαζον ἐπʼ αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 18, '¶Καὶ ἔρχονται Σαδδουκαῖοι πρὸς αὐτόν, οἵτινες λέγουσιν ἀνάστασιν μὴ εἶναι, καὶ ἐπηρώτων αὐτὸν λέγοντες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 19, '“Διδάσκαλε, Μωϋσῆς ἔγραψεν ἡμῖν, ὅτι ἐάν ‘Τινος ἀδελφὸς ἀποθάνῃ, καὶ καταλίπῃ γυναῖκα καὶ μὴ ἀφῇ τέκνα, ἵνα λάβῃ ὁ ἀδελφὸς αὐτοῦ τὴν γυναῖκα, καὶ ἐξαναστήσῃ σπέρμα τῷ ἀδελφῷ αὐτοῦ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 20, 'Ἑπτὰ ἀδελφοὶ ἦσαν· καὶ ὁ πρῶτος ἔλαβεν γυναῖκα, καὶ ἀποθνῄσκων, οὐκ ἀφῆκεν σπέρμα·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 21, 'καὶ ὁ δεύτερος ἔλαβεν αὐτήν, καὶ ἀπέθανεν, μὴ καταλιπὼν σπέρμα, καὶ ὁ τρίτος ὡσαύτως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 22, 'Καὶ οἱ ἑπτὰ, οὐκ ἀφῆκαν σπέρμα. Ἔσχατον πάντων καὶ, ἡ γυνὴ ἀπέθανεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 23, 'Ἐν τῇ ἀναστάσει, τίνος αὐτῶν ἔσται γυνή; Οἱ γὰρ ἑπτὰ ἔσχον αὐτὴν γυναῖκα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 24, 'Ἔφη αὐτοῖς ὁ  ̊Ἰησοῦς, “Οὐ διὰ τοῦτο πλανᾶσθε, μὴ εἰδότες τὰς Γραφὰς, μηδὲ τὴν δύναμιν τοῦ  ̊Θεοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 25, 'Ὅταν γὰρ ἐκ νεκρῶν ἀναστῶσιν, οὔτε γαμοῦσιν οὔτε γαμίζονται, ἀλλʼ εἰσὶν ὡς ἄγγελοι ἐν τοῖς οὐρανοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 26, 'Περὶ δὲ τῶν νεκρῶν, ὅτι ἐγείρονται, οὐκ ἀνέγνωτε ἐν τῇ βίβλῳ Μωϋσέως ἐπὶ τοῦ βάτου, πῶς εἶπεν αὐτῷ ὁ  ̊Θεὸς λέγων, ‘Ἐγὼ ὁ  ̊Θεὸς Ἀβραὰμ, καὶ  ̊Θεὸς Ἰσαὰκ, καὶ ὁ  ̊Θεὸς Ἰακώβ’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 27, 'Οὐκ ἔστιν  ̊Θεὸς νεκρῶν, ἀλλὰ ζώντων. Πολὺ πλανᾶσθε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 28, '¶Καὶ προσελθὼν εἷς τῶν γραμματέων, ἀκούσας αὐτῶν συζητούντων, ἰδὼν ὅτι καλῶς ἀπεκρίθη αὐτοῖς, ἐπηρώτησεν αὐτόν, “Ποία ἐστὶν ἐντολὴ πρώτη πάντων;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 29, 'ἀπεκρίθη ὁ  ̊Ἰησοῦς, ὅτι “Πρώτη ἐστίν: ‘Ἄκουε, Ἰσραήλ,  ̊Κύριος ὁ  ̊Θεὸς ἡμῶν  ̊Κύριος εἷς ἐστιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 30, 'καὶ ἀγαπήσεις  ̊Κύριον τὸν  ̊Θεόν σου, ἐξ ὅλης τῆς καρδίας σου, καὶ ἐξ ὅλης τῆς ψυχῆς σου, καὶ ἐξ ὅλης τῆς διανοίας σου, καὶ ἐξ ὅλης τῆς ἰσχύος σου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 31, 'Δευτέρα αὕτη: ‘Ἀγαπήσεις τὸν πλησίον σου ὡς σεαυτόν.’ Μείζων τούτων ἄλλη ἐντολὴ οὐκ ἔστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 32, 'Καὶ εἶπεν αὐτῷ ὁ γραμματεύς, “Καλῶς, Διδάσκαλε, ἐπʼ ἀληθείας εἶπας, ὅτι ‘Εἷς ἐστιν, καὶ οὐκ ἔστιν ἄλλος πλὴν αὐτοῦ’,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 33, 'καὶ, τὸ ‘Ἀγαπᾶν αὐτὸν ἐξ ὅλης τῆς καρδίας, καὶ ἐξ ὅλης τῆς συνέσεως, καὶ ἐξ ὅλης τῆς ἰσχύος’, καὶ, τὸ ‘Ἀγαπᾶν τὸν πλησίον ὡς ἑαυτὸν’, περισσότερόν ἐστιν πάντων τῶν ὁλοκαυτωμάτων καὶ θυσιῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 34, 'Καὶ ὁ  ̊Ἰησοῦς, ἰδὼν αὐτὸν, ὅτι νουνεχῶς ἀπεκρίθη, εἶπεν αὐτῷ, “Οὐ μακρὰν εἶ ἀπὸ τῆς Βασιλείας τοῦ  ̊Θεοῦ.” Καὶ οὐδεὶς οὐκέτι ἐτόλμα αὐτὸν ἐπερωτῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 35, '¶Καὶ ἀποκριθεὶς ὁ  ̊Ἰησοῦς ἔλεγεν διδάσκων ἐν τῷ ἱερῷ, “Πῶς λέγουσιν οἱ γραμματεῖς ὅτι ὁ  ̊Χριστὸς, υἱὸς Δαυίδ ἐστιν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 36, 'Αὐτὸς Δαυὶδ εἶπεν ἐν τῷ  ̊Πνεύματι τῷ ἁγίῳ, ‘Εἶπεν ὁ  ̊Κύριος τῷ  ̊Κυρίῳ μου, “Κάθου ἐκ δεξιῶν μου, ἕως ἂν θῶ τοὺς ἐχθρούς σου ὑποκάτω τῶν ποδῶν σου.”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 37, 'Αὐτὸς Δαυὶδ λέγει αὐτὸν, ‘ ̊Κύριον’, καὶ πόθεν υἱός αὐτοῦ ἐστιν;” Καὶ ὁ πολὺς ὄχλος ἤκουεν αὐτοῦ ἡδέως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 38, '¶Καὶ ἐν τῇ διδαχῇ αὐτοῦ, ἔλεγεν, “Βλέπετε ἀπὸ τῶν γραμματέων, τῶν θελόντων ἐν στολαῖς περιπατεῖν, καὶ ἀσπασμοὺς ἐν ταῖς ἀγοραῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 39, 'καὶ πρωτοκαθεδρίας ἐν ταῖς συναγωγαῖς, καὶ πρωτοκλισίας ἐν τοῖς δείπνοις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 40, 'οἱ κατεσθίοντες τὰς οἰκίας τῶν χηρῶν, καὶ προφάσει μακρὰ προσευχόμενοι. Οὗτοι λήμψονται περισσότερον κρίμα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 41, '¶Καὶ καθίσας κατέναντι τοῦ γαζοφυλακίου, ἐθεώρει πῶς ὁ ὄχλος βάλλει χαλκὸν εἰς τὸ γαζοφυλάκιον· καὶ πολλοὶ πλούσιοι ἔβαλλον πολλά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 42, 'Καὶ ἐλθοῦσα μία χήρα πτωχὴ ἔβαλεν λεπτὰ δύο, ὅ ἐστιν κοδράντης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 43, 'Καὶ προσκαλεσάμενος τοὺς μαθητὰς αὐτοῦ, εἶπεν αὐτοῖς, “Ἀμὴν, λέγω ὑμῖν ὅτι ἡ χήρα αὕτη ἡ πτωχὴ, πλεῖον πάντων ἔβαλεν τῶν βαλλόντων εἰς τὸ γαζοφυλάκιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 44, 'Πάντες γὰρ ἐκ τοῦ περισσεύοντος αὐτοῖς ἔβαλον, αὕτη δὲ ἐκ τῆς ὑστερήσεως αὐτῆς πάντα ὅσα εἶχεν ἔβαλεν, ὅλον τὸν βίον αὐτῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 1, '¶Καὶ ἐκπορευομένου αὐτοῦ ἐκ τοῦ ἱεροῦ, λέγει αὐτῷ εἷς τῶν μαθητῶν αὐτοῦ, “Διδάσκαλε, ἴδε, ποταποὶ λίθοι καὶ ποταπαὶ οἰκοδομαί!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 2, 'Καὶ ὁ  ̊Ἰησοῦς εἶπεν αὐτῷ, “Βλέπεις ταύτας τὰς μεγάλας οἰκοδομάς; Οὐ μὴ ἀφεθῇ ὧδε λίθος ἐπὶ λίθον, ὃς οὐ μὴ καταλυθῇ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 3, '¶Καὶ καθημένου αὐτοῦ εἰς τὸ Ὄρος τῶν Ἐλαιῶν κατέναντι τοῦ ἱεροῦ, ἐπηρώτα αὐτὸν κατʼ ἰδίαν Πέτρος, καὶ Ἰάκωβος, καὶ Ἰωάννης, καὶ Ἀνδρέας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 4, '“Εἰπὸν ἡμῖν πότε ταῦτα ἔσται, καὶ τί τὸ σημεῖον ὅταν μέλλῃ ταῦτα συντελεῖσθαι πάντα;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 5, 'Ὁ δὲ  ̊Ἰησοῦς ἤρξατο λέγειν αὐτοῖς, “Βλέπετε, μή τις ὑμᾶς πλανήσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 6, 'Πολλοὶ ἐλεύσονται ἐπὶ τῷ ὀνόματί μου λέγοντες, ὅτι ‘Ἐγώ εἰμι’, καὶ πολλοὺς πλανήσουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 7, 'Ὅταν δὲ ἀκούσητε πολέμους καὶ ἀκοὰς πολέμων, μὴ θροεῖσθε· δεῖ γενέσθαι, ἀλλʼ οὔπω τὸ τέλος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 8, 'Ἐγερθήσεται γὰρ ἔθνος ἐπὶ ἔθνος, καὶ βασιλεία ἐπὶ βασιλείαν. Ἔσονται σεισμοὶ κατὰ τόπους, ἔσονται λιμοί· ἀρχὴ ὠδίνων ταῦτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 9, '¶Βλέπετε δὲ ὑμεῖς ἑαυτούς· παραδώσουσιν ὑμᾶς εἰς συνέδρια καὶ εἰς συναγωγὰς δαρήσεσθε, καὶ ἐπὶ ἡγεμόνων καὶ βασιλέων σταθήσεσθε ἕνεκεν ἐμοῦ, εἰς μαρτύριον αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 10, 'Καὶ εἰς πάντα τὰ ἔθνη πρῶτον δεῖ κηρυχθῆναι τὸ εὐαγγέλιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 11, 'Καὶ ὅταν ἄγωσιν ὑμᾶς παραδιδόντες, μὴ προμεριμνᾶτε τί λαλήσητε, ἀλλʼ ὃ ἐὰν δοθῇ ὑμῖν ἐν ἐκείνῃ τῇ ὥρᾳ, τοῦτο λαλεῖτε, οὐ γάρ ἐστε ὑμεῖς οἱ λαλοῦντες, ἀλλὰ τὸ  ̊Πνεῦμα τὸ Ἅγιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 12, 'Καὶ παραδώσει ἀδελφὸς ἀδελφὸν εἰς θάνατον, καὶ πατὴρ τέκνον, καὶ ἐπαναστήσονται τέκνα ἐπὶ γονεῖς καὶ θανατώσουσιν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 13, 'Καὶ ἔσεσθε μισούμενοι ὑπὸ πάντων διὰ τὸ ὄνομά μου. Ὁ δὲ ὑπομείνας εἰς τέλος, οὗτος σωθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 14, '¶Ὅταν δὲ ἴδητε ‘τὸ βδέλυγμα τῆς ἐρημώσεως’, ἑστηκότα ὅπου οὐ δεῖ, ὁ ἀναγινώσκων νοείτω, τότε οἱ ἐν τῇ Ἰουδαίᾳ, φευγέτωσαν εἰς τὰ ὄρη,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 15, 'ὁ δὲ ἐπὶ τοῦ δώματος, μὴ καταβάτω, μηδὲ εἰσελθέτω ἆραί τι ἐκ τῆς οἰκίας αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 16, 'καὶ ὁ εἰς τὸν ἀγρὸν, μὴ ἐπιστρεψάτω εἰς τὰ ὀπίσω, ἆραι τὸ ἱμάτιον αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 17, 'Οὐαὶ δὲ ταῖς ἐν γαστρὶ ἐχούσαις καὶ ταῖς θηλαζούσαις ἐν ἐκείναις ταῖς ἡμέραις!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 18, 'Προσεύχεσθε δὲ ἵνα μὴ γένηται χειμῶνος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 19, 'Ἔσονται γὰρ αἱ ἡμέραι ἐκεῖναι θλῖψις, οἵα οὐ γέγονεν τοιαύτη, ἀπʼ ἀρχῆς κτίσεως ἣν ἔκτισεν ὁ  ̊Θεὸς, ἕως τοῦ νῦν, καὶ οὐ μὴ γένηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 20, 'Καὶ εἰ μὴ ἐκολόβωσεν  ̊Κύριος τὰς ἡμέρας, οὐκ ἂν ἐσώθη πᾶσα σάρξ. Ἀλλὰ διὰ τοὺς ἐκλεκτοὺς, οὓς ἐξελέξατο, ἐκολόβωσεν τὰς ἡμέρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 21, 'Καὶ τότε ἐάν τις ὑμῖν εἴπῃ, ‘Ἴδε, ὧδε ὁ  ̊Χριστός’, ἢ ‘Ἴδε, ἐκεῖ’, μὴ πιστεύετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 22, 'Ἐγερθήσονται γὰρ ψευδόχριστοι καὶ ψευδοπροφῆται, καὶ δώσουσιν σημεῖα καὶ τέρατα, πρὸς τὸ ἀποπλανᾶν εἰ δυνατὸν τοὺς ἐκλεκτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 23, 'Ὑμεῖς δὲ βλέπετε· ἰδοὺ, προείρηκα ὑμῖν πάντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 24, '¶Ἀλλὰ ἐν ἐκείναις ταῖς ἡμέραις, μετὰ τὴν θλῖψιν ἐκείνην, ‘ὁ ἥλιος σκοτισθήσεται, καὶ ἡ σελήνη οὐ δώσει τὸ φέγγος αὐτῆς’,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 25, '‘καὶ οἱ ἀστέρες ἔσονται ἐκ τοῦ οὐρανοῦ πίπτοντες’, καὶ αἱ δυνάμεις αἱ ἐν τοῖς οὐρανοῖς σαλευθήσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 26, 'Καὶ τότε ὄψονται ‘τὸν Υἱὸν τοῦ Ἀνθρώπου ἐρχόμενον ἐν νεφέλαις’, μετὰ δυνάμεως πολλῆς καὶ δόξης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 27, 'Καὶ τότε ἀποστελεῖ τοὺς ἀγγέλους καὶ ἐπισυνάξει τοὺς ἐκλεκτοὺς αὐτοῦ, ἐκ τῶν τεσσάρων ἀνέμων, ἀπʼ ἄκρου γῆς ἕως ἄκρου οὐρανοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 28, '¶Ἀπὸ δὲ τῆς συκῆς, μάθετε τὴν παραβολήν: ὅταν ἤδη ὁ κλάδος αὐτῆς ἁπαλὸς γένηται, καὶ ἐκφύῃ τὰ φύλλα, γινώσκετε ὅτι ἐγγὺς τὸ θέρος ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 29, 'Οὕτως καὶ ὑμεῖς, ὅταν ἴδητε ταῦτα γινόμενα, γινώσκετε ὅτι ἐγγύς ἐστιν ἐπὶ θύραις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 30, 'Ἀμὴν, λέγω ὑμῖν ὅτι οὐ μὴ παρέλθῃ ἡ γενεὰ αὕτη, μέχρις οὗ ταῦτα πάντα γένηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 31, 'Ὁ οὐρανὸς καὶ ἡ γῆ παρελεύσονται, οἱ δὲ λόγοι μου οὐ μὴ παρελεύσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 32, '¶Περὶ δὲ τῆς ἡμέρας ἐκείνης ἢ τῆς ὥρας, οὐδεὶς οἶδεν, οὐδὲ οἱ ἄγγελοι ἐν οὐρανῷ, οὐδὲ ὁ Υἱός, εἰ μὴ ὁ Πατήρ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 33, 'Βλέπετε, ἀγρυπνεῖτε, καὶ προσεύχεσθε, οὐκ οἴδατε γὰρ πότε ὁ καιρός ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 34, 'Ὡς ἄνθρωπος ἀπόδημος, ἀφεὶς τὴν οἰκίαν αὐτοῦ, καὶ δοὺς τοῖς δούλοις αὐτοῦ τὴν ἐξουσίαν, ἑκάστῳ τὸ ἔργον αὐτοῦ, καὶ τῷ θυρωρῷ ἐνετείλατο ἵνα γρηγορῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 35, 'Γρηγορεῖτε οὖν, οὐκ οἴδατε γὰρ, πότε ὁ κύριος τῆς οἰκίας ἔρχεται, ἢ ὀψὲ, ἢ μεσονύκτιον, ἢ ἀλεκτοροφωνίας, ἢ πρωΐ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 36, 'μὴ ἐλθὼν ἐξαίφνης, εὕρῃ ὑμᾶς καθεύδοντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 37, 'Ὃ δὲ ὑμῖν λέγω, πᾶσιν λέγω, γρηγορεῖτε!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 1, '¶Ἦν δὲ τὸ Πάσχα καὶ τὰ Ἄζυμα μετὰ δύο ἡμέρας. Καὶ ἐζήτουν οἱ ἀρχιερεῖς καὶ οἱ γραμματεῖς, πῶς αὐτὸν ἐν δόλῳ κρατήσαντες, ἀποκτείνωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 2, 'Ἔλεγον γάρ, “Μὴ ἐν τῇ ἑορτῇ, μήποτε ἔσται θόρυβος τοῦ λαοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 3, '¶Καὶ ὄντος αὐτοῦ ἐν Βηθανίᾳ, ἐν τῇ οἰκίᾳ Σίμωνος τοῦ λεπροῦ, κατακειμένου αὐτοῦ, ἦλθεν γυνὴ ἔχουσα ἀλάβαστρον μύρου, νάρδου πιστικῆς πολυτελοῦς· συντρίψασα τὴν ἀλάβαστρον, κατέχεεν αὐτοῦ τῆς κεφαλῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 4, 'Ἦσαν δέ τινες ἀγανακτοῦντες πρὸς ἑαυτούς, “Εἰς τί ἡ ἀπώλεια αὕτη τοῦ μύρου γέγονεν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 5, 'Ἠδύνατο γὰρ τοῦτο τὸ μύρον πραθῆναι ἐπάνω δηναρίων τριακοσίων, καὶ δοθῆναι τοῖς πτωχοῖς.” Καὶ ἐνεβριμῶντο αὐτῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 6, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν, “Ἄφετε αὐτήν· τί αὐτῇ κόπους παρέχετε; Καλὸν ἔργον ἠργάσατο ἐν ἐμοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 7, 'Πάντοτε γὰρ τοὺς πτωχοὺς ἔχετε μεθʼ ἑαυτῶν, καὶ ὅταν θέλητε, δύνασθε αὐτοῖς εὖ ποιῆσαι, ἐμὲ δὲ οὐ πάντοτε ἔχετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 8, 'Ὃ ἔσχεν ἐποίησεν, προέλαβεν μυρίσαι τὸ σῶμά μου εἰς τὸν ἐνταφιασμόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 9, 'Ἀμὴν, δὲ λέγω ὑμῖν, ὅπου ἐὰν κηρυχθῇ τὸ εὐαγγέλιον εἰς ὅλον τὸν κόσμον, καὶ ὃ ἐποίησεν αὕτη, λαληθήσεται εἰς μνημόσυνον αὐτῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 10, '¶Καὶ Ἰούδας Ἰσκαριὼθ, ὁ εἷς τῶν δώδεκα, ἀπῆλθεν πρὸς τοὺς ἀρχιερεῖς, ἵνα αὐτὸν παραδῷ αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 11, 'Οἱ δὲ ἀκούσαντες ἐχάρησαν, καὶ ἐπηγγείλαντο αὐτῷ ἀργύριον δοῦναι. Καὶ ἐζήτει πῶς αὐτὸν εὐκαίρως παραδοῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 12, '¶Καὶ τῇ πρώτῃ ἡμέρᾳ τῶν Ἀζύμων, ὅτε τὸ Πάσχα ἔθυον, λέγουσιν αὐτῷ οἱ μαθηταὶ αὐτοῦ, “Ποῦ θέλεις ἀπελθόντες ἑτοιμάσωμεν, ἵνα φάγῃς τὸ Πάσχα;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 13, 'Καὶ ἀποστέλλει δύο τῶν μαθητῶν αὐτοῦ, καὶ λέγει αὐτοῖς, “Ὑπάγετε εἰς τὴν πόλιν, καὶ ἀπαντήσει ὑμῖν ἄνθρωπος, κεράμιον ὕδατος βαστάζων· ἀκολουθήσατε αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 14, 'Καὶ ὅπου ἐὰν εἰσέλθῃ, εἴπατε τῷ οἰκοδεσπότῃ, ὅτι ‘Ὁ διδάσκαλος λέγει, “Ποῦ ἐστιν τὸ κατάλυμά μου, ὅπου τὸ Πάσχα μετὰ τῶν μαθητῶν μου φάγω;”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 15, 'Καὶ αὐτὸς ὑμῖν δείξει ἀνάγαιον μέγα ἐστρωμένον ἕτοιμον· ἐκεῖ ἑτοιμάσατε ἡμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 16, 'Καὶ ἐξῆλθον οἱ μαθηταὶ, καὶ ἦλθον εἰς τὴν πόλιν, καὶ εὗρον καθὼς εἶπεν αὐτοῖς, καὶ ἡτοίμασαν τὸ Πάσχα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 17, '¶Καὶ ὀψίας γενομένης, ἔρχεται μετὰ τῶν δώδεκα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 18, 'Καὶ ἀνακειμένων αὐτῶν καὶ ἐσθιόντων, ὁ  ̊Ἰησοῦς εἶπεν, “Ἀμὴν, λέγω ὑμῖν ὅτι εἷς ἐξ ὑμῶν παραδώσει με, ὁ ἐσθίων μετʼ ἐμοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 19, 'Ἤρξαντο λυπεῖσθαι, καὶ λέγειν αὐτῷ εἷς καθʼ εἷς, “Μήτι ἐγώ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 20, 'Ὁ δὲ εἶπεν αὐτοῖς, “Εἷς τῶν δώδεκα, ὁ ἐμβαπτόμενος μετʼ ἐμοῦ εἰς τὸ τρύβλιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 21, 'ὅτι Ὁ μὲν Υἱὸς τοῦ Ἀνθρώπου ὑπάγει, καθὼς γέγραπται περὶ αὐτοῦ, οὐαὶ δὲ τῷ ἀνθρώπῳ ἐκείνῳ διʼ οὗ ὁ Υἱὸς τοῦ Ἀνθρώπου παραδίδοται· καλὸν ἦν αὐτῷ εἰ οὐκ ἐγεννήθη ὁ ἄνθρωπος ἐκεῖνος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 22, '¶Καὶ ἐσθιόντων αὐτῶν, λαβὼν ἄρτον, εὐλογήσας, ἔκλασεν καὶ ἔδωκεν αὐτοῖς, καὶ εἶπεν, “Λάβετε, τοῦτό ἐστιν τὸ σῶμά μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 23, 'Καὶ λαβὼν ποτήριον, εὐχαριστήσας, ἔδωκεν αὐτοῖς, καὶ ἔπιον ἐξ αὐτοῦ πάντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 24, 'Καὶ εἶπεν αὐτοῖς, “Τοῦτό ἐστιν τὸ αἷμά μου τῆς διαθήκης, τὸ ἐκχυννόμενον ὑπὲρ πολλῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 25, 'Ἀμὴν, λέγω ὑμῖν ὅτι οὐκέτι οὐ μὴ πίω ἐκ τοῦ γενήματος τῆς ἀμπέλου, ἕως τῆς ἡμέρας ἐκείνης ὅταν αὐτὸ πίνω καινὸν, ἐν τῇ Βασιλείᾳ τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 26, '¶Καὶ ὑμνήσαντες, ἐξῆλθον εἰς τὸ Ὄρος τῶν Ἐλαιῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 27, 'Καὶ λέγει αὐτοῖς ὁ  ̊Ἰησοῦς, ὅτι “Πάντες σκανδαλισθήσεσθε, ὅτι γέγραπται, ‘Πατάξω τὸν ποιμένα καὶ τὰ πρόβατα διασκορπισθήσονται.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 28, 'Ἀλλὰ μετὰ τὸ ἐγερθῆναί με, προάξω ὑμᾶς εἰς τὴν Γαλιλαίαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 29, 'Ὁ δὲ Πέτρος ἔφη αὐτῷ, “Εἰ καὶ πάντες σκανδαλισθήσονται, ἀλλʼ οὐκ ἐγώ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 30, 'Καὶ λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Ἀμὴν, λέγω σοι ὅτι σὺ σήμερον, ταύτῃ τῇ νυκτὶ, πρὶν ἢ δὶς ἀλέκτορα φωνῆσαι, τρίς με ἀπαρνήσῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 31, 'Ὁ δὲ ἐκπερισσῶς ἐλάλει, “Ἐὰν δέῃ με συναποθανεῖν σοι, οὐ μή σε ἀπαρνήσομαι.” Ὡσαύτως δὲ καὶ πάντες ἔλεγον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 32, '¶Καὶ ἔρχονται εἰς χωρίον, οὗ τὸ ὄνομα Γεθσημανί, καὶ λέγει τοῖς μαθηταῖς αὐτοῦ, “Καθίσατε ὧδε, ἕως προσεύξωμαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 33, 'Καὶ παραλαμβάνει τὸν Πέτρον, καὶ τὸν Ἰάκωβον, καὶ τὸν Ἰωάννην, μετʼ αὐτοῦ, καὶ ἤρξατο ἐκθαμβεῖσθαι καὶ ἀδημονεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 34, 'Καὶ λέγει αὐτοῖς, “Περίλυπός ἐστιν ἡ ψυχή μου ἕως θανάτου· μείνατε ὧδε καὶ γρηγορεῖτε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 35, 'Καὶ προελθὼν μικρὸν, ἔπιπτεν ἐπὶ τῆς γῆς καὶ προσηύχετο ἵνα εἰ δυνατόν ἐστιν, παρέλθῃ ἀπʼ αὐτοῦ ἡ ὥρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 36, 'Καὶ ἔλεγεν, “Ἀββά, ὁ Πατήρ, πάντα δυνατά σοι. Παρένεγκε τὸ ποτήριον τοῦτο ἀπʼ ἐμοῦ· ἀλλʼ οὐ τί ἐγὼ θέλω, ἀλλὰ τί σύ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 37, 'Καὶ ἔρχεται καὶ εὑρίσκει αὐτοὺς καθεύδοντας, καὶ λέγει τῷ Πέτρῳ, “Σίμων, καθεύδεις; Οὐκ ἴσχυσας μίαν ὥραν γρηγορῆσαι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 38, 'Γρηγορεῖτε καὶ προσεύχεσθε ἵνα μὴ ἔλθητε εἰς πειρασμόν. Τὸ μὲν πνεῦμα πρόθυμον, ἡ δὲ σὰρξ ἀσθενής.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 39, 'Καὶ πάλιν ἀπελθὼν, προσηύξατο τὸν αὐτὸν λόγον εἰπών.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 40, 'Καὶ πάλιν ἐλθὼν, εὗρεν αὐτοὺς καθεύδοντας, ἦσαν γὰρ αὐτῶν οἱ ὀφθαλμοὶ καταβαρυνόμενοι, καὶ οὐκ ᾔδεισαν τί ἀποκριθῶσιν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 41, 'Καὶ ἔρχεται τὸ τρίτον, καὶ λέγει αὐτοῖς, “Καθεύδετε τὸ λοιπὸν καὶ ἀναπαύεσθε. Ἀπέχει, ἦλθεν ἡ ὥρα. Ἰδοὺ, παραδίδοται ὁ Υἱὸς τοῦ Ἀνθρώπου εἰς τὰς χεῖρας τῶν ἁμαρτωλῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 42, 'Ἐγείρεσθε, ἄγωμεν. Ἰδοὺ, ὁ παραδιδούς με ἤγγικεν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 43, '¶Καὶ εὐθὺς ἔτι αὐτοῦ λαλοῦντος, παραγίνεται Ἰούδας, εἷς τῶν δώδεκα, καὶ μετʼ αὐτοῦ ὄχλος μετὰ μαχαιρῶν καὶ ξύλων, παρὰ τῶν ἀρχιερέων, καὶ τῶν γραμματέων, καὶ τῶν πρεσβυτέρων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 44, 'Δεδώκει δὲ ὁ παραδιδοὺς αὐτὸν σύσσημον αὐτοῖς λέγων, “Ὃν ἂν φιλήσω, αὐτός ἐστιν· κρατήσατε αὐτὸν, καὶ ἀπάγετε ἀσφαλῶς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 45, 'Καὶ ἐλθὼν εὐθὺς προσελθὼν αὐτῷ, λέγει, “Ῥαββὶ”, καὶ κατεφίλησεν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 46, 'Οἱ δὲ ἐπέβαλαν τὰς χεῖρας αὐτῶν καὶ ἐκράτησαν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 47, 'Εἷς δέ τις τῶν παρεστηκότων, σπασάμενος τὴν μάχαιραν, ἔπαισεν τὸν δοῦλον τοῦ ἀρχιερέως, καὶ ἀφεῖλεν αὐτοῦ τὸ ὠτάριον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 48, 'Καὶ ἀποκριθεὶς ὁ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Ὡς ἐπὶ λῃστὴν ἐξήλθατε μετὰ μαχαιρῶν καὶ ξύλων συλλαβεῖν με;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 49, 'Καθʼ ἡμέραν ἤμην πρὸς ὑμᾶς ἐν τῷ ἱερῷ διδάσκων, καὶ οὐκ ἐκρατήσατέ με· ἀλλʼ ἵνα πληρωθῶσιν αἱ Γραφαί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 50, 'Καὶ ἀφέντες αὐτὸν, ἔφυγον πάντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 51, '¶Καὶ νεανίσκος τις συνηκολούθει αὐτῷ, περιβεβλημένος σινδόνα ἐπὶ γυμνοῦ. Καὶ κρατοῦσιν αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 52, 'ὁ δὲ καταλιπὼν τὴν σινδόνα, γυμνὸς ἔφυγεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 53, '¶Καὶ ἀπήγαγον τὸν  ̊Ἰησοῦν πρὸς τὸν ἀρχιερέα, καὶ συνέρχονται αὐτῷ πάντες οἱ ἀρχιερεῖς, καὶ οἱ πρεσβύτεροι, καὶ οἱ γραμματεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 54, 'Καὶ ὁ Πέτρος ἀπὸ μακρόθεν ἠκολούθησεν αὐτῷ, ἕως ἔσω εἰς τὴν αὐλὴν τοῦ ἀρχιερέως· καὶ ἦν συγκαθήμενος μετὰ τῶν ὑπηρετῶν, καὶ θερμαινόμενος πρὸς τὸ φῶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 55, 'Οἱ δὲ ἀρχιερεῖς καὶ ὅλον τὸ Συνέδριον ἐζήτουν κατὰ τοῦ  ̊Ἰησοῦ μαρτυρίαν, εἰς τὸ θανατῶσαι αὐτόν, καὶ οὐχ ηὕρισκον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 56, 'Πολλοὶ γὰρ ἐψευδομαρτύρουν κατʼ αὐτοῦ, καὶ ἴσαι αἱ μαρτυρίαι οὐκ ἦσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 57, 'Καί τινες ἀναστάντες, ἐψευδομαρτύρουν κατʼ αὐτοῦ λέγοντες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 58, 'ὅτι “Ἡμεῖς ἠκούσαμεν αὐτοῦ λέγοντος, ὅτι ‘Ἐγὼ καταλύσω τὸν ναὸν τοῦτον, τὸν χειροποίητον, καὶ διὰ τριῶν ἡμερῶν ἄλλον ἀχειροποίητον οἰκοδομήσω.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 59, 'Καὶ οὐδὲ οὕτως ἴση ἦν ἡ μαρτυρία αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 60, 'Καὶ ἀναστὰς ὁ ἀρχιερεὺς εἰς μέσον, ἐπηρώτησεν τὸν  ̊Ἰησοῦν λέγων, “Οὐκ ἀποκρίνῃ οὐδέν; Τί οὗτοί σου καταμαρτυροῦσιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 61, 'Ὁ δὲ ἐσιώπα, καὶ οὐκ ἀπεκρίνατο οὐδέν. Πάλιν ὁ ἀρχιερεὺς ἐπηρώτα αὐτὸν, καὶ λέγει αὐτῷ, “Σὺ εἶ ὁ  ̊Χριστὸς, ὁ Υἱὸς τοῦ εὐλογητοῦ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 62, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν, “Ἐγώ εἰμι. Καὶ ὄψεσθε τὸν Υἱὸν τοῦ Ἀνθρώπου ‘ἐκ δεξιῶν καθήμενον’ τῆς δυνάμεως, καὶ ‘ἐρχόμενον μετὰ τῶν νεφελῶν τοῦ οὐρανοῦ’.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 63, 'Ὁ δὲ ἀρχιερεὺς διαρρήξας τοὺς χιτῶνας αὐτοῦ λέγει, “Τί ἔτι χρείαν ἔχομεν μαρτύρων;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 64, 'Ἠκούσατε τῆς βλασφημίας. Τί ὑμῖν φαίνεται;” Οἱ δὲ πάντες κατέκριναν αὐτὸν, ἔνοχον εἶναι θανάτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 65, 'Καὶ ἤρξαντό τινες ἐμπτύειν αὐτῷ, καὶ περικαλύπτειν αὐτοῦ τὸ πρόσωπον, καὶ κολαφίζειν αὐτὸν, καὶ λέγειν αὐτῷ, “Προφήτευσον!” Καὶ οἱ ὑπηρέται ῥαπίσμασιν αὐτὸν ἔλαβον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 66, '¶Καὶ ὄντος τοῦ Πέτρου κάτω ἐν τῇ αὐλῇ, ἔρχεται μία τῶν παιδισκῶν τοῦ ἀρχιερέως,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 67, 'καὶ ἰδοῦσα τὸν Πέτρον θερμαινόμενον, ἐμβλέψασα αὐτῷ λέγει, “Καὶ σὺ μετὰ τοῦ Ναζαρηνοῦ ἦσθα τοῦ  ̊Ἰησοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 68, 'Ὁ δὲ ἠρνήσατο λέγων, “Οὔτε οἶδα, οὔτε ἐπίσταμαι σὺ τί λέγεις”. Καὶ ἐξῆλθεν ἔξω εἰς τὸ προαύλιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 69, 'Καὶ ἡ παιδίσκη ἰδοῦσα αὐτὸν, ἤρξατο πάλιν λέγειν τοῖς παρεστῶσιν, ὅτι “Οὗτος ἐξ αὐτῶν ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 70, 'Ὁ δὲ πάλιν ἠρνεῖτο. Καὶ μετὰ μικρὸν, πάλιν οἱ παρεστῶτες ἔλεγον τῷ Πέτρῳ, “Ἀληθῶς ἐξ αὐτῶν εἶ, καὶ γὰρ Γαλιλαῖος εἶ”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 71, 'ὁ δὲ ἤρξατο ἀναθεματίζειν καὶ ὀμνύειν, ὅτι “Οὐκ οἶδα τὸν ἄνθρωπον τοῦτον, ὃν λέγετε!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 72, 'Καὶ εὐθὺς ἐκ δευτέρου ἀλέκτωρ ἐφώνησεν. Καὶ ἀνεμνήσθη ὁ Πέτρος τὸ ῥῆμα ὡς εἶπεν αὐτῷ ὁ  ̊Ἰησοῦς, ὅτι “Πρὶν ἀλέκτορα φωνῆσαι τρίς με ἀπαρνήσῃ”, καὶ ἐπιβαλὼν, ἔκλαιεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 1, '¶Καὶ εὐθὺς πρωῒ, συμβούλιον ποιήσαντες οἱ ἀρχιερεῖς, μετὰ τῶν πρεσβυτέρων καὶ γραμματέων, καὶ ὅλον τὸ Συνέδριον, δήσαντες τὸν  ̊Ἰησοῦν, ἀπήνεγκαν καὶ παρέδωκαν Πιλάτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 2, 'Καὶ ἐπηρώτησεν αὐτὸν ὁ Πιλᾶτος, “Σὺ εἶ ὁ Βασιλεὺς τῶν Ἰουδαίων;” Ὁ δὲ ἀποκριθεὶς αὐτῷ λέγει, “Σὺ λέγεις.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 3, 'Καὶ κατηγόρουν αὐτοῦ οἱ ἀρχιερεῖς πολλά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 4, 'Ὁ δὲ Πιλᾶτος πάλιν ἐπηρώτησεν αὐτὸν λέγων, “Οὐκ ἀποκρίνῃ οὐδέν; Ἴδε, πόσα σου κατηγοροῦσιν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 5, 'Ὁ δὲ  ̊Ἰησοῦς οὐκέτι οὐδὲν ἀπεκρίθη, ὥστε θαυμάζειν τὸν Πιλᾶτον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 6, '¶Κατὰ δὲ ἑορτὴν, ἀπέλυεν αὐτοῖς ἕνα δέσμιον, ὃν παρῃτοῦντο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 7, 'Ἦν δὲ ὁ λεγόμενος Βαραββᾶς, μετὰ τῶν στασιαστῶν δεδεμένος, οἵτινες ἐν τῇ στάσει φόνον πεποιήκεισαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 8, 'Καὶ ἀναβὰς, ὁ ὄχλος ἤρξατο αἰτεῖσθαι καθὼς ἐποίει αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 9, 'Ὁ δὲ Πιλᾶτος ἀπεκρίθη αὐτοῖς λέγων, “Θέλετε ἀπολύσω ὑμῖν τὸν Βασιλέα τῶν Ἰουδαίων;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 10, 'Ἐγίνωσκεν γὰρ ὅτι διὰ φθόνον παραδεδώκεισαν αὐτὸν οἱ ἀρχιερεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 11, 'Οἱ δὲ ἀρχιερεῖς ἀνέσεισαν τὸν ὄχλον, ἵνα μᾶλλον τὸν Βαραββᾶν ἀπολύσῃ αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 12, 'Ὁ δὲ Πιλᾶτος πάλιν ἀποκριθεὶς ἔλεγεν αὐτοῖς, “Τί οὖν ποιήσω ὃν λέγετε τὸν Βασιλέα τῶν Ἰουδαίων;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 13, 'Οἱ δὲ πάλιν ἔκραξαν, “Σταύρωσον αὐτόν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 14, 'Ὁ δὲ Πιλᾶτος ἔλεγεν αὐτοῖς, “Τί γὰρ ἐποίησεν κακόν;” Οἱ δὲ περισσῶς ἔκραξαν, “Σταύρωσον αὐτόν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 15, 'Ὁ δὲ Πιλᾶτος βουλόμενος τῷ ὄχλῳ τὸ ἱκανὸν ποιῆσαι, ἀπέλυσεν αὐτοῖς τὸν Βαραββᾶν, καὶ παρέδωκεν τὸν  ̊Ἰησοῦν φραγελλώσας, ἵνα σταυρωθῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 16, '¶Οἱ δὲ στρατιῶται ἀπήγαγον αὐτὸν ἔσω τῆς αὐλῆς, ὅ ἐστιν πραιτώριον, καὶ συγκαλοῦσιν ὅλην τὴν σπεῖραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 17, 'Καὶ ἐνδιδύσκουσιν αὐτὸν πορφύραν, καὶ περιτιθέασιν αὐτῷ πλέξαντες ἀκάνθινον στέφανον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 18, 'καὶ ἤρξαντο ἀσπάζεσθαι αὐτόν, “Χαῖρε, Βασιλεῦ τῶν Ἰουδαίων!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 19, 'Καὶ ἔτυπτον αὐτοῦ τὴν κεφαλὴν καλάμῳ, καὶ ἐνέπτυον αὐτῷ, καὶ τιθέντες τὰ γόνατα, προσεκύνουν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 20, 'Καὶ ὅτε ἐνέπαιξαν αὐτῷ, ἐξέδυσαν αὐτὸν τὴν πορφύραν, καὶ ἐνέδυσαν αὐτὸν τὰ ἴδια ἱμάτια αὐτοῦ. Καὶ ἐξάγουσιν αὐτὸν, ἵνα σταυρώσωσιν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 21, '¶Καὶ ἀγγαρεύουσιν παράγοντά τινα Σίμωνα Κυρηναῖον, ἐρχόμενον ἀπʼ ἀγροῦ, τὸν πατέρα Ἀλεξάνδρου καὶ Ῥούφου, ἵνα ἄρῃ τὸν σταυρὸν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 22, 'Καὶ φέρουσιν αὐτὸν ἐπὶ τὸν Γολγοθᾶν, τόπον ὅ ἐστιν μεθερμηνευόμενος, “Κρανίου Τόπος”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 23, 'Καὶ ἐδίδουν αὐτῷ, ἐσμυρνισμένον οἶνον, ὃς δὲ οὐκ ἔλαβεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 24, 'Καὶ σταυρώσαντες αὐτὸν, διαμερίζονται τὰ ἱμάτια αὐτοῦ, βάλλοντες κλῆρον ἐπʼ αὐτὰ, τίς τί ἄρῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 25, '¶Ἦν δὲ ὥρα τρίτη, καὶ ἐσταύρωσαν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 26, 'Καὶ ἦν ἡ ἐπιγραφὴ τῆς αἰτίας αὐτοῦ ἐπιγεγραμμένη, “Ὁ Βασιλεὺς τῶν Ἰουδαίων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 27, 'Καὶ σὺν αὐτῷ σταυροῦσιν δύο λῃστάς, ἕνα ἐκ δεξιῶν καὶ ἕνα ἐξ εὐωνύμων αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 28, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 29, 'Καὶ οἱ παραπορευόμενοι ἐβλασφήμουν αὐτὸν, κινοῦντες τὰς κεφαλὰς αὐτῶν, καὶ λέγοντες, “Οὐὰ, ὁ καταλύων τὸν ναὸν καὶ οἰκοδομῶν ἐν τρισὶν ἡμέραις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 30, 'σῶσον σεαυτὸν, καταβὰς ἀπὸ τοῦ σταυροῦ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 31, 'Ὁμοίως καὶ οἱ ἀρχιερεῖς, ἐμπαίζοντες πρὸς ἀλλήλους μετὰ τῶν γραμματέων ἔλεγον, “Ἄλλους ἔσωσεν, ἑαυτὸν οὐ δύναται σῶσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 32, 'Ὁ  ̊Χριστὸς, ὁ Βασιλεὺς Ἰσραὴλ καταβάτω νῦν ἀπὸ τοῦ σταυροῦ, ἵνα ἴδωμεν καὶ πιστεύσωμεν!” Καὶ οἱ συνεσταυρωμένοι σὺν αὐτῷ ὠνείδιζον αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 33, '¶Καὶ γενομένης ὥρας ἕκτης, σκότος ἐγένετο ἐφʼ ὅλην τὴν γῆν, ἕως ὥρας ἐνάτης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 34, 'Καὶ τῇ ἐνάτῃ ὥρᾳ, ἐβόησεν ὁ  ̊Ἰησοῦς φωνῇ μεγάλῃ, “Ἐλωῒ, Ἐλωῒ, λεμὰ σαβαχθάνι;” Ὅ ἐστιν μεθερμηνευόμενον, “Ὁ  ̊Θεός μου, ὁ  ̊Θεός μου, εἰς τί ἐγκατέλιπές με;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 35, 'Καί τινες τῶν παρεστηκότων, ἀκούσαντες ἔλεγον, “Ἴδε, Ἠλίαν φωνεῖ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 36, 'Δραμὼν δέ τις, καὶ γεμίσας σπόγγον ὄξους περιθεὶς καλάμῳ, ἐπότιζεν αὐτόν λέγων, “Ἄφετε, ἴδωμεν εἰ ἔρχεται Ἠλίας καθελεῖν αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 37, 'Ὁ δὲ  ̊Ἰησοῦς ἀφεὶς φωνὴν μεγάλην, ἐξέπνευσεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 38, 'Καὶ τὸ καταπέτασμα τοῦ ναοῦ ἐσχίσθη εἰς δύο, ἀπʼ ἄνωθεν ἕως κάτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 39, 'Ἰδὼν δὲ ὁ κεντυρίων ὁ παρεστηκὼς ἐξ ἐναντίας αὐτοῦ ὅτι οὕτως ἐξέπνευσεν εἶπεν, “Ἀληθῶς οὗτος ὁ ἄνθρωπος Υἱὸς  ̊Θεοῦ ἦν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 40, '¶Ἦσαν δὲ καὶ γυναῖκες ἀπὸ μακρόθεν θεωροῦσαι, ἐν αἷς καὶ Μαριὰμ ἡ Μαγδαληνὴ, καὶ Μαρία ἡ Ἰακώβου τοῦ μικροῦ καὶ Ἰωσῆ μήτηρ, καὶ Σαλώμη,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 41, 'αἳ ὅτε ἦν ἐν τῇ Γαλιλαίᾳ ἠκολούθουν αὐτῷ καὶ διηκόνουν αὐτῷ, καὶ ἄλλαι πολλαὶ αἱ συναναβᾶσαι αὐτῷ εἰς Ἱεροσόλυμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 42, '¶Καὶ ἤδη ὀψίας γενομένης, ἐπεὶ ἦν παρασκευή, ὅ ἐστιν προσάββατον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 43, 'ἐλθὼν Ἰωσὴφ ὁ ἀπὸ Ἁριμαθαίας, εὐσχήμων βουλευτής, ὃς καὶ αὐτὸς ἦν προσδεχόμενος τὴν Βασιλείαν τοῦ  ̊Θεοῦ, τολμήσας, εἰσῆλθεν πρὸς τὸν Πιλᾶτον καὶ ᾐτήσατο τὸ σῶμα τοῦ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 44, 'Ὁ δὲ Πιλᾶτος ἐθαύμασεν εἰ ἤδη τέθνηκεν, καὶ προσκαλεσάμενος τὸν κεντυρίωνα, ἐπηρώτησεν αὐτὸν εἰ ἤδη ἀπέθανεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 45, 'Καὶ γνοὺς ἀπὸ τοῦ κεντυρίωνος, ἐδωρήσατο τὸ πτῶμα τῷ Ἰωσήφ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 46, 'Καὶ ἀγοράσας σινδόνα, καθελὼν αὐτὸν, ἐνείλησεν τῇ σινδόνι, καὶ ἔθηκεν αὐτὸν ἐν μνήματι ὃ ἦν λελατομημένον ἐκ πέτρας, καὶ προσεκύλισεν λίθον ἐπὶ τὴν θύραν τοῦ μνημείου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 47, 'Ἡ δὲ Μαρία ἡ Μαγδαληνὴ, καὶ Μαρία ἡ Ἰωσῆ, ἐθεώρουν ποῦ τέθειται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 1, '¶Καὶ διαγενομένου τοῦ Σαββάτου, ἡ Μαρία ἡ Μαγδαληνὴ, καὶ Μαρία ἡ τοῦ Ἰακώβου, καὶ Σαλώμη, ἠγόρασαν ἀρώματα, ἵνα ἐλθοῦσαι ἀλείψωσιν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 2, 'Καὶ λίαν πρωῒ μιᾷ τῶν σαββάτων, ἔρχονται ἐπὶ τὸ μνημεῖον, ἀνατείλαντος τοῦ ἡλίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 3, 'Καὶ ἔλεγον πρὸς ἑαυτάς, “Τίς ἀποκυλίσει ἡμῖν τὸν λίθον ἐκ τῆς θύρας τοῦ μνημείου;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 4, 'Καὶ ἀναβλέψασαι θεωροῦσιν ὅτι ἀποκεκύλισται ὁ λίθος, ἦν γὰρ μέγας σφόδρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 5, 'Καὶ εἰσελθοῦσαι εἰς τὸ μνημεῖον, εἶδον νεανίσκον καθήμενον ἐν τοῖς δεξιοῖς, περιβεβλημένον στολὴν λευκήν, καὶ ἐξεθαμβήθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 6, 'Ὁ δὲ λέγει αὐταῖς, “Μὴ ἐκθαμβεῖσθε.  ̊Ἰησοῦν ζητεῖτε τὸν Ναζαρηνὸν, τὸν ἐσταυρωμένον. Ἠγέρθη! Οὐκ ἔστιν ὧδε· ἴδε, ὁ τόπος ὅπου ἔθηκαν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 7, 'Ἀλλὰ ὑπάγετε, εἴπατε τοῖς μαθηταῖς αὐτοῦ καὶ τῷ Πέτρῳ, ὅτι ‘Προάγει ὑμᾶς εἰς τὴν Γαλιλαίαν· ἐκεῖ αὐτὸν ὄψεσθε, καθὼς εἶπεν ὑμῖν.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 8, 'Καὶ ἐξελθοῦσαι, ἔφυγον ἀπὸ τοῦ μνημείου, εἶχεν γὰρ αὐτὰς τρόμος καὶ ἔκστασις, καὶ οὐδενὶ οὐδὲν εἶπον, ἐφοβοῦντο γάρ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 9, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 10, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 11, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 12, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 13, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 14, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 15, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 16, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 17, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 18, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 19, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 20, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, '¶Ἐπειδήπερ πολλοὶ ἐπεχείρησαν ἀνατάξασθαι διήγησιν, περὶ τῶν πεπληροφορημένων ἐν ἡμῖν πραγμάτων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'καθὼς παρέδοσαν ἡμῖν οἱ ἀπʼ ἀρχῆς, αὐτόπται καὶ ὑπηρέται γενόμενοι τοῦ λόγου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'ἔδοξε κἀμοὶ παρηκολουθηκότι ἄνωθεν πᾶσιν ἀκριβῶς, καθεξῆς σοι γράψαι, κράτιστε Θεόφιλε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'ἵνα ἐπιγνῷς περὶ ὧν κατηχήθης λόγων τὴν ἀσφάλειαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, '¶Ἐγένετο ἐν ταῖς ἡμέραις Ἡρῴδου βασιλέως τῆς Ἰουδαίας, ἱερεύς τις ὀνόματι Ζαχαρίας ἐξ ἐφημερίας Ἀβιά, καὶ γυνὴ αὐτῷ ἐκ τῶν θυγατέρων Ἀαρών, καὶ τὸ ὄνομα αὐτῆς, Ἐλισάβετ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Ἦσαν δὲ δίκαιοι ἀμφότεροι ἐναντίον τοῦ  ̊Θεοῦ, πορευόμενοι ἐν πάσαις ταῖς ἐντολαῖς καὶ δικαιώμασιν τοῦ  ̊Κυρίου ἄμεμπτοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Καὶ οὐκ ἦν αὐτοῖς τέκνον, καθότι ἡ Ἐλισάβετ ἦν στεῖρα, καὶ ἀμφότεροι προβεβηκότες ἐν ταῖς ἡμέραις αὐτῶν ἦσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, '¶Ἐγένετο δὲ ἐν τῷ ἱερατεύειν αὐτὸν, ἐν τῇ τάξει τῆς ἐφημερίας αὐτοῦ ἔναντι τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'κατὰ τὸ ἔθος τῆς ἱερατείας, ἔλαχε τοῦ θυμιᾶσαι, εἰσελθὼν εἰς τὸν ναὸν τοῦ  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Καὶ πᾶν τὸ πλῆθος ἦν τοῦ λαοῦ προσευχόμενον ἔξω τῇ ὥρᾳ τοῦ θυμιάματος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Ὤφθη δὲ αὐτῷ ἄγγελος  ̊Κυρίου, ἑστὼς ἐκ δεξιῶν τοῦ θυσιαστηρίου τοῦ θυμιάματος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Καὶ ἐταράχθη Ζαχαρίας ἰδών, καὶ φόβος ἐπέπεσεν ἐπʼ αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Εἶπεν δὲ πρὸς αὐτὸν ὁ ἄγγελος, “Μὴ φοβοῦ, Ζαχαρία, διότι εἰσηκούσθη ἡ δέησίς σου, καὶ ἡ γυνή σου Ἐλισάβετ γεννήσει υἱόν σοι, καὶ καλέσεις τὸ ὄνομα αὐτοῦ Ἰωάννην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Καὶ ἔσται χαρά σοι καὶ ἀγαλλίασις, καὶ πολλοὶ ἐπὶ τῇ γενέσει αὐτοῦ χαρήσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Ἔσται γὰρ μέγας ἐνώπιον τοῦ  ̊Κυρίου, καὶ οἶνον καὶ σίκερα οὐ μὴ πίῃ, καὶ  ̊Πνεύματος Ἁγίου πλησθήσεται ἔτι ἐκ κοιλίας μητρὸς αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Καὶ πολλοὺς τῶν υἱῶν Ἰσραὴλ ἐπιστρέψει ἐπὶ  ̊Κύριον, τὸν  ̊Θεὸν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Καὶ αὐτὸς προελεύσεται ἐνώπιον αὐτοῦ ἐν πνεύματι καὶ δυνάμει Ἠλεία, ἐπιστρέψαι καρδίας πατέρων ἐπὶ τέκνα, καὶ ἀπειθεῖς ἐν φρονήσει δικαίων, ἑτοιμάσαι  ̊Κυρίῳ λαὸν κατεσκευασμένον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Καὶ εἶπεν Ζαχαρίας πρὸς τὸν ἄγγελον, “Κατὰ τί γνώσομαι τοῦτο; Ἐγὼ γάρ εἰμι πρεσβύτης, καὶ ἡ γυνή μου προβεβηκυῖα ἐν ταῖς ἡμέραις αὐτῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Καὶ ἀποκριθεὶς ὁ ἄγγελος εἶπεν αὐτῷ, “Ἐγώ εἰμι Γαβριὴλ, ὁ παρεστηκὼς ἐνώπιον τοῦ  ̊Θεοῦ, καὶ ἀπεστάλην λαλῆσαι πρὸς σὲ, καὶ εὐαγγελίσασθαί σοι ταῦτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Καὶ ἰδοὺ, ἔσῃ σιωπῶν καὶ μὴ δυνάμενος λαλῆσαι, ἄχρι ἧς ἡμέρας γένηται ταῦτα, ἀνθʼ ὧν οὐκ ἐπίστευσας τοῖς λόγοις μου, οἵτινες πληρωθήσονται εἰς τὸν καιρὸν αὐτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, '¶Καὶ ἦν ὁ λαὸς προσδοκῶν τὸν Ζαχαρίαν, καὶ ἐθαύμαζον ἐν τῷ χρονίζειν αὐτόν ἐν τῷ ναῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Ἐξελθὼν δὲ οὐκ ἐδύνατο λαλῆσαι αὐτοῖς, καὶ ἐπέγνωσαν ὅτι ὀπτασίαν ἑώρακεν ἐν τῷ ναῷ. Καὶ αὐτὸς ἦν διανεύων αὐτοῖς, καὶ διέμενεν κωφός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Καὶ ἐγένετο ὡς ἐπλήσθησαν αἱ ἡμέραι τῆς λειτουργίας αὐτοῦ, ἀπῆλθεν εἰς τὸν οἶκον αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, '¶Μετὰ δὲ ταύτας τὰς ἡμέρας συνέλαβεν Ἐλισάβετ ἡ γυνὴ αὐτοῦ, καὶ περιέκρυβεν ἑαυτὴν μῆνας πέντε λέγουσα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'ὅτι “Οὕτως μοι πεποίηκεν  ̊Κύριος, ἐν ἡμέραις αἷς ἐπεῖδεν, ἀφελεῖν ὄνειδός μου ἐν ἀνθρώποις.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 26, '¶Ἐν δὲ τῷ μηνὶ τῷ ἕκτῳ, ἀπεστάλη ὁ ἄγγελος Γαβριὴλ ἀπὸ τοῦ  ̊Θεοῦ εἰς πόλιν τῆς Γαλιλαίας, ᾗ ὄνομα Ναζαρὲτ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 27, 'πρὸς παρθένον ἐμνηστευμένην ἀνδρὶ, ᾧ ὄνομα Ἰωσὴφ, ἐξ οἴκου Δαυὶδ, καὶ τὸ ὄνομα τῆς παρθένου Μαριάμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 28, 'Καὶ εἰσελθὼν ὁ ἄγγελος πρὸς αὐτὴν, εἶπεν, “Χαῖρε, κεχαριτωμένη! Ὁ  ̊Κύριος μετὰ σοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 29, 'Ἡ δὲ ἐπὶ τῷ λόγῳ διεταράχθη, καὶ διελογίζετο ποταπὸς εἴη ὁ ἀσπασμὸς οὗτος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 30, 'Καὶ εἶπεν ὁ ἄγγελος αὐτῇ, “Μὴ φοβοῦ, Μαριάμ, εὗρες γὰρ χάριν παρὰ τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 31, 'Καὶ ἰδοὺ, συλλήμψῃ ἐν γαστρὶ, καὶ τέξῃ υἱόν, καὶ καλέσεις τὸ ὄνομα αὐτοῦ  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 32, 'Οὗτος ἔσται μέγας, καὶ Υἱὸς Ὑψίστου κληθήσεται, καὶ δώσει αὐτῷ  ̊Κύριος ὁ  ̊Θεὸς τὸν θρόνον Δαυὶδ, τοῦ πατρὸς αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 33, 'καὶ βασιλεύσει ἐπὶ τὸν οἶκον Ἰακὼβ, εἰς τοὺς αἰῶνας, καὶ τῆς βασιλείας αὐτοῦ, οὐκ ἔσται τέλος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 34, 'Εἶπεν δὲ Μαριὰμ πρὸς τὸν ἄγγελον, “Πῶς ἔσται τοῦτο, ἐπεὶ ἄνδρα οὐ γινώσκω;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 35, 'Καὶ ἀποκριθεὶς ὁ ἄγγελος εἶπεν αὐτῇ, “ ̊Πνεῦμα Ἅγιον ἐπελεύσεται ἐπὶ σέ, καὶ δύναμις Ὑψίστου ἐπισκιάσει σοι· διὸ καὶ τὸ γεννώμενον Ἅγιον κληθήσεται, Υἱὸς  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 36, 'Καὶ ἰδοὺ, Ἐλισάβετ, ἡ συγγενίς σου, καὶ αὐτὴ συνείληφεν υἱὸν ἐν γήρει αὐτῆς, καὶ οὗτος μὴν ἕκτος ἐστὶν αὐτῇ τῇ καλουμένῃ στείρᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 37, 'Ὅτι οὐκ ἀδυνατήσει παρὰ τοῦ  ̊Θεοῦ πᾶν ῥῆμα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 38, 'Εἶπεν δὲ Μαριάμ, “Ἰδοὺ, ἡ δούλη  ̊Κυρίου· γένοιτό μοι κατὰ τὸ ῥῆμά σου.” Καὶ ἀπῆλθεν ἀπʼ αὐτῆς ὁ ἄγγελος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 39, '¶Ἀναστᾶσα δὲ Μαριὰμ ἐν ταῖς ἡμέραις ταύταις, ἐπορεύθη εἰς τὴν ὀρεινὴν μετὰ σπουδῆς, εἰς πόλιν Ἰούδα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 40, 'καὶ εἰσῆλθεν εἰς τὸν οἶκον Ζαχαρίου, καὶ ἠσπάσατο τὴν Ἐλισάβετ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 41, 'Καὶ ἐγένετο, ὡς ἤκουσεν τὸν ἀσπασμὸν τῆς Μαρίας ἡ Ἐλισάβετ, ἐσκίρτησεν τὸ βρέφος ἐν τῇ κοιλίᾳ αὐτῆς, καὶ ἐπλήσθη  ̊Πνεύματος Ἁγίου ἡ Ἐλισάβετ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 42, 'καὶ ἀνεφώνησεν φωνῇ μεγάλῃ καὶ εἶπεν, “Εὐλογημένη σὺ ἐν γυναιξίν, καὶ εὐλογημένος ὁ καρπὸς τῆς κοιλίας σου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 43, 'Καὶ πόθεν μοι τοῦτο, ἵνα ἔλθῃ ἡ μήτηρ τοῦ  ̊Κυρίου μου πρὸς ἐμέ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 44, 'Ἰδοὺ γὰρ, ὡς ἐγένετο ἡ φωνὴ τοῦ ἀσπασμοῦ σου εἰς τὰ ὦτά μου, ἐσκίρτησεν ἐν ἀγαλλιάσει τὸ βρέφος ἐν τῇ κοιλίᾳ μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 45, 'Καὶ μακαρία ἡ πιστεύσασα ὅτι ἔσται τελείωσις τοῖς λελαλημένοις αὐτῇ παρὰ  ̊Κυρίου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 46, '¶Καὶ εἶπεν Μαριάμ: “Μεγαλύνει ἡ ψυχή μου τὸν  ̊Κύριον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 47, 'καὶ ἠγαλλίασεν τὸ πνεῦμά μου ἐπὶ τῷ  ̊Θεῷ, τῷ Σωτῆρί μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 48, 'Ὅτι ἐπέβλεψεν ἐπὶ τὴν ταπείνωσιν τῆς δούλης αὐτοῦ. Ἰδοὺ γὰρ, ἀπὸ τοῦ νῦν μακαριοῦσίν με πᾶσαι αἱ γενεαί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 49, 'Ὅτι ἐποίησέν μοι μεγάλα ὁ δυνατός, καὶ ἅγιον τὸ ὄνομα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 50, '‘Καὶ τὸ ἔλεος αὐτοῦ εἰς γενεὰς καὶ γενεὰς, τοῖς φοβουμένοις αὐτόν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 51, 'Ἐποίησεν κράτος ἐν βραχίονι αὐτοῦ, διεσκόρπισεν ὑπερηφάνους διανοίᾳ καρδίας αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 52, 'Καθεῖλεν δυνάστας ἀπὸ θρόνων, καὶ ὕψωσεν ταπεινούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 53, '‘Πεινῶντας ἐνέπλησεν ἀγαθῶν’, καὶ πλουτοῦντας ἐξαπέστειλεν κενούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 54, 'Ἀντελάβετο Ἰσραὴλ παιδὸς αὐτοῦ, μνησθῆναι ἐλέους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 55, 'καθὼς ἐλάλησεν πρὸς τοὺς πατέρας ἡμῶν, τῷ Ἀβραὰμ καὶ τῷ σπέρματι αὐτοῦ, εἰς τὸν αἰῶνα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 56, 'Ἔμεινεν δὲ Μαριὰμ σὺν αὐτῇ ὡς μῆνας τρεῖς, καὶ ὑπέστρεψεν εἰς τὸν οἶκον αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 57, '¶Τῇ δὲ Ἐλισάβετ ἐπλήσθη ὁ χρόνος, τοῦ τεκεῖν αὐτήν, καὶ ἐγέννησεν υἱόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 58, 'Καὶ ἤκουσαν οἱ περίοικοι καὶ οἱ συγγενεῖς αὐτῆς ὅτι ἐμεγάλυνεν  ̊Κύριος τὸ ἔλεος αὐτοῦ μετʼ αὐτῆς, καὶ συνέχαιρον αὐτῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 59, 'Καὶ ἐγένετο ἐν τῇ ἡμέρᾳ τῇ ὀγδόῃ, ἦλθον περιτεμεῖν τὸ παιδίον, καὶ ἐκάλουν αὐτὸ ἐπὶ τῷ ὀνόματι τοῦ πατρὸς αὐτοῦ, Ζαχαρίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 60, 'Καὶ ἀποκριθεῖσα ἡ μήτηρ αὐτοῦ εἶπεν, “Οὐχί, ἀλλὰ κληθήσεται Ἰωάννης.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 61, 'Καὶ εἶπον πρὸς αὐτὴν, ὅτι “Οὐδείς ἐστιν ἐκ τῆς συγγενείας σου, ὃς καλεῖται τῷ ὀνόματι τούτῳ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 62, 'Ἐνένευον δὲ τῷ πατρὶ αὐτοῦ, τὸ τί ἂν θέλοι καλεῖσθαι αὐτό.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 63, 'Καὶ αἰτήσας πινακίδιον, ἔγραψεν λέγων, “Ἰωάννης ἐστὶν ὄνομα αὐτοῦ.” Καὶ ἐθαύμασαν πάντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 64, 'Ἀνεῴχθη δὲ τὸ στόμα αὐτοῦ παραχρῆμα, καὶ ἡ γλῶσσα αὐτοῦ, καὶ ἐλάλει εὐλογῶν τὸν  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 65, 'Καὶ ἐγένετο ἐπὶ πάντας φόβος, τοὺς περιοικοῦντας αὐτούς, καὶ ἐν ὅλῃ τῇ ὀρεινῇ τῆς Ἰουδαίας διελαλεῖτο πάντα τὰ ῥήματα ταῦτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 66, 'Καὶ ἔθεντο πάντες οἱ ἀκούσαντες ἐν τῇ καρδίᾳ αὐτῶν, λέγοντες, “Τί ἄρα τὸ παιδίον τοῦτο ἔσται;” Καὶ γὰρ χεὶρ  ̊Κυρίου ἦν μετʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 67, '¶Καὶ Ζαχαρίας ὁ πατὴρ αὐτοῦ, ἐπλήσθη  ̊Πνεύματος Ἁγίου καὶ ἐπροφήτευσεν λέγων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 68, '“Εὐλογητὸς  ̊Κύριος ὁ  ̊Θεὸς τοῦ Ἰσραήλ, ὅτι ἐπεσκέψατο καὶ ἐποίησεν λύτρωσιν τῷ λαῷ αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 69, 'καὶ ἤγειρεν κέρας σωτηρίας ἡμῖν, ἐν οἴκῳ Δαυὶδ, παιδὸς αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 70, '(καθὼς ἐλάλησεν διὰ στόματος τῶν ἁγίων ἀπʼ αἰῶνος προφητῶν αὐτοῦ),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 71, 'σωτηρίαν ‘ἐξ ἐχθρῶν ἡμῶν, καὶ ἐκ χειρὸς πάντων τῶν μισούντων ἡμᾶς’,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 72, 'ποιῆσαι ἔλεος μετὰ τῶν πατέρων ἡμῶν, καὶ μνησθῆναι διαθήκης ἁγίας αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 73, 'ὅρκον ὃν ὤμοσεν πρὸς Ἀβραὰμ, τὸν πατέρα ἡμῶν, τοῦ δοῦναι ἡμῖν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 74, 'ἀφόβως ἐκ χειρὸς ἐχθρῶν ῥυσθέντας, λατρεύειν αὐτῷ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 75, 'ἐν ὁσιότητι καὶ δικαιοσύνῃ ἐνώπιον αὐτοῦ, πάσαις ταῖς ἡμέραις ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 76, 'Καὶ σὺ δέ, παιδίον, προφήτης Ὑψίστου κληθήσῃ, ‘προπορεύσῃ γὰρ ἐνώπιον  ̊Κυρίου ἑτοιμάσαι ὁδοὺς αὐτοῦ’,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 77, 'τοῦ δοῦναι γνῶσιν σωτηρίας τῷ λαῷ αὐτοῦ, ἐν ἀφέσει ἁμαρτιῶν αὐτῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 78, 'διὰ σπλάγχνα ἐλέους  ̊Θεοῦ ἡμῶν, ἐν οἷς ἐπισκέψεται ἡμᾶς ἀνατολὴ ἐξ ὕψους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 79, '‘ἐπιφᾶναι τοῖς ἐν σκότει καὶ σκιᾷ θανάτου καθημένοις’, τοῦ κατευθῦναι τοὺς πόδας ἡμῶν εἰς ὁδὸν εἰρήνης.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 80, '¶Τὸ δὲ παιδίον ηὔξανε καὶ ἐκραταιοῦτο πνεύματι, καὶ ἦν ἐν ταῖς ἐρήμοις ἕως ἡμέρας ἀναδείξεως αὐτοῦ πρὸς τὸν Ἰσραήλ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, '¶Ἐγένετο δὲ ἐν ταῖς ἡμέραις ἐκείναις, ἐξῆλθεν δόγμα παρὰ Καίσαρος Αὐγούστου, ἀπογράφεσθαι πᾶσαν τὴν οἰκουμένην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, '(Αὕτη ἀπογραφὴ πρώτη ἐγένετο ἡγεμονεύοντος τῆς Συρίας Κυρηνίου.)');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Καὶ ἐπορεύοντο πάντες ἀπογράφεσθαι, ἕκαστος εἰς τὴν ἑαυτοῦ πόλιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Ἀνέβη δὲ καὶ Ἰωσὴφ, ἀπὸ τῆς Γαλιλαίας ἐκ πόλεως Ναζαρὲθ, εἰς τὴν Ἰουδαίαν εἰς πόλιν Δαυὶδ, ἥτις καλεῖται Βηθλέεμ, διὰ τὸ εἶναι αὐτὸν ἐξ οἴκου καὶ πατριᾶς Δαυίδ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'ἀπογράψασθαι σὺν Μαριὰμ, τῇ ἐμνηστευμένῃ αὐτῷ, οὔσῃ ἐγκύῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Ἐγένετο δὲ ἐν τῷ εἶναι αὐτοὺς ἐκεῖ, ἐπλήσθησαν αἱ ἡμέραι τοῦ τεκεῖν αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Καὶ ἔτεκεν τὸν υἱὸν αὐτῆς τὸν πρωτότοκον, καὶ ἐσπαργάνωσεν αὐτὸν, καὶ ἀνέκλινεν αὐτὸν ἐν φάτνῃ, διότι οὐκ ἦν αὐτοῖς τόπος ἐν τῷ καταλύματι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, '¶Καὶ ποιμένες ἦσαν ἐν τῇ χώρᾳ τῇ αὐτῇ, ἀγραυλοῦντες καὶ φυλάσσοντες φυλακὰς τῆς νυκτὸς ἐπὶ τὴν ποίμνην αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Καὶ ἄγγελος  ̊Κυρίου ἐπέστη αὐτοῖς, καὶ δόξα  ̊Κυρίου περιέλαμψεν αὐτούς, καὶ ἐφοβήθησαν φόβον μέγαν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'Καὶ εἶπεν αὐτοῖς ὁ ἄγγελος, “Μὴ φοβεῖσθε, ἰδοὺ γὰρ, εὐαγγελίζομαι ὑμῖν χαρὰν μεγάλην, ἥτις ἔσται παντὶ τῷ λαῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'ὅτι ἐτέχθη ὑμῖν σήμερον Σωτὴρ, ὅς ἐστιν  ̊Χριστὸς,  ̊Κύριος, ἐν πόλει Δαυίδ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Καὶ τοῦτο ὑμῖν τὸ σημεῖον: εὑρήσετε βρέφος ἐσπαργανωμένον, καὶ κείμενον ἐν φάτνῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Καὶ ἐξαίφνης ἐγένετο σὺν τῷ ἀγγέλῳ πλῆθος στρατιᾶς οὐρανίου, αἰνούντων τὸν  ̊Θεὸν καὶ λεγόντων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, '“Δόξα ἐν ὑψίστοις  ̊Θεῷ, καὶ ἐπὶ γῆς εἰρήνη ἐν ἀνθρώποις εὐδοκίας!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, '¶Καὶ ἐγένετο ὡς ἀπῆλθον ἀπʼ αὐτῶν εἰς τὸν οὐρανὸν οἱ ἄγγελοι, οἱ ποιμένες ἐλάλουν πρὸς ἀλλήλους, “Διέλθωμεν δὴ ἕως Βηθλέεμ, καὶ ἴδωμεν τὸ ῥῆμα τοῦτο τὸ γεγονὸς, ὃ ὁ  ̊Κύριος ἐγνώρισεν ἡμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Καὶ ἦλθον σπεύσαντες, καὶ ἀνεῦραν τήν τε Μαριὰμ καὶ τὸν Ἰωσὴφ, καὶ τὸ βρέφος, κείμενον ἐν τῇ φάτνῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Ἰδόντες δὲ, ἐγνώρισαν περὶ τοῦ ῥήματος τοῦ λαληθέντος αὐτοῖς, περὶ τοῦ παιδίου τούτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Καὶ πάντες οἱ ἀκούσαντες, ἐθαύμασαν περὶ τῶν λαληθέντων ὑπὸ τῶν ποιμένων πρὸς αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Ἡ δὲ Μαρία πάντα συνετήρει τὰ ῥήματα ταῦτα, συμβάλλουσα ἐν τῇ καρδίᾳ αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Καὶ ὑπέστρεψαν οἱ ποιμένες, δοξάζοντες καὶ αἰνοῦντες τὸν  ̊Θεὸν ἐπὶ πᾶσιν οἷς ἤκουσαν καὶ εἶδον, καθὼς ἐλαλήθη πρὸς αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, '¶Καὶ ὅτε ἐπλήσθησαν ἡμέραι ὀκτὼ τοῦ περιτεμεῖν αὐτόν, καὶ ἐκλήθη τὸ ὄνομα αὐτοῦ  ̊Ἰησοῦς, τὸ κληθὲν ὑπὸ τοῦ ἀγγέλου πρὸ τοῦ συλλημφθῆναι αὐτὸν ἐν τῇ κοιλίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, '¶Καὶ ὅτε ἐπλήσθησαν αἱ ἡμέραι τοῦ καθαρισμοῦ αὐτῶν κατὰ τὸν νόμον Μωϋσέως, ἀνήγαγον αὐτὸν εἰς Ἱεροσόλυμα παραστῆσαι τῷ  ̊Κυρίῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'καθὼς γέγραπται ἐν νόμῳ  ̊Κυρίου, ὅτι “Πᾶν ἄρσεν διανοῖγον μήτραν, ἅγιον τῷ  ̊Κυρίῳ κληθήσεται”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'καὶ τοῦ δοῦναι θυσίαν, κατὰ τὸ εἰρημένον ἐν τῷ νόμῳ  ̊Κυρίου, “Ζεῦγος τρυγόνων ἢ δύο νοσσοὺς περιστερῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, '¶Καὶ ἰδοὺ, ἄνθρωπος ἦν ἐν Ἰερουσαλὴμ, ᾧ ὄνομα Συμεών, καὶ ὁ ἄνθρωπος οὗτος δίκαιος καὶ εὐλαβής, προσδεχόμενος παράκλησιν τοῦ Ἰσραήλ, καὶ  ̊Πνεῦμα ἦν Ἅγιον ἐπʼ αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 26, 'Καὶ ἦν αὐτῷ κεχρηματισμένον ὑπὸ τοῦ  ̊Πνεύματος τοῦ Ἁγίου, μὴ ἰδεῖν θάνατον πρὶν ἂν ἴδῃ τὸν  ̊Χριστὸν  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 27, 'Καὶ ἦλθεν ἐν τῷ  ̊Πνεύματι εἰς τὸ ἱερόν· καὶ ἐν τῷ εἰσαγαγεῖν τοὺς γονεῖς, τὸ παιδίον  ̊Ἰησοῦν, τοῦ ποιῆσαι αὐτοὺς κατὰ τὸ εἰθισμένον τοῦ νόμου περὶ αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 28, 'καὶ αὐτὸς ἐδέξατο αὐτὸ εἰς τὰς ἀγκάλας, καὶ εὐλόγησεν τὸν  ̊Θεὸν καὶ εἶπεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 29, '“Νῦν ἀπολύεις τὸν δοῦλόν σου, Δέσποτα, κατὰ τὸ ῥῆμά σου ἐν εἰρήνῃ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 30, 'ὅτι εἶδον οἱ ὀφθαλμοί μου τὸ σωτήριόν σου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 31, 'ὃ ἡτοίμασας κατὰ πρόσωπον πάντων τῶν λαῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 32, '‘φῶς εἰς ἀποκάλυψιν ἐθνῶν’ καὶ δόξαν λαοῦ σου, Ἰσραήλ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 33, 'Καὶ ἦν ὁ πατὴρ αὐτοῦ καὶ ἡ μήτηρ θαυμάζοντες ἐπὶ τοῖς λαλουμένοις περὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 34, 'Καὶ εὐλόγησεν αὐτοὺς Συμεὼν, καὶ εἶπεν πρὸς Μαριὰμ τὴν μητέρα αὐτοῦ, “Ἰδοὺ, οὗτος κεῖται εἰς πτῶσιν καὶ ἀνάστασιν πολλῶν ἐν τῷ Ἰσραὴλ, καὶ εἰς σημεῖον ἀντιλεγόμενον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 35, 'καὶ σοῦ αὐτῆς τὴν ψυχὴν διελεύσεται ῥομφαία, ὅπως ἂν ἀποκαλυφθῶσιν ἐκ πολλῶν καρδιῶν διαλογισμοί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 36, '¶Καὶ ἦν Ἅννα προφῆτις, θυγάτηρ Φανουήλ, ἐκ φυλῆς Ἀσήρ· αὕτη προβεβηκυῖα ἐν ἡμέραις πολλαῖς, ζήσασα μετὰ ἀνδρὸς ἔτη ἑπτὰ ἀπὸ τῆς παρθενίας αὐτῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 37, 'καὶ αὐτὴ χήρα ἕως ἐτῶν ὀγδοήκοντα τεσσάρων, ἣ οὐκ ἀφίστατο τοῦ ἱεροῦ, νηστείαις καὶ δεήσεσιν λατρεύουσα νύκτα καὶ ἡμέραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 38, 'Καὶ αὐτῇ τῇ ὥρᾳ ἐπιστᾶσα, ἀνθωμολογεῖτο τῷ  ̊Θεῷ, καὶ ἐλάλει περὶ αὐτοῦ, πᾶσιν τοῖς προσδεχομένοις λύτρωσιν Ἰερουσαλήμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 39, '¶Καὶ ὡς ἐτέλεσαν πάντα τὰ κατὰ τὸν νόμον  ̊Κυρίου, ἐπέστρεψαν εἰς τὴν Γαλιλαίαν, εἰς πόλιν ἑαυτῶν Ναζαρέτ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 40, 'Τὸ δὲ παιδίον ηὔξανεν καὶ ἐκραταιοῦτο, πληρούμενον σοφίᾳ, καὶ χάρις  ̊Θεοῦ ἦν ἐπʼ αὐτό.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 41, '¶Καὶ ἐπορεύοντο οἱ γονεῖς αὐτοῦ κατʼ ἔτος εἰς Ἰερουσαλὴμ τῇ ἑορτῇ τοῦ Πάσχα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 42, 'Καὶ ὅτε ἐγένετο ἐτῶν δώδεκα, ἀναβαινόντων αὐτῶν κατὰ τὸ ἔθος τῆς ἑορτῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 43, 'καὶ τελειωσάντων τὰς ἡμέρας, ἐν τῷ ὑποστρέφειν αὐτοὺς, ὑπέμεινεν  ̊Ἰησοῦς, ὁ παῖς ἐν Ἰερουσαλήμ, καὶ οὐκ ἔγνωσαν οἱ γονεῖς αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 44, 'Νομίσαντες δὲ αὐτὸν εἶναι ἐν τῇ συνοδίᾳ, ἦλθον ἡμέρας ὁδὸν καὶ ἀνεζήτουν αὐτὸν ἐν τοῖς συγγενέσιν καὶ τοῖς γνωστοῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 45, 'καὶ μὴ εὑρόντες, ὑπέστρεψαν εἰς Ἰερουσαλὴμ, ἀναζητοῦντες αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 46, 'Καὶ ἐγένετο μετὰ ἡμέρας τρεῖς, εὗρον αὐτὸν ἐν τῷ ἱερῷ, καθεζόμενον ἐν μέσῳ τῶν διδασκάλων, καὶ ἀκούοντα αὐτῶν καὶ ἐπερωτῶντα αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 47, 'Ἐξίσταντο δὲ πάντες οἱ ἀκούοντες αὐτοῦ ἐπὶ τῇ συνέσει καὶ ταῖς ἀποκρίσεσιν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 48, 'Καὶ ἰδόντες αὐτὸν, ἐξεπλάγησαν καὶ εἶπεν πρὸς αὐτὸν ἡ μήτηρ αὐτοῦ, “Τέκνον, τί ἐποίησας ἡμῖν οὕτως; Ἰδοὺ, ὁ πατήρ σου κἀγὼ, ὀδυνώμενοι ζητοῦμέν σε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 49, 'Καὶ εἶπεν πρὸς αὐτούς, “Τί ὅτι ἐζητεῖτέ με; Οὐκ ᾔδειτε ὅτι ἐν τοῖς τοῦ πατρός μου δεῖ εἶναί με;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 50, 'Καὶ αὐτοὶ οὐ συνῆκαν τὸ ῥῆμα ὃ ἐλάλησεν αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 51, 'Καὶ κατέβη μετʼ αὐτῶν καὶ ἦλθεν εἰς Ναζαρέτ, καὶ ἦν ὑποτασσόμενος αὐτοῖς. Καὶ ἡ μήτηρ αὐτοῦ διετήρει πάντα τὰ ῥήματα ἐν τῇ καρδίᾳ αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 52, '¶Καὶ  ̊Ἰησοῦς προέκοπτεν τῇ σοφίᾳ, καὶ ἡλικίᾳ, καὶ χάριτι παρὰ  ̊Θεῷ καὶ ἀνθρώποις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, '¶Ἐν ἔτει δὲ πεντεκαιδεκάτῳ τῆς ἡγεμονίας Τιβερίου Καίσαρος, ἡγεμονεύοντος Ποντίου Πιλάτου τῆς Ἰουδαίας, καὶ τετρααρχοῦντος τῆς Γαλιλαίας Ἡρῴδου, Φιλίππου δὲ τοῦ ἀδελφοῦ αὐτοῦ τετραρχοῦντος τῆς Ἰτουραίας καὶ Τραχωνίτιδος χώρας, καὶ Λυσανίου τῆς Ἀβιληνῆς τετραρχοῦντος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'ἐπὶ ἀρχιερέως Ἅννα καὶ Καϊάφα, ἐγένετο ῥῆμα  ̊Θεοῦ ἐπὶ Ἰωάννην, τὸν Ζαχαρίου υἱὸν, ἐν τῇ ἐρήμῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Καὶ ἦλθεν εἰς πᾶσαν περίχωρον τοῦ Ἰορδάνου, κηρύσσων βάπτισμα μετανοίας εἰς ἄφεσιν ἁμαρτιῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'ὡς γέγραπται ἐν βίβλῳ λόγων Ἠσαΐου τοῦ προφήτου, “Φωνὴ βοῶντος ἐν τῇ ἐρήμῳ: ‘Ἑτοιμάσατε τὴν ὁδὸν  ̊Κυρίου, εὐθείας ποιεῖτε τὰς τρίβους αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Πᾶσα φάραγξ πληρωθήσεται, καὶ πᾶν ὄρος καὶ βουνὸς ταπεινωθήσεται, καὶ ἔσται τὰ σκολιὰ εἰς εὐθείαν, καὶ αἱ τραχεῖαι εἰς ὁδοὺς λείας·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'καὶ ὄψεται πᾶσα σὰρξ τὸ σωτήριον τοῦ  ̊Θεοῦ.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, '¶Ἔλεγεν οὖν τοῖς ἐκπορευομένοις ὄχλοις βαπτισθῆναι ὑπʼ αὐτοῦ, “Γεννήματα ἐχιδνῶν, τίς ὑπέδειξεν ὑμῖν φυγεῖν ἀπὸ τῆς μελλούσης ὀργῆς;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Ποιήσατε οὖν καρποὺς ἀξίους τῆς μετανοίας· καὶ μὴ ἄρξησθε λέγειν ἐν ἑαυτοῖς, ‘Πατέρα ἔχομεν τὸν Ἀβραάμ’, λέγω γὰρ ὑμῖν ὅτι δύναται ὁ  ̊Θεὸς ἐκ τῶν λίθων τούτων ἐγεῖραι τέκνα τῷ Ἀβραάμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Ἤδη δὲ καὶ ἡ ἀξίνη πρὸς τὴν ῥίζαν τῶν δένδρων κεῖται· πᾶν οὖν δένδρον μὴ ποιοῦν καρπὸν καλὸν, ἐκκόπτεται καὶ εἰς πῦρ βάλλεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, '¶Καὶ ἐπηρώτων αὐτὸν οἱ ὄχλοι λέγοντες, “Τί οὖν ποιήσωμεν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Ἀποκριθεὶς δὲ ἔλεγεν αὐτοῖς, “Ὁ ἔχων δύο χιτῶνας, μεταδότω τῷ μὴ ἔχοντι, καὶ ὁ ἔχων βρώματα, ὁμοίως ποιείτω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Ἦλθον δὲ καὶ τελῶναι βαπτισθῆναι, καὶ εἶπον πρὸς αὐτόν, “Διδάσκαλε, τί ποιήσωμεν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Ὁ δὲ εἶπεν πρὸς αὐτούς, “Μηδὲν πλέον παρὰ τὸ διατεταγμένον ὑμῖν πράσσετε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Ἐπηρώτων δὲ αὐτὸν καὶ στρατευόμενοι λέγοντες, “Τί ποιήσωμεν καὶ ἡμεῖς;” Καὶ εἶπεν αὐτοῖς, “Μηδένα διασείσητε μηδὲ συκοφαντήσητε, καὶ ἀρκεῖσθε τοῖς ὀψωνίοις ὑμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, '¶Προσδοκῶντος δὲ τοῦ λαοῦ καὶ διαλογιζομένων πάντων ἐν ταῖς καρδίαις αὐτῶν περὶ τοῦ Ἰωάννου, μήποτε αὐτὸς εἴη ὁ  ̊Χριστός,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'ἀπεκρίνατο λέγων πᾶσιν ὁ Ἰωάννης, “Ἐγὼ μὲν ὕδατι βαπτίζω ὑμᾶς, ἔρχεται δὲ ὁ ἰσχυρότερός μου, οὗ οὐκ εἰμὶ ἱκανὸς λῦσαι τὸν ἱμάντα τῶν ὑποδημάτων αὐτοῦ· αὐτὸς ὑμᾶς βαπτίσει ἐν  ̊Πνεύματι Ἁγίῳ, καὶ πυρί·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'οὗ τὸ πτύον ἐν τῇ χειρὶ αὐτοῦ διακαθᾶραι τὴν ἅλωνα αὐτοῦ, καὶ συναγαγεῖν τὸν σῖτον εἰς τὴν ἀποθήκην αὐτοῦ, τὸ δὲ ἄχυρον κατακαύσει πυρὶ ἀσβέστῳ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, '¶Πολλὰ μὲν οὖν καὶ ἕτερα παρακαλῶν, εὐηγγελίζετο τὸν λαόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'Ὁ δὲ Ἡρῴδης ὁ τετράρχης, ἐλεγχόμενος ὑπʼ αὐτοῦ περὶ Ἡρῳδιάδος, τῆς γυναικὸς τοῦ ἀδελφοῦ αὐτοῦ, καὶ περὶ πάντων ὧν ἐποίησεν πονηρῶν ὁ Ἡρῴδης,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'προσέθηκεν καὶ τοῦτο ἐπὶ πᾶσιν: κατέκλεισεν τὸν Ἰωάννην ἐν φυλακῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, '¶Ἐγένετο δὲ ἐν τῷ βαπτισθῆναι ἅπαντα τὸν λαὸν, καὶ  ̊Ἰησοῦ βαπτισθέντος, καὶ προσευχομένου ἀνεῳχθῆναι τὸν οὐρανὸν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'καὶ καταβῆναι τὸ  ̊Πνεῦμα τὸ Ἅγιον σωματικῷ εἴδει, ὡς περιστερὰν ἐπʼ αὐτόν, καὶ φωνὴν ἐξ οὐρανοῦ γενέσθαι: “Σὺ εἶ ὁ Υἱός μου ὁ ἀγαπητός, ἐν σοὶ εὐδόκησα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 23, '¶Καὶ αὐτὸς ἦν  ̊Ἰησοῦς ἀρχόμενος ὡσεὶ ἐτῶν τριάκοντα, ὢν υἱός, ὡς ἐνομίζετο, Ἰωσὴφ, τοῦ Ἠλὶ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 24, 'τοῦ Ματθάτ, τοῦ Λευὶ, τοῦ Μελχὶ, τοῦ Ἰανναὶ, τοῦ Ἰωσὴφ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 25, 'τοῦ Ματταθίου, τοῦ Ἀμὼς, τοῦ Ναοὺμ, τοῦ Ἑσλὶ, τοῦ Ναγγαὶ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 26, 'τοῦ Μάαθ, τοῦ Ματταθίου, τοῦ Σεμεῒν, τοῦ Ἰωσὴχ, τοῦ Ἰωδὰ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 27, 'τοῦ Ἰωανὰν, τοῦ Ῥησὰ, τοῦ Ζοροβαβὲλ, τοῦ Σαλαθιὴλ, τοῦ Νηρὶ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 28, 'τοῦ Μελχὶ, τοῦ Ἀδδὶ, τοῦ Κωσὰμ, τοῦ Ἐλμαδὰμ, τοῦ Ἢρ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 29, 'τοῦ Ἰησοῦ, τοῦ Ἐλιέζερ, τοῦ Ἰωρεὶμ, τοῦ Μαθθὰτ, τοῦ Λευὶ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 30, 'τοῦ Συμεὼν, τοῦ Ἰούδα, τοῦ Ἰωσὴφ, τοῦ Ἰωνὰμ, τοῦ Ἐλιακεὶμ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 31, 'τοῦ Μελεὰ, τοῦ Μεννὰ, τοῦ Ματταθὰ, τοῦ Ναθὰμ, τοῦ Δαυὶδ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 32, 'τοῦ Ἰεσσαὶ, τοῦ Ἰωβὴδ, τοῦ Βόος, τοῦ Σαλὰ, τοῦ Ναασσὼν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 33, 'τοῦ Ἀμιναδὰβ, τοῦ Ἀδμὶν, τοῦ Ἀρνὶ, τοῦ Ἑσρὼμ, τοῦ Φαρὲς, τοῦ Ἰούδα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 34, 'τοῦ Ἰακὼβ, τοῦ Ἰσαὰκ, τοῦ Ἀβραὰμ, τοῦ Θάρα, τοῦ Ναχὼρ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 35, 'τοῦ Σεροὺχ, τοῦ Ῥαγαὺ, τοῦ Φάλεκ, τοῦ Ἔβερ, τοῦ Σαλὰ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 36, 'τοῦ Καϊνὰμ, τοῦ Ἀρφαξὰδ, τοῦ Σὴμ, τοῦ Νῶε, τοῦ Λάμεχ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 37, 'τοῦ Μαθουσαλὰ, τοῦ Ἑνὼχ, τοῦ Ἰάρετ, τοῦ Μαλελεὴλ, τοῦ Καϊνὰμ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 38, 'τοῦ Ἐνὼς, τοῦ Σὴθ, τοῦ Ἀδὰμ, τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, '¶ ̊Ἰησοῦς δὲ πλήρης  ̊Πνεύματος Ἁγίου, ὑπέστρεψεν ἀπὸ τοῦ Ἰορδάνου, καὶ ἤγετο ἐν τῷ  ̊Πνεύματι ἐν τῇ ἐρήμῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'ἡμέρας τεσσεράκοντα πειραζόμενος ὑπὸ τοῦ διαβόλου. Καὶ οὐκ ἔφαγεν οὐδὲν ἐν ταῖς ἡμέραις ἐκείναις, καὶ συντελεσθεισῶν αὐτῶν, ἐπείνασεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Εἶπεν δὲ αὐτῷ ὁ διάβολος, “Εἰ Υἱὸς εἶ τοῦ  ̊Θεοῦ, εἰπὲ τῷ λίθῳ τούτῳ ἵνα γένηται ἄρτος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Καὶ ἀπεκρίθη πρὸς αὐτὸν ὁ  ̊Ἰησοῦς, “Γέγραπται, ὅτι ‘Οὐκ ἐπʼ ἄρτῳ μόνῳ ζήσεται ὁ ἄνθρωπος.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, '¶Καὶ ἀναγαγὼν αὐτὸν ἔδειξεν αὐτῷ πάσας τὰς βασιλείας τῆς οἰκουμένης ἐν στιγμῇ χρόνου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Καὶ εἶπεν αὐτῷ ὁ διάβολος, “Σοὶ δώσω τὴν ἐξουσίαν ταύτην ἅπασαν καὶ τὴν δόξαν αὐτῶν, ὅτι ἐμοὶ παραδέδοται καὶ ᾧ ἐὰν θέλω, δίδωμι αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Σὺ οὖν ἐὰν προσκυνήσῃς ἐνώπιον ἐμοῦ, ἔσται σοῦ πᾶσα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Καὶ ἀποκριθεὶς ὁ  ̊Ἰησοῦς εἶπεν αὐτῷ, “Γέγραπται, ‘ ̊Κύριον τὸν  ̊Θεόν σου προσκυνήσεις καὶ αὐτῷ μόνῳ λατρεύσεις.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, '¶Ἤγαγεν δὲ αὐτὸν εἰς Ἰερουσαλὴμ, καὶ ἔστησεν ἐπὶ τὸ πτερύγιον τοῦ ἱεροῦ, καὶ εἶπεν αὐτῷ, “Εἰ Υἱὸς εἶ τοῦ  ̊Θεοῦ, βάλε σεαυτὸν ἐντεῦθεν κάτω·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'γέγραπται γὰρ, ὅτι ‘Τοῖς ἀγγέλοις αὐτοῦ ἐντελεῖται περὶ σοῦ, τοῦ διαφυλάξαι σε’,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'καὶ, ὅτι ‘Ἐπὶ χειρῶν ἀροῦσίν σε, μήποτε προσκόψῃς πρὸς λίθον τὸν πόδα σου.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Καὶ ἀποκριθεὶς εἶπεν αὐτῷ ὁ  ̊Ἰησοῦς, ὅτι “Εἴρηται, ‘Οὐκ ἐκπειράσεις  ̊Κύριον τὸν  ̊Θεόν σου.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Καὶ συντελέσας πάντα πειρασμὸν, ὁ διάβολος ἀπέστη ἀπʼ αὐτοῦ ἄχρι καιροῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, '¶Καὶ ὑπέστρεψεν ὁ  ̊Ἰησοῦς ἐν τῇ δυνάμει τοῦ  ̊Πνεύματος εἰς τὴν Γαλιλαίαν. Καὶ φήμη ἐξῆλθεν καθʼ ὅλης τῆς περιχώρου περὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Καὶ αὐτὸς ἐδίδασκεν ἐν ταῖς συναγωγαῖς αὐτῶν, δοξαζόμενος ὑπὸ πάντων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, '¶Καὶ ἦλθεν εἰς Ναζαρά, οὗ ἦν τεθραμμένος, καὶ εἰσῆλθεν κατὰ τὸ εἰωθὸς αὐτῷ, ἐν τῇ ἡμέρᾳ τῶν Σαββάτων εἰς τὴν συναγωγήν, καὶ ἀνέστη ἀναγνῶναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Καὶ ἐπεδόθη αὐτῷ βιβλίον τοῦ προφήτου Ἠσαΐου, καὶ ἀνοίξας τὸ βιβλίον, εὗρεν τὸν τόπον οὗ ἦν γεγραμμένον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, '“ ̊Πνεῦμα  ̊Κυρίου ἐπʼ ἐμέ, οὗ εἵνεκεν ἔχρισέν με εὐαγγελίσασθαι πτωχοῖς, ἀπέσταλκέν με κηρύξαι αἰχμαλώτοις ἄφεσιν, καὶ τυφλοῖς ἀνάβλεψιν, ἀποστεῖλαι τεθραυσμένους ἐν ἀφέσει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'κηρύξαι ἐνιαυτὸν  ̊Κυρίου δεκτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 20, 'Καὶ πτύξας τὸ βιβλίον ἀποδοὺς τῷ ὑπηρέτῃ, ἐκάθισεν καὶ πάντων οἱ ὀφθαλμοὶ ἐν τῇ συναγωγῇ ἦσαν ἀτενίζοντες αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 21, 'Ἤρξατο δὲ λέγειν πρὸς αὐτοὺς, ὅτι “Σήμερον πεπλήρωται ἡ Γραφὴ αὕτη ἐν τοῖς ὠσὶν ὑμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 22, 'Καὶ πάντες ἐμαρτύρουν αὐτῷ, καὶ ἐθαύμαζον ἐπὶ τοῖς λόγοις τῆς χάριτος τοῖς ἐκπορευομένοις ἐκ τοῦ στόματος αὐτοῦ, καὶ ἔλεγον, “Οὐχὶ υἱός ἐστιν Ἰωσὴφ οὗτος;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 23, 'Καὶ εἶπεν πρὸς αὐτούς, “Πάντως ἐρεῖτέ μοι τὴν παραβολὴν ταύτην: ‘“Ἰατρέ, θεράπευσον σεαυτόν”· ὅσα ἠκούσαμεν γενόμενα εἰς τὴν Καφαρναοὺμ, ποίησον καὶ ὧδε ἐν τῇ πατρίδι σου.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 24, 'Εἶπεν δέ, “Ἀμὴν, λέγω ὑμῖν ὅτι οὐδεὶς προφήτης δεκτός ἐστιν ἐν τῇ πατρίδι αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 25, 'Ἐπʼ ἀληθείας δὲ λέγω ὑμῖν, πολλαὶ χῆραι ἦσαν ἐν ταῖς ἡμέραις Ἠλίου ἐν τῷ Ἰσραήλ, ὅτε ἐκλείσθη ὁ οὐρανὸς ἐπὶ ἔτη τρία καὶ μῆνας ἕξ, ὡς ἐγένετο λιμὸς μέγας ἐπὶ πᾶσαν τὴν γῆν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 26, 'καὶ πρὸς οὐδεμίαν αὐτῶν ἐπέμφθη Ἠλίας, εἰ μὴ εἰς Σάρεπτα τῆς Σιδωνίας, πρὸς γυναῖκα χήραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 27, 'Καὶ πολλοὶ λεπροὶ ἦσαν ἐν τῷ Ἰσραὴλ, ἐπὶ Ἐλισαίου τοῦ προφήτου, καὶ οὐδεὶς αὐτῶν ἐκαθαρίσθη, εἰ μὴ Ναιμὰν ὁ Σύρος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 28, 'Καὶ ἐπλήσθησαν πάντες θυμοῦ ἐν τῇ συναγωγῇ ἀκούοντες ταῦτα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 29, 'καὶ ἀναστάντες, ἐξέβαλον αὐτὸν ἔξω τῆς πόλεως, καὶ ἤγαγον αὐτὸν ἕως ὀφρύος τοῦ ὄρους ἐφʼ οὗ ἡ πόλις ᾠκοδόμητο αὐτῶν, ὥστε κατακρημνίσαι αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 30, 'Αὐτὸς δὲ, διελθὼν διὰ μέσου αὐτῶν, ἐπορεύετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 31, '¶Καὶ κατῆλθεν εἰς Καφαρναοὺμ, πόλιν τῆς Γαλιλαίας. Καὶ ἦν διδάσκων αὐτοὺς ἐν τοῖς Σάββασιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 32, 'Καὶ ἐξεπλήσσοντο ἐπὶ τῇ διδαχῇ αὐτοῦ, ὅτι ἐν ἐξουσίᾳ ἦν ὁ λόγος αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 33, 'Καὶ ἐν τῇ συναγωγῇ ἦν ἄνθρωπος ἔχων πνεῦμα δαιμονίου ἀκαθάρτου, καὶ ἀνέκραξεν φωνῇ μεγάλῃ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 34, '“Ἔα! Τί ἡμῖν καὶ σοί,  ̊Ἰησοῦ Ναζαρηνέ; Ἦλθες ἀπολέσαι ἡμᾶς; Οἶδά σε τίς εἶ, ὁ Ἅγιος τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 35, 'Καὶ ἐπετίμησεν αὐτῷ ὁ  ̊Ἰησοῦς λέγων, “Φιμώθητι, καὶ ἔξελθε ἐξ αὐτοῦ!” Καὶ ῥίψαν αὐτὸν τὸ δαιμόνιον εἰς τὸ μέσον, ἐξῆλθεν ἀπʼ αὐτοῦ, μηδὲν βλάψαν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 36, 'Καὶ ἐγένετο θάμβος ἐπὶ πάντας, καὶ συνελάλουν πρὸς ἀλλήλους λέγοντες, “Τίς ὁ λόγος οὗτος, ὅτι ἐν ἐξουσίᾳ καὶ δυνάμει ἐπιτάσσει τοῖς ἀκαθάρτοις πνεύμασιν, καὶ ἐξέρχονται;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 37, 'Καὶ ἐξεπορεύετο ἦχος περὶ αὐτοῦ εἰς πάντα τόπον τῆς περιχώρου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 38, '¶Ἀναστὰς δὲ ἀπὸ τῆς συναγωγῆς, εἰσῆλθεν εἰς τὴν οἰκίαν Σίμωνος. Πενθερὰ δὲ τοῦ Σίμωνος ἦν συνεχομένη πυρετῷ μεγάλῳ, καὶ ἠρώτησαν αὐτὸν περὶ αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 39, 'Καὶ ἐπιστὰς ἐπάνω αὐτῆς, ἐπετίμησεν τῷ πυρετῷ, καὶ ἀφῆκεν αὐτήν· παραχρῆμα δὲ ἀναστᾶσα, διηκόνει αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 40, '¶Δύνοντος δὲ τοῦ ἡλίου, πάντες ὅσοι εἶχον ἀσθενοῦντας νόσοις ποικίλαις, ἤγαγον αὐτοὺς πρὸς αὐτόν, ὁ δὲ ἑνὶ ἑκάστῳ αὐτῶν, τὰς χεῖρας ἐπιτιθεὶς, ἐθεράπευεν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 41, 'Ἐξήρχετο δὲ καὶ δαιμόνια ἀπὸ πολλῶν, κράζοντα καὶ λέγοντα, ὅτι “Σὺ εἶ ὁ Υἱὸς τοῦ  ̊Θεοῦ.” Καὶ ἐπιτιμῶν, οὐκ εἴα αὐτὰ λαλεῖν, ὅτι ᾔδεισαν τὸν  ̊Χριστὸν αὐτὸν εἶναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 42, '¶Γενομένης δὲ ἡμέρας, ἐξελθὼν ἐπορεύθη εἰς ἔρημον τόπον, καὶ οἱ ὄχλοι ἐπεζήτουν αὐτόν, καὶ ἦλθον ἕως αὐτοῦ, καὶ κατεῖχον αὐτὸν τοῦ μὴ πορεύεσθαι ἀπʼ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 43, 'Ὁ δὲ εἶπεν πρὸς αὐτοὺς, ὅτι “Καὶ ταῖς ἑτέραις πόλεσιν εὐαγγελίσασθαί με δεῖ τὴν Βασιλείαν τοῦ  ̊Θεοῦ, ὅτι ἐπὶ τοῦτο ἀπεστάλην.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 44, 'Καὶ ἦν κηρύσσων εἰς τὰς συναγωγὰς τῆς Ἰουδαίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, '¶Ἐγένετο δὲ ἐν τῷ, τὸν ὄχλον ἐπικεῖσθαι αὐτῷ καὶ ἀκούειν τὸν λόγον τοῦ  ̊Θεοῦ, καὶ αὐτὸς ἦν ἑστὼς παρὰ τὴν λίμνην Γεννησαρέτ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'καὶ εἶδεν δύο πλοῖα ἑστῶτα παρὰ τὴν λίμνην, οἱ δὲ ἁλιεῖς ἀπʼ αὐτῶν ἀποβάντες, ἔπλυνον τὰ δίκτυα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Ἐμβὰς δὲ εἰς ἓν τῶν πλοίων, ὃ ἦν Σίμωνος, ἠρώτησεν αὐτὸν ἀπὸ τῆς γῆς ἐπαναγαγεῖν ὀλίγον. Καθίσας δὲ, ἐδίδασκεν ἐκ τοῦ πλοίου τοὺς ὄχλους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'Ὡς δὲ ἐπαύσατο λαλῶν, εἶπεν πρὸς τὸν Σίμωνα, “Ἐπανάγαγε εἰς τὸ βάθος καὶ χαλάσατε τὰ δίκτυα ὑμῶν εἰς ἄγραν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Καὶ ἀποκριθεὶς Σίμων εἶπεν, “Ἐπιστάτα, διʼ ὅλης νυκτὸς κοπιάσαντες, οὐδὲν ἐλάβομεν, ἐπὶ δὲ τῷ ῥήματί σου, χαλάσω τὰ δίκτυα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Καὶ τοῦτο ποιήσαντες, συνέκλεισαν πλῆθος ἰχθύων πολύ, διερρήσσετο δὲ τὰ δίκτυα αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Καὶ κατένευσαν τοῖς μετόχοις ἐν τῷ ἑτέρῳ πλοίῳ, τοῦ ἐλθόντας συλλαβέσθαι αὐτοῖς· καὶ ἦλθον, καὶ ἔπλησαν ἀμφότερα τὰ πλοῖα, ὥστε βυθίζεσθαι αὐτά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Ἰδὼν δὲ, Σίμων Πέτρος προσέπεσεν τοῖς γόνασιν  ̊Ἰησοῦ λέγων, “Ἔξελθε ἀπʼ ἐμοῦ, ὅτι ἀνὴρ ἁμαρτωλός εἰμι,  ̊Κύριε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Θάμβος γὰρ περιέσχεν αὐτὸν καὶ πάντας τοὺς σὺν αὐτῷ, ἐπὶ τῇ ἄγρᾳ τῶν ἰχθύων ὧν συνέλαβον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'ὁμοίως δὲ καὶ Ἰάκωβον καὶ Ἰωάννην, υἱοὺς Ζεβεδαίου, οἳ ἦσαν κοινωνοὶ τῷ Σίμωνι. Καὶ εἶπεν πρὸς τὸν Σίμωνα ὁ  ̊Ἰησοῦς, “Μὴ φοβοῦ· ἀπὸ τοῦ νῦν ἀνθρώπους ἔσῃ ζωγρῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Καὶ καταγαγόντες τὰ πλοῖα ἐπὶ τὴν γῆν, ἀφέντες πάντα, ἠκολούθησαν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, '¶Καὶ ἐγένετο ἐν τῷ εἶναι αὐτὸν ἐν μιᾷ τῶν πόλεων, καὶ ἰδοὺ, ἀνὴρ πλήρης λέπρας, ἰδὼν δὲ τὸν  ̊Ἰησοῦν, πεσὼν ἐπὶ πρόσωπον, ἐδεήθη αὐτοῦ λέγων, “ ̊Κύριε, ἐὰν θέλῃς, δύνασαί με καθαρίσαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Καὶ ἐκτείνας τὴν χεῖρα, ἥψατο αὐτοῦ λέγων, “Θέλω, καθαρίσθητι!” Καὶ εὐθέως ἡ λέπρα ἀπῆλθεν ἀπʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Καὶ αὐτὸς παρήγγειλεν αὐτῷ, “Μηδενὶ εἰπεῖν, ἀλλὰ ἀπελθὼν δεῖξον σεαυτὸν τῷ ἱερεῖ, καὶ προσένεγκε περὶ τοῦ καθαρισμοῦ σου καθὼς προσέταξεν Μωϋσῆς, εἰς μαρτύριον αὐτοῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 15, 'Διήρχετο δὲ μᾶλλον ὁ λόγος περὶ αὐτοῦ, καὶ συνήρχοντο ὄχλοι πολλοὶ ἀκούειν, καὶ θεραπεύεσθαι ἀπὸ τῶν ἀσθενειῶν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 16, 'Αὐτὸς δὲ ἦν ὑποχωρῶν ἐν ταῖς ἐρήμοις καὶ προσευχόμενος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 17, '¶Καὶ ἐγένετο ἐν μιᾷ τῶν ἡμερῶν, καὶ αὐτὸς ἦν διδάσκων, καὶ ἦσαν καθήμενοι Φαρισαῖοι καὶ νομοδιδάσκαλοι, οἳ ἦσαν ἐληλυθότες ἐκ πάσης κώμης τῆς Γαλιλαίας, καὶ Ἰουδαίας, καὶ Ἰερουσαλήμ. Καὶ δύναμις  ̊Κυρίου ἦν εἰς τὸ ἰᾶσθαι αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 18, 'Καὶ ἰδοὺ, ἄνδρες φέροντες ἐπὶ κλίνης ἄνθρωπον ὃς ἦν παραλελυμένος, καὶ ἐζήτουν αὐτὸν εἰσενεγκεῖν καὶ θεῖναι ἐνώπιον αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 19, 'Καὶ μὴ εὑρόντες ποίας εἰσενέγκωσιν αὐτὸν διὰ τὸν ὄχλον, ἀναβάντες ἐπὶ τὸ δῶμα, διὰ τῶν κεράμων καθῆκαν αὐτὸν σὺν τῷ κλινιδίῳ εἰς τὸ μέσον ἔμπροσθεν τοῦ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 20, 'Καὶ ἰδὼν τὴν πίστιν αὐτῶν εἶπεν, “Ἄνθρωπε, ἀφέωνταί σοι αἱ ἁμαρτίαι σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 21, 'Καὶ ἤρξαντο διαλογίζεσθαι οἱ γραμματεῖς καὶ οἱ Φαρισαῖοι λέγοντες, “Τίς ἐστιν οὗτος ὃς λαλεῖ βλασφημίας; Τίς δύναται ἀφιέναι ἁμαρτίας εἰ μὴ μόνος ὁ  ̊Θεός;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 22, 'Ἐπιγνοὺς δὲ ὁ  ̊Ἰησοῦς τοὺς διαλογισμοὺς αὐτῶν, ἀποκριθεὶς εἶπεν πρὸς αὐτούς, “Τί διαλογίζεσθε ἐν ταῖς καρδίαις ὑμῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 23, 'Τί ἐστιν εὐκοπώτερον, εἰπεῖν, ‘Ἀφέωνταί σοι αἱ ἁμαρτίαι σου’, ἢ εἰπεῖν, ‘Ἔγειρε καὶ περιπάτει’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 24, 'Ἵνα δὲ εἰδῆτε ὅτι ὁ Υἱὸς τοῦ Ἀνθρώπου ἐξουσίαν ἔχει ἐπὶ τῆς γῆς ἀφιέναι ἁμαρτίας”, εἶπεν τῷ παραλελυμένῳ, “σοὶ λέγω, ἔγειρε, καὶ ἄρας τὸ κλινίδιόν σου, πορεύου εἰς τὸν οἶκόν σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 25, 'Καὶ παραχρῆμα ἀναστὰς ἐνώπιον αὐτῶν, ἄρας ἐφʼ ὃ κατέκειτο, ἀπῆλθεν εἰς τὸν οἶκον αὐτοῦ δοξάζων τὸν  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 26, 'Καὶ ἔκστασις ἔλαβεν ἅπαντας, καὶ ἐδόξαζον τὸν  ̊Θεόν, καὶ ἐπλήσθησαν φόβου λέγοντες, ὅτι “Εἴδομεν παράδοξα σήμερον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 27, '¶Καὶ μετὰ ταῦτα ἐξῆλθεν, καὶ ἐθεάσατο τελώνην ὀνόματι Λευὶν, καθήμενον ἐπὶ τὸ τελώνιον, καὶ εἶπεν αὐτῷ, “Ἀκολούθει μοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 28, 'Καὶ καταλιπὼν πάντα, ἀναστὰς ἠκολούθει αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 29, '¶Καὶ ἐποίησεν δοχὴν μεγάλην Λευὶς αὐτῷ ἐν τῇ οἰκίᾳ αὐτοῦ, καὶ ἦν ὄχλος πολὺς τελωνῶν καὶ ἄλλων, οἳ ἦσαν μετʼ αὐτῶν κατακείμενοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 30, 'Καὶ ἐγόγγυζον οἱ Φαρισαῖοι καὶ οἱ γραμματεῖς αὐτῶν πρὸς τοὺς μαθητὰς αὐτοῦ λέγοντες, “Διὰ τί μετὰ τῶν τελωνῶν καὶ ἁμαρτωλῶν ἐσθίετε καὶ πίνετε;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 31, 'Καὶ ἀποκριθεὶς ὁ  ̊Ἰησοῦς εἶπεν πρὸς αὐτούς, “Οὐ χρείαν ἔχουσιν οἱ ὑγιαίνοντες ἰατροῦ, ἀλλὰ οἱ κακῶς ἔχοντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 32, 'Οὐκ ἐλήλυθα καλέσαι δικαίους, ἀλλὰ ἁμαρτωλοὺς εἰς μετάνοιαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 33, '¶Οἱ δὲ εἶπαν πρὸς αὐτόν, “Οἱ μαθηταὶ Ἰωάννου νηστεύουσιν πυκνὰ, καὶ δεήσεις ποιοῦνται, ὁμοίως καὶ οἱ τῶν Φαρισαίων, οἱ δὲ σοὶ ἐσθίουσιν καὶ πίνουσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 34, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν πρὸς αὐτούς, “Μὴ δύνασθε τοὺς υἱοὺς τοῦ νυμφῶνος ἐν ᾧ ὁ νυμφίος μετʼ αὐτῶν ἐστιν ποιῆσαι νηστεύειν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 35, 'Ἐλεύσονται δὲ ἡμέραι καὶ ὅταν ἀπαρθῇ ἀπʼ αὐτῶν ὁ νυμφίος, τότε νηστεύσουσιν ἐν ἐκείναις ταῖς ἡμέραις.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 36, 'Ἔλεγεν δὲ καὶ παραβολὴν πρὸς αὐτοὺς: ὅτι “Οὐδεὶς ἐπίβλημα ἀπὸ ἱματίου καινοῦ σχίσας, ἐπιβάλλει ἐπὶ ἱμάτιον παλαιόν· εἰ δὲ μή γε καὶ τὸ καινὸν σχίσει, καὶ τῷ παλαιῷ οὐ συμφωνήσει τὸ ἐπίβλημα τὸ ἀπὸ τοῦ καινοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 37, 'Καὶ οὐδεὶς βάλλει οἶνον νέον εἰς ἀσκοὺς παλαιούς· εἰ δὲ μή γε ῥήξει ὁ οἶνος ὁ νέος τοὺς ἀσκούς, καὶ αὐτὸς ἐκχυθήσεται, καὶ οἱ ἀσκοὶ ἀπολοῦνται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 38, 'Ἀλλὰ οἶνον νέον εἰς ἀσκοὺς καινοὺς βλητέον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 39, 'Οὐδεὶς πιὼν παλαιὸν θέλει νέον· λέγει γάρ, ‘Ὁ παλαιὸς χρηστός ἐστιν.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 1, '¶Ἐγένετο δὲ ἐν Σαββάτῳ διαπορεύεσθαι αὐτὸν διὰ σπορίμων, καὶ ἔτιλλον οἱ μαθηταὶ αὐτοῦ, καὶ ἤσθιον τοὺς στάχυας, ψώχοντες ταῖς χερσίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 2, 'Τινὲς δὲ τῶν Φαρισαίων εἶπον, “Τί ποιεῖτε ὃ οὐκ ἔξεστιν τοῖς Σάββασιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 3, 'Καὶ ἀποκριθεὶς πρὸς αὐτοὺς εἶπεν ὁ  ̊Ἰησοῦς, “Οὐδὲ τοῦτο ἀνέγνωτε, ὃ ἐποίησεν Δαυὶδ ὅτε ἐπείνασεν αὐτὸς, καὶ οἱ μετʼ αὐτοῦ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 4, 'ὡς εἰσῆλθεν εἰς τὸν οἶκον τοῦ  ̊Θεοῦ, καὶ τοὺς ἄρτους τῆς Προθέσεως λαβὼν, ἔφαγεν καὶ ἔδωκεν τοῖς μετʼ αὐτοῦ, οὓς οὐκ ἔξεστιν φαγεῖν, εἰ μὴ μόνους τοὺς ἱερεῖς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 5, 'Καὶ ἔλεγεν αὐτοῖς, “ ̊Κύριός ἐστιν τοῦ Σαββάτου ὁ Υἱὸς τοῦ Ἀνθρώπου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 6, '¶Ἐγένετο δὲ ἐν ἑτέρῳ Σαββάτῳ, εἰσελθεῖν αὐτὸν εἰς τὴν συναγωγὴν καὶ διδάσκειν· καὶ ἦν ἄνθρωπος ἐκεῖ, καὶ ἡ χεὶρ αὐτοῦ ἡ δεξιὰ ἦν ξηρά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 7, 'Παρετηροῦντο δὲ αὐτὸν οἱ γραμματεῖς καὶ οἱ Φαρισαῖοι, εἰ ἐν τῷ Σαββάτῳ θεραπεύσει, ἵνα εὕρωσιν κατηγορεῖν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 8, 'Αὐτὸς δὲ ᾔδει τοὺς διαλογισμοὺς αὐτῶν, εἶπεν δὲ τῷ ἀνδρὶ τῷ ξηρὰν ἔχοντι τὴν χεῖρα, “Ἔγειρε, καὶ στῆθι εἰς τὸ μέσον.” Καὶ ἀναστὰς, ἔστη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 9, 'Εἶπεν δὲ ὁ  ̊Ἰησοῦς πρὸς αὐτούς, “Ἐπερωτῶ ὑμᾶς, εἰ ἔξεστιν τῷ Σαββάτῳ ἀγαθοποιῆσαι ἢ κακοποιῆσαι, ψυχὴν σῶσαι ἢ ἀπολέσαι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 10, 'Καὶ περιβλεψάμενος πάντας αὐτοὺς, εἶπεν αὐτῷ, “Ἔκτεινον τὴν χεῖρά σου.” Ὁ δὲ ἐποίησεν, καὶ ἀποκατεστάθη ἡ χεὶρ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 11, 'Αὐτοὶ δὲ ἐπλήσθησαν ἀνοίας, καὶ διελάλουν πρὸς ἀλλήλους τί ἂν ποιήσαιεν τῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 12, '¶Ἐγένετο δὲ ἐν ταῖς ἡμέραις ταύταις, ἐξελθεῖν αὐτὸν εἰς τὸ ὄρος προσεύξασθαι, καὶ ἦν διανυκτερεύων ἐν τῇ προσευχῇ τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 13, 'Καὶ ὅτε ἐγένετο ἡμέρα, προσεφώνησεν τοὺς μαθητὰς αὐτοῦ, καὶ ἐκλεξάμενος ἀπʼ αὐτῶν δώδεκα, οὓς καὶ ἀποστόλους ὠνόμασεν:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 14, 'Σίμωνα ὃν καὶ ὠνόμασεν Πέτρον, καὶ Ἀνδρέαν τὸν ἀδελφὸν αὐτοῦ, καὶ Ἰάκωβον, καὶ Ἰωάννην, καὶ Φίλιππον, καὶ Βαρθολομαῖον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 15, 'καὶ Μαθθαῖον, καὶ Θωμᾶν, Ἰάκωβον Ἁλφαίου, καὶ Σίμωνα τὸν καλούμενον Ζηλωτὴν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 16, 'καὶ Ἰούδαν Ἰακώβου, καὶ Ἰούδαν Ἰσκαριὼθ, ὃς ἐγένετο προδότης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 17, '¶Καὶ καταβὰς μετʼ αὐτῶν, ἔστη ἐπὶ τόπου πεδινοῦ, καὶ ὄχλος πολὺς μαθητῶν αὐτοῦ, καὶ πλῆθος πολὺ τοῦ λαοῦ ἀπὸ πάσης τῆς Ἰουδαίας, καὶ Ἰερουσαλὴμ, καὶ τῆς παραλίου Τύρου καὶ Σιδῶνος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 18, 'οἳ ἦλθον ἀκοῦσαι αὐτοῦ καὶ ἰαθῆναι ἀπὸ τῶν νόσων αὐτῶν. Καὶ οἱ ἐνοχλούμενοι ἀπὸ πνευμάτων ἀκαθάρτων ἐθεραπεύοντο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 19, 'Καὶ πᾶς ὁ ὄχλος ἐζήτουν ἅπτεσθαι αὐτοῦ, ὅτι δύναμις παρʼ αὐτοῦ ἐξήρχετο καὶ ἰᾶτο πάντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 20, '¶Καὶ αὐτὸς ἐπάρας τοὺς ὀφθαλμοὺς αὐτοῦ εἰς τοὺς μαθητὰς αὐτοῦ ἔλεγεν, “Μακάριοι οἱ πτωχοί, ὅτι ὑμετέρα ἐστὶν ἡ Βασιλεία τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 21, 'Μακάριοι οἱ πεινῶντες νῦν, ὅτι χορτασθήσεσθε. Μακάριοι οἱ κλαίοντες νῦν, ὅτι γελάσετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 22, '¶Μακάριοί ἐστε ὅταν μισήσωσιν ὑμᾶς οἱ ἄνθρωποι, καὶ ὅταν ἀφορίσωσιν ὑμᾶς, καὶ ὀνειδίσωσιν, καὶ ἐκβάλωσιν τὸ ὄνομα ὑμῶν ὡς πονηρὸν, ἕνεκα τοῦ Υἱοῦ τοῦ Ἀνθρώπου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 23, 'Χάρητε ἐν ἐκείνῃ τῇ ἡμέρᾳ, καὶ σκιρτήσατε, ἰδοὺ γὰρ, ὁ μισθὸς ὑμῶν πολὺς ἐν τῷ οὐρανῷ. Κατὰ τὰ αὐτὰ γὰρ ἐποίουν τοῖς προφήταις οἱ πατέρες αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 24, 'Πλὴν οὐαὶ ὑμῖν τοῖς πλουσίοις, ὅτι ἀπέχετε τὴν παράκλησιν ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 25, 'Οὐαὶ ὑμῖν, οἱ ἐμπεπλησμένοι νῦν, ὅτι πεινάσετε. Οὐαί, οἱ γελῶντες νῦν, ὅτι πενθήσετε καὶ κλαύσετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 26, '¶Οὐαὶ ὅταν ὑμᾶς καλῶς εἴπωσιν πάντες οἱ ἄνθρωποι, κατὰ τὰ αὐτὰ γὰρ ἐποίουν τοῖς ψευδοπροφήταις οἱ πατέρες αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 27, '¶Ἀλλὰ ὑμῖν λέγω τοῖς ἀκούουσιν, ἀγαπᾶτε τοὺς ἐχθροὺς ὑμῶν, καλῶς ποιεῖτε τοῖς μισοῦσιν ὑμᾶς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 28, 'εὐλογεῖτε τοὺς καταρωμένους ὑμᾶς, προσεύχεσθε περὶ τῶν ἐπηρεαζόντων ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 29, 'Τῷ τύπτοντί σε ἐπὶ τὴν σιαγόνα, πάρεχε καὶ τὴν ἄλλην, καὶ ἀπὸ τοῦ αἴροντός σου τὸ ἱμάτιον, καὶ τὸν χιτῶνα μὴ κωλύσῃς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 30, 'Παντὶ αἰτοῦντί σε δίδου, καὶ ἀπὸ τοῦ αἴροντος τὰ σὰ, μὴ ἀπαίτει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 31, 'Καὶ καθὼς θέλετε ἵνα ποιῶσιν ὑμῖν οἱ ἄνθρωποι, ποιεῖτε αὐτοῖς ὁμοίως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 32, '¶Καὶ εἰ ἀγαπᾶτε τοὺς ἀγαπῶντας ὑμᾶς, ποία ὑμῖν χάρις ἐστίν; Καὶ γὰρ οἱ ἁμαρτωλοὶ τοὺς ἀγαπῶντας αὐτοὺς ἀγαπῶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 33, 'Καὶ γὰρ ἐὰν ἀγαθοποιῆτε τοὺς ἀγαθοποιοῦντας ὑμᾶς, ποία ὑμῖν χάρις ἐστίν; Καὶ οἱ ἁμαρτωλοὶ τὸ αὐτὸ ποιοῦσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 34, 'Καὶ ἐὰν δανίσητε παρʼ ὧν ἐλπίζετε λαβεῖν, ποία ὑμῖν χάρις ἐστίν; Καὶ ἁμαρτωλοὶ ἁμαρτωλοῖς δανίζουσιν, ἵνα ἀπολάβωσιν τὰ ἴσα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 35, 'Πλὴν ἀγαπᾶτε τοὺς ἐχθροὺς ὑμῶν, καὶ ἀγαθοποιεῖτε, καὶ δανίζετε μηδὲν ἀπελπίζοντες· καὶ ἔσται ὁ μισθὸς ὑμῶν πολύς, καὶ ἔσεσθε υἱοὶ Ὑψίστου, ὅτι αὐτὸς χρηστός ἐστιν ἐπὶ τοὺς ἀχαρίστους καὶ πονηρούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 36, 'Γίνεσθε οἰκτίρμονες, καθὼς ὁ Πατὴρ ὑμῶν οἰκτίρμων ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 37, '¶Καὶ μὴ κρίνετε, καὶ οὐ μὴ κριθῆτε. Καὶ μὴ καταδικάζετε, καὶ οὐ μὴ καταδικασθῆτε. Ἀπολύετε, καὶ ἀπολυθήσεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 38, 'Δίδοτε, καὶ δοθήσεται ὑμῖν· μέτρον καλὸν, πεπιεσμένον σεσαλευμένον ὑπερεκχυννόμενον, δώσουσιν εἰς τὸν κόλπον ὑμῶν, ᾧ γὰρ μέτρῳ μετρεῖτε, ἀντιμετρηθήσεται ὑμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 39, '¶Εἶπεν δὲ καὶ παραβολὴν αὐτοῖς: “Μήτι δύναται τυφλὸς τυφλὸν ὁδηγεῖν; Οὐχὶ ἀμφότεροι εἰς βόθυνον πεσοῦνται;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 40, 'Οὐκ ἔστιν μαθητὴς ὑπὲρ τὸν διδάσκαλον, κατηρτισμένος δὲ πᾶς ἔσται ὡς ὁ διδάσκαλος αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 41, 'Τί δὲ βλέπεις τὸ κάρφος τὸ ἐν τῷ ὀφθαλμῷ τοῦ ἀδελφοῦ σου, τὴν δὲ δοκὸν τὴν ἐν τῷ ἰδίῳ ὀφθαλμῷ οὐ κατανοεῖς;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 42, 'Πῶς δύνασαι λέγειν τῷ ἀδελφῷ σου, ‘Ἀδελφέ, ἄφες ἐκβάλω τὸ κάρφος τὸ ἐν τῷ ὀφθαλμῷ σου’, αὐτὸς τὴν ἐν τῷ ὀφθαλμῷ σοῦ δοκὸν οὐ βλέπων; Ὑποκριτά, ἔκβαλε πρῶτον τὴν δοκὸν ἐκ τοῦ ὀφθαλμοῦ σοῦ, καὶ τότε διαβλέψεις τὸ κάρφος τὸ ἐν τῷ ὀφθαλμῷ τοῦ ἀδελφοῦ σου ἐκβαλεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 43, '¶Οὐ γάρ ἐστιν δένδρον καλὸν ποιοῦν καρπὸν σαπρόν, οὐδὲ πάλιν δένδρον σαπρὸν ποιοῦν καρπὸν καλόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 44, 'Ἕκαστον γὰρ δένδρον ἐκ τοῦ ἰδίου καρποῦ γινώσκεται. Οὐ γὰρ ἐξ ἀκανθῶν συλλέγουσιν σῦκα, οὐδὲ ἐκ βάτου σταφυλὴν τρυγῶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 45, 'Ὁ ἀγαθὸς ἄνθρωπος ἐκ τοῦ ἀγαθοῦ θησαυροῦ τῆς καρδίας αὑτοῦ προφέρει τὸ ἀγαθόν, καὶ ὁ πονηρὸς ἐκ τοῦ πονηροῦ προφέρει τὸ πονηρόν. Ἐκ γὰρ περισσεύματος καρδίας λαλεῖ τὸ στόμα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 46, '¶Τί δέ με καλεῖτε “ ̊Κύριε,  ̊Κύριε”, καὶ οὐ ποιεῖτε ἃ λέγω;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 47, 'Πᾶς ὁ ἐρχόμενος πρός με, καὶ ἀκούων μου τῶν λόγων καὶ ποιῶν αὐτούς, ὑποδείξω ὑμῖν τίνι ἐστὶν ὅμοιος:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 48, 'ὅμοιός ἐστιν ἀνθρώπῳ οἰκοδομοῦντι οἰκίαν, ὃς ἔσκαψεν καὶ ἐβάθυνεν καὶ ἔθηκεν θεμέλιον ἐπὶ τὴν πέτραν· πλημμύρης δὲ γενομένης προσέρηξεν ὁ ποταμὸς τῇ οἰκίᾳ ἐκείνῃ, καὶ οὐκ ἴσχυσεν σαλεῦσαι αὐτὴν, διὰ τὸ καλῶς οἰκοδομῆσθαι αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 49, 'Ὁ δὲ ἀκούσας καὶ μὴ ποιήσας, ὅμοιός ἐστιν ἀνθρώπῳ οἰκοδομήσαντι οἰκίαν ἐπὶ τὴν γῆν χωρὶς θεμελίου, ᾗ προσέρρηξεν ὁ ποταμός καὶ εὐθὺς συνέπεσεν, καὶ ἐγένετο τὸ ῥῆγμα τῆς οἰκίας ἐκείνης μέγα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 1, '¶Ἐπειδὴ ἐπλήρωσεν πάντα τὰ ῥήματα αὐτοῦ εἰς τὰς ἀκοὰς τοῦ λαοῦ, εἰσῆλθεν εἰς Καφαρναούμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 2, 'Ἑκατοντάρχου δέ τινος δοῦλος κακῶς ἔχων, ἤμελλεν τελευτᾶν, ὃς ἦν αὐτῷ ἔντιμος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 3, 'Ἀκούσας δὲ περὶ τοῦ  ̊Ἰησοῦ, ἀπέστειλεν πρὸς αὐτὸν πρεσβυτέρους τῶν Ἰουδαίων, ἐρωτῶν αὐτὸν ὅπως ἐλθὼν διασώσῃ τὸν δοῦλον αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 4, 'Οἱ δὲ παραγενόμενοι πρὸς τὸν  ̊Ἰησοῦν, παρεκάλουν αὐτὸν σπουδαίως λέγοντες ὅτι “Ἄξιός ἐστιν ᾧ παρέξῃ τοῦτο,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 5, 'ἀγαπᾷ γὰρ τὸ ἔθνος ἡμῶν, καὶ τὴν συναγωγὴν αὐτὸς ᾠκοδόμησεν ἡμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 6, 'Ὁ δὲ  ̊Ἰησοῦς ἐπορεύετο σὺν αὐτοῖς. Ἤδη δὲ αὐτοῦ οὐ μακρὰν ἀπέχοντος ἀπὸ τῆς οἰκίας, ἔπεμψεν ὁ ἑκατόνταρχος φίλους λέγων αὐτῷ, “ ̊Κύριε, μὴ σκύλλου, οὐ γὰρ ἱκανός εἰμι ἵνα ὑπὸ τὴν στέγην μου εἰσέλθῃς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 7, 'διὸ οὐδὲ ἐμαυτὸν ἠξίωσα πρὸς σὲ ἐλθεῖν· ἀλλὰ εἰπὲ λόγῳ, καὶ ἰαθήτω ὁ παῖς μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 8, 'Καὶ γὰρ ἐγὼ ἄνθρωπός εἰμι ὑπὸ ἐξουσίαν τασσόμενος, ἔχων ὑπʼ ἐμαυτὸν στρατιώτας, καὶ λέγω τούτῳ, ‘Πορεύθητι’, καὶ πορεύεται, καὶ ἄλλῳ, ‘Ἔρχου’, καὶ ἔρχεται, καὶ τῷ δούλῳ μου, ‘Ποίησον τοῦτο’, καὶ ποιεῖ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 9, 'Ἀκούσας δὲ ταῦτα ὁ  ̊Ἰησοῦς, ἐθαύμασεν αὐτόν, καὶ στραφεὶς τῷ ἀκολουθοῦντι αὐτῷ ὄχλῳ εἶπεν, “Λέγω ὑμῖν, οὐδὲ ἐν τῷ Ἰσραὴλ τοσαύτην πίστιν εὗρον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 10, 'Καὶ ὑποστρέψαντες εἰς τὸν οἶκον οἱ πεμφθέντες, εὗρον τὸν δοῦλον ὑγιαίνοντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 11, '¶Καὶ ἐγένετο ἐν τῷ ἑξῆς, ἐπορεύθη εἰς πόλιν καλουμένην Ναΐν, καὶ συνεπορεύοντο αὐτῷ οἱ μαθηταὶ αὐτοῦ καὶ ὄχλος πολύς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 12, 'Ὡς δὲ ἤγγισεν τῇ πύλῃ τῆς πόλεως, καὶ ἰδοὺ ἐξεκομίζετο τεθνηκὼς μονογενὴς υἱὸς τῇ μητρὶ αὐτοῦ, καὶ αὐτὴ ἦν χήρα, καὶ ὄχλος τῆς πόλεως ἱκανὸς ἦν σὺν αὐτῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 13, 'Καὶ ἰδὼν αὐτὴν, ὁ  ̊Κύριος ἐσπλαγχνίσθη ἐπʼ αὐτῇ, καὶ εἶπεν αὐτῇ, “Μὴ κλαῖε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 14, 'Καὶ προσελθὼν, ἥψατο τῆς σοροῦ, οἱ δὲ βαστάζοντες ἔστησαν, καὶ εἶπεν, “Νεανίσκε, σοὶ λέγω, ‘Ἐγέρθητι!’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 15, 'Καὶ ἀνεκάθισεν ὁ νεκρὸς καὶ ἤρξατο λαλεῖν, καὶ ἔδωκεν αὐτὸν τῇ μητρὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 16, 'Ἔλαβεν δὲ φόβος πάντας, καὶ ἐδόξαζον τὸν  ̊Θεὸν λέγοντες, ὅτι “Προφήτης μέγας ἠγέρθη ἐν ἡμῖν!” Καὶ, ὅτι “Ἐπεσκέψατο ὁ  ̊Θεὸς τὸν λαὸν αὐτοῦ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 17, 'Καὶ ἐξῆλθεν ὁ λόγος οὗτος ἐν ὅλῃ τῇ Ἰουδαίᾳ περὶ αὐτοῦ, καὶ πάσῃ τῇ περιχώρῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 18, '¶Καὶ ἀπήγγειλαν Ἰωάννῃ οἱ μαθηταὶ αὐτοῦ περὶ πάντων τούτων. Καὶ προσκαλεσάμενος δύο τινὰς τῶν μαθητῶν αὐτοῦ, ὁ Ἰωάννης');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 19, 'ἔπεμψεν πρὸς τὸν  ̊Ἰησοῦν λέγων, “Σὺ εἶ ὁ ἐρχόμενος ἢ ἕτερον προσδοκῶμεν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 20, 'Παραγενόμενοι δὲ πρὸς αὐτὸν, οἱ ἄνδρες εἶπαν, “Ἰωάννης ὁ Βαπτιστὴς ἀπέστειλεν ἡμᾶς πρὸς σὲ λέγων, ‘Σὺ εἶ ὁ ἐρχόμενος ἢ ἄλλον προσδοκῶμεν;’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 21, 'Ἐν ἐκείνῃ τῇ ὥρᾳ, ἐθεράπευσεν πολλοὺς ἀπὸ νόσων, καὶ μαστίγων, καὶ πνευμάτων πονηρῶν καὶ τυφλοῖς πολλοῖς ἐχαρίσατο βλέπειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 22, 'Καὶ ἀποκριθεὶς εἶπεν αὐτοῖς, “Πορευθέντες, ἀπαγγείλατε Ἰωάννῃ ἃ εἴδετε καὶ ἠκούσατε: ‘τυφλοὶ ἀναβλέπουσιν’, χωλοὶ περιπατοῦσιν, λεπροὶ καθαρίζονται, καὶ κωφοὶ ἀκούουσιν, νεκροὶ ἐγείρονται, ‘πτωχοὶ εὐαγγελίζονται’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 23, 'Καὶ μακάριός ἐστιν ὃς ἐὰν μὴ σκανδαλισθῇ ἐν ἐμοί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 24, '¶Ἀπελθόντων δὲ τῶν ἀγγέλων Ἰωάννου, ἤρξατο λέγειν πρὸς τοὺς ὄχλους περὶ Ἰωάννου, “Τί ἐξήλθατε εἰς τὴν ἔρημον θεάσασθαι; Κάλαμον ὑπὸ ἀνέμου σαλευόμενον;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 25, 'Ἀλλὰ τί ἐξήλθατε ἰδεῖν; Ἄνθρωπον ἐν μαλακοῖς ἱματίοις ἠμφιεσμένον; Ἰδοὺ, οἱ ἐν ἱματισμῷ ἐνδόξῳ καὶ τρυφῇ ὑπάρχοντες ἐν τοῖς βασιλείοις εἰσίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 26, 'Ἀλλὰ τί ἐξήλθατε ἰδεῖν; Προφήτην; Ναί, λέγω ὑμῖν, καὶ περισσότερον προφήτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 27, 'Οὗτός ἐστιν περὶ οὗ γέγραπται, ‘Ἰδοὺ, ἀποστέλλω τὸν ἄγγελόν μου πρὸ προσώπου σου, ὃς κατασκευάσει τὴν ὁδόν σου ἔμπροσθέν σου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 28, 'Λέγω ὑμῖν, μείζων ἐν γεννητοῖς γυναικῶν Ἰωάννου οὐδείς ἐστιν· ὁ δὲ μικρότερος ἐν τῇ Βασιλείᾳ τοῦ  ̊Θεοῦ μείζων αὐτοῦ ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 29, '(Καὶ πᾶς ὁ λαὸς ἀκούσας καὶ οἱ τελῶναι, ἐδικαίωσαν τὸν  ̊Θεόν, βαπτισθέντες τὸ βάπτισμα Ἰωάννου·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 30, 'οἱ δὲ Φαρισαῖοι καὶ οἱ νομικοὶ, τὴν βουλὴν τοῦ  ̊Θεοῦ ἠθέτησαν εἰς ἑαυτούς, μὴ βαπτισθέντες ὑπʼ αὐτοῦ.)');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 31, '“Τίνι οὖν ὁμοιώσω τοὺς ἀνθρώπους τῆς γενεᾶς ταύτης, καὶ τίνι εἰσὶν ὅμοιοι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 32, 'Ὅμοιοί εἰσιν παιδίοις τοῖς ἐν ἀγορᾷ καθημένοις, καὶ προσφωνοῦσιν ἀλλήλοις, ἃ λέγει, ‘Ηὐλήσαμεν ὑμῖν καὶ οὐκ ὠρχήσασθε· ἐθρηνήσαμεν καὶ οὐκ ἐκλαύσατε.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 33, 'Ἐλήλυθεν γὰρ Ἰωάννης ὁ Βαπτιστὴς, μὴ ἐσθίων ἄρτον μήτε πίνων οἶνον, καὶ λέγετε, ‘Δαιμόνιον ἔχει.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 34, 'Ἐλήλυθεν ὁ Υἱὸς τοῦ Ἀνθρώπου, ἐσθίων καὶ πίνων, καὶ λέγετε, ‘Ἰδοὺ, ἄνθρωπος φάγος καὶ οἰνοπότης, φίλος τελωνῶν καὶ ἁμαρτωλῶν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 35, 'Καὶ ἐδικαιώθη ἡ σοφία ἀπὸ πάντων τῶν τέκνων αὐτῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 36, '¶Ἠρώτα δέ τις αὐτὸν τῶν Φαρισαίων ἵνα φάγῃ μετʼ αὐτοῦ· καὶ εἰσελθὼν εἰς τὸν οἶκον τοῦ Φαρισαίου, κατεκλίθη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 37, 'Καὶ ἰδοὺ γυνὴ ἥτις ἦν ἐν τῇ πόλει ἁμαρτωλός, καὶ ἐπιγνοῦσα ὅτι κατάκειται ἐν τῇ οἰκίᾳ τοῦ Φαρισαίου, κομίσασα ἀλάβαστρον μύρου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 38, 'καὶ στᾶσα ὀπίσω παρὰ τοὺς πόδας αὐτοῦ κλαίουσα, τοῖς δάκρυσιν ἤρξατο βρέχειν τοὺς πόδας αὐτοῦ, καὶ ταῖς θριξὶν τῆς κεφαλῆς αὐτῆς ἐξέμασσεν, καὶ κατεφίλει τοὺς πόδας αὐτοῦ, καὶ ἤλειφεν τῷ μύρῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 39, 'Ἰδὼν δὲ ὁ Φαρισαῖος, ὁ καλέσας αὐτὸν, εἶπεν ἐν ἑαυτῷ λέγων, “Οὗτος εἰ ἦν προφήτης, ἐγίνωσκεν ἂν τίς καὶ ποταπὴ ἡ γυνὴ, ἥτις ἅπτεται αὐτοῦ, ὅτι ἁμαρτωλός ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 40, 'Καὶ ἀποκριθεὶς ὁ  ̊Ἰησοῦς εἶπεν πρὸς αὐτόν, “Σίμων, ἔχω σοί τι εἰπεῖν.” Ὁ δέ, “Διδάσκαλε, εἰπέ”, φησίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 41, '“Δύο χρεοφειλέται ἦσαν δανιστῇ τινι: ὁ εἷς ὤφειλεν δηνάρια πεντακόσια, ὁ δὲ ἕτερος πεντήκοντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 42, 'Μὴ ἐχόντων δὲ αὐτῶν ἀποδοῦναι, ἀμφοτέροις ἐχαρίσατο. Τίς οὖν αὐτῶν, πλεῖον ἀγαπήσει αὐτόν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 43, 'Ἀποκριθεὶς δὲ Σίμων εἶπεν, “Ὑπολαμβάνω ὅτι ᾧ τὸ πλεῖον ἐχαρίσατο.” Ὁ δὲ εἶπεν αὐτῷ, “Ὀρθῶς ἔκρινας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 44, 'Καὶ στραφεὶς πρὸς τὴν γυναῖκα, τῷ Σίμωνι ἔφη, “Βλέπεις ταύτην τὴν γυναῖκα; Εἰσῆλθόν σου εἰς τὴν οἰκίαν, ὕδωρ μοι ἐπὶ πόδας οὐκ ἔδωκας· αὕτη δὲ τοῖς δάκρυσιν ἔβρεξέν μου τοὺς πόδας, καὶ ταῖς θριξὶν αὐτῆς ἐξέμαξεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 45, 'Φίλημά μοι οὐκ ἔδωκας· αὕτη δὲ ἀφʼ ἧς εἰσῆλθον, οὐ διέλιπεν καταφιλοῦσά μου τοὺς πόδας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 46, 'Ἐλαίῳ τὴν κεφαλήν μου οὐκ ἤλειψας· αὕτη δὲ μύρῳ ἤλειψεν τοὺς πόδας μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 47, 'Οὗ χάριν, λέγω σοι, ἀφέωνται αἱ ἁμαρτίαι αὐτῆς αἱ πολλαί, ὅτι ἠγάπησεν πολύ· ᾧ δὲ ὀλίγον ἀφίεται, ὀλίγον ἀγαπᾷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 48, 'Εἶπεν δὲ αὐτῇ, “Ἀφέωνταί σου αἱ ἁμαρτίαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 49, 'Καὶ ἤρξαντο οἱ συνανακείμενοι λέγειν ἐν ἑαυτοῖς, “Τίς οὗτός ἐστιν ὃς καὶ ἁμαρτίας ἀφίησιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 50, 'Εἶπεν δὲ πρὸς τὴν γυναῖκα, “Ἡ πίστις σου σέσωκέν σε· πορεύου εἰς εἰρήνην.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 1, '¶Καὶ ἐγένετο ἐν τῷ καθεξῆς, καὶ αὐτὸς διώδευεν κατὰ πόλιν καὶ κώμην, κηρύσσων καὶ εὐαγγελιζόμενος τὴν Βασιλείαν τοῦ  ̊Θεοῦ, καὶ οἱ δώδεκα σὺν αὐτῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 2, 'καὶ γυναῖκές τινες αἳ ἦσαν τεθεραπευμέναι ἀπὸ πνευμάτων πονηρῶν καὶ ἀσθενειῶν: Μαρία ἡ καλουμένη Μαγδαληνή, ἀφʼ ἧς δαιμόνια ἑπτὰ ἐξεληλύθει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 3, 'καὶ Ἰωάννα γυνὴ Χουζᾶ ἐπιτρόπου Ἡρῴδου, καὶ Σουσάννα, καὶ ἕτεραι πολλαί, αἵτινες διηκόνουν αὐτοῖς ἐκ τῶν ὑπαρχόντων αὐταῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 4, '¶Συνιόντος δὲ ὄχλου πολλοῦ καὶ τῶν κατὰ πόλιν ἐπιπορευομένων πρὸς αὐτὸν, εἶπεν διὰ παραβολῆς:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 5, '“Ἐξῆλθεν ὁ σπείρων τοῦ σπεῖραι τὸν σπόρον αὐτοῦ. Καὶ ἐν τῷ σπείρειν αὐτὸν, ὃ μὲν ἔπεσεν παρὰ τὴν ὁδόν, καὶ κατεπατήθη καὶ τὰ πετεινὰ τοῦ οὐρανοῦ κατέφαγεν αὐτό.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 6, 'Καὶ ἕτερον κατέπεσεν ἐπὶ τὴν πέτραν, καὶ φυὲν ἐξηράνθη διὰ τὸ μὴ ἔχειν ἰκμάδα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 7, 'Καὶ ἕτερον ἔπεσεν ἐν μέσῳ τῶν ἀκανθῶν, καὶ συμφυεῖσαι αἱ ἄκανθαι ἀπέπνιξαν αὐτό.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 8, 'Καὶ ἕτερον ἔπεσεν εἰς τὴν γῆν τὴν ἀγαθήν, καὶ φυὲν ἐποίησεν καρπὸν ἑκατονταπλασίονα.” Ταῦτα λέγων, ἐφώνει, “Ὁ ἔχων ὦτα ἀκούειν, ἀκουέτω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 9, '¶Ἐπηρώτων δὲ αὐτὸν οἱ μαθηταὶ αὐτοῦ, “Τίς αὕτη εἴη ἡ παραβολή;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 10, 'Ὁ δὲ εἶπεν, “Ὑμῖν δέδοται γνῶναι τὰ μυστήρια τῆς Βασιλείας τοῦ  ̊Θεοῦ, τοῖς δὲ λοιποῖς ἐν παραβολαῖς, ἵνα ‘βλέποντες μὴ βλέπωσιν, καὶ ἀκούοντες μὴ συνιῶσιν’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 11, '¶Ἔστιν δὲ αὕτη ἡ παραβολή: ὁ σπόρος ἐστὶν ὁ λόγος τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 12, 'Οἱ δὲ παρὰ τὴν ὁδόν εἰσιν οἱ ἀκούσαντες, εἶτα ἔρχεται ὁ διάβολος καὶ αἴρει τὸν λόγον ἀπὸ τῆς καρδίας αὐτῶν, ἵνα μὴ πιστεύσαντες σωθῶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 13, 'Οἱ δὲ ἐπὶ τῆς πέτρας, οἳ ὅταν ἀκούσωσιν μετὰ χαρᾶς δέχονται τὸν λόγον, καὶ οὗτοι ῥίζαν οὐκ ἔχουσιν, οἳ πρὸς καιρὸν πιστεύουσιν, καὶ ἐν καιρῷ πειρασμοῦ ἀφίστανται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 14, 'Τὸ δὲ εἰς τὰς ἀκάνθας πεσόν, οὗτοί εἰσιν οἱ ἀκούσαντες, καὶ ὑπὸ μεριμνῶν, καὶ πλούτου, καὶ ἡδονῶν τοῦ βίου, πορευόμενοι συμπνίγονται καὶ οὐ τελεσφοροῦσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 15, 'Τὸ δὲ ἐν τῇ καλῇ γῇ, οὗτοί εἰσιν οἵτινες ἐν καρδίᾳ καλῇ καὶ ἀγαθῇ, ἀκούσαντες τὸν λόγον κατέχουσιν, καὶ καρποφοροῦσιν ἐν ὑπομονῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 16, '¶Οὐδεὶς δὲ λύχνον ἅψας, καλύπτει αὐτὸν σκεύει ἢ ὑποκάτω κλίνης τίθησιν, ἀλλʼ ἐπὶ λυχνίας τίθησιν, ἵνα οἱ εἰσπορευόμενοι βλέπωσιν τὸ φῶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 17, 'Οὐ γάρ ἐστιν κρυπτὸν ὃ οὐ φανερὸν γενήσεται, οὐδὲ ἀπόκρυφον ὃ οὐ μὴ γνωσθῇ καὶ εἰς φανερὸν ἔλθῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 18, 'Βλέπετε οὖν πῶς ἀκούετε· ὃς ἂν γὰρ ἔχῃ, δοθήσεται αὐτῷ, καὶ ὃς ἂν μὴ ἔχῃ, καὶ ὃ δοκεῖ ἔχειν ἀρθήσεται ἀπʼ αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 19, '¶Παρεγένετο δὲ πρὸς αὐτὸν ἡ μήτηρ καὶ οἱ ἀδελφοὶ αὐτοῦ, καὶ οὐκ ἠδύναντο συντυχεῖν αὐτῷ διὰ τὸν ὄχλον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 20, 'Ἀπηγγέλη δὲ αὐτῷ, “Ἡ μήτηρ σου καὶ οἱ ἀδελφοί σου, ἑστήκασιν ἔξω ἰδεῖν θέλοντές σε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 21, 'Ὁ δὲ ἀποκριθεὶς εἶπεν πρὸς αὐτούς, “Μήτηρ μου καὶ ἀδελφοί μου, οὗτοί εἰσιν οἱ τὸν λόγον τοῦ  ̊Θεοῦ ἀκούοντες καὶ ποιοῦντες.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 22, '¶Ἐγένετο δὲ ἐν μιᾷ τῶν ἡμερῶν, καὶ αὐτὸς ἐνέβη εἰς πλοῖον καὶ οἱ μαθηταὶ αὐτοῦ, καὶ εἶπεν πρὸς αὐτούς, “Διέλθωμεν εἰς τὸ πέραν τῆς λίμνης”. Καὶ ἀνήχθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 23, 'Πλεόντων δὲ αὐτῶν, ἀφύπνωσεν. Καὶ κατέβη λαῖλαψ ἀνέμου εἰς τὴν λίμνην, καὶ συνεπληροῦντο καὶ ἐκινδύνευον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 24, 'Προσελθόντες δὲ, διήγειραν αὐτὸν λέγοντες, “Ἐπιστάτα, Ἐπιστάτα, ἀπολλύμεθα!” Ὁ δὲ διεγερθεὶς, ἐπετίμησεν τῷ ἀνέμῳ, καὶ τῷ κλύδωνι, τοῦ ὕδατος, καὶ ἐπαύσαντο καὶ ἐγένετο γαλήνη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 25, 'Εἶπεν δὲ αὐτοῖς, “Ποῦ ἡ πίστις ὑμῶν;” Φοβηθέντες δὲ, ἐθαύμασαν λέγοντες πρὸς ἀλλήλους, “Τίς ἄρα οὗτός ἐστιν, ὅτι καὶ τοῖς ἀνέμοις ἐπιτάσσει καὶ τῷ ὕδατι;” καὶ ὑπακούουσιν αὐτῷ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 26, '¶Καὶ κατέπλευσαν εἰς τὴν χώραν τῶν Γερασηνῶν, ἥτις ἐστὶν ἀντιπέρα τῆς Γαλιλαίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 27, 'Ἐξελθόντι δὲ αὐτῷ ἐπὶ τὴν γῆν, ὑπήντησεν ἀνήρ τις ἐκ τῆς πόλεως ἔχων δαιμόνια, καὶ χρόνῳ ἱκανῷ οὐκ ἐνεδύσατο ἱμάτιον, καὶ ἐν οἰκίᾳ οὐκ ἔμενεν, ἀλλʼ ἐν τοῖς μνήμασιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 28, 'Ἰδὼν δὲ τὸν  ̊Ἰησοῦν, ἀνακράξας προσέπεσεν αὐτῷ, καὶ φωνῇ μεγάλῃ εἶπεν, “Τί ἐμοὶ καὶ σοί,  ̊Ἰησοῦ, Υἱὲ τοῦ  ̊Θεοῦ τοῦ Ὑψίστου; Δέομαί σου, μή με βασανίσῃς!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 29, 'Παρήγγειλεν γὰρ τῷ πνεύματι τῷ ἀκαθάρτῳ ἐξελθεῖν ἀπὸ τοῦ ἀνθρώπου. Πολλοῖς γὰρ χρόνοις συνηρπάκει αὐτόν, καὶ ἐδεσμεύετο ἁλύσεσιν καὶ πέδαις, φυλασσόμενος, καὶ διαρρήσσων τὰ δεσμὰ, ἠλαύνετο ὑπὸ τοῦ δαιμονίου εἰς τὰς ἐρήμους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 30, 'Ἐπηρώτησεν δὲ αὐτὸν ὁ  ̊Ἰησοῦς, “Τί σοι ὄνομά ἐστιν;” Ὁ δὲ εἶπεν, “Λεγεών”, ὅτι εἰσῆλθεν δαιμόνια πολλὰ εἰς αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 31, 'Καὶ παρεκάλουν αὐτὸν ἵνα μὴ ἐπιτάξῃ αὐτοῖς εἰς τὴν Ἄβυσσον ἀπελθεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 32, '¶Ἦν δὲ ἐκεῖ ἀγέλη χοίρων ἱκανῶν βοσκομένη ἐν τῷ ὄρει, καὶ παρεκάλεσαν αὐτὸν ἵνα ἐπιτρέψῃ αὐτοῖς εἰς ἐκείνους εἰσελθεῖν. Καὶ ἐπέτρεψεν αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 33, 'Ἐξελθόντα δὲ τὰ δαιμόνια ἀπὸ τοῦ ἀνθρώπου, εἰσῆλθον εἰς τοὺς χοίρους, καὶ ὥρμησεν ἡ ἀγέλη κατὰ τοῦ κρημνοῦ εἰς τὴν λίμνην, καὶ ἀπεπνίγη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 34, '¶Ἰδόντες δὲ οἱ βόσκοντες, τὸ γεγονὸς, ἔφυγον καὶ ἀπήγγειλαν εἰς τὴν πόλιν καὶ εἰς τοὺς ἀγρούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 35, 'Ἐξῆλθον δὲ ἰδεῖν τὸ γεγονὸς, καὶ ἦλθαν πρὸς τὸν  ̊Ἰησοῦν, καὶ εὗραν καθήμενον τὸν ἄνθρωπον, ἀφʼ οὗ τὰ δαιμόνια ἐξῆλθεν, ἱματισμένον καὶ σωφρονοῦντα παρὰ τοὺς πόδας τοῦ  ̊Ἰησοῦ, καὶ ἐφοβήθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 36, 'Ἀπήγγειλαν δὲ αὐτοῖς οἱ ἰδόντες, πῶς ἐσώθη ὁ δαιμονισθείς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 37, 'Καὶ ἠρώτησεν αὐτὸν ἅπαν τὸ πλῆθος τῆς περιχώρου τῶν Γερασηνῶν, ἀπελθεῖν ἀπʼ αὐτῶν, ὅτι φόβῳ μεγάλῳ συνείχοντο. Αὐτὸς δὲ ἐμβὰς, εἰς πλοῖον, ὑπέστρεψεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 38, 'Ἐδεῖτο δὲ αὐτοῦ ὁ ἀνὴρ ἀφʼ οὗ ἐξεληλύθει τὰ δαιμόνια, εἶναι σὺν αὐτῷ. Ἀπέλυσεν δὲ αὐτὸν λέγων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 39, '“Ὑπόστρεφε εἰς τὸν οἶκόν σου, καὶ διηγοῦ ὅσα σοι ἐποίησεν ὁ  ̊Θεός.” Καὶ ἀπῆλθεν καθʼ ὅλην τὴν πόλιν, κηρύσσων ὅσα ἐποίησεν αὐτῷ ὁ  ̊Ἰησοῦς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 40, '¶Ἐν δὲ τῷ ὑποστρέφειν τὸν  ̊Ἰησοῦν, ἀπεδέξατο αὐτὸν ὁ ὄχλος, ἦσαν γὰρ πάντες προσδοκῶντες αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 41, 'Καὶ ἰδοὺ, ἦλθεν ἀνὴρ ᾧ ὄνομα Ἰάειρος, καὶ οὗτος ἄρχων τῆς συναγωγῆς ὑπῆρχεν, καὶ πεσὼν παρὰ τοὺς πόδας  ̊Ἰησοῦ, παρεκάλει αὐτὸν εἰσελθεῖν εἰς τὸν οἶκον αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 42, 'ὅτι θυγάτηρ μονογενὴς ἦν αὐτῷ, ὡς ἐτῶν δώδεκα, καὶ αὐτὴ ἀπέθνῃσκεν. ¶Ἐν δὲ τῷ ὑπάγειν αὐτὸν, οἱ ὄχλοι συνέπνιγον αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 43, 'Καὶ γυνὴ οὖσα ἐν ῥύσει αἵματος ἀπὸ ἐτῶν δώδεκα, ἥτις οὐκ ἴσχυσεν ἀπʼ οὐδενὸς θεραπευθῆναι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 44, 'προσελθοῦσα ὄπισθεν, ἥψατο τοῦ κρασπέδου τοῦ ἱματίου αὐτοῦ, καὶ παραχρῆμα ἔστη ἡ ῥύσις τοῦ αἵματος αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 45, 'Καὶ εἶπεν ὁ  ̊Ἰησοῦς, “Τίς ὁ ἁψάμενός μου;” Ἀρνουμένων δὲ πάντων, εἶπεν ὁ Πέτρος, “Ἐπιστάτα, οἱ ὄχλοι συνέχουσίν σε καὶ ἀποθλίβουσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 46, 'Ὁ δὲ  ̊Ἰησοῦς εἶπεν, “Ἥψατό μού τις, ἐγὼ γὰρ ἔγνων δύναμιν ἐξεληλυθυῖαν ἀπʼ ἐμοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 47, 'Ἰδοῦσα δὲ ἡ γυνὴ ὅτι οὐκ ἔλαθεν, τρέμουσα ἦλθεν καὶ προσπεσοῦσα αὐτῷ, διʼ ἣν αἰτίαν ἥψατο αὐτοῦ, ἀπήγγειλεν ἐνώπιον παντὸς τοῦ λαοῦ, καὶ ὡς ἰάθη παραχρῆμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 48, 'Ὁ δὲ εἶπεν αὐτῇ, “Θύγατερ, ἡ πίστις σου σέσωκέν σε· πορεύου εἰς εἰρήνην.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 49, '¶Ἔτι αὐτοῦ λαλοῦντος, ἔρχεταί τις παρὰ τοῦ ἀρχισυναγώγου λέγων, ὅτι “Τέθνηκεν ἡ θυγάτηρ σου, μηκέτι σκύλλε τὸν διδάσκαλον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 50, 'Ὁ δὲ  ̊Ἰησοῦς ἀκούσας, ἀπεκρίθη αὐτῷ, “Μὴ φοβοῦ, μόνον πίστευε, καὶ σωθήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 51, 'Ἐλθὼν δὲ εἰς τὴν οἰκίαν, οὐκ ἀφῆκεν εἰσελθεῖν τινα σὺν αὐτῷ, εἰ μὴ Πέτρον, καὶ Ἰωάννην, καὶ Ἰάκωβον, καὶ τὸν πατέρα τῆς παιδὸς, καὶ τὴν μητέρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 52, 'Ἔκλαιον δὲ πάντες καὶ ἐκόπτοντο αὐτήν. Ὁ δὲ εἶπεν, “Μὴ κλαίετε, οὐ γὰρ ἀπέθανεν, ἀλλὰ καθεύδει.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 53, 'Καὶ κατεγέλων αὐτοῦ, εἰδότες ὅτι ἀπέθανεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 54, 'Αὐτὸς δὲ κρατήσας τῆς χειρὸς αὐτῆς, ἐφώνησεν λέγων, “Ἡ παῖς, ἔγειρε!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 55, 'Καὶ ἐπέστρεψεν τὸ πνεῦμα αὐτῆς, καὶ ἀνέστη παραχρῆμα, καὶ διέταξεν αὐτῇ δοθῆναι φαγεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 56, 'Καὶ ἐξέστησαν οἱ γονεῖς αὐτῆς· ὁ δὲ παρήγγειλεν αὐτοῖς μηδενὶ εἰπεῖν τὸ γεγονός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 1, '¶Συγκαλεσάμενος δὲ τοὺς δώδεκα, ἔδωκεν αὐτοῖς δύναμιν καὶ ἐξουσίαν ἐπὶ πάντα τὰ δαιμόνια, καὶ νόσους θεραπεύειν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 2, 'καὶ ἀπέστειλεν αὐτοὺς κηρύσσειν τὴν Βασιλείαν τοῦ  ̊Θεοῦ, καὶ ἰᾶσθαι τοὺς ἀσθενεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 3, 'Καὶ εἶπεν πρὸς αὐτούς, “Μηδὲν αἴρετε εἰς τὴν ὁδόν, μήτε ῥάβδον, μήτε πήραν, μήτε ἄρτον, μήτε ἀργύριον, μήτε δύο χιτῶνας ἔχειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 4, 'Καὶ εἰς ἣν ἂν οἰκίαν εἰσέλθητε, ἐκεῖ μένετε καὶ ἐκεῖθεν ἐξέρχεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 5, 'Καὶ ὅσοι ἂν μὴ δέχωνται ὑμᾶς, ἐξερχόμενοι ἀπὸ τῆς πόλεως ἐκείνης, τὸν κονιορτὸν ἀπὸ τῶν ποδῶν ὑμῶν ἀποτινάσσετε, εἰς μαρτύριον ἐπʼ αὐτούς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 6, 'Ἐξερχόμενοι δὲ, διήρχοντο κατὰ τὰς κώμας, εὐαγγελιζόμενοι καὶ θεραπεύοντες πανταχοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 7, '¶Ἤκουσεν δὲ Ἡρῴδης ὁ τετράρχης τὰ γινόμενα πάντα, καὶ διηπόρει, διὰ τὸ λέγεσθαι ὑπό τινων ὅτι Ἰωάννης ἠγέρθη ἐκ νεκρῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 8, 'ὑπό τινων δὲ ὅτι Ἠλίας ἐφάνη, ἄλλων δὲ ὅτι προφήτης τις τῶν ἀρχαίων ἀνέστη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 9, 'Εἶπεν δὲ Ἡρῴδης, “Ἰωάννην ἐγὼ ἀπεκεφάλισα, τίς δέ ἐστιν οὗτος περὶ οὗ ἀκούω τοιαῦτα;” Καὶ ἐζήτει ἰδεῖν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 10, '¶Καὶ ὑποστρέψαντες, οἱ ἀπόστολοι διηγήσαντο αὐτῷ ὅσα ἐποίησαν. Καὶ παραλαβὼν αὐτοὺς, ὑπεχώρησεν κατʼ ἰδίαν εἰς πόλιν καλουμένην Βηθσαϊδά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 11, 'Οἱ δὲ ὄχλοι γνόντες, ἠκολούθησαν αὐτῷ. Καὶ ἀποδεξάμενος αὐτοὺς, ἐλάλει αὐτοῖς περὶ τῆς Βασιλείας τοῦ  ̊Θεοῦ, καὶ τοὺς χρείαν ἔχοντας θεραπείας, ἰᾶτο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 12, '¶Ἡ δὲ ἡμέρα ἤρξατο κλίνειν, προσελθόντες δὲ οἱ δώδεκα εἶπον αὐτῷ, “Ἀπόλυσον τὸν ὄχλον, ἵνα πορευθέντες εἰς τὰς κύκλῳ κώμας καὶ ἀγροὺς, καταλύσωσιν καὶ εὕρωσιν ἐπισιτισμόν, ὅτι ὧδε ἐν ἐρήμῳ τόπῳ ἐσμέν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 13, 'Εἶπεν δὲ πρὸς αὐτούς, “Δότε αὐτοῖς ὑμεῖς φαγεῖν.” Οἱ δὲ εἶπαν, “Οὐκ εἰσὶν ἡμῖν πλεῖον ἢ ἄρτοι πέντε καὶ ἰχθύες δύο, εἰ μήτι πορευθέντες, ἡμεῖς ἀγοράσωμεν εἰς πάντα τὸν λαὸν τοῦτον βρώματα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 14, '(Ἦσαν γὰρ ὡσεὶ ἄνδρες πεντακισχίλιοι.) Εἶπεν δὲ πρὸς τοὺς μαθητὰς αὐτοῦ, “Κατακλίνατε αὐτοὺς κλισίας ὡσεὶ ἀνὰ πεντήκοντα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 15, 'Καὶ ἐποίησαν οὕτως, καὶ κατέκλιναν ἅπαντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 16, 'Λαβὼν δὲ τοὺς πέντε ἄρτους καὶ τοὺς δύο ἰχθύας, ἀναβλέψας εἰς τὸν οὐρανὸν, εὐλόγησεν αὐτοὺς καὶ κατέκλασεν, καὶ ἐδίδου τοῖς μαθηταῖς παραθεῖναι τῷ ὄχλῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 17, 'Καὶ ἔφαγον καὶ ἐχορτάσθησαν πάντες, καὶ ἤρθη τὸ περισσεῦσαν αὐτοῖς κλασμάτων κόφινοι δώδεκα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 18, '¶Καὶ ἐγένετο ἐν τῷ εἶναι αὐτὸν προσευχόμενον κατὰ μόνας, συνῆσαν αὐτῷ οἱ μαθηταί, καὶ ἐπηρώτησεν αὐτοὺς λέγων, “Τίνα με λέγουσιν οἱ ὄχλοι εἶναι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 19, 'Οἱ δὲ ἀποκριθέντες εἶπαν, “Ἰωάννην τὸν Βαπτιστήν, ἄλλοι δὲ, Ἠλίαν, ἄλλοι δὲ ὅτι προφήτης τις τῶν ἀρχαίων ἀνέστη.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 20, 'Εἶπεν δὲ αὐτοῖς, “Ὑμεῖς δὲ τίνα με λέγετε εἶναι;” Πέτρος δὲ ἀποκριθεὶς εἶπεν, “Τὸν  ̊Χριστὸν τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 21, '¶Ὁ δὲ, ἐπιτιμήσας αὐτοῖς, παρήγγειλεν μηδενὶ λέγειν τοῦτο,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 22, 'εἰπὼν, ὅτι “Δεῖ τὸν Υἱὸν τοῦ Ἀνθρώπου πολλὰ παθεῖν, καὶ ἀποδοκιμασθῆναι ἀπὸ τῶν πρεσβυτέρων, καὶ ἀρχιερέων, καὶ γραμματέων, καὶ ἀποκτανθῆναι καὶ τῇ τρίτῃ ἡμέρᾳ ἐγερθῆναι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 23, '¶Ἔλεγεν δὲ πρὸς πάντας, “Εἴ τις θέλει ὀπίσω μου ἔρχεσθαι, ἀπαρνησάσθω ἑαυτὸν, καὶ ἀράτω τὸν σταυρὸν αὐτοῦ καθʼ ἡμέραν, καὶ ἀκολουθείτω μοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 24, 'Ὃς γὰρ ἂν θέλῃ τὴν ψυχὴν αὐτοῦ σῶσαι, ἀπολέσει αὐτήν· ὃς δʼ ἂν ἀπολέσῃ τὴν ψυχὴν αὐτοῦ ἕνεκεν ἐμοῦ, οὗτος σώσει αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 25, 'Τί γὰρ ὠφελεῖται ἄνθρωπος, κερδήσας τὸν κόσμον ὅλον, ἑαυτὸν δὲ ἀπολέσας ἢ ζημιωθείς;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 26, 'Ὃς γὰρ ἂν ἐπαισχυνθῇ με καὶ τοὺς ἐμοὺς λόγους, τοῦτον ὁ Υἱὸς τοῦ Ἀνθρώπου ἐπαισχυνθήσεται, ὅταν ἔλθῃ ἐν τῇ δόξῃ αὐτοῦ, καὶ τοῦ Πατρὸς, καὶ τῶν ἁγίων ἀγγέλων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 27, 'Λέγω δὲ ὑμῖν ἀληθῶς, εἰσίν τινες τῶν αὐτοῦ ἑστηκότων, οἳ οὐ μὴ γεύσωνται θανάτου, ἕως ἂν ἴδωσιν τὴν Βασιλείαν τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 28, '¶Ἐγένετο δὲ μετὰ τοὺς λόγους τούτους ὡσεὶ ἡμέραι ὀκτὼ, παραλαβὼν Πέτρον, καὶ Ἰωάννην, καὶ Ἰάκωβον, ἀνέβη εἰς τὸ ὄρος προσεύξασθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 29, 'Καὶ ἐγένετο ἐν τῷ προσεύχεσθαι αὐτὸν, τὸ εἶδος τοῦ προσώπου αὐτοῦ ἕτερον, καὶ ὁ ἱματισμὸς αὐτοῦ λευκὸς ἐξαστράπτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 30, 'Καὶ ἰδοὺ, ἄνδρες δύο συνελάλουν αὐτῷ, οἵτινες ἦσαν Μωϋσῆς καὶ Ἠλίας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 31, 'οἳ ὀφθέντες ἐν δόξῃ, ἔλεγον τὴν ἔξοδον αὐτοῦ, ἣν ἤμελλεν πληροῦν ἐν Ἰερουσαλήμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 32, 'Ὁ δὲ Πέτρος καὶ οἱ σὺν αὐτῷ ἦσαν βεβαρημένοι ὕπνῳ· διαγρηγορήσαντες δὲ εἶδον τὴν δόξαν αὐτοῦ, καὶ τοὺς δύο ἄνδρας τοὺς συνεστῶτας αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 33, 'Καὶ ἐγένετο ἐν τῷ διαχωρίζεσθαι αὐτοὺς ἀπʼ αὐτοῦ, εἶπεν ὁ Πέτρος πρὸς τὸν  ̊Ἰησοῦν, “Ἐπιστάτα, καλόν ἐστιν ἡμᾶς ὧδε εἶναι, καὶ ποιήσωμεν σκηνὰς τρεῖς: μίαν σοὶ, καὶ μίαν Μωϋσεῖ, καὶ μίαν Ἠλίᾳ”, μὴ εἰδὼς ὃ λέγει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 34, 'Ταῦτα δὲ αὐτοῦ λέγοντος, ἐγένετο νεφέλη καὶ ἐπεσκίαζεν αὐτούς· ἐφοβήθησαν δὲ ἐν τῷ εἰσελθεῖν αὐτοὺς εἰς τὴν νεφέλην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 35, 'Καὶ φωνὴ ἐγένετο ἐκ τῆς νεφέλης λέγουσα, “Οὗτός ἐστιν ὁ Υἱός μου, ὁ ἐκλελεγμένος, αὐτοῦ ἀκούετε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 36, 'Καὶ ἐν τῷ γενέσθαι τὴν φωνὴν, εὑρέθη  ̊Ἰησοῦς μόνος. Καὶ αὐτοὶ ἐσίγησαν, καὶ οὐδενὶ ἀπήγγειλαν ἐν ἐκείναις ταῖς ἡμέραις οὐδὲν ὧν ἑώρακαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 37, '¶Ἐγένετο δὲ τῇ ἑξῆς ἡμέρᾳ, κατελθόντων αὐτῶν ἀπὸ τοῦ ὄρους, συνήντησεν αὐτῷ ὄχλος πολύς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 38, 'Καὶ ἰδοὺ, ἀνὴρ ἀπὸ τοῦ ὄχλου ἐβόησεν λέγων, “Διδάσκαλε, δέομαί σου ἐπιβλέψαι ἐπὶ τὸν υἱόν μου, ὅτι μονογενής μοί ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 39, 'Καὶ ἰδοὺ, πνεῦμα λαμβάνει αὐτόν, καὶ ἐξαίφνης κράζει καὶ σπαράσσει αὐτὸν μετὰ ἀφροῦ, καὶ μόγις ἀποχωρεῖ ἀπʼ αὐτοῦ, συντρῖβον αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 40, 'Καὶ ἐδεήθην τῶν μαθητῶν σου ἵνα ἐκβάλωσιν αὐτό, καὶ οὐκ ἠδυνήθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 41, 'Ἀποκριθεὶς δὲ ὁ  ̊Ἰησοῦς εἶπεν, “Ὦ γενεὰ ἄπιστος καὶ διεστραμμένη, ἕως πότε ἔσομαι πρὸς ὑμᾶς καὶ ἀνέξομαι ὑμῶν; Προσάγαγε ὧδε τὸν υἱόν σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 42, 'Ἔτι δὲ προσερχομένου αὐτοῦ, ἔρρηξεν αὐτὸν τὸ δαιμόνιον καὶ συνεσπάραξεν. Ἐπετίμησεν δὲ ὁ  ̊Ἰησοῦς τῷ πνεύματι τῷ ἀκαθάρτῳ, καὶ ἰάσατο τὸν παῖδα καὶ ἀπέδωκεν αὐτὸν τῷ πατρὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 43, 'Ἐξεπλήσσοντο δὲ πάντες ἐπὶ τῇ μεγαλειότητι τοῦ  ̊Θεοῦ. ¶Πάντων δὲ θαυμαζόντων ἐπὶ πᾶσιν οἷς ἐποίει, εἶπεν πρὸς τοὺς μαθητὰς αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 44, '“Θέσθε ὑμεῖς εἰς τὰ ὦτα ὑμῶν τοὺς λόγους τούτους, ὁ γὰρ Υἱὸς τοῦ Ἀνθρώπου μέλλει παραδίδοσθαι εἰς χεῖρας ἀνθρώπων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 45, 'Οἱ δὲ ἠγνόουν τὸ ῥῆμα τοῦτο, καὶ ἦν παρακεκαλυμμένον ἀπʼ αὐτῶν, ἵνα μὴ αἴσθωνται αὐτό, καὶ ἐφοβοῦντο ἐρωτῆσαι αὐτὸν περὶ τοῦ ῥήματος τούτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 46, '¶Εἰσῆλθεν δὲ διαλογισμὸς ἐν αὐτοῖς, τὸ τίς ἂν εἴη μείζων αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 47, 'Ὁ δὲ  ̊Ἰησοῦς εἰδὼς τὸν διαλογισμὸν τῆς καρδίας αὐτῶν, ἐπιλαβόμενος παιδίον, ἔστησεν αὐτὸ παρʼ ἑαυτῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 48, 'καὶ εἶπεν αὐτοῖς, “Ὃς ἐὰν δέξηται τοῦτο τὸ παιδίον ἐπὶ τῷ ὀνόματί μου, ἐμὲ δέχεται, καὶ ὃς ἂν ἐμὲ δέξηται, δέχεται τὸν ἀποστείλαντά με. Ὁ γὰρ μικρότερος ἐν πᾶσιν ὑμῖν ὑπάρχων, οὗτός ἐστιν μέγας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 49, '¶Ἀποκριθεὶς δὲ Ἰωάννης εἶπεν, “Ἐπιστάτα, εἴδομέν τινα ἐν τῷ ὀνόματί σου ἐκβάλλοντα δαιμόνια, καὶ ἐκωλύομεν αὐτὸν, ὅτι οὐκ ἀκολουθεῖ μεθʼ ἡμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 50, 'Εἶπεν δὲ πρὸς αὐτὸν ὁ  ̊Ἰησοῦς, “Μὴ κωλύετε, ὃς γὰρ οὐκ ἔστιν καθʼ ὑμῶν, ὑπὲρ ὑμῶν ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 51, '¶Ἐγένετο δὲ ἐν τῷ συμπληροῦσθαι τὰς ἡμέρας τῆς ἀναλήμψεως αὐτοῦ, καὶ αὐτὸς τὸ πρόσωπον ἐστήρισεν, τοῦ πορεύεσθαι εἰς Ἰερουσαλήμ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 52, 'καὶ ἀπέστειλεν ἀγγέλους πρὸ προσώπου αὐτοῦ. Καὶ πορευθέντες, εἰσῆλθον εἰς κώμην Σαμαρειτῶν, ὡς ἑτοιμάσαι αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 53, 'Καὶ οὐκ ἐδέξαντο αὐτόν, ὅτι τὸ πρόσωπον αὐτοῦ ἦν πορευόμενον εἰς Ἰερουσαλήμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 54, 'Ἰδόντες δὲ, οἱ μαθηταὶ Ἰάκωβος καὶ Ἰωάννης εἶπαν, “ ̊Κύριε, θέλεις εἴπωμεν πῦρ καταβῆναι ἀπὸ τοῦ οὐρανοῦ καὶ ἀναλῶσαι αὐτούς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 55, 'Στραφεὶς δὲ, ἐπετίμησεν αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 56, 'Καὶ ἐπορεύθησαν εἰς ἑτέραν κώμην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 57, '¶Καὶ πορευομένων αὐτῶν ἐν τῇ ὁδῷ, εἶπέν τις πρὸς αὐτόν, “Ἀκολουθήσω σοι ὅπου ἐὰν ἀπέρχῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 58, 'Καὶ εἶπεν αὐτῷ ὁ  ̊Ἰησοῦς, “Αἱ ἀλώπεκες φωλεοὺς ἔχουσιν, καὶ τὰ πετεινὰ τοῦ οὐρανοῦ κατασκηνώσεις, ὁ δὲ Υἱὸς τοῦ Ἀνθρώπου οὐκ ἔχει ποῦ τὴν κεφαλὴν κλίνῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 59, 'Εἶπεν δὲ πρὸς ἕτερον, “Ἀκολούθει μοι.” Ὁ δὲ εἶπεν, “ ̊Κύριε, ἐπίτρεψόν μοι ἀπελθόντι, πρῶτον θάψαι τὸν πατέρα μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 60, 'Εἶπεν δὲ αὐτῷ, “Ἄφες τοὺς νεκροὺς θάψαι τοὺς ἑαυτῶν νεκρούς, σὺ δὲ ἀπελθὼν, διάγγελλε τὴν Βασιλείαν τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 61, 'Εἶπεν δὲ καὶ ἕτερος, “Ἀκολουθήσω σοι,  ̊Κύριε, πρῶτον δὲ ἐπίτρεψόν μοι ἀποτάξασθαι τοῖς εἰς τὸν οἶκόν μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 62, 'Εἶπεν δὲ ὁ  ̊Ἰησοῦς, “Οὐδεὶς ἐπιβαλὼν τὴν χεῖρα αὐτοῦ ἐπʼ ἄροτρον, καὶ βλέπων εἰς τὰ ὀπίσω, εὔθετός ἐστιν τῇ Βασιλείᾳ τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 1, '¶Μετὰ δὲ ταῦτα, ἀνέδειξεν ὁ  ̊Κύριος ἑτέρους ἑβδομήκοντα δύο, καὶ ἀπέστειλεν αὐτοὺς ἀνὰ δύο πρὸ προσώπου αὐτοῦ, εἰς πᾶσαν πόλιν καὶ τόπον οὗ ἤμελλεν αὐτὸς ἔρχεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 2, 'Ἔλεγεν δὲ πρὸς αὐτούς, “Ὁ μὲν θερισμὸς πολύς, οἱ δὲ ἐργάται ὀλίγοι. Δεήθητε οὖν τοῦ  ̊Κυρίου τοῦ θερισμοῦ, ὅπως ἐργάτας ἐκβάλῃ εἰς τὸν θερισμὸν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 3, 'Ὑπάγετε ἰδοὺ, ἀποστέλλω ὑμᾶς ὡς ἄρνας ἐν μέσῳ λύκων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 4, 'Μὴ βαστάζετε βαλλάντιον, μὴ πήραν, μὴ ὑποδήματα, καὶ μηδένα κατὰ τὴν ὁδὸν ἀσπάσησθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 5, 'Εἰς ἣν δʼ ἂν εἰσέλθητε οἰκίαν, πρῶτον λέγετε, ‘Εἰρήνη τῷ οἴκῳ τούτῳ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 6, 'Καὶ ἐὰν ἐκεῖ ᾖ υἱὸς εἰρήνης, ἐπαναπαήσεται ἐπʼ αὐτὸν ἡ εἰρήνη ὑμῶν· εἰ δὲ μή γε ἐφʼ ὑμᾶς ἀνακάμψει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 7, 'Ἐν αὐτῇ δὲ τῇ οἰκίᾳ μένετε, ἐσθίοντες καὶ πίνοντες τὰ παρʼ αὐτῶν, ἄξιος γὰρ ὁ ἐργάτης τοῦ μισθοῦ αὐτοῦ. Μὴ μεταβαίνετε ἐξ οἰκίας εἰς οἰκίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 8, 'Καὶ εἰς ἣν ἂν πόλιν εἰσέρχησθε, καὶ δέχωνται ὑμᾶς, ἐσθίετε τὰ παρατιθέμενα ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 9, 'Καὶ θεραπεύετε τοὺς ἐν αὐτῇ ἀσθενεῖς, καὶ λέγετε αὐτοῖς, ‘Ἤγγικεν ἐφʼ ὑμᾶς ἡ Βασιλεία τοῦ  ̊Θεοῦ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 10, 'Εἰς ἣν δʼ ἂν πόλιν εἰσέλθητε, καὶ μὴ δέχωνται ὑμᾶς, ἐξελθόντες εἰς τὰς πλατείας αὐτῆς εἴπατε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 11, '‘Καὶ τὸν κονιορτὸν τὸν κολληθέντα ἡμῖν ἐκ τῆς πόλεως ὑμῶν εἰς τοὺς πόδας ἀπομασσόμεθα ὑμῖν· πλὴν τοῦτο γινώσκετε ὅτι ἤγγικεν ἡ Βασιλεία τοῦ  ̊Θεοῦ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 12, 'Λέγω ὑμῖν ὅτι Σοδόμοις ἐν τῇ ἡμέρᾳ ἐκείνῃ ἀνεκτότερον ἔσται, ἢ τῇ πόλει ἐκείνῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 13, '¶Οὐαί σοι, Χοραζίν! Οὐαί σοι, Βηθσαϊδά! Ὅτι εἰ ἐν Τύρῳ καὶ Σιδῶνι ἐγενήθησαν αἱ δυνάμεις, αἱ γενόμεναι ἐν ὑμῖν, πάλαι ἂν ἐν σάκκῳ καὶ σποδῷ καθήμενοι μετενόησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 14, 'Πλὴν Τύρῳ καὶ Σιδῶνι, ἀνεκτότερον ἔσται ἐν τῇ κρίσει ἢ ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 15, 'Καὶ σύ, Καφαρναούμ, μὴ ἕως οὐρανοῦ ὑψωθήσῃ; Ἕως ἍΙδου καταβήσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 16, '¶Ὁ ἀκούων ὑμῶν, ἐμοῦ ἀκούει, καὶ ὁ ἀθετῶν ὑμᾶς, ἐμὲ ἀθετεῖ· ὁ δὲ ἐμὲ ἀθετῶν, ἀθετεῖ τὸν ἀποστείλαντά με.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 17, '¶Ὑπέστρεψαν δὲ οἱ ἑβδομήκοντα δύο μετὰ χαρᾶς λέγοντες, “ ̊Κύριε, καὶ τὰ δαιμόνια ὑποτάσσεται ἡμῖν ἐν τῷ ὀνόματί σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 18, 'Εἶπεν δὲ αὐτοῖς, “Ἐθεώρουν τὸν Σατανᾶν ὡς ἀστραπὴν ἐκ τοῦ οὐρανοῦ πεσόντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 19, 'Ἰδοὺ, δέδωκα ὑμῖν τὴν ἐξουσίαν τοῦ πατεῖν ἐπάνω ὄφεων καὶ σκορπίων, καὶ ἐπὶ πᾶσαν τὴν δύναμιν τοῦ ἐχθροῦ, καὶ οὐδὲν ὑμᾶς οὐ μὴ ἀδικήσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 20, 'Πλὴν ἐν τούτῳ μὴ χαίρετε ὅτι τὰ πνεύματα ὑμῖν ὑποτάσσεται, χαίρετε δὲ ὅτι τὰ ὀνόματα ὑμῶν ἐγγέγραπται ἐν τοῖς οὐρανοῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 21, '¶Ἐν αὐτῇ τῇ ὥρᾳ, ἠγαλλιάσατο τῷ  ̊Πνεύματι τῷ Ἁγίῳ καὶ εἶπεν, “Ἐξομολογοῦμαί σοι, Πάτερ,  ̊Κύριε τοῦ οὐρανοῦ καὶ τῆς γῆς, ὅτι ἀπέκρυψας ταῦτα ἀπὸ σοφῶν καὶ συνετῶν, καὶ ἀπεκάλυψας αὐτὰ νηπίοις. Ναί, ὁ Πατήρ, ὅτι οὕτως εὐδοκία ἐγένετο ἔμπροσθέν σου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 22, 'Πάντα μοι παρεδόθη ὑπὸ τοῦ Πατρός μου, καὶ οὐδεὶς γινώσκει τίς ἐστιν ὁ Υἱὸς, εἰ μὴ ὁ Πατήρ, καὶ τίς ἐστιν ὁ Πατὴρ, εἰ μὴ ὁ Υἱὸς καὶ ᾧ ἐὰν βούληται ὁ Υἱὸς ἀποκαλύψαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 23, '¶Καὶ στραφεὶς πρὸς τοὺς μαθητὰς κατʼ ἰδίαν, εἶπεν, “Μακάριοι οἱ ὀφθαλμοὶ οἱ βλέποντες ἃ βλέπετε!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 24, 'Λέγω γὰρ ὑμῖν ὅτι πολλοὶ προφῆται καὶ βασιλεῖς ἠθέλησαν ἰδεῖν ἃ ὑμεῖς βλέπετε, καὶ οὐκ εἶδαν, καὶ ἀκοῦσαι ἃ ἀκούετε, καὶ οὐκ ἤκουσαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 25, '¶Καὶ ἰδοὺ, νομικός τις ἀνέστη, ἐκπειράζων αὐτὸν λέγων, “Διδάσκαλε, τί ποιήσας, ζωὴν αἰώνιον κληρονομήσω;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 26, 'Ὁ δὲ εἶπεν πρὸς αὐτόν, “Ἐν τῷ νόμῳ τί γέγραπται; Πῶς ἀναγινώσκεις;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 27, 'Ὁ δὲ ἀποκριθεὶς εἶπεν, “‘Ἀγαπήσεις  ̊Κύριον τὸν  ̊Θεόν σου, ἐξ ὅλης καρδίας σου, καὶ ἐν ὅλῃ τῇ ψυχῇ σου, καὶ ἐν ὅλῃ τῇ ἰσχύϊ σου, καὶ ἐν ὅλῃ τῇ διανοίᾳ σου’, καὶ, ‘Τὸν πλησίον σου ὡς σεαυτόν.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 28, 'Εἶπεν δὲ αὐτῷ, “Ὀρθῶς ἀπεκρίθης. Τοῦτο ποίει, καὶ ζήσῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 29, '¶Ὁ δὲ θέλων δικαιῶσαι ἑαυτὸν, εἶπεν πρὸς τὸν  ̊Ἰησοῦν, “Καὶ τίς ἐστίν μου πλησίον;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 30, 'Ὑπολαβὼν ὁ  ̊Ἰησοῦς εἶπεν, “Ἄνθρωπός τις κατέβαινεν ἀπὸ Ἰερουσαλὴμ εἰς Ἰεριχὼ, καὶ λῃσταῖς περιέπεσεν, οἳ καὶ ἐκδύσαντες αὐτὸν, καὶ πληγὰς ἐπιθέντες, ἀπῆλθον ἀφέντες ἡμιθανῆ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 31, 'Κατὰ συγκυρίαν δὲ ἱερεύς τις κατέβαινεν ἐν τῇ ὁδῷ ἐκείνῃ, καὶ ἰδὼν αὐτὸν ἀντιπαρῆλθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 32, 'Ὁμοίως δὲ καὶ Λευίτης γενόμενος κατὰ τὸν τόπον, ἐλθὼν καὶ ἰδὼν ἀντιπαρῆλθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 33, 'Σαμαρείτης δέ τις ὁδεύων ἦλθεν κατʼ αὐτὸν, καὶ ἰδὼν ἐσπλαγχνίσθη');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 34, 'καὶ προσελθὼν, κατέδησεν τὰ τραύματα αὐτοῦ, ἐπιχέων ἔλαιον καὶ οἶνον, ἐπιβιβάσας δὲ αὐτὸν ἐπὶ τὸ ἴδιον κτῆνος, ἤγαγεν αὐτὸν εἰς πανδοχεῖον καὶ ἐπεμελήθη αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 35, 'Καὶ ἐπὶ τὴν αὔριον ἐκβαλὼν, ἔδωκεν δύο δηνάρια τῷ πανδοχεῖ, καὶ εἶπεν, ‘Ἐπιμελήθητι αὐτοῦ, καὶ ὅ τι ἂν προσδαπανήσῃς, ἐγὼ ἐν τῷ ἐπανέρχεσθαί με ἀποδώσω σοι.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 36, 'Τίς τούτων τῶν τριῶν πλησίον δοκεῖ σοι γεγονέναι, τοῦ ἐμπεσόντος εἰς τοὺς λῃστάς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 37, 'Ὁ δὲ εἶπεν, “Ὁ ποιήσας τὸ ἔλεος μετʼ αὐτοῦ.” Εἶπεν δὲ αὐτῷ ὁ  ̊Ἰησοῦς, “Πορεύου καὶ σὺ ποίει ὁμοίως.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 38, '¶Ἐν δὲ τῷ πορεύεσθαι αὐτοὺς, αὐτὸς εἰσῆλθεν εἰς κώμην τινά· γυνὴ δέ τις ὀνόματι Μάρθα ὑπεδέξατο αὐτὸν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 39, 'καὶ τῇδε ἦν ἀδελφὴ καλουμένη Μαριάμ, ἣ καὶ παρακαθεσθεῖσα πρὸς τοὺς πόδας τοῦ  ̊Ἰησοῦ, ἤκουεν τὸν λόγον αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 40, 'Ἡ δὲ Μάρθα περιεσπᾶτο περὶ πολλὴν διακονίαν· ἐπιστᾶσα δὲ εἶπεν, “ ̊Κύριε, οὐ μέλει σοι ὅτι ἡ ἀδελφή μου μόνην με κατέλιπεν διακονεῖν; Εἰπὲ οὖν αὐτῇ ἵνα μοι συναντιλάβηται!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 41, 'Ἀποκριθεὶς δὲ εἶπεν αὐτῇ ὁ  ̊Κύριος, “Μάρθα, Μάρθα, μεριμνᾷς καὶ θορυβάζῃ περὶ πολλά,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 42, 'ἑνὸς δέ ἐστιν χρεία· Μαριὰμ γὰρ τὴν ἀγαθὴν μερίδα ἐξελέξατο, ἥτις οὐκ ἀφαιρεθήσεται ἀπʼ αὐτῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 1, '¶Καὶ ἐγένετο ἐν τῷ εἶναι αὐτὸν ἐν τόπῳ τινὶ προσευχόμενον, ὡς ἐπαύσατο, εἶπέν τις τῶν μαθητῶν αὐτοῦ πρὸς αὐτόν, “ ̊Κύριε, δίδαξον ἡμᾶς προσεύχεσθαι, καθὼς καὶ Ἰωάννης ἐδίδαξεν τοὺς μαθητὰς αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 2, 'Εἶπεν δὲ αὐτοῖς, “Ὅταν προσεύχησθε, λέγετε, ‘Πάτερ, ἁγιασθήτω τὸ ὄνομά σου. Ἐλθάτω ἡ βασιλεία σου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 3, 'Τὸν ἄρτον ἡμῶν τὸν ἐπιούσιον, δίδου ἡμῖν τὸ καθʼ ἡμέραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 4, 'Καὶ ἄφες ἡμῖν τὰς ἁμαρτίας ἡμῶν, καὶ γὰρ αὐτοὶ ἀφίομεν παντὶ ὀφείλοντι ἡμῖν. Καὶ μὴ εἰσενέγκῃς ἡμᾶς εἰς πειρασμόν.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 5, '¶Καὶ εἶπεν πρὸς αὐτούς, “Τίς ἐξ ὑμῶν ἕξει φίλον, καὶ πορεύσεται πρὸς αὐτὸν μεσονυκτίου, καὶ εἴπῃ αὐτῷ, ‘Φίλε, χρῆσόν μοι τρεῖς ἄρτους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 6, 'ἐπειδὴ φίλος μου παρεγένετο ἐξ ὁδοῦ πρός με, καὶ οὐκ ἔχω ὃ παραθήσω αὐτῷ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 7, 'Κἀκεῖνος ἔσωθεν ἀποκριθεὶς εἴπῃ, ‘Μή μοι κόπους πάρεχε· ἤδη ἡ θύρα κέκλεισται, καὶ τὰ παιδία μου μετʼ ἐμοῦ εἰς τὴν κοίτην εἰσίν· οὐ δύναμαι ἀναστὰς δοῦναί σοι.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 8, 'Λέγω ὑμῖν, εἰ καὶ οὐ δώσει αὐτῷ ἀναστὰς, διὰ τὸ εἶναι φίλον αὐτοῦ, διά γε τὴν ἀναίδειαν αὐτοῦ ἐγερθεὶς, δώσει αὐτῷ ὅσων χρῄζει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 9, '¶Κἀγὼ ὑμῖν λέγω, ‘Αἰτεῖτε, καὶ δοθήσεται ὑμῖν· ζητεῖτε, καὶ εὑρήσετε· κρούετε, καὶ ἀνοιγήσεται ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 10, 'Πᾶς γὰρ ὁ αἰτῶν λαμβάνει, καὶ ὁ ζητῶν εὑρίσκει, καὶ τῷ κρούοντι ἀνοιγήσεται.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 11, 'Τίνα δὲ ἐξ ὑμῶν τὸν πατέρα αἰτήσει ὁ υἱὸς ἰχθύν, καὶ ἀντὶ ἰχθύος, ὄφιν αὐτῷ ἐπιδώσει;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 12, 'ἢ καὶ αἰτήσει ᾠόν, ἐπιδώσει αὐτῷ σκορπίον;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 13, 'Εἰ οὖν ὑμεῖς πονηροὶ ὑπάρχοντες, οἴδατε δόματα ἀγαθὰ διδόναι τοῖς τέκνοις ὑμῶν, πόσῳ μᾶλλον ὁ Πατὴρ ὁ ἐξ οὐρανοῦ δώσει  ̊Πνεῦμα Ἅγιον τοῖς αἰτοῦσιν αὐτόν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 14, '¶Καὶ ἦν ἐκβάλλων δαιμόνιον κωφόν. Ἐγένετο δὲ τοῦ δαιμονίου ἐξελθόντος, ἐλάλησεν ὁ κωφός. Καὶ ἐθαύμασαν οἱ ὄχλοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 15, 'Τινὲς δὲ ἐξ αὐτῶν εἶπον, “Ἐν Βεελζεβοὺλ τῷ ἄρχοντι τῶν δαιμονίων, ἐκβάλλει τὰ δαιμόνια.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 16, 'Ἕτεροι δὲ πειράζοντες, σημεῖον ἐξ οὐρανοῦ ἐζήτουν παρʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 17, 'Αὐτὸς δὲ εἰδὼς αὐτῶν τὰ διανοήματα εἶπεν αὐτοῖς, “Πᾶσα βασιλεία ἐφʼ ἑαυτὴν διαμερισθεῖσα ἐρημοῦται, καὶ οἶκος ἐπὶ οἶκον πίπτει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 18, 'Εἰ δὲ καὶ ὁ Σατανᾶς ἐφʼ ἑαυτὸν διεμερίσθη, πῶς σταθήσεται ἡ βασιλεία αὐτοῦ; Ὅτι λέγετε, ἐν Βεελζεβοὺλ ἐκβάλλειν με τὰ δαιμόνια.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 19, 'Εἰ δὲ ἐγὼ ἐν Βεελζεβοὺλ ἐκβάλλω τὰ δαιμόνια, οἱ υἱοὶ ὑμῶν ἐν τίνι ἐκβάλλουσιν; Διὰ τοῦτο, αὐτοὶ ὑμῶν κριταὶ ἔσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 20, 'Εἰ δὲ ἐν δακτύλῳ  ̊Θεοῦ, ἐγὼ ἐκβάλλω τὰ δαιμόνια, ἄρα ἔφθασεν ἐφʼ ὑμᾶς ἡ Βασιλεία τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 21, 'Ὅταν ὁ ἰσχυρὸς καθωπλισμένος, φυλάσσῃ τὴν ἑαυτοῦ αὐλήν, ἐν εἰρήνῃ ἐστὶν τὰ ὑπάρχοντα αὐτοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 22, 'ἐπὰν δὲ ἰσχυρότερος αὐτοῦ ἐπελθὼν, νικήσῃ αὐτόν, τὴν πανοπλίαν αὐτοῦ αἴρει ἐφʼ ᾗ ἐπεποίθει, καὶ τὰ σκῦλα αὐτοῦ διαδίδωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 23, 'Ὁ μὴ ὢν μετʼ ἐμοῦ, κατʼ ἐμοῦ ἐστιν, καὶ ὁ μὴ συνάγων μετʼ ἐμοῦ, σκορπίζει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 24, '¶Ὅταν τὸ ἀκάθαρτον πνεῦμα ἐξέλθῃ ἀπὸ τοῦ ἀνθρώπου, διέρχεται διʼ ἀνύδρων τόπων ζητοῦν ἀνάπαυσιν, καὶ μὴ εὑρίσκον, λέγει, ‘Ὑποστρέψω εἰς τὸν οἶκόν μου, ὅθεν ἐξῆλθον.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 25, 'Καὶ ἐλθὸν, εὑρίσκει σεσαρωμένον καὶ κεκοσμημένον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 26, 'Τότε πορεύεται καὶ παραλαμβάνει ἕτερα πνεύματα πονηρότερα ἑαυτοῦ ἑπτά, καὶ εἰσελθόντα, κατοικεῖ ἐκεῖ, καὶ γίνεται τὰ ἔσχατα τοῦ ἀνθρώπου ἐκείνου, χείρονα τῶν πρώτων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 27, '¶Ἐγένετο δὲ ἐν τῷ λέγειν αὐτὸν ταῦτα, ἐπάρασά τις φωνὴν γυνὴ ἐκ τοῦ ὄχλου, εἶπεν αὐτῷ, “Μακαρία ἡ κοιλία ἡ βαστάσασά σε, καὶ μαστοὶ οὓς ἐθήλασας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 28, 'Αὐτὸς δὲ εἶπεν, “Μενοῦν, μακάριοι οἱ ἀκούοντες τὸν λόγον τοῦ  ̊Θεοῦ καὶ φυλάσσοντες.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 29, '¶Τῶν δὲ ὄχλων ἐπαθροιζομένων, ἤρξατο λέγειν, “Ἡ γενεὰ αὕτη γενεὰ πονηρά ἐστιν· σημεῖον ζητεῖ καὶ σημεῖον οὐ δοθήσεται αὐτῇ, εἰ μὴ τὸ σημεῖον Ἰωνᾶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 30, 'Καθὼς γὰρ ἐγένετο Ἰωνᾶς τοῖς Νινευίταις σημεῖον, οὕτως ἔσται καὶ ὁ Υἱὸς τοῦ Ἀνθρώπου τῇ γενεᾷ ταύτῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 31, 'Βασίλισσα νότου ἐγερθήσεται ἐν τῇ κρίσει μετὰ τῶν ἀνδρῶν τῆς γενεᾶς ταύτης, καὶ κατακρινεῖ αὐτούς, ὅτι ἦλθεν ἐκ τῶν περάτων τῆς γῆς ἀκοῦσαι τὴν σοφίαν Σολομῶνος, καὶ ἰδοὺ, πλεῖον Σολομῶνος ὧδε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 32, 'Ἄνδρες Νινευῖται ἀναστήσονται ἐν τῇ κρίσει μετὰ τῆς γενεᾶς ταύτης, καὶ κατακρινοῦσιν αὐτήν, ὅτι μετενόησαν εἰς τὸ κήρυγμα Ἰωνᾶ, καὶ ἰδοὺ, πλεῖον Ἰωνᾶ ὧδε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 33, '¶Οὐδεὶς λύχνον ἅψας εἰς κρύπτην τίθησιν, οὐδὲ ὑπὸ τὸν μόδιον, ἀλλʼ ἐπὶ τὴν λυχνίαν, ἵνα οἱ εἰσπορευόμενοι τὸ φῶς βλέπωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 34, 'Ὁ λύχνος τοῦ σώματός ἐστιν ὁ ὀφθαλμός σου. Ὅταν ὁ ὀφθαλμός σου ἁπλοῦς ᾖ, καὶ ὅλον τὸ σῶμά σου φωτεινόν ἐστιν· ἐπὰν δὲ πονηρὸς ᾖ, καὶ τὸ σῶμά σου σκοτεινόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 35, 'Σκόπει οὖν, μὴ τὸ φῶς τὸ ἐν σοὶ σκότος ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 36, 'Εἰ οὖν τὸ σῶμά σου ὅλον φωτεινόν, μὴ ἔχον μέρος τι σκοτεινόν, ἔσται φωτεινὸν ὅλον, ὡς ὅταν ὁ λύχνος τῇ ἀστραπῇ φωτίζῃ σε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 37, '¶Ἐν δὲ τῷ λαλῆσαι, ἐρωτᾷ αὐτὸν Φαρισαῖος ὅπως ἀριστήσῃ παρʼ αὐτῷ, εἰσελθὼν δὲ, ἀνέπεσεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 38, 'Ὁ δὲ Φαρισαῖος ἰδὼν, ἐθαύμασεν ὅτι οὐ πρῶτον ἐβαπτίσθη πρὸ τοῦ ἀρίστου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 39, 'Εἶπεν δὲ ὁ  ̊Κύριος πρὸς αὐτόν, “Νῦν ὑμεῖς οἱ Φαρισαῖοι τὸ ἔξωθεν τοῦ ποτηρίου καὶ τοῦ πίνακος καθαρίζετε, τὸ δὲ ἔσωθεν ὑμῶν γέμει ἁρπαγῆς καὶ πονηρίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 40, 'Ἄφρονες! Οὐχ ὁ ποιήσας τὸ ἔξωθεν, καὶ τὸ ἔσωθεν ἐποίησεν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 41, 'Πλὴν τὰ ἐνόντα δότε ἐλεημοσύνην, καὶ ἰδοὺ, πάντα καθαρὰ ὑμῖν ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 42, '¶Ἀλλὰ οὐαὶ ὑμῖν τοῖς Φαρισαίοις, ὅτι ἀποδεκατοῦτε τὸ ἡδύοσμον, καὶ τὸ πήγανον, καὶ πᾶν λάχανον, καὶ παρέρχεσθε τὴν κρίσιν καὶ τὴν ἀγάπην τοῦ  ̊Θεοῦ. Ταῦτα δὲ ἔδει ποιῆσαι, κἀκεῖνα μὴ παρεῖναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 43, 'Οὐαὶ ὑμῖν τοῖς Φαρισαίοις, ὅτι ἀγαπᾶτε τὴν πρωτοκαθεδρίαν ἐν ταῖς συναγωγαῖς, καὶ τοὺς ἀσπασμοὺς ἐν ταῖς ἀγοραῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 44, 'Οὐαὶ ὑμῖν, ὅτι ἐστὲ ὡς τὰ μνημεῖα τὰ ἄδηλα, καὶ οἱ ἄνθρωποι περιπατοῦντες ἐπάνω οὐκ οἴδασιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 45, '¶Ἀποκριθεὶς δέ τις τῶν νομικῶν λέγει αὐτῷ, “Διδάσκαλε, ταῦτα λέγων, καὶ ἡμᾶς ὑβρίζεις.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 46, 'Ὁ δὲ εἶπεν, “Καὶ ὑμῖν τοῖς νομικοῖς οὐαί! Ὅτι φορτίζετε τοὺς ἀνθρώπους φορτία δυσβάστακτα, καὶ αὐτοὶ ἑνὶ τῶν δακτύλων ὑμῶν οὐ προσψαύετε τοῖς φορτίοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 47, 'Οὐαὶ ὑμῖν, ὅτι οἰκοδομεῖτε τὰ μνημεῖα τῶν προφητῶν, οἱ δὲ πατέρες ὑμῶν ἀπέκτειναν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 48, 'Ἄρα μαρτυρεῖτε καὶ συνευδοκεῖτε τοῖς ἔργοις τῶν πατέρων ὑμῶν, ὅτι αὐτοὶ μὲν ἀπέκτειναν αὐτοὺς, ὑμεῖς δὲ οἰκοδομεῖτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 49, 'Διὰ τοῦτο καὶ ἡ σοφία τοῦ  ̊Θεοῦ εἶπεν, ‘Ἀποστελῶ εἰς αὐτοὺς προφήτας καὶ ἀποστόλους, καὶ ἐξ αὐτῶν ἀποκτενοῦσιν καὶ διώξουσιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 50, 'ἵνα ἐκζητηθῇ τὸ αἷμα πάντων τῶν προφητῶν, τὸ ἐκχυννόμενον ἀπὸ καταβολῆς κόσμου, ἀπὸ τῆς γενεᾶς ταύτης,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 51, 'ἀπὸ αἵματος Ἅβελ ἕως αἵματος Ζαχαρίου, τοῦ ἀπολομένου μεταξὺ τοῦ θυσιαστηρίου καὶ τοῦ οἴκου. Ναί, λέγω ὑμῖν, ἐκζητηθήσεται ἀπὸ τῆς γενεᾶς ταύτης.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 52, 'Οὐαὶ ὑμῖν τοῖς νομικοῖς, ὅτι ἤρατε τὴν κλεῖδα τῆς γνώσεως· αὐτοὶ οὐκ εἰσήλθατε, καὶ τοὺς εἰσερχομένους ἐκωλύσατε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 53, '¶Κἀκεῖθεν ἐξελθόντος αὐτοῦ, ἤρξαντο οἱ γραμματεῖς καὶ οἱ Φαρισαῖοι δεινῶς ἐνέχειν, καὶ ἀποστοματίζειν αὐτὸν περὶ πλειόνων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 54, 'ἐνεδρεύοντες αὐτὸν θηρεῦσαί τι ἐκ τοῦ στόματος αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 1, '¶Ἐν οἷς ἐπισυναχθεισῶν τῶν μυριάδων τοῦ ὄχλου, ὥστε καταπατεῖν ἀλλήλους, ἤρξατο λέγειν πρὸς τοὺς μαθητὰς αὐτοῦ πρῶτον, “Προσέχετε ἑαυτοῖς ἀπὸ τῆς ζύμης, τῶν Φαρισαίων, ἥτις ἐστὶν ὑπόκρισις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 2, 'Οὐδὲν δὲ συγκεκαλυμμένον ἐστὶν, ὃ οὐκ ἀποκαλυφθήσεται, καὶ κρυπτὸν ὃ οὐ γνωσθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 3, 'Ἀνθʼ ὧν ὅσα ἐν τῇ σκοτίᾳ εἴπατε, ἐν τῷ φωτὶ ἀκουσθήσεται, καὶ ὃ πρὸς τὸ οὖς ἐλαλήσατε ἐν τοῖς ταμείοις, κηρυχθήσεται ἐπὶ τῶν δωμάτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 4, '¶Λέγω δὲ ὑμῖν, τοῖς φίλοις μου, μὴ φοβηθῆτε ἀπὸ τῶν ἀποκτεινόντων τὸ σῶμα, καὶ μετὰ ταῦτα μὴ ἐχόντων περισσότερόν τι ποιῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 5, 'Ὑποδείξω δὲ ὑμῖν τίνα φοβηθῆτε: φοβήθητε τὸν μετὰ τὸ ἀποκτεῖναι, ἔχοντα ἐξουσίαν ἐμβαλεῖν εἰς τὴν Γέενναν· ναί, λέγω ὑμῖν, τοῦτον φοβήθητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 6, 'Οὐχὶ πέντε στρουθία πωλοῦνται ἀσσαρίων δύο; Καὶ ἓν ἐξ αὐτῶν οὐκ ἔστιν ἐπιλελησμένον ἐνώπιον τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 7, 'Ἀλλὰ καὶ αἱ τρίχες τῆς κεφαλῆς ὑμῶν πᾶσαι ἠρίθμηνται. Μὴ φοβεῖσθε, πολλῶν στρουθίων διαφέρετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 8, '¶Λέγω δὲ ὑμῖν, πᾶς ὃς ἂν ὁμολογήσῃ ἐν ἐμοὶ ἔμπροσθεν τῶν ἀνθρώπων, καὶ ὁ Υἱὸς τοῦ Ἀνθρώπου ὁμολογήσει, ἐν αὐτῷ ἔμπροσθεν τῶν ἀγγέλων τοῦ  ̊Θεοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 9, 'ὁ δὲ ἀρνησάμενός με ἐνώπιον τῶν ἀνθρώπων, ἀπαρνηθήσεται ἐνώπιον τῶν ἀγγέλων τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 10, 'Καὶ πᾶς ὃς ἐρεῖ λόγον εἰς τὸν Υἱὸν τοῦ Ἀνθρώπου, ἀφεθήσεται αὐτῷ· τῷ δὲ εἰς τὸ Ἅγιον  ̊Πνεῦμα βλασφημήσαντι, οὐκ ἀφεθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 11, 'Ὅταν δὲ εἰσφέρωσιν ὑμᾶς ἐπὶ τὰς συναγωγὰς, καὶ τὰς ἀρχὰς, καὶ τὰς ἐξουσίας, μὴ μεριμνήσητε πῶς ἢ τί ἀπολογήσησθε ἢ τί εἴπητε·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 12, 'τὸ γὰρ Ἅγιον  ̊Πνεῦμα διδάξει ὑμᾶς ἐν αὐτῇ τῇ ὥρᾳ ἃ δεῖ εἰπεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 13, '¶Εἶπεν δέ τις ἐκ τοῦ ὄχλου αὐτῷ, “Διδάσκαλε, εἰπὲ τῷ ἀδελφῷ μου μερίσασθαι μετʼ ἐμοῦ τὴν κληρονομίαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 14, 'Ὁ δὲ εἶπεν αὐτῷ, “Ἄνθρωπε, τίς με κατέστησεν κριτὴν ἢ μεριστὴν ἐφʼ ὑμᾶς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 15, 'Εἶπεν δὲ πρὸς αὐτούς, “Ὁρᾶτε καὶ φυλάσσεσθε ἀπὸ πάσης πλεονεξίας, ὅτι οὐκ ἐν τῷ περισσεύειν τινὶ, ἡ ζωὴ αὐτοῦ ἐστιν ἐκ τῶν ὑπαρχόντων αὐτῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 16, 'Εἶπεν δὲ παραβολὴν πρὸς αὐτοὺς λέγων, “Ἀνθρώπου τινὸς πλουσίου εὐφόρησεν ἡ χώρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 17, 'Καὶ διελογίζετο ἐν ἑαυτῷ λέγων, ‘Τί ποιήσω, ὅτι οὐκ ἔχω ποῦ συνάξω τοὺς καρπούς μου;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 18, 'Καὶ εἶπεν, ‘Τοῦτο ποιήσω: καθελῶ μου τὰς ἀποθήκας καὶ μείζονας οἰκοδομήσω, καὶ συνάξω ἐκεῖ πάντα τὸν σῖτον καὶ τὰ ἀγαθά μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 19, 'Καὶ ἐρῶ τῇ ψυχῇ μου, “Ψυχή, ἔχεις πολλὰ ἀγαθὰ κείμενα εἰς ἔτη πολλά· ἀναπαύου, φάγε, πίε, εὐφραίνου.”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 20, 'Εἶπεν δὲ αὐτῷ ὁ  ̊Θεός, ‘Ἄφρων, ταύτῃ τῇ νυκτὶ, τὴν ψυχήν σου αἰτοῦσιν ἀπὸ σοῦ· ἃ δὲ ἡτοίμασας, τίνι ἔσται;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 21, 'Οὕτως ὁ θησαυρίζων ἑαυτῷ καὶ μὴ εἰς  ̊Θεὸν πλουτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 22, '¶Εἶπεν δὲ πρὸς τοὺς μαθητὰς “Διὰ τοῦτο λέγω ὑμῖν, μὴ μεριμνᾶτε τῇ ψυχῇ, τί φάγητε μηδὲ τῷ σώματι τί ἐνδύσησθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 23, 'Ἡ γὰρ ψυχὴ πλεῖόν ἐστιν τῆς τροφῆς, καὶ τὸ σῶμα τοῦ ἐνδύματος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 24, 'Κατανοήσατε τοὺς κόρακας, ὅτι οὐ σπείρουσιν οὐδὲ θερίζουσιν, οἷς οὐκ ἔστιν ταμεῖον οὐδὲ ἀποθήκη, καὶ ὁ  ̊Θεὸς τρέφει αὐτούς. Πόσῳ μᾶλλον ὑμεῖς διαφέρετε τῶν πετεινῶν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 25, 'Τίς δὲ ἐξ ὑμῶν μεριμνῶν, δύναται ἐπὶ τὴν ἡλικίαν αὐτοῦ προσθεῖναι πῆχυν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 26, 'Εἰ οὖν οὐδὲ ἐλάχιστον δύνασθε, τί περὶ τῶν λοιπῶν μεριμνᾶτε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 27, 'Κατανοήσατε τὰ κρίνα πῶς αὐξάνει, οὐ κοπιᾷ οὐδὲ νήθει· λέγω δὲ ὑμῖν, οὐδὲ Σολομὼν ἐν πάσῃ τῇ δόξῃ αὐτοῦ, περιεβάλετο ὡς ἓν τούτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 28, 'Εἰ δὲ ἐν ἀγρῷ τὸν χόρτον ὄντα σήμερον, καὶ αὔριον εἰς κλίβανον βαλλόμενον, ὁ  ̊Θεὸς οὕτως ἀμφιέζει, πόσῳ μᾶλλον ὑμᾶς, ὀλιγόπιστοι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 29, 'Καὶ ὑμεῖς μὴ ζητεῖτε τί φάγητε, ἢ τί πίητε, καὶ μὴ μετεωρίζεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 30, 'Ταῦτα γὰρ πάντα τὰ ἔθνη τοῦ κόσμου ἐπιζητοῦσιν, ὑμῶν δὲ ὁ Πατὴρ οἶδεν ὅτι χρῄζετε τούτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 31, 'Πλὴν ζητεῖτε τὴν βασιλείαν αὐτοῦ, καὶ ταῦτα προστεθήσεται ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 32, '¶Μὴ φοβοῦ, τὸ μικρὸν ποίμνιον, ὅτι εὐδόκησεν ὁ Πατὴρ ὑμῶν, δοῦναι ὑμῖν τὴν βασιλείαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 33, 'Πωλήσατε τὰ ὑπάρχοντα ὑμῶν, καὶ δότε ἐλεημοσύνην. Ποιήσατε ἑαυτοῖς βαλλάντια μὴ παλαιούμενα, θησαυρὸν ἀνέκλειπτον ἐν τοῖς οὐρανοῖς, ὅπου κλέπτης οὐκ ἐγγίζει οὐδὲ σὴς διαφθείρει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 34, 'Ὅπου γάρ ἐστιν ὁ θησαυρὸς ὑμῶν, ἐκεῖ καὶ ἡ καρδία ὑμῶν ἔσται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 35, '¶Ἔστωσαν ὑμῶν αἱ ὀσφύες περιεζωσμέναι, καὶ οἱ λύχνοι καιόμενοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 36, 'καὶ ὑμεῖς ὅμοιοι ἀνθρώποις προσδεχομένοις τὸν κύριον ἑαυτῶν, πότε ἀναλύσῃ ἐκ τῶν γάμων, ἵνα ἐλθόντος καὶ κρούσαντος, εὐθέως ἀνοίξωσιν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 37, 'Μακάριοι οἱ δοῦλοι ἐκεῖνοι, οὓς ἐλθὼν, ὁ  ̊Κύριος εὑρήσει γρηγοροῦντας. Ἀμὴν, λέγω ὑμῖν ὅτι περιζώσεται καὶ ἀνακλινεῖ αὐτοὺς, καὶ παρελθὼν, διακονήσει αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 38, 'Κἂν ἐν τῇ δευτέρᾳ κἂν ἐν τῇ τρίτῃ φυλακῇ ἔλθῃ, καὶ εὕρῃ οὕτως, μακάριοί εἰσιν ἐκεῖνοι!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 39, '¶Τοῦτο δὲ γινώσκετε, ὅτι εἰ ᾔδει ὁ οἰκοδεσπότης ποίᾳ ὥρᾳ ὁ κλέπτης ἔρχεται, ἐγρηγόρησεν ἂν καὶ οὐκ ἂν ἀφῆκεν διορυχθῆναι τὸν οἶκον αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 40, 'Καὶ ὑμεῖς γίνεσθε ἕτοιμοι, ὅτι ᾗ ὥρᾳ οὐ δοκεῖτε, ὁ Υἱὸς τοῦ Ἀνθρώπου ἔρχεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 41, '¶Εἶπεν δὲ ὁ Πέτρος, “ ̊Κύριε, πρὸς ἡμᾶς τὴν παραβολὴν ταύτην λέγεις, ἢ καὶ πρὸς πάντας;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 42, 'Καὶ εἶπεν ὁ  ̊Κύριος, “Τίς ἄρα ἐστὶν ὁ πιστὸς οἰκονόμος ὁ φρόνιμος, ὃν καταστήσει ὁ  ̊Κύριος ἐπὶ τῆς θεραπείας αὐτοῦ, τοῦ διδόναι ἐν καιρῷ σιτομέτριον;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 43, 'Μακάριος ὁ δοῦλος ἐκεῖνος, ὃν ἐλθὼν, ὁ κύριος αὐτοῦ εὑρήσει οὕτως ποιοῦντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 44, 'Ἀληθῶς λέγω ὑμῖν ὅτι ἐπὶ πᾶσιν τοῖς ὑπάρχουσιν αὐτοῦ καταστήσει αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 45, 'Ἐὰν δὲ εἴπῃ ὁ δοῦλος ἐκεῖνος ἐν τῇ καρδίᾳ αὐτοῦ, ‘Χρονίζει ὁ κύριός μου ἔρχεσθαι’, καὶ ἄρξηται τύπτειν τοὺς παῖδας καὶ τὰς παιδίσκας, ἐσθίειν τε καὶ πίνειν καὶ μεθύσκεσθαι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 46, 'ἥξει ὁ κύριος τοῦ δούλου ἐκείνου ἐν ἡμέρᾳ ᾗ οὐ προσδοκᾷ, καὶ ἐν ὥρᾳ ᾗ οὐ γινώσκει, καὶ διχοτομήσει αὐτὸν, καὶ τὸ μέρος αὐτοῦ μετὰ τῶν ἀπίστων θήσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 47, 'Ἐκεῖνος δὲ ὁ δοῦλος, ὁ γνοὺς τὸ θέλημα τοῦ κυρίου αὐτοῦ, καὶ μὴ ἑτοιμάσας ἢ ποιήσας πρὸς τὸ θέλημα αὐτοῦ, δαρήσεται πολλάς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 48, 'ὁ δὲ μὴ γνοὺς, ποιήσας δὲ ἄξια πληγῶν, δαρήσεται ὀλίγας. Παντὶ δὲ ᾧ ἐδόθη πολύ, πολὺ ζητηθήσεται παρʼ αὐτοῦ, καὶ ᾧ παρέθεντο πολύ, περισσότερον αἰτήσουσιν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 49, '¶Πῦρ ἦλθον βαλεῖν ἐπὶ τὴν γῆν, καὶ τί θέλω εἰ ἤδη ἀνήφθη;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 50, 'Βάπτισμα δὲ ἔχω βαπτισθῆναι, καὶ πῶς συνέχομαι ἕως ὅτου τελεσθῇ!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 51, 'Δοκεῖτε ὅτι εἰρήνην παρεγενόμην δοῦναι ἐν τῇ γῇ; Οὐχί, λέγω ὑμῖν, ἀλλʼ ἢ διαμερισμόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 52, 'Ἔσονται γὰρ ἀπὸ τοῦ νῦν, πέντε ἐν ἑνὶ οἴκῳ διαμεμερισμένοι, τρεῖς ἐπὶ δυσὶν, καὶ δύο ἐπὶ τρισίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 53, 'Διαμερισθήσονται πατὴρ ἐπὶ υἱῷ, καὶ υἱὸς ἐπὶ πατρί, μήτηρ ἐπὶ θυγατέρα, καὶ θυγάτηρ ἐπὶ τὴν μητέρα, πενθερὰ ἐπὶ τὴν νύμφην αὐτῆς, καὶ νύμφη ἐπὶ τὴν πενθεράν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 54, '¶Ἔλεγεν δὲ καὶ τοῖς ὄχλοις, “Ὅταν ἴδητε νεφέλην ἀνατέλλουσαν ἐπὶ δυσμῶν, εὐθέως λέγετε, ὅτι ‘Ὄμβρος ἔρχεται’, καὶ γίνεται οὕτως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 55, 'Καὶ ὅταν νότον πνέοντα, λέγετε, ὅτι ‘Καύσων ἔσται’, καὶ γίνεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 56, 'Ὑποκριταί! Τὸ πρόσωπον τῆς γῆς καὶ τοῦ οὐρανοῦ οἴδατε δοκιμάζειν, τὸν καιρὸν δὲ τοῦτον, πῶς οὐκ οἴδατε δοκιμάζειν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 57, '¶Τί δὲ καὶ ἀφʼ ἑαυτῶν, οὐ κρίνετε τὸ δίκαιον;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 58, 'Ὡς γὰρ ὑπάγεις μετὰ τοῦ ἀντιδίκου σου ἐπʼ ἄρχοντα ἐν τῇ ὁδῷ, δὸς ἐργασίαν ἀπηλλάχθαι ἀπʼ αὐτοῦ, μήποτε κατασύρῃ σε πρὸς τὸν κριτήν, καὶ ὁ κριτής σε παραδώσει τῷ πράκτορι, καὶ ὁ πράκτωρ σε βαλεῖ εἰς φυλακήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 59, 'Λέγω σοι, οὐ μὴ ἐξέλθῃς ἐκεῖθεν ἕως καὶ τὸ ἔσχατον λεπτὸν ἀποδῷς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 1, '¶Παρῆσαν δέ τινες ἐν αὐτῷ τῷ καιρῷ, ἀπαγγέλλοντες αὐτῷ περὶ τῶν Γαλιλαίων, ὧν τὸ αἷμα Πιλᾶτος ἔμιξεν μετὰ τῶν θυσιῶν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 2, 'Καὶ ἀποκριθεὶς εἶπεν αὐτοῖς, “Δοκεῖτε ὅτι οἱ Γαλιλαῖοι οὗτοι, ἁμαρτωλοὶ παρὰ πάντας τοὺς Γαλιλαίους ἐγένοντο, ὅτι τοιαῦτα πεπόνθασιν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 3, 'Οὐχί, λέγω ὑμῖν, ἀλλʼ ἐὰν μὴ μετανοῆτε, πάντες ὁμοίως ἀπολεῖσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 4, 'Ἢ ἐκεῖνοι οἱ δεκαοκτὼ ἐφʼ οὓς ἔπεσεν ὁ πύργος ἐν τῷ Σιλωὰμ καὶ ἀπέκτεινεν αὐτούς, δοκεῖτε ὅτι αὐτοὶ ὀφειλέται ἐγένοντο παρὰ πάντας τοὺς ἀνθρώπους τοὺς κατοικοῦντας Ἰερουσαλήμ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 5, 'Οὐχί, λέγω ὑμῖν, ἀλλʼ ἐὰν μὴ μετανοῆτε, πάντες ὁμοίως ἀπολεῖσθε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 6, '¶Ἔλεγεν δὲ ταύτην τὴν παραβολήν: “Συκῆν εἶχέν τις πεφυτευμένην ἐν τῷ ἀμπελῶνι αὐτοῦ, καὶ ἦλθεν ζητῶν καρπὸν ἐν αὐτῇ, καὶ οὐχ εὗρεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 7, 'Εἶπεν δὲ πρὸς τὸν ἀμπελουργόν, ‘Ἰδοὺ, τρία ἔτη ἀφʼ οὗ ἔρχομαι ζητῶν καρπὸν ἐν τῇ συκῇ ταύτῃ, καὶ οὐχ εὑρίσκω. Ἔκκοψον αὐτήν, ἵνα τί καὶ τὴν γῆν καταργεῖ;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 8, 'Ὁ δὲ ἀποκριθεὶς λέγει αὐτῷ, ‘Κύριε, ἄφες αὐτὴν καὶ τοῦτο τὸ ἔτος, ἕως ὅτου σκάψω περὶ αὐτὴν καὶ βάλω κόπρια·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 9, 'κἂν μὲν ποιήσῃ καρπὸν εἰς τὸ μέλλον, εἰ δὲ μή γε ἐκκόψεις αὐτήν.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 10, '¶Ἦν δὲ διδάσκων ἐν μιᾷ τῶν συναγωγῶν ἐν τοῖς Σάββασιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 11, 'Καὶ ἰδοὺ, γυνὴ πνεῦμα ἔχουσα ἀσθενείας ἔτη δεκαοκτώ, καὶ ἦν συγκύπτουσα καὶ μὴ δυναμένη ἀνακύψαι εἰς τὸ παντελές.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 12, 'Ἰδὼν δὲ αὐτὴν, ὁ  ̊Ἰησοῦς προσεφώνησεν καὶ εἶπεν αὐτῇ, “Γύναι, ἀπολέλυσαι τῆς ἀσθενείας σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 13, 'Καὶ ἐπέθηκεν αὐτῇ τὰς χεῖρας, καὶ παραχρῆμα ἀνωρθώθη καὶ ἐδόξαζεν τὸν  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 14, 'Ἀποκριθεὶς δὲ ὁ ἀρχισυνάγωγος, ἀγανακτῶν ὅτι τῷ Σαββάτῳ ἐθεράπευσεν ὁ  ̊Ἰησοῦς, ἔλεγεν τῷ ὄχλῳ, ὅτι “Ἓξ ἡμέραι εἰσὶν ἐν αἷς δεῖ ἐργάζεσθαι· ἐν αὐταῖς οὖν ἐρχόμενοι θεραπεύεσθε, καὶ μὴ τῇ ἡμέρᾳ τοῦ Σαββάτου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 15, 'Ἀπεκρίθη δὲ αὐτῷ ὁ  ̊Κύριος καὶ εἶπεν, “Ὑποκριταί! Ἕκαστος ὑμῶν τῷ Σαββάτῳ οὐ λύει τὸν βοῦν αὐτοῦ, ἢ τὸν ὄνον ἀπὸ τῆς φάτνης, καὶ ἀπαγαγὼν ποτίζει;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 16, 'Ταύτην δὲ θυγατέρα Ἀβραὰμ οὖσαν, ἣν ἔδησεν ὁ Σατανᾶς, ἰδοὺ, δέκα καὶ ὀκτὼ ἔτη, οὐκ ἔδει λυθῆναι ἀπὸ τοῦ δεσμοῦ τούτου τῇ ἡμέρᾳ τοῦ Σαββάτου;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 17, 'Καὶ ταῦτα λέγοντος αὐτοῦ, κατῃσχύνοντο πάντες οἱ ἀντικείμενοι αὐτῷ, καὶ πᾶς ὁ ὄχλος ἔχαιρεν ἐπὶ πᾶσιν τοῖς ἐνδόξοις τοῖς γινομένοις ὑπʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 18, '¶Ἔλεγεν οὖν, “Τίνι ὁμοία ἐστὶν ἡ Βασιλεία τοῦ  ̊Θεοῦ, καὶ τίνι ὁμοιώσω αὐτήν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 19, 'Ὁμοία ἐστὶν κόκκῳ σινάπεως, ὃν λαβὼν, ἄνθρωπος ἔβαλεν εἰς κῆπον ἑαυτοῦ, καὶ ηὔξησεν καὶ ἐγένετο εἰς δένδρον, καὶ ‘Τὰ πετεινὰ τοῦ οὐρανοῦ κατεσκήνωσεν ἐν τοῖς κλάδοις αὐτοῦ.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 20, '¶Καὶ πάλιν εἶπεν, “Τίνι ὁμοιώσω τὴν Βασιλείαν τοῦ  ̊Θεοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 21, 'Ὁμοία ἐστὶν ζύμῃ, ἣν λαβοῦσα, γυνὴ ἐνέκρυψεν εἰς ἀλεύρου σάτα τρία, ἕως οὗ ἐζυμώθη ὅλον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 22, '¶Καὶ διεπορεύετο κατὰ πόλεις καὶ κώμας διδάσκων, καὶ πορείαν ποιούμενος εἰς Ἱεροσόλυμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 23, 'Εἶπεν δέ τις αὐτῷ, “ ̊Κύριε, εἰ ὀλίγοι οἱ σῳζόμενοι;” Ὁ δὲ εἶπεν πρὸς αὐτούς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 24, '“Ἀγωνίζεσθε εἰσελθεῖν διὰ τῆς στενῆς θύρας, ὅτι πολλοί, λέγω ὑμῖν, ζητήσουσιν εἰσελθεῖν καὶ οὐκ ἰσχύσουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 25, 'Ἀφʼ οὗ ἂν ἐγερθῇ ὁ οἰκοδεσπότης καὶ ἀποκλείσῃ τὴν θύραν, καὶ ἄρξησθε ἔξω ἑστάναι καὶ κρούειν τὴν θύραν λέγοντες, ‘Κύριε, ἄνοιξον ἡμῖν’· καὶ ἀποκριθεὶς ἐρεῖ ὑμῖν, ‘Οὐκ οἶδα ὑμᾶς, πόθεν ἐστέ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 26, 'Τότε ἄρξεσθε λέγειν, ‘Ἐφάγομεν ἐνώπιόν σου καὶ ἐπίομεν, καὶ ἐν ταῖς πλατείαις ἡμῶν ἐδίδαξας.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 27, 'Καὶ ἐρεῖ, λέγων ὑμῖν, ‘Οὐκ οἶδα πόθεν ἐστέ· “ἀπόστητε ἀπʼ ἐμοῦ, πάντες ἐργάται ἀδικίας”.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 28, 'Ἐκεῖ ἔσται ὁ κλαυθμὸς καὶ ὁ βρυγμὸς τῶν ὀδόντων, ὅταν ὄψησθε Ἀβραὰμ, καὶ Ἰσαὰκ, καὶ Ἰακὼβ, καὶ πάντας τοὺς προφήτας, ἐν τῇ Βασιλείᾳ τοῦ  ̊Θεοῦ, ὑμᾶς δὲ ἐκβαλλομένους ἔξω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 29, 'Καὶ ἥξουσιν ἀπὸ ἀνατολῶν καὶ δυσμῶν καὶ ἀπὸ βορρᾶ καὶ νότου, καὶ ἀνακλιθήσονται ἐν τῇ Βασιλείᾳ τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 30, 'Καὶ ἰδοὺ, εἰσὶν ἔσχατοι οἳ ἔσονται πρῶτοι, καὶ εἰσὶν πρῶτοι οἳ ἔσονται ἔσχατοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 31, '¶Ἐν αὐτῇ τῇ ὥρᾳ προσῆλθάν τινες Φαρισαῖοι λέγοντες αὐτῷ, “Ἔξελθε καὶ πορεύου ἐντεῦθεν, ὅτι Ἡρῴδης θέλει σε ἀποκτεῖναι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 32, 'Καὶ εἶπεν αὐτοῖς, “Πορευθέντες εἴπατε τῇ ἀλώπεκι ταύτῃ, ‘Ἰδοὺ, ἐκβάλλω δαιμόνια, καὶ ἰάσεις ἀποτελῶ σήμερον καὶ αὔριον, καὶ τῇ τρίτῃ τελειοῦμαι.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 33, 'Πλὴν δεῖ με, σήμερον καὶ αὔριον καὶ τῇ ἐχομένῃ πορεύεσθαι, ὅτι οὐκ ἐνδέχεται προφήτην ἀπολέσθαι ἔξω Ἰερουσαλήμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 34, 'Ἰερουσαλὴμ, Ἰερουσαλήμ, ἡ ἀποκτείνουσα τοὺς προφήτας, καὶ λιθοβολοῦσα τοὺς ἀπεσταλμένους πρὸς αὐτήν, ποσάκις ἠθέλησα ἐπισυνάξαι τὰ τέκνα σου, ὃν τρόπον ὄρνις τὴν ἑαυτῆς νοσσιὰν ὑπὸ τὰς πτέρυγας, καὶ οὐκ ἠθελήσατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 35, 'Ἰδοὺ, ἀφίεται ὑμῖν ὁ οἶκος ὑμῶν. Λέγω δὲ ὑμῖν, οὐ μὴ ἴδητέ με ἕως εἴπητε, ‘Εὐλογημένος ὁ ἐρχόμενος ἐν ὀνόματι  ̊Κυρίου.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 1, '¶Καὶ ἐγένετο ἐν τῷ ἐλθεῖν αὐτὸν εἰς οἶκόν τινος τῶν ἀρχόντων Φαρισαίων, Σαββάτῳ φαγεῖν ἄρτον, καὶ αὐτοὶ ἦσαν παρατηρούμενοι αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 2, 'Καὶ ἰδοὺ, ἄνθρωπός τις ἦν ὑδρωπικὸς ἔμπροσθεν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 3, 'Καὶ ἀποκριθεὶς ὁ  ̊Ἰησοῦς εἶπεν πρὸς τοὺς νομικοὺς καὶ Φαρισαίους λέγων, “Ἔξεστιν τῷ Σαββάτῳ θεραπεῦσαι ἢ οὔ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 4, 'Οἱ δὲ ἡσύχασαν. Καὶ ἐπιλαβόμενος, ἰάσατο αὐτὸν καὶ ἀπέλυσεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 5, 'Καὶ πρὸς αὐτοὺς εἶπεν, “Τίνος ὑμῶν υἱὸς ἢ βοῦς εἰς φρέαρ πεσεῖται, καὶ οὐκ εὐθέως ἀνασπάσει αὐτὸν ἐν ἡμέρᾳ τοῦ Σαββάτου;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 6, 'Καὶ οὐκ ἴσχυσαν ἀνταποκριθῆναι πρὸς ταῦτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 7, '¶Ἔλεγεν δὲ πρὸς τοὺς κεκλημένους παραβολήν, ἐπέχων πῶς τὰς πρωτοκλισίας ἐξελέγοντο, λέγων πρὸς αὐτούς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 8, '“Ὅταν κληθῇς ὑπό τινος εἰς γάμους, μὴ κατακλιθῇς εἰς τὴν πρωτοκλισίαν, μήποτε ἐντιμότερός σου ᾖ κεκλημένος ὑπʼ αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 9, 'καὶ ἐλθὼν, ὁ σὲ καὶ αὐτὸν καλέσας ἐρεῖ σοι, ‘Δὸς τούτῳ τόπον’, καὶ τότε ἄρξῃ μετὰ αἰσχύνης τὸν ἔσχατον τόπον κατέχειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 10, 'Ἀλλʼ ὅταν κληθῇς, πορευθεὶς ἀνάπεσε εἰς τὸν ἔσχατον τόπον, ἵνα ὅταν ἔλθῃ ὁ κεκληκώς σε ἐρεῖ σοι, ‘Φίλε, προσανάβηθι ἀνώτερον.’ Τότε ἔσται σοι δόξα ἐνώπιον πάντων τῶν συνανακειμένων σοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 11, 'Ὅτι πᾶς ὁ ὑψῶν ἑαυτὸν ταπεινωθήσεται, καὶ ὁ ταπεινῶν ἑαυτὸν ὑψωθήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 12, 'Ἔλεγεν δὲ καὶ τῷ κεκληκότι αὐτόν, “Ὅταν ποιῇς ἄριστον ἢ δεῖπνον, μὴ φώνει τοὺς φίλους σου, μηδὲ τοὺς ἀδελφούς σου, μηδὲ τοὺς συγγενεῖς σου, μηδὲ γείτονας πλουσίους, μήποτε καὶ αὐτοὶ ἀντικαλέσωσίν σε καὶ γένηται ἀνταπόδομά σοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 13, 'Ἀλλʼ ὅταν ποιῇς δοχὴν κάλει πτωχούς, ἀναπείρους, χωλούς, τυφλούς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 14, 'καὶ μακάριος ἔσῃ, ὅτι οὐκ ἔχουσιν ἀνταποδοῦναί σοι, ἀνταποδοθήσεται γάρ σοι ἐν τῇ ἀναστάσει τῶν δικαίων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 15, '¶Ἀκούσας δέ τις τῶν συνανακειμένων ταῦτα, εἶπεν αὐτῷ, “Μακάριος ὅστις φάγεται ἄρτον ἐν τῇ Βασιλείᾳ τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 16, 'Ὁ δὲ εἶπεν αὐτῷ, “Ἄνθρωπός τις ἐποίει δεῖπνον μέγα, καὶ ἐκάλεσεν πολλούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 17, 'Καὶ ἀπέστειλεν τὸν δοῦλον αὐτοῦ τῇ ὥρᾳ τοῦ δείπνου εἰπεῖν τοῖς κεκλημένοις, ‘Ἔρχεσθε, ὅτι ἤδη ἕτοιμά ἐστιν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 18, 'Καὶ ἤρξαντο ἀπὸ μιᾶς πάντες παραιτεῖσθαι. Ὁ πρῶτος εἶπεν αὐτῷ, ‘Ἀγρὸν ἠγόρασα καὶ ἔχω ἀνάγκην ἐξελθὼν ἰδεῖν αὐτόν· ἐρωτῶ σε ἔχε με παρῃτημένον.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 19, 'Καὶ ἕτερος εἶπεν, ‘Ζεύγη βοῶν ἠγόρασα πέντε καὶ πορεύομαι δοκιμάσαι αὐτά· ἐρωτῶ σε ἔχε με παρῃτημένον.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 20, 'Καὶ ἕτερος εἶπεν, ‘Γυναῖκα ἔγημα καὶ διὰ τοῦτο οὐ δύναμαι ἐλθεῖν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 21, 'Καὶ παραγενόμενος, ὁ δοῦλος ἀπήγγειλεν τῷ κυρίῳ αὐτοῦ ταῦτα. Τότε ὀργισθεὶς, ὁ οἰκοδεσπότης εἶπεν τῷ δούλῳ αὐτοῦ, ‘Ἔξελθε ταχέως εἰς τὰς πλατείας καὶ ῥύμας τῆς πόλεως, καὶ τοὺς πτωχοὺς, καὶ ἀναπείρους, καὶ τυφλοὺς, καὶ χωλοὺς, εἰσάγαγε ὧδε.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 22, 'Καὶ εἶπεν ὁ δοῦλος, ‘Κύριε, γέγονεν ὃ ἐπέταξας, καὶ ἔτι τόπος ἐστίν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 23, 'Καὶ εἶπεν ὁ κύριος πρὸς τὸν δοῦλον, ‘Ἔξελθε εἰς τὰς ὁδοὺς καὶ φραγμοὺς, καὶ ἀνάγκασον εἰσελθεῖν, ἵνα γεμισθῇ μου ὁ οἶκος·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 24, 'λέγω γὰρ ὑμῖν ὅτι οὐδεὶς τῶν ἀνδρῶν ἐκείνων τῶν κεκλημένων, γεύσεταί μου τοῦ δείπνου.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 25, '¶Συνεπορεύοντο δὲ αὐτῷ ὄχλοι πολλοί, καὶ στραφεὶς, εἶπεν πρὸς αὐτούς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 26, '“Εἴ τις ἔρχεται πρός με, καὶ οὐ μισεῖ τὸν πατέρα ἑαυτοῦ, καὶ τὴν μητέρα, καὶ τὴν γυναῖκα, καὶ τὰ τέκνα, καὶ τοὺς ἀδελφοὺς, καὶ τὰς ἀδελφάς, ἔτι δὲ καὶ τὴν ψυχὴν ἑαυτοῦ, οὐ δύναται μου εἶναι μαθητής.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 27, 'Ὅστις οὐ βαστάζει τὸν σταυρὸν αὐτοῦ καὶ ἔρχεται ὀπίσω μου, οὐ δύναται εἶναί μου μαθητής.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 28, 'Τίς γὰρ ἐξ ὑμῶν θέλων πύργον οἰκοδομῆσαι, οὐχὶ πρῶτον καθίσας, ψηφίζει τὴν δαπάνην, εἰ ἔχει εἰς ἀπαρτισμόν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 29, 'Ἵνα μήποτε θέντος αὐτοῦ θεμέλιον καὶ μὴ ἰσχύοντος ἐκτελέσαι, πάντες οἱ θεωροῦντες ἄρξωνται αὐτῷ ἐμπαίζειν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 30, 'λέγοντες, ὅτι ‘Οὗτος ὁ ἄνθρωπος ἤρξατο οἰκοδομεῖν, καὶ οὐκ ἴσχυσεν ἐκτελέσαι.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 31, 'Ἢ τίς βασιλεὺς πορευόμενος ἑτέρῳ βασιλεῖ συμβαλεῖν εἰς πόλεμον, οὐχὶ καθίσας πρῶτον βουλεύσεται εἰ δυνατός ἐστιν ἐν δέκα χιλιάσιν ὑπαντῆσαι τῷ μετὰ εἴκοσι χιλιάδων ἐρχομένῳ ἐπʼ αὐτόν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 32, 'Εἰ δὲ μή γε ἔτι αὐτοῦ πόρρω ὄντος, πρεσβείαν ἀποστείλας ἐρωτᾷ εἰρήνην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 33, 'Οὕτως οὖν πᾶς ἐξ ὑμῶν ὃς οὐκ ἀποτάσσεται πᾶσιν τοῖς ἑαυτοῦ ὑπάρχουσιν, οὐ δύναται εἶναί μου μαθητής.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 34, '¶Καλὸν οὖν τὸ ἅλας, ἐὰν δὲ τὸ ἅλας μωρανθῇ, ἐν τίνι ἀρτυθήσεται;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 35, 'Οὔτε εἰς γῆν οὔτε εἰς κοπρίαν εὔθετόν ἐστιν· ἔξω βάλλουσιν αὐτό. Ὁ ἔχων ὦτα ἀκούειν, ἀκουέτω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 1, '¶Ἦσαν δὲ αὐτῷ ἐγγίζοντες πάντες οἱ τελῶναι καὶ οἱ ἁμαρτωλοὶ ἀκούειν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 2, 'Καὶ διεγόγγυζον οἵ τε Φαρισαῖοι καὶ οἱ γραμματεῖς λέγοντες, ὅτι “Οὗτος ἁμαρτωλοὺς προσδέχεται καὶ συνεσθίει αὐτοῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 3, 'Εἶπεν δὲ πρὸς αὐτοὺς τὴν παραβολὴν ταύτην λέγων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 4, '“Τίς ἄνθρωπος ἐξ ὑμῶν, ἔχων ἑκατὸν πρόβατα καὶ ἀπολέσας ἐξ αὐτῶν ἓν, οὐ καταλείπει τὰ ἐνενήκοντα ἐννέα ἐν τῇ ἐρήμῳ, καὶ πορεύεται ἐπὶ τὸ ἀπολωλὸς, ἕως εὕρῃ αὐτό;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 5, 'Καὶ εὑρὼν, ἐπιτίθησιν ἐπὶ τοὺς ὤμους αὐτοῦ χαίρων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 6, 'Καὶ ἐλθὼν εἰς τὸν οἶκον, συγκαλεῖ τοὺς φίλους καὶ τοὺς γείτονας, λέγων αὐτοῖς, ‘Συγχάρητέ μοι, ὅτι εὗρον τὸ πρόβατόν μου τὸ ἀπολωλός!’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 7, 'Λέγω ὑμῖν ὅτι οὕτως χαρὰ ἐν τῷ οὐρανῷ ἔσται ἐπὶ ἑνὶ ἁμαρτωλῷ μετανοοῦντι, ἢ ἐπὶ ἐνενήκοντα ἐννέα δικαίοις, οἵτινες οὐ χρείαν ἔχουσιν μετανοίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 8, '¶Ἢ τίς γυνὴ δραχμὰς ἔχουσα δέκα, ἐὰν ἀπολέσῃ δραχμὴν μίαν, οὐχὶ ἅπτει λύχνον, καὶ σαροῖ τὴν οἰκίαν, καὶ ζητεῖ ἐπιμελῶς, ἕως οὗ εὕρῃ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 9, 'Καὶ εὑροῦσα, συγκαλεῖ τὰς φίλας καὶ γείτονας λέγουσα, ‘Συγχάρητέ μοι, ὅτι εὗρον τὴν δραχμὴν ἣν ἀπώλεσα.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 10, 'Οὕτως λέγω ὑμῖν, γίνεται χαρὰ ἐνώπιον τῶν ἀγγέλων τοῦ  ̊Θεοῦ ἐπὶ ἑνὶ ἁμαρτωλῷ μετανοοῦντι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 11, '¶Εἶπεν δέ, “Ἄνθρωπός τις εἶχεν δύο υἱούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 12, 'Καὶ εἶπεν ὁ νεώτερος αὐτῶν τῷ πατρί, ‘Πάτερ, δός μοι τὸ ἐπιβάλλον μέρος τῆς οὐσίας.’ ὁ δὲ διεῖλεν αὐτοῖς τὸν βίον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 13, 'Καὶ μετʼ οὐ πολλὰς ἡμέρας συναγαγὼν πάντα, ὁ νεώτερος υἱὸς ἀπεδήμησεν εἰς χώραν μακράν, καὶ ἐκεῖ διεσκόρπισεν τὴν οὐσίαν αὐτοῦ, ζῶν ἀσώτως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 14, 'Δαπανήσαντος δὲ αὐτοῦ πάντα, ἐγένετο λιμὸς ἰσχυρὰ κατὰ τὴν χώραν ἐκείνην, καὶ αὐτὸς ἤρξατο ὑστερεῖσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 15, 'Καὶ πορευθεὶς, ἐκολλήθη ἑνὶ τῶν πολιτῶν τῆς χώρας ἐκείνης, καὶ ἔπεμψεν αὐτὸν εἰς τοὺς ἀγροὺς αὐτοῦ βόσκειν χοίρους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 16, 'Καὶ ἐπεθύμει χορτασθῆναι ἐκ τῶν κερατίων ὧν ἤσθιον οἱ χοῖροι, καὶ οὐδεὶς ἐδίδου αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 17, 'Εἰς ἑαυτὸν δὲ ἐλθὼν ἔφη, ‘Πόσοι μίσθιοι τοῦ πατρός μου περισσεύονται ἄρτων, ἐγὼ δὲ λιμῷ ὧδε ἀπόλλυμαι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 18, 'Ἀναστὰς, πορεύσομαι πρὸς τὸν πατέρα μου, καὶ ἐρῶ αὐτῷ, “Πάτερ, ἥμαρτον εἰς τὸν οὐρανὸν καὶ ἐνώπιόν σου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 19, 'οὐκέτι εἰμὶ ἄξιος κληθῆναι υἱός σου. Ποίησόν με ὡς ἕνα τῶν μισθίων σου.”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 20, 'Καὶ ἀναστὰς, ἦλθεν πρὸς τὸν πατέρα ἑαυτοῦ. Ἔτι δὲ αὐτοῦ μακρὰν ἀπέχοντος, εἶδεν αὐτὸν ὁ πατὴρ αὐτοῦ, καὶ ἐσπλαγχνίσθη, καὶ δραμὼν, ἐπέπεσεν ἐπὶ τὸν τράχηλον αὐτοῦ καὶ κατεφίλησεν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 21, 'Εἶπεν δὲ ὁ υἱὸς αὐτῷ, ‘Πάτερ, ἥμαρτον εἰς τὸν οὐρανὸν καὶ ἐνώπιόν σου, οὐκέτι εἰμὶ ἄξιος κληθῆναι υἱός σου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 22, 'Εἶπεν δὲ ὁ πατὴρ πρὸς τοὺς δούλους αὐτοῦ, ‘Ταχὺ ἐξενέγκατε στολὴν τὴν πρώτην, καὶ ἐνδύσατε αὐτόν, καὶ δότε δακτύλιον εἰς τὴν χεῖρα αὐτοῦ, καὶ ὑποδήματα εἰς τοὺς πόδας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 23, 'καὶ φέρετε τὸν μόσχον τὸν σιτευτόν, θύσατε, καὶ φαγόντες εὐφρανθῶμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 24, 'Ὅτι οὗτος ὁ υἱός μου νεκρὸς ἦν καὶ ἀνέζησεν, ἦν ἀπολωλὼς καὶ εὑρέθη.’ Καὶ ἤρξαντο εὐφραίνεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 25, '¶Ἦν δὲ ὁ υἱὸς αὐτοῦ ὁ πρεσβύτερος ἐν ἀγρῷ· καὶ ὡς ἐρχόμενος, ἤγγισεν τῇ οἰκίᾳ, ἤκουσεν συμφωνίας καὶ χορῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 26, 'Καὶ προσκαλεσάμενος ἕνα τῶν παίδων, ἐπυνθάνετο τί ἂν εἴη ταῦτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 27, 'Ὁ δὲ εἶπεν αὐτῷ, ὅτι ‘Ὁ ἀδελφός σου ἥκει, καὶ ἔθυσεν ὁ πατήρ σου τὸν μόσχον τὸν σιτευτόν, ὅτι ὑγιαίνοντα αὐτὸν ἀπέλαβεν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 28, 'Ὠργίσθη δὲ καὶ οὐκ ἤθελεν εἰσελθεῖν. Ὁ δὲ πατὴρ αὐτοῦ ἐξελθὼν, παρεκάλει αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 29, 'Ὁ δὲ ἀποκριθεὶς εἶπεν τῷ πατρὶ αὐτοῦ, ‘Ἰδοὺ, τοσαῦτα ἔτη δουλεύω σοι, καὶ οὐδέποτε ἐντολήν σου παρῆλθον, καὶ ἐμοὶ οὐδέποτε ἔδωκας ἔριφον, ἵνα μετὰ τῶν φίλων μου εὐφρανθῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 30, 'Ὅτε δὲ ὁ υἱός σου οὗτος, ὁ καταφαγών σου τὸν βίον μετὰ πορνῶν ἦλθεν, ἔθυσας αὐτῷ τὸν σιτευτὸν μόσχον!’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 31, 'Ὁ δὲ εἶπεν αὐτῷ, ‘Τέκνον, σὺ πάντοτε μετʼ ἐμοῦ εἶ, καὶ πάντα τὰ ἐμὰ σά ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 32, 'Εὐφρανθῆναι δὲ καὶ χαρῆναι ἔδει, ὅτι ὁ ἀδελφός σου οὗτος, νεκρὸς ἦν καὶ ἔζησεν, καὶ ἀπολωλὼς καὶ εὑρέθη.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 1, '¶Ἔλεγεν δὲ καὶ πρὸς τοὺς μαθητάς, “Ἄνθρωπός τις ἦν πλούσιος, ὃς εἶχεν οἰκονόμον, καὶ οὗτος διεβλήθη αὐτῷ ὡς διασκορπίζων τὰ ὑπάρχοντα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 2, 'Καὶ φωνήσας αὐτὸν, εἶπεν αὐτῷ, ‘Τί τοῦτο ἀκούω περὶ σοῦ; Ἀπόδος τὸν λόγον τῆς οἰκονομίας σου, οὐ γὰρ δύνῃ ἔτι οἰκονομεῖν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 3, 'Εἶπεν δὲ ἐν ἑαυτῷ ὁ οἰκονόμος, ‘Τί ποιήσω, ὅτι ὁ κύριός μου ἀφαιρεῖται τὴν οἰκονομίαν ἀπʼ ἐμοῦ; Σκάπτειν οὐκ ἰσχύω, ἐπαιτεῖν αἰσχύνομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 4, 'Ἔγνων τί ποιήσω, ἵνα ὅταν μετασταθῶ ἐκ τῆς οἰκονομίας, δέξωνταί με εἰς τοὺς οἴκους αὐτῶν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 5, 'Καὶ προσκαλεσάμενος ἕνα ἕκαστον τῶν χρεοφειλετῶν τοῦ κυρίου ἑαυτοῦ, ἔλεγεν τῷ πρώτῳ, ‘Πόσον ὀφείλεις τῷ κυρίῳ μου;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 6, 'Ὁ δὲ εἶπεν, ‘Ἑκατὸν βάτους ἐλαίου.’ Ὁ δὲ εἶπεν αὐτῷ, ‘Δέξαι σου τὰ γράμματα καὶ καθίσας ταχέως γράψον πεντήκοντα.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 7, 'Ἔπειτα ἑτέρῳ εἶπεν, ‘Σὺ δὲ πόσον ὀφείλεις;’ Ὁ δὲ εἶπεν, ‘Ἑκατὸν κόρους σίτου.’ Λέγει αὐτῷ, ‘Δέξαι σου τὰ γράμματα καὶ γράψον ὀγδοήκοντα.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 8, 'Καὶ ἐπῄνεσεν ὁ κύριος τὸν οἰκονόμον τῆς ἀδικίας, ὅτι φρονίμως ἐποίησεν. Ὅτι οἱ υἱοὶ τοῦ αἰῶνος τούτου φρονιμώτεροι ὑπὲρ τοὺς υἱοὺς τοῦ φωτὸς εἰς τὴν γενεὰν τὴν ἑαυτῶν εἰσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 9, 'Καὶ ἐγὼ ὑμῖν λέγω, ἑαυτοῖς ποιήσατε φίλους ἐκ τοῦ μαμωνᾶ τῆς ἀδικίας, ἵνα ὅταν ἐκλίπῃ, δέξωνται ὑμᾶς εἰς τὰς αἰωνίους σκηνάς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 10, '¶Ὁ πιστὸς ἐν ἐλαχίστῳ, καὶ ἐν πολλῷ πιστός ἐστιν, καὶ ὁ ἐν ἐλαχίστῳ ἄδικος, καὶ ἐν πολλῷ ἄδικός ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 11, 'Εἰ οὖν ἐν τῷ ἀδίκῳ μαμωνᾷ, πιστοὶ οὐκ ἐγένεσθε, τὸ ἀληθινὸν τίς ὑμῖν πιστεύσει;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 12, 'Καὶ εἰ ἐν τῷ ἀλλοτρίῳ, πιστοὶ οὐκ ἐγένεσθε, τὸ ὑμέτερον τίς ὑμῖν δώσει;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 13, 'Οὐδεὶς οἰκέτης δύναται δυσὶ κυρίοις δουλεύειν, ἢ γὰρ τὸν ἕνα μισήσει, καὶ τὸν ἕτερον ἀγαπήσει, ἢ ἑνὸς ἀνθέξεται, καὶ τοῦ ἑτέρου καταφρονήσει. Οὐ δύνασθε  ̊Θεῷ δουλεύειν καὶ μαμωνᾷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 14, '¶Ἤκουον δὲ ταῦτα πάντα οἱ Φαρισαῖοι, φιλάργυροι ὑπάρχοντες, καὶ ἐξεμυκτήριζον αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 15, 'Καὶ εἶπεν αὐτοῖς, “Ὑμεῖς ἐστε οἱ δικαιοῦντες ἑαυτοὺς ἐνώπιον τῶν ἀνθρώπων, ὁ δὲ  ̊Θεὸς γινώσκει τὰς καρδίας ὑμῶν· ὅτι τὸ ἐν ἀνθρώποις ὑψηλὸν, βδέλυγμα ἐνώπιον τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 16, '¶Ὁ νόμος καὶ οἱ προφῆται μέχρι Ἰωάννου· ἀπὸ τότε ἡ Βασιλεία τοῦ  ̊Θεοῦ εὐαγγελίζεται, καὶ πᾶς εἰς αὐτὴν βιάζεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 17, 'Εὐκοπώτερον δέ ἐστιν τὸν οὐρανὸν καὶ τὴν γῆν παρελθεῖν, ἢ τοῦ νόμου μίαν κεραίαν πεσεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 18, '¶Πᾶς ὁ ἀπολύων τὴν γυναῖκα αὐτοῦ καὶ γαμῶν ἑτέραν, μοιχεύει, καὶ πᾶς ὁ ἀπολελυμένην ἀπὸ ἀνδρὸς γαμῶν, μοιχεύει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 19, '¶Ἄνθρωπος δέ τις ἦν πλούσιος, καὶ ἐνεδιδύσκετο πορφύραν καὶ βύσσον, εὐφραινόμενος καθʼ ἡμέραν λαμπρῶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 20, 'Πτωχὸς δέ τις ὀνόματι Λάζαρος, ἐβέβλητο πρὸς τὸν πυλῶνα αὐτοῦ, εἱλκωμένος');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 21, 'καὶ ἐπιθυμῶν χορτασθῆναι ἀπὸ τῶν πιπτόντων ἀπὸ τῆς τραπέζης τοῦ πλουσίου· ἀλλὰ καὶ οἱ κύνες ἐρχόμενοι ἐπέλειχον τὰ ἕλκη αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 22, 'Ἐγένετο δὲ ἀποθανεῖν τὸν πτωχὸν, καὶ ἀπενεχθῆναι αὐτὸν ὑπὸ τῶν ἀγγέλων εἰς τὸν κόλπον Ἀβραάμ. Ἀπέθανεν δὲ καὶ ὁ πλούσιος καὶ ἐτάφη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 23, 'Καὶ ἐν τῷ ἍΙδῃ ἐπάρας τοὺς ὀφθαλμοὺς αὐτοῦ, ὑπάρχων ἐν βασάνοις, ὁρᾷ Ἀβραὰμ ἀπὸ μακρόθεν, καὶ Λάζαρον ἐν τοῖς κόλποις αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 24, 'Καὶ αὐτὸς φωνήσας εἶπεν, Πάτερ ‘Ἀβραάμ, ἐλέησόν με καὶ πέμψον Λάζαρον, ἵνα βάψῃ τὸ ἄκρον τοῦ δακτύλου αὐτοῦ ὕδατος, καὶ καταψύξῃ τὴν γλῶσσάν μου, ὅτι ὀδυνῶμαι ἐν τῇ φλογὶ ταύτῃ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 25, 'Εἶπεν δὲ Ἀβραάμ, ‘Τέκνον, μνήσθητι ὅτι ἀπέλαβες τὰ ἀγαθά σου ἐν τῇ ζωῇ σου, καὶ Λάζαρος ὁμοίως τὰ κακά. Νῦν δὲ ὧδε παρακαλεῖται, σὺ δὲ ὀδυνᾶσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 26, 'Καὶ ἐν πᾶσι τούτοις, μεταξὺ ἡμῶν καὶ ὑμῶν χάσμα μέγα ἐστήρικται, ὅπως οἱ θέλοντες διαβῆναι ἔνθεν πρὸς ὑμᾶς μὴ δύνωνται, μηδὲ ἐκεῖθεν πρὸς ἡμᾶς διαπερῶσιν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 27, 'Εἶπεν δέ, ‘Ἐρωτῶ σε οὖν Πάτερ, ἵνα πέμψῃς αὐτὸν εἰς τὸν οἶκον τοῦ πατρός μου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 28, 'ἔχω γὰρ πέντε ἀδελφούς, ὅπως διαμαρτύρηται αὐτοῖς, ἵνα μὴ καὶ αὐτοὶ ἔλθωσιν εἰς τὸν τόπον τοῦτον τῆς βασάνου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 29, 'Λέγει δὲ Ἀβραάμ, ‘Ἔχουσι Μωϋσέα καὶ τοὺς προφήτας· ἀκουσάτωσαν αὐτῶν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 30, 'Ὁ δὲ εἶπεν, ‘Οὐχί, Πάτερ Ἀβραάμ, ἀλλʼ ἐάν τις ἀπὸ νεκρῶν πορευθῇ πρὸς αὐτοὺς, μετανοήσουσιν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 31, 'Εἶπεν δὲ αὐτῷ, ‘Εἰ Μωϋσέως καὶ τῶν προφητῶν οὐκ ἀκούουσιν, οὐδʼ ἐάν τις ἐκ νεκρῶν ἀναστῇ, πεισθήσονται.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 1, '¶Εἶπεν δὲ πρὸς τοὺς μαθητὰς αὐτοῦ, “Ἀνένδεκτόν ἐστιν τοῦ τὰ σκάνδαλα μὴ ἐλθεῖν, πλὴν οὐαὶ διʼ οὗ ἔρχεται!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 2, 'Λυσιτελεῖ αὐτῷ εἰ λίθος μυλικὸς περίκειται περὶ τὸν τράχηλον αὐτοῦ, καὶ ἔρριπται εἰς τὴν θάλασσαν, ἢ ἵνα σκανδαλίσῃ τῶν μικρῶν τούτων ἕνα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 3, 'Προσέχετε ἑαυτοῖς! Ἐὰν ἁμάρτῃ ὁ ἀδελφός σου, ἐπιτίμησον αὐτῷ, καὶ ἐὰν μετανοήσῃ, ἄφες αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 4, 'Καὶ ἐὰν ἑπτάκις τῆς ἡμέρας ἁμαρτήσῃ εἰς σὲ, καὶ ἑπτάκις ἐπιστρέψῃ πρὸς σὲ, λέγων ‘Μετανοῶ’, ἀφήσεις αὐτῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 5, '¶Καὶ εἶπαν οἱ ἀπόστολοι τῷ  ̊Κυρίῳ, “Πρόσθες ἡμῖν πίστιν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 6, 'Εἶπεν δὲ ὁ  ̊Κύριος, “Εἰ ἔχετε πίστιν ὡς κόκκον σινάπεως, ἐλέγετε ἂν τῇ συκαμίνῳ ταύτῃ, ‘Ἐκριζώθητι καὶ φυτεύθητι ἐν τῇ θαλάσσῃ’, καὶ ὑπήκουσεν ἂν ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 7, '¶Τίς δὲ ἐξ ὑμῶν δοῦλον ἔχων, ἀροτριῶντα ἢ ποιμαίνοντα, ὃς εἰσελθόντι ἐκ τοῦ ἀγροῦ ἐρεῖ αὐτῷ, ‘Εὐθέως παρελθὼν ἀνάπεσε’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 8, 'Ἀλλʼ οὐχὶ ἐρεῖ αὐτῷ, ‘Ἑτοίμασον τί δειπνήσω, καὶ περιζωσάμενος διακόνει μοι, ἕως φάγω καὶ πίω, καὶ μετὰ ταῦτα φάγεσαι καὶ πίεσαι σύ’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 9, 'Μὴ ἔχει χάριν τῷ δούλῳ, ὅτι ἐποίησεν τὰ διαταχθέντα;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 10, 'Οὕτως καὶ ὑμεῖς ὅταν ποιήσητε πάντα τὰ διαταχθέντα ὑμῖν, λέγετε, ὅτι ‘Δοῦλοι ἀχρεῖοί ἐσμεν, ὃ ὠφείλομεν ποιῆσαι πεποιήκαμεν.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 11, '¶Καὶ ἐγένετο ἐν τῷ πορεύεσθαι εἰς Ἰερουσαλὴμ, καὶ αὐτὸς διήρχετο διὰ μέσον Σαμαρείας καὶ Γαλιλαίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 12, 'Καὶ εἰσερχομένου αὐτοῦ εἴς τινα κώμην, ἀπήντησαν δέκα λεπροὶ ἄνδρες, οἳ ἔστησαν πόρρωθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 13, 'Καὶ αὐτοὶ ἦραν φωνὴν λέγοντες, “ ̊Ἰησοῦ, Ἐπιστάτα, ἐλέησον ἡμᾶς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 14, 'Καὶ ἰδὼν, εἶπεν αὐτοῖς, “Πορευθέντες ἐπιδείξατε ἑαυτοὺς τοῖς ἱερεῦσιν.” Καὶ ἐγένετο ἐν τῷ ὑπάγειν αὐτοὺς, ἐκαθαρίσθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 15, 'Εἷς δὲ ἐξ αὐτῶν ἰδὼν ὅτι ἰάθη, ὑπέστρεψεν μετὰ φωνῆς μεγάλης δοξάζων τὸν  ̊Θεόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 16, 'καὶ ἔπεσεν ἐπὶ πρόσωπον παρὰ τοὺς πόδας αὐτοῦ, εὐχαριστῶν αὐτῷ· καὶ αὐτὸς ἦν Σαμαρείτης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 17, 'Ἀποκριθεὶς δὲ ὁ  ̊Ἰησοῦς εἶπεν, “Οὐχ οἱ δέκα ἐκαθαρίσθησαν; Οἱ δὲ ἐννέα ποῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 18, 'Οὐχ εὑρέθησαν ὑποστρέψαντες δοῦναι δόξαν τῷ  ̊Θεῷ, εἰ μὴ ὁ ἀλλογενὴς οὗτος;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 19, 'Καὶ εἶπεν αὐτῷ, “Ἀναστὰς, πορεύου· ἡ πίστις σου σέσωκέν σε!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 20, '¶Ἐπερωτηθεὶς δὲ ὑπὸ τῶν Φαρισαίων πότε ἔρχεται ἡ Βασιλεία τοῦ  ̊Θεοῦ, ἀπεκρίθη αὐτοῖς καὶ εἶπεν, “Οὐκ ἔρχεται ἡ Βασιλεία τοῦ  ̊Θεοῦ μετὰ παρατηρήσεως,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 21, 'οὐδὲ ἐροῦσιν, ‘Ἰδοὺ, ὧδε’, ἤ, ‘Ἐκεῖ’. Ἰδοὺ γὰρ, ἡ Βασιλεία τοῦ  ̊Θεοῦ ἐντὸς ὑμῶν ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 22, '¶Εἶπεν δὲ πρὸς τοὺς μαθητάς, “Ἐλεύσονται ἡμέραι ὅτε ἐπιθυμήσετε μίαν τῶν ἡμερῶν τοῦ Υἱοῦ τοῦ Ἀνθρώπου ἰδεῖν, καὶ οὐκ ὄψεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 23, 'Καὶ ἐροῦσιν ὑμῖν, ‘Ἰδοὺ, ἐκεῖ’, ἤ, ‘Ἰδοὺ, ὧδε’· μὴ ἀπέλθητε μηδὲ διώξητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 24, 'Ὥσπερ γὰρ ἡ ἀστραπὴ ἀστράπτουσα ἐκ τῆς ὑπὸ τὸν οὐρανὸν εἰς τὴν ὑπʼ οὐρανὸν λάμπει, οὕτως ἔσται ὁ Υἱὸς τοῦ Ἀνθρώπου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 25, 'Πρῶτον δὲ δεῖ αὐτὸν πολλὰ παθεῖν, καὶ ἀποδοκιμασθῆναι ἀπὸ τῆς γενεᾶς ταύτης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 26, 'Καὶ καθὼς ἐγένετο ἐν ταῖς ἡμέραις Νῶε, οὕτως ἔσται καὶ ἐν ταῖς ἡμέραις τοῦ Υἱοῦ τοῦ Ἀνθρώπου:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 27, 'ἤσθιον, ἔπινον, ἐγάμουν, ἐγαμίζοντο, ἄχρι ἧς ἡμέρας εἰσῆλθεν Νῶε εἰς τὴν κιβωτόν, καὶ ἦλθεν ὁ κατακλυσμὸς καὶ ἀπώλεσεν πάντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 28, 'Ὁμοίως καθὼς ἐγένετο ἐν ταῖς ἡμέραις Λώτ: ἤσθιον, ἔπινον, ἠγόραζον, ἐπώλουν, ἐφύτευον, ᾠκοδόμουν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 29, 'ᾗ δὲ ἡμέρᾳ ἐξῆλθεν Λὼτ ἀπὸ Σοδόμων, ἔβρεξεν πῦρ καὶ θεῖον ἀπʼ οὐρανοῦ καὶ ἀπώλεσεν πάντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 30, 'Κατὰ ταῦτα ἔσται ᾗ ἡμέρᾳ, ὁ Υἱὸς τοῦ Ἀνθρώπου ἀποκαλύπτεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 31, 'Ἐν ἐκείνῃ τῇ ἡμέρᾳ, ὃς ἔσται ἐπὶ τοῦ δώματος, καὶ τὰ σκεύη αὐτοῦ ἐν τῇ οἰκίᾳ, μὴ καταβάτω ἆραι αὐτά, καὶ ὁ ἐν ἀγρῷ, ὁμοίως μὴ ἐπιστρεψάτω εἰς τὰ ὀπίσω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 32, 'Μνημονεύετε τῆς γυναικὸς Λώτ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 33, 'Ὃς ἐὰν ζητήσῃ τὴν ψυχὴν αὐτοῦ περιποιήσασθαι, ἀπολέσει αὐτήν, ὃς δʼ ἂν ἀπολέσῃ, ζῳογονήσει αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 34, 'Λέγω ὑμῖν, ταύτῃ τῇ νυκτὶ ἔσονται δύο ἐπὶ κλίνης μιᾶς, ὁ εἷς παραλημφθήσεται, καὶ ὁ ἕτερος ἀφεθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 35, 'Ἔσονται δύο ἀλήθουσαι ἐπὶ τὸ αὐτό, ἡ μία παραλημφθήσεται, ἡ δὲ ἑτέρα ἀφεθήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 36, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 37, 'Καὶ ἀποκριθέντες λέγουσιν αὐτῷ, “Ποῦ,  ̊Κύριε;” Ὁ δὲ εἶπεν αὐτοῖς, “Ὅπου τὸ σῶμα, ἐκεῖ καὶ οἱ ἀετοὶ ἐπισυναχθήσονται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 1, '¶Ἔλεγεν δὲ παραβολὴν αὐτοῖς, πρὸς τὸ δεῖν πάντοτε προσεύχεσθαι αὐτοὺς καὶ μὴ ἐγκακεῖν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 2, 'λέγων, “Κριτής τις ἦν ἔν τινι πόλει, τὸν  ̊Θεὸν μὴ φοβούμενος καὶ ἄνθρωπον μὴ ἐντρεπόμενος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 3, 'Χήρα δὲ ἦν ἐν τῇ πόλει ἐκείνῃ, καὶ ἤρχετο πρὸς αὐτὸν λέγουσα, ‘Ἐκδίκησόν με ἀπὸ τοῦ ἀντιδίκου μου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 4, 'Καὶ οὐκ ἤθελεν ἐπὶ χρόνον, μετὰ ταῦτα δὲ εἶπεν ἐν ἑαυτῷ, ‘Εἰ καὶ τὸν  ̊Θεὸν οὐ φοβοῦμαι οὐδὲ ἄνθρωπον ἐντρέπομαι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 5, 'διά γε τὸ παρέχειν μοι κόπον τὴν χήραν ταύτην, ἐκδικήσω αὐτήν, ἵνα μὴ εἰς τέλος ἐρχομένη ὑπωπιάζῃ με.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 6, 'Εἶπεν δὲ ὁ  ̊Κύριος, “Ἀκούσατε τί ὁ κριτὴς τῆς ἀδικίας λέγει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 7, 'Ὁ δὲ  ̊Θεὸς οὐ μὴ ποιήσῃ τὴν ἐκδίκησιν τῶν ἐκλεκτῶν αὐτοῦ, τῶν βοώντων αὐτῷ ἡμέρας καὶ νυκτός, καὶ μακροθυμεῖ ἐπʼ αὐτοῖς;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 8, 'Λέγω ὑμῖν ὅτι ποιήσει τὴν ἐκδίκησιν αὐτῶν ἐν τάχει. Πλὴν ὁ Υἱὸς τοῦ Ἀνθρώπου ἐλθὼν, ἆρα εὑρήσει τὴν πίστιν ἐπὶ τῆς γῆς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 9, '¶Εἶπεν δὲ καὶ πρός τινας τοὺς πεποιθότας ἐφʼ ἑαυτοῖς ὅτι εἰσὶν δίκαιοι καὶ ἐξουθενοῦντες τοὺς λοιποὺς, τὴν παραβολὴν ταύτην:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 10, '“Ἄνθρωποι δύο ἀνέβησαν εἰς τὸ ἱερὸν προσεύξασθαι, ὁ εἷς Φαρισαῖος, καὶ ὁ ἕτερος τελώνης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 11, 'Ὁ Φαρισαῖος σταθεὶς ταῦτα πρὸς ἑαυτὸν προσηύχετο: ‘Ὁ  ̊Θεός, εὐχαριστῶ σοι ὅτι οὐκ εἰμὶ ὥσπερ οἱ λοιποὶ τῶν ἀνθρώπων, ἅρπαγες, ἄδικοι, μοιχοί, ἢ καὶ ὡς οὗτος ὁ τελώνης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 12, 'Νηστεύω δὶς τοῦ σαββάτου, ἀποδεκατεύω πάντα, ὅσα κτῶμαι.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 13, 'Ὁ δὲ τελώνης μακρόθεν ἑστὼς, οὐκ ἤθελεν οὐδὲ τοὺς ὀφθαλμοὺς ἐπᾶραι εἰς τὸν οὐρανόν, ἀλλʼ ἔτυπτεν τὸ στῆθος αὐτοῦ λέγων, ‘Ὁ  ̊Θεός, ἱλάσθητί μοι, τῷ ἁμαρτωλῷ!’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 14, 'Λέγω ὑμῖν, κατέβη οὗτος δεδικαιωμένος εἰς τὸν οἶκον αὐτοῦ, παρʼ ἐκεῖνον. Ὅτι πᾶς ὁ ὑψῶν ἑαυτὸν ταπεινωθήσεται, ὁ δὲ ταπεινῶν ἑαυτὸν ὑψωθήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 15, '¶Προσέφερον δὲ αὐτῷ καὶ τὰ βρέφη, ἵνα αὐτῶν ἅπτηται· ἰδόντες δὲ, οἱ μαθηταὶ ἐπετίμων αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 16, 'Ὁ δὲ  ̊Ἰησοῦς προσεκαλέσατο αὐτὰ λέγων, “Ἄφετε τὰ παιδία ἔρχεσθαι πρός με, καὶ μὴ κωλύετε αὐτά, τῶν γὰρ τοιούτων ἐστὶν ἡ Βασιλεία τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 17, 'Ἀμὴν, λέγω ὑμῖν, ὃς ἂν μὴ δέξηται τὴν Βασιλείαν τοῦ  ̊Θεοῦ ὡς παιδίον, οὐ μὴ εἰσέλθῃ εἰς αὐτήν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 18, '¶Καὶ ἐπηρώτησέν τις αὐτὸν ἄρχων λέγων, “Διδάσκαλε ἀγαθέ, τί ποιήσας, ζωὴν αἰώνιον κληρονομήσω;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 19, 'Εἶπεν δὲ αὐτῷ ὁ  ̊Ἰησοῦς, “Τί με λέγεις ἀγαθόν; Οὐδεὶς ἀγαθὸς, εἰ μὴ εἷς ὁ  ̊Θεός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 20, 'Τὰς ἐντολὰς οἶδας: ‘Μὴ μοιχεύσῃς, μὴ φονεύσῃς, μὴ κλέψῃς, μὴ ψευδομαρτυρήσῃς’, ‘Τίμα τὸν πατέρα σου καὶ τὴν μητέρα.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 21, 'Ὁ δὲ εἶπεν, “Ταῦτα πάντα ἐφύλαξα ἐκ νεότητος μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 22, 'Ἀκούσας δὲ, ὁ  ̊Ἰησοῦς εἶπεν αὐτῷ, “Ἔτι ἕν σοι λείπει· πάντα ὅσα ἔχεις, πώλησον καὶ διάδος πτωχοῖς, καὶ ἕξεις θησαυρὸν ἐν οὐρανοῖς, καὶ δεῦρο, ἀκολούθει μοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 23, 'Ὁ δὲ ἀκούσας ταῦτα, περίλυπος ἐγενήθη, ἦν γὰρ πλούσιος σφόδρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 24, 'Ἰδὼν δὲ αὐτὸν ὁ  ̊Ἰησοῦς εἶπεν, “Πῶς δυσκόλως οἱ τὰ χρήματα ἔχοντες, εἰς τὴν Βασιλείαν τοῦ  ̊Θεοῦ εἰσελεύσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 25, 'Εὐκοπώτερον γάρ ἐστιν κάμηλον διὰ τρήματος βελόνης εἰσελθεῖν, ἢ πλούσιον εἰς τὴν Βασιλείαν τοῦ  ̊Θεοῦ εἰσελθεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 26, 'Εἶπον δὲ οἱ ἀκούσαντες, “Καὶ τίς δύναται σωθῆναι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 27, 'Ὁ δὲ εἶπεν, “Τὰ ἀδύνατα παρὰ ἀνθρώποις, δυνατὰ παρὰ τῷ  ̊Θεῷ ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 28, '¶Εἶπεν δὲ ὁ Πέτρος, “Ἰδοὺ, ἡμεῖς ἀφήκαμεν πάντα καὶ ἠκολουθήσαμέν σοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 29, 'Ὁ δὲ εἶπεν αὐτοῖς, “Ἀμὴν, λέγω ὑμῖν ὅτι οὐδείς ἐστιν ὃς ἀφῆκεν οἰκίαν, ἢ γυναῖκα, ἢ ἀδελφοὺς, ἢ γονεῖς, ἢ τέκνα, εἵνεκεν τῆς Βασιλείας τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 30, 'ὃς οὐχὶ μὴ ἀπολάβῃ πολλαπλασίονα ἐν τῷ καιρῷ τούτῳ, καὶ ἐν τῷ αἰῶνι τῷ ἐρχομένῳ, ζωὴν αἰώνιον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 31, '¶Παραλαβὼν δὲ τοὺς δώδεκα, εἶπεν πρὸς αὐτούς, “Ἰδοὺ, ἀναβαίνομεν εἰς Ἰερουσαλήμ, καὶ τελεσθήσεται πάντα τὰ γεγραμμένα διὰ τῶν προφητῶν τῷ Υἱῷ τοῦ Ἀνθρώπου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 32, 'Παραδοθήσεται γὰρ τοῖς ἔθνεσιν, καὶ ἐμπαιχθήσεται, καὶ ὑβρισθήσεται, καὶ ἐμπτυσθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 33, 'Καὶ μαστιγώσαντες, ἀποκτενοῦσιν αὐτόν, καὶ τῇ ἡμέρᾳ τῇ τρίτῃ, ἀναστήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 34, 'Καὶ αὐτοὶ οὐδὲν τούτων συνῆκαν, καὶ ἦν τὸ ῥῆμα τοῦτο κεκρυμμένον ἀπʼ αὐτῶν, καὶ οὐκ ἐγίνωσκον τὰ λεγόμενα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 35, '¶Ἐγένετο δὲ ἐν τῷ ἐγγίζειν αὐτὸν εἰς Ἰεριχὼ, τυφλός τις ἐκάθητο παρὰ τὴν ὁδὸν ἐπαιτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 36, 'Ἀκούσας δὲ ὄχλου διαπορευομένου, ἐπυνθάνετο τί εἴη τοῦτο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 37, 'Ἀπήγγειλαν δὲ αὐτῷ, ὅτι “ ̊Ἰησοῦς ὁ Ναζωραῖος παρέρχεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 38, 'Καὶ ἐβόησεν λέγων, “ ̊Ἰησοῦ, Υἱὲ Δαυίδ, ἐλέησόν με.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 39, 'Καὶ οἱ προάγοντες ἐπετίμων αὐτῷ ἵνα σιγήσῃ. Αὐτὸς δὲ πολλῷ μᾶλλον ἔκραζεν, “Υἱὲ Δαυίδ, ἐλέησόν με.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 40, 'Σταθεὶς δὲ,  ̊Ἰησοῦς ἐκέλευσεν αὐτὸν ἀχθῆναι πρὸς αὐτόν. Ἐγγίσαντος δὲ αὐτοῦ, ἐπηρώτησεν αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 41, '“Τί σοι θέλεις ποιήσω;” Ὁ δὲ εἶπεν, “ ̊Κύριε, ἵνα ἀναβλέψω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 42, 'Καὶ ὁ  ̊Ἰησοῦς εἶπεν αὐτῷ, “Ἀνάβλεψον· ἡ πίστις σου σέσωκέν σε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 43, 'Καὶ παραχρῆμα ἀνέβλεψεν, καὶ ἠκολούθει αὐτῷ, δοξάζων τὸν  ̊Θεόν. Καὶ πᾶς ὁ λαὸς ἰδὼν, ἔδωκεν αἶνον τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 1, '¶Καὶ εἰσελθὼν, διήρχετο τὴν Ἰεριχώ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 2, 'Καὶ ἰδοὺ, ἀνὴρ ὀνόματι καλούμενος Ζακχαῖος, καὶ αὐτὸς ἦν ἀρχιτελώνης, καὶ αὐτὸς πλούσιος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 3, 'Καὶ ἐζήτει ἰδεῖν τὸν  ̊Ἰησοῦν τίς ἐστιν, καὶ οὐκ ἠδύνατο ἀπὸ τοῦ ὄχλου, ὅτι τῇ ἡλικίᾳ μικρὸς ἦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 4, 'Καὶ προδραμὼν ἔμπροσθεν, ἀνέβη ἐπὶ συκομορέαν, ἵνα ἴδῃ αὐτόν, ὅτι ἐκείνης ἤμελλεν διέρχεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 5, 'Καὶ ὡς ἦλθεν ἐπὶ τὸν τόπον, ἀναβλέψας, ὁ  ̊Ἰησοῦς εἶπεν πρὸς αὐτόν, “Ζακχαῖε, σπεύσας κατάβηθι, σήμερον γὰρ ἐν τῷ οἴκῳ σου δεῖ με μεῖναι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 6, 'Καὶ σπεύσας, κατέβη καὶ ὑπεδέξατο αὐτὸν χαίρων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 7, 'Καὶ ἰδόντες, πάντες διεγόγγυζον λέγοντες, ὅτι “Παρὰ ἁμαρτωλῷ ἀνδρὶ εἰσῆλθεν καταλῦσαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 8, 'Σταθεὶς δὲ, Ζακχαῖος εἶπεν πρὸς τὸν  ̊Κύριον, “Ἰδοὺ, τὰ ἡμίσιά μου τῶν ὑπαρχόντων,  ̊Κύριε, τοῖς πτωχοῖς δίδωμι, καὶ εἴ τινός τι ἐσυκοφάντησα, ἀποδίδωμι τετραπλοῦν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 9, 'Εἶπεν δὲ πρὸς αὐτὸν ὁ  ̊Ἰησοῦς, ὅτι “Σήμερον σωτηρία τῷ οἴκῳ τούτῳ ἐγένετο, καθότι καὶ αὐτὸς υἱὸς Ἀβραάμ ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 10, 'Ἦλθεν γὰρ ὁ Υἱὸς τοῦ Ἀνθρώπου ζητῆσαι καὶ σῶσαι τὸ ἀπολωλός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 11, '¶Ἀκουόντων δὲ αὐτῶν ταῦτα προσθεὶς, εἶπεν παραβολὴν διὰ τὸ ἐγγὺς εἶναι Ἰερουσαλὴμ αὐτὸν, καὶ δοκεῖν αὐτοὺς ὅτι παραχρῆμα μέλλει ἡ Βασιλεία τοῦ  ̊Θεοῦ ἀναφαίνεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 12, 'Εἶπεν οὖν, “Ἄνθρωπός τις εὐγενὴς ἐπορεύθη εἰς χώραν μακρὰν, λαβεῖν ἑαυτῷ βασιλείαν καὶ ὑποστρέψαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 13, 'Καλέσας δὲ δέκα δούλους ἑαυτοῦ, ἔδωκεν αὐτοῖς δέκα μνᾶς, καὶ εἶπεν πρὸς αὐτούς, ‘Πραγματεύσασθαι ἐν ᾧ ἔρχομαι.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 14, 'Οἱ δὲ πολῖται αὐτοῦ ἐμίσουν αὐτόν, καὶ ἀπέστειλαν πρεσβείαν ὀπίσω αὐτοῦ λέγοντες, ‘Οὐ θέλομεν τοῦτον βασιλεῦσαι ἐφʼ ἡμᾶς.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 15, 'Καὶ ἐγένετο ἐν τῷ ἐπανελθεῖν αὐτὸν, λαβόντα τὴν βασιλείαν, καὶ εἶπεν φωνηθῆναι αὐτῷ τοὺς δούλους τούτους οἷς δεδώκει τὸ ἀργύριον, ἵνα γνοῖ τί διεπραγματεύσαντο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 16, 'Παρεγένετο δὲ ὁ πρῶτος λέγων, ‘Κύριε, ἡ μνᾶ σου, δέκα προσηργάσατο μνᾶς.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 17, 'Καὶ εἶπεν αὐτῷ, ‘Εὖ ἀγαθὲ δοῦλε! Ὅτι ἐν ἐλαχίστῳ, πιστὸς ἐγένου, ἴσθι ἐξουσίαν ἔχων ἐπάνω δέκα πόλεων.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 18, 'Καὶ ἦλθεν ὁ δεύτερος λέγων, ‘Ἡ μνᾶ σου, Κύριε, ἐποίησεν πέντε μνᾶς.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 19, 'Εἶπεν δὲ καὶ τούτῳ, ‘Καὶ σὺ ἐπάνω γίνου πέντε πόλεων.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 20, 'Καὶ ὁ ἕτερος ἦλθεν λέγων, ‘Κύριε, ἰδοὺ, ἡ μνᾶ σου, ἣν εἶχον ἀποκειμένην ἐν σουδαρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 21, 'Ἐφοβούμην γάρ σε, ὅτι ἄνθρωπος αὐστηρὸς εἶ, αἴρεις ὃ οὐκ ἔθηκας, καὶ θερίζεις ὃ οὐκ ἔσπειρας.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 22, 'Λέγει αὐτῷ, ‘Ἐκ τοῦ στόματός σου κρίνω σε, πονηρὲ δοῦλε. ἬΙδεις ὅτι ἐγὼ ἄνθρωπος αὐστηρός εἰμι, αἴρων ὃ οὐκ ἔθηκα, καὶ θερίζων ὃ οὐκ ἔσπειρα;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 23, 'Καὶ διὰ τί οὐκ ἔδωκάς μου τὸ ἀργύριον ἐπὶ τράπεζαν, κἀγὼ ἐλθὼν, σὺν τόκῳ ἂν αὐτὸ ἔπραξα;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 24, 'Καὶ τοῖς παρεστῶσιν εἶπεν, ‘Ἄρατε ἀπʼ αὐτοῦ τὴν μνᾶν, καὶ δότε τῷ, τὰς δέκα μνᾶς ἔχοντι.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 25, 'Καὶ εἶπαν αὐτῷ, ‘Κύριε, ἔχει δέκα μνᾶς.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 26, 'Λέγω ὑμῖν ὅτι παντὶ τῷ ἔχοντι, δοθήσεται, ἀπὸ δὲ τοῦ μὴ ἔχοντος, καὶ ὃ ἔχει ἀρθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 27, 'Πλὴν τοὺς ἐχθρούς μου τούτους, τοὺς μὴ θελήσαντάς με βασιλεῦσαι ἐπʼ αὐτοὺς, ἀγάγετε ὧδε καὶ κατασφάξατε αὐτοὺς ἔμπροσθέν μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 28, '¶Καὶ εἰπὼν ταῦτα ἐπορεύετο ἔμπροσθεν ἀναβαίνων εἰς Ἱεροσόλυμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 29, '¶Καὶ ἐγένετο ὡς ἤγγισεν εἰς Βηθφαγὴ καὶ Βηθανιὰ, πρὸς τὸ ὄρος τὸ καλούμενον Ἐλαιῶν, ἀπέστειλεν δύο τῶν μαθητῶν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 30, 'λέγων, “Ὑπάγετε εἰς τὴν κατέναντι κώμην, ἐν ᾗ εἰσπορευόμενοι εὑρήσετε πῶλον δεδεμένον, ἐφʼ ὃν οὐδεὶς πώποτε ἀνθρώπων ἐκάθισεν, καὶ λύσαντες αὐτὸν, ἀγάγετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 31, 'Καὶ ἐάν τις ὑμᾶς ἐρωτᾷ, ‘Διὰ τί λύετε;’ Οὕτως ἐρεῖτε, ὅτι ‘Ὁ  ̊Κύριος αὐτοῦ χρείαν ἔχει.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 32, 'Ἀπελθόντες δὲ οἱ ἀπεσταλμένοι εὗρον καθὼς εἶπεν αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 33, 'Λυόντων δὲ αὐτῶν τὸν πῶλον, εἶπαν οἱ κύριοι αὐτοῦ πρὸς αὐτούς, “Τί λύετε τὸν πῶλον;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 34, 'Οἱ δὲ εἶπαν, ὅτι “Ὁ  ̊Κύριος αὐτοῦ χρείαν ἔχει.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 35, 'Καὶ ἤγαγον αὐτὸν πρὸς τὸν  ̊Ἰησοῦν, καὶ ἐπιρίψαντες αὐτῶν τὰ ἱμάτια ἐπὶ τὸν πῶλον, ἐπεβίβασαν τὸν  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 36, 'Πορευομένου δὲ αὐτοῦ, ὑπεστρώννυον τὰ ἱμάτια ἑαυτῶν ἐν τῇ ὁδῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 37, 'Ἐγγίζοντος δὲ αὐτοῦ ἤδη πρὸς τῇ καταβάσει τοῦ Ὄρους τῶν Ἐλαιῶν, ἤρξαντο ἅπαν τὸ πλῆθος τῶν μαθητῶν χαίροντες αἰνεῖν τὸν  ̊Θεὸν φωνῇ μεγάλῃ περὶ πασῶν ὧν εἶδον δυνάμεων');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 38, 'λέγοντες, “‘Εὐλογημένος ὁ ἐρχόμενος ὁ βασιλεὺς ἐν ὀνόματι  ̊Κυρίου’· ἐν οὐρανῷ εἰρήνη καὶ δόξα ἐν ὑψίστοις.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 39, 'Καί τινες τῶν Φαρισαίων ἀπὸ τοῦ ὄχλου εἶπαν πρὸς αὐτόν, “Διδάσκαλε, ἐπιτίμησον τοῖς μαθηταῖς σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 40, 'Καὶ ἀποκριθεὶς εἶπεν, “Λέγω ὑμῖν ὅτι ἐὰν οὗτοι σιωπήσουσιν, οἱ λίθοι κράξουσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 41, '¶Καὶ ὡς ἤγγισεν, ἰδὼν τὴν πόλιν, ἔκλαυσεν ἐπʼ αὐτήν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 42, 'λέγων, ὅτι “Εἰ ἔγνως ἐν τῇ ἡμέρᾳ ταύτῃ, καὶ σὺ, τὰ πρὸς εἰρήνην· νῦν δὲ ἐκρύβη ἀπὸ ὀφθαλμῶν σου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 43, 'Ὅτι ἥξουσιν ἡμέραι ἐπὶ σὲ, καὶ περιβαλοῦσιν οἱ ἐχθροί σου χάρακά σοι, καὶ περικυκλώσουσίν σε καὶ συνέξουσίν σε πάντοθεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 44, 'καὶ ἐδαφιοῦσίν σε καὶ τὰ τέκνα σου ἐν σοί, καὶ οὐκ ἀφήσουσιν λίθον ἐπὶ λίθον ἐν σοί, ἀνθʼ ὧν οὐκ ἔγνως τὸν καιρὸν τῆς ἐπισκοπῆς σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 45, '¶Καὶ εἰσελθὼν εἰς τὸ ἱερὸν, ἤρξατο ἐκβάλλειν τοὺς πωλοῦντας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 46, 'λέγων αὐτοῖς, “Γέγραπται, ‘Ὁ οἶκός μου οἶκος προσευχῆς’, ὑμεῖς δὲ αὐτὸν ἐποιήσατε ‘σπήλαιον λῃστῶν’.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 47, '¶Καὶ ἦν διδάσκων τὸ καθʼ ἡμέραν ἐν τῷ ἱερῷ· οἱ δὲ ἀρχιερεῖς καὶ οἱ γραμματεῖς ἐζήτουν αὐτὸν ἀπολέσαι καὶ οἱ πρῶτοι τοῦ λαοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 48, 'καὶ οὐχ εὕρισκον τὸ τί ποιήσωσιν, ὁ λαὸς γὰρ ἅπας ἐξεκρέμετο αὐτοῦ ἀκούων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 1, '¶Καὶ ἐγένετο ἐν μιᾷ τῶν ἡμερῶν, διδάσκοντος αὐτοῦ τὸν λαὸν ἐν τῷ ἱερῷ, καὶ εὐαγγελιζομένου, ἐπέστησαν οἱ ἀρχιερεῖς καὶ οἱ γραμματεῖς σὺν τοῖς πρεσβυτέροις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 2, 'καὶ εἶπαν λέγοντες πρὸς αὐτόν, “Εἰπὸν ἡμῖν ἐν ποίᾳ ἐξουσίᾳ ταῦτα ποιεῖς, ἢ τίς ἐστιν ὁ δούς σοι τὴν ἐξουσίαν ταύτην;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 3, 'Ἀποκριθεὶς δὲ εἶπεν πρὸς αὐτούς, “Ἐρωτήσω ὑμᾶς κἀγὼ λόγον καὶ εἴπατέ μοι:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 4, 'τὸ βάπτισμα Ἰωάννου, ἐξ οὐρανοῦ ἦν ἢ ἐξ ἀνθρώπων;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 5, 'Οἱ δὲ συνελογίσαντο πρὸς ἑαυτοὺς λέγοντες, ὅτι “Ἐὰν εἴπωμεν, ‘Ἐξ οὐρανοῦ’, ἐρεῖ, ‘Διὰ τί οὐκ ἐπιστεύσατε αὐτῷ;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 6, 'Ἐὰν δὲ εἴπωμεν, ‘Ἐξ ἀνθρώπων’, ὁ λαὸς ἅπας καταλιθάσει ἡμᾶς, πεπεισμένος γάρ ἐστιν Ἰωάννην προφήτην εἶναι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 7, 'Καὶ ἀπεκρίθησαν, μὴ εἰδέναι πόθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 8, 'Καὶ ὁ  ̊Ἰησοῦς εἶπεν αὐτοῖς, “Οὐδὲ ἐγὼ λέγω ὑμῖν ἐν ποίᾳ ἐξουσίᾳ ταῦτα ποιῶ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 9, '¶Ἤρξατο δὲ πρὸς τὸν λαὸν λέγειν τὴν παραβολὴν ταύτην: “Ἄνθρωπος ἐφύτευσεν ἀμπελῶνα, καὶ ἐξέδετο αὐτὸν γεωργοῖς, καὶ ἀπεδήμησεν χρόνους ἱκανούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 10, 'Καὶ καιρῷ ἀπέστειλεν πρὸς τοὺς γεωργοὺς δοῦλον, ἵνα ἀπὸ τοῦ καρποῦ τοῦ ἀμπελῶνος δώσουσιν αὐτῷ. Οἱ δὲ γεωργοὶ ἐξαπέστειλαν αὐτὸν, δείραντες κενόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 11, 'Καὶ προσέθετο ἕτερον πέμψαι δοῦλον· οἱ δὲ, κἀκεῖνον δείραντες καὶ ἀτιμάσαντες, ἐξαπέστειλαν κενόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 12, 'Καὶ προσέθετο τρίτον πέμψαι· οἱ δὲ καὶ τοῦτον τραυματίσαντες, ἐξέβαλον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 13, 'Εἶπεν δὲ ὁ κύριος τοῦ ἀμπελῶνος, ‘Τί ποιήσω; Πέμψω τὸν υἱόν μου τὸν ἀγαπητόν· ἴσως τοῦτον ἐντραπήσονται.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 14, 'Ἰδόντες δὲ αὐτὸν, οἱ γεωργοὶ διελογίζοντο πρὸς ἀλλήλους λέγοντες, ‘Οὗτός ἐστιν ὁ κληρονόμος· ἀποκτείνωμεν αὐτόν, ἵνα ἡμῶν γένηται ἡ κληρονομία.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 15, 'Καὶ ἐκβαλόντες αὐτὸν ἔξω τοῦ ἀμπελῶνος, ἀπέκτειναν. Τί οὖν ποιήσει αὐτοῖς ὁ κύριος τοῦ ἀμπελῶνος;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 16, 'Ἐλεύσεται καὶ ἀπολέσει τοὺς γεωργοὺς τούτους, καὶ δώσει τὸν ἀμπελῶνα ἄλλοις.” Ἀκούσαντες δὲ εἶπαν, “Μὴ γένοιτο!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 17, 'Ὁ δὲ ἐμβλέψας αὐτοῖς εἶπεν, “Τί οὖν ἐστιν τὸ γεγραμμένον τοῦτο, ‘Λίθον ὃν ἀπεδοκίμασαν οἱ οἰκοδομοῦντες, οὗτος ἐγενήθη εἰς κεφαλὴν γωνίας’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 18, 'Πᾶς ὁ πεσὼν ἐπʼ ἐκεῖνον τὸν λίθον, συνθλασθήσεται· ἐφʼ ὃν δʼ ἂν πέσῃ, λικμήσει αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 19, 'Καὶ ἐζήτησαν οἱ γραμματεῖς καὶ οἱ ἀρχιερεῖς ἐπιβαλεῖν ἐπʼ αὐτὸν τὰς χεῖρας, ἐν αὐτῇ τῇ ὥρᾳ, καὶ ἐφοβήθησαν τὸν λαόν, ἔγνωσαν γὰρ ὅτι πρὸς αὐτοὺς εἶπεν τὴν παραβολὴν ταύτην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 20, '¶Καὶ παρατηρήσαντες, ἀπέστειλαν ἐγκαθέτους ὑποκρινομένους ἑαυτοὺς δικαίους εἶναι, ἵνα ἐπιλάβωνται αὐτοῦ λόγου, ὥστε παραδοῦναι αὐτὸν τῇ ἀρχῇ καὶ τῇ ἐξουσίᾳ τοῦ ἡγεμόνος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 21, 'Καὶ ἐπηρώτησαν αὐτὸν λέγοντες, “Διδάσκαλε, οἴδαμεν ὅτι ὀρθῶς λέγεις, καὶ διδάσκεις, καὶ οὐ λαμβάνεις πρόσωπον, ἀλλʼ ἐπʼ ἀληθείας τὴν ὁδὸν τοῦ  ̊Θεοῦ διδάσκεις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 22, 'Ἔξεστιν ἡμᾶς Καίσαρι φόρον δοῦναι ἢ οὔ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 23, 'Κατανοήσας δὲ αὐτῶν τὴν πανουργίαν, εἶπεν πρὸς αὐτούς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 24, '“Δείξατέ μοι δηνάριον· τίνος ἔχει εἰκόνα καὶ ἐπιγραφήν;” οἱ δὲ εἶπαν, “Καίσαρος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 25, 'Ὁ δὲ εἶπεν πρὸς αὐτούς, “Τοίνυν ἀπόδοτε τὰ Καίσαρος Καίσαρι, καὶ τὰ τοῦ  ̊Θεοῦ τῷ  ̊Θεῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 26, 'Καὶ οὐκ ἴσχυσαν ἐπιλαβέσθαι τοῦ ῥήματος ἐναντίον τοῦ λαοῦ, καὶ θαυμάσαντες ἐπὶ τῇ ἀποκρίσει αὐτοῦ, ἐσίγησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 27, '¶Προσελθόντες δέ τινες τῶν Σαδδουκαίων, οἱ λέγοντες ἀνάστασιν μὴ εἶναι, ἐπηρώτησαν αὐτὸν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 28, 'λέγοντες, “Διδάσκαλε, Μωϋσῆς ἔγραψεν ἡμῖν, ‘Ἐάν τινος ἀδελφὸς ἀποθάνῃ ἔχων γυναῖκα, καὶ οὗτος ἄτεκνος ἵνα λάβῃ ὁ ἀδελφὸς αὐτοῦ τὴν γυναῖκα, καὶ ἐξαναστήσῃ σπέρμα τῷ ἀδελφῷ αὐτοῦ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 29, 'Ἑπτὰ οὖν ἀδελφοὶ ἦσαν· καὶ ὁ πρῶτος, λαβὼν γυναῖκα, ἀπέθανεν ἄτεκνος·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 30, 'καὶ ὁ δεύτερος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 31, 'καὶ ὁ τρίτος ἔλαβεν αὐτήν, ὡσαύτως δὲ καὶ οἱ ἑπτὰ, οὐ κατέλιπον τέκνα, καὶ ἀπέθανον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 32, 'Ὕστερον καὶ ἡ γυνὴ ἀπέθανεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 33, 'Ἐν τῇ οὖν ἀναστάσει, τίνος αὐτῶν γίνεται γυνή; Οἱ γὰρ ἑπτὰ ἔσχον αὐτὴν γυναῖκα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 34, '¶Καὶ εἶπεν αὐτοῖς ὁ  ̊Ἰησοῦς, “Οἱ υἱοὶ τοῦ αἰῶνος τούτου γαμοῦσιν καὶ γαμίσκονται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 35, 'οἱ δὲ καταξιωθέντες τοῦ αἰῶνος ἐκείνου, τυχεῖν καὶ τῆς ἀναστάσεως τῆς ἐκ νεκρῶν, οὔτε γαμοῦσιν οὔτε γαμίζονται·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 36, 'οὐδὲ γὰρ ἀποθανεῖν ἔτι δύνανται, ἰσάγγελοι γάρ εἰσιν, καὶ υἱοί εἰσιν  ̊Θεοῦ, τῆς ἀναστάσεως υἱοὶ ὄντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 37, 'Ὅτι δὲ ἐγείρονται οἱ νεκροὶ, καὶ Μωϋσῆς ἐμήνυσεν ἐπὶ τῆς βάτου, ὡς λέγει  ̊Κύριον, ‘τὸν  ̊Θεὸν Ἀβραὰμ, καὶ  ̊Θεὸν Ἰσαὰκ, καὶ  ̊Θεὸν Ἰακώβ’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 38, ' ̊Θεὸς δὲ οὐκ ἔστιν νεκρῶν, ἀλλὰ ζώντων, πάντες γὰρ αὐτῷ ζῶσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 39, 'Ἀποκριθέντες δέ τινες τῶν γραμματέων εἶπαν, “Διδάσκαλε, καλῶς εἶπας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 40, 'Οὐκέτι γὰρ ἐτόλμων ἐπερωτᾶν αὐτὸν οὐδέν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 41, '¶Εἶπεν δὲ πρὸς αὐτούς, “Πῶς λέγουσιν τὸν  ̊Χριστὸν εἶναι Δαυὶδ Υἱόν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 42, 'Αὐτὸς γὰρ Δαυὶδ λέγει ἐν βίβλῳ Ψαλμῶν, ‘Εἶπεν ὁ  ̊Κύριος τῷ  ̊Κυρίῳ μου, “Κάθου ἐκ δεξιῶν μου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 43, 'ἕως ἂν θῶ τοὺς ἐχθρούς σου ὑποπόδιον τῶν ποδῶν σου.”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 44, 'Δαυὶδ οὖν, αὐτὸν ‘ ̊Κύριον’, καλεῖ, καὶ πῶς αὐτοῦ υἱός ἐστιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 45, '¶Ἀκούοντος δὲ παντὸς τοῦ λαοῦ, εἶπεν τοῖς μαθηταῖς αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 46, '“Προσέχετε ἀπὸ τῶν γραμματέων τῶν θελόντων περιπατεῖν ἐν στολαῖς, καὶ φιλούντων ἀσπασμοὺς ἐν ταῖς ἀγοραῖς, καὶ πρωτοκαθεδρίας ἐν ταῖς συναγωγαῖς, καὶ πρωτοκλισίας ἐν τοῖς δείπνοις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 47, 'οἳ κατεσθίουσιν τὰς οἰκίας τῶν χηρῶν, καὶ προφάσει μακρᾷ προσεύχονται. Οὗτοι λήμψονται περισσότερον κρίμα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 1, '¶Ἀναβλέψας δὲ, εἶδεν τοὺς βάλλοντας εἰς τὸ γαζοφυλάκιον τὰ δῶρα αὐτῶν πλουσίους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 2, 'Εἶδεν δέ τινα χήραν πενιχρὰν, βάλλουσαν ἐκεῖ λεπτὰ δύο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 3, 'Καὶ εἶπεν, “Ἀληθῶς λέγω ὑμῖν ὅτι ἡ χήρα αὕτη ἡ πτωχὴ, πλεῖον πάντων ἔβαλεν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 4, 'πάντες γὰρ οὗτοι ἐκ τοῦ περισσεύοντος αὐτοῖς ἔβαλον εἰς τὰ δῶρα, αὕτη δὲ ἐκ τοῦ ὑστερήματος αὐτῆς, πάντα τὸν βίον ὃν εἶχεν ἔβαλεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 5, '¶Καί τινων λεγόντων περὶ τοῦ ἱεροῦ ὅτι λίθοις καλοῖς καὶ ἀναθήμασιν κεκόσμηται, εἶπεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 6, '“Ταῦτα ἃ θεωρεῖτε, ἐλεύσονται ἡμέραι ἐν αἷς οὐκ ἀφεθήσεται λίθος ἐπὶ λίθῳ, ὧδε, ὃς οὐ καταλυθήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 7, '¶Ἐπηρώτησαν δὲ αὐτὸν λέγοντες, “Διδάσκαλε, πότε οὖν ταῦτα ἔσται, καὶ τί τὸ σημεῖον ὅταν μέλλῃ ταῦτα γίνεσθαι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 8, 'Ὁ δὲ εἶπεν, “Βλέπετε, μὴ πλανηθῆτε· πολλοὶ γὰρ ἐλεύσονται ἐπὶ τῷ ὀνόματί μου λέγοντες, ‘Ἐγώ εἰμι’, καί, ‘Ὁ καιρὸς ἤγγικεν.’ Μὴ πορευθῆτε ὀπίσω αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 9, 'Ὅταν δὲ ἀκούσητε πολέμους καὶ ἀκαταστασίας, μὴ πτοηθῆτε· δεῖ γὰρ ταῦτα γενέσθαι πρῶτον, ἀλλʼ οὐκ εὐθέως τὸ τέλος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 10, 'Τότε ἔλεγεν αὐτοῖς, “Ἐγερθήσεται ἔθνος ἐπʼ ἔθνος, καὶ βασιλεία ἐπὶ βασιλείαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 11, 'σεισμοί τε μεγάλοι, καὶ κατὰ τόπους, λιμοὶ καὶ λοιμοὶ ἔσονται, φόβητρά τε καὶ σημεῖα ἀπʼ οὐρανοῦ μεγάλα ἔσται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 12, '¶Πρὸ δὲ τούτων πάντων, ἐπιβαλοῦσιν ἐφʼ ὑμᾶς τὰς χεῖρας αὐτῶν, καὶ διώξουσιν, παραδιδόντες εἰς τὰς συναγωγὰς καὶ φυλακάς, ἀπαγομένους ἐπὶ βασιλεῖς καὶ ἡγεμόνας, ἕνεκεν τοῦ ὀνόματός μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 13, 'Ἀποβήσεται ὑμῖν εἰς μαρτύριον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 14, 'Θέτε οὖν ἐν ταῖς καρδίαις ὑμῶν μὴ προμελετᾶν ἀπολογηθῆναι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 15, 'ἐγὼ γὰρ δώσω ὑμῖν στόμα καὶ σοφίαν, ᾗ οὐ δυνήσονται ἀντιστῆναι ἢ ἀντειπεῖν πάντες οἱ ἀντικείμενοι ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 16, 'Παραδοθήσεσθε δὲ καὶ ὑπὸ γονέων, καὶ ἀδελφῶν, καὶ συγγενῶν, καὶ φίλων, καὶ θανατώσουσιν ἐξ ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 17, 'Καὶ ἔσεσθε μισούμενοι ὑπὸ πάντων διὰ τὸ ὄνομά μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 18, 'Καὶ θρὶξ ἐκ τῆς κεφαλῆς ὑμῶν, οὐ μὴ ἀπόληται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 19, 'Ἐν τῇ ὑπομονῇ ὑμῶν, κτήσεσθε τὰς ψυχὰς ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 20, '¶Ὅταν δὲ ἴδητε κυκλουμένην ὑπὸ στρατοπέδων Ἰερουσαλήμ, τότε γνῶτε ὅτι ἤγγικεν ἡ ἐρήμωσις αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 21, 'Τότε οἱ ἐν τῇ Ἰουδαίᾳ, φευγέτωσαν εἰς τὰ ὄρη, καὶ οἱ ἐν μέσῳ αὐτῆς, ἐκχωρείτωσαν, καὶ οἱ ἐν ταῖς χώραις, μὴ εἰσερχέσθωσαν εἰς αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 22, 'Ὅτι ἡμέραι ἐκδικήσεως αὗταί εἰσιν τοῦ πλησθῆναι πάντα τὰ γεγραμμένα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 23, 'Οὐαὶ δὲ ταῖς ἐν γαστρὶ ἐχούσαις καὶ ταῖς θηλαζούσαις ἐν ἐκείναις ταῖς ἡμέραις· ἔσται γὰρ ἀνάγκη μεγάλη ἐπὶ τῆς γῆς, καὶ ὀργὴ τῷ λαῷ τούτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 24, 'Καὶ πεσοῦνται στόματι μαχαίρας, καὶ αἰχμαλωτισθήσονται εἰς τὰ ἔθνη· πάντα· καὶ Ἰερουσαλὴμ ἔσται πατουμένη ὑπὸ ἐθνῶν, ἄχρι οὗ πληρωθῶσιν καιροὶ ἐθνῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 25, '¶Καὶ ἔσονται σημεῖα ἐν ἡλίῳ, καὶ σελήνῃ, καὶ ἄστροις, καὶ ἐπὶ τῆς γῆς συνοχὴ ἐθνῶν, ἐν ἀπορίᾳ ἤχους θαλάσσης καὶ σάλου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 26, 'ἀποψυχόντων ἀνθρώπων ἀπὸ φόβου καὶ προσδοκίας τῶν ἐπερχομένων τῇ οἰκουμένῃ, αἱ γὰρ δυνάμεις τῶν οὐρανῶν σαλευθήσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 27, 'Καὶ τότε ὄψονται ‘τὸν Υἱὸν τοῦ Ἀνθρώπου, ἐρχόμενον ἐν νεφέλῃ’ μετὰ δυνάμεως καὶ δόξης πολλῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 28, 'Ἀρχομένων δὲ τούτων γίνεσθαι, ἀνακύψατε καὶ ἐπάρατε τὰς κεφαλὰς ὑμῶν, διότι ἐγγίζει ἡ ἀπολύτρωσις ὑμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 29, '¶Καὶ εἶπεν παραβολὴν αὐτοῖς: “Ἴδετε τὴν συκῆν καὶ πάντα τὰ δένδρα·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 30, 'ὅταν προβάλωσιν ἤδη, βλέποντες ἀφʼ ἑαυτῶν, γινώσκετε ὅτι ἤδη ἐγγὺς τὸ θέρος ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 31, 'Οὕτως καὶ ὑμεῖς, ὅταν ἴδητε ταῦτα γινόμενα, γινώσκετε ὅτι ἐγγύς ἐστιν ἡ Βασιλεία τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 32, 'Ἀμὴν, λέγω ὑμῖν ὅτι οὐ μὴ παρέλθῃ ἡ γενεὰ αὕτη, ἕως ἂν πάντα γένηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 33, 'Ὁ οὐρανὸς καὶ ἡ γῆ παρελεύσονται, οἱ δὲ λόγοι μου οὐ μὴ παρελεύσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 34, '¶Προσέχετε δὲ ἑαυτοῖς, μήποτε βαρηθῶσιν αἱ καρδίαι ὑμῶν ἐν κραιπάλῃ, καὶ μέθῃ, καὶ μερίμναις βιωτικαῖς, καὶ ἐπιστῇ ἐφʼ ὑμᾶς αἰφνίδιος ἡ ἡμέρα ἐκείνη');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 35, 'ὡς παγίς· ἐπεισελεύσεται γὰρ ἐπὶ πάντας τοὺς καθημένους ἐπὶ πρόσωπον πάσης τῆς γῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 36, 'Ἀγρυπνεῖτε δὲ ἐν παντὶ καιρῷ, δεόμενοι ἵνα κατισχύσητε ἐκφυγεῖν ταῦτα πάντα τὰ μέλλοντα γίνεσθαι, καὶ σταθῆναι ἔμπροσθεν τοῦ Υἱοῦ τοῦ Ἀνθρώπου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 37, '¶Ἦν δὲ τὰς ἡμέρας ἐν τῷ ἱερῷ διδάσκων, τὰς δὲ νύκτας ἐξερχόμενος, ηὐλίζετο εἰς τὸ ὄρος τὸ καλούμενον Ἐλαιῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 38, 'Καὶ πᾶς ὁ λαὸς ὤρθριζεν πρὸς αὐτὸν ἐν τῷ ἱερῷ ἀκούειν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 1, '¶Ἤγγιζεν δὲ ἡ ἑορτὴ τῶν Ἀζύμων, ἡ λεγομένη Πάσχα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 2, 'Καὶ ἐζήτουν οἱ ἀρχιερεῖς καὶ οἱ γραμματεῖς, τὸ πῶς ἀνέλωσιν αὐτόν, ἐφοβοῦντο γὰρ τὸν λαόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 3, '¶Εἰσῆλθεν δὲ Σατανᾶς εἰς Ἰούδαν, τὸν καλούμενον Ἰσκαριώτην, ὄντα ἐκ τοῦ ἀριθμοῦ τῶν δώδεκα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 4, 'Καὶ ἀπελθὼν, συνελάλησεν τοῖς ἀρχιερεῦσιν καὶ στρατηγοῖς, τὸ πῶς αὐτοῖς παραδῷ αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 5, 'Καὶ ἐχάρησαν καὶ συνέθεντο αὐτῷ ἀργύριον δοῦναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 6, 'Καὶ ἐξωμολόγησεν, καὶ ἐζήτει εὐκαιρίαν τοῦ παραδοῦναι αὐτὸν ἄτερ ὄχλου αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 7, '¶Ἦλθεν δὲ ἡ ἡμέρα τῶν Ἀζύμων, ᾗ ἔδει θύεσθαι τὸ Πάσχα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 8, 'Καὶ ἀπέστειλεν Πέτρον καὶ Ἰωάννην εἰπών, “Πορευθέντες, ἑτοιμάσατε ἡμῖν τὸ Πάσχα, ἵνα φάγωμεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 9, 'Οἱ δὲ εἶπαν αὐτῷ, “Ποῦ θέλεις ἑτοιμάσωμεν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 10, 'Ὁ δὲ εἶπεν αὐτοῖς, “Ἰδοὺ, εἰσελθόντων ὑμῶν εἰς τὴν πόλιν, συναντήσει ὑμῖν ἄνθρωπος, κεράμιον ὕδατος βαστάζων· ἀκολουθήσατε αὐτῷ εἰς τὴν οἰκίαν εἰς ἣν εἰσπορεύεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 11, 'Καὶ ἐρεῖτε τῷ οἰκοδεσπότῃ τῆς οἰκίας, ‘Λέγει σοι ὁ διδάσκαλος, “Ποῦ ἐστιν τὸ κατάλυμα, ὅπου τὸ Πάσχα μετὰ τῶν μαθητῶν μου φάγω;”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 12, 'Κἀκεῖνος ὑμῖν δείξει ἀνάγαιον μέγα, ἐστρωμένον· ἐκεῖ ἑτοιμάσατε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 13, 'Ἀπελθόντες δὲ, εὗρον καθὼς εἰρήκει αὐτοῖς, καὶ ἡτοίμασαν τὸ Πάσχα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 14, '¶Καὶ ὅτε ἐγένετο ἡ ὥρα, ἀνέπεσεν καὶ οἱ ἀπόστολοι σὺν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 15, 'Καὶ εἶπεν πρὸς αὐτούς, “Ἐπιθυμίᾳ ἐπεθύμησα τοῦτο τὸ Πάσχα φαγεῖν μεθʼ ὑμῶν, πρὸ τοῦ με παθεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 16, 'Λέγω γὰρ ὑμῖν ὅτι οὐ μὴ φάγω αὐτὸ, ἕως ὅτου πληρωθῇ ἐν τῇ Βασιλείᾳ τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 17, 'Καὶ δεξάμενος ποτήριον, εὐχαριστήσας εἶπεν, “Λάβετε τοῦτο, καὶ διαμερίσατε εἰς ἑαυτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 18, 'Λέγω γὰρ ὑμῖν, οὐ μὴ πίω ἀπὸ τοῦ νῦν ἀπὸ τοῦ γενήματος τῆς ἀμπέλου, ἕως οὗ ἡ Βασιλεία τοῦ  ̊Θεοῦ ἔλθῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 19, 'Καὶ λαβὼν ἄρτον, εὐχαριστήσας, ἔκλασεν καὶ ἔδωκεν αὐτοῖς λέγων, “Τοῦτό ἐστιν τὸ σῶμά μου, τὸ ὑπὲρ ὑμῶν διδόμενον· τοῦτο ποιεῖτε εἰς τὴν ἐμὴν ἀνάμνησιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 20, 'Καὶ τὸ ποτήριον ὡσαύτως μετὰ τὸ δειπνῆσαι λέγων, “Τοῦτο τὸ ποτήριον ἡ καινὴ διαθήκη ἐν τῷ αἵματί μου, τὸ ὑπὲρ ὑμῶν ἐκχυννόμενον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 21, 'Πλὴν ἰδοὺ, ἡ χεὶρ τοῦ παραδιδόντος με μετʼ ἐμοῦ ἐπὶ τῆς τραπέζης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 22, 'Ὅτι ὁ Υἱὸς μὲν τοῦ Ἀνθρώπου κατὰ τὸ ὡρισμένον πορεύεται, πλὴν οὐαὶ τῷ ἀνθρώπῳ ἐκείνῳ διʼ οὗ παραδίδοται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 23, 'Καὶ αὐτοὶ ἤρξαντο συζητεῖν πρὸς ἑαυτοὺς, τὸ τίς ἄρα εἴη ἐξ αὐτῶν, ὁ τοῦτο μέλλων πράσσειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 24, '¶Ἐγένετο δὲ καὶ φιλονεικία ἐν αὐτοῖς, τὸ τίς αὐτῶν δοκεῖ εἶναι μείζων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 25, 'Ὁ δὲ εἶπεν αὐτοῖς, “Οἱ βασιλεῖς τῶν ἐθνῶν κυριεύουσιν αὐτῶν, καὶ οἱ ἐξουσιάζοντες αὐτῶν, ‘εὐεργέται’, καλοῦνται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 26, 'Ὑμεῖς δὲ οὐχ οὕτως, ἀλλʼ ὁ μείζων ἐν ὑμῖν, γινέσθω ὡς ὁ νεώτερος, καὶ ὁ ἡγούμενος, ὡς ὁ διακονῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 27, 'Τίς γὰρ μείζων, ὁ ἀνακείμενος ἢ ὁ διακονῶν; Οὐχὶ ὁ ἀνακείμενος; Ἐγὼ δὲ ἐν μέσῳ ὑμῶν εἰμι ὡς ὁ διακονῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 28, '¶Ὑμεῖς δέ ἐστε οἱ διαμεμενηκότες μετʼ ἐμοῦ, ἐν τοῖς πειρασμοῖς μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 29, 'Κἀγὼ διατίθεμαι ὑμῖν καθὼς διέθετό μοι ὁ Πατήρ μου βασιλείαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 30, 'ἵνα ἔσθητε καὶ πίνητε ἐπὶ τῆς τραπέζης μου ἐν τῇ βασιλείᾳ μου, καὶ καθῆσθε ἐπὶ θρόνων, τὰς δώδεκα φυλὰς κρίνοντες τοῦ Ἰσραήλ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 31, '¶Σίμων, Σίμων, ἰδοὺ, ὁ Σατανᾶς ἐξῃτήσατο ὑμᾶς τοῦ σινιάσαι ὡς τὸν σῖτον·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 32, 'ἐγὼ δὲ ἐδεήθην περὶ σοῦ ἵνα μὴ ἐκλίπῃ ἡ πίστις σου· καὶ σύ ποτε ἐπιστρέψας, στήρισον τοὺς ἀδελφούς σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 33, 'Ὁ δὲ εἶπεν αὐτῷ, “ ̊Κύριε, μετὰ σοῦ ἕτοιμός εἰμι καὶ εἰς φυλακὴν καὶ εἰς θάνατον πορεύεσθαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 34, 'Ὁ δὲ εἶπεν, “Λέγω σοι, Πέτρε, οὐ φωνήσει σήμερον ἀλέκτωρ, ἕως τρίς με ἀπαρνήσῃ εἰδέναι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 35, '¶Καὶ εἶπεν αὐτοῖς, “Ὅτε ἀπέστειλα ὑμᾶς ἄτερ βαλλαντίου, καὶ πήρας, καὶ ὑποδημάτων, μή τινος ὑστερήσατε;” Οἱ δὲ εἶπαν, “Οὐθενός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 36, 'Εἶπεν δὲ αὐτοῖς, “Ἀλλὰ νῦν ὁ ἔχων βαλλάντιον ἀράτω, ὁμοίως καὶ πήραν, καὶ ὁ μὴ ἔχων, πωλησάτω τὸ ἱμάτιον αὐτοῦ, καὶ ἀγορασάτω μάχαιραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 37, 'Λέγω γὰρ ὑμῖν ὅτι τοῦτο τὸ γεγραμμένον, δεῖ τελεσθῆναι ἐν ἐμοί, τό ‘Καὶ μετὰ ἀνόμων ἐλογίσθη’· καὶ γὰρ τὸ περὶ ἐμοῦ τέλος ἔχει.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 38, 'Οἱ δὲ εἶπαν, “ ̊Κύριε, ἰδοὺ, μάχαιραι ὧδε δύο.” Ὁ δὲ εἶπεν αὐτοῖς, “Ἱκανόν ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 39, '¶Καὶ ἐξελθὼν, ἐπορεύθη κατὰ τὸ ἔθος εἰς τὸ Ὄρος τῶν Ἐλαιῶν, ἠκολούθησαν δὲ αὐτῷ καὶ οἱ μαθηταί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 40, 'Γενόμενος δὲ ἐπὶ τοῦ τόπου, εἶπεν αὐτοῖς, “Προσεύχεσθε μὴ εἰσελθεῖν εἰς πειρασμόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 41, 'Καὶ αὐτὸς ἀπεσπάσθη ἀπʼ αὐτῶν ὡσεὶ λίθου βολήν, καὶ θεὶς τὰ γόνατα, προσηύχετο');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 42, 'λέγων, “Πάτερ, εἰ βούλει, παρένεγκε τοῦτο τὸ ποτήριον ἀπʼ ἐμοῦ· πλὴν μὴ τὸ θέλημά μου, ἀλλὰ τὸ σὸν γινέσθω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 43, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 44, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 45, 'Καὶ ἀναστὰς ἀπὸ τῆς προσευχῆς, ἐλθὼν πρὸς τοὺς μαθητὰς, εὗρεν κοιμωμένους αὐτοὺς ἀπὸ τῆς λύπης,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 46, 'καὶ εἶπεν αὐτοῖς, “Τί καθεύδετε; Ἀναστάντες προσεύχεσθε ἵνα μὴ εἰσέλθητε εἰς πειρασμόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 47, '¶Ἔτι αὐτοῦ λαλοῦντος, ἰδοὺ, ὄχλος καὶ ὁ λεγόμενος Ἰούδας, εἷς τῶν δώδεκα, προήρχετο αὐτούς, καὶ ἤγγισεν τῷ  ̊Ἰησοῦ φιλῆσαι αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 48, ' ̊Ἰησοῦς δὲ εἶπεν αὐτῷ, “Ἰούδα, φιλήματι τὸν Υἱὸν τοῦ Ἀνθρώπου παραδίδως;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 49, 'Ἰδόντες δὲ οἱ περὶ αὐτὸν τὸ ἐσόμενον, εἶπαν, “ ̊Κύριε, εἰ πατάξομεν ἐν μαχαίρῃ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 50, 'Καὶ ἐπάταξεν εἷς τις ἐξ αὐτῶν τὸν δοῦλον τοῦ ἀρχιερέως, καὶ ἀφεῖλεν τὸ οὖς αὐτοῦ τὸ δεξιόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 51, 'Ἀποκριθεὶς δὲ ὁ  ̊Ἰησοῦς εἶπεν, “Ἐᾶτε ἕως τούτου!” Καὶ ἁψάμενος τοῦ ὠτίου, ἰάσατο αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 52, 'Εἶπεν δὲ  ̊Ἰησοῦς πρὸς τοὺς παραγενομένους ἐπʼ αὐτὸν, ἀρχιερεῖς, καὶ στρατηγοὺς τοῦ ἱεροῦ, καὶ πρεσβυτέρους, “Ὡς ἐπὶ λῃστὴν ἐξήλθατε μετὰ μαχαιρῶν καὶ ξύλων;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 53, 'Καθʼ ἡμέραν ὄντος μου μεθʼ ὑμῶν ἐν τῷ ἱερῷ, οὐκ ἐξετείνατε τὰς χεῖρας ἐπʼ ἐμέ. Ἀλλʼ αὕτη ἐστὶν ὑμῶν ἡ ὥρα, καὶ ἡ ἐξουσία τοῦ σκότους.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 54, '¶Συλλαβόντες δὲ αὐτὸν, ἤγαγον καὶ εἰσήγαγον εἰς τὴν οἰκίαν τοῦ ἀρχιερέως. Ὁ δὲ Πέτρος ἠκολούθει μακρόθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 55, 'Περιαψάντων δὲ πῦρ ἐν μέσῳ τῆς αὐλῆς, καὶ συγκαθισάντων, ἐκάθητο ὁ Πέτρος μέσος αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 56, 'Ἰδοῦσα δὲ αὐτὸν, παιδίσκη τις καθήμενον πρὸς τὸ φῶς, καὶ ἀτενίσασα αὐτῷ εἶπεν, “Καὶ οὗτος σὺν αὐτῷ ἦν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 57, 'Ὁ δὲ ἠρνήσατο λέγων, “Οὐκ οἶδα αὐτόν, γύναι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 58, 'Καὶ μετὰ βραχὺ, ἕτερος ἰδὼν αὐτὸν ἔφη, “Καὶ σὺ ἐξ αὐτῶν εἶ.” Ὁ δὲ Πέτρος ἔφη, “Ἄνθρωπε, οὐκ εἰμί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 59, 'Καὶ διαστάσης ὡσεὶ ὥρας μιᾶς, ἄλλος τις διϊσχυρίζετο λέγων, “Ἐπʼ ἀληθείας καὶ οὗτος μετʼ αὐτοῦ ἦν, καὶ γὰρ Γαλιλαῖός ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 60, 'Εἶπεν δὲ ὁ Πέτρος, “Ἄνθρωπε, οὐκ οἶδα ὃ λέγεις.” Καὶ παραχρῆμα ἔτι λαλοῦντος αὐτοῦ, ἐφώνησεν ἀλέκτωρ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 61, 'Καὶ στραφεὶς, ὁ  ̊Κύριος ἐνέβλεψεν τῷ Πέτρῳ, καὶ ὑπεμνήσθη ὁ Πέτρος τοῦ ῥήματος τοῦ  ̊Κυρίου, ὡς εἶπεν αὐτῷ, ὅτι “Πρὶν ἀλέκτορα φωνῆσαι σήμερον, ἀπαρνήσῃ με τρίς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 62, 'Καὶ ἐξελθὼν ἔξω, ἔκλαυσεν πικρῶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 63, '¶Καὶ οἱ ἄνδρες οἱ συνέχοντες αὐτὸν, ἐνέπαιζον αὐτῷ δέροντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 64, 'Καὶ περικαλύψαντες αὐτὸν, ἐπηρώτων λέγοντες, “Προφήτευσον, τίς ἐστιν ὁ παίσας σε;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 65, 'Καὶ ἕτερα πολλὰ βλασφημοῦντες, ἔλεγον εἰς αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 66, '¶Καὶ ὡς ἐγένετο ἡμέρα, συνήχθη τὸ πρεσβυτέριον τοῦ λαοῦ, ἀρχιερεῖς τε καὶ γραμματεῖς, καὶ ἀπήγαγον αὐτὸν εἰς τὸ Συνέδριον αὐτῶν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 67, 'λέγοντες, “Εἰ σὺ εἶ ὁ  ̊Χριστός, εἰπὸν ἡμῖν.” Εἶπεν δὲ αὐτοῖς, “Ἐὰν ὑμῖν εἴπω, οὐ μὴ πιστεύσητε·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 68, 'ἐὰν δὲ ἐρωτήσω, οὐ μὴ ἀποκριθῆτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 69, 'Ἀπὸ τοῦ νῦν δὲ ἔσται ὁ Υἱὸς τοῦ Ἀνθρώπου ‘καθήμενος ἐκ δεξιῶν’ τῆς δυνάμεως τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 70, 'Εἶπαν δὲ πάντες, “Σὺ οὖν εἶ ὁ Υἱὸς τοῦ  ̊Θεοῦ;” Ὁ δὲ πρὸς αὐτοὺς ἔφη, “Ὑμεῖς λέγετε ὅτι ἐγώ εἰμι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 22, 71, 'Οἱ δὲ εἶπαν, “Τί ἔτι ἔχομεν μαρτυρίας χρείαν; Αὐτοὶ γὰρ ἠκούσαμεν ἀπὸ τοῦ στόματος αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 1, '¶Καὶ ἀναστὰν, ἅπαν τὸ πλῆθος αὐτῶν ἤγαγον αὐτὸν ἐπὶ τὸν Πιλᾶτον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 2, 'Ἤρξαντο δὲ κατηγορεῖν αὐτοῦ λέγοντες, “Τοῦτον εὕρομεν διαστρέφοντα τὸ ἔθνος ἡμῶν, καὶ κωλύοντα φόρους Καίσαρι διδόναι, καὶ λέγοντα ἑαυτὸν  ̊Χριστὸν, βασιλέα εἶναι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 3, 'Ὁ δὲ Πιλᾶτος ἠρώτησεν αὐτὸν λέγων, “Σὺ εἶ ὁ βασιλεὺς τῶν Ἰουδαίων;” Ὁ δὲ ἀποκριθεὶς αὐτῷ ἔφη, “Σὺ λέγεις.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 4, 'Ὁ δὲ Πιλᾶτος εἶπεν πρὸς τοὺς ἀρχιερεῖς καὶ τοὺς ὄχλους, “Οὐδὲν εὑρίσκω αἴτιον ἐν τῷ ἀνθρώπῳ τούτῳ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 5, 'Οἱ δὲ ἐπίσχυον λέγοντες, ὅτι “Ἀνασείει τὸν λαὸν, διδάσκων καθʼ ὅλης τῆς Ἰουδαίας, ἀρξάμενος ἀπὸ τῆς Γαλιλαίας ἕως ὧδε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 6, '¶Πιλᾶτος δὲ ἀκούσας, ἐπηρώτησεν εἰ ὁ ἄνθρωπος Γαλιλαῖός ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 7, 'Καὶ ἐπιγνοὺς ὅτι ἐκ τῆς ἐξουσίας Ἡρῴδου ἐστὶν, ἀνέπεμψεν αὐτὸν πρὸς τὸν Ἡρῴδην, ὄντα καὶ αὐτὸν ἐν Ἱεροσολύμοις ἐν ταύταις ταῖς ἡμέραις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 8, 'Ὁ δὲ Ἡρῴδης ἰδὼν τὸν  ̊Ἰησοῦν, ἐχάρη λίαν, ἦν γὰρ ἐξ ἱκανῶν χρόνων θέλων ἰδεῖν αὐτὸν, διὰ τὸ ἀκούειν περὶ αὐτοῦ, καὶ ἤλπιζέν τι σημεῖον ἰδεῖν ὑπʼ αὐτοῦ γινόμενον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 9, 'Ἐπηρώτα δὲ αὐτὸν ἐν λόγοις ἱκανοῖς, αὐτὸς δὲ οὐδὲν ἀπεκρίνατο αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 10, 'Εἱστήκεισαν δὲ οἱ ἀρχιερεῖς καὶ οἱ γραμματεῖς εὐτόνως κατηγοροῦντες αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 11, 'Ἐξουθενήσας δὲ αὐτὸν καὶ ὁ Ἡρῴδης σὺν τοῖς στρατεύμασιν αὐτοῦ, καὶ ἐμπαίξας περιβαλὼν ἐσθῆτα λαμπρὰν, ἀνέπεμψεν αὐτὸν τῷ Πιλάτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 12, 'Ἐγένοντο δὲ φίλοι ὅ τε Ἡρῴδης καὶ ὁ Πιλᾶτος ἐν αὐτῇ τῇ ἡμέρᾳ μετʼ ἀλλήλων· προϋπῆρχον γὰρ ἐν ἔχθρᾳ ὄντες πρὸς αὑτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 13, '¶Πιλᾶτος δὲ συγκαλεσάμενος τοὺς ἀρχιερεῖς, καὶ τοὺς ἄρχοντας, καὶ τὸν λαὸν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 14, 'εἶπεν πρὸς αὐτούς, “Προσηνέγκατέ μοι τὸν ἄνθρωπον τοῦτον, ὡς ἀποστρέφοντα τὸν λαόν, καὶ ἰδοὺ, ἐγὼ ἐνώπιον ὑμῶν ἀνακρίνας, οὐθὲν εὗρον ἐν τῷ ἀνθρώπῳ τούτῳ αἴτιον ὧν κατηγορεῖτε κατʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 15, 'Ἀλλʼ οὐδὲ Ἡρῴδης, ἀνέπεμψεν γὰρ αὐτὸν πρὸς ἡμᾶς. Καὶ ἰδοὺ, οὐδὲν ἄξιον θανάτου ἐστὶν πεπραγμένον αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 16, 'Παιδεύσας οὖν αὐτὸν, ἀπολύσω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 17, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 18, '¶Ἀνέκραγον δὲ παμπληθεὶ λέγοντες, “Αἶρε τοῦτον, ἀπόλυσον δὲ ἡμῖν τὸν Βαραββᾶν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 19, 'Ὅστις ἦν, διὰ στάσιν τινὰ γενομένην ἐν τῇ πόλει καὶ φόνον, βληθεὶς ἐν τῇ φυλακῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 20, 'Πάλιν δὲ ὁ Πιλᾶτος προσεφώνησεν αὐτοῖς, θέλων ἀπολῦσαι τὸν  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 21, 'Οἱ δὲ ἐπεφώνουν λέγοντες, “Σταύρου, σταύρου αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 22, 'Ὁ δὲ τρίτον εἶπεν πρὸς αὐτούς, “Τί γὰρ κακὸν ἐποίησεν οὗτος; Οὐδὲν αἴτιον θανάτου εὗρον ἐν αὐτῷ. Παιδεύσας οὖν αὐτὸν, ἀπολύσω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 23, 'Οἱ δὲ ἐπέκειντο φωναῖς μεγάλαις, αἰτούμενοι αὐτὸν σταυρωθῆναι, καὶ κατίσχυον αἱ φωναὶ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 24, 'Καὶ Πιλᾶτος ἐπέκρινεν γενέσθαι τὸ αἴτημα αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 25, 'Ἀπέλυσεν δὲ τὸν διὰ στάσιν καὶ φόνον βεβλημένον εἰς τὴν φυλακὴν, ὃν ᾐτοῦντο, τὸν δὲ  ̊Ἰησοῦν παρέδωκεν τῷ θελήματι αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 26, '¶Καὶ ὡς ἀπήγαγον αὐτόν, ἐπιλαβόμενοι Σίμωνά, τινα Κυρηναῖον ἐρχόμενον ἀπʼ ἀγροῦ, ἐπέθηκαν αὐτῷ τὸν σταυρὸν, φέρειν ὄπισθεν τοῦ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 27, 'Ἠκολούθει δὲ αὐτῷ πολὺ πλῆθος τοῦ λαοῦ, καὶ γυναικῶν αἳ ἐκόπτοντο καὶ ἐθρήνουν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 28, 'Στραφεὶς δὲ πρὸς αὐτὰς,  ̊Ἰησοῦς εἶπεν, “Θυγατέρες Ἰερουσαλήμ, μὴ κλαίετε ἐπʼ ἐμέ, πλὴν ἐφʼ ἑαυτὰς κλαίετε, καὶ ἐπὶ τὰ τέκνα ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 29, 'Ὅτι ἰδοὺ, ἔρχονται ἡμέραι ἐν αἷς ἐροῦσιν, ‘Μακάριαι αἱ στεῖραι, καὶ κοιλίαι αἳ οὐκ ἐγέννησαν, καὶ μαστοὶ οἳ οὐκ ἔθρεψαν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 30, 'Τότε ‘ἄρξονται λέγειν τοῖς ὄρεσιν, “Πέσετε ἐφʼ ἡμᾶς”, καὶ τοῖς βουνοῖς, “Καλύψατε ἡμᾶς”.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 31, 'Ὅτι εἰ ἐν τῷ ὑγρῷ ξύλῳ, ταῦτα ποιοῦσιν, ἐν τῷ ξηρῷ, τί γένηται;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 32, '¶Ἤγοντο δὲ καὶ ἕτεροι κακοῦργοι δύο σὺν αὐτῷ ἀναιρεθῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 33, 'Καὶ ὅτε ἦλθον ἐπὶ τὸν τόπον τὸν καλούμενον Κρανίον, ἐκεῖ ἐσταύρωσαν αὐτὸν καὶ τοὺς κακούργους, ὃν μὲν ἐκ δεξιῶν, ὃν δὲ ἐξ ἀριστερῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 34, 'Διαμεριζόμενοι δὲ τὰ ἱμάτια αὐτοῦ, ἔβαλον κλῆρον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 35, 'Καὶ εἱστήκει ὁ λαὸς θεωρῶν. ἐξεμυκτήριζον δὲ καὶ οἱ ἄρχοντες λέγοντες, “Ἄλλους ἔσωσεν, σωσάτω ἑαυτόν, εἰ οὗτός ἐστιν ὁ  ̊Χριστὸς, ὁ υἱὸς τοῦ  ̊Θεοῦ, ὁ ἐκλεκτός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 36, 'Ἐνέπαιξαν δὲ αὐτῷ καὶ οἱ στρατιῶται προσερχόμενοι, ὄξος προσφέροντες αὐτῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 37, 'καὶ λέγοντες, “Εἰ σὺ εἶ ὁ Βασιλεὺς τῶν Ἰουδαίων, σῶσον σεαυτόν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 38, 'Ἦν δὲ καὶ ἐπιγραφὴ ἐπʼ αὐτῷ: “Ὁ Βασιλεὺς τῶν Ἰουδαίων οὗτος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 39, '¶Εἷς δὲ τῶν κρεμασθέντων κακούργων ἐβλασφήμει αὐτόν λέγων, “Οὐχὶ σὺ εἶ ὁ  ̊Χριστός; Σῶσον σεαυτὸν καὶ ἡμᾶς!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 40, 'Ἀποκριθεὶς δὲ ὁ ἕτερος ἐπιτιμῶν αὐτῷ ἔφη, “Οὐδὲ φοβῇ σὺ τὸν  ̊Θεόν, ὅτι ἐν τῷ αὐτῷ κρίματι εἶ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 41, 'Καὶ ἡμεῖς μὲν δικαίως, ἄξια γὰρ ὧν ἐπράξαμεν ἀπολαμβάνομεν· οὗτος δὲ οὐδὲν ἄτοπον ἔπραξεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 42, 'Καὶ ἔλεγεν, “ ̊Ἰησοῦ, Μνήσθητί μου, ὅταν ἔλθῃς εἰς τὴν βασιλείαν σου!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 43, 'Καὶ εἶπεν αὐτῷ, “Ἀμήν, σοι λέγω, σήμερον μετʼ ἐμοῦ ἔσῃ ἐν τῷ Παραδείσῳ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 44, '¶Καὶ ἦν ἤδη ὡσεὶ ὥρα ἕκτη, καὶ σκότος ἐγένετο ἐφʼ ὅλην τὴν γῆν ἕως ὥρας ἐνάτης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 45, 'Τοῦ ἡλίου ἐκλιπόντος, ἐσχίσθη δὲ τὸ καταπέτασμα τοῦ ναοῦ μέσον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 46, 'Καὶ φωνήσας φωνῇ μεγάλῃ, ὁ  ̊Ἰησοῦς εἶπεν, “Πάτερ, ‘εἰς χεῖράς σου παρατίθεμαι τὸ  ̊Πνεῦμά μου’.” Τοῦτο δὲ εἰπὼν, ἐξέπνευσεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 47, 'Ἰδὼν δὲ ὁ ἑκατοντάρχης τὸ γενόμενον, ἐδόξασεν τὸν  ̊Θεὸν λέγων, “Ὄντως ὁ ἄνθρωπος οὗτος δίκαιος ἦν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 48, 'Καὶ πάντες οἱ συμπαραγενόμενοι ὄχλοι ἐπὶ τὴν θεωρίαν ταύτην, θεωρήσαντες τὰ γενόμενα, τύπτοντες τὰ στήθη ὑπέστρεφον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 49, 'Εἱστήκεισαν δὲ πάντες οἱ γνωστοὶ αὐτῷ ἀπὸ μακρόθεν, καὶ γυναῖκες αἱ συνακολουθοῦσαι αὐτῷ ἀπὸ τῆς Γαλιλαίας, ὁρῶσαι ταῦτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 50, '¶Καὶ ἰδοὺ, ἀνὴρ ὀνόματι Ἰωσὴφ, βουλευτὴς ὑπάρχων, καὶ ἀνὴρ ἀγαθὸς καὶ δίκαιος');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 51, '(οὗτος οὐκ ἦν συγκατατεθειμένος τῇ βουλῇ καὶ τῇ πράξει αὐτῶν), ἀπὸ Ἁριμαθαίας, πόλεως τῶν Ἰουδαίων, ὃς προσεδέχετο τὴν Βασιλείαν τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 52, 'Οὗτος προσελθὼν τῷ Πιλάτῳ, ᾐτήσατο τὸ σῶμα τοῦ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 53, 'Καὶ καθελὼν, ἐνετύλιξεν αὐτὸ σινδόνι καὶ ἔθηκεν αὐτὸν ἐν μνήματι λαξευτῷ, οὗ οὐκ ἦν οὐδεὶς οὔπω κείμενος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 54, 'Καὶ ἡμέρα ἦν παρασκευῆς, καὶ Σάββατον ἐπέφωσκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 55, 'Κατακολουθήσασαι δὲ, αἱ γυναῖκες, αἵτινες ἦσαν συνεληλυθυῖαι ἐκ τῆς Γαλιλαίας αὐτῷ, ἐθεάσαντο τὸ μνημεῖον καὶ ὡς ἐτέθη τὸ σῶμα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 23, 56, 'Ὑποστρέψασαι δὲ, ἡτοίμασαν ἀρώματα καὶ μύρα. ¶Καὶ τὸ μὲν Σάββατον ἡσύχασαν κατὰ τὴν ἐντολήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 1, 'Τῇ δὲ μιᾷ τῶν σαββάτων, ὄρθρου βαθέως, ἐπὶ τὸ μνημεῖον ἦλθαν, φέρουσαι ἃ ἡτοίμασαν ἀρώματα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 2, 'Εὗρον δὲ τὸν λίθον ἀποκεκυλισμένον ἀπὸ τοῦ μνημείου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 3, 'Εἰσελθοῦσαι δὲ, οὐχ εὗρον τὸ σῶμα τοῦ  ̊Κυρίου  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 4, 'Καὶ ἐγένετο ἐν τῷ ἀπορεῖσθαι αὐτὰς περὶ τούτου, καὶ ἰδοὺ, ἄνδρες δύο ἐπέστησαν αὐταῖς ἐν ἐσθῆτι ἀστραπτούσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 5, 'Ἐμφόβων δὲ γενομένων αὐτῶν, καὶ κλινουσῶν τὰ πρόσωπα εἰς τὴν γῆν, εἶπαν πρὸς αὐτάς, “Τί ζητεῖτε τὸν ζῶντα μετὰ τῶν νεκρῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 6, 'Οὐκ ἔστιν ὧδε, ἀλλὰ ἠγέρθη! Μνήσθητε ὡς ἐλάλησεν ὑμῖν, ἔτι ὢν ἐν τῇ Γαλιλαίᾳ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 7, 'λέγων, ‘Τὸν Υἱὸν τοῦ Ἀνθρώπου ὅτι δεῖ παραδοθῆναι εἰς χεῖρας ἀνθρώπων ἁμαρτωλῶν, καὶ σταυρωθῆναι, καὶ τῇ τρίτῃ ἡμέρᾳ ἀναστῆναι.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 8, 'Καὶ ἐμνήσθησαν τῶν ῥημάτων αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 9, 'Καὶ ὑποστρέψασαι ἀπὸ τοῦ μνημείου, ἀπήγγειλαν ταῦτα πάντα τοῖς ἕνδεκα, καὶ πᾶσιν τοῖς λοιποῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 10, 'Ἦσαν δὲ ἡ Μαγδαληνὴ Μαρία, καὶ Ἰωάννα, καὶ Μαρία ἡ Ἰακώβου, καὶ αἱ λοιπαὶ σὺν αὐταῖς, ἔλεγον πρὸς τοὺς ἀποστόλους ταῦτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 11, 'Καὶ ἐφάνησαν ἐνώπιον αὐτῶν ὡσεὶ λῆρος τὰ ῥήματα ταῦτα, καὶ ἠπίστουν αὐταῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 12, 'Ὁ δὲ Πέτρος ἀναστὰς, ἔδραμεν ἐπὶ τὸ μνημεῖον, καὶ παρακύψας, βλέπει τὰ ὀθόνια μόνα, καὶ ἀπῆλθεν πρὸς ἑαυτὸν, θαυμάζων τὸ γεγονός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 13, '¶Καὶ ἰδοὺ, δύο ἐξ αὐτῶν ἐν αὐτῇ τῇ ἡμέρᾳ ἦσαν πορευόμενοι εἰς κώμην ἀπέχουσαν σταδίους ἑξήκοντα ἀπὸ Ἰερουσαλήμ, ᾗ ὄνομα Ἐμμαοῦς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 14, 'Καὶ αὐτοὶ ὡμίλουν πρὸς ἀλλήλους περὶ πάντων τῶν συμβεβηκότων τούτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 15, 'Καὶ ἐγένετο ἐν τῷ, ὁμιλεῖν αὐτοὺς καὶ συζητεῖν, καὶ αὐτὸς  ̊Ἰησοῦς ἐγγίσας, συνεπορεύετο αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 16, 'Οἱ δὲ ὀφθαλμοὶ αὐτῶν ἐκρατοῦντο τοῦ μὴ ἐπιγνῶναι αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 17, 'Εἶπεν δὲ πρὸς αὐτούς, “Τίνες οἱ λόγοι οὗτοι οὓς ἀντιβάλλετε πρὸς ἀλλήλους περιπατοῦντες;” Καὶ ἐστάθησαν σκυθρωποί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 18, 'Ἀποκριθεὶς δὲ εἷς ὀνόματι Κλεοπᾶς εἶπεν πρὸς αὐτόν, “Σὺ μόνος παροικεῖς Ἰερουσαλὴμ καὶ οὐκ ἔγνως τὰ γενόμενα ἐν αὐτῇ ἐν ταῖς ἡμέραις ταύταις;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 19, 'Καὶ εἶπεν αὐτοῖς, “Ποῖα;” Οἱ δὲ εἶπαν αὐτῷ, “Τὰ περὶ  ̊Ἰησοῦ τοῦ Ναζαρηνοῦ, ὃς ἐγένετο ἀνὴρ, προφήτης, δυνατὸς ἐν ἔργῳ καὶ λόγῳ, ἐναντίον τοῦ  ̊Θεοῦ καὶ παντὸς τοῦ λαοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 20, 'ὅπως τε παρέδωκαν αὐτὸν οἱ ἀρχιερεῖς καὶ οἱ ἄρχοντες ἡμῶν, εἰς κρίμα θανάτου, καὶ ἐσταύρωσαν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 21, 'Ἡμεῖς δὲ ἠλπίζομεν ὅτι αὐτός ἐστιν ὁ μέλλων λυτροῦσθαι τὸν Ἰσραήλ. Ἀλλά γε καὶ σὺν πᾶσιν τούτοις, τρίτην ταύτην ἡμέραν ἄγει, ἀφʼ οὗ ταῦτα ἐγένετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 22, 'Ἀλλὰ καὶ γυναῖκές τινες ἐξ ἡμῶν, ἐξέστησαν ἡμᾶς, γενόμεναι ὀρθριναὶ ἐπὶ τὸ μνημεῖον');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 23, 'καὶ μὴ εὑροῦσαι τὸ σῶμα αὐτοῦ, ἦλθαν λέγουσαι καὶ ὀπτασίαν ἀγγέλων ἑωρακέναι, οἳ λέγουσιν αὐτὸν ζῆν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 24, 'Καὶ ἀπῆλθόν τινες τῶν σὺν ἡμῖν ἐπὶ τὸ μνημεῖον, καὶ εὗρον οὕτως, καθὼς αἱ γυναῖκες εἶπον, αὐτὸν δὲ οὐκ εἶδον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 25, 'Καὶ αὐτὸς εἶπεν πρὸς αὐτούς, “Ὦ ἀνόητοι καὶ βραδεῖς τῇ καρδίᾳ, τοῦ πιστεύειν ἐπὶ πᾶσιν οἷς ἐλάλησαν οἱ προφῆται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 26, 'Οὐχὶ ταῦτα ἔδει παθεῖν τὸν  ̊Χριστὸν καὶ εἰσελθεῖν εἰς τὴν δόξαν αὐτοῦ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 27, 'Καὶ ἀρξάμενος ἀπὸ Μωϋσέως καὶ ἀπὸ πάντων τῶν προφητῶν, διερμήνευσεν αὐτοῖς ἐν πάσαις ταῖς Γραφαῖς τὰ περὶ ἑαυτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 28, '¶Καὶ ἤγγισαν εἰς τὴν κώμην οὗ ἐπορεύοντο, καὶ αὐτὸς προσεποιήσατο πορρώτερον πορεύεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 29, 'Καὶ παρεβιάσαντο αὐτὸν λέγοντες, “Μεῖνον μεθʼ ἡμῶν, ὅτι πρὸς ἑσπέραν ἐστὶν, καὶ κέκλικεν ἤδη ἡ ἡμέρα.” Καὶ εἰσῆλθεν τοῦ μεῖναι σὺν αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 30, 'Καὶ ἐγένετο ἐν τῷ κατακλιθῆναι αὐτὸν μετʼ αὐτῶν, λαβὼν τὸν ἄρτον, εὐλόγησεν καὶ κλάσας, ἐπεδίδου αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 31, 'Αὐτῶν δὲ διηνοίχθησαν οἱ ὀφθαλμοὶ, καὶ ἐπέγνωσαν αὐτόν. Καὶ αὐτὸς ἄφαντος ἐγένετο ἀπʼ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 32, 'Καὶ εἶπαν πρὸς ἀλλήλους, “Οὐχὶ ἡ καρδία ἡμῶν καιομένη ἦν ὡς ἐλάλει ἡμῖν ἐν τῇ ὁδῷ, ὡς διήνοιγεν ἡμῖν τὰς Γραφάς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 33, 'Καὶ ἀναστάντες αὐτῇ τῇ ὥρᾳ, ὑπέστρεψαν εἰς Ἰερουσαλήμ, καὶ εὗρον ἠθροισμένους τοὺς ἕνδεκα καὶ τοὺς σὺν αὐτοῖς');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 34, 'λέγοντας, ὅτι “Ὄντως ἠγέρθη ὁ  ̊Κύριος, καὶ ὤφθη Σίμωνι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 35, 'Καὶ αὐτοὶ ἐξηγοῦντο τὰ ἐν τῇ ὁδῷ, καὶ ὡς ἐγνώσθη αὐτοῖς ἐν τῇ κλάσει τοῦ ἄρτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 36, '¶Ταῦτα δὲ αὐτῶν λαλούντων, αὐτὸς ἔστη ἐν μέσῳ αὐτῶν καὶ λέγει αὐτοῖς, “Εἰρήνη ὑμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 37, 'Πτοηθέντες δὲ καὶ ἔμφοβοι γενόμενοι, ἐδόκουν πνεῦμα θεωρεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 38, 'Καὶ εἶπεν αὐτοῖς, “Τί τεταραγμένοι ἐστέ, καὶ διὰ τί διαλογισμοὶ ἀναβαίνουσιν ἐν τῇ καρδίᾳ ὑμῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 39, 'Ἴδετε τὰς χεῖράς μου καὶ τοὺς πόδας μου ὅτι ἐγώ εἰμι αὐτός. Ψηλαφήσατέ με καὶ ἴδετε, ὅτι πνεῦμα σάρκα καὶ ὀστέα οὐκ ἔχει, καθὼς ἐμὲ θεωρεῖτε ἔχοντα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 40, 'Καὶ τοῦτο εἰπὼν, ἔδειξεν αὐτοῖς τὰς χεῖρας καὶ τοὺς πόδας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 41, 'Ἔτι δὲ ἀπιστούντων αὐτῶν ἀπὸ τῆς χαρᾶς καὶ θαυμαζόντων, εἶπεν αὐτοῖς, “Ἔχετέ τι βρώσιμον ἐνθάδε;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 42, 'Οἱ δὲ ἐπέδωκαν αὐτῷ ἰχθύος ὀπτοῦ μέρος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 43, 'Καὶ λαβὼν, ἐνώπιον αὐτῶν ἔφαγεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 44, '¶Εἶπεν δὲ πρὸς αὐτούς, “Οὗτοι οἱ λόγοι μου, οὓς ἐλάλησα πρὸς ὑμᾶς ἔτι ὢν σὺν ὑμῖν, ὅτι δεῖ πληρωθῆναι πάντα τὰ γεγραμμένα ἐν τῷ νόμῳ Μωϋσέως, καὶ τοῖς προφήταις, καὶ ψαλμοῖς, περὶ ἐμοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 45, 'Τότε διήνοιξεν αὐτῶν τὸν νοῦν τοῦ συνιέναι τὰς Γραφάς. Καὶ εἶπεν αὐτοῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 46, 'ὅτι “Οὕτως γέγραπται, παθεῖν τὸν  ̊Χριστὸν, καὶ ἀναστῆναι ἐκ νεκρῶν τῇ τρίτῃ ἡμέρᾳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 47, 'καὶ κηρυχθῆναι ἐπὶ τῷ ὀνόματι αὐτοῦ μετάνοιαν εἰς ἄφεσιν ἁμαρτιῶν εἰς πάντα τὰ ἔθνη, ἀρξάμενον ἀπὸ Ἰερουσαλήμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 48, 'Ὑμεῖς μάρτυρες τούτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 49, 'Καὶ ἰδοὺ ἐγὼ ἀποστέλλω τὴν ἐπαγγελίαν τοῦ Πατρός μου ἐφʼ ὑμᾶς· ὑμεῖς δὲ καθίσατε ἐν τῇ πόλει, ἕως οὗ ἐνδύσησθε ἐξ ὕψους δύναμιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 50, '¶Ἐξήγαγεν δὲ αὐτοὺς ἕως πρὸς Βηθανίαν, καὶ ἐπάρας τὰς χεῖρας αὐτοῦ, εὐλόγησεν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 51, 'Καὶ ἐγένετο ἐν τῷ εὐλογεῖν αὐτὸν αὐτοὺς, διέστη ἀπʼ αὐτῶν, καὶ ἀνεφέρετο εἰς τὸν οὐρανόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 52, 'Καὶ αὐτοὶ προσκυνήσαντες αὐτὸν, ὑπέστρεψαν εἰς Ἰερουσαλὴμ μετὰ χαρᾶς μεγάλης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 24, 53, 'Καὶ ἦσαν διὰ παντὸς ἐν τῷ ἱερῷ εὐλογοῦντες τὸν  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, '¶Ἐν ἀρχῇ ἦν ὁ λόγος, καὶ ὁ λόγος ἦν πρὸς τὸν  ̊Θεόν, καὶ  ̊Θεὸς ἦν ὁ λόγος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Οὗτος ἦν ἐν ἀρχῇ πρὸς τὸν  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Πάντα διʼ αὐτοῦ ἐγένετο, καὶ χωρὶς αὐτοῦ ἐγένετο οὐδὲ ἕν ὃ γέγονεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Ἐν αὐτῷ ζωὴ ἦν, καὶ ἡ ζωὴ ἦν τὸ φῶς τῶν ἀνθρώπων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Καὶ τὸ φῶς ἐν τῇ σκοτίᾳ φαίνει, καὶ ἡ σκοτία αὐτὸ οὐ κατέλαβεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, '¶Ἐγένετο ἄνθρωπος ἀπεσταλμένος παρὰ  ̊Θεοῦ, ὄνομα αὐτῷ Ἰωάννης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'Οὗτος ἦλθεν εἰς μαρτυρίαν, ἵνα μαρτυρήσῃ περὶ τοῦ φωτός, ἵνα πάντες πιστεύσωσιν διʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Οὐκ ἦν ἐκεῖνος τὸ φῶς, ἀλλʼ ἵνα μαρτυρήσῃ περὶ τοῦ φωτός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Ἦν τὸ φῶς τὸ ἀληθινὸν, ὃ φωτίζει πάντα ἄνθρωπον, ἐρχόμενον εἰς τὸν κόσμον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, '¶Ἐν τῷ κόσμῳ ἦν, καὶ ὁ κόσμος διʼ αὐτοῦ ἐγένετο, καὶ ὁ κόσμος αὐτὸν οὐκ ἔγνω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Εἰς τὰ ἴδια ἦλθεν, καὶ οἱ ἴδιοι αὐτὸν οὐ παρέλαβον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Ὅσοι δὲ ἔλαβον αὐτόν, ἔδωκεν αὐτοῖς ἐξουσίαν τέκνα  ̊Θεοῦ γενέσθαι, τοῖς πιστεύουσιν εἰς τὸ ὄνομα αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'οἳ οὐκ ἐξ αἱμάτων, οὐδὲ ἐκ θελήματος σαρκὸς, οὐδὲ ἐκ θελήματος ἀνδρὸς, ἀλλʼ ἐκ  ̊Θεοῦ ἐγεννήθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, '¶Καὶ ὁ λόγος σὰρξ ἐγένετο καὶ ἐσκήνωσεν ἐν ἡμῖν, καὶ ἐθεασάμεθα τὴν δόξαν αὐτοῦ, δόξαν ὡς μονογενοῦς παρὰ πατρός, πλήρης χάριτος καὶ ἀληθείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Ἰωάννης μαρτυρεῖ περὶ αὐτοῦ, καὶ κέκραγεν λέγων, “Οὗτος ἦν ὃν εἶπον, ‘Ὁ ὀπίσω μου ἐρχόμενος, ἔμπροσθέν μου γέγονεν, ὅτι πρῶτός μου ἦν.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Ὅτι ἐκ τοῦ πληρώματος αὐτοῦ, ἡμεῖς πάντες ἐλάβομεν καὶ χάριν ἀντὶ χάριτος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Ὅτι ὁ νόμος διὰ Μωϋσέως ἐδόθη, ἡ χάρις καὶ ἡ ἀλήθεια διὰ  ̊Ἰησοῦ  ̊Χριστοῦ ἐγένετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, ' ̊Θεὸν οὐδεὶς ἑώρακεν πώποτε· μονογενὴς  ̊Θεὸς, ὁ ὢν εἰς τὸν κόλπον τοῦ Πατρὸς, ἐκεῖνος ἐξηγήσατο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, '¶Καὶ αὕτη ἐστὶν ἡ μαρτυρία τοῦ Ἰωάννου, ὅτε ἀπέστειλαν οἱ Ἰουδαῖοι ἐξ Ἱεροσολύμων ἱερεῖς καὶ Λευίτας, ἵνα ἐρωτήσωσιν αὐτόν, “Σὺ τίς εἶ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Καὶ ὡμολόγησεν καὶ οὐκ ἠρνήσατο, καὶ ὡμολόγησεν, ὅτι “Ἐγὼ οὐκ εἰμὶ ὁ  ̊Χριστός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Καὶ ἠρώτησαν αὐτόν, “Τί οὖν; Σὺ Ἠλίας εἶ;” Καὶ λέγει, “Οὐκ εἰμί.” “Ὁ προφήτης εἶ σύ;” Καὶ ἀπεκρίθη, “Οὔ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 22, 'Εἶπαν οὖν αὐτῷ, “Τίς εἶ; Ἵνα ἀπόκρισιν δῶμεν τοῖς πέμψασιν ἡμᾶς. Τί λέγεις περὶ σεαυτοῦ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 23, 'Ἔφη, “Ἐγὼ ‘Φωνὴ βοῶντος ἐν τῇ ἐρήμῳ: “Εὐθύνατε τὴν ὁδὸν  ̊Κυρίου”’, καθὼς εἶπεν Ἠσαΐας ὁ προφήτης.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 24, '¶Καὶ ἀπεσταλμένοι ἦσαν ἐκ τῶν Φαρισαίων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 25, 'Καὶ ἠρώτησαν αὐτὸν καὶ εἶπαν αὐτῷ, “Τί οὖν βαπτίζεις, εἰ σὺ οὐκ εἶ ὁ  ̊Χριστὸς, οὐδὲ Ἠλίας, οὐδὲ ὁ προφήτης;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 26, 'Ἀπεκρίθη αὐτοῖς ὁ Ἰωάννης λέγων, “Ἐγὼ βαπτίζω ἐν ὕδατι· μέσος ὑμῶν ἕστηκεν ὃν ὑμεῖς οὐκ οἴδατε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 27, 'ὁ ὀπίσω μου ἐρχόμενος, οὗ οὐκ εἰμὶ ἐγὼ ἄξιος, ἵνα λύσω αὐτοῦ τὸν ἱμάντα τοῦ ὑποδήματος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 28, 'Ταῦτα ἐν Βηθανίᾳ ἐγένετο, πέραν τοῦ Ἰορδάνου, ὅπου ἦν ὁ Ἰωάννης βαπτίζων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 29, '¶Τῇ ἐπαύριον βλέπει τὸν  ̊Ἰησοῦν ἐρχόμενον πρὸς αὐτόν, καὶ λέγει, “Ἴδε, ὁ Ἀμνὸς τοῦ  ̊Θεοῦ, ὁ αἴρων τὴν ἁμαρτίαν τοῦ κόσμου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 30, 'Οὗτός ἐστιν ὑπὲρ οὗ ἐγὼ εἶπον, ‘Ὀπίσω μου ἔρχεται ἀνὴρ, ὃς ἔμπροσθέν μου γέγονεν, ὅτι πρῶτός μου ἦν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 31, 'Κἀγὼ οὐκ ᾔδειν αὐτόν, ἀλλʼ ἵνα φανερωθῇ τῷ Ἰσραὴλ διὰ τοῦτο, ἦλθον ἐγὼ ἐν ὕδατι βαπτίζων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 32, 'Καὶ ἐμαρτύρησεν Ἰωάννης λέγων, ὅτι “Τεθέαμαι τὸ  ̊Πνεῦμα καταβαῖνον ὡς περιστερὰν ἐξ οὐρανοῦ, καὶ ἔμεινεν ἐπʼ αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 33, 'Κἀγὼ οὐκ ᾔδειν αὐτόν, ἀλλʼ ὁ πέμψας με βαπτίζειν ἐν ὕδατι, ἐκεῖνός μοι εἶπεν, ‘Ἐφʼ ὃν ἂν ἴδῃς τὸ  ̊Πνεῦμα καταβαῖνον καὶ μένον ἐπʼ αὐτόν, οὗτός ἐστιν ὁ βαπτίζων ἐν  ̊Πνεύματι Ἁγίῳ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 34, 'Κἀγὼ ἑώρακα καὶ μεμαρτύρηκα ὅτι οὗτός ἐστιν ὁ Υἱὸς τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 35, '¶Τῇ ἐπαύριον πάλιν εἱστήκει ὁ Ἰωάννης, καὶ ἐκ τῶν μαθητῶν αὐτοῦ δύο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 36, 'Καὶ ἐμβλέψας τῷ  ̊Ἰησοῦ περιπατοῦντι λέγει, “Ἴδε, ὁ Ἀμνὸς τοῦ  ̊Θεοῦ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 37, 'Καὶ ἤκουσαν οἱ δύο αὐτοῦ μαθηταὶ λαλοῦντος, καὶ ἠκολούθησαν τῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 38, 'Στραφεὶς δὲ ὁ  ̊Ἰησοῦς, καὶ θεασάμενος αὐτοὺς ἀκολουθοῦντας, λέγει αὐτοῖς, “Τί ζητεῖτε;” Οἱ δὲ εἶπαν αὐτῷ, “Ῥαββί” (ὃ λέγεται μεθερμηνευόμενον, “Διδάσκαλε”), “Ποῦ μένεις;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 39, 'Λέγει αὐτοῖς, “Ἔρχεσθε καὶ ὄψεσθε.” Ἦλθαν οὖν καὶ εἶδαν ποῦ μένει, καὶ παρʼ αὐτῷ ἔμειναν τὴν ἡμέραν ἐκείνην· ὥρα ἦν ὡς δεκάτη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 40, 'Ἦν Ἀνδρέας ὁ ἀδελφὸς Σίμωνος Πέτρου, εἷς ἐκ τῶν δύο τῶν ἀκουσάντων παρὰ Ἰωάννου, καὶ ἀκολουθησάντων αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 41, 'Εὑρίσκει οὗτος πρῶτον τὸν ἀδελφὸν τὸν ἴδιον Σίμωνα, καὶ λέγει αὐτῷ, “Εὑρήκαμεν τὸν Μεσσίαν”, (ὅ ἐστιν μεθερμηνευόμενον, “ ̊Χριστός”).');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 42, 'ἤγαγεν αὐτὸν πρὸς τὸν  ̊Ἰησοῦν. Ἐμβλέψας αὐτῷ, ὁ  ̊Ἰησοῦς εἶπεν, “Σὺ εἶ Σίμων ὁ υἱὸς Ἰωάννου, σὺ κληθήσῃ Κηφᾶς”, (ὃ ἑρμηνεύεται, “Πέτρος”).');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 43, '¶Τῇ ἐπαύριον ἠθέλησεν ἐξελθεῖν εἰς τὴν Γαλιλαίαν. Καὶ εὑρίσκει Φίλιππον, καὶ λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Ἀκολούθει μοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 44, 'Ἦν δὲ ὁ Φίλιππος ἀπὸ Βηθσαϊδά, ἐκ τῆς πόλεως Ἀνδρέου καὶ Πέτρου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 45, 'Εὑρίσκει Φίλιππος τὸν Ναθαναὴλ, καὶ λέγει αὐτῷ, “Ὃν ἔγραψεν Μωϋσῆς ἐν τῷ νόμῳ καὶ οἱ προφῆται, εὑρήκαμεν  ̊Ἰησοῦν υἱὸν τοῦ Ἰωσὴφ, τὸν ἀπὸ Ναζαρέτ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 46, 'Καὶ εἶπεν αὐτῷ Ναθαναήλ, “Ἐκ Ναζαρὲτ δύναταί τι ἀγαθὸν εἶναι;” Λέγει αὐτῷ ὁ Φίλιππος, “Ἔρχου καὶ ἴδε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 47, 'Εἶδεν ὁ  ̊Ἰησοῦς τὸν Ναθαναὴλ ἐρχόμενον πρὸς αὐτὸν καὶ λέγει περὶ αὐτοῦ, “Ἴδε, ἀληθῶς Ἰσραηλίτης ἐν ᾧ δόλος οὐκ ἔστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 48, 'Λέγει αὐτῷ Ναθαναήλ, “Πόθεν με γινώσκεις;” Ἀπεκρίθη  ̊Ἰησοῦς καὶ εἶπεν αὐτῷ, “Πρὸ τοῦ σε Φίλιππον φωνῆσαι, ὄντα ὑπὸ τὴν συκῆν, εἶδόν σε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 49, 'Ἀπεκρίθη αὐτῷ Ναθαναήλ, “Ῥαββί, σὺ εἶ ὁ Υἱὸς τοῦ  ̊Θεοῦ, σὺ Βασιλεὺς εἶ τοῦ Ἰσραήλ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 50, 'Ἀπεκρίθη  ̊Ἰησοῦς καὶ εἶπεν αὐτῷ, “Ὅτι εἶπόν σοι ὅτι εἶδόν σε ὑποκάτω τῆς συκῆς, πιστεύεις; Μείζω τούτων ὄψῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 51, 'Καὶ λέγει αὐτῷ, “Ἀμὴν, ἀμὴν, λέγω ὑμῖν, ὄψεσθε τὸν οὐρανὸν ἀνεῳγότα, καὶ τοὺς ἀγγέλους τοῦ  ̊Θεοῦ ἀναβαίνοντας καὶ καταβαίνοντας ἐπὶ τὸν Υἱὸν τοῦ Ἀνθρώπου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 52, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, '¶Καὶ τῇ ἡμέρᾳ τῇ τρίτῃ γάμος ἐγένετο ἐν Κανὰ τῆς Γαλιλαίας, καὶ ἦν ἡ μήτηρ τοῦ  ̊Ἰησοῦ ἐκεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Ἐκλήθη δὲ καὶ ὁ  ̊Ἰησοῦς καὶ οἱ μαθηταὶ αὐτοῦ εἰς τὸν γάμον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Καὶ ὑστερήσαντος οἴνου, λέγει ἡ μήτηρ τοῦ  ̊Ἰησοῦ πρὸς αὐτόν, “Οἶνον οὐκ ἔχουσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Καὶ λέγει αὐτῇ ὁ  ̊Ἰησοῦς, “Τί ἐμοὶ καὶ σοί, γύναι; Οὔπω ἥκει ἡ ὥρα μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Λέγει ἡ μήτηρ αὐτοῦ τοῖς διακόνοις, “Ὅ τι ἂν λέγῃ ὑμῖν ποιήσατε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'Ἦσαν δὲ ἐκεῖ λίθιναι ὑδρίαι ἓξ κατὰ τὸν καθαρισμὸν τῶν Ἰουδαίων κείμεναι, χωροῦσαι ἀνὰ μετρητὰς δύο ἢ τρεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'Λέγει αὐτοῖς ὁ  ̊Ἰησοῦς, “Γεμίσατε τὰς ὑδρίας ὕδατος.” Καὶ ἐγέμισαν αὐτὰς ἕως ἄνω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Καὶ λέγει αὐτοῖς, “Ἀντλήσατε νῦν καὶ φέρετε τῷ ἀρχιτρικλίνῳ.” Οἱ δὲ ἤνεγκαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Ὡς δὲ ἐγεύσατο ὁ ἀρχιτρίκλινος τὸ ὕδωρ οἶνον γεγενημένον, καὶ οὐκ ᾔδει πόθεν ἐστίν, οἱ δὲ διάκονοι ᾔδεισαν οἱ ἠντληκότες τὸ ὕδωρ, φωνεῖ τὸν νυμφίον ὁ ἀρχιτρίκλινος');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'καὶ λέγει αὐτῷ, “Πᾶς ἄνθρωπος πρῶτον τὸν καλὸν οἶνον τίθησιν, καὶ ὅταν μεθυσθῶσιν τὸν ἐλάσσω· σὺ τετήρηκας τὸν καλὸν οἶνον ἕως ἄρτι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Ταύτην ἐποίησεν ἀρχὴν τῶν σημείων ὁ  ̊Ἰησοῦς ἐν Κανὰ τῆς Γαλιλαίας, καὶ ἐφανέρωσεν τὴν δόξαν αὐτοῦ, καὶ ἐπίστευσαν εἰς αὐτὸν οἱ μαθηταὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, '¶Μετὰ τοῦτο κατέβη εἰς Καφαρναοὺμ, αὐτὸς καὶ ἡ μήτηρ αὐτοῦ, καὶ οἱ ἀδελφοὶ καὶ οἱ μαθηταὶ αὐτοῦ, καὶ ἐκεῖ ἔμειναν οὐ πολλὰς ἡμέρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, '¶Καὶ ἐγγὺς ἦν τὸ Πάσχα τῶν Ἰουδαίων, καὶ ἀνέβη εἰς Ἱεροσόλυμα ὁ  ̊Ἰησοῦς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Καὶ εὗρεν ἐν τῷ ἱερῷ τοὺς πωλοῦντας βόας καὶ πρόβατα καὶ περιστερὰς, καὶ τοὺς κερματιστὰς καθημένους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Καὶ ποιήσας φραγέλλιον ἐκ σχοινίων, πάντας ἐξέβαλεν ἐκ τοῦ ἱεροῦ, τά τε πρόβατα καὶ τοὺς βόας, καὶ τῶν κολλυβιστῶν ἐξέχεεν τὰ κέρματα, καὶ τὰς τραπέζας ἀνέτρεψεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Καὶ τοῖς τὰς περιστερὰς πωλοῦσιν εἶπεν, “Ἄρατε ταῦτα ἐντεῦθεν, μὴ ποιεῖτε τὸν οἶκον τοῦ πατρός μου οἶκον ἐμπορίου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Ἐμνήσθησαν οἱ μαθηταὶ αὐτοῦ ὅτι γεγραμμένον ἐστίν, “Ὁ ζῆλος τοῦ οἴκου σου καταφάγεταί με.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Ἀπεκρίθησαν οὖν οἱ Ἰουδαῖοι καὶ εἶπαν αὐτῷ, “Τί σημεῖον δεικνύεις ἡμῖν, ὅτι ταῦτα ποιεῖς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Ἀπεκρίθη  ̊Ἰησοῦς καὶ εἶπεν αὐτοῖς, “Λύσατε τὸν ναὸν τοῦτον, καὶ ἐν τρισὶν ἡμέραις ἐγερῶ αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Εἶπαν οὖν οἱ Ἰουδαῖοι, “Τεσσεράκοντα καὶ ἓξ ἔτεσιν οἰκοδομήθη ὁ ναὸς οὗτος, καὶ σὺ ἐν τρισὶν ἡμέραις ἐγερεῖς αὐτόν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Ἐκεῖνος δὲ ἔλεγεν περὶ τοῦ ναοῦ τοῦ σώματος αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Ὅτε οὖν ἠγέρθη ἐκ νεκρῶν, ἐμνήσθησαν οἱ μαθηταὶ αὐτοῦ ὅτι τοῦτο ἔλεγεν, καὶ ἐπίστευσαν τῇ Γραφῇ καὶ τῷ λόγῳ ὃν εἶπεν ὁ  ̊Ἰησοῦς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 23, '¶Ὡς δὲ ἦν ἐν τοῖς Ἱεροσολύμοις ἐν τῷ Πάσχα ἐν τῇ ἑορτῇ, πολλοὶ ἐπίστευσαν εἰς τὸ ὄνομα αὐτοῦ, θεωροῦντες αὐτοῦ τὰ σημεῖα ἃ ἐποίει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 24, 'Αὐτὸς δὲ  ̊Ἰησοῦς οὐκ ἐπίστευεν ἑαυτὸν αὐτοῖς, διὰ τὸ αὐτὸν γινώσκειν πάντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 25, 'Καὶ ὅτι οὐ χρείαν εἶχεν ἵνα τις μαρτυρήσῃ περὶ τοῦ ἀνθρώπου, αὐτὸς γὰρ ἐγίνωσκεν τί ἦν ἐν τῷ ἀνθρώπῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, '¶Ἦν δὲ ἄνθρωπος ἐκ τῶν Φαρισαίων, Νικόδημος ὄνομα αὐτῷ, ἄρχων τῶν Ἰουδαίων·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'οὗτος ἦλθεν πρὸς αὐτὸν νυκτὸς, καὶ εἶπεν αὐτῷ, “Ῥαββί, οἴδαμεν ὅτι ἀπὸ  ̊Θεοῦ ἐλήλυθας διδάσκαλος· οὐδεὶς γὰρ δύναται ταῦτα τὰ σημεῖα ποιεῖν, ἃ σὺ ποιεῖς, ἐὰν μὴ ᾖ ὁ  ̊Θεὸς μετʼ αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Ἀπεκρίθη  ̊Ἰησοῦς καὶ εἶπεν αὐτῷ, “Ἀμὴν, ἀμὴν, λέγω σοι, ἐὰν μή τις γεννηθῇ ἄνωθεν, οὐ δύναται ἰδεῖν τὴν Βασιλείαν τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'Λέγει πρὸς αὐτὸν Νικόδημος, “Πῶς δύναται ἄνθρωπος γεννηθῆναι, γέρων ὤν; Μὴ δύναται εἰς τὴν κοιλίαν τῆς μητρὸς αὐτοῦ δεύτερον εἰσελθεῖν καὶ γεννηθῆναι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Ἀπεκρίθη  ̊Ἰησοῦς, “Ἀμὴν, ἀμὴν, λέγω σοι, ἐὰν μή τις γεννηθῇ ἐξ ὕδατος καὶ  ̊Πνεύματος, οὐ δύναται εἰσελθεῖν εἰς τὴν Βασιλείαν τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Τὸ γεγεννημένον ἐκ τῆς σαρκὸς, σάρξ ἐστιν, καὶ τὸ γεγεννημένον ἐκ τοῦ  ̊Πνεύματος, πνεῦμά ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Μὴ θαυμάσῃς ὅτι εἶπόν σοι, ‘Δεῖ ὑμᾶς γεννηθῆναι ἄνωθεν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Τὸ πνεῦμα ὅπου θέλει, πνεῖ, καὶ τὴν φωνὴν αὐτοῦ ἀκούεις, ἀλλʼ οὐκ οἶδας πόθεν ἔρχεται, καὶ ποῦ ὑπάγει· οὕτως ἐστὶν πᾶς ὁ γεγεννημένος ἐκ τοῦ  ̊Πνεύματος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Ἀπεκρίθη Νικόδημος καὶ εἶπεν αὐτῷ, “Πῶς δύναται ταῦτα γενέσθαι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Ἀπεκρίθη  ̊Ἰησοῦς καὶ εἶπεν αὐτῷ, “Σὺ εἶ ὁ διδάσκαλος τοῦ Ἰσραὴλ, καὶ ταῦτα οὐ γινώσκεις;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Ἀμὴν, ἀμὴν, λέγω σοι ὅτι ὃ οἴδαμεν λαλοῦμεν, καὶ ὃ ἑωράκαμεν μαρτυροῦμεν, καὶ τὴν μαρτυρίαν ἡμῶν οὐ λαμβάνετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'Εἰ τὰ ἐπίγεια εἶπον ὑμῖν, καὶ οὐ πιστεύετε, πῶς ἐὰν εἴπω ὑμῖν τὰ ἐπουράνια, πιστεύσετε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Καὶ οὐδεὶς ἀναβέβηκεν εἰς τὸν οὐρανὸν, εἰ μὴ ὁ ἐκ τοῦ οὐρανοῦ καταβάς– ὁ Υἱὸς τοῦ Ἀνθρώπου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Καὶ καθὼς Μωϋσῆς ὕψωσεν τὸν ὄφιν ἐν τῇ ἐρήμῳ, οὕτως ὑψωθῆναι δεῖ τὸν Υἱὸν τοῦ Ἀνθρώπου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'ἵνα πᾶς ὁ πιστεύων ἐν αὐτῷ ἔχῃ ζωὴν αἰώνιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, '¶Οὕτως γὰρ ἠγάπησεν ὁ  ̊Θεὸς τὸν κόσμον, ὥστε τὸν Υἱὸν τὸν μονογενῆ ἔδωκεν, ἵνα πᾶς ὁ πιστεύων εἰς αὐτὸν μὴ ἀπόληται, ἀλλʼ ἔχῃ ζωὴν αἰώνιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Οὐ γὰρ ἀπέστειλεν ὁ  ̊Θεὸς τὸν Υἱὸν εἰς τὸν κόσμον, ἵνα κρίνῃ τὸν κόσμον, ἀλλʼ ἵνα σωθῇ ὁ κόσμος διʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Ὁ πιστεύων εἰς αὐτὸν οὐ κρίνεται. Ὁ δὲ μὴ πιστεύων, ἤδη κέκριται, ὅτι μὴ πεπίστευκεν εἰς τὸ ὄνομα τοῦ μονογενοῦς Υἱοῦ τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 19, 'Αὕτη δέ ἐστιν ἡ κρίσις, ὅτι τὸ φῶς ἐλήλυθεν εἰς τὸν κόσμον, καὶ ἠγάπησαν οἱ ἄνθρωποι μᾶλλον τὸ σκότος ἢ τὸ φῶς, ἦν γὰρ αὐτῶν πονηρὰ τὰ ἔργα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 20, 'Πᾶς γὰρ ὁ φαῦλα πράσσων, μισεῖ τὸ φῶς, καὶ οὐκ ἔρχεται πρὸς τὸ φῶς, ἵνα μὴ ἐλεγχθῇ τὰ ἔργα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 21, 'Ὁ δὲ ποιῶν τὴν ἀλήθειαν, ἔρχεται πρὸς τὸ φῶς, ἵνα φανερωθῇ αὐτοῦ τὰ ἔργα, ὅτι ἐν  ̊Θεῷ ἐστιν εἰργασμένα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 22, '¶Μετὰ ταῦτα ἦλθεν ὁ  ̊Ἰησοῦς καὶ οἱ μαθηταὶ αὐτοῦ εἰς τὴν Ἰουδαίαν γῆν, καὶ ἐκεῖ διέτριβεν μετʼ αὐτῶν καὶ ἐβάπτιζεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 23, 'Ἦν δὲ καὶ ὁ Ἰωάννης βαπτίζων ἐν Αἰνὼν ἐγγὺς τοῦ Σαλείμ, ὅτι ὕδατα πολλὰ ἦν ἐκεῖ, καὶ παρεγίνοντο καὶ ἐβαπτίζοντο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 24, 'Οὔπω γὰρ ἦν βεβλημένος εἰς τὴν φυλακὴν ὁ Ἰωάννης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 25, '¶Ἐγένετο οὖν ζήτησις ἐκ τῶν μαθητῶν Ἰωάννου μετὰ Ἰουδαίου περὶ καθαρισμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 26, 'Καὶ ἦλθαν πρὸς τὸν Ἰωάννην καὶ εἶπαν αὐτῷ, “Ῥαββί, ὃς ἦν μετὰ σοῦ πέραν τοῦ Ἰορδάνου, ᾧ σὺ μεμαρτύρηκας, ἴδε, οὗτος βαπτίζει καὶ πάντες ἔρχονται πρὸς αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 27, 'Ἀπεκρίθη Ἰωάννης καὶ εἶπεν, “Οὐ δύναται ἄνθρωπος λαμβάνειν, οὐδὲ ἓν ἐὰν μὴ ᾖ δεδομένον αὐτῷ ἐκ τοῦ οὐρανοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 28, 'Αὐτοὶ ὑμεῖς μοι μαρτυρεῖτε ὅτι εἶπον, ‘Οὐκ εἰμὶ ἐγὼ ὁ  ̊Χριστός’, ἀλλʼ, ὅτι ‘Ἀπεσταλμένος εἰμὶ ἔμπροσθεν ἐκείνου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 29, 'Ὁ ἔχων τὴν νύμφην, νυμφίος ἐστίν· ὁ δὲ φίλος τοῦ νυμφίου, ὁ ἑστηκὼς καὶ ἀκούων αὐτοῦ, χαρᾷ χαίρει διὰ τὴν φωνὴν τοῦ νυμφίου. Αὕτη οὖν ἡ χαρὰ ἡ ἐμὴ πεπλήρωται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 30, 'Ἐκεῖνον δεῖ αὐξάνειν, ἐμὲ δὲ ἐλαττοῦσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 31, '¶Ὁ ἄνωθεν ἐρχόμενος, ἐπάνω πάντων ἐστίν. Ὁ ὢν ἐκ τῆς γῆς, ἐκ τῆς γῆς ἐστιν, καὶ ἐκ τῆς γῆς λαλεῖ. Ὁ ἐκ τοῦ οὐρανοῦ ἐρχόμενος, ἐπάνω πάντων ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 32, 'Ὃ ἑώρακεν καὶ ἤκουσεν, τοῦτο μαρτυρεῖ, καὶ τὴν μαρτυρίαν αὐτοῦ, οὐδεὶς λαμβάνει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 33, 'Ὁ λαβὼν αὐτοῦ τὴν μαρτυρίαν, ἐσφράγισεν ὅτι ὁ  ̊Θεὸς ἀληθής ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 34, 'Ὃν γὰρ ἀπέστειλεν ὁ  ̊Θεὸς, τὰ ῥήματα τοῦ  ̊Θεοῦ λαλεῖ, οὐ γὰρ ἐκ μέτρου δίδωσιν τὸ  ̊Πνεῦμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 35, 'Ὁ Πατὴρ ἀγαπᾷ τὸν Υἱόν, καὶ πάντα δέδωκεν ἐν τῇ χειρὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 36, 'Ὁ πιστεύων εἰς τὸν Υἱὸν, ἔχει ζωὴν αἰώνιον· ὁ δὲ ἀπειθῶν τῷ Υἱῷ, οὐκ ὄψεται ζωήν, ἀλλʼ ἡ ὀργὴ τοῦ  ̊Θεοῦ μένει ἐπʼ αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 1, '¶Ὡς οὖν ἔγνω ὁ  ̊Κύριος ὅτι ἤκουσαν οἱ Φαρισαῖοι ὅτι  ̊Ἰησοῦς πλείονας μαθητὰς ποιεῖ καὶ βαπτίζει ἢ Ἰωάννης');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 2, '(καίτοιγε  ̊Ἰησοῦς αὐτὸς οὐκ ἐβάπτιζεν, ἀλλʼ οἱ μαθηταὶ αὐτοῦ),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 3, 'ἀφῆκεν τὴν Ἰουδαίαν καὶ ἀπῆλθεν πάλιν εἰς τὴν Γαλιλαίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 4, 'Ἔδει δὲ αὐτὸν διέρχεσθαι διὰ τῆς Σαμαρείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 5, 'Ἔρχεται οὖν εἰς πόλιν τῆς Σαμαρείας λεγομένην Συχὰρ, πλησίον τοῦ χωρίου ὃ ἔδωκεν Ἰακὼβ τῷ Ἰωσὴφ, τῷ υἱῷ αὐτοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 6, 'ἦν δὲ ἐκεῖ πηγὴ τοῦ Ἰακώβ. Ὁ οὖν  ̊Ἰησοῦς κεκοπιακὼς ἐκ τῆς ὁδοιπορίας, ἐκαθέζετο οὕτως ἐπὶ τῇ πηγῇ. Ὥρα ἦν ὡς ἕκτη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 7, '¶Ἔρχεται γυνὴ ἐκ τῆς Σαμαρείας ἀντλῆσαι ὕδωρ. Λέγει αὐτῇ ὁ  ̊Ἰησοῦς, “Δός μοι πεῖν”·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 8, 'οἱ γὰρ μαθηταὶ αὐτοῦ ἀπεληλύθεισαν εἰς τὴν πόλιν, ἵνα τροφὰς ἀγοράσωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 9, 'Λέγει οὖν αὐτῷ ἡ γυνὴ ἡ Σαμαρεῖτις, “Πῶς σὺ Ἰουδαῖος ὢν, παρʼ ἐμοῦ πεῖν αἰτεῖς γυναικὸς Σαμαρείτιδος οὔσης;” Οὐ γὰρ συγχρῶνται Ἰουδαῖοι Σαμαρείταις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 10, 'Ἀπεκρίθη  ̊Ἰησοῦς καὶ εἶπεν αὐτῇ, “Εἰ ᾔδεις τὴν δωρεὰν τοῦ  ̊Θεοῦ, καὶ τίς ἐστιν ὁ λέγων σοι, ‘Δός μοι πεῖν’, σὺ ἂν ᾔτησας αὐτὸν, καὶ ἔδωκεν ἄν σοι ὕδωρ ζῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 11, 'Λέγει αὐτῷ ἡ γυνή, “Κύριε, οὔτε ἄντλημα ἔχεις καὶ τὸ φρέαρ ἐστὶν βαθύ· πόθεν οὖν ἔχεις τὸ ὕδωρ τὸ ζῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 12, 'Μὴ σὺ μείζων εἶ τοῦ πατρὸς ἡμῶν Ἰακώβ, ὃς ἔδωκεν ἡμῖν τὸ φρέαρ, καὶ αὐτὸς ἐξ αὐτοῦ ἔπιεν, καὶ οἱ υἱοὶ αὐτοῦ, καὶ τὰ θρέμματα αὐτοῦ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 13, 'Ἀπεκρίθη  ̊Ἰησοῦς καὶ εἶπεν αὐτῇ, “Πᾶς ὁ πίνων ἐκ τοῦ ὕδατος τούτου, διψήσει πάλιν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 14, 'ὃς δʼ ἂν πίῃ ἐκ τοῦ ὕδατος οὗ ἐγὼ δώσω αὐτῷ, οὐ μὴ διψήσει, εἰς τὸν αἰῶνα, ἀλλὰ τὸ ὕδωρ ὃ δώσω αὐτῷ γενήσεται ἐν αὐτῷ πηγὴ ὕδατος, ἁλλομένου εἰς ζωὴν αἰώνιον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 15, 'Λέγει πρὸς αὐτὸν ἡ γυνή, “Κύριε, δός μοι τοῦτο τὸ ὕδωρ, ἵνα μὴ διψῶ, μηδὲ διέρχομαι ἐνθάδε ἀντλεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 16, '¶Λέγει αὐτῇ, “Ὕπαγε, φώνησον τὸν ἄνδρα σου καὶ ἐλθὲ ἐνθάδε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 17, 'Ἀπεκρίθη ἡ γυνὴ καὶ εἶπεν αὐτῷ, “Οὐκ ἔχω ἄνδρα.” Λέγει αὐτῇ ὁ  ̊Ἰησοῦς, “Καλῶς εἶπας, ὅτι ‘Ἄνδρα οὐκ ἔχω’·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 18, 'πέντε γὰρ ἄνδρας ἔσχες, καὶ νῦν ὃν ἔχεις, οὐκ ἔστιν σου ἀνήρ· τοῦτο ἀληθὲς εἴρηκας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 19, 'Λέγει αὐτῷ ἡ γυνή, “Κύριε, θεωρῶ ὅτι προφήτης εἶ σύ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 20, 'Οἱ πατέρες ἡμῶν ἐν τῷ ὄρει τούτῳ προσεκύνησαν, καὶ ὑμεῖς λέγετε ὅτι ἐν Ἱεροσολύμοις ἐστὶν ὁ τόπος ὅπου προσκυνεῖν δεῖ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 21, 'Λέγει αὐτῇ ὁ  ̊Ἰησοῦς, “Πίστευέ μοι, γύναι, ὅτι ἔρχεται ὥρα, ὅτε οὔτε ἐν τῷ ὄρει τούτῳ, οὔτε ἐν Ἱεροσολύμοις, προσκυνήσετε τῷ Πατρί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 22, 'Ὑμεῖς προσκυνεῖτε ὃ οὐκ οἴδατε, ἡμεῖς προσκυνοῦμεν ὃ οἴδαμεν, ὅτι ἡ σωτηρία ἐκ τῶν Ἰουδαίων ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 23, 'Ἀλλὰ ἔρχεται ὥρα καὶ νῦν ἐστιν, ὅτε οἱ ἀληθινοὶ προσκυνηταὶ προσκυνήσουσιν τῷ Πατρὶ ἐν πνεύματι καὶ ἀληθείᾳ, καὶ γὰρ ὁ Πατὴρ τοιούτους ζητεῖ, τοὺς προσκυνοῦντας αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 24, ' ̊Πνεῦμα ὁ  ̊Θεός, καὶ τοὺς προσκυνοῦντας αὐτὸν ἐν πνεύματι καὶ ἀληθείᾳ δεῖ προσκυνεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 25, 'Λέγει αὐτῷ ἡ γυνή, “Οἶδα ὅτι Μεσσίας ἔρχεται, ὁ λεγόμενος ‘ ̊Χριστός’· ὅταν ἔλθῃ ἐκεῖνος, ἀναγγελεῖ ἡμῖν ἅπαντα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 26, 'Λέγει αὐτῇ ὁ  ̊Ἰησοῦς, “Ἐγώ εἰμι, ὁ λαλῶν σοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 27, '¶Καὶ ἐπὶ τούτῳ ἦλθον οἱ μαθηταὶ αὐτοῦ, καὶ ἐθαύμαζον ὅτι μετὰ γυναικὸς ἐλάλει· οὐδεὶς μέντοι εἶπεν, “Τί ζητεῖς;” Ἢ, “Τί λαλεῖς μετʼ αὐτῆς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 28, 'Ἀφῆκεν οὖν τὴν ὑδρίαν αὐτῆς ἡ γυνὴ, καὶ ἀπῆλθεν εἰς τὴν πόλιν, καὶ λέγει τοῖς ἀνθρώποις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 29, '“Δεῦτε, ἴδετε ἄνθρωπον ὃς εἶπέν μοι πάντα ὅσα ἐποίησα· μήτι οὗτός ἐστιν ὁ  ̊Χριστός;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 30, 'Ἐξῆλθον ἐκ τῆς πόλεως, καὶ ἤρχοντο πρὸς αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 31, '¶Ἐν τῷ μεταξὺ ἠρώτων αὐτὸν οἱ μαθηταὶ λέγοντες, “Ῥαββί, φάγε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 32, 'Ὁ δὲ εἶπεν αὐτοῖς, “Ἐγὼ βρῶσιν ἔχω φαγεῖν, ἣν ὑμεῖς οὐκ οἴδατε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 33, 'Ἔλεγον οὖν οἱ μαθηταὶ πρὸς ἀλλήλους, “Μή τις ἤνεγκεν αὐτῷ φαγεῖν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 34, 'Λέγει αὐτοῖς ὁ  ̊Ἰησοῦς, “Ἐμὸν βρῶμά ἐστιν ἵνα ποιήσω τὸ θέλημα τοῦ πέμψαντός με, καὶ τελειώσω αὐτοῦ τὸ ἔργον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 35, 'Οὐχ ὑμεῖς λέγετε, ὅτι ‘Ἔτι τετράμηνός ἐστιν καὶ ὁ θερισμὸς ἔρχεται’; Ἰδοὺ, λέγω ὑμῖν, ἐπάρατε τοὺς ὀφθαλμοὺς ὑμῶν καὶ θεάσασθε τὰς χώρας, ὅτι λευκαί εἰσιν πρὸς θερισμόν ἤδη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 36, 'Ὁ θερίζων μισθὸν, λαμβάνει καὶ συνάγει καρπὸν εἰς ζωὴν αἰώνιον, ἵνα ὁ σπείρων ὁμοῦ χαίρῃ καὶ ὁ θερίζων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 37, 'Ἐν γὰρ τούτῳ ὁ λόγος ἐστὶν ὁ ἀληθινὸς: ὅτι ‘Ἄλλος ἐστὶν ὁ σπείρων, καὶ ἄλλος ὁ θερίζων.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 38, 'Ἐγὼ ἀπέστειλα ὑμᾶς θερίζειν ὃ οὐχ ὑμεῖς κεκοπιάκατε· ἄλλοι κεκοπιάκασιν, καὶ ὑμεῖς εἰς τὸν κόπον αὐτῶν εἰσεληλύθατε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 39, '¶Ἐκ δὲ τῆς πόλεως ἐκείνης, πολλοὶ ἐπίστευσαν εἰς αὐτὸν τῶν Σαμαρειτῶν, διὰ τὸν λόγον τῆς γυναικὸς μαρτυρούσης, ὅτι “Εἶπέν μοι πάντα ἃ ἐποίησα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 40, 'Ὡς οὖν ἦλθον πρὸς αὐτὸν οἱ Σαμαρεῖται, ἠρώτων αὐτὸν μεῖναι παρʼ αὐτοῖς, καὶ ἔμεινεν ἐκεῖ δύο ἡμέρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 41, 'Καὶ πολλῷ πλείους ἐπίστευσαν, διὰ τὸν λόγον αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 42, 'τῇ τε γυναικὶ ἔλεγον, ὅτι “Οὐκέτι διὰ τὴν σὴν λαλιὰν πιστεύομεν· αὐτοὶ γὰρ ἀκηκόαμεν καὶ οἴδαμεν ὅτι οὗτός ἐστιν ἀληθῶς ὁ Σωτὴρ τοῦ κόσμου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 43, '¶Μετὰ δὲ τὰς δύο ἡμέρας, ἐξῆλθεν ἐκεῖθεν εἰς τὴν Γαλιλαίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 44, 'Αὐτὸς γὰρ  ̊Ἰησοῦς ἐμαρτύρησεν ὅτι προφήτης ἐν τῇ ἰδίᾳ πατρίδι, τιμὴν οὐκ ἔχει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 45, 'Ὅτε οὖν ἦλθεν εἰς τὴν Γαλιλαίαν, ἐδέξαντο αὐτὸν οἱ Γαλιλαῖοι, πάντα ἑωρακότες ὅσα ἐποίησεν ἐν Ἱεροσολύμοις ἐν τῇ ἑορτῇ, καὶ αὐτοὶ γὰρ ἦλθον εἰς τὴν ἑορτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 46, '¶Ἦλθεν οὖν πάλιν εἰς τὴν Κανὰ τῆς Γαλιλαίας, ὅπου ἐποίησεν τὸ ὕδωρ οἶνον. Καὶ ἦν τις βασιλικὸς, οὗ ὁ υἱὸς ἠσθένει ἐν Καφαρναούμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 47, 'Οὗτος ἀκούσας ὅτι  ̊Ἰησοῦς ἥκει ἐκ τῆς Ἰουδαίας εἰς τὴν Γαλιλαίαν, ἀπῆλθεν πρὸς αὐτὸν, καὶ ἠρώτα ἵνα καταβῇ, καὶ ἰάσηται αὐτοῦ τὸν υἱόν, ἤμελλεν γὰρ ἀποθνῄσκειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 48, 'Εἶπεν οὖν ὁ  ̊Ἰησοῦς πρὸς αὐτόν, “Ἐὰν μὴ σημεῖα καὶ τέρατα ἴδητε, οὐ μὴ πιστεύσητε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 49, 'Λέγει πρὸς αὐτὸν ὁ βασιλικός, “Κύριε, κατάβηθι πρὶν ἀποθανεῖν τὸ παιδίον μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 50, 'Λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Πορεύου, ὁ υἱός σου ζῇ.” Ἐπίστευσεν ὁ ἄνθρωπος τῷ λόγῳ ὃν εἶπεν αὐτῷ ὁ  ̊Ἰησοῦς, καὶ ἐπορεύετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 51, 'Ἤδη δὲ αὐτοῦ καταβαίνοντος, οἱ δοῦλοι αὐτοῦ ὑπήντησαν αὐτῷ καὶ ἀπήγγειλαν λέγοντες ὅτι ὁ παῖς αὐτοῦ ζῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 52, 'Ἐπύθετο οὖν τὴν ὥραν παρʼ αὐτῶν ἐν ᾗ κομψότερον ἔσχεν. Εἶπον οὖν αὐτῷ, ὅτι “Ἐχθὲς ὥραν ἑβδόμην, ἀφῆκεν αὐτὸν ὁ πυρετός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 53, 'Ἔγνω οὖν ὁ πατὴρ ὅτι ἐκείνῃ τῇ ὥρᾳ ἐν ᾗ εἶπεν αὐτῷ ὁ  ̊Ἰησοῦς, “Ὁ υἱός σου ζῇ”, καὶ ἐπίστευσεν αὐτὸς καὶ ἡ οἰκία αὐτοῦ ὅλη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 54, 'Τοῦτο δὲ πάλιν δεύτερον σημεῖον ἐποίησεν ὁ  ̊Ἰησοῦς, ἐλθὼν ἐκ τῆς Ἰουδαίας εἰς τὴν Γαλιλαίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 1, '¶Μετὰ ταῦτα ἦν ἑορτὴ τῶν Ἰουδαίων, καὶ ἀνέβη  ̊Ἰησοῦς εἰς Ἱεροσόλυμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 2, 'Ἔστιν δὲ ἐν τοῖς Ἱεροσολύμοις ἐπὶ τῇ Προβατικῇ κολυμβήθρα, ἡ ἐπιλεγομένη Ἑβραϊστὶ, Βηθσαϊδά, πέντε στοὰς ἔχουσα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 3, 'Ἐν ταύταις κατέκειτο πλῆθος τῶν ἀσθενούντων, τυφλῶν, χωλῶν, ξηρῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 4, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 5, 'Ἦν δέ τις ἄνθρωπος ἐκεῖ, τριάκοντα ὀκτὼ ἔτη ἔχων ἐν τῇ ἀσθενείᾳ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 6, 'Τοῦτον ἰδὼν ὁ  ̊Ἰησοῦς κατακείμενον, καὶ γνοὺς ὅτι πολὺν ἤδη χρόνον ἔχει, λέγει αὐτῷ, “Θέλεις ὑγιὴς γενέσθαι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 7, 'Ἀπεκρίθη αὐτῷ ὁ ἀσθενῶν, “Κύριε, ἄνθρωπον οὐκ ἔχω, ἵνα ὅταν ταραχθῇ τὸ ὕδωρ, βάλῃ με εἰς τὴν κολυμβήθραν· ἐν ᾧ δὲ ἔρχομαι ἐγὼ, ἄλλος πρὸ ἐμοῦ καταβαίνει.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 8, 'Λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Ἔγειρε, ἆρον τὸν κράβαττόν σου, καὶ περιπάτει.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 9, 'Καὶ εὐθέως ἐγένετο ὑγιὴς ὁ ἄνθρωπος, καὶ ἦρεν τὸν κράβαττον αὐτοῦ, καὶ περιεπάτει. ¶Ἦν δὲ Σάββατον ἐν ἐκείνῃ τῇ ἡμέρᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 10, 'Ἔλεγον οὖν οἱ Ἰουδαῖοι τῷ τεθεραπευμένῳ, “Σάββατόν ἐστιν, καὶ οὐκ ἔξεστίν σοι ἆραι τὸν κράβαττον σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 11, 'ὃς δὲ ἀπεκρίθη αὐτοῖς, “Ὁ ποιήσας με ὑγιῆ, ἐκεῖνός μοι εἶπεν, ‘Ἆρον τὸν κράβαττόν σου καὶ περιπάτει.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 12, 'Ἠρώτησαν αὐτόν, “Τίς ἐστιν ὁ ἄνθρωπος ὁ εἰπών σοι, ‘Ἆρον καὶ περιπάτει’;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 13, 'Ὁ δὲ ἰαθεὶς οὐκ ᾔδει τίς ἐστιν, ὁ γὰρ  ̊Ἰησοῦς ἐξένευσεν, ὄχλου ὄντος ἐν τῷ τόπῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 14, 'Μετὰ ταῦτα εὑρίσκει αὐτὸν ὁ  ̊Ἰησοῦς ἐν τῷ ἱερῷ, καὶ εἶπεν αὐτῷ, “Ἴδε, ὑγιὴς γέγονας· μηκέτι ἁμάρτανε, ἵνα μὴ χεῖρόν σοί τι γένηται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 15, 'Ἀπῆλθεν ὁ ἄνθρωπος, καὶ ἀνήγγειλεν τοῖς Ἰουδαίοις ὅτι  ̊Ἰησοῦς ἐστιν ὁ ποιήσας αὐτὸν ὑγιῆ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 16, 'Καὶ διὰ τοῦτο, ἐδίωκον οἱ Ἰουδαῖοι τὸν  ̊Ἰησοῦν, ὅτι ταῦτα ἐποίει ἐν Σαββάτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 17, 'Ὁ δὲ ἀπεκρίνατο αὐτοῖς, “Ὁ Πατήρ μου ἕως ἄρτι ἐργάζεται, κἀγὼ ἐργάζομαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 18, 'Διὰ τοῦτο οὖν, μᾶλλον ἐζήτουν αὐτὸν οἱ Ἰουδαῖοι ἀποκτεῖναι, ὅτι οὐ μόνον ἔλυε τὸ Σάββατον, ἀλλὰ καὶ Πατέρα ἴδιον ἔλεγεν τὸν  ̊Θεόν, ἴσον ἑαυτὸν ποιῶν τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 19, '¶Ἀπεκρίνατο οὖν ὁ  ̊Ἰησοῦς καὶ ἔλεγεν αὐτοῖς, “Ἀμὴν, ἀμὴν, λέγω ὑμῖν, οὐ δύναται ὁ Υἱὸς ποιεῖν ἀφʼ ἑαυτοῦ οὐδὲν, ἐὰν μή τι βλέπῃ τὸν Πατέρα ποιοῦντα· ἃ γὰρ ἂν ἐκεῖνος ποιῇ, ταῦτα καὶ ὁ Υἱὸς ὁμοίως ποιεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 20, 'Ὁ γὰρ Πατὴρ φιλεῖ τὸν Υἱὸν, καὶ πάντα δείκνυσιν αὐτῷ ἃ αὐτὸς ποιεῖ, καὶ μείζονα τούτων δείξει αὐτῷ ἔργα, ἵνα ὑμεῖς θαυμάζητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 21, 'Ὥσπερ γὰρ ὁ Πατὴρ ἐγείρει τοὺς νεκροὺς καὶ ζῳοποιεῖ, οὕτως καὶ ὁ Υἱὸς, οὓς θέλει ζῳοποιεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 22, 'Οὐδὲ γὰρ ὁ Πατὴρ κρίνει οὐδένα, ἀλλὰ τὴν κρίσιν πᾶσαν δέδωκεν τῷ Υἱῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 23, 'ἵνα πάντες τιμῶσι τὸν Υἱὸν, καθὼς τιμῶσι τὸν Πατέρα. Ὁ μὴ τιμῶν τὸν Υἱὸν, οὐ τιμᾷ τὸν Πατέρα, τὸν πέμψαντα αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 24, 'Ἀμὴν, ἀμὴν, λέγω ὑμῖν ὅτι ὁ τὸν λόγον μου ἀκούων, καὶ πιστεύων τῷ πέμψαντί με, ἔχει ζωὴν αἰώνιον, καὶ εἰς κρίσιν οὐκ ἔρχεται, ἀλλὰ μεταβέβηκεν ἐκ τοῦ θανάτου εἰς τὴν ζωήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 25, '¶Ἀμὴν, ἀμὴν, λέγω ὑμῖν ὅτι ἔρχεται ὥρα καὶ νῦν ἐστιν, ὅτε οἱ νεκροὶ ἀκούσουσιν τῆς φωνῆς τοῦ Υἱοῦ τοῦ  ̊Θεοῦ, καὶ οἱ ἀκούσαντες ζήσουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 26, 'Ὥσπερ γὰρ ὁ Πατὴρ ἔχει ζωὴν ἐν ἑαυτῷ, οὕτως καὶ τῷ Υἱῷ ἔδωκεν ζωὴν ἔχειν ἐν ἑαυτῷ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 27, 'καὶ ἐξουσίαν ἔδωκεν αὐτῷ κρίσιν ποιεῖν, ὅτι Υἱὸς Ἀνθρώπου ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 28, 'Μὴ θαυμάζετε τοῦτο, ὅτι ἔρχεται ὥρα ἐν ᾗ πάντες οἱ ἐν τοῖς μνημείοις ἀκούσουσιν τῆς φωνῆς αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 29, 'καὶ ἐκπορεύσονται, οἱ τὰ ἀγαθὰ ποιήσαντες, εἰς ἀνάστασιν ζωῆς, οἱ δὲ τὰ φαῦλα πράξαντες, εἰς ἀνάστασιν κρίσεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 30, '¶Οὐ δύναμαι ἐγὼ ποιεῖν ἀπʼ ἐμαυτοῦ οὐδέν· καθὼς ἀκούω, κρίνω, καὶ ἡ κρίσις ἡ ἐμὴ δικαία ἐστίν, ὅτι οὐ ζητῶ τὸ θέλημα τὸ ἐμὸν, ἀλλὰ τὸ θέλημα τοῦ πέμψαντός με.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 31, '¶Ἐὰν ἐγὼ μαρτυρῶ περὶ ἐμαυτοῦ, ἡ μαρτυρία μου οὐκ ἔστιν ἀληθής.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 32, 'Ἄλλος ἐστὶν ὁ μαρτυρῶν περὶ ἐμοῦ, καὶ οἶδα ὅτι ἀληθής ἐστιν ἡ μαρτυρία ἣν μαρτυρεῖ περὶ ἐμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 33, 'Ὑμεῖς ἀπεστάλκατε πρὸς Ἰωάννην, καὶ μεμαρτύρηκεν τῇ ἀληθείᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 34, 'Ἐγὼ δὲ οὐ παρὰ ἀνθρώπου τὴν μαρτυρίαν λαμβάνω, ἀλλὰ ταῦτα λέγω, ἵνα ὑμεῖς σωθῆτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 35, 'Ἐκεῖνος ἦν ὁ λύχνος ὁ καιόμενος καὶ φαίνων, ὑμεῖς δὲ ἠθελήσατε ἀγαλλιαθῆναι πρὸς ὥραν ἐν τῷ φωτὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 36, 'Ἐγὼ δὲ ἔχω τὴν μαρτυρίαν μείζων τοῦ Ἰωάννου, τὰ γὰρ ἔργα ἃ δέδωκέν μοι ὁ Πατὴρ, ἵνα τελειώσω αὐτά, αὐτὰ τὰ ἔργα ἃ ποιῶ, μαρτυρεῖ περὶ ἐμοῦ ὅτι ὁ Πατήρ με ἀπέσταλκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 37, 'Καὶ ὁ πέμψας με Πατὴρ, ἐκεῖνος μεμαρτύρηκεν περὶ ἐμοῦ. Οὔτε φωνὴν αὐτοῦ πώποτε ἀκηκόατε, οὔτε εἶδος αὐτοῦ ἑωράκατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 38, 'Καὶ τὸν λόγον αὐτοῦ οὐκ ἔχετε ἐν ὑμῖν μένοντα, ὅτι ὃν ἀπέστειλεν ἐκεῖνος, τούτῳ ὑμεῖς οὐ πιστεύετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 39, '¶Ἐραυνᾶτε τὰς Γραφάς, ὅτι ὑμεῖς δοκεῖτε ἐν αὐταῖς ζωὴν αἰώνιον ἔχειν, καὶ ἐκεῖναί εἰσιν αἱ μαρτυροῦσαι περὶ ἐμοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 40, 'καὶ οὐ θέλετε ἐλθεῖν πρός με, ἵνα ζωὴν ἔχητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 41, 'Δόξαν παρὰ ἀνθρώπων οὐ λαμβάνω,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 42, 'ἀλλὰ ἔγνωκα ὑμᾶς ὅτι τὴν ἀγάπην τοῦ  ̊Θεοῦ οὐκ ἔχετε ἐν ἑαυτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 43, 'Ἐγὼ ἐλήλυθα ἐν τῷ ὀνόματι τοῦ Πατρός μου, καὶ οὐ λαμβάνετέ με· ἐὰν ἄλλος ἔλθῃ ἐν τῷ ὀνόματι τῷ ἰδίῳ, ἐκεῖνον λήμψεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 44, 'Πῶς δύνασθε ὑμεῖς πιστεῦσαι, δόξαν παρὰ ἀλλήλων λαμβάνοντες, καὶ τὴν δόξαν τὴν παρὰ τοῦ μόνου  ̊Θεοῦ, οὐ ζητεῖτε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 45, 'Μὴ δοκεῖτε ὅτι ἐγὼ κατηγορήσω ὑμῶν πρὸς τὸν Πατέρα. Ἔστιν ὁ κατηγορῶν ὑμῶν Μωϋσῆς, εἰς ὃν ὑμεῖς ἠλπίκατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 46, 'Εἰ γὰρ ἐπιστεύετε Μωϋσεῖ, ἐπιστεύετε ἂν ἐμοί, περὶ γὰρ ἐμοῦ ἐκεῖνος ἔγραψεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 47, 'Εἰ δὲ τοῖς ἐκείνου γράμμασιν οὐ πιστεύετε, πῶς τοῖς ἐμοῖς ῥήμασιν πιστεύσετε;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 1, '¶Μετὰ ταῦτα, ἀπῆλθεν ὁ  ̊Ἰησοῦς πέραν τῆς θαλάσσης τῆς Γαλιλαίας τῆς Τιβεριάδος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 2, 'Ἠκολούθει δὲ αὐτῷ ὄχλος πολύς, ὅτι ἐθεώρων τὰ σημεῖα ἃ ἐποίει ἐπὶ τῶν ἀσθενούντων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 3, 'Ἀνῆλθεν δὲ εἰς τὸ ὄρος  ̊Ἰησοῦς, καὶ ἐκεῖ ἐκάθητο μετὰ τῶν μαθητῶν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 4, 'Ἦν δὲ ἐγγὺς τὸ Πάσχα, ἡ ἑορτὴ τῶν Ἰουδαίων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 5, 'Ἐπάρας οὖν τοὺς ὀφθαλμοὺς ὁ  ̊Ἰησοῦς, καὶ θεασάμενος ὅτι πολὺς ὄχλος ἔρχεται πρὸς αὐτὸν, λέγει πρὸς Φίλιππον, “Πόθεν ἀγοράσωμεν ἄρτους, ἵνα φάγωσιν οὗτοι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 6, 'Τοῦτο δὲ ἔλεγεν πειράζων αὐτόν, αὐτὸς γὰρ ᾔδει τί ἔμελλεν ποιεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 7, 'Ἀπεκρίθη αὐτῷ Φίλιππος, “Διακοσίων δηναρίων ἄρτοι οὐκ ἀρκοῦσιν αὐτοῖς, ἵνα ἕκαστος βραχύ λάβῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 8, 'Λέγει αὐτῷ εἷς ἐκ τῶν μαθητῶν αὐτοῦ, Ἀνδρέας ὁ ἀδελφὸς Σίμωνος Πέτρου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 9, '“Ἔστιν παιδάριον ὧδε, ὃς ἔχει πέντε ἄρτους κριθίνους καὶ δύο ὀψάρια, ἀλλὰ ταῦτα τί ἐστιν εἰς τοσούτους;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 10, 'Εἶπεν ὁ  ̊Ἰησοῦς, “Ποιήσατε τοὺς ἀνθρώπους ἀναπεσεῖν.” Ἦν δὲ χόρτος πολὺς ἐν τῷ τόπῳ. Ἀνέπεσαν οὖν οἱ ἄνδρες, τὸν ἀριθμὸν ὡς πεντακισχίλιοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 11, 'Ἔλαβεν οὖν τοὺς ἄρτους ὁ  ̊Ἰησοῦς, καὶ εὐχαριστήσας, διέδωκεν τοῖς ἀνακειμένοις, ὁμοίως καὶ ἐκ τῶν ὀψαρίων, ὅσον ἤθελον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 12, 'Ὡς δὲ ἐνεπλήσθησαν, λέγει τοῖς μαθηταῖς αὐτοῦ, “Συναγάγετε τὰ περισσεύσαντα κλάσματα, ἵνα μή τι ἀπόληται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 13, 'Συνήγαγον οὖν καὶ ἐγέμισαν δώδεκα κοφίνους κλασμάτων ἐκ τῶν πέντε ἄρτων τῶν κριθίνων, ἃ ἐπερίσσευσαν τοῖς βεβρωκόσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 14, 'Οἱ οὖν ἄνθρωποι ἰδόντες ἃ ἐποίησεν σημεῖα ἔλεγον, ὅτι “Οὗτός ἐστιν ἀληθῶς ὁ προφήτης ὁ ἐρχόμενος εἰς τὸν κόσμον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 15, '¶ ̊Ἰησοῦς οὖν γνοὺς ὅτι μέλλουσιν ἔρχεσθαι καὶ ἁρπάζειν αὐτὸν, ἵνα ποιήσωσιν βασιλέα, ἀνεχώρησεν πάλιν εἰς τὸ ὄρος αὐτὸς μόνος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 16, '¶Ὡς δὲ ὀψία ἐγένετο, κατέβησαν οἱ μαθηταὶ αὐτοῦ ἐπὶ τὴν θάλασσαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 17, 'καὶ ἐμβάντες εἰς πλοῖον, ἤρχοντο πέραν τῆς θαλάσσης εἰς Καφαρναούμ. Καὶ σκοτία ἤδη ἐγεγόνει, καὶ οὔπω πρὸς αὐτοὺς ἐληλύθει ὁ  ̊Ἰησοῦς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 18, 'Ἥ τε θάλασσα ἀνέμου μεγάλου πνέοντος διηγείρετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 19, 'Ἐληλακότες οὖν ὡς σταδίους εἴκοσι πέντε ἢ τριάκοντα, θεωροῦσιν τὸν  ̊Ἰησοῦν περιπατοῦντα ἐπὶ τῆς θαλάσσης, καὶ ἐγγὺς τοῦ πλοίου γινόμενον, καὶ ἐφοβήθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 20, 'Ὁ δὲ λέγει αὐτοῖς, “Ἐγώ εἰμι, μὴ φοβεῖσθε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 21, 'Ἤθελον οὖν λαβεῖν αὐτὸν εἰς τὸ πλοῖον, καὶ εὐθέως ἐγένετο τὸ πλοῖον ἐπὶ τῆς γῆς εἰς ἣν ὑπῆγον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 22, '¶Τῇ ἐπαύριον ὁ ὄχλος ὁ ἑστηκὼς πέραν τῆς θαλάσσης, εἶδον ὅτι πλοιάριον ἄλλο οὐκ ἦν ἐκεῖ εἰ μὴ ἕν, καὶ ὅτι οὐ συνεισῆλθεν τοῖς μαθηταῖς αὐτοῦ ὁ  ̊Ἰησοῦς εἰς τὸ πλοῖον, ἀλλὰ μόνοι οἱ μαθηταὶ αὐτοῦ ἀπῆλθον·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 23, 'ἄλλα ἦλθεν πλοῖα ἐκ Τιβεριάδος, ἐγγὺς τοῦ τόπου ὅπου ἔφαγον τὸν ἄρτον, εὐχαριστήσαντος τοῦ  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 24, 'Ὅτε οὖν εἶδεν ὁ ὄχλος ὅτι  ̊Ἰησοῦς οὐκ ἔστιν ἐκεῖ, οὐδὲ οἱ μαθηταὶ αὐτοῦ, ἐνέβησαν αὐτοὶ εἰς τὰ πλοιάρια, καὶ ἦλθον εἰς Καφαρναοὺμ ζητοῦντες τὸν  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 25, '¶Καὶ εὑρόντες αὐτὸν πέραν τῆς θαλάσσης, εἶπον αὐτῷ, “Ῥαββί, πότε ὧδε γέγονας;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 26, 'Ἀπεκρίθη αὐτοῖς ὁ  ̊Ἰησοῦς καὶ εἶπεν, “Ἀμὴν, ἀμὴν, λέγω ὑμῖν, ζητεῖτέ με, οὐχ ὅτι εἴδετε σημεῖα, ἀλλʼ ὅτι ἐφάγετε ἐκ τῶν ἄρτων καὶ ἐχορτάσθητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 27, 'Ἐργάζεσθε μὴ τὴν βρῶσιν τὴν ἀπολλυμένην, ἀλλὰ τὴν βρῶσιν τὴν μένουσαν εἰς ζωὴν αἰώνιον, ἣν ὁ Υἱὸς τοῦ Ἀνθρώπου ὑμῖν δώσει, τοῦτον γὰρ ὁ Πατὴρ ἐσφράγισεν ὁ  ̊Θεός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 28, 'Εἶπον οὖν πρὸς αὐτόν, “Τί ποιῶμεν, ἵνα ἐργαζώμεθα τὰ ἔργα τοῦ  ̊Θεοῦ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 29, 'Ἀπεκρίθη ὁ  ̊Ἰησοῦς καὶ εἶπεν αὐτοῖς, “Τοῦτό ἐστιν τὸ ἔργον τοῦ  ̊Θεοῦ, ἵνα πιστεύητε εἰς ὃν ἀπέστειλεν ἐκεῖνος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 30, 'Εἶπον οὖν αὐτῷ, “Τί οὖν ποιεῖς σὺ σημεῖον, ἵνα ἴδωμεν καὶ πιστεύσωμέν σοι; Τί ἐργάζῃ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 31, 'Οἱ πατέρες ἡμῶν τὸ μάννα ἔφαγον ἐν τῇ ἐρήμῳ, καθώς ἐστιν γεγραμμένον, ‘Ἄρτον ἐκ τοῦ οὐρανοῦ ἔδωκεν αὐτοῖς φαγεῖν.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 32, 'Εἶπεν οὖν αὐτοῖς ὁ  ̊Ἰησοῦς, “Ἀμὴν, ἀμὴν, λέγω ὑμῖν, οὐ Μωϋσῆς δέδωκεν ὑμῖν τὸν ἄρτον ἐκ τοῦ οὐρανοῦ, ἀλλʼ ὁ Πατήρ μου δίδωσιν ὑμῖν τὸν ἄρτον ἐκ τοῦ οὐρανοῦ τὸν ἀληθινόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 33, 'Ὁ γὰρ ἄρτος τοῦ  ̊Θεοῦ ἐστιν ὁ καταβαίνων ἐκ τοῦ οὐρανοῦ, καὶ ζωὴν διδοὺς τῷ κόσμῳ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 34, 'Εἶπον οὖν πρὸς αὐτόν, “Κύριε, πάντοτε δὸς ἡμῖν τὸν ἄρτον τοῦτον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 35, '¶Εἶπεν αὐτοῖς ὁ  ̊Ἰησοῦς, “Ἐγώ εἰμι ὁ ἄρτος τῆς ζωῆς· ὁ ἐρχόμενος πρὸς ἐμὲ, οὐ μὴ πεινάσῃ, καὶ ὁ πιστεύων εἰς ἐμὲ, οὐ μὴ διψήσει πώποτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 36, 'Ἀλλʼ εἶπον ὑμῖν ὅτι καὶ ἑωράκατέ με καὶ οὐ πιστεύετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 37, 'Πᾶν ὃ δίδωσίν μοι ὁ Πατὴρ, πρὸς ἐμὲ ἥξει, καὶ τὸν ἐρχόμενον πρός ἐμὲ, οὐ μὴ ἐκβάλω ἔξω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 38, 'Ὅτι καταβέβηκα ἀπὸ τοῦ οὐρανοῦ, οὐχ ἵνα ποιῶ τὸ θέλημα τὸ ἐμὸν, ἀλλὰ τὸ θέλημα τοῦ πέμψαντός με.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 39, 'Τοῦτο δέ ἐστιν τὸ θέλημα τοῦ πέμψαντός με, ἵνα πᾶν ὃ δέδωκέν μοι, μὴ ἀπολέσω ἐξ αὐτοῦ, ἀλλὰ ἀναστήσω αὐτὸ τῇ ἐσχάτῃ ἡμέρᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 40, 'Τοῦτο γάρ ἐστιν τὸ θέλημα τοῦ Πατρός μου, ἵνα πᾶς ὁ θεωρῶν τὸν Υἱὸν καὶ πιστεύων εἰς αὐτὸν, ἔχῃ ζωὴν αἰώνιον, καὶ ἀναστήσω αὐτὸν ἐγὼ τῇ ἐσχάτῃ ἡμέρᾳ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 41, '¶Ἐγόγγυζον οὖν οἱ Ἰουδαῖοι περὶ αὐτοῦ, ὅτι εἶπεν, “Ἐγώ εἰμι ὁ ἄρτος ὁ καταβὰς ἐκ τοῦ οὐρανοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 42, 'Καὶ ἔλεγον, “Οὐχ οὗτός ἐστιν  ̊Ἰησοῦς ὁ υἱὸς Ἰωσήφ, οὗ ἡμεῖς οἴδαμεν τὸν πατέρα καὶ τὴν μητέρα; Πῶς νῦν λέγει, ὅτι ‘Ἐκ τοῦ οὐρανοῦ καταβέβηκα’;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 43, 'Ἀπεκρίθη  ̊Ἰησοῦς καὶ εἶπεν αὐτοῖς, “Μὴ γογγύζετε μετʼ ἀλλήλων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 44, 'Οὐδεὶς δύναται ἐλθεῖν πρός με, ἐὰν μὴ ὁ Πατὴρ, ὁ πέμψας με, ἑλκύσῃ αὐτόν, κἀγὼ ἀναστήσω αὐτὸν τῇ ἐσχάτῃ ἡμέρᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 45, 'Ἔστιν γεγραμμένον ἐν τοῖς προφήταις, ‘Καὶ ἔσονται πάντες διδακτοὶ  ̊Θεοῦ.’ Πᾶς ὁ ἀκούσας παρὰ τοῦ Πατρὸς καὶ μαθὼν, ἔρχεται πρὸς με.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 46, 'Οὐχ ὅτι τὸν Πατέρα ἑώρακέν τις, εἰ μὴ ὁ ὢν παρὰ τοῦ  ̊Θεοῦ, οὗτος ἑώρακεν τὸν Πατέρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 47, 'Ἀμὴν, ἀμὴν, λέγω ὑμῖν, ὁ πιστεύων ἔχει ζωὴν αἰώνιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 48, 'Ἐγώ εἰμι ὁ ἄρτος τῆς ζωῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 49, 'Οἱ πατέρες ὑμῶν ἔφαγον ἐν τῇ ἐρήμῳ τὸ μάννα, καὶ ἀπέθανον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 50, 'Οὗτός ἐστιν ὁ ἄρτος ὁ ἐκ τοῦ οὐρανοῦ καταβαίνων, ἵνα τις ἐξ αὐτοῦ φάγῃ, καὶ μὴ ἀποθάνῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 51, 'Ἐγώ εἰμι ὁ ἄρτος ὁ ζῶν ὁ ἐκ τοῦ οὐρανοῦ καταβάς· ἐάν τις φάγῃ ἐκ τούτου τοῦ ἄρτου, ζήσεται εἰς τὸν αἰῶνα. Καὶ ὁ ἄρτος δὲ ὃν ἐγὼ δώσω, ἡ σάρξ μού ἐστιν ὑπὲρ τῆς τοῦ κόσμου ζωῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 52, '¶Ἐμάχοντο οὖν πρὸς ἀλλήλους οἱ Ἰουδαῖοι λέγοντες, “Πῶς δύναται οὗτος ἡμῖν δοῦναι τὴν σάρκα αὐτοῦ φαγεῖν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 53, 'Εἶπεν οὖν αὐτοῖς ὁ  ̊Ἰησοῦς, “Ἀμὴν, ἀμὴν, λέγω ὑμῖν, ἐὰν μὴ φάγητε τὴν σάρκα τοῦ Υἱοῦ τοῦ Ἀνθρώπου, καὶ πίητε αὐτοῦ τὸ αἷμα, οὐκ ἔχετε ζωὴν ἐν ἑαυτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 54, 'Ὁ τρώγων μου τὴν σάρκα, καὶ πίνων μου τὸ αἷμα, ἔχει ζωὴν αἰώνιον, κἀγὼ ἀναστήσω αὐτὸν τῇ ἐσχάτῃ ἡμέρᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 55, 'Ἡ γὰρ σάρξ μου ἀληθής ἐστιν βρῶσις, καὶ τὸ αἷμά μου ἀληθής ἐστιν πόσις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 56, 'Ὁ τρώγων μου τὴν σάρκα, καὶ πίνων μου τὸ αἷμα, ἐν ἐμοὶ μένει, κἀγὼ ἐν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 57, 'Καθὼς ἀπέστειλέν με ὁ ζῶν Πατὴρ, κἀγὼ ζῶ διὰ τὸν Πατέρα, καὶ ὁ τρώγων με, κἀκεῖνος ζήσει διʼ ἐμέ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 58, 'Οὗτός ἐστιν ὁ ἄρτος ὁ ἐξ οὐρανοῦ καταβάς, οὐ καθὼς ἔφαγον οἱ πατέρες καὶ ἀπέθανον· ὁ τρώγων τοῦτον τὸν ἄρτον ζήσει εἰς τὸν αἰῶνα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 59, 'Ταῦτα εἶπεν ἐν συναγωγῇ, διδάσκων ἐν Καφαρναούμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 60, '¶Πολλοὶ οὖν ἀκούσαντες ἐκ τῶν μαθητῶν αὐτοῦ εἶπον, “Σκληρός ἐστιν ὁ λόγος οὗτος· τίς δύναται αὐτοῦ ἀκούειν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 61, 'Εἰδὼς δὲ ὁ  ̊Ἰησοῦς ἐν ἑαυτῷ ὅτι γογγύζουσιν περὶ τούτου οἱ μαθηταὶ αὐτοῦ, εἶπεν αὐτοῖς, “Τοῦτο ὑμᾶς σκανδαλίζει;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 62, 'Ἐὰν οὖν θεωρῆτε τὸν Υἱὸν τοῦ Ἀνθρώπου, ἀναβαίνοντα ὅπου ἦν τὸ πρότερον;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 63, 'Τὸ  ̊Πνεῦμά ἐστιν τὸ ζῳοποιοῦν, ἡ σὰρξ οὐκ ὠφελεῖ οὐδέν. Τὰ ῥήματα ἃ ἐγὼ λελάληκα ὑμῖν πνεῦμά ἐστιν καὶ ζωή ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 64, 'Ἀλλʼ εἰσὶν ἐξ ὑμῶν τινες, οἳ οὐ πιστεύουσιν.” ἬΙδει γὰρ ἐξ ἀρχῆς ὁ  ̊Ἰησοῦς, τίνες εἰσὶν οἱ μὴ πιστεύοντες, καὶ τίς ἐστιν ὁ παραδώσων αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 65, 'Καὶ ἔλεγεν, “Διὰ τοῦτο εἴρηκα ὑμῖν ὅτι οὐδεὶς δύναται ἐλθεῖν πρός με, ἐὰν μὴ ᾖ δεδομένον αὐτῷ ἐκ τοῦ Πατρός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 66, '¶Ἐκ τούτου πολλοὶ ἐκ τῶν μαθητῶν αὐτοῦ ἀπῆλθον εἰς τὰ ὀπίσω, καὶ οὐκέτι μετʼ αὐτοῦ περιεπάτουν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 67, 'Εἶπεν οὖν ὁ  ̊Ἰησοῦς τοῖς δώδεκα, “Μὴ καὶ ὑμεῖς θέλετε ὑπάγειν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 68, 'Ἀπεκρίθη αὐτῷ Σίμων Πέτρος, “ ̊Κύριε, πρὸς τίνα ἀπελευσόμεθα; Ῥήματα ζωῆς αἰωνίου ἔχεις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 69, 'Καὶ ἡμεῖς πεπιστεύκαμεν καὶ ἐγνώκαμεν ὅτι σὺ εἶ ὁ Ἅγιος τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 70, 'Ἀπεκρίθη αὐτοῖς ὁ  ̊Ἰησοῦς, “Οὐκ ἐγὼ ὑμᾶς τοὺς δώδεκα ἐξελεξάμην, καὶ ἐξ ὑμῶν εἷς διάβολός ἐστιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 71, 'Ἔλεγεν δὲ τὸν Ἰούδαν Σίμωνος Ἰσκαριώτου· οὗτος γὰρ ἔμελλεν παραδιδόναι αὐτόν, εἷς ἐκ τῶν δώδεκα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 1, '¶Καὶ μετὰ ταῦτα, περιεπάτει ὁ  ̊Ἰησοῦς ἐν τῇ Γαλιλαίᾳ, οὐ γὰρ ἤθελεν ἐν τῇ Ἰουδαίᾳ περιπατεῖν, ὅτι ἐζήτουν αὐτὸν οἱ Ἰουδαῖοι ἀποκτεῖναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 2, 'Ἦν δὲ ἐγγὺς ἡ ἑορτὴ τῶν Ἰουδαίων ἡ σκηνοπηγία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 3, 'Εἶπον οὖν πρὸς αὐτὸν οἱ ἀδελφοὶ αὐτοῦ, “Μετάβηθι ἐντεῦθεν, καὶ ὕπαγε εἰς τὴν Ἰουδαίαν, ἵνα καὶ οἱ μαθηταί σου θεωρήσουσιν σοῦ τὰ ἔργα ἃ ποιεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 4, 'Οὐδεὶς γάρ τι ἐν κρυπτῷ ποιεῖ καὶ ζητεῖ αὐτὸς ἐν παρρησίᾳ εἶναι.” Εἰ ταῦτα ποιεῖς, φανέρωσον σεαυτὸν τῷ κόσμῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 5, 'Οὐδὲ γὰρ οἱ ἀδελφοὶ αὐτοῦ ἐπίστευον εἰς αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 6, 'Λέγει οὖν αὐτοῖς ὁ  ̊Ἰησοῦς, “Ὁ καιρὸς ὁ ἐμὸς οὔπω πάρεστιν, ὁ δὲ καιρὸς ὁ ὑμέτερος πάντοτέ ἐστιν ἕτοιμος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 7, 'Οὐ δύναται ὁ κόσμος μισεῖν ὑμᾶς, ἐμὲ δὲ μισεῖ, ὅτι ἐγὼ μαρτυρῶ περὶ αὐτοῦ ὅτι τὰ ἔργα αὐτοῦ πονηρά ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 8, 'Ὑμεῖς ἀνάβητε εἰς τὴν ἑορτήν· ἐγὼ οὔπω ἀναβαίνω εἰς τὴν ἑορτὴν ταύτην, ὅτι ὁ ἐμὸς καιρὸς οὔπω πεπλήρωται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 9, 'Ταῦτα δὲ εἰπὼν αὐτοῖς ἔμεινεν ἐν τῇ Γαλιλαίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 10, '¶Ὡς δὲ ἀνέβησαν οἱ ἀδελφοὶ αὐτοῦ εἰς τὴν ἑορτήν, τότε καὶ αὐτὸς ἀνέβη, οὐ φανερῶς, ἀλλʼ ὡς ἐν κρυπτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 11, 'Οἱ οὖν Ἰουδαῖοι ἐζήτουν αὐτὸν ἐν τῇ ἑορτῇ, καὶ ἔλεγον, “Ποῦ ἐστιν ἐκεῖνος;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 12, 'Καὶ γογγυσμὸς περὶ αὐτοῦ ἦν πολὺς ἐν τοῖς ὄχλοις. Οἱ μὲν ἔλεγον, ὅτι “Ἀγαθός ἐστιν”, ἄλλοι δὲ ἔλεγον, “Οὔ, ἀλλὰ πλανᾷ τὸν ὄχλον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 13, 'Οὐδεὶς μέντοι παρρησίᾳ ἐλάλει περὶ αὐτοῦ, διὰ τὸν φόβον τῶν Ἰουδαίων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 14, '¶Ἤδη δὲ τῆς ἑορτῆς μεσούσης, ἀνέβη  ̊Ἰησοῦς εἰς τὸ ἱερὸν καὶ ἐδίδασκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 15, 'Ἐθαύμαζον οὖν οἱ Ἰουδαῖοι λέγοντες, “Πῶς οὗτος γράμματα οἶδεν, μὴ μεμαθηκώς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 16, 'Ἀπεκρίθη οὖν αὐτοῖς  ̊Ἰησοῦς καὶ εἶπεν, “Ἡ ἐμὴ διδαχὴ οὐκ ἔστιν ἐμὴ, ἀλλὰ τοῦ πέμψαντός με.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 17, 'Ἐάν τις θέλῃ τὸ θέλημα αὐτοῦ ποιεῖν, γνώσεται περὶ τῆς διδαχῆς, πότερον ἐκ τοῦ  ̊Θεοῦ ἐστιν, ἢ ἐγὼ ἀπʼ ἐμαυτοῦ λαλῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 18, 'Ὁ ἀφʼ ἑαυτοῦ λαλῶν, τὴν δόξαν τὴν ἰδίαν ζητεῖ· ὁ δὲ ζητῶν τὴν δόξαν τοῦ πέμψαντος αὐτὸν, οὗτος ἀληθής ἐστιν, καὶ ἀδικία ἐν αὐτῷ οὐκ ἔστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 19, '¶Οὐ Μωϋσῆς δέδωκεν ὑμῖν τὸν νόμον, καὶ οὐδεὶς ἐξ ὑμῶν ποιεῖ τὸν νόμον; Τί με ζητεῖτε ἀποκτεῖναι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 20, 'Ἀπεκρίθη ὁ ὄχλος, “Δαιμόνιον ἔχεις· τίς σε ζητεῖ ἀποκτεῖναι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 21, 'Ἀπεκρίθη  ̊Ἰησοῦς καὶ εἶπεν αὐτοῖς, “Ἓν ἔργον ἐποίησα καὶ πάντες θαυμάζετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 22, 'Διὰ τοῦτο Μωϋσῆς δέδωκεν ὑμῖν τὴν περιτομήν (οὐχ ὅτι ἐκ τοῦ Μωϋσέως ἐστὶν, ἀλλʼ ἐκ τῶν πατέρων), καὶ ἐν Σαββάτῳ περιτέμνετε ἄνθρωπον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 23, 'Εἰ περιτομὴν λαμβάνει ἄνθρωπος ἐν Σαββάτῳ, ἵνα μὴ λυθῇ ὁ νόμος Μωϋσέως, ἐμοὶ χολᾶτε ὅτι ὅλον ἄνθρωπον ὑγιῆ ἐποίησα ἐν Σαββάτῳ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 24, 'Μὴ κρίνετε κατʼ ὄψιν, ἀλλὰ τὴν δικαίαν κρίσιν κρίνετε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 25, '¶Ἔλεγον οὖν τινες ἐκ τῶν Ἱεροσολυμιτῶν, “Οὐχ οὗτός ἐστιν ὃν ζητοῦσιν ἀποκτεῖναι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 26, 'Καὶ ἴδε, παρρησίᾳ λαλεῖ, καὶ οὐδὲν αὐτῷ λέγουσιν. Μήποτε ἀληθῶς ἔγνωσαν οἱ ἄρχοντες ὅτι οὗτός ἐστιν ὁ  ̊Χριστός;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 27, 'Ἀλλὰ τοῦτον οἴδαμεν πόθεν ἐστίν. Ὁ δὲ  ̊Χριστὸς ὅταν ἔρχηται, οὐδεὶς γινώσκει πόθεν ἐστίν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 28, 'Ἔκραξεν οὖν ἐν τῷ ἱερῷ διδάσκων ὁ  ̊Ἰησοῦς, καὶ λέγων, “Κἀμὲ οἴδατε, καὶ οἴδατε πόθεν εἰμί· καὶ ἀπʼ ἐμαυτοῦ οὐκ ἐλήλυθα, ἀλλʼ ἔστιν ἀληθινὸς ὁ πέμψας με, ὃν ὑμεῖς οὐκ οἴδατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 29, 'Ἐγὼ οἶδα αὐτόν, ὅτι παρʼ αὐτοῦ εἰμι, κἀκεῖνός με ἀπέστειλεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 30, 'Ἐζήτουν οὖν αὐτὸν πιάσαι, καὶ οὐδεὶς ἐπέβαλεν ἐπʼ αὐτὸν τὴν χεῖρα, ὅτι οὔπω ἐληλύθει ἡ ὥρα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 31, 'Ἐκ τοῦ ὄχλου δὲ πολλοὶ ἐπίστευσαν εἰς αὐτόν, καὶ ἔλεγον, “Ὁ  ̊Χριστὸς, ὅταν ἔλθῃ, μὴ πλείονα σημεῖα ποιήσει ὧν οὗτος ἐποίησεν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 32, '¶Ἤκουσαν οἱ Φαρισαῖοι τοῦ ὄχλου γογγύζοντος περὶ αὐτοῦ ταῦτα, καὶ ἀπέστειλαν οἱ ἀρχιερεῖς καὶ οἱ Φαρισαῖοι ὑπηρέτας, ἵνα πιάσωσιν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 33, 'Εἶπεν οὖν ὁ  ̊Ἰησοῦς, “Ἔτι χρόνον μικρὸν μεθʼ ὑμῶν εἰμι, καὶ ὑπάγω πρὸς τὸν πέμψαντά με.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 34, 'Ζητήσετέ με, καὶ οὐχ εὑρήσετέ, με καὶ ὅπου εἰμὶ ἐγὼ ὑμεῖς, οὐ δύνασθε ἐλθεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 35, 'Εἶπον οὖν οἱ Ἰουδαῖοι πρὸς ἑαυτούς, “Ποῦ οὗτος μέλλει πορεύεσθαι, ὅτι ἡμεῖς οὐχ εὑρήσομεν αὐτόν; Μὴ εἰς τὴν διασπορὰν τῶν Ἑλλήνων μέλλει πορεύεσθαι, καὶ διδάσκειν τοὺς Ἕλληνας;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 36, 'Τίς ἐστιν ὁ λόγος οὗτος ὃν εἶπεν, ‘Ζητήσετέ με, καὶ οὐχ εὑρήσετέ, με καὶ ὅπου εἰμὶ ἐγὼ, ὑμεῖς οὐ δύνασθε ἐλθεῖν’;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 37, '¶Ἐν δὲ τῇ ἐσχάτῃ ἡμέρᾳ τῇ μεγάλῃ τῆς ἑορτῆς εἱστήκει ὁ  ̊Ἰησοῦς, καὶ ἔκραξεν λέγων, “Ἐάν τις διψᾷ, ἐρχέσθω πρός με καὶ πινέτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 38, 'Ὁ πιστεύων εἰς ἐμέ, καθὼς εἶπεν ἡ Γραφή, ‘Ποταμοὶ ἐκ τῆς κοιλίας αὐτοῦ ῥεύσουσιν ὕδατος ζῶντος.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 39, 'Τοῦτο δὲ εἶπεν περὶ τοῦ  ̊Πνεύματος, οὗ ἔμελλον λαμβάνειν, οἱ πιστεύσαντες εἰς αὐτόν· οὔπω γὰρ ἦν  ̊Πνεῦμα, ὅτι  ̊Ἰησοῦς οὐδέπω ἐδοξάσθη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 40, '¶Ἐκ τοῦ ὄχλου οὖν, ἀκούσαντες τῶν λόγων τούτων, ἔλεγον, “Οὗτός ἐστιν ἀληθῶς ὁ προφήτης”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 41, 'Ἄλλοι ἔλεγον, “Οὗτός ἐστιν ὁ  ̊Χριστός.” Οἱ δὲ ἔλεγον, “Μὴ γὰρ ἐκ τῆς Γαλιλαίας ὁ  ̊Χριστὸς ἔρχεται;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 42, 'Οὐχ ἡ Γραφὴ εἶπεν ὅτι ἐκ τοῦ σπέρματος Δαυὶδ, καὶ ἀπὸ Βηθλέεμ, τῆς κώμης ὅπου ἦν Δαυὶδ, ἔρχεται ὁ  ̊Χριστός;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 43, 'Σχίσμα οὖν ἐγένετο ἐν τῷ ὄχλῳ διʼ αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 44, 'Τινὲς δὲ ἤθελον ἐξ αὐτῶν πιάσαι αὐτόν, ἀλλʼ οὐδεὶς ἔβαλεν ἐπʼ αὐτὸν τὰς χεῖρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 45, '¶Ἦλθον οὖν οἱ ὑπηρέται πρὸς τοὺς ἀρχιερεῖς καὶ Φαρισαίους, καὶ εἶπον αὐτοῖς ἐκεῖνοι, “Διὰ τί οὐκ ἠγάγετε αὐτόν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 46, 'Ἀπεκρίθησαν οἱ ὑπηρέται, “Οὐδέποτε ἐλάλησεν οὕτως ἄνθρωπος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 47, 'Ἀπεκρίθησαν οὖν αὐτοῖς οἱ Φαρισαῖοι, “Μὴ καὶ ὑμεῖς πεπλάνησθε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 48, 'Μή τις ἐκ τῶν ἀρχόντων ἐπίστευσεν εἰς αὐτὸν, ἢ ἐκ τῶν Φαρισαίων;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 49, 'Ἀλλὰ ὁ ὄχλος οὗτος, ὁ μὴ γινώσκων τὸν νόμον, ἐπάρατοί εἰσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 50, 'Λέγει Νικόδημος πρὸς αὐτούς, ὁ ἐλθὼν πρὸς αὐτὸν πρότερον, εἷς ὢν ἐξ αὐτῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 51, '“Μὴ ὁ νόμος ἡμῶν κρίνει τὸν ἄνθρωπον, ἐὰν μὴ ἀκούσῃ πρῶτον παρʼ αὐτοῦ, καὶ γνῷ τί ποιεῖ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 52, 'Ἀπεκρίθησαν καὶ εἶπαν αὐτῷ, “Μὴ καὶ σὺ ἐκ τῆς Γαλιλαίας εἶ; Ἐραύνησον καὶ ἴδε ὅτι ἐκ τῆς Γαλιλαίας προφήτης οὐκ ἐγείρεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 53, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 1, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 2, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 3, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 4, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 5, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 6, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 7, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 8, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 9, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 10, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 11, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 12, '¶Πάλιν οὖν αὐτοῖς ἐλάλησεν ὁ  ̊Ἰησοῦς λέγων, “Ἐγώ εἰμι τὸ φῶς τοῦ κόσμου· ὁ ἀκολουθῶν μοι οὐ μὴ περιπατήσῃ ἐν τῇ σκοτίᾳ, ἀλλʼ ἕξει τὸ φῶς τῆς ζωῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 13, 'Εἶπον οὖν αὐτῷ οἱ Φαρισαῖοι, “Σὺ περὶ σεαυτοῦ μαρτυρεῖς· ἡ μαρτυρία σου οὐκ ἔστιν ἀληθής.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 14, 'Ἀπεκρίθη  ̊Ἰησοῦς καὶ εἶπεν αὐτοῖς, “Κἂν ἐγὼ μαρτυρῶ περὶ ἐμαυτοῦ, ἀληθής ἐστιν ἡ μαρτυρία μου, ὅτι οἶδα πόθεν ἦλθον καὶ ποῦ ὑπάγω. Ὑμεῖς δὲ οὐκ οἴδατε πόθεν ἔρχομαι ἢ ποῦ ὑπάγω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 15, 'Ὑμεῖς κατὰ τὴν σάρκα κρίνετε, ἐγὼ οὐ κρίνω οὐδένα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 16, 'Καὶ ἐὰν κρίνω δὲ ἐγώ, ἡ κρίσις ἡ ἐμὴ ἀληθινή ἐστιν, ὅτι μόνος οὐκ εἰμί, ἀλλʼ ἐγὼ καὶ ὁ πέμψας με Πατήρ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 17, 'Καὶ ἐν τῷ νόμῳ δὲ τῷ ὑμετέρῳ γέγραπται, ὅτι δύο ἀνθρώπων ἡ μαρτυρία ἀληθής ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 18, 'Ἐγώ εἰμι ὁ μαρτυρῶν περὶ ἐμαυτοῦ, καὶ μαρτυρεῖ περὶ ἐμοῦ ὁ πέμψας με Πατήρ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 19, 'Ἔλεγον οὖν αὐτῷ, “Ποῦ ἐστιν ὁ πατήρ σου;” Ἀπεκρίθη  ̊Ἰησοῦς, “Οὔτε ἐμὲ οἴδατε, οὔτε τὸν Πατέρα μου. Εἰ ἐμὲ ᾔδειτε, καὶ τὸν Πατέρα μου ἂν ᾔδειτε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 20, 'Ταῦτα τὰ ῥήματα ἐλάλησεν ἐν τῷ γαζοφυλακίῳ, διδάσκων ἐν τῷ ἱερῷ· καὶ οὐδεὶς ἐπίασεν αὐτόν, ὅτι οὔπω ἐληλύθει ἡ ὥρα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 21, '¶Εἶπεν οὖν πάλιν αὐτοῖς, “Ἐγὼ ὑπάγω καὶ ζητήσετέ με, καὶ ἐν τῇ ἁμαρτίᾳ ὑμῶν ἀποθανεῖσθε· ὅπου ἐγὼ ὑπάγω, ὑμεῖς οὐ δύνασθε ἐλθεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 22, 'Ἔλεγον οὖν οἱ Ἰουδαῖοι, “Μήτι ἀποκτενεῖ ἑαυτὸν, ὅτι λέγει, ‘Ὅπου ἐγὼ ὑπάγω ὑμεῖς, οὐ δύνασθε ἐλθεῖν’;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 23, 'Καὶ ἔλεγεν αὐτοῖς, “Ὑμεῖς ἐκ τῶν κάτω ἐστέ, ἐγὼ ἐκ τῶν ἄνω εἰμί· ὑμεῖς ἐκ τούτου τοῦ κόσμου ἐστέ, ἐγὼ οὐκ εἰμὶ ἐκ τοῦ κόσμου τούτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 24, 'Εἶπον οὖν ὑμῖν ὅτι ἀποθανεῖσθε ἐν ταῖς ἁμαρτίαις ὑμῶν· ἐὰν γὰρ μὴ πιστεύσητε ὅτι ἐγώ εἰμι, ἀποθανεῖσθε ἐν ταῖς ἁμαρτίαις ὑμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 25, 'Ἔλεγον οὖν αὐτῷ, “Σὺ τίς εἶ;” Εἶπεν αὐτοῖς ὁ  ̊Ἰησοῦς, “Τὴν ἀρχὴν ὅ τι καὶ λαλῶ ὑμῖν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 26, 'Πολλὰ ἔχω περὶ ὑμῶν λαλεῖν καὶ κρίνειν· ἀλλʼ ὁ πέμψας με ἀληθής ἐστιν, κἀγὼ ἃ ἤκουσα παρʼ αὐτοῦ, ταῦτα λαλῶ εἰς τὸν κόσμον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 27, 'Οὐκ ἔγνωσαν ὅτι τὸν Πατέρα αὐτοῖς ἔλεγεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 28, 'Εἶπεν οὖν αὐτοῖς ὁ  ̊Ἰησοῦς, “Ὅταν ὑψώσητε τὸν Υἱὸν τοῦ Ἀνθρώπου, τότε γνώσεσθε ὅτι ἐγώ εἰμι, καὶ ἀπʼ ἐμαυτοῦ ποιῶ οὐδέν, ἀλλὰ καθὼς ἐδίδαξέν με ὁ Πατὴρ, ταῦτα λαλῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 29, 'Καὶ ὁ πέμψας με, μετʼ ἐμοῦ ἐστιν· οὐκ ἀφῆκέν με μόνον, ὅτι ἐγὼ τὰ ἀρεστὰ αὐτῷ ποιῶ πάντοτε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 30, 'Ταῦτα αὐτοῦ λαλοῦντος, πολλοὶ ἐπίστευσαν εἰς αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 31, '¶Ἔλεγεν οὖν ὁ  ̊Ἰησοῦς πρὸς τοὺς πεπιστευκότας αὐτῷ Ἰουδαίους, “Ἐὰν ὑμεῖς μείνητε ἐν τῷ λόγῳ τῷ ἐμῷ, ἀληθῶς μαθηταί μού ἐστε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 32, 'Καὶ γνώσεσθε τὴν ἀλήθειαν, καὶ ἡ ἀλήθεια ἐλευθερώσει ὑμᾶς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 33, 'Ἀπεκρίθησαν πρὸς αὐτόν, “Σπέρμα Ἀβραάμ ἐσμεν, καὶ οὐδενὶ δεδουλεύκαμεν πώποτε· πῶς σὺ λέγεις, ὅτι ‘Ἐλεύθεροι γενήσεσθε’;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 34, '¶Ἀπεκρίθη αὐτοῖς ὁ  ̊Ἰησοῦς, “Ἀμὴν, ἀμὴν, λέγω ὑμῖν ὅτι πᾶς ὁ ποιῶν τὴν ἁμαρτίαν, δοῦλός ἐστιν τῆς ἁμαρτίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 35, 'Ὁ δὲ δοῦλος οὐ μένει ἐν τῇ οἰκίᾳ εἰς τὸν αἰῶνα, ὁ Υἱὸς μένει εἰς τὸν αἰῶνα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 36, 'Ἐὰν οὖν ὁ Υἱὸς ὑμᾶς ἐλευθερώσῃ, ὄντως ἐλεύθεροι ἔσεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 37, 'Οἶδα ὅτι σπέρμα Ἀβραάμ ἐστε, ἀλλὰ ζητεῖτέ με ἀποκτεῖναι, ὅτι ὁ λόγος ὁ ἐμὸς οὐ χωρεῖ ἐν ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 38, 'Ἃ ἐγὼ ἑώρακα παρὰ τῷ Πατρὶ, λαλῶ· καὶ ὑμεῖς οὖν ἃ ἠκούσατε παρὰ τοῦ πατρὸς, ποιεῖτε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 39, '¶Ἀπεκρίθησαν καὶ εἶπαν αὐτῷ, “Ὁ πατὴρ ἡμῶν Ἀβραάμ ἐστιν.” Λέγει αὐτοῖς ὁ  ̊Ἰησοῦς, “Εἰ τέκνα τοῦ Ἀβραάμ ἐστε, τὰ ἔργα τοῦ Ἀβραὰμ ἐποιεῖτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 40, 'Νῦν δὲ ζητεῖτέ με ἀποκτεῖναι, ἄνθρωπον ὃς τὴν ἀλήθειαν ὑμῖν λελάληκα, ἣν ἤκουσα παρὰ τοῦ  ̊Θεοῦ· τοῦτο Ἀβραὰμ οὐκ ἐποίησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 41, 'Ὑμεῖς ποιεῖτε τὰ ἔργα τοῦ πατρὸς ὑμῶν.” εἶπον οὖν αὐτῷ, “Ἡμεῖς ἐκ πορνείας οὐ γεγεννήμεθα· ἕνα Πατέρα ἔχομεν, τὸν  ̊Θεόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 42, 'Εἶπεν αὐτοῖς ὁ  ̊Ἰησοῦς, “Εἰ ὁ  ̊Θεὸς Πατὴρ ὑμῶν ἦν, ἠγαπᾶτε ἂν ἐμέ, ἐγὼ γὰρ ἐκ τοῦ  ̊Θεοῦ ἐξῆλθον καὶ ἥκω· οὐδὲ γὰρ ἀπʼ ἐμαυτοῦ ἐλήλυθα, ἀλλʼ ἐκεῖνός με ἀπέστειλεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 43, 'Διὰ τί τὴν λαλιὰν τὴν ἐμὴν οὐ γινώσκετε; Ὅτι οὐ δύνασθε ἀκούειν τὸν λόγον τὸν ἐμόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 44, 'Ὑμεῖς ἐκ τοῦ πατρὸς τοῦ διαβόλου ἐστὲ, καὶ τὰς ἐπιθυμίας τοῦ πατρὸς ὑμῶν θέλετε ποιεῖν. Ἐκεῖνος ἀνθρωποκτόνος ἦν ἀπʼ ἀρχῆς, καὶ ἐν τῇ ἀληθείᾳ οὐκ ἔστηκεν, ὅτι οὐκ ἔστιν ἀλήθεια ἐν αὐτῷ. Ὅταν λαλῇ τὸ ψεῦδος, ἐκ τῶν ἰδίων λαλεῖ, ὅτι ψεύστης ἐστὶν, καὶ ὁ πατὴρ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 45, 'Ἐγὼ δὲ ὅτι τὴν ἀλήθειαν λέγω, οὐ πιστεύετέ μοι!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 46, 'Τίς ἐξ ὑμῶν ἐλέγχει με περὶ ἁμαρτίας; Εἰ ἀλήθειαν λέγω, διὰ τί ὑμεῖς οὐ πιστεύετέ μοι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 47, 'Ὁ ὢν ἐκ τοῦ  ̊Θεοῦ, τὰ ῥήματα τοῦ  ̊Θεοῦ ἀκούει· διὰ τοῦτο ὑμεῖς οὐκ ἀκούετε, ὅτι ἐκ τοῦ  ̊Θεοῦ οὐκ ἐστέ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 48, '¶Ἀπεκρίθησαν οἱ Ἰουδαῖοι καὶ εἶπαν αὐτῷ, “Οὐ καλῶς λέγομεν ἡμεῖς ὅτι Σαμαρείτης εἶ σὺ, καὶ δαιμόνιον ἔχεις;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 49, 'Ἀπεκρίθη  ̊Ἰησοῦς, “Ἐγὼ δαιμόνιον οὐκ ἔχω, ἀλλὰ τιμῶ τὸν Πατέρα μου, καὶ ὑμεῖς ἀτιμάζετέ με.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 50, 'Ἐγὼ δὲ οὐ ζητῶ τὴν δόξαν μου· ἔστιν ὁ ζητῶν καὶ κρίνων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 51, 'Ἀμὴν, ἀμὴν, λέγω ὑμῖν, ἐάν τις τὸν ἐμὸν λόγον τηρήσῃ, θάνατον οὐ μὴ θεωρήσῃ εἰς τὸν αἰῶνα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 52, 'Εἶπον αὐτῷ οἱ Ἰουδαῖοι, “Νῦν ἐγνώκαμεν ὅτι δαιμόνιον ἔχεις. Ἀβραὰμ ἀπέθανεν καὶ οἱ προφῆται, καὶ σὺ λέγεις, ‘Ἐάν τις τὸν λόγον μου τηρήσῃ, οὐ μὴ γεύσηται θανάτου εἰς τὸν αἰῶνα.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 53, 'Μὴ σὺ μείζων εἶ τοῦ πατρὸς ἡμῶν Ἀβραάμ, ὅστις ἀπέθανεν; Καὶ οἱ προφῆται ἀπέθανον! Τίνα σεαυτὸν ποιεῖς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 54, 'Ἀπεκρίθη  ̊Ἰησοῦς, “Ἐὰν ἐγὼ δοξάσω ἐμαυτόν, ἡ δόξα μου οὐδέν ἐστιν· ἔστιν ὁ Πατήρ μου ὁ δοξάζων με, ὃν ὑμεῖς λέγετε, ὅτι ‘ ̊Θεὸς ἡμῶν ἐστιν’,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 55, 'καὶ οὐκ ἐγνώκατε αὐτόν, ἐγὼ δὲ οἶδα αὐτόν, κἂν εἴπω ὅτι οὐκ οἶδα αὐτόν, ἔσομαι ὅμοιος ὑμῖν ψεύστης. Ἀλλʼ οἶδα αὐτὸν, καὶ τὸν λόγον αὐτοῦ τηρῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 56, 'Ἀβραὰμ ὁ πατὴρ ὑμῶν ἠγαλλιάσατο, ἵνα ἴδῃ τὴν ἡμέραν τὴν ἐμήν, καὶ εἶδεν καὶ ἐχάρη.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 57, 'Εἶπον οὖν οἱ Ἰουδαῖοι πρὸς αὐτόν, “Πεντήκοντα ἔτη οὔπω ἔχεις, καὶ Ἀβραὰμ ἑώρακας;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 58, 'Εἶπεν αὐτοῖς  ̊Ἰησοῦς, “Ἀμὴν, ἀμὴν, λέγω ὑμῖν, πρὶν Ἀβραὰμ γενέσθαι, ἐγὼ εἰμί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 59, 'Ἦραν οὖν λίθους, ἵνα βάλωσιν ἐπʼ αὐτόν·  ̊Ἰησοῦς δὲ ἐκρύβη, καὶ ἐξῆλθεν ἐκ τοῦ ἱεροῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 1, '¶Καὶ παράγων, εἶδεν ἄνθρωπον τυφλὸν ἐκ γενετῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 2, 'Καὶ ἠρώτησαν αὐτὸν οἱ μαθηταὶ αὐτοῦ λέγοντες, “Ῥαββί, τίς ἥμαρτεν, οὗτος ἢ οἱ γονεῖς αὐτοῦ, ἵνα τυφλὸς γεννηθῇ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 3, 'Ἀπεκρίθη  ̊Ἰησοῦς, “Οὔτε οὗτος ἥμαρτεν, οὔτε οἱ γονεῖς αὐτοῦ, ἀλλʼ ἵνα φανερωθῇ τὰ ἔργα τοῦ  ̊Θεοῦ ἐν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 4, 'Ἡμᾶς δεῖ ἐργάζεσθαι τὰ ἔργα τοῦ πέμψαντός με, ἕως ἡμέρα ἐστίν· ἔρχεται νὺξ, ὅτε οὐδεὶς δύναται ἐργάζεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 5, 'Ὅταν ἐν τῷ κόσμῳ ὦ, φῶς εἰμι τοῦ κόσμου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 6, 'Ταῦτα εἰπὼν, ἔπτυσεν χαμαὶ καὶ ἐποίησεν πηλὸν ἐκ τοῦ πτύσματος, καὶ ἐπέχρισεν αὐτοῦ τὸν πηλὸν ἐπὶ τοὺς ὀφθαλμούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 7, 'Καὶ εἶπεν αὐτῷ, “Ὕπαγε, νίψαι εἰς τὴν κολυμβήθραν τοῦ Σιλωάμ” (ὃ ἑρμηνεύεται, “Ἀπεσταλμένος”). Ἀπῆλθεν οὖν καὶ ἐνίψατο, καὶ ἦλθεν βλέπων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 8, 'Οἱ οὖν γείτονες καὶ οἱ θεωροῦντες αὐτὸν τὸ πρότερον, ὅτι προσαίτης ἦν, ἔλεγον, “Οὐχ οὗτός ἐστιν ὁ καθήμενος καὶ προσαιτῶν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 9, 'Ἄλλοι ἔλεγον, ὅτι “Οὗτός ἐστιν”, ἄλλοι ἔλεγον, “Οὐχί, ἀλλὰ ὅμοιος αὐτῷ ἐστιν.” Ἐκεῖνος ἔλεγεν, ὅτι “Ἐγώ εἰμι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 10, 'Ἔλεγον οὖν αὐτῷ, “Πῶς ἠνεῴχθησάν σου οἱ ὀφθαλμοί;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 11, 'Ἀπεκρίθη ἐκεῖνος, ἄνθρωπος ὁ λεγόμενος  ̊Ἰησοῦς πηλὸν ἐποίησεν, καὶ ἐπέχρισέν μου τοὺς ὀφθαλμοὺς, καὶ εἶπέν μοι, ὅτι ‘Ὕπαγε εἰς τὸν Σιλωὰμ καὶ νίψαι.’ Ἀπελθὼν οὖν καὶ νιψάμενος, ἀνέβλεψα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 12, 'Καὶ εἶπαν αὐτῷ, “Ποῦ ἐστιν ἐκεῖνος;” Λέγει, “Οὐκ οἶδα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 13, '¶Ἄγουσιν αὐτὸν πρὸς τοὺς Φαρισαίους, τόν ποτε τυφλόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 14, 'Ἦν δὲ Σάββατον ἐν ᾗ ἡμέρᾳ τὸν πηλὸν ἐποίησεν ὁ  ̊Ἰησοῦς, καὶ ἀνέῳξεν αὐτοῦ τοὺς ὀφθαλμούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 15, 'Πάλιν οὖν ἠρώτων αὐτὸν καὶ οἱ Φαρισαῖοι πῶς ἀνέβλεψεν. Ὁ δὲ εἶπεν αὐτοῖς, “Πηλὸν ἐπέθηκέν μου ἐπὶ τοὺς ὀφθαλμούς, καὶ ἐνιψάμην, καὶ βλέπω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 16, 'Ἔλεγον οὖν ἐκ τῶν Φαρισαίων τινές, “Οὐκ ἔστιν οὗτος παρὰ  ̊Θεοῦ ὁ ἄνθρωπος, ὅτι τὸ Σάββατον οὐ τηρεῖ.” Ἄλλοι ἔλεγον, “Πῶς δύναται ἄνθρωπος ἁμαρτωλὸς τοιαῦτα σημεῖα ποιεῖν;” Καὶ σχίσμα ἦν ἐν αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 17, 'Λέγουσιν οὖν τῷ τυφλῷ πάλιν, “Σὺ τί λέγεις περὶ αὐτοῦ, ὅτι ἠνέῳξέν σου τοὺς ὀφθαλμούς;” Ὁ δὲ εἶπεν, ὅτι “Προφήτης ἐστίν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 18, '¶Οὐκ ἐπίστευσαν οὖν οἱ Ἰουδαῖοι περὶ αὐτοῦ ὅτι ἦν τυφλὸς καὶ ἀνέβλεψεν, ἕως ὅτου ἐφώνησαν τοὺς γονεῖς αὐτοῦ τοῦ ἀναβλέψαντος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 19, 'Καὶ ἠρώτησαν αὐτοὺς λέγοντες, “Οὗτός ἐστιν ὁ υἱὸς ὑμῶν, ὃν ὑμεῖς λέγετε ὅτι τυφλὸς ἐγεννήθη; Πῶς οὖν βλέπει ἄρτι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 20, 'Ἀπεκρίθησαν οὖν οἱ γονεῖς αὐτοῦ καὶ εἶπαν, “Οἴδαμεν ὅτι οὗτός ἐστιν ὁ υἱὸς ἡμῶν, καὶ ὅτι τυφλὸς ἐγεννήθη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 21, 'Πῶς δὲ νῦν βλέπει, οὐκ οἴδαμεν, ἢ τίς ἤνοιξεν αὐτοῦ τοὺς ὀφθαλμοὺς, ἡμεῖς οὐκ οἴδαμεν· αὐτὸς ἡλικίαν ἔχει, αὐτὸν ἐρωτήσατε, αὐτὸς περὶ ἑαυτοῦ λαλήσει.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 22, 'Ταῦτα εἶπον οἱ γονεῖς αὐτοῦ, ὅτι ἐφοβοῦντο τοὺς Ἰουδαίους, ἤδη γὰρ συνετέθειντο οἱ Ἰουδαῖοι ἵνα ἐάν τις αὐτὸν ὁμολογήσῃ  ̊Χριστόν, ἀποσυνάγωγος γένηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 23, 'Διὰ τοῦτο οἱ γονεῖς αὐτοῦ εἶπαν, ὅτι “Ἡλικίαν ἔχει, αὐτὸν ἐπερωτήσατε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 24, '¶Ἐφώνησαν οὖν τὸν ἄνθρωπον ἐκ δευτέρου ὃς ἦν τυφλὸς, καὶ εἶπαν αὐτῷ, “Δὸς δόξαν τῷ  ̊Θεῷ· ἡμεῖς οἴδαμεν ὅτι οὗτος ὁ ἄνθρωπος ἁμαρτωλός ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 25, 'Ἀπεκρίθη οὖν ἐκεῖνος, “Εἰ ἁμαρτωλός ἐστιν οὐκ οἶδα. Ἓν οἶδα, ὅτι τυφλὸς ὢν, ἄρτι βλέπω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 26, 'Εἶπον οὖν αὐτῷ, “Τί ἐποίησέν σοι; Πῶς ἤνοιξέν σου τοὺς ὀφθαλμούς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 27, 'Ἀπεκρίθη αὐτοῖς, “Εἶπον ὑμῖν ἤδη, καὶ οὐκ ἠκούσατε. Τί πάλιν θέλετε ἀκούειν; Μὴ καὶ ὑμεῖς θέλετε αὐτοῦ μαθηταὶ γενέσθαι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 28, 'Καὶ ἐλοιδόρησαν αὐτὸν, καὶ εἶπον, “Σὺ μαθητὴς εἶ ἐκείνου, ἡμεῖς δὲ τοῦ Μωϋσέως ἐσμὲν μαθηταί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 29, 'Ἡμεῖς οἴδαμεν ὅτι Μωϋσεῖ λελάληκεν ὁ  ̊Θεός, τοῦτον δὲ οὐκ οἴδαμεν πόθεν ἐστίν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 30, 'Ἀπεκρίθη ὁ ἄνθρωπος καὶ εἶπεν αὐτοῖς, “Ἐν τούτῳ γὰρ τὸ θαυμαστόν ἐστιν, ὅτι ὑμεῖς οὐκ οἴδατε πόθεν ἐστίν, καὶ ἤνοιξέν μου τοὺς ὀφθαλμούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 31, 'Οἴδαμεν ὅτι ἁμαρτωλῶν ὁ  ̊Θεὸς οὐκ ἀκούει, ἀλλʼ ἐάν τις θεοσεβὴς ᾖ, καὶ τὸ θέλημα αὐτοῦ ποιῇ, τούτου ἀκούει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 32, 'Ἐκ τοῦ αἰῶνος οὐκ ἠκούσθη ὅτι ἤνοιξέν τις ὀφθαλμοὺς τυφλοῦ γεγεννημένου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 33, 'Εἰ μὴ ἦν οὗτος παρὰ  ̊Θεοῦ, οὐκ ἠδύνατο ποιεῖν οὐδέν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 34, 'Ἀπεκρίθησαν καὶ εἶπαν αὐτῷ, “Ἐν ἁμαρτίαις σὺ ἐγεννήθης ὅλος, καὶ σὺ διδάσκεις ἡμᾶς;” Καὶ ἐξέβαλον αὐτὸν ἔξω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 35, '¶Ἤκουσεν  ̊Ἰησοῦς ὅτι ἐξέβαλον αὐτὸν ἔξω, καὶ εὑρὼν αὐτὸν εἶπεν, “Σὺ πιστεύεις εἰς τὸν Υἱὸν τοῦ Ἀνθρώπου;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 36, 'Ἀπεκρίθη ἐκεῖνος, “Καὶ τίς ἐστιν,” ἔφη, “κύριε, ἵνα πιστεύσω εἰς αὐτόν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 37, 'Εἶπεν αὐτῷ ὁ  ̊Ἰησοῦς, “Καὶ ἑώρακας αὐτὸν, καὶ ὁ λαλῶν μετὰ σοῦ ἐκεῖνός ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 38, 'Ὁ δὲ ἔφη, “Πιστεύω,  ̊Κύριε”· καὶ προσεκύνησεν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 39, 'Καὶ εἶπεν ὁ  ̊Ἰησοῦς, “Εἰς κρίμα ἐγὼ εἰς τὸν κόσμον τοῦτον ἦλθον, ἵνα οἱ μὴ βλέποντες, βλέπωσιν, καὶ οἱ βλέποντες, τυφλοὶ γένωνται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 40, 'Ἤκουσαν ἐκ τῶν Φαρισαίων ταῦτα οἱ μετʼ αὐτοῦ ὄντες, καὶ εἶπον αὐτῷ, “Μὴ καὶ ἡμεῖς τυφλοί ἐσμεν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 41, 'Εἶπεν αὐτοῖς ὁ  ̊Ἰησοῦς, “Εἰ τυφλοὶ ἦτε, οὐκ ἂν εἴχετε ἁμαρτίαν· νῦν δὲ λέγετε, ὅτι ‘Βλέπομεν’, ἡ ἁμαρτία ὑμῶν μένει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 1, '¶Ἀμὴν, ἀμὴν, λέγω ὑμῖν, ὁ μὴ εἰσερχόμενος διὰ τῆς θύρας, εἰς τὴν αὐλὴν τῶν προβάτων, ἀλλὰ ἀναβαίνων ἀλλαχόθεν, ἐκεῖνος κλέπτης ἐστὶν καὶ λῃστής.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 2, 'Ὁ δὲ εἰσερχόμενος διὰ τῆς θύρας, ποιμήν ἐστιν τῶν προβάτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 3, 'Τούτῳ ὁ θυρωρὸς ἀνοίγει, καὶ τὰ πρόβατα τῆς φωνῆς αὐτοῦ ἀκούει, καὶ τὰ ἴδια πρόβατα φωνεῖ κατʼ ὄνομα, καὶ ἐξάγει αὐτά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 4, 'Ὅταν τὰ ἴδια πάντα ἐκβάλῃ, ἔμπροσθεν αὐτῶν πορεύεται, καὶ τὰ πρόβατα αὐτῷ ἀκολουθεῖ, ὅτι οἴδασιν τὴν φωνὴν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 5, 'Ἀλλοτρίῳ δὲ οὐ μὴ ἀκολουθήσωσιν, ἀλλὰ φεύξονται ἀπʼ αὐτοῦ, ὅτι οὐκ οἴδασι τῶν ἀλλοτρίων τὴν φωνήν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 6, 'Ταύτην τὴν παροιμίαν εἶπεν αὐτοῖς ὁ  ̊Ἰησοῦς, ἐκεῖνοι δὲ οὐκ ἔγνωσαν τίνα ἦν, ἃ ἐλάλει αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 7, '¶Εἶπεν οὖν αὐτοῖς πάλιν ὁ  ̊Ἰησοῦς, “Ἀμὴν, ἀμὴν, λέγω ὑμῖν ὅτι ἐγώ εἰμι ἡ θύρα τῶν προβάτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 8, 'Πάντες ὅσοι ἦλθον πρὸ ἐμοῦ κλέπται εἰσὶν καὶ λῃσταί, ἀλλʼ οὐκ ἤκουσαν αὐτῶν τὰ πρόβατα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 9, 'Ἐγώ εἰμι ἡ θύρα· διʼ ἐμοῦ ἐάν τις εἰσέλθῃ σωθήσεται, καὶ εἰσελεύσεται, καὶ ἐξελεύσεται, καὶ νομὴν εὑρήσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 10, 'Ὁ κλέπτης οὐκ ἔρχεται, εἰ μὴ ἵνα κλέψῃ, καὶ θύσῃ, καὶ ἀπολέσῃ. Ἐγὼ ἦλθον, ἵνα ζωὴν ἔχωσιν, καὶ περισσὸν ἔχωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 11, '¶Ἐγώ εἰμι ὁ ποιμὴν ὁ καλός. Ὁ ποιμὴν ὁ καλὸς τὴν ψυχὴν αὐτοῦ τίθησιν ὑπὲρ τῶν προβάτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 12, 'Ὁ μισθωτὸς καὶ οὐκ ὢν ποιμήν, οὗ οὐκ ἔστιν τὰ πρόβατα ἴδια, θεωρεῖ τὸν λύκον ἐρχόμενον, καὶ ἀφίησιν τὰ πρόβατα καὶ φεύγει, καὶ ὁ λύκος ἁρπάζει αὐτὰ καὶ σκορπίζει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 13, 'ὅτι μισθωτός ἐστιν καὶ οὐ μέλει αὐτῷ περὶ τῶν προβάτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 14, 'Ἐγώ εἰμι ὁ ποιμὴν ὁ καλός, καὶ γινώσκω τὰ ἐμὰ, καὶ γινώσκουσί με τὰ ἐμά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 15, 'Καθὼς γινώσκει με ὁ Πατὴρ, κἀγὼ γινώσκω τὸν Πατέρα, καὶ τὴν ψυχήν μου τίθημι ὑπὲρ τῶν προβάτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 16, 'Καὶ ἄλλα πρόβατα ἔχω, ἃ οὐκ ἔστιν ἐκ τῆς αὐλῆς ταύτης· κἀκεῖνα δεῖ με ἀγαγεῖν, καὶ τῆς φωνῆς μου ἀκούσουσιν, καὶ γενήσονται μία ποίμνη, εἷς ποιμήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 17, 'Διὰ τοῦτό, με ὁ Πατὴρ ἀγαπᾷ, ὅτι ἐγὼ τίθημι τὴν ψυχήν μου, ἵνα πάλιν λάβω αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 18, 'Οὐδεὶς ἦρεν αὐτὴν ἀπʼ ἐμοῦ, ἀλλʼ ἐγὼ τίθημι αὐτὴν ἀπʼ ἐμαυτοῦ. Ἐξουσίαν ἔχω θεῖναι αὐτήν, καὶ ἐξουσίαν ἔχω πάλιν λαβεῖν αὐτήν. Ταύτην τὴν ἐντολὴν ἔλαβον παρὰ τοῦ Πατρός μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 19, '¶Σχίσμα πάλιν ἐγένετο ἐν τοῖς Ἰουδαίοις, διὰ τοὺς λόγους τούτους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 20, 'Ἔλεγον δὲ πολλοὶ ἐξ αὐτῶν, “Δαιμόνιον ἔχει, καὶ μαίνεται· τί αὐτοῦ ἀκούετε;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 21, 'Ἄλλοι ἔλεγον, “Ταῦτα τὰ ῥήματα οὐκ ἔστιν δαιμονιζομένου. Μὴ δαιμόνιον δύναται τυφλῶν ὀφθαλμοὺς ἀνοῖξαι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 22, '¶Ἐγένετο τότε τὰ ἐγκαίνια ἐν τοῖς Ἱεροσολύμοις. Χειμὼν ἦν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 23, 'καὶ περιεπάτει ὁ  ̊Ἰησοῦς ἐν τῷ ἱερῷ, ἐν τῇ στοᾷ τοῦ Σολομῶνος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 24, 'Ἐκύκλωσαν οὖν αὐτὸν οἱ Ἰουδαῖοι, καὶ ἔλεγον αὐτῷ, “Ἕως πότε τὴν ψυχὴν ἡμῶν αἴρεις; Εἰ σὺ εἶ ὁ  ̊Χριστός, εἰπὲ ἡμῖν παρρησίᾳ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 25, 'Ἀπεκρίθη αὐτοῖς ὁ  ̊Ἰησοῦς, “Εἶπον ὑμῖν καὶ οὐ πιστεύετε. Τὰ ἔργα ἃ ἐγὼ ποιῶ ἐν τῷ ὀνόματι τοῦ Πατρός μου, ταῦτα μαρτυρεῖ περὶ ἐμοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 26, 'ἀλλὰ ὑμεῖς οὐ πιστεύετε, ὅτι οὐκ ἐστὲ ἐκ τῶν προβάτων τῶν ἐμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 27, 'Τὰ πρόβατα τὰ ἐμὰ τῆς φωνῆς μου ἀκούουσιν, κἀγὼ γινώσκω αὐτά, καὶ ἀκολουθοῦσίν μοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 28, 'κἀγὼ δίδωμι αὐτοῖς ζωὴν αἰώνιον, καὶ οὐ μὴ ἀπόλωνται, εἰς τὸν αἰῶνα, καὶ οὐχ ἁρπάσει τις αὐτὰ ἐκ τῆς χειρός μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 29, 'Ὁ Πατήρ μου ὃς δέδωκέν μοι, πάντων μεῖζόν ἐστιν, καὶ οὐδεὶς δύναται ἁρπάζειν ἐκ τῆς χειρὸς τοῦ Πατρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 30, 'Ἐγὼ καὶ ὁ Πατὴρ ἕν ἐσμεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 31, '¶Ἐβάστασαν πάλιν λίθους οἱ Ἰουδαῖοι, ἵνα λιθάσωσιν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 32, 'Ἀπεκρίθη αὐτοῖς ὁ  ̊Ἰησοῦς, “Πολλὰ ἔργα καλὰ ἔδειξα ὑμῖν ἐκ τοῦ Πατρός· μου διὰ ποῖον αὐτῶν ἔργον, ἐμὲ λιθάζετε;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 33, 'Ἀπεκρίθησαν αὐτῷ οἱ Ἰουδαῖοι, “Περὶ καλοῦ ἔργου οὐ λιθάζομέν σε, ἀλλὰ περὶ βλασφημίας, καὶ ὅτι σὺ, ἄνθρωπος ὢν, ποιεῖς σεαυτὸν  ̊Θεόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 34, 'Ἀπεκρίθη αὐτοῖς ὁ  ̊Ἰησοῦς, “Οὐκ ἔστιν γεγραμμένον ἐν τῷ νόμῳ ὑμῶν, ὅτι ‘Ἐγὼ εἶπα, “Θεοί ἐστε”’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 35, 'Εἰ ἐκείνους εἶπεν ‘θεοὺς’, πρὸς οὓς ὁ λόγος τοῦ  ̊Θεοῦ ἐγένετο (καὶ οὐ δύναται λυθῆναι ἡ Γραφή),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 36, 'ὃν ὁ Πατὴρ ἡγίασεν καὶ ἀπέστειλεν εἰς τὸν κόσμον, ὑμεῖς λέγετε, ὅτι ‘Βλασφημεῖς’, ὅτι εἶπον, ‘Υἱὸς τοῦ  ̊Θεοῦ εἰμι’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 37, 'Εἰ οὐ ποιῶ τὰ ἔργα τοῦ Πατρός μου, μὴ πιστεύετέ μοι·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 38, 'εἰ δὲ ποιῶ, κἂν ἐμοὶ μὴ πιστεύητε, τοῖς ἔργοις πιστεύετε, ἵνα γνῶτε καὶ γινώσκητε ὅτι ἐν ἐμοὶ ὁ Πατὴρ, κἀγὼ ἐν τῷ Πατρί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 39, 'Ἐζήτουν οὖν αὐτὸν πάλιν πιάσαι, καὶ ἐξῆλθεν ἐκ τῆς χειρὸς αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 40, '¶Καὶ ἀπῆλθεν πάλιν πέραν τοῦ Ἰορδάνου, εἰς τὸν τόπον ὅπου ἦν Ἰωάννης τὸ πρῶτον βαπτίζων, καὶ ἔμεινεν ἐκεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 41, 'Καὶ πολλοὶ ἦλθον πρὸς αὐτὸν, καὶ ἔλεγον, ὅτι “Ἰωάννης μὲν σημεῖον ἐποίησεν οὐδέν, πάντα δὲ ὅσα εἶπεν Ἰωάννης περὶ τούτου ἀληθῆ ἦν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 42, 'Καὶ πολλοὶ ἐπίστευσαν εἰς αὐτὸν ἐκεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 1, '¶Ἦν δέ τις ἀσθενῶν, Λάζαρος ἀπὸ Βηθανίας ἐκ τῆς κώμης Μαρίας, καὶ Μάρθας τῆς ἀδελφῆς αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 2, 'Ἦν δὲ Μαριὰμ ἡ ἀλείψασα τὸν  ̊Κύριον μύρῳ, καὶ ἐκμάξασα τοὺς πόδας αὐτοῦ ταῖς θριξὶν αὐτῆς, ἧς ὁ ἀδελφὸς Λάζαρος ἠσθένει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 3, 'Ἀπέστειλαν οὖν αἱ ἀδελφαὶ πρὸς αὐτὸν λέγουσαι, “ ̊Κύριε, ἴδε, ὃν φιλεῖς ἀσθενεῖ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 4, 'Ἀκούσας δὲ ὁ  ̊Ἰησοῦς εἶπεν, “Αὕτη ἡ ἀσθένεια οὐκ ἔστιν πρὸς θάνατον, ἀλλʼ ὑπὲρ τῆς δόξης τοῦ  ̊Θεοῦ, ἵνα δοξασθῇ ὁ Υἱὸς τοῦ  ̊Θεοῦ διʼ αὐτῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 5, 'Ἠγάπα δὲ ὁ  ̊Ἰησοῦς τὴν Μάρθαν, καὶ τὴν ἀδελφὴν αὐτῆς, καὶ τὸν Λάζαρον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 6, 'Ὡς οὖν ἤκουσεν ὅτι ἀσθενεῖ, τότε μὲν ἔμεινεν ἐν ᾧ ἦν τόπῳ δύο ἡμέρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 7, 'Ἔπειτα μετὰ τοῦτο λέγει τοῖς μαθηταῖς, “Ἄγωμεν εἰς τὴν Ἰουδαίαν πάλιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 8, 'Λέγουσιν αὐτῷ οἱ μαθηταί, “Ῥαββί, νῦν ἐζήτουν σε λιθάσαι οἱ Ἰουδαῖοι, καὶ πάλιν ὑπάγεις ἐκεῖ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 9, 'Ἀπεκρίθη  ̊Ἰησοῦς, “Οὐχὶ δώδεκα ὧραί εἰσιν τῆς ἡμέρας; Ἐάν τις περιπατῇ ἐν τῇ ἡμέρᾳ, οὐ προσκόπτει, ὅτι τὸ φῶς τοῦ κόσμου τούτου βλέπει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 10, 'Ἐὰν δέ τις περιπατῇ ἐν τῇ νυκτί, προσκόπτει, ὅτι τὸ φῶς οὐκ ἔστιν ἐν αὐτῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 11, 'Ταῦτα εἶπεν, καὶ μετὰ τοῦτο λέγει αὐτοῖς, “Λάζαρος ὁ φίλος ἡμῶν κεκοίμηται, ἀλλὰ πορεύομαι, ἵνα ἐξυπνίσω αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 12, 'Εἶπον οὖν οἱ μαθηταὶ αὐτῷ, “ ̊Κύριε, εἰ κεκοίμηται σωθήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 13, 'Εἰρήκει δὲ ὁ  ̊Ἰησοῦς περὶ τοῦ θανάτου αὐτοῦ. Ἐκεῖνοι δὲ ἔδοξαν ὅτι περὶ τῆς κοιμήσεως τοῦ ὕπνου λέγει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 14, 'Τότε οὖν εἶπεν αὐτοῖς ὁ  ̊Ἰησοῦς παρρησίᾳ, “Λάζαρος ἀπέθανεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 15, 'καὶ χαίρω διʼ ὑμᾶς, ἵνα πιστεύσητε ὅτι οὐκ ἤμην ἐκεῖ· ἀλλὰ ἄγωμεν πρὸς αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 16, 'Εἶπεν οὖν Θωμᾶς, ὁ λεγόμενος Δίδυμος τοῖς συμμαθηταῖς, “Ἄγωμεν καὶ ἡμεῖς, ἵνα ἀποθάνωμεν μετʼ αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 17, '¶Ἐλθὼν οὖν, ὁ  ̊Ἰησοῦς εὗρεν αὐτὸν, τέσσαρας ἤδη ἡμέρας ἔχοντα ἐν τῷ μνημείῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 18, 'Ἦν δὲ Βηθανία ἐγγὺς τῶν Ἱεροσολύμων, ὡς ἀπὸ σταδίων δεκαπέντε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 19, 'Πολλοὶ δὲ ἐκ τῶν Ἰουδαίων ἐληλύθεισαν πρὸς τὴν Μάρθαν καὶ Μαριὰμ, ἵνα παραμυθήσωνται αὐτὰς περὶ τοῦ ἀδελφοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 20, 'Ἡ οὖν Μάρθα ὡς, ἤκουσεν ὅτι  ̊Ἰησοῦς ἔρχεται, ὑπήντησεν αὐτῷ· Μαρία δὲ ἐν τῷ οἴκῳ ἐκαθέζετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 21, 'Εἶπεν οὖν ἡ Μάρθα πρὸς τὸν  ̊Ἰησοῦν, “ ̊Κύριε, εἰ ἦς ὧδε, οὐκ ἂν ἀπέθανεν ὁ ἀδελφός μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 22, 'καὶ νῦν οἶδα ὅτι ὅσα ἂν αἰτήσῃ τὸν  ̊Θεὸν, δώσει σοι ὁ  ̊Θεός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 23, 'Λέγει αὐτῇ ὁ  ̊Ἰησοῦς, “Ἀναστήσεται ὁ ἀδελφός σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 24, 'Λέγει αὐτῷ Μάρθα, “Οἶδα ὅτι ἀναστήσεται ἐν τῇ ἀναστάσει ἐν τῇ ἐσχάτῃ ἡμέρᾳ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 25, 'Εἶπεν αὐτῇ ὁ  ̊Ἰησοῦς, “Ἐγώ εἰμι ἡ ἀνάστασις καὶ ἡ ζωή· ὁ πιστεύων εἰς ἐμὲ, κἂν ἀποθάνῃ, ζήσεται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 26, 'καὶ πᾶς ὁ ζῶν καὶ πιστεύων εἰς ἐμὲ, οὐ μὴ ἀποθάνῃ εἰς τὸν αἰῶνα. Πιστεύεις τοῦτο;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 27, 'Λέγει αὐτῷ, “Ναί,  ̊Κύριε· ἐγὼ πεπίστευκα ὅτι σὺ εἶ ὁ  ̊Χριστὸς, ὁ Υἱὸς τοῦ  ̊Θεοῦ, ὁ εἰς τὸν κόσμον ἐρχόμενος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 28, '¶Καὶ τοῦτο εἰποῦσα ἀπῆλθεν, καὶ ἐφώνησεν Μαριὰμ, τὴν ἀδελφὴν αὐτῆς λάθρᾳ, εἰποῦσα, “Ὁ διδάσκαλος πάρεστιν, καὶ φωνεῖ σε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 29, 'Ἐκείνη δὲ ὡς ἤκουσεν, ἠγέρθη ταχὺ καὶ ἤρχετο πρὸς αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 30, 'Οὔπω δὲ ἐληλύθει ὁ  ̊Ἰησοῦς εἰς τὴν κώμην, ἀλλʼ ἦν ἔτι ἐν τῷ τόπῳ ὅπου ὑπήντησεν αὐτῷ ἡ Μάρθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 31, 'Οἱ οὖν Ἰουδαῖοι οἱ ὄντες μετʼ αὐτῆς ἐν τῇ οἰκίᾳ καὶ παραμυθούμενοι αὐτήν, ἰδόντες τὴν Μαριὰμ ὅτι ταχέως ἀνέστη καὶ ἐξῆλθεν, ἠκολούθησαν αὐτῇ, δόξαντες ὅτι ὑπάγει εἰς τὸ μνημεῖον, ἵνα κλαύσῃ ἐκεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 32, 'Ἡ οὖν Μαριὰμ, ὡς ἦλθεν ὅπου ἦν  ̊Ἰησοῦς, ἰδοῦσα αὐτὸν, ἔπεσεν αὐτοῦ πρὸς τοὺς πόδας, λέγουσα αὐτῷ,  ̊Κύριε, εἰ ἦς ὧδε, οὐκ ἄν μου ἀπέθανεν ὁ ἀδελφός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 33, ' ̊Ἰησοῦς οὖν ὡς εἶδεν αὐτὴν κλαίουσαν, καὶ τοὺς συνελθόντας αὐτῇ Ἰουδαίους κλαίοντας, ἐνεβριμήσατο τῷ πνεύματι καὶ ἐτάραξεν ἑαυτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 34, 'Καὶ εἶπεν, “Ποῦ τεθείκατε αὐτόν;” Λέγουσιν αὐτῷ, “ ̊Κύριε, ἔρχου καὶ ἴδε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 35, 'Ἐδάκρυσεν ὁ  ̊Ἰησοῦς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 36, 'Ἔλεγον οὖν οἱ Ἰουδαῖοι, “Ἴδε, πῶς ἐφίλει αὐτόν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 37, 'Τινὲς δὲ ἐξ αὐτῶν εἶπον, “Οὐκ ἐδύνατο οὗτος, ὁ ἀνοίξας τοὺς ὀφθαλμοὺς τοῦ τυφλοῦ, ποιῆσαι ἵνα καὶ οὗτος μὴ ἀποθάνῃ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 38, '¶ ̊Ἰησοῦς οὖν πάλιν ἐμβριμώμενος ἐν ἑαυτῷ, ἔρχεται εἰς τὸ μνημεῖον. Ἦν δὲ σπήλαιον, καὶ λίθος ἐπέκειτο ἐπʼ αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 39, 'Λέγει ὁ  ̊Ἰησοῦς, “Ἄρατε τὸν λίθον.” Λέγει αὐτῷ ἡ ἀδελφὴ τοῦ τετελευτηκότος Μάρθα, “ ̊Κύριε, ἤδη ὄζει, τεταρταῖος γάρ ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 40, 'Λέγει αὐτῇ ὁ  ̊Ἰησοῦς, “Οὐκ εἶπόν σοι ὅτι ἐὰν πιστεύσῃς, ὄψῃ τὴν δόξαν τοῦ  ̊Θεοῦ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 41, 'Ἦραν οὖν τὸν λίθον. Ὁ δὲ  ̊Ἰησοῦς ἦρεν τοὺς ὀφθαλμοὺς ἄνω, καὶ εἶπεν, “Πάτερ, εὐχαριστῶ σοι ὅτι ἤκουσάς μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 42, 'Ἐγὼ δὲ ᾔδειν ὅτι πάντοτέ μου ἀκούεις, ἀλλὰ διὰ τὸν ὄχλον τὸν περιεστῶτα, εἶπον, ἵνα πιστεύσωσιν ὅτι σύ με ἀπέστειλας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 43, 'Καὶ ταῦτα εἰπὼν, φωνῇ μεγάλῃ ἐκραύγασεν, “Λάζαρε, δεῦρο ἔξω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 44, 'Ἐξῆλθεν ὁ τεθνηκὼς, δεδεμένος τοὺς πόδας καὶ τὰς χεῖρας κειρίαις, καὶ ἡ ὄψις αὐτοῦ σουδαρίῳ περιεδέδετο. Λέγει αὐτοῖς ὁ  ̊Ἰησοῦς, “Λύσατε αὐτὸν καὶ ἄφετε αὐτὸν ὑπάγειν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 45, '¶Πολλοὶ οὖν ἐκ τῶν Ἰουδαίων, οἱ ἐλθόντες πρὸς τὴν Μαριὰμ, καὶ θεασάμενοι ἃ ἐποίησεν, ἐπίστευσαν εἰς αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 46, 'Τινὲς δὲ ἐξ αὐτῶν ἀπῆλθον πρὸς τοὺς Φαρισαίους, καὶ εἶπον αὐτοῖς ἃ ἐποίησεν  ̊Ἰησοῦς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 47, 'Συνήγαγον οὖν οἱ ἀρχιερεῖς καὶ οἱ Φαρισαῖοι Συνέδριον, καὶ ἔλεγον, “Τί ποιοῦμεν, ὅτι οὗτος ὁ ἄνθρωπος πολλὰ ποιεῖ σημεῖα;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 48, 'Ἐὰν ἀφῶμεν αὐτὸν οὕτως, πάντες πιστεύσουσιν εἰς αὐτόν, καὶ ἐλεύσονται οἱ Ῥωμαῖοι, καὶ ἀροῦσιν ἡμῶν καὶ τὸν τόπον καὶ τὸ ἔθνος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 49, 'Εἷς δέ τις ἐξ αὐτῶν, Καϊάφας ἀρχιερεὺς ὢν τοῦ ἐνιαυτοῦ ἐκείνου, εἶπεν αὐτοῖς, “Ὑμεῖς οὐκ οἴδατε οὐδέν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 50, 'Οὐδὲ λογίζεσθε ὅτι συμφέρει ὑμῖν ἵνα εἷς ἄνθρωπος ἀποθάνῃ ὑπὲρ τοῦ λαοῦ, καὶ μὴ ὅλον τὸ ἔθνος ἀπόληται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 51, 'Τοῦτο δὲ ἀφʼ ἑαυτοῦ οὐκ εἶπεν, ἀλλὰ ἀρχιερεὺς ὢν τοῦ ἐνιαυτοῦ ἐκείνου, ἐπροφήτευσεν ὅτι ἤμελλεν  ̊Ἰησοῦς ἀποθνῄσκειν ὑπὲρ τοῦ ἔθνους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 52, 'καὶ οὐχ ὑπὲρ τοῦ ἔθνους μόνον, ἀλλʼ ἵνα καὶ τὰ τέκνα τοῦ  ̊Θεοῦ, τὰ διεσκορπισμένα συναγάγῃ εἰς ἕν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 53, 'Ἀπʼ ἐκείνης οὖν τῆς ἡμέρας, ἐβουλεύσαντο ἵνα ἀποκτείνωσιν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 54, '¶Ὁ οὖν  ̊Ἰησοῦς οὐκέτι παρρησίᾳ περιεπάτει ἐν τοῖς Ἰουδαίοις, ἀλλὰ ἀπῆλθεν ἐκεῖθεν εἰς τὴν χώραν ἐγγὺς τῆς ἐρήμου, εἰς Ἐφραὶμ λεγομένην πόλιν, κἀκεῖ ἔμεινεν μετὰ τῶν μαθητῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 55, '¶Ἦν δὲ ἐγγὺς τὸ Πάσχα τῶν Ἰουδαίων, καὶ ἀνέβησαν πολλοὶ εἰς Ἱεροσόλυμα ἐκ τῆς χώρας πρὸ τοῦ Πάσχα, ἵνα ἁγνίσωσιν ἑαυτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 56, 'Ἐζήτουν οὖν τὸν  ̊Ἰησοῦν, καὶ ἔλεγον μετʼ ἀλλήλων ἐν τῷ ἱερῷ ἑστηκότες, “Τί δοκεῖ ὑμῖν; Ὅτι οὐ μὴ ἔλθῃ εἰς τὴν ἑορτήν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 57, 'Δεδώκεισαν δὲ οἱ ἀρχιερεῖς καὶ οἱ Φαρισαῖοι ἐντολὰς, ἵνα ἐάν τις γνῷ ποῦ ἐστιν, μηνύσῃ, ὅπως πιάσωσιν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 1, '¶Ὁ οὖν  ̊Ἰησοῦς πρὸ ἓξ ἡμερῶν τοῦ Πάσχα, ἦλθεν εἰς Βηθανίαν, ὅπου ἦν Λάζαρος, ὃν ἤγειρεν ἐκ νεκρῶν  ̊Ἰησοῦς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 2, 'Ἐποίησαν οὖν αὐτῷ δεῖπνον ἐκεῖ, καὶ ἡ Μάρθα διηκόνει, ὁ δὲ Λάζαρος εἷς ἦν ἐκ τῶν ἀνακειμένων σὺν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 3, 'Ἡ οὖν Μαρία λαβοῦσα λίτραν μύρου νάρδου πιστικῆς πολυτίμου, ἤλειψεν τοὺς πόδας τοῦ  ̊Ἰησοῦ, καὶ ἐξέμαξεν ταῖς θριξὶν αὐτῆς τοὺς πόδας αὐτοῦ· ἡ δὲ οἰκία ἐπληρώθη ἐκ τῆς ὀσμῆς τοῦ μύρου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 4, 'Λέγει δὲ Ἰούδας ὁ Ἰσκαριώτης, εἷς τῶν μαθητῶν αὐτοῦ, ὁ μέλλων αὐτὸν παραδιδόναι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 5, '“Διὰ τί τοῦτο τὸ μύρον οὐκ ἐπράθη τριακοσίων δηναρίων, καὶ ἐδόθη πτωχοῖς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 6, 'Εἶπεν δὲ τοῦτο, οὐχ ὅτι περὶ τῶν πτωχῶν ἔμελεν αὐτῷ, ἀλλʼ ὅτι κλέπτης ἦν, καὶ τὸ γλωσσόκομον ἔχων τὰ βαλλόμενα ἐβάσταζεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 7, 'Εἶπεν οὖν ὁ  ̊Ἰησοῦς, “Ἄφες αὐτήν, ἵνα εἰς τὴν ἡμέραν τοῦ ἐνταφιασμοῦ μου, τηρήσῃ αὐτό.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 8, 'Τοὺς πτωχοὺς γὰρ πάντοτε ἔχετε μεθʼ ἑαυτῶν, ἐμὲ δὲ οὐ πάντοτε ἔχετε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 9, '¶Ἔγνω οὖν ὁ ὄχλος πολὺς ἐκ τῶν Ἰουδαίων ὅτι ἐκεῖ ἐστιν, καὶ ἦλθον, οὐ διὰ τὸν  ̊Ἰησοῦν μόνον, ἀλλʼ ἵνα καὶ τὸν Λάζαρον ἴδωσιν, ὃν ἤγειρεν ἐκ νεκρῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 10, 'Ἐβουλεύσαντο δὲ οἱ ἀρχιερεῖς ἵνα καὶ τὸν Λάζαρον ἀποκτείνωσιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 11, 'ὅτι πολλοὶ διʼ αὐτὸν ὑπῆγον τῶν Ἰουδαίων, καὶ ἐπίστευον εἰς τὸν  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 12, '¶Τῇ ἐπαύριον ὁ ὄχλος πολὺς, ὁ ἐλθὼν εἰς τὴν ἑορτήν, ἀκούσαντες ὅτι ἔρχεται ὁ  ̊Ἰησοῦς εἰς Ἱεροσόλυμα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 13, 'ἔλαβον τὰ βαΐα τῶν φοινίκων καὶ ἐξῆλθον εἰς ὑπάντησιν αὐτῷ, καὶ ἐκραύγαζον, “‘Ὡσαννά! Εὐλογημένος ὁ ἐρχόμενος ἐν ὀνόματι  ̊Κυρίου’, καὶ ὁ Βασιλεὺς τοῦ Ἰσραήλ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 14, 'Εὑρὼν δὲ ὁ  ̊Ἰησοῦς ὀνάριον, ἐκάθισεν ἐπʼ αὐτό, καθώς ἐστιν γεγραμμένον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 15, '“Μὴ φοβοῦ, θυγάτηρ Σιών· ἰδοὺ, ὁ βασιλεύς σου ἔρχεται, καθήμενος ἐπὶ πῶλον ὄνου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 16, 'Ταῦτα οὐκ ἔγνωσαν αὐτοῦ οἱ μαθηταὶ τὸ πρῶτον, ἀλλʼ ὅτε ἐδοξάσθη  ̊Ἰησοῦς, τότε ἐμνήσθησαν ὅτι ταῦτα ἦν ἐπʼ αὐτῷ γεγραμμένα, καὶ ταῦτα ἐποίησαν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 17, 'Ἐμαρτύρει οὖν ὁ ὄχλος ὁ ὢν μετʼ αὐτοῦ, ὅτε τὸν Λάζαρον ἐφώνησεν ἐκ τοῦ μνημείου, καὶ ἤγειρεν αὐτὸν ἐκ νεκρῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 18, 'Διὰ τοῦτο καὶ ὑπήντησεν αὐτῷ ὁ ὄχλος, ὅτι ἤκουσαν τοῦτο αὐτὸν πεποιηκέναι τὸ σημεῖον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 19, 'Οἱ οὖν Φαρισαῖοι εἶπαν πρὸς ἑαυτούς, “Θεωρεῖτε ὅτι οὐκ ὠφελεῖτε οὐδέν· ἴδε, ὁ κόσμος ὀπίσω αὐτοῦ ἀπῆλθεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 20, '¶Ἦσαν δὲ Ἕλληνές τινες ἐκ τῶν ἀναβαινόντων, ἵνα προσκυνήσωσιν ἐν τῇ ἑορτῇ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 21, 'οὗτοι οὖν προσῆλθον Φιλίππῳ, τῷ ἀπὸ Βηθσαϊδὰ τῆς Γαλιλαίας, καὶ ἠρώτων αὐτὸν λέγοντες, “Κύριε, θέλομεν τὸν  ̊Ἰησοῦν ἰδεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 22, 'Ἔρχεται ὁ Φίλιππος καὶ λέγει τῷ Ἀνδρέᾳ, ἔρχεται Ἀνδρέας καὶ Φίλιππος καὶ λέγουσιν τῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 23, 'Ὁ δὲ  ̊Ἰησοῦς ἀποκρίνεται αὐτοῖς λέγων, “Ἐλήλυθεν ἡ ὥρα, ἵνα δοξασθῇ ὁ Υἱὸς τοῦ Ἀνθρώπου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 24, 'Ἀμὴν, ἀμὴν, λέγω ὑμῖν, ἐὰν μὴ ὁ κόκκος τοῦ σίτου πεσὼν εἰς τὴν γῆν ἀποθάνῃ, αὐτὸς μόνος μένει· ἐὰν δὲ ἀποθάνῃ, πολὺν καρπὸν φέρει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 25, 'Ὁ φιλῶν τὴν ψυχὴν αὐτοῦ, ἀπολλύει αὐτήν, καὶ ὁ μισῶν τὴν ψυχὴν αὐτοῦ ἐν τῷ κόσμῳ τούτῳ, εἰς ζωὴν αἰώνιον φυλάξει αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 26, 'Ἐὰν ἐμοί τις διακονῇ, ἐμοὶ ἀκολουθείτω, καὶ ὅπου εἰμὶ ἐγὼ, ἐκεῖ καὶ ὁ διάκονος ὁ ἐμὸς ἔσται. Ἐάν τις ἐμοὶ διακονῇ, τιμήσει αὐτὸν ὁ Πατήρ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 27, '¶Νῦν ἡ ψυχή μου τετάρακται, καὶ τί εἴπω, ‘Πάτερ, σῶσόν με ἐκ τῆς ὥρας ταύτης’; Ἀλλὰ διὰ τοῦτο, ἦλθον εἰς τὴν ὥραν ταύτην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 28, 'Πάτερ, δόξασόν σου τὸ ὄνομα.” Ἦλθεν οὖν φωνὴ ἐκ τοῦ οὐρανοῦ: “Καὶ ἐδόξασα, καὶ πάλιν δοξάσω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 29, 'Ὁ οὖν ὄχλος ὁ ἑστὼς καὶ ἀκούσας, ἔλεγεν βροντὴν γεγονέναι. Ἄλλοι ἔλεγον, “Ἄγγελος αὐτῷ λελάληκεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 30, 'Ἀπεκρίθη καὶ εἶπεν,  ̊Ἰησοῦς “Οὐ διʼ ἐμὲ, ἡ φωνὴ αὕτη γέγονεν, ἀλλὰ διʼ ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 31, 'Νῦν κρίσις ἐστὶν τοῦ κόσμου τούτου, νῦν ὁ ἄρχων τοῦ κόσμου τούτου ἐκβληθήσεται ἔξω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 32, 'Κἀγὼ ἐὰν ὑψωθῶ ἐκ τῆς γῆς, πάντας ἑλκύσω πρὸς ἐμαυτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 33, 'Τοῦτο δὲ ἔλεγεν, σημαίνων ποίῳ θανάτῳ ἤμελλεν ἀποθνῄσκειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 34, 'Ἀπεκρίθη οὖν αὐτῷ ὁ ὄχλος, “Ἡμεῖς ἠκούσαμεν ἐκ τοῦ νόμου ὅτι ὁ  ̊Χριστὸς μένει εἰς τὸν αἰῶνα, καὶ πῶς λέγεις σὺ ὅτι δεῖ ὑψωθῆναι τὸν Υἱὸν τοῦ Ἀνθρώπου; Τίς ἐστιν οὗτος ὁ Υἱὸς τοῦ Ἀνθρώπου;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 35, 'Εἶπεν οὖν αὐτοῖς ὁ  ̊Ἰησοῦς, “Ἔτι μικρὸν χρόνον, τὸ φῶς ἐν ὑμῖν ἐστιν. Περιπατεῖτε ὡς τὸ φῶς ἔχετε, ἵνα μὴ σκοτία ὑμᾶς καταλάβῃ, καὶ ὁ περιπατῶν ἐν τῇ σκοτίᾳ, οὐκ οἶδεν ποῦ ὑπάγει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 36, 'Ὡς τὸ φῶς ἔχετε, πιστεύετε εἰς τὸ φῶς, ἵνα υἱοὶ φωτὸς γένησθε.” ¶Ταῦτα ἐλάλησεν  ̊Ἰησοῦς, καὶ ἀπελθὼν, ἐκρύβη ἀπʼ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 37, 'Τοσαῦτα δὲ αὐτοῦ σημεῖα πεποιηκότος ἔμπροσθεν αὐτῶν, οὐκ ἐπίστευον εἰς αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 38, 'ἵνα ὁ λόγος Ἠσαΐου τοῦ προφήτου πληρωθῇ ὃν εἶπεν, “ ̊Κύριε, τίς ἐπίστευσεν τῇ ἀκοῇ ἡμῶν; Καὶ ὁ βραχίων  ̊Κυρίου τίνι ἀπεκαλύφθη;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 39, 'Διὰ τοῦτο οὐκ ἠδύναντο πιστεύειν, ὅτι πάλιν εἶπεν Ἠσαΐας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 40, '“Τετύφλωκεν αὐτῶν τοὺς ὀφθαλμοὺς καὶ ἐπήρωσεν αὐτῶν τὴν καρδίαν, ἵνα μὴ ἴδωσιν τοῖς ὀφθαλμοῖς καὶ νοήσωσιν τῇ καρδίᾳ, καὶ στραφῶσιν καὶ ἰάσομαι αὐτούς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 41, 'Ταῦτα εἶπεν Ἠσαΐας, ὅτι εἶδεν τὴν δόξαν αὐτοῦ, καὶ ἐλάλησεν περὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 42, 'Ὅμως μέντοι καὶ ἐκ τῶν ἀρχόντων πολλοὶ ἐπίστευσαν εἰς αὐτόν, ἀλλὰ διὰ τοὺς Φαρισαίους οὐχ ὡμολόγουν, ἵνα μὴ ἀποσυνάγωγοι γένωνται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 43, 'Ἠγάπησαν γὰρ τὴν δόξαν τῶν ἀνθρώπων μᾶλλον ἤπερ τὴν δόξαν τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 44, '¶ ̊Ἰησοῦς δὲ ἔκραξεν καὶ εἶπεν, “Ὁ πιστεύων εἰς ἐμὲ, οὐ πιστεύει εἰς ἐμὲ, ἀλλὰ εἰς τὸν πέμψαντά με,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 45, 'καὶ ὁ θεωρῶν ἐμὲ, θεωρεῖ τὸν πέμψαντά με.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 46, 'Ἐγὼ φῶς εἰς τὸν κόσμον ἐλήλυθα, ἵνα πᾶς ὁ πιστεύων εἰς ἐμὲ, ἐν τῇ σκοτίᾳ μὴ μείνῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 47, 'Καὶ ἐάν τίς μου ἀκούσῃ τῶν ῥημάτων, καὶ μὴ φυλάξῃ, ἐγὼ οὐ κρίνω αὐτόν, οὐ γὰρ ἦλθον, ἵνα κρίνω τὸν κόσμον, ἀλλʼ ἵνα σώσω τὸν κόσμον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 48, 'Ὁ ἀθετῶν ἐμὲ καὶ μὴ λαμβάνων τὰ ῥήματά μου, ἔχει τὸν κρίνοντα αὐτόν· ὁ λόγος ὃν ἐλάλησα, ἐκεῖνος κρινεῖ αὐτὸν ἐν τῇ ἐσχάτῃ ἡμέρᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 49, 'Ὅτι ἐγὼ ἐξ ἐμαυτοῦ οὐκ ἐλάλησα, ἀλλʼ ὁ πέμψας με Πατὴρ αὐτός μοι ἐντολὴν δέδωκεν– τί εἴπω, καὶ τί λαλήσω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 50, 'Καὶ οἶδα ὅτι ἡ ἐντολὴ αὐτοῦ ζωὴ αἰώνιός ἐστιν. Ἃ οὖν ἐγὼ λαλῶ, καθὼς εἴρηκέν μοι ὁ Πατήρ, οὕτως λαλῶ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 1, '¶Πρὸ δὲ τῆς ἑορτῆς τοῦ Πάσχα, εἰδὼς ὁ  ̊Ἰησοῦς ὅτι ἦλθεν αὐτοῦ ἡ ὥρα, ἵνα μεταβῇ ἐκ τοῦ κόσμου τούτου πρὸς τὸν Πατέρα, ἀγαπήσας τοὺς ἰδίους τοὺς ἐν τῷ κόσμῳ, εἰς τέλος ἠγάπησεν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 2, 'Καὶ δείπνου γινομένου, τοῦ διαβόλου ἤδη βεβληκότος εἰς τὴν καρδίαν ἵνα παραδῷ αὐτὸν Ἰούδας Σίμωνος Ἰσκαριώτης,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 3, 'εἰδὼς ὅτι πάντα δέδωκεν αὐτῷ ὁ Πατὴρ εἰς τὰς χεῖρας, καὶ ὅτι ἀπὸ  ̊Θεοῦ ἐξῆλθεν καὶ πρὸς τὸν  ̊Θεὸν ὑπάγει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 4, 'ἐγείρεται ἐκ τοῦ δείπνου καὶ τίθησιν τὰ ἱμάτια, καὶ λαβὼν λέντιον διέζωσεν ἑαυτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 5, 'Εἶτα βάλλει ὕδωρ εἰς τὸν νιπτῆρα, καὶ ἤρξατο νίπτειν τοὺς πόδας τῶν μαθητῶν, καὶ ἐκμάσσειν τῷ λεντίῳ ᾧ ἦν διεζωσμένος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 6, 'Ἔρχεται οὖν πρὸς Σίμωνα Πέτρον. Λέγει αὐτῷ, “ ̊Κύριε, σύ μου νίπτεις τοὺς πόδας;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 7, 'Ἀπεκρίθη  ̊Ἰησοῦς καὶ εἶπεν αὐτῷ, “Ὃ ἐγὼ ποιῶ, σὺ οὐκ οἶδας ἄρτι, γνώσῃ δὲ μετὰ ταῦτα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 8, 'Λέγει αὐτῷ Πέτρος, “Οὐ μὴ νίψῃς μου τοὺς πόδας εἰς τὸν αἰῶνα.” Ἀπεκρίθη  ̊Ἰησοῦς αὐτῷ, “Ἐὰν μὴ νίψω σε, οὐκ ἔχεις μέρος μετʼ ἐμοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 9, 'Λέγει αὐτῷ Σίμων Πέτρος, “ ̊Κύριε, μὴ τοὺς πόδας μου μόνον, ἀλλὰ καὶ τὰς χεῖρας καὶ τὴν κεφαλήν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 10, 'Λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Ὁ λελουμένος οὐκ ἔχει χρείαν, εἰ μὴ τοὺς πόδας νίψασθαι, ἀλλʼ ἔστιν καθαρὸς ὅλος· καὶ ὑμεῖς καθαροί ἐστε, ἀλλʼ οὐχὶ πάντες.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 11, 'ἬΙδει γὰρ τὸν παραδιδόντα αὐτόν· διὰ τοῦτο εἶπεν, ὅτι “Οὐχὶ πάντες καθαροί ἐστε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 12, '¶Ὅτε οὖν ἔνιψεν τοὺς πόδας αὐτῶν, καὶ ἔλαβεν τὰ ἱμάτια αὐτοῦ, καὶ ἀνέπεσεν, πάλιν εἶπεν αὐτοῖς, “Γινώσκετε τί πεποίηκα ὑμῖν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 13, 'Ὑμεῖς φωνεῖτέ με ὁ ‘Διδάσκαλος’ καὶ, ὁ ‘ ̊Κύριος’, καὶ καλῶς λέγετε, εἰμὶ γάρ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 14, 'Εἰ οὖν ἐγὼ ἔνιψα ὑμῶν τοὺς πόδας, ὁ  ̊Κύριος καὶ ὁ Διδάσκαλος, καὶ ὑμεῖς ὀφείλετε ἀλλήλων νίπτειν τοὺς πόδας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 15, 'Ὑπόδειγμα γὰρ ἔδωκα ὑμῖν ἵνα καθὼς ἐγὼ ἐποίησα ὑμῖν, καὶ ὑμεῖς ποιῆτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 16, 'Ἀμὴν, ἀμὴν, λέγω ὑμῖν, οὐκ ἔστιν δοῦλος μείζων τοῦ κυρίου αὐτοῦ, οὐδὲ ἀπόστολος μείζων τοῦ πέμψαντος αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 17, 'Εἰ ταῦτα οἴδατε, μακάριοί ἐστε ἐὰν ποιῆτε αὐτά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 18, 'Οὐ περὶ πάντων ὑμῶν λέγω. Ἐγὼ οἶδα οὓς ἐξελεξάμην, ἀλλʼ ἵνα ἡ Γραφὴ πληρωθῇ, ‘Ὁ τρώγων μετʼ ἐμοῦ τὸν ἄρτον, ἐπῆρεν ἐπʼ ἐμὲ τὴν πτέρναν αὐτοῦ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 19, 'Ἀπʼ ἄρτι λέγω ὑμῖν πρὸ τοῦ γενέσθαι, ἵνα πιστεύσητε ὅταν γένηται ὅτι ἐγώ εἰμι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 20, 'Ἀμὴν, ἀμὴν, λέγω ὑμῖν, ὁ λαμβάνων ἄν τινα πέμψω, ἐμὲ λαμβάνει, ὁ δὲ ἐμὲ λαμβάνων, λαμβάνει τὸν πέμψαντά με.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 21, '¶Ταῦτα εἰπὼν, ὁ  ̊Ἰησοῦς ἐταράχθη τῷ πνεύματι καὶ ἐμαρτύρησεν καὶ εἶπεν, “Ἀμὴν, ἀμὴν, λέγω ὑμῖν ὅτι εἷς ἐξ ὑμῶν παραδώσει με.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 22, 'Ἔβλεπον οὖν εἰς ἀλλήλους οἱ μαθηταὶ, ἀπορούμενοι περὶ τίνος λέγει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 23, 'Ἦν δὲ ἀνακείμενος εἷς ἐκ τῶν μαθητῶν αὐτοῦ ἐν τῷ κόλπῳ τοῦ  ̊Ἰησοῦ, ὃν ἠγάπα ὁ  ̊Ἰησοῦς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 24, 'Νεύει οὖν τούτῳ Σίμων Πέτρος, πυθέσθαι τίς ἂν εἴη περὶ οὗ λέγει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 25, 'Ἐπιπεσὼν οὖν ἐκεῖνος οὕτως ἐπὶ τὸ στῆθος τοῦ  ̊Ἰησοῦ, λέγει αὐτῷ, “ ̊Κύριε, τίς ἐστιν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 26, 'Ἀποκρίνεται ὁ  ̊Ἰησοῦς, “Ἐκεῖνός ἐστιν ᾧ ἐγὼ, βάψας τὸ ψωμίον ἐπιδώσω.” Καὶ βάψας τὸ ψωμίον, δίδωσιν Ἰούδᾳ Σίμωνος Ἰσκαριώτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 27, 'Καὶ μετὰ τὸ ψωμίον, τότε εἰσῆλθεν εἰς ἐκεῖνον ὁ Σατανᾶς. Λέγει οὖν αὐτῷ ὁ  ̊Ἰησοῦς, “Ὃ ποιεῖς, ποίησον τάχιον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 28, 'Τοῦτο δὲ οὐδεὶς ἔγνω τῶν ἀνακειμένων, πρὸς τί εἶπεν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 29, 'Τινὲς γὰρ ἐδόκουν, ἐπεὶ τὸ γλωσσόκομον εἶχεν Ἰούδας, ὅτι λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Ἀγόρασον ὧν χρείαν ἔχομεν εἰς τὴν ἑορτήν”, ἢ τοῖς πτωχοῖς, ἵνα τι δῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 30, 'Λαβὼν οὖν τὸ ψωμίον, ἐκεῖνος ἐξῆλθεν εὐθύς. Ἦν δὲ νύξ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 31, '¶Ὅτε οὖν ἐξῆλθεν, λέγει  ̊Ἰησοῦς, “Νῦν ἐδοξάσθη ὁ Υἱὸς τοῦ Ἀνθρώπου, καὶ ὁ  ̊Θεὸς ἐδοξάσθη ἐν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 32, 'Καὶ ὁ  ̊Θεὸς δοξάσει αὐτὸν ἐν αὑτῷ, καὶ εὐθὺς δοξάσει αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 33, 'Τεκνία, ἔτι μικρὸν μεθʼ ὑμῶν εἰμι. Ζητήσετέ με, καὶ καθὼς εἶπον τοῖς Ἰουδαίοις, ὅτι ‘Ὅπου ἐγὼ ὑπάγω, ὑμεῖς οὐ δύνασθε ἐλθεῖν’, καὶ ὑμῖν λέγω ἄρτι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 34, 'Ἐντολὴν καινὴν δίδωμι ὑμῖν, ἵνα ἀγαπᾶτε ἀλλήλους, καθὼς ἠγάπησα ὑμᾶς, ἵνα καὶ ὑμεῖς ἀγαπᾶτε ἀλλήλους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 35, 'Ἐν τούτῳ γνώσονται πάντες ὅτι ἐμοὶ μαθηταί ἐστε, ἐὰν ἀγάπην ἔχητε ἐν ἀλλήλοις.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 36, '¶Λέγει αὐτῷ Σίμων Πέτρος, “ ̊Κύριε, ποῦ ὑπάγεις;” Ἀπεκρίθη αὐτῷ  ̊Ἰησοῦς, “Ὅπου ὑπάγω, οὐ δύνασαί μοι νῦν ἀκολουθῆσαι, ἀκολουθήσεις δὲ ὕστερον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 37, 'Λέγει αὐτῷ ὁ Πέτρος, “ ̊Κύριε, διὰ τί οὐ δύναμαί σοι ἀκολουθῆσαι ἄρτι; Τὴν ψυχήν μου ὑπὲρ σοῦ θήσω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 38, 'Ἀποκρίνεται  ̊Ἰησοῦς, “Τὴν ψυχήν σου ὑπὲρ ἐμοῦ θήσεις; Ἀμὴν, ἀμὴν, λέγω σοι, οὐ μὴ ἀλέκτωρ φωνήσῃ, ἕως οὗ ἀρνήσῃ με τρίς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 1, '¶Μὴ ταρασσέσθω ὑμῶν ἡ καρδία· πιστεύετε εἰς τὸν  ̊Θεόν, καὶ εἰς ἐμὲ πιστεύετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 2, 'Ἐν τῇ οἰκίᾳ τοῦ Πατρός μου, μοναὶ πολλαί εἰσιν· εἰ δὲ μή, εἶπον ἂν ὑμῖν, ὅτι πορεύομαι ἑτοιμάσαι τόπον ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 3, 'Καὶ ἐὰν πορευθῶ καὶ ἑτοιμάσω ὑμῖν τόπον πάλιν ἔρχομαι καὶ παραλήμψομαι ὑμᾶς πρὸς ἐμαυτόν, ἵνα ὅπου εἰμὶ ἐγὼ, καὶ ὑμεῖς ἦτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 4, 'Καὶ ὅπου ἐγὼ ὑπάγω οἴδατε, τὴν ὁδόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 5, 'Λέγει αὐτῷ Θωμᾶς, “ ̊Κύριε, οὐκ οἴδαμεν ποῦ ὑπάγεις· πῶς δυνάμεθα τὴν ὁδὸν εἰδέναι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 6, 'Λέγει αὐτῷ  ̊Ἰησοῦς, “Ἐγώ εἰμι ἡ ὁδὸς, καὶ ἡ ἀλήθεια, καὶ ἡ ζωή. Οὐδεὶς ἔρχεται πρὸς τὸν Πατέρα, εἰ μὴ διʼ ἐμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 7, 'Εἰ ἐγνώκειτέ με, καὶ τὸν Πατέρα μου γνώσεσθε, καὶ ἀπʼ ἄρτι γινώσκετε αὐτὸν καὶ ἑωράκατε αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 8, '¶Λέγει αὐτῷ Φίλιππος, “ ̊Κύριε, δεῖξον ἡμῖν τὸν Πατέρα, καὶ ἀρκεῖ ἡμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 9, 'Λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Τοσοῦτον χρόνον μεθʼ ὑμῶν εἰμι, καὶ οὐκ ἔγνωκάς με, Φίλιππε; Ὁ ἑωρακὼς ἐμὲ, ἑώρακεν τὸν Πατέρα· πῶς σὺ λέγεις, ‘Δεῖξον ἡμῖν τὸν Πατέρα’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 10, 'Οὐ πιστεύεις ὅτι ἐγὼ ἐν τῷ Πατρὶ, καὶ ὁ Πατὴρ ἐν ἐμοί ἐστιν; Τὰ ῥήματα ἃ ἐγὼ λέγω ὑμῖν, ἀπʼ ἐμαυτοῦ οὐ λαλῶ, ὁ δὲ Πατὴρ ἐν ἐμοὶ μένων, ποιεῖ τὰ ἔργα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 11, 'Πιστεύετέ μοι ὅτι ἐγὼ ἐν τῷ Πατρὶ, καὶ ὁ Πατὴρ ἐν ἐμοί· εἰ δὲ μή, διὰ τὰ ἔργα αὐτὰ πιστεύετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 12, 'Ἀμὴν, ἀμὴν, λέγω ὑμῖν, ὁ πιστεύων εἰς ἐμὲ, τὰ ἔργα ἃ ἐγὼ ποιῶ, κἀκεῖνος ποιήσει, καὶ μείζονα τούτων ποιήσει, ὅτι ἐγὼ πρὸς τὸν Πατέρα πορεύομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 13, 'Καὶ ὅ τι ἂν αἰτήσητε ἐν τῷ ὀνόματί μου, τοῦτο ποιήσω, ἵνα δοξασθῇ ὁ Πατὴρ ἐν τῷ Υἱῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 14, 'Ἐάν τι αἰτήσητέ με ἐν τῷ ὀνόματί μου, τοῦτο ποιήσω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 15, '¶Ἐὰν ἀγαπᾶτέ με, τὰς ἐντολὰς τὰς ἐμὰς τηρήσετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 16, 'Κἀγὼ ἐρωτήσω τὸν Πατέρα, καὶ ἄλλον Παράκλητον δώσει ὑμῖν, ἵνα μεθʼ ὑμῶν εἰς τὸν αἰῶνα ᾖ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 17, 'τὸ  ̊Πνεῦμα τῆς ἀληθείας, ὃ ὁ κόσμος οὐ δύναται λαβεῖν, ὅτι οὐ θεωρεῖ αὐτὸ οὐδὲ γινώσκει. Ὑμεῖς γινώσκετε αὐτό, ὅτι παρʼ ὑμῖν μένει, καὶ ἐν ὑμῖν ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 18, '¶Οὐκ ἀφήσω ὑμᾶς ὀρφανούς, ἔρχομαι πρὸς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 19, 'Ἔτι μικρὸν καὶ ὁ κόσμος με οὐκέτι θεωρεῖ, ὑμεῖς δὲ θεωρεῖτέ με, ὅτι ἐγὼ ζῶ, καὶ ὑμεῖς ζήσεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 20, 'Ἐν ἐκείνῃ τῇ ἡμέρᾳ ὑμεῖς γνώσεσθε ὅτι ἐγὼ ἐν τῷ Πατρί μου, καὶ ὑμεῖς ἐν ἐμοὶ, κἀγὼ ἐν ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 21, 'Ὁ ἔχων τὰς ἐντολάς μου καὶ τηρῶν αὐτὰς, ἐκεῖνός ἐστιν ὁ ἀγαπῶν με· ὁ δὲ ἀγαπῶν με, ἀγαπηθήσεται ὑπὸ τοῦ Πατρός μου, κἀγὼ ἀγαπήσω αὐτὸν, καὶ ἐμφανίσω αὐτῷ ἐμαυτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 22, 'Λέγει αὐτῷ Ἰούδας, οὐχ ὁ Ἰσκαριώτης, “ ̊Κύριε, τί γέγονεν, ὅτι ἡμῖν μέλλεις ἐμφανίζειν σεαυτὸν, καὶ οὐχὶ τῷ κόσμῳ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 23, 'Ἀπεκρίθη  ̊Ἰησοῦς καὶ εἶπεν αὐτῷ, “Ἐάν τις ἀγαπᾷ με, τὸν λόγον μου τηρήσει, καὶ ὁ Πατήρ μου ἀγαπήσει αὐτόν, καὶ πρὸς αὐτὸν ἐλευσόμεθα, καὶ μονὴν παρʼ αὐτῷ ποιησόμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 24, 'Ὁ μὴ ἀγαπῶν με, τοὺς λόγους μου οὐ τηρεῖ· καὶ ὁ λόγος ὃν ἀκούετε, οὐκ ἔστιν ἐμὸς, ἀλλὰ τοῦ πέμψαντός με Πατρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 25, '¶Ταῦτα λελάληκα ὑμῖν παρʼ ὑμῖν μένων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 26, 'Ὁ δὲ Παράκλητος, τὸ  ̊Πνεῦμα τὸ Ἅγιον, ὃ πέμψει ὁ Πατὴρ ἐν τῷ ὀνόματί μου, ἐκεῖνος ὑμᾶς διδάξει πάντα, καὶ ὑπομνήσει ὑμᾶς πάντα ἃ εἶπον ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 27, 'Εἰρήνην ἀφίημι ὑμῖν, εἰρήνην τὴν ἐμὴν δίδωμι ὑμῖν· οὐ καθὼς ὁ κόσμος δίδωσιν, ἐγὼ δίδωμι ὑμῖν. Μὴ ταρασσέσθω ὑμῶν ἡ καρδία, μηδὲ δειλιάτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 28, 'Ἠκούσατε ὅτι ἐγὼ εἶπον ὑμῖν, ‘Ὑπάγω καὶ ἔρχομαι πρὸς ὑμᾶς.’ Εἰ ἠγαπᾶτέ με, ἐχάρητε ἄν ὅτι πορεύομαι πρὸς τὸν Πατέρα, μου ὅτι ὁ Πατὴρ μείζων μού ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 29, 'Καὶ νῦν εἴρηκα ὑμῖν πρὶν γενέσθαι, ἵνα ὅταν γένηται, πιστεύσητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 30, 'Οὐκέτι πολλὰ λαλήσω μεθʼ ὑμῶν, ἔρχεται γὰρ ὁ τοῦ κόσμου ἄρχων, καὶ ἐν ἐμοὶ οὐκ ἔχει οὐδέν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 31, 'ἀλλʼ ἵνα γνῷ ὁ κόσμος ὅτι ἀγαπῶ τὸν Πατέρα, καὶ καθὼς ἐντολὴν ἔδωκέν μοι ὁ Πατὴρ, οὕτως ποιῶ. Ἐγείρεσθε, ἄγωμεν ἐντεῦθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 1, '¶Ἐγώ εἰμι ἡ ἄμπελος ἡ ἀληθινή, καὶ ὁ Πατήρ μου ὁ γεωργός ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 2, 'Πᾶν κλῆμα ἐν ἐμοὶ μὴ φέρον καρπὸν, αἴρει αὐτό, καὶ πᾶν τὸ καρπὸν φέρον, καθαίρει αὐτὸ, ἵνα καρπὸν πλείονα φέρῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 3, 'Ἤδη ὑμεῖς καθαροί ἐστε, διὰ τὸν λόγον ὃν λελάληκα ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 4, 'Μείνατε ἐν ἐμοί, κἀγὼ ἐν ὑμῖν. Καθὼς τὸ κλῆμα οὐ δύναται καρπὸν φέρειν ἀφʼ ἑαυτοῦ, ἐὰν μὴ μείνῃ ἐν τῇ ἀμπέλῳ, οὕτως οὐδὲ ὑμεῖς, ἐὰν μὴ ἐν ἐμοὶ μένητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 5, 'Ἐγώ εἰμι ἡ ἄμπελος, ὑμεῖς τὰ κλήματα. Ὁ μένων ἐν ἐμοὶ κἀγὼ ἐν αὐτῷ, οὗτος φέρει καρπὸν πολύν, ὅτι χωρὶς ἐμοῦ, οὐ δύνασθε ποιεῖν οὐδέν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 6, 'Ἐὰν μή τις μένῃ ἐν ἐμοί, ἐβλήθη ἔξω ὡς τὸ κλῆμα καὶ ἐξηράνθη, καὶ συνάγουσιν αὐτὰ καὶ εἰς τὸ πῦρ βάλλουσιν, καὶ καίεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 7, 'Ἐὰν μείνητε ἐν ἐμοὶ, καὶ τὰ ῥήματά μου ἐν ὑμῖν μείνῃ, ὃ ἐὰν θέλητε, αἰτήσασθε καὶ γενήσεται ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 8, 'Ἐν τούτῳ ἐδοξάσθη ὁ Πατήρ μου, ἵνα καρπὸν πολὺν φέρητε καὶ γένησθε ἐμοὶ μαθηταί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 9, 'Καθὼς ἠγάπησέν με ὁ Πατήρ, κἀγὼ ὑμᾶς ἠγάπησα· μείνατε ἐν τῇ ἀγάπῃ τῇ ἐμῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 10, 'Ἐὰν τὰς ἐντολάς μου τηρήσητε, μενεῖτε ἐν τῇ ἀγάπῃ μου, καθὼς ἐγὼ τοῦ Πατρὸς τὰς ἐντολὰς τετήρηκα, καὶ μένω αὐτοῦ ἐν τῇ ἀγάπῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 11, 'Ταῦτα λελάληκα ὑμῖν, ἵνα ἡ χαρὰ ἡ ἐμὴ ἐν ὑμῖν ᾖ, καὶ ἡ χαρὰ ὑμῶν πληρωθῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 12, '¶Αὕτη ἐστὶν ἡ ἐντολὴ ἡ ἐμὴ, ἵνα ἀγαπᾶτε ἀλλήλους καθὼς ἠγάπησα ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 13, 'Μείζονα ταύτης ἀγάπην οὐδεὶς ἔχει: ἵνα τις τὴν ψυχὴν αὐτοῦ θῇ ὑπὲρ τῶν φίλων αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 14, 'Ὑμεῖς φίλοι μού ἐστε, ἐὰν ποιῆτε ἃ ἐγὼ ἐντέλλομαι ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 15, 'Οὐκέτι λέγω ὑμᾶς δούλους, ὅτι ὁ δοῦλος οὐκ οἶδεν τί ποιεῖ αὐτοῦ ὁ κύριος. Ὑμᾶς δὲ εἴρηκα φίλους, ὅτι πάντα ἃ ἤκουσα παρὰ τοῦ Πατρός μου, ἐγνώρισα ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 16, 'Οὐχ ὑμεῖς με ἐξελέξασθε, ἀλλʼ ἐγὼ ἐξελεξάμην ὑμᾶς, καὶ ἔθηκα ὑμᾶς ἵνα ὑμεῖς ὑπάγητε καὶ καρπὸν φέρητε, καὶ ὁ καρπὸς ὑμῶν μένῃ, ἵνα ὅ τι ἂν αἰτήσητε τὸν Πατέρα ἐν τῷ ὀνόματί μου, δῷ ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 17, 'Ταῦτα ἐντέλλομαι ὑμῖν, ἵνα ἀγαπᾶτε ἀλλήλους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 18, '¶Εἰ ὁ κόσμος ὑμᾶς μισεῖ, γινώσκετε ὅτι ἐμὲ πρῶτον ὑμῶν μεμίσηκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 19, 'Εἰ ἐκ τοῦ κόσμου ἦτε, ὁ κόσμος ἂν τὸ ἴδιον ἐφίλει· ὅτι δὲ ἐκ τοῦ κόσμου οὐκ ἐστέ, ἀλλʼ ἐγὼ ἐξελεξάμην ὑμᾶς ἐκ τοῦ κόσμου, διὰ τοῦτο μισεῖ ὑμᾶς ὁ κόσμος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 20, 'Μνημονεύετε τοῦ λόγου οὗ ἐγὼ εἶπον ὑμῖν, ‘Οὐκ ἔστιν δοῦλος μείζων τοῦ κυρίου αὐτοῦ.’ Εἰ ἐμὲ ἐδίωξαν, καὶ ὑμᾶς διώξουσιν· εἰ τὸν λόγον μου ἐτήρησαν, καὶ τὸν ὑμέτερον τηρήσουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 21, 'Ἀλλὰ ταῦτα πάντα ποιήσουσιν εἰς ὑμᾶς διὰ τὸ ὄνομά μου, ὅτι οὐκ οἴδασιν τὸν πέμψαντά με.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 22, 'Εἰ μὴ ἦλθον καὶ ἐλάλησα αὐτοῖς, ἁμαρτίαν οὐκ εἴχοσαν· νῦν δὲ πρόφασιν οὐκ ἔχουσιν περὶ τῆς ἁμαρτίας αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 23, 'Ὁ ἐμὲ μισῶν, καὶ τὸν Πατέρα μου μισεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 24, 'Εἰ τὰ ἔργα μὴ ἐποίησα ἐν αὐτοῖς ἃ οὐδεὶς ἄλλος ἐποίησεν, ἁμαρτίαν οὐκ εἴχοσαν· νῦν δὲ καὶ ἑωράκασιν καὶ μεμισήκασιν, καὶ ἐμὲ καὶ τὸν Πατέρα μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 25, 'Ἀλλʼ ἵνα πληρωθῇ ὁ λόγος ὁ ἐν τῷ νόμῳ αὐτῶν γεγραμμένος, ὅτι ‘Ἐμίσησάν με δωρεάν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 26, '¶Ὅταν ἔλθῃ ὁ Παράκλητος, ὃν ἐγὼ πέμψω ὑμῖν παρὰ τοῦ Πατρός, τὸ  ̊Πνεῦμα τῆς ἀληθείας, ὃ παρὰ τοῦ Πατρὸς ἐκπορεύεται, ἐκεῖνος μαρτυρήσει περὶ ἐμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 27, 'Καὶ ὑμεῖς δὲ μαρτυρεῖτε, ὅτι ἀπʼ ἀρχῆς μετʼ ἐμοῦ ἐστε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 1, '¶Ταῦτα λελάληκα ὑμῖν, ἵνα μὴ σκανδαλισθῆτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 2, 'Ἀποσυναγώγους ποιήσουσιν ὑμᾶς· ἀλλʼ ἔρχεται ὥρα, ἵνα πᾶς ὁ ἀποκτείνας ὑμᾶς, δόξῃ λατρείαν προσφέρειν τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 3, 'Καὶ ταῦτα ποιήσουσιν, ὅτι οὐκ ἔγνωσαν τὸν Πατέρα οὐδὲ ἐμέ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 4, 'Ἀλλὰ ταῦτα λελάληκα ὑμῖν, ἵνα ὅταν ἔλθῃ ἡ ὥρα αὐτῶν, μνημονεύητε αὐτῶν ὅτι ἐγὼ εἶπον ὑμῖν. ¶Ταῦτα δὲ ὑμῖν ἐξ ἀρχῆς οὐκ εἶπον, ὅτι μεθʼ ὑμῶν ἤμην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 5, 'Νῦν δὲ ὑπάγω πρὸς τὸν πέμψαντά με, καὶ οὐδεὶς ἐξ ὑμῶν ἐρωτᾷ με, ‘Ποῦ ὑπάγεις;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 6, 'Ἀλλʼ ὅτι ταῦτα λελάληκα ὑμῖν, ἡ λύπη πεπλήρωκεν ὑμῶν τὴν καρδίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 7, 'Ἀλλʼ ἐγὼ τὴν ἀλήθειαν λέγω ὑμῖν, συμφέρει ὑμῖν ἵνα ἐγὼ ἀπέλθω. Ἐὰν γὰρ μὴ ἀπέλθω, ὁ Παράκλητος οὐκ ἐλεύσεται πρὸς ὑμᾶς· ἐὰν δὲ πορευθῶ, πέμψω αὐτὸν πρὸς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 8, 'Καὶ ἐλθὼν, ἐκεῖνος ἐλέγξει τὸν κόσμον περὶ ἁμαρτίας, καὶ περὶ δικαιοσύνης, καὶ περὶ κρίσεως·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 9, 'περὶ ἁμαρτίας μέν, ὅτι οὐ πιστεύουσιν εἰς ἐμέ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 10, 'περὶ δικαιοσύνης δέ, ὅτι πρὸς τὸν Πατέρα ὑπάγω, καὶ οὐκέτι θεωρεῖτέ με·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 11, 'περὶ δὲ κρίσεως, ὅτι ὁ ἄρχων τοῦ κόσμου τούτου κέκριται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 12, '¶Ἔτι πολλὰ ἔχω ὑμῖν λέγειν, ἀλλʼ οὐ δύνασθε βαστάζειν ἄρτι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 13, 'Ὅταν δὲ ἔλθῃ ἐκεῖνος, τὸ  ̊Πνεῦμα τῆς ἀληθείας, ὁδηγήσει ὑμᾶς εἰς τὴν ἀλήθειαν· πᾶσαν· οὐ γὰρ λαλήσει ἀφʼ ἑαυτοῦ, ἀλλʼ ὅσα ἀκούσει, λαλήσει, καὶ τὰ ἐρχόμενα ἀναγγελεῖ ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 14, 'Ἐκεῖνος ἐμὲ δοξάσει, ὅτι ἐκ τοῦ ἐμοῦ λήμψεται, καὶ ἀναγγελεῖ ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 15, 'Πάντα ὅσα ἔχει ὁ Πατὴρ, ἐμά ἐστιν· διὰ τοῦτο εἶπον ὅτι ἐκ τοῦ ἐμοῦ λαμβάνει, καὶ ἀναγγελεῖ ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 16, '¶Μικρὸν καὶ οὐκέτι θεωρεῖτέ με, καὶ πάλιν μικρὸν καὶ ὄψεσθέ με.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 17, 'Εἶπαν οὖν ἐκ τῶν μαθητῶν αὐτοῦ πρὸς ἀλλήλους, “Τί ἐστιν τοῦτο ὃ λέγει ἡμῖν, ‘Μικρὸν καὶ οὐ θεωρεῖτέ με, καὶ πάλιν μικρὸν καὶ ὄψεσθέ με· καί Ὅτι ὑπάγω πρὸς τὸν Πατέρα’;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 18, 'Ἔλεγον οὖν, “Τί ἐστιν τοῦτο, ὃ λέγει ‘Μικρόν’; Οὐκ οἴδαμεν τί λαλεῖ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 19, 'Ἔγνω  ̊Ἰησοῦς ὅτι ἤθελον αὐτὸν ἐρωτᾶν, καὶ εἶπεν αὐτοῖς, “Περὶ τούτου ζητεῖτε μετʼ ἀλλήλων, ὅτι εἶπον, ‘Μικρὸν καὶ οὐ θεωρεῖτέ με, καὶ πάλιν μικρὸν καὶ ὄψεσθέ με’;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 20, 'Ἀμὴν, ἀμὴν, λέγω ὑμῖν ὅτι κλαύσετε καὶ θρηνήσετε ὑμεῖς, ὁ δὲ κόσμος χαρήσεται· ὑμεῖς λυπηθήσεσθε, ἀλλʼ ἡ λύπη ὑμῶν εἰς χαρὰν γενήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 21, 'Ἡ γυνὴ ὅταν τίκτῃ, λύπην ἔχει, ὅτι ἦλθεν ἡ ὥρα αὐτῆς· ὅταν δὲ γεννήσῃ τὸ παιδίον, οὐκέτι μνημονεύει τῆς θλίψεως διὰ τὴν χαρὰν ὅτι ἐγεννήθη ἄνθρωπος εἰς τὸν κόσμον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 22, 'Καὶ ὑμεῖς οὖν νῦν μὲν λύπην ἔχετε· πάλιν δὲ ὄψομαι ὑμᾶς, καὶ χαρήσεται ὑμῶν ἡ καρδία, καὶ τὴν χαρὰν ὑμῶν, οὐδεὶς αἴρει ἀφʼ ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 23, 'Καὶ ἐν ἐκείνῃ τῇ ἡμέρᾳ ἐμὲ οὐκ ἐρωτήσετε οὐδέν. Ἀμὴν, ἀμὴν, λέγω ὑμῖν, ἄν τι αἰτήσητε τὸν Πατέρα, ἐν τῷ ὀνόματί μου, δώσει ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 24, 'Ἕως ἄρτι οὐκ ᾐτήσατε οὐδὲν ἐν τῷ ὀνόματί μου. Αἰτεῖτε καὶ λήμψεσθε, ἵνα ἡ χαρὰ ὑμῶν ᾖ πεπληρωμένη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 25, '¶Ταῦτα ἐν παροιμίαις λελάληκα ὑμῖν· ἔρχεται ὥρα ὅτε οὐκέτι ἐν παροιμίαις λαλήσω ὑμῖν, ἀλλὰ παρρησίᾳ περὶ τοῦ Πατρὸς ἀπαγγελῶ ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 26, 'Ἐν ἐκείνῃ τῇ ἡμέρᾳ ἐν τῷ ὀνόματί μου αἰτήσεσθε, καὶ οὐ λέγω ὑμῖν ὅτι ἐγὼ ἐρωτήσω τὸν Πατέρα περὶ ὑμῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 27, 'αὐτὸς γὰρ ὁ Πατὴρ φιλεῖ ὑμᾶς, ὅτι ὑμεῖς ἐμὲ πεφιλήκατε, καὶ πεπιστεύκατε ὅτι ἐγὼ παρὰ  ̊Θεοῦ ἐξῆλθον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 28, 'Ἐξῆλθον παρὰ τοῦ Πατρὸς, καὶ ἐλήλυθα εἰς τὸν κόσμον· πάλιν ἀφίημι τὸν κόσμον, καὶ πορεύομαι πρὸς τὸν Πατέρα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 29, '¶Λέγουσιν οἱ μαθηταὶ αὐτοῦ, “Ἴδε, νῦν ἐν παρρησίᾳ λαλεῖς, καὶ παροιμίαν οὐδεμίαν λέγεις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 30, 'Νῦν οἴδαμεν ὅτι οἶδας πάντα, καὶ οὐ χρείαν ἔχεις ἵνα τίς σε ἐρωτᾷ. Ἐν τούτῳ πιστεύομεν ὅτι ἀπὸ  ̊Θεοῦ ἐξῆλθες.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 31, 'Ἀπεκρίθη αὐτοῖς  ̊Ἰησοῦς, “Ἄρτι πιστεύετε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 32, 'Ἰδοὺ, ἔρχεται ὥρα καὶ ἐλήλυθεν, ἵνα σκορπισθῆτε ἕκαστος εἰς τὰ ἴδια, κἀμὲ μόνον ἀφῆτε· καὶ οὐκ εἰμὶ μόνος, ὅτι ὁ Πατὴρ μετʼ ἐμοῦ ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 33, 'Ταῦτα λελάληκα ὑμῖν, ἵνα ἐν ἐμοὶ εἰρήνην ἔχητε. Ἐν τῷ κόσμῳ θλῖψιν ἔχετε, ἀλλὰ θαρσεῖτε, ἐγὼ νενίκηκα τὸν κόσμον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 1, '¶Ταῦτα ἐλάλησεν  ̊Ἰησοῦς, καὶ ἐπάρας τοὺς ὀφθαλμοὺς αὐτοῦ εἰς τὸν οὐρανὸν εἶπεν, “Πάτερ, ἐλήλυθεν ἡ ὥρα· δόξασόν σου τὸν Υἱόν, ἵνα ὁ Υἱὸς δοξάσῃ σέ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 2, 'Καθὼς ἔδωκας αὐτῷ ἐξουσίαν πάσης σαρκός, ἵνα πᾶν ὃ δέδωκας αὐτῷ, δῷς αὐτῷ ζωὴν αἰώνιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 3, 'Αὕτη δέ ἐστιν ἡ αἰώνιος ζωὴ, ἵνα γινώσκωσι σὲ, τὸν μόνον ἀληθινὸν  ̊Θεὸν, καὶ ὃν ἀπέστειλας,  ̊Ἰησοῦν  ̊Χριστόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 4, 'Ἐγώ σε ἐδόξασα ἐπὶ τῆς γῆς, τὸ ἔργον τελειώσας, ὃ δέδωκάς μοι ἵνα ποιήσω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 5, 'Καὶ νῦν δόξασόν με σύ, Πάτερ, παρὰ σεαυτῷ, τῇ δόξῃ ᾗ εἶχον πρὸ τοῦ τὸν κόσμον εἶναι παρὰ σοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 6, '¶Ἐφανέρωσά σου τὸ ὄνομα τοῖς ἀνθρώποις οὓς ἔδωκάς μοι ἐκ τοῦ κόσμου. Σοὶ ἦσαν, κἀμοὶ αὐτοὺς ἔδωκας, καὶ τὸν λόγον σου τετήρηκαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 7, 'Νῦν ἔγνωκαν ὅτι πάντα ὅσα δέδωκάς μοι, παρὰ σοῦ εἰσιν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 8, 'ὅτι τὰ ῥήματα ἃ ἔδωκάς μοι, δέδωκα αὐτοῖς, καὶ αὐτοὶ ἔλαβον, ἀληθῶς ὅτι παρὰ σοῦ ἐξῆλθον, καὶ ἐπίστευσαν ὅτι σύ με ἀπέστειλας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 9, 'Ἐγὼ περὶ αὐτῶν ἐρωτῶ· οὐ περὶ τοῦ κόσμου ἐρωτῶ, ἀλλὰ περὶ ὧν δέδωκάς μοι, ὅτι σοί εἰσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 10, 'Καὶ τὰ ἐμὰ πάντα, σά ἐστιν, καὶ τὰ σὰ, ἐμά, καὶ δεδόξασμαι ἐν αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 11, 'Καὶ οὐκέτι εἰμὶ ἐν τῷ κόσμῳ, καὶ αὐτοὶ ἐν τῷ κόσμῳ εἰσίν, κἀγὼ πρὸς σὲ ἔρχομαι. Πάτερ Ἅγιε, τήρησον αὐτοὺς ἐν τῷ ὀνόματί σου, ᾧ δέδωκάς μοι, ἵνα ὦσιν ἓν, καθὼς ἡμεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 12, 'Ὅτε ἤμην μετʼ αὐτῶν, ἐγὼ ἐτήρουν αὐτοὺς ἐν τῷ ὀνόματί σου, ᾧ δέδωκάς μοι, καὶ ἐφύλαξα, καὶ οὐδεὶς ἐξ αὐτῶν ἀπώλετο, εἰ μὴ ὁ υἱὸς τῆς ἀπωλείας, ἵνα ἡ Γραφὴ πληρωθῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 13, 'Νῦν δὲ πρὸς σὲ ἔρχομαι, καὶ ταῦτα λαλῶ ἐν τῷ κόσμῳ, ἵνα ἔχωσιν τὴν χαρὰν τὴν ἐμὴν, πεπληρωμένην ἐν ἑαυτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 14, 'Ἐγὼ δέδωκα αὐτοῖς τὸν λόγον σου, καὶ ὁ κόσμος ἐμίσησεν αὐτούς, ὅτι οὐκ εἰσὶν ἐκ τοῦ κόσμου, καθὼς ἐγὼ οὐκ εἰμὶ ἐκ τοῦ κόσμου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 15, 'Οὐκ ἐρωτῶ ἵνα ἄρῃς αὐτοὺς ἐκ τοῦ κόσμου, ἀλλʼ ἵνα τηρήσῃς αὐτοὺς ἐκ τοῦ πονηροῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 16, 'Ἐκ τοῦ κόσμου οὐκ εἰσὶν, καθὼς ἐγὼ οὐκ εἰμὶ ἐκ τοῦ κόσμου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 17, 'Ἁγίασον αὐτοὺς ἐν τῇ ἀληθείᾳ· ὁ λόγος ὁ σὸς ἀλήθειά ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 18, 'Καθὼς ἐμὲ ἀπέστειλας εἰς τὸν κόσμον, κἀγὼ ἀπέστειλα αὐτοὺς εἰς τὸν κόσμον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 19, 'Καὶ ὑπὲρ αὐτῶν ἐγὼ ἁγιάζω ἐμαυτόν, ἵνα ὦσιν καὶ αὐτοὶ ἡγιασμένοι ἐν ἀληθείᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 20, '¶Οὐ περὶ τούτων δὲ ἐρωτῶ μόνον, ἀλλὰ καὶ περὶ τῶν πιστευόντων διὰ τοῦ λόγου αὐτῶν εἰς ἐμέ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 21, 'ἵνα πάντες ἓν ὦσιν, καθὼς σύ, Πάτερ, ἐν ἐμοὶ, κἀγὼ ἐν σοί, ἵνα καὶ αὐτοὶ ἐν ἡμῖν ὦσιν, ἵνα ὁ κόσμος πιστεύῃ ὅτι σύ με ἀπέστειλας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 22, 'Κἀγὼ τὴν δόξαν ἣν δέδωκάς μοι, δέδωκα αὐτοῖς, ἵνα ὦσιν ἓν, καθὼς ἡμεῖς ἕν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 23, 'ἐγὼ ἐν αὐτοῖς, καὶ σὺ ἐν ἐμοί, ἵνα ὦσιν τετελειωμένοι εἰς ἕν, καὶ γινώσκῃ ὁ κόσμος ὅτι σύ με ἀπέστειλας, καὶ ἠγάπησας αὐτοὺς καθὼς ἐμὲ ἠγάπησας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 24, 'Πάτερ, ὃ δέδωκάς μοι θέλω, ἵνα ὅπου εἰμὶ ἐγὼ, κἀκεῖνοι ὦσιν μετʼ ἐμοῦ, ἵνα θεωρῶσιν τὴν δόξαν τὴν ἐμὴν, ἣν ἔδωκάς μοι, ὅτι ἠγάπησάς με πρὸ καταβολῆς κόσμου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 25, '¶Πάτερ δίκαιε, καὶ ὁ κόσμος σε οὐκ ἔγνω, ἐγὼ δέ σε ἔγνων, καὶ οὗτοι ἔγνωσαν ὅτι σύ με ἀπέστειλας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 26, 'Καὶ ἐγνώρισα αὐτοῖς τὸ ὄνομά σου, καὶ γνωρίσω, ἵνα ἡ ἀγάπη ἣν ἠγάπησάς με, ἐν αὐτοῖς ᾖ, κἀγὼ ἐν αὐτοῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 1, '¶Ταῦτα εἰπὼν,  ̊Ἰησοῦς ἐξῆλθεν σὺν τοῖς μαθηταῖς αὐτοῦ πέραν τοῦ χειμάρρου τοῦ Κεδρὼν, ὅπου ἦν κῆπος, εἰς ὃν εἰσῆλθεν αὐτὸς καὶ οἱ μαθηταὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 2, 'ἬΙδει δὲ καὶ Ἰούδας, ὁ παραδιδοὺς αὐτὸν, τὸν τόπον, ὅτι πολλάκις συνήχθη  ̊Ἰησοῦς μετὰ τῶν μαθητῶν αὐτοῦ. Ἐκεῖ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 3, 'ὁ οὖν Ἰούδας λαβὼν τὴν σπεῖραν, καὶ ἐκ τῶν ἀρχιερέων καὶ Φαρισαίων ὑπηρέτας, ἔρχεται ἐκεῖ μετὰ φανῶν, καὶ λαμπάδων, καὶ ὅπλων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 4, ' ̊Ἰησοῦς οὖν εἰδὼς πάντα τὰ ἐρχόμενα ἐπʼ αὐτὸν, ἐξελθὼν εἶπεν αὐτοῖς, “Τίνα ζητεῖτε;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 5, 'Ἀπεκρίθησαν αὐτῷ, “ ̊Ἰησοῦν τὸν Ναζωραῖον.” Λέγει αὐτοῖς, “Ἐγώ εἰμι.”  ̊Ἰησοῦς εἱστήκει δὲ καὶ Ἰούδας, ὁ παραδιδοὺς αὐτὸν, μετʼ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 6, 'Ὡς οὖν εἶπεν αὐτοῖς, “Ἐγώ εἰμι”, ἀπῆλθαν εἰς τὰ ὀπίσω καὶ ἔπεσαν χαμαί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 7, 'Πάλιν οὖν ἐπηρώτησεν αὐτούς, “Τίνα ζητεῖτε;” Οἱ δὲ εἶπον, “ ̊Ἰησοῦν τὸν Ναζωραῖον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 8, 'Ἀπεκρίθη  ̊Ἰησοῦς, “Εἶπον ὑμῖν ὅτι ἐγώ εἰμι. Εἰ οὖν ἐμὲ ζητεῖτε, ἄφετε τούτους ὑπάγειν”·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 9, 'ἵνα πληρωθῇ ὁ λόγος ὃν εἶπεν, ὅτι “Οὓς δέδωκάς μοι, οὐκ ἀπώλεσα ἐξ αὐτῶν οὐδένα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 10, 'Σίμων οὖν Πέτρος ἔχων μάχαιραν, εἵλκυσεν αὐτὴν καὶ ἔπαισεν τὸν τοῦ ἀρχιερέως δοῦλον, καὶ ἀπέκοψεν αὐτοῦ τὸ ὠτάριον τὸ δεξιόν. Ἦν δὲ ὄνομα τῷ δούλῳ Μάλχος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 11, 'Εἶπεν οὖν ὁ  ̊Ἰησοῦς τῷ Πέτρῳ, “Βάλε τὴν μάχαιραν εἰς τὴν θήκην· τὸ ποτήριον ὃ δέδωκέν μοι ὁ Πατὴρ, οὐ μὴ πίω αὐτό;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 12, '¶Ἡ οὖν σπεῖρα, καὶ ὁ χιλίαρχος, καὶ οἱ ὑπηρέται τῶν Ἰουδαίων, συνέλαβον τὸν  ̊Ἰησοῦν καὶ ἔδησαν αὐτὸν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 13, 'Καὶ ἤγαγον πρὸς Ἅνναν πρῶτον, ἦν γὰρ πενθερὸς τοῦ Καϊάφα, ὃς ἦν ἀρχιερεὺς τοῦ ἐνιαυτοῦ ἐκείνου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 14, 'Ἦν δὲ Καϊάφας ὁ συμβουλεύσας τοῖς Ἰουδαίοις ὅτι συμφέρει ἕνα ἄνθρωπον ἀποθανεῖν ὑπὲρ τοῦ λαοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 15, '¶Ἠκολούθει δὲ τῷ  ̊Ἰησοῦ Σίμων Πέτρος καὶ ἄλλος μαθητής. Ὁ δὲ μαθητὴς ἐκεῖνος ἦν γνωστὸς τῷ ἀρχιερεῖ, καὶ συνεισῆλθεν τῷ  ̊Ἰησοῦ εἰς τὴν αὐλὴν τοῦ ἀρχιερέως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 16, 'Ὁ δὲ Πέτρος εἱστήκει πρὸς τῇ θύρᾳ ἔξω. Ἐξῆλθεν οὖν ὁ μαθητὴς ὁ ἄλλος ὁ ἦν γνωστὸς τοῦ ἀρχιερέως, καὶ εἶπεν τῇ θυρωρῷ καὶ εἰσήγαγεν τὸν Πέτρον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 17, 'Λέγει οὖν ἡ παιδίσκη ἡ θυρωρὸς τῷ Πέτρῳ, “Μὴ καὶ σὺ ἐκ τῶν μαθητῶν εἶ τοῦ ἀνθρώπου τούτου;” Λέγει ἐκεῖνος, “Οὐκ εἰμί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 18, 'Εἱστήκεισαν δὲ οἱ δοῦλοι καὶ οἱ ὑπηρέται, ἀνθρακιὰν πεποιηκότες, ὅτι ψῦχος ἦν, καὶ ἐθερμαίνοντο· ἦν δὲ καὶ ὁ Πέτρος μετʼ αὐτῶν ἑστὼς καὶ θερμαινόμενος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 19, '¶Ὁ οὖν ἀρχιερεὺς ἠρώτησεν τὸν  ̊Ἰησοῦν περὶ τῶν μαθητῶν αὐτοῦ, καὶ περὶ τῆς διδαχῆς αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 20, 'Ἀπεκρίθη αὐτῷ  ̊Ἰησοῦς, “Ἐγὼ παρρησίᾳ λελάληκα τῷ κόσμῳ· ἐγὼ πάντοτε ἐδίδαξα ἐν συναγωγῇ καὶ ἐν τῷ ἱερῷ, ὅπου πάντες οἱ Ἰουδαῖοι συνέρχονται, καὶ ἐν κρυπτῷ ἐλάλησα οὐδέν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 21, 'Τί με ἐρωτᾷς; Ἐρώτησον τοὺς ἀκηκοότας τί ἐλάλησα αὐτοῖς· ἴδε, οὗτοι οἴδασιν ἃ εἶπον ἐγώ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 22, 'Ταῦτα δὲ αὐτοῦ εἰπόντος, εἷς παρεστηκὼς τῶν ὑπηρετῶν ἔδωκεν ῥάπισμα τῷ  ̊Ἰησοῦ εἰπών, “Οὕτως ἀποκρίνῃ τῷ ἀρχιερεῖ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 23, 'Ἀπεκρίθη αὐτῷ  ̊Ἰησοῦς, “Εἰ κακῶς ἐλάλησα, μαρτύρησον περὶ τοῦ κακοῦ· εἰ δὲ καλῶς, τί με δέρεις;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 24, 'Ἀπέστειλεν οὖν αὐτὸν ὁ Ἅννας, δεδεμένον πρὸς Καϊάφαν τὸν ἀρχιερέα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 25, '¶Ἦν δὲ Σίμων Πέτρος ἑστὼς καὶ θερμαινόμενος. Εἶπον οὖν αὐτῷ, “Μὴ καὶ σὺ ἐκ τῶν μαθητῶν αὐτοῦ εἶ;” Ἠρνήσατο ἐκεῖνος καὶ εἶπεν, “Οὐκ εἰμί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 26, 'Λέγει εἷς ἐκ τῶν δούλων τοῦ ἀρχιερέως, συγγενὴς ὢν οὗ ἀπέκοψεν Πέτρος τὸ ὠτίον, “Οὐκ ἐγώ σε εἶδον ἐν τῷ κήπῳ μετʼ αὐτοῦ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 27, 'Πάλιν οὖν ἠρνήσατο Πέτρος, καὶ εὐθέως ἀλέκτωρ ἐφώνησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 28, '¶Ἄγουσιν οὖν τὸν  ̊Ἰησοῦν ἀπὸ τοῦ Καϊάφα εἰς τὸ πραιτώριον· ἦν δὲ πρωΐ. Καὶ αὐτοὶ οὐκ εἰσῆλθον εἰς τὸ πραιτώριον, ἵνα μὴ μιανθῶσιν, ἀλλὰ φάγωσιν τὸ Πάσχα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 29, 'Ἐξῆλθεν οὖν ὁ Πιλᾶτος ἔξω πρὸς αὐτοὺς καὶ φησίν, “Τίνα κατηγορίαν φέρετε κατὰ τοῦ ἀνθρώπου τούτου;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 30, 'Ἀπεκρίθησαν καὶ εἶπαν αὐτῷ, “Εἰ μὴ ἦν οὗτος κακὸν ποιῶν, οὐκ ἄν σοι παρεδώκαμεν αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 31, 'Εἶπεν οὖν αὐτοῖς Πιλᾶτος, “Λάβετε αὐτὸν ὑμεῖς, καὶ κατὰ τὸν νόμον ὑμῶν, κρίνατε αὐτόν.” Εἶπον αὐτῷ οἱ Ἰουδαῖοι, “Ἡμῖν οὐκ ἔξεστιν ἀποκτεῖναι οὐδένα”·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 32, 'ἵνα ὁ λόγος τοῦ  ̊Ἰησοῦ πληρωθῇ, ὃν εἶπεν, σημαίνων ποίῳ θανάτῳ ἤμελλεν ἀποθνῄσκειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 33, '¶Εἰσῆλθεν οὖν πάλιν εἰς τὸ πραιτώριον ὁ Πιλᾶτος, καὶ ἐφώνησεν τὸν  ̊Ἰησοῦν καὶ εἶπεν αὐτῷ, “Σὺ εἶ ὁ βασιλεὺς τῶν Ἰουδαίων;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 34, 'Ἀπεκρίθη  ̊Ἰησοῦς, “Ἀπὸ σεαυτοῦ σὺ τοῦτο λέγεις, ἢ ἄλλοι εἶπόν σοι περὶ ἐμοῦ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 35, 'Ἀπεκρίθη ὁ Πιλᾶτος, “Μήτι ἐγὼ Ἰουδαῖός εἰμι; Τὸ ἔθνος τὸ σὸν καὶ οἱ ἀρχιερεῖς παρέδωκάν σε ἐμοί. Τί ἐποίησας;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 36, 'Ἀπεκρίθη  ̊Ἰησοῦς, “Ἡ βασιλεία ἡ ἐμὴ οὐκ ἔστιν ἐκ τοῦ κόσμου τούτου· εἰ ἐκ τοῦ κόσμου τούτου ἦν ἡ βασιλεία ἡ ἐμή, οἱ ὑπηρέται οἱ ἐμοὶ ἠγωνίζοντο ἄν, ἵνα μὴ παραδοθῶ τοῖς Ἰουδαίοις. Νῦν δὲ ἡ βασιλεία ἡ ἐμὴ οὐκ ἔστιν ἐντεῦθεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 37, 'Εἶπεν οὖν αὐτῷ ὁ Πιλᾶτος, “Οὐκοῦν βασιλεὺς εἶ σύ;” Ἀπεκρίθη ὁ  ̊Ἰησοῦς, “Σὺ λέγεις ὅτι βασιλεύς εἰμι Ἐγὼ. εἰς τοῦτο γεγέννημαι, καὶ εἰς τοῦτο ἐλήλυθα εἰς τὸν κόσμον, ἵνα μαρτυρήσω τῇ ἀληθείᾳ. Πᾶς ὁ ὢν ἐκ τῆς ἀληθείας, ἀκούει μου τῆς φωνῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 38, 'Λέγει αὐτῷ ὁ Πιλᾶτος, “Τί ἐστιν ἀλήθεια;” ¶Καὶ τοῦτο εἰπὼν, πάλιν ἐξῆλθεν πρὸς τοὺς Ἰουδαίους, καὶ λέγει αὐτοῖς, “Ἐγὼ οὐδεμίαν εὑρίσκω ἐν αὐτῷ αἰτίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 39, 'Ἔστιν δὲ συνήθεια ὑμῖν, ἵνα ἕνα ἀπολύσω ὑμῖν ἐν τῷ Πάσχα· βούλεσθε οὖν ἀπολύσω ὑμῖν τὸν Βασιλέα τῶν Ἰουδαίων;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 40, 'Ἐκραύγασαν οὖν πάλιν λέγοντες, “Μὴ τοῦτον, ἀλλὰ τὸν Βαραββᾶν!” Ἦν δὲ ὁ Βαραββᾶς λῃστής.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 1, '¶Τότε οὖν ἔλαβεν ὁ Πιλᾶτος τὸν  ̊Ἰησοῦν καὶ ἐμαστίγωσεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 2, 'Καὶ οἱ στρατιῶται πλέξαντες στέφανον ἐξ ἀκανθῶν, ἐπέθηκαν αὐτοῦ τῇ κεφαλῇ, καὶ ἱμάτιον πορφυροῦν περιέβαλον αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 3, 'καὶ ἤρχοντο πρὸς αὐτὸν καὶ ἔλεγον, “Χαῖρε, ὁ Βασιλεὺς τῶν Ἰουδαίων!” Καὶ ἐδίδοσαν αὐτῷ ῥαπίσματα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 4, 'Καὶ ἐξῆλθεν πάλιν ἔξω ὁ Πιλᾶτος, καὶ λέγει αὐτοῖς, “Ἴδε, ἄγω ὑμῖν αὐτὸν ἔξω, ἵνα γνῶτε ὅτι αἰτίαν ἐν αὐτῷ οὐχ εὑρίσκω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 5, 'Ἐξῆλθεν οὖν ὁ  ̊Ἰησοῦς ἔξω, φορῶν τὸν ἀκάνθινον στέφανον καὶ τὸ πορφυροῦν ἱμάτιον. Καὶ λέγει αὐτοῖς, “Ἰδοὺ, ὁ ἄνθρωπος!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 6, 'Ὅτε οὖν εἶδον αὐτὸν οἱ ἀρχιερεῖς καὶ οἱ ὑπηρέται, ἐκραύγασαν λέγοντες, “Σταύρωσον! Σταύρωσον!” Λέγει αὐτοῖς ὁ Πιλᾶτος, “Λάβετε αὐτὸν ὑμεῖς καὶ σταυρώσατε, ἐγὼ γὰρ οὐχ εὑρίσκω ἐν αὐτῷ αἰτίαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 7, 'Ἀπεκρίθησαν αὐτῷ οἱ Ἰουδαῖοι, “Ἡμεῖς νόμον ἔχομεν, καὶ κατὰ τὸν νόμον ὀφείλει ἀποθανεῖν, ὅτι Υἱὸν  ̊Θεοῦ ἑαυτὸν ἐποίησεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 8, '¶Ὅτε οὖν ἤκουσεν ὁ Πιλᾶτος τοῦτον τὸν λόγον, μᾶλλον ἐφοβήθη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 9, 'Καὶ εἰσῆλθεν εἰς τὸ πραιτώριον πάλιν, καὶ λέγει τῷ  ̊Ἰησοῦ, “Πόθεν εἶ σύ;” Ὁ δὲ  ̊Ἰησοῦς ἀπόκρισιν οὐκ ἔδωκεν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 10, 'Λέγει οὖν αὐτῷ ὁ Πιλᾶτος, “Ἐμοὶ οὐ λαλεῖς; Οὐκ οἶδας ὅτι ἐξουσίαν ἔχω ἀπολῦσαί σε, καὶ ἐξουσίαν ἔχω σταυρῶσαί σε;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 11, 'Ἀπεκρίθη αὐτῷ  ̊Ἰησοῦς, “Οὐκ εἶχες ἐξουσίαν κατʼ ἐμοῦ οὐδεμίαν, εἰ μὴ ἦν δεδομένον σοι ἄνωθεν. Διὰ τοῦτο ὁ παραδούς μέ σοι, μείζονα ἁμαρτίαν ἔχει.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 12, 'Ἐκ τούτου ὁ Πιλᾶτος ἐζήτει ἀπολῦσαι αὐτόν. Οἱ δὲ Ἰουδαῖοι ἐκραύγασαν λέγοντες, “Ἐὰν τοῦτον ἀπολύσῃς, οὐκ εἶ φίλος τοῦ Καίσαρος. Πᾶς ὁ βασιλέα ἑαυτὸν ποιῶν, ἀντιλέγει τῷ Καίσαρι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 13, '¶Ὁ οὖν Πιλᾶτος, ἀκούσας τῶν λόγων τούτων, ἤγαγεν ἔξω τὸν  ̊Ἰησοῦν, καὶ ἐκάθισεν ἐπὶ βήματος, εἰς τόπον λεγόμενον Λιθόστρωτον, Ἑβραϊστὶ δὲ, Γαββαθᾶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 14, 'Ἦν δὲ παρασκευὴ τοῦ Πάσχα, ὥρα ἦν ὡς ἕκτη. Καὶ λέγει τοῖς Ἰουδαίοις, “Ἴδε, ὁ βασιλεὺς ὑμῶν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 15, 'Οἱ δὲ ἐκραύγασαν, “Ἆρον! Ἆρον! Σταύρωσον αὐτόν!” Λέγει αὐτοῖς ὁ Πιλᾶτος, “Τὸν βασιλέα ὑμῶν σταυρώσω;” Ἀπεκρίθησαν οἱ ἀρχιερεῖς, “Οὐκ ἔχομεν βασιλέα, εἰ μὴ Καίσαρα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 16, 'Τότε οὖν παρέδωκεν αὐτὸν αὐτοῖς, ἵνα σταυρωθῇ. ¶Παρέλαβον Δὲ τὸν  ̊Ἰησοῦν· αὑτόν ἀπήγαγον');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 17, 'Καὶ βαστάζων ἑαυτῷ τὸν σταυρὸν, ἐξῆλθεν εἰς τὸν λεγόμενον, “Κρανίου Τόπον”, ὃ λέγεται Ἑβραϊστὶ, Γολγοθᾶ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 18, 'ὅπου αὐτὸν ἐσταύρωσαν, καὶ μετʼ αὐτοῦ ἄλλους δύο, ἐντεῦθεν καὶ ἐντεῦθεν, μέσον δὲ τὸν  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 19, 'Ἔγραψεν δὲ καὶ τίτλον ὁ Πιλᾶτος, καὶ ἔθηκεν ἐπὶ τοῦ σταυροῦ. Ἦν δὲ γεγραμμένον, “ ̊Ἰησοῦς ὁ Ναζωραῖος, ὁ Βασιλεὺς τῶν Ἰουδαίων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 20, 'Τοῦτον οὖν τὸν τίτλον πολλοὶ ἀνέγνωσαν τῶν Ἰουδαίων, ὅτι ἐγγὺς ἦν ὁ τόπος τῆς πόλεως, ὅπου ἐσταυρώθη ὁ  ̊Ἰησοῦς· καὶ ἦν γεγραμμένον Ἑβραϊστί, Ῥωμαϊστί, Ἑλληνιστί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 21, 'Ἔλεγον οὖν τῷ Πιλάτῳ οἱ ἀρχιερεῖς τῶν Ἰουδαίων, “Μὴ γράφε, ‘Ὁ Βασιλεὺς τῶν Ἰουδαίων’, ἀλλʼ ὅτι ἐκεῖνος εἶπεν, ‘Βασιλεὺς εἰμι τῶν Ἰουδαίων.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 22, 'Ἀπεκρίθη ὁ Πιλᾶτος, “Ὃ γέγραφα, γέγραφα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 23, 'Οἱ οὖν στρατιῶται ὅτε ἐσταύρωσαν τὸν  ̊Ἰησοῦν, ἔλαβον τὰ ἱμάτια αὐτοῦ, καὶ ἐποίησαν τέσσαρα μέρη, ἑκάστῳ στρατιώτῃ μέρος, καὶ τὸν χιτῶνα. Ἦν δὲ ὁ χιτὼν ἄραφος, ἐκ τῶν ἄνωθεν ὑφαντὸς διʼ ὅλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 24, 'Εἶπον οὖν πρὸς ἀλλήλους, “Μὴ σχίσωμεν αὐτόν, ἀλλὰ λάχωμεν περὶ αὐτοῦ, τίνος ἔσται”· ἵνα ἡ Γραφὴ πληρωθῇ ἡ λέγουσα, “Διεμερίσαντο τὰ ἱμάτιά μου ἑαυτοῖς, καὶ ἐπὶ τὸν ἱματισμόν μου ἔβαλον κλῆρον.” Οἱ μὲν οὖν στρατιῶται ταῦτα ἐποίησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 25, 'Εἱστήκεισαν δὲ παρὰ τῷ σταυρῷ τοῦ  ̊Ἰησοῦ ἡ μήτηρ αὐτοῦ, καὶ ἡ ἀδελφὴ τῆς μητρὸς αὐτοῦ, Μαρία ἡ τοῦ Κλωπᾶ, καὶ Μαρία ἡ Μαγδαληνή.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 26, ' ̊Ἰησοῦς οὖν ἰδὼν τὴν μητέρα, καὶ τὸν μαθητὴν παρεστῶτα ὃν ἠγάπα, λέγει τῇ μητρί, “Γύναι, ἰδοὺ, ὁ υἱός σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 27, 'Εἶτα λέγει τῷ μαθητῇ, “Ἴδε, ἡ μήτηρ σου.” Καὶ ἀπʼ ἐκείνης τῆς ὥρας ἔλαβεν ὁ μαθητὴς αὐτὴν εἰς τὰ ἴδια.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 28, '¶Μετὰ τοῦτο εἰδὼς ὁ  ̊Ἰησοῦς ὅτι ἤδη πάντα τετέλεσται, ἵνα τελειωθῇ ἡ Γραφὴ, λέγει, “Διψῶ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 29, 'Σκεῦος ἔκειτο ὄξους μεστόν· σπόγγον οὖν μεστὸν τοῦ ὄξους ὑσσώπῳ περιθέντες, προσήνεγκαν αὐτοῦ τῷ στόματι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 30, 'Ὅτε οὖν ἔλαβεν τὸ ὄξος ὁ  ̊Ἰησοῦς, εἶπεν, “Τετέλεσται!” Καὶ κλίνας τὴν κεφαλὴν, παρέδωκεν τὸ πνεῦμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 31, '¶Οἱ οὖν Ἰουδαῖοι, ἐπεὶ παρασκευὴ ἦν, ἵνα μὴ μείνῃ ἐπὶ τοῦ σταυροῦ τὰ σώματα ἐν τῷ Σαββάτῳ (ἦν γὰρ μεγάλη ἡ ἡμέρα ἐκείνου τοῦ Σαββάτου), ἠρώτησαν τὸν Πιλᾶτον ἵνα κατεαγῶσιν αὐτῶν τὰ σκέλη, καὶ ἀρθῶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 32, 'Ἦλθον οὖν οἱ στρατιῶται, καὶ τοῦ μὲν πρώτου κατέαξαν τὰ σκέλη, καὶ τοῦ ἄλλου τοῦ συσταυρωθέντος αὐτῷ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 33, 'ἐπὶ δὲ τὸν  ̊Ἰησοῦν ἐλθόντες, ὡς εἶδον ἤδη αὐτὸν τεθνηκότα, οὐ κατέαξαν αὐτοῦ τὰ σκέλη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 34, 'Ἀλλʼ εἷς τῶν στρατιωτῶν λόγχῃ αὐτοῦ τὴν πλευρὰν ἔνυξεν, καὶ ἐξῆλθεν εὐθὺς αἷμα καὶ ὕδωρ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 35, 'Καὶ ὁ ἑωρακὼς μεμαρτύρηκεν, καὶ ἀληθινὴ αὐτοῦ ἐστιν ἡ μαρτυρία, καὶ ἐκεῖνος οἶδεν ὅτι ἀληθῆ λέγει, ἵνα καὶ ὑμεῖς πιστεύητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 36, 'Ἐγένετο γὰρ ταῦτα, ἵνα ἡ Γραφὴ πληρωθῇ, “Ὀστοῦν οὐ συντριβήσεται αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 37, 'Καὶ πάλιν ἑτέρα Γραφὴ λέγει, “Ὄψονται εἰς ὃν ἐξεκέντησαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 38, '¶Μετὰ δὲ ταῦτα, ἠρώτησεν τὸν Πιλᾶτον Ἰωσὴφ ὁ ἀπὸ Ἁριμαθαίας, ὢν μαθητὴς τοῦ  ̊Ἰησοῦ, κεκρυμμένος δὲ διὰ τὸν φόβον τῶν Ἰουδαίων, ἵνα ἄρῃ τὸ σῶμα τοῦ  ̊Ἰησοῦ· καὶ ἐπέτρεψεν ὁ Πιλᾶτος. Ἦλθον οὖν καὶ ἦραν αὑτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 39, 'Ἦλθεν δὲ καὶ Νικόδημος, ὁ ἐλθὼν πρὸς αὐτὸν νυκτὸς τὸ πρῶτον, φέρων ἕλιγμα σμύρνης καὶ ἀλόης, ὡσεὶ λίτρας ἑκατόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 40, 'Ἔλαβον οὖν τὸ σῶμα τοῦ  ̊Ἰησοῦ, καὶ ἔδησαν αὐτὸ ὀθονίοις μετὰ τῶν ἀρωμάτων, καθὼς ἔθος ἐστὶν τοῖς Ἰουδαίοις ἐνταφιάζειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 41, 'Ἦν δὲ ἐν τῷ τόπῳ ὅπου ἐσταυρώθη κῆπος, καὶ ἐν τῷ κήπῳ μνημεῖον καινόν, ἐν ᾧ οὐδέπω οὐδεὶς ἦν τεθειμένος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 42, 'Ἐκεῖ οὖν διὰ τὴν παρασκευὴν τῶν Ἰουδαίων, ὅτι ἐγγὺς ἦν τὸ μνημεῖον, ἔθηκαν τὸν  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 1, '¶Τῇ δὲ μιᾷ τῶν σαββάτων, Μαρία ἡ Μαγδαληνὴ ἔρχεται πρωῒ, σκοτίας ἔτι οὔσης, εἰς τὸ μνημεῖον, καὶ βλέπει τὸν λίθον ἠρμένον ἐκ τοῦ μνημείου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 2, 'Τρέχει οὖν καὶ ἔρχεται πρὸς Σίμωνα Πέτρον, καὶ πρὸς τὸν ἄλλον μαθητὴν ὃν ἐφίλει ὁ  ̊Ἰησοῦς, καὶ λέγει αὐτοῖς, “Ἦραν τὸν  ̊Κύριον ἐκ τοῦ μνημείου, καὶ οὐκ οἴδαμεν ποῦ ἔθηκαν αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 3, 'Ἐξῆλθεν οὖν ὁ Πέτρος καὶ ὁ ἄλλος μαθητής, καὶ ἤρχοντο εἰς τὸ μνημεῖον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 4, 'Ἔτρεχον δὲ οἱ δύο ὁμοῦ, καὶ ὁ ἄλλος μαθητὴς προέδραμεν τάχιον τοῦ Πέτρου, καὶ ἦλθεν πρῶτος εἰς τὸ μνημεῖον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 5, 'Καὶ παρακύψας, βλέπει κείμενα τὰ ὀθόνια, οὐ μέντοι εἰσῆλθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 6, 'Ἔρχεται οὖν καὶ Σίμων Πέτρος ἀκολουθῶν αὐτῷ, καὶ εἰσῆλθεν εἰς τὸ μνημεῖον, καὶ θεωρεῖ τὰ ὀθόνια κείμενα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 7, 'καὶ τὸ σουδάριον, ὃ ἦν ἐπὶ τῆς κεφαλῆς αὐτοῦ, οὐ μετὰ τῶν ὀθονίων κείμενον, ἀλλὰ χωρὶς ἐντετυλιγμένον εἰς ἕνα τόπον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 8, 'Τότε οὖν εἰσῆλθεν καὶ ὁ ἄλλος μαθητὴς, ὁ ἐλθὼν πρῶτος εἰς τὸ μνημεῖον, καὶ εἶδεν καὶ ἐπίστευσεν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 9, 'οὐδέπω γὰρ ᾔδεισαν τὴν Γραφὴν ὅτι δεῖ αὐτὸν ἐκ νεκρῶν ἀναστῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 10, 'Ἀπῆλθον οὖν πάλιν πρὸς αὑτοὺς οἱ μαθηταί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 11, '¶Μαρία δὲ εἱστήκει πρὸς τῷ μνημείῳ ἔξω κλαίουσα. Ὡς οὖν ἔκλαιεν, παρέκυψεν εἰς τὸ μνημεῖον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 12, 'καὶ θεωρεῖ δύο ἀγγέλους ἐν λευκοῖς καθεζομένους, ἕνα πρὸς τῇ κεφαλῇ, καὶ ἕνα πρὸς τοῖς ποσίν, ὅπου ἔκειτο τὸ σῶμα τοῦ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 13, 'Καὶ λέγουσιν αὐτῇ ἐκεῖνοι, “Γύναι, τί κλαίεις;” Λέγει αὐτοῖς, “Ὅτι ἦραν τὸν  ̊Κύριόν μου, καὶ οὐκ οἶδα ποῦ ἔθηκαν αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 14, 'Ταῦτα εἰποῦσα, ἐστράφη εἰς τὰ ὀπίσω, καὶ θεωρεῖ τὸν  ̊Ἰησοῦν ἑστῶτα, καὶ οὐκ ᾔδει ὅτι  ̊Ἰησοῦς ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 15, 'Λέγει αὐτῇ  ̊Ἰησοῦς, “Γύναι, τί κλαίεις; Τίνα ζητεῖς;” Ἐκείνη δοκοῦσα ὅτι ὁ κηπουρός ἐστιν, λέγει αὐτῷ, “Κύριε, εἰ σὺ ἐβάστασας αὐτόν, εἰπέ μοι ποῦ ἔθηκας αὐτόν, κἀγὼ αὐτὸν ἀρῶ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 16, 'Λέγει αὐτῇ ὁ  ̊Ἰησοῦς, “Μαριάμ!” Στραφεῖσα ἐκείνη λέγει αὐτῷ Ἑβραϊστί, “Ραββουνί” (ὃ λέγεται, “Διδάσκαλε”).');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 17, 'Λέγει αὐτῇ ὁ  ̊Ἰησοῦς, “Μή μου ἅπτου, οὔπω γὰρ ἀναβέβηκα πρὸς τὸν Πατέρα· πορεύου δὲ πρὸς τοὺς ἀδελφούς μου, καὶ εἰπὲ αὐτοῖς, ‘Ἀναβαίνω πρὸς τὸν Πατέρα μου, καὶ Πατέρα ὑμῶν, καὶ  ̊Θεόν μου, καὶ  ̊Θεὸν ὑμῶν.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 18, 'Ἔρχεται Μαριὰμ ἡ Μαγδαληνὴ ἀγγέλλουσα τοῖς μαθηταῖς, ὅτι “Ἑώρακα τὸν  ̊Κύριον”, καὶ ταῦτα εἶπεν αὐτῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 19, '¶Οὔσης οὖν ὀψίας τῇ ἡμέρᾳ ἐκείνῃ τῇ μιᾷ σαββάτων, καὶ τῶν θυρῶν κεκλεισμένων ὅπου ἦσαν οἱ μαθηταὶ διὰ τὸν φόβον τῶν Ἰουδαίων, ἦλθεν ὁ  ̊Ἰησοῦς καὶ ἔστη εἰς τὸ μέσον, καὶ λέγει αὐτοῖς, “Εἰρήνη ὑμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 20, 'Καὶ τοῦτο εἰπὼν, ἔδειξεν τὰς χεῖρας καὶ τὴν πλευρὰν αὐτοῖς. Ἐχάρησαν οὖν οἱ μαθηταὶ, ἰδόντες τὸν  ̊Κύριον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 21, 'Εἶπεν οὖν αὐτοῖς ὁ  ̊Ἰησοῦς πάλιν, “Εἰρήνη ὑμῖν· καθὼς ἀπέσταλκέν με ὁ Πατήρ, κἀγὼ πέμπω ὑμᾶς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 22, 'Καὶ τοῦτο εἰπὼν, ἐνεφύσησεν καὶ λέγει αὐτοῖς, “Λάβετε  ̊Πνεῦμα Ἅγιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 23, 'Ἄν τινων ἀφῆτε τὰς ἁμαρτίας, ἀφέωνται αὐτοῖς· ἄν τινων κρατῆτε, κεκράτηνται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 24, '¶Θωμᾶς δὲ, εἷς ἐκ τῶν δώδεκα, ὁ λεγόμενος Δίδυμος, οὐκ ἦν μετʼ αὐτῶν ὅτε ἦλθεν  ̊Ἰησοῦς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 25, 'Ἔλεγον οὖν αὐτῷ οἱ ἄλλοι μαθηταί, “Ἑωράκαμεν τὸν  ̊Κύριον.” Ὁ δὲ εἶπεν αὐτοῖς, “Ἐὰν μὴ ἴδω ἐν ταῖς χερσὶν αὐτοῦ τὸν τύπον τῶν ἥλων, καὶ βάλω τὸν δάκτυλόν μου εἰς τὸν τύπον τῶν ἥλων, καὶ βάλω μου τὴν χεῖραν εἰς τὴν πλευρὰν αὐτοῦ, οὐ μὴ πιστεύσω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 26, '¶Καὶ μεθʼ ἡμέρας ὀκτὼ πάλιν ἦσαν ἔσω οἱ μαθηταὶ αὐτοῦ, καὶ Θωμᾶς μετʼ αὐτῶν. Ἔρχεται ὁ  ̊Ἰησοῦς, τῶν θυρῶν κεκλεισμένων, καὶ ἔστη εἰς τὸ μέσον, καὶ εἶπεν, “Εἰρήνη ὑμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 27, 'Εἶτα λέγει τῷ Θωμᾷ, “Φέρε τὸν δάκτυλόν σου ὧδε, καὶ ἴδε τὰς χεῖράς μου, καὶ φέρε τὴν χεῖρά σου, καὶ βάλε εἰς τὴν πλευράν μου, καὶ μὴ γίνου ἄπιστος, ἀλλὰ πιστός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 28, 'Ἀπεκρίθη Θωμᾶς καὶ εἶπεν αὐτῷ, “Ὁ  ̊Κύριός μου καὶ ὁ  ̊Θεός μου!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 29, 'Λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Ὅτι ἑώρακάς με, πεπίστευκας· μακάριοι οἱ μὴ ἰδόντες, καὶ πιστεύσαντες.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 30, '¶Πολλὰ μὲν οὖν καὶ ἄλλα σημεῖα ἐποίησεν ὁ  ̊Ἰησοῦς ἐνώπιον τῶν μαθητῶν αὐτοῦ, ἃ οὐκ ἔστιν γεγραμμένα ἐν τῷ βιβλίῳ τούτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 31, 'Ταῦτα δὲ γέγραπται, ἵνα πιστεύητε ὅτι  ̊Ἰησοῦς ἐστιν ὁ  ̊Χριστὸς, ὁ Υἱὸς τοῦ  ̊Θεοῦ, καὶ ἵνα πιστεύοντες, ζωὴν ἔχητε ἐν τῷ ὀνόματι αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 1, '¶Μετὰ ταῦτα, ἐφανέρωσεν ἑαυτὸν πάλιν  ̊Ἰησοῦς τοῖς μαθηταῖς ἐπὶ τῆς θαλάσσης τῆς Τιβεριάδος· ἐφανέρωσεν δὲ οὕτως:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 2, 'ἦσαν ὁμοῦ Σίμων Πέτρος, καὶ Θωμᾶς ὁ λεγόμενος Δίδυμος, καὶ Ναθαναὴλ ὁ ἀπὸ Κανὰ τῆς Γαλιλαίας, καὶ οἱ τοῦ Ζεβεδαίου, καὶ ἄλλοι ἐκ τῶν μαθητῶν αὐτοῦ δύο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 3, 'Λέγει αὐτοῖς Σίμων Πέτρος, “Ὑπάγω ἁλιεύειν.” Λέγουσιν αὐτῷ, “Ἐρχόμεθα καὶ ἡμεῖς σὺν σοί.” Ἐξῆλθον καὶ ἐνέβησαν εἰς τὸ πλοῖον, καὶ ἐν ἐκείνῃ τῇ νυκτὶ ἐπίασαν οὐδέν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 4, '¶Πρωΐας δὲ ἤδη γινομένης, ἔστη  ̊Ἰησοῦς εἰς τὸν αἰγιαλόν· οὐ μέντοι ᾔδεισαν οἱ μαθηταὶ ὅτι  ̊Ἰησοῦς ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 5, 'Λέγει οὖν αὐτοῖς  ̊Ἰησοῦς, “Παιδία, μή τι προσφάγιον ἔχετε;” Ἀπεκρίθησαν αὐτῷ, “Οὔ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 6, 'Ὁ δὲ εἶπεν αὐτοῖς, “Βάλετε εἰς τὰ δεξιὰ μέρη τοῦ πλοίου τὸ δίκτυον, καὶ εὑρήσετε.” Ἔβαλον οὖν, καὶ οὐκέτι αὐτὸ ἑλκύσαι ἴσχυον ἀπὸ τοῦ πλήθους τῶν ἰχθύων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 7, 'Λέγει οὖν ὁ μαθητὴς ἐκεῖνος ὃν ἠγάπα ὁ  ̊Ἰησοῦς τῷ Πέτρῳ, “Ὁ  ̊Κύριός ἐστιν.” Σίμων οὖν Πέτρος ἀκούσας ὅτι ὁ  ̊Κύριός ἐστιν, τὸν ἐπενδύτην διεζώσατο, ἦν γὰρ γυμνός, καὶ ἔβαλεν ἑαυτὸν εἰς τὴν θάλασσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 8, 'Οἱ δὲ ἄλλοι μαθηταὶ τῷ πλοιαρίῳ ἦλθον, οὐ γὰρ ἦσαν μακρὰν ἀπὸ τῆς γῆς, ἀλλὰ ὡς ἀπὸ πηχῶν διακοσίων, σύροντες τὸ δίκτυον τῶν ἰχθύων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 9, '¶Ὡς οὖν ἀπέβησαν εἰς τὴν γῆν, βλέπουσιν ἀνθρακιὰν κειμένην, καὶ ὀψάριον ἐπικείμενον, καὶ ἄρτον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 10, 'Λέγει αὐτοῖς ὁ  ̊Ἰησοῦς, “Ἐνέγκατε ἀπὸ τῶν ὀψαρίων ὧν ἐπιάσατε νῦν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 11, 'Ἀνέβη οὖν Σίμων Πέτρος, καὶ εἵλκυσεν τὸ δίκτυον εἰς τὴν γῆν μεστὸν ἰχθύων μεγάλων ἑκατὸν πεντήκοντα τριῶν· καὶ τοσούτων ὄντων, οὐκ ἐσχίσθη τὸ δίκτυον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 12, 'Λέγει αὐτοῖς ὁ  ̊Ἰησοῦς, “Δεῦτε, ἀριστήσατε.” Οὐδεὶς δὲ ἐτόλμα τῶν μαθητῶν ἐξετάσαι αὐτόν, “Σὺ τίς εἶ;” Εἰδότες ὅτι ὁ  ̊Κύριός ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 13, 'Ἔρχεται  ̊Ἰησοῦς, καὶ λαμβάνει τὸν ἄρτον καὶ δίδωσιν αὐτοῖς, καὶ τὸ ὀψάριον ὁμοίως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 14, 'Τοῦτο ἤδη τρίτον ἐφανερώθη  ̊Ἰησοῦς τοῖς μαθηταῖς, ἐγερθεὶς ἐκ νεκρῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 15, '¶Ὅτε οὖν ἠρίστησαν, λέγει τῷ Σίμωνι Πέτρῳ ὁ  ̊Ἰησοῦς, “Σίμων Ἰωάννου, ἀγαπᾷς με πλέον τούτων;” Λέγει αὐτῷ, “Ναί,  ̊Κύριε, σὺ οἶδας ὅτι φιλῶ σε.” Λέγει αὐτῷ, “Βόσκε τὰ ἀρνία μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 16, 'Λέγει αὐτῷ πάλιν δεύτερον, “Σίμων Ἰωάννου, ἀγαπᾷς με;” Λέγει αὐτῷ, “Ναί,  ̊Κύριε, σὺ οἶδας ὅτι φιλῶ σε.” Λέγει αὐτῷ, “Ποίμαινε τὰ πρόβατά μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 17, 'Λέγει αὐτῷ τὸ τρίτον, “Σίμων Ἰωάννου, φιλεῖς με;” Ἐλυπήθη ὁ Πέτρος ὅτι εἶπεν αὐτῷ τὸ τρίτον, “Φιλεῖς με;” Καὶ λέγει αὐτῷ, “ ̊Κύριε, πάντα σὺ οἶδας, σὺ γινώσκεις ὅτι φιλῶ σε.” Λέγει αὐτῷ  ̊Ἰησοῦς, “Βόσκε τὰ προβάτιά μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 18, 'Ἀμὴν, ἀμὴν, λέγω σοι, ὅτε ἦς νεώτερος, ἐζώννυες σεαυτὸν, καὶ περιεπάτεις ὅπου ἤθελες· ὅταν δὲ γηράσῃς, ἐκτενεῖς τὰς χεῖράς σου, καὶ ἄλλος ζώσουσιν σε, καὶ οἴσει ὅπου οὐ θέλεις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 19, 'Τοῦτο δὲ εἶπεν, σημαίνων ποίῳ θανάτῳ δοξάσει τὸν  ̊Θεόν. Καὶ τοῦτο εἰπὼν, λέγει αὐτῷ, “Ἀκολούθει μοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 20, '¶Ἐπιστραφεὶς, ὁ Πέτρος βλέπει τὸν μαθητὴν ὃν ἠγάπα ὁ  ̊Ἰησοῦς ἀκολουθοῦντα, ὃς καὶ ἀνέπεσεν ἐν τῷ δείπνῳ ἐπὶ τὸ στῆθος αὐτοῦ καὶ εἶπεν, “ ̊Κύριε, τίς ἐστιν, ὁ παραδιδούς σε;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 21, 'Τοῦτον οὖν ἰδὼν, ὁ Πέτρος λέγει τῷ  ̊Ἰησοῦ, “ ̊Κύριε, οὗτος δὲ τί;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 22, 'Λέγει αὐτῷ ὁ  ̊Ἰησοῦς, “Ἐὰν αὐτὸν θέλω μένειν ἕως ἔρχομαι, τί πρὸς σέ; Σύ μοι ἀκολούθει!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 23, 'Ἐξῆλθεν οὖν οὗτος ὁ λόγος εἰς τοὺς ἀδελφοὺς, ὅτι ὁ μαθητὴς ἐκεῖνος οὐκ ἀποθνῄσκει. Οὐκ εἶπεν δὲ αὐτῷ ὁ  ̊Ἰησοῦς ὅτι Οὐκ ἀποθνῄσκει, ἀλλʼ, “Ἐὰν αὐτὸν θέλω μένειν ἕως ἔρχομαι, τί πρὸς σέ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 24, '¶Οὗτός ἐστιν ὁ μαθητὴς ὁ μαρτυρῶν περὶ τούτων, καὶ ὁ γράψας ταῦτα, καὶ οἴδαμεν ὅτι ἀληθὴς αὐτοῦ ἡ μαρτυρία ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 25, 'Ἔστιν δὲ καὶ ἄλλα πολλὰ ἃ ἐποίησεν ὁ  ̊Ἰησοῦς, ἅτινα ἐὰν γράφηται καθʼ ἕν, οὐδʼ αὐτὸν οἶμαι τὸν κόσμον χωρήσειν τὰ γραφόμενα βιβλία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, '¶Τὸν μὲν πρῶτον λόγον ἐποιησάμην περὶ πάντων, ὦ Θεόφιλε, ὧν ἤρξατο  ̊Ἰησοῦς ποιεῖν τε καὶ διδάσκειν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'ἄχρι ἧς ἡμέρας ἐντειλάμενος τοῖς ἀποστόλοις διὰ  ̊Πνεύματος Ἁγίου, οὓς ἐξελέξατο, ἀνελήμφθη·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'οἷς καὶ παρέστησεν ἑαυτὸν ζῶντα, μετὰ τὸ παθεῖν αὐτὸν, ἐν πολλοῖς τεκμηρίοις διʼ ἡμερῶν τεσσεράκοντα, ὀπτανόμενος αὐτοῖς, καὶ λέγων τὰ περὶ τῆς Βασιλείας τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Καὶ συναλιζόμενος, παρήγγειλεν αὐτοῖς, “Ἀπὸ Ἱεροσολύμων μὴ χωρίζεσθαι, ἀλλὰ περιμένειν τὴν ἐπαγγελίαν τοῦ Πατρὸς, ἣν ἠκούσατέ μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Ὅτι Ἰωάννης μὲν ἐβάπτισεν ὕδατι, ὑμεῖς δὲ ἐν  ̊Πνεύματι βαπτισθήσεσθε Ἁγίῳ, οὐ μετὰ πολλὰς ταύτας ἡμέρας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, '¶Οἱ μὲν οὖν συνελθόντες, ἠρώτων αὐτὸν λέγοντες, “ ̊Κύριε, εἰ ἐν τῷ χρόνῳ τούτῳ, ἀποκαθιστάνεις τὴν βασιλείαν τῷ Ἰσραήλ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Εἶπεν δὲ πρὸς αὐτούς, “Οὐχ ὑμῶν ἐστιν γνῶναι χρόνους ἢ καιροὺς, οὓς ὁ Πατὴρ ἔθετο ἐν τῇ ἰδίᾳ ἐξουσίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Ἀλλὰ λήμψεσθε δύναμιν, ἐπελθόντος τοῦ Ἁγίου  ̊Πνεύματος ἐφʼ ὑμᾶς, καὶ ἔσεσθέ μου μάρτυρες, ἔν τε Ἰερουσαλὴμ, καὶ ἐν πάσῃ τῇ Ἰουδαίᾳ, καὶ Σαμαρείᾳ, καὶ ἕως ἐσχάτου τῆς γῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Καὶ ταῦτα εἰπὼν, βλεπόντων αὐτῶν, ἐπήρθη καὶ νεφέλη ὑπέλαβεν αὐτὸν ἀπὸ τῶν ὀφθαλμῶν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Καὶ ὡς ἀτενίζοντες ἦσαν εἰς τὸν οὐρανὸν, πορευομένου αὐτοῦ, καὶ ἰδοὺ ἄνδρες δύο παρειστήκεισαν αὐτοῖς ἐν ἐσθήσεσι λευκαῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 11, 'οἳ καὶ εἶπαν, “Ἄνδρες, Γαλιλαῖοι, τί ἑστήκατε βλέποντες εἰς τὸν οὐρανόν; Οὗτος ὁ  ̊Ἰησοῦς ὁ ἀναλημφθεὶς ἀφʼ ὑμῶν εἰς τὸν οὐρανὸν, οὕτως ἐλεύσεται ὃν τρόπον ἐθεάσασθε αὐτὸν πορευόμενον εἰς τὸν οὐρανόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 12, '¶Τότε ὑπέστρεψαν εἰς Ἰερουσαλὴμ ἀπὸ ὄρους τοῦ καλουμένου Ἐλαιῶνος, ὅ ἐστιν ἐγγὺς Ἰερουσαλὴμ, Σαββάτου ἔχον ὁδόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 13, 'Καὶ ὅτε εἰσῆλθον, εἰς τὸ ὑπερῷον, ἀνέβησαν οὗ ἦσαν καταμένοντες, ὅ τε Πέτρος καὶ Ἰωάννης καὶ Ἰάκωβος καὶ Ἀνδρέας, Φίλιππος καὶ Θωμᾶς, Βαρθολομαῖος καὶ Μαθθαῖος, Ἰάκωβος Ἁλφαίου, καὶ Σίμων ὁ Ζηλωτὴς, καὶ Ἰούδας Ἰακώβου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 14, 'Οὗτοι πάντες ἦσαν προσκαρτεροῦντες ὁμοθυμαδὸν τῇ προσευχῇ, σὺν γυναιξὶν καὶ Μαρίᾳ τῇ μητρὶ τοῦ  ̊Ἰησοῦ, καὶ τοῖς ἀδελφοῖς αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 15, '¶Καὶ ἐν ταῖς ἡμέραις ταύταις, ἀναστὰς Πέτρος ἐν μέσῳ τῶν ἀδελφῶν εἶπεν (ἦν τε ὄχλος ὀνομάτων ἐπὶ τὸ αὐτὸ ὡσεὶ ἑκατὸν εἴκοσι),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 16, '“Ἄνδρες, ἀδελφοί, ἔδει πληρωθῆναι τὴν Γραφὴν, ἣν προεῖπεν τὸ  ̊Πνεῦμα τὸ Ἅγιον διὰ στόματος Δαυὶδ περὶ Ἰούδα, τοῦ γενομένου ὁδηγοῦ τοῖς συλλαβοῦσιν  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 17, 'Ὅτι κατηριθμημένος ἦν ἐν ἡμῖν, καὶ ἔλαχεν τὸν κλῆρον τῆς διακονίας ταύτης.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 18, '(Οὗτος μὲν οὖν ἐκτήσατο χωρίον ἐκ μισθοῦ τῆς ἀδικίας, καὶ πρηνὴς γενόμενος, ἐλάκησεν μέσος, καὶ ἐξεχύθη πάντα τὰ σπλάγχνα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 19, 'Καὶ γνωστὸν ἐγένετο πᾶσι τοῖς κατοικοῦσιν Ἰερουσαλήμ, ὥστε κληθῆναι τὸ χωρίον ἐκεῖνο τῇ διαλέκτῳ αὐτῶν, Ἁκελδαμάχ, τοῦτʼ ἔστιν, “Χωρίον Αἵματος”.)');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 20, '“Γέγραπται γὰρ ἐν βίβλῳ Ψαλμῶν, ‘Γενηθήτω ἡ ἔπαυλις αὐτοῦ ἔρημος, καὶ μὴ ἔστω ὁ κατοικῶν ἐν αὐτῇ’, καί, ‘Τὴν ἐπισκοπὴν αὐτοῦ, λαβέτω ἕτερος.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 21, 'Δεῖ οὖν τῶν συνελθόντων ἡμῖν ἀνδρῶν, ἐν παντὶ χρόνῳ ᾧ εἰσῆλθεν καὶ ἐξῆλθεν ἐφʼ ἡμᾶς ὁ  ̊Κύριος  ̊Ἰησοῦς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 22, 'ἀρξάμενος ἀπὸ τοῦ βαπτίσματος Ἰωάννου ἕως τῆς ἡμέρας ἧς ἀνελήμφθη ἀφʼ ἡμῶν, μάρτυρα τῆς ἀναστάσεως αὐτοῦ σὺν ἡμῖν, γενέσθαι ἕνα τούτων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 23, 'Καὶ ἔστησαν δύο, Ἰωσὴφ τὸν καλούμενον Βαρσαββᾶν, ὃς ἐπεκλήθη Ἰοῦστος, καὶ Ματθίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 24, 'Καὶ προσευξάμενοι, εἶπαν, “Σὺ  ̊Κύριε, καρδιογνῶστα πάντων, ἀνάδειξον ὃν ἐξελέξω ἐκ τούτων τῶν δύο ἕνα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 25, 'λαβεῖν τὸν τόπον τῆς διακονίας ταύτης καὶ ἀποστολῆς, ἀφʼ ἧς παρέβη Ἰούδας, πορευθῆναι εἰς τὸν τόπον τὸν ἴδιον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 26, 'Καὶ ἔδωκαν κλήρους αὐτοῖς, καὶ ἔπεσεν ὁ κλῆρος ἐπὶ Ματθίαν, καὶ συγκατεψηφίσθη μετὰ τῶν ἕνδεκα ἀποστόλων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, '¶Καὶ ἐν τῷ συμπληροῦσθαι τὴν ἡμέραν τῆς Πεντηκοστῆς, ἦσαν πάντες ὁμοῦ ἐπὶ τὸ αὐτό.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'Καὶ ἐγένετο ἄφνω ἐκ τοῦ οὐρανοῦ ἦχος, ὥσπερ φερομένης πνοῆς βιαίας, καὶ ἐπλήρωσεν ὅλον τὸν οἶκον οὗ ἦσαν καθήμενοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Καὶ ὤφθησαν αὐτοῖς διαμεριζόμεναι γλῶσσαι ὡσεὶ πυρός, καὶ ἐκάθισεν ἐφʼ ἕνα ἕκαστον αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Καὶ ἐπλήσθησαν πάντες  ̊Πνεύματος Ἁγίου, καὶ ἤρξαντο λαλεῖν ἑτέραις γλώσσαις, καθὼς τὸ  ̊Πνεῦμα ἐδίδου ἀποφθέγγεσθαι αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, '¶Ἦσαν δὲ ἐν Ἰερουσαλὴμ κατοικοῦντες Ἰουδαῖοι, ἄνδρες εὐλαβεῖς ἀπὸ παντὸς ἔθνους τῶν ὑπὸ τὸν οὐρανόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Γενομένης δὲ τῆς φωνῆς ταύτης, συνῆλθε τὸ πλῆθος καὶ συνεχύθη, ὅτι ἤκουσεν εἷς ἕκαστος τῇ ἰδίᾳ διαλέκτῳ λαλούντων αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Ἐξίσταντο δὲ καὶ ἐθαύμαζον λέγοντες, “Οὐχ ἰδοὺ, ἅπαντες οὗτοί εἰσιν οἱ λαλοῦντες Γαλιλαῖοι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Καὶ πῶς ἡμεῖς ἀκούομεν ἕκαστος τῇ ἰδίᾳ διαλέκτῳ ἡμῶν, ἐν ᾗ ἐγεννήθημεν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Πάρθοι, καὶ Μῆδοι, καὶ Ἐλαμῖται, καὶ οἱ κατοικοῦντες τὴν Μεσοποταμίαν, Ἰουδαίαν τε καὶ Καππαδοκίαν, Πόντον καὶ τὴν Ἀσίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Φρυγίαν τε καὶ Παμφυλίαν, Αἴγυπτον, καὶ τὰ μέρη τῆς Λιβύης τῆς κατὰ Κυρήνην, καὶ οἱ ἐπιδημοῦντες Ῥωμαῖοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Ἰουδαῖοί τε καὶ προσήλυτοι, Κρῆτες καὶ Ἄραβες– ἀκούομεν λαλούντων αὐτῶν, ταῖς ἡμετέραις γλώσσαις, τὰ μεγαλεῖα τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Ἐξίσταντο δὲ πάντες καὶ διηποροῦντο, ἄλλος πρὸς ἄλλον λέγοντες, “Τί θέλει τοῦτο εἶναι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Ἕτεροι δὲ διαχλευάζοντες ἔλεγον, ὅτι “Γλεύκους μεμεστωμένοι εἰσίν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, '¶Σταθεὶς δὲ ὁ Πέτρος σὺν τοῖς ἕνδεκα, ἐπῆρεν τὴν φωνὴν αὐτοῦ καὶ ἀπεφθέγξατο αὐτοῖς: “Ἄνδρες, Ἰουδαῖοι, καὶ οἱ κατοικοῦντες Ἰερουσαλὴμ πάντες, τοῦτο ὑμῖν γνωστὸν ἔστω καὶ ἐνωτίσασθε τὰ ῥήματά μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Οὐ γὰρ ὡς ὑμεῖς ὑπολαμβάνετε, οὗτοι μεθύουσιν, ἔστιν γὰρ ὥρα τρίτη τῆς ἡμέρας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'ἀλλὰ τοῦτό ἐστιν τὸ εἰρημένον διὰ τοῦ προφήτου Ἰωήλ:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, '‘Καὶ ἔσται ἐν ταῖς ἐσχάταις ἡμέραις’, λέγει ὁ  ̊Θεός, ‘ἐκχεῶ ἀπὸ τοῦ  ̊Πνεύματός μου ἐπὶ πᾶσαν σάρκα, καὶ προφητεύσουσιν οἱ υἱοὶ ὑμῶν, καὶ αἱ θυγατέρες ὑμῶν, καὶ οἱ νεανίσκοι ὑμῶν ὁράσεις ὄψονται, καὶ οἱ πρεσβύτεροι ὑμῶν ἐνυπνίοις ἐνυπνιασθήσονται·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'καί γε ἐπὶ τοὺς δούλους μου, καὶ ἐπὶ τὰς δούλας μου, ἐν ταῖς ἡμέραις ἐκείναις ἐκχεῶ ἀπὸ τοῦ  ̊Πνεύματός μου, καὶ προφητεύσουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Καὶ δώσω τέρατα ἐν τῷ οὐρανῷ ἄνω, καὶ σημεῖα ἐπὶ τῆς γῆς κάτω, αἷμα, καὶ πῦρ, καὶ ἀτμίδα καπνοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Ὁ ἥλιος μεταστραφήσεται εἰς σκότος καὶ ἡ σελήνη εἰς αἷμα, πρὶν ἐλθεῖν ἡμέραν  ̊Κυρίου τὴν μεγάλην καὶ ἐπιφανῆ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Καὶ ἔσται, πᾶς ὃς ἂν ἐπικαλέσηται τὸ ὄνομα  ̊Κυρίου σωθήσεται.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, '¶Ἄνδρες, Ἰσραηλῖται, ἀκούσατε τοὺς λόγους τούτους:  ̊Ἰησοῦν τὸν Ναζωραῖον, ἄνδρα ἀποδεδειγμένον ἀπὸ τοῦ  ̊Θεοῦ εἰς ὑμᾶς δυνάμεσι, καὶ τέρασι, καὶ σημείοις, οἷς ἐποίησεν διʼ αὐτοῦ ὁ  ̊Θεὸς ἐν μέσῳ ὑμῶν, καθὼς αὐτοὶ οἴδατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Τοῦτον τῇ, ὡρισμένῃ βουλῇ καὶ προγνώσει τοῦ  ̊Θεοῦ, ἔκδοτον διὰ χειρὸς ἀνόμων, προσπήξαντες ἀνείλατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Ὃν ὁ  ̊Θεὸς ἀνέστησεν, λύσας τὰς ὠδῖνας τοῦ θανάτου, καθότι οὐκ ἦν δυνατὸν κρατεῖσθαι αὐτὸν ὑπʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Δαυὶδ γὰρ λέγει εἰς αὐτόν, ‘Προορώμην τὸν  ̊Κύριον ἐνώπιόν μου διὰ παντός, ὅτι ἐκ δεξιῶν μού ἐστιν, ἵνα μὴ σαλευθῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Διὰ τοῦτο ηὐφράνθη μου ἡ καρδία καὶ ἠγαλλιάσατο ἡ γλῶσσά μου, ἔτι δὲ καὶ ἡ σάρξ μου κατασκηνώσει ἐπʼ ἐλπίδι·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'ὅτι οὐκ ἐγκαταλείψεις τὴν ψυχήν μου εἰς ἍΙδην, οὐδὲ δώσεις τὸν Ὅσιόν σου ἰδεῖν διαφθοράν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Ἐγνώρισάς μοι ὁδοὺς ζωῆς, πληρώσεις με εὐφροσύνης μετὰ τοῦ προσώπου σου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, '¶Ἄνδρες, ἀδελφοί, ἐξὸν εἰπεῖν μετὰ παρρησίας πρὸς ὑμᾶς περὶ τοῦ πατριάρχου Δαυὶδ ὅτι καὶ ἐτελεύτησεν καὶ ἐτάφη, καὶ τὸ μνῆμα αὐτοῦ ἔστιν ἐν ἡμῖν ἄχρι τῆς ἡμέρας ταύτης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 30, 'Προφήτης οὖν ὑπάρχων, καὶ εἰδὼς ὅτι ‘ὅρκῳ ὤμοσεν αὐτῷ ὁ  ̊Θεὸς’, ‘ἐκ καρποῦ τῆς ὀσφύος αὐτοῦ, καθίσαι ἐπὶ τὸν θρόνον αὐτοῦ’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 31, 'Προϊδὼν, ἐλάλησεν περὶ τῆς ἀναστάσεως τοῦ  ̊Χριστοῦ ὅτι ‘οὔτε ἐγκατελείφθη εἰς ἍΙδην’, οὔτε ἡ σὰρξ αὐτοῦ ‘εἶδεν διαφθοράν’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 32, 'Τοῦτον τὸν  ̊Ἰησοῦν ἀνέστησεν ὁ  ̊Θεός, οὗ πάντες ἡμεῖς ἐσμεν μάρτυρες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 33, 'Τῇ δεξιᾷ οὖν τοῦ  ̊Θεοῦ ὑψωθεὶς, τήν τε ἐπαγγελίαν τοῦ  ̊Πνεύματος τοῦ Ἁγίου, λαβὼν παρὰ τοῦ Πατρὸς, ἐξέχεεν τοῦτο ὃ ὑμεῖς βλέπετε καὶ ἀκούετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 34, 'Οὐ γὰρ Δαυὶδ ἀνέβη εἰς τοὺς οὐρανούς, λέγει δὲ αὐτός, ‘Εἶπεν  ̊Κύριος τῷ  ̊Κυρίῳ μου, “Κάθου ἐκ δεξιῶν μου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 35, 'ἕως ἂν θῶ τοὺς ἐχθρούς σου ὑποπόδιον τῶν ποδῶν σου.”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 36, 'Ἀσφαλῶς οὖν γινωσκέτω πᾶς οἶκος Ἰσραὴλ ὅτι καὶ  ̊Κύριον αὐτὸν καὶ  ̊Χριστὸν ἐποίησεν ὁ  ̊Θεός, τοῦτον τὸν  ̊Ἰησοῦν ὃν ὑμεῖς ἐσταυρώσατε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 37, '¶Ἀκούσαντες δὲ, κατενύγησαν τὴν καρδίαν, εἶπόν τε πρὸς τὸν Πέτρον καὶ τοὺς λοιποὺς ἀποστόλους, “Τί ποιήσωμεν, ἄνδρες, ἀδελφοί;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 38, 'Πέτρος δὲ πρὸς αὐτούς, “Μετανοήσατε”, φησίν, “καὶ βαπτισθήτω ἕκαστος ὑμῶν ἐπὶ τῷ ὀνόματι  ̊Ἰησοῦ  ̊Χριστοῦ, εἰς ἄφεσιν τῶν ἁμαρτιῶν ὑμῶν, καὶ λήμψεσθε τὴν δωρεὰν τοῦ Ἁγίου  ̊Πνεύματος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 39, 'Ὑμῖν γάρ ἐστιν ἡ ἐπαγγελία, καὶ τοῖς τέκνοις ὑμῶν, καὶ πᾶσι τοῖς εἰς μακρὰν, ὅσους ἂν προσκαλέσηται  ̊Κύριος, ὁ  ̊Θεὸς ἡμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 40, 'Ἑτέροις τε λόγοις πλείοσιν διεμαρτύρατο, καὶ παρεκάλει αὐτοὺς λέγων, “Σώθητε ἀπὸ τῆς γενεᾶς τῆς σκολιᾶς ταύτης.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 41, 'Οἱ μὲν οὖν ἀποδεξάμενοι τὸν λόγον αὐτοῦ ἐβαπτίσθησαν, καὶ προσετέθησαν ἐν τῇ ἡμέρᾳ ἐκείνῃ, ψυχαὶ ὡσεὶ τρισχίλιαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 42, 'Ἦσαν δὲ προσκαρτεροῦντες τῇ διδαχῇ τῶν ἀποστόλων, καὶ τῇ κοινωνίᾳ, τῇ κλάσει τοῦ ἄρτου, καὶ ταῖς προσευχαῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 43, '¶Ἐγίνετο δὲ πάσῃ ψυχῇ φόβος, πολλά δὲ τέρατα καὶ σημεῖα διὰ τῶν ἀποστόλων ἐγίνετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 44, 'Πάντες δὲ οἱ πιστεύσαντες ἦσαν ἐπὶ τὸ αὐτὸ, καὶ εἶχον ἅπαντα κοινά,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 45, 'καὶ τὰ κτήματα καὶ τὰς ὑπάρξεις ἐπίπρασκον, καὶ διεμέριζον αὐτὰ πᾶσιν, καθότι ἄν τις χρείαν εἶχεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 46, 'Καθʼ ἡμέραν τε προσκαρτεροῦντες ὁμοθυμαδὸν ἐν τῷ ἱερῷ, κλῶντές τε κατʼ οἶκον ἄρτον, μετελάμβανον τροφῆς ἐν ἀγαλλιάσει καὶ ἀφελότητι καρδίας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 47, 'αἰνοῦντες τὸν  ̊Θεὸν καὶ ἔχοντες χάριν πρὸς ὅλον τὸν λαόν. Ὁ δὲ  ̊Κύριος προσετίθει τοὺς σῳζομένους καθʼ ἡμέραν ἐπὶ τὸ αὐτό.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, '¶Πέτρος δὲ καὶ Ἰωάννης ἀνέβαινον εἰς τὸ ἱερὸν ἐπὶ τὴν ὥραν τῆς προσευχῆς τὴν ἐνάτην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Καί τις ἀνὴρ, χωλὸς ἐκ κοιλίας μητρὸς αὐτοῦ ὑπάρχων, ἐβαστάζετο, ὃν ἐτίθουν καθʼ ἡμέραν πρὸς τὴν θύραν τοῦ ἱεροῦ, τὴν λεγομένην Ὡραίαν, τοῦ αἰτεῖν ἐλεημοσύνην παρὰ τῶν εἰσπορευομένων εἰς τὸ ἱερόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Ὃς ἰδὼν Πέτρον καὶ Ἰωάννην μέλλοντας εἰσιέναι εἰς τὸ ἱερὸν, ἠρώτα ἐλεημοσύνην λαβεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Ἀτενίσας δὲ Πέτρος εἰς αὐτὸν σὺν τῷ Ἰωάννῃ εἶπεν, “Βλέψον εἰς ἡμᾶς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Ὁ δὲ ἐπεῖχεν αὐτοῖς, προσδοκῶν τι παρʼ αὐτῶν λαβεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Εἶπεν δὲ Πέτρος, “Ἀργύριον καὶ χρυσίον οὐχ ὑπάρχει μοι, ὃ δὲ ἔχω, τοῦτό σοι δίδωμι– ἐν τῷ ὀνόματι  ̊Ἰησοῦ  ̊Χριστοῦ τοῦ Ναζωραίου, περιπάτει!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Καὶ πιάσας αὐτὸν τῆς δεξιᾶς χειρὸς, ἤγειρεν αὐτόν· παραχρῆμα δὲ ἐστερεώθησαν αἱ βάσεις αὐτοῦ καὶ τὰ σφυδρά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Καὶ ἐξαλλόμενος, ἔστη καὶ περιεπάτει, καὶ εἰσῆλθεν σὺν αὐτοῖς εἰς τὸ ἱερὸν, περιπατῶν, καὶ ἁλλόμενος, καὶ αἰνῶν τὸν  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Καὶ εἶδεν πᾶς ὁ λαὸς αὐτὸν περιπατοῦντα καὶ αἰνοῦντα τὸν  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Ἐπεγίνωσκον δὲ αὐτὸν ὅτι αὐτὸς ἦν ὁ πρὸς τὴν ἐλεημοσύνην καθήμενος ἐπὶ τῇ Ὡραίᾳ Πύλῃ τοῦ ἱεροῦ, καὶ ἐπλήσθησαν θάμβους καὶ ἐκστάσεως ἐπὶ τῷ συμβεβηκότι αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, '¶Κρατοῦντος δὲ αὐτοῦ τὸν Πέτρον καὶ τὸν Ἰωάννην, συνέδραμεν πᾶς ὁ λαὸς πρὸς αὐτοὺς ἐπὶ τῇ στοᾷ τῇ καλουμένῃ Σολομῶντος, ἔκθαμβοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Ἰδὼν δὲ, ὁ Πέτρος ἀπεκρίνατο πρὸς τὸν λαόν, “Ἄνδρες, Ἰσραηλῖται, τί θαυμάζετε ἐπὶ τούτῳ, ἢ ἡμῖν τί ἀτενίζετε, ὡς ἰδίᾳ δυνάμει ἢ εὐσεβείᾳ πεποιηκόσιν τοῦ περιπατεῖν αὐτόν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Ὁ  ̊Θεὸς Ἀβραὰμ, καὶ ὁ  ̊Θεὸς Ἰσαὰκ, καὶ ὁ  ̊Θεὸς Ἰακώβ, ὁ  ̊Θεὸς τῶν πατέρων ἡμῶν, ἐδόξασεν τὸν παῖδα αὐτοῦ,  ̊Ἰησοῦν, ὃν ὑμεῖς μὲν παρεδώκατε, καὶ ἠρνήσασθε κατὰ πρόσωπον Πιλάτου, κρίναντος ἐκείνου ἀπολύειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Ὑμεῖς δὲ τὸν Ἅγιον καὶ Δίκαιον ἠρνήσασθε, καὶ ᾐτήσασθε ἄνδρα φονέα χαρισθῆναι ὑμῖν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'τὸν δὲ Ἀρχηγὸν τῆς ζωῆς ἀπεκτείνατε, ὃν ὁ  ̊Θεὸς ἤγειρεν ἐκ νεκρῶν, οὗ ἡμεῖς μάρτυρές ἐσμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Καὶ τῇ πίστει τοῦ ὀνόματος αὐτοῦ, τοῦτον ὃν θεωρεῖτε καὶ οἴδατε, ἐστερέωσεν τὸ ὄνομα αὐτοῦ, καὶ ἡ πίστις ἡ διʼ αὐτοῦ, ἔδωκεν αὐτῷ τὴν ὁλοκληρίαν ταύτην ἀπέναντι πάντων ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, '¶Καὶ νῦν, ἀδελφοί, οἶδα ὅτι κατὰ ἄγνοιαν ἐπράξατε, ὥσπερ καὶ οἱ ἄρχοντες ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Ὁ δὲ  ̊Θεὸς ἃ προκατήγγειλεν διὰ στόματος πάντων τῶν προφητῶν, παθεῖν τὸν  ̊Χριστὸν αὐτοῦ, ἐπλήρωσεν οὕτως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Μετανοήσατε οὖν καὶ ἐπιστρέψατε, πρὸς τὸ ἐξαλειφθῆναι ὑμῶν τὰς ἁμαρτίας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'ὅπως ἂν ἔλθωσιν καιροὶ ἀναψύξεως ἀπὸ προσώπου τοῦ  ̊Κυρίου, καὶ ἀποστείλῃ τὸν προκεχειρισμένον ὑμῖν  ̊Χριστὸν  ̊Ἰησοῦν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'ὃν δεῖ οὐρανὸν μὲν δέξασθαι, ἄχρι χρόνων ἀποκαταστάσεως πάντων, ὧν ἐλάλησεν ὁ  ̊Θεὸς διὰ στόματος τῶν ἁγίων ἀπʼ αἰῶνος αὐτοῦ προφητῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'Μωϋσῆς μὲν εἶπεν, ὅτι ‘“Προφήτην ὑμῖν ἀναστήσει  ̊Κύριος, ὁ  ̊Θεὸς ἡμῶν ἐκ τῶν ἀδελφῶν ὑμῶν, ὡς ἐμέ αὐτοῦ ἀκούσεσθε” κατὰ πάντα, ὅσα ἂν λαλήσῃ πρὸς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, '“Ἔσται δὲ πᾶσα ψυχὴ, ἥτις ἐὰν μὴ ἀκούσῃ τοῦ προφήτου ἐκείνου, ἐξολεθρευθήσεται ἐκ τοῦ λαοῦ.”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Καὶ πάντες δὲ οἱ προφῆται ἀπὸ Σαμουὴλ καὶ τῶν καθεξῆς, ὅσοι ἐλάλησαν, καὶ κατήγγειλαν τὰς ἡμέρας ταύτας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 25, 'Ὑμεῖς ἐστε οἱ υἱοὶ τῶν προφητῶν, καὶ τῆς διαθήκης ἧς διέθετο ὁ  ̊Θεὸς πρὸς τοὺς πατέρας ὑμῶν, λέγων πρὸς Ἀβραάμ, ‘Καὶ ἐν τῷ σπέρματί σου ἐνευλογηθήσονται πᾶσαι αἱ πατριαὶ τῆς γῆς.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 26, 'Ὑμῖν πρῶτον, ἀναστήσας ὁ  ̊Θεὸς τὸν παῖδα αὐτοῦ, ἀπέστειλεν αὐτὸν εὐλογοῦντα ὑμᾶς ἐν τῷ ἀποστρέφειν ἕκαστον ἀπὸ τῶν πονηριῶν ὑμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, '¶Λαλούντων δὲ αὐτῶν πρὸς τὸν λαὸν, ἐπέστησαν αὐτοῖς οἱ ἀρχιερεῖς, καὶ ὁ στρατηγὸς τοῦ ἱεροῦ, καὶ οἱ Σαδδουκαῖοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'διαπονούμενοι διὰ τὸ διδάσκειν αὐτοὺς τὸν λαὸν, καὶ καταγγέλλειν ἐν τῷ  ̊Ἰησοῦ τὴν ἀνάστασιν, τὴν ἐκ νεκρῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Καὶ ἐπέβαλον αὐτοῖς τὰς χεῖρας, καὶ ἔθεντο εἰς τήρησιν εἰς τὴν αὔριον, ἦν γὰρ ἑσπέρα ἤδη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Πολλοὶ δὲ τῶν ἀκουσάντων τὸν λόγον, ἐπίστευσαν καὶ ἐγενήθη ἀριθμὸς τῶν ἀνδρῶν ὡς χιλιάδες πέντε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, '¶Ἐγένετο δὲ ἐπὶ τὴν αὔριον συναχθῆναι αὐτῶν τοὺς ἄρχοντας, καὶ τοὺς πρεσβυτέρους, καὶ τοὺς γραμματεῖς ἐν Ἰερουσαλήμ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'καὶ Ἅννας ὁ ἀρχιερεὺς, καὶ Καϊάφας, καὶ Ἰωάννης, καὶ Ἀλέξανδρος, καὶ ὅσοι ἦσαν ἐκ γένους ἀρχιερατικοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Καὶ στήσαντες αὐτοὺς ἐν τῷ μέσῳ, ἐπυνθάνοντο, “Ἐν ποίᾳ δυνάμει ἢ ἐν ποίῳ ὀνόματι ἐποιήσατε τοῦτο ὑμεῖς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Τότε Πέτρος πλησθεὶς  ̊Πνεύματος Ἁγίου, εἶπεν πρὸς αὐτούς, “Ἄρχοντες τοῦ λαοῦ καὶ πρεσβύτεροι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'εἰ ἡμεῖς σήμερον ἀνακρινόμεθα ἐπὶ εὐεργεσίᾳ ἀνθρώπου ἀσθενοῦς, ἐν τίνι οὗτος σέσωσται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'γνωστὸν ἔστω πᾶσιν ὑμῖν καὶ παντὶ τῷ λαῷ Ἰσραὴλ, ὅτι ἐν τῷ ὀνόματι  ̊Ἰησοῦ  ̊Χριστοῦ τοῦ Ναζωραίου, ὃν ὑμεῖς ἐσταυρώσατε, ὃν ὁ  ̊Θεὸς ἤγειρεν ἐκ νεκρῶν, ἐν τούτῳ οὗτος παρέστηκεν ἐνώπιον ὑμῶν ὑγιής.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Οὗτός ἐστιν ‘ὁ λίθος ὁ ἐξουθενηθεὶς ὑφʼ ὑμῶν, τῶν οἰκοδόμων, ὁ γενόμενος εἰς κεφαλὴν γωνίας’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Καὶ οὐκ ἔστιν ἐν ἄλλῳ οὐδενὶ ἡ σωτηρία, οὐδὲ γὰρ ὄνομά ἐστιν ἕτερον ὑπὸ τὸν οὐρανὸν τὸ δεδομένον ἐν ἀνθρώποις, ἐν ᾧ δεῖ σωθῆναι ἡμᾶς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, '¶Θεωροῦντες δὲ τὴν τοῦ Πέτρου παρρησίαν καὶ Ἰωάννου, καὶ καταλαβόμενοι ὅτι ἄνθρωποι ἀγράμματοί εἰσιν καὶ ἰδιῶται, ἐθαύμαζον, ἐπεγίνωσκόν τε αὐτοὺς ὅτι σὺν τῷ  ̊Ἰησοῦ ἦσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Τόν τε ἄνθρωπον βλέποντες σὺν αὐτοῖς ἑστῶτα, τὸν τεθεραπευμένον, οὐδὲν εἶχον ἀντειπεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Κελεύσαντες δὲ αὐτοὺς ἔξω τοῦ Συνεδρίου ἀπελθεῖν, συνέβαλλον πρὸς ἀλλήλους');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'λέγοντες, “Τί ποιήσωμεν τοῖς ἀνθρώποις τούτοις; Ὅτι μὲν γὰρ γνωστὸν σημεῖον γέγονεν διʼ αὐτῶν, πᾶσιν τοῖς κατοικοῦσιν Ἰερουσαλὴμ φανερόν, καὶ οὐ δυνάμεθα ἀρνεῖσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Ἀλλʼ ἵνα μὴ ἐπὶ πλεῖον διανεμηθῇ εἰς τὸν λαόν, ἀπειλησώμεθα αὐτοῖς μηκέτι λαλεῖν ἐπὶ τῷ ὀνόματι τούτῳ μηδενὶ ἀνθρώπων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Καὶ καλέσαντες αὐτοὺς, παρήγγειλαν καθόλου μὴ φθέγγεσθαι μηδὲ διδάσκειν ἐπὶ τῷ ὀνόματι τοῦ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Ὁ δὲ Πέτρος καὶ Ἰωάννης ἀποκριθέντες εἶπον πρὸς αὐτούς, “Εἰ δίκαιόν ἐστιν ἐνώπιον τοῦ  ̊Θεοῦ, ὑμῶν ἀκούειν μᾶλλον ἢ τοῦ  ̊Θεοῦ, κρίνατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Οὐ δυνάμεθα γὰρ ἡμεῖς ἃ εἴδαμεν καὶ ἠκούσαμεν μὴ λαλεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Οἱ δὲ προσαπειλησάμενοι ἀπέλυσαν αὐτούς, μηδὲν εὑρίσκοντες τὸ πῶς κολάσωνται αὐτούς, διὰ τὸν λαόν, ὅτι πάντες ἐδόξαζον τὸν  ̊Θεὸν ἐπὶ τῷ γεγονότι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 22, 'Ἐτῶν γὰρ ἦν πλειόνων τεσσεράκοντα ὁ ἄνθρωπος, ἐφʼ ὃν γεγόνει τὸ σημεῖον τοῦτο τῆς ἰάσεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 23, '¶Ἀπολυθέντες δὲ, ἦλθον πρὸς τοὺς ἰδίους, καὶ ἀπήγγειλαν ὅσα πρὸς αὐτοὺς οἱ ἀρχιερεῖς καὶ οἱ πρεσβύτεροι εἶπαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 24, 'Οἱ δὲ ἀκούσαντες, ὁμοθυμαδὸν ἦραν φωνὴν πρὸς τὸν  ̊Θεὸν καὶ εἶπαν, “Δέσποτα, σὺ ὁ ‘ποιήσας τὸν οὐρανὸν, καὶ τὴν γῆν, καὶ τὴν θάλασσαν, καὶ πάντα τὰ ἐν αὐτοῖς’,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 25, 'ὁ τοῦ πατρὸς ἡμῶν, διὰ  ̊Πνεύματος Ἁγίου στόματος Δαυὶδ παιδός σου εἰπών, ‘Ἵνα τί ἐφρύαξαν ἔθνη, καὶ λαοὶ ἐμελέτησαν κενά;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 26, 'Παρέστησαν οἱ βασιλεῖς τῆς γῆς καὶ οἱ ἄρχοντες συνήχθησαν ἐπὶ τὸ αὐτὸ κατὰ τοῦ  ̊Κυρίου, καὶ κατὰ τοῦ  ̊Χριστοῦ αὐτοῦ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 27, 'Συνήχθησαν γὰρ ἐπʼ ἀληθείας ἐν τῇ πόλει ταύτῃ ἐπὶ τὸν ἅγιον παῖδά σου  ̊Ἰησοῦν, ὃν ἔχρισας, Ἡρῴδης τε καὶ Πόντιος Πιλᾶτος, σὺν ἔθνεσιν καὶ λαοῖς Ἰσραήλ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 28, 'ποιῆσαι ὅσα ἡ χείρ σου, καὶ ἡ βουλὴ σου προώρισεν γενέσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 29, 'Καὶ τὰ νῦν,  ̊Κύριε, ἔπιδε ἐπὶ τὰς ἀπειλὰς αὐτῶν, καὶ δὸς τοῖς δούλοις σου, μετὰ παρρησίας πάσης λαλεῖν τὸν λόγον σου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 30, 'ἐν τῷ τὴν χεῖρα ἐκτείνειν σε εἰς ἴασιν, καὶ σημεῖα, καὶ τέρατα, γίνεσθαι διὰ τοῦ ὀνόματος τοῦ ἁγίου παιδός σου,  ̊Ἰησοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 31, 'Καὶ δεηθέντων αὐτῶν, ἐσαλεύθη ὁ τόπος ἐν ᾧ ἦσαν συνηγμένοι, καὶ ἐπλήσθησαν ἅπαντες τοῦ Ἁγίου  ̊Πνεύματος, καὶ ἐλάλουν τὸν λόγον τοῦ  ̊Θεοῦ μετὰ παρρησίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 32, '¶Τοῦ δὲ πλήθους τῶν πιστευσάντων, ἦν καρδία καὶ ψυχὴ μία, καὶ οὐδὲ εἷς τι τῶν ὑπαρχόντων αὐτῷ ἔλεγεν ἴδιον εἶναι, ἀλλʼ ἦν αὐτοῖς πάντα κοινά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 33, 'Καὶ δυνάμει μεγάλῃ, ἀπεδίδουν τὸ μαρτύριον οἱ ἀπόστολοι τοῦ  ̊Κυρίου  ̊Ἰησοῦ, τῆς ἀναστάσεως, χάρις τε μεγάλη ἦν ἐπὶ πάντας αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 34, 'Οὐδὲ γὰρ ἐνδεής τις ἦν ἐν αὐτοῖς· ὅσοι γὰρ κτήτορες χωρίων ἢ οἰκιῶν ὑπῆρχον, πωλοῦντες ἔφερον τὰς τιμὰς τῶν πιπρασκομένων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 35, 'καὶ ἐτίθουν παρὰ τοὺς πόδας τῶν ἀποστόλων· διεδίδετο δὲ ἑκάστῳ, καθότι ἄν τις χρείαν εἶχεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 36, 'Ἰωσὴφ δὲ ὁ ἐπικληθεὶς Βαρναβᾶς, ἀπὸ τῶν ἀποστόλων, ὅ ἐστιν μεθερμηνευόμενον, “Υἱὸς παρακλήσεως”, Λευίτης, Κύπριος τῷ γένει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 37, 'ὑπάρχοντος αὐτῷ ἀγροῦ, πωλήσας ἤνεγκεν τὸ χρῆμα καὶ ἔθηκεν παρὰ τοὺς πόδας τῶν ἀποστόλων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, '¶Ἀνὴρ δέ τις Ἁνανίας ὀνόματι, σὺν Σαπφείρῃ τῇ γυναικὶ αὐτοῦ, ἐπώλησεν κτῆμα');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'καὶ ἐνοσφίσατο ἀπὸ τῆς τιμῆς, συνειδυίης καὶ τῆς γυναικός, καὶ ἐνέγκας μέρος τι, παρὰ τοὺς πόδας τῶν ἀποστόλων ἔθηκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Εἶπεν δὲ ὁ Πέτρος, “Ἁνανία, Διὰ τί ἐπλήρωσεν ὁ Σατανᾶς τὴν καρδίαν σου, ψεύσασθαί σε τὸ  ̊Πνεῦμα τὸ Ἅγιον, καὶ νοσφίσασθαι ἀπὸ τῆς τιμῆς τοῦ χωρίου;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Οὐχὶ μένον σοὶ ἔμενεν, καὶ πραθὲν ἐν τῇ σῇ ἐξουσίᾳ ὑπῆρχεν; Τί ὅτι ἔθου ἐν τῇ καρδίᾳ σου τὸ πρᾶγμα τοῦτο; Οὐκ ἐψεύσω ἀνθρώποις, ἀλλὰ τῷ  ̊Θεῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Ἀκούων δὲ ὁ Ἁνανίας τοὺς λόγους τούτους, πεσὼν ἐξέψυξεν. Καὶ ἐγένετο φόβος μέγας ἐπὶ πάντας τοὺς ἀκούοντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Ἀναστάντες δὲ, οἱ νεώτεροι συνέστειλαν αὐτὸν, καὶ ἐξενέγκαντες, ἔθαψαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, '¶Ἐγένετο δὲ ὡς ὡρῶν τριῶν διάστημα, καὶ ἡ γυνὴ αὐτοῦ, μὴ εἰδυῖα τὸ γεγονὸς, εἰσῆλθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Ἀπεκρίθη δὲ πρὸς αὐτὴν Πέτρος, “Εἰπέ μοι εἰ τοσούτου τὸ χωρίον ἀπέδοσθε;” Ἡ δὲ εἶπεν, “Ναί, τοσούτου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Ὁ δὲ Πέτρος πρὸς αὐτήν, “Τί ὅτι συνεφωνήθη ὑμῖν πειράσαι τὸ  ̊Πνεῦμα  ̊Κυρίου; Ἰδοὺ, οἱ πόδες τῶν θαψάντων τὸν ἄνδρα σου ἐπὶ τῇ θύρᾳ, καὶ ἐξοίσουσίν σε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Ἔπεσεν δὲ παραχρῆμα πρὸς τοὺς πόδας αὐτοῦ, καὶ ἐξέψυξεν. Εἰσελθόντες δὲ, οἱ νεανίσκοι εὗρον αὐτὴν νεκράν, καὶ ἐξενέγκαντες, ἔθαψαν πρὸς τὸν ἄνδρα αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Καὶ ἐγένετο φόβος μέγας ἐφʼ ὅλην τὴν ἐκκλησίαν, καὶ ἐπὶ πάντας τοὺς ἀκούοντας ταῦτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, '¶Διὰ δὲ τῶν χειρῶν τῶν ἀποστόλων, ἐγίνετο σημεῖα καὶ τέρατα πολλὰ ἐν τῷ λαῷ· καὶ ἦσαν ὁμοθυμαδὸν πάντες ἐν τῇ Στοᾷ Σολομῶντος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Τῶν δὲ λοιπῶν οὐδεὶς ἐτόλμα κολλᾶσθαι αὐτοῖς, ἀλλʼ ἐμεγάλυνεν αὐτοὺς ὁ λαός,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'μᾶλλον δὲ προσετίθεντο πιστεύοντες τῷ  ̊Κυρίῳ, πλήθη ἀνδρῶν τε καὶ γυναικῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'ὥστε καὶ εἰς τὰς πλατείας ἐκφέρειν τοὺς ἀσθενεῖς, καὶ τιθέναι ἐπὶ κλιναρίων καὶ κραβάττων, ἵνα ἐρχομένου Πέτρου, κἂν ἡ σκιὰ ἐπισκιάσῃ τινὶ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Συνήρχετο δὲ καὶ τὸ πλῆθος τῶν πέριξ πόλεων Ἰερουσαλήμ, φέροντες ἀσθενεῖς καὶ ὀχλουμένους ὑπὸ πνευμάτων ἀκαθάρτων, οἵτινες ἐθεραπεύοντο ἅπαντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, '¶Ἀναστὰς δὲ ὁ ἀρχιερεὺς καὶ πάντες οἱ σὺν αὐτῷ, ἡ οὖσα αἵρεσις τῶν Σαδδουκαίων, ἐπλήσθησαν ζήλου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'καὶ ἐπέβαλον τὰς χεῖρας ἐπὶ τοὺς ἀποστόλους, καὶ ἔθεντο αὐτοὺς ἐν τηρήσει δημοσίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Ἄγγελος δὲ  ̊Κυρίου διὰ νυκτὸς, ἤνοιξε τὰς θύρας τῆς φυλακῆς, ἐξαγαγών τε αὐτοὺς εἶπεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, '“Πορεύεσθε, καὶ σταθέντες, λαλεῖτε ἐν τῷ ἱερῷ τῷ λαῷ πάντα τὰ ῥήματα τῆς ζωῆς ταύτης.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Ἀκούσαντες δὲ, εἰσῆλθον ὑπὸ τὸν ὄρθρον εἰς τὸ ἱερὸν, καὶ ἐδίδασκον. ¶Παραγενόμενος δὲ ὁ ἀρχιερεὺς καὶ οἱ σὺν αὐτῷ, συνεκάλεσαν τὸ Συνέδριον καὶ πᾶσαν τὴν Γερουσίαν τῶν υἱῶν Ἰσραήλ, καὶ ἀπέστειλαν εἰς τὸ δεσμωτήριον ἀχθῆναι αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 22, 'Οἱ δὲ παραγενόμενοι ὑπηρέται, οὐχ εὗρον αὐτοὺς ἐν τῇ φυλακῇ, ἀναστρέψαντες δὲ, ἀπήγγειλαν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 23, 'λέγοντες, ὅτι “Τὸ δεσμωτήριον εὕρομεν κεκλεισμένον ἐν πάσῃ ἀσφαλείᾳ, καὶ τοὺς φύλακας ἑστῶτας ἐπὶ τῶν θυρῶν, ἀνοίξαντες δὲ, ἔσω οὐδένα εὕρομεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 24, 'Ὡς δὲ ἤκουσαν τοὺς λόγους τούτους, ὅ τε στρατηγὸς τοῦ ἱεροῦ καὶ οἱ ἀρχιερεῖς διηπόρουν περὶ αὐτῶν, τί ἂν γένοιτο τοῦτο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 25, 'Παραγενόμενος δέ, τις ἀπήγγειλεν αὐτοῖς, ὅτι “Ἰδοὺ, οἱ ἄνδρες οὓς ἔθεσθε ἐν τῇ φυλακῇ εἰσὶν ἐν τῷ ἱερῷ, ἑστῶτες καὶ διδάσκοντες τὸν λαόν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 26, 'Τότε ἀπελθὼν, ὁ στρατηγὸς σὺν τοῖς ὑπηρέταις ἦγεν αὐτούς, οὐ μετὰ βίας, ἐφοβοῦντο γὰρ τὸν λαόν, μὴ λιθασθῶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 27, '¶Ἀγαγόντες δὲ αὐτοὺς, ἔστησαν ἐν τῷ Συνεδρίῳ. Καὶ ἐπηρώτησεν αὐτοὺς ὁ ἀρχιερεὺς');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 28, 'λέγων, “Παραγγελίᾳ παρηγγείλαμεν ὑμῖν μὴ διδάσκειν ἐπὶ τῷ ὀνόματι τούτῳ, καὶ ἰδοὺ, πεπληρώκατε τὴν Ἰερουσαλὴμ τῆς διδαχῆς ὑμῶν, καὶ βούλεσθε ἐπαγαγεῖν ἐφʼ ἡμᾶς τὸ αἷμα τοῦ ἀνθρώπου τούτου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 29, 'Ἀποκριθεὶς δὲ Πέτρος καὶ οἱ ἀπόστολοι εἶπαν, “Πειθαρχεῖν δεῖ  ̊Θεῷ, μᾶλλον ἢ ἀνθρώποις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 30, 'Ὁ  ̊Θεὸς τῶν πατέρων ἡμῶν ἤγειρεν  ̊Ἰησοῦν, ὃν ὑμεῖς διεχειρίσασθε, κρεμάσαντες ἐπὶ ξύλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 31, 'Τοῦτον ὁ  ̊Θεὸς Ἀρχηγὸν καὶ Σωτῆρα ὕψωσεν, τῇ δεξιᾷ αὐτοῦ, τοῦ δοῦναι μετάνοιαν τῷ Ἰσραὴλ καὶ ἄφεσιν ἁμαρτιῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 32, 'Καὶ ἡμεῖς ἐσμεν μάρτυρες τῶν ῥημάτων τούτων, καὶ τὸ  ̊Πνεῦμα τὸ Ἅγιον, ὃ ἔδωκεν ὁ  ̊Θεὸς τοῖς πειθαρχοῦσιν αὐτῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 33, '¶Οἱ δὲ ἀκούσαντες διεπρίοντο, καὶ ἐβούλοντο ἀνελεῖν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 34, 'Ἀναστὰς δέ τις ἐν τῷ Συνεδρίῳ Φαρισαῖος ὀνόματι Γαμαλιήλ, νομοδιδάσκαλος τίμιος παντὶ τῷ λαῷ, ἐκέλευσεν ἔξω βραχὺ τοὺς ἀνθρώπους ποιῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 35, 'Εἶπέν τε πρὸς αὐτούς, “Ἄνδρες, Ἰσραηλῖται, προσέχετε ἑαυτοῖς ἐπὶ τοῖς ἀνθρώποις τούτοις τί μέλλετε πράσσειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 36, 'Πρὸ γὰρ τούτων τῶν ἡμερῶν ἀνέστη Θευδᾶς, λέγων εἶναί τινα ἑαυτόν, ᾧ προσεκλίθη ἀνδρῶν ἀριθμὸς ὡς τετρακοσίων· ὃς ἀνῃρέθη καὶ πάντες ὅσοι ἐπείθοντο αὐτῷ διελύθησαν καὶ ἐγένοντο εἰς οὐδέν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 37, 'Μετὰ τοῦτον, ἀνέστη Ἰούδας ὁ Γαλιλαῖος ἐν ταῖς ἡμέραις τῆς ἀπογραφῆς, καὶ ἀπέστησεν λαὸν ὀπίσω αὐτοῦ· κἀκεῖνος ἀπώλετο, καὶ πάντες ὅσοι ἐπείθοντο αὐτῷ διεσκορπίσθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 38, 'Καὶ τὰ νῦν λέγω ὑμῖν, ἀπόστητε ἀπὸ τῶν ἀνθρώπων τούτων καὶ ἄφετε αὐτούς, ὅτι ἐὰν ᾖ ἐξ ἀνθρώπων, ἡ βουλὴ αὕτη ἢ τὸ ἔργον τοῦτο καταλυθήσεται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 39, 'εἰ δὲ ἐκ  ̊Θεοῦ ἐστιν, οὐ δυνήσεσθε καταλῦσαι αὐτούς, μήποτε καὶ θεομάχοι εὑρεθῆτε.” Ἐπείσθησαν δὲ αὐτῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 40, 'καὶ προσκαλεσάμενοι τοὺς ἀποστόλους, δείραντες παρήγγειλαν μὴ λαλεῖν ἐπὶ τῷ ὀνόματι τοῦ  ̊Ἰησοῦ, καὶ ἀπέλυσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 41, 'Οἱ μὲν οὖν ἐπορεύοντο, χαίροντες ἀπὸ προσώπου τοῦ Συνεδρίου ὅτι κατηξιώθησαν ὑπὲρ τοῦ ὀνόματος ἀτιμασθῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 42, 'Πᾶσάν τε ἡμέραν ἐν τῷ ἱερῷ καὶ κατʼ οἶκον, οὐκ ἐπαύοντο διδάσκοντες καὶ εὐαγγελιζόμενοι τὸν  ̊Χριστὸν,  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 1, '¶Ἐν δὲ ταῖς ἡμέραις ταύταις πληθυνόντων τῶν μαθητῶν, ἐγένετο γογγυσμὸς τῶν Ἑλληνιστῶν πρὸς τοὺς Ἑβραίους, ὅτι παρεθεωροῦντο ἐν τῇ διακονίᾳ τῇ καθημερινῇ αἱ χῆραι αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 2, 'Προσκαλεσάμενοι δὲ οἱ δώδεκα τὸ πλῆθος τῶν μαθητῶν εἶπαν, “Οὐκ ἀρεστόν ἐστιν ἡμᾶς, καταλείψαντας τὸν λόγον τοῦ  ̊Θεοῦ, διακονεῖν τραπέζαις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 3, 'Ἐπισκέψασθε δέ, ἀδελφοί, ἄνδρας ἐξ ὑμῶν μαρτυρουμένους, ἑπτὰ πλήρεις  ̊Πνεύματος καὶ σοφίας, οὓς καταστήσομεν ἐπὶ τῆς χρείας ταύτης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 4, 'Ἡμεῖς δὲ τῇ προσευχῇ καὶ τῇ διακονίᾳ τοῦ λόγου προσκαρτερήσομεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 5, 'Καὶ ἤρεσεν ὁ λόγος ἐνώπιον παντὸς τοῦ πλήθους, καὶ ἐξελέξαντο Στέφανον, ἄνδρα πλήρης πίστεως καὶ  ̊Πνεύματος Ἁγίου, καὶ Φίλιππον, καὶ Πρόχορον, καὶ Νικάνορα, καὶ Τίμωνα, καὶ Παρμενᾶν, καὶ Νικόλαον προσήλυτον Ἀντιοχέα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 6, 'οὓς ἔστησαν ἐνώπιον τῶν ἀποστόλων, καὶ προσευξάμενοι, ἐπέθηκαν αὐτοῖς τὰς χεῖρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 7, '¶Καὶ ὁ λόγος τοῦ  ̊Θεοῦ ηὔξανεν, καὶ ἐπληθύνετο ὁ ἀριθμὸς τῶν μαθητῶν ἐν Ἰερουσαλὴμ σφόδρα, πολύς τε ὄχλος τῶν ἱερέων ὑπήκουον τῇ πίστει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 8, '¶Στέφανος δὲ πλήρης χάριτος καὶ δυνάμεως, ἐποίει τέρατα καὶ σημεῖα μεγάλα ἐν τῷ λαῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 9, 'Ἀνέστησαν δέ τινες τῶν ἐκ τῆς συναγωγῆς, τῆς λεγομένης Λιβερτίνων, καὶ Κυρηναίων, καὶ Ἀλεξανδρέων, καὶ τῶν ἀπὸ Κιλικίας, καὶ Ἀσίας, συζητοῦντες τῷ Στεφάνῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 10, 'Καὶ οὐκ ἴσχυον ἀντιστῆναι τῇ σοφίᾳ καὶ τῷ  ̊Πνεύματι, ᾧ ἐλάλει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 11, 'Τότε ὑπέβαλον ἄνδρας λέγοντας, ὅτι “Ἀκηκόαμεν αὐτοῦ λαλοῦντος ῥήματα βλάσφημα εἰς Μωϋσῆν καὶ τὸν  ̊Θεόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 12, 'Συνεκίνησάν τε τὸν λαὸν, καὶ τοὺς πρεσβυτέρους, καὶ τοὺς γραμματεῖς, καὶ ἐπιστάντες, συνήρπασαν αὐτὸν καὶ ἤγαγον εἰς τὸ Συνέδριον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 13, 'ἔστησάν τε μάρτυρας ψευδεῖς λέγοντας, “Ὁ ἄνθρωπος οὗτος οὐ παύεται λαλῶν ῥήματα κατὰ τοῦ τόπου τοῦ ἁγίου τούτου καὶ τοῦ νόμου”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 14, 'ἀκηκόαμεν γὰρ αὐτοῦ λέγοντος ὅτι  ̊Ἰησοῦς ὁ Ναζωραῖος οὗτος καταλύσει τὸν τόπον τοῦτον, καὶ ἀλλάξει τὰ ἔθη ἃ παρέδωκεν ἡμῖν Μωϋσῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 15, 'Καὶ ἀτενίσαντες εἰς αὐτὸν, πάντες οἱ καθεζόμενοι ἐν τῷ Συνεδρίῳ εἶδον τὸ πρόσωπον αὐτοῦ, ὡσεὶ πρόσωπον ἀγγέλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 1, '¶Εἶπεν δὲ ὁ ἀρχιερεύς, “Εἰ ταῦτα οὕτως ἔχει;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 2, 'Ὁ δὲ ἔφη, “Ἄνδρες, ἀδελφοὶ καὶ πατέρες, ἀκούσατε! Ὁ  ̊Θεὸς τῆς δόξης ὤφθη τῷ πατρὶ ἡμῶν Ἀβραὰμ, ὄντι ἐν τῇ Μεσοποταμίᾳ πρὶν ἢ κατοικῆσαι αὐτὸν ἐν Χαρράν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 3, 'καὶ εἶπεν πρὸς αὐτόν, ‘Ἔξελθε ἐκ τῆς γῆς σου καὶ ἐκ τῆς συγγενείας σου, καὶ δεῦρο εἰς τὴν γῆν ἣν ἄν σοι δείξω.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 4, 'Τότε ἐξελθὼν ἐκ γῆς Χαλδαίων, κατῴκησεν ἐν Χαρράν. Κἀκεῖθεν μετὰ τὸ ἀποθανεῖν τὸν πατέρα αὐτοῦ, μετῴκισεν αὐτὸν εἰς τὴν γῆν ταύτην, εἰς ἣν ὑμεῖς νῦν κατοικεῖτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 5, 'Καὶ οὐκ ἔδωκεν αὐτῷ κληρονομίαν ἐν αὐτῇ, οὐδὲ βῆμα ποδός, καὶ ἐπηγγείλατο ‘δοῦναι αὐτῷ εἰς κατάσχεσιν αὐτὴν, καὶ τῷ σπέρματι αὐτοῦ μετʼ αὐτόν’, οὐκ ὄντος αὐτῷ τέκνου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 6, 'Ἐλάλησεν δὲ οὕτως ὁ  ̊Θεὸς ὅτι ἔσται τὸ σπέρμα αὐτοῦ, ‘πάροικον ἐν γῇ ἀλλοτρίᾳ, καὶ δουλώσουσιν αὐτὸ καὶ κακώσουσιν ἔτη τετρακόσια.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 7, 'Καὶ τὸ ἔθνος ᾧ ἐὰν δουλεύσωσιν, κρινῶ ἐγώ’, ὁ  ̊Θεὸς εἶπεν, ‘Καὶ μετὰ ταῦτα, ἐξελεύσονται καὶ λατρεύσουσίν μοι ἐν τῷ τόπῳ τούτῳ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 8, 'Καὶ ἔδωκεν αὐτῷ διαθήκην περιτομῆς· καὶ οὕτως ἐγέννησεν τὸν Ἰσαὰκ, καὶ περιέτεμεν αὐτὸν τῇ ἡμέρᾳ τῇ ὀγδόῃ, καὶ Ἰσαὰκ τὸν Ἰακώβ, καὶ Ἰακὼβ τοὺς δώδεκα πατριάρχας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 9, '¶Καὶ οἱ πατριάρχαι ζηλώσαντες τὸν Ἰωσὴφ, ἀπέδοντο εἰς Αἴγυπτον· καὶ ἦν ὁ  ̊Θεὸς μετʼ αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 10, 'καὶ ἐξείλατο αὐτὸν ἐκ πασῶν τῶν θλίψεων αὐτοῦ, καὶ ἔδωκεν αὐτῷ χάριν καὶ σοφίαν ἐναντίον Φαραὼ, βασιλέως Αἰγύπτου, καὶ κατέστησεν αὐτὸν ἡγούμενον ἐπʼ Αἴγυπτον, καὶ ἐφʼ ὅλον τὸν οἶκον αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 11, 'Ἦλθεν δὲ λιμὸς ἐφʼ ὅλην τὴν Αἴγυπτον καὶ Χανάαν, καὶ θλῖψις μεγάλη, καὶ οὐχ εὕρισκον χορτάσματα οἱ πατέρες ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 12, 'Ἀκούσας δὲ Ἰακὼβ, ὄντα σιτία εἰς Αἴγυπτον, ἐξαπέστειλεν τοὺς πατέρας ἡμῶν πρῶτον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 13, 'Καὶ ἐν τῷ δευτέρῳ, ἐγνωρίσθη Ἰωσὴφ τοῖς ἀδελφοῖς αὐτοῦ, καὶ φανερὸν ἐγένετο τῷ Φαραὼ τὸ γένος Ἰωσήφ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 14, 'Ἀποστείλας δὲ, Ἰωσὴφ μετεκαλέσατο Ἰακὼβ, τὸν πατέρα αὐτοῦ, καὶ πᾶσαν τὴν συγγένειαν, ἐν ψυχαῖς ἑβδομήκοντα πέντε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 15, 'Καὶ κατέβη Ἰακὼβ εἰς Αἴγυπτον, καὶ ἐτελεύτησεν αὐτὸς καὶ οἱ πατέρες ἡμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 16, 'καὶ μετετέθησαν εἰς Συχὲμ, καὶ ἐτέθησαν ἐν τῷ μνήματι, ᾧ ὠνήσατο Ἀβραὰμ τιμῆς ἀργυρίου παρὰ τῶν υἱῶν Ἑμμὼρ ἐν Συχέμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 17, '¶Καθὼς δὲ ἤγγιζεν ὁ χρόνος τῆς ἐπαγγελίας, ἧς ὡμολόγησεν ὁ  ̊Θεὸς τῷ Ἀβραάμ, ηὔξησεν ὁ λαὸς καὶ ἐπληθύνθη ἐν Αἰγύπτῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 18, 'ἄχρι ‘οὗ ἀνέστη βασιλεὺς ἕτερος ἐπʼ Αἴγυπτον, ὃς οὐκ ᾔδει τὸν Ἰωσήφ’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 19, 'Οὗτος, κατασοφισάμενος τὸ γένος ἡμῶν, ἐκάκωσεν τοὺς πατέρας τοῦ ποιεῖν τὰ βρέφη ἔκθετα αὐτῶν, εἰς τὸ μὴ ζῳογονεῖσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 20, 'Ἐν ᾧ καιρῷ ἐγεννήθη Μωϋσῆς, καὶ ἦν ἀστεῖος τῷ  ̊Θεῷ· ὃς ἀνετράφη μῆνας τρεῖς ἐν τῷ οἴκῳ τοῦ πατρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 21, 'Ἐκτεθέντος δὲ αὐτοῦ, ἀνείλατο αὐτὸν ἡ θυγάτηρ Φαραὼ, καὶ ἀνεθρέψατο αὐτὸν ἑαυτῇ εἰς υἱόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 22, 'Καὶ ἐπαιδεύθη Μωϋσῆς ἐν πάσῃ σοφίᾳ Αἰγυπτίων, ἦν δὲ δυνατὸς ἐν λόγοις καὶ ἔργοις αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 23, '¶Ὡς δὲ ἐπληροῦτο αὐτῷ τεσσερακονταετὴς χρόνος, ἀνέβη ἐπὶ τὴν καρδίαν αὐτοῦ ἐπισκέψασθαι τοὺς ἀδελφοὺς αὐτοῦ, τοὺς υἱοὺς Ἰσραήλ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 24, 'Καὶ ἰδών τινα ἀδικούμενον, ἠμύνατο καὶ ἐποίησεν ἐκδίκησιν τῷ καταπονουμένῳ, πατάξας τὸν Αἰγύπτιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 25, 'Ἐνόμιζεν δὲ συνιέναι τοὺς ἀδελφοὺς ὅτι ὁ  ̊Θεὸς διὰ χειρὸς αὐτοῦ δίδωσιν σωτηρίαν αὐτοῖς, οἱ δὲ οὐ συνῆκαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 26, 'Τῇ τε ἐπιούσῃ ἡμέρᾳ, ὤφθη αὐτοῖς μαχομένοις, καὶ συνήλλασσεν αὐτοὺς εἰς εἰρήνην, εἰπών, ‘Ἄνδρες, ἀδελφοί ἐστε. Ἱνα τί ἀδικεῖτε ἀλλήλους;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 27, 'Ὁ δὲ ἀδικῶν τὸν πλησίον ἀπώσατο αὐτὸν εἰπών, ‘Τίς σε κατέστησεν ἄρχοντα καὶ δικαστὴν ἐφʼ ἡμῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 28, 'Μὴ ἀνελεῖν με σὺ θέλεις, ὃν τρόπον ἀνεῖλες ἐχθὲς τὸν Αἰγύπτιον;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 29, '‘Ἔφυγεν δὲ Μωϋσῆς’ ἐν τῷ λόγῳ τούτῳ, ‘καὶ ἐγένετο πάροικος ἐν γῇ Μαδιάμ’, οὗ ἐγέννησεν υἱοὺς δύο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 30, '¶Καὶ πληρωθέντων ἐτῶν τεσσεράκοντα, ‘ὤφθη αὐτῷ ἐν τῇ ἐρήμῳ τοῦ Ὄρους Σινᾶ, ἄγγελος ἐν φλογὶ πυρὸς βάτου’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 31, 'Ὁ δὲ Μωϋσῆς ἰδὼν, ἐθαύμασεν τὸ ὅραμα. Προσερχομένου δὲ αὐτοῦ κατανοῆσαι, ἐγένετο φωνὴ  ̊Κυρίου:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 32, '‘Ἐγὼ ὁ  ̊Θεὸς τῶν πατέρων σου, ὁ  ̊Θεὸς Ἀβραὰμ, καὶ Ἰσαὰκ, καὶ Ἰακώβ.’ Ἔντρομος δὲ γενόμενος, Μωϋσῆς οὐκ ἐτόλμα κατανοῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 33, 'Εἶπεν δὲ αὐτῷ ὁ  ̊Κύριος, ‘Λῦσον τὸ ὑπόδημα τῶν ποδῶν σου, ὁ γὰρ τόπος ἐφʼ ᾧ ἕστηκας γῆ ἁγία ἐστίν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 34, '‘Ἰδὼν, εἶδον τὴν κάκωσιν τοῦ λαοῦ μου τοῦ ἐν Αἰγύπτῳ, καὶ τοῦ στεναγμοῦ αὐτῶν ἤκουσα, καὶ κατέβην ἐξελέσθαι αὐτούς’· ‘Καὶ νῦν δεῦρο, ἀποστείλω σε εἰς Αἴγυπτον.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 35, '¶Τοῦτον τὸν Μωϋσῆν, ὃν ἠρνήσαντο εἰπόντες, ‘Τίς σε κατέστησεν ἄρχοντα καὶ δικαστήν;’ Τοῦτον ὁ  ̊Θεὸς ἄρχοντα καὶ λυτρωτὴν ἀπέσταλκεν, σὺν χειρὶ ἀγγέλου τοῦ ὀφθέντος αὐτῷ ἐν τῇ βάτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 36, 'Οὗτος ἐξήγαγεν αὐτοὺς, ποιήσας τέρατα καὶ σημεῖα ἐν τῇ Αἰγύπτῳ, καὶ ἐν Ἐρυθρᾷ Θαλάσσῃ, καὶ ἐν τῇ ἐρήμῳ, ἔτη τεσσεράκοντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 37, 'Οὗτός ἐστιν ὁ Μωϋσῆς ὁ εἴπας τοῖς υἱοῖς Ἰσραήλ, ‘Προφήτην ὑμῖν ἀναστήσει ὁ  ̊Θεὸς, ἐκ τῶν ἀδελφῶν ὑμῶν, ὡς ἐμέ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 38, 'Οὗτός ἐστιν ὁ γενόμενος ἐν τῇ ἐκκλησίᾳ ἐν τῇ ἐρήμῳ, μετὰ τοῦ ἀγγέλου τοῦ λαλοῦντος αὐτῷ ἐν τῷ Ὄρει Σινᾶ, καὶ τῶν πατέρων ἡμῶν, ὃς ἐδέξατο λόγια ζῶντα δοῦναι ὑμῖν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 39, 'ᾧ οὐκ ἠθέλησαν ὑπήκοοι γενέσθαι οἱ πατέρες ἡμῶν, ἀλλὰ ἀπώσαντο καὶ ἐστράφησαν ἐν ταῖς καρδίαις αὐτῶν εἰς Αἴγυπτον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 40, 'εἰπόντες τῷ Ἀαρών, ‘Ποίησον ἡμῖν θεοὺς οἳ προπορεύσονται ἡμῶν. Ὁ γὰρ Μωϋσῆς οὗτος, ὃς ἐξήγαγεν ἡμᾶς ἐκ γῆς Αἰγύπτου, οὐκ οἴδαμεν τί ἐγένετο αὐτῷ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 41, 'Καὶ ἐμοσχοποίησαν ἐν ταῖς ἡμέραις ἐκείναις, καὶ ἀνήγαγον θυσίαν τῷ εἰδώλῳ, καὶ εὐφραίνοντο ἐν τοῖς ἔργοις τῶν χειρῶν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 42, 'Ἔστρεψεν δὲ ὁ  ̊Θεὸς, καὶ παρέδωκεν αὐτοὺς λατρεύειν τῇ στρατιᾷ τοῦ οὐρανοῦ, καθὼς γέγραπται ἐν βίβλῳ τῶν προφητῶν, ‘Μὴ σφάγια καὶ θυσίας προσηνέγκατέ μοι, ἔτη τεσσεράκοντα ἐν τῇ ἐρήμῳ, οἶκος Ἰσραήλ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 43, 'Καὶ ἀνελάβετε τὴν σκηνὴν τοῦ Μολὸχ, καὶ τὸ ἄστρον τοῦ θεοῦ ὑμῶν Ῥομφά, τοὺς τύπους οὓς ἐποιήσατε προσκυνεῖν αὐτοῖς. Καὶ μετοικιῶ ὑμᾶς ἐπέκεινα Βαβυλῶνος.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 44, '¶Ἡ σκηνὴ τοῦ μαρτυρίου ἦν τοῖς πατράσιν ἡμῶν ἐν τῇ ἐρήμῳ, καθὼς διετάξατο ὁ λαλῶν τῷ Μωϋσῇ, ποιῆσαι αὐτὴν κατὰ τὸν τύπον ὃν ἑωράκει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 45, 'ἣν καὶ εἰσήγαγον, διαδεξάμενοι οἱ πατέρες ἡμῶν μετὰ  ̊Ἰησοῦ ἐν τῇ κατασχέσει τῶν ἐθνῶν, ὧν ἐξῶσεν ὁ  ̊Θεὸς ἀπὸ προσώπου τῶν πατέρων ἡμῶν, ἕως τῶν ἡμερῶν Δαυίδ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 46, 'ὃς εὗρεν χάριν ἐνώπιον τοῦ  ̊Θεοῦ, καὶ ᾐτήσατο εὑρεῖν σκήνωμα τῷ οἴκῳ Ἰακώβ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 47, 'Σολομῶν δὲ ᾠκοδόμησεν αὐτῷ οἶκον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 48, 'Ἀλλʼ οὐχ ὁ Ὕψιστος ἐν χειροποιήτοις κατοικεῖ, καθὼς ὁ προφήτης λέγει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 49, '‘Ὁ οὐρανός μοι θρόνος, ἡ δὲ γῆ ὑποπόδιον τῶν ποδῶν μου. Ποῖον οἶκον οἰκοδομήσετέ μοι; Λέγει  ̊Κύριος, ἢ τίς τόπος τῆς καταπαύσεώς μου;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 50, 'Οὐχὶ ἡ χείρ μου ἐποίησεν ταῦτα πάντα;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 51, '¶Σκληροτράχηλοι καὶ ἀπερίτμητοι καρδίαις καὶ τοῖς ὠσίν, ὑμεῖς ἀεὶ τῷ  ̊Πνεύματι τῷ Ἁγίῳ ἀντιπίπτετε, ὡς οἱ πατέρες ὑμῶν, καὶ ὑμεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 52, 'Τίνα τῶν προφητῶν οὐκ ἐδίωξαν οἱ πατέρες ὑμῶν; Καὶ ἀπέκτειναν τοὺς προκαταγγείλαντας περὶ τῆς ἐλεύσεως τοῦ Δικαίου, οὗ νῦν ὑμεῖς προδόται καὶ φονεῖς ἐγένεσθε!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 53, 'Οἵτινες ἐλάβετε τὸν νόμον εἰς διαταγὰς ἀγγέλων, καὶ οὐκ ἐφυλάξατε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 54, '¶Ἀκούοντες δὲ ταῦτα, διεπρίοντο ταῖς καρδίαις αὐτῶν, καὶ ἔβρυχον τοὺς ὀδόντας ἐπʼ αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 55, 'Ὑπάρχων δὲ πλήρης  ̊Πνεύματος Ἁγίου, ἀτενίσας εἰς τὸν οὐρανὸν, εἶδεν δόξαν  ̊Θεοῦ, καὶ  ̊Ἰησοῦν ἑστῶτα ἐκ δεξιῶν τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 56, 'καὶ εἶπεν, “Ἰδοὺ, θεωρῶ τοὺς οὐρανοὺς διηνοιγμένους, καὶ τὸν Υἱὸν τοῦ Ἀνθρώπου ἐκ δεξιῶν ἑστῶτα τοῦ  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 57, 'Κράξαντες δὲ φωνῇ μεγάλῃ, συνέσχον τὰ ὦτα αὐτῶν, καὶ ὥρμησαν ὁμοθυμαδὸν ἐπʼ αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 58, 'Καὶ ἐκβαλόντες ἔξω τῆς πόλεως, ἐλιθοβόλουν. Καὶ οἱ μάρτυρες ἀπέθεντο τὰ ἱμάτια αὐτῶν, παρὰ τοὺς πόδας νεανίου καλουμένου Σαύλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 59, 'Καὶ ἐλιθοβόλουν τὸν Στέφανον, ἐπικαλούμενον καὶ λέγοντα, “ ̊Κύριε  ̊Ἰησοῦ, δέξαι τὸ πνεῦμά μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 60, 'Θεὶς δὲ τὰ γόνατα, ἔκραξεν φωνῇ μεγάλῃ, “ ̊Κύριε, μὴ στήσῃς αὐτοῖς ταύτην τὴν ἁμαρτίαν.” Καὶ τοῦτο εἰπὼν, ἐκοιμήθη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 1, 'Σαῦλος δὲ ἦν συνευδοκῶν τῇ ἀναιρέσει αὐτοῦ. ¶Ἐγένετο δὲ ἐν ἐκείνῃ τῇ ἡμέρᾳ, διωγμὸς μέγας ἐπὶ τὴν ἐκκλησίαν, τὴν ἐν Ἱεροσολύμοις. Πάντες δὲ διεσπάρησαν κατὰ τὰς χώρας τῆς Ἰουδαίας καὶ Σαμαρείας, πλὴν τῶν ἀποστόλων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 2, 'Συνεκόμισαν δὲ τὸν Στέφανον ἄνδρες εὐλαβεῖς, καὶ ἐποίησαν κοπετὸν μέγαν ἐπʼ αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 3, 'Σαῦλος δὲ ἐλυμαίνετο τὴν ἐκκλησίαν, κατὰ τοὺς οἴκους εἰσπορευόμενος, σύρων τε ἄνδρας καὶ γυναῖκας, παρεδίδου εἰς φυλακήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 4, '¶Οἱ μὲν οὖν διασπαρέντες, διῆλθον εὐαγγελιζόμενοι τὸν λόγον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 5, 'Φίλιππος δὲ κατελθὼν εἰς τὴν πόλιν τῆς Σαμαρείας, ἐκήρυσσεν αὐτοῖς τὸν  ̊Χριστόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 6, 'Προσεῖχον δὲ οἱ ὄχλοι τοῖς λεγομένοις ὑπὸ τοῦ Φιλίππου ὁμοθυμαδὸν, ἐν τῷ ἀκούειν αὐτοὺς καὶ βλέπειν τὰ σημεῖα ἃ ἐποίει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 7, 'Πολλοὶ γὰρ τῶν ἐχόντων πνεύματα ἀκάθαρτα, βοῶντα φωνῇ μεγάλῃ, ἐξήρχοντο, πολλοὶ δὲ παραλελυμένοι καὶ χωλοὶ ἐθεραπεύθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 8, 'Ἐγένετο δὲ πολλὴ χαρὰ ἐν τῇ πόλει ἐκείνῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 9, '¶Ἀνὴρ δέ τις ὀνόματι Σίμων, προϋπῆρχεν ἐν τῇ πόλει μαγεύων, καὶ ἐξιστάνων τὸ ἔθνος τῆς Σαμαρείας, λέγων εἶναί τινα ἑαυτὸν μέγαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 10, 'ὯΙ προσεῖχον πάντες ἀπὸ μικροῦ ἕως μεγάλου λέγοντες, “Οὗτός ἐστιν ἡ Δύναμις τοῦ  ̊Θεοῦ, ἡ καλουμένη Μεγάλη.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 11, 'Προσεῖχον δὲ αὐτῷ, διὰ τὸ ἱκανῷ χρόνῳ ταῖς μαγείαις ἐξεστακέναι αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 12, 'Ὅτε δὲ ἐπίστευσαν τῷ Φιλίππῳ, εὐαγγελιζομένῳ περὶ τῆς Βασιλείας τοῦ  ̊Θεοῦ καὶ τοῦ ὀνόματος  ̊Ἰησοῦ  ̊Χριστοῦ, ἐβαπτίζοντο ἄνδρες τε καὶ γυναῖκες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 13, 'Ὁ δὲ Σίμων καὶ αὐτὸς ἐπίστευσεν, καὶ βαπτισθεὶς, ἦν προσκαρτερῶν τῷ Φιλίππῳ, θεωρῶν τε σημεῖα καὶ δυνάμεις μεγάλας γινομένας, ἐξίστατο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 14, '¶Ἀκούσαντες δὲ οἱ ἐν Ἱεροσολύμοις ἀπόστολοι ὅτι δέδεκται ἡ Σαμάρεια τὸν λόγον τοῦ  ̊Θεοῦ, ἀπέστειλαν πρὸς αὐτοὺς Πέτρον καὶ Ἰωάννην,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 15, 'οἵτινες καταβάντες, προσηύξαντο περὶ αὐτῶν, ὅπως λάβωσιν  ̊Πνεῦμα Ἅγιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 16, 'Οὐδέπω γὰρ ἦν ἐπʼ οὐδενὶ αὐτῶν ἐπιπεπτωκός, μόνον δὲ βεβαπτισμένοι ὑπῆρχον εἰς τὸ ὄνομα τοῦ  ̊Κυρίου  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 17, 'Τότε ἐπετίθεσαν τὰς χεῖρας ἐπʼ αὐτούς, καὶ ἐλάμβανον  ̊Πνεῦμα Ἅγιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 18, 'Ἰδὼν δὲ ὁ Σίμων ὅτι διὰ τῆς ἐπιθέσεως τῶν χειρῶν τῶν ἀποστόλων δίδοται τὸ  ̊Πνεῦμα, προσήνεγκεν αὐτοῖς χρήματα');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 19, 'λέγων, “Δότε κἀμοὶ τὴν ἐξουσίαν ταύτην, ἵνα ᾧ ἐὰν ἐπιθῶ τὰς χεῖρας, λαμβάνῃ  ̊Πνεῦμα Ἅγιον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 20, 'Πέτρος δὲ εἶπεν πρὸς αὐτόν, “Τὸ ἀργύριόν σου, σὺν σοὶ εἴη εἰς ἀπώλειαν, ὅτι τὴν δωρεὰν τοῦ  ̊Θεοῦ ἐνόμισας διὰ χρημάτων κτᾶσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 21, 'Οὐκ ἔστιν σοι μερὶς οὐδὲ κλῆρος ἐν τῷ λόγῳ τούτῳ. Ἡ γὰρ καρδία σου οὐκ ἔστιν εὐθεῖα ἔναντι τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 22, 'Μετανόησον οὖν ἀπὸ τῆς κακίας σου ταύτης, καὶ δεήθητι τοῦ  ̊Κυρίου εἰ ἄρα ἀφεθήσεταί σοι ἡ ἐπίνοια τῆς καρδίας σου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 23, 'Εἰς γὰρ χολὴν πικρίας καὶ σύνδεσμον ἀδικίας, ὁρῶ σε ὄντα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 24, 'Ἀποκριθεὶς δὲ ὁ Σίμων εἶπεν, “Δεήθητε ὑμεῖς ὑπὲρ ἐμοῦ πρὸς τὸν  ̊Κύριον, ὅπως μηδὲν ἐπέλθῃ ἐπʼ ἐμὲ ὧν εἰρήκατε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 25, '¶Οἱ μὲν οὖν, διαμαρτυράμενοι καὶ λαλήσαντες τὸν λόγον τοῦ  ̊Κυρίου, ὑπέστρεφον εἰς Ἱεροσόλυμα, πολλάς τε κώμας τῶν Σαμαρειτῶν εὐηγγελίζοντο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 26, '¶Ἄγγελος δὲ  ̊Κυρίου ἐλάλησεν πρὸς Φίλιππον λέγων, “Ἀνάστηθι καὶ πορεύου κατὰ μεσημβρίαν, ἐπὶ τὴν ὁδὸν τὴν καταβαίνουσαν ἀπὸ Ἰερουσαλὴμ εἰς Γάζαν”· αὕτη ἐστὶν ἔρημος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 27, 'Καὶ ἀναστὰς, ἐπορεύθη, καὶ ἰδοὺ, ἀνὴρ, Αἰθίοψ εὐνοῦχος, δυνάστης Κανδάκης βασιλίσσης Αἰθιόπων, ὃς ἦν ἐπὶ πάσης τῆς γάζης αὐτῆς, ὃς ἐληλύθει προσκυνήσων εἰς Ἰερουσαλήμ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 28, 'ἦν δὲ ὑποστρέφων καὶ καθήμενος ἐπὶ τοῦ ἅρματος αὐτοῦ, καὶ ἀνεγίνωσκεν τὸν προφήτην Ἠσαΐαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 29, 'Εἶπεν δὲ τὸ  ̊Πνεῦμα τῷ Φιλίππῳ, “Πρόσελθε καὶ κολλήθητι τῷ ἅρματι τούτῳ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 30, 'Προσδραμὼν δὲ, ὁ Φίλιππος ἤκουσεν αὐτοῦ ἀναγινώσκοντος Ἠσαΐαν τὸν προφήτην, καὶ εἶπεν, “Ἆρά γε γινώσκεις ἃ ἀναγινώσκεις;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 31, 'Ὁ δὲ εἶπεν, “Πῶς γὰρ ἂν δυναίμην ἐὰν μή τις ὁδηγήσει με;” Παρεκάλεσέν τε τὸν Φίλιππον ἀναβάντα καθίσαι σὺν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 32, 'Ἡ δὲ περιοχὴ τῆς Γραφῆς ἣν ἀνεγίνωσκεν ἦν αὕτη: “Ὡς πρόβατον ἐπὶ σφαγὴν ἤχθη, καὶ ὡς ἀμνὸς ἐναντίον τοῦ κείραντος αὐτὸν ἄφωνος, οὕτως οὐκ ἀνοίγει τὸ στόμα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 33, 'Ἐν τῇ ταπεινώσει, ἡ κρίσις αὐτοῦ ἤρθη, τὴν γενεὰν αὐτοῦ τίς διηγήσεται; Ὅτι αἴρεται ἀπὸ τῆς γῆς ἡ ζωὴ αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 34, 'Ἀποκριθεὶς δὲ ὁ εὐνοῦχος τῷ Φιλίππῳ εἶπεν, “Δέομαί σου περὶ τίνος ὁ προφήτης λέγει τοῦτο; Περὶ ἑαυτοῦ ἢ περὶ ἑτέρου τινός;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 35, 'Ἀνοίξας δὲ ὁ Φίλιππος τὸ στόμα αὐτοῦ, καὶ ἀρξάμενος ἀπὸ τῆς Γραφῆς ταύτης, εὐηγγελίσατο αὐτῷ τὸν  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 36, 'Ὡς δὲ ἐπορεύοντο κατὰ τὴν ὁδόν, ἦλθον ἐπί τι ὕδωρ, καί φησιν ὁ εὐνοῦχος, “Ἰδοὺ, ὕδωρ, τί κωλύει με βαπτισθῆναι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 37, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 38, 'Καὶ ἐκέλευσεν στῆναι τὸ ἅρμα, καὶ κατέβησαν, ἀμφότεροι εἰς τὸ ὕδωρ, ὅ τε Φίλιππος καὶ ὁ εὐνοῦχος, καὶ ἐβάπτισεν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 39, 'Ὅτε δὲ ἀνέβησαν ἐκ τοῦ ὕδατος,  ̊Πνεῦμα  ̊Κυρίου ἥρπασεν τὸν Φίλιππον, καὶ οὐκ εἶδεν αὐτὸν οὐκέτι ὁ εὐνοῦχος, ἐπορεύετο γὰρ τὴν ὁδὸν αὐτοῦ χαίρων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 40, 'Φίλιππος δὲ εὑρέθη εἰς Ἄζωτον, καὶ διερχόμενος εὐηγγελίζετο τὰς πόλεις πάσας, ἕως τοῦ ἐλθεῖν αὐτὸν εἰς Καισάρειαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 1, '¶Ὁ δὲ Σαῦλος, ἔτι ἐμπνέων ἀπειλῆς καὶ φόνου εἰς τοὺς μαθητὰς τοῦ  ̊Κυρίου, προσελθὼν τῷ ἀρχιερεῖ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 2, 'ᾐτήσατο παρʼ αὐτοῦ ἐπιστολὰς εἰς Δαμασκὸν πρὸς τὰς συναγωγάς, ὅπως ἐάν τινας εὕρῃ τῆς ὁδοῦ, ὄντας ἄνδρας τε καὶ γυναῖκας, δεδεμένους ἀγάγῃ εἰς Ἰερουσαλήμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 3, 'Ἐν δὲ τῷ πορεύεσθαι, ἐγένετο αὐτὸν ἐγγίζειν τῇ Δαμασκῷ, ἐξαίφνης τε αὐτὸν περιήστραψεν φῶς ἐκ τοῦ οὐρανοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 4, 'Καὶ πεσὼν ἐπὶ τὴν γῆν, ἤκουσεν φωνὴν λέγουσαν αὐτῷ, “Σαοὺλ, Σαούλ, τί με διώκεις;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 5, 'Εἶπεν δέ, “Τίς εἶ, Κύριε;” Ὁ δέ, “Ἐγώ εἰμι  ̊Ἰησοῦς, ὃν σὺ διώκεις·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 6, 'ἀλλὰ ἀνάστηθι καὶ εἴσελθε εἰς τὴν πόλιν, καὶ λαληθήσεταί σοι ὅ τί σε δεῖ ποιεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 7, 'Οἱ δὲ ἄνδρες οἱ συνοδεύοντες αὐτῷ εἱστήκεισαν ἐνεοί, ἀκούοντες μὲν τῆς φωνῆς, μηδένα δὲ θεωροῦντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 8, 'Ἠγέρθη δὲ Σαῦλος ἀπὸ τῆς γῆς, ἀνεῳγμένων δὲ τῶν ὀφθαλμῶν αὐτοῦ, οὐδὲν ἔβλεπεν. Χειραγωγοῦντες δὲ αὐτὸν, εἰσήγαγον εἰς Δαμασκόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 9, 'Καὶ ἦν ἡμέρας τρεῖς μὴ βλέπων, καὶ οὐκ ἔφαγεν οὐδὲ ἔπιεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 10, '¶Ἦν δέ τις μαθητὴς ἐν Δαμασκῷ ὀνόματι Ἁνανίας, καὶ εἶπεν πρὸς αὐτὸν ἐν ὁράματι ὁ  ̊Κύριος, “Ἁνανία.” Ὁ δὲ εἶπεν, “Ἰδοὺ, ἐγώ,  ̊Κύριε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 11, 'Ὁ δὲ  ̊Κύριος πρὸς αὐτόν, “Ἀναστὰς, πορεύθητι ἐπὶ τὴν ῥύμην τὴν καλουμένην Εὐθεῖαν, καὶ ζήτησον ἐν οἰκίᾳ Ἰούδα Σαῦλον ὀνόματι Ταρσέα, ἰδοὺ γὰρ, προσεύχεται');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 12, 'καὶ εἶδεν ἄνδρα ἐν ὁράματι, Ἁνανίαν ὀνόματι, εἰσελθόντα καὶ ἐπιθέντα αὐτῷ χεῖρας, ὅπως ἀναβλέψῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 13, 'Ἀπεκρίθη δὲ Ἁνανίας, “ ̊Κύριε, ἤκουσα ἀπὸ πολλῶν περὶ τοῦ ἀνδρὸς τούτου, ὅσα κακὰ τοῖς ἁγίοις σου ἐποίησεν ἐν Ἰερουσαλήμ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 14, 'καὶ ὧδε ἔχει ἐξουσίαν παρὰ τῶν ἀρχιερέων, δῆσαι πάντας τοὺς ἐπικαλουμένους τὸ ὄνομά σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 15, 'Εἶπεν δὲ πρὸς αὐτὸν ὁ  ̊Κύριος, “Πορεύου, ὅτι σκεῦος ἐκλογῆς ἐστίν μοι οὗτος, τοῦ βαστάσαι τὸ ὄνομά μου ἐνώπιον τῶν ἐθνῶν τε καὶ βασιλέων, υἱῶν τε Ἰσραήλ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 16, 'ἐγὼ γὰρ ὑποδείξω αὐτῷ ὅσα δεῖ αὐτὸν ὑπὲρ τοῦ ὀνόματός μου παθεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 17, 'Ἀπῆλθεν δὲ Ἁνανίας καὶ εἰσῆλθεν εἰς τὴν οἰκίαν, καὶ ἐπιθεὶς ἐπʼ αὐτὸν τὰς χεῖρας εἶπεν, “Σαοὺλ, ἀδελφέ, ὁ  ̊Κύριος ἀπέσταλκέν με  ̊Ἰησοῦς, ὁ ὀφθείς σοι ἐν τῇ ὁδῷ ᾗ ἤρχου, ὅπως ἀναβλέψῃς καὶ πλησθῇς  ̊Πνεύματος Ἁγίου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 18, 'Καὶ εὐθέως ἀπέπεσαν αὐτοῦ ἀπὸ τῶν ὀφθαλμῶν ὡς λεπίδες, ἀνέβλεψέν τε, καὶ ἀναστὰς ἐβαπτίσθη,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 19, 'καὶ λαβὼν τροφὴν, ἐνισχύθη. ¶Ἐγένετο δὲ μετὰ τῶν ἐν Δαμασκῷ μαθητῶν ἡμέρας τινὰς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 20, 'Καὶ εὐθέως ἐν ταῖς συναγωγαῖς, ἐκήρυσσεν τὸν  ̊Ἰησοῦν ὅτι οὗτός ἐστιν ὁ Υἱὸς τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 21, 'Ἐξίσταντο δὲ πάντες οἱ ἀκούοντες, καὶ ἔλεγον, “Οὐχ οὗτός ἐστιν ὁ πορθήσας ἐν Ἰερουσαλὴμ τοὺς ἐπικαλουμένους τὸ ὄνομα τοῦτο, καὶ ὧδε εἰς τοῦτο ἐληλύθει, ἵνα δεδεμένους, αὐτοὺς ἀγάγῃ ἐπὶ τοὺς ἀρχιερεῖς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 22, 'Σαῦλος δὲ μᾶλλον ἐνεδυναμοῦτο, καὶ συνέχυννεν Ἰουδαίους τοὺς κατοικοῦντας ἐν Δαμασκῷ, συμβιβάζων ὅτι οὗτός ἐστιν ὁ  ̊Χριστός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 23, '¶Ὡς δὲ ἐπληροῦντο ἡμέραι ἱκαναί, συνεβουλεύσαντο οἱ Ἰουδαῖοι ἀνελεῖν αὐτόν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 24, 'ἐγνώσθη δὲ τῷ Σαύλῳ ἡ ἐπιβουλὴ αὐτῶν. Παρετηροῦντο δὲ καὶ τὰς πύλας ἡμέρας τε καὶ νυκτὸς, ὅπως αὐτὸν ἀνέλωσιν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 25, 'λαβόντες δὲ οἱ μαθηταὶ αὐτοῦ νυκτὸς διὰ τοῦ τείχους, καθῆκαν αὐτὸν, χαλάσαντες ἐν σπυρίδι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 26, '¶Παραγενόμενος δὲ εἰς Ἰερουσαλὴμ, ἐπείραζεν κολλᾶσθαι τοῖς μαθηταῖς. Καὶ πάντες ἐφοβοῦντο αὐτόν, μὴ πιστεύοντες ὅτι ἐστὶν μαθητής.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 27, 'Βαρναβᾶς δὲ ἐπιλαβόμενος αὐτὸν, ἤγαγεν πρὸς τοὺς ἀποστόλους, καὶ διηγήσατο αὐτοῖς πῶς ἐν τῇ ὁδῷ εἶδεν τὸν  ̊Κύριον, καὶ ὅτι ἐλάλησεν αὐτῷ, καὶ πῶς ἐν Δαμασκῷ ἐπαρρησιάσατο ἐν τῷ ὀνόματι  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 28, 'Καὶ ἦν μετʼ αὐτῶν, εἰσπορευόμενος καὶ ἐκπορευόμενος εἰς Ἰερουσαλήμ, παρρησιαζόμενος ἐν τῷ ὀνόματι τοῦ  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 29, 'Ἐλάλει τε καὶ συνεζήτει πρὸς τοὺς Ἑλληνιστάς· οἱ δὲ ἐπεχείρουν ἀνελεῖν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 30, 'Ἐπιγνόντες δὲ, οἱ ἀδελφοὶ κατήγαγον αὐτὸν εἰς Καισάρειαν, καὶ ἐξαπέστειλαν αὐτὸν εἰς Ταρσόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 31, '¶Ἡ μὲν οὖν ἐκκλησία καθʼ ὅλης τῆς Ἰουδαίας, καὶ Γαλιλαίας, καὶ Σαμαρείας, εἶχεν εἰρήνην, οἰκοδομουμένη καὶ πορευομένη τῷ φόβῳ τοῦ  ̊Κυρίου, καὶ τῇ παρακλήσει τοῦ Ἁγίου  ̊Πνεύματος, ἐπληθύνετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 32, '¶Ἐγένετο δὲ Πέτρον διερχόμενον διὰ πάντων, κατελθεῖν καὶ πρὸς τοὺς ἁγίους τοὺς κατοικοῦντας Λύδδα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 33, 'Εὗρεν δὲ ἐκεῖ ἄνθρωπόν τινα ὀνόματι Αἰνέαν, ἐξ ἐτῶν ὀκτὼ κατακείμενον ἐπὶ κραβάττου, ὃς ἦν παραλελυμένος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 34, 'Καὶ εἶπεν αὐτῷ ὁ Πέτρος, “Αἰνέα, ἰᾶταί σε  ̊Ἰησοῦς  ̊Χριστός· ἀνάστηθι, καὶ στρῶσον σεαυτῷ.” Καὶ εὐθέως ἀνέστη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 35, 'Καὶ εἶδαν αὐτὸν πάντες οἱ κατοικοῦντες Λύδδα καὶ τὸν Σαρῶνα, οἵτινες ἐπέστρεψαν ἐπὶ τὸν  ̊Κύριον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 36, '¶Ἐν Ἰόππῃ δέ τις ἦν μαθήτρια ὀνόματι Ταβιθά, ἣ διερμηνευομένη λέγεται, “Δορκάς”. Αὕτη ἦν πλήρης ἔργων ἀγαθῶν, καὶ ἐλεημοσυνῶν ὧν ἐποίει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 37, 'Ἐγένετο δὲ ἐν ταῖς ἡμέραις ἐκείναις, ἀσθενήσασαν αὐτὴν ἀποθανεῖν. Λούσαντες δὲ αὐτὴν ἔθηκαν ἐν ὑπερῴῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 38, 'Ἐγγὺς δὲ οὔσης Λύδδας τῇ Ἰόππῃ, οἱ μαθηταὶ ἀκούσαντες ὅτι Πέτρος ἐστὶν ἐν αὐτῇ, ἀπέστειλαν δύο ἄνδρας πρὸς αὐτὸν παρακαλοῦντες, “Μὴ ὀκνήσῃς διελθεῖν ἕως ἡμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 39, 'Ἀναστὰς δὲ, Πέτρος συνῆλθεν αὐτοῖς, ὃν παραγενόμενον, ἀνήγαγον εἰς τὸ ὑπερῷον, καὶ παρέστησαν αὐτῷ πᾶσαι αἱ χῆραι, κλαίουσαι καὶ ἐπιδεικνύμεναι χιτῶνας καὶ ἱμάτια, ὅσα ἐποίει μετʼ αὐτῶν οὖσα ἡ Δορκάς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 40, 'Ἐκβαλὼν δὲ ἔξω πάντας ὁ Πέτρος, καὶ θεὶς τὰ γόνατα προσηύξατο, καὶ ἐπιστρέψας πρὸς τὸ σῶμα εἶπεν, “Ταβιθά, ἀνάστηθι!” Ἡ δὲ ἤνοιξεν τοὺς ὀφθαλμοὺς αὐτῆς, καὶ ἰδοῦσα τὸν Πέτρον, ἀνεκάθισεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 41, 'Δοὺς δὲ αὐτῇ χεῖρα, ἀνέστησεν αὐτήν, φωνήσας δὲ τοὺς ἁγίους καὶ τὰς χήρας, παρέστησεν αὐτὴν ζῶσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 42, 'Γνωστὸν δὲ ἐγένετο καθʼ ὅλης Ἰόππης, καὶ ἐπίστευσαν πολλοὶ ἐπὶ τὸν  ̊Κύριον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 43, 'Ἐγένετο δὲ ἡμέρας ἱκανὰς μεῖναι ἐν Ἰόππῃ, παρά τινι Σίμωνι, βυρσεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 1, '¶Ἀνὴρ δέ τις ἐν Καισαρείᾳ ὀνόματι Κορνήλιος, ἑκατοντάρχης ἐκ Σπείρης τῆς καλουμένης Ἰταλικῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 2, 'εὐσεβὴς καὶ φοβούμενος τὸν  ̊Θεὸν σὺν παντὶ τῷ οἴκῳ αὐτοῦ, ποιῶν ἐλεημοσύνας πολλὰς τῷ λαῷ, καὶ δεόμενος τοῦ  ̊Θεοῦ διὰ παντός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 3, 'Εἶδεν ἐν ὁράματι φανερῶς, ὡσεὶ περὶ ὥραν ἐνάτην τῆς ἡμέρας, ἄγγελον τοῦ  ̊Θεοῦ εἰσελθόντα πρὸς αὐτὸν, καὶ εἰπόντα αὐτῷ, “Κορνήλιε!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 4, 'Ὁ δὲ, ἀτενίσας αὐτῷ καὶ ἔμφοβος γενόμενος, εἶπεν, “Τί ἐστιν, κύριε;” Εἶπεν δὲ αὐτῷ, “Αἱ προσευχαί σου, καὶ αἱ ἐλεημοσύναι σου, ἀνέβησαν εἰς μνημόσυνον ἔμπροσθεν τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 5, 'Καὶ νῦν πέμψον ἄνδρας εἰς Ἰόππην, καὶ μετάπεμψαι Σίμωνά τινα, ὃς ἐπικαλεῖται Πέτρος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 6, 'Οὗτος ξενίζεται παρά τινι Σίμωνι βυρσεῖ, ᾧ ἐστιν οἰκία παρὰ θάλασσαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 7, 'Ὡς δὲ ἀπῆλθεν ὁ ἄγγελος ὁ λαλῶν αὐτῷ, φωνήσας δύο τῶν οἰκετῶν καὶ στρατιώτην εὐσεβῆ τῶν προσκαρτερούντων αὐτῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 8, 'καὶ ἐξηγησάμενος ἅπαντα αὐτοῖς, ἀπέστειλεν αὐτοὺς εἰς τὴν Ἰόππην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 9, '¶Τῇ δὲ ἐπαύριον, ὁδοιπορούντων ἐκείνων καὶ τῇ πόλει ἐγγιζόντων, ἀνέβη Πέτρος ἐπὶ τὸ δῶμα προσεύξασθαι, περὶ ὥραν ἕκτην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 10, 'Ἐγένετο δὲ πρόσπεινος καὶ ἤθελεν γεύσασθαι, παρασκευαζόντων δὲ αὐτῶν, ἐγένετο ἐπʼ αὐτὸν ἔκστασις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 11, 'καὶ θεωρεῖ τὸν οὐρανὸν ἀνεῳγμένον, καὶ καταβαῖνον σκεῦός τι ὡς ὀθόνην μεγάλην, τέσσαρσιν ἀρχαῖς καθιέμενον ἐπὶ τῆς γῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 12, 'ἐν ᾧ ὑπῆρχεν πάντα τὰ τετράποδα, καὶ ἑρπετὰ τῆς γῆς, καὶ πετεινὰ τοῦ οὐρανοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 13, 'Καὶ ἐγένετο φωνὴ πρὸς αὐτόν: “Ἀναστάς, Πέτρε, θῦσον καὶ φάγε!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 14, 'Ὁ δὲ Πέτρος εἶπεν, “Μηδαμῶς,  ̊Κύριε, ὅτι οὐδέποτε ἔφαγον πᾶν κοινὸν καὶ ἀκάθαρτον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 15, 'Καὶ φωνὴ πάλιν ἐκ δευτέρου πρὸς αὐτόν: “Ἃ ὁ  ̊Θεὸς ἐκαθάρισεν, σὺ μὴ κοίνου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 16, 'Τοῦτο δὲ ἐγένετο ἐπὶ τρίς, καὶ εὐθὺς ἀνελήμφθη τὸ σκεῦος εἰς τὸν οὐρανόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 17, '¶Ὡς δὲ ἐν ἑαυτῷ διηπόρει ὁ Πέτρος, τί ἂν εἴη τὸ ὅραμα ὃ εἶδεν, ἰδοὺ, οἱ ἄνδρες οἱ ἀπεσταλμένοι ὑπὸ τοῦ Κορνηλίου, διερωτήσαντες τὴν οἰκίαν τοῦ Σίμωνος, ἐπέστησαν ἐπὶ τὸν πυλῶνα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 18, 'Καὶ φωνήσαντες, ἐπυνθάνοντο εἰ Σίμων, ὁ ἐπικαλούμενος Πέτρος, ἐνθάδε ξενίζεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 19, 'Τοῦ δὲ Πέτρου διενθυμουμένου περὶ τοῦ ὁράματος, εἶπεν τὸ  ̊Πνεῦμα, αὐτῷ, “Ἰδοὺ, ἄνδρες τρεῖς ζητοῦσίν σε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 20, 'Ἀλλὰ ἀναστὰς, κατάβηθι καὶ πορεύου σὺν αὐτοῖς, μηδὲν διακρινόμενος, ὅτι ἐγὼ ἀπέσταλκα αὐτούς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 21, 'Καταβὰς δὲ, Πέτρος πρὸς τοὺς ἄνδρας εἶπεν, “Ἰδοὺ, ἐγώ εἰμι ὃν ζητεῖτε· τίς ἡ αἰτία διʼ ἣν πάρεστε;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 22, 'Οἱ δὲ εἶπαν, “Κορνήλιος ἑκατοντάρχης, ἀνὴρ δίκαιος καὶ φοβούμενος τὸν  ̊Θεὸν, μαρτυρούμενός τε ὑπὸ ὅλου τοῦ ἔθνους τῶν Ἰουδαίων, ἐχρηματίσθη ὑπὸ ἀγγέλου ἁγίου, μεταπέμψασθαί σε εἰς τὸν οἶκον αὐτοῦ, καὶ ἀκοῦσαι ῥήματα παρὰ σοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 23, 'Εἰσκαλεσάμενος οὖν αὐτοὺς ἐξένισεν. ¶Τῇ δὲ ἐπαύριον ἀναστὰς, ἐξῆλθεν σὺν αὐτοῖς, καί τινες τῶν ἀδελφῶν τῶν ἀπὸ Ἰόππης συνῆλθον αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 24, 'Τῇ δὲ ἐπαύριον, εἰσῆλθεν εἰς τὴν Καισάρειαν. Ὁ δὲ Κορνήλιος ἦν προσδοκῶν αὐτοὺς, συγκαλεσάμενος τοὺς συγγενεῖς αὐτοῦ καὶ τοὺς ἀναγκαίους φίλους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 25, 'Ὡς δὲ ἐγένετο τοῦ εἰσελθεῖν τὸν Πέτρον, συναντήσας αὐτῷ ὁ Κορνήλιος, πεσὼν ἐπὶ τοὺς πόδας, προσεκύνησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 26, 'Ὁ δὲ Πέτρος ἤγειρεν αὐτὸν λέγων, “Ἀνάστηθι· καὶ ἐγὼ αὐτὸς ἄνθρωπός εἰμι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 27, 'Καὶ συνομιλῶν αὐτῷ, εἰσῆλθεν καὶ εὑρίσκει συνεληλυθότας πολλούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 28, 'Ἔφη τε πρὸς αὐτούς, “Ὑμεῖς ἐπίστασθε ὡς ἀθέμιτόν ἐστιν ἀνδρὶ Ἰουδαίῳ κολλᾶσθαι ἢ προσέρχεσθαι ἀλλοφύλῳ. Κἀμοὶ ὁ  ̊Θεὸς ἔδειξεν, μηδένα κοινὸν ἢ ἀκάθαρτον λέγειν ἄνθρωπον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 29, 'Διὸ καὶ ἀναντιρρήτως ἦλθον, μεταπεμφθείς. Πυνθάνομαι οὖν τίνι λόγῳ μετεπέμψασθέ με;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 30, '¶Καὶ ὁ Κορνήλιος ἔφη, “Ἀπὸ τετάρτης ἡμέρας μέχρι ταύτης τῆς ὥρας, ἤμην τὴν ἐνάτην προσευχόμενος ἐν τῷ οἴκῳ μου, καὶ ἰδοὺ, ἀνὴρ ἔστη ἐνώπιόν μου ἐν ἐσθῆτι λαμπρᾷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 31, 'καὶ φησίν, ‘Κορνήλιε, εἰσηκούσθη σου ἡ προσευχὴ καὶ αἱ ἐλεημοσύναι σου ἐμνήσθησαν ἐνώπιον τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 32, 'Πέμψον οὖν εἰς Ἰόππην καὶ μετακάλεσαι Σίμωνα, ὃς ἐπικαλεῖται Πέτρος· οὗτος ξενίζεται ἐν οἰκίᾳ Σίμωνος, βυρσέως παρὰ θάλασσαν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 33, 'Ἐξαυτῆς οὖν ἔπεμψα πρὸς σέ, σύ τε καλῶς ἐποίησας παραγενόμενος. Νῦν οὖν πάντες ἡμεῖς ἐνώπιον τοῦ  ̊Θεοῦ πάρεσμεν, ἀκοῦσαι πάντα τὰ προστεταγμένα σοι ὑπὸ τοῦ  ̊Κυρίου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 34, '¶Ἀνοίξας δὲ Πέτρος τὸ στόμα εἶπεν, “Ἐπʼ ἀληθείας καταλαμβάνομαι ὅτι οὐκ ἔστιν προσωπολήμπτης ὁ  ̊Θεός,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 35, 'ἀλλʼ ἐν παντὶ ἔθνει, ὁ φοβούμενος αὐτὸν καὶ ἐργαζόμενος δικαιοσύνην, δεκτὸς αὐτῷ ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 36, 'Τὸν λόγον ἀπέστειλεν τοῖς υἱοῖς Ἰσραὴλ, εὐαγγελιζόμενος εἰρήνην διὰ  ̊Ἰησοῦ  ̊Χριστοῦ· οὗτός ἐστιν πάντων  ̊Κύριος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 37, 'Ὑμεῖς οἴδατε τὸ γενόμενον ῥῆμα καθʼ ὅλης τῆς Ἰουδαίας, ἀρξάμενος ἀπὸ τῆς Γαλιλαίας, μετὰ τὸ βάπτισμα ὃ ἐκήρυξεν Ἰωάννης,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 38, ' ̊Ἰησοῦν τὸν ἀπὸ Ναζαρέθ, ὡς ἔχρισεν αὐτὸν ὁ  ̊Θεὸς  ̊Πνεύματι Ἁγίῳ καὶ δυνάμει, ὃς διῆλθεν εὐεργετῶν καὶ ἰώμενος πάντας τοὺς καταδυναστευομένους ὑπὸ τοῦ διαβόλου, ὅτι ὁ  ̊Θεὸς ἦν μετʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 39, 'Καὶ ἡμεῖς μάρτυρες πάντων ὧν ἐποίησεν ἔν τε τῇ χώρᾳ τῶν Ἰουδαίων καὶ ἐν Ἰερουσαλήμ· ὃν καὶ ἀνεῖλαν, κρεμάσαντες ἐπὶ ξύλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 40, 'Τοῦτον ὁ  ̊Θεὸς ἤγειρεν τῇ τρίτῃ ἡμέρᾳ, καὶ ἔδωκεν αὐτὸν ἐμφανῆ γενέσθαι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 41, 'οὐ παντὶ τῷ λαῷ, ἀλλὰ μάρτυσι τοῖς προκεχειροτονημένοις ὑπὸ τοῦ  ̊Θεοῦ, ἡμῖν, οἵτινες συνεφάγομεν καὶ συνεπίομεν αὐτῷ μετὰ τὸ ἀναστῆναι αὐτὸν ἐκ νεκρῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 42, 'Καὶ παρήγγειλεν ἡμῖν κηρύξαι τῷ λαῷ, καὶ διαμαρτύρασθαι ὅτι οὗτός ἐστιν ὁ ὡρισμένος ὑπὸ τοῦ  ̊Θεοῦ, κριτὴς ζώντων καὶ νεκρῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 43, 'Τούτῳ πάντες οἱ προφῆται μαρτυροῦσιν, ἄφεσιν ἁμαρτιῶν λαβεῖν διὰ τοῦ ὀνόματος αὐτοῦ, πάντα τὸν πιστεύοντα εἰς αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 44, '¶Ἔτι λαλοῦντος τοῦ Πέτρου τὰ ῥήματα ταῦτα, ἐπέπεσε τὸ  ̊Πνεῦμα τὸ Ἅγιον ἐπὶ πάντας τοὺς ἀκούοντας τὸν λόγον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 45, 'Καὶ ἐξέστησαν οἱ ἐκ περιτομῆς πιστοὶ, ὅσοι συνῆλθαν τῷ Πέτρῳ, ὅτι καὶ ἐπὶ τὰ ἔθνη, ἡ δωρεὰ τοῦ Ἁγίου  ̊Πνεύματος ἐκκέχυται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 46, 'Ἤκουον γὰρ αὐτῶν λαλούντων γλώσσαις, καὶ μεγαλυνόντων τὸν  ̊Θεόν. Τότε ἀπεκρίθη Πέτρος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 47, '“Μήτι τὸ ὕδωρ δύναται κωλῦσαί τις τοῦ μὴ βαπτισθῆναι τούτους, οἵτινες τὸ  ̊Πνεῦμα τὸ Ἅγιον ἔλαβον, ὡς καὶ ἡμεῖς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 48, 'Προσέταξεν δὲ αὐτοὺς ἐν τῷ ὀνόματι  ̊Ἰησοῦ  ̊Χριστοῦ βαπτισθῆναι. Τότε ἠρώτησαν αὐτὸν ἐπιμεῖναι ἡμέρας τινάς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 1, '¶Ἤκουσαν δὲ οἱ ἀπόστολοι καὶ οἱ ἀδελφοὶ οἱ ὄντες κατὰ τὴν Ἰουδαίαν ὅτι καὶ τὰ ἔθνη ἐδέξαντο τὸν λόγον τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 2, 'Ὅτε δὲ ἀνέβη Πέτρος εἰς Ἰερουσαλήμ, διεκρίνοντο πρὸς αὐτὸν οἱ ἐκ περιτομῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 3, 'λέγοντες, ὅτι “Εἰσῆλθεν πρὸς ἄνδρας, ἀκροβυστίαν ἔχοντας, καὶ συνέφαγεν αὐτοῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 4, 'Ἀρξάμενος δὲ, Πέτρος ἐξετίθετο αὐτοῖς καθεξῆς, λέγων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 5, '“Ἐγὼ ἤμην ἐν πόλει Ἰόππῃ προσευχόμενος, καὶ εἶδον ἐν ἐκστάσει ὅραμα, καταβαῖνον σκεῦός τι ὡς ὀθόνην μεγάλην, τέσσαρσιν ἀρχαῖς καθιεμένην ἐκ τοῦ οὐρανοῦ, καὶ ἦλθεν ἄχρι ἐμοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 6, 'εἰς ἣν ἀτενίσας κατενόουν, καὶ εἶδον τὰ τετράποδα τῆς γῆς, καὶ τὰ θηρία, καὶ τὰ ἑρπετὰ, καὶ τὰ πετεινὰ τοῦ οὐρανοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 7, 'Ἤκουσα δὲ καὶ φωνῆς λεγούσης μοι, ‘Ἀναστάς, Πέτρε, θῦσον καὶ φάγε.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 8, 'Εἶπον δέ, ‘Μηδαμῶς,  ̊Κύριε, ὅτι κοινὸν ἢ ἀκάθαρτον οὐδέποτε εἰσῆλθεν εἰς τὸ στόμα μου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 9, 'Ἀπεκρίθη δὲ φωνὴ ἐκ δευτέρου ἐκ τοῦ οὐρανοῦ, ‘Ἃ ὁ  ̊Θεὸς ἐκαθάρισεν, σὺ μὴ κοίνου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 10, 'Τοῦτο δὲ ἐγένετο ἐπὶ τρίς, καὶ ἀνεσπάσθη πάλιν ἅπαντα εἰς τὸν οὐρανόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 11, 'Καὶ ἰδοὺ, ἐξαυτῆς τρεῖς ἄνδρες ἐπέστησαν ἐπὶ τὴν οἰκίαν ἐν ᾗ ἦμεν, ἀπεσταλμένοι ἀπὸ Καισαρείας πρός με.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 12, 'Εἶπεν δὲ τὸ  ̊Πνεῦμά μοι, συνελθεῖν αὐτοῖς, μηδὲν διακρίναντα. Ἦλθον δὲ σὺν ἐμοὶ καὶ οἱ ἓξ ἀδελφοὶ οὗτοι, καὶ εἰσήλθομεν εἰς τὸν οἶκον τοῦ ἀνδρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 13, 'Ἀπήγγειλεν δὲ ἡμῖν πῶς εἶδεν τὸν ἄγγελον ἐν τῷ οἴκῳ αὐτοῦ, σταθέντα καὶ εἰπόντα, ‘Ἀπόστειλον εἰς Ἰόππην, καὶ μετάπεμψαι Σίμωνα, τὸν ἐπικαλούμενον Πέτρον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 14, 'ὃς λαλήσει ῥήματα πρὸς σὲ, ἐν οἷς σωθήσῃ σὺ καὶ πᾶς ὁ οἶκός σου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 15, 'Ἐν δὲ τῷ ἄρξασθαί με λαλεῖν, ἐπέπεσεν τὸ  ̊Πνεῦμα τὸ Ἅγιον ἐπʼ αὐτοὺς, ὥσπερ καὶ ἐφʼ ἡμᾶς ἐν ἀρχῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 16, 'Ἐμνήσθην δὲ τοῦ ῥήματος τοῦ  ̊Κυρίου, ὡς ἔλεγεν, ‘Ἰωάννης μὲν ἐβάπτισεν ὕδατι, ὑμεῖς δὲ βαπτισθήσεσθε ἐν  ̊Πνεύματι Ἁγίῳ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 17, 'Εἰ οὖν τὴν ἴσην δωρεὰν ἔδωκεν αὐτοῖς ὁ  ̊Θεὸς, ὡς καὶ ἡμῖν πιστεύσασιν ἐπὶ τὸν  ̊Κύριον  ̊Ἰησοῦν  ̊Χριστόν, ἐγὼ τίς ἤμην δυνατὸς κωλῦσαι τὸν  ̊Θεόν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 18, 'Ἀκούσαντες δὲ ταῦτα, ἡσύχασαν καὶ ἐδόξασαν τὸν  ̊Θεὸν λέγοντες, “Ἄρα καὶ τοῖς ἔθνεσιν ὁ  ̊Θεὸς τὴν μετάνοιαν εἰς ζωὴν ἔδωκεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 19, '¶Οἱ μὲν οὖν διασπαρέντες ἀπὸ τῆς θλίψεως τῆς γενομένης ἐπὶ Στεφάνῳ, διῆλθον ἕως Φοινίκης, καὶ Κύπρου, καὶ Ἀντιοχείας, μηδενὶ λαλοῦντες τὸν λόγον εἰ μὴ μόνον Ἰουδαίοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 20, 'Ἦσαν δέ τινες ἐξ αὐτῶν ἄνδρες, Κύπριοι καὶ Κυρηναῖοι, οἵτινες ἐλθόντες εἰς Ἀντιόχειαν, ἐλάλουν καὶ πρὸς τοὺς Ἑλληνιστάς, εὐαγγελιζόμενοι τὸν  ̊Κύριον  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 21, 'Καὶ ἦν χεὶρ  ̊Κυρίου μετʼ αὐτῶν, πολύς τε ἀριθμὸς ὁ πιστεύσας, ἐπέστρεψεν ἐπὶ τὸν  ̊Κύριον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 22, 'Ἠκούσθη δὲ ὁ λόγος εἰς τὰ ὦτα τῆς ἐκκλησίας τῆς οὔσης ἐν Ἰερουσαλὴμ περὶ αὐτῶν, καὶ ἐξαπέστειλαν Βαρναβᾶν ἕως Ἀντιοχείας·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 23, 'ὃς παραγενόμενος, καὶ ἰδὼν τὴν χάριν τὴν τοῦ  ̊Θεοῦ, ἐχάρη καὶ παρεκάλει πάντας τῇ προθέσει τῆς καρδίας προσμένειν τῷ  ̊Κυρίῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 24, 'ὅτι ἦν ἀνὴρ ἀγαθὸς, καὶ πλήρης  ̊Πνεύματος Ἁγίου καὶ πίστεως. Καὶ προσετέθη ὄχλος ἱκανὸς τῷ  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 25, 'Ἐξῆλθεν δὲ εἰς Ταρσὸν ἀναζητῆσαι Σαῦλον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 26, 'καὶ εὑρὼν, ἤγαγεν εἰς Ἀντιόχειαν. Ἐγένετο δὲ αὐτοῖς καὶ ἐνιαυτὸν ὅλον συναχθῆναι ἐν τῇ ἐκκλησίᾳ, καὶ διδάξαι ὄχλον ἱκανόν, χρηματίσαι τε πρώτως ἐν Ἀντιοχείᾳ τοὺς μαθητὰς, Χριστιανούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 27, '¶Ἐν ταύταις δὲ ταῖς ἡμέραις, κατῆλθον ἀπὸ Ἱεροσολύμων προφῆται εἰς Ἀντιόχειαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 28, 'Ἀναστὰς δὲ εἷς ἐξ αὐτῶν ὀνόματι Ἅγαβος, ἐσήμανεν διὰ τοῦ  ̊Πνεύματος, λιμὸν μεγάλην μέλλειν ἔσεσθαι ἐφʼ ὅλην τὴν οἰκουμένην· ἥτις ἐγένετο ἐπὶ Κλαυδίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 29, 'Τῶν δὲ μαθητῶν καθὼς εὐπορεῖτό τις, ὥρισαν ἕκαστος αὐτῶν εἰς διακονίαν πέμψαι τοῖς κατοικοῦσιν ἐν τῇ Ἰουδαίᾳ ἀδελφοῖς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 30, 'ὃ καὶ ἐποίησαν, ἀποστείλαντες πρὸς τοὺς πρεσβυτέρους διὰ χειρὸς Βαρναβᾶ καὶ Σαύλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 1, '¶Κατʼ ἐκεῖνον δὲ τὸν καιρὸν, ἐπέβαλεν Ἡρῴδης ὁ βασιλεὺς τὰς χεῖρας κακῶσαί τινας τῶν ἀπὸ τῆς ἐκκλησίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 2, 'Ἀνεῖλεν δὲ Ἰάκωβον, τὸν ἀδελφὸν Ἰωάννου, μαχαίρῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 3, 'Ἰδὼν δὲ ὅτι ἀρεστόν ἐστιν τοῖς Ἰουδαίοις, προσέθετο συλλαβεῖν καὶ Πέτρον (ἦσαν δὲ ἡμέραι τῶν Ἀζύμων),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 4, 'ὃν καὶ πιάσας, ἔθετο εἰς φυλακήν, παραδοὺς τέσσαρσιν τετραδίοις στρατιωτῶν φυλάσσειν αὐτόν, βουλόμενος μετὰ τὸ Πάσχα ἀναγαγεῖν αὐτὸν τῷ λαῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 5, 'Ὁ μὲν οὖν Πέτρος ἐτηρεῖτο ἐν τῇ φυλακῇ· προσευχὴ δὲ ἦν ἐκτενῶς γινομένη ὑπὸ τῆς ἐκκλησίας πρὸς τὸν  ̊Θεὸν περὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 6, '¶Ὅτε δὲ ἤμελλεν προσαγαγεῖν αὐτὸν ὁ Ἡρῴδης τῇ νυκτὶ ἐκείνῃ, ἦν ὁ Πέτρος κοιμώμενος μεταξὺ δύο στρατιωτῶν, δεδεμένος ἁλύσεσιν δυσίν, φύλακές τε πρὸ τῆς θύρας ἐτήρουν τὴν φυλακήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 7, 'Καὶ ἰδοὺ, ἄγγελος  ̊Κυρίου ἐπέστη, καὶ φῶς ἔλαμψεν ἐν τῷ οἰκήματι. Πατάξας δὲ τὴν πλευρὰν τοῦ Πέτρου, ἤγειρεν αὐτὸν λέγων, “Ἀνάστα ἐν τάχει.” Καὶ ἐξέπεσαν αὐτοῦ αἱ ἁλύσεις ἐκ τῶν χειρῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 8, 'Εἶπεν δὲ ὁ ἄγγελος πρὸς αὐτόν, “Ζῶσαι καὶ ὑπόδησαι τὰ σανδάλιά σου.” Ἐποίησεν δὲ οὕτως. Καὶ λέγει αὐτῷ, “Περιβαλοῦ τὸ ἱμάτιόν σου, καὶ ἀκολούθει μοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 9, 'Καὶ ἐξελθὼν ἠκολούθει, καὶ οὐκ ᾔδει ὅτι ἀληθές ἐστιν τὸ γινόμενον διὰ τοῦ ἀγγέλου, ἐδόκει δὲ ὅραμα βλέπειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 10, 'Διελθόντες δὲ πρώτην φυλακὴν καὶ δευτέραν, ἦλθαν ἐπὶ τὴν πύλην τὴν σιδηρᾶν, τὴν φέρουσαν εἰς τὴν πόλιν, ἥτις αὐτομάτη ἠνοίγη αὐτοῖς, καὶ ἐξελθόντες προῆλθον ῥύμην μίαν, καὶ εὐθέως ἀπέστη ὁ ἄγγελος ἀπʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 11, 'Καὶ ὁ Πέτρος ἐν ἑαυτῷ γενόμενος εἶπεν, “Νῦν οἶδα ἀληθῶς ὅτι ἐξαπέστειλεν  ̊Κύριος τὸν ἄγγελον αὐτοῦ, καὶ ἐξείλατό με ἐκ χειρὸς Ἡρῴδου καὶ πάσης τῆς προσδοκίας τοῦ λαοῦ τῶν Ἰουδαίων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 12, '¶Συνιδών τε, ἦλθεν ἐπὶ τὴν οἰκίαν τῆς Μαρίας, τῆς μητρὸς Ἰωάννου, τοῦ ἐπικαλουμένου Μάρκου, οὗ ἦσαν ἱκανοὶ συνηθροισμένοι καὶ προσευχόμενοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 13, 'Κρούσαντος δὲ αὐτοῦ τὴν θύραν τοῦ πυλῶνος, προσῆλθεν παιδίσκη ὑπακοῦσαι, ὀνόματι Ῥόδη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 14, 'Καὶ ἐπιγνοῦσα τὴν φωνὴν τοῦ Πέτρου, ἀπὸ τῆς χαρᾶς οὐκ ἤνοιξεν τὸν πυλῶνα, εἰσδραμοῦσα δὲ ἀπήγγειλεν ἑστάναι τὸν Πέτρον πρὸ τοῦ πυλῶνος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 15, 'Οἱ δὲ πρὸς αὐτὴν εἶπαν, “Μαίνῃ!” Ἡ δὲ διϊσχυρίζετο οὕτως ἔχειν. Οἱ δὲ ἔλεγον, “Ὁ ἄγγελός ἐστιν αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 16, 'Ὁ δὲ Πέτρος ἐπέμενεν κρούων, ἀνοίξαντες δὲ εἶδαν αὐτὸν, καὶ ἐξέστησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 17, 'Κατασείσας δὲ αὐτοῖς τῇ χειρὶ σιγᾶν, διηγήσατο αὐτοῖς πῶς ὁ  ̊Κύριος αὐτὸν ἐξήγαγεν ἐκ τῆς φυλακῆς. Εἶπέν τε, “Ἀπαγγείλατε Ἰακώβῳ καὶ τοῖς ἀδελφοῖς ταῦτα.” Καὶ ἐξελθὼν, ἐπορεύθη εἰς ἕτερον τόπον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 18, '¶Γενομένης δὲ ἡμέρας, ἦν τάραχος οὐκ ὀλίγος ἐν τοῖς στρατιώταις, τί ἄρα ὁ Πέτρος ἐγένετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 19, 'Ἡρῴδης δὲ ἐπιζητήσας αὐτὸν καὶ μὴ εὑρὼν, ἀνακρίνας τοὺς φύλακας, ἐκέλευσεν ἀπαχθῆναι. Καὶ κατελθὼν ἀπὸ τῆς Ἰουδαίας εἰς Καισάρειαν, διέτριβεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 20, '¶Ἦν δὲ θυμομαχῶν Τυρίοις καὶ Σιδωνίοις· ὁμοθυμαδὸν δὲ παρῆσαν πρὸς αὐτόν, καὶ πείσαντες Βλάστον, τὸν ἐπὶ τοῦ κοιτῶνος τοῦ βασιλέως, ᾐτοῦντο εἰρήνην, διὰ τὸ τρέφεσθαι αὐτῶν τὴν χώραν ἀπὸ τῆς βασιλικῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 21, 'Τακτῇ δὲ ἡμέρᾳ, ὁ Ἡρῴδης, ἐνδυσάμενος ἐσθῆτα βασιλικὴν, καθίσας ἐπὶ τοῦ βήματος, ἐδημηγόρει πρὸς αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 22, 'Ὁ δὲ δῆμος ἐπεφώνει, “ ̊Θεοῦ φωνὴ, καὶ οὐκ ἀνθρώπου!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 23, 'Παραχρῆμα δὲ ἐπάταξεν αὐτὸν ἄγγελος  ̊Κυρίου, ἀνθʼ ὧν οὐκ ἔδωκεν τὴν δόξαν τῷ  ̊Θεῷ, καὶ γενόμενος σκωληκόβρωτος, ἐξέψυξεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 24, '¶Ὁ δὲ λόγος τοῦ  ̊Θεοῦ ηὔξανεν καὶ ἐπληθύνετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 25, 'Βαρναβᾶς δὲ καὶ Σαῦλος ὑπέστρεψαν εἰς Ἰερουσαλὴμ, πληρώσαντες τὴν διακονίαν, συμπαραλαβόντες Ἰωάννην, τὸν ἐπικληθέντα Μᾶρκον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 1, '¶Ἦσαν δὲ ἐν Ἀντιοχείᾳ, κατὰ τὴν οὖσαν ἐκκλησίαν προφῆται καὶ διδάσκαλοι: ὅ τε Βαρναβᾶς, καὶ Συμεὼν ὁ καλούμενος Νίγερ, καὶ Λούκιος ὁ Κυρηναῖος, Μαναήν τε Ἡρῴδου τοῦ τετράρχου σύντροφος, καὶ Σαῦλος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 2, 'Λειτουργούντων δὲ αὐτῶν τῷ  ̊Κυρίῳ καὶ νηστευόντων, εἶπεν τὸ  ̊Πνεῦμα τὸ Ἅγιον, “Ἀφορίσατε δή μοι τὸν Βαρναβᾶν καὶ Σαῦλον, εἰς τὸ ἔργον ὃ προσκέκλημαι αὐτούς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 3, 'Τότε νηστεύσαντες, καὶ προσευξάμενοι, καὶ ἐπιθέντες τὰς χεῖρας αὐτοῖς, ἀπέλυσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 4, '¶Αὐτοὶ μὲν οὖν ἐκπεμφθέντες ὑπὸ τοῦ Ἁγίου  ̊Πνεύματος, κατῆλθον εἰς Σελεύκειαν, ἐκεῖθέν τε ἀπέπλευσαν εἰς Κύπρον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 5, 'Καὶ γενόμενοι ἐν Σαλαμῖνι, κατήγγελλον τὸν λόγον τοῦ  ̊Θεοῦ ἐν ταῖς συναγωγαῖς τῶν Ἰουδαίων. Εἶχον δὲ καὶ Ἰωάννην, ὑπηρέτην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 6, 'Διελθόντες δὲ ὅλην τὴν νῆσον ἄχρι Πάφου, εὗρον ἄνδρα, τινὰ μάγον ψευδοπροφήτην Ἰουδαῖον, ᾧ ὄνομα Βαριησοῦς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 7, 'ὃς ἦν σὺν τῷ ἀνθυπάτῳ Σεργίῳ Παύλῳ, ἀνδρὶ συνετῷ. Οὗτος, προσκαλεσάμενος Βαρναβᾶν καὶ Σαῦλον, ἐπεζήτησεν ἀκοῦσαι τὸν λόγον τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 8, 'Ἀνθίστατο δὲ αὐτοῖς Ἐλύμας ὁ μάγος (οὕτως γὰρ μεθερμηνεύεται τὸ ὄνομα αὐτοῦ) ζητῶν διαστρέψαι τὸν ἀνθύπατον ἀπὸ τῆς πίστεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 9, 'Σαῦλος δέ, ὁ καὶ Παῦλος, πλησθεὶς  ̊Πνεύματος Ἁγίου, ἀτενίσας εἰς αὐτὸν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 10, 'εἶπεν, “Ὦ πλήρης παντὸς δόλου καὶ πάσης ῥᾳδιουργίας, υἱὲ διαβόλου, ἐχθρὲ πάσης δικαιοσύνης, οὐ παύσῃ διαστρέφων τὰς ὁδοὺς τοῦ  ̊Κυρίου τὰς εὐθείας;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 11, 'Καὶ νῦν ἰδοὺ, χεὶρ  ̊Κυρίου ἐπὶ σέ, καὶ ἔσῃ τυφλὸς, μὴ βλέπων τὸν ἥλιον ἄχρι καιροῦ.” Παραχρῆμά τε ἔπεσεν ἐπʼ αὐτὸν ἀχλὺς καὶ σκότος, καὶ περιάγων ἐζήτει χειραγωγούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 12, 'Τότε ἰδὼν ὁ ἀνθύπατος τὸ γεγονὸς, ἐπίστευσεν ἐκπλησσόμενος ἐπὶ τῇ διδαχῇ τοῦ  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 13, '¶Ἀναχθέντες δὲ ἀπὸ τῆς Πάφου οἱ περὶ, Παῦλον ἦλθον εἰς Πέργην τῆς Παμφυλίας. Ἰωάννης δὲ ἀποχωρήσας ἀπʼ αὐτῶν, ὑπέστρεψεν εἰς Ἱεροσόλυμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 14, 'Αὐτοὶ δὲ, διελθόντες ἀπὸ τῆς Πέργης, παρεγένοντο εἰς Ἀντιόχειαν τὴν Πισιδίαν, καὶ ἐλθόντες εἰς τὴν συναγωγὴν τῇ ἡμέρᾳ τῶν Σαββάτων, ἐκάθισαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 15, 'Μετὰ δὲ τὴν ἀνάγνωσιν τοῦ νόμου καὶ τῶν προφητῶν, ἀπέστειλαν οἱ ἀρχισυνάγωγοι πρὸς αὐτοὺς λέγοντες, “Ἄνδρες, ἀδελφοί, εἴ τίς ἐστιν ἐν ὑμῖν λόγος παρακλήσεως πρὸς τὸν λαόν, λέγετε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 16, 'Ἀναστὰς δὲ Παῦλος, καὶ κατασείσας τῇ χειρὶ εἶπεν, “Ἄνδρες, Ἰσραηλῖται, καὶ οἱ φοβούμενοι τὸν  ̊Θεόν, ἀκούσατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 17, 'Ὁ  ̊Θεὸς τοῦ λαοῦ τούτου Ἰσραὴλ ἐξελέξατο τοὺς πατέρας ἡμῶν, καὶ τὸν λαὸν ὕψωσεν ἐν τῇ παροικίᾳ ἐν γῇ Αἰγύπτου, καὶ μετὰ βραχίονος ὑψηλοῦ, ἐξήγαγεν αὐτοὺς ἐξ αὐτῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 18, 'καί ὡς τεσσερακονταετῆ χρόνον ἐτροποφόρησεν αὐτοὺς ἐν τῇ ἐρήμῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 19, 'καὶ καθελὼν ἔθνη ἑπτὰ ἐν γῇ Χανάαν, κατεκληρονόμησεν τὴν γῆν αὐτῶν–');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 20, 'ὡς ἔτεσι τετρακοσίοις καὶ πεντήκοντα. Καὶ μετὰ ταῦτα, ἔδωκεν κριτὰς ἕως Σαμουὴλ προφήτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 21, 'Κἀκεῖθεν ᾐτήσαντο βασιλέα, καὶ ἔδωκεν αὐτοῖς ὁ  ̊Θεὸς τὸν Σαοὺλ, υἱὸν Κείς, ἄνδρα ἐκ φυλῆς Βενιαμίν, ἔτη τεσσεράκοντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 22, 'Καὶ μεταστήσας αὐτὸν, ἤγειρεν τὸν Δαυὶδ αὐτοῖς εἰς βασιλέα, ᾧ καὶ εἶπεν μαρτυρήσας, ‘“Εὗρον Δαυὶδ” τὸν τοῦ Ἰεσσαί, “ἄνδρα κατὰ τὴν καρδίαν μου”, ὃς ποιήσει πάντα τὰ θελήματά μου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 23, 'Τούτου ὁ  ̊Θεὸς ἀπὸ τοῦ σπέρματος κατʼ ἐπαγγελίαν, ἤγαγεν τῷ Ἰσραὴλ Σωτῆρα,  ̊Ἰησοῦν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 24, 'προκηρύξαντος Ἰωάννου πρὸ προσώπου τῆς εἰσόδου αὐτοῦ, βάπτισμα μετανοίας παντὶ τῷ λαῷ Ἰσραήλ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 25, 'Ὡς δὲ ἐπλήρου Ἰωάννης τὸν δρόμον, ἔλεγεν, ‘Τί ἐμὲ ὑπονοεῖτε εἶναι; Οὐκ εἰμὶ ἐγώ, ἀλλʼ ἰδοὺ, ἔρχεται μετʼ ἐμὲ, οὗ οὐκ εἰμὶ ἄξιος τὸ ὑπόδημα τῶν ποδῶν λῦσαι.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 26, '¶Ἄνδρες, ἀδελφοί, υἱοὶ γένους Ἀβραὰμ, καὶ οἱ ἐν ὑμῖν φοβούμενοι τὸν  ̊Θεόν, ἡμῖν ὁ λόγος τῆς σωτηρίας ταύτης ἐξαπεστάλη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 27, 'Οἱ γὰρ κατοικοῦντες ἐν Ἰερουσαλὴμ καὶ οἱ ἄρχοντες αὐτῶν, τοῦτον ἀγνοήσαντες καὶ τὰς φωνὰς τῶν προφητῶν, τὰς κατὰ πᾶν Σάββατον ἀναγινωσκομένας, κρίναντες ἐπλήρωσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 28, 'Καὶ μηδεμίαν αἰτίαν θανάτου εὑρόντες, ᾐτήσαντο Πιλᾶτον ἀναιρεθῆναι αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 29, 'Ὡς δὲ ἐτέλεσαν πάντα τὰ περὶ αὐτοῦ γεγραμμένα, καθελόντες ἀπὸ τοῦ ξύλου, ἔθηκαν εἰς μνημεῖον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 30, 'Ὁ δὲ  ̊Θεὸς ἤγειρεν αὐτὸν ἐκ νεκρῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 31, 'ὃς ὤφθη ἐπὶ ἡμέρας πλείους τοῖς συναναβᾶσιν αὐτῷ ἀπὸ τῆς Γαλιλαίας εἰς Ἰερουσαλήμ, οἵτινες νῦν εἰσὶ μάρτυρες αὐτοῦ πρὸς τὸν λαόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 32, 'Καὶ ἡμεῖς ὑμᾶς εὐαγγελιζόμεθα τὴν πρὸς τοὺς πατέρας ἐπαγγελίαν γενομένην,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 33, 'ὅτι ταύτην ὁ  ̊Θεὸς ἐκπεπλήρωκεν τοῖς τέκνοις ἡμῶν, ἀναστήσας  ̊Ἰησοῦν, ὡς καὶ ἐν τῷ ψαλμῷ γέγραπται τῷ δευτέρῳ, ‘Υἱός μου εἶ σύ, ἐγὼ σήμερον γεγέννηκά σε.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 34, 'Ὅτι δὲ ἀνέστησεν αὐτὸν ἐκ νεκρῶν, μηκέτι μέλλοντα ὑποστρέφειν εἰς διαφθοράν, οὕτως εἴρηκεν, ὅτι ‘Δώσω ὑμῖν τὰ ὅσια Δαυὶδ τὰ πιστά.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 35, 'Διότι καὶ ἐν ἑτέρῳ λέγει, ‘Οὐ δώσεις τὸν Ὅσιόν σου ἰδεῖν διαφθοράν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 36, 'Δαυὶδ μὲν γὰρ ἰδίᾳ γενεᾷ ὑπηρετήσας τῇ τοῦ  ̊Θεοῦ βουλῇ, ἐκοιμήθη καὶ προσετέθη πρὸς τοὺς πατέρας αὐτοῦ, καὶ εἶδεν διαφθοράν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 37, 'Ὃν δὲ ὁ  ̊Θεὸς ἤγειρεν οὐκ εἶδεν διαφθοράν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 38, 'Γνωστὸν οὖν ἔστω ὑμῖν, ἄνδρες, ἀδελφοί, ὅτι διὰ τούτου, ὑμῖν ἄφεσις ἁμαρτιῶν καταγγέλλεται, καὶ ἀπὸ πάντων ὧν οὐκ ἠδυνήθητε ἐν νόμῳ Μωϋσέως δικαιωθῆναι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 39, 'ἐν τούτῳ πᾶς ὁ πιστεύων δικαιοῦται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 40, 'Βλέπετε οὖν, μὴ ἐπέλθῃ τὸ εἰρημένον ἐν τοῖς προφήταις:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 41, '‘Ἴδετε, οἱ καταφρονηταί, καὶ θαυμάσατε καὶ ἀφανίσθητε, ὅτι ἔργον ἐργάζομαι ἐγὼ ἐν ταῖς ἡμέραις ὑμῶν, ἔργον ὃ οὐ μὴ πιστεύσητε, ἐάν τις ἐκδιηγῆται ὑμῖν.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 42, '¶Ἐξιόντων δὲ, αὐτῶν παρεκάλουν εἰς τὸ μεταξὺ Σάββατον λαληθῆναι αὐτοῖς τὰ ῥήματα ταῦτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 43, 'Λυθείσης δὲ τῆς συναγωγῆς, ἠκολούθησαν πολλοὶ τῶν Ἰουδαίων καὶ τῶν σεβομένων προσηλύτων τῷ Παύλῳ καὶ τῷ Βαρναβᾷ, οἵτινες προσλαλοῦντες αὐτοῖς, ἔπειθον αὐτοὺς προσμένειν τῇ χάριτι τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 44, '¶Τῷ δὲ ἐρχομένῳ Σαββάτῳ, σχεδὸν πᾶσα ἡ πόλις συνήχθη ἀκοῦσαι τὸν λόγον τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 45, 'Ἰδόντες δὲ οἱ Ἰουδαῖοι τοὺς ὄχλους, ἐπλήσθησαν ζήλου καὶ ἀντέλεγον τοῖς ὑπὸ Παύλου λαλουμένοις βλασφημοῦντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 46, 'Παρρησιασάμενοί τε, ὁ Παῦλος καὶ ὁ Βαρναβᾶς εἶπαν, “Ὑμῖν ἦν ἀναγκαῖον πρῶτον λαληθῆναι τὸν λόγον τοῦ  ̊Θεοῦ. Ἐπειδὴ δὲ ἀπωθεῖσθε αὐτὸν, καὶ οὐκ ἀξίους κρίνετε ἑαυτοὺς τῆς αἰωνίου ζωῆς, ἰδοὺ, στρεφόμεθα εἰς τὰ ἔθνη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 47, 'Οὕτως γὰρ ἐντέταλται ἡμῖν ὁ  ̊Κύριος, ‘Τέθεικά σε εἰς φῶς ἐθνῶν, τοῦ εἶναί σε εἰς σωτηρίαν ἕως ἐσχάτου τῆς γῆς.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 48, 'Ἀκούοντα δὲ τὰ ἔθνη, ἔχαιρον καὶ ἐδόξαζον τὸν λόγον τοῦ  ̊Κυρίου, καὶ ἐπίστευσαν ὅσοι ἦσαν τεταγμένοι εἰς ζωὴν αἰώνιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 49, 'Διεφέρετο δὲ ὁ λόγος τοῦ  ̊Κυρίου διʼ ὅλης τῆς χώρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 50, 'Οἱ δὲ Ἰουδαῖοι παρώτρυναν τὰς σεβομένας γυναῖκας τὰς εὐσχήμονας, καὶ τοὺς πρώτους τῆς πόλεως, καὶ ἐπήγειραν διωγμὸν ἐπὶ τὸν Παῦλον καὶ Βαρναβᾶν, καὶ ἐξέβαλον αὐτοὺς ἀπὸ τῶν ὁρίων αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 51, 'Οἱ δὲ, ἐκτιναξάμενοι τὸν κονιορτὸν τῶν ποδῶν ἐπʼ αὐτοὺς, ἦλθον εἰς Ἰκόνιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 52, 'Οἵ τε μαθηταὶ ἐπληροῦντο χαρᾶς καὶ  ̊Πνεύματος Ἁγίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 1, '¶Ἐγένετο δὲ, ἐν Ἰκονίῳ κατὰ τὸ αὐτὸ εἰσελθεῖν αὐτοὺς εἰς τὴν συναγωγὴν τῶν Ἰουδαίων, καὶ λαλῆσαι οὕτως ὥστε πιστεῦσαι Ἰουδαίων τε καὶ Ἑλλήνων πολὺ πλῆθος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 2, 'Οἱ δὲ ἀπειθήσαντες Ἰουδαῖοι ἐπήγειραν καὶ ἐκάκωσαν τὰς ψυχὰς τῶν ἐθνῶν κατὰ τῶν ἀδελφῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 3, 'Ἱκανὸν μὲν οὖν χρόνον διέτριψαν, παρρησιαζόμενοι ἐπὶ τῷ  ̊Κυρίῳ, τῷ μαρτυροῦντι τῷ λόγῳ τῆς χάριτος αὐτοῦ, διδόντι σημεῖα καὶ τέρατα γίνεσθαι διὰ τῶν χειρῶν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 4, 'Ἐσχίσθη δὲ τὸ πλῆθος τῆς πόλεως, καὶ οἱ μὲν ἦσαν σὺν τοῖς Ἰουδαίοις, οἱ δὲ σὺν τοῖς ἀποστόλοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 5, 'Ὡς δὲ ἐγένετο ὁρμὴ τῶν ἐθνῶν τε καὶ Ἰουδαίων σὺν τοῖς ἄρχουσιν αὐτῶν, ὑβρίσαι καὶ λιθοβολῆσαι αὐτούς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 6, 'συνιδόντες, κατέφυγον εἰς τὰς πόλεις τῆς Λυκαονίας, Λύστραν, καὶ Δέρβην, καὶ τὴν περίχωρον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 7, 'κἀκεῖ εὐαγγελιζόμενοι ἦσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 8, '¶Καί τις ἀνὴρ, ἀδύνατος ἐν Λύστροις τοῖς ποσὶν, ἐκάθητο χωλὸς ἐκ κοιλίας μητρὸς αὐτοῦ, ὃς οὐδέποτε περιεπάτησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 9, 'Οὗτος ἤκουεν τοῦ Παύλου λαλοῦντος, ὃς ἀτενίσας αὐτῷ καὶ ἰδὼν ὅτι ἔχει πίστιν τοῦ σωθῆναι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 10, 'εἶπεν μεγάλῃ φωνῇ, “Ἀνάστηθι ἐπὶ τοὺς πόδας σου ὀρθός!” Καὶ ἥλατο καὶ περιεπάτει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 11, 'Οἵ τε ὄχλοι ἰδόντες ὃ ἐποίησεν Παῦλος, ἐπῆραν τὴν φωνὴν αὐτῶν Λυκαονιστὶ λέγοντες, “Οἱ θεοὶ ὁμοιωθέντες ἀνθρώποις, κατέβησαν πρὸς ἡμᾶς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 12, 'Ἐκάλουν τε τὸν Βαρναβᾶν, “Δία”, τὸν δὲ Παῦλον, “Ἑρμῆν”, ἐπειδὴ αὐτὸς ἦν ὁ ἡγούμενος τοῦ λόγου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 13, 'Ὅ τε ἱερεὺς τοῦ Διὸς, τοῦ ὄντος πρὸ τῆς πόλεως, ταύρους καὶ στέμματα ἐπὶ τοὺς πυλῶνας ἐνέγκας, σὺν τοῖς ὄχλοις ἤθελεν θύειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 14, 'Ἀκούσαντες δὲ οἱ ἀπόστολοι Βαρναβᾶς καὶ Παῦλος, διαρρήξαντες τὰ ἱμάτια ἑαυτῶν, ἐξεπήδησαν εἰς τὸν ὄχλον, κράζοντες');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 15, 'καὶ λέγοντες, “Ἄνδρες, τί ταῦτα ποιεῖτε; Καὶ ἡμεῖς ὁμοιοπαθεῖς ἐσμεν ὑμῖν ἄνθρωποι, εὐαγγελιζόμενοι ὑμᾶς ἀπὸ τούτων τῶν ματαίων ἐπιστρέφειν ἐπὶ  ̊Θεὸν ζῶντα, ‘ὃς ἐποίησεν τὸν οὐρανὸν, καὶ τὴν γῆν, καὶ τὴν θάλασσαν, καὶ πάντα τὰ ἐν αὐτοῖς’.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 16, 'Ὃς ἐν ταῖς παρῳχημέναις γενεαῖς, εἴασεν πάντα τὰ ἔθνη πορεύεσθαι ταῖς ὁδοῖς αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 17, 'Καίτοι οὐκ ἀμάρτυρον αὑτὸν ἀφῆκεν, ἀγαθουργῶν οὐρανόθεν ὑμῖν ὑετοὺς διδοὺς καὶ καιροὺς καρποφόρους, ἐμπιπλῶν τροφῆς καὶ εὐφροσύνης τὰς καρδίας ὑμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 18, 'Καὶ ταῦτα λέγοντες, μόλις κατέπαυσαν τοὺς ὄχλους τοῦ μὴ θύειν αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 19, '¶Ἐπῆλθαν δὲ ἀπὸ Ἀντιοχείας καὶ Ἰκονίου Ἰουδαῖοι, καὶ πείσαντες τοὺς ὄχλους, καὶ λιθάσαντες τὸν Παῦλον, ἔσυρον ἔξω τῆς πόλεως, νομίζοντες αὐτὸν τεθνηκέναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 20, 'Κυκλωσάντων δὲ τῶν μαθητῶν αὐτὸν, ἀναστὰς εἰσῆλθεν εἰς τὴν πόλιν. Καὶ τῇ ἐπαύριον ἐξῆλθεν σὺν τῷ Βαρναβᾷ εἰς Δέρβην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 21, '¶Εὐαγγελισάμενοί τε τὴν πόλιν ἐκείνην, καὶ μαθητεύσαντες ἱκανοὺς, ὑπέστρεψαν εἰς τὴν Λύστραν, καὶ εἰς Ἰκόνιον, καὶ εἰς Ἀντιόχειαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 22, 'ἐπιστηρίζοντες τὰς ψυχὰς τῶν μαθητῶν, παρακαλοῦντες ἐμμένειν τῇ πίστει, καὶ ὅτι διὰ πολλῶν θλίψεων, δεῖ ἡμᾶς εἰσελθεῖν εἰς τὴν Βασιλείαν τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 23, 'Χειροτονήσαντες δὲ αὐτοῖς κατʼ ἐκκλησίαν πρεσβυτέρους, προσευξάμενοι μετὰ νηστειῶν, παρέθεντο αὐτοὺς τῷ  ̊Κυρίῳ εἰς ὃν πεπιστεύκεισαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 24, 'Καὶ διελθόντες τὴν Πισιδίαν, ἦλθον εἰς τὴν Παμφυλίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 25, 'καὶ λαλήσαντες ἐν Πέργῃ τὸν λόγον, κατέβησαν εἰς Ἀττάλειαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 26, 'κἀκεῖθεν ἀπέπλευσαν εἰς Ἀντιόχειαν, ὅθεν ἦσαν παραδεδομένοι τῇ χάριτι τοῦ  ̊Θεοῦ, εἰς τὸ ἔργον ὃ ἐπλήρωσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 27, 'Παραγενόμενοι δὲ καὶ συναγαγόντες τὴν ἐκκλησίαν, ἀνήγγελλον ὅσα ἐποίησεν ὁ  ̊Θεὸς μετʼ αὐτῶν, καὶ ὅτι ἤνοιξεν τοῖς ἔθνεσιν θύραν πίστεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 28, 'Διέτριβον δὲ χρόνον οὐκ ὀλίγον σὺν τοῖς μαθηταῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 1, '¶Καί τινες κατελθόντες ἀπὸ τῆς Ἰουδαίας, ἐδίδασκον τοὺς ἀδελφοὺς, ὅτι “Ἐὰν μὴ περιτμηθῆτε τῷ ἔθει τῷ Μωϋσέως, οὐ δύνασθε σωθῆναι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 2, 'Γενομένης δὲ στάσεως καὶ ζητήσεως οὐκ ὀλίγης τῷ Παύλῳ καὶ τῷ Βαρναβᾷ πρὸς αὐτοὺς, ἔταξαν ἀναβαίνειν Παῦλον καὶ Βαρναβᾶν, καί τινας ἄλλους ἐξ αὐτῶν, πρὸς τοὺς ἀποστόλους καὶ πρεσβυτέρους εἰς Ἰερουσαλὴμ περὶ τοῦ ζητήματος τούτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 3, 'Οἱ μὲν οὖν προπεμφθέντες ὑπὸ τῆς ἐκκλησίας, διήρχοντο τήν τε Φοινίκην καὶ Σαμάρειαν, ἐκδιηγούμενοι τὴν ἐπιστροφὴν τῶν ἐθνῶν, καὶ ἐποίουν χαρὰν μεγάλην πᾶσιν τοῖς ἀδελφοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 4, 'Παραγενόμενοι δὲ εἰς Ἱεροσόλυμα, παρεδέχθησαν ἀπὸ τῆς ἐκκλησίας, καὶ τῶν ἀποστόλων, καὶ τῶν πρεσβυτέρων, ἀνήγγειλάν τε ὅσα ὁ  ̊Θεὸς ἐποίησεν μετʼ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 5, 'Ἐξανέστησαν δέ τινες τῶν ἀπὸ τῆς αἱρέσεως τῶν Φαρισαίων πεπιστευκότες, λέγοντες, ὅτι “Δεῖ περιτέμνειν αὐτοὺς, παραγγέλλειν τε τηρεῖν τὸν νόμον Μωϋσέως.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 6, '¶Συνήχθησάν δὲ οἱ ἀπόστολοι καὶ οἱ πρεσβύτεροι, ἰδεῖν περὶ τοῦ λόγου τούτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 7, 'Πολλῆς δὲ ζητήσεως γενομένης, ἀναστὰς Πέτρος εἶπεν πρὸς αὐτούς, “Ἄνδρες, ἀδελφοί, ὑμεῖς ἐπίστασθε ὅτι ἀφʼ ἡμερῶν ἀρχαίων ἐν ὑμῖν, ἐξελέξατο ὁ  ̊Θεὸς διὰ τοῦ στόματός μου, ἀκοῦσαι τὰ ἔθνη τὸν λόγον τοῦ εὐαγγελίου καὶ πιστεῦσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 8, 'Καὶ ὁ καρδιογνώστης  ̊Θεὸς ἐμαρτύρησεν αὐτοῖς, δοὺς τὸ  ̊Πνεῦμα τὸ Ἅγιον καθὼς καὶ ἡμῖν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 9, 'καὶ οὐδὲν διέκρινεν μεταξὺ ἡμῶν τε καὶ αὐτῶν, τῇ πίστει καθαρίσας τὰς καρδίας αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 10, 'Νῦν οὖν τί πειράζετε τὸν  ̊Θεόν, ἐπιθεῖναι ζυγὸν ἐπὶ τὸν τράχηλον τῶν μαθητῶν, ὃν οὔτε οἱ πατέρες ἡμῶν οὔτε ἡμεῖς ἰσχύσαμεν βαστάσαι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 11, 'Ἀλλὰ διὰ τῆς χάριτος τοῦ  ̊Κυρίου  ̊Ἰησοῦ, πιστεύομεν σωθῆναι καθʼ ὃν τρόπον κἀκεῖνοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 12, '¶Ἐσίγησεν δὲ πᾶν τὸ πλῆθος, καὶ ἤκουον Βαρναβᾶ καὶ Παύλου, ἐξηγουμένων ὅσα ἐποίησεν ὁ  ̊Θεὸς, σημεῖα καὶ τέρατα ἐν τοῖς ἔθνεσιν διʼ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 13, 'Μετὰ δὲ τὸ σιγῆσαι αὐτοὺς, ἀπεκρίθη Ἰάκωβος λέγων, “Ἄνδρες, ἀδελφοί, ἀκούσατέ μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 14, 'Συμεὼν ἐξηγήσατο καθὼς πρῶτον ὁ  ̊Θεὸς ἐπεσκέψατο, λαβεῖν ἐξ ἐθνῶν λαὸν τῷ ὀνόματι αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 15, 'Καὶ τούτῳ συμφωνοῦσιν οἱ λόγοι τῶν προφητῶν καθὼς γέγραπται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 16, '‘“Μετὰ ταῦτα ἀναστρέψω καὶ ἀνοικοδομήσω τὴν σκηνὴν Δαυὶδ τὴν πεπτωκυῖαν, καὶ τὰ κατεστραμμένα αὐτῆς, ἀνοικοδομήσω καὶ ἀνορθώσω αὐτήν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 17, 'ὅπως ἂν ἐκζητήσωσιν οἱ κατάλοιποι τῶν ἀνθρώπων τὸν  ̊Κύριον, καὶ πάντα τὰ ἔθνη, ἐφʼ οὓς ἐπικέκληται τὸ ὄνομά μου ἐπʼ αὐτούς”, λέγει  ̊Κύριος ποιῶν ταῦτα’,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 18, 'γνωστὰ ἀπʼ αἰῶνος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 19, 'Διὸ ἐγὼ κρίνω μὴ παρενοχλεῖν τοῖς ἀπὸ τῶν ἐθνῶν, ἐπιστρέφουσιν ἐπὶ τὸν  ̊Θεόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 20, 'ἀλλὰ ἐπιστεῖλαι αὐτοῖς τοῦ ἀπέχεσθαι τῶν ἀλισγημάτων τῶν εἰδώλων, καὶ τῆς πορνείας, καὶ τοῦ πνικτοῦ, καὶ τοῦ αἵματος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 21, 'Μωϋσῆς γὰρ ἐκ γενεῶν ἀρχαίων κατὰ πόλιν τοὺς κηρύσσοντας αὐτὸν, ἔχει ἐν ταῖς συναγωγαῖς κατὰ πᾶν Σάββατον ἀναγινωσκόμενος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 22, '¶Τότε ἔδοξε τοῖς ἀποστόλοις καὶ τοῖς πρεσβυτέροις σὺν ὅλῃ τῇ ἐκκλησίᾳ, ἐκλεξαμένους ἄνδρας ἐξ αὐτῶν, πέμψαι εἰς Ἀντιόχειαν σὺν τῷ Παύλῳ καὶ Βαρναβᾷ– Ἰούδαν τὸν καλούμενον Βαρσαββᾶν καὶ Σιλᾶν, ἄνδρας ἡγουμένους ἐν τοῖς ἀδελφοῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 23, 'γράψαντες διὰ χειρὸς αὐτῶν, “Οἱ ἀπόστολοι καὶ οἱ πρεσβύτεροι, ἀδελφοὶ, τοῖς κατὰ τὴν Ἀντιόχειαν, καὶ Συρίαν, καὶ Κιλικίαν, ἀδελφοῖς τοῖς ἐξ ἐθνῶν, χαίρειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 24, 'Ἐπειδὴ ἠκούσαμεν ὅτι τινὲς ἐξ ἡμῶν ἐξελθόντες, ἐτάραξαν ὑμᾶς λόγοις ἀνασκευάζοντες τὰς ψυχὰς ὑμῶν, οἷς οὐ διεστειλάμεθα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 25, 'ἔδοξεν ἡμῖν γενομένοις ὁμοθυμαδὸν, ἐκλεξαμένοις ἄνδρας πέμψαι πρὸς ὑμᾶς, σὺν τοῖς ἀγαπητοῖς ἡμῶν Βαρναβᾷ καὶ Παύλῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 26, 'ἀνθρώποις παραδεδωκόσι τὰς ψυχὰς αὐτῶν ὑπὲρ τοῦ ὀνόματος τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 27, 'Ἀπεστάλκαμεν οὖν Ἰούδαν καὶ Σιλᾶν, καὶ αὐτοὺς διὰ λόγου ἀπαγγέλλοντας τὰ αὐτά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 28, 'Ἔδοξεν γὰρ τῷ  ̊Πνεύματι τῷ Ἁγίῳ καὶ ἡμῖν, μηδὲν πλέον ἐπιτίθεσθαι ὑμῖν βάρος, πλὴν τούτων τῶν ἐπάναγκες:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 29, 'ἀπέχεσθαι εἰδωλοθύτων, καὶ αἵματος, καὶ πνικτῶν, καὶ πορνείας· ἐξ ὧν διατηροῦντες ἑαυτοὺς, εὖ πράξετε. Ἔρρωσθε!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 30, '¶Οἱ μὲν οὖν ἀπολυθέντες, κατῆλθον εἰς Ἀντιόχειαν, καὶ συναγαγόντες τὸ πλῆθος, ἐπέδωκαν τὴν ἐπιστολήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 31, 'Ἀναγνόντες δὲ, ἐχάρησαν ἐπὶ τῇ παρακλήσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 32, 'Ἰούδας τε καὶ Σιλᾶς, καὶ αὐτοὶ προφῆται ὄντες, διὰ λόγου πολλοῦ, παρεκάλεσαν τοὺς ἀδελφοὺς καὶ ἐπεστήριξαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 33, 'Ποιήσαντες δὲ χρόνον, ἀπελύθησαν μετʼ εἰρήνης ἀπὸ τῶν ἀδελφῶν, πρὸς τοὺς ἀποστείλαντας αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 34, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 35, 'Παῦλος δὲ καὶ Βαρναβᾶς διέτριβον ἐν Ἀντιοχείᾳ, διδάσκοντες καὶ εὐαγγελιζόμενοι μετὰ καὶ ἑτέρων πολλῶν, τὸν λόγον τοῦ  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 36, '¶Μετὰ δέ τινας ἡμέρας, εἶπεν πρὸς Βαρναβᾶν Παῦλος, “Ἐπιστρέψαντες δὴ ἐπισκεψώμεθα τοὺς ἀδελφοὺς κατὰ πόλιν πᾶσαν, ἐν αἷς κατηγγείλαμεν τὸν λόγον τοῦ  ̊Κυρίου, πῶς ἔχουσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 37, 'Βαρναβᾶς δὲ ἐβούλετο συμπαραλαβεῖν καὶ τὸν Ἰωάννην, τὸν καλούμενον Μᾶρκον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 38, 'Παῦλος δὲ ἠξίου τὸν ἀποστάντα ἀπʼ αὐτῶν ἀπὸ Παμφυλίας καὶ μὴ συνελθόντα αὐτοῖς εἰς τὸ ἔργον, μὴ συμπαραλαμβάνειν τοῦτον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 39, 'Ἐγένετο δὲ παροξυσμὸς, ὥστε ἀποχωρισθῆναι αὐτοὺς ἀπʼ ἀλλήλων, τόν τε Βαρναβᾶν παραλαβόντα τὸν Μᾶρκον, ἐκπλεῦσαι εἰς Κύπρον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 40, 'Παῦλος δὲ ἐπιλεξάμενος Σιλᾶν, ἐξῆλθεν παραδοθεὶς τῇ χάριτι τοῦ  ̊Κυρίου ὑπὸ τῶν ἀδελφῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 41, 'Διήρχετο δὲ τὴν Συρίαν καὶ Κιλικίαν, ἐπιστηρίζων τὰς ἐκκλησίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 1, '¶Κατήντησεν δὲ καὶ εἰς Δέρβην καὶ εἰς Λύστραν. Καὶ ἰδοὺ, μαθητής τις ἦν ἐκεῖ ὀνόματι Τιμόθεος, υἱὸς γυναικὸς Ἰουδαίας πιστῆς, πατρὸς δὲ Ἕλληνος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 2, 'ὃς ἐμαρτυρεῖτο ὑπὸ τῶν ἐν Λύστροις καὶ Ἰκονίῳ ἀδελφῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 3, 'Τοῦτον ἠθέλησεν ὁ Παῦλος σὺν αὐτῷ ἐξελθεῖν, καὶ λαβὼν περιέτεμεν αὐτὸν, διὰ τοὺς Ἰουδαίους τοὺς ὄντας ἐν τοῖς τόποις ἐκείνοις, ᾔδεισαν γὰρ ἅπαντες ὅτι Ἕλλην ὁ πατὴρ αὐτοῦ ὑπῆρχεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 4, 'Ὡς δὲ διεπορεύοντο τὰς πόλεις, παρεδίδοσαν αὐτοῖς φυλάσσειν τὰ δόγματα τὰ κεκριμένα ὑπὸ τῶν ἀποστόλων καὶ πρεσβυτέρων τῶν ἐν Ἱεροσολύμοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 5, 'Αἱ μὲν οὖν ἐκκλησίαι ἐστερεοῦντο τῇ πίστει, καὶ ἐπερίσσευον τῷ ἀριθμῷ καθʼ ἡμέραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 6, '¶Διῆλθον δὲ τὴν Φρυγίαν καὶ Γαλατικὴν χώραν, κωλυθέντες ὑπὸ τοῦ Ἁγίου  ̊Πνεύματος λαλῆσαι τὸν λόγον ἐν τῇ Ἀσίᾳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 7, 'ἐλθόντες δὲ κατὰ τὴν Μυσίαν, ἐπείραζον εἰς τὴν Βιθυνίαν πορευθῆναι, καὶ οὐκ εἴασεν αὐτοὺς τὸ  ̊Πνεῦμα  ̊Ἰησοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 8, 'παρελθόντες δὲ τὴν Μυσίαν, κατέβησαν εἰς Τρῳάδα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 9, 'Καὶ ὅραμα διὰ νυκτὸς τῷ Παύλῳ ὤφθη, ἀνὴρ Μακεδών τις ἦν ἑστὼς καὶ παρακαλῶν αὐτὸν καὶ λέγων, “Διαβὰς εἰς Μακεδονίαν, βοήθησον ἡμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 10, 'Ὡς δὲ τὸ ὅραμα εἶδεν, εὐθέως ἐζητήσαμεν ἐξελθεῖν εἰς Μακεδονίαν, συμβιβάζοντες ὅτι προσκέκληται ἡμᾶς ὁ  ̊Θεὸς εὐαγγελίσασθαι αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 11, '¶Ἀναχθέντες οὖν ἀπὸ Τρῳάδος, εὐθυδρομήσαμεν εἰς Σαμοθρᾴκην, τῇ δὲ ἐπιούσῃ εἰς Νέαν Πόλιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 12, 'κἀκεῖθεν εἰς Φιλίππους, ἥτις ἐστὶν πρώτη τῆς μερίδος Μακεδονίας πόλις, κολωνία. Ἦμεν δὲ ἐν ταύτῃ τῇ πόλει διατρίβοντες ἡμέρας τινάς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 13, 'Τῇ τε ἡμέρᾳ τῶν Σαββάτων, ἐξήλθομεν ἔξω τῆς πύλης παρὰ ποταμὸν, οὗ ἐνομίζομεν προσευχὴν εἶναι, καὶ καθίσαντες ἐλαλοῦμεν ταῖς συνελθούσαις γυναιξίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 14, 'Καί τις γυνὴ ὀνόματι Λυδία, πορφυρόπωλις πόλεως Θυατείρων, σεβομένη τὸν  ̊Θεόν ἤκουεν, ἧς ὁ  ̊Κύριος διήνοιξεν τὴν καρδίαν, προσέχειν τοῖς λαλουμένοις ὑπὸ τοῦ Παύλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 15, 'Ὡς δὲ ἐβαπτίσθη καὶ ὁ οἶκος αὐτῆς, παρεκάλεσεν λέγουσα, “Εἰ κεκρίκατέ με πιστὴν τῷ  ̊Κυρίῳ εἶναι, εἰσελθόντες εἰς τὸν οἶκόν μου, μένετε.” Καὶ παρεβιάσατο ἡμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 16, '¶Ἐγένετο δὲ, πορευομένων ἡμῶν εἰς τὴν προσευχὴν, παιδίσκην τινὰ ἔχουσαν πνεῦμα Πύθωνα, ὑπαντῆσαι ἡμῖν, ἥτις ἐργασίαν πολλὴν παρεῖχεν τοῖς κυρίοις αὐτῆς μαντευομένη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 17, 'Αὕτη κατακολουθοῦσα τῷ Παύλῳ καὶ ἡμῖν ἔκραζεν λέγουσα, “Οὗτοι οἱ ἄνθρωποι δοῦλοι τοῦ  ̊Θεοῦ τοῦ Ὑψίστου εἰσίν, οἵτινες καταγγέλλουσιν ὑμῖν ὁδὸν σωτηρίας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 18, 'Τοῦτο δὲ ἐποίει ἐπὶ πολλὰς ἡμέρας. Διαπονηθεὶς δὲ Παῦλος, καὶ ἐπιστρέψας τῷ Πνεύματι εἶπεν, “Παραγγέλλω σοι ἐν ὀνόματι  ̊Ἰησοῦ  ̊Χριστοῦ ἐξελθεῖν ἀπʼ αὐτῆς.” Καὶ ἐξῆλθεν αὐτῇ τῇ ὥρᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 19, '¶Ἰδόντες δὲ οἱ κύριοι αὐτῆς ὅτι ἐξῆλθεν ἡ ἐλπὶς τῆς ἐργασίας αὐτῶν, ἐπιλαβόμενοι τὸν Παῦλον καὶ τὸν Σιλᾶν, εἵλκυσαν εἰς τὴν ἀγορὰν ἐπὶ τοὺς ἄρχοντας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 20, 'καὶ προσαγαγόντες αὐτοὺς τοῖς στρατηγοῖς, εἶπαν, “Οὗτοι οἱ ἄνθρωποι ἐκταράσσουσιν ἡμῶν τὴν πόλιν, Ἰουδαῖοι ὑπάρχοντες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 21, 'καὶ καταγγέλλουσιν ἔθη ἃ οὐκ ἔξεστιν ἡμῖν παραδέχεσθαι οὐδὲ ποιεῖν, Ῥωμαίοις οὖσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 22, 'Καὶ συνεπέστη ὁ ὄχλος κατʼ αὐτῶν, καὶ οἱ στρατηγοὶ περιρήξαντες αὐτῶν τὰ ἱμάτια, ἐκέλευον ῥαβδίζειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 23, 'Πολλάς τε ἐπιθέντες αὐτοῖς πληγὰς, ἔβαλον εἰς φυλακήν, παραγγείλαντες τῷ δεσμοφύλακι ἀσφαλῶς τηρεῖν αὐτούς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 24, 'ὃς παραγγελίαν τοιαύτην λαβὼν, ἔβαλεν αὐτοὺς εἰς τὴν ἐσωτέραν φυλακὴν, καὶ τοὺς πόδας ἠσφαλίσατο αὐτῶν εἰς τὸ ξύλον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 25, '¶Κατὰ δὲ τὸ μεσονύκτιον, Παῦλος καὶ Σιλᾶς προσευχόμενοι, ὕμνουν τὸν  ̊Θεόν, ἐπηκροῶντο δὲ αὐτῶν οἱ δέσμιοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 26, 'Ἄφνω δὲ σεισμὸς ἐγένετο μέγας, ὥστε σαλευθῆναι τὰ θεμέλια τοῦ δεσμωτηρίου, ἠνεῴχθησαν δὲ παραχρῆμα αἱ θύραι πᾶσαι, καὶ πάντων τὰ δεσμὰ ἀνέθη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 27, 'Ἔξυπνος δὲ γενόμενος ὁ δεσμοφύλαξ, καὶ ἰδὼν ἀνεῳγμένας τὰς θύρας τῆς φυλακῆς, σπασάμενος τὴν μάχαιραν ἤμελλεν ἑαυτὸν ἀναιρεῖν, νομίζων ἐκπεφευγέναι τοὺς δεσμίους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 28, 'Ἐφώνησεν δὲ φωνῇ μεγάλῃ Παῦλος λέγων, “Μηδὲν πράξῃς σεαυτῷ κακόν, ἅπαντες γάρ ἐσμεν ἐνθάδε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 29, 'Αἰτήσας δὲ φῶτα, εἰσεπήδησεν, καὶ ἔντρομος γενόμενος, προσέπεσεν τῷ Παύλῳ καὶ Σιλᾷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 30, 'Καὶ προαγαγὼν αὐτοὺς ἔξω ἔφη, “Κύριοι, τί με δεῖ ποιεῖν, ἵνα σωθῶ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 31, 'Οἱ δὲ εἶπαν, “Πίστευσον ἐπὶ τὸν  ̊Κύριον  ̊Ἰησοῦν καὶ σωθήσῃ, σὺ καὶ ὁ οἶκός σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 32, 'Καὶ ἐλάλησαν αὐτῷ τὸν λόγον τοῦ  ̊Κυρίου, σὺν πᾶσι τοῖς ἐν τῇ οἰκίᾳ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 33, 'Καὶ παραλαβὼν αὐτοὺς ἐν ἐκείνῃ τῇ ὥρᾳ τῆς νυκτὸς, ἔλουσεν ἀπὸ τῶν πληγῶν, καὶ ἐβαπτίσθη, αὐτὸς καὶ οἱ αὐτοῦ ἅπαντες παραχρῆμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 34, 'Ἀναγαγών τε αὐτοὺς εἰς τὸν οἶκον, παρέθηκεν τράπεζαν καὶ ἠγαλλιάσατο πανοικεὶ, πεπιστευκὼς τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 35, '¶Ἡμέρας δὲ γενομένης, ἀπέστειλαν οἱ στρατηγοὶ τοὺς ῥαβδούχους λέγοντες, “Ἀπόλυσον τοὺς ἀνθρώπους ἐκείνους.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 36, 'Ἀπήγγειλεν δὲ ὁ δεσμοφύλαξ τοὺς λόγους πρὸς τὸν Παῦλον: ὅτι “Ἀπέσταλκαν οἱ στρατηγοὶ, ἵνα ἀπολυθῆτε. Νῦν οὖν ἐξελθόντες, πορεύεσθε ἐν εἰρήνῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 37, 'Ὁ δὲ Παῦλος ἔφη πρὸς αὐτούς, “Δείραντες ἡμᾶς δημοσίᾳ, ἀκατακρίτους ἀνθρώπους Ῥωμαίους ὑπάρχοντας, ἔβαλαν εἰς φυλακήν καὶ νῦν λάθρᾳ ἡμᾶς ἐκβάλλουσιν; Οὐ γάρ, ἀλλὰ ἐλθόντες αὐτοὶ, ἡμᾶς ἐξαγαγέτωσαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 38, 'Ἀπήγγειλαν δὲ τοῖς στρατηγοῖς οἱ ῥαβδοῦχοι τὰ ῥήματα ταῦτα. Ἐφοβήθησαν δὲ, ἀκούσαντες ὅτι Ῥωμαῖοί εἰσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 39, 'Καὶ ἐλθόντες, παρεκάλεσαν αὐτούς, καὶ ἐξαγαγόντες, ἠρώτων ἀπελθεῖν Ἀπὸ τῆς πόλεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 40, 'Ἐξελθόντες δὲ ἀπὸ τῆς φυλακῆς, εἰσῆλθον πρὸς τὴν Λυδίαν, καὶ ἰδόντες, παρεκάλεσαν τοὺς ἀδελφοὺς καὶ ἐξῆλθον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 1, '¶Διοδεύσαντες δὲ τὴν Ἀμφίπολιν καὶ τὴν Ἀπολλωνίαν, ἦλθον εἰς Θεσσαλονίκην, ὅπου ἦν συναγωγὴ τῶν Ἰουδαίων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 2, 'Κατὰ δὲ τὸ εἰωθὸς τῷ Παύλῳ, εἰσῆλθεν πρὸς αὐτοὺς, καὶ ἐπὶ Σάββατα τρία, διελέξατο αὐτοῖς ἀπὸ τῶν Γραφῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 3, 'διανοίγων καὶ παρατιθέμενος ὅτι τὸν  ̊Χριστὸν ἔδει παθεῖν, καὶ ἀναστῆναι ἐκ νεκρῶν, καὶ ὅτι “Οὗτός ἐστιν  ̊Χριστὸς,  ̊Ἰησοῦς, ὃν ἐγὼ καταγγέλλω ὑμῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 4, 'Καί τινες ἐξ αὐτῶν ἐπείσθησαν καὶ προσεκληρώθησαν τῷ Παύλῳ καὶ τῷ Σιλᾷ, τῶν τε σεβομένων Ἑλλήνων πλῆθος πολὺ, γυναικῶν τε τῶν πρώτων οὐκ ὀλίγαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 5, 'Ζηλώσαντες δὲ οἱ Ἰουδαῖοι, καὶ προσλαβόμενοι τῶν ἀγοραίων ἄνδρας τινὰς πονηροὺς, καὶ ὀχλοποιήσαντες, ἐθορύβουν τὴν πόλιν, καὶ ἐπιστάντες τῇ οἰκίᾳ Ἰάσονος, ἐζήτουν αὐτοὺς προαγαγεῖν εἰς τὸν δῆμον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 6, 'Μὴ εὑρόντες δὲ αὐτοὺς, ἔσυρον Ἰάσονα καί τινας ἀδελφοὺς ἐπὶ τοὺς πολιτάρχας βοῶντες, ὅτι “Οἱ τὴν οἰκουμένην ἀναστατώσαντες, οὗτοι καὶ ἐνθάδε πάρεισιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 7, 'οὓς ὑποδέδεκται Ἰάσων· καὶ οὗτοι πάντες ἀπέναντι τῶν δογμάτων Καίσαρος πράσσουσι, βασιλέα ἕτερον λέγοντες εἶναι  ̊Ἰησοῦν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 8, 'Ἐτάραξαν δὲ τὸν ὄχλον καὶ τοὺς πολιτάρχας ἀκούοντας ταῦτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 9, 'Καὶ λαβόντες τὸ ἱκανὸν παρὰ τοῦ Ἰάσονος καὶ τῶν λοιπῶν, ἀπέλυσαν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 10, '¶Οἱ δὲ ἀδελφοὶ εὐθέως διὰ νυκτὸς ἐξέπεμψαν τόν τε Παῦλον καὶ τὸν Σιλᾶν εἰς Βέροιαν, οἵτινες παραγενόμενοι, εἰς τὴν συναγωγὴν τῶν Ἰουδαίων ἀπῄεσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 11, 'Οὗτοι δὲ ἦσαν εὐγενέστεροι τῶν ἐν Θεσσαλονίκῃ, οἵτινες ἐδέξαντο τὸν λόγον μετὰ πάσης προθυμίας, καθʼ ἡμέραν ἀνακρίνοντες τὰς Γραφὰς, εἰ ἔχοι ταῦτα οὕτως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 12, 'Πολλοὶ μὲν οὖν ἐξ αὐτῶν ἐπίστευσαν, καὶ τῶν Ἑλληνίδων γυναικῶν τῶν εὐσχημόνων, καὶ ἀνδρῶν οὐκ ὀλίγοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 13, 'Ὡς δὲ ἔγνωσαν οἱ ἀπὸ τῆς Θεσσαλονίκης Ἰουδαῖοι ὅτι καὶ ἐν τῇ Βεροίᾳ κατηγγέλη ὑπὸ τοῦ Παύλου ὁ λόγος τοῦ  ̊Θεοῦ, ἦλθον κἀκεῖ, σαλεύοντες καὶ ταράσσοντες τοὺς ὄχλους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 14, 'Εὐθέως δὲ τότε τὸν Παῦλον ἐξαπέστειλαν οἱ ἀδελφοὶ, πορεύεσθαι ἕως ἐπὶ τὴν θάλασσαν· ὑπέμεινάν τε ὅ τε Σιλᾶς καὶ ὁ Τιμόθεος ἐκεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 15, 'Οἱ δὲ καθιστάνοντες τὸν Παῦλον, ἤγαγον ἕως Ἀθηνῶν, καὶ λαβόντες ἐντολὴν πρὸς τὸν Σιλᾶν καὶ τὸν Τιμόθεον, ἵνα ὡς τάχιστα ἔλθωσιν πρὸς αὐτὸν, ἐξῄεσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 16, '¶Ἐν δὲ ταῖς Ἀθήναις, ἐκδεχομένου αὐτοὺς τοῦ Παύλου, παρωξύνετο τὸ πνεῦμα αὐτοῦ ἐν αὐτῷ, θεωροῦντος κατείδωλον οὖσαν τὴν πόλιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 17, 'Διελέγετο μὲν οὖν ἐν τῇ συναγωγῇ τοῖς Ἰουδαίοις, καὶ τοῖς σεβομένοις, καὶ ἐν τῇ ἀγορᾷ κατὰ πᾶσαν ἡμέραν πρὸς τοὺς παρατυγχάνοντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 18, 'Τινὲς δὲ καὶ τῶν Ἐπικουρείων καὶ Στοϊκῶν φιλοσόφων συνέβαλλον αὐτῷ, καί τινες ἔλεγον, “Τί ἂν θέλοι ὁ σπερμολόγος οὗτος λέγειν;” Οἱ δέ, “Ξένων δαιμονίων δοκεῖ καταγγελεὺς εἶναι”· ὅτι τὸν  ̊Ἰησοῦν καὶ τὴν ἀνάστασιν εὐηγγελίζετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 19, 'Ἐπιλαβόμενοι δὲ αὐτοῦ, ἐπὶ τὸν Ἄρειον Πάγον ἤγαγον λέγοντες, “Δυνάμεθα γνῶναι τίς ἡ καινὴ αὕτη, ἡ ὑπὸ σοῦ λαλουμένη διδαχή;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 20, 'Ξενίζοντα γάρ τινα εἰσφέρεις εἰς τὰς ἀκοὰς ἡμῶν. Βουλόμεθα οὖν γνῶναι τίνα θέλει ταῦτα εἶναι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 21, '(Ἀθηναῖοι δὲ πάντες καὶ οἱ ἐπιδημοῦντες ξένοι εἰς οὐδὲν ἕτερον ηὐκαίρουν, ἢ λέγειν τι ἢ ἀκούειν τι καινότερον.)');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 22, '¶Σταθεὶς δὲ Παῦλος ἐν μέσῳ τοῦ Ἀρείου Πάγου ἔφη, “Ἄνδρες, Ἀθηναῖοι, κατὰ πάντα ὡς δεισιδαιμονεστέρους ὑμᾶς θεωρῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 23, 'Διερχόμενος γὰρ καὶ ἀναθεωρῶν τὰ σεβάσματα ὑμῶν, εὗρον καὶ βωμὸν ἐν ᾧ ἐπεγέγραπτο, ‘Ἀγνώστῳ  ̊Θεῷ.’ Ὃ οὖν ἀγνοοῦντες εὐσεβεῖτε, τοῦτο ἐγὼ καταγγέλλω ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 24, 'Ὁ  ̊Θεὸς ὁ ποιήσας τὸν κόσμον καὶ πάντα τὰ ἐν αὐτῷ, οὗτος οὐρανοῦ καὶ γῆς ὑπάρχων  ̊Κύριος, οὐκ ἐν χειροποιήτοις ναοῖς κατοικεῖ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 25, 'οὐδὲ ὑπὸ χειρῶν ἀνθρωπίνων θεραπεύεται, προσδεόμενός τινος, αὐτὸς διδοὺς πᾶσι ζωὴν, καὶ πνοὴν, καὶ τὰ πάντα·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 26, 'ἐποίησέν τε ἐξ ἑνὸς, πᾶν ἔθνος ἀνθρώπων κατοικεῖν ἐπὶ παντὸς προσώπου τῆς γῆς, ὁρίσας προστεταγμένους καιροὺς καὶ τὰς ὁροθεσίας τῆς κατοικίας αὐτῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 27, 'ζητεῖν τὸν  ̊Θεὸν, εἰ ἄρα γε ψηλαφήσειαν αὐτὸν καὶ εὕροιεν, καί γε οὐ μακρὰν ἀπὸ ἑνὸς ἑκάστου ἡμῶν ὑπάρχοντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 28, 'Ἐν αὐτῷ γὰρ ζῶμεν καὶ κινούμεθα καὶ ἐσμέν, ὡς καί τινες τῶν καθʼ ὑμᾶς ποιητῶν εἰρήκασιν, ‘Τοῦ γὰρ καὶ γένος ἐσμέν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 29, 'Γένος οὖν ὑπάρχοντες τοῦ  ̊Θεοῦ, οὐκ ὀφείλομεν νομίζειν χρυσῷ ἢ ἀργύρῳ ἢ λίθῳ χαράγματι τέχνης καὶ ἐνθυμήσεως ἀνθρώπου, τὸ θεῖον εἶναι ὅμοιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 30, 'Τοὺς μὲν οὖν χρόνους τῆς ἀγνοίας ὑπεριδὼν ὁ  ̊Θεὸς, τὰ νῦν ἀπαγγέλλει τοῖς ἀνθρώποις πάντας πανταχοῦ μετανοεῖν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 31, 'καθότι ἔστησεν ἡμέραν ἐν ᾗ μέλλει κρίνειν τὴν οἰκουμένην ἐν δικαιοσύνῃ, ἐν ἀνδρὶ ᾧ ὥρισεν, πίστιν παρασχὼν πᾶσιν, ἀναστήσας αὐτὸν ἐκ νεκρῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 32, '¶Ἀκούσαντες δὲ ἀνάστασιν νεκρῶν, οἱ μὲν ἐχλεύαζον, οἱ δὲ εἶπαν, “Ἀκουσόμεθά σου περὶ τούτου καὶ πάλιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 33, 'Οὕτως ὁ Παῦλος ἐξῆλθεν ἐκ μέσου αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 17, 34, 'Τινὲς δὲ ἄνδρες κολληθέντες αὐτῷ, ἐπίστευσαν ἐν οἷς καὶ Διονύσιος ὁ Ἀρεοπαγίτης, καὶ γυνὴ ὀνόματι Δάμαρις, καὶ ἕτεροι σὺν αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 1, '¶Μετὰ ταῦτα, χωρισθεὶς ἐκ τῶν Ἀθηνῶν, ἦλθεν εἰς Κόρινθον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 2, 'Καὶ εὑρών τινα Ἰουδαῖον ὀνόματι Ἀκύλαν, Ποντικὸν τῷ γένει, προσφάτως ἐληλυθότα ἀπὸ τῆς Ἰταλίας, καὶ Πρίσκιλλαν γυναῖκα αὐτοῦ, διὰ τὸ διατεταχέναι Κλαύδιον χωρίζεσθαι πάντας τοὺς Ἰουδαίους ἀπὸ τῆς Ῥώμης, προσῆλθεν αὐτοῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 3, 'καὶ διὰ τὸ ὁμότεχνον εἶναι, ἔμενεν παρʼ αὐτοῖς καὶ ἠργάζοντο, ἦσαν γὰρ σκηνοποιοὶ τῇ τέχνῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 4, 'Διελέγετο δὲ ἐν τῇ συναγωγῇ κατὰ πᾶν Σάββατον, ἔπειθέν τε Ἰουδαίους καὶ Ἕλληνας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 5, '¶Ὡς δὲ κατῆλθον ἀπὸ τῆς Μακεδονίας ὅ τε Σιλᾶς καὶ ὁ Τιμόθεος, συνείχετο τῷ λόγῳ ὁ Παῦλος, διαμαρτυρόμενος τοῖς Ἰουδαίοις, εἶναι τὸν  ̊Χριστὸν,  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 6, 'Ἀντιτασσομένων δὲ αὐτῶν καὶ βλασφημούντων, ἐκτιναξάμενος τὰ ἱμάτια, εἶπεν πρὸς αὐτούς, “Τὸ αἷμα ὑμῶν ἐπὶ τὴν κεφαλὴν ὑμῶν· καθαρὸς ἐγώ. Ἀπὸ τοῦ νῦν, εἰς τὰ ἔθνη πορεύσομαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 7, 'Καὶ μεταβὰς ἐκεῖθεν, εἰσῆλθεν εἰς οἰκίαν τινὸς ὀνόματι Τιτίου Ἰούστου, σεβομένου τὸν  ̊Θεόν, οὗ ἡ οἰκία ἦν συνομοροῦσα τῇ συναγωγῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 8, 'Κρίσπος δὲ ὁ ἀρχισυνάγωγος, ἐπίστευσεν τῷ  ̊Κυρίῳ σὺν ὅλῳ τῷ οἴκῳ αὐτοῦ, καὶ πολλοὶ τῶν Κορινθίων ἀκούοντες, ἐπίστευον καὶ ἐβαπτίζοντο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 9, 'Εἶπεν δὲ ὁ  ̊Κύριος ἐν νυκτὶ διʼ ὁράματος τῷ Παύλῳ, “Μὴ φοβοῦ, ἀλλὰ λάλει καὶ μὴ σιωπήσῃς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 10, 'διότι ἐγώ εἰμι μετὰ σοῦ, καὶ οὐδεὶς ἐπιθήσεταί σοι τοῦ κακῶσαί σε, διότι λαός ἐστί μοι πολὺς ἐν τῇ πόλει ταύτῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 11, 'Ἐκάθισεν δὲ ἐνιαυτὸν καὶ μῆνας ἓξ, διδάσκων ἐν αὐτοῖς τὸν λόγον τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 12, '¶Γαλλίωνος δὲ ἀνθυπάτου ὄντος τῆς Ἀχαΐας, κατεπέστησαν ὁμοθυμαδὸν οἱ Ἰουδαῖοι τῷ Παύλῳ, καὶ ἤγαγον αὐτὸν ἐπὶ τὸ βῆμα');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 13, 'λέγοντες, ὅτι “Παρὰ τὸν νόμον, ἀναπείθει οὗτος τοὺς ἀνθρώπους σέβεσθαι τὸν  ̊Θεόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 14, 'Μέλλοντος δὲ τοῦ Παύλου ἀνοίγειν τὸ στόμα, εἶπεν ὁ Γαλλίων πρὸς τοὺς Ἰουδαίους, “Εἰ μὲν ἦν ἀδίκημά τι ἢ ῥᾳδιούργημα πονηρόν, ὦ Ἰουδαῖοι, κατὰ λόγον ἂν ἀνεσχόμην ὑμῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 15, 'εἰ δὲ ζητήματά ἐστιν περὶ λόγου, καὶ ὀνομάτων, καὶ νόμου, τοῦ καθʼ ὑμᾶς, ὄψεσθε αὐτοί· κριτὴς ἐγὼ τούτων οὐ βούλομαι εἶναι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 16, 'Καὶ ἀπήλασεν αὐτοὺς ἀπὸ τοῦ βήματος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 17, 'Ἐπιλαβόμενοι δὲ πάντες Σωσθένην τὸν ἀρχισυνάγωγον, ἔτυπτον ἔμπροσθεν τοῦ βήματος. Καὶ οὐδὲν τούτων τῷ Γαλλίωνι ἔμελεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 18, '¶Ὁ δὲ Παῦλος ἔτι προσμείνας ἡμέρας ἱκανὰς, τοῖς ἀδελφοῖς ἀποταξάμενος, ἐξέπλει εἰς τὴν Συρίαν, καὶ σὺν αὐτῷ Πρίσκιλλα καὶ Ἀκύλας, κειράμενος ἐν Κεγχρεαῖς τὴν κεφαλήν, εἶχεν γὰρ εὐχήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 19, 'Κατήντησαν δὲ εἰς Ἔφεσον, κἀκείνους κατέλιπεν αὐτοῦ, αὐτὸς δὲ εἰσελθὼν εἰς τὴν συναγωγὴν, διελέξατο τοῖς Ἰουδαίοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 20, 'Ἐρωτώντων δὲ αὐτῶν ἐπὶ πλείονα χρόνον μεῖναι, οὐκ ἐπένευσεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 21, 'ἀλλὰ ἀποταξάμενος καὶ εἰπών, “Πάλιν ἀνακάμψω πρὸς ὑμᾶς, τοῦ  ̊Θεοῦ θέλοντος”, ἀνήχθη ἀπὸ τῆς Ἐφέσου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 22, 'Καὶ κατελθὼν εἰς Καισάρειαν, ἀναβὰς καὶ ἀσπασάμενος τὴν ἐκκλησίαν, κατέβη εἰς Ἀντιόχειαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 23, 'Καὶ ποιήσας χρόνον τινὰ, ἐξῆλθεν διερχόμενος καθεξῆς τὴν Γαλατικὴν χώραν καὶ Φρυγίαν, στηρίζων πάντας τοὺς μαθητάς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 24, '¶Ἰουδαῖος δέ τις Ἀπολλῶς ὀνόματι Ἀλεξανδρεὺς τῷ γένει, ἀνὴρ λόγιος, κατήντησεν εἰς Ἔφεσον, δυνατὸς ὢν ἐν ταῖς Γραφαῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 25, 'Οὗτος ἦν κατηχημένος τὴν ὁδὸν τοῦ  ̊Κυρίου, καὶ ζέων τῷ πνεύματι, ἐλάλει καὶ ἐδίδασκεν ἀκριβῶς τὰ περὶ τοῦ  ̊Ἰησοῦ, ἐπιστάμενος μόνον τὸ βάπτισμα Ἰωάννου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 26, 'Οὗτός τε ἤρξατο παρρησιάζεσθαι ἐν τῇ συναγωγῇ. Ἀκούσαντες δὲ αὐτοῦ, Πρίσκιλλα καὶ Ἀκύλας προσελάβοντο αὐτὸν, καὶ ἀκριβέστερον αὐτῷ ἐξέθεντο τὴν ὁδὸν τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 27, 'Βουλομένου δὲ αὐτοῦ διελθεῖν εἰς τὴν Ἀχαΐαν, προτρεψάμενοι, οἱ ἀδελφοὶ ἔγραψαν τοῖς μαθηταῖς ἀποδέξασθαι αὐτόν, ὃς παραγενόμενος, συνεβάλετο πολὺ τοῖς πεπιστευκόσιν διὰ τῆς χάριτος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 18, 28, 'Εὐτόνως γὰρ τοῖς Ἰουδαίοις διακατηλέγχετο δημοσίᾳ, ἐπιδεικνὺς διὰ τῶν Γραφῶν εἶναι τὸν  ̊Χριστὸν,  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 1, '¶Ἐγένετο δὲ ἐν τῷ, τὸν Ἀπολλῶ εἶναι ἐν Κορίνθῳ, Παῦλον διελθόντα τὰ ἀνωτερικὰ μέρη, κατελθεῖν εἰς Ἔφεσον καὶ εὑρεῖν τινας μαθητάς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 2, 'εἶπέν τε πρὸς αὐτούς, “Εἰ  ̊Πνεῦμα Ἅγιον ἐλάβετε, πιστεύσαντες;” Οἱ δὲ πρὸς αὐτόν, “Ἀλλʼ οὐδʼ εἰ  ̊Πνεῦμα Ἅγιον ἔστιν ἠκούσαμεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 3, 'Εἶπέν τε, “Εἰς τί οὖν ἐβαπτίσθητε;” Οἱ δὲ εἶπαν, “Εἰς τὸ Ἰωάννου βάπτισμα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 4, 'Εἶπεν δὲ Παῦλος, “Ἰωάννης ἐβάπτισεν βάπτισμα μετανοίας, τῷ λαῷ λέγων εἰς τὸν ἐρχόμενον μετʼ αὐτὸν ἵνα πιστεύσωσιν τοῦτʼ ἔστιν εἰς τὸν  ̊Ἰησοῦν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 5, 'Ἀκούσαντες δὲ, ἐβαπτίσθησαν εἰς τὸ ὄνομα τοῦ  ̊Κυρίου  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 6, 'Καὶ ἐπιθέντος αὐτοῖς τοῦ Παύλου χεῖρας, ἦλθε τὸ  ̊Πνεῦμα τὸ Ἅγιον ἐπʼ αὐτούς, ἐλάλουν τε γλώσσαις καὶ ἐπροφήτευον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 7, 'Ἦσαν δὲ οἱ πάντες ἄνδρες ὡσεὶ δώδεκα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 8, '¶Εἰσελθὼν δὲ εἰς τὴν συναγωγὴν, ἐπαρρησιάζετο ἐπὶ μῆνας τρεῖς, διαλεγόμενος καὶ πείθων περὶ τῆς Βασιλείας τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 9, 'Ὡς δέ τινες ἐσκληρύνοντο καὶ ἠπείθουν, κακολογοῦντες τὴν ὁδὸν ἐνώπιον τοῦ πλήθους, ἀποστὰς ἀπʼ αὐτῶν ἀφώρισεν τοὺς μαθητάς, καθʼ ἡμέραν διαλεγόμενος ἐν τῇ σχολῇ Τυράννου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 10, 'Τοῦτο δὲ ἐγένετο ἐπὶ ἔτη δύο, ὥστε πάντας τοὺς κατοικοῦντας τὴν Ἀσίαν ἀκοῦσαι τὸν λόγον τοῦ  ̊Κυρίου, Ἰουδαίους τε καὶ Ἕλληνας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 11, '¶Δυνάμεις τε οὐ τὰς τυχούσας, ὁ  ̊Θεὸς ἐποίει διὰ τῶν χειρῶν Παύλου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 12, 'ὥστε καὶ ἐπὶ τοὺς ἀσθενοῦντας ἀποφέρεσθαι ἀπὸ τοῦ χρωτὸς αὐτοῦ σουδάρια ἢ σιμικίνθια, καὶ ἀπαλλάσσεσθαι ἀπʼ αὐτῶν τὰς νόσους, τά τε πνεύματα τὰ πονηρὰ ἐκπορεύεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 13, 'Ἐπεχείρησαν δέ τινες καὶ τῶν περιερχομένων Ἰουδαίων ἐξορκιστῶν ὀνομάζειν ἐπὶ τοὺς ἔχοντας τὰ πνεύματα τὰ πονηρὰ τὸ ὄνομα τοῦ  ̊Κυρίου  ̊Ἰησοῦ λέγοντες, “Ὁρκίζω ὑμᾶς, τὸν  ̊Ἰησοῦν, ὃν Παῦλος κηρύσσει.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 14, 'Ἦσαν δέ τινος Σκευᾶ Ἰουδαίου ἀρχιερέως ἑπτὰ υἱοὶ τοῦτο ποιοῦντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 15, 'Ἀποκριθὲν δὲ τὸ πνεῦμα τὸ πονηρὸν εἶπεν αὐτοῖς, “Τὸν  ̊Ἰησοῦν γινώσκω, καὶ τὸν Παῦλον ἐπίσταμαι, ὑμεῖς δὲ τίνες ἐστέ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 16, 'Καὶ ἐφαλόμενος ὁ ἄνθρωπος ἐπʼ αὐτοὺς, ἐν ᾧ ἦν τὸ πνεῦμα τὸ πονηρὸν, κατακυριεύσας ἀμφοτέρων, ἴσχυσεν κατʼ αὐτῶν, ὥστε γυμνοὺς καὶ τετραυματισμένους ἐκφυγεῖν ἐκ τοῦ οἴκου ἐκείνου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 17, 'Τοῦτο δὲ ἐγένετο γνωστὸν πᾶσιν, Ἰουδαίοις τε καὶ Ἕλλησιν, τοῖς κατοικοῦσιν τὴν Ἔφεσον, καὶ ἐπέπεσεν φόβος ἐπὶ πάντας αὐτούς, καὶ ἐμεγαλύνετο τὸ ὄνομα τοῦ  ̊Κυρίου  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 18, 'Πολλοί τε τῶν πεπιστευκότων, ἤρχοντο ἐξομολογούμενοι καὶ ἀναγγέλλοντες τὰς πράξεις αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 19, 'Ἱκανοὶ δὲ τῶν τὰ περίεργα πραξάντων, συνενέγκαντες τὰς βίβλους, κατέκαιον ἐνώπιον πάντων. Καὶ συνεψήφισαν τὰς τιμὰς αὐτῶν, καὶ εὗρον ἀργυρίου μυριάδας πέντε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 20, 'Οὕτως κατὰ κράτος τοῦ  ̊Κυρίου ὁ λόγος ηὔξανεν καὶ ἴσχυεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 21, '¶Ὡς δὲ ἐπληρώθη ταῦτα, ἔθετο ὁ Παῦλος ἐν τῷ  ̊Πνεύματι, διελθὼν τὴν Μακεδονίαν καὶ Ἀχαΐαν, πορεύεσθαι εἰς Ἱεροσόλυμα εἰπὼν, ὅτι “Μετὰ τὸ γενέσθαι με ἐκεῖ, δεῖ με καὶ Ῥώμην ἰδεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 22, 'Ἀποστείλας δὲ εἰς τὴν Μακεδονίαν, δύο τῶν διακονούντων αὐτῷ, Τιμόθεον καὶ Ἔραστον, αὐτὸς ἐπέσχεν χρόνον εἰς τὴν Ἀσίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 23, '¶Ἐγένετο δὲ κατὰ τὸν καιρὸν ἐκεῖνον, τάραχος οὐκ ὀλίγος περὶ τῆς ὁδοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 24, 'Δημήτριος γάρ τις ὀνόματι ἀργυροκόπος, ποιῶν ναοὺς ἀργυροῦς Ἀρτέμιδος, παρείχετο τοῖς τεχνίταις οὐκ ὀλίγην ἐργασίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 25, 'οὓς συναθροίσας καὶ τοὺς περὶ τὰ τοιαῦτα ἐργάτας, εἶπεν, “Ἄνδρες, ἐπίστασθε ὅτι ἐκ ταύτης τῆς ἐργασίας ἡ εὐπορία ἡμῖν ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 26, 'Καὶ θεωρεῖτε καὶ ἀκούετε ὅτι οὐ μόνον Ἐφέσου, ἀλλὰ σχεδὸν πάσης τῆς Ἀσίας, ὁ Παῦλος οὗτος πείσας, μετέστησεν ἱκανὸν ὄχλον, λέγων ὅτι οὐκ εἰσὶν θεοὶ, οἱ διὰ χειρῶν γινόμενοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 27, 'Οὐ μόνον δὲ τοῦτο κινδυνεύει ἡμῖν, τὸ μέρος εἰς ἀπελεγμὸν ἐλθεῖν, ἀλλὰ καὶ τὸ τῆς μεγάλης θεᾶς Ἀρτέμιδος ἱερὸν, εἰς οὐθὲν λογισθῆναι, μέλλειν τε καὶ καθαιρεῖσθαι τῆς μεγαλειότητος αὐτῆς, ἣν ὅλη ἡ Ἀσία καὶ ἡ οἰκουμένη σέβεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 28, '¶Ἀκούσαντες δὲ, καὶ γενόμενοι πλήρεις θυμοῦ, ἔκραζον λέγοντες, “Μεγάλη ἡ Ἄρτεμις Ἐφεσίων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 29, 'Καὶ ἐπλήσθη ἡ πόλις τῆς συγχύσεως, ὥρμησάν τε ὁμοθυμαδὸν εἰς τὸ θέατρον, συναρπάσαντες Γάϊον καὶ Ἀρίσταρχον Μακεδόνας, συνεκδήμους Παύλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 30, 'Παύλου δὲ βουλομένου εἰσελθεῖν εἰς τὸν δῆμον, οὐκ εἴων αὐτὸν οἱ μαθηταί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 31, 'Τινὲς δὲ καὶ τῶν Ἀσιαρχῶν, ὄντες αὐτῷ φίλοι, πέμψαντες πρὸς αὐτὸν, παρεκάλουν μὴ δοῦναι ἑαυτὸν εἰς τὸ θέατρον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 32, 'Ἄλλοι μὲν οὖν ἄλλο τι ἔκραζον, ἦν γὰρ ἡ ἐκκλησία συγκεχυμένη, καὶ οἱ πλείους οὐκ ᾔδεισαν τίνος ἕνεκα συνεληλύθεισαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 33, 'Ἐκ δὲ τοῦ ὄχλου συνεβίβασαν Ἀλέξανδρον, προβαλόντων αὐτὸν τῶν Ἰουδαίων. Ὁ δὲ Ἀλέξανδρος κατασείσας τὴν χεῖρα, ἤθελεν ἀπολογεῖσθαι τῷ δήμῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 34, 'Ἐπιγνόντες δὲ ὅτι Ἰουδαῖός ἐστιν, φωνὴ ἐγένετο μία ἐκ πάντων, ὡς ἐπὶ ὥρας δύο κραζόντων, “Μεγάλη ἡ Ἄρτεμις Ἐφεσίων!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 35, 'Καταστείλας δὲ ὁ γραμματεὺς τὸν ὄχλον φησίν, “Ἄνδρες, Ἐφέσιοι, τίς γάρ ἐστιν ἀνθρώπων, ὃς οὐ γινώσκει τὴν Ἐφεσίων πόλιν νεωκόρον οὖσαν τῆς μεγάλης Ἀρτέμιδος καὶ τοῦ διοπετοῦς;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 36, 'Ἀναντιρρήτων οὖν ὄντων τούτων, δέον ἐστὶν ὑμᾶς κατεσταλμένους ὑπάρχειν, καὶ μηδὲν προπετὲς πράσσειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 37, 'Ἠγάγετε γὰρ τοὺς ἄνδρας τούτους, οὔτε ἱεροσύλους οὔτε βλασφημοῦντας τὴν θεὸν ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 38, 'Εἰ μὲν οὖν Δημήτριος καὶ οἱ σὺν αὐτῷ τεχνῖται ἔχουσιν πρός τινα λόγον, ἀγοραῖοι ἄγονται καὶ ἀνθύπατοί εἰσιν, ἐγκαλείτωσαν ἀλλήλοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 39, 'Εἰ δέ τι περὶ ἑτέρων ἐπιζητεῖτε, ἐν τῇ ἐννόμῳ ἐκκλησίᾳ ἐπιλυθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 40, 'Καὶ γὰρ κινδυνεύομεν ἐγκαλεῖσθαι στάσεως περὶ τῆς σήμερον, μηδενὸς αἰτίου ὑπάρχοντος, περὶ οὗ οὐ δυνησόμεθα ἀποδοῦναι λόγον περὶ τῆς συστροφῆς ταύτης.” Καὶ ταῦτα εἰπὼν, ἀπέλυσεν τὴν ἐκκλησίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 19, 41, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 1, '¶Μετὰ δὲ τὸ παύσασθαι τὸν θόρυβον, μεταπεμψάμενος ὁ Παῦλος τοὺς μαθητὰς καὶ παρακαλέσας ἀσπασάμενος, ἐξῆλθεν πορεύεσθαι εἰς Μακεδονίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 2, 'Διελθὼν δὲ τὰ μέρη ἐκεῖνα, καὶ παρακαλέσας αὐτοὺς λόγῳ πολλῷ, ἦλθεν εἰς τὴν Ἑλλάδα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 3, 'Ποιήσας τε μῆνας τρεῖς, γενομένης ἐπιβουλῆς αὐτῷ ὑπὸ τῶν Ἰουδαίων, μέλλοντι ἀνάγεσθαι εἰς τὴν Συρίαν, ἐγένετο γνώμης τοῦ ὑποστρέφειν διὰ Μακεδονίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 4, 'Συνείπετο δὲ αὐτῷ Σώπατρος Πύρρου Βεροιαῖος, Θεσσαλονικέων δὲ Ἀρίσταρχος καὶ Σεκοῦνδος, καὶ Γάϊος Δερβαῖος, καὶ Τιμόθεος, Ἀσιανοὶ δὲ Τυχικὸς καὶ Τρόφιμος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 5, 'Οὗτοι δὲ προσελθόντες ἔμενον ἡμᾶς ἐν Τρῳάδι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 6, 'Ἡμεῖς δὲ ἐξεπλεύσαμεν μετὰ τὰς ἡμέρας τῶν Ἀζύμων ἀπὸ Φιλίππων, καὶ ἤλθομεν πρὸς αὐτοὺς εἰς τὴν Τρῳάδα ἄχρι ἡμερῶν πέντε, ὅπου διετρίψαμεν ἡμέρας ἑπτά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 7, '¶Ἐν δὲ τῇ μιᾷ τῶν σαββάτων, συνηγμένων ἡμῶν κλάσαι ἄρτον, ὁ Παῦλος διελέγετο αὐτοῖς, μέλλων ἐξιέναι τῇ ἐπαύριον, παρέτεινέν τε τὸν λόγον μέχρι μεσονυκτίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 8, 'Ἦσαν δὲ λαμπάδες ἱκαναὶ ἐν τῷ ὑπερῴῳ, οὗ ἦμεν συνηγμένοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 9, 'Καθεζόμενος δέ τις νεανίας ὀνόματι Εὔτυχος ἐπὶ τῆς θυρίδος, καταφερόμενος ὕπνῳ βαθεῖ, διαλεγομένου τοῦ Παύλου ἐπὶ πλεῖον, κατενεχθεὶς ἀπὸ τοῦ ὕπνου, ἔπεσεν ἀπὸ τοῦ τριστέγου κάτω, καὶ ἤρθη νεκρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 10, 'Καταβὰς δὲ, ὁ Παῦλος ἐπέπεσεν αὐτῷ καὶ συμπεριλαβὼν εἶπεν, “Μὴ θορυβεῖσθε, ἡ γὰρ ψυχὴ αὐτοῦ ἐν αὐτῷ ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 11, 'Ἀναβὰς δὲ, καὶ κλάσας τὸν ἄρτον καὶ γευσάμενος, ἐφʼ ἱκανόν τε ὁμιλήσας ἄχρι αὐγῆς, οὕτως ἐξῆλθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 12, 'Ἤγαγον δὲ τὸν παῖδα ζῶντα, καὶ παρεκλήθησαν οὐ μετρίως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 13, '¶Ἡμεῖς δὲ, προσελθόντες ἐπὶ τὸ πλοῖον, ἀνήχθημεν ἐπὶ τὴν Ἆσσον, ἐκεῖθεν μέλλοντες ἀναλαμβάνειν τὸν Παῦλον, οὕτως γὰρ διατεταγμένος, ἦν μέλλων αὐτὸς πεζεύειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 14, 'Ὡς δὲ συνέβαλλεν ἡμῖν εἰς τὴν Ἆσσον, ἀναλαβόντες αὐτὸν, ἤλθομεν εἰς Μιτυλήνην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 15, 'Κἀκεῖθεν ἀποπλεύσαντες, τῇ ἐπιούσῃ κατηντήσαμεν ἄντικρυς Χίου, τῇ δὲ ἑτέρᾳ παρεβάλομεν εἰς Σάμον, τῇ δὲ ἐχομένῃ ἤλθομεν εἰς Μίλητον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 16, 'Κεκρίκει γὰρ ὁ Παῦλος παραπλεῦσαι τὴν Ἔφεσον, ὅπως μὴ γένηται αὐτῷ χρονοτριβῆσαι ἐν τῇ Ἀσίᾳ, ἔσπευδεν γὰρ εἰ δυνατὸν εἴη αὐτῷ, τὴν ἡμέραν τῆς Πεντηκοστῆς γενέσθαι εἰς Ἱεροσόλυμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 17, '¶Ἀπὸ δὲ τῆς Μιλήτου, πέμψας εἰς Ἔφεσον, μετεκαλέσατο τοὺς πρεσβυτέρους τῆς ἐκκλησίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 18, 'Ὡς δὲ παρεγένοντο πρὸς αὐτὸν, εἶπεν αὐτοῖς, “Ὑμεῖς ἐπίστασθε ἀπὸ πρώτης ἡμέρας ἀφʼ ἧς ἐπέβην εἰς τὴν Ἀσίαν, πῶς μεθʼ ὑμῶν τὸν πάντα χρόνον ἐγενόμην,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 19, 'δουλεύων τῷ  ̊Κυρίῳ μετὰ πάσης ταπεινοφροσύνης, καὶ δακρύων, καὶ πειρασμῶν, τῶν συμβάντων μοι ἐν ταῖς ἐπιβουλαῖς τῶν Ἰουδαίων·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 20, 'ὡς οὐδὲν ὑπεστειλάμην τῶν συμφερόντων τοῦ μὴ ἀναγγεῖλαι ὑμῖν, καὶ διδάξαι ὑμᾶς δημοσίᾳ καὶ κατʼ οἴκους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 21, 'διαμαρτυρόμενος Ἰουδαίοις τε καὶ Ἕλλησιν, τὴν εἰς  ̊Θεὸν μετάνοιαν καὶ πίστιν εἰς τὸν  ̊Κύριον ἡμῶν,  ̊Ἰησοῦν.  ̊Χριστόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 22, 'Καὶ νῦν ἰδοὺ, δεδεμένος ἐγὼ τῷ  ̊Πνεύματι, πορεύομαι εἰς Ἰερουσαλήμ, τὰ ἐν αὐτῇ συναντήσοντά ἐμοὶ μὴ εἰδώς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 23, 'πλὴν ὅτι τὸ  ̊Πνεῦμα τὸ Ἅγιον κατὰ πόλιν διαμαρτύρεταί μοι, λέγον ὅτι δεσμὰ καὶ θλίψεις με μένουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 24, 'Ἀλλʼ οὐδενὸς λόγου ποιοῦμαι τὴν ψυχὴν τιμίαν ἐμαυτῷ, ὡς τελειώσω τὸν δρόμον μου, καὶ τὴν διακονίαν ἣν ἔλαβον παρὰ τοῦ  ̊Κυρίου  ̊Ἰησοῦ, διαμαρτύρασθαι τὸ εὐαγγέλιον τῆς χάριτος τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 25, '¶Καὶ νῦν ἰδοὺ, ἐγὼ οἶδα ὅτι οὐκέτι ὄψεσθε τὸ πρόσωπόν μου ὑμεῖς πάντες, ἐν οἷς διῆλθον κηρύσσων τὴν βασιλείαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 26, 'Διότι μαρτύρομαι ὑμῖν ἐν τῇ σήμερον ἡμέρᾳ ὅτι καθαρός εἰμι ἀπὸ τοῦ αἵματος πάντων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 27, 'οὐ γὰρ ὑπεστειλάμην τοῦ μὴ ἀναγγεῖλαι πᾶσαν τὴν βουλὴν τοῦ  ̊Θεοῦ ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 28, 'Προσέχετε ἑαυτοῖς καὶ παντὶ τῷ ποιμνίῳ, ἐν ᾧ ὑμᾶς τὸ  ̊Πνεῦμα τὸ Ἅγιον ἔθετο ἐπισκόπους, ποιμαίνειν τὴν ἐκκλησίαν τοῦ  ̊Θεοῦ, ἣν περιεποιήσατο διὰ τοῦ αἵματος τοῦ ἰδίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 29, 'Ἐγὼ οἶδα ὅτι εἰσελεύσονται μετὰ τὴν ἄφιξίν μου λύκοι βαρεῖς εἰς ὑμᾶς, μὴ φειδόμενοι τοῦ ποιμνίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 30, 'καὶ ἐξ ὑμῶν αὐτῶν ἀναστήσονται ἄνδρες λαλοῦντες διεστραμμένα, τοῦ ἀποσπᾶν τοὺς μαθητὰς ὀπίσω ἑαυτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 31, 'Διὸ γρηγορεῖτε, μνημονεύοντες ὅτι τριετίαν νύκτα καὶ ἡμέραν, οὐκ ἐπαυσάμην μετὰ δακρύων νουθετῶν ἕνα ἕκαστον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 32, 'Καὶ τὰ νῦν παρατίθεμαι ὑμᾶς τῷ  ̊Θεῷ, καὶ τῷ λόγῳ τῆς χάριτος αὐτοῦ, τῷ δυναμένῳ οἰκοδομῆσαι καὶ δοῦναι τὴν κληρονομίαν ἐν τοῖς ἡγιασμένοις πᾶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 33, 'Ἀργυρίου, ἢ χρυσίου, ἢ ἱματισμοῦ, οὐδενὸς ἐπεθύμησα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 34, 'Αὐτοὶ γινώσκετε ὅτι ταῖς χρείαις μου καὶ τοῖς οὖσιν μετʼ ἐμοῦ ὑπηρέτησαν αἱ χεῖρες αὗται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 35, 'Πάντα ὑπέδειξα ὑμῖν ὅτι οὕτως κοπιῶντας δεῖ ἀντιλαμβάνεσθαι τῶν ἀσθενούντων, μνημονεύειν τε τῶν λόγων τοῦ  ̊Κυρίου  ̊Ἰησοῦ ὅτι αὐτὸς εἶπεν, ‘Μακάριόν ἐστιν μᾶλλον, διδόναι ἢ λαμβάνειν.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 36, '¶Καὶ ταῦτα εἰπὼν, θεὶς τὰ γόνατα αὐτοῦ, σὺν πᾶσιν αὐτοῖς προσηύξατο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 37, 'Ἱκανὸς δὲ κλαυθμὸς ἐγένετο πάντων, καὶ ἐπιπεσόντες ἐπὶ τὸν τράχηλον τοῦ Παύλου, κατεφίλουν αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 20, 38, 'ὀδυνώμενοι μάλιστα ἐπὶ τῷ λόγῳ ᾧ εἰρήκει ὅτι οὐκέτι μέλλουσιν τὸ πρόσωπον αὐτοῦ θεωρεῖν. Προέπεμπον δὲ αὐτὸν εἰς τὸ πλοῖον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 1, '¶Ὡς δὲ ἐγένετο ἀναχθῆναι ἡμᾶς, ἀποσπασθέντας ἀπʼ αὐτῶν, εὐθυδρομήσαντες ἤλθομεν εἰς τὴν Κῶ, τῇ δὲ ἑξῆς εἰς τὴν Ῥόδον, κἀκεῖθεν εἰς Πάταρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 2, 'Καὶ εὑρόντες πλοῖον διαπερῶν εἰς Φοινίκην, ἐπιβάντες ἀνήχθημεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 3, 'Ἀναφάναντες δὲ τὴν Κύπρον, καὶ καταλιπόντες αὐτὴν εὐώνυμον, ἐπλέομεν εἰς Συρίαν καὶ κατήλθομεν εἰς Τύρον, ἐκεῖσε γὰρ τὸ πλοῖον ἦν ἀποφορτιζόμενον τὸν γόμον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 4, 'Ἀνευρόντες δὲ τοὺς μαθητὰς, ἐπεμείναμεν αὐτοῦ ἡμέρας ἑπτά, οἵτινες τῷ Παύλῳ ἔλεγον διὰ τοῦ  ̊Πνεύματος μὴ ἐπιβαίνειν εἰς Ἱεροσόλυμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 5, 'Ὅτε δὲ ἐγένετο ἡμᾶς ἐξαρτίσαι τὰς ἡμέρας, ἐξελθόντες ἐπορευόμεθα, προπεμπόντων ἡμᾶς πάντων σὺν γυναιξὶ καὶ τέκνοις, ἕως ἔξω τῆς πόλεως, καὶ θέντες τὰ γόνατα ἐπὶ τὸν αἰγιαλὸν προσευξάμενοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 6, 'ἀπησπασάμεθα ἀλλήλους καὶ ἀνέβημεν εἰς τὸ πλοῖον, ἐκεῖνοι δὲ ὑπέστρεψαν εἰς τὰ ἴδια.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 7, '¶Ἡμεῖς δὲ, τὸν πλοῦν διανύσαντες ἀπὸ Τύρου, κατηντήσαμεν εἰς Πτολεμαΐδα, καὶ ἀσπασάμενοι τοὺς ἀδελφοὺς, ἐμείναμεν ἡμέραν μίαν παρʼ αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 8, 'Τῇ δὲ ἐπαύριον, ἐξελθόντες ἤλθομεν εἰς Καισάρειαν, καὶ εἰσελθόντες εἰς τὸν οἶκον Φιλίππου, τοῦ εὐαγγελιστοῦ, ὄντος ἐκ τῶν ἑπτὰ, ἐμείναμεν παρʼ αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 9, 'Τούτῳ δὲ ἦσαν θυγατέρες τέσσαρες παρθένοι, προφητεύουσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 10, 'Ἐπιμενόντων δὲ ἡμέρας πλείους, κατῆλθέν τις ἀπὸ τῆς Ἰουδαίας προφήτης ὀνόματι Ἅγαβος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 11, 'καὶ ἐλθὼν πρὸς ἡμᾶς, καὶ ἄρας τὴν ζώνην τοῦ Παύλου, δήσας ἑαυτοῦ τοὺς πόδας καὶ τὰς χεῖρας, εἶπεν, “Τάδε λέγει τὸ  ̊Πνεῦμα τὸ Ἅγιον: ‘Τὸν ἄνδρα οὗ ἐστιν ἡ ζώνη αὕτη, οὕτως δήσουσιν ἐν Ἰερουσαλὴμ οἱ Ἰουδαῖοι, καὶ παραδώσουσιν εἰς χεῖρας ἐθνῶν.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 12, 'Ὡς δὲ ἠκούσαμεν ταῦτα, παρεκαλοῦμεν ἡμεῖς τε καὶ οἱ ἐντόπιοι, τοῦ μὴ ἀναβαίνειν αὐτὸν εἰς Ἰερουσαλήμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 13, 'Τότε ἀπεκρίθη ὁ Παῦλος, “Τί ποιεῖτε, κλαίοντες καὶ συνθρύπτοντές μου τὴν καρδίαν; Ἐγὼ γὰρ οὐ μόνον δεθῆναι, ἀλλὰ καὶ ἀποθανεῖν εἰς Ἰερουσαλὴμ, ἑτοίμως ἔχω, ὑπὲρ τοῦ ὀνόματος τοῦ  ̊Κυρίου  ̊Ἰησοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 14, 'Μὴ πειθομένου δὲ αὐτοῦ, ἡσυχάσαμεν εἰπόντες, “Τοῦ  ̊Κυρίου τὸ θέλημα γινέσθω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 15, '¶Μετὰ δὲ τὰς ἡμέρας ταύτας, ἐπισκευασάμενοι, ἀνεβαίνομεν εἰς Ἱεροσόλυμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 16, 'Συνῆλθον δὲ καὶ τῶν μαθητῶν ἀπὸ Καισαρείας σὺν ἡμῖν, ἄγοντες παρʼ ᾧ ξενισθῶμεν Μνάσωνί, τινι Κυπρίῳ ἀρχαίῳ μαθητῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 17, '¶Γενομένων δὲ ἡμῶν εἰς Ἱεροσόλυμα, ἀσμένως ἀπεδέξαντο ἡμᾶς οἱ ἀδελφοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 18, 'Τῇ δὲ ἐπιούσῃ, εἰσῄει ὁ Παῦλος σὺν ἡμῖν πρὸς Ἰάκωβον, πάντες τε παρεγένοντο οἱ πρεσβύτεροι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 19, 'Καὶ ἀσπασάμενος αὐτοὺς, ἐξηγεῖτο καθʼ ἓν ἕκαστον, ὧν ἐποίησεν ὁ  ̊Θεὸς ἐν τοῖς ἔθνεσιν διὰ τῆς διακονίας αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 20, 'Οἱ δὲ ἀκούσαντες ἐδόξαζον τὸν  ̊Θεόν, εἶπόν τε αὐτῷ, “Θεωρεῖς, ἀδελφέ, πόσαι μυριάδες εἰσὶν ἐν τοῖς Ἰουδαίοις τῶν πεπιστευκότων, καὶ πάντες ζηλωταὶ τοῦ νόμου ὑπάρχουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 21, 'Κατηχήθησαν δὲ περὶ σοῦ, ὅτι ἀποστασίαν διδάσκεις ἀπὸ Μωϋσέως τοὺς κατὰ τὰ ἔθνη πάντας Ἰουδαίους, λέγων μὴ περιτέμνειν αὐτοὺς τὰ τέκνα, μηδὲ τοῖς ἔθεσιν περιπατεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 22, 'Τί οὖν ἐστιν; Πάντως ἀκούσονται ὅτι ἐλήλυθας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 23, 'Τοῦτο οὖν ποίησον, ὅ σοι λέγομεν. Εἰσὶν ἡμῖν ἄνδρες τέσσαρες, εὐχὴν ἔχοντες ἀφʼ ἑαυτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 24, 'Τούτους παραλαβὼν, ἁγνίσθητι σὺν αὐτοῖς καὶ δαπάνησον ἐπʼ αὐτοῖς, ἵνα ξυρήσονται τὴν κεφαλήν, καὶ γνώσονται πάντες ὅτι ὧν κατήχηνται περὶ σοῦ οὐδέν ἐστιν, ἀλλὰ στοιχεῖς καὶ αὐτὸς, φυλάσσων τὸν νόμον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 25, 'Περὶ δὲ τῶν πεπιστευκότων ἐθνῶν, ἡμεῖς ἀπεστείλαμεν κρίναντες φυλάσσεσθαι αὐτοὺς, τό τε εἰδωλόθυτον, καὶ αἷμα, καὶ πνικτὸν, καὶ πορνείαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 26, 'Τότε ὁ Παῦλος παραλαβὼν τοὺς ἄνδρας, τῇ ἐχομένῃ ἡμέρᾳ σὺν αὐτοῖς ἁγνισθεὶς, εἰσῄει εἰς τὸ ἱερόν, διαγγέλλων τὴν ἐκπλήρωσιν τῶν ἡμερῶν τοῦ ἁγνισμοῦ, ἕως οὗ προσηνέχθη ὑπὲρ ἑνὸς ἑκάστου αὐτῶν ἡ προσφορά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 27, '¶Ὡς δὲ ἔμελλον αἱ ἑπτὰ ἡμέραι συντελεῖσθαι, οἱ ἀπὸ τῆς Ἀσίας Ἰουδαῖοι, θεασάμενοι αὐτὸν ἐν τῷ ἱερῷ, συνέχεον πάντα τὸν ὄχλον, καὶ ἐπέβαλον ἐπʼ αὐτὸν τὰς χεῖρας');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 28, 'κράζοντες, “Ἄνδρες, Ἰσραηλῖται, βοηθεῖτε! Οὗτός ἐστιν ὁ ἄνθρωπος, ὁ κατὰ τοῦ λαοῦ, καὶ τοῦ νόμου, καὶ τοῦ τόπου τούτου πάντας πανταχῇ διδάσκων, ἔτι τε καὶ Ἕλληνας εἰσήγαγεν εἰς τὸ ἱερὸν, καὶ κεκοίνωκεν τὸν ἅγιον τόπον τοῦτον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 29, 'Ἦσαν γὰρ προεωρακότες Τρόφιμον τὸν Ἐφέσιον ἐν τῇ πόλει σὺν αὐτῷ, ὃν ἐνόμιζον ὅτι εἰς τὸ ἱερὸν εἰσήγαγεν ὁ Παῦλος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 30, 'Ἐκινήθη τε ἡ πόλις ὅλη, καὶ ἐγένετο συνδρομὴ τοῦ λαοῦ, καὶ ἐπιλαβόμενοι τοῦ Παύλου, εἷλκον αὐτὸν ἔξω τοῦ ἱεροῦ, καὶ εὐθέως ἐκλείσθησαν αἱ θύραι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 31, 'Ζητούντων τε αὐτὸν ἀποκτεῖναι, ἀνέβη φάσις τῷ χιλιάρχῳ τῆς σπείρης, ὅτι ὅλη συγχύννεται Ἰερουσαλήμ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 32, 'ὃς ἐξαυτῆς παραλαβὼν στρατιώτας καὶ ἑκατοντάρχας, κατέδραμεν ἐπʼ αὐτούς, οἱ δὲ ἰδόντες τὸν χιλίαρχον καὶ τοὺς στρατιώτας, ἐπαύσαντο τύπτοντες τὸν Παῦλον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 33, 'Τότε ἐγγίσας, ὁ χιλίαρχος ἐπελάβετο αὐτοῦ, καὶ ἐκέλευσε δεθῆναι ἁλύσεσι δυσί, καὶ ἐπυνθάνετο τίς εἴη καὶ τί ἐστιν πεποιηκώς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 34, 'Ἄλλοι δὲ, ἄλλο τι ἐπεφώνουν ἐν τῷ ὄχλῳ. Μὴ δυναμένου δὲ αὐτοῦ γνῶναι τὸ ἀσφαλὲς διὰ τὸν θόρυβον, ἐκέλευσεν ἄγεσθαι αὐτὸν εἰς τὴν παρεμβολήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 35, 'Ὅτε δὲ ἐγένετο ἐπὶ τοὺς ἀναβαθμούς, συνέβη βαστάζεσθαι αὐτὸν ὑπὸ τῶν στρατιωτῶν, διὰ τὴν βίαν τοῦ ὄχλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 36, 'Ἠκολούθει γὰρ τὸ πλῆθος τοῦ λαοῦ κράζοντες, “Αἶρε αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 37, '¶Μέλλων τε εἰσάγεσθαι εἰς τὴν παρεμβολὴν, ὁ Παῦλος λέγει τῷ χιλιάρχῳ, “Εἰ ἔξεστίν μοι εἰπεῖν τι πρὸς σέ;” Ὁ δὲ ἔφη, “Ἑλληνιστὶ γινώσκεις;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 38, 'Οὐκ ἄρα σὺ εἶ ὁ Αἰγύπτιος, ὁ πρὸ τούτων τῶν ἡμερῶν, ἀναστατώσας καὶ ἐξαγαγὼν εἰς τὴν ἔρημον τοὺς τετρακισχιλίους ἄνδρας τῶν σικαρίων;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 39, 'Εἶπεν δὲ ὁ Παῦλος, “Ἐγὼ ἄνθρωπος μέν εἰμι Ἰουδαῖος, Ταρσεὺς, τῆς Κιλικίας, οὐκ ἀσήμου πόλεως πολίτης. Δέομαι δέ σου, ἐπίτρεψόν μοι λαλῆσαι πρὸς τὸν λαόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 21, 40, 'Ἐπιτρέψαντος δὲ αὐτοῦ, ὁ Παῦλος ἑστὼς ἐπὶ τῶν ἀναβαθμῶν, κατέσεισε τῇ χειρὶ τῷ λαῷ, πολλῆς δὲ σιγῆς γενομένης, προσεφώνησεν τῇ Ἑβραΐδι διαλέκτῳ λέγων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 1, '“Ἄνδρες, ἀδελφοὶ, καὶ πατέρες, ἀκούσατέ μου τῆς πρὸς ὑμᾶς νυνὶ ἀπολογίας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 2, '(Ἀκούσαντες δὲ ὅτι τῇ Ἑβραΐδι διαλέκτῳ προσεφώνει αὐτοῖς, μᾶλλον παρέσχον ἡσυχίαν.) Καὶ φησίν:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 3, '“Ἐγώ εἰμι ἀνὴρ Ἰουδαῖος, γεγεννημένος ἐν Ταρσῷ τῆς Κιλικίας, ἀνατεθραμμένος δὲ ἐν τῇ πόλει ταύτῃ, παρὰ τοὺς πόδας Γαμαλιήλ, πεπαιδευμένος κατὰ ἀκρίβειαν τοῦ πατρῴου νόμου, ζηλωτὴς ὑπάρχων τοῦ  ̊Θεοῦ, καθὼς πάντες ὑμεῖς ἐστε σήμερον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 4, 'ὃς ταύτην τὴν Ὁδὸν ἐδίωξα ἄχρι θανάτου, δεσμεύων καὶ παραδιδοὺς εἰς φυλακὰς, ἄνδρας τε καὶ γυναῖκας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 5, 'ὡς καὶ ὁ ἀρχιερεὺς μαρτυρεῖ μοι καὶ πᾶν τὸ πρεσβυτέριον· παρʼ ὧν καὶ ἐπιστολὰς δεξάμενος πρὸς τοὺς ἀδελφοὺς, εἰς Δαμασκὸν ἐπορευόμην, ἄξων καὶ τοὺς ἐκεῖσε ὄντας, δεδεμένους εἰς Ἰερουσαλὴμ, ἵνα τιμωρηθῶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 6, '¶Ἐγένετο δέ μοι πορευομένῳ, καὶ ἐγγίζοντι τῇ Δαμασκῷ περὶ μεσημβρίαν, ἐξαίφνης ἐκ τοῦ οὐρανοῦ περιαστράψαι φῶς ἱκανὸν περὶ ἐμέ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 7, 'Ἔπεσά τε εἰς τὸ ἔδαφος, καὶ ἤκουσα φωνῆς λεγούσης μοι, ‘Σαοὺλ, Σαούλ, τί με διώκεις;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 8, 'Ἐγὼ δὲ ἀπεκρίθην, ‘Τίς εἶ, κύριε;’ Εἶπέν τε πρὸς ἐμέ, ‘Ἐγώ εἰμι  ̊Ἰησοῦς ὁ Ναζωραῖος, ὃν σὺ διώκεις.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 9, 'Οἱ δὲ σὺν ἐμοὶ ὄντες, τὸ μὲν φῶς ἐθεάσαντο, τὴν δὲ φωνὴν οὐκ ἤκουσαν τοῦ λαλοῦντός μοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 10, 'Εἶπον δέ, ‘Τί ποιήσω,  ̊Κύριε;’ Ὁ δὲ  ̊Κύριος εἶπεν πρός με, ‘Ἀναστὰς πορεύου εἰς Δαμασκόν, κἀκεῖ σοι λαληθήσεται περὶ πάντων ὧν τέτακταί σοι ποιῆσαι.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 11, 'Ὡς δὲ οὐκ ἐνέβλεπον ἀπὸ τῆς δόξης τοῦ φωτὸς ἐκείνου, χειραγωγούμενος ὑπὸ τῶν συνόντων μοι, ἦλθον εἰς Δαμασκόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 12, '¶Ἁνανίας δέ τις ἀνὴρ εὐλαβὴς κατὰ τὸν νόμον, μαρτυρούμενος ὑπὸ πάντων τῶν κατοικούντων Ἰουδαίων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 13, 'ἐλθὼν πρὸς ἐμὲ καὶ ἐπιστὰς, εἶπέν μοι, ‘Σαοὺλ, ἀδελφέ, ἀνάβλεψον.’ Κἀγὼ αὐτῇ τῇ ὥρᾳ ἀνέβλεψα εἰς αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 14, 'Ὁ δὲ εἶπεν, ‘Ὁ  ̊Θεὸς τῶν πατέρων ἡμῶν προεχειρίσατό σε γνῶναι τὸ θέλημα αὐτοῦ, καὶ ἰδεῖν τὸν Δίκαιον, καὶ ἀκοῦσαι φωνὴν ἐκ τοῦ στόματος αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 15, 'Ὅτι ἔσῃ μάρτυς αὐτῷ πρὸς πάντας ἀνθρώπους, ὧν ἑώρακας καὶ ἤκουσας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 16, 'Καὶ νῦν τί μέλλεις; Ἀναστὰς, βάπτισαι καὶ ἀπόλουσαι τὰς ἁμαρτίας σου, ἐπικαλεσάμενος τὸ ὄνομα αὐτοῦ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 17, '¶Ἐγένετο δέ μοι, ὑποστρέψαντι εἰς Ἰερουσαλὴμ, καὶ προσευχομένου μου ἐν τῷ ἱερῷ, γενέσθαι με ἐν ἐκστάσει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 18, 'καὶ ἰδεῖν αὐτὸν λέγοντά μοι, ‘Σπεῦσον καὶ ἔξελθε ἐν τάχει ἐξ Ἰερουσαλήμ, διότι οὐ παραδέξονταί σου μαρτυρίαν περὶ ἐμοῦ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 19, 'Κἀγὼ εἶπον, ‘ ̊Κύριε, αὐτοὶ ἐπίστανται ὅτι ἐγὼ ἤμην φυλακίζων καὶ δέρων κατὰ τὰς συναγωγὰς, τοὺς πιστεύοντας ἐπὶ σέ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 20, 'Καὶ ὅτε ἐξεχύννετο τὸ αἷμα Στεφάνου τοῦ μάρτυρός σου, καὶ αὐτὸς ἤμην ἐφεστὼς, καὶ συνευδοκῶν, καὶ φυλάσσων τὰ ἱμάτια τῶν ἀναιρούντων αὐτόν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 21, 'Καὶ εἶπεν πρός με, ‘Πορεύου, ὅτι ἐγὼ εἰς ἔθνη μακρὰν ἐξαποστελῶ σε.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 22, '¶Ἤκουον δὲ αὐτοῦ ἄχρι τούτου τοῦ λόγου, καὶ ἐπῆραν τὴν φωνὴν αὐτῶν λέγοντες, “Αἶρε ἀπὸ τῆς γῆς τὸν τοιοῦτον, οὐ γὰρ καθῆκεν αὐτὸν ζῆν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 23, 'Κραυγαζόντων τε αὐτῶν, καὶ ῥιπτούντων τὰ ἱμάτια, καὶ κονιορτὸν βαλλόντων εἰς τὸν ἀέρα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 24, 'ἐκέλευσεν ὁ χιλίαρχος εἰσάγεσθαι αὐτὸν εἰς τὴν παρεμβολήν, εἴπας μάστιξιν ἀνετάζεσθαι αὐτὸν, ἵνα ἐπιγνῷ διʼ ἣν αἰτίαν οὕτως ἐπεφώνουν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 25, 'Ὡς δὲ προέτειναν αὐτὸν τοῖς ἱμᾶσιν, εἶπεν πρὸς τὸν ἑστῶτα ἑκατόνταρχον ὁ Παῦλος, “Εἰ ἄνθρωπον Ῥωμαῖον καὶ ἀκατάκριτον, ἔξεστιν ὑμῖν μαστίζειν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 26, 'Ἀκούσας δὲ ὁ ἑκατοντάρχης, προσελθὼν τῷ χιλιάρχῳ, ἀπήγγειλεν λέγων, “Τί μέλλεις ποιεῖν; Ὁ γὰρ ἄνθρωπος οὗτος Ῥωμαῖός ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 27, 'Προσελθὼν δὲ, ὁ χιλίαρχος εἶπεν αὐτῷ, “Λέγε μοι, σὺ Ῥωμαῖος εἶ;” Ὁ δὲ ἔφη, “Ναί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 28, 'Ἀπεκρίθη δὲ ὁ χιλίαρχος, “Ἐγὼ πολλοῦ κεφαλαίου τὴν πολιτείαν ταύτην ἐκτησάμην.” Ὁ δὲ Παῦλος ἔφη, “Ἐγὼ δὲ καὶ γεγέννημαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 29, 'Εὐθέως οὖν ἀπέστησαν ἀπʼ αὐτοῦ οἱ μέλλοντες αὐτὸν ἀνετάζειν, καὶ ὁ χιλίαρχος δὲ ἐφοβήθη, ἐπιγνοὺς ὅτι Ῥωμαῖός ἐστιν, καὶ ὅτι αὐτὸν ἦν δεδεκώς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 22, 30, '¶Τῇ δὲ ἐπαύριον, βουλόμενος γνῶναι τὸ ἀσφαλὲς, τὸ τί κατηγορεῖται ὑπὸ τῶν Ἰουδαίων, ἔλυσεν αὐτόν, καὶ ἐκέλευσεν συνελθεῖν τοὺς ἀρχιερεῖς καὶ πᾶν τὸ Συνέδριον, καὶ καταγαγὼν τὸν Παῦλον, ἔστησεν εἰς αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 1, 'Ἀτενίσας δὲ τῷ Συνεδρίῳ ὁ Παῦλος εἶπεν, “Ἄνδρες, ἀδελφοί, ἐγὼ πάσῃ συνειδήσει ἀγαθῇ πεπολίτευμαι τῷ  ̊Θεῷ ἄχρι ταύτης τῆς ἡμέρας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 2, 'Ὁ δὲ ἀρχιερεὺς Ἁνανίας ἐπέταξεν τοῖς παρεστῶσιν αὐτῷ, τύπτειν αὐτοῦ τὸ στόμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 3, 'Τότε ὁ Παῦλος πρὸς αὐτὸν εἶπεν, “Τύπτειν σε μέλλει ὁ  ̊Θεός, τοῖχε κεκονιαμένε! Καὶ σὺ κάθῃ κρίνων με κατὰ τὸν νόμον, καὶ παρανομῶν κελεύεις με τύπτεσθαι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 4, 'Οἱ δὲ παρεστῶτες εἶπαν, “Τὸν ἀρχιερέα τοῦ  ̊Θεοῦ λοιδορεῖς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 5, 'Ἔφη τε ὁ Παῦλος, “Οὐκ ᾔδειν, ἀδελφοί, ὅτι ἐστὶν ἀρχιερεύς· γέγραπται γὰρ, ὅτι ‘Ἄρχοντα τοῦ λαοῦ σου, οὐκ ἐρεῖς κακῶς.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 6, '¶Γνοὺς δὲ ὁ Παῦλος ὅτι τὸ ἓν μέρος ἐστὶν Σαδδουκαίων, τὸ δὲ ἕτερον Φαρισαίων, ἔκραζεν ἐν τῷ Συνεδρίῳ, “Ἄνδρες, ἀδελφοί, ἐγὼ Φαρισαῖός εἰμι, υἱὸς Φαρισαίων· περὶ ἐλπίδος καὶ ἀναστάσεως νεκρῶν ἐγὼ κρίνομαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 7, 'Τοῦτο δὲ αὐτοῦ λαλοῦντος, ἐγένετο στάσις τῶν Φαρισαίων καὶ Σαδδουκαίων, καὶ ἐσχίσθη τὸ πλῆθος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 8, 'Σαδδουκαῖοι μὲν γὰρ λέγουσιν μὴ εἶναι ἀνάστασιν, μήτε ἄγγελον, μήτε πνεῦμα, Φαρισαῖοι δὲ ὁμολογοῦσιν τὰ ἀμφότερα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 9, 'Ἐγένετο δὲ κραυγὴ μεγάλη, καὶ ἀναστάντες τινὲς τῶν γραμματέων τοῦ μέρους τῶν Φαρισαίων, διεμάχοντο λέγοντες, “Οὐδὲν κακὸν εὑρίσκομεν ἐν τῷ ἀνθρώπῳ τούτῳ· εἰ δὲ πνεῦμα ἐλάλησεν αὐτῷ, ἢ ἄγγελος;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 10, 'Πολλῆς δὲ γινομένης στάσεως, φοβηθεὶς ὁ χιλίαρχος μὴ διασπασθῇ ὁ Παῦλος ὑπʼ αὐτῶν, ἐκέλευσεν τὸ στράτευμα καταβὰν, ἁρπάσαι αὐτὸν ἐκ μέσου αὐτῶν, ἄγειν τε εἰς τὴν παρεμβολήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 11, '¶Τῇ δὲ ἐπιούσῃ νυκτὶ, ἐπιστὰς αὐτῷ, ὁ  ̊Κύριος εἶπεν, “Θάρσει, ὡς γὰρ διεμαρτύρω τὰ περὶ ἐμοῦ εἰς Ἰερουσαλὴμ, οὕτω σε δεῖ καὶ εἰς Ῥώμην μαρτυρῆσαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 12, '¶Γενομένης δὲ ἡμέρας, ποιήσαντες συστροφὴν, οἱ Ἰουδαῖοι ἀνεθεμάτισαν ἑαυτοὺς, λέγοντες μήτε φαγεῖν μήτε πιεῖν, ἕως οὗ ἀποκτείνωσιν τὸν Παῦλον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 13, 'Ἦσαν δὲ πλείους τεσσεράκοντα οἱ ταύτην τὴν συνωμοσίαν ποιησάμενοι·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 14, 'οἵτινες προσελθόντες τοῖς ἀρχιερεῦσιν καὶ τοῖς πρεσβυτέροις εἶπαν, “Ἀναθέματι ἀνεθεματίσαμεν ἑαυτοὺς, μηδενὸς γεύσασθαι ἕως οὗ ἀποκτείνωμεν τὸν Παῦλον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 15, 'Νῦν οὖν ὑμεῖς ἐμφανίσατε τῷ χιλιάρχῳ σὺν τῷ Συνεδρίῳ, ὅπως καταγάγῃ αὐτὸν εἰς ὑμᾶς, ὡς μέλλοντας διαγινώσκειν ἀκριβέστερον τὰ περὶ αὐτοῦ· ἡμεῖς δὲ πρὸ τοῦ ἐγγίσαι αὐτὸν, ἕτοιμοί ἐσμεν τοῦ ἀνελεῖν αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 16, '¶Ἀκούσας δὲ ὁ υἱὸς τῆς ἀδελφῆς Παύλου, τὴν ἐνέδραν παραγενόμενος, καὶ εἰσελθὼν εἰς τὴν παρεμβολὴν, ἀπήγγειλεν τῷ Παύλῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 17, 'Προσκαλεσάμενος δὲ ὁ Παῦλος ἕνα τῶν ἑκατονταρχῶν, ἔφη, “Τὸν νεανίαν τοῦτον ἄπαγε πρὸς τὸν χιλίαρχον, ἔχει γὰρ ἀπαγγεῖλαί τι αὐτῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 18, 'Ὁ μὲν οὖν παραλαβὼν αὐτὸν, ἤγαγεν πρὸς τὸν χιλίαρχον, καὶ φησίν, “Ὁ δέσμιος, Παῦλος, προσκαλεσάμενός με, ἠρώτησεν τοῦτον τὸν νεανίσκον ἀγαγεῖν πρὸς σέ, ἔχοντά τι λαλῆσαί σοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 19, 'Ἐπιλαβόμενος δὲ τῆς χειρὸς αὐτοῦ ὁ χιλίαρχος, καὶ ἀναχωρήσας κατʼ ἰδίαν, ἐπυνθάνετο, “Τί ἐστιν ὃ ἔχεις ἀπαγγεῖλαί μοι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 20, 'Εἶπεν δὲ, ὅτι “Οἱ Ἰουδαῖοι συνέθεντο τοῦ ἐρωτῆσαί σε, ὅπως αὔριον τὸν Παῦλον καταγάγῃς εἰς τὸ Συνέδριον, ὡς μέλλων τι ἀκριβέστερον πυνθάνεσθαι περὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 21, 'Σὺ οὖν μὴ πεισθῇς αὐτοῖς, ἐνεδρεύουσιν γὰρ αὐτὸν ἐξ αὐτῶν ἄνδρες πλείους τεσσεράκοντα, οἵτινες ἀνεθεμάτισαν ἑαυτοὺς μήτε φαγεῖν μήτε πιεῖν, ἕως οὗ ἀνέλωσιν αὐτόν, καὶ νῦν εἰσιν ἕτοιμοι, προσδεχόμενοι τὴν ἀπὸ σοῦ ἐπαγγελίαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 22, 'Ὁ μὲν οὖν χιλίαρχος ἀπέλυσε τὸν νεανίσκον παραγγείλας, “Μηδενὶ ἐκλαλῆσαι ὅτι ταῦτα ἐνεφάνισας πρὸς ἐμέ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 23, '¶Καὶ προσκαλεσάμενός τινας δύο τῶν ἑκατονταρχῶν, εἶπεν, “Ἑτοιμάσατε στρατιώτας διακοσίους, ὅπως πορευθῶσιν ἕως Καισαρείας, καὶ ἱππεῖς ἑβδομήκοντα, καὶ δεξιολάβους διακοσίους, ἀπὸ τρίτης ὥρας τῆς νυκτός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 24, 'Κτήνη τε παραστῆσαι, ἵνα ἐπιβιβάσαντες τὸν Παῦλον, διασώσωσι πρὸς Φήλικα τὸν ἡγεμόνα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 25, 'γράψας ἐπιστολὴν, ἔχουσαν τὸν τύπον τοῦτον:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 26, '“Κλαύδιος Λυσίας, τῷ κρατίστῳ ἡγεμόνι Φήλικι, χαίρειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 27, 'Τὸν ἄνδρα τοῦτον συλλημφθέντα ὑπὸ τῶν Ἰουδαίων, καὶ μέλλοντα ἀναιρεῖσθαι ὑπʼ αὐτῶν, ἐπιστὰς σὺν τῷ στρατεύματι, ἐξειλάμην μαθὼν ὅτι Ῥωμαῖός ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 28, 'Βουλόμενός τε ἐπιγνῶναι τὴν αἰτίαν διʼ ἣν ἐνεκάλουν αὐτῷ, κατήγαγον εἰς τὸ Συνέδριον αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 29, 'Ὃν εὗρον ἐγκαλούμενον περὶ ζητημάτων τοῦ νόμου αὐτῶν, μηδὲν δὲ ἄξιον θανάτου ἢ δεσμῶν ἔχοντα ἔγκλημα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 30, 'Μηνυθείσης δέ μοι ἐπιβουλῆς εἰς τὸν ἄνδρα ἔσεσθαι, ἐξαυτῆς ἔπεμψα πρὸς σέ, παραγγείλας καὶ τοῖς κατηγόροις λέγειν αὑτούς ἐπὶ σοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 31, '¶Οἱ μὲν οὖν στρατιῶται κατὰ τὸ διατεταγμένον αὐτοῖς, ἀναλαβόντες τὸν Παῦλον, ἤγαγον διὰ νυκτὸς εἰς τὴν Ἀντιπατρίδα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 32, 'Τῇ δὲ ἐπαύριον, ἐάσαντες τοὺς ἱππεῖς ἀπέρχεσθαι σὺν αὐτῷ, ὑπέστρεψαν εἰς τὴν παρεμβολήν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 33, 'οἵτινες εἰσελθόντες εἰς τὴν Καισάρειαν, καὶ ἀναδόντες τὴν ἐπιστολὴν τῷ ἡγεμόνι, παρέστησαν καὶ τὸν Παῦλον αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 34, 'Ἀναγνοὺς δὲ, καὶ ἐπερωτήσας ἐκ ποίας ἐπαρχείας ἐστὶν, καὶ πυθόμενος ὅτι ἀπὸ Κιλικίας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 23, 35, '“Διακούσομαί σου”, ἔφη, “ὅταν καὶ οἱ κατήγοροί σου παραγένωνται”, κελεύσας ἐν τῷ πραιτωρίῳ τοῦ Ἡρῴδου, φυλάσσεσθαι αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 1, '¶Μετὰ δὲ πέντε ἡμέρας, κατέβη ὁ ἀρχιερεὺς Ἁνανίας μετὰ πρεσβυτέρων τινῶν, καὶ ῥήτορος Τερτύλλου τινός, οἵτινες ἐνεφάνισαν τῷ ἡγεμόνι κατὰ τοῦ Παύλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 2, 'Κληθέντος δὲ αὐτοῦ, ἤρξατο κατηγορεῖν ὁ Τέρτυλλος λέγων, “Πολλῆς εἰρήνης τυγχάνοντες διὰ σοῦ, καὶ διορθωμάτων γινομένων τῷ ἔθνει τούτῳ διὰ τῆς σῆς προνοίας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 3, 'πάντῃ τε καὶ πανταχοῦ, ἀποδεχόμεθα, κράτιστε Φῆλιξ, μετὰ πάσης εὐχαριστίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 4, 'Ἵνα δὲ μὴ ἐπὶ πλεῖόν σε ἐγκόπτω, παρακαλῶ ἀκοῦσαί σε ἡμῶν συντόμως, τῇ σῇ ἐπιεικείᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 5, 'Εὑρόντες γὰρ τὸν ἄνδρα τοῦτον λοιμὸν, καὶ κινοῦντα στάσεις πᾶσι τοῖς Ἰουδαίοις τοῖς κατὰ τὴν οἰκουμένην, πρωτοστάτην τε τῆς τῶν Ναζωραίων αἱρέσεως,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 6, 'ὃς καὶ τὸ ἱερὸν ἐπείρασεν βεβηλῶσαι, ὃν καὶ ἐκρατήσαμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 7, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 8, 'παρʼ οὗ δυνήσῃ αὐτὸς, ἀνακρίνας περὶ πάντων τούτων, ἐπιγνῶναι ὧν ἡμεῖς κατηγοροῦμεν αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 9, 'Συνεπέθεντο δὲ καὶ οἱ Ἰουδαῖοι, φάσκοντες ταῦτα οὕτως ἔχειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 10, '¶Ἀπεκρίθη τε ὁ Παῦλος, νεύσαντος αὐτῷ τοῦ ἡγεμόνος λέγειν, “Ἐκ πολλῶν ἐτῶν ὄντα σε κριτὴν τῷ ἔθνει τούτῳ ἐπιστάμενος, εὐθύμως τὰ περὶ ἐμαυτοῦ ἀπολογοῦμαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 11, 'Δυναμένου σου ἐπιγνῶναι ὅτι οὐ πλείους εἰσίν μοι ἡμέραι δώδεκα, ἀφʼ ἧς ἀνέβην προσκυνήσων εἰς Ἰερουσαλήμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 12, 'Καὶ οὔτε ἐν τῷ ἱερῷ εὗρόν με πρός τινα διαλεγόμενον ἢ ἐπίστασιν ποιοῦντα ὄχλου, οὔτε ἐν ταῖς συναγωγαῖς, οὔτε κατὰ τὴν πόλιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 13, 'οὐδὲ παραστῆσαι δύνανταί σοι, περὶ ὧν νυνὶ κατηγοροῦσίν μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 14, 'Ὁμολογῶ δὲ τοῦτό σοι ὅτι κατὰ τὴν Ὁδὸν ἣν λέγουσιν αἵρεσιν, οὕτως λατρεύω τῷ πατρῴῳ  ̊Θεῷ, πιστεύων πᾶσι τοῖς κατὰ τὸν νόμον καὶ τοῖς ἐν τοῖς προφήταις γεγραμμένοις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 15, 'ἐλπίδα ἔχων εἰς τὸν  ̊Θεόν, ἣν καὶ αὐτοὶ οὗτοι προσδέχονται, ἀνάστασιν μέλλειν ἔσεσθαι, δικαίων τε καὶ ἀδίκων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 16, 'Ἐν τούτῳ καὶ αὐτὸς ἀσκῶ, ἀπρόσκοπον συνείδησιν ἔχειν πρὸς τὸν  ̊Θεὸν καὶ τοὺς ἀνθρώπους διὰ παντός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 17, 'Διʼ ἐτῶν δὲ πλειόνων ἐλεημοσύνας ποιήσων εἰς τὸ ἔθνος μου παρεγενόμην καὶ προσφοράς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 18, 'ἐν αἷς εὗρόν με ἡγνισμένον ἐν τῷ ἱερῷ, οὐ μετὰ ὄχλου, οὐδὲ μετὰ θορύβου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 19, 'Τινὲς δὲ ἀπὸ τῆς Ἀσίας Ἰουδαῖοι, οὓς ἔδει ἐπὶ σοῦ παρεῖναι καὶ κατηγορεῖν, εἴ τι ἔχοιεν πρὸς ἐμέ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 20, 'Ἢ αὐτοὶ οὗτοι εἰπάτωσαν, τί εὗρον ἀδίκημα, στάντος μου ἐπὶ τοῦ Συνεδρίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 21, 'ἢ περὶ μιᾶς ταύτης φωνῆς, ἧς ἐκέκραξα ἐν αὐτοῖς ἑστὼς: ὅτι ‘Περὶ ἀναστάσεως νεκρῶν ἐγὼ κρίνομαι σήμερον ἐφʼ ὑμῶν.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 22, '¶Ἀνεβάλετο δὲ αὐτοὺς ὁ Φῆλιξ, ἀκριβέστερον εἰδὼς τὰ περὶ τῆς Ὁδοῦ, εἴπας, “Ὅταν Λυσίας ὁ χιλίαρχος καταβῇ, διαγνώσομαι τὰ καθʼ ὑμᾶς”·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 23, 'διαταξάμενος τῷ ἑκατοντάρχῃ τηρεῖσθαι αὐτὸν, ἔχειν τε ἄνεσιν, καὶ μηδένα κωλύειν τῶν ἰδίων αὐτοῦ ὑπηρετεῖν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 24, '¶Μετὰ δὲ ἡμέρας τινὰς, παραγενόμενος ὁ Φῆλιξ σὺν Δρουσίλλῃ, τῇ ἰδίᾳ γυναικὶ οὔσῃ Ἰουδαίᾳ, μετεπέμψατο τὸν Παῦλον, καὶ ἤκουσεν αὐτοῦ περὶ τῆς εἰς  ̊Χριστὸν πίστεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 25, 'Διαλεγομένου δὲ αὐτοῦ περὶ δικαιοσύνης, καὶ ἐγκρατείας, καὶ τοῦ κρίματος τοῦ μέλλοντος, ἔμφοβος γενόμενος, ὁ Φῆλιξ ἀπεκρίθη, “Τὸ νῦν ἔχον πορεύου, καιρὸν δὲ μεταλαβὼν, μετακαλέσομαί σε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 26, 'Ἅμα καὶ ἐλπίζων ὅτι χρήματα δοθήσεται αὐτῷ ὑπὸ τοῦ Παύλου, διὸ καὶ πυκνότερον αὐτὸν μεταπεμπόμενος, ὡμίλει αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 24, 27, '¶Διετίας δὲ πληρωθείσης, ἔλαβεν διάδοχον ὁ Φῆλιξ Πόρκιον Φῆστον· θέλων τε χάριτα καταθέσθαι τοῖς Ἰουδαίοις, ὁ Φῆλιξ κατέλιπεν τὸν Παῦλον δεδεμένον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 1, '¶Φῆστος οὖν ἐπιβὰς τῇ ἐπαρχείᾳ, μετὰ τρεῖς ἡμέρας ἀνέβη εἰς Ἱεροσόλυμα ἀπὸ Καισαρείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 2, 'Ἐνεφάνισάν τε αὐτῷ οἱ ἀρχιερεῖς καὶ οἱ πρῶτοι τῶν Ἰουδαίων κατὰ τοῦ Παύλου, καὶ παρεκάλουν αὐτὸν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 3, 'αἰτούμενοι χάριν κατʼ αὐτοῦ, ὅπως μεταπέμψηται αὐτὸν εἰς Ἰερουσαλήμ (ἐνέδραν ποιοῦντες ἀνελεῖν αὐτὸν κατὰ τὴν ὁδόν).');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 4, 'Ὁ μὲν οὖν Φῆστος ἀπεκρίθη, τηρεῖσθαι τὸν Παῦλον εἰς Καισάρειαν, ἑαυτὸν δὲ μέλλειν ἐν τάχει ἐκπορεύεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 5, '“Οἱ οὖν ἐν ὑμῖν”, φησίν, “δυνατοὶ συγκαταβάντες, εἴ τί ἐστιν ἐν τῷ ἀνδρὶ ἄτοπον, κατηγορείτωσαν αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 6, '¶Διατρίψας δὲ ἐν αὐτοῖς ἡμέρας, οὐ πλείους ὀκτὼ ἢ δέκα, καταβὰς εἰς Καισάρειαν, τῇ ἐπαύριον καθίσας ἐπὶ τοῦ βήματος, ἐκέλευσεν τὸν Παῦλον ἀχθῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 7, 'Παραγενομένου δὲ αὐτοῦ, περιέστησαν αὐτὸν οἱ ἀπὸ Ἱεροσολύμων καταβεβηκότες Ἰουδαῖοι, πολλὰ καὶ βαρέα αἰτιώματα καταφέροντες, ἃ οὐκ ἴσχυον ἀποδεῖξαι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 8, 'τοῦ Παύλου ἀπολογουμένου, ὅτι “Οὔτε εἰς τὸν νόμον τῶν Ἰουδαίων, οὔτε εἰς τὸ ἱερὸν, οὔτε εἰς Καίσαρά, τι ἥμαρτον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 9, 'Ὁ Φῆστος δὲ θέλων τοῖς Ἰουδαίοις χάριν καταθέσθαι, ἀποκριθεὶς τῷ Παύλῳ εἶπεν, “Θέλεις εἰς Ἱεροσόλυμα ἀναβὰς ἐκεῖ περὶ τούτων κριθῆναι ἐπʼ ἐμοῦ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 10, 'Εἶπεν δὲ ὁ Παῦλος, “Ἐπὶ τοῦ βήματος Καίσαρος ἑστώς εἰμι, οὗ με δεῖ κρίνεσθαι. Ἰουδαίους οὐδὲν ἠδίκηκα, ὡς καὶ σὺ κάλλιον ἐπιγινώσκεις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 11, 'Εἰ μὲν οὖν ἀδικῶ καὶ ἄξιον θανάτου πέπραχά τι, οὐ παραιτοῦμαι τὸ ἀποθανεῖν· εἰ δὲ οὐδέν ἐστιν ὧν οὗτοι κατηγοροῦσίν μου, οὐδείς με δύναται αὐτοῖς χαρίσασθαι. Καίσαρα ἐπικαλοῦμαι!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 12, 'Τότε ὁ Φῆστος συλλαλήσας μετὰ τοῦ συμβουλίου, ἀπεκρίθη, “Καίσαρα ἐπικέκλησαι, ἐπὶ Καίσαρα πορεύσῃ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 13, '¶Ἡμερῶν δὲ διαγενομένων τινῶν, Ἀγρίππας ὁ βασιλεὺς καὶ Βερνίκη κατήντησαν εἰς Καισάρειαν, ἀσπασάμενοι τὸν Φῆστον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 14, 'Ὡς δὲ πλείους ἡμέρας διέτριβον ἐκεῖ, ὁ Φῆστος τῷ βασιλεῖ ἀνέθετο τὰ κατὰ τὸν Παῦλον λέγων, “Ἀνήρ τίς ἐστιν, καταλελειμμένος ὑπὸ Φήλικος δέσμιος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 15, 'περὶ οὗ γενομένου μου εἰς Ἱεροσόλυμα, ἐνεφάνισαν οἱ ἀρχιερεῖς καὶ οἱ πρεσβύτεροι τῶν Ἰουδαίων, αἰτούμενοι κατʼ αὐτοῦ καταδίκην·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 16, 'πρὸς οὓς ἀπεκρίθην ὅτι οὐκ ἔστιν ἔθος Ῥωμαίοις χαρίζεσθαί τινα ἄνθρωπον πρὶν ἢ ὁ κατηγορούμενος, κατὰ πρόσωπον ἔχοι τοὺς κατηγόρους τόπον τε ἀπολογίας λάβοι περὶ τοῦ ἐγκλήματος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 17, 'Συνελθόντων οὖν αὐτῶν ἐνθάδε, ἀναβολὴν μηδεμίαν ποιησάμενος, τῇ ἑξῆς καθίσας ἐπὶ τοῦ βήματος, ἐκέλευσα ἀχθῆναι τὸν ἄνδρα·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 18, 'περὶ οὗ σταθέντες οἱ κατήγοροι οὐδεμίαν αἰτίαν ἔφερον, ὧν ἐγὼ ὑπενόουν πονηράν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 19, 'Ζητήματα δέ τινα περὶ τῆς ἰδίας δεισιδαιμονίας, εἶχον πρὸς αὐτὸν, καὶ περί τινος  ̊Ἰησοῦ τεθνηκότος, ὃν ἔφασκεν ὁ Παῦλος ζῆν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 20, 'Ἀπορούμενος δὲ, ἐγὼ τὴν περὶ τούτων ζήτησιν, ἔλεγον εἰ βούλοιτο πορεύεσθαι εἰς Ἱεροσόλυμα, κἀκεῖ κρίνεσθαι περὶ τούτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 21, 'Τοῦ δὲ Παύλου ἐπικαλεσαμένου τηρηθῆναι αὐτὸν εἰς τὴν τοῦ Σεβαστοῦ διάγνωσιν, ἐκέλευσα τηρεῖσθαι αὐτὸν, ἕως οὗ ἀναπέμψω αὐτὸν πρὸς Καίσαρα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 22, 'Ἀγρίππας δὲ πρὸς τὸν Φῆστον, “Ἐβουλόμην καὶ αὐτὸς τοῦ ἀνθρώπου ἀκοῦσαι.” “Αὔριον”, φησίν, “ἀκούσῃ αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 23, '¶Τῇ οὖν ἐπαύριον, ἐλθόντος τοῦ Ἀγρίππα καὶ τῆς Βερνίκης μετὰ πολλῆς φαντασίας, καὶ εἰσελθόντων εἰς τὸ ἀκροατήριον σύν τε χιλιάρχοις καὶ ἀνδράσιν τοῖς κατʼ ἐξοχὴν τῆς πόλεως, καὶ κελεύσαντος τοῦ Φήστου, ἤχθη ὁ Παῦλος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 24, 'Καί φησιν ὁ Φῆστος, “Ἀγρίππα Βασιλεῦ, καὶ πάντες οἱ συμπαρόντες ἡμῖν, ἄνδρες, θεωρεῖτε τοῦτον, περὶ οὗ ἅπαν τὸ πλῆθος τῶν Ἰουδαίων ἐνέτυχόν μοι, ἔν τε Ἱεροσολύμοις καὶ ἐνθάδε, βοῶντες μὴ δεῖν αὐτὸν ζῆν μηκέτι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 25, 'Ἐγὼ δὲ κατελαβόμην μηδὲν ἄξιον αὐτὸν θανάτου πεπραχέναι, αὐτοῦ δὲ τούτου ἐπικαλεσαμένου τὸν Σεβαστὸν, ἔκρινα πέμπειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 26, 'Περὶ οὗ ἀσφαλές τι γράψαι τῷ κυρίῳ οὐκ ἔχω. Διὸ προήγαγον αὐτὸν ἐφʼ ὑμῶν, καὶ μάλιστα ἐπὶ σοῦ, Βασιλεῦ Ἀγρίππα, ὅπως τῆς ἀνακρίσεως γενομένης, σχῶ τι γράψω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 25, 27, 'Ἄλογον γάρ μοι δοκεῖ πέμποντα δέσμιον, μὴ καὶ τὰς κατʼ αὐτοῦ αἰτίας σημᾶναι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 1, '¶Ἀγρίππας δὲ πρὸς τὸν Παῦλον ἔφη, “Ἐπιτρέπεταί σοι περὶ σεαυτοῦ λέγειν.” Τότε ὁ Παῦλος ἐκτείνας τὴν χεῖρα ἀπελογεῖτο,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 2, '“Περὶ πάντων ὧν ἐγκαλοῦμαι ὑπὸ Ἰουδαίων, Βασιλεῦ Ἀγρίππα, ἥγημαι ἐμαυτὸν μακάριον ἐπὶ σοῦ, μέλλων σήμερον ἀπολογεῖσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 3, 'Μάλιστα γνώστην ὄντα σε πάντων τῶν κατὰ Ἰουδαίους, ἐθῶν τε καὶ ζητημάτων· διὸ δέομαι μακροθύμως ἀκοῦσαί μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 4, '¶Τὴν μὲν οὖν βίωσίν μου, ἐκ νεότητος τὴν ἀπʼ ἀρχῆς γενομένην ἐν τῷ ἔθνει μου ἔν τε Ἱεροσολύμοις, ἴσασι πάντες Ἰουδαῖοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 5, 'προγινώσκοντές με ἄνωθεν, ἐὰν θέλωσι μαρτυρεῖν ὅτι κατὰ τὴν ἀκριβεστάτην αἵρεσιν τῆς ἡμετέρας θρησκείας, ἔζησα Φαρισαῖος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 6, 'Καὶ νῦν ἐπʼ ἐλπίδι τῆς εἰς τοὺς πατέρας ἡμῶν ἐπαγγελίας, γενομένης ὑπὸ τοῦ  ̊Θεοῦ, ἕστηκα κρινόμενος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 7, 'εἰς ἣν τὸ δωδεκάφυλον ἡμῶν ἐν ἐκτενείᾳ, νύκτα καὶ ἡμέραν λατρεῦον, ἐλπίζει καταντῆσαι· περὶ ἧς ἐλπίδος ἐγκαλοῦμαι ὑπὸ Ἰουδαίων, Βασιλεῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 8, 'Τί ἄπιστον κρίνεται παρʼ ὑμῖν, εἰ ὁ  ̊Θεὸς νεκροὺς ἐγείρει;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 9, '¶Ἐγὼ μὲν οὖν ἔδοξα ἐμαυτῷ πρὸς τὸ ὄνομα  ̊Ἰησοῦ τοῦ Ναζωραίου, δεῖν πολλὰ ἐναντία πρᾶξαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 10, 'Ὃ καὶ ἐποίησα ἐν Ἱεροσολύμοις, καὶ πολλούς τε τῶν ἁγίων ἐγὼ ἐν φυλακαῖς κατέκλεισα, τὴν παρὰ τῶν ἀρχιερέων ἐξουσίαν λαβών, ἀναιρουμένων τε αὐτῶν, κατήνεγκα ψῆφον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 11, 'Καὶ κατὰ πάσας τὰς συναγωγὰς, πολλάκις τιμωρῶν αὐτοὺς, ἠνάγκαζον βλασφημεῖν, περισσῶς τε ἐμμαινόμενος αὐτοῖς, ἐδίωκον ἕως καὶ εἰς τὰς ἔξω πόλεις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 12, '¶Ἐν οἷς πορευόμενος εἰς τὴν Δαμασκὸν, μετʼ ἐξουσίας καὶ ἐπιτροπῆς τῆς τῶν ἀρχιερέων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 13, 'ἡμέρας μέσης κατὰ τὴν ὁδὸν εἶδον, Βασιλεῦ, οὐρανόθεν ὑπὲρ τὴν λαμπρότητα τοῦ ἡλίου περιλάμψαν με φῶς, καὶ τοὺς σὺν ἐμοὶ πορευομένους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 14, 'Πάντων τε καταπεσόντων ἡμῶν εἰς τὴν γῆν, ἤκουσα φωνὴν, λέγουσαν πρός με τῇ Ἑβραΐδι διαλέκτῳ, ‘Σαοὺλ, Σαούλ, τί με διώκεις; Σκληρόν σοι πρὸς κέντρα λακτίζειν.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 15, 'Ἐγὼ δὲ εἶπα, ‘Τίς εἶ, κύριε;’ Ὁ δὲ  ̊Κύριος εἶπεν, ‘Ἐγώ εἰμι  ̊Ἰησοῦς, ὃν σὺ διώκεις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 16, 'Ἀλλὰ ἀνάστηθι, καὶ στῆθι ἐπὶ τοὺς πόδας σου· εἰς τοῦτο γὰρ ὤφθην σοι, προχειρίσασθαί σε ὑπηρέτην καὶ μάρτυρα, ὧν τε εἶδές με ὧν τε ὀφθήσομαί σοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 17, 'ἐξαιρούμενός σε ἐκ τοῦ λαοῦ καὶ ἐκ τῶν ἐθνῶν, εἰς οὓς ἐγὼ ἀποστέλλω σε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 18, 'ἀνοῖξαι ὀφθαλμοὺς αὐτῶν, τοῦ ἐπιστρέψαι ἀπὸ σκότους εἰς φῶς, καὶ τῆς ἐξουσίας τοῦ Σατανᾶ ἐπὶ τὸν  ̊Θεόν, τοῦ λαβεῖν αὐτοὺς ἄφεσιν ἁμαρτιῶν καὶ κλῆρον ἐν τοῖς ἡγιασμένοις πίστει τῇ εἰς ἐμέ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 19, '¶Ὅθεν, Βασιλεῦ Ἀγρίππα, οὐκ ἐγενόμην ἀπειθὴς τῇ οὐρανίῳ ὀπτασίᾳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 20, 'ἀλλὰ τοῖς ἐν Δαμασκῷ πρῶτόν τε, καὶ Ἱεροσολύμοις, πᾶσάν τε τὴν χώραν τῆς Ἰουδαίας, καὶ τοῖς ἔθνεσιν, ἀπήγγελλον μετανοεῖν καὶ ἐπιστρέφειν ἐπὶ τὸν  ̊Θεόν, ἄξια τῆς μετανοίας ἔργα πράσσοντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 21, 'Ἕνεκα τούτων, με Ἰουδαῖοι συλλαβόμενοι ἐν τῷ ἱερῷ, ἐπειρῶντο διαχειρίσασθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 22, 'Ἐπικουρίας οὖν τυχὼν τῆς ἀπὸ τοῦ  ̊Θεοῦ ἄχρι τῆς ἡμέρας ταύτης, ἕστηκα μαρτυρόμενος μικρῷ τε καὶ μεγάλῳ, οὐδὲν ἐκτὸς λέγων ὧν τε οἱ προφῆται ἐλάλησαν μελλόντων γίνεσθαι, καὶ Μωϋσῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 23, 'εἰ παθητὸς ὁ  ̊Χριστός, εἰ πρῶτος ἐξ ἀναστάσεως νεκρῶν, φῶς μέλλει καταγγέλλειν τῷ τε λαῷ καὶ τοῖς ἔθνεσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 24, '¶Ταῦτα δὲ αὐτοῦ ἀπολογουμένου, ὁ Φῆστος μεγάλῃ τῇ φωνῇ φησιν, “Μαίνῃ, Παῦλε! Τὰ πολλά σε γράμματα εἰς μανίαν περιτρέπει!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 25, 'Ὁ δὲ Παῦλος, “Οὐ μαίνομαι”, φησίν, “κράτιστε Φῆστε, ἀλλὰ ἀληθείας καὶ σωφροσύνης ῥήματα ἀποφθέγγομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 26, 'Ἐπίσταται γὰρ περὶ τούτων ὁ βασιλεύς, πρὸς ὃν καὶ παρρησιαζόμενος λαλῶ· λανθάνειν γὰρ αὐτὸν τι τούτων οὐ πείθομαι οὐθέν, οὐ γάρ ἐστιν ἐν γωνίᾳ πεπραγμένον τοῦτο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 27, 'Πιστεύεις, Βασιλεῦ Ἀγρίππα, τοῖς προφήταις; Οἶδα ὅτι πιστεύεις.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 28, 'Ὁ δὲ Ἀγρίππας πρὸς τὸν Παῦλον, “Ἐν ὀλίγῳ με πείθεις Χριστιανὸν ποιῆσαι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 29, 'Ὁ δὲ Παῦλος, “Εὐξαίμην ἂν τῷ  ̊Θεῷ, καὶ ἐν ὀλίγῳ καὶ ἐν μεγάλῳ, οὐ μόνον σὲ, ἀλλὰ καὶ πάντας τοὺς ἀκούοντάς μου σήμερον, γενέσθαι τοιούτους ὁποῖος κἀγώ εἰμι, παρεκτὸς τῶν δεσμῶν τούτων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 30, '¶Ἀνέστη τε ὁ βασιλεὺς καὶ ὁ ἡγεμὼν, ἥ τε Βερνίκη καὶ οἱ συγκαθήμενοι αὐτοῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 31, 'καὶ ἀναχωρήσαντες ἐλάλουν πρὸς ἀλλήλους λέγοντες, ὅτι “Οὐδὲν θανάτου ἢ δεσμῶν ἄξιον τι πράσσει ὁ ἄνθρωπος οὗτος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 26, 32, 'Ἀγρίππας δὲ τῷ Φήστῳ ἔφη, “Ἀπολελύσθαι ἐδύνατο ὁ ἄνθρωπος οὗτος, εἰ μὴ ἐπεκέκλητο Καίσαρα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 1, '¶Ὡς δὲ ἐκρίθη τοῦ ἀποπλεῖν ἡμᾶς εἰς τὴν Ἰταλίαν, παρεδίδουν τόν τε Παῦλον καί τινας ἑτέρους δεσμώτας, ἑκατοντάρχῃ ὀνόματι Ἰουλίῳ, σπείρης Σεβαστῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 2, 'Ἐπιβάντες δὲ πλοίῳ Ἀδραμυντηνῷ, μέλλοντι πλεῖν εἰς τοὺς κατὰ τὴν Ἀσίαν τόπους ἀνήχθημεν, ὄντος σὺν ἡμῖν Ἀριστάρχου, Μακεδόνος Θεσσαλονικέως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 3, 'Τῇ τε ἑτέρᾳ κατήχθημεν εἰς Σιδῶνα, φιλανθρώπως τε ὁ Ἰούλιος τῷ Παύλῳ χρησάμενος, ἐπέτρεψεν πρὸς τοὺς φίλους πορευθέντι, ἐπιμελείας τυχεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 4, 'Κἀκεῖθεν ἀναχθέντες, ὑπεπλεύσαμεν τὴν Κύπρον, διὰ τὸ τοὺς ἀνέμους εἶναι ἐναντίους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 5, 'Τό τε πέλαγος τὸ κατὰ τὴν Κιλικίαν καὶ Παμφυλίαν διαπλεύσαντες, κατήλθαμεν εἰς Μύρα τῆς Λυκίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 6, 'Κἀκεῖ εὑρὼν ὁ ἑκατοντάρχης πλοῖον Ἀλεξανδρῖνον, πλέον εἰς τὴν Ἰταλίαν, ἐνεβίβασεν ἡμᾶς εἰς αὐτό.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 7, 'Ἐν ἱκαναῖς δὲ ἡμέραις, βραδυπλοοῦντες καὶ μόλις, γενόμενοι κατὰ τὴν Κνίδον, μὴ προσεῶντος ἡμᾶς τοῦ ἀνέμου, ὑπεπλεύσαμεν τὴν Κρήτην κατὰ Σαλμώνην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 8, 'Μόλις τε παραλεγόμενοι αὐτὴν, ἤλθομεν εἰς τόπον τινὰ καλούμενον Καλοὺς Λιμένας, ᾧ ἐγγὺς πόλις ἦν Λασαία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 9, '¶Ἱκανοῦ δὲ χρόνου διαγενομένου, καὶ ὄντος ἤδη ἐπισφαλοῦς τοῦ πλοὸς, διὰ τὸ καὶ τὴν νηστείαν ἤδη παρεληλυθέναι, παρῄνει ὁ Παῦλος');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 10, 'λέγων αὐτοῖς, “Ἄνδρες, θεωρῶ ὅτι μετὰ ὕβρεως καὶ πολλῆς ζημίας, οὐ μόνον τοῦ φορτίου καὶ τοῦ πλοίου, ἀλλὰ καὶ τῶν ψυχῶν ἡμῶν, μέλλειν ἔσεσθαι τὸν πλοῦν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 11, 'Ὁ δὲ ἑκατοντάρχης τῷ κυβερνήτῃ καὶ τῷ ναυκλήρῳ μᾶλλον ἐπείθετο, ἢ τοῖς ὑπὸ Παύλου λεγομένοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 12, 'Ἀνευθέτου δὲ τοῦ λιμένος ὑπάρχοντος πρὸς παραχειμασίαν, οἱ πλείονες ἔθεντο βουλὴν ἀναχθῆναι ἐκεῖθεν, εἴ πως δύναιντο, καταντήσαντες εἰς Φοίνικα, παραχειμάσαι λιμένα τῆς Κρήτης, βλέποντα κατὰ λίβα καὶ κατὰ χῶρον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 13, '¶Ὑποπνεύσαντος δὲ νότου, δόξαντες τῆς προθέσεως κεκρατηκέναι, ἄραντες ἆσσον παρελέγοντο τὴν Κρήτην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 14, 'Μετʼ οὐ πολὺ δὲ, ἔβαλεν κατʼ αὐτῆς ἄνεμος τυφωνικὸς, ὁ καλούμενος Εὐρακύλων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 15, 'Συναρπασθέντος δὲ τοῦ πλοίου, καὶ μὴ δυναμένου ἀντοφθαλμεῖν τῷ ἀνέμῳ, ἐπιδόντες ἐφερόμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 16, 'Νησίον δέ τι ὑποδραμόντες, καλούμενον Κλαῦδα, ἰσχύσαμεν μόλις περικρατεῖς γενέσθαι τῆς σκάφης,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 17, 'ἣν ἄραντες, βοηθείαις ἐχρῶντο, ὑποζωννύντες τὸ πλοῖον. Φοβούμενοί τε μὴ εἰς τὴν Σύρτιν ἐκπέσωσιν, χαλάσαντες τὸ σκεῦος, οὕτως ἐφέροντο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 18, 'Σφοδρῶς δὲ χειμαζομένων ἡμῶν, τῇ ἑξῆς ἐκβολὴν ἐποιοῦντο,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 19, 'καὶ τῇ τρίτῃ, αὐτόχειρες τὴν σκευὴν τοῦ πλοίου ἔρριψαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 20, 'Μήτε δὲ ἡλίου μήτε ἄστρων ἐπιφαινόντων ἐπὶ πλείονας ἡμέρας, χειμῶνός τε οὐκ ὀλίγου ἐπικειμένου, λοιπὸν περιῃρεῖτο ἐλπὶς πᾶσα, τοῦ σῴζεσθαι ἡμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 21, '¶Πολλῆς τε ἀσιτίας ὑπαρχούσης, τότε σταθεὶς ὁ Παῦλος ἐν μέσῳ αὐτῶν εἶπεν, “Ἔδει μέν, ὦ ἄνδρες, πειθαρχήσαντάς μοι, μὴ ἀνάγεσθαι ἀπὸ τῆς Κρήτης, κερδῆσαί τε τὴν ὕβριν ταύτην, καὶ τὴν ζημίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 22, 'Καὶ τὰ νῦν παραινῶ ὑμᾶς εὐθυμεῖν, ἀποβολὴ γὰρ ψυχῆς οὐδεμία ἔσται ἐξ ὑμῶν, πλὴν τοῦ πλοίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 23, 'Παρέστη γάρ μοι ταύτῃ τῇ νυκτὶ τοῦ  ̊Θεοῦ, οὗ εἰμι, ᾧ καὶ λατρεύω, ἄγγελος');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 24, 'λέγων, ‘Μὴ φοβοῦ, Παῦλε· Καίσαρί σε δεῖ παραστῆναι, καὶ ἰδοὺ, κεχάρισταί σοι ὁ  ̊Θεὸς πάντας τοὺς πλέοντας μετὰ σοῦ.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 25, 'Διὸ εὐθυμεῖτε, ἄνδρες, πιστεύω γὰρ τῷ  ̊Θεῷ ὅτι οὕτως ἔσται, καθʼ ὃν τρόπον λελάληταί μοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 26, 'Εἰς νῆσον δέ τινα, δεῖ ἡμᾶς ἐκπεσεῖν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 27, '¶Ὡς δὲ τεσσαρεσκαιδεκάτη νὺξ ἐγένετο, διαφερομένων ἡμῶν ἐν τῷ Ἀδρίᾳ, κατὰ μέσον τῆς νυκτὸς, ὑπενόουν οἱ ναῦται προσάγειν τινὰ αὐτοῖς χώραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 28, 'Καὶ βολίσαντες, εὗρον ὀργυιὰς εἴκοσι, βραχὺ δὲ διαστήσαντες, καὶ πάλιν βολίσαντες, εὗρον ὀργυιὰς δεκαπέντε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 29, 'Φοβούμενοί τε μή που κατὰ τραχεῖς τόπους ἐκπέσωμεν, ἐκ πρύμνης ῥίψαντες ἀγκύρας τέσσαρας, ηὔχοντο ἡμέραν γενέσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 30, 'Τῶν δὲ ναυτῶν ζητούντων φυγεῖν ἐκ τοῦ πλοίου, καὶ χαλασάντων τὴν σκάφην εἰς τὴν θάλασσαν, προφάσει ὡς ἐκ πρώρας, ἀγκύρας μελλόντων ἐκτείνειν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 31, 'εἶπεν ὁ Παῦλος τῷ ἑκατοντάρχῃ καὶ τοῖς στρατιώταις, “Ἐὰν μὴ οὗτοι μείνωσιν ἐν τῷ πλοίῳ, ὑμεῖς σωθῆναι οὐ δύνασθε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 32, 'Τότε ἀπέκοψαν οἱ στρατιῶται τὰ σχοινία τῆς σκάφης, καὶ εἴασαν αὐτὴν ἐκπεσεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 33, '¶Ἄχρι δὲ οὗ ἡμέρα ἤμελλεν γίνεσθαι, παρεκάλει ὁ Παῦλος ἅπαντας, μεταλαβεῖν τροφῆς λέγων, “Τεσσαρεσκαιδεκάτην σήμερον ἡμέραν, προσδοκῶντες ἄσιτοι διατελεῖτε, μηθὲν προσλαβόμενοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 34, 'Διὸ παρακαλῶ ὑμᾶς μεταλαβεῖν τροφῆς, τοῦτο γὰρ πρὸς τῆς ὑμετέρας σωτηρίας ὑπάρχει· οὐδενὸς γὰρ ὑμῶν θρὶξ ἀπὸ τῆς κεφαλῆς ἀπολεῖται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 35, 'Εἴπας δὲ ταῦτα, καὶ λαβὼν ἄρτον, εὐχαρίστησεν τῷ  ̊Θεῷ ἐνώπιον πάντων, καὶ κλάσας, ἤρξατο ἐσθίειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 36, 'Εὔθυμοι δὲ γενόμενοι πάντες, καὶ αὐτοὶ προσελάβοντο τροφῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 37, 'Ἤμεθα δὲ αἱ πᾶσαι ψυχαὶ ἐν τῷ πλοίῳ, διακόσιαι ἑβδομήκοντα ἕξ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 38, 'Κορεσθέντες δὲ τροφῆς, ἐκούφιζον τὸ πλοῖον, ἐκβαλλόμενοι τὸν σῖτον εἰς τὴν θάλασσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 39, '¶Ὅτε δὲ ἡμέρα ἐγένετο, τὴν γῆν οὐκ ἐπεγίνωσκον, κόλπον δέ τινα κατενόουν ἔχοντα αἰγιαλὸν, εἰς ὃν ἐβουλεύοντο, εἰ δύναιντο ἐκσῶσαι τὸ πλοῖον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 40, 'Καὶ τὰς ἀγκύρας περιελόντες, εἴων εἰς τὴν θάλασσαν, ἅμα ἀνέντες τὰς ζευκτηρίας τῶν πηδαλίων, καὶ ἐπάραντες τὸν ἀρτέμωνα τῇ πνεούσῃ, κατεῖχον εἰς τὸν αἰγιαλόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 41, 'Περιπεσόντες δὲ εἰς τόπον διθάλασσον, ἐπέκειλαν τὴν ναῦν, καὶ ἡ μὲν πρῷρα ἐρείσασα ἔμεινεν ἀσάλευτος, ἡ δὲ πρύμνα ἐλύετο ὑπὸ τῆς βίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 42, 'Τῶν δὲ στρατιωτῶν, βουλὴ ἐγένετο ἵνα τοὺς δεσμώτας ἀποκτείνωσιν, μή τις ἐκκολυμβήσας διαφύγῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 43, 'Ὁ δὲ ἑκατοντάρχης βουλόμενος διασῶσαι τὸν Παῦλον, ἐκώλυσεν αὐτοὺς τοῦ βουλήματος, ἐκέλευσέν τε τοὺς δυναμένους κολυμβᾶν, ἀπορίψαντας πρώτους, ἐπὶ τὴν γῆν ἐξιέναι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 27, 44, 'καὶ τοὺς λοιποὺς, οὓς μὲν ἐπὶ σανίσιν, οὓς δὲ ἐπί τινων τῶν ἀπὸ τοῦ πλοίου. Καὶ οὕτως ἐγένετο, πάντας διασωθῆναι ἐπὶ τὴν γῆν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 1, '¶Καὶ διασωθέντες, τότε ἐπέγνωμεν ὅτι Μελίτη ἡ νῆσος καλεῖται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 2, 'Οἵ τε βάρβαροι παρεῖχαν οὐ τὴν τυχοῦσαν φιλανθρωπίαν ἡμῖν, ἅψαντες γὰρ πυρὰν, προσελάβοντο πάντας ἡμᾶς, διὰ τὸν ὑετὸν τὸν ἐφεστῶτα, καὶ διὰ τὸ ψῦχος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 3, 'Συστρέψαντος δὲ τοῦ Παύλου φρυγάνων τι πλῆθος, καὶ ἐπιθέντος ἐπὶ τὴν πυράν, ἔχιδνα ἀπὸ τῆς θέρμης ἐξελθοῦσα, καθῆψε τῆς χειρὸς αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 4, 'Ὡς δὲ εἶδον οἱ βάρβαροι κρεμάμενον τὸ θηρίον ἐκ τῆς χειρὸς αὐτοῦ, πρὸς ἀλλήλους ἔλεγον, “Πάντως φονεύς ἐστιν ὁ ἄνθρωπος οὗτος, ὃν διασωθέντα ἐκ τῆς θαλάσσης, ἡ δίκη ζῆν οὐκ εἴασεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 5, 'Ὁ μὲν οὖν, ἀποτινάξας τὸ θηρίον εἰς τὸ πῦρ, ἔπαθεν οὐδὲν κακόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 6, 'Οἱ δὲ προσεδόκων αὐτὸν μέλλειν πίμπρασθαι, ἢ καταπίπτειν ἄφνω νεκρόν. Ἐπὶ πολὺ δὲ, αὐτῶν προσδοκώντων καὶ θεωρούντων μηδὲν ἄτοπον εἰς αὐτὸν γινόμενον, μεταβαλόμενοι ἔλεγον αὐτὸν εἶναι θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 7, '¶Ἐν δὲ τοῖς περὶ τὸν τόπον ἐκεῖνον, ὑπῆρχεν χωρία τῷ πρώτῳ τῆς νήσου ὀνόματι Ποπλίῳ, ὃς ἀναδεξάμενος ἡμᾶς τρεῖς ἡμέρας φιλοφρόνως ἐξένισεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 8, 'Ἐγένετο δὲ, τὸν πατέρα τοῦ Ποπλίου πυρετοῖς καὶ δυσεντερίῳ συνεχόμενον κατακεῖσθαι, πρὸς ὃν ὁ Παῦλος εἰσελθὼν, καὶ προσευξάμενος, ἐπιθεὶς τὰς χεῖρας αὐτῷ, ἰάσατο αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 9, 'Τούτου δὲ γενομένου, καὶ οἱ λοιποὶ οἱ ἐν τῇ νήσῳ ἔχοντες ἀσθενείας προσήρχοντο καὶ ἐθεραπεύοντο,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 10, 'οἳ καὶ πολλαῖς τιμαῖς ἐτίμησαν ἡμᾶς, καὶ ἀναγομένοις, ἐπέθεντο τὰ πρὸς τὰς χρείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 11, '¶Μετὰ δὲ τρεῖς μῆνας, ἀνήχθημεν ἐν πλοίῳ παρακεχειμακότι ἐν τῇ νήσῳ, Ἀλεξανδρίνῳ παρασήμῳ Διοσκούροις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 12, 'Καὶ καταχθέντες εἰς Συρακούσας, ἐπεμείναμεν ἡμέρας τρεῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 13, 'ὅθεν περιελόντες, κατηντήσαμεν εἰς Ῥήγιον. Καὶ μετὰ μίαν ἡμέραν, ἐπιγενομένου νότου, δευτεραῖοι ἤλθομεν εἰς Ποτιόλους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 14, 'οὗ εὑρόντες ἀδελφοὺς, παρεκλήθημεν παρʼ αὐτοῖς ἐπιμεῖναι ἡμέρας ἑπτά. Καὶ οὕτως εἰς τὴν Ῥώμην ἤλθαμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 15, 'Κἀκεῖθεν οἱ ἀδελφοὶ ἀκούσαντες, τὰ περὶ ἡμῶν, ἦλθαν εἰς ἀπάντησιν ἡμῖν ἄχρι Ἀππίου Φόρου καὶ Τριῶν Ταβερνῶν, οὓς ἰδὼν ὁ Παῦλος, εὐχαριστήσας τῷ  ̊Θεῷ, ἔλαβε θάρσος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 16, '¶Ὅτε δὲ εἰσήλθομεν εἰς Ῥώμην, ἐπετράπη τῷ Παύλῳ μένειν καθʼ ἑαυτὸν, σὺν τῷ φυλάσσοντι αὐτὸν στρατιώτῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 17, '¶Ἐγένετο δὲ μετὰ ἡμέρας τρεῖς, συγκαλέσασθαι αὐτὸν τοὺς ὄντας τῶν Ἰουδαίων πρώτους. Συνελθόντων δὲ αὐτῶν, ἔλεγεν πρὸς αὐτούς, “Ἐγώ, Ἄνδρες, ἀδελφοί, οὐδὲν ἐναντίον ποιήσας τῷ λαῷ ἢ τοῖς ἔθεσι τοῖς πατρῴοις, δέσμιος ἐξ Ἱεροσολύμων παρεδόθην εἰς τὰς χεῖρας τῶν Ῥωμαίων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 18, 'οἵτινες ἀνακρίναντές με, ἐβούλοντο ἀπολῦσαι, διὰ τὸ μηδεμίαν αἰτίαν θανάτου ὑπάρχειν ἐν ἐμοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 19, 'Ἀντιλεγόντων δὲ τῶν Ἰουδαίων, ἠναγκάσθην ἐπικαλέσασθαι Καίσαρα, οὐχ ὡς τοῦ ἔθνους μου ἔχων τι κατηγορεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 20, 'Διὰ ταύτην οὖν τὴν αἰτίαν, παρεκάλεσα ὑμᾶς, ἰδεῖν καὶ προσλαλῆσαι, εἵνεκεν γὰρ τῆς ἐλπίδος τοῦ Ἰσραὴλ, τὴν ἅλυσιν ταύτην περίκειμαι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 21, 'Οἱ δὲ πρὸς αὐτὸν εἶπαν, “Ἡμεῖς οὔτε γράμματα περὶ σοῦ ἐδεξάμεθα ἀπὸ τῆς Ἰουδαίας, οὔτε παραγενόμενός τις τῶν ἀδελφῶν ἀπήγγειλεν ἢ ἐλάλησέν τι περὶ σοῦ πονηρόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 22, 'Ἀξιοῦμεν δὲ παρὰ σοῦ ἀκοῦσαι ἃ φρονεῖς, περὶ μὲν γὰρ τῆς αἱρέσεως ταύτης γνωστὸν ἡμῖν ἐστιν, ὅτι πανταχοῦ ἀντιλέγεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 23, '¶Ταξάμενοι δὲ αὐτῷ ἡμέραν, ἦλθον πρὸς αὐτὸν εἰς τὴν ξενίαν πλείονες, οἷς ἐξετίθετο, διαμαρτυρόμενος τὴν Βασιλείαν τοῦ  ̊Θεοῦ, πείθων τε αὐτοὺς περὶ τοῦ  ̊Ἰησοῦ, ἀπό τε τοῦ νόμου Μωϋσέως, καὶ τῶν προφητῶν, ἀπὸ πρωῒ ἕως ἑσπέρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 24, 'Καὶ οἱ μὲν ἐπείθοντο τοῖς λεγομένοις, οἱ δὲ ἠπίστουν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 25, 'Ἀσύμφωνοι δὲ ὄντες πρὸς ἀλλήλους, ἀπελύοντο, εἰπόντος τοῦ Παύλου ῥῆμα ἓν: ὅτι “Καλῶς τὸ  ̊Πνεῦμα τὸ Ἅγιον ἐλάλησεν διὰ Ἠσαΐου τοῦ προφήτου πρὸς τοὺς πατέρας ὑμῶν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 26, 'λέγων, ‘Πορεύθητι πρὸς τὸν λαὸν τοῦτον, καὶ εἰπόν, “Ἀκοῇ ἀκούσετε, καὶ οὐ μὴ συνῆτε, καὶ βλέποντες βλέψετε, καὶ οὐ μὴ ἴδητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 27, 'Ἐπαχύνθη γὰρ ἡ καρδία τοῦ λαοῦ τούτου, καὶ τοῖς ὠσὶν βαρέως ἤκουσαν, καὶ τοὺς ὀφθαλμοὺς αὐτῶν ἐκάμμυσαν, μήποτε ἴδωσιν τοῖς ὀφθαλμοῖς, καὶ τοῖς ὠσὶν ἀκούσωσιν, καὶ τῇ καρδίᾳ συνῶσιν, καὶ ἐπιστρέψωσιν, καὶ ἰάσομαι αὐτούς.”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 28, 'Γνωστὸν οὖν ἔστω, ὑμῖν ὅτι τοῖς ἔθνεσιν ἀπεστάλη τοῦτο τὸ σωτήριον τοῦ  ̊Θεοῦ, αὐτοὶ καὶ ἀκούσονται!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 29, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 30, '¶Ἐνέμεινεν δὲ διετίαν ὅλην ἐν ἰδίῳ μισθώματι, καὶ ἀπεδέχετο πάντας τοὺς εἰσπορευομένους πρὸς αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 28, 31, 'κηρύσσων τὴν Βασιλείαν τοῦ  ̊Θεοῦ, καὶ διδάσκων τὰ περὶ τοῦ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ, μετὰ πάσης παρρησίας ἀκωλύτως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, '¶Παῦλος, δοῦλος  ̊Χριστοῦ  ̊Ἰησοῦ, κλητὸς ἀπόστολος, ἀφωρισμένος εἰς εὐαγγέλιον  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'ὃ προεπηγγείλατο διὰ τῶν προφητῶν αὐτοῦ ἐν Γραφαῖς ἁγίαις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'περὶ τοῦ Υἱοῦ αὐτοῦ, τοῦ γενομένου ἐκ σπέρματος Δαυὶδ κατὰ σάρκα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'τοῦ ὁρισθέντος Υἱοῦ  ̊Θεοῦ ἐν δυνάμει κατὰ  ̊Πνεῦμα ἁγιωσύνης ἐξ ἀναστάσεως νεκρῶν,  ̊Ἰησοῦ  ̊Χριστοῦ τοῦ  ̊Κυρίου ἡμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'διʼ οὗ ἐλάβομεν χάριν καὶ ἀποστολὴν εἰς ὑπακοὴν πίστεως ἐν πᾶσιν τοῖς ἔθνεσιν ὑπὲρ τοῦ ὀνόματος αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'ἐν οἷς ἐστε καὶ ὑμεῖς κλητοὶ  ̊Ἰησοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'πᾶσιν τοῖς οὖσιν ἐν Ῥώμῃ, ἀγαπητοῖς  ̊Θεοῦ, κλητοῖς ἁγίοις: χάρις ὑμῖν καὶ εἰρήνη ἀπὸ  ̊Θεοῦ Πατρὸς ἡμῶν καὶ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, '¶Πρῶτον μὲν εὐχαριστῶ τῷ  ̊Θεῷ μου διὰ  ̊Ἰησοῦ  ̊Χριστοῦ περὶ πάντων ὑμῶν, ὅτι ἡ πίστις ὑμῶν καταγγέλλεται ἐν ὅλῳ τῷ κόσμῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Μάρτυς γάρ μού ἐστιν ὁ  ̊Θεός, ᾧ λατρεύω ἐν τῷ πνεύματί μου ἐν τῷ εὐαγγελίῳ τοῦ Υἱοῦ αὐτοῦ, ὡς ἀδιαλείπτως μνείαν ὑμῶν ποιοῦμαι');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'πάντοτε ἐπὶ τῶν προσευχῶν μου, δεόμενος εἴ πως ἤδη ποτὲ εὐοδωθήσομαι ἐν τῷ θελήματι τοῦ  ̊Θεοῦ, ἐλθεῖν πρὸς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Ἐπιποθῶ γὰρ ἰδεῖν ὑμᾶς, ἵνα τι μεταδῶ χάρισμα ὑμῖν πνευματικὸν, εἰς τὸ στηριχθῆναι ὑμᾶς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'τοῦτο δέ ἐστιν, συμπαρακληθῆναι ἐν ὑμῖν, διὰ τῆς ἐν ἀλλήλοις πίστεως, ὑμῶν τε καὶ ἐμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Οὐ θέλω δὲ ὑμᾶς ἀγνοεῖν, ἀδελφοί, ὅτι πολλάκις προεθέμην ἐλθεῖν πρὸς ὑμᾶς, καὶ ἐκωλύθην ἄχρι τοῦ δεῦρο, ἵνα τινὰ καρπὸν σχῶ καὶ ἐν ὑμῖν, καθὼς καὶ ἐν τοῖς λοιποῖς ἔθνεσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 14, 'Ἕλλησίν τε καὶ βαρβάροις, σοφοῖς τε καὶ ἀνοήτοις, ὀφειλέτης εἰμί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 15, 'Οὕτως τὸ κατʼ ἐμὲ, πρόθυμον καὶ ὑμῖν τοῖς ἐν Ῥώμῃ εὐαγγελίσασθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 16, '¶Οὐ γὰρ ἐπαισχύνομαι τὸ εὐαγγέλιον, δύναμις γὰρ  ̊Θεοῦ ἐστιν εἰς σωτηρίαν παντὶ τῷ πιστεύοντι, Ἰουδαίῳ τε πρῶτον καὶ Ἕλληνι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 17, 'Δικαιοσύνη γὰρ  ̊Θεοῦ ἐν αὐτῷ ἀποκαλύπτεται, ἐκ πίστεως εἰς πίστιν, καθὼς γέγραπται, “Ὁ δὲ δίκαιος ἐκ πίστεως ζήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 18, '¶Ἀποκαλύπτεται γὰρ ὀργὴ  ̊Θεοῦ ἀπʼ οὐρανοῦ, ἐπὶ πᾶσαν ἀσέβειαν καὶ ἀδικίαν ἀνθρώπων, τῶν τὴν ἀλήθειαν ἐν ἀδικίᾳ κατεχόντων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 19, 'διότι τὸ γνωστὸν τοῦ  ̊Θεοῦ, φανερόν ἐστιν ἐν αὐτοῖς, ὁ  ̊Θεὸς γὰρ αὐτοῖς ἐφανέρωσεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 20, 'Τὰ γὰρ ἀόρατα αὐτοῦ ἀπὸ κτίσεως κόσμου, τοῖς ποιήμασιν νοούμενα, καθορᾶται, ἥ τε ἀΐδιος αὐτοῦ δύναμις καὶ θειότης, εἰς τὸ εἶναι αὐτοὺς ἀναπολογήτους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 21, 'Διότι γνόντες τὸν  ̊Θεὸν, οὐχ ὡς  ̊Θεὸν ἐδόξασαν ἢ ηὐχαρίστησαν, ἀλλʼ ἐματαιώθησαν ἐν τοῖς διαλογισμοῖς αὐτῶν, καὶ ἐσκοτίσθη ἡ ἀσύνετος αὐτῶν καρδία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 22, 'Φάσκοντες εἶναι σοφοὶ, ἐμωράνθησαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 23, 'καὶ ἤλλαξαν τὴν δόξαν τοῦ ἀφθάρτου  ̊Θεοῦ ἐν ὁμοιώματι εἰκόνος φθαρτοῦ ἀνθρώπου, καὶ πετεινῶν, καὶ τετραπόδων, καὶ ἑρπετῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 24, '¶Διὸ παρέδωκεν αὐτοὺς ὁ  ̊Θεὸς ἐν ταῖς ἐπιθυμίαις τῶν καρδιῶν αὐτῶν εἰς ἀκαθαρσίαν, τοῦ ἀτιμάζεσθαι τὰ σώματα αὐτῶν ἐν αὐτοῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 25, 'οἵτινες μετήλλαξαν τὴν ἀλήθειαν τοῦ  ̊Θεοῦ ἐν τῷ ψεύδει, καὶ ἐσεβάσθησαν καὶ ἐλάτρευσαν τῇ κτίσει παρὰ τὸν κτίσαντα, ὅς ἐστιν εὐλογητὸς εἰς τοὺς αἰῶνας. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 26, '¶Διὰ τοῦτο, παρέδωκεν αὐτοὺς ὁ  ̊Θεὸς εἰς πάθη ἀτιμίας· αἵ τε γὰρ θήλειαι αὐτῶν μετήλλαξαν τὴν φυσικὴν χρῆσιν εἰς τὴν παρὰ φύσιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 27, 'ὁμοίως τε καὶ οἱ ἄρσενες ἀφέντες τὴν φυσικὴν χρῆσιν τῆς θηλείας, ἐξεκαύθησαν ἐν τῇ ὀρέξει αὐτῶν εἰς ἀλλήλους, ἄρσενες ἐν ἄρσεσιν τὴν ἀσχημοσύνην κατεργαζόμενοι, καὶ τὴν ἀντιμισθίαν ἣν ἔδει τῆς πλάνης αὐτῶν, ἐν ἑαυτοῖς ἀπολαμβάνοντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 28, '¶Καὶ καθὼς οὐκ ἐδοκίμασαν τὸν  ̊Θεὸν ἔχειν ἐν ἐπιγνώσει, παρέδωκεν αὐτοὺς ὁ  ̊Θεὸς εἰς ἀδόκιμον νοῦν, ποιεῖν τὰ μὴ καθήκοντα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 29, 'πεπληρωμένους πάσῃ ἀδικίᾳ, πονηρίᾳ, πλεονεξίᾳ, κακίᾳ, μεστοὺς φθόνου, φόνου, ἔριδος, δόλου, κακοηθείας, ψιθυριστάς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 30, 'καταλάλους, θεοστυγεῖς, ὑβριστάς, ὑπερηφάνους, ἀλαζόνας, ἐφευρετὰς κακῶν, γονεῦσιν ἀπειθεῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 31, 'ἀσυνέτους, ἀσυνθέτους, ἀστόργους, ἀνελεήμονας·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 32, 'οἵτινες τὸ δικαίωμα τοῦ  ̊Θεοῦ ἐπιγνόντες ὅτι οἱ τὰ τοιαῦτα πράσσοντες ἄξιοι θανάτου εἰσίν, οὐ μόνον αὐτὰ ποιοῦσιν, ἀλλὰ καὶ συνευδοκοῦσιν τοῖς πράσσουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 1, '¶Διὸ ἀναπολόγητος εἶ, ὦ ἄνθρωπε, πᾶς ὁ κρίνων, ἐν ᾧ γὰρ κρίνεις τὸν ἕτερον, σεαυτὸν κατακρίνεις, τὰ γὰρ αὐτὰ πράσσεις, ὁ κρίνων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 2, 'Οἴδαμεν δὲ ὅτι τὸ κρίμα τοῦ  ̊Θεοῦ ἐστιν κατὰ ἀλήθειαν ἐπὶ τοὺς τὰ τοιαῦτα πράσσοντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 3, 'Λογίζῃ δὲ τοῦτο, ὦ ἄνθρωπε, ὁ κρίνων τοὺς τὰ τοιαῦτα πράσσοντας, καὶ ποιῶν αὐτά, ὅτι σὺ ἐκφεύξῃ τὸ κρίμα τοῦ  ̊Θεοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 4, 'Ἢ τοῦ πλούτου τῆς χρηστότητος αὐτοῦ, καὶ τῆς ἀνοχῆς, καὶ τῆς μακροθυμίας καταφρονεῖς, ἀγνοῶν ὅτι τὸ χρηστὸν τοῦ  ̊Θεοῦ, εἰς μετάνοιάν σε ἄγει;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 5, 'Κατὰ δὲ τὴν σκληρότητά σου καὶ ἀμετανόητον καρδίαν, θησαυρίζεις σεαυτῷ ὀργὴν ἐν ἡμέρᾳ ὀργῆς καὶ ἀποκαλύψεως δικαιοκρισίας τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 6, '“ὃς ἀποδώσει ἑκάστῳ κατὰ τὰ ἔργα αὐτοῦ”:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 7, 'τοῖς μὲν καθʼ ὑπομονὴν ἔργου ἀγαθοῦ, δόξαν καὶ τιμὴν καὶ ἀφθαρσίαν ζητοῦσιν, ζωὴν αἰώνιον·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 8, 'τοῖς δὲ ἐξ ἐριθείας καὶ ἀπειθοῦσι τῇ ἀληθείᾳ, πειθομένοις δὲ τῇ ἀδικίᾳ, ὀργὴ καὶ θυμός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 9, 'Θλῖψις καὶ στενοχωρία, ἐπὶ πᾶσαν ψυχὴν ἀνθρώπου τοῦ κατεργαζομένου τὸ κακόν, Ἰουδαίου τε πρῶτον καὶ Ἕλληνος·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 10, 'δόξα δὲ, καὶ τιμὴ, καὶ εἰρήνη, παντὶ τῷ ἐργαζομένῳ τὸ ἀγαθόν, Ἰουδαίῳ τε πρῶτον καὶ Ἕλληνι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 11, 'Οὐ γάρ ἐστιν προσωπολημψία παρὰ τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 12, '¶Ὅσοι γὰρ ἀνόμως ἥμαρτον, ἀνόμως καὶ ἀπολοῦνται· καὶ ὅσοι ἐν νόμῳ ἥμαρτον, διὰ νόμου κριθήσονται·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 13, 'οὐ γὰρ οἱ ἀκροαταὶ νόμου δίκαιοι παρὰ τῷ  ̊Θεῷ, ἀλλʼ οἱ ποιηταὶ νόμου δικαιωθήσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 14, 'Ὅταν γὰρ ἔθνη τὰ μὴ νόμον ἔχοντα, φύσει τὰ τοῦ νόμου ποιῶσιν, οὗτοι νόμον μὴ ἔχοντες, ἑαυτοῖς εἰσιν νόμος·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 15, 'οἵτινες ἐνδείκνυνται τὸ ἔργον τοῦ νόμου, γραπτὸν ἐν ταῖς καρδίαις αὐτῶν, συμμαρτυρούσης αὐτῶν τῆς συνειδήσεως, καὶ μεταξὺ ἀλλήλων, τῶν λογισμῶν κατηγορούντων ἢ καὶ ἀπολογουμένων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 16, 'ἐν ᾗ ἡμέρᾳ κρίνει ὁ  ̊Θεὸς τὰ κρυπτὰ τῶν ἀνθρώπων, κατὰ τὸ εὐαγγέλιόν μου, διὰ  ̊Χριστοῦ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 17, '¶Εἰ δὲ σὺ Ἰουδαῖος ἐπονομάζῃ, καὶ ἐπαναπαύῃ νόμῳ, καὶ καυχᾶσαι ἐν  ̊Θεῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 18, 'καὶ γινώσκεις τὸ θέλημα, καὶ δοκιμάζεις τὰ διαφέροντα, κατηχούμενος ἐκ τοῦ νόμου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 19, 'πέποιθάς τε σεαυτὸν ὁδηγὸν εἶναι τυφλῶν, φῶς τῶν ἐν σκότει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 20, 'παιδευτὴν ἀφρόνων, διδάσκαλον νηπίων, ἔχοντα τὴν μόρφωσιν τῆς γνώσεως καὶ τῆς ἀληθείας ἐν τῷ νόμῳ–');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 21, 'ὁ οὖν διδάσκων ἕτερον, σεαυτὸν οὐ διδάσκεις; Ὁ κηρύσσων μὴ κλέπτειν, κλέπτεις;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 22, 'Ὁ λέγων μὴ μοιχεύειν, μοιχεύεις; Ὁ βδελυσσόμενος τὰ εἴδωλα, ἱεροσυλεῖς;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 23, 'Ὃς ἐν νόμῳ καυχᾶσαι διὰ τῆς παραβάσεως τοῦ νόμου, τὸν  ̊Θεὸν ἀτιμάζεις;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 24, '“Τὸ γὰρ ὄνομα τοῦ  ̊Θεοῦ διʼ ὑμᾶς βλασφημεῖται ἐν τοῖς ἔθνεσιν”, καθὼς γέγραπται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 25, '¶Περιτομὴ μὲν γὰρ ὠφελεῖ, ἐὰν νόμον πράσσῃς· ἐὰν δὲ παραβάτης νόμου ᾖς, ἡ περιτομή σου, ἀκροβυστία γέγονεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 26, 'Ἐὰν οὖν ἡ ἀκροβυστία, τὰ δικαιώματα τοῦ νόμου φυλάσσῃ, οὐχ ἡ ἀκροβυστία αὐτοῦ εἰς περιτομὴν λογισθήσεται;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 27, 'Καὶ κρινεῖ ἡ ἐκ φύσεως ἀκροβυστία, τὸν νόμον τελοῦσα, σὲ τὸν διὰ γράμματος καὶ περιτομῆς παραβάτην νόμου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 28, 'Οὐ γὰρ ὁ ἐν τῷ φανερῷ Ἰουδαῖός ἐστιν, οὐδὲ ἡ ἐν τῷ φανερῷ ἐν σαρκὶ περιτομή·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 29, 'ἀλλʼ ὁ ἐν τῷ κρυπτῷ Ἰουδαῖος, καὶ περιτομὴ καρδίας, ἐν  ̊Πνεύματι, οὐ γράμματι, οὗ ὁ ἔπαινος οὐκ ἐξ ἀνθρώπων, ἀλλʼ ἐκ τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 1, '¶Τί οὖν τὸ περισσὸν τοῦ Ἰουδαίου, ἢ τίς ἡ ὠφέλεια τῆς περιτομῆς;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 2, 'Πολὺ κατὰ πάντα τρόπον. Πρῶτον μὲν γὰρ ὅτι ἐπιστεύθησαν τὰ λόγια τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 3, 'Τί γάρ εἰ ἠπίστησάν τινες; Μὴ ἡ ἀπιστία αὐτῶν, τὴν πίστιν τοῦ  ̊Θεοῦ καταργήσει;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 4, 'Μὴ γένοιτο! Γινέσθω δὲ ὁ  ̊Θεὸς ἀληθής, πᾶς δὲ ἄνθρωπος ψεύστης, καθάπερ γέγραπται, “Ὅπως ἂν δικαιωθῇς ἐν τοῖς λόγοις σου, καὶ νικήσεις ἐν τῷ κρίνεσθαί σε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 5, 'Εἰ δὲ ἡ ἀδικία ἡμῶν,  ̊Θεοῦ δικαιοσύνην συνίστησιν, τί ἐροῦμεν; Μὴ ἄδικος ὁ  ̊Θεὸς, ὁ ἐπιφέρων τὴν ὀργήν; (Κατὰ ἄνθρωπον λέγω.)');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 6, 'Μὴ γένοιτο! Ἐπεὶ πῶς κρινεῖ ὁ  ̊Θεὸς τὸν κόσμον;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 7, 'Εἰ δὲ ἡ ἀλήθεια τοῦ  ̊Θεοῦ ἐν τῷ ἐμῷ ψεύσματι ἐπερίσσευσεν εἰς τὴν δόξαν αὐτοῦ, τί ἔτι κἀγὼ ὡς ἁμαρτωλὸς κρίνομαι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 8, 'Καὶ μὴ καθὼς βλασφημούμεθα, καὶ καθώς φασίν τινες ἡμᾶς λέγειν, ὅτι “Ποιήσωμεν τὰ κακὰ, ἵνα ἔλθῃ τὰ ἀγαθά;” Ὧν τὸ κρίμα ἔνδικόν ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 9, '¶Τί οὖν; Προεχόμεθα; Οὐ πάντως, προῃτιασάμεθα γὰρ, Ἰουδαίους τε καὶ Ἕλληνας, πάντας ὑφʼ ἁμαρτίαν εἶναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 10, 'Καθὼς γέγραπται, ὅτι “Οὐκ ἔστιν δίκαιος, οὐδὲ εἷς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 11, 'οὐκ ἔστιν συνίων, οὐκ ἔστιν ὁ ἐκζητῶν τὸν  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 12, 'Πάντες ἐξέκλιναν, ἅμα ἠχρεώθησαν· οὐκ ἔστιν ποιῶν χρηστότητα, οὐκ ἔστιν ἕως ἑνός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 13, '“Τάφος ἀνεῳγμένος ὁ λάρυγξ αὐτῶν, ταῖς γλώσσαις αὐτῶν ἐδολιοῦσαν”, “Ἰὸς ἀσπίδων ὑπὸ τὰ χείλη αὐτῶν”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 14, '“Ὧν τὸ στόμα ἀρᾶς καὶ πικρίας γέμει”·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 15, '“Ὀξεῖς οἱ πόδες αὐτῶν, ἐκχέαι αἷμα...');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 16, 'σύντριμμα καὶ ταλαιπωρία ἐν ταῖς ὁδοῖς αὐτῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 17, 'καὶ ὁδὸν εἰρήνης οὐκ ἔγνωσαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 18, '“Οὐκ ἔστιν φόβος  ̊Θεοῦ ἀπέναντι τῶν ὀφθαλμῶν αὐτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 19, '¶Οἴδαμεν δὲ ὅτι ὅσα ὁ νόμος λέγει, τοῖς ἐν τῷ νόμῳ λαλεῖ, ἵνα πᾶν στόμα φραγῇ, καὶ ὑπόδικος γένηται πᾶς ὁ κόσμος τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 20, 'Διότι ἐξ ἔργων νόμου, οὐ δικαιωθήσεται πᾶσα σὰρξ ἐνώπιον αὐτοῦ, διὰ γὰρ νόμου ἐπίγνωσις ἁμαρτίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 21, '¶Νυνὶ δὲ χωρὶς νόμου, δικαιοσύνη  ̊Θεοῦ πεφανέρωται, μαρτυρουμένη ὑπὸ τοῦ νόμου καὶ τῶν προφητῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 22, 'δικαιοσύνη δὲ  ̊Θεοῦ διὰ πίστεως  ̊Ἰησοῦ  ̊Χριστοῦ, εἰς πάντας τοὺς πιστεύοντας, οὐ γάρ ἐστιν διαστολή.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 23, 'Πάντες γὰρ ἥμαρτον καὶ ὑστεροῦνται τῆς δόξης τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 24, 'δικαιούμενοι δωρεὰν τῇ αὐτοῦ χάριτι, διὰ τῆς ἀπολυτρώσεως τῆς ἐν  ̊Χριστῷ  ̊Ἰησοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 25, 'ὃν προέθετο ὁ  ̊Θεὸς ἱλαστήριον, διὰ τῆς πίστεως ἐν τῷ αὐτοῦ αἵματι, εἰς ἔνδειξιν τῆς δικαιοσύνης αὐτοῦ, διὰ τὴν πάρεσιν τῶν προγεγονότων ἁμαρτημάτων');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 26, 'ἐν τῇ ἀνοχῇ τοῦ  ̊Θεοῦ, πρὸς τὴν ἔνδειξιν τῆς δικαιοσύνης αὐτοῦ ἐν τῷ νῦν καιρῷ, εἰς τὸ εἶναι αὐτὸν δίκαιον καὶ δικαιοῦντα τὸν ἐκ πίστεως  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 27, '¶Ποῦ οὖν ἡ καύχησις; Ἐξεκλείσθη. Διὰ ποίου νόμου; Τῶν ἔργων; Οὐχί, ἀλλὰ διὰ νόμου πίστεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 28, 'Λογιζόμεθα οὖν δικαιοῦσθαι πίστει ἄνθρωπον, χωρὶς ἔργων νόμου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 29, 'Ἢ Ἰουδαίων ὁ  ̊Θεὸς μόνον; Οὐχὶ καὶ ἐθνῶν; Ναὶ, καὶ ἐθνῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 30, 'εἴπερ εἷς ὁ  ̊Θεός, ὃς δικαιώσει περιτομὴν ἐκ πίστεως, καὶ ἀκροβυστίαν διὰ τῆς πίστεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 31, 'Νόμον οὖν καταργοῦμεν διὰ τῆς πίστεως; Μὴ γένοιτο! Ἀλλὰ νόμον ἱστάνομεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 1, '¶Τί οὖν ἐροῦμεν, εὑρηκέναι Ἀβραὰμ τὸν προπάτορα ἡμῶν κατὰ σάρκα;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 2, 'Εἰ γὰρ Ἀβραὰμ ἐξ ἔργων ἐδικαιώθη, ἔχει καύχημα, ἀλλʼ οὐ πρὸς  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 3, 'Τί γὰρ ἡ Γραφὴ λέγει; “Ἐπίστευσεν δὲ Ἀβραὰμ τῷ  ̊Θεῷ, καὶ ἐλογίσθη αὐτῷ εἰς δικαιοσύνην.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 4, 'Τῷ δὲ ἐργαζομένῳ, ὁ μισθὸς οὐ λογίζεται κατὰ χάριν, ἀλλὰ κατὰ ὀφείλημα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 5, 'Τῷ δὲ μὴ ἐργαζομένῳ, πιστεύοντι δὲ ἐπὶ τὸν δικαιοῦντα τὸν ἀσεβῆ, λογίζεται ἡ πίστις αὐτοῦ εἰς δικαιοσύνην,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 6, 'καθάπερ καὶ Δαυὶδ λέγει τὸν μακαρισμὸν τοῦ ἀνθρώπου ᾧ ὁ  ̊Θεὸς λογίζεται δικαιοσύνην χωρὶς ἔργων:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 7, '“Μακάριοι, ὧν ἀφέθησαν αἱ ἀνομίαι καὶ ὧν ἐπεκαλύφθησαν αἱ ἁμαρτίαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 8, 'Μακάριος ἀνὴρ, οὗ οὐ μὴ λογίσηται  ̊Κύριος ἁμαρτίαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 9, '¶Ὁ μακαρισμὸς οὖν οὗτος ἐπὶ τὴν περιτομὴν, ἢ καὶ ἐπὶ τὴν ἀκροβυστίαν; Λέγομεν γάρ, “Ἐλογίσθη τῷ Ἀβραὰμ ἡ πίστις εἰς δικαιοσύνην.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 10, 'Πῶς οὖν ἐλογίσθη; Ἐν περιτομῇ ὄντι, ἢ ἐν ἀκροβυστίᾳ; Οὐκ ἐν περιτομῇ, ἀλλʼ ἐν ἀκροβυστίᾳ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 11, 'καὶ σημεῖον ἔλαβεν περιτομῆς, σφραγῖδα τῆς δικαιοσύνης τῆς πίστεως τῆς ἐν τῇ ἀκροβυστίᾳ, εἰς τὸ εἶναι αὐτὸν πατέρα πάντων τῶν πιστευόντων διʼ ἀκροβυστίας, εἰς τὸ λογισθῆναι αὐτοῖς τὴν δικαιοσύνην,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 12, 'καὶ πατέρα περιτομῆς τοῖς οὐκ ἐκ περιτομῆς μόνον, ἀλλὰ καὶ τοῖς στοιχοῦσιν τοῖς ἴχνεσιν τῆς ἐν ἀκροβυστίᾳ πίστεως, τοῦ πατρὸς ἡμῶν Ἀβραάμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 13, '¶Οὐ γὰρ διὰ νόμου ἡ ἐπαγγελία τῷ Ἀβραὰμ ἢ τῷ σπέρματι αὐτοῦ, τὸ κληρονόμον αὐτὸν εἶναι κόσμου, ἀλλὰ διὰ δικαιοσύνης πίστεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 14, 'Εἰ γὰρ οἱ ἐκ νόμου κληρονόμοι, κεκένωται ἡ πίστις καὶ κατήργηται ἡ ἐπαγγελία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 15, 'Ὁ γὰρ νόμος ὀργὴν κατεργάζεται, οὗ δὲ οὐκ ἔστιν νόμος, οὐδὲ παράβασις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 16, '¶Διὰ τοῦτο ἐκ πίστεως, ἵνα κατὰ χάριν, εἰς τὸ εἶναι βεβαίαν, τὴν ἐπαγγελίαν παντὶ τῷ σπέρματι, οὐ τῷ ἐκ τοῦ νόμου μόνον, ἀλλὰ καὶ τῷ ἐκ πίστεως Ἀβραάμ, ὅς ἐστιν πατὴρ πάντων ἡμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 17, 'καθὼς γέγραπται, ὅτι “Πατέρα πολλῶν ἐθνῶν τέθεικά σε”, κατέναντι οὗ ἐπίστευσεν,  ̊Θεοῦ τοῦ ζῳοποιοῦντος τοὺς νεκροὺς, καὶ καλοῦντος τὰ μὴ ὄντα ὡς ὄντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 18, 'Ὃς παρʼ ἐλπίδα, ἐπʼ ἐλπίδι ἐπίστευσεν, εἰς τὸ γενέσθαι αὐτὸν πατέρα πολλῶν ἐθνῶν, κατὰ τὸ εἰρημένον, “Οὕτως ἔσται τὸ σπέρμα σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 19, 'Καὶ μὴ ἀσθενήσας τῇ πίστει, κατενόησεν τὸ ἑαυτοῦ σῶμα ἤδη νενεκρωμένον, ἑκατονταετής που ὑπάρχων, καὶ τὴν νέκρωσιν τῆς μήτρας Σάρρας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 20, 'εἰς δὲ τὴν ἐπαγγελίαν τοῦ  ̊Θεοῦ, οὐ διεκρίθη τῇ ἀπιστίᾳ, ἀλλʼ ἐνεδυναμώθη τῇ πίστει, δοὺς δόξαν τῷ  ̊Θεῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 21, 'καὶ πληροφορηθεὶς ὅτι ὃ ἐπήγγελται, δυνατός ἐστιν καὶ ποιῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 22, 'Διὸ καὶ “ἐλογίσθη αὐτῷ εἰς δικαιοσύνην”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 23, 'Οὐκ ἐγράφη δὲ διʼ αὐτὸν μόνον, ὅτι ἐλογίσθη αὐτῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 24, 'ἀλλὰ καὶ διʼ ἡμᾶς, οἷς μέλλει λογίζεσθαι, τοῖς πιστεύουσιν ἐπὶ τὸν ἐγείραντα  ̊Ἰησοῦν, τὸν  ̊Κύριον ἡμῶν, ἐκ νεκρῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 25, 'ὃς παρεδόθη διὰ τὰ παραπτώματα ἡμῶν, καὶ ἠγέρθη διὰ τὴν δικαίωσιν ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 1, '¶Δικαιωθέντες οὖν ἐκ πίστεως, εἰρήνην ἔχωμεν πρὸς τὸν  ̊Θεὸν, διὰ τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 2, 'διʼ οὗ καὶ τὴν προσαγωγὴν ἐσχήκαμεν, τῇ πίστει εἰς τὴν χάριν ταύτην, ἐν ᾗ ἑστήκαμεν, καὶ καυχώμεθα ἐπʼ ἐλπίδι τῆς δόξης τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 3, 'Οὐ μόνον δέ, ἀλλὰ καὶ καυχώμεθα ἐν ταῖς θλίψεσιν, εἰδότες ὅτι ἡ θλῖψις ὑπομονὴν κατεργάζεται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 4, 'ἡ δὲ ὑπομονὴ δοκιμήν, ἡ δὲ δοκιμὴ ἐλπίδα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 5, 'Ἡ δὲ ἐλπὶς οὐ καταισχύνει, ὅτι ἡ ἀγάπη τοῦ  ̊Θεοῦ ἐκκέχυται ἐν ταῖς καρδίαις ἡμῶν διὰ  ̊Πνεύματος Ἁγίου, τοῦ δοθέντος ἡμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 6, '¶Ἔτι γὰρ  ̊Χριστὸς, ὄντων ἡμῶν ἀσθενῶν ἔτι, κατὰ καιρὸν ὑπὲρ ἀσεβῶν ἀπέθανεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 7, 'Μόλις γὰρ ὑπὲρ δικαίου τις ἀποθανεῖται· ὑπὲρ γὰρ τοῦ ἀγαθοῦ, τάχα τις καὶ τολμᾷ ἀποθανεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 8, 'Συνίστησιν δὲ τὴν ἑαυτοῦ ἀγάπην εἰς ἡμᾶς ὁ  ̊Θεὸς, ὅτι ἔτι ἁμαρτωλῶν ὄντων ἡμῶν,  ̊Χριστὸς ὑπὲρ ἡμῶν ἀπέθανεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 9, 'Πολλῷ οὖν μᾶλλον δικαιωθέντες νῦν ἐν τῷ αἵματι αὐτοῦ, σωθησόμεθα διʼ αὐτοῦ ἀπὸ τῆς ὀργῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 10, 'Εἰ γὰρ ἐχθροὶ ὄντες, κατηλλάγημεν τῷ  ̊Θεῷ διὰ τοῦ θανάτου τοῦ Υἱοῦ αὐτοῦ, πολλῷ μᾶλλον καταλλαγέντες, σωθησόμεθα ἐν τῇ ζωῇ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 11, 'Οὐ μόνον δέ, ἀλλὰ καὶ καυχώμενοι ἐν τῷ  ̊Θεῷ, διὰ τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, διʼ οὗ νῦν τὴν καταλλαγὴν ἐλάβομεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 12, '¶Διὰ τοῦτο, ὥσπερ διʼ ἑνὸς ἀνθρώπου ἡ ἁμαρτία εἰς τὸν κόσμον εἰσῆλθεν, καὶ διὰ τῆς ἁμαρτίας ὁ θάνατος, καὶ οὕτως εἰς πάντας ἀνθρώπους ὁ θάνατος διῆλθεν, ἐφʼ ᾧ πάντες ἥμαρτον–');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 13, 'ἄχρι γὰρ νόμου, ἁμαρτία ἦν ἐν κόσμῳ, ἁμαρτία δὲ οὐκ ἐλλογεῖται, μὴ ὄντος νόμου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 14, 'Ἀλλʼ ἐβασίλευσεν ὁ θάνατος ἀπὸ Ἀδὰμ μέχρι Μωϋσέως, καὶ ἐπὶ τοὺς μὴ ἁμαρτήσαντας ἐπὶ τῷ ὁμοιώματι τῆς παραβάσεως Ἀδάμ, ὅς ἐστιν τύπος τοῦ μέλλοντος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 15, '¶Ἀλλʼ οὐχ ὡς τὸ παράπτωμα, οὕτως καὶ τὸ χάρισμα. Εἰ γὰρ τῷ τοῦ ἑνὸς παραπτώματι, οἱ πολλοὶ ἀπέθανον, πολλῷ μᾶλλον ἡ χάρις τοῦ  ̊Θεοῦ καὶ ἡ δωρεὰ ἐν χάριτι, τῇ τοῦ ἑνὸς ἀνθρώπου,  ̊Ἰησοῦ  ̊Χριστοῦ, εἰς τοὺς πολλοὺς ἐπερίσσευσεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 16, 'Καὶ οὐχ ὡς διʼ ἑνὸς ἁμαρτήσαντος, τὸ δώρημα· τὸ μὲν γὰρ κρίμα ἐξ ἑνὸς, εἰς κατάκριμα, τὸ δὲ χάρισμα ἐκ πολλῶν παραπτωμάτων, εἰς δικαίωμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 17, 'Εἰ γὰρ τῷ τοῦ ἑνὸς παραπτώματι, ὁ θάνατος ἐβασίλευσεν διὰ τοῦ ἑνός, πολλῷ μᾶλλον οἱ τὴν περισσείαν τῆς χάριτος καὶ τῆς δωρεᾶς τῆς δικαιοσύνης λαμβάνοντες, ἐν ζωῇ βασιλεύσουσιν, διὰ τοῦ ἑνὸς,  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 18, '¶Ἄρα οὖν ὡς διʼ ἑνὸς παραπτώματος, εἰς πάντας ἀνθρώπους εἰς κατάκριμα, οὕτως καὶ διʼ ἑνὸς δικαιώματος, εἰς πάντας ἀνθρώπους εἰς δικαίωσιν ζωῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 19, 'Ὥσπερ γὰρ διὰ τῆς παρακοῆς τοῦ ἑνὸς ἀνθρώπου, ἁμαρτωλοὶ κατεστάθησαν οἱ πολλοί, οὕτως καὶ διὰ τῆς ὑπακοῆς τοῦ ἑνὸς, δίκαιοι κατασταθήσονται οἱ πολλοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 20, 'Νόμος δὲ παρεισῆλθεν, ἵνα πλεονάσῃ τὸ παράπτωμα· οὗ δὲ ἐπλεόνασεν ἡ ἁμαρτία, ὑπερεπερίσσευσεν ἡ χάρις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 21, 'ἵνα ὥσπερ ἐβασίλευσεν ἡ ἁμαρτία ἐν τῷ θανάτῳ, οὕτως καὶ ἡ χάρις βασιλεύσῃ διὰ δικαιοσύνης, εἰς ζωὴν αἰώνιον διὰ  ̊Ἰησοῦ  ̊Χριστοῦ τοῦ  ̊Κυρίου ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 1, '¶Τί οὖν ἐροῦμεν; Ἐπιμένωμεν τῇ ἁμαρτίᾳ, ἵνα ἡ χάρις πλεονάσῃ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 2, 'Μὴ γένοιτο! Οἵτινες ἀπεθάνομεν τῇ ἁμαρτίᾳ, πῶς ἔτι ζήσομεν ἐν αὐτῇ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 3, 'Ἢ ἀγνοεῖτε, ὅτι ὅσοι ἐβαπτίσθημεν εἰς  ̊Χριστὸν  ̊Ἰησοῦν, εἰς τὸν θάνατον αὐτοῦ ἐβαπτίσθημεν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 4, 'Συνετάφημεν οὖν αὐτῷ διὰ τοῦ βαπτίσματος εἰς τὸν θάνατον, ἵνα ὥσπερ ἠγέρθη  ̊Χριστὸς ἐκ νεκρῶν διὰ τῆς δόξης τοῦ Πατρός, οὕτως καὶ ἡμεῖς ἐν καινότητι ζωῆς περιπατήσωμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 5, '¶Εἰ γὰρ σύμφυτοι γεγόναμεν τῷ ὁμοιώματι τοῦ θανάτου αὐτοῦ, ἀλλὰ καὶ τῆς ἀναστάσεως ἐσόμεθα·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 6, 'τοῦτο γινώσκοντες ὅτι ὁ παλαιὸς ἡμῶν ἄνθρωπος συνεσταυρώθη, ἵνα καταργηθῇ τὸ σῶμα τῆς ἁμαρτίας, τοῦ μηκέτι δουλεύειν ἡμᾶς τῇ ἁμαρτίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 7, 'Ὁ γὰρ ἀποθανὼν, δεδικαίωται ἀπὸ τῆς ἁμαρτίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 8, 'Εἰ δὲ ἀπεθάνομεν σὺν  ̊Χριστῷ, πιστεύομεν ὅτι καὶ συζήσομεν αὐτῷ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 9, 'εἰδότες ὅτι  ̊Χριστὸς ἐγερθεὶς ἐκ νεκρῶν, οὐκέτι ἀποθνῄσκει, θάνατος αὐτοῦ οὐκέτι κυριεύει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 10, 'Ὃ γὰρ ἀπέθανεν, τῇ ἁμαρτίᾳ ἀπέθανεν ἐφάπαξ· ὃ δὲ ζῇ, ζῇ τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 11, 'Οὕτως καὶ ὑμεῖς, λογίζεσθε ἑαυτοὺς εἶναι νεκροὺς μὲν τῇ ἁμαρτίᾳ, ζῶντας δὲ τῷ  ̊Θεῷ ἐν  ̊Χριστῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 12, '¶Μὴ οὖν βασιλευέτω ἡ ἁμαρτία ἐν τῷ θνητῷ ὑμῶν σώματι, εἰς τὸ ὑπακούειν ταῖς ἐπιθυμίαις αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 13, 'Μηδὲ παριστάνετε τὰ μέλη ὑμῶν, ὅπλα ἀδικίας τῇ ἁμαρτίᾳ, ἀλλὰ παραστήσατε ἑαυτοὺς τῷ  ̊Θεῷ, ὡσεὶ ἐκ νεκρῶν ζῶντας, καὶ τὰ μέλη ὑμῶν, ὅπλα δικαιοσύνης τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 14, 'Ἁμαρτία γὰρ ὑμῶν οὐ κυριεύσει, οὐ γάρ ἐστε ὑπὸ νόμον, ἀλλὰ ὑπὸ χάριν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 15, '¶Τί οὖν; Ἁμαρτήσωμεν ὅτι οὐκ ἐσμὲν ὑπὸ νόμον, ἀλλὰ ὑπὸ χάριν; Μὴ γένοιτο!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 16, 'Οὐκ οἴδατε ὅτι ᾧ παριστάνετε ἑαυτοὺς δούλους εἰς ὑπακοήν, δοῦλοί ἐστε ᾧ ὑπακούετε– ἤτοι ἁμαρτίας εἰς θάνατον, ἢ ὑπακοῆς εἰς δικαιοσύνην;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 17, 'Χάρις δὲ τῷ  ̊Θεῷ, ὅτι ἦτε δοῦλοι τῆς ἁμαρτίας, ὑπηκούσατε δὲ ἐκ καρδίας, εἰς ὃν παρεδόθητε τύπον διδαχῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 18, 'Ἐλευθερωθέντες δὲ ἀπὸ τῆς ἁμαρτίας, ἐδουλώθητε τῇ δικαιοσύνῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 19, 'Ἀνθρώπινον λέγω, διὰ τὴν ἀσθένειαν τῆς σαρκὸς ὑμῶν. Ὥσπερ γὰρ παρεστήσατε τὰ μέλη ὑμῶν δοῦλα τῇ ἀκαθαρσίᾳ, καὶ τῇ ἀνομίᾳ εἰς τὴν ἀνομίαν, οὕτως νῦν παραστήσατε τὰ μέλη ὑμῶν, δοῦλα τῇ δικαιοσύνῃ εἰς ἁγιασμόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 20, '¶Ὅτε γὰρ δοῦλοι ἦτε τῆς ἁμαρτίας, ἐλεύθεροι ἦτε τῇ δικαιοσύνῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 21, 'Τίνα οὖν καρπὸν εἴχετε τότε, ἐφʼ οἷς νῦν ἐπαισχύνεσθε; Τὸ γὰρ τέλος ἐκείνων θάνατος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 22, 'Νυνὶ δέ, ἐλευθερωθέντες ἀπὸ τῆς ἁμαρτίας, δουλωθέντες δὲ τῷ  ̊Θεῷ, ἔχετε τὸν καρπὸν ὑμῶν εἰς ἁγιασμόν, τὸ δὲ τέλος ζωὴν αἰώνιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 23, 'Τὰ γὰρ ὀψώνια τῆς ἁμαρτίας θάνατος, τὸ δὲ χάρισμα τοῦ  ̊Θεοῦ ζωὴ αἰώνιος ἐν  ̊Χριστῷ  ̊Ἰησοῦ, τῷ  ̊Κυρίῳ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 1, '¶Ἢ ἀγνοεῖτε, ἀδελφοί (γινώσκουσιν γὰρ νόμον λαλῶ), ὅτι ὁ νόμος κυριεύει τοῦ ἀνθρώπου ἐφʼ ὅσον χρόνον ζῇ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 2, 'Ἡ γὰρ ὕπανδρος γυνὴ τῷ ζῶντι ἀνδρὶ δέδεται νόμῳ· ἐὰν δὲ ἀποθάνῃ ὁ ἀνήρ, κατήργηται ἀπὸ τοῦ νόμου τοῦ ἀνδρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 3, 'Ἄρα οὖν ζῶντος τοῦ ἀνδρὸς, μοιχαλὶς χρηματίσει, ἐὰν γένηται ἀνδρὶ ἑτέρῳ· ἐὰν δὲ ἀποθάνῃ ὁ ἀνήρ, ἐλευθέρα ἐστὶν ἀπὸ τοῦ νόμου, τοῦ μὴ εἶναι αὐτὴν μοιχαλίδα γενομένην ἀνδρὶ ἑτέρῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 4, '¶Ὥστε, ἀδελφοί μου, καὶ ὑμεῖς ἐθανατώθητε τῷ νόμῳ διὰ τοῦ σώματος τοῦ  ̊Χριστοῦ, εἰς τὸ γενέσθαι ὑμᾶς ἑτέρῳ, τῷ ἐκ νεκρῶν ἐγερθέντι, ἵνα καρποφορήσωμεν τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 5, 'Ὅτε γὰρ ἦμεν ἐν τῇ σαρκί, τὰ παθήματα τῶν ἁμαρτιῶν τὰ διὰ τοῦ νόμου ἐνηργεῖτο ἐν τοῖς μέλεσιν ἡμῶν εἰς τὸ καρποφορῆσαι τῷ θανάτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 6, 'Νυνὶ δὲ κατηργήθημεν ἀπὸ τοῦ νόμου, ἀποθανόντες ἐν ᾧ κατειχόμεθα, ὥστε δουλεύειν ἡμᾶς ἐν καινότητι  ̊Πνεύματος, καὶ οὐ παλαιότητι γράμματος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 7, '¶Τί οὖν ἐροῦμεν; Ὁ νόμος ἁμαρτία; Μὴ γένοιτο! Ἀλλὰ τὴν ἁμαρτίαν οὐκ ἔγνων, εἰ μὴ διὰ νόμου, τήν τε γὰρ ἐπιθυμίαν, οὐκ ᾔδειν, εἰ μὴ ὁ νόμος ἔλεγεν, “Οὐκ ἐπιθυμήσεις.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 8, 'Ἀφορμὴν δὲ λαβοῦσα ἡ ἁμαρτία διὰ τῆς ἐντολῆς, κατειργάσατο ἐν ἐμοὶ πᾶσαν ἐπιθυμίαν, χωρὶς γὰρ νόμου, ἁμαρτία νεκρά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 9, 'Ἐγὼ δὲ ἔζων χωρὶς νόμου ποτέ· ἐλθούσης δὲ τῆς ἐντολῆς, ἡ ἁμαρτία ἀνέζησεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 10, 'ἐγὼ δὲ ἀπέθανον, καὶ εὑρέθη μοι ἡ ἐντολὴ, ἡ εἰς ζωὴν, αὕτη εἰς θάνατον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 11, 'Ἡ γὰρ ἁμαρτία ἀφορμὴν λαβοῦσα διὰ τῆς ἐντολῆς, ἐξηπάτησέν με καὶ διʼ αὐτῆς ἀπέκτεινεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 12, 'Ὥστε ὁ μὲν νόμος ἅγιος, καὶ ἡ ἐντολὴ ἁγία, καὶ δικαία, καὶ ἀγαθή.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 13, '¶Τὸ οὖν ἀγαθὸν ἐμοὶ ἐγένετο θάνατος; Μὴ γένοιτο! Ἀλλὰ ἡ ἁμαρτία, ἵνα φανῇ ἁμαρτία διὰ τοῦ ἀγαθοῦ μοι κατεργαζομένη θάνατον· ἵνα γένηται καθʼ ὑπερβολὴν ἁμαρτωλὸς ἡ ἁμαρτία διὰ τῆς ἐντολῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 14, '¶Οἴδαμεν γὰρ ὅτι ὁ νόμος πνευματικός ἐστιν· ἐγὼ δὲ σάρκινός εἰμι, πεπραμένος ὑπὸ τὴν ἁμαρτίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 15, 'Ὃ γὰρ κατεργάζομαι, οὐ γινώσκω· οὐ γὰρ ὃ θέλω, τοῦτο πράσσω, ἀλλʼ ὃ μισῶ, τοῦτο ποιῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 16, 'Εἰ δὲ ὃ οὐ θέλω, τοῦτο ποιῶ, σύμφημι τῷ νόμῳ ὅτι καλός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 17, 'Νυνὶ δὲ οὐκέτι ἐγὼ κατεργάζομαι αὐτὸ, ἀλλʼ ἡ ἐνοικοῦσα ἐν ἐμοὶ ἁμαρτία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 18, 'Οἶδα γὰρ ὅτι οὐκ οἰκεῖ ἐν ἐμοί, τοῦτʼ ἔστιν ἐν τῇ σαρκί μου, ἀγαθόν· τὸ γὰρ θέλειν παράκειταί μοι, τὸ δὲ κατεργάζεσθαι τὸ καλὸν οὔ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 19, 'Οὐ γὰρ ὃ θέλω, ποιῶ ἀγαθόν, ἀλλʼ ὃ οὐ θέλω κακὸν, τοῦτο πράσσω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 20, 'Εἰ δὲ ὃ οὐ θέλω, τοῦτο ποιῶ, οὐκέτι ἐγὼ κατεργάζομαι αὐτὸ, ἀλλʼ ἡ οἰκοῦσα ἐν ἐμοὶ ἁμαρτία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 21, '¶Εὑρίσκω ἄρα τὸν νόμον, τῷ θέλοντι ἐμοὶ ποιεῖν τὸ καλὸν, ὅτι ἐμοὶ τὸ κακὸν παράκειται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 22, 'Συνήδομαι γὰρ τῷ νόμῳ τοῦ  ̊Θεοῦ, κατὰ τὸν ἔσω ἄνθρωπον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 23, 'βλέπω δὲ ἕτερον νόμον ἐν τοῖς μέλεσίν μου, ἀντιστρατευόμενον τῷ νόμῳ τοῦ νοός μου, καὶ αἰχμαλωτίζοντά με ἐν τῷ νόμῳ τῆς ἁμαρτίας, τῷ ὄντι ἐν τοῖς μέλεσίν μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 24, 'Ταλαίπωρος ἐγὼ ἄνθρωπος! Τίς με ῥύσεται ἐκ τοῦ σώματος τοῦ θανάτου τούτου;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 25, 'Χάρις τῷ  ̊Θεῷ διὰ  ̊Ἰησοῦ  ̊Χριστοῦ τοῦ  ̊Κυρίου ἡμῶν! Ἄρα οὖν αὐτὸς ἐγὼ, τῷ μὲν νοῒ δουλεύω νόμῳ  ̊Θεοῦ, τῇ δὲ σαρκὶ, νόμῳ ἁμαρτίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 1, '¶Οὐδὲν ἄρα νῦν κατάκριμα τοῖς ἐν  ̊Χριστῷ  ̊Ἰησοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 2, 'ὁ γὰρ νόμος τοῦ  ̊Πνεύματος τῆς ζωῆς ἐν  ̊Χριστῷ  ̊Ἰησοῦ, ἠλευθέρωσέν σε ἀπὸ τοῦ νόμου τῆς ἁμαρτίας καὶ τοῦ θανάτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 3, 'Τὸ γὰρ ἀδύνατον τοῦ νόμου, ἐν ᾧ ἠσθένει διὰ τῆς σαρκός, ὁ  ̊Θεὸς τὸν ἑαυτοῦ Υἱὸν πέμψας, ἐν ὁμοιώματι σαρκὸς ἁμαρτίας, καὶ περὶ ἁμαρτίας, κατέκρινεν τὴν ἁμαρτίαν ἐν τῇ σαρκί,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 4, 'ἵνα τὸ δικαίωμα τοῦ νόμου πληρωθῇ ἐν ἡμῖν, τοῖς μὴ κατὰ σάρκα περιπατοῦσιν, ἀλλὰ κατὰ  ̊Πνεῦμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 5, 'Οἱ γὰρ κατὰ σάρκα ὄντες, τὰ τῆς σαρκὸς φρονοῦσιν, οἱ δὲ κατὰ  ̊Πνεῦμα, τὰ τοῦ  ̊Πνεύματος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 6, 'Τὸ γὰρ φρόνημα τῆς σαρκὸς θάνατος, τὸ δὲ φρόνημα τοῦ  ̊Πνεύματος ζωὴ καὶ εἰρήνη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 7, 'Διότι τὸ φρόνημα τῆς σαρκὸς ἔχθρα εἰς  ̊Θεόν, τῷ γὰρ νόμῳ τοῦ  ̊Θεοῦ οὐχ ὑποτάσσεται, οὐδὲ γὰρ δύναται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 8, 'Οἱ δὲ ἐν σαρκὶ ὄντες,  ̊Θεῷ ἀρέσαι οὐ δύνανται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 9, '¶Ὑμεῖς δὲ οὐκ ἐστὲ ἐν σαρκὶ, ἀλλʼ ἐν  ̊Πνεύματι, εἴπερ  ̊Πνεῦμα  ̊Θεοῦ οἰκεῖ ἐν ὑμῖν. Εἰ δέ τις  ̊Πνεῦμα  ̊Χριστοῦ οὐκ ἔχει, οὗτος οὐκ ἔστιν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 10, 'Εἰ δὲ  ̊Χριστὸς ἐν ὑμῖν, τὸ μὲν σῶμα νεκρὸν διὰ ἁμαρτίαν, τὸ δὲ  ̊Πνεῦμα ζωὴ διὰ δικαιοσύνην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 11, 'Εἰ δὲ τὸ  ̊Πνεῦμα τοῦ ἐγείραντος τὸν  ̊Ἰησοῦν ἐκ νεκρῶν οἰκεῖ ἐν ὑμῖν, ὁ ἐγείρας ἐκ νεκρῶν  ̊Χριστὸν  ̊Ἰησοῦν ζῳοποιήσει καὶ τὰ θνητὰ σώματα ὑμῶν, διὰ τοῦ ἐνοικοῦντος αὐτοῦ  ̊Πνεύματος ἐν ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 12, '¶Ἄρα οὖν, ἀδελφοί, ὀφειλέται ἐσμέν, οὐ τῇ σαρκὶ, τοῦ κατὰ σάρκα ζῆν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 13, 'Εἰ γὰρ κατὰ σάρκα ζῆτε, μέλλετε ἀποθνῄσκειν, εἰ δὲ  ̊Πνεύματι τὰς πράξεις τοῦ σώματος θανατοῦτε, ζήσεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 14, 'Ὅσοι γὰρ  ̊Πνεύματι  ̊Θεοῦ ἄγονται, οὗτοι υἱοὶ  ̊Θεοῦ εἰσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 15, 'Οὐ γὰρ ἐλάβετε πνεῦμα δουλείας πάλιν εἰς φόβον, ἀλλὰ ἐλάβετε  ̊Πνεῦμα υἱοθεσίας, ἐν ᾧ κράζομεν, “Ἀββά, ὁ Πατήρ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 16, 'Αὐτὸ τὸ  ̊Πνεῦμα συμμαρτυρεῖ τῷ  ̊Πνεύματι ἡμῶν ὅτι ἐσμὲν τέκνα  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 17, 'Εἰ δὲ τέκνα, καὶ κληρονόμοι· κληρονόμοι μὲν  ̊Θεοῦ, συγκληρονόμοι δὲ  ̊Χριστοῦ, εἴπερ συμπάσχομεν, ἵνα καὶ συνδοξασθῶμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 18, '¶Λογίζομαι γὰρ ὅτι οὐκ ἄξια τὰ παθήματα τοῦ νῦν καιροῦ, πρὸς τὴν μέλλουσαν δόξαν ἀποκαλυφθῆναι εἰς ἡμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 19, 'Ἡ γὰρ ἀποκαραδοκία τῆς κτίσεως, τὴν ἀποκάλυψιν τῶν υἱῶν τοῦ  ̊Θεοῦ ἀπεκδέχεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 20, 'Τῇ γὰρ ματαιότητι, ἡ κτίσις ὑπετάγη, οὐχ ἑκοῦσα, ἀλλὰ διὰ τὸν ὑποτάξαντα, ἐφʼ ἑλπίδι');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 21, 'ὅτι καὶ αὐτὴ ἡ κτίσις ἐλευθερωθήσεται ἀπὸ τῆς δουλείας τῆς φθορᾶς, εἰς τὴν ἐλευθερίαν τῆς δόξης τῶν τέκνων τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 22, 'Οἴδαμεν γὰρ ὅτι πᾶσα ἡ κτίσις συστενάζει καὶ συνωδίνει ἄχρι τοῦ νῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 23, 'Οὐ μόνον δέ, ἀλλὰ καὶ αὐτοὶ, τὴν ἀπαρχὴν τοῦ  ̊Πνεύματος ἔχοντες, ἡμεῖς καὶ αὐτοὶ ἐν ἑαυτοῖς στενάζομεν, υἱοθεσίαν ἀπεκδεχόμενοι, τὴν ἀπολύτρωσιν τοῦ σώματος ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 24, 'Τῇ γὰρ ἐλπίδι ἐσώθημεν· ἐλπὶς δὲ βλεπομένη, οὐκ ἔστιν ἐλπίς, ὃ γὰρ βλέπει τις, ἐλπίζει;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 25, 'Εἰ δὲ ὃ οὐ βλέπομεν ἐλπίζομεν, διʼ ὑπομονῆς ἀπεκδεχόμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 26, '¶Ὡσαύτως δὲ καὶ τὸ  ̊Πνεῦμα συναντιλαμβάνεται τῇ ἀσθενείᾳ ἡμῶν· τὸ γὰρ τί προσευξώμεθα καθὸ δεῖ, οὐκ οἴδαμεν, ἀλλὰ αὐτὸ τὸ  ̊Πνεῦμα ὑπερεντυγχάνει στεναγμοῖς ἀλαλήτοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 27, 'Ὁ δὲ ἐραυνῶν τὰς καρδίας οἶδεν τί τὸ φρόνημα τοῦ  ̊Πνεύματος, ὅτι κατὰ  ̊Θεὸν, ἐντυγχάνει ὑπὲρ ἁγίων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 28, '¶Οἴδαμεν δὲ ὅτι τοῖς ἀγαπῶσιν τὸν  ̊Θεὸν, πάντα συνεργεῖ ὁ  ̊Θεὸς εἰς ἀγαθόν, τοῖς κατὰ πρόθεσιν κλητοῖς οὖσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 29, 'Ὅτι οὓς προέγνω, καὶ προώρισεν συμμόρφους τῆς εἰκόνος τοῦ Υἱοῦ αὐτοῦ, εἰς τὸ εἶναι αὐτὸν πρωτότοκον ἐν πολλοῖς ἀδελφοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 30, 'Οὓς δὲ προώρισεν, τούτους καὶ ἐκάλεσεν· καὶ οὓς ἐκάλεσεν, τούτους καὶ ἐδικαίωσεν· οὓς δὲ ἐδικαίωσεν, τούτους καὶ ἐδόξασεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 31, '¶Τί οὖν ἐροῦμεν πρὸς ταῦτα; Εἰ ὁ  ̊Θεὸς ὑπὲρ ἡμῶν, τίς καθʼ ἡμῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 32, 'Ὅς γε τοῦ ἰδίου Υἱοῦ οὐκ ἐφείσατο, ἀλλὰ ὑπὲρ ἡμῶν πάντων παρέδωκεν αὐτόν, πῶς οὐχὶ καὶ σὺν αὐτῷ, τὰ πάντα ἡμῖν χαρίσεται;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 33, 'Τίς ἐγκαλέσει κατὰ ἐκλεκτῶν  ̊Θεοῦ;  ̊Θεὸς ὁ δικαιῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 34, 'Τίς ὁ κατακρίνων;  ̊Χριστὸς  ̊Ἰησοῦς ὁ ἀποθανών, μᾶλλον δὲ ἐγερθείς ὅς, καί ἐστιν ἐν δεξιᾷ τοῦ  ̊Θεοῦ, ὃς καὶ ἐντυγχάνει ὑπὲρ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 35, 'Τίς ἡμᾶς χωρίσει ἀπὸ τῆς ἀγάπης τοῦ  ̊Χριστοῦ; Θλῖψις, ἢ στενοχωρία, ἢ διωγμὸς, ἢ λιμὸς, ἢ γυμνότης, ἢ κίνδυνος, ἢ μάχαιρα;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 36, 'Καθὼς γέγραπται, ὅτι “Ἕνεκεν σοῦ, θανατούμεθα ὅλην τὴν ἡμέραν, ἐλογίσθημεν ὡς πρόβατα σφαγῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 37, 'Ἀλλʼ ἐν τούτοις πᾶσιν, ὑπερνικῶμεν διὰ τοῦ ἀγαπήσαντος ἡμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 38, 'Πέπεισμαι γὰρ ὅτι οὔτε θάνατος, οὔτε ζωὴ, οὔτε ἄγγελοι, οὔτε ἀρχαὶ, οὔτε ἐνεστῶτα, οὔτε μέλλοντα, οὔτε δυνάμεις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 39, 'οὔτε ὕψωμα, οὔτε βάθος, οὔτε τις κτίσις ἑτέρα, δυνήσεται ἡμᾶς χωρίσαι ἀπὸ τῆς ἀγάπης τοῦ  ̊Θεοῦ, τῆς ἐν  ̊Χριστῷ  ̊Ἰησοῦ, τῷ  ̊Κυρίῳ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 1, '¶Ἀλήθειαν λέγω ἐν  ̊Χριστῷ, οὐ ψεύδομαι, συμμαρτυρούσης μοι τῆς συνειδήσεώς μου ἐν  ̊Πνεύματι Ἁγίῳ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 2, 'ὅτι λύπη μοί ἐστιν μεγάλη, καὶ ἀδιάλειπτος ὀδύνη τῇ καρδίᾳ μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 3, 'Ηὐχόμην γὰρ ἀνάθεμα εἶναι αὐτὸς, ἐγὼ ἀπὸ τοῦ  ̊Χριστοῦ ὑπὲρ τῶν ἀδελφῶν μου, τῶν συγγενῶν μου, κατὰ σάρκα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 4, 'οἵτινές εἰσιν Ἰσραηλῖται, ὧν ἡ υἱοθεσία, καὶ ἡ δόξα, καὶ αἱ διαθῆκαι, καὶ ἡ νομοθεσία, καὶ ἡ λατρεία, καὶ αἱ ἐπαγγελίαι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 5, 'ὧν οἱ πατέρες, καὶ ἐξ ὧν ὁ  ̊Χριστὸς, τὸ κατὰ σάρκα ὁ ὢν ἐπὶ πάντων  ̊Θεὸς, εὐλογητὸς εἰς τοὺς αἰῶνας. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 6, '¶Οὐχ οἷον δὲ, ὅτι ἐκπέπτωκεν ὁ λόγος τοῦ  ̊Θεοῦ. Οὐ γὰρ πάντες οἱ ἐξ Ἰσραήλ οὗτοι, Ἰσραήλ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 7, 'Οὐδʼ ὅτι εἰσὶν σπέρμα Ἀβραάμ πάντες τέκνα, ἀλλʼ: “Ἐν Ἰσαὰκ κληθήσεταί σοι σπέρμα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 8, 'Τοῦτʼ ἔστιν οὐ τὰ τέκνα τῆς σαρκὸς, ταῦτα τέκνα τοῦ  ̊Θεοῦ, ἀλλὰ τὰ τέκνα τῆς ἐπαγγελίας λογίζεται εἰς σπέρμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 9, 'Ἐπαγγελίας γὰρ ὁ λόγος οὗτος: “Κατὰ τὸν καιρὸν τοῦτον, ἐλεύσομαι, καὶ ἔσται τῇ Σάρρᾳ υἱός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 10, 'Οὐ μόνον δέ, ἀλλὰ καὶ Ῥεβέκκα ἐξ ἑνὸς κοίτην, ἔχουσα Ἰσαὰκ, τοῦ πατρὸς ἡμῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 11, 'μήπω γὰρ γεννηθέντων, μηδὲ πραξάντων τι ἀγαθὸν ἢ φαῦλον, ἵνα ἡ κατʼ ἐκλογὴν πρόθεσις τοῦ  ̊Θεοῦ μένῃ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 12, 'οὐκ ἐξ ἔργων, ἀλλʼ ἐκ τοῦ καλοῦντος, ἐρρέθη αὐτῇ, ὅτι “Ὁ μείζων δουλεύσει τῷ ἐλάσσονι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 13, 'Καθὼς γέγραπται, “Τὸν Ἰακὼβ ἠγάπησα, τὸν δὲ Ἠσαῦ ἐμίσησα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 14, '¶Τί οὖν ἐροῦμεν; Μὴ ἀδικία παρὰ τῷ  ̊Θεῷ; Μὴ γένοιτο!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 15, 'Τῷ Μωϋσεῖ γὰρ λέγει, “Ἐλεήσω ὃν ἂν ἐλεῶ, καὶ οἰκτειρήσω ὃν ἂν οἰκτείρω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 16, 'Ἄρα οὖν οὐ τοῦ θέλοντος, οὐδὲ τοῦ τρέχοντος, ἀλλὰ τοῦ ἐλεῶντος  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 17, 'Λέγει γὰρ ἡ Γραφὴ τῷ Φαραὼ, ὅτι “Εἰς αὐτὸ τοῦτο ἐξήγειρά σε, ὅπως ἐνδείξωμαι ἐν σοὶ τὴν δύναμίν μου, καὶ ὅπως διαγγελῇ τὸ ὄνομά μου ἐν πάσῃ τῇ γῇ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 18, 'Ἄρα οὖν ὃν θέλει, ἐλεεῖ, ὃν δὲ θέλει, σκληρύνει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 19, '¶Ἐρεῖς μοι οὖν, “Τί οὖν ἔτι μέμφεται; Τῷ γὰρ βουλήματι αὐτοῦ τίς ἀνθέστηκεν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 20, 'Ὦ ἄνθρωπε, μενοῦνγε σὺ τίς εἶ, ὁ ἀνταποκρινόμενος τῷ  ̊Θεῷ; Μὴ ἐρεῖ τὸ πλάσμα, τῷ πλάσαντι, “Τί με ἐποίησας οὕτως;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 21, 'Ἢ οὐκ ἔχει ἐξουσίαν ὁ κεραμεὺς τοῦ πηλοῦ, ἐκ τοῦ αὐτοῦ φυράματος ποιῆσαι ὃ μὲν εἰς τιμὴν σκεῦος, ὃ δὲ εἰς ἀτιμίαν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 22, 'Εἰ δὲ θέλων ὁ  ̊Θεὸς ἐνδείξασθαι τὴν ὀργὴν, καὶ γνωρίσαι τὸ δυνατὸν αὐτοῦ, ἤνεγκεν ἐν πολλῇ μακροθυμίᾳ, σκεύη ὀργῆς κατηρτισμένα εἰς ἀπώλειαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 23, 'καὶ ἵνα γνωρίσῃ τὸν πλοῦτον τῆς δόξης αὐτοῦ ἐπὶ σκεύη ἐλέους, ἃ προητοίμασεν εἰς δόξαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 24, 'οὓς καὶ ἐκάλεσεν, ἡμᾶς οὐ μόνον ἐξ Ἰουδαίων, ἀλλὰ καὶ ἐξ ἐθνῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 25, 'Ὡς καὶ ἐν τῷ Ὡσηὲ λέγει, “Καλέσω τὸν οὐ λαόν μου, ‘Λαόν μου’, καὶ τὴν οὐκ ἠγαπημένην, ‘Ἠγαπημένην’.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 26, '“Καὶ ἔσται ἐν τῷ τόπῳ οὗ ἐρρέθη αὐτοῖς, ‘Οὐ λαός μου ὑμεῖς’, ἐκεῖ κληθήσονται υἱοὶ  ̊Θεοῦ ζῶντος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 27, '¶Ἠσαΐας δὲ κράζει ὑπὲρ τοῦ Ἰσραήλ, “Ἐὰν ᾖ ὁ ἀριθμὸς τῶν υἱῶν Ἰσραὴλ, ὡς ἡ ἄμμος τῆς θαλάσσης, τὸ ὑπόλειμμα σωθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 28, 'Λόγον γὰρ συντελῶν καὶ συντέμνων ποιήσει  ̊Κύριος ἐπὶ τῆς γῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 29, 'Καὶ καθὼς προείρηκεν Ἠσαΐας, “Εἰ μὴ  ̊Κύριος Σαβαὼθ ἐγκατέλιπεν ἡμῖν σπέρμα, ὡς Σόδομα ἂν ἐγενήθημεν, καὶ ὡς Γόμορρα ἂν ὡμοιώθημεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 30, '¶Τί οὖν ἐροῦμεν; Ὅτι ἔθνη τὰ μὴ διώκοντα δικαιοσύνην, κατέλαβεν δικαιοσύνην, δικαιοσύνην δὲ τὴν ἐκ πίστεως·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 31, 'Ἰσραὴλ δὲ διώκων νόμον δικαιοσύνης εἰς νόμον οὐκ ἔφθασεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 32, 'Διὰ τί; Ὅτι οὐκ ἐκ πίστεως, ἀλλʼ ὡς ἐξ ἔργων. Προσέκοψαν τῷ λίθῳ τοῦ προσκόμματος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 33, 'καθὼς γέγραπται, “Ἰδοὺ, τίθημι ἐν Σιὼν λίθον προσκόμματος, καὶ πέτραν σκανδάλου, καὶ ὁ πιστεύων ἐπʼ αὐτῷ, οὐ καταισχυνθήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 1, '¶Ἀδελφοί, ἡ μὲν εὐδοκία τῆς ἐμῆς καρδίας, καὶ ἡ δέησις πρὸς τὸν  ̊Θεὸν, ὑπὲρ αὐτῶν εἰς σωτηρίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 2, 'Μαρτυρῶ γὰρ αὐτοῖς ὅτι ζῆλον  ̊Θεοῦ ἔχουσιν, ἀλλʼ οὐ κατʼ ἐπίγνωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 3, 'Ἀγνοοῦντες γὰρ τὴν τοῦ  ̊Θεοῦ δικαιοσύνην, καὶ τὴν ἰδίαν ζητοῦντες στῆσαι, τῇ δικαιοσύνῃ τοῦ  ̊Θεοῦ οὐχ ὑπετάγησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 4, 'Τέλος γὰρ νόμου  ̊Χριστὸς, εἰς δικαιοσύνην παντὶ τῷ πιστεύοντι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 5, '¶Μωϋσῆς γὰρ γράφει τὴν δικαιοσύνην τὴν ἐκ νόμου, ὅτι “Ὁ ποιήσας αὐτὰ ἄνθρωπος, ζήσεται ἐν αὐτῇ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 6, 'Ἡ δὲ ἐκ πίστεως δικαιοσύνη οὕτως λέγει, “Μὴ εἴπῃς ἐν τῇ καρδίᾳ σου, ‘Τίς ἀναβήσεται εἰς τὸν οὐρανόν;’” (Τοῦτʼ ἔστιν  ̊Χριστὸν καταγαγεῖν),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 7, 'ἤ, “‘Τίς καταβήσεται εἰς τὴν Ἄβυσσον;’” (Τοῦτʼ ἔστιν  ̊Χριστὸν ἐκ νεκρῶν ἀναγαγεῖν).');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 8, 'Ἀλλὰ τί λέγει; “Ἐγγύς σου τὸ ῥῆμά ἐστιν, ἐν τῷ στόματί σου, καὶ ἐν τῇ καρδίᾳ σου”, τοῦτʼ ἔστιν τὸ ῥῆμα τῆς πίστεως ὃ κηρύσσομεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 9, 'Ὅτι ἐὰν ὁμολογήσῃς ἐν τῷ στόματί σου, “ ̊Κύριον  ̊Ἰησοῦν”, καὶ πιστεύσῃς ἐν τῇ καρδίᾳ σου ὅτι ὁ  ̊Θεὸς αὐτὸν ἤγειρεν ἐκ νεκρῶν, σωθήσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 10, 'Καρδίᾳ γὰρ πιστεύεται εἰς δικαιοσύνην, στόματι δὲ ὁμολογεῖται εἰς σωτηρίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 11, 'Λέγει γὰρ ἡ Γραφή, “Πᾶς ὁ πιστεύων ἐπʼ αὐτῷ οὐ καταισχυνθήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 12, 'Οὐ γάρ ἐστιν διαστολὴ Ἰουδαίου τε καὶ Ἕλληνος, ὁ γὰρ αὐτὸς  ̊Κύριος πάντων, πλουτῶν εἰς πάντας τοὺς ἐπικαλουμένους αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 13, '“Πᾶς” γὰρ “ὃς ἂν ἐπικαλέσηται τὸ ὄνομα  ̊Κυρίου, σωθήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 14, '¶Πῶς οὖν ἐπικαλέσωνται εἰς ὃν οὐκ ἐπίστευσαν; Πῶς δὲ πιστεύσωσιν οὗ οὐκ ἤκουσαν; Πῶς δὲ ἀκούσωσιν χωρὶς κηρύσσοντος;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 15, 'Πῶς δὲ κηρύξωσιν ἐὰν μὴ ἀποσταλῶσιν; Καθὼς γέγραπται, “Ὡς ὡραῖοι οἱ πόδες τῶν εὐαγγελιζομένων ἀγαθά!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 16, 'Ἀλλʼ οὐ πάντες ὑπήκουσαν τῷ εὐαγγελίῳ. Ἠσαΐας γὰρ λέγει, “ ̊Κύριε, τίς ἐπίστευσεν τῇ ἀκοῇ ἡμῶν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 17, 'Ἄρα ἡ πίστις ἐξ ἀκοῆς, ἡ δὲ ἀκοὴ διὰ ῥήματος  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 18, '¶Ἀλλὰ λέγω, μὴ οὐκ ἤκουσαν; Μενοῦνγε, “Εἰς πᾶσαν τὴν γῆν, ἐξῆλθεν ὁ φθόγγος αὐτῶν, καὶ εἰς τὰ πέρατα τῆς οἰκουμένης, τὰ ῥήματα αὐτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 19, 'Ἀλλὰ λέγω, μὴ Ἰσραὴλ οὐκ ἔγνω; Πρῶτος Μωϋσῆς λέγει, “Ἐγὼ παραζηλώσω ὑμᾶς, ἐπʼ οὐκ ἔθνει, ἐπʼ ἔθνει ἀσυνέτῳ, παροργιῶ ὑμᾶς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 20, 'Ἠσαΐας δὲ ἀποτολμᾷ καὶ λέγει, “Εὑρέθην ἐν τοῖς ἐμὲ μὴ ζητοῦσιν, ἐμφανὴς ἐγενόμην τοῖς ἐμὲ μὴ ἐπερωτῶσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 21, 'Πρὸς δὲ τὸν Ἰσραὴλ λέγει, “Ὅλην τὴν ἡμέραν, ἐξεπέτασα τὰς χεῖράς μου πρὸς λαὸν ἀπειθοῦντα καὶ ἀντιλέγοντα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 1, '¶Λέγω οὖν, μὴ ἀπώσατο ὁ  ̊Θεὸς τὸν λαὸν αὐτοῦ; Μὴ γένοιτο! Καὶ γὰρ ἐγὼ Ἰσραηλίτης εἰμί, ἐκ σπέρματος Ἀβραάμ, φυλῆς Βενιαμίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 2, 'Οὐκ ἀπώσατο ὁ  ̊Θεὸς τὸν λαὸν αὐτοῦ, ὃν προέγνω. Ἢ οὐκ οἴδατε ἐν Ἠλίᾳ τί λέγει ἡ Γραφή, ὡς ἐντυγχάνει τῷ  ̊Θεῷ κατὰ τοῦ Ἰσραήλ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 3, '“ ̊Κύριε, τοὺς προφήτας σου ἀπέκτειναν, τὰ θυσιαστήριά σου κατέσκαψαν, κἀγὼ ὑπελείφθην μόνος, καὶ ζητοῦσιν τὴν ψυχήν μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 4, 'Ἀλλὰ τί λέγει αὐτῷ ὁ χρηματισμός; “Κατέλιπον ἐμαυτῷ ἑπτακισχιλίους ἄνδρας, οἵτινες οὐκ ἔκαμψαν γόνυ τῇ Βάαλ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 5, 'Οὕτως οὖν καὶ ἐν τῷ νῦν καιρῷ, λεῖμμα κατʼ ἐκλογὴν χάριτος γέγονεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 6, 'Εἰ δὲ χάριτι, οὐκέτι ἐξ ἔργων, ἐπεὶ ἡ χάρις οὐκέτι γίνεται χάρις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 7, 'Τί οὖν; Ὃ ἐπιζητεῖ Ἰσραήλ, τοῦτο οὐκ ἐπέτυχεν, ἡ δὲ ἐκλογὴ ἐπέτυχεν, οἱ δὲ λοιποὶ ἐπωρώθησαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 8, 'καθὼς γέγραπται, “Ἔδωκεν αὐτοῖς ὁ  ̊Θεὸς πνεῦμα κατανύξεως”, “Ὀφθαλμοὺς τοῦ μὴ βλέπειν, καὶ ὦτα τοῦ μὴ ἀκούειν, ἕως τῆς σήμερον ἡμέρας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 9, 'Καὶ Δαυὶδ λέγει, “Γενηθήτω ἡ τράπεζα αὐτῶν εἰς παγίδα, καὶ εἰς θήραν, καὶ εἰς σκάνδαλον, καὶ εἰς ἀνταπόδομα αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 10, 'Σκοτισθήτωσαν οἱ ὀφθαλμοὶ αὐτῶν, τοῦ μὴ βλέπειν, καὶ τὸν νῶτον αὐτῶν διὰ παντὸς σύγκαμψον.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 11, '¶Λέγω οὖν μὴ ἔπταισαν, ἵνα πέσωσιν; Μὴ γένοιτο! Ἀλλὰ τῷ αὐτῶν παραπτώματι, ἡ σωτηρία τοῖς ἔθνεσιν, εἰς τὸ παραζηλῶσαι αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 12, 'Εἰ δὲ τὸ παράπτωμα αὐτῶν, πλοῦτος κόσμου, καὶ τὸ ἥττημα αὐτῶν, πλοῦτος ἐθνῶν, πόσῳ μᾶλλον τὸ πλήρωμα αὐτῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 13, '¶Ὑμῖν δὲ λέγω, τοῖς ἔθνεσιν. Ἐφʼ ὅσον μὲν οὖν εἰμι ἐγὼ ἐθνῶν ἀπόστολος, τὴν διακονίαν μου δοξάζω,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 14, 'εἴ πως παραζηλώσω μου τὴν σάρκα, καὶ σώσω τινὰς ἐξ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 15, 'Εἰ γὰρ ἡ ἀποβολὴ αὐτῶν καταλλαγὴ κόσμου, τίς ἡ πρόσλημψις εἰ μὴ ζωὴ ἐκ νεκρῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 16, 'Εἰ δὲ ἡ ἀπαρχὴ ἁγία, καὶ τὸ φύραμα· καὶ εἰ ἡ ῥίζα ἁγία, καὶ οἱ κλάδοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 17, '¶Εἰ δέ τινες τῶν κλάδων ἐξεκλάσθησαν, σὺ δὲ ἀγριέλαιος ὢν ἐνεκεντρίσθης ἐν αὐτοῖς, καὶ συγκοινωνὸς τῆς ῥίζης τῆς πιότητος τῆς ἐλαίας ἐγένου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 18, 'μὴ κατακαυχῶ τῶν κλάδων. Εἰ δὲ κατακαυχᾶσαι, οὐ σὺ τὴν ῥίζαν βαστάζεις, ἀλλʼ ἡ ῥίζα σέ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 19, 'Ἐρεῖς οὖν, “Ἐξεκλάσθησαν κλάδοι, ἵνα ἐγὼ ἐγκεντρισθῶ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 20, 'Καλῶς, τῇ ἀπιστίᾳ ἐξεκλάσθησαν, σὺ δὲ τῇ πίστει ἕστηκας. Μὴ ὑψηλὰ φρόνει, ἀλλὰ φοβοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 21, 'Εἰ γὰρ ὁ  ̊Θεὸς τῶν κατὰ φύσιν κλάδων οὐκ ἐφείσατο, οὐδὲ σοῦ φείσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 22, 'Ἴδε οὖν, χρηστότητα καὶ ἀποτομίαν  ̊Θεοῦ· ἐπὶ μὲν τοὺς πεσόντας, ἀποτομία, ἐπὶ δὲ σὲ, χρηστότης  ̊Θεοῦ, ἐὰν ἐπιμείνῃς τῇ χρηστότητι, ἐπεὶ καὶ σὺ ἐκκοπήσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 23, 'Κἀκεῖνοι δέ ἐὰν μὴ ἐπιμένωσιν τῇ ἀπιστίᾳ, ἐγκεντρισθήσονται· δυνατὸς γάρ ἐστιν ὁ  ̊Θεὸς πάλιν ἐγκεντρίσαι αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 24, 'Εἰ γὰρ σὺ ἐκ τῆς κατὰ φύσιν ἐξεκόπης ἀγριελαίου, καὶ παρὰ φύσιν ἐνεκεντρίσθης εἰς καλλιέλαιον, πόσῳ μᾶλλον οὗτοι, οἱ κατὰ φύσιν ἐγκεντρισθήσονται τῇ ἰδίᾳ ἐλαίᾳ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 25, '¶Οὐ γὰρ θέλω ὑμᾶς ἀγνοεῖν, ἀδελφοί, τὸ μυστήριον τοῦτο, ἵνα μὴ ἦτε ἐν ἑαυτοῖς φρόνιμοι, ὅτι πώρωσις ἀπὸ μέρους τῷ Ἰσραὴλ γέγονεν, ἄχρι οὗ τὸ πλήρωμα τῶν ἐθνῶν εἰσέλθῃ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 26, 'καὶ οὕτως πᾶς Ἰσραὴλ σωθήσεται, καθὼς γέγραπται, “Ἥξει ἐκ Σιὼν ὁ ῥυόμενος, ἀποστρέψει ἀσεβείας ἀπὸ Ἰακώβ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 27, 'Καὶ αὕτη αὐτοῖς, ἡ παρʼ ἐμοῦ διαθήκη”, “Ὅταν ἀφέλωμαι τὰς ἁμαρτίας αὐτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 28, 'Κατὰ μὲν τὸ εὐαγγέλιον, ἐχθροὶ διʼ ὑμᾶς, κατὰ δὲ τὴν ἐκλογὴν, ἀγαπητοὶ διὰ τοὺς πατέρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 29, 'Ἀμεταμέλητα γὰρ τὰ χαρίσματα καὶ ἡ κλῆσις τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 30, 'Ὥσπερ γὰρ ὑμεῖς ποτε ἠπειθήσατε τῷ  ̊Θεῷ, νῦν δὲ ἠλεήθητε τῇ τούτων ἀπειθείᾳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 31, 'οὕτως καὶ οὗτοι νῦν ἠπείθησαν τῷ ὑμετέρῳ ἐλέει, ἵνα καὶ αὐτοὶ νῦν ἐλεηθῶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 32, 'Συνέκλεισεν γὰρ ὁ  ̊Θεὸς τοὺς πάντας εἰς ἀπείθειαν, ἵνα τοὺς πάντας ἐλεήσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 33, '¶Ὦ βάθος πλούτου, καὶ σοφίας καὶ γνώσεως  ̊Θεοῦ! Ὡς ἀνεξεραύνητα τὰ κρίματα αὐτοῦ, καὶ ἀνεξιχνίαστοι αἱ ὁδοὶ αὐτοῦ!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 34, '“Τίς” γὰρ “ἔγνω νοῦν  ̊Κυρίου, ἢ τίς σύμβουλος αὐτοῦ ἐγένετο;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 35, '“Ἢ τίς προέδωκεν αὐτῷ, καὶ ἀνταποδοθήσεται αὐτῷ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 36, 'Ὅτι ἐξ αὐτοῦ, καὶ διʼ αὐτοῦ, καὶ εἰς αὐτὸν, τὰ πάντα. Αὐτῷ ἡ δόξα εἰς τοὺς αἰῶνας. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 1, '¶Παρακαλῶ οὖν ὑμᾶς, ἀδελφοί, διὰ τῶν οἰκτιρμῶν τοῦ  ̊Θεοῦ, παραστῆσαι τὰ σώματα ὑμῶν θυσίαν ζῶσαν, ἁγίαν, τῷ  ̊Θεῷ εὐάρεστον, τὴν λογικὴν λατρείαν ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 2, 'Καὶ μὴ συσχηματίζεσθε τῷ αἰῶνι τούτῳ, ἀλλὰ μεταμορφοῦσθε τῇ ἀνακαινώσει τοῦ νοός, εἰς τὸ δοκιμάζειν ὑμᾶς, τί τὸ θέλημα τοῦ  ̊Θεοῦ, τὸ ἀγαθὸν, καὶ εὐάρεστον, καὶ τέλειον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 3, '¶Λέγω γὰρ διὰ τῆς χάριτος τῆς δοθείσης μοι, παντὶ τῷ ὄντι ἐν ὑμῖν, μὴ ὑπερφρονεῖν παρʼ ὃ δεῖ φρονεῖν, ἀλλὰ φρονεῖν εἰς τὸ σωφρονεῖν, ἑκάστῳ ὡς ὁ  ̊Θεὸς ἐμέρισεν μέτρον πίστεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 4, 'Καθάπερ γὰρ ἐν ἑνὶ σώματι, πολλὰ μέλη ἔχομεν, τὰ δὲ μέλη πάντα οὐ τὴν αὐτὴν ἔχει πρᾶξιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 5, 'οὕτως οἱ πολλοὶ, ἓν σῶμά ἐσμεν ἐν  ̊Χριστῷ, τὸ δὲ καθʼ εἷς ἀλλήλων μέλη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 6, 'Ἔχοντες δὲ χαρίσματα κατὰ τὴν χάριν τὴν δοθεῖσαν ἡμῖν διάφορα: εἴτε προφητείαν, κατὰ τὴν ἀναλογίαν τῆς πίστεως,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 7, 'εἴτε διακονίαν, ἐν τῇ διακονίᾳ, εἴτε ὁ διδάσκων, ἐν τῇ διδασκαλίᾳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 8, 'εἴτε ὁ παρακαλῶν, ἐν τῇ παρακλήσει, ὁ μεταδιδοὺς, ἐν ἁπλότητι, ὁ προϊστάμενος, ἐν σπουδῇ, ὁ ἐλεῶν, ἐν ἱλαρότητι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 9, '¶Ἡ ἀγάπη ἀνυπόκριτος. Ἀποστυγοῦντες τὸ πονηρόν, κολλώμενοι τῷ ἀγαθῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 10, 'τῇ φιλαδελφίᾳ εἰς ἀλλήλους φιλόστοργοι, τῇ τιμῇ ἀλλήλους προηγούμενοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 11, 'τῇ σπουδῇ μὴ ὀκνηροί, τῷ πνεύματι ζέοντες, τῷ  ̊Κυρίῳ δουλεύοντες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 12, 'τῇ ἐλπίδι χαίροντες, τῇ θλίψει ὑπομένοντες, τῇ προσευχῇ προσκαρτεροῦντες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 13, 'ταῖς χρείαις τῶν ἁγίων κοινωνοῦντες, τὴν φιλοξενίαν διώκοντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 14, 'Εὐλογεῖτε τοὺς διώκοντας, ὑμᾶς εὐλογεῖτε καὶ μὴ καταρᾶσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 15, 'Χαίρειν μετὰ χαιρόντων, κλαίειν μετὰ κλαιόντων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 16, 'Τὸ αὐτὸ εἰς ἀλλήλους φρονοῦντες, μὴ τὰ ὑψηλὰ φρονοῦντες, ἀλλὰ τοῖς ταπεινοῖς συναπαγόμενοι. Μὴ γίνεσθε φρόνιμοι παρʼ ἑαυτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 17, 'Μηδενὶ κακὸν ἀντὶ κακοῦ ἀποδιδόντες, προνοούμενοι καλὰ ἐνώπιον πάντων ἀνθρώπων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 18, 'Εἰ δυνατόν τὸ ἐξ ὑμῶν, μετὰ πάντων ἀνθρώπων εἰρηνεύοντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 19, 'Μὴ ἑαυτοὺς ἐκδικοῦντες, ἀγαπητοί, ἀλλὰ δότε τόπον τῇ ὀργῇ, γέγραπται γάρ, “Ἐμοὶ ἐκδίκησις, ἐγὼ ἀνταποδώσω”, λέγει  ̊Κύριος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 20, '“Ἀλλὰ ἐὰν πεινᾷ ὁ ἐχθρός σου, ψώμιζε αὐτόν· ἐὰν διψᾷ, πότιζε αὐτόν· τοῦτο γὰρ ποιῶν, ἄνθρακας πυρὸς σωρεύσεις ἐπὶ τὴν κεφαλὴν αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 21, 'Μὴ νικῶ ὑπὸ τοῦ κακοῦ, ἀλλὰ νίκα ἐν τῷ ἀγαθῷ τὸ κακόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 1, '¶Πᾶσα ψυχὴ ἐξουσίαις ὑπερεχούσαις ὑποτασσέσθω, οὐ γὰρ ἔστιν ἐξουσία, εἰ μὴ ὑπὸ  ̊Θεοῦ, αἱ δὲ οὖσαι ὑπὸ  ̊Θεοῦ τεταγμέναι εἰσίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 2, 'Ὥστε ὁ ἀντιτασσόμενος τῇ ἐξουσίᾳ, τῇ τοῦ  ̊Θεοῦ διαταγῇ ἀνθέστηκεν, οἱ δὲ ἀνθεστηκότες, ἑαυτοῖς κρίμα λήμψονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 3, 'Οἱ γὰρ ἄρχοντες οὐκ εἰσὶν φόβος τῷ ἀγαθῷ ἔργῳ, ἀλλὰ τῷ κακῷ. Θέλεις δὲ μὴ φοβεῖσθαι τὴν ἐξουσίαν; Τὸ ἀγαθὸν ποίει, καὶ ἕξεις ἔπαινον ἐξ αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 4, ' ̊Θεοῦ γὰρ διάκονός ἐστιν σοὶ εἰς τὸ ἀγαθόν. Ἐὰν δὲ τὸ κακὸν ποιῇς, φοβοῦ· οὐ γὰρ εἰκῇ τὴν μάχαιραν φορεῖ·  ̊Θεοῦ γὰρ διάκονός ἐστιν, ἔκδικος εἰς ὀργὴν τῷ τὸ κακὸν πράσσοντι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 5, 'Διὸ ἀνάγκη ὑποτάσσεσθαι, οὐ μόνον διὰ τὴν ὀργὴν, ἀλλὰ καὶ διὰ τὴν συνείδησιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 6, 'Διὰ τοῦτο γὰρ, καὶ φόρους τελεῖτε, λειτουργοὶ γὰρ  ̊Θεοῦ εἰσιν, εἰς αὐτὸ τοῦτο προσκαρτεροῦντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 7, 'Ἀπόδοτε πᾶσι τὰς ὀφειλάς: τῷ τὸν φόρον, τὸν φόρον, τῷ τὸ τέλος, τὸ τέλος, τῷ τὸν φόβον, τὸν φόβον, τῷ τὴν τιμὴν, τὴν τιμήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 8, '¶Μηδενὶ μηδὲν ὀφείλετε, εἰ μὴ τὸ ἀλλήλους ἀγαπᾶν· ὁ γὰρ ἀγαπῶν τὸν ἕτερον, νόμον πεπλήρωκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 9, 'Τὸ γάρ, “Οὐ μοιχεύσεις”, “Οὐ φονεύσεις”, “Οὐ κλέψεις”, “οὐκ ἐπιθυμήσεις”, καὶ εἴ τις ἑτέρα ἐντολή ἐν τῷ λόγῳ τούτῳ, ἀνακεφαλαιοῦται, ἐν τῷ, “Ἀγαπήσεις τὸν πλησίον σου ὡς σεαυτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 10, 'Ἡ ἀγάπη τῷ πλησίον κακὸν οὐκ ἐργάζεται· πλήρωμα οὖν νόμου ἡ ἀγάπη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 11, '¶Καὶ τοῦτο εἰδότες τὸν καιρόν, ὅτι ὥρα ἤδη ὑμᾶς ἐξ ὕπνου ἐγερθῆναι, νῦν γὰρ ἐγγύτερον ἡμῶν ἡ σωτηρία, ἢ ὅτε ἐπιστεύσαμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 12, 'Ἡ νὺξ προέκοψεν, ἡ δὲ ἡμέρα ἤγγικεν. Ἀποθώμεθα οὖν τὰ ἔργα τοῦ σκότους, ἐνδυσώμεθα δὲ τὰ ὅπλα τοῦ φωτός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 13, 'Ὡς ἐν ἡμέρᾳ εὐσχημόνως περιπατήσωμεν, μὴ κώμοις καὶ μέθαις, μὴ κοίταις καὶ ἀσελγείαις, μὴ ἔριδι καὶ ζήλῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 14, 'Ἀλλὰ ἐνδύσασθε τὸν  ̊Κύριον  ̊Ἰησοῦν  ̊Χριστόν, καὶ τῆς σαρκὸς πρόνοιαν μὴ ποιεῖσθε, εἰς ἐπιθυμίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 1, '¶Τὸν δὲ ἀσθενοῦντα τῇ πίστει προσλαμβάνεσθε, μὴ εἰς διακρίσεις διαλογισμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 2, 'Ὃς μὲν πιστεύει φαγεῖν πάντα, ὁ δὲ ἀσθενῶν λάχανα ἐσθίει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 3, 'Ὁ ἐσθίων, τὸν μὴ ἐσθίοντα μὴ ἐξουθενείτω, ὁ δὲ μὴ ἐσθίων, τὸν ἐσθίοντα μὴ κρινέτω, ὁ  ̊Θεὸς γὰρ αὐτὸν προσελάβετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 4, 'Σὺ τίς εἶ, ὁ κρίνων ἀλλότριον οἰκέτην; Τῷ ἰδίῳ κυρίῳ στήκει ἢ πίπτει. Σταθήσεται δέ, δυνατεῖ γὰρ ὁ  ̊Κύριος στῆσαι αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 5, '¶Ὃς μὲν κρίνει ἡμέραν παρʼ ἡμέραν, ὃς δὲ κρίνει πᾶσαν ἡμέραν. Ἕκαστος ἐν τῷ ἰδίῳ νοῒ, πληροφορείσθω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 6, 'Ὁ φρονῶν τὴν ἡμέραν,  ̊Κυρίῳ φρονεῖ. Καὶ ὁ ἐσθίων,  ̊Κυρίῳ ἐσθίει, εὐχαριστεῖ γὰρ τῷ  ̊Θεῷ· καὶ ὁ μὴ ἐσθίων,  ̊Κυρίῳ οὐκ ἐσθίει, καὶ εὐχαριστεῖ τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 7, '¶Οὐδεὶς γὰρ ἡμῶν ἑαυτῷ ζῇ, καὶ οὐδεὶς ἑαυτῷ ἀποθνῄσκει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 8, 'Ἐάν τε γὰρ ζῶμεν, τῷ  ̊Κυρίῳ ζῶμεν, ἐάν τε ἀποθνῄσκωμεν, τῷ  ̊Κυρίῳ ἀποθνῄσκομεν. Ἐάν τε οὖν ζῶμεν, ἐάν τε ἀποθνῄσκωμεν, τοῦ  ̊Κυρίου ἐσμέν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 9, 'Εἰς τοῦτο γὰρ  ̊Χριστὸς ἀπέθανεν καὶ ἔζησεν, ἵνα καὶ νεκρῶν καὶ ζώντων κυριεύσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 10, '¶Σὺ δὲ τί κρίνεις τὸν ἀδελφόν σου; Ἢ καὶ σὺ τί ἐξουθενεῖς τὸν ἀδελφόν σου; Πάντες γὰρ παραστησόμεθα τῷ βήματι τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 11, 'Γέγραπται γάρ, “Ζῶ ἐγώ, λέγει  ̊Κύριος ὅτι ἐμοὶ κάμψει πᾶν γόνυ, καὶ πᾶσα γλῶσσα ἐξομολογήσεται τῷ  ̊Θεῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 12, 'Ἄρα οὖν ἕκαστος ἡμῶν περὶ ἑαυτοῦ, λόγον δώσει τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 13, '¶Μηκέτι οὖν ἀλλήλους κρίνωμεν, ἀλλὰ τοῦτο κρίνατε μᾶλλον, τὸ μὴ τιθέναι πρόσκομμα τῷ ἀδελφῷ ἢ σκάνδαλον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 14, 'Οἶδα καὶ πέπεισμαι ἐν  ̊Κυρίῳ  ̊Ἰησοῦ ὅτι οὐδὲν κοινὸν διʼ ἑαυτοῦ· εἰ μὴ τῷ λογιζομένῳ τι κοινὸν εἶναι, ἐκείνῳ κοινόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 15, 'Εἰ γὰρ διὰ βρῶμα, ὁ ἀδελφός σου λυπεῖται, οὐκέτι κατὰ ἀγάπην περιπατεῖς. Μὴ τῷ βρώματί σου ἐκεῖνον ἀπόλλυε, ὑπὲρ οὗ  ̊Χριστὸς ἀπέθανεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 16, 'Μὴ βλασφημείσθω οὖν ὑμῶν τὸ ἀγαθόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 17, 'Οὐ γάρ ἐστιν ἡ Βασιλεία τοῦ  ̊Θεοῦ βρῶσις καὶ πόσις, ἀλλὰ δικαιοσύνη, καὶ εἰρήνη, καὶ χαρὰ ἐν  ̊Πνεύματι Ἁγίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 18, 'Ὁ γὰρ ἐν τούτῳ δουλεύων τῷ  ̊Χριστῷ, εὐάρεστος τῷ  ̊Θεῷ καὶ δόκιμος τοῖς ἀνθρώποις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 19, 'Ἄρα οὖν τὰ τῆς εἰρήνης διώκωμεν, καὶ τὰ τῆς οἰκοδομῆς τῆς εἰς ἀλλήλους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 20, 'Μὴ ἕνεκεν βρώματος, κατάλυε τὸ ἔργον τοῦ  ̊Θεοῦ. Πάντα μὲν καθαρά, ἀλλὰ κακὸν τῷ ἀνθρώπῳ τῷ διὰ προσκόμματος ἐσθίοντι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 21, 'Καλὸν τὸ μὴ φαγεῖν κρέα, μηδὲ πιεῖν οἶνον, μηδὲ ἐν ᾧ ὁ ἀδελφός σου προσκόπτει, ἢ σκανδαλίζεται, ἢ ἀσθενεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 22, 'Σὺ πίστιν ἣν ἔχεις, κατὰ σεαυτὸν ἔχε ἐνώπιον τοῦ  ̊Θεοῦ. Μακάριος ὁ μὴ κρίνων ἑαυτὸν ἐν ᾧ δοκιμάζει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 23, 'Ὁ δὲ διακρινόμενος, ἐὰν φάγῃ, κατακέκριται, ὅτι οὐκ ἐκ πίστεως· πᾶν δὲ ὃ οὐκ ἐκ πίστεως, ἁμαρτία ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 24, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 25, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 26, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 1, '¶Ὀφείλομεν δὲ ἡμεῖς, οἱ δυνατοὶ, τὰ ἀσθενήματα τῶν ἀδυνάτων βαστάζειν, καὶ μὴ ἑαυτοῖς ἀρέσκειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 2, 'Ἕκαστος ἡμῶν τῷ πλησίον ἀρεσκέτω εἰς τὸ ἀγαθὸν πρὸς οἰκοδομήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 3, 'Καὶ γὰρ ὁ  ̊Χριστὸς οὐχ ἑαυτῷ ἤρεσεν, ἀλλὰ καθὼς γέγραπται, “Οἱ ὀνειδισμοὶ τῶν ὀνειδιζόντων σε, ἐπέπεσαν ἐπʼ ἐμέ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 4, 'Ὅσα γὰρ προεγράφη, εἰς τὴν ἡμετέραν διδασκαλίαν ἐγράφη, ἵνα διὰ τῆς ὑπομονῆς καὶ διὰ τῆς παρακλήσεως τῶν Γραφῶν, τὴν ἐλπίδα ἔχωμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 5, 'Ὁ δὲ  ̊Θεὸς τῆς ὑπομονῆς καὶ τῆς παρακλήσεως, δῴη ὑμῖν τὸ αὐτὸ φρονεῖν ἐν ἀλλήλοις κατὰ  ̊Χριστὸν  ̊Ἰησοῦν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 6, 'ἵνα ὁμοθυμαδὸν, ἐν ἑνὶ στόματι, δοξάζητε τὸν  ̊Θεὸν καὶ Πατέρα τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 7, '¶Διὸ προσλαμβάνεσθε ἀλλήλους, καθὼς καὶ ὁ  ̊Χριστὸς προσελάβετο ὑμᾶς, εἰς δόξαν τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 8, 'Λέγω γὰρ  ̊Χριστὸν διάκονον γεγενῆσθαι περιτομῆς ὑπὲρ ἀληθείας  ̊Θεοῦ, εἰς τὸ βεβαιῶσαι τὰς ἐπαγγελίας τῶν πατέρων');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 9, 'τὰ δὲ ἔθνη, ὑπὲρ ἐλέους δοξάσαι τὸν  ̊Θεόν, καθὼς γέγραπται, “Διὰ τοῦτο ἐξομολογήσομαί σοι ἐν ἔθνεσιν, καὶ τῷ ὀνόματί σου ψαλῶ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 10, 'Καὶ πάλιν λέγει, “Εὐφράνθητε, ἔθνη, μετὰ τοῦ λαοῦ αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 11, 'Καὶ πάλιν, “Αἰνεῖτε, πάντα τὰ ἔθνη, τὸν  ̊Κύριον, καὶ ἐπαινεσάτωσαν αὐτὸν πάντες οἱ λαοί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 12, 'Καὶ πάλιν Ἠσαΐας λέγει, “Ἔσται ἡ ῥίζα τοῦ Ἰεσσαί, καὶ ὁ ἀνιστάμενος ἄρχειν ἐθνῶν· ἐπʼ αὐτῷ ἔθνη ἐλπιοῦσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 13, 'Ὁ δὲ  ̊Θεὸς τῆς ἐλπίδος πληρώσαι ὑμᾶς πάσης χαρᾶς καὶ εἰρήνης ἐν τῷ πιστεύειν, εἰς τὸ περισσεύειν ὑμᾶς ἐν τῇ ἐλπίδι ἐν δυνάμει  ̊Πνεύματος Ἁγίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 14, '¶Πέπεισμαι δέ, ἀδελφοί μου, καὶ αὐτὸς ἐγὼ περὶ ὑμῶν, ὅτι καὶ αὐτοὶ μεστοί ἐστε ἀγαθωσύνης, πεπληρωμένοι πάσης γνώσεως, δυνάμενοι καὶ ἀλλήλους νουθετεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 15, 'Τολμηρότερον δὲ ἔγραψα ὑμῖν ἀπὸ μέρους, ὡς ἐπαναμιμνῄσκων ὑμᾶς, διὰ τὴν χάριν τὴν δοθεῖσάν μοι ὑπὸ τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 16, 'εἰς τὸ εἶναί με λειτουργὸν  ̊Χριστοῦ  ̊Ἰησοῦ εἰς τὰ ἔθνη, ἱερουργοῦντα τὸ εὐαγγέλιον τοῦ  ̊Θεοῦ, ἵνα γένηται ἡ προσφορὰ τῶν ἐθνῶν εὐπρόσδεκτος, ἡγιασμένη ἐν  ̊Πνεύματι Ἁγίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 17, 'Ἔχω οὖν τὴν καύχησιν ἐν  ̊Χριστῷ  ̊Ἰησοῦ τὰ πρὸς τὸν  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 18, 'Οὐ γὰρ τολμήσω τι λαλεῖν, ὧν οὐ κατειργάσατο  ̊Χριστὸς διʼ ἐμοῦ, εἰς ὑπακοὴν ἐθνῶν λόγῳ καὶ ἔργῳ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 19, 'ἐν δυνάμει σημείων καὶ τεράτων ἐν δυνάμει  ̊Πνεύματος  ̊Θεοῦ· ὥστε με ἀπὸ Ἰερουσαλὴμ καὶ κύκλῳ μέχρι τοῦ Ἰλλυρικοῦ, πεπληρωκέναι τὸ εὐαγγέλιον τοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 20, 'οὕτως δὲ φιλοτιμούμενον εὐαγγελίζεσθαι, οὐχ ὅπου ὠνομάσθη  ̊Χριστός, ἵνα μὴ ἐπʼ ἀλλότριον θεμέλιον οἰκοδομῶ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 21, 'ἀλλὰ καθὼς γέγραπται, “Οἷς οὐκ ἀνηγγέλη περὶ αὐτοῦ, ὄψονται, καὶ οἳ οὐκ ἀκηκόασιν, συνήσουσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 22, '¶Διὸ καὶ ἐνεκοπτόμην τὰ πολλὰ τοῦ ἐλθεῖν πρὸς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 23, 'Νυνὶ δὲ μηκέτι τόπον ἔχων ἐν τοῖς κλίμασι τούτοις, ἐπιποθίαν δὲ ἔχων τοῦ ἐλθεῖν πρὸς ὑμᾶς ἀπὸ πολλῶν ἐτῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 24, 'ὡς ἂν πορεύωμαι εἰς τὴν Σπανίαν, ἐλπίζω γὰρ διαπορευόμενος θεάσασθαι ὑμᾶς, καὶ ὑφʼ ὑμῶν προπεμφθῆναι ἐκεῖ, ἐὰν ὑμῶν πρῶτον ἀπὸ μέρους ἐμπλησθῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 25, 'Νυνὶ δὲ πορεύομαι εἰς Ἰερουσαλὴμ διακονῶν τοῖς ἁγίοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 26, 'εὐδόκησαν γὰρ Μακεδονία καὶ Ἀχαΐα κοινωνίαν τινὰ ποιήσασθαι εἰς τοὺς πτωχοὺς τῶν ἁγίων τῶν ἐν Ἰερουσαλήμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 27, 'Εὐδόκησαν γάρ καὶ ὀφειλέται εἰσὶν αὐτῶν· εἰ γὰρ τοῖς πνευματικοῖς αὐτῶν ἐκοινώνησαν τὰ ἔθνη, ὀφείλουσιν καὶ ἐν τοῖς σαρκικοῖς λειτουργῆσαι αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 28, 'Τοῦτο οὖν ἐπιτελέσας, καὶ σφραγισάμενος αὐτοῖς τὸν καρπὸν τοῦτον, ἀπελεύσομαι διʼ ὑμῶν εἰς Σπανίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 29, 'Οἶδα δὲ ὅτι ἐρχόμενος πρὸς ὑμᾶς, ἐν πληρώματι εὐλογίας  ̊Χριστοῦ, ἐλεύσομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 30, '¶Παρακαλῶ δὲ ὑμᾶς, ἀδελφοί, διὰ τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, καὶ διὰ τῆς ἀγάπης τοῦ  ̊Πνεύματος, συναγωνίσασθαί μοι ἐν ταῖς προσευχαῖς ὑπὲρ ἐμοῦ πρὸς τὸν  ̊Θεόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 31, 'ἵνα ῥυσθῶ ἀπὸ τῶν ἀπειθούντων ἐν τῇ Ἰουδαίᾳ, καὶ ἡ διακονία μου ἡ εἰς Ἰερουσαλὴμ εὐπρόσδεκτος τοῖς ἁγίοις γένηται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 32, 'ἵνα ἐν χαρᾷ ἔλθω πρὸς ὑμᾶς διὰ θελήματος  ̊Θεοῦ, συναναπαύσωμαι ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 33, 'Ὁ δὲ  ̊Θεὸς τῆς εἰρήνης μετὰ πάντων ὑμῶν. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 1, '¶Συνίστημι δὲ ὑμῖν Φοίβην, τὴν ἀδελφὴν ἡμῶν, οὖσαν καὶ διάκονον τῆς ἐκκλησίας τῆς ἐν Κεγχρεαῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 2, 'ἵνα προσδέξησθε αὐτὴν ἐν  ̊Κυρίῳ ἀξίως τῶν ἁγίων, καὶ παραστῆτε αὐτῇ ἐν ᾧ ἂν ὑμῶν χρῄζῃ πράγματι, καὶ γὰρ αὐτὴ προστάτις πολλῶν ἐγενήθη καὶ ἐμοῦ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 3, '¶Ἀσπάσασθε Πρίσκαν καὶ Ἀκύλαν, τοὺς συνεργούς μου ἐν  ̊Χριστῷ  ̊Ἰησοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 4, 'οἵτινες ὑπὲρ τῆς ψυχῆς μου, τὸν ἑαυτῶν τράχηλον ὑπέθηκαν, οἷς οὐκ ἐγὼ μόνος εὐχαριστῶ, ἀλλὰ καὶ πᾶσαι αἱ ἐκκλησίαι τῶν ἐθνῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 5, 'καὶ τὴν κατʼ οἶκον αὐτῶν ἐκκλησίαν. Ἀσπάσασθε Ἐπαίνετον, τὸν ἀγαπητόν μου, ὅς ἐστιν ἀπαρχὴ τῆς Ἀσίας εἰς  ̊Χριστόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 6, 'Ἀσπάσασθε Μαρίαν, ἥτις πολλὰ ἐκοπίασεν εἰς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 7, 'Ἀσπάσασθε Ἀνδρόνικον καὶ Ἰουνίαν, τοὺς συγγενεῖς μου καὶ συναιχμαλώτους μου, οἵτινές εἰσιν ἐπίσημοι ἐν τοῖς ἀποστόλοις, οἳ καὶ πρὸ ἐμοῦ γέγοναν ἐν  ̊Χριστῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 8, 'Ἀσπάσασθε Ἀμπλιᾶτον, τὸν ἀγαπητόν μου ἐν  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 9, 'Ἀσπάσασθε Οὐρβανὸν, τὸν συνεργὸν ἡμῶν ἐν  ̊Χριστῷ, καὶ Στάχυν τὸν ἀγαπητόν μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 10, 'Ἀσπάσασθε Ἀπελλῆν, τὸν δόκιμον ἐν  ̊Χριστῷ. Ἀσπάσασθε τοὺς ἐκ τῶν Ἀριστοβούλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 11, 'Ἀσπάσασθε Ἡρῳδίωνα, τὸν συγγενῆν μου. Ἀσπάσασθε τοὺς ἐκ τῶν Ναρκίσσου τοὺς ὄντας ἐν  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 12, 'Ἀσπάσασθε Τρύφαιναν καὶ Τρυφῶσαν, τὰς κοπιώσας ἐν  ̊Κυρίῳ. Ἀσπάσασθε Περσίδα, τὴν ἀγαπητήν, ἥτις πολλὰ ἐκοπίασεν ἐν  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 13, 'Ἀσπάσασθε Ῥοῦφον, τὸν ἐκλεκτὸν ἐν  ̊Κυρίῳ, καὶ τὴν μητέρα αὐτοῦ καὶ ἐμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 14, 'Ἀσπάσασθε Ἀσύγκριτον, Φλέγοντα, Ἑρμῆν, Πατρόβαν, Ἑρμᾶν, καὶ τοὺς σὺν αὐτοῖς ἀδελφούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 15, 'Ἀσπάσασθε Φιλόλογον καὶ Ἰουλίαν, Νηρέα καὶ τὴν ἀδελφὴν αὐτοῦ, καὶ Ὀλυμπᾶν, καὶ τοὺς σὺν αὐτοῖς πάντας ἁγίους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 16, 'Ἀσπάσασθε ἀλλήλους ἐν φιλήματι ἁγίῳ. Ἀσπάζονται ὑμᾶς αἱ ἐκκλησίαι πᾶσαι τοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 17, '¶Παρακαλῶ δὲ ὑμᾶς, ἀδελφοί, σκοπεῖν τοὺς τὰς διχοστασίας καὶ τὰ σκάνδαλα παρὰ τὴν διδαχὴν ἣν ὑμεῖς ἐμάθετε ποιοῦντας, καὶ ἐκκλίνετε ἀπʼ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 18, 'Οἱ γὰρ τοιοῦτοι τῷ  ̊Κυρίῳ ἡμῶν  ̊Χριστῷ οὐ δουλεύουσιν, ἀλλὰ τῇ ἑαυτῶν κοιλίᾳ, καὶ διὰ τῆς χρηστολογίας καὶ εὐλογίας, ἐξαπατῶσιν τὰς καρδίας τῶν ἀκάκων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 19, 'Ἡ γὰρ ὑμῶν ὑπακοὴ, εἰς πάντας ἀφίκετο. Ἐφʼ ὑμῖν οὖν χαίρω, θέλω δὲ ὑμᾶς σοφοὺς εἶναι εἰς τὸ ἀγαθόν, ἀκεραίους δὲ εἰς τὸ κακόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 20, 'Ὁ δὲ  ̊Θεὸς τῆς εἰρήνης συντρίψει τὸν Σατανᾶν ὑπὸ τοὺς πόδας ὑμῶν ἐν τάχει. Ἡ χάρις τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ μεθʼ ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 21, '¶Ἀσπάζεται ὑμᾶς Τιμόθεος, ὁ συνεργός μου, καὶ Λούκιος, καὶ Ἰάσων, καὶ Σωσίπατρος, οἱ συγγενεῖς μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 22, 'Ἀσπάζομαι ὑμᾶς ἐγὼ, Τέρτιος, ὁ γράψας τὴν ἐπιστολὴν, ἐν  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 23, 'Ἀσπάζεται ὑμᾶς Γάϊος, ὁ ξένος μου, καὶ ὅλης τῆς ἐκκλησίας. Ἀσπάζεται ὑμᾶς Ἔραστος, ὁ οἰκονόμος τῆς πόλεως, καὶ Κούαρτος ὁ ἀδελφός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 24, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 25, '¶Τῷ δὲ δυναμένῳ ὑμᾶς στηρίξαι, κατὰ τὸ εὐαγγέλιόν μου, καὶ τὸ κήρυγμα  ̊Ἰησοῦ  ̊Χριστοῦ κατὰ ἀποκάλυψιν μυστηρίου χρόνοις αἰωνίοις σεσιγημένου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 26, 'φανερωθέντος δὲ νῦν διά τε Γραφῶν προφητικῶν, κατʼ ἐπιταγὴν τοῦ αἰωνίου  ̊Θεοῦ εἰς ὑπακοὴν πίστεως, εἰς πάντα τὰ ἔθνη γνωρισθέντος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 27, 'Μόνῳ σοφῷ  ̊Θεῷ διὰ  ̊Ἰησοῦ  ̊Χριστοῦ, ᾧ ἡ δόξα εἰς τοὺς αἰῶνας. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, '¶Παῦλος, κλητὸς ἀπόστολος  ̊Χριστοῦ  ̊Ἰησοῦ διὰ θελήματος  ̊Θεοῦ, καὶ Σωσθένης, ὁ ἀδελφὸς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'τῇ ἐκκλησίᾳ τοῦ  ̊Θεοῦ, ἡγιασμένοις ἐν  ̊Χριστῷ  ̊Ἰησοῦ, τῇ οὔσῃ ἐν Κορίνθῳ, κλητοῖς ἁγίοις, σὺν πᾶσιν τοῖς ἐπικαλουμένοις τὸ ὄνομα τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, ἐν παντὶ τόπῳ, αὐτῶν καὶ ἡμῶν:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'χάρις ὑμῖν καὶ εἰρήνη ἀπὸ  ̊Θεοῦ Πατρὸς ἡμῶν καὶ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, '¶Εὐχαριστῶ τῷ  ̊Θεῷ μου πάντοτε περὶ ὑμῶν, ἐπὶ τῇ χάριτι τοῦ  ̊Θεοῦ τῇ δοθείσῃ ὑμῖν ἐν  ̊Χριστῷ  ̊Ἰησοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'ὅτι ἐν παντὶ ἐπλουτίσθητε ἐν αὐτῷ, ἐν παντὶ λόγῳ καὶ πάσῃ γνώσει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'καθὼς τὸ μαρτύριον τοῦ  ̊Χριστοῦ ἐβεβαιώθη ἐν ὑμῖν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'ὥστε ὑμᾶς μὴ ὑστερεῖσθαι ἐν μηδενὶ χαρίσματι, ἀπεκδεχομένους τὴν ἀποκάλυψιν τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'ὃς καὶ βεβαιώσει ὑμᾶς ἕως τέλους, ἀνεγκλήτους ἐν τῇ ἡμέρᾳ τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Πιστὸς ὁ  ̊Θεὸς, διʼ οὗ ἐκλήθητε εἰς κοινωνίαν τοῦ Υἱοῦ αὐτοῦ,  ̊Ἰησοῦ  ̊Χριστοῦ, τοῦ  ̊Κυρίου ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, '¶Παρακαλῶ δὲ ὑμᾶς, ἀδελφοί, διὰ τοῦ ὀνόματος τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, ἵνα τὸ αὐτὸ λέγητε πάντες, καὶ μὴ ᾖ ἐν ὑμῖν σχίσματα, ἦτε δὲ κατηρτισμένοι ἐν τῷ αὐτῷ νοῒ καὶ ἐν τῇ αὐτῇ γνώμῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Ἐδηλώθη γάρ μοι περὶ ὑμῶν, ἀδελφοί μου, ὑπὸ τῶν Χλόης, ὅτι ἔριδες ἐν ὑμῖν εἰσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Λέγω δὲ τοῦτο, ὅτι ἕκαστος ὑμῶν λέγει, “Ἐγὼ” μέν “εἰμι Παύλου”, “Ἐγὼ” δὲ “Ἀπολλῶ”, “Ἐγὼ” δὲ “Κηφᾶ”, “Ἐγὼ” δὲ “ ̊Χριστοῦ”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Μεμέρισται ὁ  ̊Χριστός; Μὴ Παῦλος ἐσταυρώθη ὑπὲρ ὑμῶν, ἢ εἰς τὸ ὄνομα Παύλου ἐβαπτίσθητε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Εὐχαριστῶ ὅτι οὐδένα ὑμῶν ἐβάπτισα, εἰ μὴ Κρίσπον καὶ Γάϊον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'ἵνα μή τις εἴπῃ ὅτι εἰς τὸ ἐμὸν ὄνομα ἐβαπτίσθητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 16, 'Ἐβάπτισα δὲ καὶ τὸν Στεφανᾶ οἶκον· λοιπὸν οὐκ οἶδα εἴ τινα ἄλλον ἐβάπτισα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 17, 'Οὐ γὰρ ἀπέστειλέν με  ̊Χριστὸς βαπτίζειν, ἀλλὰ εὐαγγελίζεσθαι, οὐκ ἐν σοφίᾳ λόγου, ἵνα μὴ κενωθῇ ὁ σταυρὸς τοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 18, '¶Ὁ λόγος γὰρ ὁ τοῦ σταυροῦ, τοῖς μὲν ἀπολλυμένοις μωρία ἐστίν, τοῖς δὲ σῳζομένοις ἡμῖν δύναμις  ̊Θεοῦ ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 19, 'Γέγραπται γάρ, “Ἀπολῶ τὴν σοφίαν τῶν σοφῶν, καὶ τὴν σύνεσιν τῶν συνετῶν ἀθετήσω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 20, 'Ποῦ σοφός; Ποῦ γραμματεύς; Ποῦ συζητητὴς τοῦ αἰῶνος τούτου; Οὐχὶ ἐμώρανεν ὁ  ̊Θεὸς τὴν σοφίαν τοῦ κόσμου;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 21, 'Ἐπειδὴ γὰρ ἐν τῇ σοφίᾳ τοῦ  ̊Θεοῦ, οὐκ ἔγνω ὁ κόσμος διὰ τῆς σοφίας τὸν  ̊Θεόν, εὐδόκησεν ὁ  ̊Θεὸς διὰ τῆς μωρίας τοῦ κηρύγματος σῶσαι τοὺς πιστεύοντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 22, 'Ἐπειδὴ καὶ Ἰουδαῖοι σημεῖα αἰτοῦσιν, καὶ Ἕλληνες σοφίαν ζητοῦσιν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 23, 'ἡμεῖς δὲ κηρύσσομεν  ̊Χριστὸν ἐσταυρωμένον, Ἰουδαίοις μὲν σκάνδαλον, ἔθνεσιν δὲ μωρίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 24, 'αὐτοῖς δὲ, τοῖς κλητοῖς, Ἰουδαίοις τε καὶ Ἕλλησιν,  ̊Χριστὸν  ̊Θεοῦ δύναμιν, καὶ  ̊Θεοῦ σοφίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 25, 'Ὅτι τὸ μωρὸν τοῦ  ̊Θεοῦ, σοφώτερον τῶν ἀνθρώπων ἐστίν, καὶ τὸ ἀσθενὲς τοῦ  ̊Θεοῦ, ἰσχυρότερον τῶν ἀνθρώπων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 26, '¶Βλέπετε γὰρ τὴν κλῆσιν ὑμῶν, ἀδελφοί, ὅτι οὐ πολλοὶ σοφοὶ κατὰ σάρκα, οὐ πολλοὶ δυνατοί, οὐ πολλοὶ εὐγενεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 27, 'Ἀλλὰ τὰ μωρὰ τοῦ κόσμου ἐξελέξατο ὁ  ̊Θεός, ἵνα καταισχύνῃ τοὺς σοφούς, καὶ τὰ ἀσθενῆ τοῦ κόσμου ἐξελέξατο ὁ  ̊Θεός, ἵνα καταισχύνῃ τὰ ἰσχυρά,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 28, 'καὶ τὰ ἀγενῆ τοῦ κόσμου καὶ τὰ ἐξουθενημένα ἐξελέξατο ὁ  ̊Θεός, τὰ μὴ ὄντα, ἵνα τὰ ὄντα καταργήσῃ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 29, 'ὅπως μὴ καυχήσηται πᾶσα σὰρξ ἐνώπιον τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 30, 'Ἐξ αὐτοῦ δὲ, ὑμεῖς ἐστε ἐν  ̊Χριστῷ  ̊Ἰησοῦ, ὃς ἐγενήθη σοφία ἡμῖν ἀπὸ  ̊Θεοῦ, δικαιοσύνη τε, καὶ ἁγιασμὸς, καὶ ἀπολύτρωσις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 31, 'ἵνα καθὼς γέγραπται, “Ὁ καυχώμενος, ἐν  ̊Κυρίῳ καυχάσθω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 1, '¶Κἀγὼ ἐλθὼν πρὸς ὑμᾶς, ἀδελφοί, ἦλθον οὐ καθʼ ὑπεροχὴν λόγου ἢ σοφίας, καταγγέλλων ὑμῖν τὸ μυστήριον τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 2, 'Οὐ γὰρ ἔκρινά τι εἰδέναι ἐν ὑμῖν, εἰ μὴ  ̊Ἰησοῦν  ̊Χριστὸν, καὶ τοῦτον ἐσταυρωμένον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 3, 'Κἀγὼ ἐν ἀσθενείᾳ, καὶ ἐν φόβῳ, καὶ ἐν τρόμῳ πολλῷ ἐγενόμην πρὸς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 4, 'Καὶ ὁ λόγος μου καὶ τὸ κήρυγμά μου, οὐκ ἐν πειθοῖς σοφίας λόγοις, ἀλλʼ ἐν ἀποδείξει  ̊Πνεύματος καὶ δυνάμεως,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 5, 'ἵνα ἡ πίστις ὑμῶν, μὴ ᾖ ἐν σοφίᾳ ἀνθρώπων, ἀλλʼ ἐν δυνάμει  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 6, '¶Σοφίαν δὲ λαλοῦμεν ἐν τοῖς τελείοις, σοφίαν δὲ, οὐ τοῦ αἰῶνος τούτου, οὐδὲ τῶν ἀρχόντων τοῦ αἰῶνος τούτου, τῶν καταργουμένων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 7, 'ἀλλὰ λαλοῦμεν  ̊Θεοῦ σοφίαν ἐν μυστηρίῳ τὴν ἀποκεκρυμμένην, ἣν προώρισεν ὁ  ̊Θεὸς πρὸ τῶν αἰώνων, εἰς δόξαν ἡμῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 8, 'ἣν οὐδεὶς τῶν ἀρχόντων τοῦ αἰῶνος τούτου ἔγνωκεν, εἰ γὰρ ἔγνωσαν, οὐκ ἂν τὸν  ̊Κύριον τῆς δόξης ἐσταύρωσαν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 9, 'ἀλλὰ καθὼς γέγραπται, “Ἃ ὀφθαλμὸς οὐκ εἶδεν, καὶ οὖς οὐκ ἤκουσεν, καὶ ἐπὶ καρδίαν ἀνθρώπου οὐκ ἀνέβη, ἃ ἡτοίμασεν ὁ  ̊Θεὸς τοῖς ἀγαπῶσιν αὐτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 10, 'Ἡμῖν γὰρ ἀπεκάλυψεν ὁ  ̊Θεὸς διὰ τοῦ  ̊Πνεύματος, τὸ γὰρ  ̊Πνεῦμα πάντα ἐραυνᾷ, καὶ τὰ βάθη τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 11, 'Τίς γὰρ οἶδεν ἀνθρώπων τὰ τοῦ ἀνθρώπου, εἰ μὴ τὸ πνεῦμα τοῦ ἀνθρώπου τὸ ἐν αὐτῷ; Οὕτως καὶ τὰ τοῦ  ̊Θεοῦ οὐδεὶς ἔγνωκεν, εἰ μὴ τὸ  ̊Πνεῦμα τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 12, 'Ἡμεῖς δὲ οὐ τὸ πνεῦμα τοῦ κόσμου ἐλάβομεν, ἀλλὰ τὸ  ̊Πνεῦμα τὸ ἐκ τοῦ  ̊Θεοῦ, ἵνα εἰδῶμεν τὰ ὑπὸ τοῦ  ̊Θεοῦ χαρισθέντα ἡμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 13, 'Ἃ καὶ λαλοῦμεν, οὐκ ἐν διδακτοῖς ἀνθρωπίνης σοφίας λόγοις, ἀλλʼ ἐν διδακτοῖς  ̊Πνεύματος, πνευματικοῖς πνευματικὰ συγκρίνοντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 14, '¶Ψυχικὸς δὲ ἄνθρωπος, οὐ δέχεται τὰ τοῦ  ̊Πνεύματος τοῦ  ̊Θεοῦ, μωρία γὰρ αὐτῷ ἐστίν, καὶ οὐ δύναται γνῶναι, ὅτι πνευματικῶς ἀνακρίνεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 15, 'Ὁ δὲ πνευματικὸς ἀνακρίνει τὰ πάντα, αὐτὸς δὲ ὑπʼ οὐδενὸς ἀνακρίνεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 16, '“Τίς” γὰρ “ἔγνω νοῦν  ̊Κυρίου, ὃς συμβιβάσει αὐτόν;” Ἡμεῖς δὲ νοῦν  ̊Χριστοῦ ἔχομεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 1, '¶Κἀγώ, ἀδελφοί, οὐκ ἠδυνήθην λαλῆσαι ὑμῖν ὡς πνευματικοῖς, ἀλλʼ ὡς σαρκίνοις, ὡς νηπίοις ἐν  ̊Χριστῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 2, 'Γάλα ὑμᾶς ἐπότισα, οὐ βρῶμα, οὔπω γὰρ ἐδύνασθε. Ἀλλʼ οὐδὲ ἔτι νῦν δύνασθε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 3, 'ἔτι γὰρ σαρκικοί ἐστε. Ὅπου γὰρ ἐν ὑμῖν ζῆλος καὶ ἔρις, οὐχὶ σαρκικοί ἐστε καὶ κατὰ ἄνθρωπον περιπατεῖτε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 4, 'Ὅταν γὰρ λέγῃ τις, “Ἐγὼ” μέν “εἰμι Παύλου”, ἕτερος δέ, “Ἐγὼ Ἀπολλῶ”, οὐκ ἄνθρωποί ἐστε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 5, '¶Τί οὖν ἐστιν Ἀπολλῶς; Τί δέ ἐστιν Παῦλος; Διάκονοι διʼ ὧν ἐπιστεύσατε, καὶ ἑκάστῳ ὡς ὁ  ̊Κύριος ἔδωκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 6, 'Ἐγὼ ἐφύτευσα, Ἀπολλῶς ἐπότισεν, ἀλλὰ ὁ  ̊Θεὸς ηὔξανεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 7, 'Ὥστε οὔτε ὁ φυτεύων ἐστίν τι, οὔτε ὁ ποτίζων, ἀλλʼ ὁ αὐξάνων,  ̊Θεός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 8, 'Ὁ φυτεύων δὲ, καὶ ὁ ποτίζων, ἕν εἰσιν, ἕκαστος δὲ τὸν ἴδιον μισθὸν λήμψεται, κατὰ τὸν ἴδιον κόπον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 9, ' ̊Θεοῦ γάρ ἐσμεν συνεργοί·  ̊Θεοῦ γεώργιον,  ̊Θεοῦ οἰκοδομή ἐστε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 10, '¶Κατὰ τὴν χάριν τοῦ  ̊Θεοῦ τὴν δοθεῖσάν μοι, ὡς σοφὸς ἀρχιτέκτων θεμέλιον ἔθηκα, ἄλλος δὲ ἐποικοδομεῖ. Ἕκαστος δὲ βλεπέτω, πῶς ἐποικοδομεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 11, 'Θεμέλιον γὰρ ἄλλον οὐδεὶς δύναται θεῖναι, παρὰ τὸν κείμενον, ὅς ἐστιν  ̊Ἰησοῦς  ̊Χριστός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 12, 'Εἰ δέ τις ἐποικοδομεῖ ἐπὶ τὸν θεμέλιον χρυσίον, ἀργύριον, λίθους τιμίους, ξύλα, χόρτον, καλάμην,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 13, 'ἑκάστου τὸ ἔργον φανερὸν γενήσεται, ἡ γὰρ ἡμέρα δηλώσει, ὅτι ἐν πυρὶ ἀποκαλύπτεται, καὶ ἑκάστου τὸ ἔργον, ὁποῖόν ἐστιν, τὸ πῦρ αὐτὸ δοκιμάσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 14, 'Εἴ τινος τὸ ἔργον μενεῖ, ὃ ἐποικοδόμησεν, μισθὸν λήμψεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 15, 'Εἴ τινος τὸ ἔργον κατακαήσεται, ζημιωθήσεται, αὐτὸς δὲ σωθήσεται, οὕτως δὲ ὡς διὰ πυρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 16, '¶Οὐκ οἴδατε ὅτι ναὸς  ̊Θεοῦ ἐστε, καὶ τὸ  ̊Πνεῦμα τοῦ  ̊Θεοῦ οἰκεῖ ἐν ὑμῖν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 17, 'Εἴ τις τὸν ναὸν τοῦ  ̊Θεοῦ φθείρει, φθερεῖ τοῦτον ὁ  ̊Θεός· ὁ γὰρ ναὸς τοῦ  ̊Θεοῦ ἅγιός ἐστιν, οἵτινές ἐστε ὑμεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 18, '¶Μηδεὶς ἑαυτὸν ἐξαπατάτω· εἴ τις δοκεῖ σοφὸς εἶναι ἐν ὑμῖν ἐν τῷ αἰῶνι τούτῳ, μωρὸς γενέσθω, ἵνα γένηται σοφός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 19, 'Ἡ γὰρ σοφία τοῦ κόσμου τούτου, μωρία παρὰ τῷ  ̊Θεῷ ἐστιν. Γέγραπται γάρ, “Ὁ δρασσόμενος τοὺς σοφοὺς ἐν τῇ πανουργίᾳ αὐτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 20, 'Καὶ πάλιν, “ ̊Κύριος γινώσκει τοὺς διαλογισμοὺς τῶν σοφῶν, ὅτι εἰσὶν μάταιοι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 21, 'Ὥστε μηδεὶς καυχάσθω ἐν ἀνθρώποις· πάντα γὰρ ὑμῶν ἐστιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 22, 'εἴτε Παῦλος, εἴτε Ἀπολλῶς, εἴτε Κηφᾶς, εἴτε κόσμος, εἴτε ζωὴ, εἴτε θάνατος, εἴτε ἐνεστῶτα, εἴτε μέλλοντα, πάντα ὑμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 23, 'ὑμεῖς δὲ  ̊Χριστοῦ,  ̊Χριστὸς δὲ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 1, '¶Οὕτως ἡμᾶς λογιζέσθω ἄνθρωπος ὡς ὑπηρέτας  ̊Χριστοῦ, καὶ οἰκονόμους μυστηρίων  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 2, 'Ὧδε λοιπὸν ζητεῖται ἐν τοῖς οἰκονόμοις ἵνα πιστός τις εὑρεθῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 3, 'Ἐμοὶ δὲ εἰς ἐλάχιστόν ἐστιν, ἵνα ὑφʼ ὑμῶν ἀνακριθῶ, ἢ ὑπὸ ἀνθρωπίνης ἡμέρας· ἀλλʼ οὐδὲ ἐμαυτὸν ἀνακρίνω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 4, 'Οὐδὲν γὰρ ἐμαυτῷ σύνοιδα, ἀλλʼ οὐκ ἐν τούτῳ δεδικαίωμαι, ὁ δὲ ἀνακρίνων με  ̊Κύριός ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 5, 'Ὥστε μὴ πρὸ καιροῦ τι κρίνετε, ἕως ἂν ἔλθῃ ὁ  ̊Κύριος, ὃς καὶ φωτίσει τὰ κρυπτὰ τοῦ σκότους, καὶ φανερώσει τὰς βουλὰς τῶν καρδιῶν, καὶ τότε ὁ ἔπαινος γενήσεται ἑκάστῳ ἀπὸ τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 6, '¶Ταῦτα δέ, ἀδελφοί, μετεσχημάτισα εἰς ἐμαυτὸν καὶ Ἀπολλῶν διʼ ὑμᾶς, ἵνα ἐν ἡμῖν μάθητε, τό “Μὴ ὑπὲρ ἃ γέγραπται”, ἵνα μὴ εἷς ὑπὲρ τοῦ ἑνὸς, φυσιοῦσθε κατὰ τοῦ ἑτέρου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 7, 'Τίς γάρ σε διακρίνει; Τί δὲ ἔχεις ὃ οὐκ ἔλαβες; Εἰ δὲ καὶ ἔλαβες, τί καυχᾶσαι ὡς μὴ λαβών;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 8, '¶Ἤδη κεκορεσμένοι ἐστέ, ἤδη ἐπλουτήσατε, χωρὶς ἡμῶν ἐβασιλεύσατε, καὶ ὄφελόν γε ἐβασιλεύσατε, ἵνα καὶ ἡμεῖς ὑμῖν συμβασιλεύσωμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 9, 'Δοκῶ γάρ ὁ  ̊Θεὸς ἡμᾶς τοὺς ἀποστόλους ἐσχάτους ἀπέδειξεν, ὡς ἐπιθανατίους, ὅτι θέατρον ἐγενήθημεν τῷ κόσμῳ, καὶ ἀγγέλοις καὶ ἀνθρώποις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 10, 'Ἡμεῖς μωροὶ διὰ  ̊Χριστόν, ὑμεῖς δὲ φρόνιμοι ἐν  ̊Χριστῷ· ἡμεῖς ἀσθενεῖς, ὑμεῖς δὲ ἰσχυροί· ὑμεῖς ἔνδοξοι, ἡμεῖς δὲ ἄτιμοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 11, 'Ἄχρι τῆς ἄρτι ὥρας, καὶ πεινῶμεν καὶ διψῶμεν, καὶ γυμνιτεύομεν, καὶ κολαφιζόμεθα, καὶ ἀστατοῦμεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 12, 'καὶ κοπιῶμεν, ἐργαζόμενοι ταῖς ἰδίαις χερσίν. Λοιδορούμενοι, εὐλογοῦμεν, διωκόμενοι, ἀνεχόμεθα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 13, 'δυσφημούμενοι, παρακαλοῦμεν· ὡς περικαθάρματα τοῦ κόσμου ἐγενήθημεν, πάντων περίψημα ἕως ἄρτι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 14, '¶Οὐκ ἐντρέπων ὑμᾶς γράφω ταῦτα, ἀλλʼ ὡς τέκνα μου ἀγαπητὰ, νουθετῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 15, 'Ἐὰν γὰρ μυρίους παιδαγωγοὺς ἔχητε ἐν  ̊Χριστῷ, ἀλλʼ οὐ πολλοὺς πατέρας, ἐν γὰρ  ̊Χριστῷ  ̊Ἰησοῦ διὰ τοῦ εὐαγγελίου, ἐγὼ ὑμᾶς ἐγέννησα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 16, 'Παρακαλῶ οὖν ὑμᾶς, μιμηταί μου γίνεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 17, 'Διὰ τοῦτο ἔπεμψα ὑμῖν Τιμόθεον, ὅς ἐστίν μου τέκνον, ἀγαπητὸν καὶ πιστὸν ἐν  ̊Κυρίῳ, ὃς ὑμᾶς ἀναμνήσει τὰς ὁδούς μου τὰς ἐν  ̊Χριστῷ  ̊Ἰησοῦ, καθὼς πανταχοῦ ἐν πάσῃ ἐκκλησίᾳ διδάσκω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 18, 'Ὡς μὴ ἐρχομένου δέ μου πρὸς ὑμᾶς, ἐφυσιώθησάν τινες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 19, 'Ἐλεύσομαι δὲ ταχέως πρὸς ὑμᾶς, ἐὰν ὁ  ̊Κύριος θελήσῃ, καὶ γνώσομαι, οὐ τὸν λόγον τῶν πεφυσιωμένων, ἀλλὰ τὴν δύναμιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 20, 'Οὐ γὰρ ἐν λόγῳ ἡ Βασιλεία τοῦ  ̊Θεοῦ, ἀλλʼ ἐν δυνάμει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 21, 'Τί θέλετε; Ἐν ῥάβδῳ ἔλθω πρὸς ὑμᾶς, ἢ ἐν ἀγάπῃ, πνεύματί τε πραΰτητος;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 1, '¶Ὅλως ἀκούεται ἐν ὑμῖν πορνεία, καὶ τοιαύτη πορνεία ἥτις οὐδὲ ἐν τοῖς ἔθνεσιν, ὥστε γυναῖκά τινα τοῦ πατρὸς ἔχειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 2, 'Καὶ ὑμεῖς πεφυσιωμένοι ἐστέ, καὶ οὐχὶ μᾶλλον ἐπενθήσατε, ἵνα ἀρθῇ ἐκ μέσου ὑμῶν ὁ, τὸ ἔργον τοῦτο ποιήσας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 3, 'Ἐγὼ μὲν γάρ ἀπὼν τῷ σώματι, παρὼν δὲ τῷ πνεύματι, ἤδη κέκρικα ὡς παρὼν, τὸν οὕτως τοῦτο κατεργασάμενον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 4, 'Ἐν τῷ ὀνόματι τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ συναχθέντων ὑμῶν καὶ τοῦ ἐμοῦ πνεύματος, σὺν τῇ δυνάμει τοῦ  ̊Κυρίου ἡμῶν  ̊Ἰησοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 5, 'παραδοῦναι τὸν τοιοῦτον τῷ Σατανᾷ εἰς ὄλεθρον τῆς σαρκός, ἵνα τὸ πνεῦμα σωθῇ ἐν τῇ ἡμέρᾳ τοῦ  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 6, '¶Οὐ καλὸν τὸ καύχημα ὑμῶν. Οὐκ οἴδατε ὅτι μικρὰ ζύμη, ὅλον τὸ φύραμα ζυμοῖ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 7, 'Ἐκκαθάρατε τὴν παλαιὰν ζύμην, ἵνα ἦτε νέον φύραμα, καθώς ἐστε ἄζυμοι. Καὶ γὰρ τὸ Πάσχα ἡμῶν ἐτύθη,  ̊Χριστός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 8, 'Ὥστε ἑορτάζωμεν, μὴ ἐν ζύμῃ παλαιᾷ, μηδὲ ἐν ζύμῃ κακίας καὶ πονηρίας, ἀλλʼ ἐν ἀζύμοις εἰλικρινείας καὶ ἀληθείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 9, '¶Ἔγραψα ὑμῖν ἐν τῇ ἐπιστολῇ, μὴ συναναμίγνυσθαι πόρνοις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 10, 'οὐ πάντως τοῖς πόρνοις τοῦ κόσμου τούτου, ἢ τοῖς πλεονέκταις καὶ ἅρπαξιν, ἢ εἰδωλολάτραις, ἐπεὶ ὠφείλετε ἄρα ἐκ τοῦ κόσμου ἐξελθεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 11, 'Νῦν δὲ ἔγραψα ὑμῖν μὴ συναναμίγνυσθαι ἐάν τις “ἀδελφὸς” ὀνομαζόμενος ᾖ πόρνος, ἢ πλεονέκτης, ἢ εἰδωλολάτρης, ἢ λοίδορος, ἢ μέθυσος, ἢ ἅρπαξ, τῷ τοιούτῳ μηδὲ συνεσθίειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 12, 'Τί γάρ μοι τοὺς ἔξω κρίνειν; Οὐχὶ τοὺς ἔσω ὑμεῖς κρίνετε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 13, 'Τοὺς δὲ ἔξω ὁ  ̊Θεὸς κρίνει. “Ἐξάρατε τὸν πονηρὸν ἐξ ὑμῶν αὐτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 1, '¶Τολμᾷ τις ὑμῶν, πρᾶγμα ἔχων πρὸς τὸν ἕτερον, κρίνεσθαι ἐπὶ τῶν ἀδίκων, καὶ οὐχὶ ἐπὶ τῶν ἁγίων;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 2, 'Ἢ οὐκ οἴδατε ὅτι οἱ ἅγιοι τὸν κόσμον κρινοῦσιν; Καὶ εἰ ἐν ὑμῖν κρίνεται ὁ κόσμος, ἀνάξιοί ἐστε κριτηρίων ἐλαχίστων;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 3, 'Οὐκ οἴδατε ὅτι ἀγγέλους κρινοῦμεν, μήτι γε βιωτικά;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 4, 'Βιωτικὰ μὲν οὖν κριτήρια ἐὰν ἔχητε, τοὺς ἐξουθενημένους ἐν τῇ ἐκκλησίᾳ, τούτους καθίζετε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 5, 'Πρὸς ἐντροπὴν ὑμῖν λέγω. Οὕτως οὐκ ἔνι ἐν ὑμῖν οὐδεὶς σοφὸς, ὃς δυνήσεται διακρῖναι ἀνὰ μέσον τοῦ ἀδελφοῦ αὐτοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 6, 'Ἀλλὰ ἀδελφὸς μετὰ ἀδελφοῦ κρίνεται, καὶ τοῦτο ἐπὶ ἀπίστων;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 7, 'Ἤδη μὲν οὖν ὅλως ἥττημα ὑμῖν ἐστιν, ὅτι κρίματα ἔχετε μεθʼ ἑαυτῶν. Διὰ τί οὐχὶ μᾶλλον ἀδικεῖσθε; Διὰ τί οὐχὶ μᾶλλον ἀποστερεῖσθε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 8, 'Ἀλλὰ ὑμεῖς ἀδικεῖτε καὶ ἀποστερεῖτε, καὶ τοῦτο ἀδελφούς!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 9, '¶Ἢ οὐκ οἴδατε ὅτι ἄδικοι  ̊Θεοῦ Βασιλείαν οὐ κληρονομήσουσιν; Μὴ πλανᾶσθε· οὔτε πόρνοι, οὔτε εἰδωλολάτραι, οὔτε μοιχοὶ, οὔτε μαλακοὶ, οὔτε ἀρσενοκοῖται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 10, 'οὔτε κλέπται, οὔτε πλεονέκται, οὐ μέθυσοι, οὐ λοίδοροι, οὐχ ἅρπαγες, Βασιλείαν  ̊Θεοῦ κληρονομήσουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 11, 'Καὶ ταῦτά τινες ἦτε· ἀλλὰ ἀπελούσασθε, ἀλλὰ ἡγιάσθητε, ἀλλὰ ἐδικαιώθητε, ἐν τῷ ὀνόματι τοῦ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ, καὶ ἐν τῷ  ̊Πνεύματι τοῦ  ̊Θεοῦ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 12, '¶Πάντα μοι ἔξεστιν, ἀλλʼ οὐ πάντα συμφέρει. Πάντα μοι ἔξεστιν, ἀλλʼ οὐκ ἐγὼ ἐξουσιασθήσομαι ὑπό τινος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 13, 'Τὰ βρώματα τῇ κοιλίᾳ, καὶ ἡ κοιλία τοῖς βρώμασιν· ὁ δὲ  ̊Θεὸς καὶ ταύτην καὶ ταῦτα καταργήσει. Τὸ δὲ σῶμα οὐ τῇ πορνείᾳ, ἀλλὰ τῷ  ̊Κυρίῳ, καὶ ὁ  ̊Κύριος τῷ σώματι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 14, 'Ὁ δὲ  ̊Θεὸς καὶ τὸν  ̊Κύριον ἤγειρεν, καὶ ἡμᾶς ἐξεγερεῖ, διὰ τῆς δυνάμεως αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 15, 'Οὐκ οἴδατε ὅτι τὰ σώματα ὑμῶν μέλη  ̊Χριστοῦ ἐστιν; Ἄρας οὖν τὰ μέλη τοῦ  ̊Χριστοῦ, ποιήσω πόρνης μέλη; Μὴ γένοιτο!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 16, 'Ἢ οὐκ οἴδατε ὅτι ὁ κολλώμενος τῇ πόρνῃ, ἓν σῶμά ἐστιν; “Ἔσονται” γάρ, φησίν, “οἱ δύο εἰς σάρκα μίαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 17, 'Ὁ δὲ κολλώμενος τῷ  ̊Κυρίῳ, ἓν πνεῦμά ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 18, 'Φεύγετε τὴν πορνείαν. Πᾶν ἁμάρτημα ὃ ἐὰν ποιήσῃ ἄνθρωπος ἐκτὸς τοῦ σώματός ἐστιν, ὁ δὲ πορνεύων εἰς τὸ ἴδιον σῶμα ἁμαρτάνει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 19, 'Ἢ οὐκ οἴδατε ὅτι τὸ σῶμα ὑμῶν, ναὸς τοῦ ἐν ὑμῖν Ἁγίου  ̊Πνεύματός ἐστιν, οὗ ἔχετε ἀπὸ  ̊Θεοῦ; Καὶ οὐκ ἐστὲ ἑαυτῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 20, 'ἠγοράσθητε γὰρ τιμῆς· δοξάσατε δὴ τὸν  ̊Θεὸν ἐν τῷ σώματι ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 1, '¶Περὶ δὲ ὧν ἐγράψατε, καλὸν ἀνθρώπῳ, γυναικὸς μὴ ἅπτεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 2, 'Διὰ δὲ τὰς πορνείας, ἕκαστος τὴν ἑαυτοῦ γυναῖκα ἐχέτω, καὶ ἑκάστη τὸν ἴδιον ἄνδρα ἐχέτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 3, 'Τῇ γυναικὶ ὁ ἀνὴρ τὴν ὀφειλὴν ἀποδιδότω, ὁμοίως δὲ καὶ ἡ γυνὴ τῷ ἀνδρί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 4, 'Ἡ γυνὴ τοῦ ἰδίου σώματος οὐκ ἐξουσιάζει, ἀλλὰ ὁ ἀνήρ· ὁμοίως δὲ, καὶ ὁ ἀνὴρ τοῦ ἰδίου σώματος οὐκ ἐξουσιάζει, ἀλλὰ ἡ γυνή.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 5, 'Μὴ ἀποστερεῖτε ἀλλήλους, εἰ μήτι ἂν ἐκ συμφώνου πρὸς καιρὸν, ἵνα σχολάσητε τῇ προσευχῇ, καὶ πάλιν ἐπὶ τὸ αὐτὸ ἦτε, ἵνα μὴ πειράζῃ ὑμᾶς ὁ Σατανᾶς, διὰ τὴν ἀκρασίαν ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 6, 'Τοῦτο δὲ λέγω κατὰ συγγνώμην, οὐ κατʼ ἐπιταγήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 7, 'Θέλω δὲ πάντας ἀνθρώπους εἶναι ὡς καὶ ἐμαυτόν. Ἀλλὰ ἕκαστος ἴδιον ἔχει χάρισμα ἐκ  ̊Θεοῦ, ὁ μὲν οὕτως, ὁ δὲ οὕτως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 8, '¶Λέγω δὲ τοῖς ἀγάμοις καὶ ταῖς χήραις, καλὸν αὐτοῖς ἐὰν μείνωσιν ὡς κἀγώ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 9, 'Εἰ δὲ οὐκ ἐγκρατεύονται, γαμησάτωσαν, κρεῖττον γάρ ἐστιν γαμῆσαι, ἢ πυροῦσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 10, '¶Τοῖς δὲ γεγαμηκόσιν, παραγγέλλω (οὐκ ἐγὼ, ἀλλὰ ὁ  ̊Κύριος), γυναῖκα ἀπὸ ἀνδρὸς μὴ χωρισθῆναι');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 11, '(ἐὰν δὲ καὶ χωρισθῇ, μενέτω ἄγαμος ἢ τῷ ἀνδρὶ καταλλαγήτω) καὶ ἄνδρα γυναῖκα μὴ ἀφιέναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 12, '¶Τοῖς δὲ λοιποῖς λέγω (ἐγώ, οὐχ ὁ  ̊Κύριος), εἴ τις ἀδελφὸς γυναῖκα ἔχει ἄπιστον, καὶ αὕτη συνευδοκεῖ οἰκεῖν μετʼ αὐτοῦ, μὴ ἀφιέτω αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 13, 'Καὶ γυνὴ ἥτις ἔχει ἄνδρα ἄπιστον, καὶ οὗτος συνευδοκεῖ οἰκεῖν μετʼ αὐτῆς, μὴ ἀφιέτω τὸν ἄνδρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 14, 'Ἡγίασται γὰρ ὁ ἀνὴρ ὁ ἄπιστος ἐν τῇ γυναικί, καὶ ἡγίασται ἡ γυνὴ ἡ ἄπιστος ἐν τῷ ἀδελφῷ· ἐπεὶ ἄρα τὰ τέκνα ὑμῶν ἀκάθαρτά ἐστιν, νῦν δὲ ἅγιά ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 15, 'Εἰ δὲ ὁ ἄπιστος χωρίζεται, χωριζέσθω. Οὐ δεδούλωται ὁ ἀδελφὸς ἢ ἡ ἀδελφὴ ἐν τοῖς τοιούτοις, ἐν δὲ εἰρήνῃ κέκληκεν ἡμᾶς ὁ  ̊Θεός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 16, 'Τί γὰρ οἶδας, γύναι, εἰ τὸν ἄνδρα σώσεις; Ἢ τί οἶδας, ἄνερ, εἰ τὴν γυναῖκα σώσεις;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 17, '¶Εἰ μὴ ἑκάστῳ ὡς μεμέρικεν ὁ  ̊Κύριος, ἕκαστον ὡς κέκληκεν ὁ  ̊Θεός, οὕτως περιπατείτω. Καὶ οὕτως ἐν ταῖς ἐκκλησίαις πάσαις διατάσσομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 18, 'Περιτετμημένος τις ἐκλήθη; Μὴ ἐπισπάσθω. Ἐν ἀκροβυστίᾳ κέκληταί τις; Μὴ περιτεμνέσθω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 19, 'Ἡ περιτομὴ οὐδέν ἐστιν, καὶ ἡ ἀκροβυστία οὐδέν ἐστιν, ἀλλὰ τήρησις ἐντολῶν  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 20, 'Ἕκαστος ἐν τῇ κλήσει ᾗ ἐκλήθη, ἐν ταύτῃ μενέτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 21, '¶Δοῦλος ἐκλήθης; Μή σοι μελέτω· ἀλλʼ εἰ καὶ δύνασαι ἐλεύθερος γενέσθαι, μᾶλλον χρῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 22, 'Ὁ γὰρ ἐν  ̊Κυρίῳ κληθεὶς δοῦλος, ἀπελεύθερος  ̊Κυρίου ἐστίν· ὁμοίως ὁ ἐλεύθερος κληθεὶς, δοῦλός ἐστιν  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 23, 'Τιμῆς ἠγοράσθητε· μὴ γίνεσθε δοῦλοι ἀνθρώπων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 24, 'Ἕκαστος ἐν ᾧ ἐκλήθη, ἀδελφοί, ἐν τούτῳ μενέτω παρὰ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 25, '¶Περὶ δὲ τῶν παρθένων, ἐπιταγὴν  ̊Κυρίου οὐκ ἔχω, γνώμην δὲ δίδωμι, ὡς ἠλεημένος ὑπὸ  ̊Κυρίου, πιστὸς εἶναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 26, 'Νομίζω οὖν τοῦτο καλὸν ὑπάρχειν διὰ τὴν ἐνεστῶσαν ἀνάγκην, ὅτι καλὸν ἀνθρώπῳ τὸ οὕτως εἶναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 27, 'Δέδεσαι γυναικί; Μὴ ζήτει λύσιν. Λέλυσαι ἀπὸ γυναικός; Μὴ ζήτει γυναῖκα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 28, 'Ἐὰν δὲ καὶ γαμήσῃς, οὐχ ἥμαρτες. Καὶ ἐὰν γήμῃ ἡ παρθένος, οὐχ ἥμαρτεν. Θλῖψιν δὲ τῇ σαρκὶ ἕξουσιν οἱ τοιοῦτοι, ἐγὼ δὲ ὑμῶν φείδομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 29, 'Τοῦτο δέ φημι, ἀδελφοί, ὁ καιρὸς συνεσταλμένος ἐστίν. Τὸ λοιπὸν, ἵνα καὶ οἱ ἔχοντες γυναῖκας, ὡς μὴ ἔχοντες ὦσιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 30, 'καὶ οἱ κλαίοντες, ὡς μὴ κλαίοντες, καὶ οἱ χαίροντες, ὡς μὴ χαίροντες, καὶ οἱ ἀγοράζοντες, ὡς μὴ κατέχοντες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 31, 'καὶ οἱ χρώμενοι τὸν κόσμον, ὡς μὴ καταχρώμενοι· παράγει γὰρ τὸ σχῆμα τοῦ κόσμου τούτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 32, '¶Θέλω δὲ ὑμᾶς ἀμερίμνους εἶναι. Ὁ ἄγαμος μεριμνᾷ τὰ τοῦ  ̊Κυρίου, πῶς ἀρέσῃ τῷ  ̊Κυρίῳ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 33, 'ὁ δὲ γαμήσας μεριμνᾷ τὰ τοῦ κόσμου, πῶς ἀρέσῃ τῇ γυναικί, καὶ μεμέρισται. Καὶ ἡ γυνὴ ἡ ἄγαμος καὶ ἡ παρθένος');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 34, 'ἡ ἄγαμος μεριμνᾷ τὰ τοῦ  ̊Κυρίου, ἵνα ᾖ ἁγία, καὶ τῷ σώματι καὶ τῷ πνεύματι· ἡ δὲ γαμήσασα μεριμνᾷ τὰ τοῦ κόσμου, πῶς ἀρέσῃ τῷ ἀνδρί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 35, 'Τοῦτο δὲ πρὸς τὸ ὑμῶν αὐτῶν σύμφορον λέγω, οὐχ ἵνα βρόχον ὑμῖν ἐπιβάλω, ἀλλὰ πρὸς τὸ εὔσχημον καὶ εὐπάρεδρον τῷ  ̊Κυρίῳ ἀπερισπάστως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 36, '¶Εἰ δέ τις ἀσχημονεῖν ἐπὶ τὴν παρθένον αὐτοῦ νομίζει, ἐὰν ᾖ ὑπέρακμος καὶ οὕτως ὀφείλει γίνεσθαι, ὃ θέλει ποιείτω· οὐχ ἁμαρτάνει· γαμείτωσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 37, 'Ὃς δὲ ἕστηκεν ἐν τῇ καρδίᾳ αὐτοῦ ἑδραῖος, μὴ ἔχων ἀνάγκην, ἐξουσίαν δὲ ἔχει περὶ τοῦ ἰδίου θελήματος, καὶ τοῦτο κέκρικεν ἐν τῇ ἰδίᾳ καρδίᾳ, τηρεῖν τὴν ἑαυτοῦ παρθένον, καλῶς ποιήσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 38, 'Ὥστε καὶ ὁ γαμίζων τὴν ἑαυτοῦ παρθένον, καλῶς ποιεῖ, καὶ ὁ μὴ γαμίζων, κρεῖσσον ποιήσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 39, '¶Γυνὴ δέδεται ἐφʼ ὅσον χρόνον ζῇ ὁ ἀνὴρ αὐτῆς· ἐὰν δὲ κοιμηθῇ ὁ ἀνήρ, ἐλευθέρα ἐστὶν ᾧ θέλει γαμηθῆναι, μόνον ἐν  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 40, 'Μακαριωτέρα δέ ἐστιν, ἐὰν οὕτως μείνῃ, κατὰ τὴν ἐμὴν γνώμην, δοκῶ δὲ κἀγὼ,  ̊Πνεῦμα  ̊Θεοῦ ἔχειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 1, '¶Περὶ δὲ τῶν εἰδωλοθύτων, οἴδαμεν ὅτι πάντες γνῶσιν ἔχομεν. Ἡ γνῶσις φυσιοῖ, ἡ δὲ ἀγάπη οἰκοδομεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 2, 'Εἴ τις δοκεῖ ἐγνωκέναι τι, οὔπω ἔγνω καθὼς δεῖ γνῶναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 3, 'Εἰ δέ τις ἀγαπᾷ τὸν  ̊Θεόν, οὗτος ἔγνωσται ὑπʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 4, '¶Περὶ τῆς βρώσεως οὖν τῶν εἰδωλοθύτων, οἴδαμεν ὅτι οὐδὲν εἴδωλον ἐν κόσμῳ, καὶ ὅτι οὐδεὶς  ̊Θεὸς εἰ μὴ εἷς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 5, 'Καὶ γὰρ εἴπερ εἰσὶν λεγόμενοι θεοὶ, εἴτε ἐν οὐρανῷ εἴτε ἐπὶ γῆς, ὥσπερ εἰσὶν θεοὶ πολλοὶ καὶ κύριοι πολλοί,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 6, 'ἀλλʼ ἡμῖν εἷς  ̊Θεὸς ὁ Πατήρ, ἐξ οὗ τὰ πάντα, καὶ ἡμεῖς εἰς αὐτόν, καὶ εἷς  ̊Κύριος,  ̊Ἰησοῦς  ̊Χριστός, διʼ οὗ τὰ πάντα, καὶ ἡμεῖς διʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 7, '¶Ἀλλʼ οὐκ ἐν πᾶσιν ἡ γνῶσις· τινὲς δὲ τῇ συνηθείᾳ ἕως ἄρτι τοῦ εἰδώλου, ὡς εἰδωλόθυτον ἐσθίουσιν, καὶ ἡ συνείδησις αὐτῶν ἀσθενὴς οὖσα, μολύνεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 8, 'Βρῶμα δὲ ἡμᾶς οὐ παραστήσει τῷ  ̊Θεῷ· οὔτε ἐὰν μὴ φάγωμεν, περισσεύομεν, οὔτε ἐὰν φάγωμεν, ὑστερούμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 9, 'Βλέπετε δὲ μή πως ἡ ἐξουσία ὑμῶν αὕτη, πρόσκομμα γένηται τοῖς ἀσθενέσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 10, 'Ἐὰν γάρ τις ἴδῃ σε τὸν ἔχοντα γνῶσιν ἐν εἰδωλείῳ κατακείμενον, οὐχὶ ἡ συνείδησις αὐτοῦ ἀσθενοῦς ὄντος, οἰκοδομηθήσεται, εἰς τὸ τὰ εἰδωλόθυτα ἐσθίειν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 11, 'Ἀπόλλυται γὰρ ὁ ἀσθενῶν ἐν τῇ σῇ γνώσει, ὁ ἀδελφὸς, διʼ ὃν  ̊Χριστὸς ἀπέθανεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 12, 'Οὕτως δὲ ἁμαρτάνοντες εἰς τοὺς ἀδελφοὺς, καὶ τύπτοντες αὐτῶν τὴν συνείδησιν ἀσθενοῦσαν, εἰς  ̊Χριστὸν ἁμαρτάνετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 13, 'Διόπερ εἰ βρῶμα σκανδαλίζει τὸν ἀδελφόν μου, οὐ μὴ φάγω κρέα εἰς τὸν αἰῶνα, ἵνα μὴ τὸν ἀδελφόν μου σκανδαλίσω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 1, '¶Οὐκ εἰμὶ ἐλεύθερος; Οὐκ εἰμὶ ἀπόστολος; Οὐχὶ  ̊Ἰησοῦν τὸν  ̊Κύριον ἡμῶν ἑόρακα; Οὐ τὸ ἔργον μου ὑμεῖς ἐστε ἐν  ̊Κυρίῳ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 2, 'Εἰ ἄλλοις οὐκ εἰμὶ ἀπόστολος, ἀλλά γε ὑμῖν εἰμι, ἡ γὰρ σφραγίς μου τῆς ἀποστολῆς, ὑμεῖς ἐστε ἐν  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 3, '¶Ἡ ἐμὴ ἀπολογία τοῖς ἐμὲ ἀνακρίνουσίν ἐστιν αὕτη:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 4, 'μὴ οὐκ ἔχομεν ἐξουσίαν φαγεῖν καὶ πεῖν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 5, 'Μὴ οὐκ ἔχομεν ἐξουσίαν ἀδελφὴν, γυναῖκα περιάγειν, ὡς καὶ οἱ λοιποὶ ἀπόστολοι, καὶ οἱ ἀδελφοὶ τοῦ  ̊Κυρίου, καὶ Κηφᾶς;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 6, 'Ἢ μόνος ἐγὼ καὶ Βαρναβᾶς, οὐκ ἔχομεν ἐξουσίαν μὴ ἐργάζεσθαι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 7, 'Τίς στρατεύεται ἰδίοις ὀψωνίοις ποτέ; Τίς φυτεύει ἀμπελῶνα, καὶ τὸν καρπὸν αὐτοῦ οὐκ ἐσθίει; Ἢ τίς ποιμαίνει ποίμνην, καὶ ἐκ τοῦ γάλακτος τῆς ποίμνης, οὐκ ἐσθίει;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 8, '¶Μὴ κατὰ ἄνθρωπον, ταῦτα λαλῶ, ἢ καὶ ὁ νόμος ταῦτα οὐ λέγει;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 9, 'Ἐν γὰρ τῷ Μωϋσέως νόμῳ, γέγραπται, “Οὐ φιμώσεις βοῦν ἀλοῶντα.” Μὴ τῶν βοῶν μέλει τῷ  ̊Θεῷ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 10, 'Ἢ διʼ ἡμᾶς πάντως λέγει; Διʼ ἡμᾶς γὰρ ἐγράφη ὅτι ὀφείλει ἐπʼ ἐλπίδι ὁ ἀροτριῶν ἀροτριᾶν, καὶ ὁ ἀλοῶν ἐπʼ ἐλπίδι τοῦ μετέχειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 11, 'Εἰ ἡμεῖς ὑμῖν τὰ πνευματικὰ ἐσπείραμεν, μέγα εἰ ἡμεῖς ὑμῶν τὰ σαρκικὰ θερίσομεν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 12, 'Εἰ ἄλλοι τῆς ὑμῶν ἐξουσίας μετέχουσιν, οὐ μᾶλλον ἡμεῖς; ¶Ἀλλʼ οὐκ ἐχρησάμεθα τῇ ἐξουσίᾳ ταύτῃ, ἀλλὰ πάντα στέγομεν, ἵνα μή τινα ἐγκοπὴν δῶμεν τῷ εὐαγγελίῳ τοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 13, 'Οὐκ οἴδατε ὅτι οἱ τὰ ἱερὰ ἐργαζόμενοι, ἐκ τοῦ ἱεροῦ ἐσθίουσιν, οἱ τῷ θυσιαστηρίῳ παρεδρεύοντες, τῷ θυσιαστηρίῳ συμμερίζονται;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 14, 'Οὕτως καὶ ὁ  ̊Κύριος διέταξεν τοῖς τὸ εὐαγγέλιον καταγγέλλουσιν, ἐκ τοῦ εὐαγγελίου ζῆν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 15, '¶Ἐγὼ δὲ οὐ κέχρημαι οὐδενὶ τούτων. Οὐκ ἔγραψα δὲ ταῦτα, ἵνα οὕτως γένηται ἐν ἐμοί, καλὸν γάρ μοι μᾶλλον ἀποθανεῖν, ἢ τὸ καύχημά μου οὐδεὶς κενώσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 16, 'Ἐὰν γὰρ εὐαγγελίζωμαι, οὐκ ἔστιν μοι καύχημα, ἀνάγκη γάρ μοι ἐπίκειται· οὐαὶ γάρ μοί ἐστιν, ἐὰν μὴ εὐαγγελίζωμαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 17, 'Εἰ γὰρ ἑκὼν τοῦτο πράσσω, μισθὸν ἔχω· εἰ δὲ ἄκων, οἰκονομίαν πεπίστευμαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 18, 'Τίς οὖν μού ἐστιν ὁ μισθός; Ἵνα εὐαγγελιζόμενος ἀδάπανον, θήσω τὸ εὐαγγέλιον, εἰς τὸ μὴ καταχρήσασθαι τῇ ἐξουσίᾳ μου ἐν τῷ εὐαγγελίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 19, '¶Ἐλεύθερος γὰρ ὢν ἐκ πάντων, πᾶσιν ἐμαυτὸν ἐδούλωσα, ἵνα τοὺς πλείονας κερδήσω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 20, 'Καὶ ἐγενόμην τοῖς Ἰουδαίοις, ὡς Ἰουδαῖος, ἵνα Ἰουδαίους κερδήσω· τοῖς ὑπὸ νόμον, ὡς ὑπὸ νόμον, μὴ ὢν αὐτὸς ὑπὸ νόμον, ἵνα τοὺς ὑπὸ νόμον κερδήσω·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 21, 'τοῖς ἀνόμοις, ὡς ἄνομος, μὴ ὢν ἄνομος  ̊Θεοῦ, ἀλλʼ ἔννομος  ̊Χριστοῦ, ἵνα κερδάνω τοὺς ἀνόμους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 22, 'Ἐγενόμην τοῖς ἀσθενέσιν, ἀσθενής, ἵνα τοὺς ἀσθενεῖς κερδήσω. Τοῖς πᾶσιν γέγονα πάντα, ἵνα πάντως τινὰς σώσω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 23, 'Πάντα δὲ ποιῶ διὰ τὸ εὐαγγέλιον, ἵνα συγκοινωνὸς αὐτοῦ γένωμαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 24, '¶Οὐκ οἴδατε ὅτι οἱ ἐν σταδίῳ τρέχοντες, πάντες μὲν τρέχουσιν, εἷς δὲ λαμβάνει τὸ βραβεῖον; Οὕτως τρέχετε, ἵνα καταλάβητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 25, 'Πᾶς δὲ ὁ ἀγωνιζόμενος, πάντα ἐγκρατεύεται, ἐκεῖνοι μὲν οὖν ἵνα φθαρτὸν στέφανον λάβωσιν, ἡμεῖς δὲ ἄφθαρτον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 26, 'Ἐγὼ τοίνυν οὕτως τρέχω, ὡς οὐκ ἀδήλως, οὕτως πυκτεύω, ὡς οὐκ ἀέρα δέρων·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 27, 'ἀλλὰ ὑπωπιάζω μου τὸ σῶμα, καὶ δουλαγωγῶ, μή πως ἄλλοις κηρύξας, αὐτὸς ἀδόκιμος γένωμαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 1, '¶Οὐ θέλω γὰρ ὑμᾶς ἀγνοεῖν, ἀδελφοί, ὅτι οἱ πατέρες ἡμῶν πάντες ὑπὸ τὴν νεφέλην ἦσαν, καὶ πάντες διὰ τῆς θαλάσσης διῆλθον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 2, 'καὶ πάντες εἰς τὸν Μωϋσῆν ἐβαπτίσαντο ἐν τῇ νεφέλῃ, καὶ ἐν τῇ θαλάσσῃ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 3, 'καὶ πάντες τὸ αὐτὸ πνευματικὸν βρῶμα ἔφαγον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 4, 'καὶ πάντες τὸ αὐτὸ πνευματικὸν ἔπιον πόμα, ἔπινον γὰρ ἐκ πνευματικῆς ἀκολουθούσης πέτρας, ἡ δὲ πέτρα ἦν ὁ  ̊Χριστός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 5, 'Ἀλλʼ οὐκ ἐν τοῖς πλείοσιν αὐτῶν ηὐδόκησεν ὁ  ̊Θεός, κατεστρώθησαν γὰρ ἐν τῇ ἐρήμῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 6, '¶Ταῦτα δὲ τύποι ἡμῶν ἐγενήθησαν, εἰς τὸ μὴ εἶναι ἡμᾶς ἐπιθυμητὰς κακῶν, καθὼς κἀκεῖνοι ἐπεθύμησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 7, 'Μηδὲ εἰδωλολάτραι γίνεσθε, καθώς τινες αὐτῶν· ὥσπερ γέγραπται, “Ἐκάθισεν ὁ λαὸς φαγεῖν καὶ πεῖν, καὶ ἀνέστησαν παίζειν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 8, 'Μηδὲ πορνεύωμεν, καθώς τινες αὐτῶν ἐπόρνευσαν, καὶ ἔπεσαν μιᾷ ἡμέρᾳ εἴκοσι τρεῖς χιλιάδες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 9, 'Μηδὲ ἐκπειράζωμεν τὸν  ̊Κύριον, καθώς τινες αὐτῶν ἐπείρασαν, καὶ ὑπὸ τῶν ὄφεων ἀπώλλυντο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 10, 'Μηδὲ γογγύζετε, καθάπερ τινὲς αὐτῶν ἐγόγγυσαν, καὶ ἀπώλοντο ὑπὸ τοῦ ὀλοθρευτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 11, 'Ταῦτα δὲ τυπικῶς συνέβαινεν ἐκείνοις, ἐγράφη δὲ πρὸς νουθεσίαν ἡμῶν, εἰς οὓς τὰ τέλη τῶν αἰώνων κατήντηκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 12, 'Ὥστε ὁ δοκῶν ἑστάναι, βλεπέτω μὴ πέσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 13, 'Πειρασμὸς ὑμᾶς οὐκ εἴληφεν, εἰ μὴ ἀνθρώπινος· πιστὸς δὲ ὁ  ̊Θεός, ὃς οὐκ ἐάσει ὑμᾶς πειρασθῆναι ὑπὲρ ὃ δύνασθε, ἀλλὰ ποιήσει σὺν τῷ πειρασμῷ καὶ τὴν ἔκβασιν τοῦ δύνασθαι ὑπενεγκεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 14, '¶Διόπερ, ἀγαπητοί μου, φεύγετε ἀπὸ τῆς εἰδωλολατρίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 15, 'Ὡς φρονίμοις λέγω, κρίνατε ὑμεῖς ὅ φημι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 16, 'Τὸ ποτήριον τῆς εὐλογίας, ὃ εὐλογοῦμεν, οὐχὶ κοινωνία ἐστὶν τοῦ αἵματος τοῦ  ̊Χριστοῦ; Τὸν ἄρτον ὃν κλῶμεν, οὐχὶ κοινωνία τοῦ σώματος τοῦ  ̊Χριστοῦ ἐστιν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 17, 'Ὅτι εἷς ἄρτος, ἓν σῶμα οἱ πολλοί ἐσμεν, οἱ γὰρ πάντες ἐκ τοῦ ἑνὸς ἄρτου μετέχομεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 18, 'Βλέπετε τὸν Ἰσραὴλ κατὰ σάρκα· οὐχὶ οἱ ἐσθίοντες τὰς θυσίας, κοινωνοὶ τοῦ θυσιαστηρίου εἰσίν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 19, 'Τί οὖν φημι; Ὅτι εἰδωλόθυτόν τί ἐστιν, τί ἐστιν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 20, 'Ἀλλʼ ὅτι ἃ θύουσιν τὰ ἔθνη, δαιμονίοις καὶ οὐ  ̊Θεῷ θύουσιν, οὐ θέλω δὲ ὑμᾶς κοινωνοὺς τῶν δαιμονίων γίνεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 21, 'Οὐ δύνασθε ποτήριον  ̊Κυρίου πίνειν, καὶ ποτήριον δαιμονίων. Οὐ δύνασθε τραπέζης  ̊Κυρίου μετέχειν, καὶ τραπέζης δαιμονίων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 22, 'Ἢ παραζηλοῦμεν τὸν  ̊Κύριον; Μὴ ἰσχυρότεροι αὐτοῦ ἐσμεν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 23, '¶Πάντα ἔξεστιν, ἀλλʼ οὐ πάντα συμφέρει. Πάντα ἔξεστιν, ἀλλʼ οὐ πάντα οἰκοδομεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 24, 'Μηδεὶς τὸ ἑαυτοῦ ζητείτω, ἀλλὰ τὸ τοῦ ἑτέρου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 25, 'Πᾶν τὸ ἐν μακέλλῳ πωλούμενον ἐσθίετε, μηδὲν ἀνακρίνοντες διὰ τὴν συνείδησιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 26, '“Τοῦ  ̊Κυρίου γὰρ ἡ γῆ, καὶ τὸ πλήρωμα αὐτῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 27, 'Εἴ τις καλεῖ ὑμᾶς τῶν ἀπίστων, καὶ θέλετε πορεύεσθαι, πᾶν τὸ παρατιθέμενον ὑμῖν ἐσθίετε, μηδὲν ἀνακρίνοντες διὰ τὴν συνείδησιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 28, 'Ἐὰν δέ τις ὑμῖν εἴπῃ, “Τοῦτο ἱερόθυτόν ἐστιν”, μὴ ἐσθίετε, διʼ ἐκεῖνον τὸν μηνύσαντα, καὶ τὴν συνείδησιν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 29, 'συνείδησιν δὲ λέγω, οὐχὶ τὴν ἑαυτοῦ, ἀλλὰ τὴν τοῦ ἑτέρου· ἵνα τί γὰρ ἡ ἐλευθερία μου κρίνεται ὑπὸ ἄλλης συνειδήσεως;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 30, 'Εἰ ἐγὼ χάριτι μετέχω, τί βλασφημοῦμαι ὑπὲρ οὗ ἐγὼ εὐχαριστῶ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 31, '¶Εἴτε οὖν ἐσθίετε, εἴτε πίνετε, εἴτε τι ποιεῖτε, πάντα εἰς δόξαν  ̊Θεοῦ ποιεῖτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 32, 'Ἀπρόσκοποι καὶ Ἰουδαίοις γίνεσθε, καὶ Ἕλλησιν, καὶ τῇ ἐκκλησίᾳ τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 33, 'Καθὼς κἀγὼ πάντα, πᾶσιν ἀρέσκω, μὴ ζητῶν τὸ ἐμαυτοῦ σύμφορον, ἀλλὰ τὸ τῶν πολλῶν, ἵνα σωθῶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 1, 'Μιμηταί μου γίνεσθε, καθὼς κἀγὼ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 2, '¶Ἐπαινῶ δὲ ὑμᾶς ὅτι πάντα μου μέμνησθε, καὶ καθὼς παρέδωκα ὑμῖν τὰς παραδόσεις κατέχετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 3, 'Θέλω δὲ ὑμᾶς εἰδέναι ὅτι παντὸς ἀνδρὸς ἡ κεφαλὴ ὁ  ̊Χριστός ἐστιν, κεφαλὴ δὲ γυναικὸς ὁ ἀνήρ, κεφαλὴ δὲ τοῦ  ̊Χριστοῦ ὁ  ̊Θεός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 4, 'Πᾶς ἀνὴρ προσευχόμενος ἢ προφητεύων κατὰ κεφαλῆς ἔχων, καταισχύνει τὴν κεφαλὴν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 5, 'Πᾶσα δὲ γυνὴ προσευχομένη ἢ προφητεύουσα ἀκατακαλύπτῳ τῇ κεφαλῇ, καταισχύνει τὴν κεφαλὴν αὐτῆς, ἓν γάρ ἐστιν καὶ τὸ αὐτὸ τῇ ἐξυρημένῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 6, 'Εἰ γὰρ οὐ κατακαλύπτεται γυνή, καὶ κειράσθω. Εἰ δὲ αἰσχρὸν γυναικὶ τὸ κείρασθαι ἢ ξυρᾶσθαι, κατακαλυπτέσθω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 7, 'Ἀνὴρ μὲν γὰρ οὐκ ὀφείλει κατακαλύπτεσθαι τὴν κεφαλήν, εἰκὼν καὶ δόξα  ̊Θεοῦ ὑπάρχων· ἡ γυνὴ δὲ δόξα ἀνδρός ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 8, 'Οὐ γάρ ἐστιν ἀνὴρ ἐκ γυναικός, ἀλλὰ γυνὴ ἐξ ἀνδρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 9, 'Καὶ γὰρ οὐκ ἐκτίσθη ἀνὴρ διὰ τὴν γυναῖκα, ἀλλὰ γυνὴ διὰ τὸν ἄνδρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 10, 'Διὰ τοῦτο ὀφείλει ἡ γυνὴ ἐξουσίαν ἔχειν ἐπὶ τῆς κεφαλῆς, διὰ τοὺς ἀγγέλους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 11, 'Πλὴν οὔτε γυνὴ χωρὶς ἀνδρὸς, οὔτε ἀνὴρ χωρὶς γυναικὸς ἐν  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 12, 'Ὥσπερ γὰρ ἡ γυνὴ ἐκ τοῦ ἀνδρός, οὕτως καὶ ὁ ἀνὴρ διὰ τῆς γυναικός, τὰ δὲ πάντα ἐκ τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 13, 'Ἐν ὑμῖν αὐτοῖς κρίνατε: πρέπον ἐστὶν γυναῖκα ἀκατακάλυπτον, τῷ  ̊Θεῷ προσεύχεσθαι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 14, 'Οὐδὲ ἡ φύσις αὐτὴ διδάσκει ὑμᾶς ὅτι ἀνὴρ μὲν ἐὰν κομᾷ, ἀτιμία αὐτῷ ἐστιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 15, 'γυνὴ δὲ ἐὰν κομᾷ, δόξα αὐτῇ ἐστιν; Ὅτι ἡ κόμη ἀντὶ περιβολαίου δέδοται αὐτῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 16, 'Εἰ δέ τις δοκεῖ φιλόνεικος εἶναι, ἡμεῖς τοιαύτην συνήθειαν οὐκ ἔχομεν, οὐδὲ αἱ ἐκκλησίαι τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 17, '¶Τοῦτο δὲ παραγγέλλων, οὐκ ἐπαινῶ, ὅτι οὐκ εἰς τὸ κρεῖσσον, ἀλλὰ εἰς τὸ ἧσσον, συνέρχεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 18, 'Πρῶτον μὲν γὰρ συνερχομένων ὑμῶν ἐν ἐκκλησίᾳ, ἀκούω σχίσματα ἐν ὑμῖν ὑπάρχειν, καὶ μέρος τι πιστεύω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 19, 'Δεῖ γὰρ καὶ αἱρέσεις ἐν ὑμῖν εἶναι, ἵνα καὶ οἱ δόκιμοι φανεροὶ γένωνται ἐν ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 20, 'Συνερχομένων οὖν ὑμῶν ἐπὶ τὸ αὐτὸ, οὐκ ἔστιν Κυριακὸν δεῖπνον φαγεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 21, 'Ἕκαστος γὰρ τὸ ἴδιον δεῖπνον προλαμβάνει ἐν τῷ φαγεῖν, καὶ ὃς μὲν πεινᾷ, ὃς δὲ μεθύει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 22, 'Μὴ γὰρ οἰκίας οὐκ ἔχετε εἰς τὸ ἐσθίειν καὶ πίνειν; Ἢ τῆς ἐκκλησίας τοῦ  ̊Θεοῦ καταφρονεῖτε, καὶ καταισχύνετε τοὺς μὴ ἔχοντας; Τί εἴπω ὑμῖν; Ἐπαινέσω ὑμᾶς ἐν τούτῳ; Οὐκ ἐπαινῶ!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 23, '¶Ἐγὼ γὰρ παρέλαβον ἀπὸ τοῦ  ̊Κυρίου, ὃ καὶ παρέδωκα ὑμῖν, ὅτι ὁ  ̊Κύριος  ̊Ἰησοῦς ἐν τῇ νυκτὶ ᾗ παρεδίδετο, ἔλαβεν ἄρτον');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 24, 'καὶ εὐχαριστήσας ἔκλασεν, καὶ εἶπεν, “Τοῦτό μού ἐστιν τὸ σῶμα, τὸ ὑπὲρ ὑμῶν· τοῦτο ποιεῖτε εἰς τὴν ἐμὴν ἀνάμνησιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 25, 'Ὡσαύτως καὶ τὸ ποτήριον μετὰ τὸ δειπνῆσαι λέγων, “‘Τοῦτο τὸ ποτήριον ἡ καινὴ διαθήκη ἐστὶν ἐν τῷ ἐμῷ αἵματι’· τοῦτο ποιεῖτε, ὁσάκις ἐὰν πίνητε, εἰς τὴν ἐμὴν ἀνάμνησιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 26, 'Ὁσάκις γὰρ ἐὰν ἐσθίητε τὸν ἄρτον τοῦτον, καὶ τὸ ποτήριον πίνητε, τὸν θάνατον τοῦ  ̊Κυρίου καταγγέλλετε, ἄχρι οὗ ἔλθῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 27, '¶Ὥστε ὃς ἂν ἐσθίῃ τὸν ἄρτον ἢ πίνῃ τὸ ποτήριον τοῦ  ̊Κυρίου ἀναξίως, ἔνοχος ἔσται τοῦ σώματος καὶ τοῦ αἵματος τοῦ  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 28, 'Δοκιμαζέτω δὲ ἄνθρωπος ἑαυτόν, καὶ οὕτως ἐκ τοῦ ἄρτου ἐσθιέτω, καὶ ἐκ τοῦ ποτηρίου πινέτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 29, 'Ὁ γὰρ ἐσθίων καὶ πίνων κρίμα ἑαυτῷ, ἐσθίει καὶ πίνει μὴ διακρίνων τὸ σῶμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 30, 'Διὰ τοῦτο ἐν ὑμῖν πολλοὶ ἀσθενεῖς καὶ ἄρρωστοι, καὶ κοιμῶνται ἱκανοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 31, 'Εἰ δὲ ἑαυτοὺς διεκρίνομεν, οὐκ ἂν ἐκρινόμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 32, 'Κρινόμενοι δὲ ὑπὸ τοῦ  ̊Κυρίου, παιδευόμεθα, ἵνα μὴ σὺν τῷ κόσμῳ κατακριθῶμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 33, '¶Ὥστε, ἀδελφοί μου, συνερχόμενοι εἰς τὸ φαγεῖν, ἀλλήλους ἐκδέχεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 34, 'Εἴ τις πεινᾷ, ἐν οἴκῳ ἐσθιέτω, ἵνα μὴ εἰς κρίμα συνέρχησθε. Τὰ δὲ λοιπὰ, ὡς ἂν ἔλθω, διατάξομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 1, '¶Περὶ δὲ τῶν πνευματικῶν, ἀδελφοί, οὐ θέλω ὑμᾶς ἀγνοεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 2, 'Οἴδατε ὅτι ὅτε ἔθνη ἦτε, πρὸς τὰ εἴδωλα τὰ ἄφωνα ὡς ἂν ἤγεσθε, ἀπαγόμενοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 3, 'Διὸ γνωρίζω ὑμῖν ὅτι οὐδεὶς ἐν  ̊Πνεύματι  ̊Θεοῦ λαλῶν, λέγει, “Ἀνάθεμα  ̊Ἰησοῦς”, καὶ οὐδεὶς δύναται εἰπεῖν, “ ̊Κύριος  ̊Ἰησοῦς”, εἰ μὴ ἐν  ̊Πνεύματι Ἁγίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 4, '¶Διαιρέσεις δὲ χαρισμάτων εἰσίν, τὸ δὲ αὐτὸ  ̊Πνεῦμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 5, 'Καὶ διαιρέσεις διακονιῶν εἰσιν, καὶ ὁ αὐτὸς  ̊Κύριος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 6, 'Καὶ διαιρέσεις ἐνεργημάτων εἰσίν, καὶ ὁ αὐτὸς  ̊Θεός, ὁ ἐνεργῶν τὰ πάντα ἐν πᾶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 7, 'Ἑκάστῳ δὲ δίδοται ἡ φανέρωσις τοῦ  ̊Πνεύματος πρὸς τὸ συμφέρον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 8, 'ὯΙ μὲν γὰρ διὰ τοῦ  ̊Πνεύματος δίδοται λόγος σοφίας, ἄλλῳ δὲ λόγος γνώσεως κατὰ τὸ αὐτὸ  ̊Πνεῦμα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 9, 'ἑτέρῳ δὲ πίστις ἐν τῷ αὐτῷ  ̊Πνεύματι, ἄλλῳ δὲ χαρίσματα ἰαμάτων ἐν τῷ ἑνὶ  ̊Πνεύματι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 10, 'ἄλλῳ δὲ ἐνεργήματα δυνάμεων, ἄλλῳ προφητεία, ἄλλῳ διακρίσεις πνευμάτων, ἑτέρῳ γένη γλωσσῶν, ἄλλῳ δὲ ἑρμηνεία γλωσσῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 11, 'Πάντα δὲ ταῦτα ἐνεργεῖ τὸ ἓν καὶ τὸ αὐτὸ  ̊Πνεῦμα, διαιροῦν ἰδίᾳ ἑκάστῳ καθὼς βούλεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 12, '¶Καθάπερ γὰρ τὸ σῶμα ἕν ἐστιν, καὶ μέλη πολλὰ ἔχει, πάντα δὲ τὰ μέλη τοῦ σώματος, πολλὰ ὄντα, ἕν ἐστιν σῶμα, οὕτως καὶ ὁ  ̊Χριστός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 13, 'Καὶ γὰρ ἐν ἑνὶ  ̊Πνεύματι ἡμεῖς πάντες εἰς ἓν σῶμα ἐβαπτίσθημεν, εἴτε Ἰουδαῖοι, εἴτε Ἕλληνες, εἴτε δοῦλοι, εἴτε ἐλεύθεροι, καὶ πάντες ἓν  ̊Πνεῦμα ἐποτίσθημεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 14, '¶Καὶ γὰρ τὸ σῶμα οὐκ ἔστιν ἓν μέλος, ἀλλὰ πολλά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 15, 'Ἐὰν εἴπῃ ὁ πούς, “Ὅτι οὐκ εἰμὶ χείρ, οὐκ εἰμὶ ἐκ τοῦ σώματος”, οὐ παρὰ τοῦτο, οὐκ ἔστιν ἐκ τοῦ σώματος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 16, 'Καὶ ἐὰν εἴπῃ τὸ οὖς, “Ὅτι οὐκ εἰμὶ ὀφθαλμός, οὐκ εἰμὶ ἐκ τοῦ σώματος”, οὐ παρὰ τοῦτο, οὐκ ἔστιν ἐκ τοῦ σώματος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 17, 'Εἰ ὅλον τὸ σῶμα ὀφθαλμός, ποῦ ἡ ἀκοή; Εἰ ὅλον ἀκοή, ποῦ ἡ ὄσφρησις;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 18, 'Νυνὶ δὲ ὁ  ̊Θεὸς ἔθετο τὰ μέλη, ἓν ἕκαστον αὐτῶν ἐν τῷ σώματι, καθὼς ἠθέλησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 19, 'Εἰ δὲ ἦν τὰ πάντα ἓν μέλος, ποῦ τὸ σῶμα;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 20, 'Νῦν δὲ πολλὰ μὲν μέλη, ἓν δὲ σῶμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 21, 'Οὐ δύναται δὲ ὁ ὀφθαλμὸς εἰπεῖν τῇ χειρί, “Χρείαν σου οὐκ ἔχω”, ἢ πάλιν ἡ κεφαλὴ τοῖς ποσίν, “Χρείαν ὑμῶν οὐκ ἔχω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 22, 'Ἀλλὰ πολλῷ μᾶλλον τὰ δοκοῦντα μέλη τοῦ σώματος ἀσθενέστερα ὑπάρχειν, ἀναγκαῖά ἐστιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 23, 'καὶ ἃ δοκοῦμεν ἀτιμότερα εἶναι τοῦ σώματος, τούτοις τιμὴν περισσοτέραν περιτίθεμεν, καὶ τὰ ἀσχήμονα ἡμῶν, εὐσχημοσύνην περισσοτέραν ἔχει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 24, 'τὰ δὲ εὐσχήμονα ἡμῶν, οὐ χρείαν ἔχει. Ἀλλὰ ὁ  ̊Θεὸς συνεκέρασεν τὸ σῶμα, τῷ ὑστερουμένῳ, περισσοτέραν δοὺς τιμήν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 25, 'ἵνα μὴ ᾖ σχίσμα ἐν τῷ σώματι, ἀλλὰ τὸ αὐτὸ ὑπὲρ ἀλλήλων μεριμνῶσι τὰ μέλη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 26, 'Καὶ εἴτε πάσχει ἓν μέλος, συμπάσχει πάντα τὰ μέλη· εἴτε δοξάζεται μέλος, συγχαίρει πάντα τὰ μέλη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 27, '¶Ὑμεῖς δέ ἐστε σῶμα  ̊Χριστοῦ, καὶ μέλη ἐκ μέρους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 28, 'Καὶ οὓς μὲν ἔθετο ὁ  ̊Θεὸς ἐν τῇ ἐκκλησίᾳ πρῶτον ἀποστόλους, δεύτερον προφήτας, τρίτον διδασκάλους, ἔπειτα δυνάμεις, ἔπειτα χαρίσματα ἰαμάτων, ἀντιλήμψεις, κυβερνήσεις, γένη γλωσσῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 29, 'Μὴ πάντες ἀπόστολοι; Μὴ πάντες προφῆται; Μὴ πάντες διδάσκαλοι; Μὴ πάντες δυνάμεις;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 30, 'Μὴ πάντες χαρίσματα ἔχουσιν ἰαμάτων; Μὴ πάντες γλώσσαις λαλοῦσιν; Μὴ πάντες διερμηνεύουσιν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 31, 'Ζηλοῦτε δὲ τὰ χαρίσματα τὰ μείζονα. Καὶ ἔτι καθʼ ὑπερβολὴν ὁδὸν, ὑμῖν δείκνυμι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 1, '¶Ἐὰν ταῖς γλώσσαις τῶν ἀνθρώπων λαλῶ καὶ τῶν ἀγγέλων, ἀγάπην δὲ μὴ ἔχω, γέγονα χαλκὸς ἠχῶν ἢ κύμβαλον ἀλαλάζον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 2, 'Κἂν ἔχω προφητείαν, καὶ εἰδῶ τὰ μυστήρια πάντα, καὶ πᾶσαν τὴν γνῶσιν, κἂν ἔχω πᾶσαν τὴν πίστιν, ὥστε ὄρη μεθιστάναι, ἀγάπην δὲ μὴ ἔχω, οὐθέν εἰμι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 3, 'Κἂν ψωμίσω πάντα τὰ ὑπάρχοντά μου, καὶ παραδῶ τὸ σῶμά μου, ἵνα καυχήσωμαι, ἀγάπην δὲ μὴ ἔχω, οὐδὲν ὠφελοῦμαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 4, '¶Ἡ ἀγάπη μακροθυμεῖ, χρηστεύεται· ἡ ἀγάπη οὐ ζηλοῖ· ἡ ἀγάπη οὐ περπερεύεται, οὐ φυσιοῦται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 5, 'οὐκ ἀσχημονεῖ, οὐ ζητεῖ τὰ ἑαυτῆς, οὐ παροξύνεται, οὐ λογίζεται τὸ κακόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 6, 'οὐ χαίρει ἐπὶ τῇ ἀδικίᾳ, συγχαίρει δὲ τῇ ἀληθείᾳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 7, 'πάντα στέγει, πάντα πιστεύει, πάντα ἐλπίζει, πάντα ὑπομένει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 8, '¶Ἡ ἀγάπη οὐδέποτε πίπτει. Εἴτε δὲ προφητεῖαι, καταργηθήσονται· εἴτε γλῶσσαι, παύσονται· εἴτε γνῶσις, καταργηθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 9, 'Ἐκ μέρους γὰρ γινώσκομεν, καὶ ἐκ μέρους προφητεύομεν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 10, 'ὅταν δὲ ἔλθῃ τὸ τέλειον, τὸ ἐκ μέρους καταργηθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 11, 'Ὅτε ἤμην νήπιος, ἐλάλουν ὡς νήπιος, ἐφρόνουν ὡς νήπιος, ἐλογιζόμην ὡς νήπιος· ὅτε γέγονα ἀνήρ, κατήργηκα τὰ τοῦ νηπίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 12, 'Βλέπομεν γὰρ ἄρτι διʼ ἐσόπτρου ἐν αἰνίγματι, τότε δὲ πρόσωπον πρὸς πρόσωπον· ἄρτι γινώσκω ἐκ μέρους, τότε δὲ ἐπιγνώσομαι, καθὼς καὶ ἐπεγνώσθην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 13, 'Νυνὶ δὲ μένει πίστις, ἐλπίς, ἀγάπη, τὰ τρία ταῦτα, μείζων δὲ τούτων ἡ ἀγάπη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 1, '¶Διώκετε τὴν ἀγάπην, ζηλοῦτε δὲ τὰ πνευματικά, μᾶλλον δὲ ἵνα προφητεύητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 2, 'Ὁ γὰρ λαλῶν γλώσσῃ, οὐκ ἀνθρώποις λαλεῖ, ἀλλὰ  ̊Θεῷ, οὐδεὶς γὰρ ἀκούει, πνεύματι δὲ λαλεῖ μυστήρια.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 3, 'Ὁ δὲ προφητεύων, ἀνθρώποις λαλεῖ οἰκοδομὴν, καὶ παράκλησιν, καὶ παραμυθίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 4, 'Ὁ λαλῶν γλώσσῃ, ἑαυτὸν οἰκοδομεῖ, ὁ δὲ προφητεύων, ἐκκλησίαν οἰκοδομεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 5, 'Θέλω δὲ πάντας ὑμᾶς λαλεῖν γλώσσαις, μᾶλλον δὲ ἵνα προφητεύητε· μείζων δὲ ὁ προφητεύων, ἢ ὁ λαλῶν γλώσσαις, ἐκτὸς εἰ μὴ διερμηνεύῃ, ἵνα ἡ ἐκκλησία οἰκοδομὴν λάβῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 6, '¶Νῦν δέ, ἀδελφοί, ἐὰν ἔλθω πρὸς ὑμᾶς γλώσσαις λαλῶν, τί ὑμᾶς ὠφελήσω, ἐὰν μὴ ὑμῖν λαλήσω, ἢ ἐν ἀποκαλύψει, ἢ ἐν γνώσει, ἢ ἐν προφητείᾳ, ἢ ἐν διδαχῇ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 7, 'Ὅμως τὰ ἄψυχα φωνὴν διδόντα, εἴτε αὐλὸς, εἴτε κιθάρα, ἐὰν διαστολὴν τοῖς φθόγγοις μὴ δῷ, πῶς γνωσθήσεται τὸ αὐλούμενον ἢ τὸ κιθαριζόμενον;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 8, 'Καὶ γὰρ ἐὰν ἄδηλον σάλπιγξ φωνὴν δῷ, τίς παρασκευάσεται εἰς πόλεμον;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 9, 'Οὕτως καὶ ὑμεῖς διὰ τῆς γλώσσης, ἐὰν μὴ εὔσημον λόγον δῶτε, πῶς γνωσθήσεται τὸ λαλούμενον; Ἔσεσθε γὰρ εἰς ἀέρα λαλοῦντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 10, 'Τοσαῦτα εἰ τύχοι, γένη φωνῶν εἰσιν ἐν κόσμῳ, καὶ οὐδὲν ἄφωνον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 11, 'Ἐὰν οὖν μὴ εἰδῶ τὴν δύναμιν τῆς φωνῆς, ἔσομαι τῷ λαλοῦντι βάρβαρος, καὶ ὁ λαλῶν ἐν ἐμοὶ βάρβαρος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 12, 'Οὕτως καὶ ὑμεῖς, ἐπεὶ ζηλωταί ἐστε πνευμάτων, πρὸς τὴν οἰκοδομὴν τῆς ἐκκλησίας, ζητεῖτε ἵνα περισσεύητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 13, '¶Διὸ ὁ λαλῶν γλώσσῃ, προσευχέσθω ἵνα διερμηνεύῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 14, 'Ἐὰν γὰρ προσεύχωμαι γλώσσῃ, τὸ πνεῦμά μου προσεύχεται, ὁ δὲ νοῦς μου ἄκαρπός ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 15, 'Τί οὖν ἐστιν; Προσεύξομαι τῷ  ̊Πνεύματι, προσεύξομαι δὲ καὶ τῷ νοΐ. Ψαλῶ τῷ  ̊Πνεύματι, ψαλῶ δὲ καὶ τῷ νοΐ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 16, 'Ἐπεὶ ἐὰν εὐλογῇς πνεύματι, ὁ ἀναπληρῶν τὸν τόπον τοῦ ἰδιώτου, πῶς ἐρεῖ, τὸ “Ἀμήν”, ἐπὶ τῇ σῇ εὐχαριστίᾳ, ἐπειδὴ τί λέγεις, οὐκ οἶδεν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 17, 'Σὺ μὲν γὰρ καλῶς εὐχαριστεῖς, ἀλλʼ ὁ ἕτερος οὐκ οἰκοδομεῖται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 18, 'Εὐχαριστῶ τῷ  ̊Θεῷ, πάντων ὑμῶν μᾶλλον, γλώσσαις λαλῶ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 19, 'ἀλλὰ ἐν ἐκκλησίᾳ, θέλω πέντε λόγους τῷ νοΐ μου λαλῆσαι, ἵνα καὶ ἄλλους κατηχήσω, ἢ μυρίους λόγους ἐν γλώσσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 20, '¶Ἀδελφοί, μὴ παιδία γίνεσθε ταῖς φρεσίν, ἀλλὰ τῇ κακίᾳ, νηπιάζετε, ταῖς δὲ φρεσὶν, τέλειοι γίνεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 21, 'Ἐν τῷ νόμῳ γέγραπται, ὅτι “Ἐν ἑτερογλώσσοις καὶ ἐν χείλεσιν ἑτέρων, λαλήσω τῷ λαῷ τούτῳ... καὶ οὐδʼ οὕτως εἰσακούσονταί μου”, λέγει  ̊Κύριος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 22, 'Ὥστε αἱ γλῶσσαι εἰς σημεῖόν εἰσιν, οὐ τοῖς πιστεύουσιν, ἀλλὰ τοῖς ἀπίστοις, ἡ δὲ προφητεία, οὐ τοῖς ἀπίστοις, ἀλλὰ τοῖς πιστεύουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 23, 'Ἐὰν οὖν συνέλθῃ ἡ ἐκκλησία ὅλη ἐπὶ τὸ αὐτὸ, καὶ πάντες λαλῶσιν γλώσσαις, εἰσέλθωσιν δὲ ἰδιῶται ἢ ἄπιστοι, οὐκ ἐροῦσιν ὅτι μαίνεσθε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 24, 'Ἐὰν δὲ πάντες προφητεύωσιν, εἰσέλθῃ δέ τις ἄπιστος ἢ ἰδιώτης, ἐλέγχεται ὑπὸ πάντων, ἀνακρίνεται ὑπὸ πάντων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 25, 'τὰ κρυπτὰ τῆς καρδίας αὐτοῦ φανερὰ γίνεται, καὶ οὕτως πεσὼν ἐπὶ πρόσωπον, προσκυνήσει τῷ  ̊Θεῷ ἀπαγγέλλων, ὅτι “Ὄντως ὁ  ̊Θεὸς ἐν ὑμῖν ἐστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 26, '¶Τί οὖν ἐστιν, ἀδελφοί; Ὅταν συνέρχησθε, ἕκαστος ψαλμὸν ἔχει, διδαχὴν ἔχει, ἀποκάλυψιν ἔχει, γλῶσσαν ἔχει, ἑρμηνείαν ἔχει. Πάντα πρὸς οἰκοδομὴν γινέσθω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 27, 'Εἴτε γλώσσῃ τις λαλεῖ, κατὰ δύο ἢ τὸ πλεῖστον τρεῖς, καὶ ἀνὰ μέρος, καὶ εἷς διερμηνευέτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 28, 'Ἐὰν δὲ μὴ ᾖ διερμηνευτής, σιγάτω ἐν ἐκκλησίᾳ, ἑαυτῷ δὲ λαλείτω καὶ τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 29, 'Προφῆται δὲ δύο ἢ τρεῖς λαλείτωσαν, καὶ οἱ ἄλλοι διακρινέτωσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 30, 'Ἐὰν δὲ ἄλλῳ ἀποκαλυφθῇ καθημένῳ, ὁ πρῶτος σιγάτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 31, 'Δύνασθε γὰρ καθʼ ἕνα πάντες προφητεύειν, ἵνα πάντες μανθάνωσιν, καὶ πάντες παρακαλῶνται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 32, 'Καὶ πνεύματα προφητῶν, προφήταις ὑποτάσσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 33, 'Οὐ γάρ ἐστιν ἀκαταστασίας ὁ  ̊Θεὸς, ἀλλὰ εἰρήνης. ¶Ὡς ἐν πάσαις ταῖς ἐκκλησίαις τῶν ἁγίων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 34, 'αἱ γυναῖκες ἐν ταῖς ἐκκλησίαις σιγάτωσαν, οὐ γὰρ ἐπιτρέπεται αὐταῖς λαλεῖν, ἀλλὰ ὑποτασσέσθωσαν, καθὼς καὶ ὁ νόμος λέγει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 35, 'Εἰ δέ τι μαθεῖν θέλουσιν, ἐν οἴκῳ τοὺς ἰδίους ἄνδρας ἐπερωτάτωσαν, αἰσχρὸν γάρ ἐστιν γυναικὶ λαλεῖν ἐν ἐκκλησίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 36, 'Ἢ ἀφʼ ὑμῶν ὁ λόγος τοῦ  ̊Θεοῦ ἐξῆλθεν, ἢ εἰς ὑμᾶς μόνους κατήντησεν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 37, '¶Εἴ τις δοκεῖ προφήτης εἶναι ἢ πνευματικός, ἐπιγινωσκέτω ἃ γράφω ὑμῖν ὅτι  ̊Κυρίου ἐστὶν ἐντολή.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 38, 'Εἰ δέ τις ἀγνοεῖ, ἀγνοείτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 39, 'Ὥστε, ἀδελφοί, ζηλοῦτε τὸ προφητεύειν, καὶ τὸ λαλεῖν μὴ κωλύετε ἐν γλώσσαις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 14, 40, 'Πάντα δὲ εὐσχημόνως καὶ κατὰ τάξιν γινέσθω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 1, '¶Γνωρίζω δὲ ὑμῖν, ἀδελφοί, τὸ εὐαγγέλιον ὃ εὐηγγελισάμην ὑμῖν, ὃ καὶ παρελάβετε, ἐν ᾧ καὶ ἑστήκατε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 2, 'διʼ οὗ καὶ σῴζεσθε, τίνι λόγῳ εὐηγγελισάμην ὑμῖν, εἰ κατέχετε, ἐκτὸς εἰ μὴ εἰκῇ ἐπιστεύσατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 3, '¶Παρέδωκα γὰρ ὑμῖν ἐν πρώτοις, ὃ καὶ παρέλαβον: ὅτι  ̊Χριστὸς ἀπέθανεν ὑπὲρ τῶν ἁμαρτιῶν ἡμῶν κατὰ τὰς Γραφάς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 4, 'καὶ ὅτι ἐτάφη, καὶ ὅτι ἐγήγερται τῇ ἡμέρᾳ τῇ τρίτῃ κατὰ τὰς Γραφάς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 5, 'καὶ ὅτι ὤφθη Κηφᾷ, εἶτα τοῖς δώδεκα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 6, 'Ἔπειτα ὤφθη ἐπάνω πεντακοσίοις ἀδελφοῖς ἐφάπαξ, ἐξ ὧν οἱ πλείονες μένουσιν ἕως ἄρτι, τινὲς δὲ ἐκοιμήθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 7, 'Ἔπειτα ὤφθη Ἰακώβῳ, εἶτα τοῖς ἀποστόλοις πᾶσιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 8, 'ἔσχατον δὲ πάντων, ὡσπερεὶ τῷ ἐκτρώματι, ὤφθη κἀμοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 9, 'Ἐγὼ γάρ εἰμι ὁ ἐλάχιστος τῶν ἀποστόλων, ὃς οὐκ εἰμὶ ἱκανὸς καλεῖσθαι ἀπόστολος, διότι ἐδίωξα τὴν ἐκκλησίαν τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 10, 'Χάριτι δὲ  ̊Θεοῦ, εἰμι ὅ εἰμι, καὶ ἡ χάρις αὐτοῦ ἡ εἰς ἐμὲ, οὐ κενὴ ἐγενήθη, ἀλλὰ περισσότερον αὐτῶν πάντων ἐκοπίασα, οὐκ ἐγὼ δὲ, ἀλλὰ ἡ χάρις τοῦ  ̊Θεοῦ σὺν ἐμοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 11, 'Εἴτε οὖν ἐγὼ εἴτε ἐκεῖνοι, οὕτως κηρύσσομεν, καὶ οὕτως ἐπιστεύσατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 12, '¶Εἰ δὲ  ̊Χριστὸς κηρύσσεται, ὅτι ἐκ νεκρῶν ἐγήγερται, πῶς λέγουσιν ἐν ὑμῖν τινες ὅτι ἀνάστασις νεκρῶν οὐκ ἔστιν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 13, 'Εἰ δὲ ἀνάστασις νεκρῶν οὐκ ἔστιν, οὐδὲ  ̊Χριστὸς ἐγήγερται·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 14, 'εἰ δὲ  ̊Χριστὸς οὐκ ἐγήγερται, κενὸν ἄρα τὸ κήρυγμα ἡμῶν, κενὴ καὶ ἡ πίστις ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 15, 'Εὑρισκόμεθα δὲ καὶ ψευδομάρτυρες τοῦ  ̊Θεοῦ, ὅτι ἐμαρτυρήσαμεν κατὰ τοῦ  ̊Θεοῦ ὅτι ἤγειρεν τὸν  ̊Χριστόν, ὃν οὐκ ἤγειρεν, εἴπερ ἄρα νεκροὶ οὐκ ἐγείρονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 16, 'Εἰ γὰρ νεκροὶ οὐκ ἐγείρονται, οὐδὲ  ̊Χριστὸς ἐγήγερται·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 17, 'εἰ δὲ  ̊Χριστὸς οὐκ ἐγήγερται, ματαία ἡ πίστις ὑμῶν, καὶ ἔτι ἐστὲ ἐν ταῖς ἁμαρτίαις ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 18, 'Ἄρα καὶ οἱ κοιμηθέντες ἐν  ̊Χριστῷ ἀπώλοντο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 19, 'Εἰ ἐν τῇ ζωῇ ταύτῃ, ἐν  ̊Χριστῷ ἠλπικότες ἐσμὲν μόνον, ἐλεεινότεροι πάντων ἀνθρώπων ἐσμέν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 20, '¶Νυνὶ δὲ  ̊Χριστὸς ἐγήγερται ἐκ νεκρῶν, ἀπαρχὴ τῶν κεκοιμημένων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 21, 'Ἐπειδὴ γὰρ διʼ ἀνθρώπου θάνατος, καὶ διʼ ἀνθρώπου ἀνάστασις νεκρῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 22, 'Ὥσπερ γὰρ ἐν τῷ Ἀδὰμ, πάντες ἀποθνῄσκουσιν, οὕτως καὶ ἐν τῷ  ̊Χριστῷ, πάντες ζῳοποιηθήσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 23, 'Ἕκαστος δὲ ἐν τῷ ἰδίῳ τάγματι: ἀπαρχὴ  ̊Χριστός, ἔπειτα οἱ τοῦ  ̊Χριστοῦ ἐν τῇ παρουσίᾳ αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 24, 'εἶτα τὸ τέλος, ὅταν παραδιδῷ τὴν βασιλείαν τῷ  ̊Θεῷ καὶ Πατρί, ὅταν καταργήσῃ πᾶσαν ἀρχὴν, καὶ πᾶσαν ἐξουσίαν, καὶ δύναμιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 25, 'Δεῖ γὰρ αὐτὸν βασιλεύειν, ἄχρι οὗ θῇ πάντας τοὺς ἐχθροὺς ὑπὸ τοὺς πόδας αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 26, 'Ἔσχατος ἐχθρὸς καταργεῖται ὁ θάνατος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 27, '“Πάντα γὰρ ὑπέταξεν ὑπὸ τοὺς πόδας αὐτοῦ.” Ὅταν δὲ εἴπῃ ὅτι πάντα ὑποτέτακται, δῆλον ὅτι ἐκτὸς τοῦ ὑποτάξαντος αὐτῷ τὰ πάντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 28, 'Ὅταν δὲ ὑποταγῇ αὐτῷ τὰ πάντα, τότε καὶ αὐτὸς ὁ Υἱὸς, ὑποταγήσεται τῷ ὑποτάξαντι αὐτῷ τὰ πάντα, ἵνα ᾖ ὁ  ̊Θεὸς πάντα ἐν πᾶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 29, '¶Ἐπεὶ τί ποιήσουσιν, οἱ βαπτιζόμενοι ὑπὲρ τῶν νεκρῶν; Εἰ ὅλως νεκροὶ οὐκ ἐγείρονται, τί καὶ βαπτίζονται ὑπὲρ αὐτῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 30, 'Τί καὶ ἡμεῖς κινδυνεύομεν πᾶσαν ὥραν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 31, 'Καθʼ ἡμέραν ἀποθνῄσκω, νὴ τὴν ὑμετέραν καύχησιν, ἀδελφοί, ἣν ἔχω ἐν  ̊Χριστῷ  ̊Ἰησοῦ, τῷ  ̊Κυρίῳ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 32, 'Εἰ κατὰ ἄνθρωπον, ἐθηριομάχησα ἐν Ἐφέσῳ, τί μοι τὸ ὄφελος; Εἰ νεκροὶ οὐκ ἐγείρονται, “Φάγωμεν καὶ πίωμεν, αὔριον γὰρ ἀποθνῄσκομεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 33, 'Μὴ πλανᾶσθε– φθείρουσιν ἤθη χρηστὰ ὁμιλίαι κακαί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 34, 'Ἐκνήψατε δικαίως καὶ μὴ ἁμαρτάνετε, ἀγνωσίαν γὰρ  ̊Θεοῦ τινες ἔχουσιν· πρὸς ἐντροπὴν ὑμῖν λαλῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 35, '¶Ἀλλʼ ἐρεῖ τις, “Πῶς ἐγείρονται οἱ νεκροί;” Ποίῳ δὲ σώματι ἔρχονται;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 36, 'Ἄφρων! Σὺ ὃ σπείρεις, οὐ ζῳοποιεῖται, ἐὰν μὴ ἀποθάνῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 37, 'Καὶ ὃ σπείρεις, οὐ τὸ σῶμα τὸ γενησόμενον σπείρεις, ἀλλὰ γυμνὸν κόκκον, εἰ τύχοι σίτου, ἤ τινος τῶν λοιπῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 38, 'Ὁ δὲ  ̊Θεὸς δίδωσιν αὐτῷ σῶμα, καθὼς ἠθέλησεν, καὶ ἑκάστῳ τῶν σπερμάτων, ἴδιον σῶμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 39, 'Οὐ πᾶσα σὰρξ ἡ αὐτὴ σάρξ, ἀλλὰ ἄλλη μὲν ἀνθρώπων, ἄλλη δὲ σὰρξ κτηνῶν, ἄλλη δὲ σὰρξ πτηνῶν, ἄλλη δὲ ἰχθύων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 40, 'Καὶ σώματα ἐπουράνια, καὶ σώματα ἐπίγεια. Ἀλλὰ ἑτέρα μὲν ἡ τῶν ἐπουρανίων δόξα, ἑτέρα δὲ ἡ τῶν ἐπιγείων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 41, 'Ἄλλη δόξα ἡλίου, καὶ ἄλλη δόξα σελήνης, καὶ ἄλλη δόξα ἀστέρων, ἀστὴρ γὰρ ἀστέρος διαφέρει ἐν δόξῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 42, '¶Οὕτως καὶ ἡ ἀνάστασις τῶν νεκρῶν. Σπείρεται ἐν φθορᾷ, ἐγείρεται ἐν ἀφθαρσίᾳ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 43, 'σπείρεται ἐν ἀτιμίᾳ, ἐγείρεται ἐν δόξῃ· σπείρεται ἐν ἀσθενείᾳ, ἐγείρεται ἐν δυνάμει·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 44, 'σπείρεται σῶμα ψυχικόν, ἐγείρεται σῶμα πνευματικόν. Εἰ ἔστιν σῶμα ψυχικόν, ἔστιν καὶ πνευματικόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 45, 'Οὕτως καὶ γέγραπται, “Ἐγένετο ὁ πρῶτος ἄνθρωπος”, Ἀδὰμ, “εἰς ψυχὴν ζῶσαν”. Ὁ ἔσχατος Ἀδὰμ εἰς πνεῦμα ζῳοποιοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 46, 'Ἀλλʼ οὐ πρῶτον τὸ πνευματικὸν, ἀλλὰ τὸ ψυχικόν, ἔπειτα τὸ πνευματικόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 47, 'Ὁ πρῶτος ἄνθρωπος ἐκ γῆς, χοϊκός, ὁ δεύτερος ἄνθρωπος, ἐξ οὐρανοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 48, 'Οἷος ὁ χοϊκός, τοιοῦτοι καὶ οἱ χοϊκοί, καὶ οἷος ὁ ἐπουράνιος, τοιοῦτοι καὶ οἱ ἐπουράνιοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 49, 'Καὶ καθὼς ἐφορέσαμεν τὴν εἰκόνα τοῦ χοϊκοῦ, φορέσωμεν καὶ τὴν εἰκόνα τοῦ ἐπουρανίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 50, '¶Τοῦτο δέ φημι, ἀδελφοί, ὅτι σὰρξ καὶ αἷμα Βασιλείαν  ̊Θεοῦ κληρονομῆσαι οὐ δύναται, οὐδὲ ἡ φθορὰ, τὴν ἀφθαρσίαν κληρονομεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 51, 'Ἰδοὺ, μυστήριον ὑμῖν λέγω: πάντες οὐ κοιμηθησόμεθα, πάντες δὲ ἀλλαγησόμεθα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 52, 'ἐν ἀτόμῳ, ἐν ῥιπῇ ὀφθαλμοῦ, ἐν τῇ ἐσχάτῃ σάλπιγγι· σαλπίσει γάρ, καὶ οἱ νεκροὶ ἐγερθήσονται ἄφθαρτοι, καὶ ἡμεῖς ἀλλαγησόμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 53, 'Δεῖ γὰρ τὸ φθαρτὸν τοῦτο ἐνδύσασθαι ἀφθαρσίαν, καὶ τὸ θνητὸν τοῦτο ἐνδύσασθαι ἀθανασίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 54, 'Ὅταν δὲ τὸ φθαρτὸν τοῦτο ἐνδύσηται ἀφθαρσίαν, καὶ τὸ θνητὸν τοῦτο ἐνδύσηται ἀθανασίαν, τότε γενήσεται ὁ λόγος ὁ γεγραμμένος, “Κατεπόθη ὁ θάνατος εἰς νῖκος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 55, '“Ποῦ σου, θάνατε, τὸ νῖκος; Ποῦ σου, θάνατε, τὸ κέντρον;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 56, 'Τὸ δὲ κέντρον τοῦ θανάτου ἡ ἁμαρτία, ἡ δὲ δύναμις τῆς ἁμαρτίας ὁ νόμος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 57, 'Τῷ δὲ  ̊Θεῷ χάρις, τῷ διδόντι ἡμῖν τὸ νῖκος διὰ τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 15, 58, '¶Ὥστε, ἀδελφοί μου ἀγαπητοί, ἑδραῖοι γίνεσθε, ἀμετακίνητοι, περισσεύοντες ἐν τῷ ἔργῳ τοῦ  ̊Κυρίου πάντοτε, εἰδότες ὅτι ὁ κόπος ὑμῶν οὐκ ἔστιν κενὸς ἐν  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 1, '¶Περὶ δὲ τῆς λογίας τῆς εἰς τοὺς ἁγίους, ὥσπερ διέταξα ταῖς ἐκκλησίαις τῆς Γαλατίας, οὕτως καὶ ὑμεῖς ποιήσατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 2, 'Κατὰ μίαν σαββάτου, ἕκαστος ὑμῶν παρʼ ἑαυτῷ τιθέτω, θησαυρίζων ὅ τι ἂν εὐοδῶται, ἵνα μὴ ὅταν ἔλθω, τότε λογίαι γίνωνται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 3, 'Ὅταν δὲ παραγένωμαι, οὓς ἐὰν δοκιμάσητε, διʼ ἐπιστολῶν τούτους πέμψω, ἀπενεγκεῖν τὴν χάριν ὑμῶν εἰς Ἰερουσαλήμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 4, 'Ἐὰν δὲ ἄξιον ᾖ τοῦ κἀμὲ πορεύεσθαι, σὺν ἐμοὶ πορεύσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 5, '¶Ἐλεύσομαι δὲ πρὸς ὑμᾶς, ὅταν Μακεδονίαν διέλθω, Μακεδονίαν γὰρ διέρχομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 6, 'Πρὸς ὑμᾶς δὲ τυχὸν παραμενῶ, ἢ παραχειμάσω, ἵνα ὑμεῖς με προπέμψητε, οὗ ἐὰν πορεύωμαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 7, 'Οὐ θέλω γὰρ ὑμᾶς ἄρτι ἐν παρόδῳ ἰδεῖν, ἐλπίζω γὰρ χρόνον τινὰ ἐπιμεῖναι πρὸς ὑμᾶς, ἐὰν ὁ  ̊Κύριος ἐπιτρέψῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 8, 'Ἐπιμενῶ δὲ ἐν Ἐφέσῳ ἕως τῆς Πεντηκοστῆς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 9, 'θύρα γάρ μοι ἀνέῳγεν μεγάλη καὶ ἐνεργής, καὶ ἀντικείμενοι πολλοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 10, '¶Ἐὰν δὲ ἔλθῃ Τιμόθεος, βλέπετε ἵνα ἀφόβως γένηται πρὸς ὑμᾶς, τὸ γὰρ ἔργον  ̊Κυρίου ἐργάζεται, ὡς ἐγώ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 11, 'Μή τις οὖν αὐτὸν ἐξουθενήσῃ. Προπέμψατε δὲ αὐτὸν ἐν εἰρήνῃ, ἵνα ἔλθῃ πρός με, ἐκδέχομαι γὰρ αὐτὸν μετὰ τῶν ἀδελφῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 12, '¶Περὶ δὲ Ἀπολλῶ τοῦ ἀδελφοῦ, πολλὰ παρεκάλεσα αὐτὸν ἵνα ἔλθῃ πρὸς ὑμᾶς μετὰ τῶν ἀδελφῶν· καὶ πάντως οὐκ ἦν θέλημα ἵνα νῦν ἔλθῃ, ἐλεύσεται δὲ ὅταν εὐκαιρήσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 13, '¶Γρηγορεῖτε, στήκετε ἐν τῇ πίστει, ἀνδρίζεσθε, κραταιοῦσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 14, 'Πάντα ὑμῶν ἐν ἀγάπῃ γινέσθω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 15, '¶Παρακαλῶ δὲ ὑμᾶς, ἀδελφοί, οἴδατε τὴν οἰκίαν Στεφανᾶ ὅτι ἐστὶν ἀπαρχὴ τῆς Ἀχαΐας, καὶ εἰς διακονίαν τοῖς ἁγίοις ἔταξαν ἑαυτούς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 16, 'ἵνα καὶ ὑμεῖς ὑποτάσσησθε τοῖς τοιούτοις, καὶ παντὶ τῷ συνεργοῦντι καὶ κοπιῶντι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 17, 'Χαίρω δὲ ἐπὶ τῇ παρουσίᾳ Στεφανᾶ, καὶ Φορτουνάτου, καὶ Ἀχαϊκοῦ, ὅτι τὸ ὑμῶν ὑστέρημα οὗτοι ἀνεπλήρωσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 18, 'Ἀνέπαυσαν γὰρ τὸ ἐμὸν πνεῦμα καὶ τὸ ὑμῶν. Ἐπιγινώσκετε οὖν τοὺς τοιούτους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 19, '¶Ἀσπάζονται ὑμᾶς αἱ ἐκκλησίαι τῆς Ἀσίας. Ἀσπάζονται ὑμᾶς ἐν  ̊Κυρίῳ πολλὰ Ἀκύλας καὶ Πρίσκα, σὺν τῇ κατʼ οἶκον αὐτῶν ἐκκλησίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 20, 'Ἀσπάζονται ὑμᾶς οἱ ἀδελφοὶ πάντες. Ἀσπάσασθε ἀλλήλους ἐν φιλήματι ἁγίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 21, '¶Ὁ ἀσπασμὸς τῇ ἐμῇ χειρὶ, Παύλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 22, 'Εἴ τις οὐ φιλεῖ τὸν  ̊Κύριον, ἤτω ἀνάθεμα. Μαράνα θά!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 23, 'Ἡ χάρις τοῦ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ μεθʼ ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 16, 24, 'Ἡ ἀγάπη μου μετὰ πάντων ὑμῶν ἐν  ̊Χριστῷ  ̊Ἰησοῦ. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, '¶Παῦλος, ἀπόστολος  ̊Χριστοῦ  ̊Ἰησοῦ διὰ θελήματος  ̊Θεοῦ, καὶ Τιμόθεος ὁ ἀδελφὸς, τῇ ἐκκλησίᾳ τοῦ  ̊Θεοῦ τῇ οὔσῃ ἐν Κορίνθῳ, σὺν τοῖς ἁγίοις πᾶσιν τοῖς οὖσιν ἐν ὅλῃ τῇ Ἀχαΐᾳ:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'χάρις ὑμῖν καὶ εἰρήνη, ἀπὸ  ̊Θεοῦ Πατρὸς ἡμῶν καὶ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, '¶Εὐλογητὸς ὁ  ̊Θεὸς καὶ Πατὴρ τοῦ  ̊Κυρίου ἡμῶν  ̊Ἰησοῦ  ̊Χριστοῦ, ὁ Πατὴρ τῶν οἰκτιρμῶν καὶ  ̊Θεὸς πάσης παρακλήσεως,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'ὁ παρακαλῶν ἡμᾶς ἐπὶ πάσῃ τῇ θλίψει ἡμῶν, εἰς τὸ δύνασθαι ἡμᾶς παρακαλεῖν τοὺς ἐν πάσῃ θλίψει, διὰ τῆς παρακλήσεως ἧς παρακαλούμεθα αὐτοὶ ὑπὸ τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Ὅτι καθὼς περισσεύει τὰ παθήματα τοῦ  ̊Χριστοῦ εἰς ἡμᾶς, οὕτως διὰ τοῦ  ̊Χριστοῦ περισσεύει καὶ ἡ παράκλησις ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Εἴτε δὲ θλιβόμεθα, ὑπὲρ τῆς ὑμῶν παρακλήσεως καὶ σωτηρίας, εἴτε παρακαλούμεθα, ὑπὲρ τῆς ὑμῶν παρακλήσεως, τῆς ἐνεργουμένης ἐν ὑπομονῇ τῶν αὐτῶν παθημάτων, ὧν καὶ ἡμεῖς πάσχομεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Καὶ ἡ ἐλπὶς ἡμῶν βεβαία ὑπὲρ ὑμῶν, εἰδότες ὅτι ὡς κοινωνοί ἐστε τῶν παθημάτων, οὕτως καὶ τῆς παρακλήσεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, '¶Οὐ γὰρ θέλομεν ὑμᾶς ἀγνοεῖν, ἀδελφοί, ὑπὲρ τῆς θλίψεως ἡμῶν τῆς γενομένης ἐν τῇ Ἀσίᾳ, ὅτι καθʼ ὑπερβολὴν ὑπὲρ δύναμιν ἐβαρήθημεν, ὥστε ἐξαπορηθῆναι ἡμᾶς καὶ τοῦ ζῆν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Ἀλλὰ αὐτοὶ ἐν ἑαυτοῖς τὸ ἀπόκριμα τοῦ θανάτου ἐσχήκαμεν, ἵνα μὴ πεποιθότες ὦμεν ἐφʼ ἑαυτοῖς, ἀλλʼ ἐπὶ τῷ  ̊Θεῷ, τῷ ἐγείροντι τοὺς νεκρούς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'ὃς ἐκ τηλικούτου θανάτου ἐρρύσατο ἡμᾶς, καὶ ῥύσεται, εἰς ὃν ἠλπίκαμεν ὅτι καὶ ἔτι ῥύσεται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'συνυπουργούντων καὶ ὑμῶν ὑπὲρ ἡμῶν τῇ δεήσει, ἵνα ἐκ πολλῶν προσώπων, τὸ εἰς ἡμᾶς χάρισμα, διὰ πολλῶν, εὐχαριστηθῇ ὑπὲρ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, '¶Ἡ γὰρ καύχησις ἡμῶν αὕτη ἐστίν: τὸ μαρτύριον τῆς συνειδήσεως ἡμῶν, ὅτι ἐν ἁγιότητι καὶ εἰλικρινείᾳ τοῦ  ̊Θεοῦ, καὶ οὐκ ἐν σοφίᾳ σαρκικῇ, ἀλλʼ ἐν χάριτι  ̊Θεοῦ, ἀνεστράφημεν ἐν τῷ κόσμῳ, περισσοτέρως δὲ πρὸς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Οὐ γὰρ ἄλλα γράφομεν ὑμῖν, ἀλλʼ ἢ ἃ ἀναγινώσκετε ἢ καὶ ἐπιγινώσκετε, ἐλπίζω δὲ ὅτι ἕως τέλους ἐπιγνώσεσθε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'καθὼς καὶ ἐπέγνωτε ἡμᾶς ἀπὸ μέρους, ὅτι καύχημα ὑμῶν ἐσμεν, καθάπερ καὶ ὑμεῖς ἡμῶν, ἐν τῇ ἡμέρᾳ τοῦ  ̊Κυρίου  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, '¶Καὶ ταύτῃ τῇ πεποιθήσει ἐβουλόμην πρότερον, πρὸς ὑμᾶς ἐλθεῖν, ἵνα δευτέραν χάριν σχῆτε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'καὶ διʼ ὑμῶν διελθεῖν εἰς Μακεδονίαν, καὶ πάλιν ἀπὸ Μακεδονίας ἐλθεῖν πρὸς ὑμᾶς, καὶ ὑφʼ ὑμῶν προπεμφθῆναι εἰς τὴν Ἰουδαίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Τοῦτο οὖν βουλόμενος, μήτι ἄρα τῇ ἐλαφρίᾳ ἐχρησάμην; Ἢ ἃ βουλεύομαι, κατὰ σάρκα βουλεύομαι, ἵνα ᾖ παρʼ ἐμοὶ τὸ “Ναὶ, ναὶ”, καὶ τὸ “Οὒ, οὔ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Πιστὸς δὲ ὁ  ̊Θεὸς, ὅτι ὁ λόγος ἡμῶν ὁ πρὸς ὑμᾶς, οὐκ ἔστιν “Ναὶ” καὶ “Οὔ”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Ὁ τοῦ  ̊Θεοῦ γὰρ Υἱὸς,  ̊Ἰησοῦς  ̊Χριστὸς, ὁ ἐν ὑμῖν διʼ ἡμῶν κηρυχθείς, διʼ ἐμοῦ, καὶ Σιλουανοῦ, καὶ Τιμοθέου, οὐκ ἐγένετο “Ναὶ” καὶ “Οὒ”, ἀλλὰ “Ναὶ” ἐν αὐτῷ γέγονεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Ὅσαι γὰρ ἐπαγγελίαι  ̊Θεοῦ, ἐν αὐτῷ τὸ “Ναί”. Διὸ καὶ διʼ αὐτοῦ, τὸ “Ἀμὴν”, τῷ  ̊Θεῷ πρὸς δόξαν διʼ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'Ὁ δὲ βεβαιῶν ἡμᾶς σὺν ὑμῖν εἰς  ̊Χριστὸν καὶ χρίσας ἡμᾶς  ̊Θεός,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'ὁ καὶ σφραγισάμενος ἡμᾶς καὶ δοὺς τὸν ἀρραβῶνα τοῦ  ̊Πνεύματος ἐν ταῖς καρδίαις ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, '¶Ἐγὼ δὲ μάρτυρα τὸν  ̊Θεὸν ἐπικαλοῦμαι ἐπὶ τὴν ἐμὴν ψυχήν ὅτι φειδόμενος ὑμῶν οὐκέτι ἦλθον εἰς Κόρινθον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Οὐχ ὅτι κυριεύομεν ὑμῶν τῆς πίστεως, ἀλλὰ συνεργοί ἐσμεν τῆς χαρᾶς ὑμῶν, τῇ γὰρ πίστει ἑστήκατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 1, 'Ἔκρινα γὰρ ἐμαυτῷ τοῦτο, τὸ μὴ πάλιν ἐν λύπῃ πρὸς ὑμᾶς ἐλθεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 2, 'Εἰ γὰρ ἐγὼ λυπῶ ὑμᾶς, καὶ τίς ὁ εὐφραίνων με, εἰ μὴ ὁ λυπούμενος ἐξ ἐμοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 3, 'Καὶ ἔγραψα τοῦτο αὐτὸ, ἵνα μὴ ἐλθὼν, λύπην σχῶ ἀφʼ ὧν ἔδει με χαίρειν, πεποιθὼς ἐπὶ πάντας ὑμᾶς ὅτι ἡ ἐμὴ χαρὰ πάντων ὑμῶν ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 4, 'Ἐκ γὰρ πολλῆς θλίψεως καὶ συνοχῆς καρδίας, ἔγραψα ὑμῖν διὰ πολλῶν δακρύων, οὐχ ἵνα λυπηθῆτε, ἀλλὰ τὴν ἀγάπην ἵνα γνῶτε ἣν ἔχω περισσοτέρως εἰς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 5, '¶Εἰ δέ τις λελύπηκεν, οὐκ ἐμὲ λελύπηκεν, ἀλλὰ ἀπὸ μέρους, ἵνα μὴ ἐπιβαρῶ πάντας ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 6, 'Ἱκανὸν τῷ τοιούτῳ ἡ ἐπιτιμία αὕτη, ἡ ὑπὸ τῶν πλειόνων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 7, 'ὥστε τοὐναντίον μᾶλλον ὑμᾶς χαρίσασθαι καὶ παρακαλέσαι, μή πως τῇ περισσοτέρᾳ λύπῃ, καταποθῇ ὁ τοιοῦτος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 8, 'Διὸ παρακαλῶ ὑμᾶς, κυρῶσαι εἰς αὐτὸν ἀγάπην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 9, 'Εἰς τοῦτο γὰρ καὶ ἔγραψα, ἵνα γνῶ τὴν δοκιμὴν ὑμῶν, εἰ εἰς πάντα ὑπήκοοί ἐστε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 10, 'ὯΙ δέ τι χαρίζεσθε, κἀγώ· καὶ γὰρ ἐγὼ ὃ κεχάρισμαι, εἴ τι κεχάρισμαι, διʼ ὑμᾶς ἐν προσώπῳ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 11, 'ἵνα μὴ πλεονεκτηθῶμεν ὑπὸ τοῦ Σατανᾶ, οὐ γὰρ αὐτοῦ τὰ νοήματα ἀγνοοῦμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 12, '¶Ἐλθὼν δὲ εἰς τὴν Τρῳάδα εἰς τὸ εὐαγγέλιον τοῦ  ̊Χριστοῦ, καὶ θύρας μοι ἀνεῳγμένης ἐν  ̊Κυρίῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 13, 'οὐκ ἔσχηκα ἄνεσιν τῷ πνεύματί μου, τῷ μὴ εὑρεῖν με Τίτον τὸν ἀδελφόν μου, ἀλλὰ ἀποταξάμενος αὐτοῖς, ἐξῆλθον εἰς Μακεδονίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 14, '¶Τῷ δὲ  ̊Θεῷ χάρις, τῷ πάντοτε θριαμβεύοντι ἡμᾶς ἐν τῷ  ̊Χριστῷ, καὶ τὴν ὀσμὴν τῆς γνώσεως αὐτοῦ, φανεροῦντι διʼ ἡμῶν ἐν παντὶ τόπῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 15, 'Ὅτι  ̊Χριστοῦ εὐωδία ἐσμὲν τῷ  ̊Θεῷ, ἐν τοῖς σῳζομένοις καὶ ἐν τοῖς ἀπολλυμένοις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 16, 'οἷς μὲν ὀσμὴ ἐκ θανάτου εἰς θάνατον, οἷς δὲ ὀσμὴ ἐκ ζωῆς εἰς ζωήν. Καὶ πρὸς ταῦτα τίς ἱκανός;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 17, 'Οὐ γάρ ἐσμεν ὡς οἱ πολλοὶ καπηλεύοντες τὸν λόγον τοῦ  ̊Θεοῦ, ἀλλʼ ὡς ἐξ εἰλικρινείας, ἀλλʼ ὡς ἐκ  ̊Θεοῦ, κατέναντι  ̊Θεοῦ ἐν  ̊Χριστῷ λαλοῦμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 1, '¶Ἀρχόμεθα πάλιν ἑαυτοὺς συνιστάνειν; Ἢ μὴ χρῄζομεν, ὥς τινες, συστατικῶν ἐπιστολῶν πρὸς ὑμᾶς ἢ ἐξ ὑμῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 2, 'Ἡ ἐπιστολὴ ἡμῶν ὑμεῖς ἐστε, ἐγγεγραμμένη ἐν ταῖς καρδίαις ἡμῶν, γινωσκομένη καὶ ἀναγινωσκομένη ὑπὸ πάντων ἀνθρώπων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 3, 'φανερούμενοι ὅτι ἐστὲ ἐπιστολὴ  ̊Χριστοῦ, διακονηθεῖσα ὑφʼ ἡμῶν, ἐγγεγραμμένη οὐ μέλανι, ἀλλὰ  ̊Πνεύματι  ̊Θεοῦ ζῶντος, οὐκ ἐν πλαξὶν λιθίναις, ἀλλʼ ἐν πλαξὶν καρδίαις σαρκίναις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 4, '¶Πεποίθησιν δὲ τοιαύτην ἔχομεν διὰ τοῦ  ̊Χριστοῦ πρὸς τὸν  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 5, 'Οὐχ ὅτι ἀφʼ ἑαυτῶν ἱκανοί ἐσμεν λογίσασθαί τι ὡς ἐξ ἑαυτῶν, ἀλλʼ ἡ ἱκανότης ἡμῶν ἐκ τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 6, 'ὃς καὶ ἱκάνωσεν ἡμᾶς διακόνους καινῆς διαθήκης, οὐ γράμματος, ἀλλὰ  ̊Πνεύματος, τὸ γὰρ γράμμα ἀποκτένει, τὸ δὲ  ̊Πνεῦμα ζῳοποιεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 7, '¶Εἰ δὲ ἡ διακονία τοῦ θανάτου ἐν γράμμασιν ἐντετυπωμένη λίθοις ἐγενήθη ἐν δόξῃ, ὥστε μὴ δύνασθαι ἀτενίσαι τοὺς υἱοὺς Ἰσραὴλ εἰς τὸ πρόσωπον Μωϋσέως, διὰ τὴν δόξαν τοῦ προσώπου αὐτοῦ, τὴν καταργουμένην,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 8, 'πῶς οὐχὶ μᾶλλον ἡ διακονία τοῦ  ̊Πνεύματος ἔσται ἐν δόξῃ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 9, 'Εἰ γὰρ τῇ διακονίᾳ τῆς κατακρίσεως, δόξα πολλῷ μᾶλλον περισσεύει ἡ διακονία τῆς δικαιοσύνης δόξῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 10, 'Καὶ γὰρ οὐ δεδόξασται, τὸ δεδοξασμένον ἐν τούτῳ τῷ μέρει εἵνεκεν τῆς ὑπερβαλλούσης δόξης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 11, 'Εἰ γὰρ τὸ καταργούμενον διὰ δόξης, πολλῷ μᾶλλον τὸ μένον ἐν δόξῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 12, '¶Ἔχοντες οὖν τοιαύτην ἐλπίδα πολλῇ παρρησίᾳ χρώμεθα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 13, 'καὶ οὐ καθάπερ Μωϋσῆς ἐτίθει κάλυμμα ἐπὶ τὸ πρόσωπον αὐτοῦ, πρὸς τὸ μὴ ἀτενίσαι τοὺς υἱοὺς Ἰσραὴλ, εἰς τὸ τέλος τοῦ καταργουμένου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 14, 'Ἀλλʼ ἐπωρώθη τὰ νοήματα αὐτῶν. Ἄχρι γὰρ τῆς σήμερον ἡμέρας, τὸ αὐτὸ κάλυμμα ἐπὶ τῇ ἀναγνώσει τῆς παλαιᾶς διαθήκης μένει, μὴ ἀνακαλυπτόμενον ὅτι ἐν  ̊Χριστῷ καταργεῖται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 15, 'Ἀλλʼ ἕως σήμερον ἡνίκα ἂν ἀναγινώσκηται Μωϋσῆς, κάλυμμα ἐπὶ τὴν καρδίαν αὐτῶν κεῖται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 16, 'Ἡνίκα δὲ ἐὰν ἐπιστρέψῃ πρὸς  ̊Κύριον, περιαιρεῖται τὸ κάλυμμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 17, 'Ὁ δὲ  ̊Κύριος τὸ  ̊Πνεῦμά ἐστιν· οὗ δὲ τὸ  ̊Πνεῦμα  ̊Κυρίου, ἐλευθερία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 18, 'Ἡμεῖς δὲ πάντες ἀνακεκαλυμμένῳ προσώπῳ, τὴν δόξαν  ̊Κυρίου κατοπτριζόμενοι, τὴν αὐτὴν εἰκόνα μεταμορφούμεθα, ἀπὸ δόξης εἰς δόξαν, καθάπερ ἀπὸ  ̊Κυρίου,  ̊Πνεύματος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 1, '¶Διὰ τοῦτο ἔχοντες τὴν διακονίαν ταύτην, καθὼς ἠλεήθημεν, οὐκ ἐγκακοῦμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 2, 'Ἀλλὰ ἀπειπάμεθα τὰ κρυπτὰ τῆς αἰσχύνης, μὴ περιπατοῦντες ἐν πανουργίᾳ, μηδὲ δολοῦντες τὸν λόγον τοῦ  ̊Θεοῦ, ἀλλὰ τῇ φανερώσει τῆς ἀληθείας, συνιστάνοντες ἑαυτοὺς πρὸς πᾶσαν συνείδησιν ἀνθρώπων ἐνώπιον τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 3, 'Εἰ δὲ καὶ ἔστιν κεκαλυμμένον τὸ εὐαγγέλιον ἡμῶν, ἐν τοῖς ἀπολλυμένοις ἐστὶν κεκαλυμμένον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 4, 'ἐν οἷς ὁ  ̊θεὸς τοῦ αἰῶνος τούτου ἐτύφλωσεν τὰ νοήματα τῶν ἀπίστων, εἰς τὸ μὴ αὐγάσαι τὸν φωτισμὸν τοῦ εὐαγγελίου τῆς δόξης τοῦ  ̊Χριστοῦ, ὅς ἐστιν εἰκὼν τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 5, 'Οὐ γὰρ ἑαυτοὺς κηρύσσομεν, ἀλλὰ  ̊Ἰησοῦν  ̊Χριστὸν  ̊Κύριον, ἑαυτοὺς δὲ δούλους ὑμῶν διὰ  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 6, 'Ὅτι ὁ  ̊Θεὸς ὁ εἰπών, “Ἐκ σκότους φῶς λάμψει”, ὃς ἔλαμψεν ἐν ταῖς καρδίαις ἡμῶν, πρὸς φωτισμὸν τῆς γνώσεως τῆς δόξης τοῦ  ̊Θεοῦ ἐν προσώπῳ  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 7, '¶Ἔχομεν δὲ τὸν θησαυρὸν τοῦτον ἐν ὀστρακίνοις σκεύεσιν, ἵνα ἡ ὑπερβολὴ τῆς δυνάμεως ᾖ τοῦ  ̊Θεοῦ, καὶ μὴ ἐξ ἡμῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 8, 'ἐν παντὶ θλιβόμενοι, ἀλλʼ οὐ στενοχωρούμενοι, ἀπορούμενοι, ἀλλʼ οὐκ ἐξαπορούμενοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 9, 'διωκόμενοι, ἀλλʼ οὐκ ἐγκαταλειπόμενοι, καταβαλλόμενοι, ἀλλʼ οὐκ ἀπολλύμενοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 10, 'πάντοτε τὴν νέκρωσιν τοῦ  ̊Ἰησοῦ ἐν τῷ σώματι περιφέροντες, ἵνα καὶ ἡ ζωὴ τοῦ  ̊Ἰησοῦ ἐν τῷ σώματι ἡμῶν φανερωθῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 11, 'Ἀεὶ γὰρ ἡμεῖς, οἱ ζῶντες, εἰς θάνατον παραδιδόμεθα διὰ  ̊Ἰησοῦν, ἵνα καὶ ἡ ζωὴ τοῦ  ̊Ἰησοῦ φανερωθῇ ἐν τῇ θνητῇ σαρκὶ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 12, 'Ὥστε ὁ θάνατος ἐν ἡμῖν ἐνεργεῖται, ἡ δὲ ζωὴ ἐν ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 13, '¶Ἔχοντες δὲ τὸ αὐτὸ πνεῦμα τῆς πίστεως, κατὰ τὸ γεγραμμένον, “Ἐπίστευσα, διὸ ἐλάλησα”, καὶ ἡμεῖς πιστεύομεν, διὸ καὶ λαλοῦμεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 14, 'εἰδότες ὅτι ὁ ἐγείρας τὸν  ̊Ἰησοῦν, καὶ ἡμᾶς σὺν  ̊Ἰησοῦ ἐγερεῖ, καὶ παραστήσει σὺν ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 15, 'Τὰ γὰρ πάντα διʼ ὑμᾶς, ἵνα ἡ χάρις πλεονάσασα διὰ τῶν πλειόνων, τὴν εὐχαριστίαν περισσεύσῃ εἰς τὴν δόξαν τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 16, '¶Διὸ οὐκ ἐγκακοῦμεν, ἀλλʼ εἰ καὶ ὁ ἔξω ἡμῶν ἄνθρωπος διαφθείρεται, ἀλλʼ ὁ ἔσω ἡμῶν ἀνακαινοῦται ἡμέρᾳ καὶ ἡμέρᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 17, 'Τὸ γὰρ παραυτίκα ἐλαφρὸν τῆς θλίψεως καθʼ ὑπερβολὴν εἰς ὑπερβολὴν αἰώνιον βάρος δόξης, κατεργάζεται ἡμῖν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 18, 'μὴ σκοπούντων ἡμῶν τὰ βλεπόμενα, ἀλλὰ τὰ μὴ βλεπόμενα, τὰ γὰρ βλεπόμενα πρόσκαιρα, τὰ δὲ μὴ βλεπόμενα αἰώνια.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 1, '¶Οἴδαμεν γὰρ ὅτι ἐὰν ἡ ἐπίγειος ἡμῶν οἰκία τοῦ σκήνους καταλυθῇ, οἰκοδομὴν ἐκ  ̊Θεοῦ ἔχομεν, οἰκίαν ἀχειροποίητον αἰώνιον ἐν τοῖς οὐρανοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 2, 'Καὶ γὰρ ἐν τούτῳ στενάζομεν, τὸ οἰκητήριον ἡμῶν τὸ ἐξ οὐρανοῦ ἐπενδύσασθαι ἐπιποθοῦντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 3, 'Εἴ γε καὶ ἐνδυσάμενοι, οὐ γυμνοὶ εὑρεθησόμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 4, 'Καὶ γὰρ οἱ ὄντες ἐν τῷ σκήνει, στενάζομεν, βαρούμενοι ἐφʼ ᾧ οὐ θέλομεν ἐκδύσασθαι, ἀλλʼ ἐπενδύσασθαι, ἵνα καταποθῇ τὸ θνητὸν ὑπὸ τῆς ζωῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 5, 'Ὁ δὲ κατεργασάμενος ἡμᾶς εἰς αὐτὸ τοῦτο  ̊Θεός, ὁ δοὺς ἡμῖν τὸν ἀρραβῶνα τοῦ  ̊Πνεύματος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 6, '¶Θαρροῦντες οὖν πάντοτε, καὶ εἰδότες ὅτι ἐνδημοῦντες ἐν τῷ σώματι, ἐκδημοῦμεν ἀπὸ τοῦ  ̊Κυρίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 7, 'διὰ πίστεως γὰρ περιπατοῦμεν, οὐ διὰ εἴδους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 8, 'Θαρροῦμεν δὲ καὶ εὐδοκοῦμεν μᾶλλον ἐκδημῆσαι ἐκ τοῦ σώματος καὶ ἐνδημῆσαι πρὸς τὸν  ̊Κύριον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 9, 'Διὸ καὶ φιλοτιμούμεθα, εἴτε ἐνδημοῦντες εἴτε ἐκδημοῦντες, εὐάρεστοι αὐτῷ εἶναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 10, 'Τοὺς γὰρ πάντας ἡμᾶς φανερωθῆναι δεῖ, ἔμπροσθεν τοῦ βήματος τοῦ  ̊Χριστοῦ, ἵνα κομίσηται ἕκαστος τὰ διὰ τοῦ σώματος, πρὸς ἃ ἔπραξεν, εἴτε ἀγαθὸν εἴτε κακόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 11, '¶Εἰδότες οὖν τὸν φόβον τοῦ  ̊Κυρίου, ἀνθρώπους πείθομεν,  ̊Θεῷ δὲ πεφανερώμεθα· ἐλπίζω δὲ καὶ ἐν ταῖς συνειδήσεσιν ὑμῶν πεφανερῶσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 12, 'Οὐ πάλιν ἑαυτοὺς συνιστάνομεν ὑμῖν, ἀλλὰ ἀφορμὴν διδόντες ὑμῖν καυχήματος ὑπὲρ ἡμῶν, ἵνα ἔχητε πρὸς τοὺς ἐν προσώπῳ καυχωμένους, καὶ μὴ ἐν καρδίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 13, 'Εἴτε γὰρ ἐξέστημεν,  ̊Θεῷ· εἴτε σωφρονοῦμεν, ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 14, 'Ἡ γὰρ ἀγάπη τοῦ  ̊Χριστοῦ συνέχει ἡμᾶς, κρίναντας τοῦτο, ὅτι εἷς ὑπὲρ πάντων ἀπέθανεν, ἄρα οἱ πάντες ἀπέθανον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 15, 'Καὶ ὑπὲρ πάντων ἀπέθανεν, ἵνα οἱ ζῶντες, μηκέτι ἑαυτοῖς ζῶσιν, ἀλλὰ τῷ ὑπὲρ αὐτῶν ἀποθανόντι καὶ ἐγερθέντι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 16, '¶Ὥστε ἡμεῖς ἀπὸ τοῦ νῦν οὐδένα οἴδαμεν κατὰ σάρκα. Εἰ καὶ ἐγνώκαμεν κατὰ σάρκα  ̊Χριστόν, ἀλλὰ νῦν οὐκέτι γινώσκομεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 17, 'Ὥστε εἴ τις ἐν  ̊Χριστῷ, καινὴ κτίσις· τὰ ἀρχαῖα παρῆλθεν, ἰδοὺ, γέγονεν καινά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 18, 'Τὰ δὲ πάντα ἐκ τοῦ  ̊Θεοῦ, τοῦ καταλλάξαντος ἡμᾶς ἑαυτῷ διὰ  ̊Χριστοῦ, καὶ δόντος ἡμῖν τὴν διακονίαν τῆς καταλλαγῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 19, 'ὡς ὅτι  ̊Θεὸς ἦν ἐν  ̊Χριστῷ κόσμον καταλλάσσων ἑαυτῷ, μὴ λογιζόμενος αὐτοῖς τὰ παραπτώματα αὐτῶν, καὶ θέμενος ἐν ἡμῖν τὸν λόγον τῆς καταλλαγῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 20, 'Ὑπὲρ  ̊Χριστοῦ οὖν πρεσβεύομεν, ὡς τοῦ  ̊Θεοῦ παρακαλοῦντος διʼ ἡμῶν· δεόμεθα ὑπὲρ  ̊Χριστοῦ, καταλλάγητε τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 21, 'Τὸν μὴ γνόντα ἁμαρτίαν, ὑπὲρ ἡμῶν ἁμαρτίαν ἐποίησεν, ἵνα ἡμεῖς γενώμεθα δικαιοσύνη  ̊Θεοῦ ἐν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 1, '¶Συνεργοῦντες δὲ καὶ, παρακαλοῦμεν μὴ εἰς κενὸν τὴν χάριν τοῦ  ̊Θεοῦ δέξασθαι ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 2, 'Λέγει γάρ, “Καιρῷ δεκτῷ ἐπήκουσά σου, καὶ ἐν ἡμέρᾳ σωτηρίας ἐβοήθησά σοι.” Ἰδοὺ, νῦν “καιρὸς εὐπρόσδεκτος”, ἰδοὺ, νῦν “ἡμέρα σωτηρίας”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 3, 'Μηδεμίαν ἐν μηδενὶ διδόντες προσκοπήν, ἵνα μὴ μωμηθῇ ἡ διακονία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 4, 'Ἀλλʼ ἐν παντὶ συνιστάντες ἑαυτοὺς ὡς  ̊Θεοῦ διάκονοι: ἐν ὑπομονῇ πολλῇ, ἐν θλίψεσιν, ἐν ἀνάγκαις, ἐν στενοχωρίαις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 5, 'ἐν πληγαῖς, ἐν φυλακαῖς, ἐν ἀκαταστασίαις, ἐν κόποις, ἐν ἀγρυπνίαις, ἐν νηστείαις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 6, 'ἐν ἁγνότητι, ἐν γνώσει, ἐν μακροθυμίᾳ, ἐν χρηστότητι, ἐν  ̊Πνεύματι Ἁγίῳ, ἐν ἀγάπῃ ἀνυποκρίτῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 7, 'ἐν λόγῳ ἀληθείας, ἐν δυνάμει  ̊Θεοῦ, διὰ τῶν ὅπλων τῆς δικαιοσύνης τῶν δεξιῶν καὶ ἀριστερῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 8, 'διὰ δόξης καὶ ἀτιμίας, διὰ δυσφημίας καὶ εὐφημίας· ὡς πλάνοι καὶ ἀληθεῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 9, 'ὡς ἀγνοούμενοι καὶ ἐπιγινωσκόμενοι, ὡς ἀποθνῄσκοντες καὶ ἰδοὺ, ζῶμεν, ὡς παιδευόμενοι καὶ μὴ θανατούμενοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 10, 'ὡς λυπούμενοι ἀεὶ δὲ χαίροντες, ὡς πτωχοὶ πολλοὺς δὲ πλουτίζοντες, ὡς μηδὲν ἔχοντες καὶ πάντα κατέχοντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 11, '¶Τὸ στόμα ἡμῶν ἀνέῳγεν πρὸς ὑμᾶς, Κορίνθιοι, ἡ καρδία ἡμῶν πεπλάτυνται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 12, 'Οὐ στενοχωρεῖσθε ἐν ἡμῖν, στενοχωρεῖσθε δὲ ἐν τοῖς σπλάγχνοις ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 13, 'Τὴν δὲ αὐτὴν ἀντιμισθίαν (ὡς τέκνοις λέγω) πλατύνθητε καὶ ὑμεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 14, '¶Μὴ γίνεσθε ἑτεροζυγοῦντες ἀπίστοις· τίς γὰρ μετοχὴ δικαιοσύνῃ καὶ ἀνομίᾳ, ἢ τίς κοινωνία φωτὶ πρὸς σκότος;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 15, 'Τίς δὲ συμφώνησις  ̊Χριστοῦ πρὸς Βελιάρ, ἢ τίς μερὶς πιστῷ μετὰ ἀπίστου;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 16, 'Τίς δὲ συγκατάθεσις ναῷ  ̊Θεοῦ μετὰ εἰδώλων; ἡμεῖς γὰρ ναὸς  ̊Θεοῦ ἐσμεν ζῶντος, καθὼς εἶπεν ὁ  ̊Θεὸς, ὅτι “Ἐνοικήσω ἐν αὐτοῖς”, καὶ “ἐμπεριπατήσω, καὶ ἔσομαι αὐτῶν  ̊Θεός, καὶ αὐτοὶ ἔσονταί μου λαός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 17, '“Διὸ ἐξέλθατε ἐκ μέσου αὐτῶν καὶ ἀφορίσθητε”, λέγει  ̊Κύριος, “καὶ ἀκαθάρτου μὴ ἅπτεσθε”· “Κἀγὼ εἰσδέξομαι ὑμᾶς”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 18, '“Καὶ ἔσομαι ὑμῖν εἰς πατέρα, καὶ ὑμεῖς ἔσεσθέ μοι εἰς υἱοὺς καὶ θυγατέρας”, λέγει  ̊Κύριος Παντοκράτωρ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 1, 'Ταύτας οὖν ἔχοντες τὰς ἐπαγγελίας, ἀγαπητοί, καθαρίσωμεν ἑαυτοὺς ἀπὸ παντὸς μολυσμοῦ σαρκὸς καὶ πνεύματος, ἐπιτελοῦντες ἁγιωσύνην ἐν φόβῳ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 2, '¶Χωρήσατε ἡμᾶς· οὐδένα ἠδικήσαμεν, οὐδένα ἐφθείραμεν, οὐδένα ἐπλεονεκτήσαμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 3, 'Πρὸς κατάκρισιν οὐ λέγω, προείρηκα γὰρ ὅτι ἐν ταῖς καρδίαις ἡμῶν ἐστε, εἰς τὸ συναποθανεῖν καὶ συζῆν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 4, 'Πολλή μοι παρρησία πρὸς ὑμᾶς, πολλή μοι καύχησις ὑπὲρ ὑμῶν· πεπλήρωμαι τῇ παρακλήσει, ὑπερπερισσεύομαι τῇ χαρᾷ ἐπὶ πάσῃ τῇ θλίψει ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 5, '¶Καὶ γὰρ ἐλθόντων ἡμῶν εἰς Μακεδονίαν, οὐδεμίαν ἔσχηκεν ἄνεσιν ἡ σὰρξ ἡμῶν, ἀλλʼ ἐν παντὶ θλιβόμενοι– ἔξωθεν μάχαι, ἔσωθεν φόβοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 6, 'Ἀλλʼ ὁ παρακαλῶν τοὺς ταπεινοὺς, παρεκάλεσεν ἡμᾶς ὁ  ̊Θεὸς ἐν τῇ παρουσίᾳ Τίτου·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 7, 'οὐ μόνον δὲ ἐν τῇ παρουσίᾳ αὐτοῦ, ἀλλὰ καὶ ἐν τῇ παρακλήσει ᾗ παρεκλήθη ἐφʼ ὑμῖν, ἀναγγέλλων ἡμῖν τὴν ὑμῶν ἐπιπόθησιν, τὸν ὑμῶν ὀδυρμόν, τὸν ὑμῶν ζῆλον ὑπὲρ ἐμοῦ, ὥστε με μᾶλλον χαρῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 8, 'Ὅτι εἰ καὶ ἐλύπησα ὑμᾶς ἐν τῇ ἐπιστολῇ, οὐ μεταμέλομαι. Εἰ καὶ μετεμελόμην (βλέπω ὅτι ἡ ἐπιστολὴ ἐκείνη, εἰ καὶ πρὸς ὥραν ἐλύπησεν ὑμᾶς)');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 9, 'νῦν χαίρω οὐχ ὅτι ἐλυπήθητε, ἀλλʼ ὅτι ἐλυπήθητε εἰς μετάνοιαν, ἐλυπήθητε γὰρ κατὰ  ̊Θεόν, ἵνα ἐν μηδενὶ ζημιωθῆτε ἐξ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 10, 'Ἡ γὰρ κατὰ  ̊Θεὸν λύπη, μετάνοιαν εἰς σωτηρίαν ἀμεταμέλητον ἐργάζεται· ἡ δὲ τοῦ κόσμου λύπη, θάνατον κατεργάζεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 11, 'Ἰδοὺ γὰρ αὐτὸ τοῦτο τὸ κατὰ  ̊Θεὸν λυπηθῆναι, πόσην κατειργάσατο ὑμῖν σπουδήν: ἀλλὰ ἀπολογίαν, ἀλλὰ ἀγανάκτησιν, ἀλλὰ φόβον, ἀλλὰ ἐπιπόθησιν, ἀλλὰ ζῆλον, ἀλλὰ ἐκδίκησιν! Ἐν παντὶ συνεστήσατε ἑαυτοὺς ἁγνοὺς εἶναι τῷ πράγματι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 12, 'Ἄρα εἰ καὶ ἔγραψα ὑμῖν, οὐχ ἕνεκεν τοῦ ἀδικήσαντος, οὐδὲ ἕνεκεν τοῦ ἀδικηθέντος, ἀλλʼ ἕνεκεν τοῦ φανερωθῆναι τὴν σπουδὴν ὑμῶν, τὴν ὑπὲρ ἡμῶν πρὸς ὑμᾶς ἐνώπιον τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 13, 'Διὰ τοῦτο παρακεκλήμεθα. ¶Ἐπὶ δὲ τῇ παρακλήσει ἡμῶν, περισσοτέρως μᾶλλον ἐχάρημεν ἐπὶ τῇ χαρᾷ Τίτου, ὅτι ἀναπέπαυται τὸ πνεῦμα αὐτοῦ ἀπὸ πάντων ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 14, 'Ὅτι εἴ τι αὐτῷ ὑπὲρ ὑμῶν κεκαύχημαι, οὐ κατῃσχύνθην, ἀλλʼ ὡς πάντα ἐν ἀληθείᾳ ἐλαλήσαμεν ὑμῖν, οὕτως καὶ ἡ καύχησις ἡμῶν ἐπὶ Τίτου ἀλήθεια ἐγενήθη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 15, 'Καὶ τὰ σπλάγχνα αὐτοῦ περισσοτέρως εἰς ὑμᾶς ἐστιν, ἀναμιμνῃσκομένου τὴν πάντων ὑμῶν ὑπακοήν, ὡς μετὰ φόβου καὶ τρόμου ἐδέξασθε αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 16, 'Χαίρω ὅτι ἐν παντὶ, θαρρῶ ἐν ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 1, '¶Γνωρίζομεν δὲ ὑμῖν, ἀδελφοί, τὴν χάριν τοῦ  ̊Θεοῦ τὴν δεδομένην ἐν ταῖς ἐκκλησίαις τῆς Μακεδονίας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 2, 'ὅτι ἐν πολλῇ δοκιμῇ θλίψεως, ἡ περισσεία τῆς χαρᾶς αὐτῶν καὶ ἡ κατὰ βάθους πτωχεία αὐτῶν, ἐπερίσσευσεν εἰς τὸ πλοῦτος τῆς ἁπλότητος αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 3, 'Ὅτι κατὰ δύναμιν μαρτυρῶ, καὶ παρὰ δύναμιν, αὐθαίρετοι');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 4, 'μετὰ πολλῆς παρακλήσεως δεόμενοι ἡμῶν, τὴν χάριν καὶ τὴν κοινωνίαν τῆς διακονίας τῆς εἰς τοὺς ἁγίους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 5, 'Καὶ οὐ καθὼς ἠλπίσαμεν, ἀλλʼ ἑαυτοὺς ἔδωκαν, πρῶτον τῷ  ̊Κυρίῳ, καὶ ἡμῖν, διὰ θελήματος  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 6, 'Εἰς τὸ παρακαλέσαι ἡμᾶς Τίτον, ἵνα καθὼς προενήρξατο, οὕτως καὶ ἐπιτελέσῃ εἰς ὑμᾶς καὶ τὴν χάριν ταύτην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 7, 'Ἀλλʼ ὥσπερ ἐν παντὶ περισσεύετε, πίστει, καὶ λόγῳ, καὶ γνώσει, καὶ πάσῃ σπουδῇ, καὶ τῇ ἐξ ἡμῶν ἐν ὑμῖν ἀγάπῃ, ἵνα καὶ ἐν ταύτῃ τῇ χάριτι περισσεύητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 8, '¶Οὐ κατʼ ἐπιταγὴν λέγω, ἀλλὰ διὰ τῆς ἑτέρων σπουδῆς, καὶ τὸ τῆς ὑμετέρας ἀγάπης γνήσιον δοκιμάζων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 9, 'Γινώσκετε γὰρ τὴν χάριν τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, ὅτι διʼ ὑμᾶς ἐπτώχευσεν, πλούσιος ὤν, ἵνα ὑμεῖς τῇ ἐκείνου πτωχείᾳ πλουτήσητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 10, 'Καὶ γνώμην ἐν τούτῳ δίδωμι, τοῦτο γὰρ ὑμῖν συμφέρει, οἵτινες οὐ μόνον τὸ ποιῆσαι, ἀλλὰ καὶ τὸ θέλειν, προενήρξασθε ἀπὸ πέρυσι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 11, 'Νυνὶ δὲ καὶ τὸ ποιῆσαι ἐπιτελέσατε, ὅπως καθάπερ ἡ προθυμία τοῦ θέλειν, οὕτως καὶ τὸ ἐπιτελέσαι ἐκ τοῦ ἔχειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 12, 'Εἰ γὰρ ἡ προθυμία πρόκειται, καθὸ ἐὰν ἔχῃ εὐπρόσδεκτος, οὐ καθὸ οὐκ ἔχει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 13, 'Οὐ γὰρ ἵνα ἄλλοις ἄνεσις, ὑμῖν θλῖψις, ἀλλʼ ἐξ ἰσότητος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 14, 'Ἐν τῷ νῦν καιρῷ, τὸ ὑμῶν περίσσευμα εἰς τὸ ἐκείνων ὑστέρημα, ἵνα καὶ τὸ ἐκείνων περίσσευμα γένηται εἰς τὸ ὑμῶν ὑστέρημα, ὅπως γένηται ἰσότης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 15, 'Καθὼς γέγραπται, “Ὁ τὸ πολὺ, οὐκ ἐπλεόνασεν, καὶ ὁ τὸ ὀλίγον, οὐκ ἠλαττόνησεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 16, '¶Χάρις δὲ τῷ  ̊Θεῷ, τῷ διδόντι τὴν αὐτὴν σπουδὴν ὑπὲρ ὑμῶν ἐν τῇ καρδίᾳ Τίτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 17, 'Ὅτι τὴν μὲν παράκλησιν ἐδέξατο, σπουδαιότερος δὲ ὑπάρχων αὐθαίρετος, ἐξῆλθεν πρὸς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 18, 'Συνεπέμψαμεν δὲ μετʼ αὐτοῦ τὸν ἀδελφὸν, οὗ ὁ ἔπαινος ἐν τῷ εὐαγγελίῳ διὰ πασῶν τῶν ἐκκλησιῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 19, 'οὐ μόνον δὲ, ἀλλὰ καὶ χειροτονηθεὶς ὑπὸ τῶν ἐκκλησιῶν συνέκδημος ἡμῶν, ἐν τῇ χάριτι ταύτῃ τῇ διακονουμένῃ ὑφʼ ἡμῶν, πρὸς τὴν τοῦ  ̊Κυρίου δόξαν, καὶ προθυμίαν ἡμῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 20, 'στελλόμενοι τοῦτο, μή τις ἡμᾶς μωμήσηται, ἐν τῇ ἁδρότητι ταύτῃ τῇ διακονουμένῃ ὑφʼ ἡμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 21, 'προνοοῦμεν γὰρ καλὰ, οὐ μόνον ἐνώπιον  ̊Κυρίου, ἀλλὰ καὶ ἐνώπιον ἀνθρώπων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 22, 'Συνεπέμψαμεν δὲ αὐτοῖς τὸν ἀδελφὸν ἡμῶν, ὃν ἐδοκιμάσαμεν ἐν πολλοῖς, πολλάκις σπουδαῖον ὄντα, νυνὶ δὲ πολὺ σπουδαιότερον πεποιθήσει πολλῇ τῇ εἰς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 23, 'Εἴτε ὑπὲρ Τίτου, κοινωνὸς ἐμὸς καὶ εἰς ὑμᾶς συνεργός, εἴτε ἀδελφοὶ ἡμῶν, ἀπόστολοι ἐκκλησιῶν δόξα  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 24, 'Τὴν οὖν ἔνδειξιν τῆς ἀγάπης ὑμῶν, καὶ ἡμῶν καυχήσεως ὑπὲρ ὑμῶν, εἰς αὐτοὺς ἐνδεικνύμενοι εἰς πρόσωπον τῶν ἐκκλησιῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 1, '¶Περὶ μὲν γὰρ τῆς διακονίας τῆς εἰς τοὺς ἁγίους, περισσόν μοί ἐστιν τὸ γράφειν ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 2, 'Οἶδα γὰρ τὴν προθυμίαν ὑμῶν, ἣν ὑπὲρ ὑμῶν καυχῶμαι Μακεδόσιν, ὅτι Ἀχαΐα παρεσκεύασται ἀπὸ πέρυσι, καὶ τὸ ὑμῶν ζῆλος ἠρέθισε τοὺς πλείονας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 3, 'Ἔπεμψα δὲ τοὺς ἀδελφούς, ἵνα μὴ τὸ καύχημα ἡμῶν, τὸ ὑπὲρ ὑμῶν, κενωθῇ ἐν τῷ μέρει τούτῳ, ἵνα καθὼς ἔλεγον, παρεσκευασμένοι ἦτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 4, 'Μή πως ἐὰν ἔλθωσιν σὺν ἐμοὶ Μακεδόνες, καὶ εὕρωσιν ὑμᾶς ἀπαρασκευάστους, καταισχυνθῶμεν ἡμεῖς, ἵνα μὴ λέγωμεν ὑμεῖς, ἐν τῇ ὑποστάσει ταύτῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 5, 'Ἀναγκαῖον οὖν ἡγησάμην παρακαλέσαι τοὺς ἀδελφοὺς, ἵνα προέλθωσιν εἰς ὑμᾶς καὶ προκαταρτίσωσιν τὴν προεπηγγελμένην εὐλογίαν ὑμῶν, ταύτην ἑτοίμην εἶναι οὕτως ὡς εὐλογίαν, καὶ μὴ ὡς πλεονεξίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 6, '¶Τοῦτο δέ: ὁ σπείρων φειδομένως, φειδομένως καὶ θερίσει, καὶ ὁ σπείρων ἐπʼ εὐλογίαις, ἐπʼ εὐλογίαις καὶ θερίσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 7, 'Ἕκαστος καθὼς προῄρηται τῇ καρδίᾳ, μὴ ἐκ λύπης ἢ ἐξ ἀνάγκης, ἱλαρὸν γὰρ δότην ἀγαπᾷ ὁ  ̊Θεός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 8, 'Δυνατεῖ δὲ ὁ  ̊Θεὸς πᾶσαν χάριν περισσεῦσαι εἰς ὑμᾶς, ἵνα ἐν παντὶ πάντοτε πᾶσαν αὐτάρκειαν ἔχοντες, περισσεύητε εἰς πᾶν ἔργον ἀγαθόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 9, 'Καθὼς γέγραπται, “Ἐσκόρπισεν, ἔδωκεν τοῖς πένησιν, ἡ δικαιοσύνη αὐτοῦ μένει εἰς τὸν αἰῶνα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 10, 'Ὁ δὲ ἐπιχορηγῶν σπόρον τῷ σπείροντι, καὶ ἄρτον εἰς βρῶσιν, χορηγήσει καὶ πληθυνεῖ τὸν σπόρον ὑμῶν, καὶ αὐξήσει τὰ γενήματα τῆς δικαιοσύνης ὑμῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 11, 'ἐν παντὶ πλουτιζόμενοι εἰς πᾶσαν ἁπλότητα, ἥτις κατεργάζεται διʼ ἡμῶν, εὐχαριστίαν τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 12, 'Ὅτι ἡ διακονία τῆς λειτουργίας ταύτης, οὐ μόνον ἐστὶν προσαναπληροῦσα τὰ ὑστερήματα τῶν ἁγίων, ἀλλὰ καὶ περισσεύουσα διὰ πολλῶν εὐχαριστιῶν τῷ  ̊Θεῷ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 13, 'διὰ τῆς δοκιμῆς τῆς διακονίας ταύτης, δοξάζοντες τὸν  ̊Θεὸν ἐπὶ τῇ ὑποταγῇ τῆς ὁμολογίας ὑμῶν εἰς τὸ εὐαγγέλιον τοῦ  ̊Χριστοῦ, καὶ ἁπλότητι τῆς κοινωνίας εἰς αὐτοὺς καὶ εἰς πάντας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 14, 'καὶ αὐτῶν δεήσει ὑπὲρ ὑμῶν, ἐπιποθούντων ὑμᾶς, διὰ τὴν ὑπερβάλλουσαν χάριν τοῦ  ̊Θεοῦ ἐφʼ ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 15, 'Χάρις τῷ  ̊Θεῷ ἐπὶ τῇ ἀνεκδιηγήτῳ αὐτοῦ δωρεᾷ!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 1, '¶Αὐτὸς δὲ ἐγὼ, Παῦλος, παρακαλῶ ὑμᾶς διὰ τῆς πραΰτητος καὶ ἐπιεικείας τοῦ  ̊Χριστοῦ, ὃς κατὰ πρόσωπον μὲν ταπεινὸς ἐν ὑμῖν, ἀπὼν δὲ θαρρῶ εἰς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 2, 'Δέομαι δὲ τὸ μὴ, παρὼν θαρρῆσαι τῇ πεποιθήσει ᾗ λογίζομαι, τολμῆσαι ἐπί τινας τοὺς λογιζομένους ἡμᾶς, ὡς κατὰ σάρκα περιπατοῦντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 3, 'Ἐν σαρκὶ γὰρ περιπατοῦντες, οὐ κατὰ σάρκα στρατευόμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 4, 'Τὰ γὰρ ὅπλα τῆς στρατείας ἡμῶν οὐ σαρκικὰ, ἀλλὰ δυνατὰ τῷ  ̊Θεῷ πρὸς καθαίρεσιν ὀχυρωμάτων, λογισμοὺς καθαιροῦντες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 5, 'καὶ πᾶν ὕψωμα ἐπαιρόμενον κατὰ τῆς γνώσεως τοῦ  ̊Θεοῦ, καὶ αἰχμαλωτίζοντες πᾶν νόημα εἰς τὴν ὑπακοὴν τοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 6, 'καὶ ἐν ἑτοίμῳ ἔχοντες ἐκδικῆσαι πᾶσαν παρακοήν, ὅταν πληρωθῇ ὑμῶν ἡ ὑπακοή.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 7, '¶Τὰ κατὰ πρόσωπον βλέπετε. Εἴ τις πέποιθεν ἑαυτῷ  ̊Χριστοῦ εἶναι, τοῦτο λογιζέσθω πάλιν ἐφʼ ἑαυτοῦ, ὅτι καθὼς αὐτὸς  ̊Χριστοῦ, οὕτως καὶ ἡμεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 8, 'Ἐάν τε γὰρ περισσότερόν τι καυχήσωμαι περὶ τῆς ἐξουσίας ἡμῶν, ἧς ἔδωκεν ὁ  ̊Κύριος εἰς οἰκοδομὴν καὶ οὐκ εἰς καθαίρεσιν ὑμῶν, οὐκ αἰσχυνθήσομαι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 9, 'ἵνα μὴ δόξω ὡς ἂν ἐκφοβεῖν ὑμᾶς διὰ τῶν ἐπιστολῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 10, 'Ὅτι, “Αἱ ἐπιστολαὶ μέν”, φησίν, “βαρεῖαι καὶ ἰσχυραί, ἡ δὲ παρουσία τοῦ σώματος ἀσθενὴς, καὶ ὁ λόγος ἐξουθενημένος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 11, 'Τοῦτο λογιζέσθω ὁ τοιοῦτος, ὅτι οἷοί ἐσμεν τῷ λόγῳ διʼ ἐπιστολῶν ἀπόντες, τοιοῦτοι καὶ παρόντες τῷ ἔργῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 12, '¶Οὐ γὰρ τολμῶμεν ἐγκρῖναι ἢ συγκρῖναι ἑαυτούς, τισιν τῶν ἑαυτοὺς συνιστανόντων· ἀλλὰ αὐτοὶ ἐν ἑαυτοῖς, ἑαυτοὺς μετροῦντες καὶ συγκρίνοντες ἑαυτοὺς ἑαυτοῖς, οὐ συνιᾶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 13, 'Ἡμεῖς δὲ οὐκ εἰς τὰ ἄμετρα καυχησόμεθα, ἀλλὰ κατὰ τὸ μέτρον τοῦ κανόνος, οὗ ἐμέρισεν ἡμῖν ὁ  ̊Θεὸς μέτρου, ἐφικέσθαι ἄχρι καὶ ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 14, 'Οὐ γὰρ ὡς μὴ ἐφικνούμενοι εἰς ὑμᾶς, ὑπερεκτείνομεν ἑαυτούς, ἄχρι γὰρ καὶ ὑμῶν ἐφθάσαμεν ἐν τῷ εὐαγγελίῳ τοῦ  ̊Χριστοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 15, 'οὐκ εἰς τὰ ἄμετρα καυχώμενοι ἐν ἀλλοτρίοις κόποις, ἐλπίδα δὲ ἔχοντες, αὐξανομένης τῆς πίστεως ὑμῶν, ἐν ὑμῖν μεγαλυνθῆναι κατὰ τὸν κανόνα ἡμῶν εἰς περισσείαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 16, 'εἰς τὰ ὑπερέκεινα ὑμῶν εὐαγγελίσασθαι, οὐκ ἐν ἀλλοτρίῳ κανόνι εἰς τὰ ἕτοιμα καυχήσασθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 17, 'Ὁ δὲ καυχώμενος, ἐν  ̊Κυρίῳ καυχάσθω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 18, 'Οὐ γὰρ ὁ ἑαυτὸν συνιστάνων, ἐκεῖνός ἐστιν δόκιμος, ἀλλὰ ὃν ὁ  ̊Κύριος συνίστησιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 1, '¶Ὄφελον ἀνείχεσθέ μου μικρόν τι ἀφροσύνης, ἀλλὰ καὶ ἀνέχεσθέ μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 2, 'Ζηλῶ γὰρ ὑμᾶς  ̊Θεοῦ ζήλῳ, ἡρμοσάμην γὰρ ὑμᾶς ἑνὶ ἀνδρὶ, παρθένον ἁγνὴν παραστῆσαι τῷ  ̊Χριστῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 3, 'Φοβοῦμαι δὲ, μή πως ὡς ὁ ὄφις ἐξηπάτησεν Εὕαν ἐν τῇ πανουργίᾳ αὐτοῦ, φθαρῇ τὰ νοήματα ὑμῶν ἀπὸ τῆς ἁπλότητος καὶ τῆς ἁγνότητος τῆς εἰς τὸν  ̊Χριστόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 4, 'Εἰ μὲν γὰρ ὁ ἐρχόμενος ἄλλον  ̊Ἰησοῦν κηρύσσει ὃν οὐκ ἐκηρύξαμεν, ἢ πνεῦμα ἕτερον λαμβάνετε ὃ οὐκ ἐλάβετε, ἢ εὐαγγέλιον ἕτερον ὃ οὐκ ἐδέξασθε, καλῶς ἀνέχεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 5, 'Λογίζομαι γὰρ μηδὲν ὑστερηκέναι τῶν ὑπερλίαν ἀποστόλων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 6, 'Εἰ δὲ καὶ ἰδιώτης τῷ λόγῳ, ἀλλʼ οὐ τῇ γνώσει, ἀλλʼ ἐν παντὶ φανερώσαντες ἐν πᾶσιν εἰς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 7, '¶Ἢ ἁμαρτίαν ἐποίησα ἐμαυτὸν ταπεινῶν, ἵνα ὑμεῖς ὑψωθῆτε, ὅτι δωρεὰν τὸ τοῦ  ̊Θεοῦ εὐαγγέλιον εὐηγγελισάμην ὑμῖν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 8, 'Ἄλλας ἐκκλησίας ἐσύλησα, λαβὼν ὀψώνιον πρὸς τὴν ὑμῶν διακονίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 9, 'καὶ παρὼν πρὸς ὑμᾶς καὶ ὑστερηθεὶς, οὐ κατενάρκησα οὐθενός· τὸ γὰρ ὑστέρημά μου προσανεπλήρωσαν οἱ ἀδελφοὶ ἐλθόντες ἀπὸ Μακεδονίας, καὶ ἐν παντὶ ἀβαρῆ ἐμαυτὸν ὑμῖν ἐτήρησα καὶ τηρήσω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 10, 'Ἔστιν ἀλήθεια  ̊Χριστοῦ ἐν ἐμοὶ, ὅτι ἡ καύχησις αὕτη οὐ φραγήσεται εἰς ἐμὲ ἐν τοῖς κλίμασι τῆς Ἀχαΐας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 11, 'Διὰ τί; Ὅτι οὐκ ἀγαπῶ ὑμᾶς; Ὁ  ̊Θεὸς οἶδεν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 12, '¶Ὃ δὲ ποιῶ, καὶ ποιήσω, ἵνα ἐκκόψω τὴν ἀφορμὴν τῶν θελόντων ἀφορμήν, ἵνα ἐν ᾧ καυχῶνται, εὑρεθῶσιν καθὼς καὶ ἡμεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 13, 'Οἱ γὰρ τοιοῦτοι ψευδαπόστολοι, ἐργάται δόλιοι, μετασχηματιζόμενοι εἰς ἀποστόλους  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 14, 'Καὶ οὐ θαῦμα, αὐτὸς γὰρ ὁ Σατανᾶς μετασχηματίζεται εἰς ἄγγελον φωτός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 15, 'Οὐ μέγα οὖν, εἰ καὶ οἱ διάκονοι αὐτοῦ μετασχηματίζονται ὡς διάκονοι δικαιοσύνης, ὧν τὸ τέλος ἔσται κατὰ τὰ ἔργα αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 16, '¶Πάλιν λέγω, μή τίς με δόξῃ ἄφρονα εἶναι· εἰ δὲ μή γε κἂν ὡς ἄφρονα δέξασθέ με, ἵνα κἀγὼ μικρόν τι καυχήσωμαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 17, 'Ὃ λαλῶ, οὐ κατὰ  ̊Κύριον λαλῶ, ἀλλʼ ὡς ἐν ἀφροσύνῃ, ἐν ταύτῃ τῇ ὑποστάσει τῆς καυχήσεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 18, 'Ἐπεὶ πολλοὶ καυχῶνται κατὰ σάρκα, κἀγὼ καυχήσομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 19, 'Ἡδέως γὰρ ἀνέχεσθε τῶν ἀφρόνων, φρόνιμοι ὄντες!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 20, 'Ἀνέχεσθε γὰρ, εἴ τις ὑμᾶς καταδουλοῖ, εἴ τις κατεσθίει, εἴ τις λαμβάνει, εἴ τις ἐπαίρεται, εἴ τις εἰς πρόσωπον ὑμᾶς δέρει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 21, 'Κατὰ ἀτιμίαν λέγω ὡς ὅτι ἡμεῖς ἠσθενήκαμεν! Ἐν ᾧ δʼ ἄν τις τολμᾷ (ἐν ἀφροσύνῃ λέγω), τολμῶ κἀγώ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 22, 'Ἑβραῖοί εἰσιν; Κἀγώ. Ἰσραηλῖταί εἰσιν; Κἀγώ. Σπέρμα Ἀβραάμ εἰσιν; Κἀγώ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 23, 'Διάκονοι  ̊Χριστοῦ εἰσιν; (Παραφρονῶν λαλῶ), ὑπὲρ ἐγώ: ἐν κόποις περισσοτέρως, ἐν φυλακαῖς περισσοτέρως, ἐν πληγαῖς ὑπερβαλλόντως, ἐν θανάτοις πολλάκις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 24, 'Ὑπὸ Ἰουδαίων πεντάκις τεσσεράκοντα παρὰ μίαν ἔλαβον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 25, 'τρὶς ἐραβδίσθην, ἅπαξ ἐλιθάσθην, τρὶς ἐναυάγησα, νυχθήμερον ἐν τῷ βυθῷ πεποίηκα·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 26, 'ὁδοιπορίαις πολλάκις, κινδύνοις ποταμῶν, κινδύνοις λῃστῶν, κινδύνοις ἐκ γένους, κινδύνοις ἐξ ἐθνῶν, κινδύνοις ἐν πόλει, κινδύνοις ἐν ἐρημίᾳ, κινδύνοις ἐν θαλάσσῃ, κινδύνοις ἐν ψευδαδέλφοις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 27, 'κόπῳ καὶ μόχθῳ, ἐν ἀγρυπνίαις πολλάκις, ἐν λιμῷ καὶ δίψει, ἐν νηστείαις πολλάκις, ἐν ψύχει καὶ γυμνότητι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 28, 'Χωρὶς τῶν παρεκτὸς, ἡ ἐπίστασίς μοι ἡ καθʼ ἡμέραν, ἡ μέριμνα πασῶν τῶν ἐκκλησιῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 29, 'Τίς ἀσθενεῖ, καὶ οὐκ ἀσθενῶ; Τίς σκανδαλίζεται, καὶ οὐκ ἐγὼ πυροῦμαι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 30, '¶Εἰ καυχᾶσθαι δεῖ, τὰ τῆς ἀσθενείας μου καυχήσομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 31, 'Ὁ  ̊Θεὸς καὶ Πατὴρ τοῦ  ̊Κυρίου  ̊Ἰησοῦ οἶδεν, ὁ ὢν εὐλογητὸς εἰς τοὺς αἰῶνας, ὅτι οὐ ψεύδομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 32, 'Ἐν Δαμασκῷ ὁ ἐθνάρχης Ἁρέτα τοῦ βασιλέως ἐφρούρει τὴν πόλιν Δαμασκηνῶν πιάσαι με, θέλων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 33, 'καὶ διὰ θυρίδος ἐν σαργάνῃ, ἐχαλάσθην διὰ τοῦ τείχους καὶ ἐξέφυγον τὰς χεῖρας αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 1, '¶Καυχᾶσθαι δεῖ, οὐ συμφέρον μέν, ἐλεύσομαι δὲ εἰς ὀπτασίας καὶ ἀποκαλύψεις  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 2, 'Οἶδα ἄνθρωπον ἐν  ̊Χριστῷ πρὸ ἐτῶν δεκατεσσάρων (εἴτε ἐν σώματι οὐκ οἶδα, εἴτε ἐκτὸς τοῦ σώματος οὐκ οἶδα, ὁ  ̊Θεὸς οἶδεν), ἁρπαγέντα τὸν τοιοῦτον ἕως τρίτου οὐρανοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 3, 'Καὶ οἶδα τὸν τοιοῦτον ἄνθρωπον (εἴτε ἐν σώματι εἴτε χωρὶς τοῦ σώματος οὐκ οἶδα, ὁ  ̊Θεὸς οἶδεν),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 4, 'ὅτι ἡρπάγη εἰς τὸν Παράδεισον, καὶ ἤκουσεν ἄρρητα ῥήματα, ἃ οὐκ ἐξὸν ἀνθρώπῳ λαλῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 5, 'Ὑπὲρ τοῦ τοιούτου, καυχήσομαι, ὑπὲρ δὲ ἐμαυτοῦ, οὐ καυχήσομαι, εἰ μὴ ἐν ταῖς ἀσθενείαις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 6, 'Ἐὰν γὰρ θελήσω καυχήσασθαι, οὐκ ἔσομαι ἄφρων, ἀλήθειαν γὰρ ἐρῶ· φείδομαι δέ, μή τις εἰς ἐμὲ λογίσηται ὑπὲρ ὃ βλέπει με, ἢ ἀκούει ἐξ ἐμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 7, 'Καὶ τῇ ὑπερβολῇ τῶν ἀποκαλύψεων, διὸ ἵνα μὴ ὑπεραίρωμαι, ἐδόθη μοι σκόλοψ τῇ σαρκί, ἄγγελος Σατανᾶ, ἵνα με κολαφίζῃ, ἵνα μὴ ὑπεραίρωμαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 8, 'Ὑπὲρ τούτου τρὶς τὸν  ̊Κύριον παρεκάλεσα ἵνα ἀποστῇ ἀπʼ ἐμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 9, 'Καὶ εἴρηκέν μοι, “Ἀρκεῖ σοι ἡ χάρις μου, ἡ γὰρ δύναμις ἐν ἀσθενείᾳ τελεῖται.” Ἥδιστα οὖν μᾶλλον καυχήσομαι ἐν ταῖς ἀσθενείαις μου, ἵνα ἐπισκηνώσῃ ἐπʼ ἐμὲ ἡ δύναμις τοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 10, 'Διὸ εὐδοκῶ ἐν ἀσθενείαις, ἐν ὕβρεσιν, ἐν ἀνάγκαις, ἐν διωγμοῖς, καὶ στενοχωρίαις, ὑπὲρ  ̊Χριστοῦ· ὅταν γὰρ ἀσθενῶ, τότε δυνατός εἰμι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 11, '¶Γέγονα ἄφρων· ὑμεῖς με ἠναγκάσατε. Ἐγὼ γὰρ ὤφειλον ὑφʼ ὑμῶν συνίστασθαι. Οὐδὲν γὰρ ὑστέρησα τῶν ὑπερλίαν ἀποστόλων, εἰ καὶ οὐδέν εἰμι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 12, 'Τὰ μὲν σημεῖα τοῦ ἀποστόλου κατειργάσθη ἐν ὑμῖν ἐν πάσῃ ὑπομονῇ– σημείοις τε, καὶ τέρασιν, καὶ δυνάμεσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 13, 'Τί γάρ ἐστιν ὃ ἡσσώθητε ὑπὲρ τὰς λοιπὰς ἐκκλησίας, εἰ μὴ ὅτι αὐτὸς ἐγὼ οὐ κατενάρκησα ὑμῶν; Χαρίσασθέ μοι τὴν ἀδικίαν ταύτην!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 14, '¶Ἰδοὺ, τρίτον τοῦτο ἑτοίμως ἔχω ἐλθεῖν πρὸς ὑμᾶς, καὶ οὐ καταναρκήσω· οὐ γὰρ ζητῶ τὰ ὑμῶν, ἀλλὰ ὑμᾶς, οὐ γὰρ ὀφείλει τὰ τέκνα τοῖς γονεῦσιν θησαυρίζειν, ἀλλὰ οἱ γονεῖς τοῖς τέκνοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 15, 'Ἐγὼ δὲ ἥδιστα δαπανήσω καὶ ἐκδαπανηθήσομαι ὑπὲρ τῶν ψυχῶν ὑμῶν. Εἰ περισσοτέρως ὑμᾶς ἀγαπῶν, ἧσσον ἀγαπῶμαι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 16, 'Ἔστω δέ, ἐγὼ οὐ κατεβάρησα ὑμᾶς· ἀλλὰ ὑπάρχων πανοῦργος δόλῳ, ὑμᾶς ἔλαβον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 17, 'Μή τινα ὧν ἀπέσταλκα πρὸς ὑμᾶς, διʼ αὐτοῦ ἐπλεονέκτησα ὑμᾶς;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 18, 'Παρεκάλεσα Τίτον καὶ συναπέστειλα τὸν ἀδελφόν. Μήτι ἐπλεονέκτησεν ὑμᾶς Τίτος; Οὐ τῷ αὐτῷ πνεύματι περιεπατήσαμεν οὐ τοῖς αὐτοῖς ἴχνεσιν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 19, '¶Πάλαι δοκεῖτε ὅτι ὑμῖν ἀπολογούμεθα; Κατέναντι  ̊Θεοῦ ἐν  ̊Χριστῷ λαλοῦμεν. Τὰ δὲ πάντα, ἀγαπητοί, ὑπὲρ τῆς ὑμῶν οἰκοδομῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 20, 'Φοβοῦμαι γὰρ, μή πως ἐλθὼν οὐχ οἵους θέλω, εὕρω ὑμᾶς, κἀγὼ εὑρεθῶ ὑμῖν οἷον οὐ θέλετε, μή πως ἔρις, ζῆλος, θυμοί, ἐριθεῖαι, καταλαλιαί, ψιθυρισμοί, φυσιώσεις, ἀκαταστασίαι·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 21, 'μὴ πάλιν ἐλθόντος μου, ταπεινώσει με ὁ  ̊Θεός μου πρὸς ὑμᾶς, καὶ πενθήσω πολλοὺς τῶν προημαρτηκότων, καὶ μὴ μετανοησάντων ἐπὶ τῇ ἀκαθαρσίᾳ, καὶ πορνείᾳ, καὶ ἀσελγείᾳ, ᾗ ἔπραξαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 1, '¶Τρίτον τοῦτο ἔρχομαι πρὸς ὑμᾶς. “Ἐπὶ στόματος δύο μαρτύρων καὶ τριῶν σταθήσεται πᾶν ῥῆμα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 2, 'Προείρηκα καὶ προλέγω, ὡς παρὼν τὸ δεύτερον, καὶ ἀπὼν νῦν τοῖς προημαρτηκόσιν, καὶ τοῖς λοιποῖς πᾶσιν, ὅτι ἐὰν ἔλθω εἰς τὸ πάλιν, οὐ φείσομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 3, 'Ἐπεὶ δοκιμὴν ζητεῖτε τοῦ ἐν ἐμοὶ λαλοῦντος  ̊Χριστοῦ, ὃς εἰς ὑμᾶς οὐκ ἀσθενεῖ, ἀλλὰ δυνατεῖ ἐν ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 4, 'Καὶ γὰρ ἐσταυρώθη ἐξ ἀσθενείας, ἀλλὰ ζῇ ἐκ δυνάμεως  ̊Θεοῦ. Καὶ γὰρ ἡμεῖς ἀσθενοῦμεν ἐν αὐτῷ, ἀλλὰ ζήσομεν σὺν αὐτῷ ἐκ δυνάμεως  ̊Θεοῦ εἰς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 5, '¶Ἑαυτοὺς πειράζετε εἰ ἐστὲ ἐν τῇ πίστει, ἑαυτοὺς δοκιμάζετε. Ἢ οὐκ ἐπιγινώσκετε ἑαυτοὺς, ὅτι  ̊Χριστὸς  ̊Ἰησοῦς ἐν ὑμῖν, εἰ μήτι ἀδόκιμοί ἐστε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 6, 'Ἐλπίζω δὲ ὅτι γνώσεσθε ὅτι ἡμεῖς οὐκ ἐσμὲν ἀδόκιμοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 7, 'Εὐχόμεθα δὲ πρὸς τὸν  ̊Θεὸν μὴ ποιῆσαι ὑμᾶς κακὸν μηδέν, οὐχ ἵνα ἡμεῖς δόκιμοι φανῶμεν, ἀλλʼ ἵνα ὑμεῖς τὸ καλὸν ποιῆτε, ἡμεῖς δὲ ὡς ἀδόκιμοι ὦμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 8, 'Οὐ γὰρ δυνάμεθά τι κατὰ τῆς ἀληθείας, ἀλλʼ ὑπὲρ τῆς ἀληθείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 9, 'Χαίρομεν γὰρ ὅταν ἡμεῖς ἀσθενῶμεν, ὑμεῖς δὲ δυνατοὶ ἦτε. Τοῦτο καὶ εὐχόμεθα, τὴν ὑμῶν κατάρτισιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 10, 'Διὰ τοῦτο ταῦτα ἀπὼν γράφω, ἵνα παρὼν μὴ ἀποτόμως χρήσωμαι, κατὰ τὴν ἐξουσίαν ἣν ὁ  ̊Κύριος ἔδωκέν μοι εἰς οἰκοδομὴν καὶ οὐκ εἰς καθαίρεσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 11, '¶Λοιπόν ἀδελφοί, χαίρετε, καταρτίζεσθε, παρακαλεῖσθε, τὸ αὐτὸ φρονεῖτε, εἰρηνεύετε, καὶ ὁ  ̊Θεὸς τῆς ἀγάπης καὶ εἰρήνης ἔσται μεθʼ ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 12, 'Ἀσπάσασθε ἀλλήλους ἐν ἁγίῳ φιλήματι. Ἀσπάζονται ὑμᾶς οἱ ἅγιοι πάντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 13, 'Ἡ χάρις τοῦ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ, καὶ ἡ ἀγάπη τοῦ  ̊Θεοῦ, καὶ ἡ κοινωνία τοῦ Ἁγίου  ̊Πνεύματος, μετὰ πάντων ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 14, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, '¶Παῦλος, ἀπόστολος (οὐκ ἀπʼ ἀνθρώπων, οὐδὲ διʼ ἀνθρώπου, ἀλλὰ διὰ  ̊Ἰησοῦ  ̊Χριστοῦ, καὶ  ̊Θεοῦ Πατρὸς τοῦ ἐγείραντος αὐτὸν ἐκ νεκρῶν),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'καὶ οἱ σὺν ἐμοὶ πάντες ἀδελφοί, ταῖς ἐκκλησίαις τῆς Γαλατίας:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'χάρις ὑμῖν καὶ εἰρήνη ἀπὸ  ̊Θεοῦ Πατρὸς καὶ  ̊Κυρίου ἡμῶν  ̊Ἰησοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'τοῦ δόντος ἑαυτὸν περὶ τῶν ἁμαρτιῶν ἡμῶν, ὅπως ἐξέληται ἡμᾶς ἐκ τοῦ αἰῶνος τοῦ ἐνεστῶτος πονηροῦ, κατὰ τὸ θέλημα τοῦ  ̊Θεοῦ καὶ Πατρὸς ἡμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'ᾧ ἡ δόξα εἰς τοὺς αἰῶνας τῶν αἰώνων. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, '¶Θαυμάζω ὅτι οὕτως ταχέως, μετατίθεσθε ἀπὸ τοῦ καλέσαντος ὑμᾶς ἐν χάριτι  ̊Χριστοῦ, εἰς ἕτερον εὐαγγέλιον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'ὃ οὐκ ἔστιν ἄλλο, εἰ μή τινές εἰσιν οἱ ταράσσοντες ὑμᾶς, καὶ θέλοντες μεταστρέψαι τὸ εὐαγγέλιον τοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Ἀλλὰ καὶ ἐὰν ἡμεῖς ἢ ἄγγελος ἐξ οὐρανοῦ ὑμῖν εὐαγγελίζηται παρʼ ὃ εὐηγγελισάμεθα ὑμῖν, ἀνάθεμα ἔστω!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Ὡς προειρήκαμεν, καὶ ἄρτι πάλιν λέγω, εἴ τις ὑμᾶς εὐαγγελίζεται παρʼ ὃ παρελάβετε, ἀνάθεμα ἔστω!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, '¶Ἄρτι γὰρ ἀνθρώπους πείθω ἢ τὸν  ̊Θεόν; Ἢ ζητῶ ἀνθρώποις ἀρέσκειν; Εἰ ἔτι ἀνθρώποις ἤρεσκον,  ̊Χριστοῦ δοῦλος οὐκ ἂν ἤμην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, '¶Γνωρίζω γὰρ ὑμῖν, ἀδελφοί, τὸ εὐαγγέλιον τὸ εὐαγγελισθὲν ὑπʼ ἐμοῦ, ὅτι οὐκ ἔστιν κατὰ ἄνθρωπον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Οὐδὲ γὰρ ἐγὼ παρὰ ἀνθρώπου παρέλαβον αὐτό, οὔτε ἐδιδάχθην, ἀλλὰ διʼ ἀποκαλύψεως  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, '¶Ἠκούσατε γὰρ τὴν ἐμὴν ἀναστροφήν ποτε ἐν τῷ Ἰουδαϊσμῷ, ὅτι καθʼ ὑπερβολὴν ἐδίωκον τὴν ἐκκλησίαν τοῦ  ̊Θεοῦ, καὶ ἐπόρθουν αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Καὶ προέκοπτον ἐν τῷ Ἰουδαϊσμῷ ὑπὲρ πολλοὺς συνηλικιώτας ἐν τῷ γένει μου, περισσοτέρως ζηλωτὴς ὑπάρχων τῶν πατρικῶν μου παραδόσεων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Ὅτε δὲ εὐδόκησεν ὁ, ἀφορίσας με ἐκ κοιλίας μητρός μου, καὶ καλέσας διὰ τῆς χάριτος αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'ἀποκαλύψαι τὸν Υἱὸν αὐτοῦ ἐν ἐμοὶ, ἵνα εὐαγγελίζωμαι αὐτὸν ἐν τοῖς ἔθνεσιν, εὐθέως οὐ προσανεθέμην σαρκὶ καὶ αἵματι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'οὐδὲ ἀνῆλθον εἰς Ἱεροσόλυμα πρὸς τοὺς πρὸ ἐμοῦ ἀποστόλους, ἀλλὰ ἀπῆλθον εἰς Ἀραβίαν, καὶ πάλιν ὑπέστρεψα εἰς Δαμασκόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, '¶Ἔπειτα μετὰ ἔτη τρία, ἀνῆλθον εἰς Ἱεροσόλυμα ἱστορῆσαι Κηφᾶν, καὶ ἐπέμεινα πρὸς αὐτὸν ἡμέρας δεκαπέντε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Ἕτερον δὲ τῶν ἀποστόλων οὐκ εἶδον, εἰ μὴ Ἰάκωβον, τὸν ἀδελφὸν τοῦ  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Ἃ δὲ γράφω ὑμῖν, ἰδοὺ, ἐνώπιον τοῦ  ̊Θεοῦ, ὅτι οὐ ψεύδομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 21, 'Ἔπειτα ἦλθον εἰς τὰ κλίματα τῆς Συρίας καὶ τῆς Κιλικίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 22, 'Ἤμην δὲ ἀγνοούμενος τῷ προσώπῳ ταῖς ἐκκλησίαις τῆς Ἰουδαίας, ταῖς ἐν  ̊Χριστῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 23, 'μόνον δὲ ἀκούοντες ἦσαν, ὅτι “Ὁ διώκων ἡμᾶς ποτε, νῦν εὐαγγελίζεται τὴν πίστιν, ἥν ποτε ἐπόρθει.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 24, 'Καὶ ἐδόξαζον ἐν ἐμοὶ τὸν  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, '¶Ἔπειτα διὰ δεκατεσσάρων ἐτῶν, πάλιν ἀνέβην εἰς Ἱεροσόλυμα μετὰ Βαρναβᾶ, συμπαραλαβὼν καὶ Τίτον·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'ἀνέβην δὲ κατὰ ἀποκάλυψιν, καὶ ἀνεθέμην αὐτοῖς τὸ εὐαγγέλιον ὃ κηρύσσω ἐν τοῖς ἔθνεσιν, κατʼ ἰδίαν δὲ τοῖς δοκοῦσιν, μή πως εἰς κενὸν τρέχω ἢ ἔδραμον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Ἀλλʼ οὐδὲ Τίτος ὁ σὺν ἐμοί, Ἕλλην ὤν, ἠναγκάσθη περιτμηθῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Διὰ δὲ τοὺς παρεισάκτους ψευδαδέλφους, οἵτινες παρεισῆλθον κατασκοπῆσαι τὴν ἐλευθερίαν ἡμῶν, ἣν ἔχομεν ἐν  ̊Χριστῷ  ̊Ἰησοῦ, ἵνα ἡμᾶς καταδουλώσουσιν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'οἷς οὐδὲ πρὸς ὥραν εἴξαμεν τῇ ὑποταγῇ, ἵνα ἡ ἀλήθεια τοῦ εὐαγγελίου διαμείνῃ πρὸς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Ἀπὸ δὲ τῶν δοκούντων εἶναί τι (ὁποῖοί ποτε ἦσαν, οὐδέν μοι διαφέρει, πρόσωπον ὁ  ̊Θεὸς ἀνθρώπου οὐ λαμβάνει), ἐμοὶ γὰρ οἱ δοκοῦντες οὐδὲν προσανέθεντο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Ἀλλὰ τοὐναντίον ἰδόντες ὅτι πεπίστευμαι τὸ εὐαγγέλιον τῆς ἀκροβυστίας, καθὼς Πέτρος τῆς περιτομῆς');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, '(ὁ γὰρ ἐνεργήσας Πέτρῳ εἰς ἀποστολὴν τῆς περιτομῆς, ἐνήργησεν καὶ ἐμοὶ εἰς τὰ ἔθνη),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'καὶ γνόντες τὴν χάριν τὴν δοθεῖσάν μοι, Ἰάκωβος καὶ Κηφᾶς, καὶ Ἰωάννης, οἱ δοκοῦντες στῦλοι εἶναι, δεξιὰς ἔδωκαν ἐμοὶ καὶ Βαρναβᾷ κοινωνίας, ἵνα ἡμεῖς εἰς τὰ ἔθνη, αὐτοὶ δὲ εἰς τὴν περιτομήν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'μόνον τῶν πτωχῶν ἵνα μνημονεύωμεν, ὃ καὶ ἐσπούδασα αὐτὸ τοῦτο ποιῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, '¶Ὅτε δὲ ἦλθεν Κηφᾶς εἰς Ἀντιόχειαν, κατὰ πρόσωπον αὐτῷ ἀντέστην, ὅτι κατεγνωσμένος ἦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Πρὸ τοῦ γὰρ ἐλθεῖν τινας ἀπὸ Ἰακώβου, μετὰ τῶν ἐθνῶν συνήσθιεν· ὅτε δὲ ἦλθον, ὑπέστελλεν καὶ ἀφώριζεν ἑαυτόν, φοβούμενος τοὺς ἐκ περιτομῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Καὶ συνυπεκρίθησαν αὐτῷ καὶ οἱ λοιποὶ Ἰουδαῖοι, ὥστε καὶ Βαρναβᾶς συναπήχθη αὐτῶν τῇ ὑποκρίσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Ἀλλʼ ὅτε εἶδον ὅτι οὐκ ὀρθοποδοῦσιν πρὸς τὴν ἀλήθειαν τοῦ εὐαγγελίου, εἶπον τῷ Κηφᾷ ἔμπροσθεν πάντων, “Εἰ σὺ Ἰουδαῖος, ὑπάρχων ἐθνικῶς καὶ οὐκ Ἰουδαϊκῶς ζῇς, πῶς τὰ ἔθνη ἀναγκάζεις Ἰουδαΐζειν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, '¶Ἡμεῖς φύσει Ἰουδαῖοι καὶ οὐκ ἐξ ἐθνῶν ἁμαρτωλοί,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'εἰδότες δὲ ὅτι οὐ δικαιοῦται ἄνθρωπος ἐξ ἔργων νόμου, ἐὰν μὴ διὰ πίστεως  ̊Ἰησοῦ  ̊Χριστοῦ, καὶ ἡμεῖς εἰς  ̊Χριστὸν  ̊Ἰησοῦν ἐπιστεύσαμεν, ἵνα δικαιωθῶμεν ἐκ πίστεως  ̊Χριστοῦ, καὶ οὐκ ἐξ ἔργων νόμου, ὅτι ἐξ ἔργων νόμου, οὐ δικαιωθήσεται πᾶσα σάρξ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Εἰ δὲ ζητοῦντες δικαιωθῆναι ἐν  ̊Χριστῷ, εὑρέθημεν καὶ αὐτοὶ ἁμαρτωλοί, ἆρα  ̊Χριστὸς ἁμαρτίας διάκονος; Μὴ γένοιτο!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Εἰ γὰρ ἃ κατέλυσα, ταῦτα πάλιν οἰκοδομῶ, παραβάτην ἐμαυτὸν συνιστάνω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Ἐγὼ γὰρ διὰ νόμου νόμῳ ἀπέθανον, ἵνα  ̊Θεῷ ζήσω.  ̊Χριστῷ συνεσταύρωμαι·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'ζῶ δὲ, οὐκέτι ἐγώ, ζῇ δὲ ἐν ἐμοὶ  ̊Χριστός· ὃ δὲ νῦν ζῶ ἐν σαρκί, ἐν πίστει ζῶ τῇ τοῦ Υἱοῦ τοῦ  ̊Θεοῦ, τοῦ ἀγαπήσαντός με, καὶ παραδόντος ἑαυτὸν ὑπὲρ ἐμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Οὐκ ἀθετῶ τὴν χάριν τοῦ  ̊Θεοῦ· εἰ γὰρ διὰ νόμου δικαιοσύνη, ἄρα  ̊Χριστὸς δωρεὰν ἀπέθανεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, '¶Ὦ ἀνόητοι Γαλάται! Τίς ὑμᾶς ἐβάσκανεν, οἷς κατʼ ὀφθαλμοὺς  ̊Ἰησοῦς  ̊Χριστὸς προεγράφη ἐσταυρωμένος;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Τοῦτο μόνον θέλω μαθεῖν ἀφʼ ὑμῶν: ἐξ ἔργων νόμου τὸ  ̊Πνεῦμα ἐλάβετε, ἢ ἐξ ἀκοῆς πίστεως;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Οὕτως ἀνόητοί ἐστε; Ἐναρξάμενοι  ̊Πνεύματι, νῦν σαρκὶ ἐπιτελεῖσθε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Τοσαῦτα ἐπάθετε εἰκῇ– εἴ γε καὶ εἰκῇ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Ὁ οὖν ἐπιχορηγῶν ὑμῖν τὸ  ̊Πνεῦμα καὶ ἐνεργῶν δυνάμεις ἐν ὑμῖν, ἐξ ἔργων νόμου ἢ ἐξ ἀκοῆς πίστεως;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Καθὼς Ἀβραὰμ “ἐπίστευσεν τῷ  ̊Θεῷ καὶ ἐλογίσθη αὐτῷ εἰς δικαιοσύνην”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, '¶Γινώσκετε ἄρα ὅτι οἱ ἐκ πίστεως, οὗτοι υἱοί εἰσιν Ἀβραάμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Προϊδοῦσα δὲ ἡ Γραφὴ ὅτι ἐκ πίστεως δικαιοῖ τὰ ἔθνη ὁ  ̊Θεὸς, προευηγγελίσατο τῷ Ἀβραὰμ, ὅτι “Ἐνευλογηθήσονται ἐν σοὶ πάντα τὰ ἔθνη.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Ὥστε οἱ ἐκ πίστεως εὐλογοῦνται σὺν τῷ πιστῷ Ἀβραάμ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, '¶Ὅσοι γὰρ ἐξ ἔργων νόμου εἰσὶν ὑπὸ κατάραν εἰσίν, γέγραπται γὰρ, ὅτι “Ἐπικατάρατος πᾶς ὃς οὐκ ἐμμένει πᾶσιν τοῖς γεγραμμένοις ἐν τῷ βιβλίῳ τοῦ νόμου, τοῦ ποιῆσαι αὐτά.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Ὅτι δὲ ἐν νόμῳ, οὐδεὶς δικαιοῦται παρὰ τῷ  ̊Θεῷ δῆλον, ὅτι, “Ὁ δίκαιος ἐκ πίστεως ζήσεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Ὁ δὲ νόμος οὐκ ἔστιν ἐκ πίστεως, ἀλλʼ, “Ὁ ποιήσας αὐτὰ, ζήσεται ἐν αὐτοῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, ' ̊Χριστὸς ἡμᾶς ἐξηγόρασεν ἐκ τῆς κατάρας τοῦ νόμου, γενόμενος ὑπὲρ ἡμῶν κατάρα, ὅτι γέγραπται, “Ἐπικατάρατος πᾶς ὁ κρεμάμενος ἐπὶ ξύλου”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'ἵνα εἰς τὰ ἔθνη ἡ εὐλογία τοῦ Ἀβραὰμ γένηται ἐν  ̊Χριστῷ  ̊Ἰησοῦ, ἵνα τὴν ἐπαγγελίαν τοῦ  ̊Πνεύματος λάβωμεν διὰ τῆς πίστεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, '¶Ἀδελφοί, κατὰ ἄνθρωπον λέγω. Ὅμως ἀνθρώπου κεκυρωμένην διαθήκην, οὐδεὶς ἀθετεῖ ἢ ἐπιδιατάσσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Τῷ δὲ Ἀβραὰμ ἐρρέθησαν αἱ ἐπαγγελίαι καὶ τῷ σπέρματι αὐτοῦ. Οὐ λέγει, “Καὶ τοῖς σπέρμασιν”, ὡς ἐπὶ πολλῶν, ἀλλʼ ὡς ἐφʼ ἑνός, “Καὶ τῷ σπέρματί σου”, ὅς ἐστιν  ̊Χριστός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Τοῦτο δὲ λέγω: διαθήκην προκεκυρωμένην ὑπὸ τοῦ  ̊Θεοῦ, ὁ μετὰ τετρακόσια καὶ τριάκοντα ἔτη γεγονὼς νόμος οὐκ ἀκυροῖ, εἰς τὸ καταργῆσαι τὴν ἐπαγγελίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Εἰ γὰρ ἐκ νόμου ἡ κληρονομία, οὐκέτι ἐξ ἐπαγγελίας· τῷ δὲ Ἀβραὰμ διʼ ἐπαγγελίας κεχάρισται ὁ  ̊Θεός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, '¶Τί οὖν ὁ νόμος; Τῶν παραβάσεων χάριν προσετέθη, ἄχρις οὗ ἔλθῃ τὸ σπέρμα ᾧ ἐπήγγελται, διαταγεὶς διʼ ἀγγέλων ἐν χειρὶ μεσίτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Ὁ δὲ μεσίτης ἑνὸς οὐκ ἔστιν, ὁ δὲ  ̊Θεὸς εἷς ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, '¶Ὁ οὖν νόμος κατὰ τῶν ἐπαγγελιῶν τοῦ  ̊Θεοῦ; Μὴ γένοιτο! Εἰ γὰρ ἐδόθη νόμος ὁ δυνάμενος ζῳοποιῆσαι, ὄντως ἐκ νόμου ἂν ἦν ἡ δικαιοσύνη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Ἀλλὰ συνέκλεισεν ἡ Γραφὴ τὰ πάντα ὑπὸ ἁμαρτίαν, ἵνα ἡ ἐπαγγελία ἐκ πίστεως  ̊Ἰησοῦ  ̊Χριστοῦ δοθῇ τοῖς πιστεύουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 23, '¶Πρὸ τοῦ δὲ ἐλθεῖν τὴν πίστιν, ὑπὸ νόμον ἐφρουρούμεθα, συγκλειόμενοι εἰς τὴν μέλλουσαν πίστιν ἀποκαλυφθῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 24, 'Ὥστε ὁ νόμος, παιδαγωγὸς ἡμῶν γέγονεν εἰς  ̊Χριστόν, ἵνα ἐκ πίστεως δικαιωθῶμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 25, 'Ἐλθούσης δὲ τῆς πίστεως, οὐκέτι ὑπὸ παιδαγωγόν ἐσμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 26, 'Πάντες γὰρ υἱοὶ  ̊Θεοῦ ἐστε διὰ τῆς πίστεως ἐν  ̊Χριστῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 27, 'Ὅσοι γὰρ εἰς  ̊Χριστὸν ἐβαπτίσθητε,  ̊Χριστὸν ἐνεδύσασθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 28, 'Οὐκ ἔνι Ἰουδαῖος οὐδὲ Ἕλλην, οὐκ ἔνι δοῦλος οὐδὲ ἐλεύθερος, οὐκ ἔνι ἄρσεν καὶ θῆλυ, πάντες γὰρ ὑμεῖς εἷς ἐστε ἐν  ̊Χριστῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 29, 'Εἰ δὲ ὑμεῖς  ̊Χριστοῦ, ἄρα τοῦ Ἀβραὰμ σπέρμα ἐστέ, κατʼ ἐπαγγελίαν κληρονόμοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, '¶Λέγω δέ, ἐφʼ ὅσον χρόνον ὁ κληρονόμος νήπιός ἐστιν, οὐδὲν διαφέρει δούλου, κύριος πάντων ὤν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'ἀλλὰ ὑπὸ ἐπιτρόπους ἐστὶν καὶ οἰκονόμους, ἄχρι τῆς προθεσμίας τοῦ πατρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Οὕτως καὶ ἡμεῖς, ὅτε ἦμεν νήπιοι, ὑπὸ τὰ στοιχεῖα τοῦ κόσμου ἦμεν δεδουλωμένοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Ὅτε δὲ ἦλθεν τὸ πλήρωμα τοῦ χρόνου, ἐξαπέστειλεν ὁ  ̊Θεὸς τὸν Υἱὸν αὐτοῦ, γενόμενον ἐκ γυναικός, γενόμενον ὑπὸ νόμον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'ἵνα τοὺς ὑπὸ νόμον ἐξαγοράσῃ, ἵνα τὴν υἱοθεσίαν ἀπολάβωμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Ὅτι δέ ἐστε υἱοί, ἐξαπέστειλεν ὁ  ̊Θεὸς τὸ  ̊Πνεῦμα τοῦ υἱοῦ αὐτοῦ εἰς τὰς καρδίας ἡμῶν κρᾶζον, “Ἀββά, ὁ Πατήρ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Ὥστε οὐκέτι εἶ δοῦλος, ἀλλὰ υἱός· εἰ δὲ υἱός, καὶ κληρονόμος διὰ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, '¶Ἀλλὰ τότε μὲν οὐκ εἰδότες  ̊Θεὸν, ἐδουλεύσατε τοῖς φύσει μὴ οὖσι θεοῖς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'νῦν δὲ γνόντες  ̊Θεόν, μᾶλλον δὲ γνωσθέντες ὑπὸ  ̊Θεοῦ, πῶς ἐπιστρέφετε πάλιν ἐπὶ τὰ ἀσθενῆ καὶ πτωχὰ στοιχεῖα, οἷς πάλιν ἄνωθεν δουλεύειν θέλετε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Ἡμέρας παρατηρεῖσθε, καὶ μῆνας, καὶ καιροὺς, καὶ ἐνιαυτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Φοβοῦμαι ὑμᾶς, μή πως εἰκῇ κεκοπίακα εἰς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 12, '¶Γίνεσθε ὡς ἐγώ, ὅτι κἀγὼ ὡς ὑμεῖς, ἀδελφοί, δέομαι ὑμῶν. Οὐδέν με ἠδικήσατε·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 13, 'οἴδατε δὲ ὅτι διʼ ἀσθένειαν τῆς σαρκὸς, εὐηγγελισάμην ὑμῖν τὸ πρότερον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 14, 'Καὶ τὸν πειρασμὸν ὑμῶν ἐν τῇ σαρκί μου, οὐκ ἐξουθενήσατε οὐδὲ ἐξεπτύσατε, ἀλλʼ ὡς ἄγγελον  ̊Θεοῦ ἐδέξασθέ με, ὡς  ̊Χριστὸν  ̊Ἰησοῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 15, 'Ποῦ οὖν ὁ μακαρισμὸς ὑμῶν; Μαρτυρῶ γὰρ ὑμῖν ὅτι εἰ δυνατὸν τοὺς ὀφθαλμοὺς ὑμῶν ἐξορύξαντες, ἐδώκατέ μοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 16, 'Ὥστε ἐχθρὸς ὑμῶν γέγονα, ἀληθεύων ὑμῖν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 17, 'Ζηλοῦσιν ὑμᾶς οὐ καλῶς, ἀλλὰ ἐκκλεῖσαι ὑμᾶς θέλουσιν, ἵνα αὐτοὺς ζηλοῦτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 18, 'Καλὸν δὲ ζηλοῦσθαι ἐν καλῷ πάντοτε, καὶ μὴ μόνον ἐν τῷ παρεῖναί με πρὸς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 19, 'Τέκνα μου, οὓς πάλιν ὠδίνω, μέχρις οὗ μορφωθῇ  ̊Χριστὸς ἐν ὑμῖν–');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 20, 'ἤθελον δὲ παρεῖναι πρὸς ὑμᾶς ἄρτι, καὶ ἀλλάξαι τὴν φωνήν μου, ὅτι ἀποροῦμαι ἐν ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 21, '¶Λέγετέ μοι, οἱ ὑπὸ νόμον θέλοντες εἶναι, τὸν νόμον οὐκ ἀκούετε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 22, 'Γέγραπται γὰρ ὅτι Ἀβραὰμ δύο υἱοὺς ἔσχεν, ἕνα ἐκ τῆς παιδίσκης, καὶ ἕνα ἐκ τῆς ἐλευθέρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 23, 'Ἀλλʼ ὁ μὲν ἐκ τῆς παιδίσκης, κατὰ σάρκα γεγέννηται, ὁ δὲ ἐκ τῆς ἐλευθέρας, διʼ ἐπαγγελίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 24, 'Ἅτινά ἐστιν ἀλληγορούμενα, αὗται γάρ εἰσιν δύο διαθῆκαι: μία μὲν ἀπὸ Ὄρους Σινᾶ εἰς δουλείαν γεννῶσα, ἥτις ἐστὶν Ἁγάρ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 25, 'Τὸ δὲ Ἁγὰρ Σινᾶ Ὄρος ἐστὶν ἐν τῇ Ἀραβίᾳ, συστοιχεῖ δὲ τῇ νῦν Ἰερουσαλήμ, δουλεύει γὰρ μετὰ τῶν τέκνων αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 26, 'Ἡ δὲ ἄνω Ἰερουσαλὴμ ἐλευθέρα ἐστίν, ἥτις ἐστὶν μήτηρ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 27, 'Γέγραπται γάρ, “Εὐφράνθητι, στεῖρα, ἡ οὐ τίκτουσα, ῥῆξον καὶ βόησον, ἡ οὐκ ὠδίνουσα, ὅτι πολλὰ τὰ τέκνα τῆς ἐρήμου μᾶλλον, ἢ τῆς ἐχούσης τὸν ἄνδρα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 28, 'Ὑμεῖς δέ, ἀδελφοί, κατὰ Ἰσαὰκ, ἐπαγγελίας τέκνα ἐστέ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 29, 'Ἀλλʼ ὥσπερ τότε ὁ κατὰ σάρκα γεννηθεὶς, ἐδίωκε τὸν κατὰ  ̊Πνεῦμα, οὕτως καὶ νῦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 30, 'Ἀλλὰ τί λέγει ἡ Γραφή; “Ἔκβαλε τὴν παιδίσκην καὶ τὸν υἱὸν αὐτῆς, οὐ γὰρ μὴ κληρονομήσει ὁ υἱὸς τῆς παιδίσκης, μετὰ τοῦ υἱοῦ τῆς ἐλευθέρας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 31, 'Διό ἀδελφοί, οὐκ ἐσμὲν παιδίσκης τέκνα, ἀλλὰ τῆς ἐλευθέρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Τῇ ἐλευθερίᾳ, ἡμᾶς  ̊Χριστὸς ἠλευθέρωσεν, στήκετε οὖν, καὶ μὴ πάλιν ζυγῷ δουλείας ἐνέχεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, '¶Ἴδε, ἐγὼ Παῦλος λέγω ὑμῖν ὅτι ἐὰν περιτέμνησθε,  ̊Χριστὸς ὑμᾶς οὐδὲν ὠφελήσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Μαρτύρομαι δὲ πάλιν παντὶ ἀνθρώπῳ περιτεμνομένῳ ὅτι ὀφειλέτης ἐστὶν, ὅλον τὸν νόμον ποιῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Κατηργήθητε ἀπὸ  ̊Χριστοῦ, οἵτινες ἐν νόμῳ δικαιοῦσθε, τῆς χάριτος ἐξεπέσατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Ἡμεῖς γὰρ  ̊Πνεύματι ἐκ πίστεως ἐλπίδα δικαιοσύνης ἀπεκδεχόμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Ἐν γὰρ  ̊Χριστῷ  ̊Ἰησοῦ, οὔτε περιτομή τι ἰσχύει, οὔτε ἀκροβυστία, ἀλλὰ πίστις διʼ ἀγάπης ἐνεργουμένη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, '¶Ἐτρέχετε καλῶς· τίς ὑμᾶς ἐνέκοψεν, ἀληθείᾳ μὴ πείθεσθαι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Ἡ πεισμονὴ οὐκ ἐκ τοῦ καλοῦντος ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Μικρὰ ζύμη ὅλον τὸ φύραμα ζυμοῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Ἐγὼ πέποιθα εἰς ὑμᾶς ἐν  ̊Κυρίῳ ὅτι οὐδὲν ἄλλο φρονήσετε. Ὁ δὲ ταράσσων ὑμᾶς, βαστάσει τὸ κρίμα, ὅστις ἐὰν ᾖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Ἐγὼ δέ, ἀδελφοί, εἰ περιτομὴν ἔτι κηρύσσω, τί ἔτι διώκομαι; Ἄρα κατήργηται τὸ σκάνδαλον τοῦ σταυροῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Ὄφελον καὶ ἀποκόψονται οἱ ἀναστατοῦντες ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, '¶Ὑμεῖς γὰρ ἐπʼ ἐλευθερίᾳ ἐκλήθητε, ἀδελφοί· μόνον μὴ τὴν ἐλευθερίαν εἰς ἀφορμὴν τῇ σαρκί, ἀλλὰ διὰ τῆς ἀγάπης δουλεύετε ἀλλήλοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Ὁ γὰρ πᾶς νόμος ἐν ἑνὶ λόγῳ πεπλήρωται, ἐν τῷ, “Ἀγαπήσεις τὸν πλησίον σου ὡς σεαυτόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 15, 'Εἰ δὲ ἀλλήλους δάκνετε καὶ κατεσθίετε, βλέπετε, μὴ ὑπʼ ἀλλήλων ἀναλωθῆτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 16, '¶Λέγω δέ,  ̊Πνεύματι περιπατεῖτε, καὶ ἐπιθυμίαν σαρκὸς οὐ μὴ τελέσητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 17, 'Ἡ γὰρ σὰρξ ἐπιθυμεῖ κατὰ τοῦ  ̊Πνεύματος, τὸ δὲ  ̊Πνεῦμα κατὰ τῆς σαρκός, ταῦτα γὰρ ἀλλήλοις ἀντίκειται, ἵνα μὴ ἃ ἐὰν θέλητε, ταῦτα ποιῆτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 18, 'Εἰ δὲ  ̊Πνεύματι ἄγεσθε, οὐκ ἐστὲ ὑπὸ νόμον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 19, 'Φανερὰ δέ ἐστιν τὰ ἔργα τῆς σαρκός, ἅτινά ἐστιν πορνεία, ἀκαθαρσία, ἀσέλγεια,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 20, 'εἰδωλολατρεία, φαρμακεία, ἔχθραι, ἔρις, ζῆλοι, θυμοί, ἐριθεῖαι, διχοστασίαι, αἱρέσεις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 21, 'φθόνοι, μέθαι, κῶμοι, καὶ τὰ ὅμοια τούτοις, ἃ προλέγω ὑμῖν, καθὼς προεῖπον, ὅτι οἱ τὰ τοιαῦτα πράσσοντες, Βασιλείαν  ̊Θεοῦ οὐ κληρονομήσουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 22, '¶Ὁ δὲ καρπὸς τοῦ  ̊Πνεύματός ἐστιν ἀγάπη, χαρά, εἰρήνη, μακροθυμία, χρηστότης, ἀγαθωσύνη, πίστις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 23, 'πραΰτης, ἐγκράτεια· κατὰ τῶν τοιούτων, οὐκ ἔστιν νόμος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 24, 'Οἱ δὲ τοῦ  ̊Χριστοῦ  ̊Ἰησοῦ, τὴν σάρκα ἐσταύρωσαν σὺν τοῖς παθήμασιν καὶ ταῖς ἐπιθυμίαις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 25, 'Εἰ ζῶμεν  ̊Πνεύματι,  ̊Πνεύματι καὶ στοιχῶμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 26, 'Μὴ γινώμεθα κενόδοξοι, ἀλλήλους προκαλούμενοι, ἀλλήλοις φθονοῦντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, '¶Ἀδελφοί, ἐὰν καὶ προλημφθῇ ἄνθρωπος ἔν τινι παραπτώματι, ὑμεῖς, οἱ πνευματικοὶ, καταρτίζετε τὸν τοιοῦτον ἐν πνεύματι πραΰτητος, σκοπῶν σεαυτόν, μὴ καὶ σὺ πειρασθῇς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Ἀλλήλων τὰ βάρη βαστάζετε, καὶ οὕτως ἀναπληρώσατε τὸν νόμον τοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Εἰ γὰρ δοκεῖ τις εἶναί τι, μηδὲν ὤν, φρεναπατᾷ ἑαυτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Τὸ δὲ ἔργον ἑαυτοῦ δοκιμαζέτω ἕκαστος, καὶ τότε εἰς ἑαυτὸν μόνον τὸ καύχημα ἕξει, καὶ οὐκ εἰς τὸν ἕτερον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Ἕκαστος γὰρ τὸ ἴδιον φορτίον βαστάσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, '¶Κοινωνείτω δὲ ὁ κατηχούμενος τὸν λόγον, τῷ κατηχοῦντι, ἐν πᾶσιν ἀγαθοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Μὴ πλανᾶσθε,  ̊Θεὸς οὐ μυκτηρίζεται. Ὃ γὰρ ἐὰν σπείρῃ ἄνθρωπος, τοῦτο καὶ θερίσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Ὅτι ὁ σπείρων εἰς τὴν σάρκα ἑαυτοῦ, ἐκ τῆς σαρκὸς θερίσει φθοράν, ὁ δὲ σπείρων εἰς τὸ  ̊Πνεῦμα, ἐκ τοῦ  ̊Πνεύματος θερίσει ζωὴν αἰώνιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Τὸ δὲ καλὸν ποιοῦντες, μὴ ἐγκακῶμεν, καιρῷ γὰρ ἰδίῳ, θερίσομεν μὴ ἐκλυόμενοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Ἄρα οὖν, ὡς καιρὸν ἔχομεν, ἐργαζώμεθα τὸ ἀγαθὸν πρὸς πάντας, μάλιστα δὲ πρὸς τοὺς οἰκείους τῆς πίστεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, '¶Ἴδετε πηλίκοις ὑμῖν γράμμασιν ἔγραψα τῇ ἐμῇ χειρί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Ὅσοι θέλουσιν εὐπροσωπῆσαι ἐν σαρκί, οὗτοι ἀναγκάζουσιν ὑμᾶς περιτέμνεσθαι, μόνον ἵνα τῷ σταυρῷ τοῦ  ̊Χριστοῦ  ̊Ἰησοῦ μὴ διώκωνται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'Οὐδὲ γὰρ οἱ περιτετμημένοι αὐτοὶ νόμον φυλάσσουσιν, ἀλλὰ θέλουσιν ὑμᾶς περιτέμνεσθαι, ἵνα ἐν τῇ ὑμετέρᾳ σαρκὶ καυχήσωνται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Ἐμοὶ δὲ, μὴ γένοιτο καυχᾶσθαι, εἰ μὴ ἐν τῷ σταυρῷ τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, διʼ οὗ ἐμοὶ κόσμος ἐσταύρωται, κἀγὼ κόσμῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Οὔτε γὰρ περιτομή τί ἐστιν, οὔτε ἀκροβυστία, ἀλλὰ καινὴ κτίσις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'Καὶ ὅσοι τῷ κανόνι τούτῳ στοιχήσουσιν, εἰρήνη ἐπʼ αὐτοὺς, καὶ ἔλεος, καὶ ἐπὶ τὸν Ἰσραὴλ τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, '¶Τοῦ λοιποῦ, κόπους μοι μηδεὶς παρεχέτω, ἐγὼ γὰρ τὰ στίγματα τοῦ  ̊Ἰησοῦ ἐν τῷ σώματί μου βαστάζω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 18, '¶Ἡ χάρις τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, μετὰ τοῦ πνεύματος ὑμῶν, ἀδελφοί. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 1, '¶Παῦλος, ἀπόστολος  ̊Χριστοῦ  ̊Ἰησοῦ διὰ θελήματος  ̊Θεοῦ, τοῖς ἁγίοις τοῖς οὖσιν ἐν Ἐφέσῳ καὶ πιστοῖς ἐν  ̊Χριστῷ  ̊Ἰησοῦ:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 2, 'χάρις ὑμῖν καὶ εἰρήνη ἀπὸ  ̊Θεοῦ Πατρὸς ἡμῶν καὶ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 3, '¶Εὐλογητὸς ὁ  ̊Θεὸς καὶ Πατὴρ τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, ὁ εὐλογήσας ἡμᾶς ἐν πάσῃ εὐλογίᾳ πνευματικῇ ἐν τοῖς ἐπουρανίοις ἐν  ̊Χριστῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 4, 'καθὼς ἐξελέξατο ἡμᾶς ἐν αὐτῷ πρὸ καταβολῆς κόσμου, εἶναι ἡμᾶς ἁγίους καὶ ἀμώμους κατενώπιον αὐτοῦ ἐν ἀγάπῃ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 5, 'προορίσας ἡμᾶς εἰς υἱοθεσίαν διὰ  ̊Ἰησοῦ  ̊Χριστοῦ εἰς αὐτόν, κατὰ τὴν εὐδοκίαν τοῦ θελήματος αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 6, 'εἰς ἔπαινον δόξης τῆς χάριτος αὐτοῦ, ἧς ἐχαρίτωσεν ἡμᾶς ἐν τῷ ἠγαπημένῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 7, 'ἐν ᾧ ἔχομεν τὴν ἀπολύτρωσιν διὰ τοῦ αἵματος αὐτοῦ, τὴν ἄφεσιν τῶν παραπτωμάτων, κατὰ τὸ πλοῦτος τῆς χάριτος αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 8, 'ἧς ἐπερίσσευσεν εἰς ἡμᾶς ἐν πάσῃ σοφίᾳ καὶ φρονήσει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 9, 'γνωρίσας ἡμῖν τὸ μυστήριον τοῦ θελήματος αὐτοῦ, κατὰ τὴν εὐδοκίαν αὐτοῦ, ἣν προέθετο ἐν αὐτῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 10, 'εἰς οἰκονομίαν τοῦ πληρώματος τῶν καιρῶν, ἀνακεφαλαιώσασθαι τὰ πάντα ἐν τῷ  ̊Χριστῷ, τὰ ἐπὶ τοῖς οὐρανοῖς, καὶ τὰ ἐπὶ τῆς γῆς· ἐν αὐτῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 11, 'ἐν ᾧ καὶ ἐκληρώθημεν, προορισθέντες κατὰ πρόθεσιν τοῦ τὰ πάντα ἐνεργοῦντος, κατὰ τὴν βουλὴν τοῦ θελήματος αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 12, 'εἰς τὸ εἶναι ἡμᾶς, εἰς ἔπαινον δόξης αὐτοῦ, τοὺς προηλπικότας ἐν τῷ  ̊Χριστῷ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 13, 'ἐν ᾧ καὶ ὑμεῖς ἀκούσαντες τὸν λόγον τῆς ἀληθείας, τὸ εὐαγγέλιον τῆς σωτηρίας ὑμῶν, ἐν ᾧ καὶ πιστεύσαντες, ἐσφραγίσθητε τῷ  ̊Πνεύματι τῆς ἐπαγγελίας τῷ Ἁγίῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 14, 'ὅ ἐστιν ἀρραβὼν τῆς κληρονομίας ἡμῶν, εἰς ἀπολύτρωσιν τῆς περιποιήσεως, εἰς ἔπαινον τῆς δόξης αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 15, '¶Διὰ τοῦτο, κἀγώ ἀκούσας τὴν καθʼ ὑμᾶς πίστιν ἐν τῷ  ̊Κυρίῳ  ̊Ἰησοῦ, καὶ τὴν εἰς πάντας τοὺς ἁγίους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 16, 'οὐ παύομαι εὐχαριστῶν ὑπὲρ ὑμῶν, μνείαν ποιούμενος ἐπὶ τῶν προσευχῶν μου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 17, 'ἵνα ὁ  ̊Θεὸς τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, ὁ Πατὴρ τῆς δόξης, δώῃ ὑμῖν πνεῦμα σοφίας καὶ ἀποκαλύψεως, ἐν ἐπιγνώσει αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 18, 'πεφωτισμένους τοὺς ὀφθαλμοὺς τῆς καρδίας ὑμῶν εἰς τὸ εἰδέναι ὑμᾶς, τίς ἐστιν ἡ ἐλπὶς τῆς κλήσεως αὐτοῦ, τίς ὁ πλοῦτος τῆς δόξης τῆς κληρονομίας αὐτοῦ, ἐν τοῖς ἁγίοις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 19, 'καὶ τί τὸ ὑπερβάλλον μέγεθος τῆς δυνάμεως αὐτοῦ εἰς ἡμᾶς, τοὺς πιστεύοντας κατὰ τὴν ἐνέργειαν τοῦ κράτους τῆς ἰσχύος αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 20, 'ἣν ἐνήργηκεν ἐν τῷ  ̊Χριστῷ, ἐγείρας αὐτὸν ἐκ νεκρῶν, καὶ καθίσας ἐν δεξιᾷ αὐτοῦ, ἐν τοῖς ἐπουρανίοις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 21, 'ὑπεράνω πάσης ἀρχῆς, καὶ ἐξουσίας, καὶ δυνάμεως, καὶ κυριότητος, καὶ παντὸς ὀνόματος ὀνομαζομένου, οὐ μόνον ἐν τῷ αἰῶνι τούτῳ, ἀλλὰ καὶ ἐν τῷ μέλλοντι·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 22, 'καὶ πάντα ὑπέταξεν ὑπὸ τοὺς πόδας αὐτοῦ, καὶ αὐτὸν ἔδωκεν κεφαλὴν ὑπὲρ πάντα τῇ ἐκκλησίᾳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 23, 'ἥτις ἐστὶν τὸ σῶμα αὐτοῦ, τὸ πλήρωμα τοῦ τὰ πάντα ἐν πᾶσιν πληρουμένου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 1, '¶Καὶ ὑμᾶς ὄντας νεκροὺς τοῖς παραπτώμασιν καὶ ταῖς ἁμαρτίαις ὑμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 2, 'ἐν αἷς ποτε περιεπατήσατε, κατὰ τὸν αἰῶνα τοῦ κόσμου τούτου, κατὰ τὸν ἄρχοντα τῆς ἐξουσίας τοῦ ἀέρος, τοῦ πνεύματος τοῦ νῦν ἐνεργοῦντος ἐν τοῖς υἱοῖς τῆς ἀπειθείας·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 3, 'ἐν οἷς καὶ ἡμεῖς πάντες ἀνεστράφημέν ποτε ἐν ταῖς ἐπιθυμίαις τῆς σαρκὸς ἡμῶν, ποιοῦντες τὰ θελήματα τῆς σαρκὸς καὶ τῶν διανοιῶν, καὶ ἤμεθα τέκνα φύσει ὀργῆς, ὡς καὶ οἱ λοιποί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 4, 'Ὁ δὲ  ̊Θεὸς πλούσιος ὢν ἐν ἐλέει, διὰ τὴν πολλὴν ἀγάπην αὐτοῦ, ἣν ἠγάπησεν ἡμᾶς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 5, 'καὶ ὄντας ἡμᾶς νεκροὺς τοῖς παραπτώμασιν, συνεζωοποίησεν τῷ  ̊Χριστῷ (χάριτί ἐστε σεσῳσμένοι),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 6, 'καὶ συνήγειρεν καὶ συνεκάθισεν ἐν τοῖς ἐπουρανίοις ἐν  ̊Χριστῷ  ̊Ἰησοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 7, 'ἵνα ἐνδείξηται ἐν τοῖς αἰῶσιν, τοῖς ἐπερχομένοις τὸ ὑπερβάλλον πλοῦτος τῆς χάριτος αὐτοῦ, ἐν χρηστότητι ἐφʼ ἡμᾶς ἐν  ̊Χριστῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 8, 'Τῇ γὰρ χάριτί ἐστε σεσῳσμένοι διὰ πίστεως, καὶ τοῦτο οὐκ ἐξ ὑμῶν,  ̊Θεοῦ τὸ δῶρον·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 9, 'οὐκ ἐξ ἔργων, ἵνα μή τις καυχήσηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 10, 'Αὐτοῦ γάρ ἐσμεν ποίημα, κτισθέντες ἐν  ̊Χριστῷ  ̊Ἰησοῦ ἐπὶ ἔργοις ἀγαθοῖς, οἷς προητοίμασεν ὁ  ̊Θεὸς, ἵνα ἐν αὐτοῖς περιπατήσωμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 11, '¶Διὸ μνημονεύετε ὅτι ποτὲ ὑμεῖς τὰ ἔθνη ἐν σαρκί, οἱ λεγόμενοι ἀκροβυστία ὑπὸ τῆς λεγομένης περιτομῆς ἐν σαρκὶ χειροποιήτου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 12, 'ὅτι ἦτε τῷ καιρῷ ἐκείνῳ χωρὶς  ̊Χριστοῦ, ἀπηλλοτριωμένοι τῆς πολιτείας τοῦ Ἰσραὴλ, καὶ ξένοι τῶν διαθηκῶν τῆς ἐπαγγελίας, ἐλπίδα μὴ ἔχοντες, καὶ ἄθεοι ἐν τῷ κόσμῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 13, 'Νυνὶ δὲ ἐν  ̊Χριστῷ  ̊Ἰησοῦ, ὑμεῖς οἵ ποτε ὄντες μακρὰν, ἐγενήθητε ἐγγὺς ἐν τῷ αἵματι τοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 14, 'Αὐτὸς γάρ ἐστιν ἡ εἰρήνη ἡμῶν, ὁ ποιήσας τὰ ἀμφότερα ἓν, καὶ τὸ μεσότοιχον τοῦ φραγμοῦ λύσας, τὴν ἔχθραν ἐν τῇ σαρκὶ αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 15, 'τὸν νόμον τῶν ἐντολῶν ἐν δόγμασιν καταργήσας, ἵνα τοὺς δύο κτίσῃ ἐν αὑτῷ εἰς ἕνα καινὸν ἄνθρωπον, ποιῶν εἰρήνην,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 16, 'καὶ ἀποκαταλλάξῃ τοὺς ἀμφοτέρους ἐν ἑνὶ σώματι τῷ  ̊Θεῷ διὰ τοῦ σταυροῦ, ἀποκτείνας τὴν ἔχθραν ἐν αὐτῷ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 17, 'καὶ ἐλθὼν, εὐηγγελίσατο, “εἰρήνην ὑμῖν τοῖς μακρὰν, καὶ εἰρήνην τοῖς ἐγγύς”·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 18, 'ὅτι διʼ αὐτοῦ ἔχομεν τὴν προσαγωγὴν, οἱ ἀμφότεροι ἐν ἑνὶ  ̊Πνεύματι πρὸς τὸν Πατέρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 19, 'Ἄρα οὖν οὐκέτι ἐστὲ ξένοι καὶ πάροικοι, ἀλλὰ ἐστὲ συμπολῖται τῶν ἁγίων καὶ οἰκεῖοι τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 20, 'ἐποικοδομηθέντες ἐπὶ τῷ θεμελίῳ τῶν ἀποστόλων καὶ προφητῶν, ὄντος ἀκρογωνιαίου αὐτοῦ  ̊Χριστοῦ  ̊Ἰησοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 21, 'ἐν ᾧ πᾶσα ἡ οἰκοδομὴ συναρμολογουμένη, αὔξει εἰς ναὸν ἅγιον ἐν  ̊Κυρίῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 22, 'ἐν ᾧ καὶ ὑμεῖς συνοικοδομεῖσθε, εἰς κατοικητήριον τοῦ  ̊Θεοῦ ἐν  ̊Πνεύματι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 1, '¶Τούτου χάριν, ἐγὼ Παῦλος, ὁ δέσμιος τοῦ  ̊Χριστοῦ  ̊Ἰησοῦ ὑπὲρ ὑμῶν τῶν ἐθνῶν–');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 2, 'εἴ γε ἠκούσατε τὴν οἰκονομίαν τῆς χάριτος τοῦ  ̊Θεοῦ, τῆς δοθείσης μοι εἰς ὑμᾶς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 3, 'κατὰ ἀποκάλυψιν ἐγνωρίσθη μοι τὸ μυστήριον, καθὼς προέγραψα ἐν ὀλίγῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 4, 'πρὸς ὃ δύνασθε ἀναγινώσκοντες νοῆσαι τὴν σύνεσίν μου ἐν τῷ μυστηρίῳ τοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 5, 'ὃ ἑτέραις γενεαῖς οὐκ ἐγνωρίσθη τοῖς υἱοῖς τῶν ἀνθρώπων, ὡς νῦν ἀπεκαλύφθη τοῖς ἁγίοις ἀποστόλοις αὐτοῦ καὶ προφήταις ἐν  ̊Πνεύματι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 6, 'εἶναι τὰ ἔθνη, συγκληρονόμα, καὶ σύσσωμα, καὶ συμμέτοχα, τῆς ἐπαγγελίας ἐν  ̊Χριστῷ  ̊Ἰησοῦ, διὰ τοῦ εὐαγγελίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 7, 'οὗ ἐγενήθην διάκονος κατὰ τὴν δωρεὰν τῆς χάριτος τοῦ  ̊Θεοῦ τῆς δοθείσης μοι, κατὰ τὴν ἐνέργειαν τῆς δυνάμεως αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 8, 'Ἐμοὶ τῷ, ἐλαχιστοτέρῳ πάντων ἁγίων, ἐδόθη ἡ χάρις αὕτη, τοῖς ἔθνεσιν εὐαγγελίσασθαι, τὸ ἀνεξιχνίαστον πλοῦτος τοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 9, 'καὶ φωτίσαι πάντας, τίς ἡ οἰκονομία τοῦ μυστηρίου, τοῦ ἀποκεκρυμμένου ἀπὸ τῶν αἰώνων ἐν τῷ  ̊Θεῷ, τῷ τὰ πάντα κτίσαντι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 10, 'ἵνα γνωρισθῇ νῦν ταῖς ἀρχαῖς καὶ ταῖς ἐξουσίαις ἐν τοῖς ἐπουρανίοις διὰ τῆς ἐκκλησίας ἡ πολυποίκιλος σοφία τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 11, 'κατὰ πρόθεσιν τῶν αἰώνων, ἣν ἐποίησεν ἐν τῷ  ̊Χριστῷ  ̊Ἰησοῦ, τῷ  ̊Κυρίῳ ἡμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 12, 'ἐν ᾧ ἔχομεν τὴν παρρησίαν καὶ προσαγωγὴν ἐν πεποιθήσει διὰ τῆς πίστεως αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 13, 'Διὸ αἰτοῦμαι μὴ ἐγκακεῖν ἐν ταῖς θλίψεσίν μου ὑπὲρ ὑμῶν, ἥτις ἐστὶν δόξα ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 14, '¶Τούτου χάριν, κάμπτω τὰ γόνατά μου πρὸς τὸν Πατέρα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 15, 'ἐξ οὗ πᾶσα πατριὰ ἐν οὐρανοῖς καὶ ἐπὶ γῆς ὀνομάζεται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 16, 'ἵνα δῷ ὑμῖν κατὰ τὸ πλοῦτος τῆς δόξης αὐτοῦ, δυνάμει κραταιωθῆναι διὰ τοῦ  ̊Πνεύματος αὐτοῦ εἰς τὸν ἔσω ἄνθρωπον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 17, 'κατοικῆσαι τὸν  ̊Χριστὸν διὰ τῆς πίστεως ἐν ταῖς καρδίαις ὑμῶν ἐν ἀγάπῃ, ἐρριζωμένοι καὶ τεθεμελιωμένοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 18, 'ἵνα ἐξισχύσητε καταλαβέσθαι σὺν πᾶσιν τοῖς ἁγίοις, τί τὸ πλάτος, καὶ μῆκος, καὶ ὕψος, καὶ βάθος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 19, 'γνῶναί τε τὴν ὑπερβάλλουσαν τῆς γνώσεως ἀγάπην τοῦ  ̊Χριστοῦ, ἵνα πληρωθῆτε εἰς πᾶν τὸ πλήρωμα τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 20, '¶Τῷ δὲ δυναμένῳ ὑπὲρ πάντα, ποιῆσαι ὑπερεκπερισσοῦ ὧν αἰτούμεθα ἢ νοοῦμεν, κατὰ τὴν δύναμιν τὴν ἐνεργουμένην ἐν ἡμῖν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 21, 'αὐτῷ ἡ δόξα ἐν τῇ ἐκκλησίᾳ καὶ ἐν  ̊Χριστῷ  ̊Ἰησοῦ, εἰς πάσας τὰς γενεὰς τοῦ αἰῶνος τῶν αἰώνων. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 1, '¶Παρακαλῶ οὖν ὑμᾶς, ἐγὼ ὁ δέσμιος ἐν  ̊Κυρίῳ, ἀξίως περιπατῆσαι τῆς κλήσεως ἧς ἐκλήθητε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 2, 'μετὰ πάσης ταπεινοφροσύνης καὶ πραΰτητος, μετὰ μακροθυμίας, ἀνεχόμενοι ἀλλήλων ἐν ἀγάπῃ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 3, 'σπουδάζοντες τηρεῖν τὴν ἑνότητα τοῦ  ̊Πνεύματος ἐν τῷ συνδέσμῳ τῆς εἰρήνης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 4, 'Ἓν σῶμα καὶ ἓν  ̊Πνεῦμα, καθὼς καὶ ἐκλήθητε ἐν μιᾷ ἐλπίδι τῆς κλήσεως ὑμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 5, 'εἷς  ̊Κύριος, μία πίστις, ἓν βάπτισμα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 6, 'εἷς  ̊Θεὸς καὶ Πατὴρ πάντων, ὁ ἐπὶ πάντων, καὶ διὰ πάντων, καὶ ἐν πᾶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 7, '¶Ἑνὶ δὲ ἑκάστῳ ἡμῶν ἐδόθη ἡ χάρις, κατὰ τὸ μέτρον τῆς δωρεᾶς τοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 8, 'Διὸ λέγει, “Ἀναβὰς εἰς ὕψος, ᾐχμαλώτευσεν αἰχμαλωσίαν, ἔδωκεν δόματα τοῖς ἀνθρώποις.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 9, 'Τὸ δὲ, “ἀνέβη”, τί ἐστιν, εἰ μὴ ὅτι καὶ κατέβη εἰς τὰ κατώτερα μέρη τῆς γῆς;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 10, 'Ὁ καταβὰς αὐτός ἐστιν καὶ ὁ ἀναβὰς ὑπεράνω πάντων τῶν οὐρανῶν, ἵνα πληρώσῃ τὰ πάντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 11, 'Καὶ αὐτὸς ἔδωκεν τοὺς μὲν ἀποστόλους, τοὺς δὲ προφήτας, τοὺς δὲ εὐαγγελιστάς, τοὺς δὲ ποιμένας καὶ διδασκάλους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 12, 'πρὸς τὸν καταρτισμὸν τῶν ἁγίων εἰς ἔργον διακονίας, εἰς οἰκοδομὴν τοῦ σώματος τοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 13, 'μέχρι καταντήσωμεν οἱ πάντες εἰς τὴν ἑνότητα τῆς πίστεως, καὶ τῆς ἐπιγνώσεως τοῦ Υἱοῦ τοῦ  ̊Θεοῦ, εἰς ἄνδρα τέλειον, εἰς μέτρον ἡλικίας τοῦ πληρώματος τοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 14, 'ἵνα μηκέτι ὦμεν νήπιοι, κλυδωνιζόμενοι καὶ περιφερόμενοι παντὶ ἀνέμῳ τῆς διδασκαλίας ἐν τῇ κυβείᾳ τῶν ἀνθρώπων, ἐν πανουργίᾳ πρὸς τὴν μεθοδείαν τῆς πλάνης,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 15, 'ἀληθεύοντες δὲ ἐν ἀγάπῃ, αὐξήσωμεν εἰς αὐτὸν τὰ πάντα, ὅς ἐστιν ἡ κεφαλή  ̊Χριστός,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 16, 'ἐξ οὗ πᾶν τὸ σῶμα, συναρμολογούμενον καὶ συμβιβαζόμενον διὰ πάσης ἁφῆς τῆς ἐπιχορηγίας κατʼ ἐνέργειαν ἐν μέτρῳ ἑνὸς ἑκάστου μέρους, τὴν αὔξησιν τοῦ σώματος ποιεῖται εἰς οἰκοδομὴν ἑαυτοῦ ἐν ἀγάπῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 17, '¶Τοῦτο οὖν λέγω καὶ μαρτύρομαι ἐν  ̊Κυρίῳ, μηκέτι ὑμᾶς περιπατεῖν, καθὼς καὶ τὰ ἔθνη περιπατεῖ ἐν ματαιότητι τοῦ νοὸς αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 18, 'Ἐσκοτωμένοι τῇ διανοίᾳ ὄντες, ἀπηλλοτριωμένοι τῆς ζωῆς τοῦ  ̊Θεοῦ, διὰ τὴν ἄγνοιαν τὴν οὖσαν ἐν αὐτοῖς, διὰ τὴν πώρωσιν τῆς καρδίας αὐτῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 19, 'οἵτινες ἀπηλγηκότες, ἑαυτοὺς παρέδωκαν τῇ ἀσελγείᾳ εἰς ἐργασίαν ἀκαθαρσίας πάσης ἐν πλεονεξίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 20, 'Ὑμεῖς δὲ οὐχ οὕτως ἐμάθετε τὸν  ̊Χριστόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 21, 'εἴ γε αὐτὸν ἠκούσατε καὶ ἐν αὐτῷ ἐδιδάχθητε, καθώς ἐστιν ἀλήθεια ἐν τῷ  ̊Ἰησοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 22, 'ἀποθέσθαι ὑμᾶς κατὰ τὴν προτέραν ἀναστροφὴν τὸν παλαιὸν ἄνθρωπον, τὸν φθειρόμενον κατὰ τὰς ἐπιθυμίας τῆς ἀπάτης,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 23, 'ἀνανεοῦσθαι δὲ τῷ πνεύματι τοῦ νοὸς ὑμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 24, 'καὶ ἐνδύσασθαι τὸν καινὸν ἄνθρωπον τὸν κατὰ  ̊Θεὸν, κτισθέντα ἐν δικαιοσύνῃ καὶ ὁσιότητι τῆς ἀληθείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 25, '¶Διὸ ἀποθέμενοι τὸ ψεῦδος, “λαλεῖτε ἀλήθειαν ἕκαστος μετὰ τοῦ πλησίον αὐτοῦ”, ὅτι ἐσμὲν ἀλλήλων μέλη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 26, '“Ὀργίζεσθε, καὶ μὴ ἁμαρτάνετε”· ὁ ἥλιος μὴ ἐπιδυέτω ἐπὶ παροργισμῷ ὑμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 27, 'μηδὲ δίδοτε τόπον τῷ διαβόλῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 28, 'Ὁ κλέπτων μηκέτι κλεπτέτω, μᾶλλον δὲ κοπιάτω, ἐργαζόμενος ταῖς χερσὶν τὸ ἀγαθόν, ἵνα ἔχῃ μεταδιδόναι τῷ χρείαν ἔχοντι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 29, 'Πᾶς λόγος σαπρὸς ἐκ τοῦ στόματος ὑμῶν μὴ ἐκπορευέσθω, ἀλλʼ εἴ τις ἀγαθὸς πρὸς οἰκοδομὴν τῆς χρείας, ἵνα δῷ χάριν τοῖς ἀκούουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 30, 'Καὶ μὴ λυπεῖτε τὸ  ̊Πνεῦμα τὸ Ἅγιον τοῦ  ̊Θεοῦ, ἐν ᾧ ἐσφραγίσθητε εἰς ἡμέραν ἀπολυτρώσεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 31, 'Πᾶσα πικρία, καὶ θυμὸς, καὶ ὀργὴ, καὶ κραυγὴ, καὶ βλασφημία, ἀρθήτω ἀφʼ ὑμῶν σὺν πάσῃ κακίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 32, 'Γίνεσθε εἰς ἀλλήλους χρηστοί, εὔσπλαγχνοι, χαριζόμενοι ἑαυτοῖς, καθὼς καὶ ὁ  ̊Θεὸς ἐν  ̊Χριστῷ ἐχαρίσατο ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 1, 'Γίνεσθε οὖν μιμηταὶ τοῦ  ̊Θεοῦ ὡς τέκνα ἀγαπητά,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 2, 'καὶ περιπατεῖτε ἐν ἀγάπῃ, καθὼς καὶ ὁ  ̊Χριστὸς ἠγάπησεν ὑμᾶς, καὶ παρέδωκεν ἑαυτὸν ὑπὲρ ἡμῶν, προσφορὰν καὶ θυσίαν τῷ  ̊Θεῷ εἰς ὀσμὴν εὐωδίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 3, '¶Πορνεία δὲ, καὶ ἀκαθαρσία πᾶσα, ἢ πλεονεξία, μηδὲ ὀνομαζέσθω ἐν ὑμῖν, καθὼς πρέπει ἁγίοις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 4, 'καὶ αἰσχρότης, καὶ μωρολογία, ἢ εὐτραπελία, ἃ οὐκ ἀνῆκεν, ἀλλὰ μᾶλλον εὐχαριστία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 5, 'Τοῦτο γὰρ ἴστε γινώσκοντες ὅτι πᾶς πόρνος, ἢ ἀκάθαρτος, ἢ πλεονέκτης, ὅ ἐστιν εἰδωλολάτρης, οὐκ ἔχει κληρονομίαν ἐν τῇ βασιλείᾳ τοῦ  ̊Χριστοῦ καὶ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 6, '¶Μηδεὶς ὑμᾶς ἀπατάτω κενοῖς λόγοις διὰ ταῦτα, γὰρ ἔρχεται ἡ ὀργὴ τοῦ  ̊Θεοῦ ἐπὶ τοὺς υἱοὺς τῆς ἀπειθείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 7, 'Μὴ οὖν γίνεσθε συμμέτοχοι αὐτῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 8, 'ἦτε γάρ ποτε σκότος, νῦν δὲ φῶς ἐν  ̊Κυρίῳ· ὡς τέκνα φωτὸς περιπατεῖτε');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 9, '(ὁ γὰρ καρπὸς τοῦ φωτὸς ἐν πάσῃ ἀγαθωσύνῃ, καὶ δικαιοσύνῃ, καὶ ἀληθείᾳ),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 10, 'δοκιμάζοντες τί ἐστιν εὐάρεστον τῷ  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 11, 'Καὶ μὴ συγκοινωνεῖτε τοῖς ἔργοις τοῖς ἀκάρποις τοῦ σκότους, μᾶλλον δὲ καὶ ἐλέγχετε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 12, 'τὰ γὰρ κρυφῇ γινόμενα ὑπʼ αὐτῶν, αἰσχρόν ἐστιν καὶ λέγειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 13, 'Τὰ δὲ πάντα ἐλεγχόμενα ὑπὸ τοῦ φωτὸς φανεροῦται, πᾶν γὰρ τὸ φανερούμενον φῶς ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 14, 'Διὸ λέγει, “Ἔγειρε, ὁ καθεύδων, καὶ ἀνάστα ἐκ τῶν νεκρῶν, καὶ ἐπιφαύσει σοι ὁ  ̊Χριστός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 15, '¶Βλέπετε οὖν ἀκριβῶς πῶς περιπατεῖτε, μὴ ὡς ἄσοφοι, ἀλλʼ ὡς σοφοί,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 16, 'ἐξαγοραζόμενοι τὸν καιρόν, ὅτι αἱ ἡμέραι πονηραί εἰσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 17, 'Διὰ τοῦτο, μὴ γίνεσθε ἄφρονες, ἀλλὰ συνίετε τί τὸ θέλημα τοῦ  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 18, 'Καὶ μὴ μεθύσκεσθε οἴνῳ, ἐν ᾧ ἐστιν ἀσωτία, ἀλλὰ πληροῦσθε ἐν  ̊Πνεύματι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 19, 'λαλοῦντες ἑαυτοῖς ἐν ψαλμοῖς, καὶ ὕμνοις, καὶ ᾠδαῖς πνευματικαῖς, ᾄδοντες καὶ ψάλλοντες τῇ καρδίᾳ ὑμῶν τῷ  ̊Κυρίῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 20, 'εὐχαριστοῦντες πάντοτε ὑπὲρ πάντων ἐν ὀνόματι τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, τῷ  ̊Θεῷ καὶ Πατρί,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 21, 'ὑποτασσόμενοι ἀλλήλοις ἐν φόβῳ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 22, '¶Αἱ γυναῖκες τοῖς ἰδίοις ἀνδράσιν ὡς τῷ  ̊Κυρίῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 23, 'ὅτι ἀνήρ ἐστιν κεφαλὴ τῆς γυναικὸς, ὡς καὶ ὁ  ̊Χριστὸς κεφαλὴ τῆς ἐκκλησίας, αὐτὸς Σωτὴρ τοῦ σώματος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 24, 'Ἀλλʼ ὡς ἡ ἐκκλησία ὑποτάσσεται τῷ  ̊Χριστῷ, οὕτως καὶ αἱ γυναῖκες τοῖς ἀνδράσιν ἐν παντί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 25, '¶Οἱ ἄνδρες ἀγαπᾶτε τὰς γυναῖκας, καθὼς καὶ ὁ  ̊Χριστὸς ἠγάπησεν τὴν ἐκκλησίαν, καὶ ἑαυτὸν παρέδωκεν ὑπὲρ αὐτῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 26, 'ἵνα αὐτὴν ἁγιάσῃ, καθαρίσας τῷ λουτρῷ τοῦ ὕδατος ἐν ῥήματι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 27, 'ἵνα παραστήσῃ αὐτὸς ἑαυτῷ ἔνδοξον τὴν ἐκκλησίαν, μὴ ἔχουσαν σπίλον, ἢ ῥυτίδα, ἤ τι τῶν τοιούτων, ἀλλʼ ἵνα ᾖ ἁγία καὶ ἄμωμος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 28, 'Οὕτως ὀφείλουσιν καὶ οἱ ἄνδρες ἀγαπᾶν τὰς ἑαυτῶν γυναῖκας, ὡς τὰ ἑαυτῶν σώματα. Ὁ ἀγαπῶν τὴν ἑαυτοῦ γυναῖκα, ἑαυτὸν ἀγαπᾷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 29, 'Οὐδεὶς γάρ ποτε τὴν ἑαυτοῦ σάρκα ἐμίσησεν, ἀλλὰ ἐκτρέφει καὶ θάλπει αὐτήν, καθὼς καὶ ὁ  ̊Χριστὸς τὴν ἐκκλησίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 30, 'ὅτι μέλη ἐσμὲν τοῦ σώματος αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 31, '“Ἀντὶ τούτου καταλείψει ἄνθρωπος τὸν πατέρα καὶ τὴν μητέρα, καὶ προσκολληθήσεται τῇ γυναικὶ αὐτοῦ, καὶ ἔσονται οἱ δύο εἰς σάρκα μίαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 32, 'Τὸ μυστήριον τοῦτο μέγα ἐστίν, ἐγὼ δὲ λέγω εἰς  ̊Χριστὸν καὶ εἰς τὴν ἐκκλησίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 33, 'Πλὴν καὶ ὑμεῖς, οἱ καθʼ ἕνα, ἕκαστος τὴν ἑαυτοῦ γυναῖκα οὕτως ἀγαπάτω ὡς ἑαυτόν, ἡ δὲ γυνὴ, ἵνα φοβῆται τὸν ἄνδρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 1, '¶Τὰ τέκνα, ὑπακούετε τοῖς γονεῦσιν ὑμῶν ἐν  ̊Κυρίῳ, τοῦτο γάρ ἐστιν δίκαιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 2, '“Τίμα τὸν πατέρα σου καὶ τὴν μητέρα” (ἥτις ἐστὶν ἐντολὴ πρώτη ἐν ἐπαγγελίᾳ),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 3, '“ἵνα εὖ σοι γένηται, καὶ ἔσῃ μακροχρόνιος ἐπὶ τῆς γῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 4, '¶Καὶ, οἱ πατέρες, μὴ παροργίζετε τὰ τέκνα ὑμῶν, ἀλλὰ ἐκτρέφετε αὐτὰ ἐν παιδείᾳ καὶ νουθεσίᾳ  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 5, '¶Οἱ δοῦλοι, ὑπακούετε τοῖς κατὰ σάρκα κυρίοις μετὰ φόβου καὶ τρόμου, ἐν ἁπλότητι τῆς καρδίας ὑμῶν ὡς τῷ  ̊Χριστῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 6, 'μὴ κατʼ ὀφθαλμοδουλείαν ὡς ἀνθρωπάρεσκοι, ἀλλʼ ὡς δοῦλοι  ̊Χριστοῦ, ποιοῦντες τὸ θέλημα τοῦ  ̊Θεοῦ ἐκ ψυχῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 7, 'μετʼ εὐνοίας δουλεύοντες ὡς τῷ  ̊Κυρίῳ, καὶ οὐκ ἀνθρώποις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 8, 'εἰδότες ὅτι ἐάν ποιήσῃ ἕκαστος ἀγαθόν, τοῦτο κομίσεται παρὰ  ̊Κυρίου, εἴτε δοῦλος εἴτε ἐλεύθερος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 9, '¶Καὶ, οἱ κύριοι, τὰ αὐτὰ ποιεῖτε πρὸς αὐτούς, ἀνιέντες τὴν ἀπειλήν, εἰδότες ὅτι καὶ αὐτῶν καὶ ὑμῶν ὁ  ̊Κύριός ἐστιν ἐν οὐρανοῖς, καὶ προσωπολημψία οὐκ ἔστιν παρʼ αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 10, '¶Τοῦ λοιποῦ, δυναμοῦσθε, ἐν  ̊Κυρίῳ καὶ ἐν τῷ κράτει τῆς ἰσχύος αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 11, 'Ἐνδύσασθε τὴν πανοπλίαν τοῦ  ̊Θεοῦ, πρὸς τὸ δύνασθαι ὑμᾶς στῆναι πρὸς τὰς μεθοδείας τοῦ διαβόλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 12, 'Ὅτι οὐκ ἔστιν ἡμῖν ἡ πάλη πρὸς αἷμα καὶ σάρκα, ἀλλὰ πρὸς τὰς ἀρχάς, πρὸς τὰς ἐξουσίας, πρὸς τοὺς κοσμοκράτορας τοῦ σκότους τούτου, πρὸς τὰ πνευματικὰ τῆς πονηρίας ἐν τοῖς ἐπουρανίοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 13, 'Διὰ τοῦτο, ἀναλάβετε τὴν πανοπλίαν τοῦ  ̊Θεοῦ, ἵνα δυνηθῆτε ἀντιστῆναι ἐν τῇ ἡμέρᾳ τῇ πονηρᾷ, καὶ ἅπαντα κατεργασάμενοι, στῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 14, 'Στῆτε οὖν, “περιζωσάμενοι τὴν ὀσφὺν ὑμῶν ἐν ἀληθείᾳ”, καὶ “ἐνδυσάμενοι τὸν θώρακα τῆς δικαιοσύνης”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 15, 'καὶ ὑποδησάμενοι τοὺς “πόδας ἐν ἑτοιμασίᾳ τοῦ εὐαγγελίου τῆς εἰρήνης”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 16, 'Ἐν πᾶσιν ἀναλαβόντες τὸν θυρεὸν τῆς πίστεως, ἐν ᾧ δυνήσεσθε πάντα τὰ βέλη τοῦ πονηροῦ πεπυρωμένα σβέσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 17, 'Καὶ “τὴν περικεφαλαίαν τοῦ σωτηρίου” δέξασθε, καὶ τὴν μάχαιραν τοῦ  ̊Πνεύματος, ὅ ἐστιν ῥῆμα  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 18, 'διὰ πάσης προσευχῆς καὶ δεήσεως, προσευχόμενοι ἐν παντὶ καιρῷ ἐν  ̊Πνεύματι, καὶ εἰς αὐτὸ, ἀγρυπνοῦντες ἐν πάσῃ προσκαρτερήσει καὶ δεήσει περὶ πάντων τῶν ἁγίων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 19, 'καὶ ὑπὲρ ἐμοῦ, ἵνα μοι δοθῇ λόγος ἐν ἀνοίξει τοῦ στόματός μου, ἐν παρρησίᾳ γνωρίσαι τὸ μυστήριον τοῦ εὐαγγελίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 20, 'ὑπὲρ οὗ πρεσβεύω ἐν ἁλύσει, ἵνα ἐν αὐτῷ παρρησιάσωμαι, ὡς δεῖ με λαλῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 21, '¶Ἵνα δὲ εἰδῆτε καὶ ὑμεῖς τὰ κατʼ ἐμέ, τί πράσσω, πάντα γνωρίσει ὑμῖν Τυχικὸς, ὁ ἀγαπητὸς ἀδελφὸς καὶ πιστὸς διάκονος ἐν  ̊Κυρίῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 22, 'ὃν ἔπεμψα πρὸς ὑμᾶς εἰς αὐτὸ τοῦτο, ἵνα γνῶτε τὰ περὶ ἡμῶν, καὶ παρακαλέσῃ τὰς καρδίας ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 23, '¶Εἰρήνη τοῖς ἀδελφοῖς καὶ ἀγάπη μετὰ πίστεως ἀπὸ  ̊Θεοῦ Πατρὸς καὶ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 6, 24, 'Ἡ χάρις μετὰ πάντων τῶν ἀγαπώντων τὸν  ̊Κύριον ἡμῶν,  ̊Ἰησοῦν  ̊Χριστὸν, ἐν ἀφθαρσίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 1, '¶Παῦλος καὶ Τιμόθεος, δοῦλοι  ̊Χριστοῦ  ̊Ἰησοῦ· πᾶσιν τοῖς ἁγίοις ἐν  ̊Χριστῷ  ̊Ἰησοῦ τοῖς οὖσιν ἐν Φιλίπποις, σὺν ἐπισκόποις καὶ διακόνοις:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 2, 'χάρις ὑμῖν καὶ εἰρήνη ἀπὸ  ̊Θεοῦ Πατρὸς ἡμῶν καὶ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 3, '¶Εὐχαριστῶ τῷ  ̊Θεῷ μου ἐπὶ πάσῃ τῇ μνείᾳ ὑμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 4, 'πάντοτε ἐν πάσῃ δεήσει μου ὑπὲρ πάντων ὑμῶν, μετὰ χαρᾶς τὴν δέησιν ποιούμενος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 5, 'ἐπὶ τῇ κοινωνίᾳ ὑμῶν εἰς τὸ εὐαγγέλιον, ἀπὸ τῆς πρώτης ἡμέρας ἄχρι τοῦ νῦν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 6, 'πεποιθὼς αὐτὸ τοῦτο, ὅτι ὁ ἐναρξάμενος ἐν ὑμῖν ἔργον ἀγαθὸν, ἐπιτελέσει ἄχρι ἡμέρας  ̊Χριστοῦ  ̊Ἰησοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 7, 'καθώς ἐστιν δίκαιον ἐμοὶ τοῦτο φρονεῖν ὑπὲρ πάντων ὑμῶν, διὰ τὸ ἔχειν με ἐν τῇ καρδίᾳ ὑμᾶς, ἔν τε τοῖς δεσμοῖς μου, καὶ ἐν τῇ ἀπολογίᾳ καὶ βεβαιώσει τοῦ εὐαγγελίου, συγκοινωνούς μου τῆς χάριτος πάντας ὑμᾶς ὄντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 8, 'Μάρτυς γάρ μου ὁ  ̊Θεός, ὡς ἐπιποθῶ πάντας ὑμᾶς ἐν σπλάγχνοις  ̊Χριστοῦ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 9, 'Καὶ τοῦτο προσεύχομαι, ἵνα ἡ ἀγάπη ὑμῶν ἔτι μᾶλλον καὶ μᾶλλον περισσεύῃ ἐν ἐπιγνώσει καὶ πάσῃ αἰσθήσει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 10, 'εἰς τὸ δοκιμάζειν ὑμᾶς τὰ διαφέροντα, ἵνα ἦτε εἰλικρινεῖς καὶ ἀπρόσκοποι εἰς ἡμέραν  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 11, 'πεπληρωμένοι καρπὸν δικαιοσύνης τὸν διὰ  ̊Ἰησοῦ  ̊Χριστοῦ, εἰς δόξαν καὶ ἔπαινον  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 12, '¶Γινώσκειν δὲ ὑμᾶς, βούλομαι, ἀδελφοί, ὅτι τὰ κατʼ ἐμὲ, μᾶλλον εἰς προκοπὴν τοῦ εὐαγγελίου ἐλήλυθεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 13, 'ὥστε τοὺς δεσμούς μου φανεροὺς ἐν  ̊Χριστῷ γενέσθαι, ἐν ὅλῳ τῷ πραιτωρίῳ καὶ τοῖς λοιποῖς πᾶσιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 14, 'καὶ τοὺς πλείονας τῶν ἀδελφῶν ἐν  ̊Κυρίῳ πεποιθότας τοῖς δεσμοῖς μου, περισσοτέρως τολμᾶν ἀφόβως τὸν λόγον τοῦ  ̊Θεοῦ λαλεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 15, '¶Τινὲς μὲν καὶ διὰ φθόνον καὶ ἔριν, τινὲς δὲ καὶ διʼ εὐδοκίαν τὸν  ̊Χριστὸν κηρύσσουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 16, 'Οἱ δὲ ἐξ ἐριθείας τὸν  ̊Χριστὸν καταγγέλλουσιν, οὐχ ἁγνῶς οἰόμενοι θλῖψιν ἐγείρειν τοῖς δεσμοῖς μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 17, 'Οἱ μὲν ἐξ ἀγάπης εἰδότες ὅτι εἰς ἀπολογίαν τοῦ εὐαγγελίου κεῖμαι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 18, 'τί γάρ; Πλὴν ὅτι παντὶ τρόπῳ, εἴτε προφάσει εἴτε ἀληθείᾳ,  ̊Χριστὸς καταγγέλλεται, καὶ ἐν τούτῳ χαίρω, ἀλλὰ καὶ χαρήσομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 19, 'Οἶδα γὰρ ὅτι τοῦτό μοι ἀποβήσεται εἰς σωτηρίαν διὰ τῆς ὑμῶν δεήσεως, καὶ ἐπιχορηγίας τοῦ  ̊Πνεύματος  ̊Ἰησοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 20, 'κατὰ τὴν ἀποκαραδοκίαν καὶ ἐλπίδα μου, ὅτι ἐν οὐδενὶ αἰσχυνθήσομαι, ἀλλʼ ἐν πάσῃ παρρησίᾳ, ὡς πάντοτε καὶ νῦν, μεγαλυνθήσεται  ̊Χριστὸς ἐν τῷ σώματί μου, εἴτε διὰ ζωῆς εἴτε διὰ θανάτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 21, 'Ἐμοὶ γὰρ τὸ ζῆν  ̊Χριστὸς, καὶ τὸ ἀποθανεῖν κέρδος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 22, 'Εἰ δὲ τὸ ζῆν ἐν σαρκί, τοῦτό μοι καρπὸς ἔργου. Καὶ τί αἱρήσομαι οὐ γνωρίζω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 23, 'Συνέχομαι δὲ ἐκ τῶν δύο, τὴν ἐπιθυμίαν ἔχων εἰς τὸ ἀναλῦσαι καὶ σὺν  ̊Χριστῷ εἶναι, πολλῷ γὰρ μᾶλλον κρεῖσσον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 24, 'τὸ δὲ ἐπιμένειν ἐν τῇ σαρκὶ, ἀναγκαιότερον διʼ ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 25, 'Καὶ τοῦτο πεποιθὼς, οἶδα ὅτι μενῶ καὶ παραμενῶ πᾶσιν ὑμῖν εἰς τὴν ὑμῶν προκοπὴν καὶ χαρὰν τῆς πίστεως,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 26, 'ἵνα τὸ καύχημα ὑμῶν περισσεύῃ ἐν  ̊Χριστῷ  ̊Ἰησοῦ ἐν ἐμοὶ, διὰ τῆς ἐμῆς παρουσίας πάλιν πρὸς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 27, '¶Μόνον ἀξίως τοῦ εὐαγγελίου τοῦ  ̊Χριστοῦ πολιτεύεσθε, ἵνα εἴτε ἐλθὼν καὶ ἰδὼν ὑμᾶς, εἴτε ἀπὼν, ἀκούω τὰ περὶ ὑμῶν, ὅτι στήκετε ἐν ἑνὶ πνεύματι, μιᾷ ψυχῇ συναθλοῦντες τῇ πίστει τοῦ εὐαγγελίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 28, 'καὶ μὴ πτυρόμενοι ἐν μηδενὶ ὑπὸ τῶν ἀντικειμένων, ἥτις ἐστὶν αὐτοῖς ἔνδειξις ἀπωλείας, ὑμῶν δὲ σωτηρίας, καὶ τοῦτο ἀπὸ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 29, 'ὅτι ὑμῖν ἐχαρίσθη τὸ ὑπὲρ  ̊Χριστοῦ, οὐ μόνον τὸ εἰς αὐτὸν πιστεύειν, ἀλλὰ καὶ τὸ ὑπὲρ αὐτοῦ πάσχειν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 30, 'τὸν αὐτὸν ἀγῶνα ἔχοντες, οἷον εἴδετε ἐν ἐμοὶ, καὶ νῦν ἀκούετε ἐν ἐμοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 1, '¶Εἴ τις οὖν παράκλησις ἐν  ̊Χριστῷ, εἴ τι παραμύθιον ἀγάπης, εἴ τις κοινωνία  ̊Πνεύματος, εἴ τις σπλάγχνα καὶ οἰκτιρμοί,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 2, 'πληρώσατέ μου τὴν χαρὰν, ἵνα τὸ αὐτὸ φρονῆτε, τὴν αὐτὴν ἀγάπην ἔχοντες, σύμψυχοι, τὸ ἓν φρονοῦντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 3, 'Μηδὲν κατʼ ἐριθείαν μηδὲ κατὰ κενοδοξίαν, ἀλλὰ τῇ ταπεινοφροσύνῃ ἀλλήλους ἡγούμενοι ὑπερέχοντας ἑαυτῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 4, 'μὴ τὰ ἑαυτῶν ἕκαστος σκοποῦντες, ἀλλὰ καὶ τὰ ἑτέρων ἕκαστοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 5, 'Τοῦτο φρονεῖτε ἐν ὑμῖν, ὃ καὶ ἐν  ̊Χριστῷ  ̊Ἰησοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 6, 'ὃς ἐν μορφῇ  ̊Θεοῦ ὑπάρχων, οὐχ ἁρπαγμὸν ἡγήσατο τὸ εἶναι ἴσα  ̊Θεῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 7, 'ἀλλὰ ἑαυτὸν ἐκένωσεν, μορφὴν δούλου λαβών, ἐν ὁμοιώματι ἀνθρώπων γενόμενος. Καὶ σχήματι εὑρεθεὶς ὡς ἄνθρωπος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 8, 'ἐταπείνωσεν ἑαυτὸν, γενόμενος ὑπήκοος μέχρι θανάτου, θανάτου δὲ σταυροῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 9, 'Διὸ καὶ ὁ  ̊Θεὸς αὐτὸν ὑπερύψωσεν, καὶ ἐχαρίσατο αὐτῷ τὸ ὄνομα τὸ ὑπὲρ πᾶν ὄνομα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 10, 'ἵνα ἐν τῷ ὀνόματι  ̊Ἰησοῦ, πᾶν γόνυ κάμψῃ ἐπουρανίων καὶ ἐπιγείων καὶ καταχθονίων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 11, 'καὶ πᾶσα γλῶσσα ἐξομολογήσηται ὅτι  ̊Κύριος  ̊Ἰησοῦς  ̊Χριστὸς, εἰς δόξαν  ̊Θεοῦ Πατρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 12, '¶Ὥστε, ἀγαπητοί μου, καθὼς πάντοτε ὑπηκούσατε, μὴ ὡς ἐν τῇ παρουσίᾳ μου μόνον, ἀλλὰ νῦν πολλῷ μᾶλλον ἐν τῇ ἀπουσίᾳ μου, μετὰ φόβου καὶ τρόμου τὴν ἑαυτῶν σωτηρίαν κατεργάζεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 13, ' ̊Θεὸς γάρ ἐστιν ὁ ἐνεργῶν ἐν ὑμῖν, καὶ τὸ θέλειν, καὶ τὸ ἐνεργεῖν, ὑπὲρ τῆς εὐδοκίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 14, '¶Πάντα ποιεῖτε χωρὶς γογγυσμῶν καὶ διαλογισμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 15, 'ἵνα γένησθε ἄμεμπτοι καὶ ἀκέραιοι, τέκνα  ̊Θεοῦ ἄμωμα μέσον γενεᾶς σκολιᾶς καὶ διεστραμμένης, ἐν οἷς φαίνεσθε ὡς φωστῆρες ἐν κόσμῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 16, 'λόγον ζωῆς ἐπέχοντες εἰς καύχημα ἐμοὶ εἰς ἡμέραν  ̊Χριστοῦ, ὅτι οὐκ εἰς κενὸν ἔδραμον, οὐδὲ εἰς κενὸν ἐκοπίασα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 17, 'ἀλλʼ εἰ καὶ σπένδομαι ἐπὶ τῇ θυσίᾳ καὶ λειτουργίᾳ τῆς πίστεως ὑμῶν, χαίρω καὶ συγχαίρω πᾶσιν ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 18, 'Τὸ δὲ αὐτὸ καὶ ὑμεῖς χαίρετε καὶ συγχαίρετέ μοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 19, '¶Ἐλπίζω δὲ ἐν  ̊Κυρίῳ  ̊Ἰησοῦ, Τιμόθεον ταχέως πέμψαι ὑμῖν, ἵνα κἀγὼ εὐψυχῶ, γνοὺς τὰ περὶ ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 20, 'Οὐδένα γὰρ ἔχω ἰσόψυχον, ὅστις γνησίως τὰ περὶ ὑμῶν μεριμνήσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 21, 'Οἱ πάντες γὰρ τὰ ἑαυτῶν ζητοῦσιν, οὐ τὰ  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 22, 'Τὴν δὲ δοκιμὴν αὐτοῦ γινώσκετε, ὅτι ὡς πατρὶ τέκνον, σὺν ἐμοὶ ἐδούλευσεν εἰς τὸ εὐαγγέλιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 23, 'Τοῦτον μὲν οὖν ἐλπίζω πέμψαι, ὡς ἂν ἀφίδω τὰ περὶ ἐμὲ ἐξαυτῆς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 24, 'πέποιθα δὲ ἐν  ̊Κυρίῳ ὅτι καὶ αὐτὸς ταχέως ἐλεύσομαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 25, '¶Ἀναγκαῖον δὲ ἡγησάμην, Ἐπαφρόδιτον, τὸν ἀδελφὸν καὶ συνεργὸν καὶ συστρατιώτην μου, ὑμῶν δὲ ἀπόστολον καὶ λειτουργὸν τῆς χρείας μου, πέμψαι πρὸς ὑμᾶς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 26, 'ἐπειδὴ ἐπιποθῶν ἦν πάντας ὑμᾶς, καὶ ἀδημονῶν διότι ἠκούσατε ὅτι ἠσθένησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 27, 'Καὶ γὰρ ἠσθένησεν παραπλήσιον θανάτῳ, ἀλλὰ ὁ  ̊Θεὸς ἠλέησεν αὐτόν, οὐκ αὐτὸν δὲ μόνον, ἀλλὰ καὶ ἐμέ, ἵνα μὴ λύπην ἐπὶ λύπην σχῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 28, 'Σπουδαιοτέρως οὖν ἔπεμψα αὐτὸν, ἵνα ἰδόντες αὐτὸν πάλιν, χαρῆτε κἀγὼ ἀλυπότερος ὦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 29, 'Προσδέχεσθε οὖν αὐτὸν ἐν  ̊Κυρίῳ μετὰ πάσης χαρᾶς, καὶ τοὺς τοιούτους ἐντίμους ἔχετε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 30, 'ὅτι διὰ τὸ ἔργον  ̊Χριστοῦ μέχρι θανάτου ἤγγισεν, παραβολευσάμενος τῇ ψυχῇ, ἵνα ἀναπληρώσῃ τὸ ὑμῶν ὑστέρημα, τῆς πρός με λειτουργίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 1, '¶Τὸ λοιπόν, ἀδελφοί μου, χαίρετε ἐν  ̊Κυρίῳ. Τὰ αὐτὰ γράφειν ὑμῖν, ἐμοὶ μὲν οὐκ ὀκνηρόν, ὑμῖν δὲ ἀσφαλές.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 2, '¶Βλέπετε τοὺς κύνας, βλέπετε τοὺς κακοὺς ἐργάτας, βλέπετε τὴν κατατομήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 3, 'Ἡμεῖς γάρ ἐσμεν ἡ περιτομή, οἱ  ̊Πνεύματι  ̊Θεοῦ λατρεύοντες καὶ καυχώμενοι ἐν  ̊Χριστῷ  ̊Ἰησοῦ, καὶ οὐκ ἐν σαρκὶ πεποιθότες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 4, 'καίπερ ἐγὼ ἔχων πεποίθησιν καὶ ἐν σαρκί. ¶Εἴ τις δοκεῖ ἄλλος πεποιθέναι ἐν σαρκί, ἐγὼ μᾶλλον:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 5, 'περιτομῇ ὀκταήμερος ἐκ γένους Ἰσραήλ φυλῆς Βενιαμίν, Ἑβραῖος ἐξ Ἑβραίων, κατὰ νόμον Φαρισαῖος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 6, 'κατὰ ζῆλος διώκων τὴν ἐκκλησίαν, κατὰ δικαιοσύνην τὴν ἐν νόμῳ γενόμενος ἄμεμπτος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 7, 'Ἀλλὰ ἅτινα ἦν μοι κέρδη, ταῦτα ἥγημαι διὰ τὸν  ̊Χριστὸν ζημίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 8, 'Ἀλλὰ μενοῦνγε καὶ ἡγοῦμαι πάντα ζημίαν εἶναι, διὰ τὸ ὑπερέχον τῆς γνώσεως  ̊Χριστοῦ  ̊Ἰησοῦ τοῦ  ̊Κυρίου μου, διʼ ὃν τὰ πάντα ἐζημιώθην καὶ ἡγοῦμαι σκύβαλα, ἵνα  ̊Χριστὸν κερδήσω');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 9, 'καὶ εὑρεθῶ ἐν αὐτῷ, μὴ ἔχων ἐμὴν δικαιοσύνην τὴν ἐκ νόμου, ἀλλὰ τὴν διὰ πίστεως  ̊Χριστοῦ, τὴν ἐκ  ̊Θεοῦ δικαιοσύνην ἐπὶ τῇ πίστει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 10, 'τοῦ γνῶναι αὐτὸν, καὶ τὴν δύναμιν τῆς ἀναστάσεως αὐτοῦ, καὶ κοινωνίαν παθημάτων αὐτοῦ, συμμορφιζόμενος τῷ θανάτῳ αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 11, 'εἴ πως καταντήσω εἰς τὴν ἐξανάστασιν τὴν ἐκ νεκρῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 12, '¶Οὐχ ὅτι ἤδη ἔλαβον, ἢ ἤδη τετελείωμαι, διώκω δὲ, εἰ καὶ καταλάβω, ἐφʼ ᾧ καὶ κατελήμφθην ὑπὸ  ̊Χριστοῦ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 13, 'Ἀδελφοί, ἐγὼ ἐμαυτὸν οὐ λογίζομαι κατειληφέναι, ἓν δέ: τὰ μὲν ὀπίσω ἐπιλανθανόμενος, τοῖς δὲ ἔμπροσθεν ἐπεκτεινόμενος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 14, 'κατὰ σκοπὸν διώκω εἰς τὸ βραβεῖον τῆς ἄνω κλήσεως τοῦ  ̊Θεοῦ ἐν  ̊Χριστῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 15, 'Ὅσοι οὖν τέλειοι, τοῦτο φρονῶμεν· καὶ εἴ τι ἑτέρως φρονεῖτε, καὶ τοῦτο ὁ  ̊Θεὸς ὑμῖν ἀποκαλύψει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 16, 'Πλὴν εἰς ὃ ἐφθάσαμεν, τῷ αὐτῷ στοιχεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 17, '¶Συμμιμηταί μου γίνεσθε, ἀδελφοί, καὶ σκοπεῖτε τοὺς οὕτω περιπατοῦντας, καθὼς ἔχετε τύπον ἡμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 18, 'Πολλοὶ γὰρ περιπατοῦσιν, οὓς πολλάκις ἔλεγον ὑμῖν, νῦν δὲ καὶ κλαίων, λέγω, τοὺς ἐχθροὺς τοῦ σταυροῦ τοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 19, 'ὧν τὸ τέλος ἀπώλεια, ὧν ὁ  ̊Θεὸς ἡ κοιλία, καὶ ἡ δόξα ἐν τῇ αἰσχύνῃ αὐτῶν, οἱ τὰ ἐπίγεια φρονοῦντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 20, 'Ἡμῶν γὰρ τὸ πολίτευμα ἐν οὐρανοῖς ὑπάρχει, ἐξ οὗ καὶ Σωτῆρα ἀπεκδεχόμεθα,  ̊Κύριον  ̊Ἰησοῦν  ̊Χριστόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 21, 'ὃς μετασχηματίσει τὸ σῶμα τῆς ταπεινώσεως ἡμῶν, σύμμορφον τῷ σώματι τῆς δόξης αὐτοῦ, κατὰ τὴν ἐνέργειαν τοῦ δύνασθαι αὐτὸν, καὶ ὑποτάξαι αὑτῷ τὰ πάντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 1, 'Ὥστε, ἀδελφοί μου ἀγαπητοὶ καὶ ἐπιπόθητοι, χαρὰ καὶ στέφανός μου, οὕτως στήκετε ἐν  ̊Κυρίῳ, ἀγαπητοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 2, '¶Εὐοδίαν παρακαλῶ, καὶ Συντύχην παρακαλῶ, τὸ αὐτὸ φρονεῖν ἐν  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 3, 'Ναὶ, ἐρωτῶ καὶ σέ, γνήσιε σύζυγε, συλλαμβάνου αὐταῖς, αἵτινες ἐν τῷ εὐαγγελίῳ συνήθλησάν μοι, μετὰ καὶ Κλήμεντος καὶ τῶν λοιπῶν συνεργῶν μου, ὧν τὰ ὀνόματα ἐν βίβλῳ ζωῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 4, '¶Χαίρετε ἐν  ̊Κυρίῳ πάντοτε, πάλιν ἐρῶ, χαίρετε!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 5, 'Τὸ ἐπιεικὲς ὑμῶν γνωσθήτω πᾶσιν ἀνθρώποις. Ὁ  ̊Κύριος ἐγγύς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 6, 'Μηδὲν μεριμνᾶτε, ἀλλʼ ἐν παντὶ, τῇ προσευχῇ καὶ τῇ δεήσει μετὰ εὐχαριστίας, τὰ αἰτήματα ὑμῶν γνωριζέσθω πρὸς τὸν  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 7, 'Καὶ ἡ εἰρήνη τοῦ  ̊Θεοῦ ἡ ὑπερέχουσα πάντα νοῦν, φρουρήσει τὰς καρδίας ὑμῶν καὶ τὰ νοήματα ὑμῶν ἐν  ̊Χριστῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 8, '¶Τὸ λοιπόν, ἀδελφοί, ὅσα ἐστὶν ἀληθῆ, ὅσα σεμνά, ὅσα δίκαια, ὅσα ἁγνά, ὅσα προσφιλῆ, ὅσα εὔφημα, εἴ τις ἀρετὴ, καὶ εἴ τις ἔπαινος, ταῦτα λογίζεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 9, 'Ἃ καὶ ἐμάθετε καὶ παρελάβετε, καὶ ἠκούσατε καὶ εἴδετε, ἐν ἐμοί, ταῦτα πράσσετε· καὶ ὁ  ̊Θεὸς τῆς εἰρήνης ἔσται μεθʼ ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 10, '¶Ἐχάρην δὲ ἐν  ̊Κυρίῳ μεγάλως, ὅτι ἤδη ποτὲ ἀνεθάλετε τὸ ὑπὲρ ἐμοῦ φρονεῖν, ἐφʼ ᾧ καὶ ἐφρονεῖτε, ἠκαιρεῖσθε δέ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 11, 'Οὐχ ὅτι καθʼ ὑστέρησιν λέγω, ἐγὼ γὰρ ἔμαθον ἐν οἷς εἰμι αὐτάρκης εἶναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 12, 'Οἶδα καὶ ταπεινοῦσθαι, οἶδα καὶ περισσεύειν. Ἐν παντὶ καὶ ἐν πᾶσιν μεμύημαι, καὶ χορτάζεσθαι καὶ πεινᾶν, καὶ περισσεύειν καὶ ὑστερεῖσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 13, 'Πάντα ἰσχύω ἐν τῷ ἐνδυναμοῦντί με.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 14, 'Πλὴν καλῶς ἐποιήσατε, συγκοινωνήσαντές μου τῇ θλίψει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 15, '¶Οἴδατε δὲ καὶ ὑμεῖς, Φιλιππήσιοι, ὅτι ἐν ἀρχῇ τοῦ εὐαγγελίου, ὅτε ἐξῆλθον ἀπὸ Μακεδονίας, οὐδεμία μοι ἐκκλησία ἐκοινώνησεν εἰς λόγον δόσεως καὶ λήμψεως, εἰ μὴ ὑμεῖς μόνοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 16, 'Ὅτι καὶ ἐν Θεσσαλονίκῃ, καὶ ἅπαξ καὶ δὶς, εἰς τὴν χρείαν μοι ἐπέμψατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 17, 'Οὐχ ὅτι ἐπιζητῶ τὸ δόμα, ἀλλὰ ἐπιζητῶ τὸν καρπὸν τὸν πλεονάζοντα εἰς λόγον ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 18, 'Ἀπέχω δὲ πάντα, καὶ περισσεύω· πεπλήρωμαι, δεξάμενος παρὰ Ἐπαφροδίτου τὰ παρʼ ὑμῶν, ὀσμὴν εὐωδίας, θυσίαν δεκτήν, εὐάρεστον τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 19, 'Ὁ δὲ  ̊Θεός μου πληρώσει πᾶσαν χρείαν ὑμῶν, κατὰ τὸ πλοῦτος αὐτοῦ ἐν δόξῃ ἐν  ̊Χριστῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 20, 'Τῷ δὲ  ̊Θεῷ καὶ Πατρὶ ἡμῶν ἡ δόξα εἰς τοὺς αἰῶνας τῶν αἰώνων. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 21, '¶Ἀσπάσασθε πάντα ἅγιον ἐν  ̊Χριστῷ  ̊Ἰησοῦ, ἀσπάζονται ὑμᾶς οἱ σὺν ἐμοὶ ἀδελφοί,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 22, 'ἀσπάζονται ὑμᾶς πάντες οἱ ἅγιοι, μάλιστα δὲ οἱ ἐκ τῆς Καίσαρος οἰκίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 23, 'Ἡ χάρις τοῦ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ μετὰ τοῦ πνεύματος ὑμῶν. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 1, '¶Παῦλος, ἀπόστολος  ̊Χριστοῦ  ̊Ἰησοῦ διὰ θελήματος  ̊Θεοῦ, καὶ Τιμόθεος ὁ ἀδελφὸς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 2, 'τοῖς ἐν Κολοσσαῖς ἁγίοις, καὶ πιστοῖς ἀδελφοῖς ἐν  ̊Χριστῷ: χάρις ὑμῖν καὶ εἰρήνη ἀπὸ  ̊Θεοῦ Πατρὸς ἡμῶν καὶ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 3, '¶Εὐχαριστοῦμεν τῷ  ̊Θεῷ Πατρὶ τοῦ  ̊Κυρίου ἡμῶν  ̊Ἰησοῦ  ̊Χριστοῦ, πάντοτε περὶ ὑμῶν προσευχόμενοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 4, 'ἀκούσαντες τὴν πίστιν ὑμῶν ἐν  ̊Χριστῷ  ̊Ἰησοῦ, καὶ τὴν ἀγάπην ἣν ἔχετε εἰς πάντας τοὺς ἁγίους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 5, 'διὰ τὴν ἐλπίδα τὴν ἀποκειμένην ὑμῖν ἐν τοῖς οὐρανοῖς, ἣν προηκούσατε ἐν τῷ λόγῳ τῆς ἀληθείας, τοῦ εὐαγγελίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 6, 'τοῦ παρόντος εἰς ὑμᾶς, καθὼς καὶ ἐν παντὶ τῷ κόσμῳ, ἐστὶν καρποφορούμενον καὶ αὐξανόμενον, καθὼς καὶ ἐν ὑμῖν, ἀφʼ ἧς ἡμέρας ἠκούσατε καὶ ἐπέγνωτε τὴν χάριν τοῦ  ̊Θεοῦ ἐν ἀληθείᾳ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 7, 'καθὼς ἐμάθετε ἀπὸ Ἐπαφρᾶ, τοῦ ἀγαπητοῦ συνδούλου ἡμῶν, ὅς ἐστιν πιστὸς ὑπὲρ ἡμῶν διάκονος τοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 8, 'ὁ καὶ δηλώσας ἡμῖν τὴν ὑμῶν ἀγάπην ἐν  ̊Πνεύματι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 9, '¶Διὰ τοῦτο καὶ ἡμεῖς, ἀφʼ ἧς ἡμέρας ἠκούσαμεν, οὐ παυόμεθα ὑπὲρ ὑμῶν προσευχόμενοι καὶ αἰτούμενοι, ἵνα πληρωθῆτε τὴν ἐπίγνωσιν τοῦ θελήματος αὐτοῦ ἐν πάσῃ σοφίᾳ καὶ συνέσει πνευματικῇ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 10, 'περιπατῆσαι ἀξίως τοῦ  ̊Κυρίου εἰς πᾶσαν ἀρεσκείαν, ἐν παντὶ ἔργῳ ἀγαθῷ καρποφοροῦντες, καὶ αὐξανόμενοι τῇ ἐπιγνώσει τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 11, 'ἐν πάσῃ δυνάμει δυναμούμενοι, κατὰ τὸ κράτος τῆς δόξης αὐτοῦ, εἰς πᾶσαν ὑπομονὴν καὶ μακροθυμίαν μετὰ χαρᾶς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 12, 'εὐχαριστοῦντες τῷ Πατρὶ, τῷ ἱκανώσαντι ὑμᾶς εἰς τὴν μερίδα τοῦ κλήρου τῶν ἁγίων ἐν τῷ φωτί,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 13, 'ὃς ἐρρύσατο ἡμᾶς ἐκ τῆς ἐξουσίας τοῦ σκότους, καὶ μετέστησεν εἰς τὴν βασιλείαν τοῦ Υἱοῦ τῆς ἀγάπης αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 14, 'ἐν ᾧ ἔχομεν τὴν ἀπολύτρωσιν, τὴν ἄφεσιν τῶν ἁμαρτιῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 15, 'ὅς ἐστιν εἰκὼν τοῦ  ̊Θεοῦ τοῦ ἀοράτου, πρωτότοκος πάσης κτίσεως,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 16, 'ὅτι ἐν αὐτῷ ἐκτίσθη τὰ πάντα ἐν τοῖς οὐρανοῖς καὶ ἐπὶ τῆς γῆς, τὰ ὁρατὰ καὶ τὰ ἀόρατα, εἴτε θρόνοι, εἴτε κυριότητες, εἴτε ἀρχαὶ, εἴτε ἐξουσίαι· τὰ πάντα διʼ αὐτοῦ καὶ εἰς αὐτὸν ἔκτισται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 17, 'Καὶ αὐτός ἐστιν πρὸ πάντων, καὶ τὰ πάντα ἐν αὐτῷ συνέστηκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 18, 'Καὶ αὐτός ἐστιν ἡ κεφαλὴ τοῦ σώματος, τῆς ἐκκλησίας, ὅς ἐστιν ἡ ἀρχή, πρωτότοκος ἐκ τῶν νεκρῶν, ἵνα γένηται ἐν πᾶσιν αὐτὸς πρωτεύων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 19, 'ὅτι ἐν αὐτῷ εὐδόκησεν πᾶν τὸ πλήρωμα κατοικῆσαι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 20, 'καὶ διʼ αὐτοῦ ἀποκαταλλάξαι τὰ πάντα εἰς αὐτόν, εἰρηνοποιήσας διὰ τοῦ αἵματος τοῦ σταυροῦ αὐτοῦ διʼ αὐτοῦ, εἴτε τὰ ἐπὶ τῆς γῆς, εἴτε τὰ ἐν τοῖς οὐρανοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 21, 'Καὶ ὑμᾶς ποτε ὄντας ἀπηλλοτριωμένους καὶ ἐχθροὺς τῇ διανοίᾳ ἐν τοῖς ἔργοις τοῖς πονηροῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 22, 'νυνὶ δὲ ἀποκατηλλάγητε ἐν τῷ σώματι τῆς σαρκὸς αὐτοῦ, διὰ τοῦ θανάτου, παραστῆσαι ὑμᾶς ἁγίους, καὶ ἀμώμους, καὶ ἀνεγκλήτους, κατενώπιον αὐτοῦ–');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 23, 'εἴ γε ἐπιμένετε τῇ πίστει, τεθεμελιωμένοι καὶ ἑδραῖοι, καὶ μὴ μετακινούμενοι ἀπὸ τῆς ἐλπίδος τοῦ εὐαγγελίου οὗ ἠκούσατε, τοῦ κηρυχθέντος ἐν πάσῃ κτίσει τῇ ὑπὸ τὸν οὐρανόν, οὗ ἐγενόμην ἐγὼ Παῦλος διάκονος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 24, '¶Νῦν χαίρω ἐν τοῖς παθήμασιν ὑπὲρ ὑμῶν, καὶ ἀνταναπληρῶ τὰ ὑστερήματα τῶν θλίψεων τοῦ  ̊Χριστοῦ ἐν τῇ σαρκί μου ὑπὲρ τοῦ σώματος αὐτοῦ, ὅ ἐστιν ἡ ἐκκλησία,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 25, 'ἧς ἐγενόμην ἐγὼ διάκονος, κατὰ τὴν οἰκονομίαν τοῦ  ̊Θεοῦ, τὴν δοθεῖσάν μοι εἰς ὑμᾶς πληρῶσαι τὸν λόγον τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 26, 'τὸ μυστήριον τὸ ἀποκεκρυμμένον ἀπὸ τῶν αἰώνων καὶ ἀπὸ τῶν γενεῶν, νῦν δὲ ἐφανερώθη τοῖς ἁγίοις αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 27, 'οἷς ἠθέλησεν ὁ  ̊Θεὸς, γνωρίσαι τί τὸ πλοῦτος τῆς δόξης τοῦ μυστηρίου τούτου ἐν τοῖς ἔθνεσιν, ὅ ἐστιν  ̊Χριστὸς ἐν ὑμῖν, ἡ ἐλπὶς τῆς δόξης·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 28, 'ὃν ἡμεῖς καταγγέλλομεν, νουθετοῦντες πάντα ἄνθρωπον καὶ διδάσκοντες πάντα ἄνθρωπον ἐν πάσῃ σοφίᾳ, ἵνα παραστήσωμεν πάντα ἄνθρωπον τέλειον ἐν  ̊Χριστῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 29, 'Εἰς ὃ καὶ κοπιῶ, ἀγωνιζόμενος κατὰ τὴν ἐνέργειαν αὐτοῦ, τὴν ἐνεργουμένην ἐν ἐμοὶ ἐν δυνάμει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 1, '¶Θέλω γὰρ ὑμᾶς εἰδέναι, ἡλίκον ἀγῶνα ἔχω ὑπὲρ ὑμῶν καὶ τῶν ἐν Λαοδικείᾳ, καὶ ὅσοι οὐχ ἑόρακαν τὸ πρόσωπόν μου ἐν σαρκί,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 2, 'ἵνα παρακληθῶσιν αἱ καρδίαι αὐτῶν, συμβιβασθέντες ἐν ἀγάπῃ, καὶ εἰς πᾶν πλοῦτος τῆς πληροφορίας τῆς συνέσεως, εἰς ἐπίγνωσιν τοῦ μυστηρίου τοῦ  ̊Θεοῦ,  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 3, 'ἐν ᾧ εἰσιν πάντες οἱ θησαυροὶ τῆς σοφίας καὶ γνώσεως ἀπόκρυφοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 4, 'Τοῦτο λέγω, ἵνα μηδεὶς ὑμᾶς παραλογίζηται ἐν πιθανολογίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 5, 'Εἰ γὰρ καὶ τῇ σαρκὶ ἄπειμι, ἀλλὰ τῷ πνεύματι σὺν ὑμῖν εἰμι, χαίρων καὶ βλέπων ὑμῶν τὴν τάξιν, καὶ τὸ στερέωμα τῆς εἰς  ̊Χριστὸν πίστεως ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 6, '¶Ὡς οὖν παρελάβετε τὸν  ̊Χριστὸν  ̊Ἰησοῦν τὸν  ̊Κύριον, ἐν αὐτῷ περιπατεῖτε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 7, 'ἐρριζωμένοι καὶ ἐποικοδομούμενοι ἐν αὐτῷ, καὶ βεβαιούμενοι τῇ πίστει, καθὼς ἐδιδάχθητε, περισσεύοντες ἐν εὐχαριστίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 8, '¶Βλέπετε, μή τις ὑμᾶς ἔσται ὁ συλαγωγῶν διὰ τῆς φιλοσοφίας καὶ κενῆς ἀπάτης, κατὰ τὴν παράδοσιν τῶν ἀνθρώπων, κατὰ τὰ στοιχεῖα τοῦ κόσμου, καὶ οὐ κατὰ  ̊Χριστόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 9, 'Ὅτι ἐν αὐτῷ κατοικεῖ πᾶν τὸ πλήρωμα τῆς Θεότητος σωματικῶς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 10, 'καὶ ἐστὲ ἐν αὐτῷ πεπληρωμένοι, ὅς ἐστιν ἡ κεφαλὴ πάσης ἀρχῆς καὶ ἐξουσίας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 11, 'ἐν ᾧ καὶ περιετμήθητε περιτομῇ ἀχειροποιήτῳ, ἐν τῇ ἀπεκδύσει τοῦ σώματος τῆς σαρκός, ἐν τῇ περιτομῇ τοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 12, 'συνταφέντες αὐτῷ ἐν τῷ βαπτισμῷ, ἐν ᾧ καὶ συνηγέρθητε, διὰ τῆς πίστεως τῆς ἐνεργείας τοῦ  ̊Θεοῦ, τοῦ ἐγείραντος αὐτὸν ἐκ νεκρῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 13, 'Καὶ ὑμᾶς νεκροὺς ὄντας ἐν τοῖς παραπτώμασιν καὶ τῇ ἀκροβυστίᾳ τῆς σαρκὸς ὑμῶν, συνεζωοποίησεν ἡμᾶς σὺν αὐτῷ, χαρισάμενος ἡμῖν πάντα τὰ παραπτώματα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 14, 'ἐξαλείψας τὸ καθʼ ἡμῶν χειρόγραφον τοῖς δόγμασιν, ὃ ἦν ὑπεναντίον ἡμῖν, καὶ αὐτὸ ἦρκεν ἐκ τοῦ μέσου, προσηλώσας αὐτὸ τῷ σταυρῷ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 15, 'ἀπεκδυσάμενος τὰς ἀρχὰς καὶ τὰς ἐξουσίας, ἐδειγμάτισεν ἐν παρρησίᾳ, θριαμβεύσας αὐτοὺς ἐν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 16, '¶Μὴ οὖν τις ὑμᾶς κρινέτω ἐν βρώσει, καὶ ἐν πόσει, ἢ ἐν μέρει ἑορτῆς, ἢ νεομηνίας, ἢ Σαββάτων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 17, 'ἅ ἐστιν σκιὰ τῶν μελλόντων, τὸ δὲ σῶμα τοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 18, 'Μηδεὶς ὑμᾶς καταβραβευέτω, θέλων ἐν ταπεινοφροσύνῃ, καὶ θρησκείᾳ τῶν ἀγγέλων, ἃ ἑόρακεν ἐμβατεύων, εἰκῇ φυσιούμενος ὑπὸ τοῦ νοὸς τῆς σαρκὸς αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 19, 'καὶ οὐ κρατῶν τὴν κεφαλήν, ἐξ οὗ πᾶν τὸ σῶμα διὰ τῶν ἁφῶν καὶ συνδέσμων ἐπιχορηγούμενον καὶ συμβιβαζόμενον, αὔξει τὴν αὔξησιν τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 20, '¶Εἰ ἀπεθάνετε σὺν  ̊Χριστῷ ἀπὸ τῶν στοιχείων τοῦ κόσμου, τί ὡς ζῶντες ἐν κόσμῳ δογματίζεσθε:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 21, '“Μὴ ἅψῃ! Μηδὲ γεύσῃ! Μηδὲ θίγῃς!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 22, 'Ἅ ἐστιν πάντα εἰς φθορὰν τῇ ἀποχρήσει, κατὰ τὰ ἐντάλματα καὶ διδασκαλίας τῶν ἀνθρώπων;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 23, 'Ἅτινά ἐστιν λόγον μὲν ἔχοντα σοφίας ἐν ἐθελοθρησκίᾳ καὶ ταπεινοφροσύνῃ, καὶ ἀφειδίᾳ σώματος, οὐκ ἐν τιμῇ τινι πρὸς πλησμονὴν τῆς σαρκός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 1, '¶Εἰ οὖν συνηγέρθητε τῷ  ̊Χριστῷ, τὰ ἄνω ζητεῖτε, οὗ ὁ  ̊Χριστός ἐστιν, ἐν δεξιᾷ τοῦ  ̊Θεοῦ καθήμενος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 2, 'Τὰ ἄνω φρονεῖτε, μὴ τὰ ἐπὶ τῆς γῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 3, 'Ἀπεθάνετε γάρ, καὶ ἡ ζωὴ ὑμῶν κέκρυπται σὺν τῷ  ̊Χριστῷ ἐν τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 4, 'Ὅταν ὁ  ̊Χριστὸς φανερωθῇ, ἡ ζωὴ ὑμῶν, τότε καὶ ὑμεῖς σὺν αὐτῷ φανερωθήσεσθε ἐν δόξῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 5, '¶Νεκρώσατε οὖν τὰ μέλη τὰ ἐπὶ τῆς γῆς: πορνείαν, ἀκαθαρσίαν, πάθος, ἐπιθυμίαν κακήν, καὶ τὴν πλεονεξίαν, ἥτις ἐστὶν εἰδωλολατρία,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 6, 'διʼ ἃ ἔρχεται ἡ ὀργὴ τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 7, 'ἐν οἷς καὶ ὑμεῖς περιεπατήσατέ ποτε ὅτε ἐζῆτε ἐν τούτοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 8, 'Νυνὶ δὲ ἀπόθεσθε καὶ ὑμεῖς τὰ πάντα: ὀργήν, θυμόν, κακίαν, βλασφημίαν, αἰσχρολογίαν ἐκ τοῦ στόματος ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 9, 'Μὴ ψεύδεσθε εἰς ἀλλήλους, ἀπεκδυσάμενοι τὸν παλαιὸν ἄνθρωπον σὺν ταῖς πράξεσιν αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 10, 'καὶ ἐνδυσάμενοι τὸν νέον, τὸν ἀνακαινούμενον εἰς ἐπίγνωσιν, κατʼ εἰκόνα τοῦ κτίσαντος αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 11, 'ὅπου οὐκ ἔνι Ἕλλην καὶ Ἰουδαῖος, περιτομὴ καὶ ἀκροβυστία, βάρβαρος, Σκύθης, δοῦλος, ἐλεύθερος, ἀλλὰ πάντα καὶ ἐν πᾶσιν  ̊Χριστός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 12, '¶Ἐνδύσασθε οὖν, ὡς ἐκλεκτοὶ τοῦ  ̊Θεοῦ ἅγιοι καὶ ἠγαπημένοι, σπλάγχνα οἰκτιρμοῦ, χρηστότητα, ταπεινοφροσύνην, πραΰτητα, μακροθυμίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 13, 'ἀνεχόμενοι ἀλλήλων καὶ χαριζόμενοι ἑαυτοῖς, ἐάν τις πρός τινα ἔχῃ μομφήν· καθὼς καὶ ὁ  ̊Κύριος ἐχαρίσατο ὑμῖν, οὕτως καὶ ὑμεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 14, 'Ἐπὶ πᾶσιν δὲ τούτοις, τὴν ἀγάπην, ὅ ἐστιν σύνδεσμος τῆς τελειότητος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 15, 'Καὶ ἡ εἰρήνη τοῦ  ̊Χριστοῦ βραβευέτω ἐν ταῖς καρδίαις ὑμῶν, εἰς ἣν καὶ ἐκλήθητε ἐν ἑνὶ σώματι· καὶ εὐχάριστοι γίνεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 16, 'Ὁ λόγος τοῦ  ̊Χριστοῦ ἐνοικείτω ἐν ὑμῖν πλουσίως ἐν πάσῃ σοφίᾳ, διδάσκοντες καὶ νουθετοῦντες ἑαυτοὺς ψαλμοῖς, ὕμνοις, ᾠδαῖς πνευματικαῖς, ἐν τῇ χάριτι ᾄδοντες ἐν ταῖς καρδίαις ὑμῶν τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 17, 'Καὶ πᾶν, ὅ τι ἐὰν ποιῆτε ἐν λόγῳ ἢ ἐν ἔργῳ, πάντα ἐν ὀνόματι  ̊Κυρίου  ̊Ἰησοῦ, εὐχαριστοῦντες τῷ  ̊Θεῷ Πατρὶ διʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 18, '¶Αἱ γυναῖκες, ὑποτάσσεσθε τοῖς ἀνδράσιν, ὡς ἀνῆκεν ἐν  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 19, 'Οἱ ἄνδρες, ἀγαπᾶτε τὰς γυναῖκας, καὶ μὴ πικραίνεσθε πρὸς αὐτάς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 20, '¶Τὰ τέκνα, ὑπακούετε τοῖς γονεῦσιν κατὰ πάντα, τοῦτο γὰρ εὐάρεστόν ἐστιν ἐν  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 21, 'Οἱ πατέρες, μὴ ἐρεθίζετε τὰ τέκνα ὑμῶν, ἵνα μὴ ἀθυμῶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 22, 'Οἱ δοῦλοι, ὑπακούετε κατὰ πάντα τοῖς κατὰ σάρκα κυρίοις, μὴ ἐν ὀφθαλμοδουλεία, ὡς ἀνθρωπάρεσκοι, ἀλλʼ ἐν ἁπλότητι καρδίας, φοβούμενοι τὸν  ̊Κύριον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 23, 'Ὃ ἐὰν ποιῆτε, ἐκ ψυχῆς ἐργάζεσθε, ὡς τῷ  ̊Κυρίῳ καὶ οὐκ ἀνθρώποις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 24, 'εἰδότες ὅτι ἀπὸ  ̊Κυρίου ἀπολήμψεσθε τὴν ἀνταπόδοσιν τῆς κληρονομίας. Τῷ  ̊Κυρίῳ  ̊Χριστῷ δουλεύετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 25, 'Ὁ γὰρ ἀδικῶν, κομιεῖται ὃ ἠδίκησεν, καὶ οὐκ ἔστιν προσωπολημψία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 1, 'Οἱ κύριοι, τὸ δίκαιον καὶ τὴν ἰσότητα τοῖς δούλοις παρέχεσθε, εἰδότες ὅτι καὶ ὑμεῖς ἔχετε  ̊Κύριον ἐν οὐρανῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 2, '¶Τῇ προσευχῇ προσκαρτερεῖτε, γρηγοροῦντες ἐν αὐτῇ ἐν εὐχαριστίᾳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 3, 'προσευχόμενοι ἅμα καὶ περὶ ἡμῶν, ἵνα ὁ  ̊Θεὸς ἀνοίξῃ ἡμῖν θύραν τοῦ λόγου, λαλῆσαι τὸ μυστήριον τοῦ  ̊Χριστοῦ, διʼ ὃ καὶ δέδεμαι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 4, 'ἵνα φανερώσω αὐτὸ, ὡς δεῖ με λαλῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 5, '¶Ἐν σοφίᾳ περιπατεῖτε πρὸς τοὺς ἔξω, τὸν καιρὸν ἐξαγοραζόμενοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 6, 'Ὁ λόγος ὑμῶν πάντοτε ἐν χάριτι, ἅλατι ἠρτυμένος, εἰδέναι πῶς δεῖ ὑμᾶς ἑνὶ ἑκάστῳ ἀποκρίνεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 7, '¶Τὰ κατʼ ἐμὲ πάντα γνωρίσει ὑμῖν Τυχικὸς, ὁ ἀγαπητὸς ἀδελφὸς, καὶ πιστὸς διάκονος, καὶ σύνδουλος ἐν  ̊Κυρίῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 8, 'ὃν ἔπεμψα πρὸς ὑμᾶς εἰς αὐτὸ τοῦτο, ἵνα γνῶτε τὰ περὶ ὑμῶν, καὶ παρακαλέσῃ τὰς καρδίας ὑμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 9, 'σὺν Ὀνησίμῳ, τῷ πιστῷ καὶ ἀγαπητῷ ἀδελφῷ, ὅς ἐστιν ἐξ ὑμῶν. Πάντα ὑμῖν γνωρίσουσιν τὰ ὧδε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 10, '¶Ἀσπάζεται ὑμᾶς Ἀρίσταρχος, ὁ συναιχμάλωτός μου, καὶ Μᾶρκος, ὁ ἀνεψιὸς Βαρναβᾶ (περὶ οὗ ἐλάβετε ἐντολάς, ἐὰν ἔλθῃ πρὸς ὑμᾶς, δέξασθε αὐτόν),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 11, 'καὶ Ἰησοῦς, ὁ λεγόμενος Ἰοῦστος, οἱ ὄντες ἐκ περιτομῆς οὗτοι, μόνοι συνεργοὶ εἰς τὴν Βασιλείαν τοῦ  ̊Θεοῦ, οἵτινες ἐγενήθησάν μοι παρηγορία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 12, 'Ἀσπάζεται ὑμᾶς Ἐπαφρᾶς, ὁ ἐξ ὑμῶν, δοῦλος  ̊Χριστοῦ  ̊Ἰησοῦ, πάντοτε ἀγωνιζόμενος ὑπὲρ ὑμῶν ἐν ταῖς προσευχαῖς, ἵνα σταθῆτε τέλειοι καὶ πεπληροφορημένοι ἐν παντὶ θελήματι τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 13, 'Μαρτυρῶ γὰρ αὐτῷ ὅτι ἔχει πολὺν πόνον ὑπὲρ ὑμῶν, καὶ τῶν ἐν Λαοδικείᾳ, καὶ τῶν ἐν Ἱεραπόλει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 14, 'Ἀσπάζεται ὑμᾶς Λουκᾶς, ὁ ἰατρὸς ὁ ἀγαπητὸς, καὶ Δημᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 15, 'Ἀσπάσασθε τοὺς ἐν Λαοδικείᾳ ἀδελφοὺς, καὶ Νύμφαν, καὶ τὴν κατʼ οἶκον αὐτῶν ἐκκλησίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 16, 'Καὶ ὅταν ἀναγνωσθῇ παρʼ ὑμῖν ἡ ἐπιστολή, ποιήσατε ἵνα καὶ ἐν τῇ Λαοδικέων ἐκκλησίᾳ ἀναγνωσθῇ, καὶ τὴν ἐκ Λαοδικείας ἵνα καὶ ὑμεῖς ἀναγνῶτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 17, 'Καὶ εἴπατε Ἀρχίππῳ, “Βλέπε τὴν διακονίαν ἣν παρέλαβες ἐν  ̊Κυρίῳ, ἵνα αὐτὴν πληροῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 18, '¶Ὁ ἀσπασμὸς τῇ ἐμῇ χειρὶ, Παύλου. Μνημονεύετέ μου τῶν δεσμῶν. Ἡ χάρις μεθʼ ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 1, '¶Παῦλος, καὶ Σιλουανὸς, καὶ Τιμόθεος, τῇ ἐκκλησίᾳ Θεσσαλονικέων ἐν  ̊Θεῷ Πατρὶ καὶ  ̊Κυρίῳ  ̊Ἰησοῦ  ̊Χριστῷ: χάρις ὑμῖν καὶ εἰρήνη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 2, '¶Εὐχαριστοῦμεν τῷ  ̊Θεῷ πάντοτε περὶ πάντων ὑμῶν, μνείαν ποιούμενοι ἐπὶ τῶν προσευχῶν ἡμῶν, ἀδιαλείπτως');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 3, 'μνημονεύοντες ὑμῶν τοῦ ἔργου τῆς πίστεως, καὶ τοῦ κόπου τῆς ἀγάπης, καὶ τῆς ὑπομονῆς τῆς ἐλπίδος τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, ἔμπροσθεν τοῦ  ̊Θεοῦ καὶ Πατρὸς ἡμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 4, 'εἰδότες, ἀδελφοὶ ἠγαπημένοι ὑπὸ τοῦ  ̊Θεοῦ, τὴν ἐκλογὴν ὑμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 5, 'ὅτι τὸ εὐαγγέλιον ἡμῶν οὐκ ἐγενήθη εἰς ὑμᾶς ἐν λόγῳ μόνον, ἀλλὰ καὶ ἐν δυνάμει, καὶ ἐν  ̊Πνεύματι Ἁγίῳ, καὶ πληροφορίᾳ πολλῇ, καθὼς οἴδατε οἷοι ἐγενήθημεν ὑμῖν διʼ ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 6, 'Καὶ ὑμεῖς μιμηταὶ ἡμῶν ἐγενήθητε καὶ τοῦ  ̊Κυρίου, δεξάμενοι τὸν λόγον ἐν θλίψει πολλῇ μετὰ χαρᾶς  ̊Πνεύματος Ἁγίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 7, 'ὥστε γενέσθαι ὑμᾶς τύπους πᾶσιν τοῖς πιστεύουσιν ἐν τῇ Μακεδονίᾳ καὶ ἐν τῇ Ἀχαΐᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 8, 'Ἀφʼ ὑμῶν γὰρ ἐξήχηται ὁ λόγος τοῦ  ̊Κυρίου, οὐ μόνον ἐν τῇ Μακεδονίᾳ καὶ ἐν τῇ Ἀχαΐᾳ, ἀλλʼ ἐν παντὶ τόπῳ ἡ πίστις ὑμῶν ἡ πρὸς τὸν  ̊Θεὸν ἐξελήλυθεν, ὥστε μὴ χρείαν ἔχειν ἡμᾶς λαλεῖν τι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 9, 'Αὐτοὶ γὰρ περὶ ἡμῶν ἀπαγγέλλουσιν ὁποίαν εἴσοδον ἔσχομεν πρὸς ὑμᾶς, καὶ πῶς ἐπεστρέψατε πρὸς τὸν  ̊Θεὸν ἀπὸ τῶν εἰδώλων, δουλεύειν  ̊Θεῷ ζῶντι καὶ ἀληθινῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 10, 'καὶ ἀναμένειν τὸν Υἱὸν αὐτοῦ ἐκ τῶν οὐρανῶν, ὃν ἤγειρεν ἐκ τῶν νεκρῶν,  ̊Ἰησοῦν, τὸν ῥυόμενον ἡμᾶς ἐκ τῆς ὀργῆς τῆς ἐρχομένης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 1, '¶Αὐτοὶ γὰρ οἴδατε, ἀδελφοί, τὴν εἴσοδον ἡμῶν τὴν πρὸς ὑμᾶς, ὅτι οὐ κενὴ γέγονεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 2, 'ἀλλὰ προπαθόντες καὶ ὑβρισθέντες, καθὼς οἴδατε, ἐν Φιλίπποις ἐπαρρησιασάμεθα ἐν τῷ  ̊Θεῷ ἡμῶν, λαλῆσαι πρὸς ὑμᾶς τὸ εὐαγγέλιον τοῦ  ̊Θεοῦ ἐν πολλῷ ἀγῶνι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 3, 'Ἡ γὰρ παράκλησις ἡμῶν οὐκ ἐκ πλάνης, οὐδὲ ἐξ ἀκαθαρσίας, οὐδὲ ἐν δόλῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 4, 'ἀλλὰ καθὼς δεδοκιμάσμεθα ὑπὸ τοῦ  ̊Θεοῦ, πιστευθῆναι τὸ εὐαγγέλιον, οὕτως λαλοῦμεν, οὐχ ὡς ἀνθρώποις ἀρέσκοντες, ἀλλὰ  ̊Θεῷ, τῷ δοκιμάζοντι τὰς καρδίας ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 5, 'Οὔτε γάρ ποτε ἐν λόγῳ κολακείας ἐγενήθημεν, καθὼς οἴδατε, οὔτε ἐν προφάσει πλεονεξίας ( ̊Θεὸς μάρτυς)');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 6, 'οὔτε ζητοῦντες ἐξ ἀνθρώπων δόξαν, οὔτε ἀφʼ ὑμῶν, οὔτε ἀπʼ ἄλλων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 7, 'δυνάμενοι ἐν βάρει εἶναι, ὡς  ̊Χριστοῦ ἀπόστολοι. Ἀλλὰ ἐγενήθημεν νήπιοι ἐν μέσῳ ὑμῶν, ὡς ἐὰν τροφὸς θάλπῃ τὰ ἑαυτῆς τέκνα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 8, 'Οὕτως ὁμειρόμενοι ὑμῶν, εὐδοκοῦμεν μεταδοῦναι ὑμῖν, οὐ μόνον τὸ εὐαγγέλιον τοῦ  ̊Θεοῦ, ἀλλὰ καὶ τὰς ἑαυτῶν ψυχάς, διότι ἀγαπητοὶ ἡμῖν ἐγενήθητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 9, '¶Μνημονεύετε γάρ, ἀδελφοί, τὸν κόπον ἡμῶν καὶ τὸν μόχθον· νυκτὸς καὶ ἡμέρας ἐργαζόμενοι, πρὸς τὸ μὴ ἐπιβαρῆσαί τινα ὑμῶν, ἐκηρύξαμεν εἰς ὑμᾶς τὸ εὐαγγέλιον τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 10, 'Ὑμεῖς μάρτυρες καὶ ὁ  ̊Θεός, ὡς ὁσίως, καὶ δικαίως, καὶ ἀμέμπτως, ὑμῖν τοῖς πιστεύουσιν ἐγενήθημεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 11, 'καθάπερ οἴδατε ὡς ἕνα ἕκαστον ὑμῶν, ὡς πατὴρ τέκνα ἑαυτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 12, 'παρακαλοῦντες ὑμᾶς, καὶ παραμυθούμενοι, καὶ μαρτυρόμενοι, εἰς τὸ περιπατεῖν ὑμᾶς ἀξίως τοῦ  ̊Θεοῦ, τοῦ καλέσαντος ὑμᾶς εἰς τὴν ἑαυτοῦ βασιλείαν καὶ δόξαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 13, '¶Καὶ διὰ τοῦτο καὶ ἡμεῖς εὐχαριστοῦμεν τῷ  ̊Θεῷ ἀδιαλείπτως ὅτι παραλαβόντες λόγον ἀκοῆς παρʼ ἡμῶν τοῦ  ̊Θεοῦ, ἐδέξασθε οὐ λόγον ἀνθρώπων, ἀλλὰ καθὼς ἀληθῶς ἐστὶν, λόγον  ̊Θεοῦ, ὃς καὶ ἐνεργεῖται ἐν ὑμῖν τοῖς πιστεύουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 14, 'Ὑμεῖς γὰρ μιμηταὶ ἐγενήθητε, ἀδελφοί, τῶν ἐκκλησιῶν τοῦ  ̊Θεοῦ, τῶν οὐσῶν ἐν τῇ Ἰουδαίᾳ ἐν  ̊Χριστῷ  ̊Ἰησοῦ, ὅτι τὰ αὐτὰ ἐπάθετε, καὶ ὑμεῖς ὑπὸ τῶν ἰδίων συμφυλετῶν, καθὼς καὶ αὐτοὶ ὑπὸ τῶν Ἰουδαίων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 15, 'τῶν καὶ τὸν  ̊Κύριον ἀποκτεινάντων  ̊Ἰησοῦν, καὶ τοὺς προφήτας, καὶ ἡμᾶς ἐκδιωξάντων, καὶ  ̊Θεῷ μὴ ἀρεσκόντων, καὶ πᾶσιν ἀνθρώποις ἐναντίων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 16, 'κωλυόντων ἡμᾶς τοῖς ἔθνεσιν λαλῆσαι, ἵνα σωθῶσιν, εἰς τὸ ἀναπληρῶσαι αὐτῶν τὰς ἁμαρτίας πάντοτε. Ἔφθασεν δὲ ἐπʼ αὐτοὺς ἡ ὀργὴ εἰς τέλος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 17, '¶Ἡμεῖς δέ, ἀδελφοί, ἀπορφανισθέντες ἀφʼ ὑμῶν, πρὸς καιρὸν ὥρας, προσώπῳ οὐ καρδίᾳ, περισσοτέρως ἐσπουδάσαμεν τὸ πρόσωπον ὑμῶν ἰδεῖν ἐν πολλῇ ἐπιθυμίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 18, 'Διότι ἠθελήσαμεν ἐλθεῖν πρὸς ὑμᾶς, ἐγὼ μὲν Παῦλος, καὶ ἅπαξ καὶ δίς, καὶ ἐνέκοψεν ἡμᾶς ὁ Σατανᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 19, 'Τίς γὰρ ἡμῶν ἐλπὶς ἢ χαρὰ ἢ στέφανος καυχήσεως; Ἢ οὐχὶ καὶ ὑμεῖς, ἔμπροσθεν τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ, ἐν τῇ αὐτοῦ παρουσίᾳ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 20, 'Ὑμεῖς γάρ ἐστε ἡ δόξα ἡμῶν, καὶ ἡ χαρά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 1, '¶Διὸ μηκέτι στέγοντες, ηὐδοκήσαμεν καταλειφθῆναι ἐν Ἀθήναις μόνοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 2, 'καὶ ἐπέμψαμεν Τιμόθεον, τὸν ἀδελφὸν ἡμῶν, καὶ διάκονον τοῦ  ̊Θεοῦ ἐν τῷ εὐαγγελίῳ τοῦ  ̊Χριστοῦ, εἰς τὸ στηρίξαι ὑμᾶς καὶ παρακαλέσαι, ὑπὲρ τῆς πίστεως ὑμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 3, 'τὸ μηδένα σαίνεσθαι ἐν ταῖς θλίψεσιν ταύταις. Αὐτοὶ γὰρ οἴδατε ὅτι εἰς τοῦτο κείμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 4, 'Καὶ γὰρ ὅτε πρὸς ὑμᾶς ἦμεν, προελέγομεν ὑμῖν ὅτι μέλλομεν θλίβεσθαι, καθὼς καὶ ἐγένετο καὶ οἴδατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 5, 'Διὰ τοῦτο κἀγὼ μηκέτι στέγων, ἔπεμψα εἰς τὸ γνῶναι τὴν πίστιν ὑμῶν, μή πως ἐπείρασεν ὑμᾶς ὁ πειράζων, καὶ εἰς κενὸν γένηται ὁ κόπος ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 6, '¶Ἄρτι δὲ ἐλθόντος Τιμοθέου πρὸς ἡμᾶς ἀφʼ ὑμῶν, καὶ εὐαγγελισαμένου ἡμῖν τὴν πίστιν καὶ τὴν ἀγάπην ὑμῶν, καὶ ὅτι ἔχετε μνείαν ἡμῶν ἀγαθὴν πάντοτε, ἐπιποθοῦντες ἡμᾶς ἰδεῖν, καθάπερ καὶ ἡμεῖς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 7, 'Διὰ τοῦτο παρεκλήθημεν, ἀδελφοί, ἐφʼ ὑμῖν ἐπὶ πάσῃ τῇ ἀνάγκῃ καὶ θλίψει ἡμῶν, διὰ τῆς ὑμῶν πίστεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 8, 'Ὅτι νῦν ζῶμεν, ἐὰν ὑμεῖς στήκετε ἐν  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 9, 'Τίνα γὰρ εὐχαριστίαν δυνάμεθα τῷ  ̊Θεῷ ἀνταποδοῦναι περὶ ὑμῶν, ἐπὶ πάσῃ τῇ χαρᾷ ᾗ χαίρομεν διʼ ὑμᾶς, ἔμπροσθεν τοῦ  ̊Θεοῦ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 10, 'Νυκτὸς καὶ ἡμέρας, ὑπερεκπερισσοῦ δεόμενοι εἰς τὸ ἰδεῖν ὑμῶν τὸ πρόσωπον, καὶ καταρτίσαι τὰ ὑστερήματα τῆς πίστεως ὑμῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 11, '¶Αὐτὸς δὲ ὁ  ̊Θεὸς καὶ Πατὴρ ἡμῶν, καὶ ὁ  ̊Κύριος ἡμῶν,  ̊Ἰησοῦς, κατευθύναι τὴν ὁδὸν ἡμῶν πρὸς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 12, 'Ὑμᾶς δὲ ὁ  ̊Κύριος πλεονάσαι καὶ περισσεύσαι τῇ ἀγάπῃ εἰς ἀλλήλους, καὶ εἰς πάντας, καθάπερ καὶ ἡμεῖς εἰς ὑμᾶς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 13, 'εἰς τὸ στηρίξαι ὑμῶν τὰς καρδίας, ἀμέμπτους ἐν ἁγιωσύνῃ ἔμπροσθεν τοῦ  ̊Θεοῦ καὶ Πατρὸς ἡμῶν, ἐν τῇ παρουσίᾳ τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ, μετὰ πάντων τῶν ἁγίων αὐτοῦ. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 1, '¶Λοιπὸν οὖν, ἀδελφοί, ἐρωτῶμεν ὑμᾶς καὶ παρακαλοῦμεν ἐν  ̊Κυρίῳ  ̊Ἰησοῦ, καθὼς παρελάβετε παρʼ ἡμῶν, τὸ πῶς δεῖ ὑμᾶς περιπατεῖν καὶ ἀρέσκειν  ̊Θεῷ (καθὼς καὶ περιπατεῖτε), ἵνα περισσεύητε μᾶλλον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 2, 'Οἴδατε γὰρ τίνας παραγγελίας ἐδώκαμεν ὑμῖν διὰ τοῦ  ̊Κυρίου  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 3, 'Τοῦτο γάρ ἐστιν θέλημα τοῦ  ̊Θεοῦ, ὁ ἁγιασμὸς ὑμῶν, ἀπέχεσθαι ὑμᾶς ἀπὸ τῆς πορνείας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 4, 'εἰδέναι ἕκαστον ὑμῶν τὸ ἑαυτοῦ σκεῦος, κτᾶσθαι ἐν ἁγιασμῷ καὶ τιμῇ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 5, 'μὴ ἐν πάθει ἐπιθυμίας, καθάπερ καὶ τὰ ἔθνη τὰ μὴ εἰδότα τὸν  ̊Θεόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 6, 'τὸ μὴ ὑπερβαίνειν καὶ πλεονεκτεῖν ἐν τῷ πράγματι τὸν ἀδελφὸν αὐτοῦ, διότι ἔκδικος  ̊Κύριος περὶ πάντων τούτων, καθὼς καὶ προείπαμεν ὑμῖν καὶ διεμαρτυράμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 7, 'Οὐ γὰρ ἐκάλεσεν ἡμᾶς ὁ  ̊Θεὸς ἐπὶ ἀκαθαρσίᾳ, ἀλλʼ ἐν ἁγιασμῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 8, 'Τοιγαροῦν ὁ ἀθετῶν, οὐκ ἄνθρωπον ἀθετεῖ, ἀλλὰ τὸν  ̊Θεὸν, τὸν διδόντα τὸ  ̊Πνεῦμα αὐτοῦ τὸ Ἅγιον εἰς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 9, '¶Περὶ δὲ τῆς φιλαδελφίας, οὐ χρείαν ἔχετε γράφειν ὑμῖν, αὐτοὶ γὰρ ὑμεῖς θεοδίδακτοί ἐστε, εἰς τὸ ἀγαπᾶν ἀλλήλους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 10, 'Καὶ γὰρ ποιεῖτε αὐτὸ εἰς πάντας τοὺς ἀδελφοὺς, τοὺς ἐν ὅλῃ τῇ Μακεδονίᾳ. Παρακαλοῦμεν δὲ ὑμᾶς, ἀδελφοί, περισσεύειν μᾶλλον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 11, 'καὶ φιλοτιμεῖσθαι ἡσυχάζειν καὶ πράσσειν τὰ ἴδια, καὶ ἐργάζεσθαι ταῖς ἰδίαις χερσὶν ὑμῶν, καθὼς ὑμῖν παρηγγείλαμεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 12, 'ἵνα περιπατῆτε εὐσχημόνως πρὸς τοὺς ἔξω, καὶ μηδενὸς χρείαν ἔχητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 13, '¶Οὐ θέλομεν δὲ ὑμᾶς ἀγνοεῖν, ἀδελφοί, περὶ τῶν κοιμωμένων, ἵνα μὴ λυπῆσθε, καθὼς καὶ οἱ λοιποὶ, οἱ μὴ ἔχοντες ἐλπίδα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 14, 'Εἰ γὰρ πιστεύομεν ὅτι  ̊Ἰησοῦς ἀπέθανεν καὶ ἀνέστη, οὕτως καὶ ὁ  ̊Θεὸς τοὺς κοιμηθέντας διὰ τοῦ  ̊Ἰησοῦ ἄξει σὺν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 15, 'Τοῦτο γὰρ ὑμῖν λέγομεν ἐν λόγῳ  ̊Κυρίου, ὅτι ἡμεῖς οἱ ζῶντες, οἱ περιλειπόμενοι εἰς τὴν παρουσίαν τοῦ  ̊Κυρίου, οὐ μὴ φθάσωμεν τοὺς κοιμηθέντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 16, 'Ὅτι αὐτὸς ὁ  ̊Κύριος ἐν κελεύσματι, ἐν φωνῇ ἀρχαγγέλου, καὶ ἐν σάλπιγγι  ̊Θεοῦ, καταβήσεται ἀπʼ οὐρανοῦ, καὶ οἱ νεκροὶ ἐν  ̊Χριστῷ ἀναστήσονται πρῶτον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 17, 'ἔπειτα ἡμεῖς οἱ ζῶντες, οἱ περιλειπόμενοι ἅμα σὺν αὐτοῖς, ἁρπαγησόμεθα ἐν νεφέλαις εἰς ἀπάντησιν τοῦ  ̊Κυρίου εἰς ἀέρα· καὶ οὕτως πάντοτε σὺν  ̊Κυρίῳ ἐσόμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 18, 'Ὥστε παρακαλεῖτε ἀλλήλους ἐν τοῖς λόγοις τούτοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 1, '¶Περὶ δὲ τῶν χρόνων καὶ τῶν καιρῶν, ἀδελφοί, οὐ χρείαν ἔχετε ὑμῖν γράφεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 2, 'Αὐτοὶ γὰρ ἀκριβῶς οἴδατε ὅτι ἡμέρα  ̊Κυρίου, ὡς κλέπτης ἐν νυκτὶ οὕτως ἔρχεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 3, 'Ὅταν λέγωσιν, “Εἰρήνη καὶ ἀσφάλεια”, τότε αἰφνίδιος ἐπίσταται αὐτοῖς ὄλεθρος, ὥσπερ ἡ ὠδὶν τῇ ἐν γαστρὶ ἐχούσῃ, καὶ οὐ μὴ ἐκφύγωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 4, 'Ὑμεῖς δέ, ἀδελφοί, οὐκ ἐστὲ ἐν σκότει, ἵνα ἡ ἡμέρα ὑμᾶς ὡς κλέπτας καταλάβῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 5, 'Πάντες γὰρ ὑμεῖς υἱοὶ φωτός ἐστε, καὶ υἱοὶ ἡμέρας. Οὐκ ἐσμὲν νυκτὸς οὐδὲ σκότους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 6, 'Ἄρα οὖν μὴ καθεύδωμεν ὡς οἱ λοιποί, ἀλλὰ γρηγορῶμεν καὶ νήφωμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 7, 'Οἱ γὰρ καθεύδοντες, νυκτὸς καθεύδουσιν, καὶ οἱ μεθυσκόμενοι, νυκτὸς μεθύουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 8, 'Ἡμεῖς δὲ ἡμέρας ὄντες, νήφωμεν, ἐνδυσάμενοι θώρακα πίστεως καὶ ἀγάπης, καὶ περικεφαλαίαν, ἐλπίδα σωτηρίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 9, 'Ὅτι οὐκ ἔθετο ἡμᾶς ὁ  ̊Θεὸς εἰς ὀργὴν, ἀλλὰ εἰς περιποίησιν σωτηρίας διὰ τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 10, 'τοῦ ἀποθανόντος περὶ ἡμῶν, ἵνα εἴτε γρηγορῶμεν εἴτε καθεύδωμεν, ἅμα σὺν αὐτῷ ζήσωμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 11, 'Διὸ παρακαλεῖτε ἀλλήλους, καὶ οἰκοδομεῖτε εἷς τὸν ἕνα, καθὼς καὶ ποιεῖτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 12, '¶Ἐρωτῶμεν δὲ ὑμᾶς, ἀδελφοί, εἰδέναι τοὺς κοπιῶντας ἐν ὑμῖν, καὶ προϊσταμένους ὑμῶν ἐν  ̊Κυρίῳ, καὶ νουθετοῦντας ὑμᾶς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 13, 'καὶ ἡγεῖσθαι αὐτοὺς ὑπερεκπερισσοῦ ἐν ἀγάπῃ, διὰ τὸ ἔργον αὐτῶν. Εἰρηνεύετε ἐν ἑαυτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 14, 'Παρακαλοῦμεν δὲ ὑμᾶς, ἀδελφοί, νουθετεῖτε τοὺς ἀτάκτους, παραμυθεῖσθε τοὺς ὀλιγοψύχους, ἀντέχεσθε τῶν ἀσθενῶν, μακροθυμεῖτε πρὸς πάντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 15, 'Ὁρᾶτε μή τις κακὸν ἀντὶ κακοῦ τινι ἀποδῷ, ἀλλὰ πάντοτε τὸ ἀγαθὸν διώκετε, καὶ εἰς ἀλλήλους καὶ εἰς πάντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 16, 'Πάντοτε χαίρετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 17, 'Ἀδιαλείπτως προσεύχεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 18, 'Ἐν παντὶ εὐχαριστεῖτε· τοῦτο γὰρ θέλημα  ̊Θεοῦ ἐν  ̊Χριστῷ  ̊Ἰησοῦ εἰς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 19, 'Τὸ  ̊Πνεῦμα μὴ σβέννυτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 20, 'Προφητείας μὴ ἐξουθενεῖτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 21, 'Πάντα δοκιμάζετε, τὸ καλὸν κατέχετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 22, 'Ἀπὸ παντὸς εἴδους πονηροῦ ἀπέχεσθε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 23, '¶Αὐτὸς δὲ ὁ  ̊Θεὸς τῆς εἰρήνης ἁγιάσαι ὑμᾶς ὁλοτελεῖς, καὶ ὁλόκληρον ὑμῶν τὸ πνεῦμα, καὶ ἡ ψυχὴ, καὶ τὸ σῶμα, ἀμέμπτως ἐν τῇ παρουσίᾳ τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, τηρηθείη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 24, 'Πιστὸς ὁ καλῶν ὑμᾶς, ὃς καὶ ποιήσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 25, '¶Ἀδελφοί, προσεύχεσθε καὶ περὶ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 26, 'Ἀσπάσασθε τοὺς ἀδελφοὺς πάντας ἐν φιλήματι ἁγίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 27, 'Ἐνορκίζω ὑμᾶς τὸν  ̊Κύριον, ἀναγνωσθῆναι τὴν ἐπιστολὴν πᾶσιν τοῖς ἀδελφοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 28, 'Ἡ χάρις τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, μεθʼ ὑμῶν. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 1, '¶Παῦλος, καὶ Σιλουανὸς, καὶ Τιμόθεος· τῇ ἐκκλησίᾳ Θεσσαλονικέων, ἐν  ̊Θεῷ Πατρὶ ἡμῶν καὶ  ̊Κυρίῳ  ̊Ἰησοῦ  ̊Χριστῷ:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 2, 'χάρις ὑμῖν καὶ εἰρήνη ἀπὸ  ̊Θεοῦ Πατρὸς ἡμῶν καὶ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 3, '¶Εὐχαριστεῖν ὀφείλομεν τῷ  ̊Θεῷ πάντοτε περὶ ὑμῶν, ἀδελφοί, καθὼς ἄξιόν ἐστιν, ὅτι ὑπεραυξάνει ἡ πίστις ὑμῶν, καὶ πλεονάζει ἡ ἀγάπη ἑνὸς ἑκάστου, πάντων ὑμῶν, εἰς ἀλλήλους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 4, 'ὥστε αὐτοὺς ἡμᾶς ἐν ὑμῖν ἐγκαυχᾶσθαι, ἐν ταῖς ἐκκλησίαις τοῦ  ̊Θεοῦ, ὑπὲρ τῆς ὑπομονῆς ὑμῶν, καὶ πίστεως ἐν πᾶσιν τοῖς διωγμοῖς ὑμῶν, καὶ ταῖς θλίψεσιν αἷς ἀνέχεσθε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 5, 'ἔνδειγμα τῆς δικαίας κρίσεως τοῦ  ̊Θεοῦ, εἰς τὸ καταξιωθῆναι ὑμᾶς τῆς Βασιλείας τοῦ  ̊Θεοῦ, ὑπὲρ ἧς καὶ πάσχετε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 6, 'εἴπερ δίκαιον παρὰ  ̊Θεῷ, ἀνταποδοῦναι τοῖς θλίβουσιν ὑμᾶς θλῖψιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 7, 'καὶ ὑμῖν τοῖς θλιβομένοις, ἄνεσιν μεθʼ ἡμῶν ἐν τῇ ἀποκαλύψει τοῦ  ̊Κυρίου  ̊Ἰησοῦ ἀπʼ οὐρανοῦ, μετʼ ἀγγέλων δυνάμεως αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 8, 'ἐν πυρὶ φλογός διδόντος ἐκδίκησιν τοῖς μὴ εἰδόσι  ̊Θεὸν, καὶ τοῖς μὴ ὑπακούουσιν τῷ εὐαγγελίῳ τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ,  ̊Χριστοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 9, 'οἵτινες δίκην τίσουσιν ὄλεθρον αἰώνιον, ἀπὸ προσώπου τοῦ  ̊Κυρίου, καὶ ἀπὸ τῆς δόξης τῆς ἰσχύος αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 10, 'ὅταν ἔλθῃ ἐνδοξασθῆναι ἐν τοῖς ἁγίοις αὐτοῦ, καὶ θαυμασθῆναι ἐν πᾶσιν τοῖς πιστεύσασιν, ὅτι ἐπιστεύθη τὸ μαρτύριον ἡμῶν ἐφʼ ὑμᾶς ἐν τῇ ἡμέρᾳ ἐκείνῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 11, 'Εἰς ὃ καὶ προσευχόμεθα πάντοτε περὶ ὑμῶν, ἵνα ὑμᾶς ἀξιώσῃ τῆς κλήσεως ὁ  ̊Θεὸς ἡμῶν, καὶ πληρώσῃ πᾶσαν εὐδοκίαν ἀγαθωσύνης, καὶ ἔργον πίστεως ἐν δυνάμει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 12, 'ὅπως ἐνδοξασθῇ τὸ ὄνομα τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ, ἐν ὑμῖν, καὶ ὑμεῖς ἐν αὐτῷ, κατὰ τὴν χάριν τοῦ  ̊Θεοῦ ἡμῶν καὶ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 1, '¶Ἐρωτῶμεν δὲ ὑμᾶς, ἀδελφοί, ὑπὲρ τῆς παρουσίας τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, καὶ ἡμῶν ἐπισυναγωγῆς ἐπʼ αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 2, 'εἰς τὸ μὴ ταχέως σαλευθῆναι ὑμᾶς ἀπὸ τοῦ νοὸς, μηδὲ θροεῖσθαι, μήτε διὰ πνεύματος, μήτε διὰ λόγου, μήτε διʼ ἐπιστολῆς, ὡς διʼ ἡμῶν, ὡς ὅτι ἐνέστηκεν ἡ ἡμέρα τοῦ  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 3, 'Μή τις ὑμᾶς ἐξαπατήσῃ κατὰ μηδένα τρόπον, ὅτι ἐὰν μὴ ἔλθῃ ἡ ἀποστασία πρῶτον, καὶ ἀποκαλυφθῇ ὁ ἄνθρωπος τῆς ἀνομίας, ὁ υἱὸς τῆς ἀπωλείας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 4, 'ὁ ἀντικείμενος καὶ ὑπεραιρόμενος ἐπὶ πάντα λεγόμενον θεὸν ἢ σέβασμα, ὥστε αὐτὸν εἰς τὸν ναὸν τοῦ  ̊Θεοῦ καθίσαι, ἀποδεικνύντα ἑαυτὸν ὅτι ἔστιν  ̊Θεός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 5, 'Οὐ μνημονεύετε ὅτι ἔτι ὢν πρὸς ὑμᾶς, ταῦτα ἔλεγον ὑμῖν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 6, 'Καὶ νῦν τὸ κατέχον οἴδατε, εἰς τὸ ἀποκαλυφθῆναι αὐτὸν ἐν τῷ αὐτοῦ καιρῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 7, 'Τὸ γὰρ μυστήριον ἤδη ἐνεργεῖται τῆς ἀνομίας· μόνον ὁ κατέχων ἄρτι, ἕως ἐκ μέσου γένηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 8, 'Καὶ τότε ἀποκαλυφθήσεται ὁ ἄνομος, ὃν ὁ  ̊Κύριος  ̊Ἰησοῦς ἀνελεῖ τῷ πνεύματι τοῦ στόματος αὐτοῦ, καὶ καταργήσει τῇ ἐπιφανείᾳ τῆς παρουσίας αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 9, 'οὗ ἐστιν ἡ παρουσία, κατʼ ἐνέργειαν τοῦ Σατανᾶ ἐν πάσῃ δυνάμει, καὶ σημείοις, καὶ τέρασιν ψεύδους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 10, 'καὶ ἐν πάσῃ ἀπάτῃ ἀδικίας, τοῖς ἀπολλυμένοις, ἀνθʼ ὧν τὴν ἀγάπην τῆς ἀληθείας οὐκ ἐδέξαντο, εἰς τὸ σωθῆναι αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 11, 'Καὶ διὰ τοῦτο, πέμπει αὐτοῖς ὁ  ̊Θεὸς ἐνέργειαν πλάνης, εἰς τὸ πιστεῦσαι αὐτοὺς τῷ ψεύδει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 12, 'ἵνα κριθῶσιν ἅπαντες οἱ μὴ πιστεύσαντες τῇ ἀληθείᾳ, ἀλλὰ εὐδοκήσαντες τῇ ἀδικίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 13, '¶Ἡμεῖς δὲ ὀφείλομεν εὐχαριστεῖν τῷ  ̊Θεῷ πάντοτε περὶ ὑμῶν, ἀδελφοὶ ἠγαπημένοι ὑπὸ  ̊Κυρίου, ὅτι εἵλατο ὑμᾶς ὁ  ̊Θεὸς, ἀπʼ ἀρχῆς εἰς σωτηρίαν ἐν ἁγιασμῷ  ̊Πνεύματος καὶ πίστει ἀληθείας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 14, 'εἰς ὃ ἐκάλεσεν ὑμᾶς, διὰ τοῦ εὐαγγελίου ἡμῶν, εἰς περιποίησιν δόξης τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 15, 'Ἄρα οὖν, ἀδελφοί, στήκετε καὶ κρατεῖτε τὰς παραδόσεις ἃς ἐδιδάχθητε, εἴτε διὰ λόγου, εἴτε διʼ ἐπιστολῆς ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 16, '¶Αὐτὸς δὲ ὁ  ̊Κύριος ἡμῶν,  ̊Ἰησοῦς  ̊Χριστὸς, καὶ ὁ  ̊Θεὸς ὁ Πατὴρ ἡμῶν, ὁ ἀγαπήσας ἡμᾶς καὶ δοὺς παράκλησιν αἰωνίαν, καὶ ἐλπίδα ἀγαθὴν ἐν χάριτι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 17, 'παρακαλέσαι ὑμῶν τὰς καρδίας, καὶ στηρίξαι ἐν παντὶ ἔργῳ καὶ λόγῳ ἀγαθῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 1, '¶Τὸ λοιπὸν, προσεύχεσθε, ἀδελφοί, περὶ ἡμῶν, ἵνα ὁ λόγος τοῦ  ̊Κυρίου τρέχῃ καὶ δοξάζηται, καθὼς καὶ πρὸς ὑμᾶς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 2, 'καὶ ἵνα ῥυσθῶμεν ἀπὸ τῶν ἀτόπων καὶ πονηρῶν ἀνθρώπων, οὐ γὰρ πάντων ἡ πίστις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 3, 'Πιστὸς δέ ἐστιν ὁ  ̊Κύριος, ὃς στηρίξει ὑμᾶς, καὶ φυλάξει ἀπὸ τοῦ πονηροῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 4, 'Πεποίθαμεν δὲ ἐν  ̊Κυρίῳ ἐφʼ ὑμᾶς ὅτι ἃ παραγγέλλομεν, καὶ ποιεῖτε καὶ ποιήσετε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 5, 'Ὁ δὲ  ̊Κύριος κατευθύναι ὑμῶν τὰς καρδίας εἰς τὴν ἀγάπην τοῦ  ̊Θεοῦ, καὶ εἰς τὴν ὑπομονὴν τοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 6, '¶Παραγγέλλομεν δὲ ὑμῖν, ἀδελφοί, ἐν ὀνόματι τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, στέλλεσθαι ὑμᾶς ἀπὸ παντὸς ἀδελφοῦ ἀτάκτως περιπατοῦντος, καὶ μὴ κατὰ τὴν παράδοσιν ἣν παρελάβοσαν παρʼ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 7, 'Αὐτοὶ γὰρ οἴδατε πῶς δεῖ μιμεῖσθαι ἡμᾶς, ὅτι οὐκ ἠτακτήσαμεν ἐν ὑμῖν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 8, 'οὐδὲ δωρεὰν ἄρτον ἐφάγομεν παρά τινος, ἀλλʼ ἐν κόπῳ καὶ μόχθῳ, νυκτὸς καὶ ἡμέρας ἐργαζόμενοι, πρὸς τὸ μὴ ἐπιβαρῆσαί τινα ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 9, 'Οὐχ ὅτι οὐκ ἔχομεν ἐξουσίαν, ἀλλʼ ἵνα ἑαυτοὺς τύπον δῶμεν ὑμῖν, εἰς τὸ μιμεῖσθαι ἡμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 10, 'Καὶ γὰρ ὅτε ἦμεν πρὸς ὑμᾶς, τοῦτο παρηγγέλλομεν ὑμῖν, ὅτι εἴ τις οὐ θέλει ἐργάζεσθαι, μηδὲ ἐσθιέτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 11, 'Ἀκούομεν γάρ τινας περιπατοῦντας ἐν ὑμῖν ἀτάκτως, μηδὲν ἐργαζομένους, ἀλλὰ περιεργαζομένους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 12, 'Τοῖς δὲ τοιούτοις παραγγέλλομεν καὶ παρακαλοῦμεν ἐν  ̊Κυρίῳ  ̊Ἰησοῦ  ̊Χριστῷ, ἵνα μετὰ ἡσυχίας ἐργαζόμενοι τὸν ἑαυτῶν ἄρτον ἐσθίωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 13, 'Ὑμεῖς δέ, ἀδελφοί, μὴ ἐγκακήσητε καλοποιοῦντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 14, '¶Εἰ δέ τις οὐχ ὑπακούει τῷ λόγῳ ἡμῶν διὰ τῆς ἐπιστολῆς, τοῦτον σημειοῦσθε, μὴ συναναμίγνυσθαι αὐτῷ, ἵνα ἐντραπῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 15, 'Καὶ μὴ ὡς ἐχθρὸν ἡγεῖσθε, ἀλλὰ νουθετεῖτε ὡς ἀδελφόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 16, '¶Αὐτὸς δὲ ὁ  ̊Κύριος τῆς εἰρήνης, δῴη ὑμῖν τὴν εἰρήνην διὰ παντὸς ἐν παντὶ τρόπῳ. Ὁ  ̊Κύριος μετὰ πάντων ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 17, '¶Ὁ ἀσπασμὸς τῇ ἐμῇ χειρὶ, Παύλου, ὅ ἐστιν σημεῖον ἐν πάσῃ ἐπιστολῇ, οὕτως γράφω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 18, 'Ἡ χάρις τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, μετὰ πάντων ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 1, '¶Παῦλος, ἀπόστολος  ̊Χριστοῦ  ̊Ἰησοῦ, κατʼ ἐπιταγὴν  ̊Θεοῦ Σωτῆρος ἡμῶν, καὶ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ τῆς ἐλπίδος ἡμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 2, 'Τιμοθέῳ, γνησίῳ τέκνῳ ἐν πίστει: χάρις, ἔλεος, εἰρήνη ἀπὸ  ̊Θεοῦ Πατρὸς καὶ  ̊Χριστοῦ  ̊Ἰησοῦ τοῦ  ̊Κυρίου ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 3, '¶Καθὼς παρεκάλεσά σε προσμεῖναι ἐν Ἐφέσῳ, πορευόμενος εἰς Μακεδονίαν, ἵνα παραγγείλῃς τισὶν μὴ ἑτεροδιδασκαλεῖν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 4, 'μηδὲ προσέχειν μύθοις καὶ γενεαλογίαις ἀπεράντοις, αἵτινες ἐκζητήσεις παρέχουσι μᾶλλον ἢ οἰκονομίαν  ̊Θεοῦ, τὴν ἐν πίστει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 5, 'Τὸ δὲ τέλος τῆς παραγγελίας ἐστὶν ἀγάπη ἐκ καθαρᾶς καρδίας, καὶ συνειδήσεως ἀγαθῆς, καὶ πίστεως ἀνυποκρίτου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 6, 'ὧν τινες ἀστοχήσαντες, ἐξετράπησαν εἰς ματαιολογίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 7, 'θέλοντες εἶναι νομοδιδάσκαλοι, μὴ νοοῦντες μήτε ἃ λέγουσιν, μήτε περὶ τίνων διαβεβαιοῦνται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 8, '¶Οἴδαμεν δὲ ὅτι καλὸς ὁ νόμος, ἐάν τις αὐτῷ νομίμως χρῆται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 9, 'εἰδὼς τοῦτο, ὅτι δικαίῳ νόμος οὐ κεῖται, ἀνόμοις δὲ καὶ ἀνυποτάκτοις, ἀσεβέσι καὶ ἁμαρτωλοῖς, ἀνοσίοις καὶ βεβήλοις, πατρολῴαις καὶ μητρολῴαις, ἀνδροφόνοις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 10, 'πόρνοις, ἀρσενοκοίταις, ἀνδραποδισταῖς, ψεύσταις, ἐπιόρκοις, καὶ εἴ τι ἕτερον τῇ ὑγιαινούσῃ διδασκαλίᾳ ἀντίκειται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 11, 'κατὰ τὸ εὐαγγέλιον τῆς δόξης τοῦ μακαρίου  ̊Θεοῦ, ὃ ἐπιστεύθην ἐγώ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 12, '¶Χάριν ἔχω τῷ ἐνδυναμώσαντί με,  ̊Χριστῷ  ̊Ἰησοῦ τῷ  ̊Κυρίῳ ἡμῶν, ὅτι πιστόν με ἡγήσατο, θέμενος εἰς διακονίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 13, 'τὸ πρότερον ὄντα βλάσφημον, καὶ διώκτην, καὶ ὑβριστήν· ἀλλὰ ἠλεήθην, ὅτι ἀγνοῶν, ἐποίησα ἐν ἀπιστίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 14, 'Ὑπερεπλεόνασεν δὲ ἡ χάρις τοῦ  ̊Κυρίου ἡμῶν, μετὰ πίστεως καὶ ἀγάπης τῆς ἐν  ̊Χριστῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 15, 'Πιστὸς ὁ λόγος, καὶ πάσης ἀποδοχῆς ἄξιος: ὅτι “ ̊Χριστὸς  ̊Ἰησοῦς ἦλθεν εἰς τὸν κόσμον ἁμαρτωλοὺς σῶσαι”, ὧν πρῶτός εἰμι ἐγώ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 16, 'Ἀλλὰ διὰ τοῦτο ἠλεήθην, ἵνα ἐν ἐμοὶ πρώτῳ ἐνδείξηται  ̊Ἰησοῦς  ̊Χριστὸς τὴν ἅπασαν μακροθυμίαν, πρὸς ὑποτύπωσιν τῶν μελλόντων πιστεύειν ἐπʼ αὐτῷ, εἰς ζωὴν αἰώνιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 17, 'Τῷ δὲ Βασιλεῖ τῶν αἰώνων, ἀφθάρτῳ, ἀοράτῳ, μόνῳ  ̊Θεῷ, τιμὴ καὶ δόξα, εἰς τοὺς αἰῶνας τῶν αἰώνων. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 18, '¶Ταύτην τὴν παραγγελίαν παρατίθεμαί σοι, τέκνον, Τιμόθεε, κατὰ τὰς προαγούσας ἐπὶ σὲ προφητείας, ἵνα στρατεύῃ ἐν αὐταῖς τὴν καλὴν στρατείαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 19, 'ἔχων πίστιν καὶ ἀγαθὴν συνείδησιν, ἥν τινες ἀπωσάμενοι, περὶ τὴν πίστιν ἐναυάγησαν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 20, 'ὧν ἐστιν Ὑμέναιος καὶ Ἀλέξανδρος, οὓς παρέδωκα τῷ Σατανᾷ, ἵνα παιδευθῶσι μὴ βλασφημεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 1, '¶Παρακαλῶ οὖν, πρῶτον πάντων ποιεῖσθαι δεήσεις, προσευχάς, ἐντεύξεις, εὐχαριστίας, ὑπὲρ πάντων ἀνθρώπων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 2, 'ὑπὲρ βασιλέων καὶ πάντων τῶν ἐν ὑπεροχῇ ὄντων, ἵνα ἤρεμον καὶ ἡσύχιον βίον διάγωμεν ἐν πάσῃ εὐσεβείᾳ καὶ σεμνότητι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 3, 'Τοῦτο καλὸν καὶ ἀπόδεκτον ἐνώπιον τοῦ Σωτῆρος ἡμῶν,  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 4, 'ὃς πάντας ἀνθρώπους θέλει σωθῆναι, καὶ εἰς ἐπίγνωσιν ἀληθείας ἐλθεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 5, 'Εἷς γὰρ  ̊Θεός, εἷς καὶ μεσίτης  ̊Θεοῦ καὶ ἀνθρώπων, ἄνθρωπος  ̊Χριστὸς  ̊Ἰησοῦς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 6, 'ὁ δοὺς ἑαυτὸν ἀντίλυτρον ὑπὲρ πάντων, καὶ μαρτύριον καιροῖς ἰδίοις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 7, 'εἰς ὃ ἐτέθην ἐγὼ κῆρυξ καὶ ἀπόστολος (ἀλήθειαν λέγω ἐν  ̊Χριστῷ, οὐ ψεύδομαι), διδάσκαλος ἐθνῶν ἐν γνώσει καὶ ἀληθείᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 8, '¶Βούλομαι οὖν, προσεύχεσθαι τοὺς ἄνδρας ἐν παντὶ τόπῳ, ἐπαίροντας ὁσίους χεῖρας χωρὶς ὀργῆς καὶ διαλογισμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 9, 'Ὡσαύτως γυναῖκας ἐν καταστολῇ κοσμίῳ μετὰ αἰδοῦς καὶ σωφροσύνης κοσμεῖν ἑαυτάς, μὴ ἐν πλέγμασιν, καὶ χρυσῷ, ἢ μαργαρίταις, ἢ ἱματισμῷ πολυτελεῖ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 10, 'ἀλλʼ ὃ πρέπει γυναιξὶν ἐπαγγελλομέναις θεοσέβειαν, διʼ ἔργων ἀγαθῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 11, 'Γυνὴ ἐν ἡσυχίᾳ μανθανέτω ἐν πάσῃ ὑποταγῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 12, 'Διδάσκειν δὲ γυναικὶ οὐκ ἐπιτρέπω, οὐδὲ αὐθεντεῖν ἀνδρός, ἀλλʼ εἶναι ἐν ἡσυχίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 13, 'Ἀδὰμ γὰρ πρῶτος ἐπλάσθη, εἶτα Εὕα·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 14, 'καὶ Ἀδὰμ οὐκ ἠπατήθη, ἡ δὲ γυνὴ ἐξαπατηθεῖσα, ἐν παραβάσει γέγονεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 15, 'Σωθήσεται δὲ διὰ τῆς τεκνογονίας, ἐὰν μείνωσιν ἐν πίστει, καὶ ἀγάπῃ, καὶ ἁγιασμῷ, μετὰ σωφροσύνης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 1, '¶Πιστὸς ὁ λόγος: “Εἴ τις ἐπισκοπῆς ὀρέγεται, καλοῦ ἔργου ἐπιθυμεῖ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 2, 'Δεῖ οὖν τὸν ἐπίσκοπον ἀνεπίλημπτον εἶναι, μιᾶς γυναικὸς ἄνδρα, νηφάλιον, σώφρονα, κόσμιον, φιλόξενον, διδακτικόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 3, 'μὴ πάροινον, μὴ πλήκτην, ἀλλὰ ἐπιεικῆ, ἄμαχον, ἀφιλάργυρον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 4, 'τοῦ ἰδίου οἴκου καλῶς προϊστάμενον, τέκνα ἔχοντα ἐν ὑποταγῇ, μετὰ πάσης σεμνότητος');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 5, '(εἰ δέ τις τοῦ ἰδίου οἴκου προστῆναι οὐκ οἶδεν, πῶς ἐκκλησίας  ̊Θεοῦ ἐπιμελήσεται;)');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 6, 'Μὴ νεόφυτον, ἵνα μὴ τυφωθεὶς, εἰς κρίμα ἐμπέσῃ τοῦ διαβόλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 7, 'Δεῖ δὲ καὶ, μαρτυρίαν καλὴν ἔχειν ἀπὸ τῶν ἔξωθεν, ἵνα μὴ εἰς ὀνειδισμὸν ἐμπέσῃ, καὶ παγίδα τοῦ διαβόλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 8, '¶Διακόνους ὡσαύτως σεμνούς, μὴ διλόγους, μὴ οἴνῳ πολλῷ προσέχοντας, μὴ αἰσχροκερδεῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 9, 'ἔχοντας τὸ μυστήριον τῆς πίστεως ἐν καθαρᾷ συνειδήσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 10, 'Καὶ οὗτοι δὲ δοκιμαζέσθωσαν πρῶτον, εἶτα διακονείτωσαν, ἀνέγκλητοι ὄντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 11, 'Γυναῖκας ὡσαύτως σεμνάς, μὴ διαβόλους, νηφαλίους, πιστὰς ἐν πᾶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 12, 'Διάκονοι ἔστωσαν μιᾶς γυναικὸς ἄνδρες, τέκνων καλῶς προϊστάμενοι καὶ τῶν ἰδίων οἴκων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 13, 'Οἱ γὰρ καλῶς διακονήσαντες, βαθμὸν ἑαυτοῖς καλὸν περιποιοῦνται, καὶ πολλὴν παρρησίαν ἐν πίστει τῇ ἐν  ̊Χριστῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 14, '¶Ταῦτά σοι γράφω, ἐλπίζων ἐλθεῖν πρὸς σὲ ἐν τάχει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 15, 'ἐὰν δὲ βραδύνω, ἵνα εἰδῇς πῶς δεῖ ἐν οἴκῳ  ̊Θεοῦ ἀναστρέφεσθαι, ἥτις ἐστὶν ἐκκλησία  ̊Θεοῦ ζῶντος, στῦλος καὶ ἑδραίωμα τῆς ἀληθείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 16, 'Καὶ ὁμολογουμένως μέγα ἐστὶν τὸ τῆς εὐσεβείας μυστήριον: “Ὃς ἐφανερώθη ἐν σαρκί, ἐδικαιώθη ἐν  ̊Πνεύματι, ὤφθη ἀγγέλοις, ἐκηρύχθη ἐν ἔθνεσιν, ἐπιστεύθη ἐν κόσμῳ, ἀνελήμφθη ἐν δόξῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 1, '¶Τὸ δὲ  ̊Πνεῦμα ῥητῶς λέγει ὅτι ἐν ὑστέροις καιροῖς, ἀποστήσονταί τινες τῆς πίστεως, προσέχοντες πνεύμασι πλάνοις καὶ διδασκαλίαις δαιμονίων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 2, 'ἐν ὑποκρίσει ψευδολόγων, κεκαυστηριασμένων τὴν ἰδίαν συνείδησιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 3, 'κωλυόντων γαμεῖν, ἀπέχεσθαι βρωμάτων ἃ ὁ  ̊Θεὸς ἔκτισεν εἰς μετάλημψιν μετὰ εὐχαριστίας, τοῖς πιστοῖς καὶ ἐπεγνωκόσι τὴν ἀλήθειαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 4, 'Ὅτι πᾶν κτίσμα  ̊Θεοῦ καλόν, καὶ οὐδὲν ἀπόβλητον μετὰ εὐχαριστίας λαμβανόμενον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 5, 'ἁγιάζεται γὰρ διὰ λόγου  ̊Θεοῦ καὶ ἐντεύξεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 6, '¶Ταῦτα ὑποτιθέμενος τοῖς ἀδελφοῖς, καλὸς ἔσῃ διάκονος  ̊Χριστοῦ  ̊Ἰησοῦ, ἐντρεφόμενος τοῖς λόγοις τῆς πίστεως, καὶ τῆς καλῆς διδασκαλίας ᾗ παρηκολούθηκας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 7, 'Τοὺς δὲ βεβήλους καὶ γραώδεις μύθους παραιτοῦ. Γύμναζε δὲ σεαυτὸν πρὸς εὐσέβειαν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 8, '“Ἡ” γὰρ “σωματικὴ γυμνασία πρὸς ὀλίγον ἐστὶν ὠφέλιμος, ἡ δὲ εὐσέβεια πρὸς πάντα ὠφέλιμός ἐστιν”, ἐπαγγελίαν ἔχουσα ζωῆς τῆς νῦν, καὶ τῆς μελλούσης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 9, 'Πιστὸς ὁ λόγος, καὶ πάσης ἀποδοχῆς ἄξιος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 10, 'Εἰς τοῦτο γὰρ κοπιῶμεν καὶ ἀγωνιζόμεθα, ὅτι ἠλπίκαμεν ἐπὶ  ̊Θεῷ ζῶντι, ὅς ἐστιν Σωτὴρ πάντων ἀνθρώπων, μάλιστα πιστῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 11, '¶Παράγγελλε ταῦτα καὶ δίδασκε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 12, 'Μηδείς σου τῆς νεότητος καταφρονείτω, ἀλλὰ τύπος γίνου τῶν πιστῶν, ἐν λόγῳ, ἐν ἀναστροφῇ, ἐν ἀγάπῃ, ἐν πίστει, ἐν ἁγνείᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 13, 'Ἕως ἔρχομαι, πρόσεχε τῇ ἀναγνώσει, τῇ παρακλήσει, τῇ διδασκαλίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 14, 'Μὴ ἀμέλει τοῦ ἐν σοὶ χαρίσματος, ὃ ἐδόθη σοι διὰ προφητείας, μετὰ ἐπιθέσεως τῶν χειρῶν τοῦ πρεσβυτερίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 15, 'Ταῦτα μελέτα, ἐν τούτοις ἴσθι, ἵνα σου ἡ προκοπὴ φανερὰ ᾖ πᾶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 16, 'Ἔπεχε σεαυτῷ καὶ τῇ διδασκαλίᾳ. Ἐπίμενε αὐτοῖς, τοῦτο γὰρ ποιῶν, καὶ σεαυτὸν σώσεις καὶ τοὺς ἀκούοντάς σου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 1, '¶Πρεσβυτέρῳ μὴ ἐπιπλήξῃς, ἀλλὰ παρακάλει ὡς πατέρα, νεωτέρους ὡς ἀδελφούς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 2, 'πρεσβυτέρας ὡς μητέρας, νεωτέρας ὡς ἀδελφὰς, ἐν πάσῃ ἁγνείᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 3, '¶Χήρας τίμα, τὰς ὄντως χήρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 4, 'Εἰ δέ τις χήρα, τέκνα ἢ ἔκγονα ἔχει, μανθανέτωσαν πρῶτον τὸν ἴδιον οἶκον εὐσεβεῖν, καὶ ἀμοιβὰς ἀποδιδόναι τοῖς προγόνοις, τοῦτο γάρ ἐστιν ἀπόδεκτον ἐνώπιον τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 5, 'Ἡ δὲ ὄντως χήρα καὶ μεμονωμένη, ἤλπικεν ἐπὶ  ̊Θεὸν, καὶ προσμένει ταῖς δεήσεσιν καὶ ταῖς προσευχαῖς, νυκτὸς καὶ ἡμέρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 6, 'Ἡ δὲ σπαταλῶσα, ζῶσα τέθνηκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 7, 'Καὶ ταῦτα παράγγελλε, ἵνα ἀνεπίλημπτοι ὦσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 8, 'Εἰ δέ τις τῶν ἰδίων καὶ μάλιστα οἰκείων οὐ προνοεῖ, τὴν πίστιν ἤρνηται, καὶ ἔστιν ἀπίστου χείρων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 9, '¶Χήρα καταλεγέσθω μὴ ἔλαττον ἐτῶν ἑξήκοντα γεγονυῖα, ἑνὸς ἀνδρὸς γυνή,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 10, 'ἐν ἔργοις καλοῖς μαρτυρουμένη: εἰ ἐτεκνοτρόφησεν, εἰ ἐξενοδόχησεν, εἰ ἁγίων πόδας ἔνιψεν, εἰ θλιβομένοις ἐπήρκεσεν, εἰ παντὶ ἔργῳ ἀγαθῷ ἐπηκολούθησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 11, 'Νεωτέρας δὲ χήρας παραιτοῦ· ὅταν γὰρ καταστρηνιάσωσιν τοῦ  ̊Χριστοῦ, γαμεῖν θέλουσιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 12, 'ἔχουσαι κρίμα ὅτι τὴν πρώτην πίστιν ἠθέτησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 13, 'Ἅμα δὲ καὶ ἀργαὶ μανθάνουσιν, περιερχόμεναι τὰς οἰκίας, οὐ μόνον δὲ ἀργαὶ, ἀλλὰ καὶ φλύαροι καὶ περίεργοι, λαλοῦσαι τὰ μὴ δέοντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 14, 'Βούλομαι οὖν νεωτέρας γαμεῖν, τεκνογονεῖν, οἰκοδεσποτεῖν, μηδεμίαν ἀφορμὴν διδόναι τῷ ἀντικειμένῳ λοιδορίας χάριν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 15, 'Ἤδη γάρ τινες ἐξετράπησαν ὀπίσω τοῦ Σατανᾶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 16, 'Εἴ τις πιστὴ ἔχει χήρας, ἐπαρκείσθω αὐταῖς, καὶ μὴ βαρείσθω ἡ ἐκκλησία, ἵνα ταῖς ὄντως χήραις ἐπαρκέσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 17, '¶Οἱ καλῶς προεστῶτες πρεσβύτεροι, διπλῆς τιμῆς ἀξιούσθωσαν, μάλιστα οἱ κοπιῶντες ἐν λόγῳ καὶ διδασκαλίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 18, 'Λέγει γὰρ ἡ Γραφή, “Βοῦν ἀλοῶντα οὐ φιμώσεις”, καί, “Ἄξιος ὁ ἐργάτης τοῦ μισθοῦ αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 19, 'Κατὰ πρεσβυτέρου κατηγορίαν μὴ παραδέχου, ἐκτὸς εἰ μὴ ἐπὶ δύο ἢ τριῶν μαρτύρων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 20, 'Τοὺς ἁμαρτάνοντας ἐνώπιον, πάντων ἔλεγχε, ἵνα καὶ οἱ λοιποὶ φόβον ἔχωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 21, 'Διαμαρτύρομαι ἐνώπιον τοῦ  ̊Θεοῦ, καὶ  ̊Χριστοῦ  ̊Ἰησοῦ, καὶ τῶν ἐκλεκτῶν ἀγγέλων, ἵνα ταῦτα φυλάξῃς χωρὶς προκρίματος, μηδὲν ποιῶν κατὰ πρόσκλισιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 22, 'Χεῖρας ταχέως μηδενὶ ἐπιτίθει, μηδὲ κοινώνει ἁμαρτίαις ἀλλοτρίαις· σεαυτὸν ἁγνὸν τήρει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 23, 'Μηκέτι ὑδροπότει, ἀλλὰ οἴνῳ ὀλίγῳ χρῶ, διὰ τὸν στόμαχον καὶ τὰς πυκνάς σου ἀσθενείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 24, 'Τινῶν ἀνθρώπων αἱ ἁμαρτίαι πρόδηλοί εἰσιν, προάγουσαι εἰς κρίσιν, τισὶν δὲ καὶ ἐπακολουθοῦσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 25, 'Ὡσαύτως καὶ τὰ ἔργα τὰ καλὰ πρόδηλα, καὶ τὰ ἄλλως ἔχοντα, κρυβῆναι οὐ δύνανται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 1, '¶Ὅσοι εἰσὶν ὑπὸ ζυγὸν δοῦλοι, τοὺς ἰδίους δεσπότας πάσης τιμῆς ἀξίους ἡγείσθωσαν, ἵνα μὴ τὸ ὄνομα τοῦ  ̊Θεοῦ καὶ ἡ διδασκαλία βλασφημῆται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 2, 'Οἱ δὲ πιστοὺς ἔχοντες δεσπότας, μὴ καταφρονείτωσαν, ὅτι ἀδελφοί εἰσιν, ἀλλὰ μᾶλλον δουλευέτωσαν, ὅτι πιστοί εἰσιν καὶ ἀγαπητοὶ, οἱ τῆς εὐεργεσίας ἀντιλαμβανόμενοι. ¶Ταῦτα δίδασκε καὶ παρακάλει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 3, 'Εἴ τις ἑτεροδιδασκαλεῖ, καὶ μὴ προσέρχεται ὑγιαίνουσι λόγοις, τοῖς τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, καὶ τῇ κατʼ εὐσέβειαν διδασκαλίᾳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 4, 'τετύφωται μηδὲν ἐπιστάμενος, ἀλλὰ νοσῶν περὶ ζητήσεις καὶ λογομαχίας, ἐξ ὧν γίνεται φθόνος, ἔρις, βλασφημίαι, ὑπόνοιαι πονηραί,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 5, 'διαπαρατριβαὶ, διεφθαρμένων ἀνθρώπων τὸν νοῦν καὶ ἀπεστερημένων τῆς ἀληθείας, νομιζόντων πορισμὸν εἶναι τὴν εὐσέβειαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 6, 'Ἔστιν δὲ πορισμὸς μέγας ἡ εὐσέβεια μετὰ αὐταρκείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 7, 'Οὐδὲν γὰρ εἰσηνέγκαμεν εἰς τὸν κόσμον, ὅτι οὐδὲ ἐξενεγκεῖν τι δυνάμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 8, 'Ἔχοντες δὲ διατροφὰς καὶ σκεπάσματα, τούτοις ἀρκεσθησόμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 9, 'Οἱ δὲ βουλόμενοι πλουτεῖν, ἐμπίπτουσιν εἰς πειρασμὸν, καὶ παγίδα, καὶ ἐπιθυμίας πολλὰς ἀνοήτους καὶ βλαβεράς, αἵτινες βυθίζουσι τοὺς ἀνθρώπους εἰς ὄλεθρον καὶ ἀπώλειαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 10, 'Ῥίζα γὰρ πάντων τῶν κακῶν ἐστιν ἡ φιλαργυρία, ἧς τινες ὀρεγόμενοι, ἀπεπλανήθησαν ἀπὸ τῆς πίστεως, καὶ ἑαυτοὺς περιέπειραν ὀδύναις πολλαῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 11, '¶Σὺ δέ, ὦ ἄνθρωπε  ̊Θεοῦ, ταῦτα φεῦγε· δίωκε δὲ δικαιοσύνην, εὐσέβειαν, πίστιν, ἀγάπην, ὑπομονήν, πραϋπαθίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 12, 'Ἀγωνίζου τὸν καλὸν ἀγῶνα τῆς πίστεως, ἐπιλαβοῦ τῆς αἰωνίου ζωῆς, εἰς ἣν ἐκλήθης καὶ ὡμολόγησας τὴν καλὴν ὁμολογίαν ἐνώπιον πολλῶν μαρτύρων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 13, 'Παραγγέλλω σοι ἐνώπιον τοῦ  ̊Θεοῦ, τοῦ ζῳοποιοῦντος τὰ πάντα, καὶ  ̊Χριστοῦ  ̊Ἰησοῦ, τοῦ μαρτυρήσαντος ἐπὶ Ποντίου Πιλάτου τὴν καλὴν ὁμολογίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 14, 'τηρῆσαί σε τὴν ἐντολὴν ἄσπιλον ἀνεπίλημπτον, μέχρι τῆς ἐπιφανείας τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 15, 'ἣν καιροῖς ἰδίοις δείξει ὁ μακάριος καὶ μόνος Δυνάστης, ὁ Βασιλεὺς τῶν βασιλευόντων, καὶ  ̊Κύριος τῶν κυριευόντων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 16, 'ὁ μόνος ἔχων ἀθανασίαν, φῶς οἰκῶν ἀπρόσιτον, ὃν εἶδεν οὐδεὶς ἀνθρώπων, οὐδὲ ἰδεῖν δύναται· ᾧ τιμὴ καὶ κράτος αἰώνιον. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 17, '¶Τοῖς πλουσίοις ἐν τῷ νῦν αἰῶνι, παράγγελλε μὴ ὑψηλοφρονεῖν, μηδὲ ἠλπικέναι ἐπὶ πλούτου ἀδηλότητι, ἀλλʼ ἐπὶ  ̊Θεῷ, τῷ παρέχοντι ἡμῖν πάντα πλουσίως εἰς ἀπόλαυσιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 18, 'ἀγαθοεργεῖν, πλουτεῖν ἐν ἔργοις καλοῖς, εὐμεταδότους εἶναι, κοινωνικούς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 19, 'ἀποθησαυρίζοντας ἑαυτοῖς θεμέλιον καλὸν εἰς τὸ μέλλον, ἵνα ἐπιλάβωνται τῆς ὄντως ζωῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 20, '¶Ὦ Τιμόθεε, τὴν παραθήκην φύλαξον, ἐκτρεπόμενος τὰς βεβήλους κενοφωνίας καὶ ἀντιθέσεις τῆς ψευδωνύμου γνώσεως,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 21, 'ἥν τινες ἐπαγγελλόμενοι περὶ τὴν πίστιν ἠστόχησαν. Ἡ χάρις μεθʼ ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 1, '¶Παῦλος, ἀπόστολος  ̊Χριστοῦ  ̊Ἰησοῦ, διὰ θελήματος  ̊Θεοῦ, κατʼ ἐπαγγελίαν ζωῆς τῆς ἐν  ̊Χριστῷ  ̊Ἰησοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 2, 'Τιμοθέῳ ἀγαπητῷ τέκνῳ: χάρις, ἔλεος, εἰρήνη, ἀπὸ  ̊Θεοῦ Πατρὸς καὶ  ̊Χριστοῦ  ̊Ἰησοῦ τοῦ  ̊Κυρίου ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 3, '¶Χάριν ἔχω τῷ  ̊Θεῷ, ᾧ λατρεύω ἀπὸ προγόνων ἐν καθαρᾷ συνειδήσει, ὡς ἀδιάλειπτον ἔχω τὴν περὶ σοῦ μνείαν, ἐν ταῖς δεήσεσίν μου, νυκτὸς καὶ ἡμέρας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 4, 'ἐπιποθῶν σε ἰδεῖν, μεμνημένος σου τῶν δακρύων, ἵνα χαρᾶς πληρωθῶ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 5, 'ὑπόμνησιν λαβὼν τῆς ἐν σοὶ ἀνυποκρίτου πίστεως, ἥτις ἐνῴκησεν πρῶτον ἐν τῇ μάμμῃ σου, Λωΐδι, καὶ τῇ μητρί σου, Εὐνίκῃ, πέπεισμαι δὲ ὅτι καὶ ἐν σοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 6, 'Διʼ ἣν αἰτίαν ἀναμιμνῄσκω σε ἀναζωπυρεῖν τὸ χάρισμα τοῦ  ̊Θεοῦ, ὅ ἐστιν ἐν σοὶ διὰ τῆς ἐπιθέσεως τῶν χειρῶν μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 7, 'Οὐ γὰρ ἔδωκεν ἡμῖν ὁ  ̊Θεὸς πνεῦμα δειλίας, ἀλλὰ δυνάμεως, καὶ ἀγάπης, καὶ σωφρονισμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 8, '¶Μὴ οὖν ἐπαισχυνθῇς τὸ μαρτύριον τοῦ  ̊Κυρίου ἡμῶν, μηδὲ ἐμὲ, τὸν δέσμιον αὐτοῦ, ἀλλὰ συγκακοπάθησον τῷ εὐαγγελίῳ, κατὰ δύναμιν  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 9, 'τοῦ σώσαντος ἡμᾶς, καὶ καλέσαντος κλήσει ἁγίᾳ, οὐ κατὰ τὰ ἔργα ἡμῶν, ἀλλὰ κατὰ ἰδίαν πρόθεσιν καὶ χάριν, τὴν δοθεῖσαν ἡμῖν ἐν  ̊Χριστῷ  ̊Ἰησοῦ πρὸ χρόνων αἰωνίων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 10, 'φανερωθεῖσαν δὲ νῦν, διὰ τῆς ἐπιφανείας τοῦ Σωτῆρος ἡμῶν,  ̊Χριστοῦ  ̊Ἰησοῦ, καταργήσαντος μὲν τὸν θάνατον, φωτίσαντος δὲ ζωὴν καὶ ἀφθαρσίαν διὰ τοῦ εὐαγγελίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 11, 'εἰς ὃ ἐτέθην ἐγὼ κῆρυξ, καὶ ἀπόστολος, καὶ διδάσκαλος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 12, 'Διʼ ἣν αἰτίαν καὶ ταῦτα πάσχω, ἀλλʼ οὐκ ἐπαισχύνομαι, οἶδα γὰρ ᾧ πεπίστευκα, καὶ πέπεισμαι ὅτι δυνατός ἐστιν, τὴν παραθήκην μου φυλάξαι εἰς ἐκείνην τὴν ἡμέραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 13, 'Ὑποτύπωσιν ἔχε ὑγιαινόντων λόγων, ὧν παρʼ ἐμοῦ ἤκουσας, ἐν πίστει καὶ ἀγάπῃ τῇ ἐν  ̊Χριστῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 14, 'Τὴν καλὴν παραθήκην φύλαξον, διὰ  ̊Πνεύματος Ἁγίου τοῦ ἐνοικοῦντος ἐν ἡμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 15, '¶Οἶδας τοῦτο, ὅτι ἀπεστράφησάν με πάντες οἱ ἐν τῇ Ἀσίᾳ, ὧν ἐστιν Φύγελος καὶ Ἑρμογένης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 16, 'Δῴη ἔλεος ὁ  ̊Κύριος τῷ Ὀνησιφόρου οἴκῳ, ὅτι πολλάκις με ἀνέψυξεν, καὶ τὴν ἅλυσίν μου οὐκ ἐπαισχύνθη,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 17, 'ἀλλὰ γενόμενος ἐν Ῥώμῃ, σπουδαίως ἐζήτησέν με καὶ εὗρεν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 18, '(δῴη αὐτῷ ὁ  ̊Κύριος, εὑρεῖν ἔλεος παρὰ  ̊Κυρίου ἐν ἐκείνῃ τῇ ἡμέρᾳ), καὶ ὅσα ἐν Ἐφέσῳ διηκόνησεν, βέλτιον σὺ γινώσκεις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 1, '¶Σὺ οὖν, τέκνον μου, ἐνδυναμοῦ ἐν τῇ χάριτι τῇ ἐν  ̊Χριστῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 2, 'Καὶ ἃ ἤκουσας παρʼ ἐμοῦ διὰ πολλῶν μαρτύρων, ταῦτα παράθου πιστοῖς ἀνθρώποις, οἵτινες ἱκανοὶ ἔσονται καὶ ἑτέρους διδάξαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 3, 'Συγκακοπάθησον ὡς καλὸς στρατιώτης  ̊Χριστοῦ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 4, 'Οὐδεὶς στρατευόμενος ἐμπλέκεται ταῖς τοῦ βίου πραγματείαις, ἵνα τῷ στρατολογήσαντι ἀρέσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 5, 'Ἐὰν δὲ καὶ ἀθλῇ τις, οὐ στεφανοῦται, ἐὰν μὴ νομίμως ἀθλήσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 6, 'Τὸν κοπιῶντα γεωργὸν δεῖ πρῶτον τῶν καρπῶν μεταλαμβάνειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 7, 'Νόει ὃ λέγω, δώσει γάρ σοι ὁ  ̊Κύριος σύνεσιν ἐν πᾶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 8, '¶Μνημόνευε  ̊Ἰησοῦν  ̊Χριστὸν, ἐγηγερμένον ἐκ νεκρῶν, ἐκ σπέρματος Δαυίδ, κατὰ τὸ εὐαγγέλιόν μου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 9, 'ἐν ᾧ κακοπαθῶ μέχρι δεσμῶν ὡς κακοῦργος. Ἀλλὰ ὁ λόγος τοῦ  ̊Θεοῦ οὐ δέδεται!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 10, 'Διὰ τοῦτο, πάντα ὑπομένω διὰ τοὺς ἐκλεκτούς, ἵνα καὶ αὐτοὶ σωτηρίας τύχωσιν τῆς ἐν  ̊Χριστῷ  ̊Ἰησοῦ μετὰ δόξης αἰωνίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 11, 'Πιστὸς ὁ λόγος: “Εἰ γὰρ συναπεθάνομεν, καὶ συζήσομεν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 12, 'εἰ ὑπομένομεν, καὶ συμβασιλεύσομεν· εἰ ἀρνησόμεθα, κἀκεῖνος ἀρνήσεται ἡμᾶς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 13, 'εἰ ἀπιστοῦμεν, ἐκεῖνος πιστὸς μένει· ἀρνήσασθαι γὰρ ἑαυτὸν οὐ δύναται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 14, '¶Ταῦτα ὑπομίμνῃσκε, διαμαρτυρόμενος ἐνώπιον τοῦ  ̊Θεοῦ, μὴ λογομαχεῖν ἐπʼ οὐδὲν χρήσιμον, ἐπὶ καταστροφῇ τῶν ἀκουόντων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 15, 'Σπούδασον σεαυτὸν δόκιμον παραστῆσαι τῷ  ̊Θεῷ, ἐργάτην ἀνεπαίσχυντον, ὀρθοτομοῦντα τὸν λόγον τῆς ἀληθείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 16, 'Τὰς δὲ βεβήλους κενοφωνίας περιΐστασο, ἐπὶ πλεῖον γὰρ προκόψουσιν ἀσεβείας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 17, 'καὶ ὁ λόγος αὐτῶν ὡς γάγγραινα νομὴν ἕξει· ὧν ἐστιν Ὑμέναιος, καὶ Φίλητος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 18, 'οἵτινες περὶ τὴν ἀλήθειαν ἠστόχησαν, λέγοντες τὴν ἀνάστασιν ἤδη γεγονέναι, καὶ ἀνατρέπουσιν τήν τινων πίστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 19, 'Ὁ μέντοι στερεὸς θεμέλιος τοῦ  ̊Θεοῦ ἕστηκεν, ἔχων τὴν σφραγῖδα ταύτην: “Ἔγνω  ̊Κύριος τοὺς ὄντας αὐτοῦ”, καί, “Ἀποστήτω ἀπὸ ἀδικίας πᾶς ὁ ὀνομάζων τὸ ὄνομα  ̊Κυρίου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 20, '¶Ἐν μεγάλῃ δὲ οἰκίᾳ, οὐκ ἔστιν μόνον σκεύη χρυσᾶ καὶ ἀργυρᾶ, ἀλλὰ καὶ ξύλινα καὶ ὀστράκινα, καὶ ἃ μὲν εἰς τιμὴν, ἃ δὲ εἰς ἀτιμίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 21, 'Ἐὰν οὖν τις ἐκκαθάρῃ ἑαυτὸν ἀπὸ τούτων, ἔσται σκεῦος εἰς τιμήν, ἡγιασμένον εὔχρηστον τῷ Δεσπότῃ, εἰς πᾶν ἔργον ἀγαθὸν ἡτοιμασμένον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 22, 'Τὰς δὲ νεωτερικὰς ἐπιθυμίας φεῦγε, δίωκε δὲ δικαιοσύνην, πίστιν, ἀγάπην, εἰρήνην, μετὰ τῶν ἐπικαλουμένων τὸν  ̊Κύριον ἐκ καθαρᾶς καρδίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 23, 'Τὰς δὲ μωρὰς καὶ ἀπαιδεύτους ζητήσεις παραιτοῦ, εἰδὼς ὅτι γεννῶσι μάχας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 24, 'Δοῦλον δὲ  ̊Κυρίου οὐ δεῖ μάχεσθαι, ἀλλὰ ἤπιον εἶναι πρὸς πάντας, διδακτικόν, ἀνεξίκακον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 25, 'ἐν πραΰτητι παιδεύοντα τοὺς ἀντιδιατιθεμένους, μήποτε δώῃ αὐτοῖς ὁ  ̊Θεὸς μετάνοιαν εἰς ἐπίγνωσιν ἀληθείας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 26, 'καὶ ἀνανήψωσιν ἐκ τῆς τοῦ διαβόλου παγίδος, ἐζωγρημένοι ὑπʼ αὐτοῦ, εἰς τὸ ἐκείνου θέλημα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 1, '¶Τοῦτο δὲ γίνωσκε, ὅτι ἐν ἐσχάταις ἡμέραις ἐνστήσονται καιροὶ χαλεποί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 2, 'Ἔσονται γὰρ οἱ ἄνθρωποι φίλαυτοι, φιλάργυροι, ἀλαζόνες, ὑπερήφανοι, βλάσφημοι, γονεῦσιν ἀπειθεῖς, ἀχάριστοι, ἀνόσιοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 3, 'ἄστοργοι, ἄσπονδοι, διάβολοι, ἀκρατεῖς, ἀνήμεροι, ἀφιλάγαθοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 4, 'προδόται, προπετεῖς, τετυφωμένοι, φιλήδονοι μᾶλλον ἢ φιλόθεοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 5, 'ἔχοντες μόρφωσιν εὐσεβείας, τὴν δὲ δύναμιν αὐτῆς ἠρνημένοι· καὶ τούτους ἀποτρέπου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 6, 'Ἐκ τούτων γάρ, εἰσιν οἱ ἐνδύνοντες εἰς τὰς οἰκίας, καὶ αἰχμαλωτίζοντες γυναικάρια, σεσωρευμένα ἁμαρτίαις, ἀγόμενα ἐπιθυμίαις ποικίλαις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 7, 'πάντοτε μανθάνοντα, καὶ μηδέποτε εἰς ἐπίγνωσιν ἀληθείας ἐλθεῖν δυνάμενα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 8, 'Ὃν τρόπον δὲ Ἰάννης καὶ Ἰαμβρῆς ἀντέστησαν Μωϋσεῖ, οὕτως καὶ οὗτοι ἀνθίστανται τῇ ἀληθείᾳ, ἄνθρωποι κατεφθαρμένοι τὸν νοῦν, ἀδόκιμοι περὶ τὴν πίστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 9, 'Ἀλλʼ οὐ προκόψουσιν ἐπὶ πλεῖον, ἡ γὰρ ἄνοια αὐτῶν ἔκδηλος ἔσται πᾶσιν, ὡς καὶ ἡ ἐκείνων ἐγένετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 10, '¶Σὺ δὲ παρηκολούθησάς μου τῇ διδασκαλίᾳ, τῇ ἀγωγῇ, τῇ προθέσει, τῇ πίστει, τῇ μακροθυμίᾳ, τῇ ἀγάπῃ, τῇ ὑπομονῇ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 11, 'τοῖς διωγμοῖς, τοῖς παθήμασιν, οἷά μοι ἐγένετο ἐν Ἀντιοχείᾳ, ἐν Ἰκονίῳ, ἐν Λύστροις, οἵους διωγμοὺς ὑπήνεγκα, καὶ ἐκ πάντων, με ἐρρύσατο ὁ  ̊Κύριος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 12, 'Καὶ πάντες δὲ οἱ θέλοντες ζῆν εὐσεβῶς ἐν  ̊Χριστῷ  ̊Ἰησοῦ διωχθήσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 13, 'Πονηροὶ δὲ ἄνθρωποι καὶ γόητες προκόψουσιν ἐπὶ τὸ χεῖρον, πλανῶντες καὶ πλανώμενοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 14, 'Σὺ δὲ μένε ἐν οἷς ἔμαθες καὶ ἐπιστώθης, εἰδὼς παρὰ τίνων ἔμαθες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 15, 'καὶ ὅτι ἀπὸ βρέφους τὰ ἱερὰ γράμματα οἶδας, τὰ δυνάμενά σε σοφίσαι εἰς σωτηρίαν διὰ πίστεως τῆς ἐν  ̊Χριστῷ  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 16, 'Πᾶσα Γραφὴ θεόπνευστος καὶ ὠφέλιμος πρὸς διδασκαλίαν, πρὸς ἐλεγμόν, πρὸς ἐπανόρθωσιν, πρὸς παιδείαν τὴν ἐν δικαιοσύνῃ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 17, 'ἵνα ἄρτιος ᾖ ὁ τοῦ  ̊Θεοῦ ἄνθρωπος, πρὸς πᾶν ἔργον ἀγαθὸν ἐξηρτισμένος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 1, '¶Διαμαρτύρομαι ἐνώπιον τοῦ  ̊Θεοῦ καὶ  ̊Χριστοῦ  ̊Ἰησοῦ, τοῦ μέλλοντος κρίνειν ζῶντας καὶ νεκρούς, καὶ τὴν ἐπιφάνειαν αὐτοῦ, καὶ τὴν βασιλείαν αὐτοῦ:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 2, 'κήρυξον τὸν λόγον, ἐπίστηθι εὐκαίρως, ἀκαίρως, ἔλεγξον, ἐπιτίμησον, παρακάλεσον, ἐν πάσῃ μακροθυμίᾳ καὶ διδαχῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 3, 'Ἔσται γὰρ καιρὸς ὅτε τῆς ὑγιαινούσης διδασκαλίας οὐκ ἀνέξονται, ἀλλὰ κατὰ τὰς ἰδίας ἐπιθυμίας, ἑαυτοῖς ἐπισωρεύσουσιν διδασκάλους, κνηθόμενοι τὴν ἀκοήν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 4, 'καὶ ἀπὸ μὲν τῆς ἀληθείας τὴν ἀκοὴν ἀποστρέψουσιν, ἐπὶ δὲ τοὺς μύθους ἐκτραπήσονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 5, 'Σὺ δὲ νῆφε ἐν πᾶσιν, κακοπάθησον, ἔργον ποίησον εὐαγγελιστοῦ, τὴν διακονίαν σου πληροφόρησον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 6, '¶Ἐγὼ γὰρ ἤδη σπένδομαι, καὶ ὁ καιρὸς τῆς ἀναλύσεώς μου ἐφέστηκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 7, 'Τὸν καλὸν ἀγῶνα ἠγώνισμαι, τὸν δρόμον τετέλεκα, τὴν πίστιν τετήρηκα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 8, 'Λοιπὸν ἀπόκειταί μοι ὁ τῆς δικαιοσύνης στέφανος, ὃν ἀποδώσει μοι ὁ  ̊Κύριος ἐν, ἐκείνῃ τῇ ἡμέρᾳ, ὁ δίκαιος κριτής, οὐ μόνον δὲ ἐμοὶ, ἀλλὰ καὶ πᾶσιν τοῖς ἠγαπηκόσι τὴν ἐπιφάνειαν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 9, '¶Σπούδασον ἐλθεῖν πρός με ταχέως·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 10, 'Δημᾶς γάρ με ἐγκατέλειπεν, ἀγαπήσας τὸν νῦν αἰῶνα, καὶ ἐπορεύθη εἰς Θεσσαλονίκην, Κρήσκης εἰς Γαλατίαν, Τίτος εἰς Δαλματίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 11, 'Λουκᾶς ἐστιν μόνος μετʼ ἐμοῦ. Μᾶρκον ἀναλαβὼν, ἄγε μετὰ σεαυτοῦ, ἔστιν γάρ μοι εὔχρηστος εἰς διακονίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 12, 'Τυχικὸν δὲ ἀπέστειλα εἰς Ἔφεσον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 13, 'Τὸν φελόνην ὃν ἀπέλιπον ἐν Τρῳάδι παρὰ Κάρπῳ, ἐρχόμενος φέρε, καὶ τὰ βιβλία, μάλιστα τὰς μεμβράνας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 14, 'Ἀλέξανδρος ὁ χαλκεὺς, πολλά μοι κακὰ ἐνεδείξατο· ἀποδώσει αὐτῷ ὁ  ̊Κύριος κατὰ τὰ ἔργα αὐτοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 15, 'ὃν καὶ σὺ φυλάσσου, λίαν γὰρ ἀντέστη τοῖς ἡμετέροις λόγοις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 16, '¶Ἐν τῇ πρώτῃ μου ἀπολογίᾳ, οὐδείς μοι παρεγένετο, ἀλλὰ πάντες με ἐγκατέλιπον· μὴ αὐτοῖς λογισθείη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 17, 'Ὁ δὲ  ̊Κύριός μοι παρέστη, καὶ ἐνεδυνάμωσέν με, ἵνα διʼ ἐμοῦ τὸ κήρυγμα πληροφορηθῇ, καὶ ἀκούσωσιν πάντα τὰ ἔθνη, καὶ ἐρρύσθην ἐκ στόματος λέοντος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 18, 'Ῥύσεταί με ὁ  ̊Κύριος ἀπὸ παντὸς ἔργου πονηροῦ, καὶ σώσει εἰς τὴν βασιλείαν αὐτοῦ τὴν ἐπουράνιον· ᾧ ἡ δόξα εἰς τοὺς αἰῶνας τῶν αἰώνων. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 19, '¶Ἄσπασαι Πρίσκαν καὶ Ἀκύλαν, καὶ τὸν Ὀνησιφόρου οἶκον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 20, 'Ἔραστος ἔμεινεν ἐν Κορίνθῳ, Τρόφιμον δὲ ἀπέλιπον ἐν Μιλήτῳ ἀσθενοῦντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 21, 'Σπούδασον πρὸ χειμῶνος ἐλθεῖν. Ἀσπάζεταί σε Εὔβουλος, καὶ Πούδης, καὶ Λίνος, καὶ Κλαυδία, καὶ οἱ ἀδελφοὶ πάντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 22, '¶Ὁ  ̊Κύριος  ̊Ἰησοῦς μετὰ τοῦ πνεύματός σου. Ἡ χάρις μεθʼ ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 1, '¶Παῦλος, δοῦλος  ̊Θεοῦ, ἀπόστολος δὲ  ̊Ἰησοῦ  ̊Χριστοῦ, κατὰ πίστιν ἐκλεκτῶν  ̊Θεοῦ, καὶ ἐπίγνωσιν ἀληθείας, τῆς κατʼ εὐσέβειαν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 2, 'ἐπʼ ἐλπίδι ζωῆς αἰωνίου, ἣν ἐπηγγείλατο ὁ ἀψευδὴς  ̊Θεὸς πρὸ χρόνων αἰωνίων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 3, 'ἐφανέρωσεν δὲ καιροῖς ἰδίοις τὸν λόγον αὐτοῦ ἐν κηρύγματι, ὃ ἐπιστεύθην ἐγὼ, κατʼ ἐπιταγὴν τοῦ Σωτῆρος ἡμῶν  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 4, 'Τίτῳ, γνησίῳ τέκνῳ, κατὰ κοινὴν πίστιν: χάρις καὶ εἰρήνη ἀπὸ  ̊Θεοῦ Πατρὸς καὶ  ̊Χριστοῦ  ̊Ἰησοῦ τοῦ Σωτῆρος ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 5, '¶Τούτου χάριν, ἀπέλιπόν σε ἐν Κρήτῃ, ἵνα τὰ λείποντα ἐπιδιορθώσῃ, καὶ καταστήσῃς κατὰ πόλιν πρεσβυτέρους, ὡς ἐγώ σοι διεταξάμην,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 6, 'εἴ τίς ἐστιν ἀνέγκλητος, μιᾶς γυναικὸς ἀνήρ, τέκνα ἔχων πιστά, μὴ ἐν κατηγορίᾳ ἀσωτίας ἢ ἀνυπότακτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 7, 'Δεῖ γὰρ τὸν ἐπίσκοπον ἀνέγκλητον εἶναι, ὡς  ̊Θεοῦ οἰκονόμον, μὴ αὐθάδη, μὴ ὀργίλον, μὴ πάροινον, μὴ πλήκτην, μὴ αἰσχροκερδῆ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 8, 'ἀλλὰ φιλόξενον, φιλάγαθον, σώφρονα, δίκαιον, ὅσιον, ἐγκρατῆ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 9, 'ἀντεχόμενον τοῦ κατὰ τὴν διδαχὴν πιστοῦ λόγου, ἵνα δυνατὸς ᾖ, καὶ παρακαλεῖν ἐν τῇ διδασκαλίᾳ τῇ ὑγιαινούσῃ, καὶ τοὺς ἀντιλέγοντας ἐλέγχειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 10, '¶Εἰσὶν γὰρ πολλοὶ ἀνυπότακτοι, ματαιολόγοι, καὶ φρεναπάται, μάλιστα οἱ ἐκ τῆς περιτομῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 11, 'οὓς δεῖ ἐπιστομίζειν, οἵτινες ὅλους οἴκους ἀνατρέπουσιν, διδάσκοντες ἃ μὴ δεῖ, αἰσχροῦ κέρδους χάριν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 12, 'Εἶπέν τις ἐξ αὐτῶν, ἴδιος αὐτῶν προφήτης, “Κρῆτες ἀεὶ ψεῦσται, κακὰ θηρία, γαστέρες ἀργαί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 13, 'Ἡ μαρτυρία αὕτη ἐστὶν ἀληθής. Διʼ ἣν αἰτίαν ἔλεγχε αὐτοὺς ἀποτόμως, ἵνα ὑγιαίνωσιν ἐν τῇ πίστει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 14, 'μὴ προσέχοντες Ἰουδαϊκοῖς μύθοις καὶ ἐντολαῖς ἀνθρώπων, ἀποστρεφομένων τὴν ἀλήθειαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 15, 'Πάντα καθαρὰ τοῖς καθαροῖς· τοῖς δὲ μεμιαμμένοις καὶ ἀπίστοις, οὐδὲν καθαρόν, ἀλλὰ μεμίανται αὐτῶν καὶ ὁ νοῦς, καὶ ἡ συνείδησις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 16, ' ̊Θεὸν ὁμολογοῦσιν εἰδέναι, τοῖς δὲ ἔργοις ἀρνοῦνται, βδελυκτοὶ ὄντες καὶ ἀπειθεῖς, καὶ πρὸς πᾶν ἔργον ἀγαθὸν ἀδόκιμοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 1, '¶Σὺ δὲ λάλει ἃ πρέπει τῇ ὑγιαινούσῃ διδασκαλίᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 2, 'Πρεσβύτας νηφαλίους εἶναι, σεμνούς, σώφρονας, ὑγιαίνοντας τῇ πίστει, τῇ ἀγάπῃ, τῇ ὑπομονῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 3, '¶Πρεσβύτιδας ὡσαύτως ἐν καταστήματι ἱεροπρεπεῖς, μὴ διαβόλους, μηδὲ οἴνῳ πολλῷ δεδουλωμένας, καλοδιδασκάλους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 4, 'ἵνα σωφρονίζουσιν τὰς νέας φιλάνδρους εἶναι, φιλοτέκνους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 5, 'σώφρονας, ἁγνάς, οἰκουργούς, ἀγαθάς, ὑποτασσομένας τοῖς ἰδίοις ἀνδράσιν, ἵνα μὴ ὁ λόγος τοῦ  ̊Θεοῦ βλασφημῆται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 6, '¶Τοὺς νεωτέρους ὡσαύτως παρακάλει, σωφρονεῖν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 7, 'περὶ πάντα σεαυτὸν παρεχόμενος τύπον καλῶν ἔργων, ἐν τῇ διδασκαλίᾳ ἀφθορίαν, σεμνότητα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 8, 'λόγον ὑγιῆ, ἀκατάγνωστον, ἵνα ὁ ἐξ ἐναντίας ἐντραπῇ, μηδὲν ἔχων λέγειν περὶ ἡμῶν φαῦλον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 9, '¶Δούλους ἰδίοις δεσπόταις ὑποτάσσεσθαι ἐν πᾶσιν, εὐαρέστους εἶναι, μὴ ἀντιλέγοντας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 10, 'μὴ νοσφιζομένους, ἀλλὰ πᾶσαν πίστιν ἐνδεικνυμένους ἀγαθήν, ἵνα τὴν διδασκαλίαν τὴν τοῦ Σωτῆρος ἡμῶν,  ̊Θεοῦ, κοσμῶσιν ἐν πᾶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 11, '¶Ἐπεφάνη γὰρ ἡ χάρις τοῦ  ̊Θεοῦ, σωτήριος πᾶσιν ἀνθρώποις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 12, 'παιδεύουσα ἡμᾶς ἵνα ἀρνησάμενοι τὴν ἀσέβειαν καὶ τὰς κοσμικὰς ἐπιθυμίας, σωφρόνως καὶ δικαίως, καὶ εὐσεβῶς, ζήσωμεν ἐν τῷ νῦν αἰῶνι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 13, 'προσδεχόμενοι τὴν μακαρίαν ἐλπίδα, καὶ ἐπιφάνειαν τῆς δόξης τοῦ μεγάλου  ̊Θεοῦ καὶ Σωτῆρος ἡμῶν,  ̊Ἰησοῦ·  ̊Χριστοῦ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 14, 'ὃς ἔδωκεν ἑαυτὸν ὑπὲρ ἡμῶν, ἵνα λυτρώσηται ἡμᾶς ἀπὸ πάσης ἀνομίας, καὶ καθαρίσῃ ἑαυτῷ λαὸν περιούσιον, ζηλωτὴν καλῶν ἔργων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 15, '¶Ταῦτα λάλει, καὶ παρακάλει, καὶ ἔλεγχε, μετὰ πάσης ἐπιταγῆς. Μηδείς σου περιφρονείτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 1, '¶Ὑπομίμνῃσκε αὐτοὺς ἀρχαῖς, ἐξουσίαις, ὑποτάσσεσθαι, πειθαρχεῖν, πρὸς πᾶν ἔργον ἀγαθὸν ἑτοίμους εἶναι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 2, 'μηδένα βλασφημεῖν, ἀμάχους εἶναι, ἐπιεικεῖς, πᾶσαν ἐνδεικνυμένους πραΰτητα πρὸς πάντας ἀνθρώπους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 3, 'Ἦμεν γάρ ποτε καὶ ἡμεῖς ἀνόητοι, ἀπειθεῖς, πλανώμενοι, δουλεύοντες ἐπιθυμίαις καὶ ἡδοναῖς ποικίλαις, ἐν κακίᾳ καὶ φθόνῳ διάγοντες, στυγητοί, μισοῦντες ἀλλήλους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 4, 'Ὅτε δὲ ἡ χρηστότης καὶ ἡ φιλανθρωπία ἐπεφάνη τοῦ Σωτῆρος ἡμῶν,  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 5, 'οὐκ ἐξ ἔργων τῶν ἐν δικαιοσύνῃ, ἃ ἐποιήσαμεν ἡμεῖς, ἀλλὰ κατὰ τὸ αὐτοῦ ἔλεος, ἔσωσεν ἡμᾶς, διὰ λουτροῦ παλιγγενεσίας καὶ ἀνακαινώσεως  ̊Πνεύματος Ἁγίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 6, 'οὗ ἐξέχεεν ἐφʼ ἡμᾶς πλουσίως, διὰ  ̊Ἰησοῦ  ̊Χριστοῦ, τοῦ Σωτῆρος ἡμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 7, 'ἵνα δικαιωθέντες τῇ ἐκείνου χάριτι, κληρονόμοι γενηθῶμεν, κατʼ ἐλπίδα ζωῆς αἰωνίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 8, '¶Πιστὸς ὁ λόγος, καὶ περὶ τούτων βούλομαί σε διαβεβαιοῦσθαι, “Ἵνα φροντίζωσιν καλῶν ἔργων προΐστασθαι, οἱ πεπιστευκότες  ̊Θεῷ.” Ταῦτά ἐστιν καλὰ καὶ ὠφέλιμα τοῖς ἀνθρώποις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 9, 'Μωρὰς δὲ ζητήσεις, καὶ γενεαλογίας, καὶ ἔρεις, καὶ μάχας νομικὰς, περιΐστασο, εἰσὶν γὰρ ἀνωφελεῖς καὶ μάταιοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 10, 'Αἱρετικὸν ἄνθρωπον μετὰ μίαν καὶ δευτέραν νουθεσίαν παραιτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 11, 'εἰδὼς ὅτι ἐξέστραπται ὁ τοιοῦτος καὶ ἁμαρτάνει, ὢν αὐτοκατάκριτος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 12, '¶Ὅταν πέμψω Ἀρτεμᾶν πρὸς σὲ ἢ Τυχικόν, σπούδασον ἐλθεῖν πρός με εἰς Νικόπολιν, ἐκεῖ γὰρ κέκρικα παραχειμάσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 13, 'Ζηνᾶν τὸν νομικὸν καὶ Ἀπολλῶν σπουδαίως πρόπεμψον, ἵνα μηδὲν αὐτοῖς λείπῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 14, 'Μανθανέτωσαν δὲ καὶ οἱ ἡμέτεροι καλῶν ἔργων προΐστασθαι εἰς τὰς ἀναγκαίας χρείας, ἵνα μὴ ὦσιν ἄκαρποι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 15, '¶Ἀσπάζονταί σε οἱ μετʼ ἐμοῦ πάντες. Ἄσπασαι τοὺς φιλοῦντας ἡμᾶς ἐν πίστει. Ἡ χάρις μετὰ πάντων ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 1, '¶Παῦλος, δέσμιος  ̊Χριστοῦ  ̊Ἰησοῦ, καὶ Τιμόθεος, ὁ ἀδελφὸς, Φιλήμονι, τῷ ἀγαπητῷ καὶ συνεργῷ ἡμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 2, 'καὶ Ἀπφίᾳ, τῇ ἀδελφῇ, καὶ Ἀρχίππῳ, τῷ συστρατιώτῃ ἡμῶν, καὶ τῇ κατʼ οἶκόν σου ἐκκλησίᾳ:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 3, 'χάρις ὑμῖν καὶ εἰρήνη, ἀπὸ  ̊Θεοῦ Πατρὸς ἡμῶν καὶ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 4, '¶Εὐχαριστῶ τῷ  ̊Θεῷ μου πάντοτε, μνείαν σου ποιούμενος ἐπὶ τῶν προσευχῶν μου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 5, 'ἀκούων σου τὴν ἀγάπην καὶ τὴν πίστιν, ἣν ἔχεις εἰς τὸν  ̊Κύριον  ̊Ἰησοῦν, καὶ εἰς πάντας τοὺς ἁγίους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 6, 'ὅπως ἡ κοινωνία τῆς πίστεώς σου, ἐνεργὴς γένηται ἐν ἐπιγνώσει παντὸς ἀγαθοῦ τοῦ ἐν ἡμῖν εἰς  ̊Χριστόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 7, 'Χαρὰν γὰρ πολλὴν ἔσχον καὶ παράκλησιν, ἐπὶ τῇ ἀγάπῃ σου, ὅτι τὰ σπλάγχνα τῶν ἁγίων ἀναπέπαυται διὰ σοῦ, ἀδελφέ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 8, '¶Διό, πολλὴν ἐν  ̊Χριστῷ παρρησίαν ἔχων, ἐπιτάσσειν σοι τὸ ἀνῆκον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 9, 'διὰ τὴν ἀγάπην μᾶλλον παρακαλῶ τοιοῦτος ὢν, ὡς Παῦλος (πρεσβύτης νυνὶ δὲ καὶ δέσμιος  ̊Χριστοῦ  ̊Ἰησοῦ),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 10, 'παρακαλῶ σε περὶ τοῦ ἐμοῦ τέκνου, ὃν ἐγέννησα ἐν τοῖς δεσμοῖς, Ὀνήσιμον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 11, 'τόν ποτέ σοι ἄχρηστον, νυνὶ δὲ σοὶ καὶ ἐμοὶ εὔχρηστον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 12, 'ὃν ἀνέπεμψά σοι αὐτόν, τοῦτʼ ἔστιν τὰ ἐμὰ σπλάγχνα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 13, 'ὃν ἐγὼ ἐβουλόμην πρὸς ἐμαυτὸν κατέχειν, ἵνα ὑπὲρ σοῦ μοι διακονῇ ἐν τοῖς δεσμοῖς τοῦ εὐαγγελίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 14, 'χωρὶς δὲ τῆς σῆς γνώμης, οὐδὲν ἠθέλησα ποιῆσαι, ἵνα μὴ ὡς κατὰ ἀνάγκην τὸ ἀγαθόν σου ᾖ, ἀλλὰ κατὰ ἑκούσιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 15, 'Τάχα γὰρ διὰ τοῦτο, ἐχωρίσθη πρὸς ὥραν, ἵνα αἰώνιον αὐτὸν ἀπέχῃς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 16, 'οὐκέτι ὡς δοῦλον, ἀλλʼ ὑπὲρ δοῦλον, ἀδελφὸν ἀγαπητόν, μάλιστα ἐμοί πόσῳ δὲ μᾶλλον σοὶ, καὶ ἐν σαρκὶ καὶ ἐν  ̊Κυρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 17, '¶Εἰ οὖν με ἔχεις κοινωνόν, προσλαβοῦ αὐτὸν ὡς ἐμέ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 18, 'Εἰ δέ τι ἠδίκησέν σε ἢ ὀφείλει, τοῦτο ἐμοὶ ἐλλόγα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 19, 'Ἐγὼ Παῦλος ἔγραψα τῇ ἐμῇ χειρί, ἐγὼ ἀποτίσω· ἵνα μὴ λέγω σοι ὅτι καὶ σεαυτόν μοι προσοφείλεις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 20, 'Ναί, ἀδελφέ, ἐγώ σου ὀναίμην ἐν  ̊Κυρίῳ· ἀνάπαυσόν μου τὰ σπλάγχνα ἐν  ̊Χριστῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 21, 'Πεποιθὼς τῇ ὑπακοῇ σου, ἔγραψά σοι, εἰδὼς ὅτι καὶ ὑπὲρ ἃ λέγω, ποιήσεις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 22, 'Ἅμα δὲ καὶ ἑτοίμαζέ μοι ξενίαν, ἐλπίζω γὰρ ὅτι διὰ τῶν προσευχῶν ὑμῶν, χαρισθήσομαι ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 23, '¶Ἀσπάζεταί σε Ἐπαφρᾶς, ὁ συναιχμάλωτός μου ἐν  ̊Χριστῷ  ̊Ἰησοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 24, 'Μᾶρκος, Ἀρίσταρχος, Δημᾶς, Λουκᾶς, οἱ συνεργοί μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 25, '¶Ἡ χάρις τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, μετὰ τοῦ πνεύματος ὑμῶν. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 1, '¶Πολυμερῶς καὶ πολυτρόπως πάλαι, ὁ  ̊Θεὸς, λαλήσας τοῖς πατράσιν ἐν τοῖς προφήταις');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 2, 'ἐπʼ ἐσχάτου τῶν ἡμερῶν τούτων, ἐλάλησεν ἡμῖν ἐν Υἱῷ, ὃν ἔθηκεν κληρονόμον πάντων, διʼ οὗ καὶ ἐποίησεν τοὺς αἰῶνας·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 3, 'ὃς ὢν ἀπαύγασμα τῆς δόξης καὶ χαρακτὴρ τῆς ὑποστάσεως αὐτοῦ, φέρων τε τὰ πάντα τῷ ῥήματι τῆς δυνάμεως αὐτοῦ, καθαρισμὸν τῶν ἁμαρτιῶν “ποιησάμενος, ἐκάθισεν ἐν δεξιᾷ” τῆς Μεγαλωσύνης ἐν ὑψηλοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 4, 'Τοσούτῳ κρείττων γενόμενος τῶν ἀγγέλων, ὅσῳ διαφορώτερον παρʼ αὐτοὺς, κεκληρονόμηκεν ὄνομα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 5, '¶Τίνι γὰρ εἶπέν ποτε τῶν ἀγγέλων, “Υἱός μου εἶ σύ, ἐγὼ σήμερον γεγέννηκά σε;” Καὶ πάλιν, “Ἐγὼ ἔσομαι αὐτῷ εἰς Πατέρα, καὶ αὐτὸς ἔσται μοι εἰς Υἱόν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 6, 'Ὅταν δὲ πάλιν εἰσαγάγῃ τὸν πρωτότοκον εἰς τὴν οἰκουμένην, λέγει, “Καὶ προσκυνησάτωσαν αὐτῷ πάντες ἄγγελοι  ̊Θεοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 7, 'Καὶ πρὸς μὲν τοὺς ἀγγέλους λέγει, “Ὁ ποιῶν τοὺς ἀγγέλους αὐτοῦ πνεύματα, καὶ τοὺς λειτουργοὺς αὐτοῦ πυρὸς φλόγα”·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 8, 'πρὸς δὲ τὸν Υἱόν, “Ὁ θρόνος σου, ὁ  ̊Θεὸς, εἰς τὸν αἰῶνα τοῦ αἰῶνος, καὶ ἡ ῥάβδος τῆς εὐθύτητος ῥάβδος τῆς βασιλείας αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 9, 'Ἠγάπησας δικαιοσύνην καὶ ἐμίσησας ἀνομίαν· διὰ τοῦτο, ἔχρισέν σε ὁ  ̊Θεός, ὁ  ̊Θεός σου, ἔλαιον ἀγαλλιάσεως παρὰ τοὺς μετόχους σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 10, 'Καί, “Σὺ κατʼ ἀρχάς,  ̊Κύριε, τὴν γῆν ἐθεμελίωσας, καὶ ἔργα τῶν χειρῶν σού εἰσιν οἱ οὐρανοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 11, 'Αὐτοὶ ἀπολοῦνται, σὺ δὲ διαμένεις· καὶ πάντες ὡς ἱμάτιον παλαιωθήσονται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 12, 'καὶ ὡσεὶ περιβόλαιον ἑλίξεις αὐτούς, ὡς ἱμάτιον καὶ ἀλλαγήσονται· σὺ δὲ ὁ αὐτὸς εἶ, καὶ τὰ ἔτη σου οὐκ ἐκλείψουσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 13, 'Πρὸς τίνα δὲ τῶν ἀγγέλων εἴρηκέν ποτε, “Κάθου ἐκ δεξιῶν μου, ἕως ἂν θῶ τοὺς ἐχθρούς σου, ὑποπόδιον τῶν ποδῶν σου;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 14, 'Οὐχὶ πάντες εἰσὶν λειτουργικὰ πνεύματα, εἰς διακονίαν ἀποστελλόμενα, διὰ τοὺς μέλλοντας κληρονομεῖν σωτηρίαν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 1, '¶Διὰ τοῦτο, δεῖ περισσοτέρως προσέχειν ἡμᾶς τοῖς ἀκουσθεῖσιν, μήποτε παραρυῶμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 2, 'Εἰ γὰρ ὁ διʼ ἀγγέλων λαληθεὶς λόγος ἐγένετο βέβαιος, καὶ πᾶσα παράβασις καὶ παρακοὴ ἔλαβεν ἔνδικον μισθαποδοσίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 3, 'πῶς ἡμεῖς ἐκφευξόμεθα τηλικαύτης ἀμελήσαντες σωτηρίας; Ἥτις ἀρχὴν λαβοῦσα, λαλεῖσθαι διὰ τοῦ  ̊Κυρίου, ὑπὸ τῶν ἀκουσάντων εἰς ἡμᾶς ἐβεβαιώθη,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 4, 'συνεπιμαρτυροῦντος τοῦ  ̊Θεοῦ σημείοις τε, καὶ τέρασιν, καὶ ποικίλαις δυνάμεσιν, καὶ  ̊Πνεύματος Ἁγίου μερισμοῖς, κατὰ τὴν αὐτοῦ θέλησιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 5, '¶Οὐ γὰρ ἀγγέλοις ὑπέταξεν τὴν οἰκουμένην τὴν μέλλουσαν, περὶ ἧς λαλοῦμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 6, 'Διεμαρτύρατο δέ πού τις λέγων, “Τί ἐστιν ἄνθρωπος, ὅτι μιμνῄσκῃ αὐτοῦ, ἢ υἱὸς ἀνθρώπου, ὅτι ἐπισκέπτῃ αὐτόν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 7, 'Ἠλάττωσας αὐτὸν, βραχύ τι παρʼ ἀγγέλους, δόξῃ καὶ τιμῇ ἐστεφάνωσας αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 8, 'πάντα ὑπέταξας ὑποκάτω τῶν ποδῶν αὐτοῦ.” Ἐν γὰρ τῷ ὑποτάξαι αὐτῷ τὰ πάντα, οὐδὲν ἀφῆκεν αὐτῷ ἀνυπότακτον. Νῦν δὲ οὔπω ὁρῶμεν αὐτῷ τὰ πάντα ὑποτεταγμένα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 9, 'Τὸν δὲ βραχύ τι παρʼ ἀγγέλους ἠλαττωμένον, βλέπομεν  ̊Ἰησοῦν, διὰ τὸ πάθημα τοῦ θανάτου, δόξῃ καὶ τιμῇ ἐστεφανωμένον, ὅπως χάριτι  ̊Θεοῦ, ὑπὲρ παντὸς γεύσηται θανάτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 10, '¶Ἔπρεπεν γὰρ αὐτῷ, διʼ ὃν τὰ πάντα, καὶ διʼ οὗ τὰ πάντα, πολλοὺς υἱοὺς εἰς δόξαν ἀγαγόντα, τὸν ἀρχηγὸν τῆς σωτηρίας αὐτῶν, διὰ παθημάτων τελειῶσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 11, 'Ὅ τε γὰρ ἁγιάζων, καὶ οἱ ἁγιαζόμενοι, ἐξ ἑνὸς πάντες· διʼ ἣν αἰτίαν, οὐκ ἐπαισχύνεται ἀδελφοὺς αὐτοὺς καλεῖν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 12, 'λέγων, “Ἀπαγγελῶ τὸ ὄνομά σου τοῖς ἀδελφοῖς μου, ἐν μέσῳ ἐκκλησίας ὑμνήσω σε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 13, 'Καὶ πάλιν, “Ἐγὼ ἔσομαι πεποιθὼς ἐπʼ αὐτῷ.” Καὶ πάλιν, “Ἰδοὺ, ἐγὼ καὶ τὰ παιδία, ἅ μοι ἔδωκεν ὁ  ̊Θεός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 14, '¶Ἐπεὶ οὖν τὰ παιδία κεκοινώνηκεν αἵματος καὶ σαρκός, καὶ αὐτὸς παραπλησίως μετέσχεν τῶν αὐτῶν, ἵνα διὰ τοῦ θανάτου, καταργήσῃ τὸν τὸ κράτος ἔχοντα τοῦ θανάτου, τοῦτʼ ἔστιν τὸν διάβολον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 15, 'καὶ ἀπαλλάξῃ τούτους, ὅσοι φόβῳ θανάτου, διὰ παντὸς τοῦ ζῆν, ἔνοχοι ἦσαν δουλείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 16, 'Οὐ γὰρ δήπου ἀγγέλων ἐπιλαμβάνεται, ἀλλὰ σπέρματος Ἀβραὰμ ἐπιλαμβάνεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 17, 'Ὅθεν ὤφειλεν κατὰ πάντα τοῖς ἀδελφοῖς ὁμοιωθῆναι, ἵνα ἐλεήμων γένηται καὶ πιστὸς ἀρχιερεὺς τὰ πρὸς τὸν  ̊Θεόν, εἰς τὸ ἱλάσκεσθαι τὰς ἁμαρτίας τοῦ λαοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 18, 'Ἐν ᾧ γὰρ πέπονθεν αὐτὸς πειρασθείς, δύναται τοῖς πειραζομένοις βοηθῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 1, '¶Ὅθεν, ἀδελφοὶ ἅγιοι κλήσεως ἐπουρανίου, μέτοχοι, κατανοήσατε τὸν ἀπόστολον καὶ ἀρχιερέα τῆς ὁμολογίας ἡμῶν,  ̊Ἰησοῦν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 2, 'πιστὸν ὄντα τῷ ποιήσαντι αὐτὸν, ὡς καὶ Μωϋσῆς ἐν τῷ οἴκῳ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 3, 'Πλείονος γὰρ οὗτος δόξης παρὰ Μωϋσῆν ἠξίωται, καθʼ ὅσον πλείονα τιμὴν ἔχει τοῦ οἴκου, ὁ κατασκευάσας αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 4, 'Πᾶς γὰρ οἶκος κατασκευάζεται ὑπό τινος, ὁ δὲ πάντα κατασκευάσας  ̊Θεός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 5, 'Καὶ Μωϋσῆς μὲν πιστὸς ἐν ὅλῳ τῷ οἴκῳ αὐτοῦ, ὡς θεράπων εἰς μαρτύριον τῶν λαληθησομένων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 6, ' ̊Χριστὸς δὲ ὡς Υἱὸς ἐπὶ τὸν οἶκον αὐτοῦ, οὗ οἶκός ἐσμεν ἡμεῖς, ἐὰν τὴν παρρησίαν καὶ τὸ καύχημα τῆς ἐλπίδος κατάσχωμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 7, '¶Διό καθὼς λέγει τὸ  ̊Πνεῦμα τὸ Ἅγιον, “Σήμερον ἐὰν τῆς φωνῆς αὐτοῦ ἀκούσητε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 8, 'μὴ σκληρύνητε τὰς καρδίας ὑμῶν, ὡς ἐν τῷ παραπικρασμῷ, κατὰ τὴν ἡμέραν τοῦ πειρασμοῦ, ἐν τῇ ἐρήμῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 9, 'οὗ ἐπείρασαν οἱ πατέρες ὑμῶν ἐν δοκιμασίᾳ, καὶ εἶδον τὰ ἔργα μου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 10, 'τεσσεράκοντα ἔτη. Διὸ προσώχθισα τῇ γενεᾷ ταύτῃ, καὶ εἶπον, ‘Ἀεὶ πλανῶνται τῇ καρδίᾳ· αὐτοὶ δὲ οὐκ ἔγνωσαν τὰς ὁδούς μου’·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 11, 'ὡς ὤμοσα ἐν τῇ ὀργῇ μου, ‘Εἰ εἰσελεύσονται εἰς τὴν κατάπαυσίν μου.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 12, 'Βλέπετε, ἀδελφοί, μήποτε ἔσται ἔν τινι ὑμῶν καρδία πονηρὰ ἀπιστίας, ἐν τῷ ἀποστῆναι ἀπὸ  ̊Θεοῦ ζῶντος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 13, 'Ἀλλὰ παρακαλεῖτε ἑαυτοὺς καθʼ ἑκάστην ἡμέραν, ἄχρις οὗ, τὸ “σήμερον” καλεῖται, ἵνα μὴ σκληρυνθῇ τις ἐξ ὑμῶν ἀπάτῃ τῆς ἁμαρτίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 14, 'Μέτοχοι γὰρ τοῦ  ̊Χριστοῦ γεγόναμεν, ἐάνπερ τὴν ἀρχὴν τῆς ὑποστάσεως, μέχρι τέλους βεβαίαν κατάσχωμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 15, 'Ἐν τῷ λέγεσθαι, “Σήμερον ἐὰν τῆς φωνῆς αὐτοῦ ἀκούσητε, μὴ σκληρύνητε τὰς καρδίας ὑμῶν, ὡς ἐν τῷ παραπικρασμῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 16, 'Τίνες γὰρ ἀκούσαντες παρεπίκραναν; Ἀλλʼ οὐ πάντες οἱ ἐξελθόντες ἐξ Αἰγύπτου διὰ Μωϋσέως;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 17, 'Τίσιν δὲ προσώχθισεν τεσσεράκοντα ἔτη; Οὐχὶ τοῖς ἁμαρτήσασιν, ὧν τὰ κῶλα ἔπεσεν ἐν τῇ ἐρήμῳ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 18, 'Τίσιν δὲ ὤμοσεν μὴ εἰσελεύσεσθαι εἰς τὴν κατάπαυσιν αὐτοῦ, εἰ μὴ τοῖς ἀπειθήσασιν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 19, 'Καὶ βλέπομεν ὅτι οὐκ ἠδυνήθησαν εἰσελθεῖν διʼ ἀπιστίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 1, '¶Φοβηθῶμεν οὖν, μήποτε καταλειπομένης ἐπαγγελίας εἰσελθεῖν εἰς τὴν κατάπαυσιν αὐτοῦ, δοκῇ τις ἐξ ὑμῶν ὑστερηκέναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 2, 'Καὶ γάρ ἐσμεν εὐηγγελισμένοι καθάπερ κἀκεῖνοι, ἀλλʼ οὐκ ὠφέλησεν ὁ λόγος τῆς ἀκοῆς ἐκείνους, μὴ συγκεκερασμένους τῇ πίστει τοῖς ἀκούσασιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 3, 'Εἰσερχόμεθα γὰρ εἰς κατάπαυσιν, οἱ πιστεύσαντες, καθὼς εἴρηκεν, “Ὡς ὤμοσα ἐν τῇ ὀργῇ μου, ‘Εἰ εἰσελεύσονται εἰς τὴν κατάπαυσίν μου’”, καίτοι τῶν ἔργων ἀπὸ καταβολῆς κόσμου γενηθέντων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 4, 'Εἴρηκεν γάρ που περὶ τῆς ἑβδόμης οὕτως: “Καὶ κατέπαυσεν ὁ  ̊Θεὸς ἐν τῇ ἡμέρᾳ τῇ ἑβδόμῃ ἀπὸ πάντων τῶν ἔργων αὐτοῦ”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 5, 'καὶ ἐν τούτῳ πάλιν, “Εἰ εἰσελεύσονται εἰς τὴν κατάπαυσίν μου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 6, 'Ἐπεὶ οὖν ἀπολείπεται τινὰς εἰσελθεῖν εἰς αὐτήν, καὶ οἱ πρότερον εὐαγγελισθέντες, οὐκ εἰσῆλθον διʼ ἀπείθειαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 7, 'πάλιν τινὰ ὁρίζει ἡμέραν, “σήμερον”, ἐν Δαυὶδ λέγων μετὰ τοσοῦτον χρόνον, καθὼς προείρηται, “Σήμερον ἐὰν τῆς φωνῆς αὐτοῦ ἀκούσητε, μὴ σκληρύνητε τὰς καρδίας ὑμῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 8, 'Εἰ γὰρ αὐτοὺς Ἰησοῦς κατέπαυσεν, οὐκ ἂν περὶ ἄλλης ἐλάλει μετὰ ταῦτα ἡμέρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 9, 'Ἄρα ἀπολείπεται σαββατισμὸς τῷ λαῷ τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 10, 'Ὁ γὰρ εἰσελθὼν εἰς τὴν κατάπαυσιν αὐτοῦ, καὶ αὐτὸς κατέπαυσεν ἀπὸ τῶν ἔργων αὐτοῦ, ὥσπερ ἀπὸ τῶν ἰδίων ὁ  ̊Θεός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 11, 'Σπουδάσωμεν οὖν εἰσελθεῖν εἰς ἐκείνην τὴν κατάπαυσιν, ἵνα μὴ ἐν τῷ αὐτῷ τις ὑποδείγματι πέσῃ τῆς ἀπειθείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 12, '¶Ζῶν γὰρ ὁ λόγος τοῦ  ̊Θεοῦ, καὶ ἐνεργὴς, καὶ τομώτερος, ὑπὲρ πᾶσαν μάχαιραν δίστομον, καὶ διϊκνούμενος ἄχρι μερισμοῦ ψυχῆς καὶ πνεύματος, ἁρμῶν τε καὶ μυελῶν, καὶ κριτικὸς ἐνθυμήσεων καὶ ἐννοιῶν καρδίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 13, 'Καὶ οὐκ ἔστιν κτίσις ἀφανὴς ἐνώπιον αὐτοῦ, πάντα δὲ γυμνὰ καὶ τετραχηλισμένα τοῖς ὀφθαλμοῖς αὐτοῦ, πρὸς ὃν ἡμῖν ὁ λόγος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 14, '¶Ἔχοντες οὖν ἀρχιερέα μέγαν, διεληλυθότα τοὺς οὐρανούς,  ̊Ἰησοῦν, τὸν Υἱὸν τοῦ  ̊Θεοῦ, κρατῶμεν τῆς ὁμολογίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 15, 'Οὐ γὰρ ἔχομεν ἀρχιερέα μὴ δυνάμενον συμπαθῆσαι ταῖς ἀσθενείαις ἡμῶν, πεπειρασμένον δὲ κατὰ πάντα καθʼ ὁμοιότητα χωρὶς ἁμαρτίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 16, 'Προσερχώμεθα οὖν μετὰ παρρησίας τῷ θρόνῳ τῆς χάριτος, ἵνα λάβωμεν ἔλεος, καὶ χάριν εὕρωμεν, εἰς εὔκαιρον βοήθειαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 1, '¶Πᾶς γὰρ ἀρχιερεὺς ἐξ ἀνθρώπων λαμβανόμενος ὑπὲρ ἀνθρώπων καθίσταται τὰ πρὸς τὸν  ̊Θεόν, ἵνα προσφέρῃ δῶρά τε καὶ θυσίας ὑπὲρ ἁμαρτιῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 2, 'μετριοπαθεῖν δυνάμενος τοῖς ἀγνοοῦσι καὶ πλανωμένοις, ἐπεὶ καὶ αὐτὸς περίκειται ἀσθένειαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 3, 'καὶ διʼ αὐτὴν ὀφείλει, καθὼς περὶ τοῦ λαοῦ οὕτως καὶ περὶ αὑτοῦ, προσφέρειν περὶ ἁμαρτιῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 4, 'Καὶ οὐχ ἑαυτῷ τις λαμβάνει τὴν τιμήν, ἀλλὰ καλούμενος ὑπὸ τοῦ  ̊Θεοῦ, καθώσπερ καὶ Ἀαρών.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 5, '¶Οὕτως καὶ ὁ  ̊Χριστὸς οὐχ ἑαυτὸν ἐδόξασεν γενηθῆναι ἀρχιερέα, ἀλλʼ ὁ λαλήσας πρὸς αὐτόν, “Υἱός μου εἶ σύ, ἐγὼ σήμερον γεγέννηκά σε.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 6, 'Καθὼς καὶ ἐν ἑτέρῳ λέγει, “Σὺ ἱερεὺς εἰς τὸν αἰῶνα κατὰ τὴν τάξιν Μελχισέδεκ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 7, 'Ὃς ἐν ταῖς ἡμέραις τῆς σαρκὸς αὐτοῦ, δεήσεις τε καὶ ἱκετηρίας, πρὸς τὸν δυνάμενον σῴζειν αὐτὸν ἐκ θανάτου, μετὰ κραυγῆς ἰσχυρᾶς καὶ δακρύων προσενέγκας, καὶ εἰσακουσθεὶς ἀπὸ τῆς εὐλαβείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 8, 'Καίπερ ὢν υἱός, ἔμαθεν ἀφʼ ὧν ἔπαθεν τὴν ὑπακοήν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 9, 'καὶ τελειωθεὶς, ἐγένετο πᾶσιν τοῖς ὑπακούουσιν αὐτῷ αἴτιος σωτηρίας αἰωνίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 10, 'προσαγορευθεὶς ὑπὸ τοῦ  ̊Θεοῦ ἀρχιερεὺς κατὰ τὴν τάξιν Μελχισέδεκ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 11, '¶Περὶ οὗ πολὺς ἡμῖν ὁ λόγος, καὶ δυσερμήνευτος λέγειν, ἐπεὶ νωθροὶ γεγόνατε ταῖς ἀκοαῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 12, 'Καὶ γὰρ ὀφείλοντες εἶναι διδάσκαλοι διὰ τὸν χρόνον, πάλιν χρείαν ἔχετε τοῦ διδάσκειν ὑμᾶς, τινὰ τὰ στοιχεῖα τῆς ἀρχῆς τῶν λογίων τοῦ  ̊Θεοῦ, καὶ γεγόνατε χρείαν ἔχοντες γάλακτος, οὐ στερεᾶς τροφῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 13, 'Πᾶς γὰρ ὁ μετέχων γάλακτος ἄπειρος λόγου δικαιοσύνης, νήπιος γάρ ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 14, 'Τελείων δέ ἐστιν ἡ στερεὰ τροφή, τῶν διὰ τὴν ἕξιν τὰ αἰσθητήρια γεγυμνασμένα, ἐχόντων πρὸς διάκρισιν, καλοῦ τε καὶ κακοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 1, '¶Διὸ ἀφέντες τὸν τῆς ἀρχῆς τοῦ  ̊Χριστοῦ λόγον, ἐπὶ τὴν τελειότητα φερώμεθα, μὴ πάλιν θεμέλιον καταβαλλόμενοι μετανοίας ἀπὸ νεκρῶν ἔργων, καὶ πίστεως ἐπὶ  ̊Θεόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 2, 'βαπτισμῶν διδαχὴν, ἐπιθέσεώς τε χειρῶν, ἀναστάσεώς τε νεκρῶν, καὶ κρίματος αἰωνίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 3, 'Καὶ τοῦτο ποιήσομεν, ἐάνπερ ἐπιτρέπῃ ὁ  ̊Θεός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 4, 'Ἀδύνατον γὰρ τοὺς ἅπαξ φωτισθέντας, γευσαμένους τε τῆς δωρεᾶς τῆς ἐπουρανίου, καὶ μετόχους γενηθέντας  ̊Πνεύματος Ἁγίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 5, 'καὶ καλὸν γευσαμένους  ̊Θεοῦ ῥῆμα, δυνάμεις τε μέλλοντος αἰῶνος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 6, 'καὶ παραπεσόντας, πάλιν ἀνακαινίζειν εἰς μετάνοιαν, ἀνασταυροῦντας ἑαυτοῖς τὸν Υἱὸν τοῦ  ̊Θεοῦ, καὶ παραδειγματίζοντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 7, 'Γῆ γὰρ ἡ πιοῦσα τὸν ἐπʼ αὐτῆς ἐρχόμενον πολλάκις ὑετόν, καὶ τίκτουσα βοτάνην εὔθετον, ἐκείνοις διʼ οὓς καὶ γεωργεῖται, μεταλαμβάνει εὐλογίας ἀπὸ τοῦ  ̊Θεοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 8, 'ἐκφέρουσα δὲ ἀκάνθας καὶ τριβόλους, ἀδόκιμος καὶ κατάρας ἐγγύς, ἧς τὸ τέλος εἰς καῦσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 9, '¶Πεπείσμεθα δὲ περὶ ὑμῶν, ἀγαπητοί, τὰ κρείσσονα καὶ ἐχόμενα σωτηρίας, εἰ καὶ οὕτως λαλοῦμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 10, 'Οὐ γὰρ ἄδικος ὁ  ̊Θεὸς, ἐπιλαθέσθαι τοῦ ἔργου ὑμῶν, καὶ τῆς ἀγάπης ἧς ἐνεδείξασθε εἰς τὸ ὄνομα αὐτοῦ, διακονήσαντες τοῖς ἁγίοις καὶ διακονοῦντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 11, 'Ἐπιθυμοῦμεν δὲ ἕκαστον ὑμῶν τὴν αὐτὴν ἐνδείκνυσθαι σπουδὴν, πρὸς τὴν πληροφορίαν τῆς ἐλπίδος ἄχρι τέλους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 12, 'ἵνα μὴ νωθροὶ γένησθε, μιμηταὶ δὲ τῶν διὰ πίστεως καὶ μακροθυμίας, κληρονομούντων τὰς ἐπαγγελίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 13, '¶Τῷ γὰρ Ἀβραὰμ ἐπαγγειλάμενος ὁ  ̊Θεός, ἐπεὶ κατʼ οὐδενὸς εἶχεν μείζονος ὀμόσαι, ὤμοσεν καθʼ ἑαυτοῦ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 14, 'λέγων, “Εἰ μὴν εὐλογῶν, εὐλογήσω σε, καὶ πληθύνων, πληθυνῶ σε”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 15, 'Καὶ οὕτως μακροθυμήσας, ἐπέτυχεν τῆς ἐπαγγελίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 16, 'Ἄνθρωποι γὰρ κατὰ τοῦ μείζονος ὀμνύουσιν, καὶ πάσης αὐτοῖς ἀντιλογίας πέρας, εἰς βεβαίωσιν ὁ ὅρκος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 17, 'Ἐν ᾧ περισσότερον βουλόμενος ὁ  ̊Θεὸς ἐπιδεῖξαι τοῖς κληρονόμοις τῆς ἐπαγγελίας, τὸ ἀμετάθετον τῆς βουλῆς αὐτοῦ, ἐμεσίτευσεν ὅρκῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 18, 'ἵνα διὰ δύο πραγμάτων ἀμεταθέτων, ἐν οἷς ἀδύνατον ψεύσασθαι τὸν  ̊Θεόν, ἰσχυρὰν παράκλησιν ἔχωμεν, οἱ καταφυγόντες κρατῆσαι τῆς προκειμένης ἐλπίδος·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 19, 'ἣν ὡς ἄγκυραν ἔχομεν τῆς ψυχῆς, ἀσφαλῆ τε καὶ βεβαίαν, καὶ εἰσερχομένην εἰς τὸ ἐσώτερον τοῦ καταπετάσματος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 20, 'ὅπου πρόδρομος ὑπὲρ ἡμῶν εἰσῆλθεν,  ̊Ἰησοῦς, κατὰ τὴν τάξιν Μελχισέδεκ, ἀρχιερεὺς γενόμενος εἰς τὸν αἰῶνα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 1, '¶Οὗτος γὰρ ὁ Μελχισέδεκ, βασιλεὺς Σαλήμ, ἱερεὺς τοῦ  ̊Θεοῦ τοῦ Ὑψίστου, ὁ συναντήσας Ἀβραὰμ ὑποστρέφοντι ἀπὸ τῆς κοπῆς τῶν βασιλέων, καὶ εὐλογήσας αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 2, 'ᾧ καὶ δεκάτην ἀπὸ πάντων ἐμέρισεν Ἀβραάμ, πρῶτον μὲν ἑρμηνευόμενος “Βασιλεὺς δικαιοσύνης”, ἔπειτα δὲ καὶ “Βασιλεὺς Σαλήμ”, ὅ ἐστιν, “Βασιλεὺς εἰρήνης”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 3, 'ἀπάτωρ, ἀμήτωρ, ἀγενεαλόγητος, μήτε ἀρχὴν ἡμερῶν, μήτε ζωῆς τέλος ἔχων, ἀφωμοιωμένος δὲ τῷ Υἱῷ τοῦ  ̊Θεοῦ, μένει ἱερεὺς εἰς τὸ διηνεκές.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 4, '¶Θεωρεῖτε δὲ πηλίκος οὗτος, ᾧ δεκάτην Ἀβραὰμ, ἔδωκεν ἐκ τῶν ἀκροθινίων, ὁ πατριάρχης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 5, 'Καὶ οἱ μὲν ἐκ τῶν υἱῶν Λευὶ τὴν ἱερατείαν λαμβάνοντες, ἐντολὴν ἔχουσιν ἀποδεκατοῖν τὸν λαὸν κατὰ τὸν νόμον, τοῦτʼ ἔστιν τοὺς ἀδελφοὺς αὐτῶν, καίπερ ἐξεληλυθότας ἐκ τῆς ὀσφύος Ἀβραάμ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 6, 'ὁ δὲ μὴ γενεαλογούμενος ἐξ αὐτῶν, δεδεκάτωκεν Ἀβραάμ, καὶ τὸν ἔχοντα τὰς ἐπαγγελίας, εὐλόγηκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 7, 'Χωρὶς δὲ πάσης ἀντιλογίας, τὸ ἔλαττον ὑπὸ τοῦ κρείττονος εὐλογεῖται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 8, 'Καὶ ὧδε μὲν δεκάτας ἀποθνῄσκοντες ἄνθρωποι λαμβάνουσιν, ἐκεῖ δὲ μαρτυρούμενος ὅτι ζῇ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 9, 'Καὶ ὡς ἔπος εἰπεῖν, διʼ Ἀβραὰμ, καὶ Λευεὶς, ὁ δεκάτας λαμβάνων, δεδεκάτωται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 10, 'Ἔτι γὰρ ἐν τῇ ὀσφύϊ τοῦ πατρὸς ἦν, ὅτε συνήντησεν αὐτῷ Μελχισέδεκ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 11, '¶Εἰ μὲν οὖν τελείωσις διὰ τῆς Λευιτικῆς ἱερωσύνης ἦν, ὁ λαὸς γὰρ ἐπʼ αὐτῆς νενομοθέτηται, τίς ἔτι χρεία κατὰ τὴν τάξιν Μελχισέδεκ, ἕτερον ἀνίστασθαι ἱερέα, καὶ οὐ κατὰ τὴν τάξιν Ἀαρὼν λέγεσθαι;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 12, 'Μετατιθεμένης γὰρ τῆς ἱερωσύνης, ἐξ ἀνάγκης καὶ νόμου μετάθεσις γίνεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 13, 'Ἐφʼ ὃν γὰρ λέγεται ταῦτα, φυλῆς ἑτέρας μετέσχηκεν, ἀφʼ ἧς οὐδεὶς προσέσχηκεν τῷ θυσιαστηρίῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 14, 'Πρόδηλον γὰρ, ὅτι ἐξ Ἰούδα ἀνατέταλκεν ὁ  ̊Κύριος ἡμῶν, εἰς ἣν φυλὴν περὶ ἱερέων οὐδὲν Μωϋσῆς ἐλάλησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 15, '¶Καὶ περισσότερον ἔτι κατάδηλόν ἐστιν, εἰ κατὰ τὴν ὁμοιότητα Μελχισέδεκ, ἀνίσταται ἱερεὺς ἕτερος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 16, 'ὃς οὐ κατὰ νόμον ἐντολῆς σαρκίνης γέγονεν, ἀλλὰ κατὰ δύναμιν ζωῆς ἀκαταλύτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 17, 'Μαρτυρεῖται γὰρ, ὅτι “Σὺ ἱερεὺς εἰς τὸν αἰῶνα κατὰ τὴν τάξιν Μελχισέδεκ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 18, 'Ἀθέτησις μὲν γὰρ γίνεται προαγούσης ἐντολῆς, διὰ τὸ αὐτῆς ἀσθενὲς καὶ ἀνωφελές,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 19, '(οὐδὲν γὰρ ἐτελείωσεν ὁ νόμος), ἐπεισαγωγὴ δὲ κρείττονος ἐλπίδος, διʼ ἧς ἐγγίζομεν τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 20, '¶Καὶ καθʼ ὅσον οὐ χωρὶς ὁρκωμοσίας, οἱ μὲν γὰρ χωρὶς ὁρκωμοσίας εἰσὶν ἱερεῖς γεγονότες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 21, 'ὁ δὲ μετὰ ὁρκωμοσίας διὰ τοῦ λέγοντος πρὸς αὐτόν, “Ὤμοσεν  ̊Κύριος, καὶ οὐ μεταμεληθήσεται, ‘Σὺ ἱερεὺς εἰς τὸν αἰῶνα’”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 22, 'κατὰ τοσοῦτο καὶ κρείττονος διαθήκης, γέγονεν ἔγγυος,  ̊Ἰησοῦς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 23, '¶Καὶ οἱ μὲν πλείονές εἰσιν γεγονότες ἱερεῖς, διὰ τὸ θανάτῳ κωλύεσθαι παραμένειν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 24, 'ὁ δὲ διὰ τὸ μένειν αὐτὸν εἰς τὸν αἰῶνα, ἀπαράβατον ἔχει τὴν ἱερωσύνην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 25, 'Ὅθεν καὶ σῴζειν εἰς τὸ παντελὲς δύναται, τοὺς προσερχομένους διʼ αὐτοῦ τῷ  ̊Θεῷ, πάντοτε ζῶν εἰς τὸ ἐντυγχάνειν ὑπὲρ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 26, '¶Τοιοῦτος γὰρ ἡμῖν καὶ ἔπρεπεν ἀρχιερεύς, ὅσιος, ἄκακος, ἀμίαντος, κεχωρισμένος ἀπὸ τῶν ἁμαρτωλῶν, καὶ ὑψηλότερος τῶν οὐρανῶν γενόμενος·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 27, 'ὃς οὐκ ἔχει καθʼ ἡμέραν ἀνάγκην, ὥσπερ οἱ ἀρχιερεῖς, πρότερον ὑπὲρ τῶν ἰδίων ἁμαρτιῶν θυσίας ἀναφέρειν, ἔπειτα τῶν τοῦ λαοῦ· τοῦτο γὰρ ἐποίησεν ἐφάπαξ, ἑαυτὸν ἀνενέγκας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 28, 'Ὁ νόμος γὰρ ἀνθρώπους καθίστησιν ἀρχιερεῖς ἔχοντας ἀσθένειαν, ὁ λόγος δὲ τῆς ὁρκωμοσίας, τῆς μετὰ τὸν νόμον, Υἱόν, εἰς τὸν αἰῶνα τετελειωμένον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 1, '¶Κεφάλαιον δὲ ἐπὶ τοῖς λεγομένοις: τοιοῦτον ἔχομεν ἀρχιερέα, ὃς ἐκάθισεν ἐν δεξιᾷ τοῦ θρόνου τῆς Μεγαλωσύνης ἐν τοῖς οὐρανοῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 2, 'τῶν ἁγίων λειτουργὸς καὶ τῆς σκηνῆς τῆς ἀληθινῆς, ἣν ἔπηξεν ὁ  ̊Κύριος, οὐκ ἄνθρωπος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 3, 'Πᾶς γὰρ ἀρχιερεὺς εἰς τὸ προσφέρειν, δῶρά τε καὶ θυσίας καθίσταται· ὅθεν ἀναγκαῖον ἔχειν τι καὶ τοῦτον ὃ προσενέγκῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 4, 'Εἰ μὲν οὖν ἦν ἐπὶ γῆς, οὐδʼ ἂν ἦν ἱερεύς, ὄντων τῶν προσφερόντων κατὰ νόμον τὰ δῶρα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 5, 'οἵτινες ὑποδείγματι καὶ σκιᾷ λατρεύουσιν τῶν ἐπουρανίων, καθὼς κεχρημάτισται Μωϋσῆς, μέλλων ἐπιτελεῖν τὴν σκηνήν, “Ὅρα”, γάρ φησίν, “ποιήσεις πάντα κατὰ τὸν τύπον τὸν δειχθέντα σοι ἐν τῷ ὄρει”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 6, 'νῦν δὲ διαφορωτέρας τέτυχεν λειτουργίας, ὅσῳ καὶ κρείττονός ἐστιν διαθήκης μεσίτης, ἥτις ἐπὶ κρείττοσιν ἐπαγγελίαις νενομοθέτηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 7, '¶Εἰ γὰρ ἡ πρώτη ἐκείνη ἦν ἄμεμπτος, οὐκ ἂν δευτέρας ἐζητεῖτο τόπος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 8, 'Μεμφόμενος γὰρ αὐτοῖς λέγει, “Ἰδοὺ, ἡμέραι ἔρχονται, λέγει  ̊Κύριος, καὶ συντελέσω, ἐπὶ τὸν οἶκον Ἰσραὴλ, καὶ ἐπὶ τὸν οἶκον Ἰούδα, διαθήκην καινήν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 9, 'οὐ κατὰ τὴν διαθήκην ἣν ἐποίησα τοῖς πατράσιν αὐτῶν, ἐν ἡμέρᾳ ἐπιλαβομένου μου τῆς χειρὸς αὐτῶν, ἐξαγαγεῖν αὐτοὺς ἐκ γῆς Αἰγύπτου, ὅτι αὐτοὶ οὐκ ἐνέμειναν ἐν τῇ διαθήκῃ μου, κἀγὼ ἠμέλησα αὐτῶν, λέγει  ̊Κύριος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 10, 'Ὅτι αὕτη ἡ διαθήκη, ἣν διαθήσομαι τῷ οἴκῳ Ἰσραὴλ μετὰ τὰς ἡμέρας ἐκείνας, λέγει  ̊Κύριος, διδοὺς νόμους μου εἰς τὴν διάνοιαν αὐτῶν, καὶ ἐπὶ καρδίας αὐτῶν ἐπιγράψω αὐτούς, καὶ ἔσομαι αὐτοῖς εἰς  ̊Θεόν, καὶ αὐτοὶ ἔσονταί μοι εἰς λαόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 11, 'Καὶ οὐ μὴ διδάξωσιν ἕκαστος τὸν πολίτην αὐτοῦ, καὶ ἕκαστος τὸν ἀδελφὸν αὐτοῦ λέγων, ‘Γνῶθι τὸν  ̊Κύριον’, ὅτι πάντες εἰδήσουσίν με, ἀπὸ μικροῦ ἕως μεγάλου αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 12, 'Ὅτι ἵλεως ἔσομαι ταῖς ἀδικίαις αὐτῶν, καὶ τῶν ἁμαρτιῶν αὐτῶν οὐ μὴ μνησθῶ ἔτι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 13, 'Ἐν τῷ λέγειν, “Καινὴν”, πεπαλαίωκεν τὴν πρώτην. Τὸ δὲ παλαιούμενον καὶ γηράσκον ἐγγὺς ἀφανισμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 1, '¶Εἶχε μὲν οὖν ἡ πρώτη δικαιώματα λατρείας, τό τε ἅγιον κοσμικόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 2, 'Σκηνὴ γὰρ κατεσκευάσθη ἡ πρώτη, ἐν ᾗ ἥ τε λυχνία καὶ ἡ τράπεζα, καὶ ἡ Πρόθεσις τῶν ἄρτων, ἥτις λέγεται Ἅγια.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 3, 'Μετὰ δὲ τὸ δεύτερον καταπέτασμα σκηνὴ, ἡ λεγομένη Ἅγια Ἁγίων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 4, 'χρυσοῦν ἔχουσα θυμιατήριον καὶ τὴν κιβωτὸν τῆς διαθήκης, περικεκαλυμμένην πάντοθεν χρυσίῳ, ἐν ᾗ στάμνος χρυσῆ ἔχουσα τὸ μάννα, καὶ ἡ ῥάβδος Ἀαρὼν ἡ βλαστήσασα, καὶ αἱ πλάκες τῆς διαθήκης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 5, 'Ὑπεράνω δὲ αὐτῆς, Χερουβεὶν δόξης κατασκιάζοντα τὸ ἱλαστήριον· περὶ ὧν οὐκ ἔστιν νῦν λέγειν κατὰ μέρος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 6, '¶Τούτων δὲ οὕτως κατεσκευασμένων, εἰς μὲν τὴν πρώτην σκηνὴν, διὰ παντὸς εἰσίασιν οἱ ἱερεῖς, τὰς λατρείας ἐπιτελοῦντες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 7, 'εἰς δὲ τὴν δευτέραν, ἅπαξ τοῦ ἐνιαυτοῦ μόνος ὁ ἀρχιερεύς, οὐ χωρὶς αἵματος, ὃ προσφέρει ὑπὲρ ἑαυτοῦ καὶ τῶν τοῦ λαοῦ ἀγνοημάτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 8, 'Τοῦτο δηλοῦντος τοῦ  ̊Πνεύματος τοῦ Ἁγίου, μήπω πεφανερῶσθαι τὴν τῶν ἁγίων ὁδὸν, ἔτι τῆς πρώτης σκηνῆς ἐχούσης στάσιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 9, 'ἥτις παραβολὴ εἰς τὸν καιρὸν τὸν ἐνεστηκότα, καθʼ ἣν δῶρά τε καὶ θυσίαι προσφέρονται, μὴ δυνάμεναι κατὰ συνείδησιν τελειῶσαι τὸν λατρεύοντα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 10, 'μόνον ἐπὶ βρώμασιν, καὶ πόμασιν, καὶ διαφόροις βαπτισμοῖς, δικαιώματα σαρκὸς, μέχρι καιροῦ διορθώσεως ἐπικείμενα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 11, '¶ ̊Χριστὸς δὲ παραγενόμενος ἀρχιερεὺς, τῶν γενομένων ἀγαθῶν, διὰ τῆς μείζονος καὶ τελειοτέρας σκηνῆς, οὐ χειροποιήτου τοῦτʼ ἔστιν, οὐ ταύτης τῆς κτίσεως,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 12, 'οὐδὲ διʼ αἵματος τράγων καὶ μόσχων, διὰ δὲ τοῦ ἰδίου αἵματος, εἰσῆλθεν ἐφάπαξ εἰς τὰ ἅγια, αἰωνίαν λύτρωσιν εὑράμενος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 13, 'Εἰ γὰρ τὸ αἷμα τράγων, καὶ ταύρων, καὶ σποδὸς δαμάλεως, ῥαντίζουσα τοὺς κεκοινωμένους, ἁγιάζει πρὸς τὴν τῆς σαρκὸς καθαρότητα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 14, 'πόσῳ μᾶλλον τὸ αἷμα τοῦ  ̊Χριστοῦ, ὃς διὰ  ̊Πνεύματος αἰωνίου, ἑαυτὸν προσήνεγκεν ἄμωμον τῷ  ̊Θεῷ, καθαριεῖ τὴν συνείδησιν ὑμῶν ἀπὸ νεκρῶν ἔργων, εἰς τὸ λατρεύειν  ̊Θεῷ ζῶντι!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 15, '¶Καὶ διὰ τοῦτο, διαθήκης καινῆς μεσίτης ἐστίν, ὅπως θανάτου γενομένου εἰς ἀπολύτρωσιν τῶν ἐπὶ τῇ πρώτῃ διαθήκῃ παραβάσεων, τὴν ἐπαγγελίαν λάβωσιν οἱ κεκλημένοι τῆς αἰωνίου κληρονομίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 16, 'Ὅπου γὰρ διαθήκη, θάνατον ἀνάγκη φέρεσθαι τοῦ διαθεμένου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 17, 'Διαθήκη γὰρ ἐπὶ νεκροῖς βεβαία, ἐπεὶ μήποτε ἰσχύει, ὅτε ζῇ ὁ διαθέμενος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 18, 'Ὅθεν οὐδὲ ἡ πρώτη χωρὶς αἵματος ἐγκεκαίνισται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 19, 'Λαληθείσης γὰρ πάσης ἐντολῆς κατὰ τὸν νόμον ὑπὸ Μωϋσέως παντὶ τῷ λαῷ, λαβὼν τὸ αἷμα τῶν μόσχων, καὶ τῶν τράγων, μετὰ ὕδατος, καὶ ἐρίου κοκκίνου, καὶ ὑσσώπου, αὐτό τε τὸ βιβλίον καὶ πάντα τὸν λαὸν, ἐρράντισεν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 20, 'λέγων, “Τοῦτο τὸ αἷμα τῆς διαθήκης, ἧς ἐνετείλατο πρὸς ὑμᾶς ὁ  ̊Θεός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 21, 'Καὶ τὴν σκηνὴν δὲ, καὶ πάντα τὰ σκεύη τῆς λειτουργίας, τῷ αἵματι ὁμοίως ἐρράντισεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 22, 'Καὶ σχεδὸν ἐν αἵματι πάντα καθαρίζεται κατὰ τὸν νόμον, καὶ χωρὶς αἱματεκχυσίας, οὐ γίνεται ἄφεσις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 23, '¶Ἀνάγκη οὖν τὰ μὲν ὑποδείγματα τῶν ἐν τοῖς οὐρανοῖς τούτοις καθαρίζεσθαι, αὐτὰ δὲ τὰ ἐπουράνια κρείττοσι θυσίαις παρὰ ταύτας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 24, 'Οὐ γὰρ εἰς χειροποίητα εἰσῆλθεν ἅγια  ̊Χριστός, ἀντίτυπα τῶν ἀληθινῶν, ἀλλʼ εἰς αὐτὸν τὸν οὐρανόν, νῦν ἐμφανισθῆναι τῷ προσώπῳ τοῦ  ̊Θεοῦ ὑπὲρ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 25, 'Οὐδʼ ἵνα πολλάκις προσφέρῃ ἑαυτόν, ὥσπερ ὁ ἀρχιερεὺς εἰσέρχεται εἰς τὰ ἅγια κατʼ ἐνιαυτὸν ἐν αἵματι ἀλλοτρίῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 26, 'ἐπεὶ ἔδει αὐτὸν πολλάκις παθεῖν ἀπὸ καταβολῆς κόσμου. Νυνὶ δὲ ἅπαξ ἐπὶ συντελείᾳ τῶν αἰώνων, εἰς ἀθέτησιν ἁμαρτίας διὰ τῆς θυσίας αὐτοῦ πεφανέρωται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 27, 'Καὶ καθʼ ὅσον ἀπόκειται τοῖς ἀνθρώποις ἅπαξ ἀποθανεῖν, μετὰ δὲ τοῦτο κρίσις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 28, 'οὕτως καὶ ὁ  ̊Χριστός ἅπαξ προσενεχθεὶς εἰς τὸ πολλῶν ἀνενεγκεῖν ἁμαρτίας, ἐκ δευτέρου χωρὶς ἁμαρτίας ὀφθήσεται τοῖς αὐτὸν ἀπεκδεχομένοις εἰς σωτηρίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 1, '¶Σκιὰν γὰρ ἔχων ὁ νόμος τῶν μελλόντων ἀγαθῶν, οὐκ αὐτὴν τὴν εἰκόνα τῶν πραγμάτων, κατʼ ἐνιαυτὸν ταῖς αὐταῖς θυσίαις, ἃς προσφέρουσιν εἰς τὸ διηνεκὲς, οὐδέποτε δύνανται τοὺς προσερχομένους τελειῶσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 2, 'Ἐπεὶ οὐκ ἂν ἐπαύσαντο προσφερόμεναι, διὰ τὸ μηδεμίαν ἔχειν ἔτι συνείδησιν ἁμαρτιῶν, τοὺς λατρεύοντας ἅπαξ κεκαθαρισμένους;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 3, 'Ἀλλʼ ἐν αὐταῖς ἀνάμνησις ἁμαρτιῶν κατʼ ἐνιαυτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 4, 'Ἀδύνατον γὰρ αἷμα ταύρων καὶ τράγων ἀφαιρεῖν ἁμαρτίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 5, 'Διὸ εἰσερχόμενος εἰς τὸν κόσμον, λέγει, “Θυσίαν καὶ προσφορὰν οὐκ ἠθέλησας, σῶμα δὲ κατηρτίσω μοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 6, 'Ὁλοκαυτώματα καὶ περὶ ἁμαρτίας οὐκ εὐδόκησας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 7, 'Τότε εἶπον, ‘Ἰδοὺ, ἥκω (ἐν κεφαλίδι βιβλίου γέγραπται περὶ ἐμοῦ) τοῦ ποιῆσαι ὁ  ̊Θεός τὸ θέλημά σου.’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 8, 'Ἀνώτερον λέγων, ὅτι “Θυσίας, καὶ προσφορὰς, καὶ ὁλοκαυτώματα, καὶ περὶ ἁμαρτίας, οὐκ ἠθέλησας, οὐδὲ εὐδόκησας” (αἵτινες κατὰ νόμον προσφέρονται),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 9, 'τότε εἴρηκεν, “Ἰδοὺ, ἥκω τοῦ ποιῆσαι τὸ θέλημά σου.” Ἀναιρεῖ τὸ πρῶτον, ἵνα τὸ δεύτερον στήσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 10, 'Ἐν ᾧ θελήματι, ἡγιασμένοι ἐσμὲν διὰ τῆς προσφορᾶς τοῦ σώματος  ̊Ἰησοῦ  ̊Χριστοῦ ἐφάπαξ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 11, '¶Καὶ πᾶς μὲν ἱερεὺς ἕστηκεν καθʼ ἡμέραν λειτουργῶν, καὶ τὰς αὐτὰς πολλάκις προσφέρων θυσίας, αἵτινες οὐδέποτε δύνανται περιελεῖν ἁμαρτίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 12, 'Οὗτος δὲ, μίαν ὑπὲρ ἁμαρτιῶν προσενέγκας θυσίαν, εἰς τὸ διηνεκὲς, “ἐκάθισεν ἐν δεξιᾷ τοῦ  ̊Θεοῦ”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 13, 'τὸ λοιπὸν, ἐκδεχόμενος “ἕως τεθῶσιν οἱ ἐχθροὶ αὐτοῦ ὑποπόδιον τῶν ποδῶν αὐτοῦ”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 14, 'Μιᾷ γὰρ προσφορᾷ, τετελείωκεν εἰς τὸ διηνεκὲς τοὺς ἁγιαζομένους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 15, 'Μαρτυρεῖ δὲ ἡμῖν καὶ τὸ  ̊Πνεῦμα τὸ Ἅγιον, μετὰ γὰρ τὸ εἰρηκέναι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 16, '“Αὕτη ἡ διαθήκη ἣν διαθήσομαι πρὸς αὐτοὺς μετὰ τὰς ἡμέρας ἐκείνας, λέγει  ̊Κύριος, διδοὺς νόμους μου ἐπὶ καρδίας αὐτῶν, καὶ ἐπὶ τὴν διάνοιαν αὐτῶν ἐπιγράψω αὐτούς...');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 17, 'καὶ τῶν ἁμαρτιῶν αὐτῶν, καὶ τῶν ἀνομιῶν αὐτῶν, οὐ μὴ μνησθήσομαι ἔτι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 18, 'Ὅπου δὲ ἄφεσις τούτων, οὐκέτι προσφορὰ περὶ ἁμαρτίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 19, '¶Ἔχοντες οὖν, ἀδελφοί, παρρησίαν εἰς τὴν εἴσοδον τῶν ἁγίων ἐν τῷ αἵματι  ̊Ἰησοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 20, 'ἣν ἐνεκαίνισεν ἡμῖν ὁδὸν πρόσφατον καὶ ζῶσαν διὰ τοῦ καταπετάσματος, τοῦτʼ ἔστιν τῆς σαρκὸς αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 21, 'καὶ ἱερέα μέγαν ἐπὶ τὸν οἶκον τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 22, 'προσερχώμεθα μετὰ ἀληθινῆς καρδίας ἐν πληροφορίᾳ πίστεως, ῥεραντισμένοι τὰς καρδίας ἀπὸ συνειδήσεως πονηρᾶς, καὶ λελουμένοι τὸ σῶμα ὕδατι καθαρῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 23, 'Κατέχωμεν τὴν ὁμολογίαν τῆς ἐλπίδος ἀκλινῆ, πιστὸς γὰρ ὁ ἐπαγγειλάμενος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 24, 'καὶ κατανοῶμεν ἀλλήλους εἰς παροξυσμὸν ἀγάπης καὶ καλῶν ἔργων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 25, 'μὴ ἐγκαταλείποντες τὴν ἐπισυναγωγὴν ἑαυτῶν, καθὼς ἔθος τισίν, ἀλλὰ παρακαλοῦντες καὶ τοσούτῳ μᾶλλον, ὅσῳ βλέπετε ἐγγίζουσαν τὴν ἡμέραν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 26, '¶Ἑκουσίως γὰρ ἁμαρτανόντων ἡμῶν μετὰ τὸ λαβεῖν τὴν ἐπίγνωσιν τῆς ἀληθείας, οὐκέτι περὶ ἁμαρτιῶν ἀπολείπεται θυσία,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 27, 'φοβερὰ δέ τις ἐκδοχὴ κρίσεως, καὶ “πυρὸς ζῆλος ἐσθίειν μέλλοντος τοὺς ὑπεναντίους”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 28, 'Ἀθετήσας τις νόμον Μωϋσέως χωρὶς οἰκτιρμῶν ἐπὶ δυσὶν ἢ τρισὶν μάρτυσιν ἀποθνῄσκει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 29, 'Πόσῳ δοκεῖτε χείρονος ἀξιωθήσεται τιμωρίας, ὁ τὸν Υἱὸν τοῦ  ̊Θεοῦ καταπατήσας, καὶ τὸ αἷμα τῆς διαθήκης κοινὸν ἡγησάμενος, ἐν ᾧ ἡγιάσθη, καὶ τὸ  ̊Πνεῦμα τῆς χάριτος ἐνυβρίσας!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 30, 'Οἴδαμεν γὰρ τὸν εἰπόντα, “Ἐμοὶ ἐκδίκησις, ἐγὼ ἀνταποδώσω”, καὶ πάλιν, “Κρινεῖ  ̊Κύριος τὸν λαὸν αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 31, 'Φοβερὸν τὸ ἐμπεσεῖν εἰς χεῖρας  ̊Θεοῦ ζῶντος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 32, '¶Ἀναμιμνῄσκεσθε δὲ τὰς πρότερον ἡμέρας, ἐν αἷς φωτισθέντες πολλὴν ἄθλησιν ὑπεμείνατε παθημάτων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 33, 'τοῦτο μὲν ὀνειδισμοῖς τε καὶ θλίψεσιν θεατριζόμενοι, τοῦτο δὲ κοινωνοὶ τῶν οὕτως ἀναστρεφομένων γενηθέντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 34, 'Καὶ γὰρ τοῖς δεσμίοις συνεπαθήσατε, καὶ τὴν ἁρπαγὴν τῶν ὑπαρχόντων ὑμῶν μετὰ χαρᾶς προσεδέξασθε, γινώσκοντες ἔχειν ἑαυτοὺς κρείσσονα ὕπαρξιν, καὶ μένουσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 35, 'Μὴ ἀποβάλητε οὖν τὴν παρρησίαν ὑμῶν, ἥτις ἔχει μεγάλην μισθαποδοσίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 36, 'Ὑπομονῆς γὰρ ἔχετε χρείαν, ἵνα τὸ θέλημα τοῦ  ̊Θεοῦ ποιήσαντες, κομίσησθε τὴν ἐπαγγελίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 37, '“Ἔτι γὰρ μικρὸν ὅσον, ὅσον ὁ ἐρχόμενος ἥξει, καὶ οὐ χρονίσει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 38, 'Ὁ δὲ δίκαιός μου ἐκ πίστεως ζήσεται, καὶ ἐὰν ὑποστείληται, οὐκ εὐδοκεῖ ἡ ψυχή μου ἐν αὐτῷ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 39, 'Ἡμεῖς δὲ οὐκ ἐσμὲν ὑποστολῆς εἰς ἀπώλειαν, ἀλλὰ πίστεως εἰς περιποίησιν ψυχῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 1, '¶Ἔστιν δὲ πίστις ἐλπιζομένων ὑπόστασις, πραγμάτων ἔλεγχος οὐ βλεπομένων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 2, 'Ἐν ταύτῃ γὰρ ἐμαρτυρήθησαν οἱ πρεσβύτεροι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 3, 'Πίστει νοοῦμεν κατηρτίσθαι τοὺς αἰῶνας ῥήματι  ̊Θεοῦ, εἰς τὸ μὴ ἐκ φαινομένων, τὸ βλεπόμενον γεγονέναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 4, '¶Πίστει πλείονα θυσίαν, Ἅβελ παρὰ Κάϊν προσήνεγκεν τῷ  ̊Θεῷ, διʼ ἧς ἐμαρτυρήθη εἶναι δίκαιος, μαρτυροῦντος ἐπὶ τοῖς δώροις αὐτοῦ τοῦ  ̊Θεοῦ, καὶ διʼ αὐτῆς, ἀποθανὼν ἔτι λαλεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 5, 'Πίστει Ἑνὼχ μετετέθη, τοῦ μὴ ἰδεῖν θάνατον, “καὶ οὐχ ηὑρίσκετο, διότι μετέθηκεν αὐτὸν ὁ  ̊Θεός”· πρὸ γὰρ τῆς μεταθέσεως, μεμαρτύρηται εὐηρεστηκέναι τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 6, 'Χωρὶς δὲ πίστεως, ἀδύνατον εὐαρεστῆσαι, πιστεῦσαι γὰρ δεῖ τὸν προσερχόμενον τῷ  ̊Θεῷ ὅτι ἔστιν, καὶ τοῖς ἐκζητοῦσιν αὐτὸν, μισθαποδότης γίνεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 7, 'Πίστει χρηματισθεὶς, Νῶε, περὶ τῶν μηδέπω βλεπομένων, εὐλαβηθεὶς, κατεσκεύασεν κιβωτὸν εἰς σωτηρίαν τοῦ οἴκου αὐτοῦ, διʼ ἧς κατέκρινεν τὸν κόσμον, καὶ τῆς κατὰ πίστιν δικαιοσύνης, ἐγένετο κληρονόμος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 8, '¶Πίστει καλούμενος, Ἀβραὰμ, ὑπήκουσεν ἐξελθεῖν εἰς τόπον ὃν ἤμελλεν λαμβάνειν εἰς κληρονομίαν, καὶ ἐξῆλθεν μὴ ἐπιστάμενος ποῦ ἔρχεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 9, 'Πίστει παρῴκησεν εἰς γῆν τῆς ἐπαγγελίας ὡς ἀλλοτρίαν, ἐν σκηναῖς κατοικήσας μετὰ Ἰσαὰκ καὶ Ἰακὼβ, τῶν συγκληρονόμων τῆς ἐπαγγελίας τῆς αὐτῆς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 10, 'ἐξεδέχετο γὰρ τὴν τοὺς θεμελίους ἔχουσαν πόλιν, ἧς τεχνίτης καὶ δημιουργὸς ὁ  ̊Θεός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 11, 'Πίστει καὶ αὐτὴ Σάρρᾳ δύναμιν εἰς καταβολὴν σπέρματος ἔλαβεν, καὶ παρὰ καιρὸν ἡλικίας, ἐπεὶ πιστὸν ἡγήσατο τὸν ἐπαγγειλάμενον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 12, 'Διὸ καὶ ἀφʼ ἑνὸς ἐγεννήθησαν, καὶ ταῦτα νενεκρωμένου, “καθὼς τὰ ἄστρα τοῦ οὐρανοῦ τῷ πλήθει, καὶ ὡς ἡ ἄμμος, ἡ παρὰ τὸ χεῖλος τῆς θαλάσσης, ἡ ἀναρίθμητος”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 13, '¶Κατὰ πίστιν ἀπέθανον οὗτοι πάντες, μὴ προσδεξάμενοι τὰς ἐπαγγελίας, ἀλλὰ πόρρωθεν αὐτὰς ἰδόντες, καὶ ἀσπασάμενοι, καὶ ὁμολογήσαντες, ὅτι ξένοι καὶ παρεπίδημοί εἰσιν ἐπὶ τῆς γῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 14, 'Οἱ γὰρ τοιαῦτα λέγοντες, ἐμφανίζουσιν ὅτι πατρίδα ἐπιζητοῦσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 15, 'Καὶ εἰ μὲν ἐκείνης μνημονεύουσιν ἀφʼ ἧς ἐξέβησαν, εἶχον ἂν καιρὸν ἀνακάμψαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 16, 'Νῦν δὲ κρείττονος ὀρέγονται, τοῦτʼ ἔστιν ἐπουρανίου. Διὸ οὐκ ἐπαισχύνεται αὐτοὺς ὁ  ̊Θεὸς,  ̊Θεὸς ἐπικαλεῖσθαι αὐτῶν, ἡτοίμασεν γὰρ αὐτοῖς πόλιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 17, '¶Πίστει προσενήνοχεν Ἀβραὰμ τὸν Ἰσαὰκ πειραζόμενος, καὶ τὸν μονογενῆ προσέφερεν, ὁ τὰς ἐπαγγελίας ἀναδεξάμενος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 18, 'πρὸς ὃν ἐλαλήθη, ὅτι “Ἐν Ἰσαὰκ κληθήσεταί σοι σπέρμα”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 19, 'λογισάμενος ὅτι καὶ ἐκ νεκρῶν ἐγείρειν δυνατὸς ὁ  ̊Θεός, ὅθεν αὐτὸν καὶ ἐν παραβολῇ ἐκομίσατο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 20, 'Πίστει καὶ περὶ μελλόντων, εὐλόγησεν Ἰσαὰκ, τὸν Ἰακὼβ, καὶ τὸν Ἠσαῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 21, 'Πίστει Ἰακὼβ, ἀποθνῄσκων, ἕκαστον τῶν υἱῶν Ἰωσὴφ εὐλόγησεν, καὶ προσεκύνησεν ἐπὶ τὸ ἄκρον τῆς ῥάβδου αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 22, 'Πίστει Ἰωσὴφ, τελευτῶν, περὶ τῆς ἐξόδου τῶν υἱῶν Ἰσραὴλ ἐμνημόνευσεν, καὶ περὶ τῶν ὀστέων αὐτοῦ ἐνετείλατο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 23, '¶Πίστει Μωϋσῆς, γεννηθεὶς, ἐκρύβη τρίμηνον ὑπὸ τῶν πατέρων αὐτοῦ, διότι εἶδον ἀστεῖον τὸ παιδίον, καὶ οὐκ ἐφοβήθησαν τὸ διάταγμα τοῦ βασιλέως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 24, 'Πίστει Μωϋσῆς, μέγας γενόμενος, ἠρνήσατο λέγεσθαι υἱὸς θυγατρὸς Φαραώ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 25, 'μᾶλλον ἑλόμενος συγκακουχεῖσθαι τῷ λαῷ τοῦ  ̊Θεοῦ, ἢ πρόσκαιρον ἔχειν ἁμαρτίας ἀπόλαυσιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 26, 'μείζονα πλοῦτον ἡγησάμενος τῶν Αἰγύπτου θησαυρῶν, τὸν ὀνειδισμὸν τοῦ  ̊Χριστοῦ, ἀπέβλεπεν γὰρ εἰς τὴν μισθαποδοσίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 27, 'Πίστει κατέλιπεν Αἴγυπτον, μὴ φοβηθεὶς τὸν θυμὸν τοῦ βασιλέως, τὸν γὰρ ἀόρατον ὡς ὁρῶν, ἐκαρτέρησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 28, 'Πίστει πεποίηκεν τὸ Πάσχα καὶ τὴν πρόσχυσιν τοῦ αἵματος, ἵνα μὴ ὁ ὀλοθρεύων τὰ πρωτότοκα θίγῃ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 29, '¶Πίστει διέβησαν τὴν Ἐρυθρὰν Θάλασσαν, ὡς διὰ ξηρᾶς γῆς, ἧς πεῖραν λαβόντες, οἱ Αἰγύπτιοι κατεπόθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 30, 'Πίστει τὰ τείχη Ἰεριχὼ ἔπεσαν, κυκλωθέντα ἐπὶ ἑπτὰ ἡμέρας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 31, 'Πίστει Ῥαὰβ ἡ πόρνη οὐ συναπώλετο τοῖς ἀπειθήσασιν, δεξαμένη τοὺς κατασκόπους μετʼ εἰρήνης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 32, '¶Καὶ τί ἔτι λέγω; Ἐπιλείψει με γὰρ διηγούμενον ὁ χρόνος, περὶ Γεδεών, Βαράκ, Σαμψών, Ἰεφθάε, Δαυίδ τε καὶ Σαμουὴλ, καὶ τῶν προφητῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 33, 'οἳ διὰ πίστεως κατηγωνίσαντο βασιλείας, εἰργάσαντο δικαιοσύνην, ἐπέτυχον ἐπαγγελιῶν, ἔφραξαν στόματα λεόντων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 34, 'ἔσβεσαν δύναμιν πυρός, ἔφυγον στόματα μαχαίρης, ἐδυναμώθησαν ἀπὸ ἀσθενείας, ἐγενήθησαν ἰσχυροὶ ἐν πολέμῳ, παρεμβολὰς ἔκλιναν ἀλλοτρίων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 35, 'Ἔλαβον γυναῖκες ἐξ ἀναστάσεως τοὺς νεκροὺς αὐτῶν, ἄλλοι δὲ ἐτυμπανίσθησαν, οὐ προσδεξάμενοι τὴν ἀπολύτρωσιν, ἵνα κρείττονος ἀναστάσεως τύχωσιν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 36, 'ἕτεροι δὲ ἐμπαιγμῶν καὶ μαστίγων πεῖραν ἔλαβον, ἔτι δὲ δεσμῶν καὶ φυλακῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 37, 'Ἐλιθάσθησαν, ἐπρίσθησαν, ἐπειράσθησαν, ἐν φόνῳ μαχαίρης ἀπέθανον, περιῆλθον ἐν μηλωταῖς, ἐν αἰγείοις δέρμασιν, ὑστερούμενοι, θλιβόμενοι, κακουχούμενοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 38, 'ὧν οὐκ ἦν ἄξιος ὁ κόσμος, ἐπὶ ἐρημίαις πλανώμενοι, καὶ ὄρεσιν, καὶ σπηλαίοις, καὶ ταῖς ὀπαῖς τῆς γῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 39, 'Καὶ οὗτοι πάντες μαρτυρηθέντες διὰ τῆς πίστεως, οὐκ ἐκομίσαντο τὴν ἐπαγγελίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 40, 'τοῦ  ̊Θεοῦ περὶ ἡμῶν κρεῖττόν τι προβλεψαμένου, ἵνα μὴ χωρὶς ἡμῶν τελειωθῶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 1, '¶Τοιγαροῦν καὶ ἡμεῖς, τοσοῦτον ἔχοντες περικείμενον ἡμῖν νέφος μαρτύρων, ὄγκον ἀποθέμενοι πάντα καὶ τὴν εὐπερίστατον ἁμαρτίαν διʼ ὑπομονῆς, τρέχωμεν τὸν προκείμενον ἡμῖν ἀγῶνα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 2, 'ἀφορῶντες εἰς τὸν τῆς πίστεως ἀρχηγὸν καὶ τελειωτὴν,  ̊Ἰησοῦν, ὃς ἀντὶ τῆς προκειμένης αὐτῷ χαρᾶς, ὑπέμεινεν σταυρὸν, αἰσχύνης καταφρονήσας, “ἐν δεξιᾷ τε τοῦ θρόνου τοῦ  ̊Θεοῦ κεκάθικεν”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 3, '¶Ἀναλογίσασθε γὰρ τὸν τοιαύτην ὑπομεμενηκότα ὑπὸ τῶν ἁμαρτωλῶν εἰς αὑτούς ἀντιλογίαν, ἵνα μὴ κάμητε, ταῖς ψυχαῖς ὑμῶν ἐκλυόμενοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 4, 'Οὔπω μέχρις αἵματος ἀντικατέστητε, πρὸς τὴν ἁμαρτίαν ἀνταγωνιζόμενοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 5, 'καὶ ἐκλέλησθε τῆς παρακλήσεως, ἥτις ὑμῖν ὡς υἱοῖς διαλέγεται, “Υἱέ μου, μὴ ὀλιγώρει παιδείας  ̊Κυρίου, μηδὲ ἐκλύου ὑπʼ αὐτοῦ ἐλεγχόμενος·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 6, 'ὃν γὰρ ἀγαπᾷ  ̊Κύριος, παιδεύει, μαστιγοῖ δὲ πάντα υἱὸν ὃν παραδέχεται.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 7, 'Εἰς παιδείαν ὑπομένετε, ὡς υἱοῖς ὑμῖν προσφέρεται ὁ  ̊Θεός· τίς γὰρ υἱὸς ὃν οὐ παιδεύει πατήρ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 8, 'Εἰ δὲ χωρίς ἐστε παιδείας, ἧς μέτοχοι γεγόνασι πάντες, ἄρα νόθοι καὶ οὐχ υἱοί ἐστε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 9, 'Εἶτα τοὺς μὲν τῆς σαρκὸς ἡμῶν πατέρας εἴχομεν παιδευτὰς, καὶ ἐνετρεπόμεθα· οὐ πολὺ μᾶλλον ὑποταγησόμεθα τῷ Πατρὶ τῶν πνευμάτων, καὶ ζήσομεν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 10, 'Οἱ μὲν γὰρ πρὸς ὀλίγας ἡμέρας κατὰ τὸ δοκοῦν αὐτοῖς ἐπαίδευον, ὁ δὲ ἐπὶ τὸ συμφέρον, εἰς τὸ μεταλαβεῖν τῆς ἁγιότητος αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 11, 'Πᾶσα δὲ παιδεία πρὸς μὲν τὸ παρὸν, οὐ δοκεῖ χαρᾶς εἶναι, ἀλλὰ λύπης, ὕστερον δὲ καρπὸν εἰρηνικὸν τοῖς διʼ αὐτῆς γεγυμνασμένοις ἀποδίδωσιν δικαιοσύνης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 12, '¶Διὸ τὰς παρειμένας χεῖρας, καὶ τὰ παραλελυμένα γόνατα, ἀνορθώσατε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 13, 'καὶ “τροχιὰς ὀρθὰς ποιεῖτε τοῖς ποσὶν ὑμῶν”, ἵνα μὴ τὸ χωλὸν ἐκτραπῇ, ἰαθῇ δὲ μᾶλλον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 14, '¶Εἰρήνην διώκετε μετὰ πάντων, καὶ τὸν ἁγιασμόν, οὗ χωρὶς οὐδεὶς ὄψεται τὸν  ̊Κύριον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 15, 'Ἐπισκοποῦντες μή τις ὑστερῶν ἀπὸ τῆς χάριτος τοῦ  ̊Θεοῦ, μή τις ῥίζα πικρίας ἄνω φύουσα ἐνοχλῇ, καὶ διʼ αὐτῆς μιανθῶσιν οἱ πολλοί,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 16, 'μή τις πόρνος ἢ βέβηλος, ὡς Ἠσαῦ, ὃς ἀντὶ βρώσεως μιᾶς, ἀπέδετο τὰ πρωτοτόκια ἑαυτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 17, 'ἴστε γὰρ ὅτι καὶ μετέπειτα θέλων κληρονομῆσαι τὴν εὐλογίαν, ἀπεδοκιμάσθη, μετανοίας γὰρ τόπον οὐχ εὗρεν, καίπερ μετὰ δακρύων ἐκζητήσας αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 18, '¶Οὐ γὰρ προσεληλύθατε, ψηλαφωμένῳ καὶ κεκαυμένῳ πυρὶ, καὶ γνόφῳ, καὶ ζόφῳ, καὶ θυέλλῃ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 19, 'καὶ σάλπιγγος ἤχῳ, καὶ φωνῇ ῥημάτων, ἧς οἱ ἀκούσαντες, παρῃτήσαντο μὴ προστεθῆναι αὐτοῖς λόγον·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 20, 'οὐκ ἔφερον γὰρ τὸ διαστελλόμενον, “Κἂν θηρίον θίγῃ τοῦ ὄρους, λιθοβοληθήσεται”·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 21, 'καί οὕτω φοβερὸν ἦν τὸ φανταζόμενον, Μωϋσῆς εἶπεν, “Ἔκφοβός εἰμι καὶ ἔντρομος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 22, 'Ἀλλὰ προσεληλύθατε Σιὼν Ὄρει καὶ πόλει  ̊Θεοῦ ζῶντος, Ἰερουσαλὴμ ἐπουρανίῳ, καὶ μυριάσιν ἀγγέλων πανηγύρει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 23, 'καὶ ἐκκλησίᾳ πρωτοτόκων, ἀπογεγραμμένων ἐν οὐρανοῖς, καὶ κριτῇ  ̊Θεῷ πάντων, καὶ πνεύμασι δικαίων τετελειωμένων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 24, 'καὶ διαθήκης νέας μεσίτῃ,  ̊Ἰησοῦ, καὶ αἵματι ῥαντισμοῦ, κρεῖττον λαλοῦντι παρὰ τὸν Ἅβελ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 25, '¶Βλέπετε, μὴ παραιτήσησθε τὸν λαλοῦντα. Εἰ γὰρ ἐκεῖνοι οὐκ ἐξέφυγον ἐπὶ γῆς, παραιτησάμενοι τὸν χρηματίζοντα, πολὺ μᾶλλον ἡμεῖς οἱ τὸν ἀπʼ οὐρανῶν ἀποστρεφόμενοι·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 26, 'οὗ ἡ φωνὴ τὴν γῆν ἐσάλευσεν τότε, νῦν δὲ ἐπήγγελται λέγων, “Ἔτι ἅπαξ ἐγὼ σείσω, οὐ μόνον τὴν γῆν, ἀλλὰ καὶ τὸν οὐρανόν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 27, 'Τὸ δὲ, “ἔτι ἅπαξ”, δηλοῖ τὴν τῶν σαλευομένων μετάθεσιν, ὡς πεποιημένων, ἵνα μείνῃ τὰ μὴ σαλευόμενα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 28, 'Διὸ βασιλείαν ἀσάλευτον παραλαμβάνοντες, ἔχωμεν χάριν, διʼ ἧς λατρεύωμεν εὐαρέστως τῷ  ̊Θεῷ μετὰ εὐλαβείας καὶ δέους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 29, 'Καὶ “γὰρ ὁ  ̊Θεὸς ἡμῶν πῦρ καταναλίσκον”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 1, '¶Ἡ φιλαδελφία μενέτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 2, 'Τῆς φιλοξενίας μὴ ἐπιλανθάνεσθε, διὰ ταύτης γὰρ, ἔλαθόν τινες ξενίσαντες ἀγγέλους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 3, 'Μιμνῄσκεσθε τῶν δεσμίων, ὡς συνδεδεμένοι, τῶν κακουχουμένων ὡς καὶ αὐτοὶ ὄντες ἐν σώματι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 4, 'Τίμιος ὁ γάμος ἐν πᾶσιν καὶ ἡ κοίτη ἀμίαντος, πόρνους γὰρ καὶ μοιχοὺς κρινεῖ ὁ  ̊Θεός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 5, 'Ἀφιλάργυρος ὁ τρόπος, ἀρκούμενοι τοῖς παροῦσιν· αὐτὸς γὰρ εἴρηκεν, “Οὐ μή σε ἀνῶ, οὐδʼ οὐ μή σε ἐγκαταλίπω.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 6, 'Ὥστε θαρροῦντας ἡμᾶς λέγειν, “ ̊Κύριος ἐμοὶ βοηθός, καὶ οὐ φοβηθήσομαι· τί ποιήσει μοι ἄνθρωπος;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 7, '¶Μνημονεύετε τῶν ἡγουμένων ὑμῶν, οἵτινες ἐλάλησαν ὑμῖν τὸν λόγον τοῦ  ̊Θεοῦ, ὧν ἀναθεωροῦντες τὴν ἔκβασιν τῆς ἀναστροφῆς, μιμεῖσθε τὴν πίστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 8, ' ̊Ἰησοῦς  ̊Χριστὸς, ἐχθὲς καὶ σήμερον, ὁ αὐτός, καὶ εἰς τοὺς αἰῶνας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 9, 'Διδαχαῖς ποικίλαις καὶ ξέναις, μὴ παραφέρεσθε· καλὸν γὰρ χάριτι βεβαιοῦσθαι τὴν καρδίαν, οὐ βρώμασιν, ἐν οἷς οὐκ ὠφελήθησαν οἱ περιπατοῦντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 10, 'Ἔχομεν θυσιαστήριον, ἐξ οὗ φαγεῖν οὐκ ἔχουσιν ἐξουσίαν, οἱ τῇ σκηνῇ λατρεύοντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 11, 'Ὧν γὰρ εἰσφέρεται ζῴων τὸ αἷμα περὶ ἁμαρτίας εἰς τὰ ἅγια διὰ τοῦ ἀρχιερέως, τούτων τὰ σώματα κατακαίεται ἔξω τῆς παρεμβολῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 12, 'Διὸ καὶ  ̊Ἰησοῦς, ἵνα ἁγιάσῃ διὰ τοῦ ἰδίου αἵματος τὸν λαόν, ἔξω τῆς πύλης ἔπαθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 13, 'Τοίνυν ἐξερχώμεθα πρὸς αὐτὸν ἔξω τῆς παρεμβολῆς, τὸν ὀνειδισμὸν αὐτοῦ φέροντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 14, 'Οὐ γὰρ ἔχομεν ὧδε μένουσαν πόλιν, ἀλλὰ τὴν μέλλουσαν ἐπιζητοῦμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 15, 'Διʼ αὐτοῦ οὖν ἀναφέρωμεν θυσίαν αἰνέσεως διὰ παντὸς τῷ  ̊Θεῷ, τοῦτʼ ἔστιν καρπὸν χειλέων ὁμολογούντων τῷ ὀνόματι αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 16, 'Τῆς δὲ εὐποιΐας καὶ κοινωνίας μὴ ἐπιλανθάνεσθε, τοιαύταις γὰρ θυσίαις εὐαρεστεῖται ὁ  ̊Θεός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 17, '¶Πείθεσθε τοῖς ἡγουμένοις ὑμῶν, καὶ ὑπείκετε, αὐτοὶ γὰρ ἀγρυπνοῦσιν ὑπὲρ τῶν ψυχῶν ὑμῶν, ὡς λόγον ἀποδώσοντες, ἵνα μετὰ χαρᾶς τοῦτο ποιῶσιν, καὶ μὴ στενάζοντες, ἀλυσιτελὲς γὰρ ὑμῖν τοῦτο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 18, '¶Προσεύχεσθε περὶ ἡμῶν, πειθόμεθα γὰρ ὅτι καλὴν συνείδησιν ἔχομεν, ἐν πᾶσιν καλῶς θέλοντες ἀναστρέφεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 19, 'Περισσοτέρως δὲ παρακαλῶ τοῦτο ποιῆσαι, ἵνα τάχιον ἀποκατασταθῶ ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 20, '¶Ὁ δὲ  ̊Θεὸς τῆς εἰρήνης, ὁ ἀναγαγὼν ἐκ νεκρῶν τὸν Ποιμένα τῶν προβάτων τὸν μέγαν, ἐν αἵματι διαθήκης αἰωνίου, τὸν  ̊Κύριον ἡμῶν,  ̊Ἰησοῦν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 21, 'καταρτίσαι ὑμᾶς ἐν παντὶ ἀγαθῷ, εἰς τὸ ποιῆσαι τὸ θέλημα αὐτοῦ, ποιῶν ἐν ἡμῖν τὸ εὐάρεστον ἐνώπιον αὐτοῦ, διὰ  ̊Ἰησοῦ  ̊Χριστοῦ, ᾧ ἡ δόξα εἰς τοὺς αἰῶνας τῶν αἰώνων. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 22, '¶Παρακαλῶ δὲ ὑμᾶς, ἀδελφοί, ἀνέχεσθε τοῦ λόγου τῆς παρακλήσεως, καὶ γὰρ διὰ βραχέων ἐπέστειλα ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 23, 'Γινώσκετε τὸν ἀδελφὸν ἡμῶν, Τιμόθεον, ἀπολελυμένον, μεθʼ οὗ ἐὰν τάχιον ἔρχηται, ὄψομαι ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 24, 'Ἀσπάσασθε πάντας τοὺς ἡγουμένους ὑμῶν, καὶ πάντας τοὺς ἁγίους. Ἀσπάζονται ὑμᾶς οἱ ἀπὸ τῆς Ἰταλίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 25, 'Ἡ χάρις μετὰ πάντων ὑμῶν. ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 1, '¶Ἰάκωβος,  ̊Θεοῦ καὶ  ̊Κυρίου  ̊Ἰησοῦ  ̊Χριστοῦ, δοῦλος, ταῖς δώδεκα φυλαῖς ταῖς ἐν τῇ διασπορᾷ: χαίρειν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 2, '¶Πᾶσαν χαρὰν ἡγήσασθε, ἀδελφοί μου, ὅταν πειρασμοῖς περιπέσητε ποικίλοις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 3, 'γινώσκοντες ὅτι τὸ δοκίμιον ὑμῶν τῆς πίστεως κατεργάζεται ὑπομονήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 4, 'Ἡ δὲ ὑπομονὴ ἔργον τέλειον ἐχέτω, ἵνα ἦτε τέλειοι καὶ ὁλόκληροι, ἐν μηδενὶ λειπόμενοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 5, '¶Εἰ δέ τις ὑμῶν λείπεται σοφίας, αἰτείτω παρὰ τοῦ διδόντος,  ̊Θεοῦ, πᾶσιν ἁπλῶς, καὶ μὴ ὀνειδίζοντος, καὶ δοθήσεται αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 6, 'Αἰτείτω δὲ ἐν πίστει, μηδὲν διακρινόμενος, ὁ γὰρ διακρινόμενος ἔοικεν κλύδωνι θαλάσσης, ἀνεμιζομένῳ καὶ ῥιπιζομένῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 7, 'Μὴ γὰρ οἰέσθω ὁ ἄνθρωπος ἐκεῖνος ὅτι λήμψεταί τι παρὰ τοῦ  ̊Κυρίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 8, 'ἀνὴρ δίψυχος, ἀκατάστατος ἐν πάσαις ταῖς ὁδοῖς αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 9, '¶Καυχάσθω δὲ ὁ ἀδελφὸς ὁ ταπεινὸς, ἐν τῷ ὕψει αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 10, 'ὁ δὲ πλούσιος, ἐν τῇ ταπεινώσει αὐτοῦ, ὅτι ὡς ἄνθος χόρτου παρελεύσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 11, 'Ἀνέτειλεν γὰρ ὁ ἥλιος σὺν τῷ καύσωνι, καὶ ἐξήρανεν τὸν χόρτον, καὶ τὸ ἄνθος αὐτοῦ ἐξέπεσεν, καὶ ἡ εὐπρέπεια τοῦ προσώπου αὐτοῦ ἀπώλετο. Οὕτως καὶ ὁ πλούσιος ἐν ταῖς πορείαις αὐτοῦ μαρανθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 12, '¶Μακάριος ἀνὴρ ὃς ὑπομένει πειρασμόν, ὅτι δόκιμος γενόμενος, λήμψεται τὸν στέφανον τῆς ζωῆς, ὃν ἐπηγγείλατο τοῖς ἀγαπῶσιν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 13, 'Μηδεὶς πειραζόμενος λεγέτω, ὅτι “Ἀπὸ  ̊Θεοῦ πειράζομαι.” Ὁ γὰρ  ̊Θεὸς ἀπείραστός ἐστιν κακῶν, πειράζει δὲ αὐτὸς οὐδένα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 14, 'Ἕκαστος δὲ πειράζεται ὑπὸ τῆς ἰδίας ἐπιθυμίας, ἐξελκόμενος καὶ δελεαζόμενος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 15, 'Εἶτα ἡ ἐπιθυμία συλλαβοῦσα τίκτει ἁμαρτίαν, ἡ δὲ ἁμαρτία ἀποτελεσθεῖσα, ἀποκύει θάνατον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 16, 'Μὴ πλανᾶσθε, ἀδελφοί μου ἀγαπητοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 17, '¶Πᾶσα δόσις ἀγαθὴ, καὶ πᾶν δώρημα τέλειον ἄνωθέν ἐστιν, καταβαῖνον ἀπὸ τοῦ Πατρὸς τῶν φώτων, παρʼ ᾧ οὐκ ἔνι παραλλαγὴ ἢ τροπῆς ἀποσκίασμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 18, 'Βουληθεὶς, ἀπεκύησεν ἡμᾶς λόγῳ ἀληθείας, εἰς τὸ εἶναι ἡμᾶς ἀπαρχήν τινα τῶν αὐτοῦ κτισμάτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 19, '¶Ἴστε, ἀδελφοί μου ἀγαπητοί. Ἔστω δὲ πᾶς ἄνθρωπος ταχὺς εἰς τὸ ἀκοῦσαι, βραδὺς εἰς τὸ λαλῆσαι, βραδὺς εἰς ὀργήν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 20, 'ὀργὴ γὰρ ἀνδρὸς, δικαιοσύνην  ̊Θεοῦ οὐκ ἐργάζεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 21, 'Διὸ ἀποθέμενοι πᾶσαν ῥυπαρίαν καὶ περισσείαν κακίας, ἐν πραΰτητι δέξασθε τὸν ἔμφυτον λόγον, τὸν δυνάμενον σῶσαι τὰς ψυχὰς ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 22, '¶Γίνεσθε δὲ ποιηταὶ λόγου, καὶ μὴ μόνον ἀκροαταὶ παραλογιζόμενοι ἑαυτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 23, 'Ὅτι εἴ τις ἀκροατὴς λόγου ἐστὶν, καὶ οὐ ποιητής, οὗτος ἔοικεν ἀνδρὶ κατανοοῦντι τὸ πρόσωπον τῆς γενέσεως αὐτοῦ ἐν ἐσόπτρῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 24, 'Κατενόησεν γὰρ ἑαυτὸν καὶ ἀπελήλυθεν, καὶ εὐθέως ἐπελάθετο ὁποῖος ἦν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 25, 'Ὁ δὲ παρακύψας εἰς νόμον τέλειον, τὸν τῆς ἐλευθερίας, καὶ παραμείνας, οὐκ ἀκροατὴς ἐπιλησμονῆς γενόμενος, ἀλλὰ ποιητὴς ἔργου, οὗτος μακάριος ἐν τῇ ποιήσει αὐτοῦ ἔσται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 26, '¶Εἴ τις δοκεῖ θρησκὸς εἶναι, μὴ χαλιναγωγῶν γλῶσσαν ἑαυτοῦ, ἀλλὰ ἀπατῶν καρδίαν αὐτοῦ, τούτου μάταιος ἡ θρησκεία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 27, 'Θρησκεία καθαρὰ καὶ ἀμίαντος παρὰ τῷ  ̊Θεῷ καὶ Πατρὶ αὕτη ἐστίν: ἐπισκέπτεσθαι ὀρφανοὺς καὶ χήρας ἐν τῇ θλίψει αὐτῶν, ἄσπιλον ἑαυτὸν τηρεῖν ἀπὸ τοῦ κόσμου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 1, '¶Ἀδελφοί μου, μὴ ἐν προσωπολημψίαις ἔχετε τὴν πίστιν τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, τῆς δόξης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 2, 'Ἐὰν γὰρ εἰσέλθῃ εἰς συναγωγὴν ὑμῶν, ἀνὴρ χρυσοδακτύλιος, ἐν ἐσθῆτι λαμπρᾷ, εἰσέλθῃ δὲ καὶ πτωχὸς, ἐν ῥυπαρᾷ ἐσθῆτι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 3, 'ἐπιβλέψητε δὲ ἐπὶ τὸν φοροῦντα τὴν ἐσθῆτα τὴν λαμπρὰν, καὶ εἴπητε, “Σὺ κάθου ὧδε καλῶς”, καὶ τῷ πτωχῷ εἴπητε, “Σὺ στῆθι ἐκεῖ”, ἢ, “Κάθου ὑπὸ τὸ ὑποπόδιόν μου”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 4, 'οὐ διεκρίθητε ἐν ἑαυτοῖς, καὶ ἐγένεσθε κριταὶ διαλογισμῶν πονηρῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 5, 'Ἀκούσατε, ἀδελφοί μου ἀγαπητοί: οὐχ ὁ  ̊Θεὸς ἐξελέξατο τοὺς πτωχοὺς τῷ κόσμῳ, πλουσίους ἐν πίστει, καὶ κληρονόμους τῆς βασιλείας ἧς ἐπηγγείλατο τοῖς ἀγαπῶσιν αὐτόν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 6, 'Ὑμεῖς δὲ ἠτιμάσατε τὸν πτωχόν. Οὐχ οἱ πλούσιοι καταδυναστεύουσιν ὑμῶν, καὶ αὐτοὶ ἕλκουσιν ὑμᾶς εἰς κριτήρια;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 7, 'Οὐκ αὐτοὶ βλασφημοῦσιν τὸ καλὸν ὄνομα τὸ ἐπικληθὲν ἐφʼ ὑμᾶς;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 8, '¶Εἰ μέντοι νόμον τελεῖτε βασιλικὸν, κατὰ τὴν Γραφήν, “Ἀγαπήσεις τὸν πλησίον σου ὡς σεαυτόν”, καλῶς ποιεῖτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 9, 'Εἰ δὲ προσωπολημπτεῖτε, ἁμαρτίαν ἐργάζεσθε, ἐλεγχόμενοι ὑπὸ τοῦ νόμου ὡς παραβάται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 10, 'Ὅστις γὰρ ὅλον τὸν νόμον τηρήσῃ, πταίσῃ δὲ ἐν ἑνί, γέγονεν πάντων ἔνοχος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 11, 'Ὁ γὰρ εἰπών, “Μὴ μοιχεύσῃς”, εἶπεν καί, “Μὴ φονεύσῃς.” Εἰ δὲ οὐ μοιχεύεις, φονεύεις δέ, γέγονας παραβάτης νόμου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 12, 'Οὕτως λαλεῖτε, καὶ οὕτως ποιεῖτε, ὡς διὰ νόμου ἐλευθερίας μέλλοντες κρίνεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 13, 'Ἡ γὰρ κρίσις ἀνέλεος τῷ μὴ ποιήσαντι ἔλεος. Κατακαυχᾶται ἔλεος κρίσεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 14, '¶Τί ὄφελος, ἀδελφοί μου, ἐὰν πίστιν λέγῃ τις, ἔχειν ἔργα, δὲ μὴ ἔχῃ; Μὴ δύναται ἡ πίστις σῶσαι αὐτόν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 15, 'Ἐὰν ἀδελφὸς ἢ ἀδελφὴ γυμνοὶ ὑπάρχωσιν, καὶ λειπόμενοι τῆς ἐφημέρου τροφῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 16, 'εἴπῃ δέ τις αὐτοῖς ἐξ ὑμῶν, “Ὑπάγετε ἐν εἰρήνῃ, θερμαίνεσθε καὶ χορτάζεσθε”, μὴ δῶτε δὲ αὐτοῖς τὰ ἐπιτήδεια τοῦ σώματος, τί ὄφελος;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 17, 'Οὕτως καὶ ἡ πίστις, ἐὰν μὴ ἔχῃ ἔργα, νεκρά ἐστιν καθʼ ἑαυτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 18, '¶Ἀλλʼ ἐρεῖ τις, “Σὺ πίστιν ἔχεις, κἀγὼ ἔργα ἔχω. Δεῖξόν μοι τὴν πίστιν σου χωρὶς τῶν ἔργων, κἀγώ σοι δείξω ἐκ τῶν ἔργων μου τὴν πίστιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 19, 'Σὺ πιστεύεις ὅτι εἷς ἐστιν ὁ  ̊Θεός. Καλῶς ποιεῖς· καὶ τὰ δαιμόνια πιστεύουσιν καὶ φρίσσουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 20, 'Θέλεις δὲ γνῶναι, ὦ ἄνθρωπε κενέ, ὅτι ἡ πίστις χωρὶς τῶν ἔργων ἀργή ἐστιν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 21, 'Ἀβραὰμ ὁ πατὴρ ἡμῶν οὐκ ἐξ ἔργων ἐδικαιώθη, ἀνενέγκας Ἰσαὰκ τὸν υἱὸν αὐτοῦ ἐπὶ τὸ θυσιαστήριον;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 22, 'Βλέπεις ὅτι ἡ πίστις συνήργει τοῖς ἔργοις αὐτοῦ, καὶ ἐκ τῶν ἔργων ἡ πίστις ἐτελειώθη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 23, 'Καὶ ἐπληρώθη ἡ Γραφὴ ἡ λέγουσα, “Ἐπίστευσεν δὲ Ἀβραὰμ τῷ  ̊Θεῷ, καὶ ἐλογίσθη αὐτῷ εἰς δικαιοσύνην”, καὶ φίλος  ̊Θεοῦ ἐκλήθη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 24, 'Ὁρᾶτε ὅτι ἐξ ἔργων δικαιοῦται ἄνθρωπος, καὶ οὐκ ἐκ πίστεως μόνον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 25, 'Ὁμοίως δὲ καὶ Ῥαὰβ ἡ πόρνη οὐκ ἐξ ἔργων ἐδικαιώθη, ὑποδεξαμένη τοὺς ἀγγέλους καὶ ἑτέρᾳ ὁδῷ ἐκβαλοῦσα;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 26, 'Ὥσπερ γὰρ τὸ σῶμα χωρὶς πνεύματος νεκρόν ἐστιν, οὕτως καὶ ἡ πίστις χωρὶς ἔργων νεκρά ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 1, '¶Μὴ πολλοὶ διδάσκαλοι γίνεσθε, ἀδελφοί μου, εἰδότες ὅτι μεῖζον κρίμα λημψόμεθα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 2, 'Πολλὰ γὰρ πταίομεν ἅπαντες. Εἴ τις ἐν λόγῳ οὐ πταίει, οὗτος τέλειος ἀνήρ, δυνατὸς χαλιναγωγῆσαι καὶ ὅλον τὸ σῶμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 3, 'Εἰ δὲ τῶν ἵππων τοὺς χαλινοὺς εἰς τὰ στόματα βάλλομεν, εἰς τὸ πείθεσθαι αὐτοὺς ἡμῖν, καὶ ὅλον τὸ σῶμα αὐτῶν μετάγομεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 4, 'Ἰδοὺ, καὶ τὰ πλοῖα, τηλικαῦτα ὄντα, καὶ ὑπὸ ἀνέμων σκληρῶν ἐλαυνόμενα, μετάγεται ὑπὸ ἐλαχίστου πηδαλίου, ὅπου ἡ ὁρμὴ τοῦ εὐθύνοντος βούλεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 5, 'Οὕτως καὶ ἡ γλῶσσα μικρὸν μέλος ἐστὶν, καὶ μεγάλα αὐχεῖ. ¶Ἰδοὺ, ἡλίκον πῦρ, ἡλίκην ὕλην ἀνάπτει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 6, 'Καὶ ἡ γλῶσσα πῦρ, ὁ κόσμος τῆς ἀδικίας· ἡ γλῶσσα καθίσταται ἐν τοῖς μέλεσιν ἡμῶν, ἡ σπιλοῦσα ὅλον τὸ σῶμα, καὶ φλογίζουσα τὸν τροχὸν τῆς γενέσεως, καὶ φλογιζομένη ὑπὸ τῆς Γεέννης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 7, 'Πᾶσα γὰρ φύσις θηρίων τε καὶ πετεινῶν, ἑρπετῶν τε καὶ ἐναλίων, δαμάζεται καὶ δεδάμασται τῇ φύσει τῇ ἀνθρωπίνῃ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 8, 'τὴν δὲ γλῶσσαν οὐδεὶς δαμάσαι δύναται ἀνθρώπων, ἀκατάστατον κακόν, μεστὴ ἰοῦ θανατηφόρου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 9, 'Ἐν αὐτῇ εὐλογοῦμεν τὸν  ̊Κύριον καὶ Πατέρα, καὶ ἐν αὐτῇ καταρώμεθα τοὺς ἀνθρώπους, τοὺς καθʼ ὁμοίωσιν  ̊Θεοῦ γεγονότας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 10, 'Ἐκ τοῦ αὐτοῦ στόματος ἐξέρχεται εὐλογία καὶ κατάρα. Οὐ χρή ἀδελφοί μου ταῦτα οὕτως γίνεσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 11, 'Μήτι ἡ πηγὴ ἐκ τῆς αὐτῆς ὀπῆς βρύει τὸ γλυκὺ καὶ τὸ πικρόν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 12, 'Μὴ δύναται, ἀδελφοί μου, συκῆ ἐλαίας ποιῆσαι ἢ ἄμπελος σῦκα; Οὔτε ἁλυκὸν γλυκὺ ποιῆσαι ὕδωρ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 13, '¶Τίς σοφὸς καὶ ἐπιστήμων ἐν ὑμῖν; Δειξάτω ἐκ τῆς καλῆς ἀναστροφῆς τὰ ἔργα αὐτοῦ ἐν πραΰτητι σοφίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 14, 'Εἰ δὲ ζῆλον πικρὸν ἔχετε, καὶ ἐριθείαν ἐν τῇ καρδίᾳ ὑμῶν, μὴ κατακαυχᾶσθε καὶ ψεύδεσθε κατὰ τῆς ἀληθείας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 15, 'Οὐκ ἔστιν αὕτη ἡ σοφία ἄνωθεν κατερχομένη, ἀλλὰ ἐπίγειος, ψυχική, δαιμονιώδης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 16, 'Ὅπου γὰρ ζῆλος καὶ ἐριθεία, ἐκεῖ ἀκαταστασία καὶ πᾶν φαῦλον πρᾶγμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 17, 'Ἡ δὲ ἄνωθεν σοφία, πρῶτον μὲν ἁγνή ἐστιν, ἔπειτα εἰρηνική, ἐπιεικής, εὐπειθής, μεστὴ ἐλέους καὶ καρπῶν ἀγαθῶν, ἀδιάκριτος, ἀνυπόκριτος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 18, 'Καρπὸς δὲ δικαιοσύνης ἐν εἰρήνῃ σπείρεται, τοῖς ποιοῦσιν εἰρήνην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 1, '¶Πόθεν πόλεμοι καὶ πόθεν μάχαι ἐν ὑμῖν; Οὐκ ἐντεῦθεν ἐκ τῶν ἡδονῶν ὑμῶν, τῶν στρατευομένων ἐν τοῖς μέλεσιν ὑμῶν;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 2, 'Ἐπιθυμεῖτε καὶ οὐκ ἔχετε· φονεύετε καὶ ζηλοῦτε, καὶ οὐ δύνασθε ἐπιτυχεῖν· μάχεσθε καὶ πολεμεῖτε. Οὐκ ἔχετε, διὰ τὸ μὴ αἰτεῖσθαι ὑμᾶς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 3, 'αἰτεῖτε καὶ οὐ λαμβάνετε, διότι κακῶς αἰτεῖσθε, ἵνα ἐν ταῖς ἡδοναῖς ὑμῶν δαπανήσητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 4, 'Μοιχαλίδες! Οὐκ οἴδατε ὅτι ἡ φιλία τοῦ κόσμου, ἔχθρα τοῦ  ̊Θεοῦ ἐστιν; Ὃς ἐὰν οὖν βουληθῇ φίλος εἶναι τοῦ κόσμου, ἐχθρὸς τοῦ  ̊Θεοῦ καθίσταται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 5, 'Ἢ δοκεῖτε ὅτι κενῶς ἡ Γραφὴ λέγει, “Πρὸς φθόνον ἐπιποθεῖ τὸ  ̊Πνεῦμα ὃ κατῴκισεν ἐν ἡμῖν;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 6, 'Μείζονα δὲ δίδωσιν χάριν. Διὸ λέγει, “Ὁ  ̊Θεὸς ὑπερηφάνοις ἀντιτάσσεται, ταπεινοῖς δὲ δίδωσιν χάριν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 7, 'Ὑποτάγητε οὖν τῷ  ̊Θεῷ. Ἀντίστητε δὲ τῷ διαβόλῳ, καὶ φεύξεται ἀφʼ ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 8, 'Ἐγγίσατε τῷ  ̊Θεῷ, καὶ ἐγγιεῖ ὑμῖν. Καθαρίσατε χεῖρας, ἁμαρτωλοί, καὶ ἁγνίσατε καρδίας, δίψυχοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 9, 'Ταλαιπωρήσατε, καὶ πενθήσατε, καὶ κλαύσατε. Ὁ γέλως ὑμῶν εἰς πένθος μετατραπήτω, καὶ ἡ χαρὰ εἰς κατήφειαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 10, 'Ταπεινώθητε ἐνώπιον  ̊Κυρίου, καὶ ὑψώσει ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 11, '¶Μὴ καταλαλεῖτε ἀλλήλων, ἀδελφοί. Ὁ καταλαλῶν ἀδελφοῦ ἢ κρίνων τὸν ἀδελφὸν αὐτοῦ, καταλαλεῖ νόμου καὶ κρίνει νόμον. Εἰ δὲ νόμον κρίνεις, οὐκ εἶ ποιητὴς νόμου, ἀλλὰ κριτής.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 12, 'Εἷς ἐστιν νομοθέτης καὶ κριτής, ὁ δυνάμενος σῶσαι καὶ ἀπολέσαι. Σὺ δὲ τίς εἶ, ὁ κρίνων τὸν πλησίον;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 13, '¶Ἄγε νῦν, οἱ λέγοντες, “Σήμερον ἢ αὔριον, πορευσόμεθα εἰς τήνδε τὴν πόλιν, καὶ ποιήσομεν ἐκεῖ ἐνιαυτὸν, καὶ ἐμπορευσόμεθα, καὶ κερδήσομεν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 14, 'Οἵτινες οὐκ ἐπίστασθε τῆς αὔριον, ποία γὰρ ζωὴ ὑμῶν; Ἀτμὶς γάρ ἐστε, ἡ πρὸς ὀλίγον φαινομένη, ἔπειτα καὶ ἀφανιζομένη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 15, 'Ἀντὶ τοῦ λέγειν ὑμᾶς, “Ἐὰν ὁ  ̊Κύριος θελήσῃ, καὶ ζήσομεν καὶ ποιήσομεν, τοῦτο ἢ ἐκεῖνο.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 16, 'Νῦν δὲ καυχᾶσθε ἐν ταῖς ἀλαζονείαις ὑμῶν. Πᾶσα καύχησις τοιαύτη πονηρά ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 17, 'Εἰδότι οὖν καλὸν ποιεῖν, καὶ μὴ ποιοῦντι, ἁμαρτία αὐτῷ ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 1, '¶Ἄγε νῦν, οἱ πλούσιοι, κλαύσατε, ὀλολύζοντες ἐπὶ ταῖς ταλαιπωρίαις ὑμῶν ταῖς ἐπερχομέναις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 2, 'Ὁ πλοῦτος ὑμῶν σέσηπεν, καὶ τὰ ἱμάτια ὑμῶν σητόβρωτα γέγονεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 3, 'Ὁ χρυσὸς ὑμῶν καὶ ὁ ἄργυρος κατίωται, καὶ ὁ ἰὸς αὐτῶν εἰς μαρτύριον ὑμῖν ἔσται, καὶ φάγεται τὰς σάρκας ὑμῶν ὡς πῦρ. Ἐθησαυρίσατε ἐν ἐσχάταις ἡμέραις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 4, 'Ἰδοὺ, ὁ μισθὸς τῶν ἐργατῶν, τῶν ἀμησάντων τὰς χώρας ὑμῶν, ὁ ἀφυστερημένος ἀφʼ ὑμῶν, κράζει, καὶ αἱ βοαὶ τῶν θερισάντων, εἰς τὰ ὦτα  ̊Κυρίου Σαβαὼθ εἰσελήλυθαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 5, 'Ἐτρυφήσατε ἐπὶ τῆς γῆς. Καὶ ἐσπαταλήσατε, ἐθρέψατε τὰς καρδίας ὑμῶν ἐν ἡμέρᾳ σφαγῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 6, 'Κατεδικάσατε, ἐφονεύσατε τὸν δίκαιον, οὐκ ἀντιτάσσεται ὑμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 7, '¶Μακροθυμήσατε οὖν, ἀδελφοί, ἕως τῆς παρουσίας τοῦ  ̊Κυρίου. Ἰδοὺ, ὁ γεωργὸς ἐκδέχεται τὸν τίμιον καρπὸν τῆς γῆς, μακροθυμῶν ἐπʼ αὐτῷ ἕως λάβῃ πρόϊμον καὶ ὄψιμον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 8, 'Μακροθυμήσατε καὶ ὑμεῖς, στηρίξατε τὰς καρδίας ὑμῶν, ὅτι ἡ παρουσία τοῦ  ̊Κυρίου ἤγγικεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 9, 'Μὴ στενάζετε, ἀδελφοί, κατʼ ἀλλήλων, ἵνα μὴ κριθῆτε. Ἰδοὺ, ὁ κριτὴς πρὸ τῶν θυρῶν ἕστηκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 10, 'Ὑπόδειγμα λάβετε, ἀδελφοί, τῆς κακοπαθείας, καὶ τῆς μακροθυμίας, τοὺς προφήτας, οἳ ἐλάλησαν ἐν ὀνόματι  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 11, 'Ἰδοὺ, μακαρίζομεν τοὺς ὑπομείναντας. Τὴν ὑπομονὴν Ἰὼβ ἠκούσατε, καὶ τὸ τέλος  ̊Κυρίου εἴδετε, ὅτι πολύσπλαγχνός ἐστιν ὁ  ̊Κύριος καὶ οἰκτίρμων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 12, '¶Πρὸ πάντων δέ, ἀδελφοί μου, μὴ ὀμνύετε, μήτε τὸν οὐρανὸν, μήτε τὴν γῆν, μήτε ἄλλον τινὰ ὅρκον· ἤτω δὲ ὑμῶν τὸ “Ναὶ”, ναὶ, καὶ τὸ “Οὒ”, οὔ, ἵνα μὴ ὑπὸ κρίσιν πέσητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 13, '¶Κακοπαθεῖ τις ἐν ὑμῖν; Προσευχέσθω. Εὐθυμεῖ τις; Ψαλλέτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 14, 'Ἀσθενεῖ τις ἐν ὑμῖν; Προσκαλεσάσθω τοὺς πρεσβυτέρους τῆς ἐκκλησίας, καὶ προσευξάσθωσαν ἐπʼ αὐτὸν, ἀλείψαντες αὐτὸν ἐλαίῳ ἐν τῷ ὀνόματι τοῦ  ̊Κυρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 15, 'Καὶ ἡ εὐχὴ τῆς πίστεως σώσει τὸν κάμνοντα, καὶ ἐγερεῖ αὐτὸν ὁ  ̊Κύριος· κἂν ἁμαρτίας ᾖ πεποιηκώς, ἀφεθήσεται αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 16, 'Ἐξομολογεῖσθε οὖν ἀλλήλοις τὰς ἁμαρτίας, καὶ προσεύχεσθε ὑπὲρ ἀλλήλων, ὅπως ἰαθῆτε. Πολὺ ἰσχύει δέησις δικαίου ἐνεργουμένη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 17, 'Ἠλίας ἄνθρωπος ἦν ὁμοιοπαθὴς ἡμῖν, καὶ προσευχῇ προσηύξατο τοῦ μὴ βρέξαι, καὶ οὐκ ἔβρεξεν ἐπὶ τῆς γῆς, ἐνιαυτοὺς τρεῖς καὶ μῆνας ἕξ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 18, 'Καὶ πάλιν προσηύξατο, καὶ ὁ οὐρανὸς ὑετὸν ἔδωκεν, καὶ ἡ γῆ ἐβλάστησεν τὸν καρπὸν αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 19, '¶Ἀδελφοί μου, ἐάν τις ἐν ὑμῖν πλανηθῇ ἀπὸ τῆς ἀληθείας, καὶ ἐπιστρέψῃ τις αὐτόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 20, 'γινώσκετε ὅτι ὁ ἐπιστρέψας ἁμαρτωλὸν ἐκ πλάνης ὁδοῦ αὐτοῦ, σώσει ψυχὴν αὐτοῦ ἐκ θανάτου, καὶ καλύψει πλῆθος ἁμαρτιῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 1, '¶Πέτρος, ἀπόστολος  ̊Ἰησοῦ  ̊Χριστοῦ, ἐκλεκτοῖς παρεπιδήμοις διασπορᾶς Πόντου, Γαλατίας, Καππαδοκίας, Ἀσίας, καὶ Βιθυνίας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 2, 'κατὰ πρόγνωσιν  ̊Θεοῦ Πατρός ἐν ἁγιασμῷ  ̊Πνεύματος, εἰς ὑπακοὴν καὶ ῥαντισμὸν αἵματος  ̊Ἰησοῦ  ̊Χριστοῦ: χάρις ὑμῖν καὶ εἰρήνη πληθυνθείη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 3, '¶Εὐλογητὸς ὁ  ̊Θεὸς καὶ Πατὴρ τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, ὁ κατὰ τὸ πολὺ αὐτοῦ ἔλεος, ἀναγεννήσας ἡμᾶς εἰς ἐλπίδα ζῶσαν, διʼ ἀναστάσεως  ̊Ἰησοῦ  ̊Χριστοῦ ἐκ νεκρῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 4, 'εἰς κληρονομίαν ἄφθαρτον, καὶ ἀμίαντον, καὶ ἀμάραντον, τετηρημένην ἐν οὐρανοῖς εἰς ὑμᾶς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 5, 'τοὺς ἐν δυνάμει  ̊Θεοῦ φρουρουμένους διὰ πίστεως, εἰς σωτηρίαν ἑτοίμην ἀποκαλυφθῆναι ἐν καιρῷ ἐσχάτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 6, 'Ἐν ᾧ ἀγαλλιᾶσθε ὀλίγον ἄρτι, εἰ δέον λυπηθέντες ἐν ποικίλοις πειρασμοῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 7, 'ἵνα τὸ δοκίμιον ὑμῶν τῆς πίστεως πολυτιμότερον χρυσίου τοῦ ἀπολλυμένου, διὰ πυρὸς δὲ δοκιμαζομένου, εὑρεθῇ εἰς ἔπαινον, καὶ δόξαν, καὶ τιμὴν, ἐν ἀποκαλύψει  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 8, 'Ὃν οὐκ ἰδόντες ἀγαπᾶτε, εἰς ὃν ἄρτι μὴ ὁρῶντες πιστεύοντες δὲ, ἀγαλλιᾶσθε χαρᾷ ἀνεκλαλήτῳ καὶ δεδοξασμένῃ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 9, 'κομιζόμενοι τὸ τέλος τῆς πίστεως ὑμῶν, σωτηρίαν ψυχῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 10, '¶Περὶ ἧς σωτηρίας, ἐξεζήτησαν καὶ ἐξηραύνησαν προφῆται, οἱ περὶ τῆς εἰς ὑμᾶς χάριτος προφητεύσαντες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 11, 'ἐραυνῶντες εἰς τίνα ἢ ποῖον καιρὸν ἐδήλου τὸ ἐν αὐτοῖς  ̊Πνεῦμα  ̊Χριστοῦ, προμαρτυρόμενον τὰ εἰς  ̊Χριστὸν παθήματα, καὶ τὰς μετὰ ταῦτα δόξας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 12, 'Οἷς ἀπεκαλύφθη ὅτι οὐχ ἑαυτοῖς, ὑμῖν δὲ διηκόνουν αὐτά, ἃ νῦν ἀνηγγέλη ὑμῖν, διὰ τῶν εὐαγγελισαμένων ὑμᾶς  ̊Πνεύματι Ἁγίῳ, ἀποσταλέντι ἀπʼ οὐρανοῦ, εἰς ἃ ἐπιθυμοῦσιν ἄγγελοι παρακύψαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 13, '¶Διὸ ἀναζωσάμενοι τὰς ὀσφύας τῆς διανοίας ὑμῶν, νήφοντες, τελείως ἐλπίσατε ἐπὶ τὴν φερομένην ὑμῖν χάριν ἐν ἀποκαλύψει  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 14, 'Ὡς τέκνα ὑπακοῆς, μὴ συσχηματιζόμενοι ταῖς πρότερον ἐν τῇ ἀγνοίᾳ ὑμῶν ἐπιθυμίαις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 15, 'ἀλλὰ κατὰ τὸν καλέσαντα ὑμᾶς ἅγιον, καὶ αὐτοὶ ἅγιοι ἐν πάσῃ ἀναστροφῇ γενήθητε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 16, 'διότι γέγραπται, “Ἅγιοι ἔσεσθε, ὅτι ἐγὼ ἅγιος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 17, '¶Καὶ εἰ Πατέρα ἐπικαλεῖσθε, τὸν ἀπροσωπολήμπτως κρίνοντα κατὰ τὸ ἑκάστου ἔργον, ἐν φόβῳ τὸν τῆς παροικίας ὑμῶν χρόνον ἀναστράφητε·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 18, 'εἰδότες ὅτι οὐ φθαρτοῖς, ἀργυρίῳ ἢ χρυσίῳ, ἐλυτρώθητε ἐκ τῆς ματαίας ὑμῶν ἀναστροφῆς πατροπαραδότου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 19, 'ἀλλὰ τιμίῳ αἵματι, ὡς ἀμνοῦ ἀμώμου καὶ ἀσπίλου  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 20, 'προεγνωσμένου μὲν πρὸ καταβολῆς κόσμου, φανερωθέντος δὲ ἐπʼ ἐσχάτου τῶν χρόνων διʼ ὑμᾶς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 21, 'τοὺς διʼ αὐτοῦ πιστοὺς εἰς  ̊Θεὸν, τὸν ἐγείραντα αὐτὸν ἐκ νεκρῶν, καὶ δόξαν αὐτῷ δόντα, ὥστε τὴν πίστιν ὑμῶν καὶ ἐλπίδα, εἶναι εἰς  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 22, '¶Τὰς ψυχὰς ὑμῶν ἡγνικότες ἐν τῇ ὑπακοῇ τῆς ἀληθείας εἰς φιλαδελφίαν ἀνυπόκριτον ἐκ καρδίας, ἀλλήλους ἀγαπήσατε ἐκτενῶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 23, 'Ἀναγεγεννημένοι, οὐκ ἐκ σπορᾶς φθαρτῆς, ἀλλὰ ἀφθάρτου, διὰ λόγου ζῶντος  ̊Θεοῦ, καὶ μένοντος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 24, 'Διότι, “Πᾶσα σὰρξ ὡς χόρτος, καὶ πᾶσα δόξα αὐτῆς ὡς ἄνθος χόρτου.” “Ἐξηράνθη ὁ χόρτος, καὶ τὸ ἄνθος ἐξέπεσεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 25, 'τὸ δὲ ῥῆμα  ̊Κυρίου μένει εἰς τὸν αἰῶνα.” Τοῦτο δέ ἐστιν τὸ ῥῆμα τὸ εὐαγγελισθὲν εἰς ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 1, '¶Ἀποθέμενοι οὖν πᾶσαν κακίαν, καὶ πάντα δόλον, καὶ ὑποκρίσεις, καὶ φθόνους, καὶ πάσας καταλαλιάς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 2, 'ὡς ἀρτιγέννητα βρέφη τὸ λογικὸν ἄδολον γάλα ἐπιποθήσατε, ἵνα ἐν αὐτῷ αὐξηθῆτε εἰς σωτηρίαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 3, 'εἰ ἐγεύσασθε ὅτι χρηστὸς ὁ  ̊Κύριος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 4, '¶Πρὸς ὃν προσερχόμενοι λίθον ζῶντα, ὑπὸ ἀνθρώπων μὲν ἀποδεδοκιμασμένον, παρὰ δὲ  ̊Θεῷ ἐκλεκτὸν, ἔντιμον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 5, 'καὶ αὐτοὶ ὡς λίθοι ζῶντες οἰκοδομεῖσθε, οἶκος πνευματικὸς, εἰς ἱεράτευμα ἅγιον ἀνενέγκαι πνευματικὰς θυσίας εὐπροσδέκτους  ̊Θεῷ διὰ  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 6, 'Διότι περιέχει ἐν Γραφῇ: “Ἰδοὺ, τίθημι ἐν Σιὼν λίθον, ἀκρογωνιαῖον ἐκλεκτὸν ἔντιμον, καὶ ὁ πιστεύων ἐπʼ αὐτῷ, οὐ μὴ καταισχυνθῇ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 7, 'Ὑμῖν οὖν ἡ τιμὴ, τοῖς πιστεύουσιν· ἀπιστοῦσιν δὲ, “Λίθος ὃν ἀπεδοκίμασαν οἱ οἰκοδομοῦντες, οὗτος ἐγενήθη εἰς κεφαλὴν γωνίας”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 8, 'καὶ, “Λίθος προσκόμματος, καὶ πέτρα σκανδάλου”· οἳ προσκόπτουσιν τῷ λόγῳ ἀπειθοῦντες, εἰς ὃ καὶ ἐτέθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 9, '¶Ὑμεῖς δὲ “γένος ἐκλεκτόν”, “βασίλειον ἱεράτευμα, ἔθνος ἅγιον, λαὸς εἰς περιποίησιν”, ὅπως τὰς ἀρετὰς ἐξαγγείλητε, τοῦ ἐκ σκότους ὑμᾶς καλέσαντος, εἰς τὸ θαυμαστὸν αὐτοῦ φῶς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 10, 'οἵ ποτε “οὐ λαὸς, νῦν δὲ λαὸς  ̊Θεοῦ, οἱ οὐκ ἠλεημένοι, νῦν δὲ ἐλεηθέντες”.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 11, '¶Ἀγαπητοί, παρακαλῶ ὡς παροίκους καὶ παρεπιδήμους, ἀπέχεσθαι τῶν σαρκικῶν ἐπιθυμιῶν, αἵτινες στρατεύονται κατὰ τῆς ψυχῆς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 12, 'τὴν ἀναστροφὴν ὑμῶν ἐν τοῖς ἔθνεσιν ἔχοντες καλήν, ἵνα ἐν ᾧ καταλαλοῦσιν ὑμῶν ὡς κακοποιῶν, ἐκ τῶν καλῶν ἔργων ἐποπτεύοντες, δοξάσωσι τὸν  ̊Θεὸν ἐν ἡμέρᾳ ἐπισκοπῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 13, '¶Ὑποτάγητε πάσῃ ἀνθρωπίνῃ κτίσει διὰ τὸν  ̊Κύριον· εἴτε βασιλεῖ ὡς ὑπερέχοντι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 14, 'εἴτε ἡγεμόσιν ὡς διʼ αὐτοῦ πεμπομένοις, εἰς ἐκδίκησιν κακοποιῶν, ἔπαινον δὲ ἀγαθοποιῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 15, 'Ὅτι οὕτως ἐστὶν τὸ θέλημα τοῦ  ̊Θεοῦ, ἀγαθοποιοῦντας φιμοῦν τὴν τῶν ἀφρόνων ἀνθρώπων ἀγνωσίαν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 16, 'ὡς ἐλεύθεροι, καὶ μὴ ὡς ἐπικάλυμμα ἔχοντες τῆς κακίας τὴν ἐλευθερίαν, ἀλλʼ ὡς  ̊Θεοῦ δοῦλοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 17, 'Πάντας τιμήσατε, τὴν ἀδελφότητα ἀγαπᾶτε, τὸν  ̊Θεὸν φοβεῖσθε, τὸν βασιλέα τιμᾶτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 18, '¶Οἱ οἰκέται, ὑποτασσόμενοι ἐν παντὶ φόβῳ τοῖς δεσπόταις, οὐ μόνον τοῖς ἀγαθοῖς καὶ ἐπιεικέσιν, ἀλλὰ καὶ τοῖς σκολιοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 19, 'Τοῦτο γὰρ χάρις, εἰ διὰ συνείδησιν  ̊Θεοῦ, ὑποφέρει τις λύπας πάσχων ἀδίκως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 20, 'Ποῖον γὰρ κλέος, εἰ ἁμαρτάνοντες καὶ κολαφιζόμενοι ὑπομενεῖτε; Ἀλλʼ εἰ ἀγαθοποιοῦντες καὶ πάσχοντες ὑπομενεῖτε, τοῦτο χάρις παρὰ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 21, 'Εἰς τοῦτο γὰρ ἐκλήθητε, ὅτι καὶ  ̊Χριστὸς ἔπαθεν ὑπὲρ ὑμῶν, ὑμῖν ὑπολιμπάνων ὑπογραμμὸν, ἵνα ἐπακολουθήσητε τοῖς ἴχνεσιν αὐτοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 22, '“ὃς ἁμαρτίαν οὐκ ἐποίησεν, οὐδὲ εὑρέθη δόλος ἐν τῷ στόματι αὐτοῦ”·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 23, 'ὃς λοιδορούμενος, οὐκ ἀντελοιδόρει, πάσχων, οὐκ ἠπείλει, παρεδίδου δὲ τῷ κρίνοντι δικαίως·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 24, 'ὃς τὰς ἁμαρτίας ἡμῶν αὐτὸς ἀνήνεγκεν ἐν τῷ σώματι αὐτοῦ ἐπὶ τὸ ξύλον, ἵνα ταῖς ἁμαρτίαις ἀπογενόμενοι, τῇ δικαιοσύνῃ ζήσωμεν· οὗ τῷ μώλωπι ἰάθητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 25, 'Ἦτε γὰρ ὡς πρόβατα πλανώμενοι, ἀλλʼ ἐπεστράφητε νῦν ἐπὶ τὸν ποιμένα καὶ ἐπίσκοπον τῶν ψυχῶν ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 1, '¶Ὁμοίως, γυναῖκες, ὑποτασσόμεναι τοῖς ἰδίοις ἀνδράσιν, ἵνα καὶ εἴ τινες ἀπειθοῦσιν τῷ λόγῳ, διὰ τῆς τῶν γυναικῶν ἀναστροφῆς ἄνευ λόγου κερδηθήσονται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 2, 'ἐποπτεύσαντες τὴν ἐν φόβῳ ἁγνὴν ἀναστροφὴν ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 3, 'Ὧν ἔστω οὐχ ὁ ἔξωθεν ἐμπλοκῆς τριχῶν καὶ περιθέσεως χρυσίων ἢ ἐνδύσεως ἱματίων κόσμος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 4, 'ἀλλʼ ὁ κρυπτὸς τῆς καρδίας ἄνθρωπος, ἐν τῷ ἀφθάρτῳ τοῦ πρᾳέος καὶ ἡσυχίου πνεύματος, ὅ ἐστιν ἐνώπιον τοῦ  ̊Θεοῦ πολυτελές.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 5, 'Οὕτως γάρ ποτε καὶ αἱ ἅγιαι γυναῖκες αἱ ἐλπίζουσαι εἰς  ̊Θεὸν ἐκόσμουν ἑαυτάς, ὑποτασσόμεναι τοῖς ἰδίοις ἀνδράσιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 6, 'ὡς Σάρρα ὑπήκουσεν τῷ Ἀβραάμ, “κύριον”, αὐτὸν καλοῦσα, ἧς ἐγενήθητε τέκνα, ἀγαθοποιοῦσαι καὶ μὴ φοβούμεναι μηδεμίαν πτόησιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 7, '¶Οἱ ἄνδρες, ὁμοίως συνοικοῦντες κατὰ γνῶσιν, ὡς ἀσθενεστέρῳ σκεύει τῷ γυναικείῳ, ἀπονέμοντες τιμήν ὡς καὶ συγκληρονόμοις χάριτος ζωῆς, εἰς τὸ μὴ ἐγκόπτεσθαι τὰς προσευχὰς ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 8, '¶Τὸ δὲ τέλος, πάντες, ὁμόφρονες, συμπαθεῖς, φιλάδελφοι, εὔσπλαγχνοι, ταπεινόφρονες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 9, 'μὴ ἀποδιδόντες κακὸν ἀντὶ κακοῦ, ἢ λοιδορίαν ἀντὶ λοιδορίας, τοὐναντίον δὲ εὐλογοῦντες, ὅτι εἰς τοῦτο ἐκλήθητε, ἵνα εὐλογίαν κληρονομήσητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 10, '“Ὁ” γὰρ “θέλων ζωὴν ἀγαπᾶν, καὶ ἰδεῖν ἡμέρας ἀγαθὰς, παυσάτω τὴν γλῶσσαν ἀπὸ κακοῦ, καὶ χείλη τοῦ μὴ λαλῆσαι δόλον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 11, 'Ἐκκλινάτω δὲ ἀπὸ κακοῦ, καὶ ποιησάτω ἀγαθόν, ζητησάτω εἰρήνην καὶ διωξάτω αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 12, 'Ὅτι ὀφθαλμοὶ  ̊Κυρίου ἐπὶ δικαίους, καὶ ὦτα αὐτοῦ εἰς δέησιν αὐτῶν, πρόσωπον δὲ  ̊Κυρίου ἐπὶ ποιοῦντας κακά.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 13, '¶Καὶ τίς ὁ κακώσων ὑμᾶς, ἐὰν τοῦ ἀγαθοῦ ζηλωταὶ γένησθε;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 14, 'Ἀλλʼ εἰ καὶ πάσχοιτε διὰ δικαιοσύνην, μακάριοι. “Τὸν δὲ φόβον αὐτῶν, μὴ φοβηθῆτε μηδὲ ταραχθῆτε”,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 15, ' ̊Κύριον δὲ τὸν  ̊Χριστὸν ἁγιάσατε ἐν ταῖς καρδίαις ὑμῶν, ἕτοιμοι ἀεὶ πρὸς ἀπολογίαν παντὶ τῷ αἰτοῦντι ὑμᾶς λόγον, περὶ τῆς ἐν ὑμῖν ἐλπίδος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 16, 'ἀλλὰ μετὰ πραΰτητος καὶ φόβου, συνείδησιν ἔχοντες ἀγαθήν, ἵνα ἐν ᾧ καταλαλοῦσιν ὑμῶν ὡς κακοποιῶν, καταισχυνθῶσιν οἱ ἐπηρεάζοντες ὑμῶν τὴν ἀγαθὴν ἐν  ̊Χριστῷ ἀναστροφήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 17, 'Κρεῖττον γὰρ ἀγαθοποιοῦντας, εἰ θέλοι τὸ θέλημα τοῦ  ̊Θεοῦ, πάσχειν ἢ κακοποιοῦντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 18, 'Ὅτι καὶ  ̊Χριστὸς ἅπαξ περὶ ἁμαρτιῶν ἀπέθανεν, δίκαιος ὑπὲρ ἀδίκων, ἵνα ὑμᾶς προσαγάγῃ τῷ  ̊Θεῷ, θανατωθεὶς μὲν σαρκὶ, ζῳοποιηθεὶς δὲ  ̊Πνεύματι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 19, 'ἐν ᾧ καὶ τοῖς ἐν φυλακῇ πνεύμασιν πορευθεὶς ἐκήρυξεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 20, 'ἀπειθήσασίν ποτε ὅτε ἀπεξεδέχετο ἡ τοῦ  ̊Θεοῦ μακροθυμία ἐν ἡμέραις Νῶε, κατασκευαζομένης κιβωτοῦ εἰς ἣν ὀλίγοι, τοῦτʼ ἔστιν, ὀκτὼ ψυχαί, διεσώθησαν διʼ ὕδατος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 21, 'Ὃ καὶ ὑμᾶς ἀντίτυπον νῦν σῴζει βάπτισμα, οὐ σαρκὸς ἀπόθεσις ῥύπου, ἀλλὰ συνειδήσεως ἀγαθῆς, ἐπερώτημα εἰς  ̊Θεόν διʼ ἀναστάσεως  ̊Ἰησοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 22, 'ὅς ἐστιν ἐν δεξιᾷ  ̊Θεοῦ, πορευθεὶς εἰς οὐρανὸν, ὑποταγέντων αὐτῷ ἀγγέλων, καὶ ἐξουσιῶν, καὶ δυνάμεων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 1, '¶ ̊Χριστοῦ οὖν παθόντος σαρκὶ, καὶ ὑμεῖς τὴν αὐτὴν ἔννοιαν ὁπλίσασθε, ὅτι ὁ παθὼν σαρκὶ πέπαυται ἁμαρτίας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 2, 'εἰς τὸ μηκέτι ἀνθρώπων ἐπιθυμίαις, ἀλλὰ θελήματι  ̊Θεοῦ, τὸν ἐπίλοιπον ἐν σαρκὶ βιῶσαι χρόνον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 3, 'Ἀρκετὸς γὰρ ὁ παρεληλυθὼς χρόνος τὸ βούλημα τῶν ἐθνῶν κατειργάσθαι, πεπορευμένους ἐν ἀσελγείαις, ἐπιθυμίαις, οἰνοφλυγίαις, κώμοις, πότοις, καὶ ἀθεμίτοις εἰδωλολατρίαις.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 4, 'Ἐν ᾧ ξενίζονται, μὴ συντρεχόντων ὑμῶν εἰς τὴν αὐτὴν τῆς ἀσωτίας ἀνάχυσιν, βλασφημοῦντες·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 5, 'οἳ ἀποδώσουσιν λόγον τῷ ἑτοίμως κρῖναι ζῶντας καὶ νεκρούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 6, 'Εἰς τοῦτο γὰρ καὶ νεκροῖς εὐηγγελίσθη, ἵνα κριθῶσι μὲν κατὰ ἀνθρώπους σαρκὶ, ζῶσι δὲ κατὰ  ̊Θεὸν πνεύματι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 7, '¶Πάντων δὲ τὸ τέλος ἤγγικεν. Σωφρονήσατε οὖν καὶ νήψατε εἰς προσευχάς·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 8, 'πρὸ πάντων, τὴν εἰς ἑαυτοὺς ἀγάπην ἐκτενῆ ἔχοντες, ὅτι ἀγάπη καλύπτει πλῆθος ἁμαρτιῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 9, 'φιλόξενοι εἰς ἀλλήλους ἄνευ γογγυσμοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 10, 'ἕκαστος καθὼς ἔλαβεν χάρισμα, εἰς ἑαυτοὺς αὐτὸ διακονοῦντες, ὡς καλοὶ οἰκονόμοι ποικίλης χάριτος  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 11, 'Εἴ τις λαλεῖ, ὡς λόγια  ̊Θεοῦ· εἴ τις διακονεῖ, ὡς ἐξ ἰσχύος ἧς χορηγεῖ ὁ  ̊Θεός, ἵνα ἐν πᾶσιν δοξάζηται ὁ  ̊Θεὸς διὰ  ̊Ἰησοῦ  ̊Χριστοῦ, ᾧ ἐστιν ἡ δόξα καὶ τὸ κράτος εἰς τοὺς αἰῶνας τῶν αἰώνων. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 12, '¶Ἀγαπητοί, μὴ ξενίζεσθε τῇ ἐν ὑμῖν πυρώσει πρὸς πειρασμὸν ὑμῖν γινομένῃ, ὡς ξένου ὑμῖν συμβαίνοντος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 13, 'ἀλλὰ καθὸ κοινωνεῖτε τοῖς τοῦ  ̊Χριστοῦ παθήμασιν, χαίρετε ἵνα καὶ ἐν τῇ ἀποκαλύψει τῆς δόξης αὐτοῦ χαρῆτε ἀγαλλιώμενοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 14, 'Εἰ ὀνειδίζεσθε ἐν ὀνόματι  ̊Χριστοῦ, μακάριοι, ὅτι τὸ τῆς δόξης καὶ τὸ τοῦ  ̊Θεοῦ  ̊Πνεῦμα, ἐφʼ ὑμᾶς ἀναπαύεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 15, 'Μὴ γάρ τις ὑμῶν πασχέτω ὡς φονεὺς, ἢ κλέπτης, ἢ κακοποιὸς, ἢ ὡς ἀλλοτριεπίσκοπος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 16, 'Εἰ δὲ ὡς Χριστιανός, μὴ αἰσχυνέσθω, δοξαζέτω δὲ τὸν  ̊Θεὸν ἐν τῷ ὀνόματι τούτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 17, 'Ὅτι ὁ καιρὸς τοῦ ἄρξασθαι τὸ κρίμα ἀπὸ τοῦ οἴκου τοῦ  ̊Θεοῦ· εἰ δὲ πρῶτον ἀφʼ ἡμῶν, τί τὸ τέλος τῶν ἀπειθούντων τῷ τοῦ  ̊Θεοῦ εὐαγγελίῳ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 18, '“Καὶ εἰ ὁ δίκαιος μόλις σῴζεται, ὁ ἀσεβὴς καὶ ἁμαρτωλὸς ποῦ φανεῖται;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 4, 19, 'Ὥστε καὶ οἱ πάσχοντες κατὰ τὸ θέλημα τοῦ  ̊Θεοῦ, πιστῷ Κτίστῃ παρατιθέσθωσαν τὰς ψυχὰς αὐτῶν ἐν ἀγαθοποιΐᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 5, 1, '¶Πρεσβυτέρους οὖν ἐν ὑμῖν παρακαλῶ, ὁ συμπρεσβύτερος καὶ μάρτυς τῶν τοῦ  ̊Χριστοῦ παθημάτων, ὁ καὶ τῆς μελλούσης ἀποκαλύπτεσθαι δόξης κοινωνός,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 5, 2, 'ποιμάνατε τὸ ἐν ὑμῖν ποίμνιον τοῦ  ̊Θεοῦ, μὴ ἀναγκαστῶς, ἀλλὰ ἑκουσίως, κατὰ  ̊Θεόν, μηδὲ αἰσχροκερδῶς, ἀλλὰ προθύμως,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 5, 3, 'μηδʼ ὡς κατακυριεύοντες τῶν κλήρων, ἀλλὰ τύποι γινόμενοι τοῦ ποιμνίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 5, 4, 'Καὶ φανερωθέντος τοῦ ἀρχιποίμενος, κομιεῖσθε τὸν ἀμαράντινον τῆς δόξης στέφανον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 5, 5, 'Ὁμοίως, νεώτεροι, ὑποτάγητε πρεσβυτέροις. Πάντες, δὲ ἀλλήλοις τὴν ταπεινοφροσύνην ἐγκομβώσασθε ὅτι, “Ὁ  ̊Θεὸς ὑπερηφάνοις ἀντιτάσσεται, ταπεινοῖς δὲ δίδωσιν χάριν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 5, 6, '¶Ταπεινώθητε οὖν ὑπὸ τὴν κραταιὰν χεῖρα τοῦ  ̊Θεοῦ, ἵνα ὑμᾶς ὑψώσῃ ἐν καιρῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 5, 7, 'πᾶσαν τὴν μέριμναν ὑμῶν ἐπιρίψαντες ἐπʼ αὐτόν, ὅτι αὐτῷ μέλει περὶ ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 5, 8, 'Νήψατε, γρηγορήσατε. Ὁ ἀντίδικος ὑμῶν, διάβολος, ὡς λέων ὠρυόμενος περιπατεῖ, ζητῶν καταπιεῖν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 5, 9, 'ᾧ ἀντίστητε, στερεοὶ τῇ πίστει, εἰδότες τὰ αὐτὰ τῶν παθημάτων, τῇ ἐν τῷ κόσμῳ ὑμῶν ἀδελφότητι ἐπιτελεῖσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 5, 10, 'Ὁ δὲ  ̊Θεὸς πάσης χάριτος, ὁ καλέσας ὑμᾶς εἰς τὴν αἰώνιον αὐτοῦ δόξαν ἐν  ̊Χριστῷ, ὀλίγον παθόντας, αὐτὸς καταρτίσει, στηρίξει, σθενώσει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 5, 11, 'αὐτῷ τὸ κράτος εἰς τοὺς αἰῶνας τῶν αἰώνων. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 5, 12, '¶Διὰ Σιλουανοῦ, ὑμῖν τοῦ πιστοῦ ἀδελφοῦ (ὡς λογίζομαι), διʼ ὀλίγων ἔγραψα, παρακαλῶν καὶ ἐπιμαρτυρῶν ταύτην εἶναι ἀληθῆ χάριν τοῦ  ̊Θεοῦ, εἰς ἣν στῆτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 5, 13, 'Ἀσπάζεται ὑμᾶς ἡ ἐν Βαβυλῶνι συνεκλεκτὴ, καὶ Μᾶρκος, ὁ υἱός μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 5, 14, 'Ἀσπάσασθε ἀλλήλους ἐν φιλήματι ἀγάπης. Εἰρήνη ὑμῖν πᾶσιν, τοῖς ἐν  ̊Χριστῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 1, '¶Σίμων Πέτρος, δοῦλος καὶ ἀπόστολος  ̊Ἰησοῦ  ̊Χριστοῦ, τοῖς ἰσότιμον ἡμῖν λαχοῦσιν πίστιν ἐν δικαιοσύνῃ τοῦ  ̊Θεοῦ ἡμῶν καὶ Σωτῆρος,  ̊Ἰησοῦ  ̊Χριστοῦ:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 2, 'χάρις ὑμῖν καὶ εἰρήνη πληθυνθείη ἐν ἐπιγνώσει τοῦ  ̊Θεοῦ, καὶ  ̊Ἰησοῦ τοῦ  ̊Κυρίου ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 3, '¶Ὡς πάντα ἡμῖν τῆς θείας δυνάμεως αὐτοῦ, τὰ πρὸς ζωὴν καὶ εὐσέβειαν δεδωρημένης, διὰ τῆς ἐπιγνώσεως τοῦ καλέσαντος ἡμᾶς, ἰδίᾳ δόξῃ καὶ ἀρετῇ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 4, 'διʼ ὧν τὰ τίμια καὶ μέγιστα ἡμῖν ἐπαγγέλματα δεδώρηται, ἵνα διὰ τούτων γένησθε θείας κοινωνοὶ φύσεως, ἀποφυγόντες τῆς ἐν τῷ κόσμῳ ἐν ἐπιθυμίᾳ φθορᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 5, 'Καὶ αὐτὸ τοῦτο δὲ σπουδὴν πᾶσαν παρεισενέγκαντες, ἐπιχορηγήσατε ἐν τῇ πίστει ὑμῶν τὴν ἀρετήν, ἐν δὲ τῇ ἀρετῇ τὴν γνῶσιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 6, 'ἐν δὲ τῇ γνώσει τὴν ἐγκράτειαν, ἐν δὲ τῇ ἐγκρατείᾳ τὴν ὑπομονήν, ἐν δὲ τῇ ὑπομονῇ τὴν εὐσέβειαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 7, 'ἐν δὲ τῇ εὐσεβείᾳ τὴν φιλαδελφίαν, ἐν δὲ τῇ φιλαδελφίᾳ τὴν ἀγάπην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 8, 'Ταῦτα γὰρ ὑμῖν ὑπάρχοντα καὶ πλεονάζοντα, οὐκ ἀργοὺς οὐδὲ ἀκάρπους καθίστησιν, εἰς τὴν τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, ἐπίγνωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 9, 'ὯΙ γὰρ μὴ πάρεστιν ταῦτα, τυφλός ἐστιν, μυωπάζων, λήθην λαβὼν τοῦ καθαρισμοῦ τῶν πάλαι αὐτοῦ ἁμαρτιῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 10, 'Διὸ μᾶλλον, ἀδελφοί, σπουδάσατε, βεβαίαν ὑμῶν τὴν κλῆσιν καὶ ἐκλογὴν ποιεῖσθαι, ταῦτα γὰρ ποιοῦντες οὐ μὴ πταίσητέ ποτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 11, 'Οὕτως γὰρ πλουσίως ἐπιχορηγηθήσεται ὑμῖν ἡ εἴσοδος εἰς τὴν αἰώνιον βασιλείαν τοῦ  ̊Κυρίου ἡμῶν καὶ Σωτῆρος,  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 12, '¶Διὸ μελλήσω ἀεὶ ὑμᾶς ὑπομιμνῄσκειν περὶ τούτων, καίπερ εἰδότας καὶ ἐστηριγμένους ἐν τῇ παρούσῃ ἀληθείᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 13, 'Δίκαιον δὲ ἡγοῦμαι ἐφʼ ὅσον εἰμὶ ἐν τούτῳ τῷ σκηνώματι, διεγείρειν ὑμᾶς ἐν ὑπομνήσει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 14, 'εἰδὼς ὅτι ταχινή ἐστιν ἡ ἀπόθεσις τοῦ σκηνώματός μου, καθὼς καὶ ὁ  ̊Κύριος ἡμῶν,  ̊Ἰησοῦς  ̊Χριστὸς, ἐδήλωσέν μοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 15, 'Σπουδάσω δὲ καὶ ἑκάστοτε ἔχειν ὑμᾶς μετὰ τὴν ἐμὴν ἔξοδον, τὴν τούτων μνήμην ποιεῖσθαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 16, '¶Οὐ γὰρ σεσοφισμένοις μύθοις ἐξακολουθήσαντες, ἐγνωρίσαμεν ὑμῖν τὴν τοῦ  ̊Κυρίου ἡμῶν  ̊Ἰησοῦ  ̊Χριστοῦ δύναμιν καὶ παρουσίαν, ἀλλʼ ἐπόπται γενηθέντες τῆς ἐκείνου μεγαλειότητος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 17, 'Λαβὼν γὰρ παρὰ  ̊Θεοῦ Πατρὸς τιμὴν καὶ δόξαν, φωνῆς ἐνεχθείσης αὐτῷ τοιᾶσδε ὑπὸ τῆς Μεγαλοπρεποῦς Δόξης, “Οὗτός ἐστιν ὁ Υἱός μου, ὁ ἀγαπητός εἰς ὃν ἐγὼ εὐδόκησα”·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 18, 'καὶ ταύτην τὴν φωνὴν ἡμεῖς ἠκούσαμεν ἐξ οὐρανοῦ, ἐνεχθεῖσαν σὺν αὐτῷ, ὄντες ἐν τῷ ἁγίῳ ὄρει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 19, 'Καὶ ἔχομεν βεβαιότερον τὸν προφητικὸν λόγον, ᾧ καλῶς ποιεῖτε προσέχοντες, ὡς λύχνῳ φαίνοντι ἐν αὐχμηρῷ τόπῳ, ἕως οὗ ἡμέρα διαυγάσῃ, καὶ φωσφόρος ἀνατείλῃ ἐν ταῖς καρδίαις ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 20, 'Τοῦτο πρῶτον γινώσκοντες, ὅτι πᾶσα προφητεία Γραφῆς ἰδίας ἐπιλύσεως οὐ γίνεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 21, 'Οὐ γὰρ θελήματι ἀνθρώπου ἠνέχθη προφητεία ποτέ, ἀλλὰ ὑπὸ  ̊Πνεύματος Ἁγίου φερόμενοι, ἐλάλησαν ἀπὸ  ̊Θεοῦ ἅγιοι ἄνθρωποι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 1, '¶Ἐγένοντο δὲ καὶ ψευδοπροφῆται ἐν τῷ λαῷ, ὡς καὶ ἐν ὑμῖν ἔσονται ψευδοδιδάσκαλοι, οἵτινες παρεισάξουσιν αἱρέσεις ἀπωλείας, καὶ τὸν ἀγοράσαντα αὐτοὺς Δεσπότην ἀρνούμενοι, ἐπάγοντες ἑαυτοῖς ταχινὴν ἀπώλειαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 2, 'Καὶ πολλοὶ ἐξακολουθήσουσιν αὐτῶν ταῖς ἀσελγείαις, διʼ οὓς ἡ ὁδὸς τῆς ἀληθείας βλασφημηθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 3, 'Καὶ ἐν πλεονεξίᾳ πλαστοῖς λόγοις ὑμᾶς ἐμπορεύσονται· οἷς τὸ κρίμα ἔκπαλαι οὐκ ἀργεῖ, καὶ ἡ ἀπώλεια αὐτῶν οὐ νυστάζει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 4, '¶Εἰ γὰρ ὁ  ̊Θεὸς ἀγγέλων ἁμαρτησάντων οὐκ ἐφείσατο, ἀλλὰ σειροῖς ζόφου ταρταρώσας, παρέδωκεν εἰς κρίσιν τηρουμένους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 5, 'καὶ ἀρχαίου κόσμου οὐκ ἐφείσατο, ἀλλὰ ὄγδοον, Νῶε, δικαιοσύνης κήρυκα ἐφύλαξεν, κατακλυσμὸν κόσμῳ ἀσεβῶν ἐπάξας,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 6, 'καὶ πόλεις Σοδόμων καὶ Γομόρρας τεφρώσας κατέκρινεν, ὑπόδειγμα μελλόντων ἀσεβεῖν τεθεικώς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 7, 'καὶ δίκαιον Λὼτ, καταπονούμενον ὑπὸ τῆς τῶν ἀθέσμων ἐν ἀσελγείᾳ ἀναστροφῆς ἐρρύσατο');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 8, '(βλέμματι γὰρ καὶ ἀκοῇ ὁ δίκαιος, ἐγκατοικῶν ἐν αὐτοῖς ἡμέραν ἐξ ἡμέρας, ψυχὴν δικαίαν ἀνόμοις ἔργοις ἐβασάνιζεν)·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 9, 'οἶδεν  ̊Κύριος εὐσεβεῖς ἐκ πειρασμοῦ ῥύεσθαι, ἀδίκους δὲ εἰς ἡμέραν κρίσεως κολαζομένους τηρεῖν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 10, 'μάλιστα δὲ τοὺς ὀπίσω σαρκὸς ἐν ἐπιθυμίᾳ μιασμοῦ πορευομένους, καὶ κυριότητος καταφρονοῦντας. ¶Τολμηταὶ αὐθάδεις, δόξας οὐ τρέμουσιν, βλασφημοῦντες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 11, 'ὅπου ἄγγελοι ἰσχύϊ καὶ δυνάμει μείζονες ὄντες, οὐ φέρουσιν κατʼ αὐτῶν παρὰ  ̊Κυρίῳ βλάσφημον κρίσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 12, 'Οὗτοι δέ ὡς ἄλογα ζῷα, γεγεννημένα φυσικὰ εἰς ἅλωσιν καὶ φθοράν, ἐν οἷς ἀγνοοῦσιν βλασφημοῦντες, ἐν τῇ φθορᾷ αὐτῶν καὶ φθαρήσονται,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 13, 'ἀδικούμενοι μισθὸν ἀδικίας, ἡδονὴν ἡγούμενοι τὴν ἐν ἡμέρᾳ τρυφήν, σπίλοι καὶ μῶμοι ἐντρυφῶντες ἐν ταῖς ἀπάταις αὐτῶν, συνευωχούμενοι ὑμῖν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 14, 'ὀφθαλμοὺς ἔχοντες μεστοὺς μοιχαλίδος, καὶ ἀκαταπαύστους ἁμαρτίας, δελεάζοντες ψυχὰς ἀστηρίκτους, καρδίαν γεγυμνασμένην πλεονεξίας ἔχοντες, κατάρας τέκνα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 15, 'καταλιπόντες εὐθεῖαν ὁδὸν, ἐπλανήθησαν ἐξακολουθήσαντες τῇ ὁδῷ τοῦ Βαλαὰμ τοῦ Βοσὸρ, ὃς μισθὸν ἀδικίας ἠγάπησεν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 16, 'ἔλεγξιν δὲ ἔσχεν ἰδίας παρανομίας, ὑποζύγιον ἄφωνον ἐν ἀνθρώπου φωνῇ φθεγξάμενον, ἐκώλυσεν τὴν τοῦ προφήτου παραφρονίαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 17, '¶Οὗτοί εἰσιν πηγαὶ ἄνυδροι, καὶ ὁμίχλαι ὑπὸ λαίλαπος ἐλαυνόμεναι, οἷς ὁ ζόφος τοῦ σκότους τετήρηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 18, 'Ὑπέρογκα γὰρ ματαιότητος φθεγγόμενοι, δελεάζουσιν ἐν ἐπιθυμίαις σαρκὸς ἀσελγείαις, τοὺς ὀλίγως ἀποφεύγοντας τοὺς ἐν πλάνῃ ἀναστρεφομένους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 19, 'ἐλευθερίαν αὐτοῖς ἐπαγγελλόμενοι, αὐτοὶ δοῦλοι ὑπάρχοντες τῆς φθορᾶς· ᾧ γάρ τις ἥττηται, τούτῳ δεδούλωται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 20, 'Εἰ γὰρ ἀποφυγόντες τὰ μιάσματα τοῦ κόσμου, ἐν ἐπιγνώσει τοῦ  ̊Κυρίου καὶ Σωτῆρος,  ̊Ἰησοῦ  ̊Χριστοῦ, τούτοις δὲ πάλιν ἐμπλακέντες ἡττῶνται, γέγονεν αὐτοῖς τὰ ἔσχατα χείρονα τῶν πρώτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 21, 'Κρεῖττον γὰρ ἦν αὐτοῖς, μὴ ἐπεγνωκέναι τὴν ὁδὸν τῆς δικαιοσύνης, ἢ ἐπιγνοῦσιν, ὑποστρέψαι ἐκ τῆς παραδοθείσης αὐτοῖς ἁγίας ἐντολῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 22, 'Συμβέβηκεν αὐτοῖς τὸ τῆς ἀληθοῦς παροιμίας: “Κύων ἐπιστρέψας ἐπὶ τὸ ἴδιον ἐξέραμα”, καί, “Ὗς λουσαμένη, εἰς κυλισμὸν βορβόρου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 1, '¶Ταύτην ἤδη, ἀγαπητοί, δευτέραν ὑμῖν γράφω ἐπιστολήν, ἐν αἷς διεγείρω ὑμῶν ἐν ὑπομνήσει τὴν εἰλικρινῆ διάνοιαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 2, 'μνησθῆναι τῶν προειρημένων ῥημάτων, ὑπὸ τῶν ἁγίων προφητῶν, καὶ τῆς τῶν ἀποστόλων ὑμῶν ἐντολῆς τοῦ  ̊Κυρίου καὶ Σωτῆρος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 3, 'Τοῦτο πρῶτον γινώσκοντες, ὅτι ἐλεύσονται ἐπʼ ἐσχάτων τῶν ἡμερῶν ἐν ἐμπαιγμονῇ ἐμπαῖκται, κατὰ τὰς ἰδίας ἐπιθυμίας αὐτῶν πορευόμενοι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 4, 'καὶ λέγοντες, “Ποῦ ἐστιν ἡ ἐπαγγελία τῆς παρουσίας αὐτοῦ; Ἀφʼ ἧς γὰρ οἱ πατέρες ἐκοιμήθησαν, πάντα οὕτως διαμένει ἀπʼ ἀρχῆς κτίσεως.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 5, 'Λανθάνει γὰρ αὐτοὺς τοῦτο θέλοντας, ὅτι οὐρανοὶ ἦσαν ἔκπαλαι, καὶ γῆ ἐξ ὕδατος καὶ διʼ ὕδατος συνεστῶσα τῷ τοῦ  ̊Θεοῦ λόγῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 6, 'διʼ ὧν ὁ τότε κόσμος ὕδατι κατακλυσθεὶς ἀπώλετο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 7, 'Οἱ δὲ νῦν οὐρανοὶ καὶ ἡ γῆ, τῷ αὐτῷ λόγῳ τεθησαυρισμένοι εἰσὶν, πυρὶ τηρούμενοι εἰς ἡμέραν κρίσεως καὶ ἀπωλείας τῶν ἀσεβῶν ἀνθρώπων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 8, '¶Ἓν δὲ τοῦτο μὴ λανθανέτω ὑμᾶς, ἀγαπητοί, ὅτι μία ἡμέρα παρὰ  ̊Κυρίῳ ὡς χίλια ἔτη, καὶ χίλια ἔτη ὡς ἡμέρα μία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 9, 'Οὐ βραδύνει  ̊Κύριος τῆς ἐπαγγελίας, ὥς τινες βραδύτητα ἡγοῦνται, ἀλλὰ μακροθυμεῖ εἰς ὑμᾶς, μὴ βουλόμενός τινας ἀπολέσθαι, ἀλλὰ πάντας εἰς μετάνοιαν χωρῆσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 10, 'Ἥξει δὲ ἡμέρα  ̊Κυρίου ὡς κλέπτης, ἐν ᾗ οἱ οὐρανοὶ ῥοιζηδὸν παρελεύσονται, στοιχεῖα δὲ καυσούμενα λυθήσεται, καὶ γῆ καὶ τὰ ἐν αὐτῇ ἔργα εὑρεθήσεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 11, '¶Τούτων οὕτως πάντων λυομένων, ποταποὺς δεῖ ὑπάρχειν ὑμᾶς ἐν ἁγίαις ἀναστροφαῖς καὶ εὐσεβείαις,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 12, 'προσδοκῶντας καὶ σπεύδοντας τὴν παρουσίαν τῆς τοῦ  ̊Θεοῦ ἡμέρας, διʼ ἣν οὐρανοὶ πυρούμενοι, λυθήσονται, καὶ στοιχεῖα καυσούμενα, τήκεται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 13, 'Καινοὺς δὲ οὐρανοὺς καὶ γῆν καινὴν, κατὰ τὸ ἐπάγγελμα αὐτοῦ προσδοκῶμεν, ἐν οἷς δικαιοσύνη κατοικεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 14, '¶Διό, ἀγαπητοί, ταῦτα προσδοκῶντες, σπουδάσατε ἄσπιλοι καὶ ἀμώμητοι αὐτῷ εὑρεθῆναι ἐν εἰρήνῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 15, 'Καὶ τὴν τοῦ  ̊Κυρίου ἡμῶν μακροθυμίαν, σωτηρίαν ἡγεῖσθε, καθὼς καὶ ὁ ἀγαπητὸς ἡμῶν ἀδελφὸς Παῦλος, κατὰ τὴν δοθεῖσαν αὐτῷ σοφίαν, ἔγραψεν ὑμῖν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 16, 'ὡς καὶ ἐν πάσαις ἐπιστολαῖς, λαλῶν ἐν αὐταῖς περὶ τούτων, ἐν αἷς ἐστιν δυσνόητά τινα, ἃ οἱ ἀμαθεῖς καὶ ἀστήρικτοι στρεβλοῦσιν ὡς καὶ τὰς λοιπὰς Γραφὰς, πρὸς τὴν ἰδίαν αὐτῶν ἀπώλειαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 17, 'Ὑμεῖς οὖν, ἀγαπητοί, προγινώσκοντες φυλάσσεσθε, ἵνα μὴ τῇ τῶν ἀθέσμων πλάνῃ συναπαχθέντες, ἐκπέσητε τοῦ ἰδίου στηριγμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 18, 'Αὐξάνετε δὲ ἐν χάριτι, καὶ γνώσει τοῦ  ̊Κυρίου ἡμῶν καὶ Σωτῆρος,  ̊Ἰησοῦ  ̊Χριστοῦ. Αὐτῷ ἡ δόξα καὶ νῦν καὶ εἰς ἡμέραν αἰῶνος. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 1, '¶Ὃ ἦν ἀπʼ ἀρχῆς, ὃ ἀκηκόαμεν, ὃ ἑωράκαμεν τοῖς ὀφθαλμοῖς ἡμῶν, ὃ ἐθεασάμεθα, καὶ αἱ χεῖρες ἡμῶν ἐψηλάφησαν, περὶ τοῦ λόγου τῆς ζωῆς–');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 2, 'καὶ ἡ ζωὴ ἐφανερώθη, καὶ ἑωράκαμεν, καὶ μαρτυροῦμεν, καὶ ἀπαγγέλλομεν ὑμῖν, τὴν ζωὴν τὴν αἰώνιον, ἥτις ἦν πρὸς τὸν Πατέρα, καὶ ἐφανερώθη ἡμῖν–');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 3, 'ὃ ἑωράκαμεν, καὶ ἀκηκόαμεν, ἀπαγγέλλομεν καὶ ὑμῖν, ἵνα καὶ ὑμεῖς κοινωνίαν ἔχητε μεθʼ ἡμῶν· καὶ ἡ κοινωνία δὲ ἡ ἡμετέρα μετὰ τοῦ Πατρὸς, καὶ μετὰ τοῦ Υἱοῦ αὐτοῦ,  ̊Ἰησοῦ  ̊Χριστοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 4, 'Καὶ ταῦτα γράφομεν ἡμεῖς, ἵνα ἡ χαρὰ ἡμῶν ᾖ πεπληρωμένη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 5, '¶Καὶ ἔστιν αὕτη ἡ ἀγγελία ἣν ἀκηκόαμεν ἀπʼ αὐτοῦ καὶ ἀναγγέλλομεν ὑμῖν, ὅτι ὁ  ̊Θεὸς φῶς ἐστιν, καὶ σκοτία ἐν αὐτῷ, οὐκ ἔστιν οὐδεμία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 6, 'Ἐὰν εἴπωμεν ὅτι κοινωνίαν ἔχομεν μετʼ αὐτοῦ, καὶ ἐν τῷ σκότει περιπατῶμεν, ψευδόμεθα καὶ οὐ ποιοῦμεν τὴν ἀλήθειαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 7, 'Ἐὰν δὲ ἐν τῷ φωτὶ περιπατῶμεν, ὡς αὐτός ἐστιν ἐν τῷ φωτί, κοινωνίαν ἔχομεν μετʼ ἀλλήλων, καὶ τὸ αἷμα  ̊Ἰησοῦ τοῦ Υἱοῦ αὐτοῦ, καθαρίζει ἡμᾶς ἀπὸ πάσης ἁμαρτίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 8, 'Ἐὰν εἴπωμεν ὅτι ἁμαρτίαν οὐκ ἔχομεν, ἑαυτοὺς πλανῶμεν καὶ ἡ ἀλήθεια οὐκ ἔστιν ἐν ἡμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 9, 'Ἐὰν ὁμολογῶμεν τὰς ἁμαρτίας ἡμῶν, πιστός ἐστιν καὶ δίκαιος, ἵνα ἀφῇ ἡμῖν τὰς ἁμαρτίας, καὶ καθαρίσῃ ἡμᾶς ἀπὸ πάσης ἀδικίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 10, 'Ἐὰν εἴπωμεν ὅτι οὐχ ἡμαρτήκαμεν, ψεύστην ποιοῦμεν αὐτὸν, καὶ ὁ λόγος αὐτοῦ οὐκ ἔστιν ἐν ἡμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 1, '¶Τεκνία μου, ταῦτα γράφω ὑμῖν, ἵνα μὴ ἁμάρτητε. Καὶ ἐάν τις ἁμάρτῃ, Παράκλητον ἔχομεν πρὸς τὸν Πατέρα,  ̊Ἰησοῦν  ̊Χριστὸν δίκαιον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 2, 'καὶ αὐτὸς ἱλασμός ἐστιν περὶ τῶν ἁμαρτιῶν ἡμῶν, οὐ περὶ τῶν ἡμετέρων δὲ μόνον, ἀλλὰ καὶ περὶ ὅλου τοῦ κόσμου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 3, '¶Καὶ ἐν τούτῳ γινώσκομεν ὅτι ἐγνώκαμεν αὐτόν, ἐὰν τὰς ἐντολὰς αὐτοῦ τηρῶμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 4, 'Ὁ λέγων, ὅτι “Ἔγνωκα αὐτὸν”, καὶ τὰς ἐντολὰς αὐτοῦ μὴ τηρῶν, ψεύστης ἐστίν, καὶ ἐν τούτῳ ἡ ἀλήθεια οὐκ ἔστιν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 5, 'ὃς δʼ ἂν τηρῇ αὐτοῦ τὸν λόγον, ἀληθῶς ἐν τούτῳ ἡ ἀγάπη τοῦ  ̊Θεοῦ τετελείωται. Ἐν τούτῳ γινώσκομεν ὅτι ἐν αὐτῷ ἐσμεν:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 6, 'ὁ λέγων ἐν αὐτῷ μένειν, ὀφείλει καθὼς ἐκεῖνος περιεπάτησεν, καὶ αὐτὸς περιπατεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 7, '¶Ἀγαπητοί, οὐκ ἐντολὴν καινὴν γράφω ὑμῖν, ἀλλʼ ἐντολὴν παλαιὰν, ἣν εἴχετε ἀπʼ ἀρχῆς. Ἡ ἐντολὴ ἡ παλαιά ἐστιν ὁ λόγος ὃν ἠκούσατε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 8, 'Πάλιν ἐντολὴν καινὴν γράφω ὑμῖν, ὅ ἐστιν ἀληθὲς ἐν αὐτῷ καὶ ἐν ὑμῖν, ὅτι ἡ σκοτία παράγεται, καὶ τὸ φῶς τὸ ἀληθινὸν ἤδη φαίνει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 9, 'Ὁ λέγων ἐν τῷ φωτὶ εἶναι, καὶ τὸν ἀδελφὸν αὐτοῦ μισῶν, ἐν τῇ σκοτίᾳ ἐστὶν ἕως ἄρτι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 10, 'Ὁ ἀγαπῶν τὸν ἀδελφὸν αὐτοῦ, ἐν τῷ φωτὶ μένει, καὶ σκάνδαλον ἐν αὐτῷ οὐκ ἔστιν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 11, 'Ὁ δὲ μισῶν τὸν ἀδελφὸν αὐτοῦ, ἐν τῇ σκοτίᾳ ἐστὶν, καὶ ἐν τῇ σκοτίᾳ περιπατεῖ, καὶ οὐκ οἶδεν ποῦ ὑπάγει, ὅτι ἡ σκοτία ἐτύφλωσεν τοὺς ὀφθαλμοὺς αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 12, '¶Γράφω ὑμῖν, τεκνία, ὅτι ἀφέωνται ὑμῖν αἱ ἁμαρτίαι, διὰ τὸ ὄνομα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 13, 'Γράφω ὑμῖν, πατέρες, ὅτι ἐγνώκατε τὸν ἀπʼ ἀρχῆς. Γράφω ὑμῖν, νεανίσκοι, ὅτι νενικήκατε τὸν πονηρόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 14, 'Ἔγραψα ὑμῖν, παιδία, ὅτι ἐγνώκατε τὸν Πατέρα. Ἔγραψα ὑμῖν, πατέρες, ὅτι ἐγνώκατε τὸν ἀπʼ ἀρχῆς. Ἔγραψα ὑμῖν, νεανίσκοι, ὅτι ἰσχυροί ἐστε, καὶ ὁ λόγος τοῦ  ̊Θεοῦ ἐν ὑμῖν μένει, καὶ νενικήκατε τὸν πονηρόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 15, '¶Μὴ ἀγαπᾶτε τὸν κόσμον, μηδὲ τὰ ἐν τῷ κόσμῳ. Ἐάν τις ἀγαπᾷ τὸν κόσμον, οὐκ ἔστιν ἡ ἀγάπη τοῦ Πατρὸς ἐν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 16, 'Ὅτι πᾶν τὸ ἐν τῷ κόσμῳ, ἡ ἐπιθυμία τῆς σαρκὸς, καὶ ἡ ἐπιθυμία τῶν ὀφθαλμῶν, καὶ ἡ ἀλαζονεία τοῦ βίου, οὐκ ἔστιν ἐκ τοῦ Πατρός, ἀλλʼ ἐκ τοῦ κόσμου ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 17, 'Καὶ ὁ κόσμος παράγεται, καὶ ἡ ἐπιθυμία αὐτοῦ, ὁ δὲ ποιῶν τὸ θέλημα τοῦ  ̊Θεοῦ, μένει εἰς τὸν αἰῶνα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 18, '¶Παιδία, ἐσχάτη ὥρα ἐστίν, καὶ καθὼς ἠκούσατε ὅτι ἀντίχριστος ἔρχεται, καὶ νῦν ἀντίχριστοι πολλοὶ γεγόνασιν, ὅθεν γινώσκομεν ὅτι ἐσχάτη ὥρα ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 19, 'Ἐξ ἡμῶν ἐξῆλθαν, ἀλλʼ οὐκ ἦσαν ἐξ ἡμῶν· εἰ γὰρ ἐξ ἡμῶν ἦσαν, μεμενήκεισαν ἂν μεθʼ ἡμῶν· ἀλλʼ ἵνα φανερωθῶσιν ὅτι οὐκ εἰσὶν πάντες ἐξ ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 20, 'Καὶ ὑμεῖς χρῖσμα ἔχετε ἀπὸ τοῦ Ἁγίου, καὶ οἴδατε πάντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 21, 'Οὐκ ἔγραψα ὑμῖν ὅτι οὐκ οἴδατε τὴν ἀλήθειαν, ἀλλʼ ὅτι οἴδατε αὐτήν, καὶ ὅτι πᾶν ψεῦδος ἐκ τῆς ἀληθείας οὐκ ἔστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 22, 'Τίς ἐστιν ὁ ψεύστης, εἰ μὴ ὁ ἀρνούμενος ὅτι  ̊Ἰησοῦς οὐκ ἔστιν ὁ  ̊Χριστός; Οὗτός ἐστιν ὁ ἀντίχριστος, ὁ ἀρνούμενος τὸν Πατέρα καὶ τὸν Υἱόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 23, 'Πᾶς ὁ ἀρνούμενος τὸν Υἱὸν, οὐδὲ τὸν Πατέρα ἔχει. Ὁ ὁμολογῶν τὸν Υἱὸν, καὶ τὸν Πατέρα ἔχει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 24, 'Ὑμεῖς ὃ ἠκούσατε ἀπʼ ἀρχῆς, ἐν ὑμῖν μενέτω. Ἐὰν ἐν ὑμῖν μείνῃ ὃ ἀπʼ ἀρχῆς ἠκούσατε, καὶ ὑμεῖς ἐν τῷ Υἱῷ καὶ ἐν τῷ Πατρὶ μενεῖτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 25, 'Καὶ αὕτη ἐστὶν ἡ ἐπαγγελία ἣν αὐτὸς ἐπηγγείλατο ἡμῖν– τὴν ζωὴν τὴν αἰώνιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 26, '¶Ταῦτα ἔγραψα ὑμῖν περὶ τῶν πλανώντων ὑμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 27, 'Καὶ ὑμεῖς, τὸ χρῖσμα ὃ ἐλάβετε ἀπʼ αὐτοῦ, μένει ἐν ὑμῖν, καὶ οὐ χρείαν ἔχετε ἵνα τις διδάσκῃ ὑμᾶς· ἀλλʼ ὡς τὸ αὐτοῦ χρῖσμα διδάσκει ὑμᾶς περὶ πάντων, καὶ ἀληθές ἐστιν καὶ οὐκ ἔστιν ψεῦδος, καὶ καθὼς ἐδίδαξεν ὑμᾶς, μένετε ἐν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 28, '¶Καὶ νῦν, τεκνία, μένετε ἐν αὐτῷ, ἵνα ἐὰν φανερωθῇ, σχῶμεν παρρησίαν, καὶ μὴ αἰσχυνθῶμεν ἀπʼ αὐτοῦ ἐν τῇ παρουσίᾳ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 29, 'Ἐὰν εἰδῆτε ὅτι δίκαιός ἐστιν, γινώσκετε ὅτι καὶ πᾶς ὁ ποιῶν τὴν δικαιοσύνην ἐξ αὐτοῦ γεγέννηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 1, 'Ἴδετε ποταπὴν ἀγάπην δέδωκεν ἡμῖν ὁ Πατὴρ, ἵνα τέκνα  ̊Θεοῦ κληθῶμεν, καὶ ἐσμέν. Διὰ τοῦτο, ὁ κόσμος οὐ γινώσκει ἡμᾶς, ὅτι οὐκ ἔγνω αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 2, 'Ἀγαπητοί, νῦν τέκνα  ̊Θεοῦ ἐσμεν, καὶ οὔπω ἐφανερώθη τί ἐσόμεθα. Οἴδαμεν ὅτι ἐὰν φανερωθῇ, ὅμοιοι αὐτῷ ἐσόμεθα, ὅτι ὀψόμεθα αὐτὸν καθώς ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 3, 'Καὶ πᾶς ὁ ἔχων τὴν ἐλπίδα ταύτην ἐπʼ αὐτῷ, ἁγνίζει ἑαυτὸν, καθὼς ἐκεῖνος ἁγνός ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 4, '¶Πᾶς ὁ ποιῶν τὴν ἁμαρτίαν, καὶ τὴν ἀνομίαν ποιεῖ, καὶ ἡ ἁμαρτία ἐστὶν ἡ ἀνομία.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 5, 'Καὶ οἴδατε ὅτι ἐκεῖνος ἐφανερώθη, ἵνα τὰς ἁμαρτίας ἄρῃ, καὶ ἁμαρτία ἐν αὐτῷ οὐκ ἔστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 6, 'Πᾶς ὁ ἐν αὐτῷ μένων οὐχ ἁμαρτάνει, πᾶς ὁ ἁμαρτάνων οὐχ ἑώρακεν αὐτὸν, οὐδὲ ἔγνωκεν αὐτόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 7, 'Τεκνία, μηδεὶς πλανάτω ὑμᾶς· ὁ ποιῶν τὴν δικαιοσύνην, δίκαιός ἐστιν, καθὼς ἐκεῖνος δίκαιός ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 8, 'Ὁ ποιῶν τὴν ἁμαρτίαν, ἐκ τοῦ διαβόλου ἐστίν, ὅτι ἀπʼ ἀρχῆς ὁ διάβολος ἁμαρτάνει. Εἰς τοῦτο ἐφανερώθη ὁ Υἱὸς τοῦ  ̊Θεοῦ, ἵνα λύσῃ τὰ ἔργα τοῦ διαβόλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 9, 'Πᾶς ὁ γεγεννημένος ἐκ τοῦ  ̊Θεοῦ, ἁμαρτίαν οὐ ποιεῖ, ὅτι σπέρμα αὐτοῦ ἐν αὐτῷ μένει, καὶ οὐ δύναται ἁμαρτάνειν, ὅτι ἐκ τοῦ  ̊Θεοῦ γεγέννηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 10, 'Ἐν τούτῳ φανερά ἐστιν τὰ τέκνα τοῦ  ̊Θεοῦ, καὶ τὰ τέκνα τοῦ διαβόλου: πᾶς ὁ μὴ ποιῶν δικαιοσύνην, οὐκ ἔστιν ἐκ τοῦ  ̊Θεοῦ, καὶ ὁ μὴ ἀγαπῶν τὸν ἀδελφὸν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 11, '¶Ὅτι αὕτη ἐστὶν ἡ ἀγγελία ἣν ἠκούσατε ἀπʼ ἀρχῆς, ἵνα ἀγαπῶμεν ἀλλήλους·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 12, 'οὐ καθὼς Κάϊν ἐκ τοῦ πονηροῦ ἦν, καὶ ἔσφαξεν τὸν ἀδελφὸν αὐτοῦ. Καὶ χάριν τίνος ἔσφαξεν αὐτόν; Ὅτι τὰ ἔργα αὐτοῦ πονηρὰ ἦν, τὰ δὲ τοῦ ἀδελφοῦ αὐτοῦ, δίκαια.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 13, 'Μὴ θαυμάζετε, ἀδελφοί, εἰ μισεῖ ὑμᾶς ὁ κόσμος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 14, 'Ἡμεῖς οἴδαμεν ὅτι μεταβεβήκαμεν ἐκ τοῦ θανάτου εἰς τὴν ζωήν, ὅτι ἀγαπῶμεν τοὺς ἀδελφούς. Ὁ μὴ ἀγαπῶν, μένει ἐν τῷ θανάτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 15, 'Πᾶς ὁ μισῶν τὸν ἀδελφὸν αὐτοῦ, ἀνθρωποκτόνος ἐστίν, καὶ οἴδατε ὅτι πᾶς ἀνθρωποκτόνος οὐκ ἔχει ζωὴν αἰώνιον ἐν ἑαυτῷ μένουσαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 16, 'Ἐν τούτῳ ἐγνώκαμεν τὴν ἀγάπην, ὅτι ἐκεῖνος ὑπὲρ ἡμῶν τὴν ψυχὴν αὐτοῦ ἔθηκεν· καὶ ἡμεῖς ὀφείλομεν ὑπὲρ τῶν ἀδελφῶν, τὰς ψυχὰς θεῖναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 17, 'Ὃς δʼ ἂν ἔχῃ τὸν βίον τοῦ κόσμου, καὶ θεωρῇ τὸν ἀδελφὸν αὐτοῦ χρείαν ἔχοντα, καὶ κλείσῃ τὰ σπλάγχνα αὐτοῦ ἀπʼ αὐτοῦ, πῶς ἡ ἀγάπη τοῦ  ̊Θεοῦ μένει ἐν αὐτῷ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 18, '¶Τεκνία, μὴ ἀγαπῶμεν λόγῳ, μηδὲ τῇ γλώσσῃ, ἀλλὰ ἐν ἔργῳ καὶ ἀληθείᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 19, 'ἐν τούτῳ γνωσόμεθα ὅτι ἐκ τῆς ἀληθείας ἐσμέν, καὶ ἔμπροσθεν αὐτοῦ πείσομεν τὰς καρδίας ἡμῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 20, 'ὅτι ἐὰν καταγινώσκῃ ἡμῶν ἡ καρδία, ὅτι μείζων ἐστὶν ὁ  ̊Θεὸς τῆς καρδίας ἡμῶν, καὶ γινώσκει πάντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 21, 'Ἀγαπητοί, ἐὰν ἡ καρδία μὴ καταγινώσκῃ, παρρησίαν ἔχομεν πρὸς τὸν  ̊Θεόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 22, 'καὶ ὃ ἐὰν αἰτῶμεν, λαμβάνομεν ἀπʼ αὐτοῦ, ὅτι τὰς ἐντολὰς αὐτοῦ τηροῦμεν, καὶ τὰ ἀρεστὰ ἐνώπιον αὐτοῦ ποιοῦμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 23, 'Καὶ αὕτη ἐστὶν ἡ ἐντολὴ αὐτοῦ, ἵνα πιστεύωμεν τῷ ὀνόματι τοῦ Υἱοῦ αὐτοῦ,  ̊Ἰησοῦ  ̊Χριστοῦ, καὶ ἀγαπῶμεν ἀλλήλους, καθὼς ἔδωκεν ἐντολὴν ἡμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 24, 'Καὶ ὁ τηρῶν τὰς ἐντολὰς αὐτοῦ, ἐν αὐτῷ μένει, καὶ αὐτὸς ἐν αὐτῷ. Καὶ ἐν τούτῳ γινώσκομεν ὅτι μένει ἐν ἡμῖν, ἐκ τοῦ  ̊Πνεύματος οὗ ἡμῖν ἔδωκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 1, '¶Ἀγαπητοί, μὴ παντὶ πνεύματι πιστεύετε, ἀλλὰ δοκιμάζετε τὰ πνεύματα, εἰ ἐκ τοῦ  ̊Θεοῦ ἐστιν, ὅτι πολλοὶ ψευδοπροφῆται ἐξεληλύθασιν εἰς τὸν κόσμον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 2, 'Ἐν τούτῳ γινώσκετε τὸ  ̊Πνεῦμα τοῦ  ̊Θεοῦ: πᾶν πνεῦμα ὃ ὁμολογεῖ  ̊Ἰησοῦν  ̊Χριστὸν ἐν σαρκὶ ἐληλυθότα, ἐκ τοῦ  ̊Θεοῦ ἐστιν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 3, 'καὶ πᾶν πνεῦμα ὃ μὴ ὁμολογεῖ τὸν  ̊Ἰησοῦν, ἐκ τοῦ  ̊Θεοῦ οὐκ ἔστιν. Καὶ τοῦτό ἐστιν τὸ τοῦ ἀντιχρίστου, ὃ ἀκηκόατε ὅτι ἔρχεται, καὶ νῦν ἐν τῷ κόσμῳ ἐστὶν ἤδη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 4, 'Ὑμεῖς ἐκ τοῦ  ̊Θεοῦ ἐστε, τεκνία, καὶ νενικήκατε αὐτούς, ὅτι μείζων ἐστὶν ὁ ἐν ὑμῖν, ἢ ὁ ἐν τῷ κόσμῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 5, 'Αὐτοὶ ἐκ τοῦ κόσμου εἰσίν· διὰ τοῦτο ἐκ τοῦ κόσμου λαλοῦσιν, καὶ ὁ κόσμος αὐτῶν ἀκούει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 6, 'Ἡμεῖς ἐκ τοῦ  ̊Θεοῦ ἐσμεν. Ὁ γινώσκων τὸν  ̊Θεὸν, ἀκούει ἡμῶν, ὃς οὐκ ἔστιν ἐκ τοῦ  ̊Θεοῦ, οὐκ ἀκούει ἡμῶν. Ἐκ τούτου γινώσκομεν τὸ πνεῦμα τῆς ἀληθείας καὶ τὸ πνεῦμα τῆς πλάνης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 7, '¶Ἀγαπητοί, ἀγαπῶμεν ἀλλήλους, ὅτι ἡ ἀγάπη ἐκ τοῦ  ̊Θεοῦ ἐστιν, καὶ πᾶς ὁ ἀγαπῶν, ἐκ τοῦ  ̊Θεοῦ γεγέννηται, καὶ γινώσκει τὸν  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 8, 'Ὁ μὴ ἀγαπῶν, οὐκ ἔγνω τὸν  ̊Θεόν, ὅτι ὁ  ̊Θεὸς ἀγάπη ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 9, 'Ἐν τούτῳ ἐφανερώθη ἡ ἀγάπη τοῦ  ̊Θεοῦ ἐν ἡμῖν, ὅτι τὸν Υἱὸν αὐτοῦ, τὸν μονογενῆ, ἀπέσταλκεν ὁ  ̊Θεὸς εἰς τὸν κόσμον, ἵνα ζήσωμεν διʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 10, 'Ἐν τούτῳ ἐστὶν ἡ ἀγάπη, οὐχ ὅτι ἡμεῖς ἠγαπήκαμεν τὸν  ̊Θεόν, ἀλλʼ ὅτι αὐτὸς ἠγάπησεν ἡμᾶς, καὶ ἀπέστειλεν τὸν Υἱὸν αὐτοῦ, ἱλασμὸν περὶ τῶν ἁμαρτιῶν ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 11, 'Ἀγαπητοί, εἰ οὕτως ὁ  ̊Θεὸς ἠγάπησεν ἡμᾶς, καὶ ἡμεῖς ὀφείλομεν ἀλλήλους ἀγαπᾶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 12, ' ̊Θεὸν οὐδεὶς πώποτε τεθέαται, ἐὰν ἀγαπῶμεν ἀλλήλους, ὁ  ̊Θεὸς ἐν ἡμῖν μένει, καὶ ἡ ἀγάπη αὐτοῦ τετελειωμένη ἐν ἡμῖν ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 13, '¶Ἐν τούτῳ γινώσκομεν, ὅτι ἐν αὐτῷ μένομεν, καὶ αὐτὸς ἐν ἡμῖν, ὅτι ἐκ τοῦ  ̊Πνεύματος αὐτοῦ δέδωκεν ἡμῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 14, 'Καὶ ἡμεῖς τεθεάμεθα καὶ μαρτυροῦμεν ὅτι ὁ Πατὴρ ἀπέσταλκεν τὸν Υἱὸν, Σωτῆρα τοῦ κόσμου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 15, 'Ὃς ἂν ὁμολογήσῃ ὅτι  ̊Ἰησοῦς ἐστιν ὁ Υἱὸς τοῦ  ̊Θεοῦ, ὁ  ̊Θεὸς ἐν αὐτῷ μένει, καὶ αὐτὸς ἐν τῷ  ̊Θεῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 16, 'Καὶ ἡμεῖς ἐγνώκαμεν καὶ πεπιστεύκαμεν τὴν ἀγάπην ἣν ἔχει ὁ  ̊Θεὸς ἐν ἡμῖν. ¶Ὁ  ̊Θεὸς ἀγάπη ἐστίν, καὶ ὁ μένων ἐν τῇ ἀγάπῃ, ἐν τῷ  ̊Θεῷ μένει, καὶ ὁ  ̊Θεὸς ἐν αὐτῷ μένει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 17, 'Ἐν τούτῳ τετελείωται ἡ ἀγάπη μεθʼ ἡμῶν, ἵνα παρρησίαν ἔχωμεν ἐν τῇ ἡμέρᾳ τῆς κρίσεως, ὅτι καθὼς ἐκεῖνός ἐστιν, καὶ ἡμεῖς ἐσμεν ἐν τῷ κόσμῳ τούτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 18, 'Φόβος οὐκ ἔστιν ἐν τῇ ἀγάπῃ, ἀλλʼ ἡ τελεία ἀγάπη ἔξω βάλλει τὸν φόβον, ὅτι ὁ φόβος κόλασιν ἔχει, ὁ δὲ φοβούμενος, οὐ τετελείωται ἐν τῇ ἀγάπῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 19, 'Ἡμεῖς ἀγαπῶμεν, ὅτι αὐτὸς πρῶτος ἠγάπησεν ἡμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 20, 'Ἐάν τις εἴπῃ, ὅτι “Ἀγαπῶ τὸν  ̊Θεόν”, καὶ τὸν ἀδελφὸν αὐτοῦ μισῇ, ψεύστης ἐστίν· ὁ γὰρ μὴ ἀγαπῶν τὸν ἀδελφὸν αὐτοῦ, ὃν ἑώρακεν, τὸν  ̊Θεὸν, ὃν οὐχ ἑώρακεν, οὐ δύναται ἀγαπᾶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 21, 'Καὶ ταύτην τὴν ἐντολὴν ἔχομεν ἀπʼ αὐτοῦ, ἵνα ὁ ἀγαπῶν τὸν  ̊Θεὸν, ἀγαπᾷ καὶ τὸν ἀδελφὸν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 1, '¶Πᾶς ὁ πιστεύων ὅτι  ̊Ἰησοῦς ἐστιν ὁ  ̊Χριστὸς, ἐκ τοῦ  ̊Θεοῦ γεγέννηται, καὶ πᾶς ὁ ἀγαπῶν τὸν γεννήσαντα, ἀγαπᾷ καὶ τὸν γεγεννημένον ἐξ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 2, 'Ἐν τούτῳ γινώσκομεν ὅτι ἀγαπῶμεν τὰ τέκνα τοῦ  ̊Θεοῦ: ὅταν τὸν  ̊Θεὸν ἀγαπῶμεν, καὶ τὰς ἐντολὰς αὐτοῦ τηρῶμεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 3, 'Αὕτη γάρ ἐστιν ἡ ἀγάπη τοῦ  ̊Θεοῦ, ἵνα τὰς ἐντολὰς αὐτοῦ τηρῶμεν, καὶ αἱ ἐντολαὶ αὐτοῦ βαρεῖαι οὐκ εἰσίν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 4, 'ὅτι πᾶν τὸ γεγεννημένον ἐκ τοῦ  ̊Θεοῦ, νικᾷ τὸν κόσμον. Καὶ αὕτη ἐστὶν ἡ νίκη ἡ νικήσασα τὸν κόσμον– ἡ πίστις ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 5, 'Τίς ἐστιν δὲ ὁ νικῶν τὸν κόσμον, εἰ μὴ ὁ πιστεύων ὅτι  ̊Ἰησοῦς ἐστιν ὁ Υἱὸς τοῦ  ̊Θεοῦ;');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 6, '¶Οὗτός ἐστιν ὁ ἐλθὼν διʼ ὕδατος καὶ αἵματος,  ̊Ἰησοῦς  ̊Χριστός· οὐκ ἐν τῷ ὕδατι μόνον, ἀλλʼ ἐν τῷ ὕδατι καὶ ἐν τῷ αἵματι. Καὶ τὸ  ̊Πνεῦμά ἐστιν τὸ μαρτυροῦν, ὅτι τὸ  ̊Πνεῦμά ἐστιν ἡ ἀλήθεια.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 7, 'Ὅτι τρεῖς εἰσιν οἱ μαρτυροῦντες:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 8, 'τὸ  ̊Πνεῦμα, καὶ τὸ ὕδωρ, καὶ τὸ αἷμα, καὶ οἱ τρεῖς εἰς τὸ ἕν εἰσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 9, 'Εἰ τὴν μαρτυρίαν τῶν ἀνθρώπων λαμβάνομεν, ἡ μαρτυρία τοῦ  ̊Θεοῦ μείζων ἐστίν, ὅτι αὕτη ἐστὶν ἡ μαρτυρία τοῦ  ̊Θεοῦ, ὅτι μεμαρτύρηκεν περὶ τοῦ Υἱοῦ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 10, 'Ὁ πιστεύων εἰς τὸν Υἱὸν τοῦ  ̊Θεοῦ, ἔχει τὴν μαρτυρίαν ἐν αὑτῷ· ὁ μὴ πιστεύων τῷ  ̊Θεῷ, ψεύστην πεποίηκεν αὐτόν, ὅτι οὐ πεπίστευκεν εἰς τὴν μαρτυρίαν ἣν μεμαρτύρηκεν ὁ  ̊Θεὸς περὶ τοῦ Υἱοῦ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 11, 'Καὶ αὕτη ἐστὶν ἡ μαρτυρία: ὅτι ζωὴν αἰώνιον ἔδωκεν ἡμῖν ὁ  ̊Θεὸς, καὶ αὕτη ἡ ζωὴ ἐν τῷ Υἱῷ αὐτοῦ ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 12, 'Ὁ ἔχων τὸν Υἱὸν, ἔχει τὴν ζωήν· ὁ μὴ ἔχων τὸν Υἱὸν τοῦ  ̊Θεοῦ, τὴν ζωὴν οὐκ ἔχει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 13, '¶Ταῦτα ἔγραψα ὑμῖν, ἵνα εἰδῆτε ὅτι ζωὴν ἔχετε αἰώνιον, τοῖς πιστεύουσιν εἰς τὸ ὄνομα τοῦ υἱοῦ τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 14, 'καὶ αὕτη ἐστὶν ἡ παρρησία ἣν ἔχομεν πρὸς αὐτόν: ὅτι ἐάν τι αἰτώμεθα κατὰ τὸ θέλημα αὐτοῦ, ἀκούει ἡμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 15, 'Καὶ ἐὰν οἴδαμεν ὅτι ἀκούει ἡμῶν, ὃ ἂν αἰτώμεθα, οἴδαμεν ὅτι ἔχομεν τὰ αἰτήματα ἃ ᾐτήκαμεν ἀπʼ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 16, 'Ἐάν τις ἴδῃ τὸν ἀδελφὸν αὐτοῦ ἁμαρτάνοντα ἁμαρτίαν μὴ πρὸς θάνατον, αἰτήσει καὶ δώσει αὐτῷ ζωήν, τοῖς ἁμαρτάνουσιν μὴ πρὸς θάνατον. Ἔστιν ἁμαρτία πρὸς θάνατον· οὐ περὶ ἐκείνης λέγω ἵνα ἐρωτήσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 17, 'Πᾶσα ἀδικία ἁμαρτία ἐστίν, καὶ ἔστιν ἁμαρτία οὐ πρὸς θάνατον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 18, '¶Οἴδαμεν ὅτι πᾶς ὁ γεγεννημένος ἐκ τοῦ  ̊Θεοῦ οὐχ ἁμαρτάνει, ἀλλʼ ὁ γεννηθεὶς ἐκ τοῦ  ̊Θεοῦ τηρεῖ αὐτόν καὶ ὁ πονηρὸς οὐχ ἅπτεται αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 19, 'Οἴδαμεν ὅτι ἐκ τοῦ  ̊Θεοῦ ἐσμεν, καὶ ὁ κόσμος ὅλος ἐν τῷ πονηρῷ κεῖται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 20, 'Οἴδαμεν δὲ ὅτι ὁ Υἱὸς τοῦ  ̊Θεοῦ ἥκει, καὶ δέδωκεν ἡμῖν διάνοιαν, ἵνα γινώσκομεν τὸν Ἀληθινόν· καὶ ἐσμὲν ἐν τῷ Ἀληθινῷ, ἐν τῷ Υἱῷ αὐτοῦ,  ̊Ἰησοῦ  ̊Χριστῷ. Οὗτός ἐστιν ὁ ἀληθινὸς  ̊Θεὸς καὶ ζωὴ αἰώνιος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 21, '¶Τεκνία, φυλάξατε ἑαυτὰ ἀπὸ τῶν εἰδώλων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 1, '¶Ὁ πρεσβύτερος· ἐκλεκτῇ κυρίᾳ καὶ τοῖς τέκνοις αὐτῆς, οὓς ἐγὼ ἀγαπῶ ἐν ἀληθείᾳ (καὶ οὐκ ἐγὼ μόνος, ἀλλὰ καὶ πάντες οἱ ἐγνωκότες τὴν ἀλήθειαν),');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 2, 'διὰ τὴν ἀλήθειαν τὴν μένουσαν ἐν ἡμῖν, καὶ μεθʼ ἡμῶν ἔσται εἰς τὸν αἰῶνα:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 3, 'ἔσται μεθʼ ἡμῶν χάρις, ἔλεος, εἰρήνη, παρὰ  ̊Θεοῦ Πατρός καὶ παρὰ  ̊Ἰησοῦ  ̊Χριστοῦ, τοῦ Υἱοῦ τοῦ Πατρός, ἐν ἀληθείᾳ καὶ ἀγάπῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 4, '¶Ἐχάρην λίαν ὅτι εὕρηκα ἐκ τῶν τέκνων σου περιπατοῦντας ἐν ἀληθείᾳ, καθὼς ἐντολὴν ἐλάβομεν παρὰ τοῦ Πατρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 5, 'Καὶ νῦν ἐρωτῶ σε, κυρία, οὐχ ὡς ἐντολὴν καινὴν γράφων σοι, ἀλλὰ ἣν εἴχαμεν ἀπʼ ἀρχῆς, ἵνα ἀγαπῶμεν ἀλλήλους.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 6, 'Καὶ αὕτη ἐστὶν ἡ ἀγάπη: ἵνα περιπατῶμεν κατὰ τὰς ἐντολὰς αὐτοῦ. Αὕτη ἡ ἐντολή ἐστιν, καθὼς ἠκούσατε ἀπʼ ἀρχῆς, ἵνα ἐν αὐτῇ περιπατῆτε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 7, 'Ὅτι πολλοὶ πλάνοι ἐξῆλθον εἰς τὸν κόσμον, οἱ μὴ ὁμολογοῦντες  ̊Ἰησοῦν  ̊Χριστὸν ἐρχόμενον ἐν σαρκί. Οὗτός ἐστιν ὁ πλάνος καὶ ὁ ἀντίχριστος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 8, 'Βλέπετε ἑαυτούς ἵνα μὴ ἀπολέσητε ἃ ειργάσασθαι, ἀλλὰ μισθὸν πλήρη ἀπολάβητε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 9, 'Πᾶς ὁ προάγων καὶ μὴ μένων ἐν τῇ διδαχῇ τοῦ  ̊Χριστοῦ,  ̊Θεὸν οὐκ ἔχει· ὁ μένων ἐν τῇ διδαχῇ, οὗτος καὶ τὸν Πατέρα καὶ τὸν Υἱὸν ἔχει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 10, 'Εἴ τις ἔρχεται πρὸς ὑμᾶς, καὶ ταύτην τὴν διδαχὴν οὐ φέρει, μὴ λαμβάνετε αὐτὸν εἰς οἰκίαν, καὶ χαίρειν αὐτῷ μὴ λέγετε·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 11, 'ὁ λέγων γὰρ αὐτῷ χαίρειν κοινωνεῖ τοῖς ἔργοις αὐτοῦ τοῖς πονηροῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 12, '¶Πολλὰ ἔχων ὑμῖν γράφειν, οὐκ ἐβουλήθην διὰ χάρτου καὶ μέλανος, ἀλλὰ ἐλπίζω γενέσθαι πρὸς ὑμᾶς, καὶ στόμα πρὸς στόμα λαλῆσαι, ἵνα ἡ χαρὰ ὑμῶν πεπληρωμένη ᾖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 13, 'Ἀσπάζεταί σε τὰ τέκνα τῆς ἀδελφῆς σου τῆς ἐκλεκτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 1, '¶Ὁ πρεσβύτερος· Γαΐῳ τῷ ἀγαπητῷ, ὃν ἐγὼ ἀγαπῶ ἐν ἀληθείᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 2, '¶Ἀγαπητέ, περὶ πάντων εὔχομαί σε εὐοδοῦσθαι καὶ ὑγιαίνειν, καθὼς εὐοδοῦταί σου ἡ ψυχή.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 3, 'Ἐχάρην γὰρ λίαν ἐρχομένων ἀδελφῶν καὶ μαρτυρούντων σου τῇ ἀληθείᾳ, καθὼς σὺ ἐν ἀληθείᾳ περιπατεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 4, 'Μειζοτέραν τούτων οὐκ ἔχω χαράν, ἵνα ἀκούω τὰ ἐμὰ τέκνα ἐν τῇ ἀληθείᾳ περιπατοῦντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 5, '¶Ἀγαπητέ, πιστὸν ποιεῖς ὃ, ἐὰν ἐργάσῃ εἰς τοὺς ἀδελφοὺς καὶ τοῦτο ξένους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 6, 'οἳ ἐμαρτύρησάν σου τῇ ἀγάπῃ ἐνώπιον ἐκκλησίας, οὓς καλῶς ποιήσεις, προπέμψας ἀξίως τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 7, 'Ὑπὲρ γὰρ τοῦ ὀνόματος ἐξῆλθαν, μηδὲν λαμβάνοντες ἀπὸ τῶν ἐθνικῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 8, 'Ἡμεῖς οὖν ὀφείλομεν ὑπολαμβάνειν τοὺς τοιούτους, ἵνα συνεργοὶ γινώμεθα τῇ ἀληθείᾳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 9, '¶Ἔγραψά τι τῇ ἐκκλησίᾳ, ἀλλʼ ὁ φιλοπρωτεύων αὐτῶν, Διοτρέφης, οὐκ ἐπιδέχεται ἡμᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 10, 'Διὰ τοῦτο, ἐὰν ἔλθω, ὑπομνήσω αὐτοῦ τὰ ἔργα, ἃ ποιεῖ, λόγοις πονηροῖς φλυαρῶν ἡμᾶς, καὶ μὴ ἀρκούμενος ἐπὶ τούτοις, οὔτε αὐτὸς ἐπιδέχεται τοὺς ἀδελφοὺς, καὶ τοὺς βουλομένους κωλύει, καὶ ἐκ τῆς ἐκκλησίας ἐκβάλλει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 11, '¶Ἀγαπητέ, μὴ μιμοῦ τὸ κακὸν, ἀλλὰ τὸ ἀγαθόν. Ὁ ἀγαθοποιῶν ἐκ τοῦ  ̊Θεοῦ ἐστιν, ὁ κακοποιῶν οὐχ ἑώρακεν τὸν  ̊Θεόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 12, 'Δημητρίῳ μεμαρτύρηται ὑπὸ πάντων, καὶ ὑπὸ αὐτῆς τῆς ἀληθείας· καὶ ἡμεῖς δὲ μαρτυροῦμεν, καὶ οἶδας ὅτι ἡ μαρτυρία ἡμῶν ἀληθής ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 13, '¶Πολλὰ εἶχον γράψαι σοι, ἀλλʼ οὐ θέλω διὰ μέλανος καὶ καλάμου σοι γράφειν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 14, 'ἐλπίζω δὲ εὐθέως σε ἰδεῖν, καὶ στόμα πρὸς στόμα λαλήσομεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 15, '¶Εἰρήνη σοι. Ἀσπάζονταί σε οἱ φίλοι. Ἀσπάζου τοὺς φίλους κατʼ ὄνομα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 1, '¶Ἰούδας,  ̊Ἰησοῦ  ̊Χριστοῦ δοῦλος, ἀδελφὸς δὲ Ἰακώβου, τοῖς ἐν  ̊Θεῷ Πατρὶ ἠγαπημένοις, καὶ  ̊Ἰησοῦ  ̊Χριστῷ τετηρημένοις κλητοῖς:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 2, 'ἔλεος ὑμῖν, καὶ εἰρήνη, καὶ ἀγάπη πληθυνθείη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 3, '¶Ἀγαπητοί, πᾶσαν σπουδὴν ποιούμενος γράφειν ὑμῖν περὶ τῆς κοινῆς ἡμῶν σωτηρίας, ἀνάγκην ἔσχον γράψαι ὑμῖν, παρακαλῶν ἐπαγωνίζεσθαι τῇ ἅπαξ παραδοθείσῃ τοῖς ἁγίοις πίστει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 4, 'Παρεισέδυσαν γάρ τινες ἄνθρωποι οἱ πάλαι προγεγραμμένοι εἰς τοῦτο τὸ κρίμα, ἀσεβεῖς, τὴν τοῦ  ̊Θεοῦ ἡμῶν χάριτα μετατιθέντες εἰς ἀσέλγειαν, καὶ τὸν μόνον Δεσπότην καὶ  ̊Κύριον ἡμῶν,  ̊Ἰησοῦν  ̊Χριστὸν, ἀρνούμενοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 5, '¶Ὑπομνῆσαι δὲ ὑμᾶς βούλομαι, εἰδότας ὑμᾶς ἅπαξ πάντα, ὅτι  ̊Ἰησοῦς λαὸν ἐκ γῆς Αἰγύπτου σώσας, τὸ δεύτερον τοὺς μὴ πιστεύσαντας ἀπώλεσεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 6, 'Ἀγγέλους τε τοὺς μὴ τηρήσαντας τὴν ἑαυτῶν ἀρχὴν, ἀλλὰ ἀπολιπόντας τὸ ἴδιον οἰκητήριον, εἰς κρίσιν μεγάλης ἡμέρας, δεσμοῖς ἀϊδίοις ὑπὸ ζόφον τετήρηκεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 7, 'Ὡς Σόδομα καὶ Γόμορρα, καὶ αἱ περὶ αὐτὰς πόλεις, τὸν ὅμοιον τρόπον τούτοις ἐκπορνεύσασαι, καὶ ἀπελθοῦσαι ὀπίσω σαρκὸς ἑτέρας, πρόκεινται δεῖγμα πυρὸς αἰωνίου δίκην ὑπέχουσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 8, '¶Ὁμοίως μέντοι καὶ οὗτοι ἐνυπνιαζόμενοι, σάρκα μὲν μιαίνουσιν, κυριότητα δὲ ἀθετοῦσιν, δόξας δὲ βλασφημοῦσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 9, 'Ὁ δὲ Μιχαὴλ ὁ ἀρχάγγελος, ὅτε τῷ διαβόλῳ διακρινόμενος, διελέγετο περὶ τοῦ Μωϋσέως σώματος, οὐκ ἐτόλμησεν κρίσιν ἐπενεγκεῖν βλασφημίας, ἀλλὰ εἶπεν, “Ἐπιτιμήσαι σοι  ̊Κύριος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 10, 'Οὗτοι δὲ ὅσα μὲν οὐκ οἴδασιν βλασφημοῦσιν, ὅσα δὲ φυσικῶς ὡς τὰ ἄλογα ζῷα ἐπίστανται, ἐν τούτοις φθείρονται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 11, 'Οὐαὶ αὐτοῖς! Ὅτι τῇ ὁδῷ τοῦ Κάϊν ἐπορεύθησαν, καὶ τῇ πλάνῃ τοῦ Βαλαὰμ μισθοῦ ἐξεχύθησαν, καὶ τῇ ἀντιλογίᾳ τοῦ Κόρε ἀπώλοντο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 12, 'Οὗτοί εἰσιν οἱ ἐν ταῖς ἀγάπαις ὑμῶν, σπιλάδες συνευωχούμενοι ἀφόβως, ἑαυτοὺς ποιμαίνοντες, νεφέλαι ἄνυδροι ὑπὸ ἀνέμων παραφερόμεναι, δένδρα φθινοπωρινὰ ἄκαρπα δὶς ἀποθανόντα ἐκριζωθέντα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 13, 'κύματα ἄγρια θαλάσσης ἐπαφρίζοντα τὰς ἑαυτῶν αἰσχύνας, ἀστέρες πλανῆται, οἷς ὁ ζόφος τοῦ σκότους εἰς αἰῶνα τετήρηται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 14, 'Ἐπροφήτευσεν δὲ καὶ τούτοις ἕβδομος ἀπὸ Ἀδὰμ, Ἑνὼχ, λέγων, “Ἰδοὺ, ἦλθεν  ̊Κύριος ἐν ἁγίαις μυριάσιν αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 15, 'ποιῆσαι κρίσιν κατὰ πάντων, καὶ ἐλέγξαι πάντας τοὺς ἀσεβεῖς περὶ πάντων τῶν ἔργων ἀσεβείας αὐτῶν, ὧν ἠσέβησαν, καὶ περὶ πάντων τῶν σκληρῶν, ὧν ἐλάλησαν κατʼ αὐτοῦ ἁμαρτωλοὶ ἀσεβεῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 16, 'Οὗτοί εἰσιν γογγυσταί μεμψίμοιροι, κατὰ τὰς ἐπιθυμίας αὐτῶν πορευόμενοι, καὶ τὸ στόμα αὐτῶν λαλεῖ ὑπέρογκα, θαυμάζοντες πρόσωπα ὠφελείας χάριν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 17, '¶Ὑμεῖς δέ, ἀγαπητοί, μνήσθητε τῶν ῥημάτων τῶν προειρημένων ὑπὸ τῶν ἀποστόλων τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 18, 'ὅτι ἔλεγον ὑμῖν, “Ἐπʼ ἐσχάτου χρόνου ἔσονται ἐμπαῖκται κατὰ τὰς ἑαυτῶν ἐπιθυμίας πορευόμενοι τῶν ἀσεβειῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 19, 'Οὗτοί εἰσιν οἱ ἀποδιορίζοντες, ψυχικοί,  ̊Πνεῦμα μὴ ἔχοντες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 20, 'Ὑμεῖς δέ, ἀγαπητοί, ἐποικοδομοῦντες ἑαυτοὺς τῇ ἁγιωτάτῃ ὑμῶν πίστει, ἐν  ̊Πνεύματι Ἁγίῳ προσευχόμενοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 21, 'Ἑαυτοὺς ἐν ἀγάπῃ  ̊Θεοῦ τηρήσατε, προσδεχόμενοι τὸ ἔλεος τοῦ  ̊Κυρίου ἡμῶν,  ̊Ἰησοῦ  ̊Χριστοῦ, εἰς ζωὴν αἰώνιον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 22, 'Καὶ οὓς μὲν ἐλεᾶτε διακρινομένους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 23, 'οὓς δὲ σῴζετε ἐκ πυρὸς ἁρπάζοντες, οὓς δὲ ἐλεᾶτε ἐν φόβῳ, μισοῦντες καὶ τὸν ἀπὸ τῆς σαρκὸς ἐσπιλωμένον χιτῶνα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 24, '¶Τῷ δὲ δυναμένῳ φυλάξαι ὑμᾶς ἀπταίστους, καὶ στῆσαι κατενώπιον τῆς δόξης αὐτοῦ ἀμώμους ἐν ἀγαλλιάσει,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 25, 'μόνῳ  ̊Θεῷ Σωτῆρι ἡμῶν, διὰ  ̊Ἰησοῦ  ̊Χριστοῦ τοῦ  ̊Κυρίου ἡμῶν, δόξα, μεγαλωσύνη, κράτος, καὶ ἐξουσία, πρὸ παντὸς τοῦ αἰῶνος, καὶ νῦν, καὶ εἰς πάντας τοὺς αἰῶνας. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 1, '¶Ἀποκάλυψις  ̊Ἰησοῦ  ̊Χριστοῦ, ἣν ἔδωκεν αὐτῷ ὁ  ̊Θεὸς, δεῖξαι τοῖς δούλοις αὐτοῦ, ἃ δεῖ γενέσθαι ἐν τάχει, καὶ ἐσήμανεν, ἀποστείλας διὰ τοῦ ἀγγέλου αὐτοῦ τῷ δούλῳ αὐτοῦ, Ἰωάννῃ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 2, 'ὃς ἐμαρτύρησεν τὸν λόγον τοῦ  ̊Θεοῦ, καὶ τὴν μαρτυρίαν  ̊Ἰησοῦ  ̊Χριστοῦ, ὅσα εἶδεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 3, 'Μακάριος ὁ ἀναγινώσκων καὶ οἱ ἀκούοντες τοὺς λόγους τῆς προφητείας, καὶ τηροῦντες τὰ ἐν αὐτῇ γεγραμμένα, ὁ γὰρ καιρὸς ἐγγύς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 4, '¶Ἰωάννης ταῖς ἑπτὰ ἐκκλησίαις ταῖς ἐν τῇ Ἀσίᾳ: χάρις ὑμῖν καὶ εἰρήνη, ἀπὸ ὁ ὢν, καὶ ὁ ἦν, καὶ ὁ ἐρχόμενος, καὶ ἀπὸ τῶν ἑπτὰ πνευμάτων, ἃ ἐνώπιον τοῦ θρόνου αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 5, 'καὶ ἀπὸ  ̊Ἰησοῦ  ̊Χριστοῦ, ὁ μάρτυς ὁ πιστός, ὁ πρωτότοκος τῶν νεκρῶν, καὶ ὁ ἄρχων τῶν βασιλέων τῆς γῆς. ¶Τῷ ἀγαπῶντι ἡμᾶς, καὶ λύσαντι ἡμᾶς ἐκ τῶν ἁμαρτιῶν ἡμῶν ἐν τῷ αἵματι αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 6, 'καὶ ἐποίησεν ἡμᾶς βασιλείαν, ἱερεῖς τῷ  ̊Θεῷ καὶ Πατρὶ αὐτοῦ– αὐτῷ ἡ δόξα καὶ τὸ κράτος εἰς τοὺς αἰῶνας. Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 7, '¶“Ἰδοὺ, ἔρχεται μετὰ τῶν νεφελῶν”, καὶ ὄψεται αὐτὸν πᾶς ὀφθαλμὸς, καὶ οἵτινες αὐτὸν ἐξεκέντησαν, καὶ κόψονται ἐπʼ αὐτὸν πᾶσαι αἱ φυλαὶ τῆς γῆς. Ναί! Ἀμήν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 8, '¶“Ἐγώ εἰμι τὸ Ἄλφα καὶ τὸ Ὦ”, λέγει  ̊Κύριος, ὁ  ̊Θεός, “ὁ ὢν, καὶ ὁ ἦν, καὶ ὁ ἐρχόμενος, ὁ Παντοκράτωρ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 9, '¶Ἐγὼ Ἰωάννης, ὁ ἀδελφὸς ὑμῶν, καὶ συγκοινωνὸς ἐν τῇ θλίψει, καὶ βασιλείᾳ, καὶ ὑπομονῇ, ἐν  ̊Ἰησοῦ, ἐγενόμην ἐν τῇ νήσῳ τῇ καλουμένῃ Πάτμῳ, διὰ τὸν λόγον τοῦ  ̊Θεοῦ καὶ τὴν μαρτυρίαν  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 10, 'Ἐγενόμην ἐν  ̊Πνεύματι ἐν τῇ Κυριακῇ ἡμέρᾳ, καὶ ἤκουσα ὀπίσω μου φωνὴν μεγάλην ὡς σάλπιγγος');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 11, 'λεγούσης, “Ὃ βλέπεις, γράψον εἰς βιβλίον, καὶ πέμψον ταῖς ἑπτὰ ἐκκλησίαις: εἰς Ἔφεσον, καὶ εἰς Σμύρναν, καὶ εἰς Πέργαμον, καὶ εἰς Θυάτειρα, καὶ εἰς Σάρδεις, καὶ εἰς Φιλαδέλφειαν, καὶ εἰς Λαοδίκειαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 12, '¶Καὶ ἐπέστρεψα βλέπειν τὴν φωνὴν ἥτις ἐλάλει μετʼ ἐμοῦ. Καὶ ἐπιστρέψας, εἶδον ἑπτὰ λυχνίας χρυσᾶς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 13, 'καὶ ἐν μέσῳ τῶν λυχνιῶν, “ὅμοιον Ὑιῷ Ἀνθρώπου”, ἐνδεδυμένον ποδήρη, καὶ περιεζωσμένον πρὸς τοῖς μαστοῖς ζώνην χρυσᾶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 14, 'Ἡ δὲ κεφαλὴ αὐτοῦ καὶ αἱ τρίχες λευκαὶ, ὡς ἔριον λευκόν ὡς χιών, καὶ οἱ ὀφθαλμοὶ αὐτοῦ ὡς φλὸξ πυρός,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 15, 'καὶ οἱ πόδες αὐτοῦ ὅμοιοι χαλκολιβάνῳ ὡς ἐν καμίνῳ πεπυρωμένης, καὶ ἡ φωνὴ αὐτοῦ ὡς φωνὴ ὑδάτων πολλῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 16, 'καὶ ἔχων ἐν τῇ δεξιᾷ χειρὶ αὐτοῦ ἀστέρας ἑπτά, καὶ ἐκ τοῦ στόματος αὐτοῦ ῥομφαία δίστομος ὀξεῖα ἐκπορευομένη, καὶ ἡ ὄψις αὐτοῦ ὡς ὁ ἥλιος φαίνει ἐν τῇ δυνάμει αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 17, '¶Καὶ ὅτε εἶδον αὐτόν, ἔπεσα πρὸς τοὺς πόδας αὐτοῦ, ὡς νεκρός. Καὶ ἔθηκεν τὴν δεξιὰν αὐτοῦ ἐπʼ ἐμὲ λέγων, “Μὴ φοβοῦ· ἐγώ εἰμι ὁ πρῶτος καὶ ὁ ἔσχατος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 18, 'καὶ ὁ ζῶν καὶ ἐγενόμην νεκρὸς, καὶ ἰδοὺ, ζῶν εἰμι εἰς τοὺς αἰῶνας τῶν αἰώνων, καὶ ἔχω τὰς κλεῖς τοῦ θανάτου καὶ τοῦ ἍΙδου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 19, 'Γράψον οὖν ἃ εἶδες, καὶ ἃ εἰσὶν, καὶ ἃ μέλλει γενέσθαι μετὰ ταῦτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 1, 20, 'Τὸ μυστήριον τῶν ἑπτὰ ἀστέρων, οὓς εἶδες ἐπὶ τῆς δεξιᾶς μου, καὶ τὰς ἑπτὰ λυχνίας τὰς χρυσᾶς: οἱ ἑπτὰ ἀστέρες, ἄγγελοι τῶν ἑπτὰ ἐκκλησιῶν εἰσίν, καὶ αἱ λυχνίαι ἑπτὰ, ἑπτὰ ἐκκλησίαι εἰσίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 1, '¶Τῷ ἀγγέλῳ τῷ ἐν Ἐφέσῳ ἐκκλησίας γράψον: ‘Τάδε λέγει ὁ κρατῶν τοὺς ἑπτὰ ἀστέρας ἐν τῇ δεξιᾷ αὐτοῦ, ὁ περιπατῶν ἐν μέσῳ τῶν ἑπτὰ λυχνιῶν τῶν χρυσέων:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 2, '“Οἶδα τὰ ἔργα σου, καὶ τὸν κόπον καὶ τὴν ὑπομονήν σου, καὶ ὅτι οὐ δύνῃ βαστάσαι κακούς, καὶ ἐπείρασας τοὺς λέγοντας ἑαυτοὺς ἀποστόλους, καὶ οὐκ εἰσίν, καὶ εὗρες αὐτοὺς ψευδεῖς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 3, 'καὶ ὑπομονὴν ἔχεις, καὶ ἐβάστασας διὰ τὸ ὄνομά μου, καὶ οὐ κεκοπίακες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 4, 'Ἀλλʼ ἔχω κατὰ σοῦ ὅτι τὴν ἀγάπην σου τὴν πρώτην ἀφῆκες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 5, 'Μνημόνευε οὖν πόθεν πέπτωκας καὶ μετανόησον, καὶ τὰ πρῶτα ἔργα ποίησον. Εἰ δὲ μή, ἔρχομαί σοι καὶ κινήσω τὴν λυχνίαν σου ἐκ τοῦ τόπου αὐτῆς, ἐὰν μὴ μετανοήσῃς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 6, 'Ἀλλὰ τοῦτο ἔχεις, ὅτι μισεῖς τὰ ἔργα τῶν Νικολαϊτῶν, ἃ κἀγὼ μισῶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 7, 'Ὁ ἔχων οὖς, ἀκουσάτω τί τὸ  ̊Πνεῦμα λέγει ταῖς ἐκκλησίαις. Τῷ νικῶντι, δώσω αὐτῷ φαγεῖν ἐκ τοῦ ξύλου τῆς ζωῆς, ὅ ἐστιν ἐν τῷ Παραδείσῳ τοῦ  ̊Θεοῦ.”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 8, '¶Καὶ τῷ ἀγγέλῳ τῆς ἐν Σμύρνῃ ἐκκλησίας γράψον: ‘Τάδε λέγει ὁ πρῶτος καὶ ὁ ἔσχατος, ὃς ἐγένετο νεκρὸς καὶ ἔζησεν:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 9, '“Οἶδά σου τὴν θλῖψιν καὶ τὴν πτωχείαν (ἀλλὰ πλούσιος εἶ), καὶ τὴν βλασφημίαν ἐκ τῶν λεγόντων Ἰουδαίους εἶναι ἑαυτούς, καὶ οὐκ εἰσίν, ἀλλὰ συναγωγὴ τοῦ Σατανᾶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 10, 'Μὴ φοβοῦ ἃ μέλλεις πάσχειν. Ἰδοὺ, μέλλει βάλλειν ὁ διάβολος ἐξ ὑμῶν εἰς φυλακὴν, ἵνα πειρασθῆτε, καὶ ἕξετε θλῖψιν ἡμερῶν δέκα. Γίνου πιστὸς ἄχρι θανάτου, καὶ δώσω σοι τὸν στέφανον τῆς ζωῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 11, 'Ὁ ἔχων οὖς, ἀκουσάτω τί τὸ  ̊Πνεῦμα λέγει ταῖς ἐκκλησίαις. Ὁ νικῶν οὐ μὴ ἀδικηθῇ ἐκ τοῦ θανάτου τοῦ δευτέρου.”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 12, '¶Καὶ τῷ ἀγγέλῳ τῆς ἐν Περγάμῳ ἐκκλησίας γράψον: ‘Τάδε λέγει ὁ ἔχων τὴν ῥομφαίαν τὴν δίστομον τὴν ὀξεῖαν:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 13, '“Οἶδα ποῦ κατοικεῖς, ὅπου ὁ θρόνος τοῦ Σατανᾶ, καὶ κρατεῖς τὸ ὄνομά μου, καὶ οὐκ ἠρνήσω τὴν πίστιν μου, καὶ ἐν ταῖς ἡμέραις Ἀντιπᾶς, ὁ μάρτυς μου ὁ πιστός μου, ὃς ἀπεκτάνθη παρʼ ὑμῖν, ὅπου ὁ Σατανᾶς κατοικεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 14, 'Ἀλλʼ ἔχω κατὰ σοῦ ὀλίγα, ὅτι ἔχεις ἐκεῖ κρατοῦντας τὴν διδαχὴν Βαλαάμ, ὃς ἐδίδασκεν τῷ Βαλὰκ βαλεῖν σκάνδαλον ἐνώπιον τῶν υἱῶν Ἰσραήλ, φαγεῖν εἰδωλόθυτα καὶ πορνεῦσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 15, 'Οὕτως ἔχεις καὶ σὺ, κρατοῦντας τὴν διδαχὴν Νικολαϊτῶν ὁμοίως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 16, 'Μετανόησον οὖν! Εἰ δὲ μή, ἔρχομαί σοι ταχύ, καὶ πολεμήσω μετʼ αὐτῶν ἐν τῇ ῥομφαίᾳ τοῦ στόματός μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 17, 'Ὁ ἔχων οὖς, ἀκουσάτω τί τὸ  ̊Πνεῦμα λέγει ταῖς ἐκκλησίαις. Τῷ νικῶντι, δώσω αὐτῷ τοῦ μάννα τοῦ κεκρυμμένου, καὶ δώσω αὐτῷ ψῆφον λευκήν, καὶ ἐπὶ τὴν ψῆφον ὄνομα καινὸν γεγραμμένον, ὃ οὐδεὶς οἶδεν, εἰ μὴ ὁ λαμβάνων.”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 18, '¶Καὶ τῷ ἀγγέλῳ τῆς ἐν Θυατείροις ἐκκλησίας γράψον: ‘Τάδε λέγει ὁ Υἱὸς τοῦ  ̊Θεοῦ, ὁ ἔχων τοὺς ὀφθαλμοὺς αὐτοῦ ὡς φλόγα πυρός, καὶ οἱ πόδες αὐτοῦ ὅμοιοι χαλκολιβάνῳ:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 19, '“Οἶδά σου τὰ ἔργα, καὶ τὴν ἀγάπην, καὶ τὴν πίστιν, καὶ τὴν διακονίαν, καὶ τὴν ὑπομονήν σου, καὶ τὰ ἔργα σου, τὰ ἔσχατα πλείονα τῶν πρώτων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 20, 'Ἀλλʼ ἔχω κατὰ σοῦ ὅτι ἀφεῖς τὴν γυναῖκα Ἰεζάβελ, ἡ λέγουσα ἑαυτὴν προφῆτιν, καὶ διδάσκει καὶ πλανᾷ τοὺς ἐμοὺς δούλους πορνεῦσαι, καὶ φαγεῖν εἰδωλόθυτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 21, 'Καὶ ἔδωκα αὐτῇ χρόνον, ἵνα μετανοήσῃ, καὶ οὐ ἤθελησεν μετανοῆσαι ἐκ τῆς πορνείας αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 22, 'ἰδοὺ, βάλλω αὐτὴν εἰς κλίνην, καὶ τοὺς μοιχεύοντας μετʼ αὐτῆς εἰς θλῖψιν μεγάλην, ἐὰν μὴ μετανοήσουσιν ἐκ τῶν ἔργων αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 23, 'Καὶ τὰ τέκνα αὐτῆς ἀποκτενῶ ἐν θανάτῳ· καὶ γνώσονται πᾶσαι αἱ ἐκκλησίαι ὅτι ἐγώ εἰμι ὁ ἐραυνῶν νεφροὺς καὶ καρδίας, καὶ δώσω ὑμῖν ἑκάστῳ κατὰ τὰ ἔργα ὑμῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 24, 'Ὑμῖν δὲ λέγω τοῖς λοιποῖς τοῖς ἐν Θυατείροις, ὅσοι οὐκ ἔχουσιν τὴν διδαχὴν ταύτην, οἵτινες οὐκ ἔγνωσαν τὰ βαθέα τοῦ Σατανᾶ, ὡς λέγουσιν, οὐ βάλλω ἐφʼ ὑμᾶς ἄλλο βάρος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 25, 'Πλὴν ὃ ἔχετε, κρατήσατε ἄχρι οὗ ἂν ἥξω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 26, 'Καὶ ὁ νικῶν καὶ ὁ τηρῶν ἄχρι τέλους τὰ ἔργα μου, ‘δώσω αὐτῷ ἐξουσίαν ἐπὶ τῶν ἐθνῶν...');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 27, 'καὶ ποιμανεῖ αὐτοὺς ἐν ῥάβδῳ σιδηρᾷ, ὡς τὰ σκεύη τὰ κεραμικὰ συντρίβεται’,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 28, 'ὡς κἀγὼ εἴληφα παρὰ τοῦ πατρός μου, καὶ δώσω αὐτῷ τὸν ἀστέρα τὸν πρωϊνόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 2, 29, 'Ὁ ἔχων οὖς, ἀκουσάτω τί τὸ  ̊Πνεῦμα λέγει ταῖς ἐκκλησίαις.”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 1, '¶Καὶ τῷ ἀγγέλῳ τῆς ἐν Σάρδεσιν ἐκκλησίας γράψον: ‘Τάδε λέγει ὁ ἔχων τὰ ἑπτὰ πνεύματα τοῦ  ̊Θεοῦ καὶ τοὺς ἑπτὰ ἀστέρας: “Οἶδά σου τὰ ἔργα, ὅτι ὄνομα ἔχεις, ὅτι ζῇς, καὶ νεκρὸς εἶ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 2, 'Γίνου γρηγορῶν, καὶ στήρισον τὰ λοιπὰ, ἃ ἔμελλον ἀποθανεῖν, οὐ γὰρ εὕρηκά σου ἔργα, πεπληρωμένα ἐνώπιον τοῦ  ̊Θεοῦ μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 3, 'Μνημόνευε οὖν πῶς εἴληφας καὶ ἤκουσας, καὶ τήρει καὶ μετανόησον. Ἐὰν οὖν μὴ γρηγορήσῃς, ἥξω ὡς κλέπτης, καὶ οὐ μὴ γνῷς ποίαν ὥραν ἥξω ἐπὶ σέ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 4, 'Ἀλλὰ ἔχεις ὀλίγα ὀνόματα ἐν Σάρδεσιν, ἃ οὐκ ἐμόλυναν τὰ ἱμάτια αὐτῶν, καὶ περιπατήσουσιν μετʼ ἐμοῦ ἐν λευκοῖς, ὅτι ἄξιοί εἰσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 5, 'Ὁ νικῶν, οὕτως περιβαλεῖται ἐν ἱματίοις λευκοῖς, καὶ οὐ μὴ ἐξαλείψω τὸ ὄνομα αὐτοῦ ἐκ τῆς βίβλου τῆς ζωῆς, καὶ ὁμολογήσω τὸ ὄνομα αὐτοῦ ἐνώπιον τοῦ Πατρός μου, καὶ ἐνώπιον τῶν ἀγγέλων αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 6, 'Ὁ ἔχων οὖς, ἀκουσάτω τί τὸ  ̊Πνεῦμα λέγει ταῖς ἐκκλησίαις.”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 7, '¶Καὶ τῷ ἀγγέλῳ τῆς ἐν Φιλαδελφείᾳ ἐκκλησίας γράψον: ‘Τάδε λέγει ὁ Ἅγιος, ὁ Ἀληθινός, ὁ ἔχων τὴν κλεῖν Δαυίδ, ὁ ἀνοίγων καὶ οὐδεὶς κλείσει, καὶ κλείων καὶ οὐδεὶς ἀνοίγει:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 8, '“Οἶδά σου τὰ ἔργα. Ἰδοὺ, δέδωκα ἐνώπιόν σου θύραν ἀνεῳγμένην, ἣν οὐδεὶς δύναται κλεῖσαι αὐτήν, ὅτι μικρὰν ἔχεις δύναμιν, καὶ ἐτήρησάς μου τὸν λόγον, καὶ οὐκ ἠρνήσω τὸ ὄνομά μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 9, 'Ἰδοὺ, διδῶ ἐκ τῆς συναγωγῆς τοῦ Σατανᾶ, τῶν λεγόντων ἑαυτοὺς Ἰουδαίους εἶναι, καὶ οὐκ εἰσὶν, ἀλλὰ ψεύδονται· ἰδοὺ, ποιήσω αὐτοὺς ἵνα ἥξουσιν καὶ προσκυνήσουσιν ἐνώπιον τῶν ποδῶν σου, καὶ γνῶσιν ὅτι ἐγὼ ἠγάπησά σε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 10, 'Ὅτι ἐτήρησας τὸν λόγον τῆς ὑπομονῆς μου, κἀγώ σε τηρήσω ἐκ τῆς ὥρας τοῦ πειρασμοῦ τῆς μελλούσης ἔρχεσθαι ἐπὶ τῆς οἰκουμένης ὅλης, πειράσαι τοὺς κατοικοῦντας ἐπὶ τῆς γῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 11, 'Ἔρχομαι ταχύ· κράτει ὃ ἔχεις, ἵνα μηδεὶς λάβῃ τὸν στέφανόν σου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 12, 'Ὁ νικῶν, ποιήσω αὐτὸν στῦλον ἐν τῷ ναῷ τοῦ  ̊Θεοῦ μου, καὶ ἔξω οὐ μὴ ἐξέλθῃ ἔτι, καὶ γράψω ἐπʼ αὐτὸν τὸ ὄνομα τοῦ  ̊Θεοῦ μου, καὶ τὸ ὄνομα τῆς πόλεως τοῦ  ̊Θεοῦ μου, τῆς καινῆς Ἰερουσαλήμ, ἡ καταβαίνουσα ἐκ τοῦ οὐρανοῦ ἀπὸ τοῦ  ̊Θεοῦ μου, καὶ τὸ ὄνομά μου τὸ καινόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 13, 'Ὁ ἔχων οὖς, ἀκουσάτω τί τὸ  ̊Πνεῦμα λέγει ταῖς ἐκκλησίαις.”’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 14, '¶Καὶ τῷ ἀγγέλῳ τῆς ἐν Λαοδικείᾳ ἐκκλησίας γράψον: ‘Τάδε λέγει ὁ Ἀμήν, ὁ μάρτυς ὁ πιστὸς καὶ ὁ ἀληθινός, ἡ ἀρχὴ τῆς κτίσεως τοῦ  ̊Θεοῦ:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 15, '“Οἶδά σου τὰ ἔργα, ὅτι οὔτε ψυχρὸς εἶ οὔτε ζεστός. Ὄφελος ψυχρὸς ἦς ἢ ζεστός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 16, 'Οὕτως, ὅτι χλιαρὸς εἶ, καὶ οὔτε ζεστὸς οὔτε ψυχρός, μέλλω σε ἐμέσαι ἐκ τοῦ στόματός μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 17, 'Ὅτι λέγεις, ὅτι ‘Πλούσιός εἰμι, καὶ πεπλούτηκα, καὶ οὐδὲν χρείαν ἔχω’, καὶ οὐκ οἶδας ὅτι σὺ εἶ ὁ ταλαίπωρος, καὶ ἐλεεινὸς, καὶ πτωχὸς, καὶ τυφλὸς, καὶ γυμνός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 18, 'Συμβουλεύω σοι ἀγοράσαι παρʼ ἐμοῦ χρυσίον πεπυρωμένον ἐκ πυρὸς, ἵνα πλουτήσῃς, καὶ ἱμάτια λευκὰ, ἵνα περιβάλῃ, καὶ μὴ φανερωθῇ ἡ αἰσχύνη τῆς γυμνότητός σου, καὶ κολλύριον ἐγχρῖσαι τοὺς ὀφθαλμούς σου, ἵνα βλέπῃς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 19, 'Ἐγὼ ὅσους ἐὰν φιλῶ, ἐλέγχω καὶ παιδεύω· ζήλευε οὖν καὶ μετανόησον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 20, 'Ἰδοὺ, ἕστηκα ἐπὶ τὴν θύραν καὶ κρούω· ἐάν τις ἀκούσῃ τῆς φωνῆς μου καὶ ἀνοίξῃ τὴν θύραν, εἰσελεύσομαι πρὸς αὐτὸν, καὶ δειπνήσω μετʼ αὐτοῦ, καὶ αὐτὸς μετʼ ἐμοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 21, 'Ὁ νικῶν, δώσω αὐτῷ καθίσαι μετʼ ἐμοῦ ἐν τῷ θρόνῳ μου, ὡς κἀγὼ ἐνίκησα, καὶ ἐκάθισα μετὰ τοῦ Πατρός μου ἐν τῷ θρόνῳ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 3, 22, 'Ὁ ἔχων οὖς, ἀκουσάτω τί τὸ  ̊Πνεῦμα λέγει ταῖς ἐκκλησίαις.”’”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 4, 1, '¶Μετὰ ταῦτα εἶδον, καὶ ἰδοὺ, θύρα ἠνεῳγμένη ἐν τῷ οὐρανῷ, καὶ ἡ φωνὴ ἡ πρώτη ἣν ἤκουσα ὡς σάλπιγγος λαλούσης μετʼ ἐμοῦ λέγων, “Ἀνάβα ὧδε, καὶ δείξω σοι ἃ δεῖ γενέσθαι μετὰ ταῦτα.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 4, 2, 'Εὐθέως ἐγενόμην ἐν  ̊Πνεύματι, καὶ ἰδοὺ, θρόνος ἔκειτο ἐν τῷ οὐρανῷ, καὶ ἐπὶ τὸν θρόνον καθήμενος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 4, 3, 'καὶ ὁ καθήμενος ὅμοιος ὁράσει λίθῳ, ἰάσπιδι καὶ σαρδίῳ, καὶ ἶρις κυκλόθεν τοῦ θρόνου ὅμοιος ὁράσει σμαραγδίνῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 4, 4, 'Καὶ κυκλόθεν τοῦ θρόνου θρόνους εἴκοσι τέσσαρες, καὶ ἐπὶ τοὺς εἴκοσι τέσσαρας θρόνους πρεσβυτέρους καθημένους, περιβεβλημένους ἱματίοις λευκοῖς, καὶ ἐπὶ τὰς κεφαλὰς αὐτῶν στεφάνους χρυσοῦς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 4, 5, 'Καὶ ἐκ τοῦ θρόνου ἐκπορεύονται ἀστραπαὶ, καὶ φωναὶ, καὶ βρονταί. Καὶ ἑπτὰ λαμπάδες πυρὸς καιόμεναι ἐνώπιον τοῦ θρόνου, ἅ εστιν τὰ ἑπτὰ πνεύματα τοῦ  ̊Θεοῦ·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 4, 6, 'καὶ ἐνώπιον τοῦ θρόνου ὡς θάλασσα ὑαλίνη, ὁμοία κρυστάλλῳ. ¶Καὶ ἐν μέσῳ τοῦ θρόνου καὶ κύκλῳ τοῦ θρόνου, τέσσαρα ζῷα, γέμοντα ὀφθαλμῶν ἔμπροσθεν καὶ ὄπισθεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 4, 7, 'Καὶ τὸ ζῷον τὸ πρῶτον ὅμοιον λέοντι, καὶ τὸ δεύτερον ζῷον ὅμοιον μόσχῳ, καὶ τὸ τρίτον ζῷον ἔχον τὸ πρόσωπον ὡς ἀνθρώπου, καὶ τὸ τέταρτον ζῷον ὅμοιον ἀετῷ πετομένῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 4, 8, 'Καὶ τὰ τέσσαρα ζῷα, ἓν καθʼ ἓν αὐτῶν, ἔχων ἀνὰ πτέρυγας ἕξ, κυκλόθεν καὶ ἔσωθεν γέμουσιν ὀφθαλμῶν, καὶ ἀνάπαυσιν οὐκ ἔχουσιν ἡμέρας καὶ νυκτὸς λέγοντες, “‘Ἅγιος, Ἅγιος, Ἅγιος,  ̊Κύριος ὁ  ̊Θεός ὁ Παντοκράτωρ’, ὁ ἦν, καὶ ὁ ὢν, καὶ ὁ ἐρχόμενος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 4, 9, 'Καὶ ὅταν δώσουσιν τὰ ζῷα δόξαν, καὶ τιμὴν, καὶ εὐχαριστίαν, τῷ καθημένῳ ἐπὶ τῷ θρόνῳ, τῷ ζῶντι εἰς τοὺς αἰῶνας τῶν αἰώνων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 4, 10, 'πεσοῦνται οἱ εἴκοσι τέσσαρες πρεσβύτεροι ἐνώπιον τοῦ καθημένου ἐπὶ τοῦ θρόνου, καὶ προσκυνήσουσιν τῷ ζῶντι εἰς τοὺς αἰῶνας τῶν αἰώνων, καὶ βαλοῦσιν τοὺς στεφάνους αὐτῶν ἐνώπιον τοῦ θρόνου λέγοντες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 4, 11, '“Ἄξιος εἶ, ὁ  ̊Κύριος καὶ ὁ  ̊Θεὸς ἡμῶν, λαβεῖν τὴν δόξαν καὶ τὴν τιμὴν καὶ τὴν δύναμιν, ὅτι σὺ ἔκτισας τὰ πάντα, καὶ διὰ τὸ θέλημά σου ἦσαν, καὶ ἐκτίσθησαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 5, 1, '¶Καὶ εἶδον ἐπὶ τὴν δεξιὰν τοῦ καθημένου ἐπὶ τοῦ θρόνου βιβλίον, γεγραμμένον ἔσωθεν καὶ ὄπισθεν, κατεσφραγισμένον σφραγῖσιν ἑπτά.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 5, 2, 'Καὶ εἶδον ἄγγελον ἰσχυρὸν, κηρύσσοντα ἐν φωνῇ μεγάλῃ, “Τίς ἄξιος ἀνοῖξαι τὸ βιβλίον, καὶ λῦσαι τὰς σφραγῖδας αὐτοῦ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 5, 3, 'Καὶ οὐδεὶς ἐδύνατο ἐν τῷ οὐρανῷ, οὐδὲ ἐπὶ τῆς γῆς, οὐδὲ ὑποκάτω τῆς γῆς, ἀνοῖξαι τὸ βιβλίον, οὔτε βλέπειν αὐτό.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 5, 4, 'Καὶ ἔκλαιον πολὺ, ὅτι οὐδεὶς ἄξιος εὑρεθήσεται ἀνοῖξαι τὸ βιβλίον, οὔτε βλέπειν αὐτό.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 5, 5, 'Καὶ εἷς ἐκ τῶν πρεσβυτέρων λέγει μοι, “Μὴ κλαῖε. Ἰδοὺ, ἐνίκησεν ὁ λέων ὁ ἐκ τῆς φυλῆς Ἰούδα, ἡ ῥίζα Δαυίδ, ἀνοῖξαι τὸ βιβλίον, καὶ τὰς ἑπτὰ σφραγῖδας αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 5, 6, 'Καὶ εἶδον ἐν μέσῳ τοῦ θρόνου καὶ τῶν τεσσάρων ζῴων καὶ ἐν μέσῳ τῶν πρεσβυτέρων, Ἀρνίον ἑστηκὸς ὡς ἐσφαγμένον, ἔχων κέρατα ἑπτὰ καὶ ὀφθαλμοὺς ἑπτά, οἵ εἰσιν τὰ ἑπτὰ πνεύματα τοῦ  ̊Θεοῦ, ἀπεσταλμένοι εἰς πᾶσαν τὴν γῆν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 5, 7, 'Καὶ ἦλθεν καὶ εἴληφεν ἐκ τῆς δεξιᾶς τοῦ καθημένου ἐπὶ τοῦ θρόνου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 5, 8, 'Καὶ ὅτε ἔλαβεν τὸ βιβλίον, τὰ τέσσαρα ζῷα καὶ οἱ εἴκοσι τέσσαρες πρεσβύτεροι ἔπεσαν ἐνώπιον τοῦ Ἀρνίου, ἔχοντες ἕκαστος κιθάραν καὶ φιάλας χρυσᾶς γεμούσας θυμιαμάτων, αἵ εἰσιν αἱ προσευχαὶ τῶν ἁγίων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 5, 9, 'Καὶ ᾄδουσιν ᾠδὴν καινὴν λέγοντες, “Ἄξιος εἶ λαβεῖν τὸ βιβλίον, καὶ ἀνοῖξαι τὰς σφραγῖδας αὐτοῦ, ὅτι ἐσφάγης, καὶ ἠγόρασας τῷ  ̊Θεῷ ἡμᾶς ἐν τῷ αἵματί σου, ἐκ πάσης φυλῆς, καὶ γλώσσης, καὶ λαοῦ, καὶ ἔθνους,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 5, 10, 'καὶ ἐποίησας αὐτοὺς τῷ  ̊Θεῷ ἡμῶν, βασιλείαν καὶ ἱερεῖς, καὶ βασιλεύσουσιν ἐπὶ τῆς γῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 5, 11, '¶Καὶ εἶδον, καὶ ἤκουσα φωνὴν ἀγγέλων πολλῶν κύκλῳ τοῦ θρόνου, καὶ τῶν ζῴων, καὶ τῶν πρεσβυτέρων, καὶ ἦν ὁ ἀριθμὸς αὐτῶν μυριάδες μυριάδων καὶ χιλιάδες χιλιάδων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 5, 12, 'λέγοντες φωνῇ μεγάλῃ, “Ἄξιόν ἐστιν τὸ Ἀρνίον τὸ ἐσφαγμένον, λαβεῖν τὴν δύναμιν, καὶ πλοῦτον, καὶ σοφίαν, καὶ ἰσχὺν, καὶ τιμὴν, καὶ δόξαν, καὶ εὐλογίαν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 5, 13, 'Καὶ πᾶν κτίσμα ὃ ἐν τῷ οὐρανῷ, καὶ ἐπὶ τῆς γῆς, καὶ ὑποκάτω τῆς γῆς, καὶ ἐπὶ τῆς θαλάσσης, καὶ τὰ ἐν αὐτοῖς πάντα, ἤκουσα λέγοντας, “Τῷ καθημένῳ ἐπὶ τοῦ θρόνου καὶ τῷ Ἀρνίῳ ἡ εὐλογία, καὶ ἡ τιμὴ, καὶ ἡ δόξα, καὶ τὸ κράτος, εἰς τοὺς αἰῶνας τῶν αἰώνων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 5, 14, 'Καὶ τὰ τέσσαρα ζῷα ἔλεγον, “Ἀμήν!” Καὶ οἱ πρεσβύτεροι ἔπεσαν καὶ προσεκύνησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 1, '¶Καὶ εἶδον, ὅτε ἤνοιξεν τὸ Ἀρνίον μίαν ἐκ τῶν ἑπτὰ σφραγίδων, καὶ ἤκουσα ἑνὸς ἐκ τῶν τεσσάρων ζῴων, λέγοντος ὡς φωνῇ βροντῆς, “Ἔρχου!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 2, 'Καὶ εἶδον, καὶ ἰδοὺ, ἵππος λευκός, καὶ ὁ καθήμενος ἐπʼ αὐτὸν ἔχων τόξον, καὶ ἐδόθη αὐτῷ στέφανος, καὶ ἐξῆλθεν νικῶν, καὶ ἵνα νικήσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 3, '¶Καὶ ὅτε ἤνοιξεν τὴν σφραγῖδα τὴν δευτέραν, ἤκουσα τοῦ δευτέρου ζῴου λέγοντος, “Ἔρχου!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 4, 'Καὶ ἐξῆλθεν ἄλλος ἵππος πυρρός, καὶ τῷ καθημένῳ ἐπʼ αὐτὸν, ἐδόθη αὐτῷ λαβεῖν τὴν εἰρήνην ἐκ τῆς γῆς, καὶ ἵνα ἀλλήλους σφάξουσιν, καὶ ἐδόθη αὐτῷ μάχαιρα μεγάλη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 5, '¶Καὶ ὅτε ἤνοιξεν τὴν σφραγῖδα τὴν τρίτην, ἤκουσα τοῦ τρίτου ζῴου λέγοντος, “Ἔρχου.” Καὶ εἶδον, καὶ ἰδοὺ, ἵππος μέλας, καὶ ὁ καθήμενος ἐπʼ αὐτὸν, ἔχων ζυγὸν ἐν τῇ χειρὶ αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 6, 'Καὶ ἤκουσα ὡς φωνὴν ἐν μέσῳ τῶν τεσσάρων ζῴων λέγουσαν, “Χοῖνιξ σίτου δηναρίου, καὶ τρεῖς χοίνικες κριθῶν δηναρίου, καὶ τὸ ἔλαιον καὶ τὸν οἶνον μὴ ἀδικήσῃς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 7, '¶Καὶ ὅτε ἤνοιξεν τὴν σφραγῖδα τὴν τετάρτην, ἤκουσα φωνὴν τοῦ τετάρτου ζῴου λέγοντος, “Ἔρχου!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 8, 'Καὶ εἶδον, καὶ ἰδοὺ, ἵππος χλωρός, καὶ ὁ καθήμενος ἐπάνω αὐτοῦ, ὄνομα αὐτῷ Θάνατος, καὶ ὁ ἍΙδης ἠκολούθει μετʼ αὐτοῦ, καὶ ἐδόθη αὐτοῖς ἐξουσία ἐπὶ τὸ τέταρτον τῆς γῆς, ἀποκτεῖναι ἐν ῥομφαίᾳ, καὶ ἐν λιμῷ, καὶ ἐν θανάτῳ, καὶ ὑπὸ τῶν θηρίων τῆς γῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 9, '¶Καὶ ὅτε ἤνοιξεν τὴν πέμπτην σφραγῖδα, εἶδον ὑποκάτω τοῦ θυσιαστηρίου, τὰς ψυχὰς τῶν ἐσφαγμένων διὰ τὸν λόγον τοῦ  ̊Θεοῦ, καὶ διὰ τὴν μαρτυρίαν ἣν εἶχον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 10, 'Καὶ ἔκραξαν φωνῇ μεγάλῃ λέγοντες, “Ἕως πότε ὁ Δεσπότης ὁ ἅγιος καὶ ἀληθινός, οὐ κρίνεις καὶ ἐκδικεῖς τὸ αἷμα ἡμῶν, ἐκ τῶν κατοικούντων ἐπὶ τῆς γῆς;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 11, 'Καὶ ἐδόθη αὐτοῖς ἑκάστῳ στολὴ λευκή, καὶ ἐρρέθη αὐτοῖς ἵνα ἀναπαύσωνται ἔτι χρόνον μικρόν, ἕως πληρωθῶσιν καὶ οἱ σύνδουλοι αὐτῶν, καὶ οἱ ἀδελφοὶ αὐτῶν, οἱ μέλλοντες ἀποκτέννεσθαι ὡς καὶ αὐτοί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 12, '¶Καὶ εἶδον ὅτε ἤνοιξεν τὴν σφραγῖδα τὴν ἕκτην, καὶ σεισμὸς μέγας ἐγένετο, καὶ ὁ ἥλιος ἐγένετο μέλας ὡς σάκκος τρίχινος, καὶ ἡ σελήνη ὅλη ἐγένετο ὡς αἷμα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 13, 'καὶ οἱ ἀστέρες τοῦ οὐρανοῦ ἔπεσαν εἰς τὴν γῆν, ὡς συκῆ βάλλει τοὺς ὀλύνθους αὐτῆς, ὑπὸ ἀνέμου μεγάλου σειομένη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 14, 'Καὶ ὁ οὐρανὸς ἀπεχωρίσθη ὡς βιβλίον ἑλισσόμενον, καὶ πᾶν ὄρος καὶ νῆσος ἐκ τῶν τόπων αὐτῶν ἐκινήθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 15, 'Καὶ οἱ βασιλεῖς τῆς γῆς, καὶ οἱ μεγιστᾶνες, καὶ οἱ χιλίαρχοι, καὶ οἱ πλούσιοι, καὶ οἱ ἰσχυροὶ, καὶ πᾶς δοῦλος καὶ ἐλεύθερος, ἔκρυψαν ἑαυτοὺς εἰς τὰ σπήλαια καὶ εἰς τὰς πέτρας τῶν ὀρέων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 16, 'καὶ λέγουσιν τοῖς ὄρεσιν καὶ ταῖς πέτραις, “Πέσετε ἐφʼ ἡμᾶς, καὶ κρύψατε ἡμᾶς ἀπὸ προσώπου τοῦ καθημένου ἐπὶ τοῦ θρόνου, καὶ ἀπὸ τῆς ὀργῆς τοῦ Ἀρνίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 6, 17, 'ὅτι ἦλθεν ἡ ἡμέρα ἡ μεγάλη τῆς ὀργῆς αὐτῶν, καὶ τίς δύναται σταθῆναι;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 1, '¶Μετὰ τοῦτο εἶδον τέσσαρας ἀγγέλους ἑστῶτας ἐπὶ τὰς τέσσαρας γωνίας τῆς γῆς, κρατοῦντας τοὺς τέσσαρας ἀνέμους τῆς γῆς, ἵνα μὴ πνέῃ ἄνεμος ἐπὶ τῆς γῆς, μήτε ἐπὶ τῆς θαλάσσης, μήτε ἐπὶ πᾶν δένδρον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 2, 'Καὶ εἶδον ἄλλον ἄγγελον, ἀναβαίνοντα ἀπὸ ἀνατολῆς ἡλίου, ἔχοντα σφραγῖδα  ̊Θεοῦ ζῶντος, καὶ ἔκραξεν φωνῇ μεγάλῃ τοῖς τέσσαρσιν ἀγγέλοις οἷς ἐδόθη αὐτοῖς ἀδικῆσαι τὴν γῆν καὶ τὴν θάλασσαν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 3, 'λέγων, “Μὴ ἀδικήσητε τὴν γῆν, μήτε τὴν θάλασσαν μήτε τὰ δένδρα, ἄχρι σφραγίσωμεν τοὺς δούλους τοῦ  ̊Θεοῦ ἡμῶν ἐπὶ τῶν μετώπων αὐτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 4, '¶Καὶ ἤκουσα τὸν ἀριθμὸν τῶν ἐσφραγισμένων, ἑκατὸν τεσσεράκοντα τέσσαρες χιλιάδες, ἐσφραγισμένοι ἐκ πάσης φυλῆς υἱῶν Ἰσραήλ:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 5, 'ἐκ φυλῆς Ἰούδα δώδεκα χιλιάδες ἐσφραγισμένοι, ἐκ φυλῆς Ῥουβὴν δώδεκα χιλιάδες, ἐκ φυλῆς Γὰδ δώδεκα χιλιάδες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 6, 'ἐκ φυλῆς Ἀσὴρ δώδεκα χιλιάδες, ἐκ φυλῆς Νεφθαλὶμ δώδεκα χιλιάδες, ἐκ φυλῆς Μανασσῆ δώδεκα χιλιάδες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 7, 'ἐκ φυλῆς Συμεὼν δώδεκα χιλιάδες, ἐκ φυλῆς Λευὶ δώδεκα χιλιάδες, ἐκ φυλῆς Ἰσσαχὰρ δώδεκα χιλιάδες,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 8, 'ἐκ φυλῆς Ζαβουλὼν δώδεκα χιλιάδες, ἐκ φυλῆς Ἰωσὴφ δώδεκα χιλιάδες, ἐκ φυλῆς Βενιαμὶν δώδεκα χιλιάδες ἐσφραγισμένοι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 9, '¶Μετὰ ταῦτα εἶδον, καὶ ἰδοὺ, ὄχλος πολύς, ὃν ἀριθμῆσαι αὐτὸν οὐδεὶς ἐδύνατο, ἐκ παντὸς ἔθνους, καὶ φυλῶν, καὶ λαῶν, καὶ γλωσσῶν, ἑστῶτες ἐνώπιον τοῦ θρόνου καὶ ἐνώπιον τοῦ Ἀρνίου, περιβεβλημένους στολὰς λευκάς, καὶ φοίνικες ἐν ταῖς χερσὶν αὐτῶν·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 10, 'καὶ κράζουσιν φωνῇ μεγάλῃ λέγοντες, “Ἡ σωτηρία τῷ  ̊Θεῷ ἡμῶν, τῷ καθημένῳ ἐπὶ τῷ θρόνῳ καὶ τῷ Ἀρνίῳ!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 11, 'Καὶ πάντες οἱ ἄγγελοι εἱστήκεισαν κύκλῳ τοῦ θρόνου, καὶ τῶν πρεσβυτέρων, καὶ τῶν τεσσάρων ζῴων, καὶ ἔπεσαν ἐνώπιον τοῦ θρόνου ἐπὶ τὰ πρόσωπα αὐτῶν, καὶ προσεκύνησαν τῷ  ̊Θεῷ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 12, 'λέγοντες, “Ἀμήν! Ἡ εὐλογία, καὶ ἡ δόξα, καὶ ἡ σοφία, καὶ ἡ εὐχαριστία, καὶ ἡ τιμὴ, καὶ ἡ δύναμις, καὶ ἡ ἰσχὺς, τῷ  ̊Θεῷ ἡμῶν εἰς τοὺς αἰῶνας τῶν αἰώνων. Ἀμήν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 13, '¶Καὶ ἀπεκρίθη εἷς ἐκ τῶν πρεσβυτέρων, λέγων μοι, “Οὗτοι, οἱ περιβεβλημένοι τὰς στολὰς τὰς λευκὰς, τίνες εἰσὶν καὶ πόθεν ἦλθον;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 14, 'Καὶ εἴρηκα αὐτῷ, “Κύριέ μου, σὺ οἶδας.” Καὶ εἶπέν μοι, “Οὗτοί εἰσιν οἱ ἐρχόμενοι ἐκ τῆς θλίψεως τῆς μεγάλης, καὶ ἔπλυναν τὰς στολὰς αὐτῶν, καὶ ἐλεύκαναν αὐτὰς ἐν τῷ αἵματι τοῦ Ἀρνίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 15, 'Διὰ τοῦτό, εἰσιν ἐνώπιον τοῦ θρόνου τοῦ  ̊Θεοῦ, καὶ λατρεύουσιν αὐτῷ ἡμέρας καὶ νυκτὸς ἐν τῷ ναῷ αὐτοῦ, καὶ ὁ καθήμενος ἐπὶ τοῦ θρόνου σκηνώσει ἐπʼ αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 16, 'Οὐ πεινάσουσιν ἔτι, οὐδὲ διψήσουσιν ἔτι, οὐδὲ μὴ πέσῃ ἐπʼ αὐτοὺς ὁ ἥλιος, οὐδὲ πᾶν καῦμα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 7, 17, 'ὅτι τὸ Ἀρνίον τὸ ἀνὰ μέσον τοῦ θρόνου ποιμανεῖ αὐτούς, καὶ ὁδηγήσει αὐτοὺς ἐπὶ ζωῆς πηγὰς ὑδάτων, καὶ ἐξαλείψει ὁ  ̊Θεὸς πᾶν δάκρυον ἐκ τῶν ὀφθαλμῶν αὐτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 8, 1, '¶Καὶ ὅταν ἤνοιξεν τὴν σφραγῖδα τὴν ἑβδόμην, ἐγένετο σιγὴ ἐν τῷ οὐρανῷ ὡς ἡμίωρον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 8, 2, 'Καὶ εἶδον τοὺς ἑπτὰ ἀγγέλους, οἳ ἐνώπιον τοῦ  ̊Θεοῦ ἑστήκασιν, καὶ ἐδόθησαν αὐτοῖς ἑπτὰ σάλπιγγες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 8, 3, '¶Καὶ ἄλλος ἄγγελος ἦλθεν καὶ ἐστάθη ἐπὶ τοῦ θυσιαστήριον, ἔχων λιβανωτὸν χρυσοῦν, καὶ ἐδόθη αὐτῷ θυμιάματα πολλὰ, ἵνα δώσει ταῖς προσευχαῖς τῶν ἁγίων πάντων ἐπὶ τὸ θυσιαστήριον τὸ χρυσοῦν τὸ ἐνώπιον τοῦ θρόνου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 8, 4, 'Καὶ ἀνέβη ὁ καπνὸς τῶν θυμιαμάτων ταῖς προσευχαῖς τῶν ἁγίων ἐκ χειρὸς τοῦ ἀγγέλου ἐνώπιον τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 8, 5, 'Καὶ εἴληφεν ὁ ἄγγελος τὸν λιβανωτόν, καὶ ἐγέμισεν αὐτὸν ἐκ τοῦ πυρὸς τοῦ θυσιαστηρίου, καὶ ἔβαλεν εἰς τὴν γῆν· καὶ ἐγένοντο βρονταὶ, καὶ φωναὶ, καὶ ἀστραπαὶ, καὶ σεισμός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 8, 6, '¶Καὶ οἱ ἑπτὰ ἄγγελοι οἱ ἔχοντες τὰς ἑπτὰ σάλπιγγας ἡτοίμασαν αὑτοὺς, ἵνα σαλπίσωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 8, 7, '¶Καὶ ὁ πρῶτος ἐσάλπισεν, καὶ ἐγένετο χάλαζα καὶ πῦρ μεμιγμένα ἐν αἵματι, καὶ ἐβλήθη εἰς τὴν γῆν· καὶ τὸ τρίτον τῆς γῆς κατεκάη, καὶ τὸ τρίτον τῶν δένδρων κατεκάη, καὶ πᾶς χόρτος χλωρὸς κατεκάη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 8, 8, '¶Καὶ ὁ δεύτερος ἄγγελος ἐσάλπισεν, καὶ ὡς ὄρος μέγα πυρὶ καιόμενον, ἐβλήθη εἰς τὴν θάλασσαν· καὶ ἐγένετο τὸ τρίτον τῆς θαλάσσης αἷμα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 8, 9, 'καὶ ἀπέθανε τὸ τρίτον τῶν κτισμάτων τῶν ἐν τῇ θαλάσσῃ τὰ ἔχοντα ψυχὴν, καὶ τὸ τρίτον τῶν πλοίων διεφθάρησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 8, 10, '¶Καὶ ὁ τρίτος ἄγγελος ἐσάλπισεν, καὶ ἔπεσεν ἐκ τοῦ οὐρανοῦ ἀστὴρ μέγας, καιόμενος ὡς λαμπάς, καὶ ἔπεσεν ἐπὶ τὸ τρίτον τῶν ποταμῶν, καὶ ἐπὶ τὰς πηγὰς τῶν ὑδάτων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 8, 11, 'καὶ τὸ ὄνομα τοῦ ἀστέρος λέγεται ὁ Ἄψινθος. Καὶ ἐγένετο τὸ τρίτον τῶν ὑδάτων εἰς ἀψίνθιον, καὶ πολλοὶ τῶν ἀνθρώπων ἀπέθανον ἐκ τῶν ὑδάτων, ὅτι ἐπικράνθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 8, 12, '¶Καὶ ὁ τέταρτος ἄγγελος ἐσάλπισεν, καὶ ἐπλήγη τὸ τρίτον τοῦ ἡλίου, καὶ τὸ τρίτον τῆς σελήνης, καὶ τὸ τρίτον τῶν ἀστέρων, ἵνα σκοτισθῇ τὸ τρίτον αὐτῶν, καὶ ἡ ἡμέρα μὴ φάνῃ τὸ τρίτον αὐτῆς, καὶ ἡ νὺξ ὁμοίως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 8, 13, '¶Καὶ εἶδον, καὶ ἤκουσα ἑνὸς ἀετοῦ πετομένου ἐν μεσουρανήματι, λέγοντος φωνῇ μεγάλῃ, “Οὐαὶ, οὐαὶ, οὐαὶ, τοὺς κατοικοῦντας ἐπὶ τῆς γῆς, ἐκ τῶν λοιπῶν φωνῶν τῆς σάλπιγγος τῶν τριῶν ἀγγέλων τῶν μελλόντων σαλπίζειν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 1, '¶Καὶ ὁ πέμπτος ἄγγελος ἐσάλπισεν, καὶ εἶδον ἀστέρα ἐκ τοῦ οὐρανοῦ πεπτωκότα εἰς τὴν γῆν, καὶ ἐδόθη αὐτῷ ἡ κλεὶς τοῦ φρέατος τῆς Ἀβύσσου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 2, 'καὶ ἤνοιξεν τὸ φρέαρ τῆς Ἀβύσσου, καὶ ἀνέβη καπνὸς ἐκ τοῦ φρέατος, ὡς καπνὸς καμίνου μεγάλης, καὶ ἐσκοτίσθη ὁ ἥλιος καὶ ὁ ἀὴρ ἐκ τοῦ καπνοῦ τοῦ φρέατος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 3, 'Καὶ ἐκ τοῦ καπνοῦ ἐξῆλθον ἀκρίδες εἰς τὴν γῆν, καὶ ἐδόθη αὐταῖς ἐξουσία, ὡς ἔχουσιν ἐξουσίαν οἱ σκορπίοι τῆς γῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 4, 'Καὶ ἐρρέθη αὐταῖς ἵνα μὴ ἀδικήσωσιν τὸν χόρτον τῆς γῆς, οὐδὲ πᾶν χλωρὸν, οὐδὲ πᾶν δένδρον, εἰ μὴ τοὺς ἀνθρώπους οἵτινες οὐκ ἔχουσι τὴν σφραγῖδα τοῦ  ̊Θεοῦ ἐπὶ τῶν μετώπων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 5, 'Καὶ ἐδόθη αὐτοῖς, ἵνα μὴ ἀποκτείνωσιν αὐτούς, ἀλλʼ ἵνα βασανισθήσονται μῆνας πέντε· καὶ ὁ βασανισμὸς αὐτῶν ὡς βασανισμὸς σκορπίου, ὅταν παίσῃ ἄνθρωπον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 6, 'Καὶ ἐν ταῖς ἡμέραις ἐκείναις, ζητήσουσιν οἱ ἄνθρωποι τὸν θάνατον, καὶ οὐ μὴ εὑρήσουσιν αὐτόν, καὶ ἐπιθυμήσουσιν ἀποθανεῖν, καὶ φεύγει ὁ θάνατος ἀπʼ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 7, '¶Καὶ τὰ ὁμοιώματα τῶν ἀκρίδων ὅμοια ἵπποις ἡτοιμασμένοις εἰς πόλεμον, καὶ ἐπὶ τὰς κεφαλὰς αὐτῶν ὡς στέφανοι ὅμοιοι χρυσῷ, καὶ τὰ πρόσωπα αὐτῶν ὡς πρόσωπα ἀνθρώπων,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 8, 'καὶ εἶχαν τρίχας ὡς τρίχας γυναικῶν, καὶ οἱ ὀδόντες αὐτῶν ὡς λεόντων ἦσαν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 9, 'καὶ εἶχον θώρακας ὡς θώρακας σιδηροῦς, καὶ ἡ φωνὴ τῶν πτερύγων αὐτῶν ὡς φωνὴ ἁρμάτων ἵππων πολλῶν τρεχόντων εἰς πόλεμον,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 10, 'καὶ ἔχουσιν οὐρὰς ὁμοίας σκορπίοις καὶ κέντρα, καὶ ἐν ταῖς οὐραῖς αὐτῶν ἡ ἐξουσία αὐτῶν ἀδικῆσαι τοὺς ἀνθρώπους μῆνας πέντε.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 11, 'Ἔχουσιν ἐπʼ αὐτῶν βασιλέα, τὸν ἄγγελον τῆς Ἀβύσσου· ὄνομα αὐτῷ Ἑβραϊστὶ, Ἀβαδδών, καὶ ἐν τῇ Ἑλληνικῇ ὄνομα ἔχει, Ἀπολλύων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 12, '¶Ἡ οὐαὶ ἡ μία ἀπῆλθεν· ἰδοὺ, ἔρχεται ἔτι δύο οὐαὶ μετὰ ταῦτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 13, '¶Καὶ ὁ ἕκτος ἄγγελος ἐσάλπισεν, καὶ ἤκουσα φωνὴν μίαν ἐκ τῶν κεράτων τοῦ θυσιαστηρίου τοῦ χρυσοῦ τοῦ ἐνώπιον τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 14, 'λέγοντα τῷ ἕκτῳ ἀγγέλῳ, ὁ ἔχων τὴν σάλπιγγα, “Λῦσον τοὺς τέσσαρας ἀγγέλους, τοὺς δεδεμένους ἐπὶ τῷ ποταμῷ τῷ μεγάλῳ Εὐφράτῃ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 15, 'Καὶ ἐλύθησαν οἱ τέσσαρες ἄγγελοι, οἱ ἡτοιμασμένοι εἰς τὴν ὥραν, καὶ ἡμέραν, καὶ μῆνα, καὶ ἐνιαυτόν, ἵνα ἀποκτείνωσιν τὸ τρίτον τῶν ἀνθρώπων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 16, 'Καὶ ὁ ἀριθμὸς τῶν στρατευμάτων τοῦ ἱππικοῦ δύο μυριάδες μυριάδων· ἤκουσα τὸν ἀριθμὸν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 17, 'Καὶ οὕτως εἶδον τοὺς ἵππους ἐν τῇ ὁράσει, καὶ τοὺς καθημένους ἐπʼ αὐτῶν: ἔχοντας θώρακας πυρίνους, καὶ ὑακινθίνους, καὶ θειώδεις, καὶ αἱ κεφαλαὶ τῶν ἵππων ὡς κεφαλαὶ λεόντων, καὶ ἐκ τῶν στομάτων αὐτῶν ἐκπορεύεται πῦρ, καὶ καπνὸς, καὶ θεῖον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 18, 'Ἀπὸ τῶν τριῶν πληγῶν τούτων ἀπεκτάνθησαν τὸ τρίτον τῶν ἀνθρώπων ἐκ τοῦ πυρὸς, καὶ τοῦ καπνοῦ, καὶ τοῦ θείου, τοῦ ἐκπορευομένου ἐκ τῶν στομάτων αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 19, 'Ἡ γὰρ ἐξουσία τῶν ἵππων ἐν τῷ στόματι αὐτῶν ἐστιν καὶ ἐν ταῖς οὐραῖς αὐτῶν, αἱ γὰρ οὐραὶ αὐτῶν ὅμοιαι ὄφεσιν, ἔχουσαι κεφαλάς, καὶ ἐν αὐταῖς ἀδικοῦσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 20, '¶Καὶ οἱ λοιποὶ τῶν ἀνθρώπων, οἳ οὐκ ἀπεκτάνθησαν ἐν ταῖς πληγαῖς ταύταις, οὐδὲ μετενόησαν ἐκ τῶν ἔργων τῶν χειρῶν αὐτῶν, ἵνα μὴ προσκυνήσουσιν τὰ δαιμόνια, καὶ τὰ εἴδωλα τὰ χρυσᾶ, καὶ τὰ ἀργυρᾶ, καὶ τὰ χαλκᾶ, καὶ τὰ λίθινα, καὶ τὰ ξύλινα, ἃ οὔτε βλέπειν δύνανται, οὔτε ἀκούειν, οὔτε περιπατεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 9, 21, 'Καὶ οὐ μετενόησαν ἐκ τῶν φόνων αὐτῶν, οὔτε ἐκ τῶν φαρμάκων αὐτῶν, οὔτε ἐκ τῆς πονηρίας αὐτῶν, οὔτε ἐκ τῶν κλεμμάτων αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 10, 1, '¶Καὶ εἶδον ἄλλον ἄγγελον ἰσχυρὸν, καταβαίνοντα ἐκ τοῦ οὐρανοῦ, περιβεβλημένον νεφέλην, καὶ ἡ ἶρις ἐπὶ τὴν κεφαλὴν αὐτοῦ, καὶ τὸ πρόσωπον αὐτοῦ ὡς ὁ ἥλιος, καὶ οἱ πόδες αὐτοῦ ὡς στῦλοι πυρός,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 10, 2, 'καὶ ἔχων ἐν τῇ χειρὶ αὐτοῦ βιβλαρίδιον ἠνεῳγμένον. Καὶ ἔθηκεν τὸν πόδα αὐτοῦ τὸν δεξιὸν ἐπὶ τῆς θαλάσσης, τὸν δὲ εὐώνυμον ἐπὶ τῆς γῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 10, 3, 'καὶ ἔκραξεν φωνῇ μεγάλῃ ὥσπερ λέων μυκᾶται. Καὶ ὅτε ἔκραξεν, ἐλάλησαν αἱ ἑπτὰ βρονταὶ τὰς ἑαυτῶν φωνάς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 10, 4, 'Καὶ ὅτε ἐλάλησαν αἱ ἑπτὰ βρονταί, ἤμελλον γράφειν, καὶ ἤκουσα φωνὴν ἐκ τοῦ οὐρανοῦ λέγουσαν, “Σφράγισον ἃ ἐλάλησαν αἱ ἑπτὰ βρονταί, καὶ μὴ αὐτὰ γράψῃς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 10, 5, 'Καὶ ὁ ἄγγελος, ὃν εἶδον ἑστῶτα ἐπὶ τῆς θαλάσσης καὶ ἐπὶ τῆς γῆς, ἦρεν τὴν χεῖρα αὐτοῦ τὴν δεξιὰν εἰς τὸν οὐρανόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 10, 6, 'καὶ ὤμοσεν ἐν τῷ ζῶντι εἰς τοὺς αἰῶνας τῶν αἰώνων, “ὃς ἔκτισεν τὸν οὐρανὸν καὶ τὰ ἐν αὐτῷ, καὶ τὴν γῆν καὶ τὰ ἐν αὐτῇ, καὶ τὴν θάλασσαν καὶ τὰ ἐν αὐτῇ”, ὅτι χρόνος οὐκέτι ἔσται!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 10, 7, 'Ἀλλʼ ἐν ταῖς ἡμέραις τῆς φωνῆς τοῦ ἑβδόμου ἀγγέλου, ὅταν μέλλῃ σαλπίζειν, καὶ ἐτελέσθη τὸ μυστήριον τοῦ  ̊Θεοῦ, ὡς εὐηγγέλισεν τοὺς ἑαυτοῦ δούλους, τοὺς προφήτας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 10, 8, '¶Καὶ ἡ φωνὴ ἣν ἤκουσα ἐκ τοῦ οὐρανοῦ, πάλιν λαλοῦσαν μετʼ ἐμοῦ, καὶ λέγουσαν, “Ὕπαγε, λάβε τὸ βιβλίον τὸ ἠνεῳγμένον ἐν τῇ χειρὶ τοῦ ἀγγέλου, τοῦ ἑστῶτος ἐπὶ τῆς θαλάσσης καὶ ἐπὶ τῆς γῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 10, 9, 'Καὶ ἀπῆλθα πρὸς τὸν ἄγγελον, λέγων αὐτῷ δοῦναί μοι τὸ βιβλαρίδιον. Καὶ λέγει μοι, “Λάβε καὶ κατάφαγε αὐτό, καὶ πικρανεῖ σου τὴν κοιλίαν, ἀλλʼ ἐν τῷ στόματί σου, ἔσται γλυκὺ ὡς μέλι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 10, 10, 'Καὶ ἔλαβον τὸ βιβλαρίδιον ἐκ τῆς χειρὸς τοῦ ἀγγέλου, καὶ κατέφαγον αὐτό, καὶ ἦν ἐν τῷ στόματί μου ὡς μέλι γλυκύ· καὶ ὅτε ἔφαγον αὐτό, ἐπικράνθη ἡ κοιλία μου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 10, 11, '¶Καὶ λέγουσίν μοι, “Δεῖ σε πάλιν προφητεῦσαι ἐπὶ λαοῖς, καὶ ἔθνεσιν, καὶ γλώσσαις, καὶ βασιλεῦσιν πολλοῖς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 1, '¶Καὶ ἐδόθη μοι κάλαμος ὅμοιος ῥάβδῳ λέγων, “Ἔγειρε, καὶ μέτρησον τὸν ναὸν τοῦ  ̊Θεοῦ, καὶ τὸ θυσιαστήριον, καὶ τοὺς προσκυνοῦντας ἐν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 2, 'Καὶ τὴν αὐλὴν τὴν ἔξωθεν τοῦ ναοῦ, ἔκβαλε ἔξωθεν καὶ μὴ αὐτὴν μετρήσῃς, ὅτι ἐδόθη τοῖς ἔθνεσιν, καὶ τὴν πόλιν τὴν ἁγίαν πατήσουσιν μῆνας τεσσεράκοντα δύο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 3, 'Καὶ δώσω τοῖς δυσὶν μάρτυσίν μου, καὶ προφητεύσουσιν ἡμέρας χιλίας διακοσίας ἑξήκοντα, περιβεβλημένοι σάκκους.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 4, '¶Οὗτοί εἰσιν αἱ δύο ἐλαῖαι καὶ αἱ δύο λυχνίαι, αἱ ἐνώπιον τοῦ  ̊Κυρίου τῆς γῆς ἑστῶτες.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 5, 'Καὶ εἴ τις αὐτοὺς θέλει ἀδικῆσαι, πῦρ ἐκπορεύεται ἐκ τοῦ στόματος αὐτῶν, καὶ κατεσθίει τοὺς ἐχθροὺς αὐτῶν. Καὶ εἴ τις θελήσῃ αὐτοὺς ἀδικῆσαι, οὕτως δεῖ αὐτὸν ἀποκτανθῆναι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 6, 'Οὗτοι ἔχουσιν τὴν ἐξουσίαν κλεῖσαι τὸν οὐρανόν, ἵνα μὴ ὑετὸς βρέχῃ τὰς ἡμέρας τῆς προφητείας αὐτῶν, καὶ ἐξουσίαν ἔχουσιν ἐπὶ τῶν ὑδάτων, στρέφειν αὐτὰ εἰς αἷμα, καὶ πατάξαι τὴν γῆν ἐν πάσῃ πληγῇ, ὁσάκις ἐὰν θελήσωσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 7, '¶Καὶ ὅταν τελέσωσιν τὴν μαρτυρίαν αὐτῶν, τὸ θηρίον τὸ ἀναβαῖνον ἐκ τῆς Ἀβύσσου ποιήσει μετʼ αὐτῶν πόλεμον, καὶ νικήσει αὐτοὺς, καὶ ἀποκτενεῖ αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 8, 'Καὶ τὸ πτῶμα αὐτῶν ἐπὶ τῆς πλατείας τῆς πόλεως τῆς μεγάλης, ἥτις καλεῖται πνευματικῶς, Σόδομα καὶ Αἴγυπτος, ὅπου καὶ ὁ  ̊Κύριος αὐτῶν ἐσταυρώθη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 9, 'Καὶ βλέπουσιν ἐκ τῶν λαῶν, καὶ φυλῶν, καὶ γλωσσῶν, καὶ ἐθνῶν, τὸ πτῶμα αὐτῶν ἡμέρας τρεῖς καὶ ἥμισυ, καὶ τὰ πτώματα αὐτῶν οὐκ ἀφίουσιν τεθῆναι εἰς μνῆμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 10, 'Καὶ οἱ κατοικοῦντες ἐπὶ τῆς γῆς χαίρουσιν ἐπʼ αὐτοῖς, καὶ εὐφραίνονται, καὶ δῶρα πέμψουσιν ἀλλήλοις, ὅτι οὗτοι οἱ δύο προφῆται ἐβασάνισαν τοὺς κατοικοῦντας ἐπὶ τῆς γῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 11, '¶Καὶ μετὰ τὰς τρεῖς ἡμέρας καὶ ἥμισυ, πνεῦμα ζωῆς ἐκ τοῦ  ̊Θεοῦ εἰσῆλθεν εἰς αὐτοῖς, καὶ ἔστησαν ἐπὶ τοὺς πόδας αὐτῶν, καὶ φόβος μέγας ἐπέπεσεν ἐπὶ τοὺς θεωροῦντας αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 12, 'Καὶ ἤκουσαν φωνὴν μεγάλην ἐκ τοῦ οὐρανοῦ, λέγουσαν αὐτοῖς, “Ἀνάβατε ὧδε”. Καὶ ἀνέβησαν εἰς τὸν οὐρανὸν ἐν τῇ νεφέλῃ, καὶ ἐθεώρησαν αὐτοὺς οἱ ἐχθροὶ αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 13, 'Καὶ ἐν ἐκείνῃ τῇ ὥρᾳ ἐγένετο σεισμὸς μέγας, καὶ τὸ δέκατον τῆς πόλεως ἔπεσεν, καὶ ἀπεκτάνθησαν ἐν τῷ σεισμῷ, ὀνόματα ἀνθρώπων χιλιάδες ἑπτά, καὶ οἱ λοιποὶ ἔμφοβοι ἐγένοντο, καὶ ἔδωκαν δόξαν τῷ  ̊Θεῷ τοῦ οὐρανοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 14, '¶Ἡ οὐαὶ ἡ δευτέρα ἀπῆλθεν· ἰδοὺ, ἡ οὐαὶ ἡ τρίτη ἔρχεται ταχύ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 15, '¶Καὶ ὁ ἕβδομος ἄγγελος ἐσάλπισεν, καὶ ἐγένοντο φωναὶ μεγάλαι ἐν τῷ οὐρανῷ λέγουσαι, “Ἐγένετο ἡ βασιλεία τοῦ κόσμου τοῦ  ̊Κυρίου ἡμῶν καὶ τοῦ  ̊Χριστοῦ αὐτοῦ, καὶ βασιλεύσει εἰς τοὺς αἰῶνας τῶν αἰώνων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 16, '¶Καὶ οἱ εἴκοσι τέσσαρες πρεσβύτεροι οἱ ἐνώπιον τοῦ  ̊Θεοῦ κάθηνται ἐπὶ τοὺς θρόνους αὐτῶν, ἔπεσαν ἐπὶ τὰ πρόσωπα αὐτῶν, καὶ προσεκύνησαν τῷ  ̊Θεῷ');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 17, 'λέγοντες, “Εὐχαριστοῦμέν σοι,  ̊Κύριε, ὁ  ̊Θεός ὁ Παντοκράτωρ, ὁ ὢν, καὶ ὁ ἦν, καὶ ὅτι εἴληφας τὴν δύναμίν σου τὴν μεγάλην, καὶ ἐβασίλευσας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 18, 'Καὶ τὰ ἔθνη ὠργίσθησαν, καὶ ἦλθεν ἡ ὀργή σου, καὶ ὁ καιρὸς τῶν νεκρῶν κριθῆναι, καὶ δοῦναι τὸν μισθὸν τοῖς δούλοις σου, τοῖς προφήταις, καὶ τοῖς ἁγίοις, καὶ τοῖς φοβουμένοις τὸ ὄνομά σου, τοὺς μικροὺς καὶ τοὺς μεγάλους, καὶ διαφθεῖραι τοὺς διαφθείροντας τὴν γῆν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 11, 19, '¶Καὶ ἠνοίγη ὁ ναὸς τοῦ  ̊Θεοῦ ὁ ἐν τῷ οὐρανῷ, καὶ ὤφθη ἡ κιβωτὸς τῆς διαθήκης αὐτοῦ ἐν τῷ ναῷ αὐτοῦ, καὶ ἐγένοντο ἀστραπαὶ, καὶ φωναὶ, καὶ βρονταὶ, καὶ σεισμὸς, καὶ χάλαζα μεγάλη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 1, '¶Καὶ σημεῖον μέγα ὤφθη ἐν τῷ οὐρανῷ: γυνὴ περιβεβλημένη τὸν ἥλιον, καὶ ἡ σελήνη ὑποκάτω τῶν ποδῶν αὐτῆς, καὶ ἐπὶ τῆς κεφαλῆς αὐτῆς στέφανος ἀστέρων δώδεκα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 2, 'καὶ ἐν γαστρὶ ἔχουσα, καὶ κράζει ὠδίνουσα, καὶ βασανιζομένη τεκεῖν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 3, 'Καὶ ὤφθη ἄλλο σημεῖον ἐν τῷ οὐρανῷ: καὶ ἰδοὺ, δράκων πυρρὸς μέγας ἔχων κεφαλὰς ἑπτὰ, καὶ κέρατα δέκα, καὶ ἐπὶ τὰς κεφαλὰς αὐτοῦ ἑπτὰ διαδήματα,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 4, 'καὶ ἡ οὐρὰ αὐτοῦ σύρει τὸ τρίτον τῶν ἀστέρων τοῦ οὐρανοῦ, καὶ ἔβαλεν αὐτοὺς εἰς τὴν γῆν. Καὶ ὁ δράκων ἕστηκεν ἐνώπιον τῆς γυναικὸς τῆς μελλούσης τεκεῖν, ἵνα ὅταν τέκῃ, τὸ τέκνον αὐτῆς καταφάγῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 5, 'Καὶ ἔτεκεν υἱόν ἄρσεν, ὃς μέλλει ποιμαίνειν πάντα τὰ ἔθνη ἐν ῥάβδῳ σιδηρᾷ· καὶ ἡρπάσθη τὸ τέκνον αὐτῆς πρὸς τὸν  ̊Θεὸν, καὶ πρὸς τὸν θρόνον αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 6, 'Καὶ ἡ γυνὴ ἔφυγεν εἰς τὴν ἔρημον, ὅπου ἔχει ἐκεῖ τόπον ἡτοιμασμένον ἀπὸ τοῦ  ̊Θεοῦ, ἵνα ἐκεῖ τρέφωσιν αὐτὴν ἡμέρας χιλίας διακοσίας ἑξήκοντα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 7, '¶Καὶ ἐγένετο πόλεμος ἐν τῷ οὐρανῷ, ὁ Μιχαὴλ καὶ οἱ ἄγγελοι αὐτοῦ τοῦ πολεμῆσαι μετὰ τοῦ δράκοντος. Καὶ ὁ δράκων ἐπολέμησεν καὶ οἱ ἄγγελοι αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 8, 'καὶ οὐκ ἴσχυσαν, οὐδὲ τόπος εὑρέθη αὐτῶν ἔτι ἐν τῷ οὐρανῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 9, 'Καὶ ἐβλήθη ὁ δράκων ὁ μέγας, ὁ ὄφις ὁ ἀρχαῖος, ὁ καλούμενος, Διάβολος, καὶ ὁ Σατανᾶς, ὁ πλανῶν τὴν οἰκουμένην ὅλην· ἐβλήθη εἰς τὴν γῆν, καὶ οἱ ἄγγελοι αὐτοῦ μετʼ αὐτοῦ ἐβλήθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 10, '¶Καὶ ἤκουσα φωνὴν μεγάλην ἐν τῷ οὐρανῷ λέγουσαν, “Ἄρτι ἐγένετο ἡ σωτηρία, καὶ ἡ δύναμις, καὶ ἡ Βασιλεία τοῦ  ̊Θεοῦ ἡμῶν, καὶ ἡ ἐξουσία τοῦ  ̊Χριστοῦ αὐτοῦ, ὅτι ἐβλήθη ὁ κατήγορος τῶν ἀδελφῶν ἡμῶν, ὁ κατηγορῶν αὐτοὺς ἐνώπιον τοῦ  ̊Θεοῦ ἡμῶν, ἡμέρας καὶ νυκτός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 11, 'Καὶ αὐτοὶ ἐνίκησαν αὐτὸν διὰ τὸ αἷμα τοῦ Ἀρνίου, καὶ διὰ τὸν λόγον τῆς μαρτυρίας αὐτῶν, καὶ οὐκ ἠγάπησαν τὴν ψυχὴν αὐτῶν ἄχρι θανάτου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 12, 'Διὰ τοῦτο εὐφραίνεσθε, οὐρανοὶ, καὶ οἱ ἐν αὐτοῖς σκηνοῦντες! οὐαὶ τὴν γῆν καὶ τὴν θάλασσαν, ὅτι κατέβη ὁ διάβολος πρὸς ὑμᾶς, ἔχων θυμὸν μέγαν, εἰδὼς ὅτι ὀλίγον καιρὸν ἔχει.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 13, '¶Καὶ ὅτε εἶδεν ὁ δράκων ὅτι ἐβλήθη εἰς τὴν γῆν, ἐδίωξεν τὴν γυναῖκα, ἥτις ἔτεκεν τὸν ἄρσενα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 14, 'Καὶ ἐδόθησαν τῇ γυναικὶ δύο πτέρυγες τοῦ ἀετοῦ τοῦ μεγάλου, ἵνα πέτηται εἰς τὴν ἔρημον εἰς τὸν τόπον αὐτῆς, ὅπου τρέφεται ἐκεῖ καιρὸν, καὶ καιροὺς, καὶ ἥμισυ καιροῦ, ἀπὸ προσώπου τοῦ ὄφεως.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 15, 'Καὶ ἔβαλεν ὁ ὄφις ἐκ τοῦ στόματος αὐτοῦ ὀπίσω τῆς γυναικὸς, ὕδωρ ὡς ποταμόν, ἵνα αὐτὴν ποταμοφόρητον ποιήσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 16, 'Καὶ ἐβοήθησεν ἡ γῆ τῇ γυναικί, καὶ ἤνοιξεν ἡ γῆ τὸ στόμα αὐτῆς, καὶ κατέπιεν τὸν ποταμὸν, ὃν ἔβαλεν ὁ δράκων ἐκ τοῦ στόματος αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 17, 'Καὶ ὠργίσθη ὁ δράκων ἐπὶ τῇ γυναικί, καὶ ἀπῆλθεν ποιῆσαι πόλεμον μετὰ τῶν λοιπῶν τοῦ σπέρματος αὐτῆς, τῶν τηρούντων τὰς ἐντολὰς τοῦ  ̊Θεοῦ, καὶ ἐχόντων τὴν μαρτυρίαν  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 12, 18, 'Καὶ ἐστάθη ἐπὶ τὴν ἄμμον τῆς θαλάσσης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 1, '¶Καὶ εἶδον ἐκ τῆς θαλάσσης θηρίον ἀναβαῖνον, ἔχον κέρατα δέκα καὶ κεφαλὰς ἑπτά, καὶ ἐπὶ τῶν κεράτων αὐτοῦ δέκα διαδήματα, καὶ ἐπὶ τὰς κεφαλὰς αὐτοῦ ὀνόμα βλασφημίας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 2, 'Καὶ τὸ θηρίον ὃ εἶδον ἦν ὅμοιον παρδάλει, καὶ οἱ πόδες αὐτοῦ ὡς ἄρκου, καὶ τὸ στόμα αὐτοῦ ὡς στόμα λέοντος. Καὶ ἔδωκεν αὐτῷ ὁ δράκων τὴν δύναμιν αὐτοῦ, καὶ τὸν θρόνον αὐτοῦ, καὶ ἐξουσίαν μεγάλην.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 3, 'Καὶ μίαν ἐκ τῶν κεφαλῶν αὐτοῦ ὡς ἐσφαγμένην εἰς θάνατον, καὶ ἡ πληγὴ τοῦ θανάτου αὐτοῦ ἐθεραπεύθη. Καὶ ἐθαυμάσθη ὅλη ἡ γῆ ὀπίσω τοῦ θηρίου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 4, 'καὶ προσεκύνησαν τῷ δράκοντι, ὅτι ἔδωκεν τὴν ἐξουσίαν τῷ θηρίῳ, καὶ προσεκύνησαν τῷ θηρίῳ λέγοντες, “Τίς ὅμοιος τῷ θηρίῳ, καὶ τίς δύναται πολεμῆσαι μετʼ αὐτοῦ;”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 5, '¶Καὶ ἐδόθη αὐτῷ στόμα λαλοῦν μεγάλα καὶ βλασφημίας, καὶ ἐδόθη αὐτῷ ἐξουσία ποιῆσαι μῆνας τεσσεράκοντα δύο.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 6, 'Καὶ ἤνοιξε τὸ στόμα αὐτοῦ εἰς βλασφημίας πρὸς τὸν  ̊Θεόν, βλασφημῆσαι τὸ ὄνομα αὐτοῦ, καὶ τὴν σκηνὴν αὐτοῦ, τοὺς ἐν τῷ οὐρανῷ σκηνοῦντας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 7, 'Καὶ ἐδόθη αὐτῷ ἐξουσία ἐπὶ πᾶσαν φυλὴν, καὶ λαὸν, καὶ γλῶσσαν, καὶ ἔθνος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 8, 'Καὶ προσκυνήσουσιν αὐτὸν πάντες οἱ κατοικοῦντες ἐπὶ τῆς γῆς, ὧν οὐ γέγραπται τὸ ὄνομα αὐτοῦ ἐν βιβλίῳ τῆς ζωῆς τοῦ Ἀρνίου, τοῦ ἐσφαγμένου ἀπὸ καταβολῆς κόσμου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 9, '¶Εἴ τις ἔχει οὖς, ἀκουσάτω.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 10, 'Εἴ τις εἰς αἰχμαλωσίαν, ὑπάγει· εἴ τις ἐν μαχαίρῃ ἀποκτείνει, δεῖ αὐτὸν ἐν μαχαίρῃ ἀποκτανθῆναι. Ὧδέ ἐστιν ἡ ὑπομονὴ καὶ ἡ πίστις τῶν ἁγίων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 11, '¶Καὶ εἶδον ἄλλο θηρίον ἀναβαῖνον ἐκ τῆς γῆς, καὶ εἶχεν κέρατα δύο ὅμοια ἀρνίῳ, καὶ ἐλάλει ὡς δράκων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 12, 'Καὶ τὴν ἐξουσίαν τοῦ πρώτου θηρίου πᾶσαν ποιεῖ ἐνώπιον αὐτοῦ. Καὶ ποιεῖ τὴν γῆν καὶ τοὺς ἐν αὐτῇ κατοικοῦντας, ἵνα προσκυνήσουσιν τὸ θηρίον τὸ πρῶτον, οὗ ἐθεραπεύθη ἡ πληγὴ τοῦ θανάτου αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 13, 'Καὶ ποιεῖ σημεῖα μεγάλα, ἵνα καὶ πῦρ ποιῇ ἐκ τοῦ οὐρανοῦ καταβαίνειν εἰς τὴν γῆν ἐνώπιον τῶν ἀνθρώπων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 14, 'Καὶ πλανᾷ τοὺς κατοικοῦντας ἐπὶ τῆς γῆς, διὰ τὰ σημεῖα ἃ ἐδόθη αὐτῷ ποιῆσαι ἐνώπιον τοῦ θηρίου, λέγων τοῖς κατοικοῦσιν ἐπὶ τῆς γῆς, ποιῆσαι εἰκόνα τῷ θηρίῳ, ὃς ἔχει τὴν πληγὴν τῆς μαχαίρης, καὶ ἔζησεν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 15, 'Καὶ ἐδόθη αὐτῷ δοῦναι πνεῦμα τῇ εἰκόνι τοῦ θηρίου, ἵνα καὶ λαλήσῃ ἡ εἰκὼν τοῦ θηρίου, καὶ ποιήσει ὅσοι ἂν μὴ προσκυνήσουσιν τῇ εἰκόνι τοῦ θηρίου ἀποκτανθῶσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 16, 'Καὶ ποιεῖ πάντας, τοὺς μικροὺς καὶ τοὺς μεγάλους, καὶ τοὺς πλουσίους καὶ τοὺς πτωχούς, καὶ τοὺς ἐλευθέρους καὶ τοὺς δούλους, ἵνα δῶσιν αὐτοῖς χάραγμα ἐπὶ τῆς χειρὸς αὐτῶν τῆς δεξιᾶς, ἢ ἐπὶ τὸ μέτωπον αὐτῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 17, 'καὶ ἵνα μή τις δύνηται ἀγοράσαι ἢ πωλῆσαι, εἰ μὴ ὁ ἔχων τὸ χάραγμα, τὸ ὄνομα τοῦ θηρίου, ἢ τὸν ἀριθμὸν τοῦ ὀνόματος αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 13, 18, 'Ὧδε ἡ σοφία ἐστίν: ὁ ἔχων νοῦν ψηφισάτω τὸν ἀριθμὸν τοῦ θηρίου, ἀριθμὸς γὰρ ἀνθρώπου ἐστίν, καὶ ὁ ἀριθμὸς αὐτοῦ ἐστὶν ἑξακόσιοι ἑξήκοντα ἕξ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 1, '¶Καὶ εἶδον, καὶ ἰδοὺ, τὸ Ἀρνίον ἑστὸς ἐπὶ τὸ Ὄρος Σιών, καὶ μετʼ αὐτοῦ ἑκατὸν τεσσεράκοντα τέσσαρες χιλιάδες ἔχουσαι τὸ ὄνομα αὐτοῦ, καὶ τὸ ὄνομα τοῦ Πατρὸς αὐτοῦ, γεγραμμένον ἐπὶ τῶν μετώπων αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 2, 'Καὶ ἤκουσα φωνὴν ἐκ τοῦ οὐρανοῦ, ὡς φωνὴν ὑδάτων πολλῶν, καὶ ὡς φωνὴν βροντῆς μεγάλης, καὶ ἡ φωνὴ ἣν ἤκουσα ὡς κιθαρῳδῶν κιθαριζόντων ἐν ταῖς κιθάραις αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 3, 'Καὶ ᾄδουσιν ᾠδὴν καινὴν ἐνώπιον τοῦ θρόνου, καὶ ἐνώπιον τῶν τεσσάρων ζῴων, καὶ τῶν πρεσβυτέρων. Καὶ οὐδεὶς ἐδύνατο μαθεῖν τὴν ᾠδὴν, εἰ μὴ αἱ ἑκατὸν τεσσεράκοντα τέσσαρες χιλιάδες, οἱ ἠγορασμένοι ἀπὸ τῆς γῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 4, 'Οὗτοί εἰσιν οἳ μετὰ γυναικῶν οὐκ ἐμολύνθησαν, παρθένοι γάρ εἰσιν. Οὗτοι οἱ ἀκολουθοῦντες τῷ Ἀρνίῳ ὅπου ἂν ὑπάγει. Οὗτοι ἠγοράσθησαν ἀπὸ τῶν ἀνθρώπων ἀπαρχὴ τῷ  ̊Θεῷ καὶ τῷ Ἀρνίῳ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 5, 'καὶ ἐν τῷ στόματι αὐτῶν οὐχ εὑρέθη ψεῦδος, ἄμωμοί γάρ εἰσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 6, '¶Καὶ εἶδον ἄλλον ἄγγελον πετόμενον ἐν μεσουρανήματι, ἔχοντα εὐαγγέλιον αἰώνιον εὐαγγελίσαι ἐπὶ τοὺς κατοικοῦντας ἐπὶ τῆς γῆς, καὶ ἐπὶ πᾶν ἔθνος, καὶ φυλὴν, καὶ γλῶσσαν, καὶ λαόν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 7, 'λέγων ἐν φωνῇ μεγάλῃ, “Φοβήθητε τὸν  ̊Θεὸν, καὶ δότε αὐτῷ δόξαν, ὅτι ἦλθεν ἡ ὥρα τῆς κρίσεως αὐτοῦ, καὶ προσκυνήσατε τῷ ποιήσαντι τὸν οὐρανὸν, καὶ τὴν γῆν, καὶ θάλασσαν, καὶ πηγὰς ὑδάτων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 8, '¶Καὶ ἄλλος δεύτερος ἄγγελος ἠκολούθησεν λέγων, “Ἔπεσεν, ἔπεσεν Βαβυλὼν ἡ μεγάλη, ἣ ἐκ τοῦ οἴνου τοῦ θυμοῦ τῆς πορνείας αὐτῆς, πεπότικεν πάντα τὰ ἔθνη.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 9, '¶Καὶ ἄλλος ἄγγελος τρίτος ἠκολούθησεν αὐτοῖς, λέγων ἐν φωνῇ μεγάλῃ, “Εἴ τις προσκυνεῖ τὸ θηρίον καὶ τὴν εἰκόνα αὐτοῦ, καὶ λαμβάνει χάραγμα ἐπὶ τοῦ μετώπου αὐτοῦ, ἢ ἐπὶ τὴν χεῖρα αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 10, 'καὶ αὐτὸς πίεται ἐκ τοῦ οἴνου τοῦ θυμοῦ τοῦ  ̊Θεοῦ, τοῦ κεκερασμένου ἀκράτου ἐν τῷ ποτηρίῳ τῆς ὀργῆς αὐτοῦ, καὶ βασανισθήσεται ἐν πυρὶ καὶ θείῳ ἐνώπιον τῶν ἀγγέλων ἁγίων καὶ ἐνώπιον τοῦ Ἀρνίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 11, 'Καὶ ὁ καπνὸς τοῦ βασανισμοῦ αὐτῶν εἰς αἰῶνας αἰώνων ἀναβαίνει, καὶ οὐκ ἔχουσιν ἀνάπαυσιν, ἡμέρας καὶ νυκτός, οἱ προσκυνοῦντες τὸ θηρίον καὶ τὴν εἰκόνα αὐτοῦ, καὶ εἴ τις λαμβάνει τὸ χάραγμα τοῦ ὀνόματος αὐτοῦ.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 12, '¶Ὧδε ἡ ὑπομονὴ τῶν ἁγίων ἐστίν, οἱ τηροῦντες τὰς ἐντολὰς τοῦ  ̊Θεοῦ, καὶ τὴν πίστιν  ̊Ἰησοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 13, '¶Καὶ ἤκουσα φωνῆς ἐκ τοῦ οὐρανοῦ λεγούσης, “Γράψον, ‘Μακάριοι οἱ νεκροὶ οἱ ἐν  ̊Κυρίῳ ἀποθνῄσκοντες ἀπʼ ἄρτι.’” “Ναί”, Λέγει τὸ  ̊Πνεῦμα, “ἵνα ἀναπαήσονται ἐκ τῶν κόπων αὐτῶν, τὰ γὰρ ἔργα αὐτῶν ἀκολουθεῖ μετʼ αὐτῶν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 14, '¶Καὶ εἶδον, καὶ “ἰδοὺ, νεφέλη λευκή, καὶ ἐπὶ τὴν νεφέλην καθήμενον ὅμοιον υἱὸν Ἀνθρώπου”, ἔχων ἐπὶ τῆς κεφαλῆς αὐτοῦ στέφανον χρυσοῦν, καὶ ἐν τῇ χειρὶ αὐτοῦ δρέπανον ὀξύ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 15, 'Καὶ ἄλλος ἄγγελος ἐξῆλθεν ἐκ τοῦ ναοῦ, κράζων ἐν φωνῇ μεγάλῃ τῷ καθημένῳ ἐπὶ τῆς νεφέλης, “Πέμψον τὸ δρέπανόν σου καὶ θέρισον, ὅτι ἦλθεν ἡ ὥρα θερίσαι, ὅτι ἐξηράνθη ὁ θερισμὸς τῆς γῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 16, 'Καὶ ἔβαλεν ὁ καθήμενος ἐπὶ τῆς νεφέλης τὸ δρέπανον αὐτοῦ ἐπὶ τὴν γῆν, καὶ ἐθερίσθη ἡ γῆ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 17, '¶Καὶ ἄλλος ἄγγελος ἐξῆλθεν ἐκ τοῦ ναοῦ τοῦ ἐν τῷ οὐρανῷ, ἔχων καὶ αὐτὸς δρέπανον ὀξύ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 18, 'Καὶ ἄλλος ἄγγελος ἐκ τοῦ θυσιαστηρίου, ὁ ἔχων ἐξουσίαν ἐπὶ τοῦ πυρός, καὶ ἐφώνησεν φωνῇ μεγάλῃ τῷ ἔχοντι τὸ δρέπανον τὸ ὀξὺ λέγων, “Πέμψον σου τὸ δρέπανον τὸ ὀξὺ, καὶ τρύγησον τοὺς βότρυας τῆς ἀμπέλου τῆς γῆς, ὅτι ἤκμασαν αἱ σταφυλαὶ αὐτῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 19, 'Καὶ ἔβαλεν ὁ ἄγγελος τὸ δρέπανον αὐτοῦ εἰς τὴν γῆν, καὶ ἐτρύγησεν τὴν ἄμπελον τῆς γῆς, καὶ ἔβαλεν εἰς τὴν ληνὸν τοῦ θυμοῦ τοῦ  ̊Θεοῦ τὸν μέγαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 14, 20, 'Καὶ ἐπατήθη ἡ ληνὸς ἔξωθεν τῆς πόλεως, καὶ ἐξῆλθεν αἷμα ἐκ τῆς ληνοῦ, ἄχρι τῶν χαλινῶν τῶν ἵππων ἀπὸ σταδίων χιλίων ἑξακοσίων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 15, 1, '¶Καὶ εἶδον ἄλλο σημεῖον ἐν τῷ οὐρανῷ, μέγα καὶ θαυμαστόν, ἀγγέλους ἑπτὰ ἔχοντας πληγὰς ἑπτὰ τὰς ἐσχάτας, ὅτι ἐν αὐταῖς ἐτελέσθη ὁ θυμὸς τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 15, 2, '¶Καὶ εἶδον ὡς θάλασσαν ὑαλίνην μεμιγμένην πυρί, καὶ τοὺς νικῶντας ἐκ τοῦ θηρίου, καὶ ἐκ τῆς εἰκόνος αὐτοῦ, καὶ ἐκ τοῦ ἀριθμοῦ τοῦ ὀνόματος αὐτοῦ, ἑστῶτας ἐπὶ τὴν θάλασσαν τὴν ὑαλίνην, ἔχοντας κιθάρας τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 15, 3, 'Καὶ ᾄδουσιν τὴν ᾠδὴν Μωϋσέως, τοῦ δούλου τοῦ  ̊Θεοῦ, καὶ τὴν ᾠδὴν τοῦ Ἀρνίου λέγοντες, “Μεγάλα καὶ θαυμαστὰ τὰ ἔργα σου,  ̊Κύριε ὁ  ̊Θεός ὁ Παντοκράτωρ! Δίκαιαι καὶ ἀληθιναὶ αἱ ὁδοί σου, ὁ Βασιλεὺς τῶν αἰώνων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 15, 4, 'Τίς οὐ μὴ φοβηθῇ,  ̊Κύριε, καὶ δοξάσει τὸ ὄνομά σου, ὅτι μόνος ὅσιος; ‘Ὅτι πάντα τὰ ἔθνη ἥξουσιν καὶ προσκυνήσουσιν ἐνώπιόν σου’, ὅτι τὰ δικαιώματά σου ἐφανερώθησαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 15, 5, '¶Καὶ μετὰ ταῦτα εἶδον, καὶ ἠνοίγη ὁ ναὸς τῆς σκηνῆς τοῦ μαρτυρίου ἐν τῷ οὐρανῷ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 15, 6, 'καὶ ἐξῆλθον οἱ ἑπτὰ ἄγγελοι οἱ ἔχοντες τὰς ἑπτὰ πληγὰς ἐκ τοῦ ναοῦ, ἐνδεδυμένοι λίθον καθαρὸν λαμπρὸν, καὶ περιεζωσμένοι περὶ τὰ στήθη ζώνας χρυσᾶς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 15, 7, 'Καὶ ἓν ἐκ τῶν τεσσάρων ζῴων ἔδωκεν τοῖς ἑπτὰ ἀγγέλοις ἑπτὰ φιάλας χρυσᾶς, γεμούσας τοῦ θυμοῦ τοῦ  ̊Θεοῦ, τοῦ ζῶντος εἰς τοὺς αἰῶνας τῶν αἰώνων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 15, 8, 'Καὶ ἐγεμίσθη ὁ ναὸς καπνοῦ ἐκ τῆς δόξης τοῦ  ̊Θεοῦ, καὶ ἐκ τῆς δυνάμεως αὐτοῦ, καὶ οὐδεὶς ἐδύνατο εἰσελθεῖν εἰς τὸν ναὸν, ἄχρι τελεσθῶσιν αἱ ἑπτὰ πληγαὶ τῶν ἑπτὰ ἀγγέλων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 15, 9, '');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 1, '¶Καὶ ἤκουσα μεγάλης φωνῆς ἐκ τοῦ ναοῦ, λεγούσης τοῖς ἑπτὰ ἀγγέλοις, “Ὑπάγετε καὶ ἐκχέετε τὰς ἑπτὰ φιάλας τοῦ θυμοῦ τοῦ  ̊Θεοῦ εἰς τὴν γῆν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 2, '¶Καὶ ἀπῆλθεν ὁ πρῶτος, καὶ ἐξέχεεν τὴν φιάλην αὐτοῦ εἰς τὴν γῆν, καὶ ἐγένετο ἕλκος κακὸν καὶ πονηρὸν, ἐπὶ τοὺς ἀνθρώπους τοὺς ἔχοντας τὸ χάραγμα τοῦ θηρίου, καὶ τοὺς προσκυνοῦντας τῇ εἰκόνι αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 3, '¶Καὶ ὁ δεύτερος ἐξέχεεν τὴν φιάλην αὐτοῦ εἰς τὴν θάλασσαν, καὶ ἐγένετο αἷμα ὡς νεκροῦ, καὶ πᾶσα ψυχὴ ζωῆς ἀπέθανεν τὰ ἐν τῇ θαλάσσῃ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 4, '¶Καὶ ὁ τρίτος ἐξέχεεν τὴν φιάλην αὐτοῦ εἰς τοὺς ποταμοὺς καὶ τὰς πηγὰς τῶν ὑδάτων, καὶ ἐγένετο αἷμα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 5, 'Καὶ ἤκουσα τοῦ ἀγγέλου τῶν ὑδάτων λέγοντος, “Δίκαιος εἶ, ὁ ὢν, καὶ ὁ ἦν, ὅσιος, ὅτι ταῦτα ἔκρινας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 6, 'Ὅτι αἷμα ἁγίων καὶ προφητῶν ἐξέχεαν, καὶ αἷμα αὐτοῖς δέδωκας πεῖν· ἄξιοί εἰσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 7, 'Καὶ ἤκουσα τοῦ θυσιαστηρίου λέγοντος, “Ναί,  ̊Κύριε ὁ  ̊Θεός ὁ Παντοκράτωρ, ἀληθιναὶ καὶ δίκαιαι αἱ κρίσεις σου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 8, '¶Καὶ ὁ τέταρτος ἐξέχεεν τὴν φιάλην αὐτοῦ ἐπὶ τὸν ἥλιον, καὶ ἐδόθη αὐτῷ καυματίσαι τοὺς ἀνθρώπους ἐν πυρί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 9, 'Καὶ ἐκαυματίσθησαν οἱ ἄνθρωποι καῦμα μέγα, καὶ ἐβλασφήμησαν τὸ ὄνομα τοῦ  ̊Θεοῦ, τοῦ ἔχοντος τὴν ἐξουσίαν ἐπὶ τὰς πληγὰς ταύτας, καὶ οὐ μετενόησαν δοῦναι αὐτῷ δόξαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 10, '¶Καὶ ὁ πέμπτος ἐξέχεεν τὴν φιάλην αὐτοῦ ἐπὶ τὸν θρόνον τοῦ θηρίου, καὶ ἐγένετο ἡ βασιλεία αὐτοῦ ἐσκοτωμένη, καὶ ἐμασῶντο τὰς γλώσσας αὐτῶν ἐκ τοῦ πόνου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 11, 'καὶ ἐβλασφήμησαν τὸν  ̊Θεὸν τοῦ οὐρανοῦ ἐκ τῶν πόνων αὐτῶν, καὶ ἐκ τῶν ἑλκῶν αὐτῶν, καὶ οὐ μετενόησαν ἐκ τῶν ἔργων αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 12, '¶Καὶ ὁ ἕκτος ἐξέχεεν τὴν φιάλην αὐτοῦ ἐπὶ τὸν ποταμὸν τὸν μέγαν τὸν Εὐφράτην, καὶ ἐξηράνθη τὸ ὕδωρ αὐτοῦ, ἵνα ἑτοιμασθῇ ἡ ὁδὸς τῶν βασιλέων τῶν ἀπὸ ἀνατολῆς ἡλίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 13, 'Καὶ εἶδον ἐκ τοῦ στόματος τοῦ δράκοντος, καὶ ἐκ τοῦ στόματος τοῦ θηρίου, καὶ ἐκ τοῦ στόματος τοῦ ψευδοπροφήτου, πνεύματα τρία ἀκάθαρτα ὡσει βατράχους·');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 14, 'εἰσὶν γὰρ πνεύματα δαιμονίων ποιοῦντα σημεῖα, ἐκπορεύεσθαι ἐπὶ τοὺς βασιλεῖς τῆς οἰκουμένης ὅλης, συναγαγεῖν αὐτοὺς εἰς τὸν πόλεμον τῆς μεγάλης ἡμέρας τοῦ  ̊Θεοῦ τοῦ Παντοκράτορος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 15, '(“Ἰδοὺ, ἔρχομαι ὡς κλέπτης. Μακάριος ὁ γρηγορῶν καὶ τηρῶν τὰ ἱμάτια αὐτοῦ, ἵνα μὴ γυμνὸς περιπατῇ, καὶ βλέπωσιν τὴν ἀσχημοσύνην αὐτοῦ”.)');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 16, 'Καὶ συνήγαγεν αὐτοὺς εἰς τὸν τόπον τὸν καλούμενον Ἑβραϊστὶ Ἁρμαγεδών.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 17, '¶Καὶ ὁ ἕβδομος ἐξέχεεν τὴν φιάλην αὐτοῦ ἐπὶ τὸν ἀέρα, καὶ ἐξῆλθεν φωνὴ μεγάλη ἐκ τοῦ ναοῦ ἀπὸ τοῦ θρόνου λέγουσα, “Γέγονεν!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 18, 'Καὶ ἐγένοντο ἀστραπαὶ, καὶ φωναὶ, καὶ βρονταί, καὶ σεισμὸς ἐγένετο μέγας, οἷος οὐκ ἐγένετο, ἀφʼ οὗ ἄνθρωπος ἐγένοντο ἐπὶ τῆς γῆς, τηλικοῦτος σεισμὸς οὕτω μέγας.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 19, 'Καὶ ἐγένετο ἡ πόλις ἡ μεγάλη εἰς τρία μέρη, καὶ αἱ πόλεις τῶν ἐθνῶν ἔπεσαν, καὶ Βαβυλὼν ἡ μεγάλη ἐμνήσθη ἐνώπιον τοῦ  ̊Θεοῦ, δοῦναι αὐτῇ τὸ ποτήριον τοῦ οἴνου τοῦ θυμοῦ τῆς ὀργῆς αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 20, 'Καὶ πᾶσα νῆσος ἔφυγεν, καὶ ὄρη οὐχ εὑρέθησαν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 16, 21, 'Καὶ χάλαζα μεγάλη, ὡς ταλαντιαία, καταβαίνει ἐκ τοῦ οὐρανοῦ ἐπὶ τοὺς ἀνθρώπους, καὶ ἐβλασφήμησαν οἱ ἄνθρωποι τὸν  ̊Θεὸν, ἐκ τῆς πληγῆς τῆς χαλάζης, ὅτι μεγάλη ἐστὶν ἡ πληγὴ αὐτῆς σφόδρα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 1, '¶Καὶ ἦλθεν εἷς ἐκ τῶν ἑπτὰ ἀγγέλων τῶν ἐχόντων τὰς ἑπτὰ φιάλας, καὶ ἐλάλησεν μετʼ ἐμοῦ λέγων, “Δεῦρο, δείξω σοι τὸ κρίμα τῆς πόρνης τῆς μεγάλης τῆς καθημένης ἐπὶ ὑδάτων πολλῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 2, 'μεθʼ ἧς ἐπόρνευσαν οἱ βασιλεῖς τῆς γῆς, καὶ ἐμεθύσθησαν οἱ κατοικοῦντες τὴν γῆν ἐκ τοῦ οἴνου τῆς πορνείας αὐτῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 3, 'Καὶ ἀπήνεγκέν με εἰς ἔρημον ἐν  ̊Πνεύματι. Καὶ εἶδον γυναῖκα καθημένην ἐπὶ θηρίον κόκκινον, γέμοντα ὀνόματα βλασφημίας, ἔχων κεφαλὰς ἑπτὰ καὶ κέρατα δέκα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 4, 'Καὶ ἡ γυνὴ ἦν περιβεβλημένη πορφυροῦν καὶ κόκκινον, καὶ κεχρυσωμένη χρυσίῳ, καὶ λίθῳ τιμίῳ, καὶ μαργαρίταις, ἔχουσα ποτήριον χρυσοῦν ἐν τῇ χειρὶ αὐτῆς, γέμον βδελυγμάτων καὶ τὰ ἀκάθαρτα τῆς πορνείας αὐτῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 5, 'καὶ ἐπὶ τὸ μέτωπον αὐτῆς ὄνομα γεγραμμένον, “Μυστήριον Βαβυλὼν ἡ Μεγάλη, ἡ μήτηρ τῶν πορνῶν, καὶ τῶν βδελυγμάτων τῆς γῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 6, 'Καὶ εἶδα τὴν γυναῖκα μεθύουσαν ἐκ τοῦ αἵματος τῶν ἁγίων, καὶ ἐκ τοῦ αἵματος τῶν μαρτύρων  ̊Ἰησοῦ. ¶Καὶ ἐθαύμασα, ἰδὼν αὐτὴν θαῦμα μέγα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 7, 'Καὶ εἶπέν μοι ὁ ἄγγελος, “Διὰ τί ἐθαύμασας; Ἐγὼ ἐρῶ σοι τὸ μυστήριον τῆς γυναικὸς, καὶ τοῦ θηρίου τοῦ βαστάζοντος αὐτήν, τοῦ ἔχοντος τὰς ἑπτὰ κεφαλὰς καὶ τὰ δέκα κέρατα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 8, 'Τὸ θηρίον ὃ εἶδες ἦν, καὶ οὐκ ἔστιν, καὶ μέλλει ἀναβαίνειν ἐκ τῆς Ἀβύσσου, καὶ εἰς ἀπώλειαν ὑπάγειν. Καὶ θαυμάσονται οἱ κατοικοῦντες ἐπὶ τῆς γῆς, ὧν οὐ γέγραπται τὰ ὀνόματα ἐπὶ τὸ βιβλίον τῆς ζωῆς ἀπὸ καταβολῆς κόσμου, βλεπόντων τὸ θηρίον, ὅτι ἦν καὶ οὐκ ἔστιν καὶ παρέσται.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 9, '¶Ὧδε ὁ νοῦς ὁ ἔχων σοφίαν: αἱ ἑπτὰ κεφαλαὶ ἑπτὰ ὄρη εἰσίν, ὅπου ἡ γυνὴ κάθηται ἐπʼ αὐτῶν. Καὶ βασιλεῖς ἑπτά εἰσιν:');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 10, 'οἱ πέντε ἔπεσαν, ὁ εἷς ἔστιν, ὁ ἄλλος οὔπω ἦλθεν, καὶ ὅταν ἔλθῃ, ὀλίγον αὐτὸν δεῖ μεῖναι');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 11, 'καὶ τὸ θηρίον ὃ ἦν, καὶ οὐκ ἔστιν, καὶ αὐτὸς ὄγδοός ἐστιν, καὶ ἐκ τῶν ἑπτά ἐστιν, καὶ εἰς ἀπώλειαν ὑπάγει.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 12, 'Καὶ τὰ δέκα κέρατα ἃ εἶδες, δέκα βασιλεῖς εἰσιν, οἵτινες βασιλείαν οὕτω ἔλαβον, ἀλλὰ ἐξουσίαν ὡς βασιλεῖς μίαν ὥραν λαμβάνουσιν μετὰ τοῦ θηρίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 13, 'Οὗτοι μίαν γνώμην ἔχουσιν, καὶ τὴν δύναμιν καὶ τὴν ἐξουσίαν αὐτῶν τῷ θηρίῳ διδόασιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 14, 'Οὗτοι μετὰ τοῦ Ἀρνίου πολεμήσουσιν, καὶ τὸ Ἀρνίον νικήσει αὐτούς, ὅτι  ̊Κύριος κυρίων ἐστὶν καὶ Βασιλεὺς βασιλέων, καὶ οἱ μετʼ αὐτοῦ, κλητοὶ, καὶ ἐκλεκτοὶ, καὶ πιστοί.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 15, '¶Καὶ λέγει μοι, “Τὰ ὕδατα ἃ εἶδες, οὗ ἡ πόρνη κάθηται, λαοὶ καὶ ὄχλοι εἰσὶν, καὶ ἔθνη καὶ γλῶσσαι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 16, 'Καὶ τὰ δέκα κέρατα ἃ εἶδες καὶ τὸ θηρίον, οὗτοι μισήσουσιν τὴν πόρνην, καὶ ἠρημωμένην ποιήσουσιν αὐτὴν καὶ γυμνήν, καὶ τὰς σάρκας αὐτῆς φάγονται, καὶ αὐτὴν κατακαύσουσιν ἐν πυρί.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 17, 'Ὁ γὰρ  ̊Θεὸς ἔδωκεν εἰς τὰς καρδίας αὐτῶν ποιῆσαι τὴν γνώμην αὐτοῦ, καὶ ποιῆσαι μίαν γνώμην, καὶ δοῦναι τὴν βασιλείαν αὐτῶν τῷ θηρίῳ, ἄχρι τελεσθήσονται οἱ λόγοι τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 17, 18, 'Καὶ ἡ γυνὴ ἣν εἶδες ἔστιν ἡ πόλις ἡ μεγάλη, ἡ ἔχουσα βασιλείαν ἐπὶ τῶν βασιλέων τῆς γῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 1, '¶Μετὰ ταῦτα εἶδον ἄλλον ἄγγελον καταβαίνοντα ἐκ τοῦ οὐρανοῦ, ἔχοντα ἐξουσίαν μεγάλην, καὶ ἡ γῆ ἐφωτίσθη ἐκ τῆς δόξης αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 2, 'Καὶ ἔκραξεν ἐν ἰσχυρᾷ φωνῇ λέγων, “Ἔπεσεν, ἔπεσεν Βαβυλὼν ἡ μεγάλη! Καὶ ἐγένετο κατοικητήριον δαιμονίων, καὶ φυλακὴ παντὸς πνεύματος ἀκαθάρτου, καὶ φυλακὴ παντὸς ὀρνέου ἀκαθάρτου, καὶ μεμισημένου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 3, 'Ὅτι ἐκ τοῦ οἴνου τοῦ θυμοῦ τῆς πορνείας αὐτῆς, πέπτωκαν πάντα τὰ ἔθνη, καὶ οἱ βασιλεῖς τῆς γῆς μετʼ αὐτῆς ἐπόρνευσαν, καὶ οἱ ἔμποροι τῆς γῆς ἐκ τῆς δυνάμεως τοῦ στρήνους αὐτῆς ἐπλούτησαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 4, '¶Καὶ ἤκουσα ἄλλην φωνὴν ἐκ τοῦ οὐρανοῦ λέγουσαν, “Ἐξέλθατε ὁ λαός μου ἐξ αὐτῆς, ἵνα μὴ συγκοινωνήσητε ταῖς ἁμαρτίαις αὐτῆς, καὶ ἐκ τῶν πληγῶν αὐτῆς, ἵνα μὴ λάβητε,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 5, 'ὅτι ἐκολλήθησαν αὐτῆς αἱ ἁμαρτίαι ἄχρι τοῦ οὐρανοῦ, καὶ ἐμνημόνευσεν ὁ  ̊Θεὸς τὰ ἀδικήματα αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 6, 'Ἀπόδοτε αὐτῇ ὡς καὶ αὐτὴ ἀπέδωκεν, καὶ διπλώσατε τὰ διπλᾶ, κατὰ τὰ ἔργα αὐτῆς· ἐν τῷ ποτηρίῳ ᾧ ἐκέρασεν, κεράσατε αὐτῇ διπλοῦν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 7, 'ὅσα ἐδόξασεν αὑτὴν καὶ ἐστρηνίασεν, τοσοῦτον δότε αὐτῇ βασανισμὸν καὶ πένθος. Ὅτι ἐν τῇ καρδίᾳ αὐτῆς λέγει, ὅτι ‘Κάθημαι βασίλισσα... καὶ χήρα οὐκ εἰμί καὶ πένθος οὐ μὴ ἴδω.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 8, 'Διὰ τοῦτο, ἐν μιᾷ ἡμέρᾳ ἥξουσιν αἱ πληγαὶ αὐτῆς, θάνατος, καὶ πένθος, καὶ λιμός, καὶ ἐν πυρὶ κατακαυθήσεται, ὅτι ἰσχυρὸς  ̊Κύριος ὁ  ̊Θεὸς ὁ κρίνας αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 9, '¶Καὶ κλαύσονται καὶ κόψονται ἐπʼ αὐτὴν οἱ βασιλεῖς τῆς γῆς, οἱ μετʼ αὐτῆς πορνεύσαντες καὶ στρηνιάσαντες, ὅταν βλέπωσιν τὸν καπνὸν τῆς πυρώσεως αὐτῆς,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 10, 'ἀπὸ μακρόθεν ἑστηκότες, διὰ τὸν φόβον τοῦ βασανισμοῦ αὐτῆς λέγοντες, ‘Οὐαὶ, οὐαί, ἡ πόλις ἡ μεγάλη Βαβυλὼν, ἡ πόλις ἡ ἰσχυρά! Ὅτι μιᾷ ὥρᾳ ἦλθεν ἡ κρίσις σου.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 11, '¶Καὶ οἱ ἔμποροι τῆς γῆς κλαίουσιν καὶ πενθοῦσιν ἐπʼ αὐτήν, ὅτι τὸν γόμον αὐτῶν οὐδεὶς ἀγοράζει οὐκέτι–');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 12, 'γόμον χρυσοῦ, καὶ ἀργύρου, καὶ λίθου τιμίου, καὶ μαργαριτῶν, καὶ βυσσίνου, καὶ πορφύρας, καὶ σιρικοῦ, καὶ κοκκίνου, καὶ πᾶν ξύλον θύϊνον, καὶ πᾶν σκεῦος ἐλεφάντινον, καὶ πᾶν σκεῦος ἐκ ξύλου τιμιωτάτου, καὶ χαλκοῦ, καὶ σιδήρου, καὶ μαρμάρου,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 13, 'καὶ κιννάμωμον, καὶ ἄμωμον, καὶ θυμιάματα, καὶ μύρον, καὶ λίβανον, καὶ οἶνον, καὶ ἔλαιον, καὶ σεμίδαλιν, καὶ σῖτον, καὶ κτήνη, καὶ πρόβατα, καὶ ἵππων, καὶ ῥεδῶν, καὶ σωμάτων, καὶ ψυχὰς ἀνθρώπων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 14, 'Καὶ ἡ ὀπώρα σου τῆς ἐπιθυμίας τῆς ψυχῆς ἀπῆλθεν ἀπὸ σοῦ, καὶ πάντα τὰ λιπαρὰ καὶ τὰ λαμπρὰ ἀπώλετο ἀπὸ σοῦ, καὶ οὐκέτι οὐ μὴ αὐτὰ εὑρήσουσιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 15, 'Οἱ ἔμποροι τούτων οἱ πλουτήσαντες, ἀπʼ αὐτῆς ἀπὸ μακρόθεν στήσονται, διὰ τὸν φόβον τοῦ βασανισμοῦ αὐτῆς, κλαίοντες καὶ πενθοῦντες');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 16, 'λέγοντες, ‘Οὐαὶ, οὐαί, ἡ πόλις ἡ μεγάλη, ἡ περιβεβλημένη βύσσινον, καὶ πορφυροῦν, καὶ κόκκινον, καὶ κεχρυσωμένη ἐν χρυσίῳ, καὶ λίθῳ τιμίῳ, καὶ μαργαρίτῃ!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 17, 'Ὅτι μιᾷ ὥρᾳ ἠρημώθη ὁ τοσοῦτος πλοῦτος.’ ¶Καὶ πᾶς κυβερνήτης, καὶ πᾶς ὁ ἐπὶ τόπον πλέων, καὶ ναῦται, καὶ ὅσοι τὴν θάλασσαν ἐργάζονται, ἀπὸ μακρόθεν ἔστησαν');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 18, 'καὶ ἔκραξαν, βλέποντες τὸν καπνὸν τῆς πυρώσεως αὐτῆς λέγοντες, ‘Τίς ὁμοία τῇ πόλει τῇ μεγάλῃ;’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 19, 'Καὶ ἔβαλον χοῦν ἐπὶ τὰς κεφαλὰς αὐτῶν, καὶ ἔκραξαν, κλαίοντες καὶ πενθοῦντες λέγοντες, ‘Οὐαὶ, οὐαί, ἡ πόλις ἡ μεγάλη, ἐν ᾗ ἐπλούτησαν πάντες οἱ ἔχοντες τὰ πλοῖα ἐν τῇ θαλάσσῃ ἐκ τῆς τιμιότητος αὐτῆς! Ὅτι μιᾷ ὥρᾳ ἠρημώθη.’');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 20, '¶Εὐφραίνου ἐπʼ αὐτῇ, οὐρανέ, καὶ οἱ ἅγιοι, καὶ οἱ ἀπόστολοι, καὶ οἱ προφῆται, ὅτι ἔκρινεν ὁ  ̊Θεὸς τὸ κρίμα ὑμῶν ἐξ αὐτῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 21, '¶Καὶ ἦρεν εἷς ἄγγελος ἰσχυρὸς λίθον ὡς λίθον μέγαν, καὶ ἔβαλεν εἰς τὴν θάλασσαν λέγων, “Οὕτως ὁρμήματι βληθήσεται Βαβυλὼν ἡ μεγάλη πόλις, καὶ οὐ μὴ εὑρεθῇ ἔτι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 22, 'Καὶ φωνὴ κιθαρῳδῶν, καὶ μουσικῶν, καὶ αὐλητῶν, καὶ σαλπιστῶν, οὐ μὴ ἀκουσθῇ ἐν σοὶ ἔτι, καὶ πᾶς τεχνίτης πάσης τέχνης οὐ μὴ εὑρεθῇ ἐν σοὶ ἔτι, καὶ φωνὴ μύλου οὐ μὴ ἀκουσθῇ ἐν σοὶ ἔτι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 23, 'καὶ φῶς λύχνου οὐ μὴ φάνῃ ἐν σοὶ ἔτι, καὶ φωνὴ νυμφίου καὶ νύμφης οὐ μὴ ἀκουσθῇ ἐν σοὶ ἔτι· ὅτι οἱ ἔμποροί σου ἦσαν οἱ μεγιστᾶνες τῆς γῆς, ὅτι ἐν τῇ φαρμακείᾳ σου ἐπλανήθησαν πάντα τὰ ἔθνη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 18, 24, 'Καὶ ἐν αὐτῇ αἷμα προφητῶν καὶ ἁγίων εὑρέθη, καὶ πάντων τῶν ἐσφαγμένων ἐπὶ τῆς γῆς.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 1, '¶Μετὰ ταῦτα ἤκουσα ὡς φωνὴν μεγάλην ὄχλου πολλοῦ ἐν τῷ οὐρανῷ λεγόντων, “Ἁλληλουϊά! Ἡ σωτηρία, καὶ ἡ δόξα, καὶ ἡ δύναμις, τοῦ  ̊Θεοῦ ἡμῶν!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 2, '‘Ὅτι ἀληθιναὶ καὶ δίκαιαι αἱ κρίσεις αὐτοῦ’, ὅτι ἔκρινεν τὴν πόρνην τὴν μεγάλην, ἥτις ἔφθειρεν τὴν γῆν ἐν τῇ πορνείᾳ αὐτῆς, καὶ ‘ἐξεδίκησεν τὸ αἷμα τῶν δούλων αὐτοῦ ἐκ χειρὸς αὐτῆς’.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 3, 'Καὶ δεύτερον εἴρηκαν, “Ἁλληλουϊά! Καὶ ‘ὁ καπνὸς αὐτῆς ἀναβαίνει εἰς τοὺς αἰῶνας τῶν αἰώνων’.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 4, 'Καὶ ἔπεσαν οἱ πρεσβύτεροι οἱ εἴκοσι τέσσαρες, καὶ τὰ τέσσαρα ζῷα, καὶ προσεκύνησαν τῷ  ̊Θεῷ, τῷ καθημένῳ ἐπὶ τῷ θρόνῳ λέγοντες, “Ἀμήν! Ἁλληλουϊά!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 5, '¶Καὶ φωνὴ ἀπὸ τοῦ θρόνου ἐξῆλθεν λέγουσα, “Αἰνεῖτε τῷ  ̊Θεῷ ἡμῶν, πάντες οἱ δοῦλοι αὐτοῦ, οἱ φοβούμενοι αὐτόν, οἱ μικροὶ καὶ οἱ μεγάλοι!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 6, 'Καὶ ἤκουσα ὡς φωνὴν ὄχλου πολλοῦ, καὶ ὡς φωνὴν ὑδάτων πολλῶν, καὶ ὡς φωνὴν βροντῶν ἰσχυρῶν λεγόντων, “Ἁλληλουϊά, ὅτι ἐβασίλευσεν  ̊Κύριος, ὁ  ̊Θεὸς ἡμῶν ὁ Παντοκράτωρ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 7, 'Χαίρωμεν καὶ ἀγαλλιῶμεν, καὶ δῶμεν τὴν δόξαν αὐτῷ, ὅτι ἦλθεν ὁ γάμος τοῦ Ἀρνίου, καὶ ἡ γυνὴ αὐτοῦ ἡτοίμασεν ἑαυτήν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 8, 'Καὶ ἐδόθη αὐτῇ, ἵνα περιβάληται βύσσινον λαμπρὸν καθαρόν, τὸ γὰρ βύσσινον τὰ δικαιώματα τῶν ἁγίων ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 9, '¶Καὶ λέγει μοι, “Γράψον, ‘Μακάριοι οἱ εἰς τὸ δεῖπνον τοῦ γάμου τοῦ Ἀρνίου κεκλημένοι.’” Καὶ λέγει μοι, “Οὗτοι οἱ λόγοι ἀληθινοὶ τοῦ  ̊Θεοῦ εἰσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 10, 'Καὶ ἔπεσα ἔμπροσθεν τῶν ποδῶν αὐτοῦ προσκυνῆσαι αὐτῷ. Καὶ λέγει μοι, “Ὅρα μή· σύνδουλός σού εἰμι, καὶ τῶν ἀδελφῶν σου τῶν ἐχόντων τὴν μαρτυρίαν  ̊Ἰησοῦ· τῷ  ̊Θεῷ προσκύνησον. Ἡ γὰρ μαρτυρία  ̊Ἰησοῦ ἐστιν τὸ πνεῦμα τῆς προφητείας.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 11, '¶Καὶ εἶδον τὸν οὐρανὸν ἠνεῳγμένον, καὶ ἰδοὺ, ἵππος λευκός, καὶ ὁ καθήμενος ἐπʼ αὐτὸν, Πιστὸς καλούμενος καὶ Ἀληθινός, καὶ ἐν δικαιοσύνῃ κρίνει καὶ πολεμεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 12, 'Οἱ δὲ ὀφθαλμοὶ αὐτοῦ φλὸξ πυρός, καὶ ἐπὶ τὴν κεφαλὴν αὐτοῦ διαδήματα πολλά, ἔχων ὄνομα γεγραμμένον, ὃ οὐδεὶς οἶδεν, εἰ μὴ αὐτός,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 13, 'καὶ περιβεβλημένος ἱμάτιον βεβαμμένον αἵματι, καὶ κέκληται τὸ ὄνομα αὐτοῦ, ὁ Λόγος τοῦ  ̊Θεοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 14, 'Καὶ τὰ στρατεύματα ἐν τῷ οὐρανῷ ἠκολούθει αὐτῷ ἐφʼ ἵπποις λευκοῖς, ἐνδεδυμένοι βύσσινον λευκὸν καθαρόν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 15, 'Καὶ ἐκ τοῦ στόματος αὐτοῦ ἐκπορεύεται ῥομφαία ὀξεῖα, ἵνα ἐν αὐτῇ πατάξῃ τὰ ἔθνη, “καὶ αὐτὸς ποιμανεῖ αὐτοὺς ἐν ῥάβδῳ σιδηρᾷ”· καὶ αὐτὸς πατεῖ τὴν ληνὸν τοῦ οἴνου τοῦ θυμοῦ τῆς ὀργῆς τοῦ  ̊Θεοῦ τοῦ Παντοκράτορος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 16, 'Καὶ ἔχει ἐπὶ τὸ ἱμάτιον καὶ ἐπὶ τὸν μηρὸν αὐτοῦ, ὄνομα γεγραμμένον, “Βασιλεὺς βασιλέων καὶ  ̊Κύριος κυρίων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 17, '¶Καὶ εἶδον ἕνα ἄγγελον ἑστῶτα ἐν τῷ ἡλίῳ, καὶ ἔκραξεν ἐν φωνῇ μεγάλῃ, λέγων πᾶσι τοῖς ὀρνέοις τοῖς πετομένοις ἐν μεσουρανήματι, “Δεῦτε, συνάχθητε εἰς τὸ δεῖπνον τὸ μέγα τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 18, 'ἵνα φάγητε σάρκας βασιλέων, καὶ σάρκας χιλιάρχων, καὶ σάρκας ἰσχυρῶν, καὶ σάρκας ἵππων, καὶ τῶν καθημένων ἐπʼ αὐτούς, καὶ σάρκας πάντων, ἐλευθέρων τε καὶ δούλων, καὶ μικρῶν καὶ μεγάλων.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 19, 'Καὶ εἶδον τὸ θηρίον, καὶ τοὺς βασιλεῖς τῆς γῆς, καὶ τὰ στρατεύματα αὐτῶν, συνηγμένα ποιῆσαι τὸν πόλεμον μετὰ τοῦ καθημένου ἐπὶ τοῦ ἵππου, καὶ μετὰ τοῦ στρατεύματος αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 20, 'Καὶ ἐπιάσθη τὸ θηρίον, καὶ μετʼ αὐτοῦ ὁ ψευδοπροφήτης, ὁ ποιήσας τὰ σημεῖα ἐνώπιον αὐτοῦ, ἐν οἷς ἐπλάνησεν τοὺς λαβόντας τὸ χάραγμα τοῦ θηρίου, καὶ τοὺς προσκυνοῦντας τῇ εἰκόνι αὐτοῦ. Ζῶντες ἐβλήθησαν οἱ δύο εἰς τὴν λίμνην τοῦ πυρὸς, τῆς καιομένης ἐν θείῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 19, 21, 'Καὶ οἱ λοιποὶ ἀπεκτάνθησαν ἐν τῇ ῥομφαίᾳ τοῦ καθημένου ἐπὶ τοῦ ἵππου, τῇ ἐξελθούσῃ ἐκ τοῦ στόματος αὐτοῦ, καὶ πάντα τὰ ὄρνεα ἐχορτάσθησαν ἐκ τῶν σαρκῶν αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 1, '¶Καὶ εἶδον ἄγγελον καταβαίνοντα ἐκ τοῦ οὐρανοῦ, ἔχοντα τὴν κλεῖν τῆς Ἀβύσσου, καὶ ἅλυσιν μεγάλην ἐπὶ τὴν χεῖρα αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 2, 'Καὶ ἐκράτησεν τὸν δράκοντα, τὸν ὄφιν τὸν ἀρχαῖον, ὅς ἐστιν Διάβολος καὶ ὁ Σατανᾶς, καὶ ἔδησεν αὐτὸν χίλια ἔτη,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 3, 'καὶ ἔβαλεν αὐτὸν εἰς τὴν Ἄβυσσον, καὶ ἔκλεισεν καὶ ἐσφράγισεν ἐπάνω αὐτοῦ, ἵνα μὴ πλανήσῃ ἔτι τὰ ἔθνη, ἄχρι τελεσθῇ τὰ χίλια ἔτη· μετὰ ταῦτα, δεῖ αὐτὸν λυθῆναι μικρὸν χρόνον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 4, '¶Καὶ εἶδον θρόνους, καὶ ἐκάθισαν ἐπʼ αὐτούς, καὶ κρίμα ἐδόθη αὐτοῖς, καὶ τὰς ψυχὰς τῶν πεπελεκισμένων διὰ τὴν μαρτυρίαν  ̊Ἰησοῦ, καὶ διὰ τὸν λόγον τοῦ  ̊Θεοῦ, καὶ οἵτινες οὐ προσεκύνησαν τὸ θηρίον, οὐδὲ τὴν εἰκόνα αὐτοῦ, καὶ οὐκ ἔλαβον τὸ χάραγμα ἐπὶ τὸ μέτωπον, καὶ ἐπὶ τὴν χεῖρα αὐτῶν· καὶ ἔζησαν καὶ ἐβασίλευσαν μετὰ τοῦ  ̊Χριστοῦ χίλια ἔτη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 5, 'Οἱ λοιποὶ τῶν νεκρῶν οὐκ ἔζησαν, ἄχρι τελεσθῇ τὰ χίλια ἔτη. Αὕτη ἡ ἀνάστασις ἡ πρώτη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 6, 'Μακάριος καὶ ἅγιος ὁ ἔχων μέρος ἐν τῇ ἀναστάσει τῇ πρώτῃ! Ἐπὶ τούτων ὁ δεύτερος θάνατος οὐκ ἔχει ἐξουσίαν, ἀλλʼ ἔσονται ἱερεῖς τοῦ  ̊Θεοῦ καὶ τοῦ  ̊Χριστοῦ, καὶ βασιλεύσουσιν μετʼ αὐτοῦ τὰ χίλια ἔτη.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 7, '¶Καὶ ὅταν τελεσθῇ τὰ χίλια ἔτη, λυθήσεται ὁ Σατανᾶς ἐκ τῆς φυλακῆς αὐτοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 8, 'καὶ ἐξελεύσεται πλανῆσαι τὰ ἔθνη τὰ ἐν ταῖς τέσσαρσιν γωνίαις τῆς γῆς, τὸν Γὼγ καὶ Μαγώγ, συναγαγεῖν αὐτοὺς εἰς τὸν πόλεμον, ὧν ὁ ἀριθμὸς αὐτῶν ὡς ἡ ἄμμος τῆς θαλάσσης.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 9, 'Καὶ ἀνέβησαν ἐπὶ τὸ πλάτος τῆς γῆς, καὶ ἐκύκλωσαν τὴν παρεμβολὴν τῶν ἁγίων, καὶ τὴν πόλιν τὴν ἠγαπημένην. Καὶ κατέβη πῦρ ἐκ τοῦ οὐρανοῦ καὶ κατέφαγεν αὐτούς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 10, 'Καὶ ὁ διάβολος, ὁ πλανῶν αὐτοὺς, ἐβλήθη εἰς τὴν λίμνην τοῦ πυρὸς καὶ θείου, ὅπου καὶ τὸ θηρίον καὶ ὁ ψευδοπροφήτης, καὶ βασανισθήσονται ἡμέρας καὶ νυκτὸς εἰς τοὺς αἰῶνας τῶν αἰώνων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 11, '¶Καὶ εἶδον θρόνον μέγαν λευκὸν, καὶ τὸν καθήμενον ἐπʼ αὐτοῦ, οὗ ἀπὸ τοῦ προσώπου ἔφυγεν ἡ γῆ καὶ ὁ οὐρανός, καὶ τόπος οὐχ εὑρέθη αὐτοῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 12, 'Καὶ εἶδον τοὺς νεκρούς, τοὺς μεγάλους καὶ τοὺς μικρούς, ἑστῶτας ἐνώπιον τοῦ θρόνου, καὶ βιβλία ἠνοίχθησαν· καὶ ἄλλο βιβλίον ἠνεῴχθη, ὅ ἐστιν τῆς ζωῆς. Καὶ ἐκρίθησαν οἱ νεκροὶ ἐκ τῶν γεγραμμένων ἐν τοῖς βιβλίοις κατὰ τὰ ἔργα αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 13, 'Καὶ ἔδωκεν ἡ θάλασσα τοὺς νεκροὺς τοὺς ἐν αὐτῇ, καὶ ὁ θάνατος καὶ ὁ ἍΙδης ἔδωκαν τοὺς νεκροὺς τοὺς ἐν αὐτοῖς, καὶ ἐκρίθησαν ἕκαστος κατὰ τὰ ἔργα αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 14, 'Καὶ ὁ θάνατος καὶ ὁ ἍΙδης ἐβλήθησαν εἰς τὴν λίμνην τοῦ πυρός. Οὗτος ὁ θάνατος ὁ δεύτερός ἐστιν, ἡ λίμνη τοῦ πυρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 20, 15, 'Καὶ εἴ τις οὐχ εὑρέθη ἐν τῇ βίβλῳ τῆς ζωῆς γεγραμμένος, ἐβλήθη εἰς τὴν λίμνην τοῦ πυρός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 1, '¶Καὶ εἶδον οὐρανὸν καινὸν καὶ γῆν καινήν· ὁ γὰρ πρῶτος οὐρανὸς καὶ ἡ πρώτη γῆ ἀπῆλθαν, καὶ ἡ θάλασσα οὐκ ἔστιν ἔτι.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 2, 'Καὶ τὴν πόλιν τὴν ἁγίαν, Ἰερουσαλὴμ καινὴν, εἶδον καταβαίνουσαν ἐκ τοῦ οὐρανοῦ ἀπὸ τοῦ  ̊Θεοῦ, ἡτοιμασμένην ὡς νύμφην, κεκοσμημένην τῷ ἀνδρὶ αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 3, 'Καὶ ἤκουσα φωνῆς μεγάλης ἐκ τοῦ θρόνου λεγούσης, “Ἰδοὺ, ἡ σκηνὴ τοῦ  ̊Θεοῦ μετὰ τῶν ἀνθρώπων, καὶ σκηνώσει μετʼ αὐτῶν, καὶ αὐτοὶ λαοὶ αὐτοῦ ἔσονται, καὶ αὐτὸς ὁ  ̊Θεὸς ἔσται μετʼ αὐτῶν,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 4, 'καὶ ἐξαλείψει πᾶν δάκρυον ἐκ τῶν ὀφθαλμῶν αὐτῶν, καὶ ὁ θάνατος οὐκ ἔσται ἔτι, οὔτε πένθος, οὔτε κραυγὴ, οὔτε πόνος, οὐκ ἔσται ἔτι. Τὰ πρῶτα ἀπῆλθαν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 5, '¶Καὶ εἶπεν ὁ καθήμενος ἐπὶ τῷ θρόνῳ, “Ἰδοὺ, καινὰ ποιῶ πάντα.” Καὶ λέγει μοι, “Γράψον, ὅτι οὗτοι οἱ λόγοι πιστοὶ καὶ ἀληθινοί εἰσιν.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 6, 'Καὶ εἶπέν μοι, “Γέγοναν! Ἐγὼ τὸ Ἄλφα καὶ τὸ Ὦ, ἡ ἀρχὴ καὶ τὸ τέλος. Ἐγὼ τῷ διψῶντι δώσω ἐκ τῆς πηγῆς τοῦ ὕδατος τῆς ζωῆς δωρεάν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 7, 'Ὁ νικῶν κληρονομήσει ταῦτα, καὶ ἔσομαι αὐτῷ  ̊Θεὸς, καὶ αὐτὸς ἔσται μοι υἱός.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 8, 'Τοῖς δὲ δειλοῖς, καὶ ἀπίστοις, καὶ ἐβδελυγμένοις, καὶ φονεῦσι, καὶ πόρνοις, καὶ φαρμάκοις, καὶ εἰδωλολάτραις, καὶ πᾶσι τοῖς ψευδέσιν, τὸ μέρος αὐτῶν ἐν τῇ λίμνῃ τῇ καιομένῃ πυρὶ καὶ θείῳ, ὅ ἐστιν ὁ θάνατος ὁ δεύτερος.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 9, '¶Καὶ ἦλθεν εἷς ἐκ τῶν ἑπτὰ ἀγγέλων, τῶν ἐχόντων τὰς ἑπτὰ φιάλας, τῶν γεμόντων τῶν ἑπτὰ πληγῶν τῶν ἐσχάτων, καὶ ἐλάλησεν μετʼ ἐμοῦ λέγων, “Δεῦρο, δείξω σοι τὴν νύμφην, τὴν γυναῖκα τοῦ Ἀρνίου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 10, 'Καὶ ἀπήνεγκέν με ἐν  ̊Πνεύματι ἐπὶ ὄρος μέγα καὶ ὑψηλόν, καὶ ἔδειξέν μοι τὴν πόλιν τὴν ἁγίαν Ἰερουσαλὴμ, καταβαίνουσαν ἐκ τοῦ οὐρανοῦ ἀπὸ τοῦ  ̊Θεοῦ,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 11, 'ἔχουσαν τὴν δόξαν ἀπὸ τοῦ  ̊Θεοῦ. Ὁ φωστὴρ αὐτῆς ὅμοιος λίθῳ τιμιωτάτῳ, ὡς λίθῳ ἰάσπιδι κρυσταλλίζοντι,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 12, 'ἔχουσα τεῖχος μέγα καὶ ὑψηλόν, ἔχουσα πυλῶνας δώδεκα, καὶ ἐπὶ τοὺς πυλῶνας ἀγγέλους δώδεκα, καὶ ὀνόματα ἐπιγεγραμμένα, ἅ ἐστιν τῶν δώδεκα φυλῶν υἱῶν Ἰσραήλ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 13, 'Ἀπὸ ἀνατολῆς πυλῶνες τρεῖς, καὶ ἀπὸ βορρᾶ πυλῶνες τρεῖς, καὶ ἀπὸ δυσμῶν πυλῶνες τρεῖς, καὶ ἀπὸ νότου πυλῶνες τρεῖς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 14, 'Καὶ τὸ τεῖχος τῆς πόλεως ἔχων θεμελίους δώδεκα, καὶ ἐπʼ αὐτῶν δώδεκα ὀνόματα τῶν δώδεκα ἀποστόλων τοῦ Ἀρνίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 15, '¶Καὶ ὁ λαλῶν μετʼ ἐμοῦ εἶχεν μέτρον κάλαμον χρυσοῦν, ἵνα μετρήσῃ τὴν πόλιν, καὶ τοὺς πυλῶνας αὐτῆς, καὶ τὸ τεῖχος αὐτῆς.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 16, 'Καὶ ἡ πόλις τετράγωνος κεῖται, καὶ τὸ μῆκος αὐτῆς ὅσον τὸ πλάτος. Καὶ ἐμέτρησεν τὴν πόλιν τῷ καλάμῳ ἐπὶ σταδίων δώδεκα χιλιάδων– τὸ μῆκος, καὶ τὸ πλάτος, καὶ τὸ ὕψος αὐτῆς, ἴσα ἐστίν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 17, 'Καὶ ἐμέτρησεν τὸ τεῖχος αὐτῆς, ἑκατὸν τεσσεράκοντα τεσσάρων πηχῶν, μέτρον ἀνθρώπου ὅ ἐστιν ἀγγέλου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 18, 'Καὶ ἦν ἡ ἐνδώμησις τοῦ τείχους αὐτῆς ἴασπις, καὶ ἡ πόλις χρυσίον καθαρὸν, ὅμοιον ὑάλῳ καθαρῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 19, 'οἱ θεμέλιοι τοῦ τείχους τῆς πόλεως παντὶ λίθῳ τιμίῳ κεκοσμημένοι. Ὁ θεμέλιος ὁ πρῶτος ἴασπις, ὁ δεύτερος σάπφειρος, ὁ τρίτος χαλκηδών, ὁ τέταρτος σμάραγδος,');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 20, 'ὁ πέμπτος σαρδόνυξ, ὁ ἕκτος σάρδιον, ὁ ἕβδομος χρυσόλιθος, ὁ ὄγδοος βήρυλλος, ὁ ἔνατος τοπάζιον, ὁ δέκατος χρυσόπρασος, ὁ ἑνδέκατος ὑάκινθος, ὁ δωδέκατος ἀμέθυστος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 21, 'Καὶ οἱ δώδεκα πυλῶνες δώδεκα μαργαρῖται, ἀνὰ εἷς ἕκαστος τῶν πυλώνων ἦν ἐξ ἑνὸς μαργαρίτου. Καὶ ἡ πλατεῖα τῆς πόλεως χρυσίον καθαρὸν ὡς ὕαλος διαυγής.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 22, '¶Καὶ ναὸν οὐκ εἶδον ἐν αὐτῇ, ὁ γὰρ  ̊Κύριος ὁ  ̊Θεός ὁ Παντοκράτωρ ναὸς αὐτῆς ἐστιν, καὶ τὸ Ἀρνίον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 23, 'Καὶ ἡ πόλις οὐ χρείαν ἔχει τοῦ ἡλίου οὐδὲ τῆς σελήνης ἵνα φαίνωσιν αὐτῇ, ἡ γὰρ δόξα τοῦ  ̊Θεοῦ ἐφώτισεν αὐτήν, καὶ ὁ λύχνος αὐτῆς τὸ Ἀρνίον.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 24, 'Καὶ περιπατήσουσιν τὰ ἔθνη διὰ τοῦ φωτὸς αὐτῆς, καὶ οἱ βασιλεῖς τῆς γῆς φέρουσιν τὴν δόξαν αὐτῶν εἰς αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 25, 'Καὶ οἱ πυλῶνες αὐτῆς οὐ μὴ κλεισθῶσιν ἡμέρας, νὺξ γὰρ οὐκ ἔσται ἐκεῖ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 26, 'Καὶ οἴσουσιν τὴν δόξαν καὶ τὴν τιμὴν τῶν ἐθνῶν εἰς αὐτήν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 21, 27, 'Καὶ οὐ μὴ εἰσέλθῃ εἰς αὐτὴν πᾶν κοινὸν, καὶ ὁ ποιῶν βδέλυγμα καὶ ψεῦδος, εἰ μὴ οἱ γεγραμμένοι ἐν τῷ βιβλίῳ τῆς ζωῆς τοῦ Ἀρνίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 1, '¶Καὶ ἔδειξέν μοι ποταμὸν ὕδατος ζωῆς λαμπρὸν ὡς κρύσταλλον, ἐκπορευόμενον ἐκ τοῦ θρόνου τοῦ  ̊Θεοῦ καὶ τοῦ Ἀρνίου.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 2, 'Ἐν μέσῳ τῆς πλατείας αὐτῆς καὶ τοῦ ποταμοῦ, ἐντεῦθεν καὶ ἐκεῖθεν, ξύλον ζωῆς ποιοῦν καρποὺς δώδεκα, κατὰ μῆνα ἕκαστον ἀποδιδοῦν τὸν καρπὸν αὐτοῦ, καὶ τὰ φύλλα τοῦ ξύλου εἰς θεραπείαν τῶν ἐθνῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 3, 'Καὶ πᾶν κατάθεμα οὐκ ἔσται ἔτι. Καὶ ὁ θρόνος τοῦ  ̊Θεοῦ καὶ τοῦ Ἀρνίου ἐν αὐτῇ ἔσται, καὶ οἱ δοῦλοι αὐτοῦ λατρεύσουσιν αὐτῷ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 4, 'Καὶ ὄψονται τὸ πρόσωπον αὐτοῦ, καὶ τὸ ὄνομα αὐτοῦ ἐπὶ τῶν μετώπων αὐτῶν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 5, 'Καὶ νὺξ οὐκ ἔσται ἔτι, καὶ οὐκ ἔχουσιν χρείαν φωτὸς λύχνου καὶ φωτὸς ἡλίου, ὅτι  ̊Κύριος ὁ  ̊Θεὸς φωτίσει ἐπʼ αὐτούς, καὶ βασιλεύσουσιν εἰς τοὺς αἰῶνας τῶν αἰώνων.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 6, '¶Καὶ εἶπέν μοι, “Οὗτοι οἱ λόγοι πιστοὶ καὶ ἀληθινοί, καὶ ὁ  ̊Κύριος, ὁ  ̊Θεὸς τῶν πνευμάτων τῶν προφητῶν, ἀπέστειλεν τὸν ἄγγελον αὐτοῦ, δεῖξαι τοῖς δούλοις αὐτοῦ ἃ δεῖ γενέσθαι ἐν τάχει.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 7, '“Καὶ ἰδοὺ, ἔρχομαι ταχύ. Μακάριος ὁ τηρῶν τοὺς λόγους τῆς προφητείας τοῦ βιβλίου τούτου.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 8, '¶Κἀγὼ Ἰωάννης ὁ ἀκούων καὶ βλέπων ταῦτα. Καὶ ὅτε ἤκουσα καὶ ἔβλεψα, ἔπεσα προσκυνῆσαι ἔμπροσθεν τῶν ποδῶν τοῦ ἀγγέλου τοῦ δεικνύοντός μοι ταῦτα.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 9, 'Καὶ λέγει μοι, “Ὅρα μή· σύνδουλός σού εἰμι καὶ τῶν ἀδελφῶν σου, τῶν προφητῶν, καὶ τῶν τηρούντων τοὺς λόγους τοῦ βιβλίου τούτου. Τῷ  ̊Θεῷ προσκύνησον!”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 10, '¶Καὶ λέγει μοι, “Μὴ σφραγίσῃς τοὺς λόγους τῆς προφητείας τοῦ βιβλίου τούτου, ὁ καιρὸς γὰρ ἐγγύς ἐστιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 11, 'Ὁ ἀδικῶν, ἀδικησάτω ἔτι, καὶ ὁ ῥυπαρὸς, ῥυπανθήτω ἔτι, καὶ ὁ δίκαιος, δικαιοσύνην ποιησάτω ἔτι, καὶ ὁ ἅγιος, ἁγιασθήτω ἔτι.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 12, '¶“Ἰδοὺ, ἔρχομαι ταχύ, καὶ ὁ μισθός μου μετʼ ἐμοῦ, ἀποδοῦναι ἑκάστῳ ὡς τὸ ἔργον ἐστὶν αὐτοῦ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 13, 'Ἐγὼ τὸ Ἄλφα καὶ τὸ Ὦ, ὁ πρῶτος καὶ ὁ ἔσχατος, ἡ ἀρχὴ καὶ τὸ τέλος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 14, '¶Μακάριοι οἱ πλύνοντες τὰς στολὰς αὐτῶν, ἵνα ἔσται ἡ ἐξουσία αὐτῶν ἐπὶ τὸ ξύλον τῆς ζωῆς, καὶ τοῖς πυλῶσιν εἰσέλθωσιν εἰς τὴν πόλιν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 15, 'Ἔξω οἱ κύνες, καὶ οἱ φάρμακοι, καὶ οἱ πόρνοι, καὶ οἱ φονεῖς, καὶ οἱ εἰδωλολάτραι, καὶ πᾶς φιλῶν καὶ ποιῶν ψεῦδος.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 16, '¶Ἐγὼ,  ̊Ἰησοῦς, ἔπεμψα τὸν ἄγγελόν μου, μαρτυρῆσαι ὑμῖν ταῦτα ἐπὶ ταῖς ἐκκλησίαις. Ἐγώ εἰμι ἡ ῥίζα καὶ τὸ γένος Δαυίδ, ὁ ἀστὴρ ὁ λαμπρός, ὁ πρωϊνός.”');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 17, 'Καὶ τὸ  ̊Πνεῦμα καὶ ἡ νύμφη λέγουσιν, “Ἔρχου!” Καὶ ὁ ἀκούων εἰπάτω, “Ἔρχου!” Καὶ ὁ διψῶν ἐρχέσθω, ὁ θέλων λαβέτω ὕδωρ ζωῆς δωρεάν.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 18, '¶Μαρτυρῶ ἐγὼ παντὶ τῷ ἀκούοντι τοὺς λόγους τῆς προφητείας τοῦ βιβλίου τούτου: ἐάν τις ἐπιθῇ ἐπʼ αὐτά, ἐπιθήσει ἐπʼ αὐτὸν ὁ  ̊Θεὸς τὰς πληγὰς τὰς γεγραμμένας ἐν τῷ βιβλίῳ τούτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 19, 'Καὶ ἐάν τις ἀφέλῃ ἀπὸ τῶν λόγων τοῦ βιβλίου τῆς προφητείας ταύτης, ἀφελεῖ ὁ  ̊Θεὸς τὸ μέρος αὐτοῦ ἀπὸ τοῦ ξύλου τῆς ζωῆς καὶ ἐκ τῆς πόλεως τῆς ἁγίας, τῶν γεγραμμένων ἐν τῷ βιβλίῳ τούτῳ.');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 20, '¶Λέγει ὁ μαρτυρῶν ταῦτα, “Ναί, ἔρχομαι ταχύ. Ἀμήν!” Ἔρχου,  ̊Κύριε  ̊Ἰησοῦ!');
INSERT INTO `StatResGNT_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (84, 22, 21, '¶Ἡ χάρις τοῦ  ̊Κυρίου  ̊Ἰησοῦ μετὰ τῶν ἁγίων. Ἀμήν!');
